def remember_chat_title(chat_id: int, title: str = "") -> None:
    if not chat_id:
        return
    if title:
        cfg_set(chat_id, "chat_title", title)


def get_chat_title(chat_id: int) -> str:
    """Devuelve el título conocido del grupo sin depender de Telegram.

    Algunos bloques nuevos del menú privado llaman a get_chat_title();
    en versiones anteriores no existía y provocaba NameError al entrar
    en IA Cerebrito o Permisos módulos.
    """
    try:
        state = STATE_CACHE.get(int(chat_id))
        if state and isinstance(getattr(state, "admin_config", None), dict):
            title = state.admin_config.get("chat_title")
            if title:
                return str(title)

        fn = globals().get("cfg_value")
        if callable(fn):
            title = fn(int(chat_id), "chat_title", "")
            if title:
                return str(title)
    except Exception:
        pass
    return str(chat_id)


