            InlineKeyboardButton("⏰ Hora", callback_data=f"cfg|phrase_time|{chat_id}|daily_phrase"),
            InlineKeyboardButton("✏️ Título", callback_data=f"cfg|phrase_title|{chat_id}|daily_phrase"),
