async def render_control_view(bot, chat_id: int, body_text: str, reply_markup: InlineKeyboardMarkup) -> None:
    """Renderiza vistas temporales de la mesa editando el mismo mensaje.

    Mantiene compatibilidad con partes antiguas que envían body_text+markup.
    """
    state = get_state(chat_id)
    if not state.dj_mode:
        return
    if bool(admin_cfg(chat_id).get("dj_mesa_minimized", False)):
        return

    text = control_header(state) + body_text
    if state.control_message_id:
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=state.control_message_id,
                text=text,
                reply_markup=reply_markup,
                parse_mode=ParseMode.HTML,
            )
            admin_cfg(chat_id)["dj_mesa_visible"] = True
            save_all_states()
            return
        except BadRequest as e:
            err = str(e).lower()
            if "message is not modified" in err:
                admin_cfg(chat_id)["dj_mesa_visible"] = True
                save_all_states()
                return
            if _is_msg_not_found_error_v28(e):
                state.control_message_id = None
                save_all_states()
            else:
                logger.warning("No se pudo editar vista mesa DJ %s en chat %s: %s", state.control_message_id, chat_id, e)
                return
        except Exception:
            logger.exception("Fallo temporal editando vista mesa DJ %s en chat %s; no se recrea.", state.control_message_id, chat_id)
            return

    await _send_new_control_panel_v28(bot, chat_id)


