async def _dj_open_or_explain_live_v29(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, start_call: bool = True) -> tuple[bool, Optional[str]]:
    """Intenta asegurar el videochat y devolver URL para abrirlo.

    Devuelve (ok, url). Si no hay URL, deja un aviso temporal en el grupo explicando
    que debe abrirse el videochat desde Telegram o configurar VOICE_CHAT_LINKS.
    """
    if start_call:
        try:
            await VOICE.ensure_videochat_started(chat_id)
        except Exception:
            logger.exception("No se pudo iniciar/asegurar videochat en chat %s", chat_id)

    url = await build_live_join_url(context.bot, chat_id)
    if url:
        return True, url

    try:
        await send_temp_message(
            context.bot,
            chat_id,
            (
                "🎧 <b>Directo musical activo</b>\n\n"
                "No puedo abrir el videochat automáticamente porque este grupo no tiene "
                "enlace público/directo configurado.\n\n"
                "Abre el videochat desde la barra superior de Telegram o configura "
                "<code>VOICE_CHAT_LINK</code> / <code>VOICE_CHAT_LINKS</code> en Railway."
            ),
            ttl=45,
        )
    except Exception:
        pass
    return False, None


