async def validation_chat_member_update(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        cmu = update.chat_member
        if cmu:
            chat_id = int(cmu.chat.id); user = cmu.new_chat_member.user
            old_status = str(getattr(cmu.old_chat_member, "status", "") or "")
            new_status = str(getattr(cmu.new_chat_member, "status", "") or "")
            actor = getattr(cmu, "from_user", None)
            if old_status in ("left", "kicked", "") and new_status in ("member", "restricted"):
                await _v33_private_alert(context, chat_id, f"👤 {user.mention_html()} ha entrado en <b>{h(cmu.chat.title or chat_id)}</b>.")
            elif new_status == "kicked":
                by = f" por {actor.mention_html()}" if actor else ""
                await _v33_private_alert(context, chat_id, f"⛔ {user.mention_html()} ha sido expulsado{by} en <b>{h(cmu.chat.title or chat_id)}</b>.")
            elif old_status not in ("left", "kicked", "") and new_status == "left":
                await _v33_private_alert(context, chat_id, f"🚪 {user.mention_html()} ha salido voluntariamente de <b>{h(cmu.chat.title or chat_id)}</b>.")
            elif new_status == "restricted" and not bool(getattr(cmu.new_chat_member, "can_send_messages", True)):
                by = f" por {actor.mention_html()}" if actor else ""
                await _v33_private_alert(context, chat_id, f"🔇 {user.mention_html()} ha sido silenciado{by} en <b>{h(cmu.chat.title or chat_id)}</b>.")
    except Exception:
        logger.exception("Error enviando alerta privada de ChatMember")
    await _old_validation_chat_member_update_v33(update, context)


