async def owner_mention_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_chat or not update.effective_user:
        return
    if update.effective_chat.type == "private" or getattr(update.effective_user, "is_bot", False):
        return
    chat_id = int(update.effective_chat.id)
    if not bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)):
        return
    owner_ids = set(_v33_owner_ids_env())
    owner_usernames: set[str] = set()
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for adm in admins:
            if getattr(adm, "status", "") == "creator":
                owner_ids.add(int(adm.user.id))
            if int(adm.user.id) in owner_ids and adm.user.username:
                owner_usernames.add(adm.user.username.lower())
    except Exception:
        pass
    found = False
    text = update.message.text or update.message.caption or ""
    for ent in (update.message.entities or []) + (update.message.caption_entities or []):
        if ent.type == "text_mention" and getattr(ent, "user", None) and int(ent.user.id) in owner_ids:
            found = True
        if ent.type == "mention":
            mention = text[ent.offset:ent.offset + ent.length].lstrip("@").lower()
            if mention in owner_usernames:
                found = True
    if found:
        await _v33_private_alert(context, chat_id, f"📣 {update.effective_user.mention_html()} te ha mencionado en <b>{h(update.effective_chat.title or chat_id)}</b>.", message_id=update.message.message_id)


def _v33_status_for_chat(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    recs = cfg.get("recurring_messages") if isinstance(cfg.get("recurring_messages"), list) else []
    preg_jobs = cfg.get("pregonero_auto_jobs") if isinstance(cfg.get("pregonero_auto_jobs"), list) else []
    polls = _v32_polls(chat_id)
    active_recs = sum(1 for r in recs if r.get("enabled", True))
    active_preg = sum(1 for j in preg_jobs if j.get("enabled", True))
    open_polls = sum(1 for p in polls if str(p.get("status") or "") == "open")
    return (
        f"<b>{h(chat_id)}</b>\n"
        f"Validación: <b>{'ON' if validation_is_active_for_chat(chat_id) else 'OFF'}</b>\n"
        f"Recurrentes: <b>{active_recs}/{len(recs)}</b>\n"
        f"Pregoneros auto: <b>{active_preg}/{len(preg_jobs)}</b>\n"
        f"Encuestas abiertas: <b>{open_polls}</b>\n"
        f"Privadito: <b>{'ON' if cfg_value(chat_id, 'privadito_enabled', False) else 'OFF'}</b>\n"
        f"Frase del día: <b>{'ON' if cfg_value(chat_id, 'daily_phrase_enabled', False) else 'OFF'}</b>\n"
        f"Borrado comandos: <b>{h(str(cfg_value(chat_id, 'global_command_delete_mode', 'off')))}</b>\n"
    )


def ping_text_full() -> str:
    base = ping_text()
    lines = [base, "", "<b>Estado módulos</b>"]
    if not STATE_CACHE:
        lines.append("No hay grupos cargados en estado.")
    else:
        for chat_id in list(STATE_CACHE.keys())[:20]:
            lines.append(_v33_status_for_chat(int(chat_id)))
    lines.append("✅ Si ves este mensaje, el bot responde correctamente.")
