def _v42_remaining_label(seconds: int) -> str:
    try:
        seconds = max(0, int(seconds))
    except Exception:
        seconds = 0
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _sec = divmod(rem, 60)
    parts: List[str] = []
    if days:
        parts.append(f"{days} día" if days == 1 else f"{days} días")
    if hours:
        parts.append(f"{hours} hora" if hours == 1 else f"{hours} horas")
    if minutes or not parts:
        parts.append(f"{minutes} min")
    return ", ".join(parts)


def _v32_poll_text(poll: Dict[str, Any], *, results: bool = False) -> str:
    q = h(poll.get("question", "Encuesta"))
    desc = str(poll.get("description") or "").strip()
    multi = bool(poll.get("multi", False))
    status = str(poll.get("status") or "open")
    close_ts = int(poll.get("close_ts", 0) or 0)
    now = int(time.time())
    remaining = max(0, close_ts - now) if close_ts else 0
    votes = poll.get("votes") if isinstance(poll.get("votes"), dict) else {}
    lines = ["📊 <b>Encuesta anónima</b>", "", f"<b>{q}</b>"]
    if desc:
        lines.extend(["", desc])
    lines.extend(["", "Tipo: <b>respuesta múltiple</b>" if multi else "Tipo: <b>una respuesta</b>"])
    if status == "open":
        lines.append(f"⏳ Tiempo restante: <b>{h(_v42_remaining_label(remaining))}</b>")
        lines.append(f"🗳 Votos recibidos: <b>{len(votes)}</b>")
        lines.append("<i>Los porcentajes se mostrarán solo al finalizar.</i>")
    else:
        lines.append("Estado: <b>finalizada</b>")
    if results or status != "open":
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        counts = _v32_poll_counts(poll)
        total = sum(counts)
        lines.extend(["", "<b>Resultados finales:</b>"])
        for idx, opt in enumerate(opts):
            c = counts[idx] if idx < len(counts) else 0
            pct = int(round((c / total) * 100)) if total else 0
            bar = "█" * max(1, min(10, pct // 10)) if c else "░"
            lines.append(f"{idx+1}. {h(opt)} — <b>{c}</b> votos · <b>{pct}%</b> {bar}")
        lines.append(f"\nTotal votos: <b>{total}</b>")
    else:
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        lines.extend(["", "<b>Opciones:</b>"])
        for idx, opt in enumerate(opts):
            lines.append(f"{idx+1}. {h(opt)}")
    return "\n".join(lines)


def _v32_poll_markup(chat_id: int, poll: Dict[str, Any]) -> Optional[InlineKeyboardMarkup]:
    if str(poll.get("status") or "open") != "open":
        return None
    poll_id = int(poll.get("id", 0) or 0)
    opts = poll.get("options") if isinstance(poll.get("options"), list) else []
    close_ts = int(poll.get("close_ts", 0) or 0)
    remaining = max(0, close_ts - int(time.time())) if close_ts else 0
    votes = poll.get("votes") if isinstance(poll.get("votes"), dict) else {}
    rows: List[List[InlineKeyboardButton]] = []
    for idx, opt in enumerate(opts):
        rows.append([InlineKeyboardButton(f"{idx+1}. {str(opt)[:48]}", callback_data=f"poll|vote|{chat_id}|{poll_id}|{idx}")])

    rows.append([InlineKeyboardButton(f"⏳ Queda {_v42_remaining_label(remaining)} · 🗳 {len(votes)} votos", callback_data=f"poll|time|{chat_id}|{poll_id}")])
    return InlineKeyboardMarkup(rows)


_old_poll_callback_router_v42 = poll_callback_router
async def poll_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("poll|time|"):
        try:
            parts = data.split("|")
            chat_id = int(parts[2]); poll_id = int(parts[3])
            poll = _v32_poll_find(chat_id, poll_id)
            if poll:
                rem = max(0, int(poll.get("close_ts", 0) or 0) - int(time.time()))
                votes = poll.get("votes") if isinstance(poll.get("votes"), dict) else {}
                await q.answer(f"Queda {_v42_remaining_label(rem)} · {len(votes)} votos", show_alert=False)
                return
        except Exception:
            pass
        await q.answer(); return
    await _old_poll_callback_router_v42(update, context)


_old_poll_close_loop_v42 = poll_close_loop
async def poll_close_loop(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    for chat_id, state in list(STATE_CACHE.items()):
        try:
            for poll in list(_v32_polls(chat_id)):
                if str(poll.get("status") or "open") != "open":
                    continue
                if int(poll.get("close_ts", 0) or 0) <= now:
                    await _v32_close_poll(context, chat_id, poll, silent=True)
                    continue
                last = int(poll.get("last_remaining_edit_ts", 0) or 0)

                if now - last >= 60:
                    poll["last_remaining_edit_ts"] = now
                    save_all_states()
                    try:
                        await _v33_send_or_edit_poll_message(context, chat_id, poll)
                    except Exception:
                        logger.exception("No se pudo refrescar tiempo de encuesta %s", poll.get("id"))
        except Exception:
            logger.exception("Error revisando/actualizando encuestas del chat %s", chat_id)
    await _old_poll_close_loop_v42(context)


def _imp_games(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    games = cfg.setdefault("impostor_games", [])
    if not isinstance(games, list):
        games = []
        cfg["impostor_games"] = games
    return games


def _imp_next_id(chat_id: int) -> int:
    ids = []
    for g in _imp_games(chat_id):
        try: ids.append(int(g.get("id", 0) or 0))
        except Exception: pass
    return max(ids) + 1 if ids else 1


def _imp_find(chat_id: int, game_id: int) -> Optional[Dict[str, Any]]:
    for g in _imp_games(chat_id):
        try:
            if int(g.get("id", 0) or 0) == int(game_id):
                return g
        except Exception:
            pass
    return None


def _imp_player(game: Dict[str, Any], user_id: int) -> Optional[Dict[str, Any]]:
    for p in game.get("players", []) if isinstance(game.get("players"), list) else []:
        try:
            if int(p.get("id", 0) or 0) == int(user_id):
                return p
        except Exception:
            continue
    return None


def _imp_mention(player: Dict[str, Any]) -> str:
    uid = int(player.get("id", 0) or 0)
    name = h(player.get("name") or str(uid))
    return f'<a href="tg://user?id={uid}">{name}</a>'


def _imp_lobby_text(game: Dict[str, Any]) -> str:
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    lines = [
        "🎭 <b>Juego del Impostor</b>", "",
        "Todos tendrán una palabra secreta… menos el impostor.",
        "El impostor tendrá que disimular y parecer que sabe de qué va la cosa 😏", "",
        f"Jugadores: <b>{len(players)}</b>",
    ]
    if players:
        lines.append("")
        for i, p in enumerate(players, 1):
            lines.append(f"{i}. {_imp_mention(p)}")
    lines.extend(["", "Mínimo 3 jugadores. Máximo recomendado: 12."])
    return "\n".join(lines)


def _imp_lobby_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🙋 Unirme", callback_data=f"imp|join|{chat_id}|{gid}"), InlineKeyboardButton("🚪 Salir", callback_data=f"imp|leave|{chat_id}|{gid}")],
        [InlineKeyboardButton("▶️ Empezar", callback_data=f"imp|start|{chat_id}|{gid}"), InlineKeyboardButton("❌ Cancelar", callback_data=f"imp|cancel|{chat_id}|{gid}")],
    ])


def _imp_secret_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows: List[List[InlineKeyboardButton]] = []
    row: List[InlineKeyboardButton] = []
    for p in game.get("players", []):
        row.append(InlineKeyboardButton(f"🔐 {str(p.get('name','Jugador'))[:20]}", callback_data=f"imp|secret|{chat_id}|{gid}|{int(p.get('id',0) or 0)}"))
        if len(row) == 2:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("🎲 Siguiente turno", callback_data=f"imp|next|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


def _imp_turn_text(game: Dict[str, Any]) -> str:
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    if not players:
        return "🎭 Partida sin jugadores."
    idx = int(game.get("turn_idx", 0) or 0) % len(players)
    rnd = int(game.get("round", 1) or 1)
    p = players[idx]
    prompts = {
        1: "Da una pista suave de tu palabra, sin decirla directamente.",
        2: "Di una frase que encaje con tu palabra y observa quién se pone nervioso.",
        3: "Última ronda: defiende tu teoría y señala quién te huele a impostor.",
    }
    return (
        f"🎭 <b>Impostor · Ronda {rnd}/3</b>\n\n"
        f"Turno de {_imp_mention(p)}\n\n"
        f"💬 {prompts.get(rnd, prompts[3])}\n\n"
        "Cuando conteste, pulsa <b>Siguiente turno</b>."
    )


def _imp_turn_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows = [[InlineKeyboardButton("🎲 Siguiente turno", callback_data=f"imp|next|{chat_id}|{gid}")]]
    rows.append([InlineKeyboardButton("🗳 Votar impostor", callback_data=f"imp|vote_menu|{chat_id}|{gid}"), InlineKeyboardButton("❌ Cancelar", callback_data=f"imp|cancel|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


def _imp_vote_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows: List[List[InlineKeyboardButton]] = []
    row: List[InlineKeyboardButton] = []
    for p in game.get("players", []):
        row.append(InlineKeyboardButton(str(p.get("name", "Jugador"))[:22], callback_data=f"imp|vote|{chat_id}|{gid}|{int(p.get('id',0) or 0)}"))
        if len(row) == 2:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("🔙 Volver al turno", callback_data=f"imp|show_turn|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == "private":
        await update.message.reply_text("Usa /impostor dentro del grupo.")
        return
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get("status")) in ("lobby", "active", "voting")), None)
    if active:
        await update.message.reply_html("Ya hay una partida de Impostor activa. Cancélala o termínala antes de crear otra.")
        return
    raw = " ".join(context.args).strip() if getattr(context, "args", None) else ""
    word = raw[:60] if raw else secrets.choice(IMPOSTOR_WORDS)
    gid = _imp_next_id(chat_id)
    creator = update.effective_user
    game = {
        "id": gid,
        "status": "lobby",
        "word": word,
        "creator_id": int(creator.id),
        "created_ts": int(time.time()),
        "players": [{"id": int(creator.id), "name": display_name(creator)}],
        "round": 1,
        "turn_idx": 0,
        "votes": {},
        "impostor_id": 0,
        "message_id": 0,
    }
    msg = await update.message.reply_html(_imp_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game["message_id"] = msg.message_id
    _imp_games(chat_id).insert(0, game)
    save_all_states()


async def impostorstop_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text("Solo administradores pueden cancelar una partida.")
        return
    for g in _imp_games(chat_id):
        if str(g.get("status")) in ("lobby", "active", "voting"):
            g["status"] = "cancelled"; save_all_states()
            await update.message.reply_text("🎭 Partida de Impostor cancelada.")
            return
    await update.message.reply_text("No hay partida activa.")


async def _imp_finish(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = "") -> None:
    game["status"] = "finished"
    imp_id = int(game.get("impostor_id", 0) or 0)
    imp = _imp_player(game, imp_id) or {"id": imp_id, "name": "Impostor"}
    word = h(game.get("word") or "")
    votes = game.get("votes") if isinstance(game.get("votes"), dict) else {}
    counts: Dict[int, int] = {}
    for target in votes.values():
        try: counts[int(target)] = counts.get(int(target), 0) + 1
        except Exception: pass
    voted_txt = ""
    if counts:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        top = _imp_player(game, top_id) or {"id": top_id, "name": str(top_id)}
        voted_txt = f"\nEl más votado fue {_imp_mention(top)} con <b>{top_votes}</b> votos."
    txt = (
        "🎭 <b>Fin del juego del Impostor</b>\n\n"
        f"La palabra era: <b>{word}</b>\n"
        f"El impostor era: {_imp_mention(imp)} 😈"
        f"{voted_txt}"
    )
    if reason:
        txt += f"\n\n{reason}"
    save_all_states()
    await context.bot.send_message(chat_id, txt, parse_mode=ParseMode.HTML)


async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    if len(parts) < 4:
        await q.answer(); return
    action = parts[1]
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer("Partida inválida", show_alert=True); return
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer("No encuentro la partida", show_alert=True); return
    uid = int(q.from_user.id)

    if action == "join":
        if str(game.get("status")) != "lobby":
            await q.answer("La partida ya empezó", show_alert=True); return
        if _imp_player(game, uid):
            await q.answer("Ya estás dentro ✅"); return
        players = game.setdefault("players", [])
        if len(players) >= 20:
            await q.answer("Máximo 20 jugadores", show_alert=True); return
        players.append({"id": uid, "name": display_name(q.from_user)})
        save_all_states()
        try:
            await q.edit_message_text(_imp_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
        except Exception:
            pass
        await q.answer("Te has unido 🎭")
        return

    if action == "leave":
        if str(game.get("status")) != "lobby":
            await q.answer("La partida ya empezó", show_alert=True); return
        game["players"] = [p for p in game.get("players", []) if int(p.get("id", 0) or 0) != uid]
        save_all_states()
        try:
            await q.edit_message_text(_imp_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
        except Exception:
            pass
        await q.answer("Has salido")
        return

    if action == "cancel":
        allowed = uid == int(game.get("creator_id", 0) or 0) or await is_admin(context, chat_id, uid)
        if not allowed:
            await q.answer("Solo creador/admin", show_alert=True); return
        game["status"] = "cancelled"; save_all_states()
        try:
            await q.edit_message_text("🎭 Partida de Impostor cancelada.")
        except Exception:
            await context.bot.send_message(chat_id, "🎭 Partida de Impostor cancelada.")
        await q.answer("Cancelada")
        return

    if action == "start":
        allowed = uid == int(game.get("creator_id", 0) or 0) or await is_admin(context, chat_id, uid)
        if not allowed:
            await q.answer("Solo creador/admin puede empezar", show_alert=True); return
        players = game.get("players", [])
        if len(players) < 3:
            await q.answer("Mínimo 3 jugadores", show_alert=True); return
        game["status"] = "active"
        game["round"] = 1
        game["turn_idx"] = 0
        game["votes"] = {}
        game["impostor_id"] = int(secrets.choice(players).get("id"))
        save_all_states()
        await q.answer("Partida iniciada")
        try:
            await q.edit_message_text("🎭 <b>Partida iniciada</b>\n\nCada jugador debe pulsar su botón para ver su palabra secreta.", parse_mode=ParseMode.HTML, reply_markup=_imp_secret_markup(chat_id, game))
        except Exception:
            await context.bot.send_message(chat_id, "🎭 <b>Partida iniciada</b>\n\nCada jugador debe pulsar su botón para ver su palabra secreta.", parse_mode=ParseMode.HTML, reply_markup=_imp_secret_markup(chat_id, game))
        await context.bot.send_message(chat_id, _imp_turn_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_turn_markup(chat_id, game))
        return

    if action == "secret":
        if len(parts) < 5:
            await q.answer("Botón inválido", show_alert=True); return
        target_uid = int(parts[4])
        if uid != target_uid:
            await q.answer("Este secreto no es para ti 😏", show_alert=True); return
        if int(game.get("impostor_id", 0) or 0) == uid:
            await q.answer("😈 ERES EL IMPOSTOR. No sabes la palabra. Disimula y acusa con cabeza.", show_alert=True)
        else:
            await q.answer(f"🔐 Tu palabra es: {game.get('word')}", show_alert=True)
        return

    if action in ("next", "show_turn"):
        if str(game.get("status")) not in ("active", "voting"):
            await q.answer("La partida no está activa", show_alert=True); return
        players = game.get("players", [])
        if not players:
            await q.answer("Sin jugadores", show_alert=True); return
        if action == "next":

            current = players[int(game.get("turn_idx", 0) or 0) % len(players)]
            if uid != int(current.get("id", 0) or 0) and not await is_admin(context, chat_id, uid):
                await q.answer("Solo el jugador del turno o admin puede avanzar", show_alert=True); return
            game["turn_idx"] = int(game.get("turn_idx", 0) or 0) + 1
            if int(game["turn_idx"]) >= len(players):
                game["turn_idx"] = 0
                game["round"] = int(game.get("round", 1) or 1) + 1
            if int(game.get("round", 1) or 1) > 3:
                game["status"] = "voting"
                save_all_states()
                await q.edit_message_text("🗳 <b>Votación final</b>\n\n¿Quién crees que es el impostor?", parse_mode=ParseMode.HTML, reply_markup=_imp_vote_markup(chat_id, game))
                await q.answer("Votación final")
                return
            save_all_states()
        await q.edit_message_text(_imp_turn_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_turn_markup(chat_id, game))
        await q.answer()
        return

    if action == "vote_menu":
        if uid not in [int(p.get("id", 0) or 0) for p in game.get("players", [])]:
            await q.answer("Solo jugadores pueden votar", show_alert=True); return
        game["status"] = "voting"; save_all_states()
        await q.edit_message_text("🗳 <b>Votación</b>\n\n¿Quién crees que es el impostor?", parse_mode=ParseMode.HTML, reply_markup=_imp_vote_markup(chat_id, game))
        await q.answer()
        return

    if action == "vote":
        if len(parts) < 5:
            await q.answer("Voto inválido", show_alert=True); return
        if uid not in [int(p.get("id", 0) or 0) for p in game.get("players", [])]:
            await q.answer("Solo jugadores pueden votar", show_alert=True); return
        target_uid = int(parts[4])
        votes = game.setdefault("votes", {})
        votes[str(uid)] = target_uid
        save_all_states()
        players = game.get("players", [])
        if len(votes) >= len(players):
            await q.answer("Voto guardado. Fin de partida ✅")
            await _imp_finish(context, chat_id, game)
            try:
                await q.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass
        else:
            await q.answer(f"Voto guardado ✅ ({len(votes)}/{len(players)})")
        return

    await q.answer()


_old_build_application_v42 = build_application
def build_application() -> Application:
    app = _old_build_application_v42()
    app.add_handler(command_handler("impostor", impostor_command))
    app.add_handler(command_handler("impostorstop", impostorstop_command))
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern="^imp\\|"))
    return app


def _dj_private_recent_store(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    store = cfg.setdefault("dj_private_recent_tracks_by_user", {})
    if not isinstance(store, dict):
        store = {}
        cfg["dj_private_recent_tracks_by_user"] = store
    return store


def _track_from_stored_dict(data: Dict[str, Any]) -> Optional[Track]:
    try:
        clean = {k: v for k, v in dict(data).items() if not str(k).startswith("_")}
        return Track(**clean)
    except Exception:
        return None


def _dj_private_recent_tracks(chat_id: int, user_id: int, *, seconds: int = 1800, limit: int = 100) -> List[Track]:
    now = int(time.time())
    rows: List[Tuple[int, Track]] = []
    store = _dj_private_recent_store(chat_id)
    user_bucket = store.get(str(user_id), [])
    if isinstance(user_bucket, list):
        for raw in user_bucket:
            if not isinstance(raw, dict):
                continue
            ts = int(raw.get("_detected_at", 0) or 0)
            if ts and now - ts > seconds:
                continue
            tr = _track_from_stored_dict(raw)
            if tr:
                rows.append((ts, tr))

    try:
        for tr in _recent_detected_tracks_v21(chat_id, seconds=seconds, limit=limit):
            rows.append((now, tr))
    except Exception:
        pass
    rows.sort(key=lambda x: x[0])
    out: List[Track] = []
    seen: set[str] = set()
    for _ts, tr in rows:
        fp = track_fingerprint(tr)
        if fp in seen:
            continue
        seen.add(fp)
        out.append(tr)
        if len(out) >= limit:
            break
    return out


def _remember_dj_private_recent(chat_id: int, user_id: int, track: Track) -> None:
    store = _dj_private_recent_store(chat_id)
    bucket = store.setdefault(str(user_id), [])
    if not isinstance(bucket, list):
        bucket = []
    data = asdict(track)
    data["_detected_at"] = int(time.time())
    data["_detected_by"] = int(user_id)
    bucket.append(data)

    bucket = bucket[-120:]
    store[str(user_id)] = bucket
    admin_cfg(chat_id)["dj_private_recent_tracks_by_user"] = store
    save_all_states()


_old_dj_private_music_router_v43 = dj_private_music_router
async def dj_private_music_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type != "private":
        return
    target_chat_id = dj_selected_private_group(update.effective_user.id)
    if target_chat_id is None:
        return
    if not (await is_admin(context, target_chat_id, update.effective_user.id) or await is_controller(context, target_chat_id, update.effective_user.id)):
        return
    track = extract_track_from_message(update.message)
    if not track:
        return
    register_detected_track(update.effective_chat.id, update.message.message_id, track, update.effective_user.id)
    _remember_dj_private_recent(target_chat_id, update.effective_user.id, track)
    keyboard = InlineKeyboardMarkup([
        [InlineKeyboardButton("⏭️ Primera cola", callback_data=f"djtrack|first|{target_chat_id}|{update.message.message_id}")],
        [InlineKeyboardButton("➕ Cola final", callback_data=f"djtrack|queue|{target_chat_id}|{update.message.message_id}"), InlineKeyboardButton("📚 Biblioteca", callback_data=f"djtrack|lib|{target_chat_id}|{update.message.message_id}")],
        [InlineKeyboardButton("➕ Todas recientes a cola", callback_data=f"djpriv|recentall|{target_chat_id}")],
    ])
    await update.message.reply_html(
        f"🎛️ <b>DJ-PLAN privado</b>\nDetectada: <b>{h(track.title)}</b>\nGrupo destino: <code>{target_chat_id}</code>\n\nPuedes añadir esta canción o todas las recientes de golpe.",
        reply_markup=keyboard,
    )


_old_djprivate_callback_router_v43 = djprivate_callback_router
async def djprivate_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    data = query.data if query else ""
    if query and data.startswith("djpriv|recentall|"):
        try:
            parts = data.split("|")
            chat_id = int(parts[2])
        except Exception:
            await query.answer("Grupo no válido.", show_alert=True)
            return
        if not await is_admin(context, chat_id, update.effective_user.id):
            await query.answer("Solo administradores del grupo vinculado.", show_alert=True)
            return
        tracks = _dj_private_recent_tracks(chat_id, int(update.effective_user.id), seconds=1800, limit=100)
        if not tracks:
            await query.answer("No hay canciones recientes detectadas para este grupo.", show_alert=True)
            return
        added = 0
        for tr in tracks:
            try:
                tr.added_by_id = int(update.effective_user.id)
                tr.added_by_name = display_name(update.effective_user)
                await queue_track(chat_id, tr)
                added += 1
            except Exception:
                logger.exception("No se pudo añadir reciente privada a cola")
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
        await query.answer(f"Añadidas {added} recientes a cola ✅", show_alert=True)
        try:
            await query.edit_message_text(dj_private_text(chat_id), reply_markup=dj_private_markup(chat_id), parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return
    return await _old_djprivate_callback_router_v43(update, context)


def _imp_active_players(game: Dict[str, Any]) -> List[Dict[str, Any]]:
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    eliminated = {int(x) for x in game.get("eliminated", []) if str(x).lstrip("-").isdigit()}
    return [p for p in players if int(p.get("id", 0) or 0) not in eliminated]


def _imp_eliminated_names(game: Dict[str, Any]) -> str:
    eliminated = {int(x) for x in game.get("eliminated", []) if str(x).lstrip("-").isdigit()}
    if not eliminated:
        return "Nadie"
    names = []
    for p in game.get("players", []):
        if int(p.get("id", 0) or 0) in eliminated:
            names.append(str(p.get("name") or p.get("id")))
    return ", ".join(names) if names else "Nadie"


def _imp_turn_text(game: Dict[str, Any]) -> str:
    players = _imp_active_players(game)
    if not players:
        return "🎭 <b>Impostor</b>\n\nNo quedan jugadores activos."
    idx = int(game.get("turn_idx", 0) or 0) % len(players)
    current = players[idx]
    ronda = int(game.get("round", 1) or 1)
    return (
        "🎭 <b>Juego del Impostor</b>\n\n"
        f"Ronda: <b>{ronda}/3</b>\n"
        f"Turno de: {_imp_mention(current)}\n\n"
        "🗣️ <b>Di una palabra, frase corta o pista</b> relacionada con tu palabra secreta.\n"
        "La gracia es seguir el hilo sin delatarte.\n"
        "Si eres el impostor, disimula, escucha a los demás y acusa con cabeza 😈\n\n"
        f"Eliminados: <i>{h(_imp_eliminated_names(game))}</i>"
    )


def _imp_accuse_markup(chat_id: int, game: Dict[str, Any], accuser_id: int) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows: List[List[InlineKeyboardButton]] = []
    row: List[InlineKeyboardButton] = []
    for p in _imp_active_players(game):
        pid = int(p.get("id", 0) or 0)
        if pid == int(accuser_id):
            continue
        row.append(InlineKeyboardButton(str(p.get("name", "Jugador"))[:22], callback_data=f"imp|accuse|{chat_id}|{gid}|{accuser_id}|{pid}"))
        if len(row) == 2:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("🔙 Volver al turno", callback_data=f"imp|show_turn|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


def _imp_turn_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Ya he dicho mi palabra", callback_data=f"imp|next|{chat_id}|{gid}")],
        [InlineKeyboardButton("🚨 El impostor es...", callback_data=f"imp|accuse_menu|{chat_id}|{gid}")],
        [InlineKeyboardButton("🔐 Ver mi palabra", callback_data=f"imp|mysecret|{chat_id}|{gid}")],
        [InlineKeyboardButton("🗳 Votación final", callback_data=f"imp|vote_menu|{chat_id}|{gid}")],
    ])


def _imp_vote_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows: List[List[InlineKeyboardButton]] = []
    row: List[InlineKeyboardButton] = []
    for p in _imp_active_players(game):
        row.append(InlineKeyboardButton(str(p.get("name", "Jugador"))[:22], callback_data=f"imp|vote|{chat_id}|{gid}|{int(p.get('id',0) or 0)}"))
        if len(row) == 2:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("🔙 Volver al turno", callback_data=f"imp|show_turn|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


def _imp_current_player(game: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    players = _imp_active_players(game)
    if not players:
        return None
    return players[int(game.get("turn_idx", 0) or 0) % len(players)]


_old_impostor_callback_router_v43 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    if not data.startswith("imp|") or len(parts) < 4:
        return await _old_impostor_callback_router_v43(update, context)
    action = parts[1]
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer("Partida inválida", show_alert=True); return
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer("No encuentro la partida", show_alert=True); return
    uid = int(q.from_user.id)

    if action == "start":

        await _old_impostor_callback_router_v43(update, context)
        g2 = _imp_find(chat_id, gid)
        if g2:
            g2.setdefault("eliminated", [])
            g2.setdefault("accusations", [])
            g2.setdefault("spoken", {})
            save_all_states()
        return

    if action == "mysecret":
        if uid not in [int(p.get("id", 0) or 0) for p in game.get("players", [])]:
            await q.answer("No estás jugando esta partida.", show_alert=True); return
        if int(game.get("impostor_id", 0) or 0) == uid:
            await q.answer("😈 ERES EL IMPOSTOR. No sabes la palabra. Disimula y acusa a otro cuando puedas.", show_alert=True)
        else:
            await q.answer(f"🔐 Tu palabra es: {game.get('word')}", show_alert=True)
        return

    if action == "accuse_menu":
        if str(game.get("status")) not in ("active", "voting"):
            await q.answer("La partida no está activa.", show_alert=True); return
        active_ids = [int(p.get("id", 0) or 0) for p in _imp_active_players(game)]
        if uid not in active_ids:
            await q.answer("Estás eliminado o no juegas esta partida.", show_alert=True); return
        await q.answer("Elige a quién acusas")
        await q.edit_message_text("🚨 <b>El impostor es...</b>\n\nElige a quién acusas. Si fallas, quedas eliminado.", parse_mode=ParseMode.HTML, reply_markup=_imp_accuse_markup(chat_id, game, uid))
        return

    if action == "accuse":
        if len(parts) < 6:
            await q.answer("Acusación inválida", show_alert=True); return
        try:
            accuser_id = int(parts[4]); target_id = int(parts[5])
        except Exception:
            await q.answer("Acusación inválida", show_alert=True); return
        if uid != accuser_id:
            await q.answer("Esta acusación no es tuya.", show_alert=True); return
        active_ids = [int(p.get("id", 0) or 0) for p in _imp_active_players(game)]
        if accuser_id not in active_ids:
            await q.answer("Ya estás eliminado.", show_alert=True); return
        game.setdefault("accusations", []).append({"by": accuser_id, "target": target_id, "ts": int(time.time())})
        if target_id == int(game.get("impostor_id", 0) or 0):
            acc = _imp_player(game, accuser_id) or {"id": accuser_id, "name": str(accuser_id)}
            tgt = _imp_player(game, target_id) or {"id": target_id, "name": str(target_id)}
            await q.answer("¡Correcto! Era el impostor ✅", show_alert=True)
            await _imp_finish(context, chat_id, game, reason=f"\n{_imp_mention(acc)} acertó acusando a {_imp_mention(tgt)}.")
            try:
                await q.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass
            return

        eliminated = game.setdefault("eliminated", [])
        if accuser_id not in [int(x) for x in eliminated if str(x).lstrip('-').isdigit()]:
            eliminated.append(accuser_id)
        active = _imp_active_players(game)
        save_all_states()
        wrong = _imp_player(game, accuser_id) or {"id": accuser_id, "name": str(accuser_id)}
        target = _imp_player(game, target_id) or {"id": target_id, "name": str(target_id)}
        if len(active) <= 2:
            await q.answer("Fallaste y quedas eliminado. Fin de partida.", show_alert=True)
            await _imp_finish(context, chat_id, game, reason=f"\n{_imp_mention(wrong)} acusó a {_imp_mention(target)} y falló.")
            return

        game["turn_idx"] = int(game.get("turn_idx", 0) or 0) % max(1, len(active))
        save_all_states()
        await q.answer("Fallaste: quedas eliminado ❌", show_alert=True)
        await q.edit_message_text(
            f"❌ {_imp_mention(wrong)} acusó a {_imp_mention(target)} y falló.\n\nSigue el juego.",
            parse_mode=ParseMode.HTML,
            reply_markup=_imp_turn_markup(chat_id, game),
        )
        return

    if action in ("next", "show_turn"):
        if str(game.get("status")) not in ("active", "voting"):
            await q.answer("La partida no está activa", show_alert=True); return
        active = _imp_active_players(game)
        if not active:
            await q.answer("Sin jugadores activos", show_alert=True); return
        if action == "next":
            current = active[int(game.get("turn_idx", 0) or 0) % len(active)]
            if uid != int(current.get("id", 0) or 0) and not await is_admin(context, chat_id, uid):
                await q.answer("Solo el jugador del turno o admin puede avanzar", show_alert=True); return
            game["turn_idx"] = int(game.get("turn_idx", 0) or 0) + 1
            if int(game["turn_idx"]) >= len(active):
                game["turn_idx"] = 0
                game["round"] = int(game.get("round", 1) or 1) + 1
            if int(game.get("round", 1) or 1) > 3:
                game["status"] = "voting"
                save_all_states()
                await q.edit_message_text("🗳 <b>Votación final</b>\n\n¿Quién crees que es el impostor?", parse_mode=ParseMode.HTML, reply_markup=_imp_vote_markup(chat_id, game))
                await q.answer("Votación final")
                return
            save_all_states()
        await q.edit_message_text(_imp_turn_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_turn_markup(chat_id, game))
        await q.answer()
        return

    if action == "vote_menu":
        if uid not in [int(p.get("id", 0) or 0) for p in _imp_active_players(game)]:
            await q.answer("Solo jugadores activos pueden votar", show_alert=True); return
        game["status"] = "voting"; save_all_states()
        await q.edit_message_text("🗳 <b>Votación final</b>\n\n¿Quién crees que es el impostor?", parse_mode=ParseMode.HTML, reply_markup=_imp_vote_markup(chat_id, game))
        await q.answer()
        return


    return await _old_impostor_callback_router_v43(update, context)


def _owner_alert_targets() -> List[int]:
    raw = os.getenv("BOT_OWNER_IDS", "").strip()
    ids: set[int] = set()
    if raw:
        for part in raw.split(","):
            try:
                ids.add(int(part.strip()))
            except Exception:
                pass
    ids.update(int(x) for x in ADMIN_IDS)
    return sorted(ids)


async def _send_owner_private_alert(context: ContextTypes.DEFAULT_TYPE, text: str, *, url: Optional[str] = None) -> None:
    markup = InlineKeyboardMarkup([[InlineKeyboardButton("➡️ Ir al mensaje", url=url)]]) if url else None
    for uid in _owner_alert_targets():
        try:
            await context.bot.send_message(uid, text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
        except Exception:

            pass


def _chat_message_url_from_message(message) -> Optional[str]:
    try:
        chat = message.chat
        if getattr(chat, "username", None):
            return f"https://t.me/{chat.username}/{message.message_id}"
        cid = str(message.chat_id)
        if cid.startswith("-100"):
            return f"https://t.me/c/{cid[4:]}/{message.message_id}"
    except Exception:
        pass
    return None


async def _v43_new_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    if not getattr(update.message, "new_chat_members", None):
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    for user in update.message.new_chat_members:
        if getattr(user, "is_bot", False):
            continue
        mention = user.mention_html()
        await _send_owner_private_alert(context, f"👋 {mention} ha entrado en <b>{chat_title}</b>.", url=_chat_message_url_from_message(update.message))


async def _v43_left_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not getattr(update.message, "left_chat_member", None):
        return
    user = update.message.left_chat_member
    if getattr(user, "is_bot", False):
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    await _send_owner_private_alert(context, f"🚪 {user.mention_html()} ha salido/ha sido expulsado de <b>{chat_title}</b>.", url=_chat_message_url_from_message(update.message))


async def _v43_chat_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, "chat_member", None)
    if not cmu or not getattr(cmu, "chat", None):
        return
    chat_title = h(getattr(cmu.chat, "title", "Grupo") or "Grupo")
    old = getattr(cmu, "old_chat_member", None)
    new = getattr(cmu, "new_chat_member", None)
    user = getattr(old, "user", None) or getattr(new, "user", None)
    if not user or getattr(user, "is_bot", False):
        return
    old_status = str(getattr(old, "status", "") or "")
    new_status = str(getattr(new, "status", "") or "")
    actor = getattr(cmu, "from_user", None)
    actor_txt = f" por {actor.mention_html()}" if actor else ""
    if old_status not in ("left", "kicked", "") and new_status == "kicked":
        await _send_owner_private_alert(context, f"⛔ {user.mention_html()} ha sido expulsado de <b>{chat_title}</b>{actor_txt}.")
    elif old_status not in ("left", "kicked", "") and new_status == "left":
        await _send_owner_private_alert(context, f"🚪 {user.mention_html()} ha salido de <b>{chat_title}</b>.")
    elif new_status in ("restricted",) and getattr(new, "can_send_messages", True) is False:
        await _send_owner_private_alert(context, f"🔇 {user.mention_html()} ha sido silenciado en <b>{chat_title}</b>{actor_txt}.")


async def owner_mention_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    text = (update.message.text or update.message.caption or "")
    if not text:
        return

    targets = _owner_alert_targets()
    mentioned = False

    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        if int(update.message.reply_to_message.from_user.id) in targets:
            mentioned = True

    try:
        entities = list(update.message.entities or []) + list(update.message.caption_entities or [])
        for ent in entities:
            user = getattr(ent, "user", None)
            if user and int(user.id) in targets:
                mentioned = True
                break
    except Exception:
        pass
    if not mentioned:
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    sender = update.effective_user.mention_html()
    snippet = h(text[:300])
    await _send_owner_private_alert(context, f"🔔 {sender} te ha mencionado/respondido en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=_chat_message_url_from_message(update.message))


_old_build_application_v43 = build_application
def build_application() -> Application:
    app = _old_build_application_v43()

    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, _v43_new_member_alert), group=-60)
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER, _v43_left_member_alert), group=-60)
    app.add_handler(ChatMemberHandler(_v43_chat_member_alert, ChatMemberHandler.CHAT_MEMBER), group=-60)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, owner_mention_alert_handler), group=-61)

    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern="^imp\\|"), group=-55)

    app.add_handler(CallbackQueryHandler(djprivate_callback_router, pattern="^djpriv\\|"), group=-55)
    return app


def _v44_today_key(ts: Optional[int] = None) -> str:
    import datetime
    ts = int(ts or time.time())
    return datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d")


def _v44_week_key(ts: Optional[int] = None) -> str:
    import datetime
    ts = int(ts or time.time())
    d = datetime.datetime.fromtimestamp(ts).date()
    y, w, _ = d.isocalendar()
    return f"{y}-W{w:02d}"


def _imp_score_store(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    store = cfg.setdefault("impostor_ranking", {"general": {}, "daily": {}, "weekly": {}})
    if not isinstance(store, dict):
        store = {"general": {}, "daily": {}, "weekly": {}}
        cfg["impostor_ranking"] = store
    store.setdefault("general", {})
    store.setdefault("daily", {})
    store.setdefault("weekly", {})
    return store


def _imp_add_points(chat_id: int, player: Dict[str, Any], points: int) -> None:
    try:
        uid = str(int(player.get("id", 0) or 0))
    except Exception:
        return
    if not uid or uid == "0":
        return
    name = str(player.get("name") or uid)
    store = _imp_score_store(chat_id)
    for scope, key in (("general", "all"), ("daily", _v44_today_key()), ("weekly", _v44_week_key())):
        bucket = store.setdefault(scope, {})
        period = bucket.setdefault(key, {})
        row = period.setdefault(uid, {"name": name, "points": 0, "games": 0})
        row["name"] = name
        row["points"] = int(row.get("points", 0) or 0) + int(points)
        row["games"] = int(row.get("games", 0) or 0) + 1


def _imp_score_game(chat_id: int, game: Dict[str, Any], winner_side: str) -> str:
    if game.get("ranking_scored"):
        return ""
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    eliminated = {int(x) for x in game.get("eliminated", []) if str(x).lstrip("-").isdigit()}
    imp_id = int(game.get("impostor_id", 0) or 0)
    winners: List[int] = []
    for p in players:
        pid = int(p.get("id", 0) or 0)
        if pid in eliminated:
            _imp_add_points(chat_id, p, 1)
        elif winner_side == "impostor" and pid == imp_id:
            _imp_add_points(chat_id, p, 5)
            winners.append(pid)
        elif winner_side == "crew" and pid != imp_id:
            _imp_add_points(chat_id, p, 5)
            winners.append(pid)
        else:
            _imp_add_points(chat_id, p, 2)
    game["ranking_scored"] = True
    save_all_states()
    if winner_side == "crew":
        return "\n🏆 Gana el grupo: +5 pts para quienes pillaron al impostor."
    if winner_side == "impostor":
        return "\n🏆 Gana el impostor: +5 pts por sobrevivir."
    return ""


def _imp_ranking_text(chat_id: int, scope: str = "general") -> str:
    scope = (scope or "general").lower()
    if scope in ("dia", "día", "diario", "daily"):
        scope = "daily"; key = _v44_today_key(); title = "diario"
    elif scope in ("semana", "semanal", "weekly"):
        scope = "weekly"; key = _v44_week_key(); title = "semanal"
    else:
        scope = "general"; key = "all"; title = "general"
    data = _imp_score_store(chat_id).get(scope, {}).get(key, {})
    rows = []
    for uid, row in data.items():
        try:
            rows.append((int(row.get("points", 0) or 0), int(row.get("games", 0) or 0), str(row.get("name") or uid)))
        except Exception:
            pass
    rows.sort(key=lambda x: (-x[0], -x[1], x[2].lower()))
    lines = [f"🎭 <b>Ranking Impostor {h(title)}</b>", ""]
    if not rows:
        lines.append("Todavía no hay puntos.")
    else:
        for i, (pts, games, name) in enumerate(rows[:15], 1):
            lines.append(f"{i}. <b>{h(name)}</b> — {pts} pts · {games} partidas")
    lines.extend(["", "Puntos: ganador 5 · finalista 2 · eliminado 1"])
    return "\n".join(lines)


async def rankingimpostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    scope = " ".join(context.args).strip() if getattr(context, "args", None) else "general"
    await update.message.reply_html(_imp_ranking_text(int(update.effective_chat.id), scope))


