async def _v44_chat_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, "chat_member", None)
    if not cmu or not getattr(cmu, "chat", None):
        return
    chat_id = int(cmu.chat.id)
    chat_title = h(getattr(cmu.chat, "title", "Grupo") or "Grupo")
    old = getattr(cmu, "old_chat_member", None)
    new = getattr(cmu, "new_chat_member", None)
    user = getattr(old, "user", None) or getattr(new, "user", None)
    if not user or getattr(user, "is_bot", False):
        return
    old_status = str(getattr(old, "status", "") or "")
    new_status = str(getattr(new, "status", "") or "")
    actor = getattr(cmu, "from_user", None)
    actor_txt = f" por {actor.mention_html()}" if actor else ""
    if old_status not in ("left", "kicked", "") and new_status == "kicked":
        await _send_owner_private_alert_typed(context, chat_id, "owner_alert_kicked_members", f"⛔ {user.mention_html()} ha sido expulsado de <b>{chat_title}</b>{actor_txt}.")
    elif old_status not in ("left", "kicked", "") and new_status == "left":
        await _send_owner_private_alert_typed(context, chat_id, "owner_alert_left_members", f"🚪 {user.mention_html()} ha salido de <b>{chat_title}</b>.")
    elif new_status in ("restricted",) and getattr(new, "can_send_messages", True) is False:
        await _send_owner_private_alert_typed(context, chat_id, "owner_alert_muted_members", f"🔇 {user.mention_html()} ha sido silenciado en <b>{chat_title}</b>{actor_txt}.")


async def owner_mention_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)) or not bool(cfg_value(chat_id, "owner_alert_mentions", True)):
        return
    text = (update.message.text or update.message.caption or "")
    if not text:
        return
    targets = _owner_alert_targets()
    mentioned = False
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        if int(update.message.reply_to_message.from_user.id) in targets:
            mentioned = True
    try:
        entities = list(update.message.entities or []) + list(update.message.caption_entities or [])
        for ent in entities:
            user = getattr(ent, "user", None)
            if user and int(user.id) in targets:
                mentioned = True
                break
    except Exception:
        pass
    if not mentioned:
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    sender = update.effective_user.mention_html()
    snippet = h(text[:300])
    await _send_owner_private_alert_typed(context, chat_id, "owner_alert_mentions", f"🔔 {sender} te ha mencionado/respondido en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=_chat_message_url_from_message(update.message))


_old_build_application_v44 = build_application
def build_application() -> Application:
    app = _old_build_application_v44()

    app.add_handler(command_handler("rankingimpostor", rankingimpostor_command), group=-80)
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern="^imp\\|"), group=-85)
    app.add_handler(CallbackQueryHandler(djprivate_callback_router, pattern="^djpriv\\|"), group=-85)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern="^cfg\\|alert_"), group=-85)
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, _v44_new_member_alert), group=-90)
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER, _v44_left_member_alert), group=-90)
    app.add_handler(ChatMemberHandler(_v44_chat_member_alert, ChatMemberHandler.CHAT_MEMBER), group=-90)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, owner_mention_alert_handler), group=-91)
    return app


import datetime as _dt
