async def cerebrito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    prompt = " ".join(context.args).strip() if getattr(context, "args", None) else ""
    if not prompt:
        await update.message.reply_html("Usa: <code>/cerebrito tu pregunta</code>")
        return
    if not bool(cfg_value(chat_id, "ai_enabled", True)):
        await update.message.reply_text("🧠 Cerebrito está desactivado en este grupo.")
        return
    if _ai_limit_reached(chat_id, int(update.effective_user.id), "planecito", "ai_planecito_daily_limit"):
        await update.message.reply_text("Has llegado al límite diario de consultas a Cerebrito.")
        return
    msg = await update.message.reply_text("🧠 Pensando...")
    answer = await _openai_chat_text(chat_id, prompt, user_name=display_name(update.effective_user), chat_title=getattr(update.effective_chat, "title", ""))
    _ai_usage_inc(chat_id, int(update.effective_user.id), "planecito")
    try:
        await msg.edit_text(answer[:3900])
    except Exception:
        await update.message.reply_text(answer[:3900])


async def planecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    return await cerebrito_command(update, context)

