async def _owner_usernames_for_chat(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> set[str]:
    names: set[str] = set()
    for uid in _owner_alert_targets():
        try:
            member = await context.bot.get_chat_member(chat_id, int(uid))
            username = getattr(getattr(member, "user", None), "username", None)
            if username:
                names.add(username.lower())
        except Exception:
            pass
    return names

async def owner_mention_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    text = (update.message.text or update.message.caption or "")
    if not text:
        return


    upper = text.upper()
    if ("#PRESENTACIÓN" in upper or "#PRESENTACION" in upper) and bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)) and bool(cfg_value(chat_id, "owner_alert_tags", True)):
        chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
        sender = update.effective_user.mention_html()
        snippet = h(text[:300])
        await _send_owner_private_alert_typed(context, chat_id, "owner_alert_tags", f"🏷 {sender} ha usado <b>#PRESENTACIÓN</b> en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=_chat_message_url_from_message(update.message))
        return

    if not bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)) or not bool(cfg_value(chat_id, "owner_alert_mentions", True)):
        return

    targets = _owner_alert_targets()
    mentioned = False
    try:
        entities = list(update.message.entities or []) + list(update.message.caption_entities or [])
        owner_usernames = await _owner_usernames_for_chat(context, chat_id)
        for ent in entities:
            user = getattr(ent, "user", None)
            if user and int(user.id) in targets:
                mentioned = True
                break
            if getattr(ent, "type", "") == "mention":
                raw = text[ent.offset:ent.offset + ent.length].lstrip("@").lower()
                if raw in owner_usernames:
                    mentioned = True
                    break
    except Exception:
        pass
    if not mentioned:
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    sender = update.effective_user.mention_html()
    snippet = h(text[:300])
    await _send_owner_private_alert_typed(context, chat_id, "owner_alert_mentions", f"🔔 {sender} te ha mencionado en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=_chat_message_url_from_message(update.message))


def _imp_last_clues_text(game: Dict[str, Any], limit: int = 6) -> str:
    clues = game.get("clues") if isinstance(game.get("clues"), list) else []
    if not clues:
        return ""
    lines = ["", "<b>🧩 Pistas:</b>"]
    for row in clues[-limit:]:
        try:
            lines.append(f"• <b>{h(row.get('name','Jugador'))}</b>: <i>{h(row.get('text',''))}</i>")
        except Exception:
            pass
    return "\n".join(lines)

_old_imp_turn_text_v46 = _imp_turn_text
def _imp_turn_text(game: Dict[str, Any]) -> str:
    players = _imp_active_players(game)
    if not players:
        return "🎭 <b>Impostor</b>\n\nNo quedan jugadores activos."
    idx = int(game.get("turn_idx", 0) or 0) % len(players)
    current = players[idx]
    ronda = int(game.get("round", 1) or 1)
    return (
        "🎭 <b>Impostor</b>\n"
        f"Ronda <b>{ronda}/3</b> · Turno de {_imp_mention(current)}\n\n"
        "Pulsa <b>✍️ Responder pista</b> y escribe una palabra o frase corta.\n"
        "No digas la palabra secreta. El impostor tiene que disimular 😏"
        f"{_imp_last_clues_text(game)}"
    )

def _imp_turn_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✍️ Responder pista", callback_data=f"imp|respond|{chat_id}|{gid}")],
        [InlineKeyboardButton("🚨 El impostor es...", callback_data=f"imp|accuse_menu|{chat_id}|{gid}")],
        [InlineKeyboardButton("🔐 Ver mi palabra", callback_data=f"imp|mysecret|{chat_id}|{gid}"), InlineKeyboardButton("🏆 Ranking", callback_data=f"imp|ranking|{chat_id}|{gid}")],
        [InlineKeyboardButton("🗳 Votación final", callback_data=f"imp|vote_menu|{chat_id}|{gid}")],
    ])

def _imp_pending_key(chat_id: int, user_id: int) -> str:
    return f"imp_clue:{int(chat_id)}:{int(user_id)}"

def _imp_advance_turn_after_clue(game: Dict[str, Any]) -> None:
    active = _imp_active_players(game)
    if not active:
        return
    game["turn_idx"] = int(game.get("turn_idx", 0) or 0) + 1
    if int(game["turn_idx"]) >= len(active):
        game["turn_idx"] = 0
        game["round"] = int(game.get("round", 1) or 1) + 1
    if int(game.get("round", 1) or 1) > 3:
        game["status"] = "voting"

async def _imp_render_game_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    mid = int(game.get("turn_message_id") or game.get("message_id") or 0)
    try:
        if str(game.get("status")) == "voting":
            text = "🗳 <b>Votación final</b>\n\n¿Quién crees que es el impostor?"
            markup = _imp_vote_markup(chat_id, game)
        else:
            text = _imp_turn_text(game)
            markup = _imp_turn_markup(chat_id, game)
        if mid:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
            game["turn_message_id"] = msg.message_id
            save_all_states()
    except Exception:
        try:
            msg = await context.bot.send_message(chat_id, _imp_turn_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_turn_markup(chat_id, game))
            game["turn_message_id"] = msg.message_id
            save_all_states()
        except Exception:
            logger.exception("No se pudo renderizar turno de impostor")

_old_impostor_callback_router_v46 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    if not data.startswith("imp|"):
        return await _old_impostor_callback_router_v46(update, context)
    parts = data.split("|")
    if len(parts) >= 4 and parts[1] == "respond":
        try:
            chat_id = int(parts[2]); gid = int(parts[3])
        except Exception:
            await q.answer("Partida inválida", show_alert=True); return
        game = _imp_find(chat_id, gid)
        if not game or str(game.get("status")) != "active":
            await q.answer("La partida no está activa", show_alert=True); return
        current = _imp_current_player(game)
        if not current or int(current.get("id", 0) or 0) != int(q.from_user.id):
            await q.answer("Ahora no te toca responder.", show_alert=True); return
        game["turn_message_id"] = q.message.message_id if q.message else int(game.get("turn_message_id") or 0)
        PENDING_ACTIONS[_imp_pending_key(chat_id, q.from_user.id)] = {"chat_id": chat_id, "gid": gid, "ts": int(time.time())}
        save_all_states()
        await q.answer("Escribe ahora tu pista en el grupo. Al enviarla, paso turno automáticamente.", show_alert=True)
        return
    return await _old_impostor_callback_router_v46(update, context)

async def impostor_clue_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == "private":
        return
    text = (update.message.text or update.message.caption or "").strip()
    if not text or text.startswith("/"):
        return
    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    key = _imp_pending_key(chat_id, uid)
    pending = PENDING_ACTIONS.get(key)
    if not pending:
        return

    if int(time.time()) - int(pending.get("ts", 0) or 0) > 300:
        PENDING_ACTIONS.pop(key, None)
        return
    game = _imp_find(chat_id, int(pending.get("gid", 0) or 0))
    if not game or str(game.get("status")) != "active":
        PENDING_ACTIONS.pop(key, None); return
    current = _imp_current_player(game)
    if not current or int(current.get("id", 0) or 0) != uid:
        PENDING_ACTIONS.pop(key, None); return
    clue = text[:140]
    game.setdefault("clues", []).append({"uid": uid, "name": display_name(update.effective_user), "text": clue, "round": int(game.get("round", 1) or 1), "ts": int(time.time())})
    PENDING_ACTIONS.pop(key, None)
    _imp_advance_turn_after_clue(game)
    save_all_states()
    await _imp_render_game_message(context, chat_id, game)


_old_build_application_v46 = build_application
def build_application() -> Application:
    app = _old_build_application_v46()

    app.add_handler(command_handler("cerebrito", cerebrito_command), group=-72)

    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, impostor_clue_text_handler), group=-120)

    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern="^imp\\|"), group=-130)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern="^cfg\\|block\\|.*\\|owner_alerts$"), group=-130)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, owner_mention_alert_handler), group=-121)
    return app


