async def cfg_private_block_direct_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ""
    if not data.startswith("cfg|"):
        return
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""


    if action not in ("block", "home"):
        return

    await q.answer()
    if not is_global_admin_user(update.effective_user.id):
        await q.answer("Solo ADMIN_IDS.", show_alert=True)
        return

    try:
        chat_id = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        await q.answer("Grupo inválido.", show_alert=True)
        return

    try:
        if action == "home":
            text = admin_private_main_text(chat_id)
            markup = admin_private_main_markup(chat_id)
        else:
            block = parts[3] if len(parts) > 3 else ""
            if block not in ADMIN_PRIVATE_BLOCK_IDS:
                text = admin_private_main_text(chat_id)
                markup = admin_private_main_markup(chat_id)
            else:
                text = admin_private_block_text(chat_id, block)
                markup = admin_private_block_markup(chat_id, block)

        try:
            await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except BadRequest as e:

            if "message is not modified" in str(e).lower():
                return
            await q.message.reply_html(text, reply_markup=markup)
        except Exception:
            await q.message.reply_html(text, reply_markup=markup)
    except Exception:
        logger.exception("Error abriendo bloque privado directo: %s", data)
        await q.answer("No pude abrir ese menú. Reintenta con /ajustes.", show_alert=True)


_old_build_application_v48 = build_application
def build_application() -> Application:
    app = _old_build_application_v48()

    app.add_handler(CallbackQueryHandler(cfg_private_block_direct_router, pattern=r"^cfg\|(block|home)\|"), group=-500)
    return app


try:
    _previous_impostor_clue_text_handler_v49 = impostor_clue_text_handler
except NameError:
    _previous_impostor_clue_text_handler_v49 = None

async def impostor_clue_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return

    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    key = _imp_pending_key(chat_id, uid) if '_imp_pending_key' in globals() else f"{chat_id}:{uid}:imp_clue"


    had_pending_before = key in PENDING_ACTIONS

    if _previous_impostor_clue_text_handler_v49:
        await _previous_impostor_clue_text_handler_v49(update, context)


    if not had_pending_before:
        return


    if key in PENDING_ACTIONS:
        return


    if bool(cfg_value(chat_id, "imp_cleanup_enabled", True)) and bool(cfg_value(chat_id, "imp_delete_player_clues", False)):
        txt = (getattr(update.message, 'text', None) or getattr(update.message, 'caption', None) or '').strip()
        if txt and not txt.startswith('/'):
            try:
                await context.bot.delete_message(chat_id=chat_id, message_id=update.message.message_id)
            except Exception:
                pass


def _apply_safe_member_message_defaults_v49(chat_id: int) -> None:
    try:
        cfg = admin_cfg(chat_id)

        cfg.setdefault('validation_delete_wrong_messages', False)

        cfg.setdefault('imp_delete_player_clues', False)
        save_all_states()
    except Exception:
        logger.exception('No pude aplicar defaults seguros de borrado')

_old_get_state_v49 = get_state
def get_state(chat_id: int) -> ChatState:
    state = _old_get_state_v49(chat_id)

    try:
        cfg = state.admin_config
        changed = False
        if 'validation_delete_wrong_messages' not in cfg:
            cfg['validation_delete_wrong_messages'] = False; changed = True
        if 'imp_delete_player_clues' not in cfg:
            cfg['imp_delete_player_clues'] = False; changed = True
        if changed:
            save_all_states()
    except Exception:
        pass
    return state


async def desbloquear_chat_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text('Solo administradores.')
        return
    cfg = admin_cfg(chat_id)
    cfg['validation_delete_wrong_messages'] = False
    cfg['imp_delete_player_clues'] = False
    cfg['service_cleanup_enabled'] = False
    cfg['command_cleanup_mode'] = 'off'
    cfg['hot_command_delete_mode'] = 'off'
    save_all_states()
    await update.message.reply_text('✅ Chat desbloqueado: ya no borraré mensajes normales de miembros. He desactivado limpieza agresiva, borrado de pistas y borrado de comandos.')

