def _v51_service_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    rows.append([InlineKeyboardButton(("✅ " if bool(cfg_value(chat_id, "service_cleanup_enabled", False)) else "❌ ") + "Limpieza automática", callback_data=f"cfg|svc_toggle|{chat_id}|service_cleanup")])
    labels = globals().get("SERVICE_CLEANUP_LABELS", {}) or {}
    if not labels:
        labels = {
            "pinned_message": "📌 Mensaje fijado", "new_chat_photo": "🖼 Foto grupo", "delete_chat_photo": "🗑 Quitar foto",
            "new_chat_title": "✏️ Título", "new_members": "👋 Entradas", "left_member": "🚪 Salidas", "video_chat": "🎧 Videochat", "other": "➕ Otros",
        }
    items = list(labels.items())
    for i in range(0, len(items), 2):
        chunk = items[i:i+2]
        row = []
        for key, label in chunk:
            try:
                active = service_cleanup_type_enabled(chat_id, key)
            except Exception:
                active = False
            row.append(InlineKeyboardButton(("✅ " if active else "❌ ") + str(label), callback_data=f"cfg|svc_type|{chat_id}|{key}|service_cleanup"))
        rows.append(row)
    rows.append([
        InlineKeyboardButton("✅ Activar recomendados", callback_data=f"cfg|svc_preset|{chat_id}|recommended|service_cleanup"),
        InlineKeyboardButton("❌ Todo OFF", callback_data=f"cfg|svc_preset|{chat_id}|off|service_cleanup"),
    ])
    rows.append([InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")])
    return InlineKeyboardMarkup(rows)


def _v51_command_cleanup_text(chat_id: int) -> str:
    try:
        label = command_cleanup_label(chat_id)
    except Exception:
        label = str(cfg_value(chat_id, "command_cleanup_mode", "off"))
    return (
        "<b>🧹 Borrado de comandos</b>\n"
        f"Grupo: <b>{h(_v51_title(chat_id))}</b>\n\n"
        f"Estado actual: <b>{h(label)}</b>\n\n"
        "Solo borra el mensaje donde alguien escribe un comando. No borra mensajes normales de miembros ni paneles."
    )


def _v51_command_cleanup_markup(chat_id: int) -> InlineKeyboardMarkup:
    def st(v: str) -> str:
        try:
            return command_cleanup_status(chat_id, v)
        except Exception:
            mode = str(cfg_value(chat_id, "command_cleanup_mode", "off"))
            ttl = int(cfg_value(chat_id, "command_cleanup_ttl_seconds", 0) or 0)
            if v == "off": return "✅" if mode == "off" else "❌"
            if v == "instant": return "✅" if mode == "instant" else "❌"
            return "✅" if mode == "ttl" and ttl == int(v) else "❌"
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"{st('off')} No borrar", callback_data=f"cfg|cleanup_set|{chat_id}|off|command_cleanup"), InlineKeyboardButton(f"{st('instant')} Al ejecutar", callback_data=f"cfg|cleanup_set|{chat_id}|instant|command_cleanup")],
        [InlineKeyboardButton(f"{st('5')} A los 5s", callback_data=f"cfg|cleanup_set|{chat_id}|5|command_cleanup"), InlineKeyboardButton(f"{st('30')} A los 30s", callback_data=f"cfg|cleanup_set|{chat_id}|30|command_cleanup")],
        [InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")],
    ])


