_old_v51_admin_private_block_text = admin_private_block_text
async def _v51_render(query, text: str, markup: Optional[InlineKeyboardMarkup] = None) -> None:
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except BadRequest as e:
        if "message is not modified" in str(e).lower():
            return
        try:
            await query.message.reply_html(text, reply_markup=markup)
        except Exception:
            logger.exception("V51 no pudo enviar panel")
    except Exception:
        try:
            await query.message.reply_html(text, reply_markup=markup)
        except Exception:
            logger.exception("V51 no pudo enviar panel")


def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    _v51_ensure_blocks()
    if block == "service_cleanup": return _v51_service_text(chat_id)
    if block == "command_cleanup": return _v51_command_cleanup_text(chat_id)
    if block == "owner_alerts": return _v51_alerts_text(chat_id)
    if block == "impostor_settings": return _v51_imp_text(chat_id)
    if block == "ai": return _v51_ai_text(chat_id)
    return _old_v51_admin_private_block_text(chat_id, block, page)


_old_v51_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    _v51_ensure_blocks()
    if block == "service_cleanup": return _v51_service_markup(chat_id)
    if block == "command_cleanup": return _v51_command_cleanup_markup(chat_id)
    if block == "owner_alerts": return _v51_alerts_markup(chat_id)
    if block == "impostor_settings": return _v51_imp_markup(chat_id)
    if block == "ai": return _v51_ai_markup(chat_id)
    return _old_v51_admin_private_block_markup(chat_id, block, page)


async def _v51_cfg_master_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ""
    if not (data.startswith("cfg|") or data.startswith("cfgsafe|")):
        return
    parts = data.split("|")
    prefix = parts[0]
    action = parts[1] if len(parts) > 1 else ""

    new_actions = {"svc_toggle", "svc_type", "svc_preset", "cleanup_set", "impconf", "alert_toggle"}
    ai_actions = action.startswith("ai_")
    is_nav = action in {"list", "open", "home", "reload", "block", "block_reload", "block_save", "close", "save"}
    target_block = parts[3] if action in {"block", "block_reload", "block_save"} and len(parts) >= 4 else ""
    if not (prefix == "cfgsafe" or action in new_actions or ai_actions or (is_nav and (target_block in {"service_cleanup", "command_cleanup", "owner_alerts", "impostor_settings", "ai", "polls"} or action in {"open", "home", "list", "close", "save"}))):
        return
    try:
        await q.answer()
    except Exception:
        pass
    if not is_global_admin_user(update.effective_user.id):
        try: await q.answer("Solo ADMIN_IDS.", show_alert=True)
        except Exception: pass
        raise _V51Stop
    _v51_ensure_blocks()
    if action == "list" or (prefix == "cfgsafe" and action == "list"):
        try:
            await _v51_render(q, "<b>Elige el grupo que quieres configurar:</b>", _v50_chat_selector_markup() if '_v50_chat_selector_markup' in globals() else admin_private_chat_selector_markup(update.effective_user.id))
        except Exception:
            logger.exception("V51 selector list")
        raise _V51Stop
    if len(parts) < 3:
        raise _V51Stop
    try:
        chat_id = int(parts[2])
    except Exception:
        try: await q.answer("Grupo inválido", show_alert=True)
        except Exception: pass
        raise _V51Stop
    if action in {"open", "home", "reload"}:
        await _v51_render(q, admin_private_main_text(chat_id), admin_private_main_markup(chat_id))
        raise _V51Stop
    if action == "close":
        try: await q.message.delete()
        except Exception: await _v51_render(q, "Panel cerrado.", None)
        raise _V51Stop
    if action == "save":
        save_all_states(); await _v51_render(q, admin_private_main_text(chat_id), admin_private_main_markup(chat_id)); raise _V51Stop
    if action in {"block", "block_reload", "block_save"}:
        block = parts[3] if len(parts) >= 4 else "validation"
        if action == "block_save": save_all_states()
        await _v51_render(q, admin_private_block_text(chat_id, block), admin_private_block_markup(chat_id, block))
        raise _V51Stop

    if action == "svc_toggle":
        cfg_set(chat_id, "service_cleanup_enabled", not bool(cfg_value(chat_id, "service_cleanup_enabled", False)))
        await _v51_render(q, admin_private_block_text(chat_id, "service_cleanup"), admin_private_block_markup(chat_id, "service_cleanup")); raise _V51Stop
    if action == "svc_type" and len(parts) >= 4:
        kind = parts[3]
        try: service_cleanup_set_type(chat_id, kind, not service_cleanup_type_enabled(chat_id, kind))
        except Exception: pass
        await _v51_render(q, admin_private_block_text(chat_id, "service_cleanup"), admin_private_block_markup(chat_id, "service_cleanup")); raise _V51Stop
    if action == "svc_preset":
        mode = parts[3] if len(parts) >= 4 else "off"
        labels = globals().get("SERVICE_CLEANUP_LABELS", {}) or {}
        if mode == "off":
            cfg_set(chat_id, "service_cleanup_enabled", False); cfg_set(chat_id, "service_cleanup_types", {k: False for k in labels})
        else:
            cfg_set(chat_id, "service_cleanup_enabled", True); cfg_set(chat_id, "service_cleanup_types", {k: (k not in ("new_members", "left_member")) for k in labels})
        await _v51_render(q, admin_private_block_text(chat_id, "service_cleanup"), admin_private_block_markup(chat_id, "service_cleanup")); raise _V51Stop

    if action == "cleanup_set" and len(parts) >= 4:
        mode = parts[3]
        if mode == "off": cfg_set(chat_id, "command_cleanup_mode", "off"); cfg_set(chat_id, "command_cleanup_ttl_seconds", 0)
        elif mode == "instant": cfg_set(chat_id, "command_cleanup_mode", "instant"); cfg_set(chat_id, "command_cleanup_ttl_seconds", 0)
        else: cfg_set(chat_id, "command_cleanup_mode", "ttl"); cfg_set(chat_id, "command_cleanup_ttl_seconds", int(mode))
        await _v51_render(q, admin_private_block_text(chat_id, "command_cleanup"), admin_private_block_markup(chat_id, "command_cleanup")); raise _V51Stop

    if action == "impconf":
        sub = parts[3] if len(parts) >= 4 else ""
        if sub == "toggle" and len(parts) >= 6:
            key = parts[4]; default = bool(int(parts[5])) if str(parts[5]).isdigit() else False
            cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, default)))
        elif sub == "ttl" and len(parts) >= 5:
            cfg_set(chat_id, "imp_finish_delete_ttl", int(parts[4]))
        await _v51_render(q, admin_private_block_text(chat_id, "impostor_settings"), admin_private_block_markup(chat_id, "impostor_settings")); raise _V51Stop

    if action == "alert_toggle":
        key = parts[4] if len(parts) >= 5 else "owner_private_alerts_enabled"
        cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, True)))
        await _v51_render(q, admin_private_block_text(chat_id, "owner_alerts"), admin_private_block_markup(chat_id, "owner_alerts")); raise _V51Stop

    if ai_actions:
        try:
            if action == "ai_toggle":
                flag = parts[3] if len(parts) > 3 else "enabled"
                keymap = {"enabled": "ai_enabled", "auto": "ai_auto_enabled", "good": "ai_good_morning_enabled", "image": "ai_good_morning_image"}
                key = keymap.get(flag, "ai_enabled"); cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, key == "ai_enabled")))
            elif action == "ai_freq" and len(parts) > 3: cfg_set(chat_id, "ai_auto_frequency", int(parts[3]))
            elif action == "ai_tone" and len(parts) > 3: cfg_set(chat_id, "ai_tone", parts[3])
            elif action == "ai_plimit" and len(parts) > 3: cfg_set(chat_id, "ai_planecito_daily_limit", int(parts[3]))
            elif action == "ai_alimit" and len(parts) > 3: cfg_set(chat_id, "ai_auto_daily_limit", int(parts[3]))
            elif action == "ai_set_time":
                set_config_pending(q.from_user.id, {"kind": "ai_good_morning_time", "chat_id": chat_id})
                await q.message.reply_html("🕘 Escribe la hora, por ejemplo <code>09:00</code>."); raise _V51Stop
            elif action == "ai_test_good":
                try: await _ai_send_good_morning(context.bot, chat_id, manual=True)
                except Exception: await q.message.reply_text("No pude enviar prueba. Revisa OPENAI_API_KEY.")
            elif action == "ai_cmd_new":
                set_config_pending(q.from_user.id, {"kind": "ai_custom_command", "chat_id": chat_id})
                await q.message.reply_html("➕ Escribe: <code>nombre | instrucciones</code>"); raise _V51Stop
            elif action == "ai_custom_prompt":
                set_config_pending(q.from_user.id, {"kind": "ai_custom_prompt", "chat_id": chat_id})
                await q.message.reply_html("🧠 Escribe el prompt extra. Usa <code>off</code> para borrar."); raise _V51Stop
            elif action == "ai_test_prompt":
                try:
                    ans = await _ai_openai_response(chat_id, "Dame una frase corta para animar el grupo hoy.", max_output_tokens=120)
                    await q.message.reply_text(ans[:1200])
                except Exception: await q.message.reply_text("No pude probar la IA. Revisa OPENAI_API_KEY.")
            elif action == "ai_cmd_list":
                cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else {}
                txt = "<b>📋 Comandos IA</b>\n\n" + ("\n".join(f"• <code>/{h(k)}</code>" for k in sorted(cmds)) if cmds else "No hay comandos personalizados.")
                await q.message.reply_html(txt); raise _V51Stop
        except _V51Stop:
            raise
        except Exception:
            logger.exception("V51 error en IA")
        await _v51_render(q, admin_private_block_text(chat_id, "ai"), admin_private_block_markup(chat_id, "ai")); raise _V51Stop


_base_impostor_router_v51 = impostor_callback_router
async def _v51_impostor_once_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or "").startswith("imp|"):
        return
    await _base_impostor_router_v51(update, context)
    raise _V51Stop


_old_build_application_v51 = build_application
def build_application() -> Application:
    _v51_ensure_blocks()
    app = _old_build_application_v51()

    app.add_handler(CallbackQueryHandler(_v51_cfg_master_router, pattern=r"^(cfg|cfgsafe)\|"), group=-30000)
    app.add_handler(CallbackQueryHandler(_v51_impostor_once_router, pattern=r"^imp\|"), group=-30000)
    return app


_V52_ALERT_SEEN: Dict[str, float] = {}


def _v52_cleanup_seen() -> None:
    try:
        import time as _time
        now = _time.time()
        for k, ts in list(_V52_ALERT_SEEN.items()):
            if now - float(ts) > 180:
                _V52_ALERT_SEEN.pop(k, None)
    except Exception:
        pass


def _v52_alert_once(chat_id: int, kind: str, update_obj: Any, extra: str = "") -> bool:
    """Devuelve True solo la primera vez que se procesa esa alerta."""
    try:
        import time as _time
        _v52_cleanup_seen()
        msg_id = 0
        if getattr(update_obj, "message", None):
            msg_id = int(getattr(update_obj.message, "message_id", 0) or 0)
        elif getattr(update_obj, "chat_member", None):
            cmu = update_obj.chat_member
            user = getattr(getattr(cmu, "new_chat_member", None), "user", None) or getattr(getattr(cmu, "old_chat_member", None), "user", None)
            msg_id = int(getattr(user, "id", 0) or 0)
        key = f"{int(chat_id)}:{kind}:{msg_id}:{extra}"
        if key in _V52_ALERT_SEEN:
            return False
        _V52_ALERT_SEEN[key] = _time.time()
        return True
    except Exception:
        return True


async def _v52_private_alert_typed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, kind: str, text: str, *, url: Optional[str] = None, update_obj: Any = None, extra: str = "") -> None:
    if not bool(cfg_value(chat_id, "owner_private_alerts_enabled", True)):
        return
    if not bool(cfg_value(chat_id, kind, True)):
        return
    if update_obj is not None and not _v52_alert_once(chat_id, kind, update_obj, extra=extra):
        return
    try:
        await _send_owner_private_alert_typed(context, chat_id, kind, text, url=url)
    except Exception:
        logger.exception("V52 no pudo enviar alerta privada")


async def _v52_new_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not getattr(update.message, "new_chat_members", None):
        return
    chat_id = int(update.effective_chat.id)
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    for user in update.message.new_chat_members:
        if getattr(user, "is_bot", False):
            continue
        await _v52_private_alert_typed(
            context,
            chat_id,
            "owner_alert_new_members",
            f"👋 {user.mention_html()} ha entrado en <b>{chat_title}</b>.",
            url=_chat_message_url_from_message(update.message) if '_chat_message_url_from_message' in globals() else None,
            update_obj=update,
            extra=str(user.id),
        )


async def _v52_left_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not getattr(update.message, "left_chat_member", None):
        return
    chat_id = int(update.effective_chat.id)
    user = update.message.left_chat_member
    if getattr(user, "is_bot", False):
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    await _v52_private_alert_typed(
        context,
        chat_id,
        "owner_alert_left_members",
        f"🚪 {user.mention_html()} ha salido/ha sido expulsado de <b>{chat_title}</b>.",
        url=_chat_message_url_from_message(update.message) if '_chat_message_url_from_message' in globals() else None,
        update_obj=update,
        extra=str(user.id),
    )


async def _v52_chat_member_alert(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, "chat_member", None)
    if not cmu or not getattr(cmu, "chat", None):
        return
    chat_id = int(cmu.chat.id)
    chat_title = h(getattr(cmu.chat, "title", "Grupo") or "Grupo")
    old = getattr(cmu, "old_chat_member", None)
    new = getattr(cmu, "new_chat_member", None)
    user = getattr(new, "user", None) or getattr(old, "user", None)
    if not user or getattr(user, "is_bot", False):
        return
    old_status = str(getattr(old, "status", "") or "")
    new_status = str(getattr(new, "status", "") or "")
    actor = getattr(cmu, "from_user", None)
    actor_txt = f" por {actor.mention_html()}" if actor else ""
    if old_status not in ("left", "kicked", "") and new_status == "kicked":
        await _v52_private_alert_typed(context, chat_id, "owner_alert_kicked_members", f"⛔ {user.mention_html()} ha sido expulsado de <b>{chat_title}</b>{actor_txt}.", update_obj=update, extra=f"kick:{user.id}:{new_status}")
    elif old_status not in ("left", "kicked", "") and new_status == "left":
        await _v52_private_alert_typed(context, chat_id, "owner_alert_left_members", f"🚪 {user.mention_html()} ha salido de <b>{chat_title}</b>.", update_obj=update, extra=f"left:{user.id}:{new_status}")
    elif new_status == "restricted" and getattr(new, "can_send_messages", True) is False:
        await _v52_private_alert_typed(context, chat_id, "owner_alert_muted_members", f"🔇 {user.mention_html()} ha sido silenciado en <b>{chat_title}</b>{actor_txt}.", update_obj=update, extra=f"mute:{user.id}:{new_status}")


async def _v52_owner_mention_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    text = update.message.text or update.message.caption or ""
    if not text:
        return
    chat_title = h(getattr(update.effective_chat, "title", "Grupo") or "Grupo")
    sender = update.effective_user.mention_html()
    snippet = h(text[:300])
    upper = text.upper()
    url = _chat_message_url_from_message(update.message) if '_chat_message_url_from_message' in globals() else None
    if ("#PRESENTACIÓN" in upper or "#PRESENTACION" in upper):
        await _v52_private_alert_typed(context, chat_id, "owner_alert_tags", f"🏷 {sender} ha usado <b>#PRESENTACIÓN</b> en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=url, update_obj=update, extra="tag")
        return
    if not bool(cfg_value(chat_id, "owner_alert_mentions", True)):
        return
    mentioned = False
    try:
        targets = _owner_alert_targets() if '_owner_alert_targets' in globals() else set(ADMIN_IDS)
        owner_usernames = set()
        try:
            owner_usernames = await _owner_usernames_for_chat(context, chat_id) if '_owner_usernames_for_chat' in globals() else set()
        except Exception:
            owner_usernames = set()
        entities = list(update.message.entities or []) + list(update.message.caption_entities or [])
        for ent in entities:
            user = getattr(ent, "user", None)
            if user and int(user.id) in targets:
                mentioned = True
                break
            if getattr(ent, "type", "") == "mention":
                raw = text[ent.offset:ent.offset + ent.length].lstrip("@").lower()
                if raw in owner_usernames:
                    mentioned = True
                    break
    except Exception:
        logger.exception("V52 error revisando mención")
    if not mentioned:
        return
    await _v52_private_alert_typed(context, chat_id, "owner_alert_mentions", f"🔔 {sender} te ha mencionado en <b>{chat_title}</b>.\n\n<i>{snippet}</i>", url=url, update_obj=update, extra="mention")


_old_v52_admin_private_main_markup = admin_private_main_markup
def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Menú privado robusto: no pierde Alertas privadas por estar al final de la lista."""
    try:
        _v51_ensure_blocks() if '_v51_ensure_blocks' in globals() else None
        rows: List[List[InlineKeyboardButton]] = []
        normal_blocks = [(k, l) for k, l in ADMIN_PRIVATE_BLOCKS if k != "lists"]
        for i in range(0, len(normal_blocks), 2):
            chunk = normal_blocks[i:i+2]
            rows.append([InlineKeyboardButton(block_label(chat_id, key, label), callback_data=f"cfg|block|{chat_id}|{key}") for key, label in chunk])
        state = get_state(chat_id)
        pending_count = sum(1 for r in state.validation_users.values() if r.get("status") in ("answering", "pending_admin", "timeout"))
        log_count = len([r for r in state.action_log if int(r.get("ts") or 0) >= _now_ts() - 3 * 86400])
        lists_label = f"{admin_block_icon(chat_id, 'lists')} 📊 LISTADOS Y CONTROL · 👥 {pending_count} · 📜 {log_count} · 🚫 {len(state.expelled_users)}"
        rows.append([InlineKeyboardButton(lists_label, callback_data=f"cfg|block|{chat_id}|lists")])
        rows.append([InlineKeyboardButton("🔄 Reload", callback_data=f"cfg|reload|{chat_id}"), InlineKeyboardButton("💾 Guardar", callback_data=f"cfg|save|{chat_id}"), InlineKeyboardButton("❌ Cerrar panel", callback_data=f"cfg|close|{chat_id}")])
        rows.append([InlineKeyboardButton("🔙 Elegir otro grupo", callback_data="cfg|list")])
        return InlineKeyboardMarkup(rows)
    except Exception:
        logger.exception("V52 error creando menú principal privado")
        return _old_v52_admin_private_main_markup(chat_id)


_ALERT_HANDLER_NAMES_V52 = {
    "owner_mention_alert_handler",
    "_v43_new_member_alert", "_v43_left_member_alert", "_v43_chat_member_alert",
    "_v44_new_member_alert", "_v44_left_member_alert", "_v44_chat_member_alert",
    "_v52_owner_mention_alert_handler", "_v52_new_member_alert", "_v52_left_member_alert", "_v52_chat_member_alert",
}


def _v52_strip_duplicate_alert_handlers(app: Application) -> None:
    """Quita handlers antiguos que causaban 3-4 avisos privados por la misma mención."""
    try:
        for group, handlers in list(app.handlers.items()):
            cleaned = []
            for handler in handlers:
                cb = getattr(handler, "callback", None)
                name = getattr(cb, "__name__", "")
                if name in _ALERT_HANDLER_NAMES_V52:
                    continue
                cleaned.append(handler)
            app.handlers[group] = cleaned
    except Exception:
        logger.exception("V52 no pudo limpiar handlers duplicados")


_old_build_application_v52 = build_application
def build_application() -> Application:
    _v51_ensure_blocks() if '_v51_ensure_blocks' in globals() else None
    app = _old_build_application_v52()
    _v52_strip_duplicate_alert_handlers(app)
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, _v52_new_member_alert), group=-40000)
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER, _v52_left_member_alert), group=-40000)
    app.add_handler(ChatMemberHandler(_v52_chat_member_alert, ChatMemberHandler.CHAT_MEMBER), group=-40000)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v52_owner_mention_alert_handler), group=-40000)
    return app

def main() -> None:
    _v51_ensure_blocks()
    app = build_application()
    app.run_polling(drop_pending_updates=False)


def _v53_group_ids_for_alerts() -> List[int]:
    """Grupos configurables para alertas: grupos existentes en state.json."""
    ids: List[int] = []
    try:
        for cid in sorted(STATE_CACHE.keys(), key=lambda x: str(x)):
            try:
                icid = int(cid)
            except Exception:
                continue

            if icid < 0:
                ids.append(icid)
    except Exception:
        logger.exception("V53 no pudo listar grupos para alertas")
    return ids


def _v53_group_title(chat_id: int) -> str:
    try:
        if '_v51_title' in globals():
            return str(_v51_title(chat_id))
    except Exception:
        pass
    try:
        state = get_state(chat_id)
        cfg = getattr(state, 'admin_config', {}) or {}
        for key in ('title', 'chat_title', 'group_title', 'name'):
            if cfg.get(key):
                return str(cfg.get(key))
    except Exception:
        pass
    return str(chat_id)


def _v53_alert_prefs() -> List[Tuple[str, str, bool]]:
    return [
        ("owner_private_alerts_enabled", "🔔 Alertas generales", True),
        ("owner_alert_new_members", "👋 Entradas", True),
        ("owner_alert_left_members", "🚪 Salidas voluntarias", True),
        ("owner_alert_kicked_members", "⛔ Expulsiones", True),
        ("owner_alert_muted_members", "🔇 Silenciados", True),
        ("owner_alert_mentions", "@ Menciones directas", True),
        ("owner_alert_tags", "🏷 #PRESENTACIÓN", True),
    ]


def _v53_alerts_text(chat_id: int) -> str:
    lines = [
        "<b>🔔 Alertas privadas</b>",
        f"Grupo: <b>{h(_v53_group_title(chat_id))}</b>",
        "",
        "Elige qué avisos quieres recibir en este chat privado.",
        "Los avisos incluirán el grupo y, si Telegram lo permite, botón para ir al mensaje.",
        "",
    ]
    for key, label, default in _v53_alert_prefs():
        try:
            active = bool(cfg_value(chat_id, key, default))
        except Exception:
            active = default
        lines.append(f"{label}: <b>{'ON' if active else 'OFF'}</b>")
    lines.extend([
        "",
        "Nota: Telegram solo permite enviarte privados si antes has abierto chat con el bot.",
    ])
    return "\n".join(lines)


def _v53_alerts_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    prefs = _v53_alert_prefs()
    for i in range(0, len(prefs), 2):
        row: List[InlineKeyboardButton] = []
        for key, label, default in prefs[i:i+2]:
            try:
                active = bool(cfg_value(chat_id, key, default))
            except Exception:
                active = default
            short = label.replace("Alertas generales", "General").replace(" directas", "")
            row.append(InlineKeyboardButton(f"{'✅' if active else '❌'} {short}", callback_data=f"alertstart|toggle|{chat_id}|{key}"))
        rows.append(row)
    rows.append([
        InlineKeyboardButton("✅ Activar recomendadas", callback_data=f"alertstart|preset|{chat_id}|recommended"),
        InlineKeyboardButton("❌ Todo OFF", callback_data=f"alertstart|preset|{chat_id}|off"),
    ])
    rows.append([
        InlineKeyboardButton("🔄 Actualizar", callback_data=f"alertstart|open|{chat_id}"),
        InlineKeyboardButton("💾 Guardar y cerrar", callback_data="alertstart|close"),
    ])
    rows.append([InlineKeyboardButton("🌐 Elegir otro grupo", callback_data="alertstart|list")])
    return InlineKeyboardMarkup(rows)


def _v53_group_selector_text() -> str:
    ids = _v53_group_ids_for_alerts()
    if not ids:
        return (
            "<b>🔔 Alertas privadas</b>\n\n"
            "No encuentro grupos en la configuración guardada.\n\n"
            "Entra en el grupo y ejecuta primero <code>/plan</code> o usa el bot en ese grupo para que quede registrado."
        )
    return "<b>🔔 Alertas privadas</b>\n\nElige el grupo del que quieres configurar avisos privados:"


def _v53_group_selector_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for chat_id in _v53_group_ids_for_alerts():
        title = _v53_group_title(chat_id)
        rows.append([InlineKeyboardButton(f"🔔 {title}", callback_data=f"alertstart|open|{chat_id}")])
    rows.append([InlineKeyboardButton("❌ Cerrar", callback_data="alertstart|close")])
    return InlineKeyboardMarkup(rows)


async def _v53_show_alert_group_selector(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if update.message:
        await update.message.reply_text(
            _v53_group_selector_text(),
            reply_markup=_v53_group_selector_markup(),
            parse_mode=ParseMode.HTML,
        )


async def _v53_render_alerts_panel(query, chat_id: int) -> None:
    text = _v53_alerts_text(chat_id)
    markup = _v53_alerts_markup(chat_id)
    try:
        await query.edit_message_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query.message.reply_text(text, reply_markup=markup, parse_mode=ParseMode.HTML)
        except Exception:
            logger.exception("V53 no pudo mostrar panel de alertas")


async def _v53_alertstart_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    try:
        await q.answer()
    except Exception:
        pass
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else "list"
    if action == "close":
        try:
            await q.message.delete()
        except Exception:
            try:
                await q.edit_message_text("✅ Configuración guardada.")
            except Exception:
                pass
        return
    if action == "list":
        try:
            await q.edit_message_text(_v53_group_selector_text(), reply_markup=_v53_group_selector_markup(), parse_mode=ParseMode.HTML)
        except Exception:
            await q.message.reply_text(_v53_group_selector_text(), reply_markup=_v53_group_selector_markup(), parse_mode=ParseMode.HTML)
        return
    try:
        chat_id = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        await q.message.reply_text("⚠️ Grupo no válido.")
        return
    if action == "open":
        await _v53_render_alerts_panel(q, chat_id)
        return
    if action == "toggle" and len(parts) >= 4:
        key = parts[3]
        default = True
        for k, _, d in _v53_alert_prefs():
            if k == key:
                default = d
                break
        try:
            cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, default)))
        except Exception:
            logger.exception("V53 no pudo alternar alerta %s", key)
        await _v53_render_alerts_panel(q, chat_id)
        return
    if action == "preset" and len(parts) >= 4:
        preset = parts[3]
        if preset == "off":
            for key, _, _ in _v53_alert_prefs():
                cfg_set(chat_id, key, False)
        else:

            for key, _, default in _v53_alert_prefs():
                cfg_set(chat_id, key, default)
        await _v53_render_alerts_panel(q, chat_id)
        return


_old_start_command_v53 = start_command
async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if update.effective_chat and update.effective_chat.type == "private":
        await _v53_show_alert_group_selector(update, context)
        return
    await _old_start_command_v53(update, context)


_old_build_application_v53 = build_application
def build_application() -> Application:
    app = _old_build_application_v53()

    app.add_handler(CallbackQueryHandler(_v53_alertstart_callback, pattern=r"^alertstart\|"), group=-50000)
    return app


def main() -> None:
    try:
        _v51_ensure_blocks() if '_v51_ensure_blocks' in globals() else None
    except Exception:
        pass
    app = build_application()
    app.run_polling(drop_pending_updates=False)


