def _v54_remove_alerts_from_ajustes() -> None:
    """Elimina Alertas privadas del menú /ajustes, aunque parches anteriores lo reinserten."""
    global ADMIN_PRIVATE_BLOCKS, ADMIN_PRIVATE_BLOCK_IDS
    try:
        ADMIN_PRIVATE_BLOCKS = [(k, v) for (k, v) in list(ADMIN_PRIVATE_BLOCKS) if k != "owner_alerts"]
    except Exception:
        pass
    try:
        ADMIN_PRIVATE_BLOCK_IDS = {k for k, _ in ADMIN_PRIVATE_BLOCKS}
    except Exception:
        try:
            ADMIN_PRIVATE_BLOCK_IDS.discard("owner_alerts")
        except Exception:
            pass


