def _v54_alert_cfg_set(key: str, value: bool) -> None:
    try:
        cfg_set(GLOBAL_ALERTS_CHAT_ID, key, bool(value))
    except Exception:
        try:
            state = get_state(GLOBAL_ALERTS_CHAT_ID)
            state.admin_config[key] = bool(value)
            save_all_states()
        except Exception:
            logger.exception("V54 no pudo guardar configuración global de alertas %s", key)


