try:
    from telegram.ext import ApplicationHandlerStop
except Exception:
    class ApplicationHandlerStop(Exception):
        pass

_ALERT_WATCH_PENDING_V55: Dict[int, bool] = {}
_ALERT_WATCH_DEDUP_V55: Dict[str, int] = {}


def _v55_watch_list() -> List[str]:
    try:
        raw = cfg_value(GLOBAL_ALERTS_CHAT_ID, "owner_alert_watch_users_list", [])
    except Exception:
        raw = []
    if not isinstance(raw, list):
        raw = []
    result: List[str] = []
    for item in raw:
        s = str(item or "").strip()
        if not s:
            continue
        if s not in result:
            result.append(s)
    return result


def _v55_save_watch_list(items: List[str]) -> None:
    clean: List[str] = []
    for item in items:
        s = str(item or "").strip()
        if not s:
            continue
        if s.startswith("@@"):
            s = s[1:]
        if s not in clean:
            clean.append(s)
    _v54_alert_cfg_set("owner_alert_watch_users_enabled", bool(_v54_alert_cfg_value("owner_alert_watch_users_enabled", True)))
    try:
        state = get_state(GLOBAL_ALERTS_CHAT_ID)
        state.admin_config["owner_alert_watch_users_list"] = clean
        save_all_states()
    except Exception:
        logger.exception("V55 no pudo guardar usuarios vigilados")


def _v55_alert_prefs() -> List[Tuple[str, str, bool]]:
    return [
        ("owner_private_alerts_enabled", "🔔 Alertas generales", True),
        ("owner_alert_new_members", "👋 Entradas", True),
        ("owner_alert_left_members", "🚪 Salidas voluntarias", True),
        ("owner_alert_kicked_members", "⛔ Expulsiones", True),
        ("owner_alert_muted_members", "🔇 Silenciados", True),
        ("owner_alert_mentions", "@ Menciones directas", True),
        ("owner_alert_tags", "🏷 #PRESENTACIÓN", True),
        ("owner_alert_watch_users_enabled", "👤 Usuarios vigilados", True),
    ]


def _v54_alert_prefs() -> List[Tuple[str, str, bool]]:
    return _v55_alert_prefs()


def _v54_global_alerts_text() -> str:
    watches = _v55_watch_list()
    lines = [
        "<b>🔔 Alertas privadas</b>",
        "<i>Configuración global para todos los grupos.</i>",
        "",
        "Elige qué avisos quieres recibir en este chat privado.",
        "Cada aviso indicará de qué grupo viene y, si Telegram lo permite, llevará botón para ir al mensaje.",
        "",
    ]
    for key, label, default in _v55_alert_prefs():
        lines.append(f"{label}: <b>{'ON' if _v54_alert_cfg_value(key, default) else 'OFF'}</b>")
    lines.append("")
    if watches:
        lines.append("<b>Usuarios vigilados:</b>")
        for item in watches[:20]:
            lines.append(f"• <code>{h(item)}</code>")
        if len(watches) > 20:
            lines.append(f"… y {len(watches) - 20} más")
    else:
        lines.append("<b>Usuarios vigilados:</b> ninguno")
    lines.extend([
        "",
        "Puedes añadir <code>@usuario</code> o un ID numérico. Cuando ese usuario hable en cualquier grupo, te llegará aviso privado.",
        "",
        "Nota: para recibir avisos, debes haber abierto este chat privado con el bot.",
    ])
    return "\n".join(lines)


def _v54_global_alerts_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    prefs = _v55_alert_prefs()
    for i in range(0, len(prefs), 2):
        row: List[InlineKeyboardButton] = []
        for key, label, default in prefs[i:i+2]:
            active = _v54_alert_cfg_value(key, default)
            short = (label.replace("Alertas generales", "General")
                          .replace(" directas", "")
                          .replace("Usuarios vigilados", "Vigilados"))
            row.append(InlineKeyboardButton(f"{'✅' if active else '❌'} {short}", callback_data=f"alertglobal|toggle|{key}"))
        rows.append(row)
    rows.append([
        InlineKeyboardButton("👤 Ver vigilados", callback_data="alertglobal|watchmenu"),
        InlineKeyboardButton("➕ Añadir usuario", callback_data="alertglobal|watchadd"),
    ])
    rows.append([
        InlineKeyboardButton("🧹 Vaciar vigilados", callback_data="alertglobal|watchclear"),
    ])
    rows.append([
        InlineKeyboardButton("✅ Activar recomendadas", callback_data="alertglobal|preset|recommended"),
        InlineKeyboardButton("❌ Todo OFF", callback_data="alertglobal|preset|off"),
    ])
    rows.append([
        InlineKeyboardButton("🔄 Actualizar", callback_data="alertglobal|open"),
        InlineKeyboardButton("💾 Guardar y cerrar", callback_data="alertglobal|close"),
    ])
    return InlineKeyboardMarkup(rows)


async def _v55_show_watch_menu(q) -> None:
    watches = _v55_watch_list()
    text = ["<b>👤 Usuarios vigilados</b>", ""]
    if watches:
        text.append("Te avisaré cuando cualquiera de estos usuarios escriba en cualquier grupo:")
        text.append("")
        for idx, item in enumerate(watches, 1):
            text.append(f"{idx}. <code>{h(item)}</code>")
    else:
        text.append("No hay usuarios vigilados todavía.")
    rows: List[List[InlineKeyboardButton]] = []
    for idx, item in enumerate(watches[:20]):
        rows.append([InlineKeyboardButton(f"🗑 {item[:32]}", callback_data=f"alertglobal|watchremove|{idx}")])
    rows.append([InlineKeyboardButton("➕ Añadir usuario", callback_data="alertglobal|watchadd")])
    rows.append([InlineKeyboardButton("🔙 Volver", callback_data="alertglobal|open")])
    try:
        await q.edit_message_text("\n".join(text), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows), disable_web_page_preview=True)
    except Exception:
        await q.message.reply_text("\n".join(text), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows), disable_web_page_preview=True)


async def _v55_alertglobal_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else "open"
    try:
        await q.answer()
    except Exception:
        pass
    if action == "watchmenu":
        await _v55_show_watch_menu(q)
        raise ApplicationHandlerStop
    if action == "watchadd":
        if update.effective_user:
            _ALERT_WATCH_PENDING_V55[int(update.effective_user.id)] = True
        try:
            await q.edit_message_text(
                "<b>➕ Añadir usuario vigilado</b>\n\nEnvíame ahora el <code>@username</code> o el ID numérico del usuario.\n\nEjemplo: <code>@javier</code>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("❌ Cancelar", callback_data="alertglobal|open")]]),
                disable_web_page_preview=True,
            )
        except Exception:
            await q.message.reply_text("Envíame el @username o ID del usuario a vigilar.")
        raise ApplicationHandlerStop
    if action == "watchclear":
        _v55_save_watch_list([])
        await _v54_render_global_alerts(q)
        raise ApplicationHandlerStop
    if action == "watchremove" and len(parts) >= 3:
        try:
            idx = int(parts[2])
            watches = _v55_watch_list()
            if 0 <= idx < len(watches):
                watches.pop(idx)
                _v55_save_watch_list(watches)
        except Exception:
            pass
        await _v55_show_watch_menu(q)
        raise ApplicationHandlerStop

    await _v54_alertglobal_callback(update, context)
    raise ApplicationHandlerStop


async def _v55_alert_watch_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message or update.effective_chat.type != "private":
        return
    uid = int(update.effective_user.id)
    if not _ALERT_WATCH_PENDING_V55.pop(uid, False):
        return
    value = (update.message.text or "").strip()
    if not value:
        await update.message.reply_text("No he recibido ningún usuario.")
        return

    if value.startswith("@"):
        value = "@" + value[1:].strip().lower()
    elif value.lstrip("-").isdigit():
        value = str(int(value))
    else:

        value = "@" + value.strip().lower()
    watches = _v55_watch_list()
    if value not in watches:
        watches.append(value)
        _v55_save_watch_list(watches)
    await update.message.reply_text(
        f"✅ Añadido a usuarios vigilados: {value}",
        reply_markup=_v54_global_alerts_markup(),
        parse_mode=ParseMode.HTML,
    )


def _v55_user_is_watched(user) -> bool:
    watches = _v55_watch_list()
    if not watches or not _v54_alert_cfg_value("owner_alert_watch_users_enabled", True):
        return False
    uid = str(getattr(user, "id", "") or "")
    username = (getattr(user, "username", "") or "").lower().strip()
    username_at = f"@{username}" if username else ""
    for item in watches:
        token = str(item or "").strip().lower()
        if not token:
            continue
        if token.lstrip("-").isdigit() and token == uid:
            return True
        if token.startswith("@") and username_at and token == username_at:
            return True
        if username and token == username:
            return True
    return False


async def _v55_watched_user_alert_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_chat or update.effective_chat.type == "private":
        return
    user = update.effective_user
    if not user or not _v55_user_is_watched(user):
        return
    chat_id = int(update.effective_chat.id)
    key = f"watch:{chat_id}:{update.message.message_id}:{getattr(user, 'id', 0)}"
    if key in _ALERT_WATCH_DEDUP_V55:
        return
    _ALERT_WATCH_DEDUP_V55[key] = int(__import__('time').time())

    if len(_ALERT_WATCH_DEDUP_V55) > 500:
        now = int(__import__('time').time())
        for k, ts in list(_ALERT_WATCH_DEDUP_V55.items()):
            if now - int(ts) > 3600:
                _ALERT_WATCH_DEDUP_V55.pop(k, None)
    try:
        chat_title = h(getattr(update.effective_chat, "title", "") or str(chat_id))
        sender = user.mention_html()
        text = (update.message.text or update.message.caption or "").strip()
        snippet = h(text[:300])
        url = _chat_message_url_from_message(update.message) if '_chat_message_url_from_message' in globals() else None
        body = f"👤 {sender} ha escrito en <b>{chat_title}</b>."
        if snippet:
            body += f"\n\n<i>{snippet}</i>"
        await _send_owner_private_alert_typed(context, chat_id, "owner_alert_watch_users_enabled", body, url=url)
    except Exception:
        logger.exception("V55 no pudo enviar alerta de usuario vigilado")


