async def _v57_cerebrito_answer(chat_id: int, prompt: str, *, max_output_tokens: int = 650) -> str:
    """Usa la función IA existente del bot, pero con control de errores claro."""
    try:
        if not os.getenv("OPENAI_API_KEY", "").strip():
            return "❌ Falta OPENAI_API_KEY en Railway. Añádela en Variables y redeploya."
        if "_ai_openai_response" not in globals():
            return "❌ No encuentro la función interna de IA (_ai_openai_response)."
        return await asyncio.wait_for(_ai_openai_response(chat_id, prompt, max_output_tokens=max_output_tokens), timeout=45)
    except asyncio.TimeoutError:
        return "⚠️ OpenAI tardó demasiado en responder. Prueba otra vez en unos segundos."
    except Exception as e:
        logger.exception("V57 Cerebrito error")
        return f"⚠️ Error en Cerebrito ({type(e).__name__}): {h(str(e)[:500])}"


async def cerebrito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    prompt = " ".join(context.args or []).strip()
    if not prompt:
        await update.message.reply_html("Usa: <code>/cerebrito tu pregunta</code>")
        return
    if not bool(cfg_value(chat_id, "ai_enabled", True)):
        await update.message.reply_text("🧠 Cerebrito está desactivado en este grupo.")
        return
    if _ai_limit_reached(chat_id, int(update.effective_user.id), "planecito", "ai_planecito_daily_limit"):
        await update.message.reply_text("⏳ Has llegado al límite diario de consultas a Cerebrito.")
        return

    waiting = await update.message.reply_text("🧠 Cerebrito está pensando…")
    answer = await _v57_cerebrito_answer(chat_id, prompt, max_output_tokens=700)
    try:

        if not answer.startswith(("❌", "⚠️")):
            _ai_usage_inc(chat_id, int(update.effective_user.id), "planecito")
    except Exception:
        pass
    try:
        await waiting.edit_text(answer[:3900], parse_mode=ParseMode.HTML if "<" in answer and ">" in answer else None)
    except Exception:
        try:
            await waiting.edit_text(answer[:3900])
        except Exception:
            await update.message.reply_text(answer[:3900])


async def planecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    return await cerebrito_command(update, context)


async def iatest_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    model = str(cfg_value(chat_id, "ai_model", os.getenv("OPENAI_MODEL", "gpt-4.1-mini")) or os.getenv("OPENAI_MODEL", "gpt-4.1-mini"))
    key_ok = bool(os.getenv("OPENAI_API_KEY", "").strip())
    waiting = await update.message.reply_text(
        f"🧪 Test Cerebrito\nOPENAI_API_KEY: {'✅' if key_ok else '❌'}\nModelo: {model}\nProbando conexión…"
    )
    if not key_ok:
        await waiting.edit_text("❌ Falta OPENAI_API_KEY en Railway.")
        return
    answer = await _v57_cerebrito_answer(chat_id, "Responde exactamente: OK Cerebrito funcionando", max_output_tokens=80)
    try:
        await waiting.edit_text(("🧪 Resultado Cerebrito:\n\n" + answer)[:3900])
    except Exception:
        await update.message.reply_text(("🧪 Resultado Cerebrito:\n\n" + answer)[:3900])


_old_build_application_v57 = build_application

def build_application() -> Application:
    app = _old_build_application_v57()

    app.add_handler(command_handler("cerebrito", cerebrito_command), group=-99999)
    app.add_handler(command_handler("planecito", planecito_command), group=-99999)
    app.add_handler(command_handler("iatest", iatest_command), group=-99999)
    logger.info("V57 Cerebrito mínimo seguro cargado")
    return app


from telegram.ext import ApplicationHandlerStop


def _v58_imp_players_lines(game: Dict[str, Any]) -> str:
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    eliminated = {int(x) for x in (game.get("eliminated", []) if isinstance(game.get("eliminated", []), list) else [])}
    lines: List[str] = []
    for i, p in enumerate(players, 1):
        try:
            uid = int(p.get("id", 0) or 0)
            suffix = " ❌" if uid in eliminated else ""
            lines.append(f"{i}. {_imp_mention(p)}{suffix}")
        except Exception:
            pass
    return "\n".join(lines) if lines else "Sin jugadores."


def _v58_imp_card_text(game: Dict[str, Any]) -> str:
    status = str(game.get("status") or "lobby")
    players = _imp_active_players(game) if status in ("active", "voting") else (game.get("players", []) if isinstance(game.get("players"), list) else [])
    ronda = int(game.get("round", 1) or 1)
    current = _imp_current_player(game) if status == "active" else None
    clues = game.get("clues") if isinstance(game.get("clues"), list) else []

    if status == "lobby":
        return (
            "🎭 <b>Juego del Impostor</b>\n\n"
            "Todos tienen una palabra secreta menos una persona: <b>el impostor</b>.\n"
            "El impostor debe disimular y seguir el hilo 😏\n\n"
            f"👥 Jugadores: <b>{len(players)}</b>\n"
            f"{_v58_imp_players_lines(game)}\n\n"
            "Mínimo 3 jugadores."
        )

    if status == "voting":
        extra = _imp_last_clues_text(game, limit=8) if "_imp_last_clues_text" in globals() else ""
        return (
            "🗳 <b>Impostor · Votación final</b>\n\n"
            "Ya se acabaron las rondas. Ahora toca señalar al sospechoso.\n"
            "Pulsa votar y elige quién crees que es el impostor."
            f"{extra}"
        )

    extra = _imp_last_clues_text(game, limit=8) if "_imp_last_clues_text" in globals() else ""
    return (
        "🎭 <b>Impostor</b>\n"
        f"Ronda <b>{ronda}/3</b> · Jugadores activos: <b>{len(players)}</b>\n\n"
        f"Turno actual: {_imp_mention(current) if current else '<i>sin turno</i>'}\n\n"
        "Cada jugador debe dar una pista corta, sin decir la palabra secreta.\n"
        "Si sospechas, puedes acusar. Si fallas, quedas eliminado."
        f"{extra}"
    )


def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    status = str(game.get("status") or "lobby")
    if status == "lobby":
        return _imp_lobby_markup(chat_id, game)
    if status == "voting":
        return InlineKeyboardMarkup([
            [InlineKeyboardButton("🗳 Votar impostor", callback_data=f"imp|vote_menu|{chat_id}|{gid}")],
            [InlineKeyboardButton("🔐 Ver mi palabra", callback_data=f"imp|mysecret|{chat_id}|{gid}"), InlineKeyboardButton("🏆 Ranking", callback_data=f"imp|ranking|{chat_id}|{gid}")],
        ])
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔐 Ver mi palabra", callback_data=f"imp|mysecret|{chat_id}|{gid}"), InlineKeyboardButton("🚨 El impostor es...", callback_data=f"imp|accuse_menu|{chat_id}|{gid}")],
        [InlineKeyboardButton("🗳 Votación final", callback_data=f"imp|vote_menu|{chat_id}|{gid}"), InlineKeyboardButton("🏆 Ranking", callback_data=f"imp|ranking|{chat_id}|{gid}")],
    ])


def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    current = _imp_current_player(game)
    ronda = int(game.get("round", 1) or 1)
    if not current:
        return "🎭 No hay jugador de turno."
    ayudas = {
        1: "Da una pista suave, una palabra o frase corta.",
        2: "Da una pista un poco más clara, pero sin regalar la palabra.",
        3: "Última pista. Puedes arriesgar un poco más, pero no digas la palabra exacta.",
    }
    return (
        f"✍️ {_imp_mention(current)}, <b>te toca.</b>\n\n"
        f"{ayudas.get(ronda, ayudas[3])}\n"
        "Pulsa <b>Responder pista</b> y escribe tu pista en el grupo."
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✍️ Responder pista", callback_data=f"imp|respond|{chat_id}|{gid}")],
        [InlineKeyboardButton("🚨 El impostor es...", callback_data=f"imp|accuse_menu|{chat_id}|{gid}")],
    ])


async def _v58_delete_if_exists(bot, chat_id: int, key_mid: Any) -> None:
    try:
        mid = int(key_mid or 0)
    except Exception:
        mid = 0
    if mid:
        try:
            await safe_delete(bot, chat_id, mid)
        except Exception:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=mid)
            except Exception:
                pass


async def _v58_imp_render_down(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, delete_previous: bool = True) -> None:
    """Muestra el estado del juego abajo. Borra la tarjeta y prompt anteriores para que no se acumulen."""
    bot = context.bot
    if delete_previous:
        await _v58_delete_if_exists(bot, chat_id, game.get("v58_card_message_id") or game.get("turn_message_id"))
        await _v58_delete_if_exists(bot, chat_id, game.get("v58_prompt_message_id"))
        game["v58_card_message_id"] = 0
        game["v58_prompt_message_id"] = 0

    status = str(game.get("status") or "lobby")
    card = await bot.send_message(chat_id, _v58_imp_card_text(game), parse_mode=ParseMode.HTML, reply_markup=_v58_imp_card_markup(chat_id, game))
    game["v58_card_message_id"] = card.message_id
    game["turn_message_id"] = card.message_id

    if status == "active":
        prompt = await bot.send_message(chat_id, _v58_imp_prompt_text(game), parse_mode=ParseMode.HTML, reply_markup=_v58_imp_prompt_markup(chat_id, game))
        game["v58_prompt_message_id"] = prompt.message_id

    save_all_states()


async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:
    q = update.callback_query
    uid = int(q.from_user.id) if q else 0
    allowed = uid == int(game.get("creator_id", 0) or 0) or await is_admin(context, chat_id, uid)
    if not allowed:
        if q: await q.answer("Solo creador/admin puede empezar", show_alert=True)
        raise ApplicationHandlerStop
    players = game.get("players", []) if isinstance(game.get("players"), list) else []
    if len(players) < 3:
        if q: await q.answer("Mínimo 3 jugadores", show_alert=True)
        raise ApplicationHandlerStop
    game["status"] = "active"
    game["round"] = 1
    game["turn_idx"] = 0
    game["votes"] = {}
    game["eliminated"] = []
    game["accusations"] = []
    game["clues"] = []
    game["impostor_id"] = int(secrets.choice(players).get("id"))
    save_all_states()


    try:
        if q and q.message:
            await safe_delete(context.bot, chat_id, q.message.message_id)
    except Exception:
        pass

    if q:
        await q.answer("Partida iniciada 🎭")
    await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    raise ApplicationHandlerStop


_old_impostor_callback_router_v58 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    if not data.startswith("imp|"):
        return await _old_impostor_callback_router_v58(update, context)
    parts = data.split("|")
    if len(parts) < 4:
        await q.answer(); raise ApplicationHandlerStop
    action = parts[1]
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer("Partida inválida", show_alert=True); raise ApplicationHandlerStop
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer("No encuentro la partida", show_alert=True); raise ApplicationHandlerStop

    if action == "start":
        await _v58_imp_start_game(update, context, chat_id, gid, game)

    if action == "respond":
        if str(game.get("status")) != "active":
            await q.answer("La partida no está activa", show_alert=True); raise ApplicationHandlerStop
        current = _imp_current_player(game)
        if not current or int(current.get("id", 0) or 0) != int(q.from_user.id):
            await q.answer("Ahora no te toca responder.", show_alert=True); raise ApplicationHandlerStop
        PENDING_ACTIONS[_imp_pending_key(chat_id, q.from_user.id)] = {"chat_id": chat_id, "gid": gid, "ts": int(time.time())}
        save_all_states()
        await q.answer("Escribe ahora tu pista en el grupo. Al enviarla paso turno automáticamente.", show_alert=True)
        raise ApplicationHandlerStop

    if action in ("show_turn", "next"):
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
        await q.answer()
        raise ApplicationHandlerStop


    await _old_impostor_callback_router_v58(update, context)
    raise ApplicationHandlerStop


async def impostor_clue_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == "private":
        return
    text = (update.message.text or update.message.caption or "").strip()
    if not text or text.startswith("/"):
        return
    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    key = _imp_pending_key(chat_id, uid)
    pending = PENDING_ACTIONS.get(key)
    if not pending:
        return
    if int(time.time()) - int(pending.get("ts", 0) or 0) > 300:
        PENDING_ACTIONS.pop(key, None)
        return
    game = _imp_find(chat_id, int(pending.get("gid", 0) or 0))
    if not game or str(game.get("status")) != "active":
        PENDING_ACTIONS.pop(key, None)
        return
    current = _imp_current_player(game)
    if not current or int(current.get("id", 0) or 0) != uid:
        PENDING_ACTIONS.pop(key, None)
        return

    clue = text[:140]
    game.setdefault("clues", []).append({"uid": uid, "name": display_name(update.effective_user), "text": clue, "round": int(game.get("round", 1) or 1), "ts": int(time.time())})
    PENDING_ACTIONS.pop(key, None)
    _imp_advance_turn_after_clue(game)
    save_all_states()


    if bool(cfg_value(chat_id, "imp_delete_player_clues", False)):
        try:
            await safe_delete(context.bot, chat_id, update.message.message_id)
        except Exception:
            pass

    await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    raise ApplicationHandlerStop


_old_build_application_v58 = build_application

def build_application() -> Application:
    app = _old_build_application_v58()

    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r"^imp\|"), group=-100000)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, impostor_clue_text_handler), group=-99990)
    logger.info("V58 Impostor turnos abajo cargado")
    return app


IMPOSTOR_SKIP_SECONDS = 60
IMPOSTOR_SKIP_TASKS: Dict[str, asyncio.Task] = {}


def _imp_game_key(chat_id: int, gid: int) -> str:
    return f"imp_skip:{int(chat_id)}:{int(gid)}"


def _imp_player_by_id(game: Dict[str, Any], user_id: int) -> Optional[Dict[str, Any]]:
    for p in game.get("players", []) if isinstance(game.get("players"), list) else []:
        try:
            if int(p.get("id", 0) or 0) == int(user_id):
                return p
        except Exception:
            pass
    return None


def _imp_creator_or_admin_id(game: Dict[str, Any], user_id: int) -> bool:
    try:
        return int(game.get("creator_id", 0) or 0) == int(user_id)
    except Exception:
        return False


async def _imp_can_manage(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], user_id: int) -> bool:
    if _imp_creator_or_admin_id(game, user_id):
        return True
    try:
        return await is_admin(context, chat_id, user_id)
    except Exception:
        return False


def _imp_cancel_skip_task(chat_id: int, gid: int) -> None:
    key = _imp_game_key(chat_id, gid)
    task = IMPOSTOR_SKIP_TASKS.pop(key, None)
    if task and not task.done():
        task.cancel()


def _imp_clear_pending_for_chat_game(chat_id: int, gid: int, user_id: Optional[int] = None) -> None:
    prefix = f"imp_clue:{int(chat_id)}:"
    for key, data in list(PENDING_ACTIONS.items()):
        if not str(key).startswith(prefix):
            continue
        try:
            if int(data.get("gid", 0) or 0) != int(gid):
                continue
            if user_id is not None and int(key.rsplit(":", 1)[1]) != int(user_id):
                continue
        except Exception:
            continue
        PENDING_ACTIONS.pop(key, None)


def _imp_advance_turn_skip(game: Dict[str, Any]) -> None:
    """Avanza turno sin guardar pista. Mantiene la misma lógica de rondas."""
    active = _imp_active_players(game)
    if not active:
        return
    game["turn_idx"] = int(game.get("turn_idx", 0) or 0) + 1
    if int(game["turn_idx"]) >= len(active):
        game["turn_idx"] = 0
        game["round"] = int(game.get("round", 1) or 1) + 1
    if int(game.get("round", 1) or 1) > 3:
        game["status"] = "voting"


async def _imp_auto_skip_later(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, user_id: int, round_no: int, turn_idx: int) -> None:
    try:
        await asyncio.sleep(IMPOSTOR_SKIP_SECONDS)
        game = _imp_find(chat_id, gid)
        if not game or str(game.get("status")) != "active":
            return
        current = _imp_current_player(game)
        if not current or int(current.get("id", 0) or 0) != int(user_id):
            return
        if int(game.get("round", 1) or 1) != int(round_no):
            return
        if int(game.get("turn_idx", 0) or 0) != int(turn_idx):
            return

        name = current.get("name") or current.get("first_name") or "Jugador"
        game.setdefault("clues", []).append({
            "uid": int(user_id),
            "name": str(name),
            "text": "⏭ turno saltado por inactividad",
            "round": int(game.get("round", 1) or 1),
            "ts": int(time.time()),
            "system": True,
        })
        _imp_clear_pending_for_chat_game(chat_id, gid, user_id)
        _imp_advance_turn_skip(game)
        save_all_states()
        try:
            await context.bot.send_message(chat_id, f"⏭ {_imp_mention(current)} no respondió en 1 minuto. Paso al siguiente turno.", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception("Error autosaltando turno Impostor")
    finally:
        IMPOSTOR_SKIP_TASKS.pop(_imp_game_key(chat_id, gid), None)


def _imp_schedule_auto_skip(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    try:
        if str(game.get("status")) != "active":
            return
        gid = int(game.get("id", 0) or 0)
        current = _imp_current_player(game)
        if not current:
            return
        _imp_cancel_skip_task(chat_id, gid)
        user_id = int(current.get("id", 0) or 0)
        round_no = int(game.get("round", 1) or 1)
        turn_idx = int(game.get("turn_idx", 0) or 0)
        IMPOSTOR_SKIP_TASKS[_imp_game_key(chat_id, gid)] = asyncio.create_task(_imp_auto_skip_later(context, chat_id, gid, user_id, round_no, turn_idx))
    except Exception:
        logger.exception("No se pudo programar autosalto Impostor")


_old_v58_imp_prompt_text_v59 = _v58_imp_prompt_text
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    base = _old_v58_imp_prompt_text_v59(game)
    return base + "\n\n⏱ Si no responde en <b>1 minuto</b>, salto el turno automáticamente."


_old_v58_imp_prompt_markup_v59 = _v58_imp_prompt_markup
def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✍️ Responder pista", callback_data=f"imp|respond|{chat_id}|{gid}")],
        [InlineKeyboardButton("⏭ Saltar turno", callback_data=f"imp|skip|{chat_id}|{gid}"), InlineKeyboardButton("🚫 Expulsar jugador", callback_data=f"imp|kick_menu|{chat_id}|{gid}")],
        [InlineKeyboardButton("🚨 El impostor es...", callback_data=f"imp|accuse_menu|{chat_id}|{gid}")],
    ])


_old_v58_imp_render_down_v59 = _v58_imp_render_down
async def _v58_imp_render_down(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, delete_previous: bool = True) -> None:
    await _old_v58_imp_render_down_v59(context, chat_id, game, delete_previous=delete_previous)
    try:
        gid = int(game.get("id", 0) or 0)
        if str(game.get("status")) == "active":
            _imp_schedule_auto_skip(context, chat_id, game)
        else:
            _imp_cancel_skip_task(chat_id, gid)
    except Exception:
        logger.exception("Fallo programando/cancelando autosalto tras render")


def _imp_kick_player_from_game(game: Dict[str, Any], user_id: int) -> bool:
    player = _imp_player_by_id(game, user_id)
    if not player:
        return False
    eliminated = game.setdefault("eliminated", [])
    if int(user_id) not in [int(x) for x in eliminated]:
        eliminated.append(int(user_id))
    _imp_clear_pending_for_chat_game(int(game.get("chat_id", 0) or 0), int(game.get("id", 0) or 0), int(user_id))
    active = _imp_active_players(game)

    if active:
        game["turn_idx"] = max(0, min(int(game.get("turn_idx", 0) or 0), len(active) - 1))
    return True


def _imp_kick_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    rows: List[List[InlineKeyboardButton]] = []
    for p in _imp_active_players(game):
        try:
            rows.append([InlineKeyboardButton(f"🚫 {p.get('name') or p.get('first_name') or p.get('id')}", callback_data=f"imp|kick_player|{chat_id}|{gid}|{int(p.get('id'))}")])
        except Exception:
            pass
    rows.append([InlineKeyboardButton("🔙 Volver", callback_data=f"imp|show_turn|{chat_id}|{gid}")])
    return InlineKeyboardMarkup(rows)


_old_impostor_callback_router_v59 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    if not data.startswith("imp|"):
        return await _old_impostor_callback_router_v59(update, context)
    parts = data.split("|")
    if len(parts) < 4:
        try: await q.answer()
        except Exception: pass
        raise ApplicationHandlerStop
    action = parts[1]
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer("Partida inválida", show_alert=True); raise ApplicationHandlerStop
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer("No encuentro la partida", show_alert=True); raise ApplicationHandlerStop

    if action == "skip":
        if not await _imp_can_manage(context, chat_id, game, int(q.from_user.id)):
            await q.answer("Solo admin o creador de la partida puede saltar turnos.", show_alert=True); raise ApplicationHandlerStop
        if str(game.get("status")) != "active":
            await q.answer("La partida no está activa.", show_alert=True); raise ApplicationHandlerStop
        current = _imp_current_player(game)
        if current:
            game.setdefault("clues", []).append({"uid": int(current.get("id", 0) or 0), "name": current.get("name") or "Jugador", "text": "⏭ turno saltado por admin", "round": int(game.get("round", 1) or 1), "ts": int(time.time()), "system": True})
            _imp_clear_pending_for_chat_game(chat_id, gid, int(current.get("id", 0) or 0))
        _imp_advance_turn_skip(game)
        save_all_states()
        await q.answer("Turno saltado.")
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
        raise ApplicationHandlerStop

    if action == "kick_menu":
        if not await _imp_can_manage(context, chat_id, game, int(q.from_user.id)):
            await q.answer("Solo admin o creador puede expulsar jugadores.", show_alert=True); raise ApplicationHandlerStop
        await q.answer()
        try:
            await q.message.reply_html("🚫 <b>Expulsar jugador de la partida</b>", reply_markup=_imp_kick_markup(chat_id, game))
        except Exception:
            pass
        raise ApplicationHandlerStop

    if action == "kick_player" and len(parts) >= 5:
        if not await _imp_can_manage(context, chat_id, game, int(q.from_user.id)):
            await q.answer("Solo admin o creador puede expulsar jugadores.", show_alert=True); raise ApplicationHandlerStop
        try:
            target_id = int(parts[4])
        except Exception:
            await q.answer("Jugador inválido", show_alert=True); raise ApplicationHandlerStop
        player = _imp_player_by_id(game, target_id)
        if not player:
            await q.answer("Ese jugador no está activo.", show_alert=True); raise ApplicationHandlerStop
        _imp_kick_player_from_game(game, target_id)
        active = _imp_active_players(game)
        if len(active) < 3:
            game["status"] = "cancelled"
            save_all_states()
            _imp_cancel_skip_task(chat_id, gid)
            await q.answer("Jugador expulsado. Partida cancelada: quedan menos de 3.", show_alert=True)
            try:
                await context.bot.send_message(chat_id, f"🚫 {_imp_mention(player)} fue expulsado del juego. Quedan menos de 3 jugadores, partida cancelada.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_delete_if_exists(context.bot, chat_id, game.get("v58_card_message_id") or game.get("turn_message_id"))
            await _v58_delete_if_exists(context.bot, chat_id, game.get("v58_prompt_message_id"))
        else:
            save_all_states()
            await q.answer("Jugador expulsado del juego.")
            try:
                await context.bot.send_message(chat_id, f"🚫 {_imp_mention(player)} ha sido expulsado del juego por admin.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
        raise ApplicationHandlerStop

    return await _old_impostor_callback_router_v59(update, context)


async def impostorskip_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == "private":
        await update.message.reply_text("Usa /impostorskip dentro del grupo."); return
    games = [g for g in _imp_games(chat_id) if str(g.get("status")) == "active"]
    if not games:
        await update.message.reply_text("No hay partida activa de Impostor."); return
    game = games[-1]
    if not await _imp_can_manage(context, chat_id, game, int(update.effective_user.id)):
        await update.message.reply_text("Solo admin o creador de la partida puede saltar turnos."); return
    current = _imp_current_player(game)
    if current:
        game.setdefault("clues", []).append({"uid": int(current.get("id", 0) or 0), "name": current.get("name") or "Jugador", "text": "⏭ turno saltado por admin", "round": int(game.get("round", 1) or 1), "ts": int(time.time()), "system": True})
        _imp_clear_pending_for_chat_game(chat_id, int(game.get("id", 0) or 0), int(current.get("id", 0) or 0))
    _imp_advance_turn_skip(game)
    save_all_states()
    await update.message.reply_text("⏭ Turno saltado.")
    await _v58_imp_render_down(context, chat_id, game, delete_previous=True)


async def impostorexpulsar_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == "private":
        await update.message.reply_text("Usa /impostorexpulsar dentro del grupo."); return
    games = [g for g in _imp_games(chat_id) if str(g.get("status")) == "active"]
    if not games:
        await update.message.reply_text("No hay partida activa de Impostor."); return
    game = games[-1]
    if not await _imp_can_manage(context, chat_id, game, int(update.effective_user.id)):
        await update.message.reply_text("Solo admin o creador puede expulsar jugadores del juego."); return
    target_id = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_id = int(update.message.reply_to_message.from_user.id)
    elif context.args:
        raw = context.args[0].strip().lstrip("@")
        if raw.isdigit():
            target_id = int(raw)
        else:
            for p in game.get("players", []) if isinstance(game.get("players"), list) else []:
                if str(p.get("username", "")).lower().lstrip("@") == raw.lower() or str(p.get("name", "")).lower() == raw.lower():
                    target_id = int(p.get("id", 0) or 0); break
    if not target_id:
        await update.message.reply_text("Responde al jugador con /impostorexpulsar o pon su ID/@username."); return
    player = _imp_player_by_id(game, target_id)
    if not player:
        await update.message.reply_text("Ese usuario no está activo en la partida."); return
    _imp_kick_player_from_game(game, target_id)
    active = _imp_active_players(game)
    if len(active) < 3:
        game["status"] = "cancelled"
        save_all_states()
        _imp_cancel_skip_task(chat_id, int(game.get("id", 0) or 0))
        await update.message.reply_html(f"🚫 {_imp_mention(player)} expulsado del juego. Quedan menos de 3 jugadores, partida cancelada.")
        await _v58_delete_if_exists(context.bot, chat_id, game.get("v58_card_message_id") or game.get("turn_message_id"))
        await _v58_delete_if_exists(context.bot, chat_id, game.get("v58_prompt_message_id"))
        return
    save_all_states()
    await update.message.reply_html(f"🚫 {_imp_mention(player)} expulsado del juego.")
    await _v58_imp_render_down(context, chat_id, game, delete_previous=True)


_old_build_application_v59 = build_application
