IMPOSTOR_TURN_SECONDS = 60


def _v60_penalties(game: Dict[str, Any]) -> Dict[str, int]:
    p = game.setdefault("score_penalties", {})
    if not isinstance(p, dict):
        p = {}
        game["score_penalties"] = p
    return p


def _v60_add_penalty(game: Dict[str, Any], user_id: int, points: int) -> None:
    p = _v60_penalties(game)
    uid = str(int(user_id))
    p[uid] = int(p.get(uid, 0) or 0) + int(points)


def _v60_timeout_counts(game: Dict[str, Any]) -> Dict[str, int]:
    d = game.setdefault("timeout_counts", {})
    if not isinstance(d, dict):
        d = {}
        game["timeout_counts"] = d
    return d


def _v60_current_timeout_count(game: Dict[str, Any], user_id: int) -> int:
    return int(_v60_timeout_counts(game).get(str(int(user_id)), 0) or 0)


def _v60_format_remaining(seconds: int = IMPOSTOR_TURN_SECONDS) -> str:
    seconds = max(0, int(seconds))
    m, s = divmod(seconds, 60)
    return f"{m}:{s:02d}"


_old_v58_imp_prompt_text_v60 = _v58_imp_prompt_text
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    base = _old_v58_imp_prompt_text_v60(game)
    current = _imp_current_player(game)
    warn = ""
    if current:
        c = _v60_current_timeout_count(game, int(current.get("id", 0) or 0))
        if c <= 0:
            warn = "Si no responde, pierde <b>1 punto</b> y salto turno."
        else:
            warn = "Si vuelve a quedarse sin responder, queda <b>expulsado del juego</b> y pierde <b>3 puntos más</b>."
    return base + f"\n\n⏱ <b>Tiempo:</b> {_v60_format_remaining()} · {warn}"


_old_v51_imp_text_v60 = globals().get('_v51_imp_text')
def _v60_imp_text(chat_id: int) -> str:
    try:
        base = _old_v51_imp_text_v60(chat_id) if callable(_old_v51_imp_text_v60) else admin_private_block_text(chat_id, 'impostor_settings')
    except Exception:
        base = "<b>🎭 Configuración Impostor</b>"
    return base + (
        "\n\n<b>Opciones nuevas</b>"
        f"\nInicio aleatorio: <b>{_v51_bool_label(cfg_value(chat_id, 'imp_random_start', True)) if '_v51_bool_label' in globals() else ('ON' if cfg_value(chat_id, 'imp_random_start', True) else 'OFF')}</b>"
        "\nMensaje fijado para unirse: crea un aviso arriba con botón para entrar al juego. Se quitará automáticamente al empezar la partida."
    )


_old_v51_imp_markup_v60 = globals().get('_v51_imp_markup')
def _v60_imp_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows = []
    try:
        old = _old_v51_imp_markup_v60(chat_id) if callable(_old_v51_imp_markup_v60) else None
        if old and getattr(old, 'inline_keyboard', None):
            rows = [list(r) for r in old.inline_keyboard]
    except Exception:
        rows = []

    back = None
    if rows and rows[-1] and any('Volver' in (getattr(b, 'text', '') or '') for b in rows[-1]):
        back = rows.pop()
    status = '✅' if bool(cfg_value(chat_id, 'imp_random_start', True)) else '❌'
    rows.append([InlineKeyboardButton(f"{status} Inicio aleatorio", callback_data=f"cfg|impconf|{chat_id}|toggle|imp_random_start|1")])
    rows.append([InlineKeyboardButton("📌 Fijar botón para jugar", callback_data=f"cfg|imp_pin|{chat_id}")])
    rows.append(back or [InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")])
    return InlineKeyboardMarkup(rows)


_old_admin_private_block_text_v60 = admin_private_block_text
