_old_admin_private_block_markup_v60 = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str) -> InlineKeyboardMarkup:
    if block == 'impostor_settings':
        return _v60_imp_markup(chat_id)
    return _old_admin_private_block_markup_v60(chat_id, block)


async def _v60_pin_impostor_invite(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> int:
    cfg = admin_cfg(chat_id)
    old_mid = int(cfg.get('impostor_invite_pin_id') or 0)
    if old_mid:
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=old_mid)
        except Exception:
            pass
        try:
            await safe_delete(context.bot, chat_id, old_mid)
        except Exception:
            pass
        cfg['impostor_invite_pin_id'] = 0
    txt = (
        "🎭 <b>Juego del Impostor</b>\n\n"
        "Pulsa el botón para crear/unirte a la sala.\n"
        "Cuando empiece la partida, este aviso se quitará automáticamente."
    )
    msg = await context.bot.send_message(
        chat_id,
        txt,
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🎭 Jugar / Unirme", callback_data=f"imp|pin_join|{chat_id}|0")]])
    )
    cfg['impostor_invite_pin_id'] = int(msg.message_id)
    save_all_states()
    try:
        await context.bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
    except Exception:
        pass
    return int(msg.message_id)


async def _v60_remove_impostor_invite_pin(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    cfg = admin_cfg(chat_id)
    mid = int(cfg.get('impostor_invite_pin_id') or 0)
    if not mid:
        return
    try:
        await context.bot.unpin_chat_message(chat_id=chat_id, message_id=mid)
    except Exception:
        pass
    try:
        await safe_delete(context.bot, chat_id, mid)
    except Exception:
        pass
    cfg['impostor_invite_pin_id'] = 0
    save_all_states()


async def _v60_create_or_join_impostor_from_pin(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    q = update.callback_query
    if not q:
        return
    uid = int(q.from_user.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active and str(active.get('status')) != 'lobby':
        await q.answer('Ya hay una partida en marcha.', show_alert=True)
        return
    if not active:
        word = secrets.choice(IMPOSTOR_WORDS)
        gid = _imp_next_id(chat_id)
        active = {
            'id': gid,
            'status': 'lobby',
            'word': word,
            'creator_id': uid,
            'created_ts': int(time.time()),
            'players': [{'id': uid, 'name': display_name(q.from_user), 'username': getattr(q.from_user, 'username', '') or ''}],
            'round': 1,
            'turn_idx': 0,
            'votes': {},
            'impostor_id': 0,
            'message_id': 0,
        }
        msg = await context.bot.send_message(chat_id, _imp_lobby_text(active), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, active))
        active['message_id'] = int(msg.message_id)
        _imp_games(chat_id).insert(0, active)
        save_all_states()
        await q.answer('Sala creada y te has unido 🎭')
        return
    if _imp_player(active, uid):
        await q.answer('Ya estás dentro ✅')
        return
    players = active.setdefault('players', [])
    if len(players) >= 20:
        await q.answer('Máximo 20 jugadores', show_alert=True)
        return
    players.append({'id': uid, 'name': display_name(q.from_user), 'username': getattr(q.from_user, 'username', '') or ''})
    save_all_states()
    try:
        mid = int(active.get('message_id') or 0)
        if mid:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_imp_lobby_text(active), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, active))
    except Exception:
        pass
    await q.answer('Te has unido 🎭')


_old_v58_imp_start_game_v60 = _v58_imp_start_game
async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:

    q = update.callback_query
    uid = int(q.from_user.id) if q else 0
    allowed = uid == int(game.get('creator_id', 0) or 0) or await is_admin(context, chat_id, uid)
    if not allowed:
        if q: await q.answer('Solo creador/admin puede empezar', show_alert=True)
        raise ApplicationHandlerStop
    players = game.get('players', []) if isinstance(game.get('players'), list) else []
    if len(players) < 3:
        if q: await q.answer('Mínimo 3 jugadores', show_alert=True)
        raise ApplicationHandlerStop
    game['status'] = 'active'
    game['round'] = 1
    game['turn_idx'] = secrets.randbelow(len(players)) if bool(cfg_value(chat_id, 'imp_random_start', True)) and players else 0
    game['votes'] = {}
    game['eliminated'] = []
    game['accusations'] = []
    game['clues'] = []
    game['timeout_counts'] = {}
    game['score_penalties'] = {}
    game['impostor_id'] = int(secrets.choice(players).get('id'))
    save_all_states()
    await _v60_remove_impostor_invite_pin(context, chat_id)
    try:
        if q and q.message:
            await safe_delete(context.bot, chat_id, q.message.message_id)
    except Exception:
        pass
    if q:
        await q.answer('Partida iniciada 🎭')
    await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    raise ApplicationHandlerStop


_old_imp_auto_skip_later_v60 = _imp_auto_skip_later
async def _imp_auto_skip_later(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, user_id: int, round_no: int, turn_idx: int) -> None:
    try:
        await asyncio.sleep(IMPOSTOR_TURN_SECONDS)
        game = _imp_find(chat_id, gid)
        if not game or str(game.get('status')) != 'active':
            return
        current = _imp_current_player(game)
        if not current or int(current.get('id', 0) or 0) != int(user_id):
            return
        if int(game.get('round', 1) or 1) != int(round_no):
            return
        if int(game.get('turn_idx', 0) or 0) != int(turn_idx):
            return
        counts = _v60_timeout_counts(game)
        uid = str(int(user_id))
        previous = int(counts.get(uid, 0) or 0)
        counts[uid] = previous + 1
        name = current.get('name') or current.get('first_name') or 'Jugador'
        _imp_clear_pending_for_chat_game(chat_id, gid, user_id)
        if previous <= 0:
            _v60_add_penalty(game, user_id, -1)
            game.setdefault('clues', []).append({'uid': int(user_id), 'name': str(name), 'text': '⏭ perdió turno por no responder (-1 punto)', 'round': int(game.get('round', 1) or 1), 'ts': int(time.time()), 'system': True})
            _imp_advance_turn_skip(game)
            save_all_states()
            try:
                await context.bot.send_message(chat_id, f"⏭ {_imp_mention(current)} no respondió en 1 minuto. Pierde <b>1 punto</b> y paso turno.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
            return

        _v60_add_penalty(game, user_id, -3)
        _imp_kick_player_from_game(game, user_id)
        game.setdefault('clues', []).append({'uid': int(user_id), 'name': str(name), 'text': '🚫 expulsado por segunda inactividad (-3 puntos)', 'round': int(game.get('round', 1) or 1), 'ts': int(time.time()), 'system': True})
        active = _imp_active_players(game)
        if len(active) < 3:
            game['status'] = 'cancelled'
            save_all_states()
            try:
                await context.bot.send_message(chat_id, f"🚫 {_imp_mention(current)} volvió a quedarse sin responder. Queda expulsado del juego y pierde <b>3 puntos</b>.\nQuedan menos de 3 jugadores: partida cancelada.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_card_message_id') or game.get('turn_message_id'))
            await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
            return
        save_all_states()
        try:
            await context.bot.send_message(chat_id, f"🚫 {_imp_mention(current)} volvió a quedarse sin responder. Queda expulsado del juego y pierde <b>3 puntos</b> más.", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error en autosalto/expulsión Impostor V60')
    finally:
        IMPOSTOR_SKIP_TASKS.pop(_imp_game_key(chat_id, gid), None)


def _v60_add_delta_no_game(chat_id: int, player: Dict[str, Any], points: int) -> None:
    try:
        uid = str(int(player.get('id', 0) or 0))
    except Exception:
        return
    name = str(player.get('name') or uid)
    store = _imp_score_store(chat_id)
    for scope, key in (("general", "all"), ("daily", _v44_today_key()), ("weekly", _v44_week_key())):
        bucket = store.setdefault(scope, {})
        period = bucket.setdefault(key, {})
        row = period.setdefault(uid, {'name': name, 'points': 0, 'games': 0})
        row['name'] = name
        row['points'] = int(row.get('points', 0) or 0) + int(points)


_old_imp_score_game_v60 = _imp_score_game
def _imp_score_game(chat_id: int, game: Dict[str, Any], winner_side: str) -> str:
    txt = _old_imp_score_game_v60(chat_id, game, winner_side)
    penalties = game.get('score_penalties') if isinstance(game.get('score_penalties'), dict) else {}
    if penalties and not game.get('ranking_penalties_applied'):
        players = game.get('players', []) if isinstance(game.get('players'), list) else []
        by_id = {str(int(p.get('id', 0) or 0)): p for p in players if str(p.get('id', '')).lstrip('-').isdigit()}
        total_pen = 0
        for uid, pts in penalties.items():
            try:
                p = by_id.get(str(int(uid)))
                val = int(pts)
            except Exception:
                continue
            if p and val:
                _v60_add_delta_no_game(chat_id, p, val)
                total_pen += val
        game['ranking_penalties_applied'] = True
        save_all_states()
        if total_pen:
            txt += "\n⏱ Penalizaciones de inactividad aplicadas al ranking."
    return txt


_old_admin_private_config_callback_v60 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|imp_pin|'):
        try:
            chat_id = int(data.split('|')[2])
        except Exception:
            await q.answer('Grupo inválido', show_alert=True); return
        try:
            await _v60_pin_impostor_invite(context, chat_id)
            await q.answer('Mensaje fijado creado en el grupo ✅', show_alert=True)
            await _v51_render(q, admin_private_block_text(chat_id, 'impostor_settings'), admin_private_block_markup(chat_id, 'impostor_settings')) if '_v51_render' in globals() else None
        except Exception as e:
            logger.exception('No se pudo fijar invitación de Impostor')
            await q.answer(f'No pude fijarlo: {type(e).__name__}', show_alert=True)
        raise ApplicationHandlerStop
    return await _old_admin_private_config_callback_v60(update, context)


_old_impostor_callback_router_v60 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    if data.startswith('imp|pin_join|') and len(parts) >= 3:
        try:
            chat_id = int(parts[2])
        except Exception:
            await q.answer('Grupo inválido', show_alert=True); raise ApplicationHandlerStop
        await _v60_create_or_join_impostor_from_pin(update, context, chat_id)
        raise ApplicationHandlerStop
    return await _old_impostor_callback_router_v60(update, context)


