def _v61_int_cfg(chat_id: int, key: str, default: int, min_v: int, max_v: int) -> int:
    try:
        v = int(cfg_value(chat_id, key, default) or default)
    except Exception:
        v = default
    return max(min_v, min(max_v, v))


def _v61_turn_seconds(chat_id: int) -> int:

    return _v61_int_cfg(chat_id, "imp_turn_seconds", 60, 20, 300)


def _v61_min_accuse_round(chat_id: int) -> int:
    return _v61_int_cfg(chat_id, "imp_min_accuse_round", 1, 1, 3)


def _v61_final_vote_only(chat_id: int) -> bool:
    return bool(cfg_value(chat_id, "imp_final_vote_only", False))


def _v61_seconds_human(seconds: int) -> str:
    try:
        s = int(seconds)
    except Exception:
        s = 60
    if s < 60:
        return f"{s} segundos"
    if s == 60:
        return "1 minuto"
    if s % 60 == 0:
        return f"{s//60} minutos"
    m, r = divmod(s, 60)
    return f"{m} min {r}s"


def _v61_can_accuse_now(chat_id: int, game: Dict[str, Any]) -> tuple[bool, str]:
    if _v61_final_vote_only(chat_id):
        return False, "En esta configuración solo se descubre al impostor por votación final."
    try:
        ronda = int(game.get("round", 1) or 1)
    except Exception:
        ronda = 1
    min_r = _v61_min_accuse_round(chat_id)
    if ronda < min_r:
        return False, f"Todavía no se puede acusar. Configurado desde la ronda {min_r}."
    return True, ""


_old_v60_imp_text_v61 = globals().get('_v60_imp_text')
def _v61_imp_text(chat_id: int) -> str:
    try:
        base = _old_v60_imp_text_v61(chat_id) if callable(_old_v60_imp_text_v61) else admin_private_block_text(chat_id, 'impostor_settings')
    except Exception:
        base = "<b>🎭 Configuración Impostor</b>"
    return base + (
        "\n\n<b>Control de turnos y acusaciones</b>"
        f"\nTiempo para responder: <b>{h(_v61_seconds_human(_v61_turn_seconds(chat_id)))}</b>"
        f"\nAcusar permitido desde ronda: <b>{_v61_min_accuse_round(chat_id)}</b>"
        f"\nSolo votación final: <b>{'ON' if _v61_final_vote_only(chat_id) else 'OFF'}</b>"
        "\n\nSi activas <b>Solo votación final</b>, nadie podrá pulsar 'El impostor es...' durante las rondas. Solo se votará al terminar las 3 rondas."
    )


