_old_admin_private_block_markup_v61 = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str) -> InlineKeyboardMarkup:
    if block != 'impostor_settings':
        return _old_admin_private_block_markup_v61(chat_id, block)
    try:
        old = _old_admin_private_block_markup_v61(chat_id, block)
        rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]
    except Exception:
        rows = []
    back = None
    if rows and rows[-1] and any('Volver' in (getattr(b, 'text', '') or '') for b in rows[-1]):
        back = rows.pop()

    current_t = _v61_turn_seconds(chat_id)
    rows.append([
        InlineKeyboardButton(("✅ " if current_t == 30 else "") + "30s", callback_data=f"cfg|imp61|{chat_id}|turn|30"),
        InlineKeyboardButton(("✅ " if current_t == 60 else "") + "1 min", callback_data=f"cfg|imp61|{chat_id}|turn|60"),
        InlineKeyboardButton(("✅ " if current_t == 90 else "") + "1:30", callback_data=f"cfg|imp61|{chat_id}|turn|90"),
        InlineKeyboardButton(("✅ " if current_t == 120 else "") + "2 min", callback_data=f"cfg|imp61|{chat_id}|turn|120"),
    ])
    min_r = _v61_min_accuse_round(chat_id)
    rows.append([
        InlineKeyboardButton(("✅ " if min_r == 1 else "") + "Acusar R1", callback_data=f"cfg|imp61|{chat_id}|minround|1"),
        InlineKeyboardButton(("✅ " if min_r == 2 else "") + "Acusar R2", callback_data=f"cfg|imp61|{chat_id}|minround|2"),
        InlineKeyboardButton(("✅ " if min_r == 3 else "") + "Acusar R3", callback_data=f"cfg|imp61|{chat_id}|minround|3"),
    ])
    rows.append([
        InlineKeyboardButton(("✅ " if _v61_final_vote_only(chat_id) else "❌ ") + "Solo votación final", callback_data=f"cfg|imp61|{chat_id}|toggle|imp_final_vote_only")
    ])
    rows.append(back or [InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")])
    return InlineKeyboardMarkup(rows)


_old_v58_imp_prompt_text_v61 = _v58_imp_prompt_text
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:

    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    base = _old_v58_imp_prompt_text_v61(game)
    if chat_id:

        base = base.replace("⏱ <b>Tiempo:</b> 1:00", f"⏱ <b>Tiempo:</b> {_v60_format_remaining(_v61_turn_seconds(chat_id))}")
        base = base.replace("Si no responde en <b>1 minuto</b>", f"Si no responde en <b>{h(_v61_seconds_human(_v61_turn_seconds(chat_id)))}</b>")
    return base


_old_v58_imp_card_markup_v61 = _v58_imp_card_markup
def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get("id", 0) or 0)
    status = str(game.get("status") or "lobby")
