    if not _v61_final_vote_only(chat_id):
        rows.append([InlineKeyboardButton("🗳 Votación final", callback_data=f"imp|vote_menu|{chat_id}|{gid}"), InlineKeyboardButton("🏆 Ranking", callback_data=f"imp|ranking|{chat_id}|{gid}")])
    else:
        rows.append([InlineKeyboardButton("🏆 Ranking", callback_data=f"imp|ranking|{chat_id}|{gid}")])
