_old_imp_auto_skip_later_v61 = _imp_auto_skip_later
async def _imp_auto_skip_later(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, user_id: int, round_no: int, turn_idx: int) -> None:

    try:
        await asyncio.sleep(_v61_turn_seconds(chat_id))
        game = _imp_find(chat_id, gid)
        if not game or str(game.get('status')) != 'active':
            return
        current = _imp_current_player(game)
        if not current or int(current.get('id', 0) or 0) != int(user_id):
            return
        if int(game.get('round', 1) or 1) != int(round_no):
            return
        if int(game.get('turn_idx', 0) or 0) != int(turn_idx):
            return
        counts = _v60_timeout_counts(game)
        uid = str(int(user_id))
        previous = int(counts.get(uid, 0) or 0)
        counts[uid] = previous + 1
        name = current.get('name') or current.get('first_name') or 'Jugador'
        _imp_clear_pending_for_chat_game(chat_id, gid, user_id)
        if previous <= 0:
            _v60_add_penalty(game, user_id, -1)
            game.setdefault('clues', []).append({'uid': int(user_id), 'name': str(name), 'text': '⏭ perdió turno por no responder (-1 punto)', 'round': int(game.get('round', 1) or 1), 'ts': int(time.time()), 'system': True})
            _imp_advance_turn_skip(game)
            save_all_states()
            try:
                await context.bot.send_message(chat_id, f"⏭ {_imp_mention(current)} no respondió en {_v61_seconds_human(_v61_turn_seconds(chat_id))}. Pierde <b>1 punto</b> y paso turno.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
            return
        _v60_add_penalty(game, user_id, -3)
        _imp_kick_player_from_game(game, user_id)
        game.setdefault('clues', []).append({'uid': int(user_id), 'name': str(name), 'text': '🚫 expulsado por segunda inactividad (-3 puntos)', 'round': int(game.get('round', 1) or 1), 'ts': int(time.time()), 'system': True})
        active = _imp_active_players(game)
        if len(active) < 3:
            game['status'] = 'cancelled'
            save_all_states()
            try:
                await context.bot.send_message(chat_id, f"🚫 {_imp_mention(current)} volvió a quedarse sin responder. Queda expulsado del juego y pierde <b>3 puntos</b>.\nQuedan menos de 3 jugadores: partida cancelada.", parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_card_message_id') or game.get('turn_message_id'))
            await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
            return
        save_all_states()
        try:
            await context.bot.send_message(chat_id, f"🚫 {_imp_mention(current)} volvió a quedarse sin responder. Queda expulsado del juego y pierde <b>3 puntos</b> más.", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error en autosalto/expulsión Impostor V61')
    finally:
        IMPOSTOR_SKIP_TASKS.pop(_imp_game_key(chat_id, gid), None)


_old_admin_private_config_callback_v61 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|imp61|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2])
            action = parts[3]
            value = parts[4] if len(parts) > 4 else ''
        except Exception:
            await q.answer('Configuración inválida', show_alert=True)
            raise ApplicationHandlerStop
        if action == 'turn':
            cfg_set(chat_id, 'imp_turn_seconds', _v61_int_cfg(chat_id, 'tmp', int(value), 20, 300) if str(value).isdigit() else 60)
            await q.answer('Tiempo actualizado ✅')
        elif action == 'minround':
            cfg_set(chat_id, 'imp_min_accuse_round', _v61_int_cfg(chat_id, 'tmp', int(value), 1, 3) if str(value).isdigit() else 1)
            await q.answer('Ronda mínima actualizada ✅')
        elif action == 'toggle' and value == 'imp_final_vote_only':
            cfg_set(chat_id, 'imp_final_vote_only', not _v61_final_vote_only(chat_id))
            await q.answer('Modo de votación actualizado ✅')
        else:
            await q.answer('Acción no reconocida', show_alert=True)
        try:
            await _v51_render(q, admin_private_block_text(chat_id, 'impostor_settings'), admin_private_block_markup(chat_id, 'impostor_settings'))
        except Exception:
            try:
                await q.message.reply_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
            except Exception:
                pass
        raise ApplicationHandlerStop
    return await _old_admin_private_config_callback_v61(update, context)


_old_impostor_callback_router_v61 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v61(update, context)
    parts = data.split('|')
    try:
        action = parts[1]
        chat_id = int(parts[2]) if len(parts) > 2 else 0
        gid = int(parts[3]) if len(parts) > 3 else 0
        game = _imp_find(chat_id, gid) if chat_id and gid else None
    except Exception:
        game = None
        action = ''
        chat_id = 0
    if game and action in ('accuse_menu', 'accuse'):
        allowed, reason = _v61_can_accuse_now(chat_id, game)
        if not allowed:
            await q.answer(reason, show_alert=True)
            raise ApplicationHandlerStop
    if game and action == 'vote_menu' and _v61_final_vote_only(chat_id) and str(game.get('status')) != 'voting':
        await q.answer('La votación solo se abre al terminar todas las rondas.', show_alert=True)
        raise ApplicationHandlerStop
    await _old_impostor_callback_router_v61(update, context)
    raise ApplicationHandlerStop


_old_build_application_v61 = build_application
def build_application() -> Application:
    app = _old_build_application_v61()
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r"^imp\|"), group=-100600)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r"^cfg\|imp61\|"), group=-100600)
    logger.info('V61 Impostor configuración avanzada cargada')
    return app


import re as _re_v62

try:
    from telegram.ext import ApplicationHandlerStop
except Exception:
    ApplicationHandlerStop = Exception

OWNER_IDS = parse_admin_ids(os.getenv("BOT_OWNER_IDS", "")) or set(ADMIN_IDS)

PERMISSION_MODULES_V62 = [
    ("polls", "📊 Encuestas"),
    ("impostor", "🎭 Impostor"),
    ("ai", "🧠 Cerebrito"),
    ("pregonero", "📣 Pregonero"),
    ("daily_phrase", "🌞 Frase del día"),
    ("ai_commands", "⚙️ Comandos IA"),
]
PERMISSION_ROLES_V62 = [
    ("owner", "👑 Dueño"),
    ("admins", "🛡 Admins Telegram"),
    ("admin_ids", "🆔 IDs Admin"),
    ("members", "👥 Miembros"),
]
DEFAULT_PERMISSION_V62 = {
    "polls": "admins",
    "impostor": "members",
    "ai": "members",
    "pregonero": "admins",
    "daily_phrase": "members",
    "ai_commands": "members",
}

try:
    if ("permissions", "🔐 Permisos módulos") not in ADMIN_PRIVATE_BLOCKS:
        ADMIN_PRIVATE_BLOCKS.append(("permissions", "🔐 Permisos módulos"))
    if "ADMIN_PRIVATE_BLOCK_IDS" in globals():
        ADMIN_PRIVATE_BLOCK_IDS.update({"permissions", "ai"})
except Exception:
    pass


def _v62_bool(value: bool) -> str:
    return "ON ✅" if bool(value) else "OFF ❌"


def _v62_role_label(role: str) -> str:
    return dict(PERMISSION_ROLES_V62).get(str(role), str(role))


def _v62_perm_key(module: str) -> str:
    return f"perm_{module}"


def _v62_module_role(chat_id: int, module: str) -> str:
    return str(cfg_value(chat_id, _v62_perm_key(module), DEFAULT_PERMISSION_V62.get(module, "admins")) or DEFAULT_PERMISSION_V62.get(module, "admins"))


async def _v62_is_owner(user_id: int) -> bool:
    return int(user_id) in OWNER_IDS


async def _v62_allowed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int, module: str) -> bool:
    role = _v62_module_role(chat_id, module)
    user_id = int(user_id)
    if role == "members":
        return True
    if user_id in OWNER_IDS:
        return True
    if role == "owner":
        return False
    if role == "admin_ids":
        return user_id in ADMIN_IDS
    if role == "admins":
        return await is_admin(context, chat_id, user_id)
    return await is_admin(context, chat_id, user_id)


async def _v62_guard_command(update: Update, context: ContextTypes.DEFAULT_TYPE, module: str) -> bool:
    if not update.effective_chat or not update.effective_user or not update.message:
        return False
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == "private":
        return True
    if not await _v62_allowed(context, chat_id, int(update.effective_user.id), module):
        await update.message.reply_html(f"⛔ Este comando está limitado a: <b>{h(_v62_role_label(_v62_module_role(chat_id, module)))}</b>.")
        raise ApplicationHandlerStop
    return True


async def _v62_guard_ai_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmd = ""
    if update.message and update.message.text:
        cmd = update.message.text.split()[0].split('@')[0].lstrip('/').lower()
    chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    module = "ai_commands" if cmd not in ("cerebrito", "planecito", "iatest", "tiempo") else "ai"
    await _v62_guard_command(update, context, module)


async def _v62_guard_impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "impostor")


async def _v62_guard_poll_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "polls")


async def _v62_guard_pregonero_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "pregonero")


async def _v62_guard_daily_phrase_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _v62_guard_command(update, context, "daily_phrase")


def _v62_ai_rows(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    rows = cfg.setdefault("ai_recurrents", [])
    if not isinstance(rows, list):
        rows = []
        cfg["ai_recurrents"] = rows
    return rows


def _v62_next_id(rows: List[Dict[str, Any]]) -> int:
    try:
        return max([int(r.get("id", 0) or 0) for r in rows] + [0]) + 1
    except Exception:
        return int(time.time())


def _v62_schedule_label(row: Dict[str, Any]) -> str:
    sched = row.get("schedule") if isinstance(row.get("schedule"), dict) else {}
    return str(sched.get("label") or _schedule_label_v20(sched) if '_schedule_label_v20' in globals() else sched.get('type', ''))


def _v62_format_ai_recurrent(row: Dict[str, Any]) -> str:
    state = "ON" if bool(row.get("enabled", True)) else "OFF"
    img = " · imagen" if bool(row.get("image", False)) else ""
    return f"#{row.get('id')} · {h(row.get('name','IA'))} · {h(_v62_schedule_label(row))} · {state}{img}"


async def _v62_send_ai_recurrent(application: Application, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    prompt = str(row.get("prompt") or "Genera un mensaje corto y divertido para el grupo.").strip()
    name = str(row.get("name") or "Cerebrito")
    answer = await _v57_cerebrito_answer(chat_id, prompt, max_output_tokens=350) if '_v57_cerebrito_answer' in globals() else await _ai_openai_response(chat_id, prompt, max_output_tokens=350)
    text = f"<b>{h(name)}</b>\n\n{h(answer)}"
    try:
        if bool(row.get("image", False)) and '_ai_generate_greeting_image' in globals():
            img = _ai_generate_greeting_image(name, answer[:80])
            if img:
                msg = await application.bot.send_photo(chat_id, photo=img, caption=text[:1000], parse_mode=ParseMode.HTML)
                return int(msg.message_id)
        msg = await application.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)
        return int(msg.message_id)
    except Exception:
        logger.exception("No se pudo enviar recurrente IA %s en %s", row.get('id'), chat_id)
        return None


async def _v62_ai_recurrent_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    now_dt = _local_dt_v15(now) if '_local_dt_v15' in globals() else __import__('datetime').datetime.now()
    for chat_id in list(STATE_CACHE.keys()):
        try:
            for row in _v62_ai_rows(int(chat_id)):
                if not recurring_due(row, now):
                    continue

                row["last_sent_ts"] = now
                sched_type = (row.get("schedule") or {}).get("type") if isinstance(row.get("schedule"), dict) else ""
                if sched_type == "daily":
                    row["last_day"] = now_dt.strftime("%Y-%m-%d")
                elif sched_type == "weekly":
                    row["last_week_key"] = f"{now_dt.strftime('%G-%V')}-{now_dt.weekday()}"
                elif sched_type == "date":
                    row["last_date_key"] = str((row.get("schedule") or {}).get("date", now_dt.strftime("%Y-%m-%d")))
                    row["enabled"] = False
                save_all_states()
                await _v62_send_ai_recurrent(context.application, int(chat_id), row)
                await asyncio.sleep(0.5)
        except Exception:
            logger.exception("Error en recurrente IA chat %s", chat_id)


