async def _v69_send_recurring_preview(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
    except Exception:
        await q.answer('Vista previa inválida.', show_alert=True)
        raise ApplicationHandlerStop
    row = recurring_find(chat_id, rid)
    if not row:
        await q.answer('No encuentro ese recurrente.', show_alert=True)
        raise ApplicationHandlerStop
    if not await is_admin(context, chat_id, q.from_user.id):
        await q.answer('Solo administradores.', show_alert=True)
        raise ApplicationHandlerStop
    await q.answer('Enviando vista previa…')
    text = str(row.get('text') or '').strip()
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    markup = recurring_buttons_markup(row, self_url=str(row.get('last_message_link') or 'https://t.me/'), chat_id=int(chat_id))
    header = '👁 <b>Vista previa del recurrente</b>\n<blockquote>Así se verá en el grupo. Los botones son funcionales.</blockquote>\n\n'
    try:
        if media and media.get('file_id'):
            fid = media.get('file_id'); mtype = media.get('type')
            caption = header + (text or '')
            if mtype == 'photo':
                await context.bot.send_photo(q.message.chat_id, photo=fid, caption=caption[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
            elif mtype == 'video':
                await context.bot.send_video(q.message.chat_id, video=fid, caption=caption[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
            elif mtype == 'animation':
                await context.bot.send_animation(q.message.chat_id, animation=fid, caption=caption[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
            else:
                await context.bot.send_document(q.message.chat_id, document=fid, caption=caption[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await context.bot.send_message(q.message.chat_id, header + (text or 'Mensaje recurrente'), parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    except Exception as e:
        logger.exception('No se pudo enviar vista previa recurrente')
        await q.answer(f'Error enviando vista previa: {type(e).__name__}', show_alert=True)
    raise ApplicationHandlerStop


async def _v69_recurring_command_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        await q.answer('Botón inválido', show_alert=True)
        raise ApplicationHandlerStop
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = int(q.message.chat_id) if q.message else 0
    cmd = _v66_clean_cmd_name(parts[2]) if '_v66_clean_cmd_name' in globals() else _v65_clean_rec_cmd(parts[2])
    user = q.from_user
    allowed = set(_v66_allowed_rec_commands(chat_id)) if '_v66_allowed_rec_commands' in globals() else set(_V65_ALLOWED_REC_COMMANDS)
    if not cmd:
        await q.answer('Comando vacío', show_alert=True)
        raise ApplicationHandlerStop
    if cmd not in allowed:
        await q.answer(f'/{cmd} no está permitido en botones.', show_alert=True)
        raise ApplicationHandlerStop
    try:
        await q.answer('Ejecutando…')
    except Exception:
        pass
    try:
        chat_type = 'supergroup' if int(chat_id) < 0 else 'private'
        title = get_chat_title(chat_id) if 'get_chat_title' in globals() else str(chat_id)
        fake_update_id = int(time.time() * 1000) % 2147483647

        fake_msg_id = 2140000000 - (fake_update_id % 1000000)
        payload = {
            'update_id': fake_update_id,
            'message': {
                'message_id': fake_msg_id,
                'date': int(time.time()),
                'chat': {'id': int(chat_id), 'type': chat_type, 'title': title},
                'from': {
                    'id': int(user.id),
                    'is_bot': False,
                    'first_name': getattr(user, 'first_name', None) or 'Usuario',
                    'last_name': getattr(user, 'last_name', None) or None,
                    'username': getattr(user, 'username', None) or None,
                },
                'text': f'/{cmd}',
                'entities': [{'type': 'bot_command', 'offset': 0, 'length': len(cmd) + 1}],
            },
        }
        fake_update = Update.de_json(payload, context.bot)
        await context.application.process_update(fake_update)
    except Exception:
        logger.exception('Error ejecutando comando permitido desde recurrente V69: %s', q.data)
        try:
            await q.answer('Error ejecutando el comando. Revisa logs.', show_alert=True)
        except Exception:
            pass
    raise ApplicationHandlerStop


