def _v70_repeat_menu_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    opts = [
        ("20 min", 20 * 60),
        ("1 hora", 3600),
        ("2 horas", 2 * 3600),
        ("4 horas", 4 * 3600),
        ("6 horas", 6 * 3600),
        ("12 horas", 12 * 3600),
        ("24 horas", 24 * 3600),
    ]
    rows: List[List[InlineKeyboardButton]] = []
    for i in range(0, len(opts), 2):
        row = []
        for label, sec in opts[i:i+2]:
            row.append(InlineKeyboardButton(f"cada {label}", callback_data=f"cfg|rec_repeat_set|{chat_id}|{rid}|{sec}|recurrentes"))
        rows.append(row)
    rows.append([InlineKeyboardButton("✍️ Otro intervalo", callback_data=f"cfg|rec_repeat_custom|{chat_id}|{rid}|recurrentes")])
    rows.append([InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|rec_edit|{chat_id}|{rid}|recurrentes")])
    return InlineKeyboardMarkup(rows)


async def _v70_recurring_schedule_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    parts = q.data.split('|')

    if len(parts) < 4 or parts[0] != 'cfg':
        return
    action = parts[1]
    if action not in {'rec_start_custom', 'rec_repeat_menu', 'rec_repeat_set', 'rec_repeat_custom', 'rec_until_toggle', 'rec_until_custom'}:
        return
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
    except Exception:
        await q.answer('Datos inválidos.', show_alert=True)
        raise _ApplicationHandlerStop_v70
    if not await is_admin(context, chat_id, q.from_user.id):
        await q.answer('Solo administradores.', show_alert=True)
        raise _ApplicationHandlerStop_v70
    row = recurring_find(chat_id, rid)
    if not row:
        await q.answer('No encuentro ese recurrente.', show_alert=True)
        raise _ApplicationHandlerStop_v70
    try:
        if action == 'rec_start_custom':
            set_config_pending(q.from_user.id, {'kind': 'cfg_rec_set_start_v70', 'chat_id': chat_id, 'rid': rid, 'return_block': 'recurrentes'})
            await q.answer()
            await q.edit_message_text(
                "🟢 <b>Inicio del recurrente</b>\n\n"
                "Escribe cuándo debe empezar. Ejemplos:\n"
                "<code>lunes 10:00</code>\n"
                "<code>diario 10:00</code>\n"
                "<code>2026-05-20 09:30</code>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')]])
            )
        elif action == 'rec_repeat_menu':
            await q.answer()
            await q.edit_message_text(
                "🔁 <b>Repetición</b>\n\nElige cada cuánto se repite después del inicio.",
                parse_mode=ParseMode.HTML,
                reply_markup=_v70_repeat_menu_markup(chat_id, rid)
            )
        elif action == 'rec_repeat_set':
            seconds = int(parts[4]) if len(parts) >= 5 else 3600
            sched = _v70_make_start_interval_schedule(row, repeat_seconds=seconds)
            _v70_update_row_schedule(row, sched)
            await q.answer('Repetición actualizada ✅')
            await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
        elif action == 'rec_repeat_custom':
            set_config_pending(q.from_user.id, {'kind': 'cfg_rec_set_repeat_v70', 'chat_id': chat_id, 'rid': rid, 'return_block': 'recurrentes'})
            await q.answer()
            await q.edit_message_text(
                "🔁 <b>Repetición personalizada</b>\n\nEscribe, por ejemplo:\n"
                "<code>cada 20m</code>\n<code>cada 1h</code>\n<code>cada 2 horas</code>\n<code>cada 4h</code>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')]])
            )
        elif action == 'rec_until_toggle':
            sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
            if str(sched.get('type') or '') != 'start_interval':
                sched = _v70_make_start_interval_schedule(row)
            if bool(sched.get('until_enabled')):
                sched['until_enabled'] = False
                _v70_update_row_schedule(row, sched)
                await q.answer('Hasta desactivado ✅')
                await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
            elif int(sched.get('until_ts') or 0) > 0:
                sched['until_enabled'] = True
                sched['label'] = _v70_start_interval_label(sched)
                _v70_update_row_schedule(row, sched)
                await q.answer('Hasta activado ✅')
                await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
            else:
                set_config_pending(q.from_user.id, {'kind': 'cfg_rec_set_until_v70', 'chat_id': chat_id, 'rid': rid, 'return_block': 'recurrentes'})
                await q.answer()
                await q.edit_message_text(
                    "⏹ <b>Hasta cuándo repetir</b>\n\nEscribe la fecha y hora de fin. Ejemplo:\n"
                    "<code>2026-05-20 18:00</code>\n\n"
                    "Cuando llegue esa fecha/hora, el recurrente se desactiva.",
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')]])
                )
        elif action == 'rec_until_custom':
            set_config_pending(q.from_user.id, {'kind': 'cfg_rec_set_until_v70', 'chat_id': chat_id, 'rid': rid, 'return_block': 'recurrentes'})
            await q.answer()
            await q.edit_message_text(
                "🕘 <b>Fecha/hora de fin</b>\n\nEscribe, por ejemplo:\n"
                "<code>2026-05-20 18:00</code>",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')]])
            )
    except Exception:
        logger.exception('Error en callback recurrentes V70: %s', q.data)
        try:
            await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception:
            pass
    raise _ApplicationHandlerStop_v70


def _v70_parse_repeat_text(text: str) -> int:
    raw = str(text or '').strip().lower()
    m = _re_v7.search(r'(?:cada\s*)?(\d+)\s*(m|min|minuto|minutos|h|hora|horas|d|dia|día|dias|días)', raw)
    if not m:
        raise ValueError('No entiendo el intervalo. Ejemplo: cada 20m, cada 1h, cada 2 horas')
    n = int(m.group(1))
    unit = m.group(2)
    if unit.startswith('m'):
        return max(60, n * 60)
    if unit.startswith('h'):
        return max(60, n * 3600)
    return max(60, n * 86400)


async def _v70_recurring_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') not in {'cfg_rec_set_start_v70', 'cfg_rec_set_repeat_v70', 'cfg_rec_set_until_v70'}:
        return
    chat_id = int(pending.get('chat_id') or 0)
    rid = int(pending.get('rid') or 0)
    row = recurring_find(chat_id, rid)
    if not row:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('No encuentro ese recurrente.')
        raise _ApplicationHandlerStop_v70
    if not await is_admin(context, chat_id, update.effective_user.id):
        pop_config_pending(update.effective_user.id)
        await update.message.reply_text('No tienes permisos de admin en ese grupo.')
        raise _ApplicationHandlerStop_v70
    text = plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')
    try:
        kind = pending.get('kind')
        if kind == 'cfg_rec_set_start_v70':
            start = _v70_parse_start_input(text)
            sched = _v70_make_start_interval_schedule(row, start=start)
            _v70_update_row_schedule(row, sched)
            prefix = '✅ Inicio actualizado.'
        elif kind == 'cfg_rec_set_repeat_v70':
            seconds = _v70_parse_repeat_text(text)
            sched = _v70_make_start_interval_schedule(row, repeat_seconds=seconds)
            _v70_update_row_schedule(row, sched)
            prefix = '✅ Repetición actualizada.'
        else:
            until = _v70_parse_until_input(text)
            sched = _v70_make_start_interval_schedule(row, until=until, until_enabled=True)
            _v70_update_row_schedule(row, sched)
            prefix = '✅ Fecha/hora de fin actualizada.'
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html(prefix + '\n\n' + recurring_detail_text(chat_id, rid), reply_markup=recurring_detail_markup(chat_id, rid))
    except ValueError as e:
        await update.message.reply_html(f'❌ {h(str(e))}')
    except Exception:
        logger.exception('Error procesando texto recurrente V70')
        await update.message.reply_html('❌ Error guardando la configuración. Revisa logs.')
    raise _ApplicationHandlerStop_v70


_old_v70_build_application = build_application

def build_application() -> Application:
    app = _old_v70_build_application()
    app.add_handler(CallbackQueryHandler(_v70_recurring_schedule_callback, pattern=r'^cfg\|rec_(start_custom|repeat_menu|repeat_set|repeat_custom|until_toggle|until_custom)\|'), group=-1700000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v70_recurring_pending_text), group=-1700001)
    logger.info('V70 recurrentes: Inicio/Repetir/Hasta por botones cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V71Stop
except Exception:
    _V71Stop = Exception

_V71_PRIVATE_GARBAGE: Dict[int, List[int]] = {}
_V71_AI_REC_DRAFTS: Dict[int, Dict[str, Any]] = {}


def _v71_track_private_message(user_id: int, message_id: Optional[int]) -> None:
    if not message_id:
        return
    bucket = _V71_PRIVATE_GARBAGE.setdefault(int(user_id), [])
    if int(message_id) not in bucket:
        bucket.append(int(message_id))
        if len(bucket) > 80:
            del bucket[:-80]


async def _v71_private_reply_html(update: Update, text: str, **kwargs):
    msg = await update.message.reply_html(text, **kwargs)
    try:
        _v71_track_private_message(update.effective_user.id, msg.message_id)
    except Exception:
        pass
    return msg


async def _v71_cleanup_private_panels(bot, chat_id: int, user_id: int, keep_message_id: Optional[int] = None) -> None:
    ids = list(dict.fromkeys(_V71_PRIVATE_GARBAGE.get(int(user_id), [])))
    if keep_message_id:
        ids = [mid for mid in ids if int(mid) != int(keep_message_id)]
    for mid in sorted(ids, reverse=True):
        try:
            await bot.delete_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass
    _V71_PRIVATE_GARBAGE[int(user_id)] = []


def _v71_ai_commands_for_chat(chat_id: int) -> Dict[str, Any]:
    try:
        return _ai_custom_commands(chat_id)
    except Exception:
        raw = cfg_value(chat_id, 'ai_custom_commands', {})
        return raw if isinstance(raw, dict) else {}


def _v71_find_ai_command(command: str, preferred_chat_id: Optional[int] = None) -> Tuple[Optional[int], Optional[Dict[str, Any]]]:
    cmd = _ai_clean_command_name(command) if '_ai_clean_command_name' in globals() else str(command).lstrip('/').lower()
    if preferred_chat_id and preferred_chat_id in STATE_CACHE:
        data = _v71_ai_commands_for_chat(int(preferred_chat_id)).get(cmd)
        if isinstance(data, dict):
            return int(preferred_chat_id), data
    for cid in list(STATE_CACHE.keys()):
        data = _v71_ai_commands_for_chat(int(cid)).get(cmd)
        if isinstance(data, dict):
            return int(cid), data
    return None, None


def _v71_format_ai_custom_prompt(data: Dict[str, Any], user_text: str, user_name: str = '') -> str:
    prompt = str(data.get('prompt') or data.get('instructions') or '').strip()
    query = str(user_text or '').strip()
    if '{query}' in prompt or '{consulta}' in prompt or '{texto}' in prompt:
        return prompt.replace('{query}', query).replace('{consulta}', query).replace('{texto}', query)
    return f"{prompt}\n\nConsulta del usuario: {query}" if prompt else query


async def _v71_ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    text = (update.message.text or '').strip()
    if not text.startswith('/'):
        return
    first, *rest = text.split(maxsplit=1)
    cmd = (_ai_clean_command_name(first) if '_ai_clean_command_name' in globals() else first.lstrip('/').lower())

    reserved = {'start','help','ajustes','plan','djplan','ping','preguntita','retito','examen','privadito','impostor','impostorstop','cerebrito','planecito','tiempo','iatest'}
    if cmd in reserved:
        return
    preferred = int(update.effective_chat.id) if update.effective_chat and int(update.effective_chat.id) in STATE_CACHE else None
    chat_id, data = _v71_find_ai_command(cmd, preferred)
    if not chat_id or not data:
        return
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await update.message.reply_text('🧠 Cerebrito está desactivado en ese grupo.')
        raise _V71Stop
    arg = rest[0].strip() if rest else ''
    if not arg:


        set_config_pending(update.effective_user.id, {'kind': 'ai_custom_command_query_v71', 'chat_id': int(chat_id), 'cmd': cmd})
        msg = await update.message.reply_html(
            'Pulsa responder y escribe el dato que falta.',
            reply_markup=ForceReply(selective=True),
        )
        if update.effective_chat and update.effective_chat.type == 'private':
            _v71_track_private_message(update.effective_user.id, msg.message_id)
        raise _V71Stop
    wait = await update.message.reply_text('🧠 Pensando…')
    try:
        prompt = _v71_format_ai_custom_prompt(data, arg, display_name(update.effective_user))
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        try:
            await wait.edit_text(ans[:3900])
        except Exception:
            await update.message.reply_text(ans[:3900])
        _ai_usage_inc(int(chat_id), int(update.effective_user.id), 'planecito')
    except Exception as e:
        logger.exception('Error comando IA personalizado V71 /%s', cmd)
        try:
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
        except Exception:
            await update.message.reply_text(f'❌ Error IA: {type(e).__name__}')
    raise _V71Stop


async def _v71_pending_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending:
        return
    kind = pending.get('kind')
    text = plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')
    raw = (text or '').strip()
    uid = int(update.effective_user.id)

    if kind == 'ai_custom_command_query_v71':
        chat_id = int(pending.get('chat_id') or 0)
        cmd = str(pending.get('cmd') or '')
        data = _v71_ai_commands_for_chat(chat_id).get(cmd)
        pop_config_pending(uid)
        if not isinstance(data, dict):
            await _v71_private_reply_html(update, 'No encuentro ese comando IA.')
            raise _V71Stop
        wait = await update.message.reply_text('🧠 Pensando…')
        if update.effective_chat and update.effective_chat.type == 'private':
            _v71_track_private_message(uid, wait.message_id)
        try:
            prompt = _v71_format_ai_custom_prompt(data, raw, display_name(update.effective_user))
            ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=int(cfg_value(chat_id, 'ai_custom_command_tokens', 500) or 500))
            await wait.edit_text(ans[:3900])
        except Exception as e:
            logger.exception('Error respuesta guiada IA V71')
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
        raise _V71Stop

    if kind == 'ai_custom_command_v71':
        chat_id = int(pending.get('chat_id') or 0)
        parts = [p.strip() for p in raw.split('|')]
        if len(parts) < 2:
            await _v71_private_reply_html(update, 'Formato: <code>comando | mensaje que pregunta | prompt</code>\nTambién acepto: <code>comando | prompt</code>')
            raise _V71Stop
        if len(parts) == 2:
            name_raw, prompt = parts[0], parts[1]
            ask = '¿Qué quieres consultar?'
        else:
            name_raw, ask, prompt = parts[0], parts[1], ' | '.join(parts[2:])
        name = _ai_clean_command_name(name_raw) if '_ai_clean_command_name' in globals() else name_raw.lstrip('/').lower()
        if not name:
            await _v71_private_reply_html(update, 'Nombre de comando inválido.')
            raise _V71Stop
        cmds = _v71_ai_commands_for_chat(chat_id)
        cmds[name] = {'prompt': prompt[:2000], 'ask': ask[:500], 'created_by': uid, 'created_ts': int(time.time())}
        cfg_set(chat_id, 'ai_custom_commands', cmds)
        pop_config_pending(uid)
        await _v71_private_reply_html(update, f'✅ Comando IA creado: <code>/{h(name)}</code>\n\nSi lo usan sin texto, preguntará:\n<blockquote>{h(ask[:500])}</blockquote>')
        raise _V71Stop


    if kind in {'ai_rec_name_v71','ai_rec_schedule_v71','ai_rec_prompt_v71'}:
        draft = dict(pending.get('draft') or {})
        chat_id = int(pending.get('chat_id') or draft.get('chat_id') or 0)
        if kind == 'ai_rec_name_v71':
            draft = {'chat_id': chat_id, 'name': raw[:60] or 'Recurrente IA'}
            set_config_pending(uid, {'kind': 'ai_rec_schedule_v71', 'chat_id': chat_id, 'draft': draft})
            await _v71_private_reply_html(update, '🕘 Ahora escribe el horario. Ejemplos:\n<code>diario 10:00</code>\n<code>lunes 10:00</code>\n<code>cada 2h</code>')
            raise _V71Stop
        if kind == 'ai_rec_schedule_v71':
            try:
                sched = parse_recurring_when(raw)
            except Exception as e:
                await _v71_private_reply_html(update, f'❌ Horario no válido: {h(str(e))}')
                raise _V71Stop
            draft['schedule'] = sched
            set_config_pending(uid, {'kind': 'ai_rec_prompt_v71', 'chat_id': chat_id, 'draft': draft})
            await _v71_private_reply_html(update, '🧠 Ahora escribe el prompt que usará la IA cada vez que se publique.\n\nEjemplo:\n<code>Crea un mensaje de buenos días juvenil, corto y divertido para el grupo.</code>')
            raise _V71Stop
        if kind == 'ai_rec_prompt_v71':
            draft['prompt'] = raw[:2500]
            set_config_pending(uid, {'kind': 'ai_rec_image_v71', 'chat_id': chat_id, 'draft': draft})
            kb = InlineKeyboardMarkup([[InlineKeyboardButton('🖼 Con imagen', callback_data=f"cfg|ai_rec_img|{chat_id}|1"), InlineKeyboardButton('📝 Solo texto', callback_data=f"cfg|ai_rec_img|{chat_id}|0")]])
            await _v71_private_reply_html(update, '¿Quieres acompañarlo con imagen/cartel generado localmente?', reply_markup=kb)
            raise _V71Stop


    if kind == 'cfg_rec_add_button_v71':
        chat_id = int(pending.get('chat_id') or 0); rid = int(pending.get('rid') or 0)
        row = recurring_find(chat_id, rid)
        if not row:
            pop_config_pending(uid); await _v71_private_reply_html(update, 'No encuentro ese recurrente.'); raise _V71Stop
        buttons = recurring_parse_buttons_private(raw)
        if not buttons:
            await _v71_private_reply_html(update, 'No detecté botón válido. Usa <code>Texto=https://...</code> o <code>Texto=cmd:comando</code>.')
            raise _V71Stop
        existing = row.get('buttons') if isinstance(row.get('buttons'), list) else []
        row['buttons'] = (existing + buttons)[:24]
        save_all_states(); pop_config_pending(uid)
        await _v71_private_reply_html(update, '✅ Botón añadido.\n\n' + recurring_detail_text(chat_id, rid), reply_markup=recurring_detail_markup(chat_id, rid))
        raise _V71Stop


_old_v71_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v71_admin_private_block_markup(chat_id, block, page)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    if block == 'ai':
        extra = [
            [InlineKeyboardButton('➕ Comando IA guiado', callback_data=f'cfg|ai_cmd_new_guided|{chat_id}'), InlineKeyboardButton('🔁 Recurrente IA guiado', callback_data=f'cfg|ai_rec_new|{chat_id}')],
        ]

        if rows and any('home' in str(getattr(b, 'callback_data', '')) for b in rows[-1]):
            rows = rows[:-1] + extra + rows[-1:]
        else:
            rows.extend(extra)
    return InlineKeyboardMarkup(rows)


def _v71_buttons_text(row: Dict[str, Any]) -> str:
    buttons = row.get('buttons') if isinstance(row.get('buttons'), list) else []
    if not buttons:
        return 'No hay botones configurados.'
    lines = []
    for i,b in enumerate(buttons,1):
        if not isinstance(b, dict): continue
        label = str(b.get('text') or '')
        target = str(b.get('url') or b.get('cmd') or '')
        lines.append(f'{i}. <b>{h(label)}</b> → <code>{h(target)}</code>')
    return '\n'.join(lines) or 'No hay botones configurados.'


def _v71_buttons_menu_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    row = recurring_find(chat_id, rid) or {}
    buttons = row.get('buttons') if isinstance(row.get('buttons'), list) else []
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('➕ Añadir botón', callback_data=f'cfg|rec_button_add|{chat_id}|{rid}'), InlineKeyboardButton('🧹 Vaciar botones', callback_data=f'cfg|rec_button_clear|{chat_id}|{rid}')]]
    for idx,b in enumerate(buttons[:20]):
        label = str(b.get('text') if isinstance(b, dict) else f'Botón {idx+1}')[:24]
        rows.append([InlineKeyboardButton(f'🗑 {idx+1}. {label}', callback_data=f'cfg|rec_button_del|{chat_id}|{rid}|{idx}')])
    rows.append([InlineKeyboardButton('🔙 Volver al recurrente', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)


_old_v71_recurring_detail_markup = recurring_detail_markup

def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    markup = _old_v71_recurring_detail_markup(chat_id, rid)
    rows = []
    for row in getattr(markup, 'inline_keyboard', []):
        newrow = []
        for btn in row:
            cd = getattr(btn, 'callback_data', '')
            if cd and 'rec_edit_buttons' in cd:
                newrow.append(InlineKeyboardButton(getattr(btn, 'text', '⌨️ Botones'), callback_data=f'cfg|rec_buttons_menu|{chat_id}|{rid}'))
            else:
                newrow.append(btn)
        rows.append(newrow)
    return InlineKeyboardMarkup(rows)


async def _v71_recurring_ai_and_buttons_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    try:
        if action == 'ai_cmd_new_guided':
            chat_id = int(parts[2])
            set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_v71', 'chat_id': chat_id})
            await q.answer()
            msg = await q.message.reply_html('➕ <b>Nuevo comando IA guiado</b>\n\nFormato recomendado:\n<code>tiempecito | ¿De qué ciudad quieres el tiempo? | Responde con el tiempo actual de {query} en tono claro y breve.</code>\n\nSi usas solo dos partes será:\n<code>comando | prompt</code>')
            _v71_track_private_message(q.from_user.id, msg.message_id)
            raise _V71Stop
        if action == 'ai_rec_new':
            chat_id = int(parts[2])
            set_config_pending(q.from_user.id, {'kind': 'ai_rec_name_v71', 'chat_id': chat_id})
            await q.answer()
            msg = await q.message.reply_html('🔁 <b>Nuevo recurrente IA</b>\n\nEscribe el nombre interno. Ejemplo:\n<code>Buenos días IA</code>')
            _v71_track_private_message(q.from_user.id, msg.message_id)
            raise _V71Stop
        if action == 'ai_rec_img':
            chat_id = int(parts[2]); use_img = str(parts[3]) == '1'
            pending = get_config_pending(q.from_user.id) or {}
            draft = dict(pending.get('draft') or {})
            if pending.get('kind') != 'ai_rec_image_v71' or int(pending.get('chat_id') or 0) != chat_id:
                await q.answer('No hay creación IA pendiente.', show_alert=True); raise _V71Stop
            sched = draft.get('schedule') if isinstance(draft.get('schedule'), dict) else {'type':'daily','time':'10:00','label':'diario 10:00'}
            rid = recurring_next_id(chat_id)
            row = {'id': rid, 'name': draft.get('name') or f'Recurrente IA {rid}', 'text': '🧠 Generando mensaje con IA…', 'enabled': True, 'pin': False, 'buttons': [], 'media': None, 'schedule': sched, 'schedule_label': sched.get('label',''), 'last_sent_ts': 0, 'ai_prompt': draft.get('prompt') or '', 'ai_image': bool(use_img)}
            recurring_list(chat_id).append(row)
            save_all_states(); pop_config_pending(q.from_user.id)
            await q.answer('Recurrente IA creado ✅')
            await q.message.reply_html('✅ Recurrente IA creado.\n\n' + recurring_detail_text(chat_id, rid), reply_markup=recurring_detail_markup(chat_id, rid))
            raise _V71Stop
        if action == 'rec_buttons_menu':
            chat_id = int(parts[2]); rid = int(parts[3])
            row = recurring_find(chat_id, rid)
            if not row:
                await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V71Stop
            await q.answer()
            await q.edit_message_text('⌨️ <b>Botones del recurrente</b>\n\n' + _v71_buttons_text(row), parse_mode=ParseMode.HTML, reply_markup=_v71_buttons_menu_markup(chat_id, rid))
            raise _V71Stop
        if action == 'rec_button_add':
            chat_id = int(parts[2]); rid = int(parts[3])
            set_config_pending(q.from_user.id, {'kind': 'cfg_rec_add_button_v71', 'chat_id': chat_id, 'rid': rid})
            await q.answer()
            await q.message.reply_html('➕ <b>Añadir botón</b>\n\nEnvíame uno o varios botones. No borra los existentes.\n\nEjemplos:\n<code>🎯 Preguntita=cmd:preguntita</code>\n<code>📜 Normas=https://t.me/...</code>')
            raise _V71Stop
        if action == 'rec_button_clear':
            chat_id = int(parts[2]); rid = int(parts[3])
            row = recurring_find(chat_id, rid)
            if row:
                row['buttons'] = []; save_all_states()
            await q.answer('Botones borrados ✅')
            await q.edit_message_text('⌨️ <b>Botones del recurrente</b>\n\nNo hay botones configurados.', parse_mode=ParseMode.HTML, reply_markup=_v71_buttons_menu_markup(chat_id, rid))
            raise _V71Stop
        if action == 'rec_button_del':
            chat_id = int(parts[2]); rid = int(parts[3]); idx = int(parts[4])
            row = recurring_find(chat_id, rid)
            if row and isinstance(row.get('buttons'), list) and 0 <= idx < len(row['buttons']):
                row['buttons'].pop(idx); save_all_states()
            await q.answer('Botón eliminado ✅')
            await q.edit_message_text('⌨️ <b>Botones del recurrente</b>\n\n' + _v71_buttons_text(row or {}), parse_mode=ParseMode.HTML, reply_markup=_v71_buttons_menu_markup(chat_id, rid))
            raise _V71Stop
    except _V71Stop:
        raise
    except Exception:
        logger.exception('Error callback V71 %s', data)
        try:
            await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V71Stop


_old_v71_send_recurring_message = send_recurring_message

async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    if isinstance(row, dict) and str(row.get('ai_prompt') or '').strip():
        prompt = str(row.get('ai_prompt') or '').strip()
        try:
            generated = await _ai_openai_response(chat_id, prompt, max_output_tokens=220)
        except Exception:
            logger.exception('No se pudo generar recurrente IA')
            generated = '🧠 No pude generar el mensaje IA ahora.'

        temp = dict(row)
        temp['text'] = generated
        if bool(row.get('ai_image')) and '_ai_generate_greeting_image' in globals():
            try:
                img = _ai_generate_greeting_image('✨ EL PLAN', generated[:80])
                if img:
                    msg = await context.bot.send_photo(chat_id, photo=img, caption=generated[:1024], parse_mode=ParseMode.HTML, reply_markup=recurring_buttons_markup(row, chat_id=chat_id))
                    await register_bot_message(chat_id, msg.message_id)
                    previous_message_id = int(row.get('last_message_id') or 0)
                    row['last_message_id'] = int(msg.message_id); row['last_sent_ts'] = int(time.time())
                    save_all_states()
                    if bool(row.get('delete_previous', True)) and previous_message_id and previous_message_id != int(msg.message_id):
                        await safe_delete(context.bot, chat_id, previous_message_id)
                    return int(msg.message_id)
            except Exception:
                logger.exception('No se pudo enviar imagen de recurrente IA')
        return await _old_v71_send_recurring_message(context, chat_id, temp)
    return await _old_v71_send_recurring_message(context, chat_id, row)


async def _v71_private_close_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.message:
        return
    data = q.data or ''
    if not (data.startswith('cfg|close') or data.startswith('cfgsafe|close') or data.startswith('hot|close') or data.startswith('djpriv|close')):
        return
    if getattr(q.message.chat, 'type', '') == 'private':
        try:
            await q.answer('Cerrando…')
        except Exception:
            pass
        await _v71_cleanup_private_panels(context.bot, q.message.chat_id, q.from_user.id, keep_message_id=None)
        try:
            await q.message.delete()
        except Exception:
            pass
        raise _V71Stop


_old_v71_build_application = build_application

def build_application() -> Application:
    app = _old_v71_build_application()
    app.add_handler(CallbackQueryHandler(_v71_private_close_router, pattern=r'^(cfg|cfgsafe|hot|djpriv)\|close'), group=-2200000)
    app.add_handler(CallbackQueryHandler(_v71_recurring_ai_and_buttons_callback, pattern=r'^cfg\|(ai_cmd_new_guided|ai_rec_new|ai_rec_img|rec_buttons_menu|rec_button_add|rec_button_clear|rec_button_del)\|'), group=-2199000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v71_pending_text_handler), group=-2198000)
    app.add_handler(MessageHandler(filters.COMMAND, _v71_ai_custom_command_handler), group=-2197000)
    logger.info('V71 IA guiada, recurrentes IA y botones acumulables cargado')
    return app


DJ_SESSION_TIMER_TASKS: Dict[int, asyncio.Task] = {}

try:
    from telegram.ext import ApplicationHandlerStop as _V75Stop
except Exception:
    _V75Stop = Exception


def _v75_cfg(chat_id: int) -> Dict[str, Any]:
    return get_state(chat_id).admin_config


def _v75_session_mode(chat_id: int) -> str:
    return str(_v75_cfg(chat_id).get('dj_session_mode') or '').lower()


def _v75_set_mode(chat_id: int, mode: str) -> None:
    _v75_cfg(chat_id)['dj_session_mode'] = mode
    save_all_states()


def _v75_timer_label(chat_id: int) -> str:
    import time as _time
    end = int(_v75_cfg(chat_id).get('dj_session_ends_at') or 0)
    if not end:
        return 'sin temporizador'
    left = max(0, end - int(_time.time()))
    if left <= 0:
        return 'finalizando'
    h0, rem = divmod(left, 3600)
    m0, _s = divmod(rem, 60)
    if h0:
        return f'{h0}h {m0:02d}m'
    return f'{m0}m'


def _v75_current_next(chat_id: int) -> tuple[str, str]:
    state = get_state(chat_id)
    now = 'Nada sonando'
    nxt = 'Nada en cola'
    try:
        if state.now_playing:
            now = shorten_title(Track(**state.now_playing).title, 42)
        if state.queue:
            nxt = shorten_title(Track(**state.queue[0]).title, 42)
    except Exception:
        pass
    return now, nxt


async def _v75_close_session_later(bot, chat_id: int, ends_at: int, mode: str) -> None:
    import time as _time
    try:
        await asyncio.sleep(max(1, int(ends_at) - int(_time.time())))
        cfg = _v75_cfg(chat_id)
        if int(cfg.get('dj_session_ends_at') or 0) != int(ends_at):
            return
        if str(cfg.get('dj_session_mode') or '') != mode:
            return
        await close_dj_session(bot, chat_id)
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error cerrando sesión DJ por temporizador V75')


def _v75_cancel_timer(chat_id: int) -> None:
    task = DJ_SESSION_TIMER_TASKS.pop(int(chat_id), None)
    if task and not task.done():
        task.cancel()
    _v75_cfg(chat_id)['dj_session_ends_at'] = 0
    save_all_states()


def _v75_set_timer(bot, chat_id: int, hours: int, mode: str) -> None:
    import time as _time
    _v75_cancel_timer(chat_id)
    ends_at = int(_time.time()) + int(hours) * 3600
    cfg = _v75_cfg(chat_id)
    cfg['dj_session_ends_at'] = ends_at
    cfg['dj_session_timer_hours'] = int(hours)
    save_all_states()
    DJ_SESSION_TIMER_TASKS[int(chat_id)] = asyncio.create_task(_v75_close_session_later(bot, chat_id, ends_at, mode))


def main_menu_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎧 MODO DJ FÁCIL', callback_data='dj_easy_menu')],
        [InlineKeyboardButton('🎛 MODO DJ-PRO', callback_data='menu_panel')],
    ])


_old_v75_panel_text = panel_text
def panel_text(state: ChatState) -> str:
    sync_panel_override_expiry(state)

    chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), 0)
    mode = _v75_session_mode(chat_id) if chat_id else ''
    status = '🛜 ON' if state.live_enabled else '🛑 OFF'
    dj = state.assigned_dj_name or 'Sin asignar'
    if state.now_playing:
        song_label = '💽'
        song_value = shorten_title(Track(**state.now_playing).title, 28)
    elif state.queue:
        song_label = '⏭️'
        song_value = shorten_title(Track(**state.queue[0]).title, 28)
    else:
        song_label = '❌'
        song_value = 'Nada sonando'
    title = '🎧 DJ FÁCIL' if mode == 'easy' else '🎛 DJ-PRO'
    timer = f' | ⏱ {_v75_timer_label(chat_id)}' if chat_id and int(_v75_cfg(chat_id).get('dj_session_ends_at') or 0) else ''
    return f'<b>{title}</b> 🔊 DIRECTO {status} <b>{song_label}</b> <i>{h(song_value)}</i> | 🎧 DJ: <b>{h(dj)}</b>{timer}'


def _v75_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    mode = _v75_session_mode(chat_id)
    if mode == 'easy':
        main_button = InlineKeyboardButton('🎧 DJ Fácil', callback_data='dj_easy_menu')
    else:
        main_button = InlineKeyboardButton('🎛 Mesa DJ-PRO', callback_data='menu_panel')
    return InlineKeyboardMarkup([[main_button, InlineKeyboardButton('❤️ Me gusta', callback_data='djlike|current')]])


_old_v75_ensure_panel = ensure_panel
async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v75_panel_markup(chat_id)
        old_panel_id = state.panel_message_id
        if old_panel_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=old_panel_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
                save_all_states()
                return
            except BadRequest as e:
                if 'message is not modified' in str(e).lower():
                    return
                if 'message to edit not found' in str(e).lower():
                    state.panel_message_id = None
                    save_all_states()
            except Exception:
                logger.exception('No se pudo editar panel V75; se recrea')
        if old_panel_id:
            try:
                await bot.unpin_chat_message(chat_id=chat_id, message_id=old_panel_id)
            except Exception:
                pass
            try:
                await safe_delete(bot, chat_id, old_panel_id)
            except Exception:
                pass
            state.panel_message_id = None
            save_all_states()
        msg = await bot.send_message(chat_id=chat_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
        state.panel_message_id = msg.message_id
        save_all_states()
        await register_bot_message(chat_id, msg.message_id)
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            logger.exception('No se pudo fijar panel V75')
        await enforce_single_core_messages(bot, chat_id)


_old_v75_ensure_control_panel = ensure_control_panel
async def ensure_control_panel(bot, chat_id: int) -> None:
    if _v75_session_mode(chat_id) == 'easy':
        return
    return await _old_v75_ensure_control_panel(bot, chat_id)


