async def _v75_open_pro(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    state = get_state(chat_id)
    if not await is_controller(context, chat_id, user_id):
        await query.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V75Stop
    await query.answer()
    state.dj_mode = True
    state.assigned_dj_id = user_id if state.assigned_dj_id is None else state.assigned_dj_id
    state.assigned_dj_name = display_name(update.effective_user) if not state.assigned_dj_name else state.assigned_dj_name
    _v75_set_mode(chat_id, 'pro')
    save_all_states()
    try:
        await query.message.delete()
    except Exception:
        pass
    await cleanup_track_controls(context.bot, chat_id)
    await ensure_panel(context.bot, chat_id)
    await _old_v75_ensure_control_panel(context.bot, chat_id)
    await cleanup_bot_messages_keep_core(context.bot, chat_id)
    raise _V75Stop


async def _v75_dj_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if not query or not update.effective_chat or not update.effective_user:
        return
    data = query.data or ''
    if data == 'menu_panel':
        await _v75_open_pro(update, context)
    if data not in {'dj_easy_menu','dj_easy_start','dj_easy_next','dj_easy_close','dj_easy_info'} and not data.startswith('dj_timer|'):
        return
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    state = get_state(chat_id)

    if data.startswith('dj_timer|'):
        _, mode, hours_s = data.split('|')
        try:
            hours = int(hours_s)
        except Exception:
            hours = 0

        if mode == 'pro' and not await is_controller(context, chat_id, user_id):
            await query.answer('No estás autorizado para cambiar el temporizador DJ-PRO.', show_alert=True)
            raise _V75Stop
        if mode == 'easy' and not (state.assigned_dj_id == user_id or await is_controller(context, chat_id, user_id)):
            await query.answer('No estás autorizado para cambiar el temporizador DJ Fácil.', show_alert=True)
            raise _V75Stop
        if hours <= 0:
            _v75_cancel_timer(chat_id)
            await query.answer('Temporizador quitado ✅', show_alert=True)
        else:
            _v75_set_timer(context.bot, chat_id, hours, _v75_session_mode(chat_id) or mode)
            await query.answer(f'DJ se cerrará en {hours}h ✅', show_alert=True)
        await ensure_panel(context.bot, chat_id)
        if _v75_session_mode(chat_id) == 'easy':
            await _v75_show_easy_panel(query, context, chat_id)
        else:
            await _old_v75_ensure_control_panel(context.bot, chat_id)
        raise _V75Stop


    if data == 'dj_easy_menu':
        if state.dj_mode and _v75_session_mode(chat_id) == 'easy' and not (state.assigned_dj_id == user_id or await is_controller(context, chat_id, user_id)):
            await query.answer('No estás autorizado para controlar este DJ Fácil.', show_alert=True)
            raise _V75Stop
        await query.answer()
        await _v75_show_easy_panel(query, context, chat_id)
        raise _V75Stop

    if data == 'dj_easy_info':
        await query.answer('Instrucciones')
        await query.edit_message_text(
            '<b>ℹ️ Abrir videochat manualmente</b>\n\n'
            '1. Pulsa arriba en el <b>nombre del grupo</b>.\n'
            '2. Entra en <b>Videochat</b> o <b>Directo</b>.\n'
            '3. Vuelve al bot y deja DJ Fácil funcionando.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Volver DJ Fácil', callback_data='dj_easy_menu')]])
        )
        raise _V75Stop

    if data == 'dj_easy_start':

        await query.answer('Activando DJ Fácil…')
        state.dj_mode = True
        state.assigned_dj_id = user_id
        state.assigned_dj_name = display_name(update.effective_user)
        _v75_set_mode(chat_id, 'easy')
        if state.library:
            items = [dict(x) for x in state.library]
            try:
                import random as _r
                _r.shuffle(items)
            except Exception:
                pass
            state.queue = dedupe_track_items(items)
        state.dj_shuffle_enabled = True
        state.auto_track_enabled = True
        state.auto_sig_seconds = 0
        save_all_states()
        try:
            await VOICE.ensure_videochat_started(chat_id)
        except Exception:
            logger.exception('No se pudo abrir videochat automáticamente')
        if not state.now_playing and state.queue:
            await simulate_panel_next(chat_id, reason='dj_easy_start')
        await ensure_panel(context.bot, chat_id)
        await _v75_show_easy_panel(query, context, chat_id)
        await query.answer('DJ Fácil activado ✅', show_alert=True)
        raise _V75Stop

    if data == 'dj_easy_next':
        if not (state.assigned_dj_id == user_id or await is_controller(context, chat_id, user_id)):
            await query.answer('No estás autorizado para pasar canción.', show_alert=True)
            raise _V75Stop
        if not state.queue:
            await query.answer('No hay canciones en cola.', show_alert=True)
            raise _V75Stop
        await simulate_panel_next(chat_id, reason='dj_easy_next')
        await ensure_panel(context.bot, chat_id)
        await _v75_show_easy_panel(query, context, chat_id)
        raise _V75Stop

    if data == 'dj_easy_close':
        if not (state.assigned_dj_id == user_id or await is_controller(context, chat_id, user_id)):
            await query.answer('No estás autorizado para cerrar DJ Fácil.', show_alert=True)
            raise _V75Stop
        await query.answer('Cerrando DJ Fácil…')
        _v75_cancel_timer(chat_id)
        await close_dj_session(context.bot, chat_id)
        try:
            await query.message.delete()
        except Exception:
            pass
        raise _V75Stop


_old_v75_close_dj_session = close_dj_session
async def close_dj_session(bot, chat_id: int) -> None:
    _v75_cancel_timer(chat_id)
    return await _old_v75_close_dj_session(bot, chat_id)


