try:
    from telegram.ext import ApplicationHandlerStop as _V77Stop
except Exception:
    _V77Stop = Exception

_DJ_ROLES_V77 = {
    'owner': '👑 Dueño/ADMIN_IDS',
    'admins': '🛡 Admins Telegram',
    'admin_ids': '🆔 IDs Admin',
    'members': '👥 Todos los miembros',
    'manual': '👤 Solo manuales',
}


def _v77_role_label(role: str) -> str:
    return _DJ_ROLES_V77.get(str(role or ''), str(role or 'No configurado'))


def _v77_ensure_private_blocks() -> None:
    """Quita owner_alerts de ajustes e inserta Permisos DJ antes de Listados."""
    global ADMIN_PRIVATE_BLOCKS, ADMIN_PRIVATE_BLOCK_IDS
    cleaned = []
    seen = set()
    for key, label in list(ADMIN_PRIVATE_BLOCKS):
        if key == 'owner_alerts':
            continue
        if key == 'dj_permissions':
            continue
        if key in seen:
            continue
        cleaned.append((key, label))
        seen.add(key)
    insert_at = next((i for i, (k, _l) in enumerate(cleaned) if k == 'lists'), len(cleaned))
    cleaned.insert(insert_at, ('dj_permissions', '🎛 Permisos DJ'))
    ADMIN_PRIVATE_BLOCKS = cleaned
    ADMIN_PRIVATE_BLOCK_IDS = {k for k, _l in ADMIN_PRIVATE_BLOCKS}


_v77_ensure_private_blocks()


def _v77_manual_ids(chat_id: int, mode: str) -> set[int]:
    vals = cfg_value(chat_id, f'dj_{mode}_manual_ids', []) or []
    out = set()
    if isinstance(vals, list):
        for v in vals:
            try:
                out.add(int(v))
            except Exception:
                pass
    return out


def _v77_manual_usernames(chat_id: int, mode: str) -> set[str]:
    vals = cfg_value(chat_id, f'dj_{mode}_manual_usernames', []) or []
    out = set()
    if isinstance(vals, list):
        for v in vals:
            s = str(v or '').strip().lower().lstrip('@')
            if s:
                out.add(s)
    return out


def _v77_user_id(user) -> int:
    try:
        return int(getattr(user, 'id', 0) or 0)
    except Exception:
        return 0


def _v77_username(user) -> str:
    return str(getattr(user, 'username', '') or '').strip().lower().lstrip('@')


async def _v77_dj_allowed(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, mode: str) -> bool:
    """mode: easy o pro. ADMIN_IDS siempre pueden."""
    uid = _v77_user_id(user)
    username = _v77_username(user)
    if uid in ADMIN_IDS:
        return True
    if uid in _v77_manual_ids(chat_id, mode):
        return True
    if username and username in _v77_manual_usernames(chat_id, mode):
        return True
    role = str(cfg_value(chat_id, f'dj_{mode}_role', 'admins' if mode == 'pro' else 'members') or '').lower()
    if role in ('owner', 'admin_ids'):
        return uid in ADMIN_IDS
    if role == 'manual':
        return False
    if role == 'members':
        return True
    if role == 'admins':
        try:
            member = await context.bot.get_chat_member(chat_id, uid)
            return member.status in ('administrator', 'creator')
        except Exception:
            return False
    return False


_old_v77_is_controller = is_controller
async def is_controller(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> bool:
    """La mesa DJ-PRO usa el permiso pro si está configurado; si no, mantiene comportamiento viejo."""
    if cfg_value(chat_id, 'dj_pro_role', None) is not None:
        class _U:
            id = int(user_id)
            username = ''
        return await _v77_dj_allowed(context, chat_id, _U(), 'pro')
    return await _old_v77_is_controller(context, chat_id, user_id)


def _v77_dj_perm_text(chat_id: int) -> str:
    title = get_chat_title(chat_id) if 'get_chat_title' in globals() else str(chat_id)
    easy_role = str(cfg_value(chat_id, 'dj_easy_role', 'members') or 'members')
    pro_role = str(cfg_value(chat_id, 'dj_pro_role', 'admins') or 'admins')
    easy_ids = sorted(_v77_manual_ids(chat_id, 'easy'))
    pro_ids = sorted(_v77_manual_ids(chat_id, 'pro'))
    easy_users = sorted(_v77_manual_usernames(chat_id, 'easy'))
    pro_users = sorted(_v77_manual_usernames(chat_id, 'pro'))
    lines = [
        '<b>🎛 Permisos DJ</b>',
        f'Grupo: <b>{h(title)}</b>',
        '',
        f'🎧 MODO DJ FÁCIL: <b>{h(_v77_role_label(easy_role))}</b>',
        f'🎛 MODO DJ-PRO: <b>{h(_v77_role_label(pro_role))}</b>',
        '',
        '<b>Usuarios manuales DJ Fácil:</b>',
        ', '.join([str(x) for x in easy_ids] + [f'@{h(x)}' for x in easy_users]) or '<i>Ninguno</i>',
        '',
        '<b>Usuarios manuales DJ-PRO:</b>',
        ', '.join([str(x) for x in pro_ids] + [f'@{h(x)}' for x in pro_users]) or '<i>Ninguno</i>',
        '',
        '<i>Son permisos independientes. Puedes dar DJ Fácil a miembros y dejar DJ-PRO solo para admins/manuales.</i>',
    ]
    return '\n'.join(lines)


def _v77_dj_perm_markup(chat_id: int) -> InlineKeyboardMarkup:
    roles = [('owner','👑 Dueño'), ('admins','🛡 Admins'), ('admin_ids','🆔 IDs'), ('members','👥 Miembros'), ('manual','👤 Manual')]
    rows: List[List[InlineKeyboardButton]] = []
    rows.append([InlineKeyboardButton('🎧 MODO DJ FÁCIL', callback_data=f'cfg|noop|{chat_id}|dj_permissions')])
    rows.append([InlineKeyboardButton(label, callback_data=f'cfg|djperm_role|{chat_id}|easy|{role}') for role, label in roles[:3]])
    rows.append([InlineKeyboardButton(label, callback_data=f'cfg|djperm_role|{chat_id}|easy|{role}') for role, label in roles[3:]])
    rows.append([InlineKeyboardButton('➕ Usuario fácil', callback_data=f'cfg|djperm_add|{chat_id}|easy'), InlineKeyboardButton('🧹 Vaciar fácil', callback_data=f'cfg|djperm_clear|{chat_id}|easy')])
    rows.append([InlineKeyboardButton('🎛 MODO DJ-PRO', callback_data=f'cfg|noop|{chat_id}|dj_permissions')])
    rows.append([InlineKeyboardButton(label, callback_data=f'cfg|djperm_role|{chat_id}|pro|{role}') for role, label in roles[:3]])
    rows.append([InlineKeyboardButton(label, callback_data=f'cfg|djperm_role|{chat_id}|pro|{role}') for role, label in roles[3:]])
    rows.append([InlineKeyboardButton('➕ Usuario PRO', callback_data=f'cfg|djperm_add|{chat_id}|pro'), InlineKeyboardButton('🧹 Vaciar PRO', callback_data=f'cfg|djperm_clear|{chat_id}|pro')])
    rows.append([InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


