async def _v77_render_block(q, chat_id: int, block: str) -> None:
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, block), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, block))
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        await q.message.reply_html(admin_private_block_text(chat_id, block), reply_markup=admin_private_block_markup(chat_id, block))
    except Exception:
        await q.message.reply_html(admin_private_block_text(chat_id, block), reply_markup=admin_private_block_markup(chat_id, block))


async def _v77_djperm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|djperm_'):
        return
    parts = data.split('|')
    action = parts[1]
    try:
        await q.answer()
    except Exception:
        pass
    try:
        chat_id = int(parts[2])
        if action == 'djperm_role':
            mode = parts[3]
            role = parts[4]
            if mode not in ('easy', 'pro') or role not in _DJ_ROLES_V77:
                await q.answer('Opción inválida', show_alert=True)
                raise _V77Stop
            cfg_set(chat_id, f'dj_{mode}_role', role)
            await _v77_render_block(q, chat_id, 'dj_permissions')
            raise _V77Stop
        if action == 'djperm_add':
            mode = parts[3]
            if mode not in ('easy', 'pro'):
                await q.answer('Modo inválido', show_alert=True)
                raise _V77Stop
            set_config_pending(q.from_user.id, {'kind': 'djperm_add_user_v77', 'chat_id': chat_id, 'mode': mode})
            await q.message.reply_html('➕ <b>Añadir usuario a permisos DJ</b>\n\nEnvía un ID numérico o @username.\n\nEjemplos:\n<code>123456789</code>\n<code>@usuario</code>')
            raise _V77Stop
        if action == 'djperm_clear':
            mode = parts[3]
            cfg = admin_cfg(chat_id)
            cfg[f'dj_{mode}_manual_ids'] = []
            cfg[f'dj_{mode}_manual_usernames'] = []
            save_all_states()
            await _v77_render_block(q, chat_id, 'dj_permissions')
            raise _V77Stop
    except _V77Stop:
        raise
    except Exception:
        logger.exception('Error permisos DJ V77: %s', data)
        try:
            await q.answer('Error en permisos DJ. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V77Stop


async def _v77_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'djperm_add_user_v77':
        return
    chat_id = int(pending.get('chat_id') or 0)
    mode = str(pending.get('mode') or 'easy')
    raw = (update.message.text or update.message.caption or '').strip()
    cfg = admin_cfg(chat_id)
    if raw.startswith('@') or (raw and not raw.lstrip('-').isdigit()):
        username = raw.strip().lower().lstrip('@').split()[0]
        arr = cfg.setdefault(f'dj_{mode}_manual_usernames', [])
        if username and username not in arr:
            arr.append(username)
    else:
        try:
            uid = int(raw)
            arr = cfg.setdefault(f'dj_{mode}_manual_ids', [])
            if uid not in arr:
                arr.append(uid)
        except Exception:
            await update.message.reply_html('❌ No entendí el usuario. Envía ID numérico o @username.')
            raise _V77Stop
    pop_config_pending(update.effective_user.id)
    save_all_states()
    await update.message.reply_html('✅ Usuario añadido a permisos DJ. Vuelve al panel de Permisos DJ para verlo.')
    raise _V77Stop


async def _v77_dj_permission_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    chat_id = int(update.effective_chat.id)
    if data == 'menu_panel':
        if not await _v77_dj_allowed(context, chat_id, update.effective_user, 'pro'):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V77Stop
    elif data.startswith('dj_easy_') or data.startswith('dj_timer|easy'):

        state = get_state(chat_id)
        if state.dj_mode and _v75_session_mode(chat_id) == 'easy' and (state.assigned_dj_id == update.effective_user.id or await _v77_dj_allowed(context, chat_id, update.effective_user, 'pro')):
            return
        if not await _v77_dj_allowed(context, chat_id, update.effective_user, 'easy'):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V77Stop


_old_v77_build_application = build_application
def build_application() -> Application:
    _v77_ensure_private_blocks()
    app = _old_v77_build_application()

    app.add_handler(CallbackQueryHandler(_v77_djperm_callback, pattern=r'^cfg\|djperm_'), group=-4000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, _v77_pending_text), group=-3999000)
    app.add_handler(CallbackQueryHandler(_v77_dj_permission_guard, pattern=r'^(menu_panel|dj_easy_|dj_timer\|easy)'), group=-3998000)
    logger.info('V77 ajustes sin alertas privadas + permisos DJ Easy/PRO cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V78Stop
except Exception:
    _V78Stop = Exception


def _v78_active_players(game: Dict[str, Any]) -> List[Dict[str, Any]]:
    try:
        return _imp_active_players(game)
    except Exception:
        return game.get('players', []) if isinstance(game.get('players'), list) else []


def _v78_clues_lines(game: Dict[str, Any], limit: int = 10) -> str:
    clues = game.get('clues') if isinstance(game.get('clues'), list) else []
    if not clues:
        return '<i>Aún no hay pistas.</i>'
    rows = []
    for c in clues[-limit:]:
        if not isinstance(c, dict):
            continue
        name = h(c.get('name') or 'Jugador')
        txt = h(c.get('text') or '')
        rnd = int(c.get('round', game.get('round', 1)) or 1)
        if txt:
            rows.append(f'• <b>R{rnd}</b> · {name}: <i>{txt}</i>')
    return '\n'.join(rows) if rows else '<i>Aún no hay pistas.</i>'


def _v78_vote_counts(game: Dict[str, Any]) -> Dict[int, int]:
    votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
    counts: Dict[int, int] = {}
    for target in votes.values():
        try:
            tid = int(target)
            counts[tid] = counts.get(tid, 0) + 1
        except Exception:
            pass
    return counts


def _v78_vote_status_text(game: Dict[str, Any]) -> str:
    active = _v78_active_players(game)
    active_ids = {int(p.get('id', 0) or 0) for p in active}
    votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
    voted_ids = []
    for k in votes.keys():
        try:
            uid = int(k)
            if uid in active_ids:
                voted_ids.append(uid)
        except Exception:
            pass
    voted_names = []
    for uid in voted_ids:
        p = _imp_player(game, uid) or {'id': uid, 'name': str(uid)}
        voted_names.append(_imp_mention(p))
    counts = _v78_vote_counts(game)
    count_lines = []
    for p in active:
        try:
            uid = int(p.get('id', 0) or 0)
            count_lines.append(f'{_imp_mention(p)}: <b>{counts.get(uid, 0)}</b>')
        except Exception:
            pass
    total = len(voted_ids)
    needed = len(active)
    return (
        '🗳 <b>Votación final</b>\n\n'
        'Elige quién crees que es el impostor.\n\n'
        f'📊 Votos emitidos: <b>{total}/{needed}</b>\n'
        f'👥 Han votado: {", ".join(voted_names) if voted_names else "<i>nadie todavía</i>"}\n\n'
        '<b>Recuento actual:</b>\n'
        f'{" · ".join(count_lines) if count_lines else "<i>sin votos</i>"}'
    )


def _v58_imp_card_text(game: Dict[str, Any]) -> str:
    status = str(game.get('status') or 'lobby')
    players = _v78_active_players(game) if status in ('active', 'voting') else (game.get('players', []) if isinstance(game.get('players'), list) else [])
    ronda = int(game.get('round', 1) or 1)
    current = _imp_current_player(game) if status == 'active' else None
    if status == 'lobby':
        return (
            '🎭 <b>Juego del Impostor</b>\n\n'
            'Todos tendrán una palabra secreta menos una persona.\n'
            'El impostor debe disimular y seguir el hilo 😏\n\n'
            f'👥 Jugadores: <b>{len(players)}</b>\n'
            f'{_v58_imp_players_lines(game)}\n\n'
            'Mínimo 3 jugadores.'
        )
    if status == 'voting':
        return _v78_vote_status_text(game)
    return (
        '🎭 <b>Impostor · Pistas</b>\n'
        f'Ronda <b>{ronda}/3</b> · Activos: <b>{len(players)}</b>\n'
        f'Turno: {_imp_mention(current) if current else "<i>sin turno</i>"}\n\n'
        '<b>🧩 Pistas acumuladas</b>\n'
        f'{_v78_clues_lines(game, limit=10)}'
    )


def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    if status == 'voting':
        return InlineKeyboardMarkup([
            [InlineKeyboardButton('🗳 Votar', callback_data=f'imp|vote_menu|{chat_id}|{gid}')],
            [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')],
        ])
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')]
    ]

    try:
        if not _v61_final_vote_only(chat_id):
            rows.append([InlineKeyboardButton('🗳 Abrir votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    except Exception:
        rows.append([InlineKeyboardButton('🗳 Abrir votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)

    return InlineKeyboardMarkup([
        [InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]
    ])


def _v78_vote_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    counts = _v78_vote_counts(game)
    rows: List[List[InlineKeyboardButton]] = []
    for p in _v78_active_players(game):
        try:
            uid = int(p.get('id', 0) or 0)
            name = str(p.get('name') or uid)
            rows.append([InlineKeyboardButton(f'{name} · {counts.get(uid, 0)} voto(s)', callback_data=f'imp|vote|{chat_id}|{gid}|{uid}')])
        except Exception:
            pass
    rows.append([InlineKeyboardButton('🔙 Volver al juego', callback_data=f'imp|refresh|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


async def _v78_send_finished_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:
    if game.get('v78_finished_sent'):
        return
    game['status'] = 'finished'
    game['v78_finished_sent'] = True
    imp_id = int(game.get('impostor_id', 0) or 0)
    imp = _imp_player(game, imp_id) or {'id': imp_id, 'name': 'Impostor'}
    word = h(game.get('word') or '')
    counts = _v78_vote_counts(game)
    voted_txt = ''
    winner_side = str(game.get('winner_side') or '')
    if counts:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        top = _imp_player(game, top_id) or {'id': top_id, 'name': str(top_id)}
        voted_txt = f'\nEl más votado fue {_imp_mention(top)} con <b>{top_votes}</b> voto(s).'
        if not winner_side:
            winner_side = 'crew' if int(top_id) == imp_id else 'impostor'
    if not winner_side:
        winner_side = 'impostor'
    game['winner_side'] = winner_side
    score_txt = ''
    try:
        score_txt = _imp_score_game(chat_id, game, winner_side)
    except Exception:
        logger.exception('No se pudo puntuar Impostor V78')
    txt = (
        '🎭 <b>Resultado del Impostor</b>\n\n'
        f'La palabra era: <b>{word}</b>\n'
        f'El impostor era: {_imp_mention(imp)} 😈'
        f'{voted_txt}'
    )
    if reason:
        txt += f'\n\n{reason}'
    if score_txt:
        txt += f'\n\n{score_txt}'
    save_all_states()
    try:
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_card_message_id') or game.get('turn_message_id'))
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
    except Exception:
        pass
    await context.bot.send_message(
        chat_id,
        txt,
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🎭 Iniciar otra partida', callback_data=f'imp|new|{chat_id}')]])
    )


async def _imp_finish(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:
    await _v78_send_finished_result(context, chat_id, game, reason)


async def _v78_create_new_game_from_button(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    q = update.callback_query
    uid = int(q.from_user.id) if q else 0

    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active:
        await q.answer('Ya hay una partida activa.', show_alert=True)
        return
    word = secrets.choice(IMPOSTOR_WORDS)
    gid = _imp_next_id(chat_id)
    game = {
        'id': gid,
        'status': 'lobby',
        'word': word,
        'creator_id': uid,
        'created_ts': int(time.time()),
        'players': [{'id': uid, 'name': display_name(q.from_user), 'username': getattr(q.from_user, 'username', '') or ''}],
        'round': 1,
        'turn_idx': 0,
        'votes': {},
        'impostor_id': 0,
        'message_id': 0,
    }
    msg = await context.bot.send_message(chat_id, _imp_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await q.answer('Nueva partida creada 🎭')


_old_impostor_callback_router_v78 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v78(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'new':
            chat_id = int(parts[2])
            await _v78_create_new_game_from_button(update, context, chat_id)
            raise _V78Stop
        if len(parts) < 4:
            return await _old_impostor_callback_router_v78(update, context)
        chat_id = int(parts[2]); gid = int(parts[3])
        game = _imp_find(chat_id, gid)
        if not game:
            return await _old_impostor_callback_router_v78(update, context)
        uid = int(q.from_user.id)
        if action == 'vote_menu':
            if uid not in [int(p.get('id', 0) or 0) for p in _v78_active_players(game)]:
                await q.answer('No estás en la partida.', show_alert=True)
                raise _V78Stop
            game['status'] = 'voting'
            save_all_states()
            await q.answer()
            await q.edit_message_text(_v78_vote_status_text(game), parse_mode=ParseMode.HTML, reply_markup=_v78_vote_markup(chat_id, game))
            raise _V78Stop
        if action == 'vote':
            if len(parts) < 5:
                raise _V78Stop
            if uid not in [int(p.get('id', 0) or 0) for p in _v78_active_players(game)]:
                await q.answer('No estás en la partida.', show_alert=True)
                raise _V78Stop
            target_id = int(parts[4])
            if target_id not in [int(p.get('id', 0) or 0) for p in _v78_active_players(game)]:
                await q.answer('Ese jugador ya no está activo.', show_alert=True)
                raise _V78Stop
            votes = game.setdefault('votes', {})
            votes[str(uid)] = target_id
            game['status'] = 'voting'
            save_all_states()
            active_ids = [int(p.get('id', 0) or 0) for p in _v78_active_players(game)]
            if all(str(x) in votes for x in active_ids):
                await q.answer('Voto registrado. Votación completa ✅')
                await _v78_send_finished_result(context, chat_id, game)
                raise _V78Stop
            await q.answer('Voto registrado ✅')
            await q.edit_message_text(_v78_vote_status_text(game), parse_mode=ParseMode.HTML, reply_markup=_v78_vote_markup(chat_id, game))
            raise _V78Stop
        if action == 'refresh' and str(game.get('status')) == 'voting':
            await q.answer()
            await q.edit_message_text(_v78_vote_status_text(game), parse_mode=ParseMode.HTML, reply_markup=_v78_vote_markup(chat_id, game))
            raise _V78Stop
    except _V78Stop:
        raise
    except Exception:
        logger.exception('Error Impostor V78: %s', data)
        try:
            await q.answer('Error en Impostor. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V78Stop
    return await _old_impostor_callback_router_v78(update, context)


_old_build_application_v78 = build_application
def build_application() -> Application:
    app = _old_build_application_v78()
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-4100000)
    logger.info('V78 Impostor visual/votaciones cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V79Stop
except Exception:
    _V79Stop = Exception

_V79_NORMAL_WORDS = [
    'playa','discoteca','cita','pizza','karaoke','viaje','secreto','fiesta','beso','coqueteo','cine','terraza','hotel','misterio','mensaje','noche',
    'canción','mirada','café','plan','verano','chisme','bar','confesión','brindis','tatuaje','perfume','ascensor','desayuno','after','whatsapp','selfie',
    'risa','botella','cóctel','tren','aeropuerto','maleta','piscina','sofá','domingo','cumpleaños','concierto','amigo','ex','vecino','playlist','señal',
    'playback','taxi','secreto','playa','pulsera','llamada','foto','mensaje','sorpresa','barbacoa','montaña','lluvia','paraguas','helado','gafas',
    'maquillaje','zapatos','camisa','vestido','reloj','llaves','portal','azotea','terraza','copas','baile','ronda','meme','reto','pregunta','regalo',
    'sueño','mentira','verdad','rumor','grupo','fiestón','madrugada','amanecer','lío','atrevimiento','mirador','playa','tardeo','chupito','brillo',
]


_V79_HOT_WORDS = [
    'mamada','felación','trío','follar','polla','pene','sexo','orgasmo','chupar','correrse','penetración','postura','calentón','deseo','morbo','fantasía',
    'gemido','lencería','desnudo','culo','pechos','tetas','lengua','cama','ducha','juguete','dominación','sumisión','beso negro','porno','erección',
    'eyaculación','masturbación','sexo oral','polvo','rapidito','noches calientes','calentura','lubricante','condón','placer','provocar','perversión',
]


def _v79_word_bank(chat_id: int) -> list[str]:
    return list(_V79_HOT_WORDS if bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)) else _V79_NORMAL_WORDS)


def _v79_pick_word(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    words = [w for w in _v79_word_bank(chat_id) if str(w).strip()]
    if not words:
        words = list(IMPOSTOR_WORDS)
    hist = cfg.setdefault('imp_word_history', [])
    if not isinstance(hist, list):
        hist = []
        cfg['imp_word_history'] = hist
    recent = {str(x).lower() for x in hist[-40:]}
    available = [w for w in words if str(w).lower() not in recent]
    if not available:
        available = words[:]
        hist.clear()
    word = secrets.choice(available)
    hist.append(word)
    del hist[:-80]
    save_all_states()
    return word


async def _v79_pin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int) -> None:
    if not message_id:
        return
    cfg = admin_cfg(chat_id)
    old = int(cfg.get('imp_current_lobby_pin_id') or 0)
    if old and old != int(message_id):
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=old)
        except Exception:
            pass
    cfg['imp_current_lobby_pin_id'] = int(message_id)
    save_all_states()
    try:
        await context.bot.pin_chat_message(chat_id=chat_id, message_id=int(message_id), disable_notification=True)
    except Exception:
        pass


async def _v79_unpin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Optional[Dict[str, Any]] = None) -> None:
    cfg = admin_cfg(chat_id)
    mid = int((game or {}).get('message_id') or cfg.get('imp_current_lobby_pin_id') or 0)
    if mid:
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass
    cfg['imp_current_lobby_pin_id'] = 0
    save_all_states()


def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    current = _imp_current_player(game)
    ronda = int(game.get('round', 1) or 1)
    if not current:
        return '🎭 No hay jugador de turno.'
    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    seconds = _v61_turn_seconds(chat_id) if chat_id and '_v61_turn_seconds' in globals() else 60
    ayudas = {
        1: 'Da una pista suave, una palabra o frase corta.',
        2: 'Da una pista un poco más clara, pero sin regalar la palabra.',
        3: 'Última pista. Puedes arriesgar un poco más, pero no digas la palabra exacta.',
    }
    count = _v60_current_timeout_count(game, int(current.get('id', 0) or 0)) if '_v60_current_timeout_count' in globals() else 0
    warn = 'Si no responde, pierde <b>1 punto</b> y se salta turno.' if count <= 0 else 'Si vuelve a no responder, queda <b>expulsado</b> y pierde <b>3 puntos más</b>.'
    return (
        f'✍️ {_imp_mention(current)}, <b>te toca.</b>\n\n'
        f'{h(ayudas.get(ronda, ayudas[3]))}\n'
        'Pulsa <b>Responder pista</b> y escribe tu pista en el grupo.\n\n'
        f'⏱ <b>Tiempo:</b> {_v60_format_remaining(seconds) if "_v60_format_remaining" in globals() else str(seconds) + "s"} · {warn}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    return InlineKeyboardMarkup([[InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]])


def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    if status == 'voting':
        return InlineKeyboardMarkup([
            [InlineKeyboardButton('🗳 Votar', callback_data=f'imp|vote_menu|{chat_id}|{gid}')],
            [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')],
        ])
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')]]
    try:
        can_accuse, reason = _v61_can_accuse_now(chat_id, game)
    except Exception:
        can_accuse, reason = True, ''
    if can_accuse:
        rows.append([InlineKeyboardButton('🚨 Acusar impostor', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    else:

        try:
            if not _v61_final_vote_only(chat_id):
                rows.append([InlineKeyboardButton(f'🚨 Acusar: {reason}', callback_data=f'imp|accuse_locked|{chat_id}|{gid}')])
        except Exception:
            pass
    try:
        if not _v61_final_vote_only(chat_id):
            rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    except Exception:
        rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        return
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active:
        await update.message.reply_html('Ya hay una partida de Impostor activa. Cancélala o termínala antes de crear otra.')
        return
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    word = raw[:60] if raw else _v79_pick_word(chat_id)
    gid = _imp_next_id(chat_id)
    creator = update.effective_user
    game = {
        'id': gid,
        'status': 'lobby',
        'word': word,
        'creator_id': int(creator.id),
        'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1,
        'turn_idx': 0,
        'votes': {},
        'impostor_id': 0,
        'message_id': 0,
    }
    msg = await update.message.reply_html(_imp_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)


_old_v79_v58_imp_start_game = _v58_imp_start_game
async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:
    await _v79_unpin_lobby(context, chat_id, game)
    game['chat_id'] = int(chat_id)
    save_all_states()
    return await _old_v79_v58_imp_start_game(update, context, chat_id, gid, game)


