def _v89_deepcopy_json(obj: Any) -> Any:
    try:
        return json.loads(json.dumps(obj, ensure_ascii=False))
    except Exception:
        import copy as _copy
        return _copy.deepcopy(obj)


def _v89_known_chats() -> List[int]:
    try:
        return _v88_known_chats()
    except Exception:
        return [int(x) for x in STATE_CACHE.keys()]


def _v89_chat_title(chat_id: int) -> str:
    try:
        return _v88_chat_title(chat_id)
    except Exception:
        try:
            return str(get_chat_title(chat_id))
        except Exception:
            return str(chat_id)


async def _v89_check_admin_both(context: ContextTypes.DEFAULT_TYPE, user_id: int, source_chat_id: int, dest_chat_id: Optional[int] = None) -> bool:
    try:
        if not await is_admin(context, int(source_chat_id), int(user_id)):
            return False
        if dest_chat_id is not None and not await is_admin(context, int(dest_chat_id), int(user_id)):
            return False
    except Exception:

        return True
    return True


def _v89_ai_export_dest_markup(source_chat_id: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for dest in _v89_known_chats():
        if int(dest) == int(source_chat_id):
            continue
        rows.append([InlineKeyboardButton(f'➡️ {_v89_chat_title(dest)}', callback_data=f'cfg|ai_export_to|{source_chat_id}|{int(dest)}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay otros grupos configurados', callback_data=f'cfg|noop|{source_chat_id}|ai')])
    rows.append([InlineKeyboardButton('🔙 Volver a IA', callback_data=f'cfg|block|{source_chat_id}|ai')])
    return InlineKeyboardMarkup(rows)


def _v89_dj_lists_source_markup(source_chat_id: int) -> InlineKeyboardMarkup:
    state = get_state(source_chat_id)
    names = sorted(state.saved_lists.keys())
    rows: List[List[InlineKeyboardButton]] = []
    if names:
        rows.append([InlineKeyboardButton('📦 Todas las listas', callback_data=f'cfg|djlist_export_dest|{source_chat_id}|-1')])
    for idx, name in enumerate(names[:40]):
        rows.append([InlineKeyboardButton(f'🎵 {name[:42]} ({len(state.saved_lists.get(name, []))})', callback_data=f'cfg|djlist_export_dest|{source_chat_id}|{idx}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay listas DJ guardadas', callback_data=f'cfg|noop|{source_chat_id}|dj_permissions')])
    rows.append([InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|block|{source_chat_id}|dj_permissions')])
    return InlineKeyboardMarkup(rows)


def _v89_dj_lists_dest_markup(source_chat_id: int, idx: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for dest in _v89_known_chats():
        if int(dest) == int(source_chat_id):
            continue
        rows.append([InlineKeyboardButton(f'➡️ {_v89_chat_title(dest)}', callback_data=f'cfg|djlist_export_to|{source_chat_id}|{idx}|{int(dest)}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay otros grupos configurados', callback_data=f'cfg|noop|{source_chat_id}|dj_permissions')])
    rows.append([InlineKeyboardButton('🔙 Elegir otra lista', callback_data=f'cfg|djlist_export_menu|{source_chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v89_merge_saved_list(dest_state: ChatState, name: str, items: List[Dict[str, Any]]) -> Tuple[str, int]:

    clean_items = dedupe_track_items([dict(x) for x in items])
    before = len(dest_state.saved_lists.get(name, []))
    merged = list(dest_state.saved_lists.get(name, [])) + clean_items
    dest_state.saved_lists[name] = dedupe_track_items(merged)
    after = len(dest_state.saved_lists.get(name, []))
    return name, max(0, after - before)


_old_v89_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v89_admin_private_block_markup(chat_id, block, page)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    try:
        if block == 'ai':
            btn = [InlineKeyboardButton('📤 Exportar comandos IA', callback_data=f'cfg|ai_export_menu|{chat_id}')]
            insert_at = max(0, len(rows) - 1)
            rows.insert(insert_at, btn)
        elif block in ('dj_permissions', 'lists'):
            btn = [InlineKeyboardButton('📤 Exportar listas DJ', callback_data=f'cfg|djlist_export_menu|{chat_id}')]
            insert_at = max(0, len(rows) - 1)
            rows.insert(insert_at, btn)
    except Exception:
        logger.exception('No se pudo añadir botones export V89')
    return InlineKeyboardMarkup(rows)


async def _v89_export_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'ai_export_menu':
            source_chat_id = int(parts[2])
            if not await _v89_check_admin_both(context, q.from_user.id, source_chat_id):
                await q.answer('Solo administradores del grupo origen.', show_alert=True)
                raise _V89Stop
            cmds = _ai_custom_commands(source_chat_id)
            await q.answer()
            await q.edit_message_text(
                '<b>📤 Exportar comandos IA</b>\n\n'
                f'Origen: <b>{h(_v89_chat_title(source_chat_id))}</b>\n'
                f'Comandos IA: <b>{len(cmds)}</b>\n\n'
                'Elige el grupo destino. Se copiarán los comandos IA con su nombre, mensaje de dato faltante, prompt, configuración y metadatos.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v89_ai_export_dest_markup(source_chat_id),
            )
            raise _V89Stop

        if action == 'ai_export_to':
            source_chat_id = int(parts[2]); dest_chat_id = int(parts[3])
            if not await _v89_check_admin_both(context, q.from_user.id, source_chat_id, dest_chat_id):
                await q.answer('Tienes que ser admin del origen y del destino.', show_alert=True)
                raise _V89Stop
            source_cmds = _ai_custom_commands(source_chat_id)
            if not source_cmds:
                await q.answer('No hay comandos IA que exportar.', show_alert=True)
                raise _V89Stop
            dest_cmds = _ai_custom_commands(dest_chat_id)
            created = 0; overwritten = 0
            for name, value in source_cmds.items():
                if name in dest_cmds:
                    overwritten += 1
                else:
                    created += 1
                dest_cmds[name] = _v89_deepcopy_json(value)
                if isinstance(dest_cmds[name], dict):
                    dest_cmds[name]['exported_from_chat_id'] = int(source_chat_id)
                    dest_cmds[name]['exported_ts'] = int(__import__('time').time())
            save_all_states()
            await q.answer('Comandos IA exportados ✅', show_alert=True)
            await q.edit_message_text(
                '<b>✅ Comandos IA exportados</b>\n\n'
                f'De: <b>{h(_v89_chat_title(source_chat_id))}</b>\n'
                f'A: <b>{h(_v89_chat_title(dest_chat_id))}</b>\n\n'
                f'✅ Nuevos: <b>{created}</b>\n'
                f'♻️ Sobrescritos: <b>{overwritten}</b>',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton('🧠 Ver IA destino', callback_data=f'cfg|block|{dest_chat_id}|ai')],
                    [InlineKeyboardButton('🔙 Volver origen', callback_data=f'cfg|block|{source_chat_id}|ai')],
                ]),
            )
            raise _V89Stop

        if action == 'djlist_export_menu':
            source_chat_id = int(parts[2])
            if not await _v89_check_admin_both(context, q.from_user.id, source_chat_id):
                await q.answer('Solo administradores del grupo origen.', show_alert=True)
                raise _V89Stop
            state = get_state(source_chat_id)
            await q.answer()
            await q.edit_message_text(
                '<b>📤 Exportar listas DJ</b>\n\n'
                f'Origen: <b>{h(_v89_chat_title(source_chat_id))}</b>\n'
                f'Listas guardadas: <b>{len(state.saved_lists)}</b>\n\n'
                'Elige qué lista quieres exportar o exporta todas.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v89_dj_lists_source_markup(source_chat_id),
            )
            raise _V89Stop

        if action == 'djlist_export_dest':
            source_chat_id = int(parts[2]); idx = int(parts[3])
            state = get_state(source_chat_id)
            names = sorted(state.saved_lists.keys())
            if idx >= 0 and idx >= len(names):
                await q.answer('Lista inválida.', show_alert=True)
                raise _V89Stop
            if not await _v89_check_admin_both(context, q.from_user.id, source_chat_id):
                await q.answer('Solo administradores del grupo origen.', show_alert=True)
                raise _V89Stop
            label = 'Todas las listas' if idx < 0 else names[idx]
            await q.answer()
            await q.edit_message_text(
                '<b>📤 Exportar listas DJ</b>\n\n'
                f'Origen: <b>{h(_v89_chat_title(source_chat_id))}</b>\n'
                f'Exportar: <b>{h(label)}</b>\n\n'
                'Elige el grupo destino.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v89_dj_lists_dest_markup(source_chat_id, idx),
            )
            raise _V89Stop

        if action == 'djlist_export_to':
            source_chat_id = int(parts[2]); idx = int(parts[3]); dest_chat_id = int(parts[4])
            if not await _v89_check_admin_both(context, q.from_user.id, source_chat_id, dest_chat_id):
                await q.answer('Tienes que ser admin del origen y del destino.', show_alert=True)
                raise _V89Stop
            src = get_state(source_chat_id); dst = get_state(dest_chat_id)
            names = sorted(src.saved_lists.keys())
            exported = 0; added_total = 0
            if idx < 0:
                selected = names
            else:
                if idx >= len(names):
                    await q.answer('Lista inválida.', show_alert=True)
                    raise _V89Stop
                selected = [names[idx]]
            for name in selected:
                _name, added = _v89_merge_saved_list(dst, name, src.saved_lists.get(name, []))
                exported += 1
                added_total += added
            save_all_states()
            await q.answer('Listas DJ exportadas ✅', show_alert=True)
            await q.edit_message_text(
                '<b>✅ Listas DJ exportadas</b>\n\n'
                f'De: <b>{h(_v89_chat_title(source_chat_id))}</b>\n'
                f'A: <b>{h(_v89_chat_title(dest_chat_id))}</b>\n\n'
                f'Listas copiadas/fusionadas: <b>{exported}</b>\n'
                f'Canciones nuevas añadidas: <b>{added_total}</b>\n\n'
                'Si una lista ya existía en destino, se ha fusionado sin duplicar canciones.',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton('🎛 Ver Permisos DJ destino', callback_data=f'cfg|block|{dest_chat_id}|dj_permissions')],
                    [InlineKeyboardButton('🔙 Exportar más', callback_data=f'cfg|djlist_export_menu|{source_chat_id}')],
                ]),
            )
            raise _V89Stop
    except _V89Stop:
        raise
    except Exception:
        logger.exception('Error exportando IA/DJ V89: %s', data)
        try:
            await q.answer('Error exportando. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V89Stop


