async def _v96_rec_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')

    try:
        chat_id = int(parts[2])
        page = int(parts[3])
    except Exception:
        try:
            await q.answer('Página inválida.', show_alert=True)
        except Exception:
            pass
        raise _V96Stop

    page = recurring_clamp_page(chat_id, page)
    try:
        await q.answer(f'Página {page + 1}/{recurring_total_pages(chat_id)}')
    except Exception:
        pass

    text = admin_private_block_text(chat_id, 'recurrentes', page)
    markup = admin_private_block_markup(chat_id, 'recurrentes', page)
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except BadRequest as e:

        if 'not modified' in str(e).lower():
            pass
        else:
            logger.exception('No se pudo cambiar página recurrentes V96')
            try:
                await q.message.reply_html(text, reply_markup=markup)
            except Exception:
                pass
    except Exception:
        logger.exception('No se pudo cambiar página recurrentes V96')
        try:
            await q.message.reply_html(text, reply_markup=markup)
        except Exception:
            pass
    raise _V96Stop


