_old_v97_admin_private_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    text = _old_v97_admin_private_block_text(chat_id, block, 0 if block == 'recurrentes' else page)
    if block == 'recurrentes':

        try:
            text = re.sub(r' · Página: <b>\d+/\d+</b>', '', text)
            text = re.sub(r' · Página <b>\d+/\d+</b>', '', text)
            text = re.sub(r'Página:? <b>\d+/\d+</b>', '', text)
        except Exception:
            pass
        text += "\n\n<i>Vista sin paginación: se muestran todos los recurrentes configurados en esta misma pantalla.</i>"
    return text


_old_v97_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v97_admin_private_block_markup(chat_id, block, 0 if block == 'recurrentes' else page)
    if block != 'recurrentes':
        return markup
    try:
        rows: List[List[InlineKeyboardButton]] = []
        for row in getattr(markup, 'inline_keyboard', []) or []:

            texts = [str(getattr(b, 'text', '') or '') for b in row]
            callbacks = [str(getattr(b, 'callback_data', '') or '') for b in row]
            if any('Anterior' in t or 'Siguiente' in t or re.match(r'^📄 \d+/\d+$', t) for t in texts):
                continue
            if any(cb.startswith('cfg|rec_page|') for cb in callbacks):

                new_row = []
                for b in row:
                    cb = str(getattr(b, 'callback_data', '') or '')
                    txt = str(getattr(b, 'text', '') or '')
                    if cb.startswith('cfg|rec_page|') and 'Recargar' in txt:
                        new_row.append(InlineKeyboardButton('🔄 Recargar', callback_data=f'cfg|block|{chat_id}|recurrentes'))
                    elif not cb.startswith('cfg|rec_page|'):
                        new_row.append(b)
                if new_row:
                    rows.append(new_row)
                continue
            rows.append(list(row))
        return InlineKeyboardMarkup(rows)
    except Exception:
        logger.exception('No se pudo quitar paginación recurrentes V97')
        return markup


async def _v97_rec_page_compat(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    try:
        parts = (q.data or '').split('|')
        chat_id = int(parts[2])
    except Exception:
        try:
            await q.answer('Recurrentes sin paginación.', show_alert=False)
        except Exception:
            pass
        raise _V96Stop if '_V96Stop' in globals() else Exception()
    try:
        await q.answer('Vista completa de recurrentes')
    except Exception:
        pass
    await q.edit_message_text(admin_private_block_text(chat_id, 'recurrentes'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'recurrentes'))
    raise _V96Stop if '_V96Stop' in globals() else Exception()


_old_build_application_v97 = build_application

def build_application() -> Application:
    app = _old_build_application_v97()
    app.add_handler(CallbackQueryHandler(_v97_rec_page_compat, pattern=r'^cfg\|rec_page\|'), group=-8000000)
    logger.info('V97 recurrentes sin paginación cargado')
    return app


