_old_start_command_v98 = start_command
async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if update.effective_chat and update.effective_chat.type == 'private':
        return await _old_start_command_v98(update, context)
    if not update.message or not update.effective_chat:
        return
    msg = await update.message.reply_html('<b>🎧 Música en directo</b>\n\nElige un modo:', reply_markup=main_menu_markup())
    try:
        await register_bot_message(update.effective_chat.id, msg.message_id)
    except Exception:
        pass
    asyncio.create_task(_v98_delete_later(context.bot, update.effective_chat.id, msg.message_id, 30))
    try:
        await safe_delete(context.bot, update.effective_chat.id, update.message.message_id)
    except Exception:
        pass


