_old_panel_text_v98 = panel_text
def panel_text(state: ChatState) -> str:
    try:

        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is not None:
            cfg = admin_cfg(int(chat_id))
            custom = str(cfg.get('dj_panel_custom_text_html') or '').strip()
            if custom:
                current = 'Nada sonando'
                nxt = 'Nada en cola'
                if state.now_playing:
                    current = shorten_title(Track(**state.now_playing).title, 42)
                if state.queue:
                    nxt = shorten_title(Track(**state.queue[0]).title, 42)
                repl = {
                    '{estado}': 'ON' if state.live_enabled else 'OFF',
                    '{cancion}': h(current),
                    '{actual}': h(current),
                    '{siguiente}': h(nxt),
                    '{dj}': h(state.assigned_dj_name or 'Sin asignar'),
                    '{cola}': str(len(state.queue)),
                    '{biblioteca}': str(len(state.library)),
                }
                for k, v in repl.items():
                    custom = custom.replace(k, v)
                return custom
    except Exception:
        logger.exception('Error en panel_text custom V98')
    return _old_panel_text_v98(state)


_old_v72_dj_perm_text_v98 = _v72_dj_perm_text if '_v72_dj_perm_text' in globals() else None
def _v98_dj_panel_cfg_text(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    custom = str(cfg.get('dj_panel_custom_text_html') or '').strip()
    base = _old_v72_dj_perm_text_v98(chat_id) if callable(_old_v72_dj_perm_text_v98) else '<b>🎛 Permisos DJ</b>'
    base += "\n\n<b>Mensaje fijado superior DJ</b>\n"
    base += 'Personalizado: <b>' + ('ON ✅' if custom else 'OFF · usando defecto') + '</b>\n'
    base += 'Puedes usar HTML, emojis premium de Telegram y variables: <code>{estado}</code>, <code>{cancion}</code>, <code>{siguiente}</code>, <code>{dj}</code>, <code>{cola}</code>.'
    return base


