_PRIVATE_CLEAN_TRACK_V99: Dict[int, List[int]] = {}


def _v99_track_private(user_id: int, message_id: Optional[int]) -> None:
    try:
        if not user_id or not message_id:
            return
        arr = _PRIVATE_CLEAN_TRACK_V99.setdefault(int(user_id), [])
        mid = int(message_id)
        if mid not in arr:
            arr.append(mid)
        if len(arr) > 150:
            del arr[:-150]
        if '_v71_track_private_message' in globals():
            _v71_track_private_message(int(user_id), mid)
    except Exception:
        pass


async def _v99_clean_private(bot, private_chat_id: int, user_id: int) -> int:
    deleted = 0
    ids = list(dict.fromkeys(_PRIVATE_CLEAN_TRACK_V99.get(int(user_id), [])))
    try:
        if '_V71_PRIVATE_GARBAGE' in globals():
            ids.extend(list(dict.fromkeys(_V71_PRIVATE_GARBAGE.get(int(user_id), []))))
    except Exception:
        pass
    try:
        if '_PRIVATE_PANEL_MESSAGES_V67' in globals():
            ids.extend(list(dict.fromkeys(PRIVATE_PANEL_MESSAGES_V67.get(int(private_chat_id), []))))
    except Exception:
        pass
    for mid in sorted(set(int(x) for x in ids if x), reverse=True):
        try:
            await bot.delete_message(chat_id=int(private_chat_id), message_id=mid)
            deleted += 1
        except Exception:
            pass
    _PRIVATE_CLEAN_TRACK_V99[int(user_id)] = []
    try:
        if '_V71_PRIVATE_GARBAGE' in globals():
            _V71_PRIVATE_GARBAGE[int(user_id)] = []
    except Exception:
        pass
    try:
        if '_PRIVATE_PANEL_MESSAGES_V67' in globals():
            PRIVATE_PANEL_MESSAGES_V67[int(private_chat_id)] = set()
    except Exception:
        pass
    return deleted


