def _v99_local_label(ts: int) -> str:
    try:
        dt = _local_dt_v15(int(ts)) if '_local_dt_v15' in globals() else _dt_v15.fromtimestamp(int(ts))
        return dt.strftime('%d/%m %H:%M')
    except Exception:
        return str(ts)


def _v99_next_run_ts(row: Dict[str, Any], now_ts: Optional[int] = None) -> Optional[int]:
    import copy, time as _time
    now_ts = int(now_ts or _time.time())
    if not bool(row.get('enabled', True)):
        return None
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    stype = str(sched.get('type') or '')
    try:
        if stype == 'start_interval':
            start_ts = int(sched.get('start_ts') or 0)
            repeat = max(60, int(sched.get('repeat_seconds') or 3600))
            until_ts = int(sched.get('until_ts') or 0) if bool(sched.get('until_enabled')) else 0
            last = int(row.get('last_sent_ts') or 0)
            nxt = start_ts if last <= 0 else max(now_ts, last + repeat)
            if nxt < now_ts:

                diff = now_ts - nxt
                jumps = (diff // repeat) + 1
                nxt += jumps * repeat
            if until_ts and nxt > until_ts:
                return None
            return nxt
        if stype == 'interval':
            sec = max(30, int(sched.get('seconds', 3600) or 3600))
            last = int(row.get('last_sent_ts') or 0)
            return now_ts if last <= 0 else max(now_ts, last + sec)

        probe = copy.deepcopy(row)
        for offset in range(0, 31 * 24 * 60 + 1):
            ts = now_ts + offset * 60
            try:
                if recurring_due(probe, ts):
                    return ts
            except Exception:
                pass
    except Exception:
        logger.exception('No se pudo calcular próxima hora recurrente')
    return None


def _v99_next_run_label(row: Dict[str, Any]) -> str:
    nxt = _v99_next_run_ts(row)
    return _v99_local_label(nxt) if nxt else 'sin próxima hora'


_old_v99_recurring_detail_text = recurring_detail_text
