try:
    from telegram.ext import ApplicationHandlerStop as _V104Stop
except Exception:
    _V104Stop = Exception


def _v104_layout(row: Dict[str, Any]) -> str:
    layout = str(row.get('media_layout') or row.get('rec_media_layout') or '').strip().lower()
    if layout in {'caption','media_above','text_above','media_only','text_only'}:
        return layout

    pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').lower()
    return 'text_above' if pos == 'below' else 'media_above'


def _v104_layout_label(layout: str) -> str:
    return {
        'caption': '1 mensaje: multimedia + texto/caption',
        'media_above': '2 mensajes: multimedia arriba y texto abajo',
        'text_above': '2 mensajes: texto arriba y multimedia abajo',
        'media_only': 'solo multimedia, sin texto',
        'text_only': 'solo texto, sin multimedia',
    }.get(layout, layout)


async def _v104_send_media_caption(bot, chat_id: int, media: Dict[str, Any], text: str, markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    caption = text or None
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)


async def _v104_send_media_only(bot, chat_id: int, media: Dict[str, Any], markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, reply_markup=markup)


async def _v104_send_text(bot, chat_id: int, text: str, markup=None):
    return await bot.send_message(chat_id, text=text or ' ', parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)


async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    text = str(row.get('text') or '').strip()
    layout = _v104_layout(row)


    if not media or not media.get('file_id') or layout == 'text_only':
        previous_ids: List[int] = []
        try:
            if isinstance(row.get('last_message_ids'), list):
                previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
            if int(row.get('last_message_id') or 0):
                previous_ids.append(int(row.get('last_message_id')))
        except Exception:
            pass
        delete_previous = bool(row.get('delete_previous', True))
        try:
            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_text(context.bot, chat_id, text or ' ', markup=markup)
            await register_bot_message(chat_id, msg.message_id)
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else ''
            try:
                markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
                if markup2:
                    await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
            except Exception:
                pass
            row['last_message_id'] = int(msg.message_id)
            row['last_message_ids'] = [int(msg.message_id)]
            row['last_message_link'] = link
            row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
            save_all_states()
            if bool(row.get('pin', False)):
                try: await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
                except Exception: pass
            if delete_previous:
                if '_v98_delete_message_ids' in globals():
                    await _v98_delete_message_ids(context.bot, chat_id, [x for x in previous_ids if x != int(msg.message_id)])
                else:
                    for mid in previous_ids:
                        if mid != int(msg.message_id):
                            try: await safe_delete(context.bot, chat_id, mid)
                            except Exception: pass
            return int(msg.message_id)
        except Exception:
            logger.exception('No se pudo enviar recurrente texto V104 %s en chat %s', row.get('id'), chat_id)
            return None

    previous_ids: List[int] = []
    try:
        if isinstance(row.get('last_message_ids'), list):
            previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
        if int(row.get('last_message_id') or 0):
            previous_ids.append(int(row.get('last_message_id')))
    except Exception:
        pass
    delete_previous = bool(row.get('delete_previous', True))
    sent_ids: List[int] = []
    main_msg = None
    pin_id = None

    try:
        if layout == 'caption':

            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_media_caption(context.bot, chat_id, media, text, markup=markup)
            main_msg = msg
            sent_ids.append(int(msg.message_id))
            await register_bot_message(chat_id, msg.message_id)
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else ''
            try:
                markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
                if markup2:
                    await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
            except Exception:
                pass
            pin_id = int(msg.message_id)
        elif layout == 'media_only':
            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
            main_msg = msg
            sent_ids.append(int(msg.message_id))
            await register_bot_message(chat_id, msg.message_id)
            pin_id = int(msg.message_id)
        elif layout == 'media_above':
            media_msg = await _v104_send_media_only(context.bot, chat_id, media)
            sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
            if text:
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, media_msg.message_id) if '_v98_message_link' in globals() else None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                txt_msg = await _v104_send_text(context.bot, chat_id, text, markup=markup)
                sent_ids.append(int(txt_msg.message_id)); await register_bot_message(chat_id, txt_msg.message_id)
                main_msg = txt_msg

                pin_id = int(txt_msg.message_id)
            else:
                main_msg = media_msg
                pin_id = int(media_msg.message_id)
                markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                if markup:
                    try: await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=media_msg.message_id, reply_markup=markup)
                    except Exception: pass
        else:
            if text:
                txt_msg = await _v104_send_text(context.bot, chat_id, text)
                sent_ids.append(int(txt_msg.message_id)); await register_bot_message(chat_id, txt_msg.message_id)
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, txt_msg.message_id) if '_v98_message_link' in globals() else None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                media_msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
                sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
                main_msg = media_msg

                pin_id = int(txt_msg.message_id)
            else:
                markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                media_msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
                sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
                main_msg = media_msg
                pin_id = int(media_msg.message_id)

        if main_msg is None:
            return None
        row['last_message_id'] = int(main_msg.message_id)
        row['last_message_ids'] = sent_ids
        try:
            row['last_message_link'] = _v98_message_link(chat_id, int(main_msg.message_id)) if '_v98_message_link' in globals() else ''
        except Exception:
            row['last_message_link'] = ''
        row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
        save_all_states()

        if bool(row.get('pin', False)) and pin_id:
            try: await context.bot.pin_chat_message(chat_id, int(pin_id), disable_notification=True)
            except Exception: pass
        if delete_previous:
            ids = [x for x in previous_ids if x not in sent_ids]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try: await safe_delete(context.bot, chat_id, mid)
                    except Exception: pass
        return int(main_msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia V104 %s en chat %s', row.get('id'), chat_id)
        return None


_old_recurring_detail_text_v104 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:
    txt = _old_recurring_detail_text_v104(chat_id, rid)
    row = recurring_find(chat_id, rid)
    if isinstance(row, dict) and isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        layout = _v104_layout(row)
        txt += f"\n\n📐 Formato multimedia: <b>{h(_v104_layout_label(layout))}</b>"
        if layout != 'caption' and bool(row.get('pin', False)):
            txt += "\n⚠️ Si quieres que el fijado muestre miniatura + texto juntos, usa el modo <b>1 mensaje: multimedia + texto/caption</b>."
    return txt


_old_recurring_detail_markup_v104 = recurring_detail_markup
def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    markup = _old_recurring_detail_markup_v104(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]
    row = recurring_find(chat_id, rid) or {}
    if isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        insert_at = max(0, len(rows) - 1)
        layout = _v104_layout(row)
        rows.insert(insert_at, [InlineKeyboardButton('📐 Formato multimedia', callback_data=f'cfg|rec_media_layout_menu|{chat_id}|{rid}')])


    return InlineKeyboardMarkup(rows)


def _v104_layout_menu(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    row = recurring_find(chat_id, rid) or {}
    current = _v104_layout(row)
    opts = [
        ('caption', '📌 1 mensaje: multimedia + texto/caption'),
        ('media_above', '🖼 Multimedia arriba + texto abajo'),
        ('text_above', '📝 Texto arriba + multimedia abajo'),
        ('media_only', '🚫 Solo multimedia, sin texto'),
        ('text_only', '📝 Solo texto, sin multimedia'),
    ]
    rows = []
    for key, label in opts:
        rows.append([InlineKeyboardButton(('✅ ' if key == current else '') + label, callback_data=f'cfg|rec_media_layout_set|{chat_id}|{rid}|{key}')])
    rows.append([InlineKeyboardButton('🔙 Volver al recurrente', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)


async def _v104_recurrente_layout_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    if action not in {'rec_media_layout_menu', 'rec_media_layout_set'}:
        return
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
        row = recurring_find(chat_id, rid)
        if not row:
            await q.answer('No encuentro ese recurrente.', show_alert=True)
            raise _V104Stop
        if action == 'rec_media_layout_menu':
            await q.answer('Formato multimedia')
            await q.edit_message_text(
                '<b>📐 Formato multimedia</b>\n\n'
                'Elige cómo quieres que se publique este recurrente.\n\n'
                'Para que el <b>mensaje fijado</b> muestre miniatura + texto juntos, usa el modo de 1 mensaje/caption.\n'
                'Para ver texto y multimedia separados en el chat, usa los modos de 2 mensajes.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v104_layout_menu(chat_id, rid),
            )
            raise _V104Stop
        layout = parts[4]
        if layout not in {'caption','media_above','text_above','media_only','text_only'}:
            await q.answer('Formato no válido', show_alert=True)
            raise _V104Stop
        row['media_layout'] = layout

        if layout == 'text_above':
            row['media_position'] = 'below'
        elif layout == 'media_above':
            row['media_position'] = 'above'
        save_all_states()
        await q.answer('Formato guardado ✅')
        await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
        raise _V104Stop
    except _V104Stop:
        raise
    except Exception:
        logger.exception('Error formato multimedia recurrente V104: %s', data)
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V104Stop


_old_build_application_v104 = build_application
def build_application() -> Application:
    app = _old_build_application_v104()
    app.add_handler(CallbackQueryHandler(_v104_recurrente_layout_callback, pattern=r'^cfg\|rec_media_layout_'), group=-9000000)
    logger.info('V104 recurrentes multimedia con modos visuales configurables cargado')
    return app


