async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v105_panel_markup(chat_id)
        old_id = state.panel_message_id
        if old_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=old_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
                save_all_states()
                return
            except BadRequest as e:
                msg = str(e).lower()
                if 'message is not modified' in msg:
                    return
                if 'message to edit not found' in msg:
                    state.panel_message_id = None
                    save_all_states()
            except Exception:
                logger.exception('No se pudo editar panel DJ V105; se creará uno nuevo')

        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        state.panel_message_id = int(msg.message_id)
        save_all_states()
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            logger.exception('No se pudo fijar panel DJ V105')


async def cleanup_all_bot_messages(bot, chat_id: int) -> None:
    state = get_state(chat_id)
    keep_ids = {mid for mid in [state.panel_message_id, state.control_message_id, state.temp_pin_message_id] if mid}

    for mid in list(state.temp_message_ids):
        if mid not in keep_ids:
            await safe_delete(bot, chat_id, mid)
    state.temp_message_ids = [mid for mid in state.temp_message_ids if mid in keep_ids]
    save_all_states()


async def cleanup_bot_messages_keep_core(bot, chat_id: int) -> None:
    state = get_state(chat_id)
    keep_ids = {mid for mid in [state.panel_message_id, state.control_message_id, state.temp_pin_message_id] if mid}
    for mid in list(state.temp_message_ids):
        if mid not in keep_ids:
            await safe_delete(bot, chat_id, mid)
    state.temp_message_ids = [mid for mid in state.temp_message_ids if mid in keep_ids]

    save_all_states()


