async def _v106_show_easy(q, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    try:
        await q.edit_message_text(_v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        sent = await context.bot.send_message(chat_id, _v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
        try:
            await register_temp_message(chat_id, sent.message_id)
        except Exception:
            pass
    except Exception:
        logger.exception('No se pudo mostrar DJ Fácil')


async def _v106_modes_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_menu', 'menu_panel'}:
        return
    chat_id = int(update.effective_chat.id)
    state = get_state(chat_id)
    user = update.effective_user
    if data == 'dj_easy_menu':
        if not await _v106_user_can(context, chat_id, user, 'easy'):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V106Stop
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        state.auto_track_enabled = True if state.auto_track_enabled else state.auto_track_enabled
        _v106_cfg(chat_id)['dj_mesa_minimized'] = True
        _v106_cfg(chat_id)['dj_mesa_visible'] = False
        _v106_cfg(chat_id)['dj_announce_now_enabled'] = False
        _v106_set_mode(chat_id, 'easy')
        save_all_states()
        await q.answer('DJ Fácil abierto ✅')
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop

    if not await _v106_user_can(context, chat_id, user, 'pro'):
        await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V106Stop
    state.dj_mode = True
    if not state.assigned_dj_id:
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
    _v106_cfg(chat_id)['dj_mesa_minimized'] = False
    _v106_cfg(chat_id)['dj_mesa_visible'] = True
    _v106_set_mode(chat_id, 'pro')
    set_control_view(state, 'home', 0)
    save_all_states()
    await q.answer('Mesa DJ-PRO abierta ✅')
    await ensure_panel(context.bot, chat_id)
    await ensure_control_panel(context.bot, chat_id)
    raise _V106Stop


async def _v106_easy_actions(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_start','dj_easy_next','dj_easy_close','dj_easy_info'} and not data.startswith('dj_timer|easy|'):
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    state = get_state(chat_id)
    if not await _v106_user_can(context, chat_id, user, 'easy'):
        await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V106Stop
    _v106_set_mode(chat_id, 'easy')
    _v106_cfg(chat_id)['dj_mesa_minimized'] = True
    _v106_cfg(chat_id)['dj_mesa_visible'] = False
    _v106_cfg(chat_id)['dj_announce_now_enabled'] = False
    if data == 'dj_easy_info':
        await q.answer('Instrucciones')
        await q.edit_message_text(
            '<b>ℹ️ Abrir videochat manualmente</b>\n\n'
            '1. Pulsa arriba en el <b>nombre del grupo</b>.\n'
            '2. Entra en <b>Videochat / Directo</b>.\n'
            '3. Vuelve al panel de DJ Fácil.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Volver DJ Fácil', callback_data='dj_easy_menu')]])
        )
        raise _V106Stop
    if data.startswith('dj_timer|easy|'):
        hours = 0
        try:
            hours = int(data.split('|')[2])
        except Exception:
            pass
        try:
            if hours <= 0:
                _v75_cancel_timer(chat_id)
                await q.answer('Temporizador OFF ✅', show_alert=True)
            else:
                _v75_set_timer(context.bot, chat_id, hours, 'easy')
                await q.answer(f'DJ Fácil se cerrará en {hours}h ✅', show_alert=True)
        except Exception:
            logger.exception('No se pudo gestionar temporizador easy')
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_start':
        if not state.library:
            await q.answer('La biblioteca está vacía.', show_alert=True)
            raise _V106Stop
        items = [dict(x) for x in state.library]
        try:
            import random as _r106
            _r106.shuffle(items)
        except Exception:
            pass
        state.queue = dedupe_track_items(items)
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        state.dj_shuffle_enabled = True
        state.auto_track_enabled = True
        state.auto_sig_seconds = 0
        save_all_states()
        try:
            await _dj_open_or_explain_live_v29(context, chat_id, start_call=True)
        except Exception:
            logger.exception('No pude abrir/explicar directo easy')
        if not state.now_playing:
            try:
                await simulate_panel_next(chat_id, reason='dj_easy_start')
            except Exception:
                logger.exception('No pude iniciar primera canción easy')
        await q.answer('DJ Fácil iniciado ✅', show_alert=True)
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_next':
        if not state.dj_mode:
            await q.answer('DJ Fácil no está activo.', show_alert=True)
            raise _V106Stop
        ok = await simulate_panel_next(chat_id, reason='dj_easy_next')
        await q.answer('Siguiente canción ✅' if ok else 'No hay canción siguiente.', show_alert=True)
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_close':
        await q.answer('Cerrando DJ Fácil…')
        await close_dj_session(context.bot, chat_id)
        try:
            await q.edit_message_text('🎧 DJ Fácil cerrado ✅')
        except Exception:
            pass
        raise _V106Stop


