async def _v106_saved_list_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Listas a cola/reproducir sin duplicar, con prioridad máxima."""
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('lst|'):
        return
    parts = data.split('|')
    if len(parts) < 3 or parts[1] not in {'a','p'}:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await q.answer('Solo el DJ asignado puede cargar listas.', show_alert=True)
        raise _V106Stop
    state = get_state(chat_id)
    try:
        idx = int(parts[2])
    except Exception:
        idx = -1
    names = sorted(state.saved_lists.keys())
    if not (0 <= idx < len(names)):
        await q.answer('Lista no válida.', show_alert=True)
        raise _V106Stop
    name = names[idx]
    items = [dict(x) for x in state.saved_lists.get(name, [])]
    if parts[1] == 'a':
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + items)
        save_all_states()
        await q.answer('Lista añadida sin duplicar ✅', show_alert=True)
    else:
        if not items:
            await q.answer('Lista vacía.', show_alert=True)
            raise _V106Stop
        first = Track(**items[0])
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + items[1:])
        save_all_states()
        await play_selected_track(context, chat_id, first)
        await q.answer('Lista reproduciendo sin duplicar ✅', show_alert=True)
    set_control_view(state, 'saved_lists', 0)
    save_all_states()
    await ensure_panel(context.bot, chat_id)
    await ensure_control_panel(context.bot, chat_id)
    raise _V106Stop


