async def _v106_dj_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('djpriv|'):
        return
    parts = data.split('|')
    if len(parts) < 2 or parts[1] not in {'loadlist','recentq'}:
        return
    action = parts[1]
    try:
        chat_id = int(parts[2]) if len(parts) > 2 else int(dj_selected_private_group(update.effective_user.id) or 0)
    except Exception:
        chat_id = 0
    if not chat_id:
        await q.answer('Primero vincula un grupo con /djgrupo.', show_alert=True)
        raise _V106Stop
    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await q.answer('Solo admin o DJ asignado.', show_alert=True)
        raise _V106Stop
    state = get_state(chat_id)
    if action == 'loadlist':
        try:
            idx = int(parts[3])
        except Exception:
            idx = -1
        names = sorted(state.saved_lists.keys())[:80]
        if not (0 <= idx < len(names)):
            await q.answer('Lista no válida.', show_alert=True)
            raise _V106Stop
        name = names[idx]
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + [dict(x) for x in state.saved_lists.get(name, [])])
        save_all_states()
        await q.answer('Lista cargada sin duplicar ✅', show_alert=True)
    else:
        private_chat_id = int(q.message.chat_id) if q.message else int(update.effective_user.id)
        recent = list((TRACK_REGISTRY.get(private_chat_id, {}) or {}).values())[-100:]
        if not recent:
            await q.answer('No hay canciones recientes en este privado.', show_alert=True)
            raise _V106Stop
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + [dict(x) for x in recent])
        save_all_states()
        await q.answer(f'{len(recent)} recientes añadidas sin duplicar ✅', show_alert=True)
    await ensure_panel(context.bot, chat_id)
    if _v106_mode(chat_id) == 'pro':
        await ensure_control_panel(context.bot, chat_id)
    try:
        await q.edit_message_text(dj_private_text(chat_id), reply_markup=dj_private_markup(chat_id), parse_mode=ParseMode.HTML)
    except Exception:
        pass
    raise _V106Stop


try:
    _old_v106_dj_private_markup = dj_private_markup
    def dj_private_markup(chat_id: int) -> InlineKeyboardMarkup:
        markup = _old_v106_dj_private_markup(chat_id)
        rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
        flat = [getattr(b, 'callback_data', '') for row in rows for b in row]
        if not any(str(cd).startswith('djpriv|recentq|') for cd in flat):
            rows.insert(1, [InlineKeyboardButton('➕ Recientes a cola', callback_data=f'djpriv|recentq|{chat_id}')])
        return InlineKeyboardMarkup(rows)
except Exception:
    pass


_old_build_application_v106 = build_application

def build_application() -> Application:
    app = _old_build_application_v106()

    app.add_handler(CallbackQueryHandler(_v106_modes_router, pattern=r'^(dj_easy_menu|menu_panel)$'), group=-99999999)
    app.add_handler(CallbackQueryHandler(_v106_easy_actions, pattern=r'^(dj_easy_start|dj_easy_next|dj_easy_close|dj_easy_info|dj_timer\|easy\|)'), group=-99999999)
