        [InlineKeyboardButton('▶️ Empezar partida', callback_data=f'imp|start|{chat_id}|{gid}'), InlineKeyboardButton('⚙️ Configurar partida', callback_data=f'imp|cfg|{chat_id}|{gid}')],
        [InlineKeyboardButton('📣 Recordar', callback_data=f'imp|remind|{chat_id}|{gid}'), InlineKeyboardButton('📘 Instrucciones', callback_data=f'imp|instructions|{chat_id}|{gid}')],
