_old_admin_private_config_callback_v110 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|impimg|'):
        try:
            _cfg, _act, chat_s, kind = data.split('|')[:4]
            chat_id = int(chat_s)
        except Exception:
            await q.answer('Configuración inválida', show_alert=True); raise _V110Stop
        set_config_pending(q.from_user.id, {'kind': f'imp_image_{kind}_v110', 'chat_id': chat_id})
        await q.answer()
        await q.message.reply_html('Envía ahora una <b>foto</b> para usarla en el Impostor.\n\nLobby: imagen encima del lobby.\nGanador: imagen encima del resultado final.')
        raise _V110Stop
    if q and data.startswith('cfg|impimgclear|'):
        try:
            chat_id = int(data.split('|')[2])
        except Exception:
            await q.answer('Grupo inválido', show_alert=True); raise _V110Stop
        cfg = admin_cfg(chat_id)
        cfg.pop('imp_lobby_image_file_id', None)
        cfg.pop('imp_winner_image_file_id', None)
        save_all_states()
        await q.answer('Imágenes quitadas ✅')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        except Exception:
            pass
        raise _V110Stop
    return await _old_admin_private_config_callback_v110(update, context)


_old_admin_private_config_text_v110 = globals().get('admin_private_config_text')
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending and str(pending.get('kind','')).startswith('imp_image_'):
            chat_id = int(pending.get('chat_id') or 0)
            kind = str(pending.get('kind'))
            photos = getattr(update.message, 'photo', None)
            if not photos:
                await update.message.reply_html('❌ Envía una foto, no texto.')
                return True
            file_id = photos[-1].file_id
            cfg = admin_cfg(chat_id)
            if 'lobby' in kind:
                cfg['imp_lobby_image_file_id'] = file_id
            else:
                cfg['imp_winner_image_file_id'] = file_id
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html('✅ Imagen guardada para Impostor.')
            return True
    if callable(_old_admin_private_config_text_v110):
        return await _old_admin_private_config_text_v110(update, context)
    return False


_old_impostor_command_v110 = impostor_command
async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        return
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby','active','voting')), None)
    if active:
        await update.message.reply_html('Ya hay una partida de Impostor activa. Cancélala o termínala antes de crear otra.')
        return
    gid = _imp_next_id(chat_id)
    cfg = _v110_cfg_defaults(chat_id)
    word = _v110_pick_word(chat_id, bool(cfg.get('hot')))
    creator = update.effective_user
    game = {
        'id': gid, 'status': 'lobby', 'word': word, 'creator_id': int(creator.id), 'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1, 'turn_idx': 0, 'votes': {}, 'impostor_id': 0, 'message_id': 0, 'chat_id': chat_id,
        'v110_config': cfg,
        'v83_auto_start_sec': int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0),
    }
    img = admin_cfg(chat_id).get('imp_lobby_image_file_id')
    if img:
        msg = await update.message.reply_photo(photo=img, caption=_v110_lobby_text(game)[:1024], parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    else:
        msg = await update.message.reply_html(_v110_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)


async def _v79_create_game(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> Dict[str, Any]:
    cfg = _v110_cfg_defaults(chat_id)
    gid = _imp_next_id(chat_id)
    game = {
        'id': gid, 'status': 'lobby', 'word': _v110_pick_word(chat_id, bool(cfg.get('hot'))), 'creator_id': int(user.id), 'created_ts': int(time.time()),
        'players': [{'id': int(user.id), 'name': display_name(user), 'username': getattr(user, 'username', '') or ''}],
        'round': 1, 'turn_idx': 0, 'votes': {}, 'impostor_id': 0, 'message_id': 0, 'chat_id': chat_id,
        'v110_config': cfg,
        'v83_auto_start_sec': int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0),
    }
    img = admin_cfg(chat_id).get('imp_lobby_image_file_id')
    if img:
        msg = await context.bot.send_photo(chat_id, photo=img, caption=_v110_lobby_text(game)[:1024], parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    else:
        msg = await context.bot.send_message(chat_id, _v110_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)
    return game


def _v61_final_vote_only(chat_id: int, game: Optional[Dict[str, Any]] = None) -> bool:
    if isinstance(game, dict):
        return bool(_v110_ensure_game_config(chat_id, game).get('final_vote_only'))
    return bool(cfg_value(chat_id, 'imp_final_vote_only', False))


def _v61_min_accuse_round(chat_id: int, game: Optional[Dict[str, Any]] = None) -> int:
    if isinstance(game, dict):
        return int(_v110_ensure_game_config(chat_id, game).get('accuse_round') or 1)
    return int(cfg_value(chat_id, 'imp_min_accuse_round', 1) or 1)


def _v61_can_accuse_now(chat_id: int, game: Dict[str, Any]) -> tuple[bool, str]:
    cfg = _v110_ensure_game_config(chat_id, game)
    if bool(cfg.get('final_vote_only')):
        return False, 'Solo votación final R3'
    ronda = int(game.get('round', 1) or 1)
    min_r = int(cfg.get('accuse_round') or 1)
    if ronda < min_r:
        return False, f'desde R{min_r}'
    return True, ''


def _v110_clues_by_round(game: Dict[str, Any]) -> str:
    clues = game.get('clues') if isinstance(game.get('clues'), list) else []
    if not clues:
        return '<i>Aún no hay pistas.</i>'
    lines = []
    for r in (1, 2, 3):
        part = [c for c in clues if int(c.get('round', 0) or 0) == r]
        if not part:
            continue
        lines.append(f'<b>Ronda {r}</b>')
        for c in part:
            lines.append(f'• <b>{h(c.get("name", "Jugador"))}</b>: <i>{h(c.get("text", ""))}</i>')
    return '\n'.join(lines) if lines else '<i>Aún no hay pistas.</i>'


def _v58_imp_card_text(game: Dict[str, Any]) -> str:
    chat_id = int(game.get('chat_id') or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _v110_lobby_text(game)
    active = _imp_active_players(game)
    current = _imp_current_player(game)
    ronda = int(game.get('round', 1) or 1)
    return (
        '<b>EL JUEGO DEL IMPOSTOR</b>\n'
        f'🎯 Turno actual: <b>R{ronda}</b>\n'
        f'👤 Jugador actual: {_imp_mention(current) if current else "<i>sin turno</i>"}\n'
        f'👥 Activos: <b>{len(active)}</b>\n'
        f'⚙️ {h(_v110_config_summary(chat_id, game))}\n\n'
        '<b>🧩 Pistas</b>\n'
        f'{_v110_clues_by_round(game)}'
    )


def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    if str(game.get('status') or '') == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    return InlineKeyboardMarkup([[InlineKeyboardButton('🔐 Ver palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')]])


def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    current = _imp_current_player(game)
    if not current:
        return '🎭 Sin turno.'
    chat_id = int(game.get('chat_id') or 0)
    seconds = _v110_turn_seconds(chat_id, game)
    ronda = int(game.get('round', 1) or 1)
    return (
        f'✍️ {_imp_mention(current)}, te toca R{ronda}.\n'
        'Pulsa <b>Responder pista</b> y escribe una pista corta.\n'
        f'⏱ {fmt_duration(seconds)}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]]
    can, _reason = _v61_can_accuse_now(chat_id, game)
    if can:
        rows.append([InlineKeyboardButton('🚨 Acusar a…', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


_old_v94_send_finished_result_v110 = _v94_send_finished_result
async def _v94_send_finished_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:
    if game.get('v110_finished_sent'):
        return

    game['status'] = 'finished'
    game['v110_finished_sent'] = True
    gid = int(game.get('id', 0) or 0)
    try:
        _v94_cancel_vote_task(chat_id, gid)
    except Exception:
        pass
    imp_id = int(game.get('impostor_id', 0) or 0)
    imp = _imp_player(game, imp_id) or {'id': imp_id, 'name': 'Impostor'}
    counts = _v78_vote_counts(game) if '_v78_vote_counts' in globals() else {}
    winner_side = str(game.get('winner_side') or '')
    if counts and not winner_side:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        winner_side = 'crew' if int(top_id) == imp_id else 'impostor'
    if not winner_side:
        winner_side = 'impostor'
    game['winner_side'] = winner_side
    score_txt = _imp_score_game(chat_id, game, winner_side)
    mp = game.get('v94_points') if isinstance(game.get('v94_points'), dict) else {}
    rank_lines = []
    order = sorted(mp.items(), key=lambda kv: int(kv[1].get('points', 0) or 0), reverse=True)
    medals = ['🥇','🥈','🥉']
    for i, (uid, row) in enumerate(order, 1):
        medal = medals[i-1] if i <= 3 else f'{i}.'
        pts = int(row.get('points', 0) or 0)
        reasons = '; '.join(row.get('reasons', [])[:4])
        rank_lines.append(f'{medal} <b>{h(row.get("name") or uid)}</b>: <b>{pts:+d}</b> pts' + (f' · <i>{h(reasons)}</i>' if reasons else ''))
    scoring = (
        '<b>📋 Sistema de puntuación</b>\n'
        '• Jugar +1 · no eliminado +1\n'
        '• Impostor al final +3 · acusación fallida contra otro +2 · no ser más votado +5\n'
        '• Acusar y acertar: R1 +4 / R2 +3 / R3 +2\n'
        '• Acusar y fallar: -5 y eliminado\n'
        '• No votar a tiempo: -5 y -1 adicional\n'
        '• Votación final: acertar +3 / fallar -3\n'
        '• Inocente votado: +2 por voto recibido'
    )
    txt = (
        '🎭 <b>RESULTADO · EL JUEGO DEL IMPOSTOR</b>\n\n'
        f'🔐 Palabra: <b>{h(game.get("word") or "")}</b>\n'
        f'😈 Impostor: {_imp_mention(imp)}\n'
    )
    if reason:
        txt += f'\n{reason}\n'
    txt += '\n<b>🏆 Ranking de esta partida</b>\n' + ('\n'.join(rank_lines) if rank_lines else (score_txt or 'Sin puntuación.'))
    txt += '\n\n' + scoring
    try:
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v94_vote_message_id'))
    except Exception:
        pass
    save_all_states()
    markup = InlineKeyboardMarkup([[InlineKeyboardButton('🎭 Iniciar otra partida', callback_data=f'imp|new|{chat_id}')], [InlineKeyboardButton('🏆 Ver ranking', callback_data=f'imp|ranking|{chat_id}|{gid}')]])
    img = admin_cfg(chat_id).get('imp_winner_image_file_id')
    try:
        if img:
            await context.bot.send_photo(chat_id, photo=img, caption=txt[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await context.bot.send_message(chat_id, txt[:3900], parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await context.bot.send_message(chat_id, txt[:3900], parse_mode=ParseMode.HTML, reply_markup=markup)


async def _imp_finish(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:
    await _v94_send_finished_result(context, chat_id, game, reason)


_old_impostor_callback_router_v110 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v110(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''

    if action in ('cfg','cfgset','cfgback','remind'):
        try:
            chat_id = int(parts[2]); gid = int(parts[3])
        except Exception:
            await q.answer('Partida inválida', show_alert=True); raise _V110Stop
        game = _imp_find(chat_id, gid)
        if not game or str(game.get('status')) != 'lobby':
            await q.answer('Solo se configura mientras el lobby está abierto.', show_alert=True); raise _V110Stop
        if action == 'remind':
            await context.bot.send_message(chat_id, '<b>🎭 Partida de Impostor abierta</b>\n\n¿Te apuntas?', parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🙋 Unirme', callback_data=f'imp|join|{chat_id}|{gid}')]]))
            await q.answer('Recordatorio enviado abajo ✅')
            raise _V110Stop
        if not await _v110_can_configure(context, chat_id, q.from_user.id):
            await q.answer('Solo dueño/admin puede configurar esta partida.', show_alert=True); raise _V110Stop
        if action == 'cfg':
            await q.answer()
            await q.edit_message_text('<b>⚙️ Configurar partida de Impostor</b>\n\n' + h(_v110_config_summary(chat_id, game)), parse_mode=ParseMode.HTML, reply_markup=_v110_lobby_cfg_markup(chat_id, game))
            raise _V110Stop
        if action == 'cfgback':
            await q.answer()
            await q.edit_message_text(_v110_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
            raise _V110Stop

        if len(parts) < 6:
            await q.answer('Configuración inválida', show_alert=True); raise _V110Stop
        key = parts[4]; val = parts[5]
        cfg = _v110_ensure_game_config(chat_id, game)
        if key == 'accuse':
            cfg['final_vote_only'] = False
            cfg['accuse_round'] = max(1, min(3, int(val)))
        elif key == 'final':
            cfg['final_vote_only'] = True
        elif key == 'speed':
            cfg['speed'] = 'fast' if val == 'fast' else 'normal'
        elif key == 'hot':
            cfg['hot'] = val == '1'

            game['word'] = _v110_pick_word(chat_id, bool(cfg.get('hot')))
        save_all_states()
        await q.answer('Configuración actualizada ✅')
        await q.edit_message_text('<b>⚙️ Configurar partida de Impostor</b>\n\n' + h(_v110_config_summary(chat_id, game)), parse_mode=ParseMode.HTML, reply_markup=_v110_lobby_cfg_markup(chat_id, game))

        raise _V110Stop

    if action == 'accuse_menu':
        try:
            chat_id = int(parts[2]); gid = int(parts[3])
        except Exception:
            return await _old_impostor_callback_router_v110(update, context)
        game = _imp_find(chat_id, gid)
        if game:
            ronda = int(game.get('round', 1) or 1)
            pts_ok = _v94_accuse_points(ronda, True) if '_v94_accuse_points' in globals() else {1:4,2:3,3:2}.get(ronda,2)
            await q.answer(f'Si fallas quedas eliminado. Si aciertas sumas +{pts_ok} puntos.', show_alert=True)
        return await _old_impostor_callback_router_v110(update, context)


    if action in ('join','leave'):
        try:
            chat_id = int(parts[2]); gid = int(parts[3])
        except Exception:
            return await _old_impostor_callback_router_v110(update, context)
        res = await _old_impostor_callback_router_v110(update, context)
        game = _imp_find(chat_id, gid)
        if game and str(game.get('status')) == 'lobby':
            await _v110_refresh_lobby(context, chat_id, game)
        return res

    return await _old_impostor_callback_router_v110(update, context)


_old_v58_imp_start_game_v110 = _v58_imp_start_game
async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:
    cfg = _v110_ensure_game_config(chat_id, game)
    game['chat_id'] = int(chat_id)

    game['word'] = _v110_pick_word(chat_id, bool(cfg.get('hot')))
    return await _old_v58_imp_start_game_v110(update, context, chat_id, gid, game)


_old_build_application_v110 = build_application

def build_application() -> Application:
    _v110_ensure_manual_block()
    app = _old_build_application_v110()
    app.add_handler(command_handler('impostor', impostor_command), group=-700000000)
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-700000000)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r'^cfg\|impimg'), group=-700000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.TEXT) & ~filters.COMMAND, admin_private_config_text), group=-700000000)
    logger.info('V110 Impostor PRO visual/configurable + manual del bot cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V111Stop
except Exception:
    _V111Stop = Exception


async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        raise _V111Stop
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        raise _V111Stop
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby','active','voting')), None)
    if active:

        if str(active.get('status')) == 'lobby':
            try:
                await _v110_refresh_lobby(context, chat_id, active)
            except Exception:
                pass
            await update.message.reply_html('🎭 Ya hay una sala de Impostor abierta. Usa el botón <b>Unirme</b> del mensaje fijado.')
        else:
            await update.message.reply_html('🎭 Ya hay una partida de Impostor en marcha. Termínala o cancélala antes de crear otra.')
        raise _V111Stop

    gid = _imp_next_id(chat_id)
    cfg = _v110_cfg_defaults(chat_id)
    word = _v110_pick_word(chat_id, bool(cfg.get('hot')))
    creator = update.effective_user
    game = {
        'id': gid, 'status': 'lobby', 'word': word, 'creator_id': int(creator.id), 'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1, 'turn_idx': 0, 'votes': {}, 'impostor_id': 0, 'message_id': 0, 'chat_id': chat_id,
        'v110_config': cfg,
        'v83_auto_start_sec': int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0),
    }
    img = admin_cfg(chat_id).get('imp_lobby_image_file_id')
    if img:
        msg = await update.message.reply_photo(photo=img, caption=_v110_lobby_text(game)[:1024], parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    else:
        msg = await update.message.reply_html(_v110_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)
    raise _V111Stop


def _v111_dj_status_text(chat_id: int, state: ChatState) -> str:
    cfg = admin_cfg(chat_id)
    on = str(cfg.get('dj_status_on_emoji') or '🛜 ON')
    off = str(cfg.get('dj_status_off_emoji') or '🛑 OFF')
    return on if bool(state.live_enabled) else off


def panel_text(state: ChatState) -> str:

    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is not None:
            cfg = admin_cfg(int(chat_id))
            custom = str(cfg.get('dj_panel_custom_text_html') or '').strip()
            current = 'Nada sonando'
            nxt = 'Nada en cola'
            if state.now_playing:
                current = shorten_title(Track(**state.now_playing).title, 42)
            if state.queue:
                nxt = shorten_title(Track(**state.queue[0]).title, 42)
            status = _v111_dj_status_text(int(chat_id), state)
            if custom:
                repl = {
                    '{estado}': h(status),
                    '{cancion}': h(current),
                    '{actual}': h(current),
                    '{siguiente}': h(nxt),
                    '{dj}': h(state.assigned_dj_name or 'Sin asignar'),
                    '{cola}': str(len(state.queue)),
                    '{biblioteca}': str(len(state.library)),
                }
                for k, v in repl.items():
                    custom = custom.replace(k, v)
                return custom
            dj = state.assigned_dj_name or 'Sin asignar'
            if state.now_playing:
                song_label = '💽'; song_value = current
            elif state.queue:
                song_label = '⏭️'; song_value = nxt
            else:
                song_label = '❌'; song_value = 'Nada sonando'
            return f'🔊 <b>DIRECTO</b> {h(status)} <b>{song_label}</b> <i>{h(song_value)}</i> | 🎧 DJ: <b>{h(dj)}</b>'
    except Exception:
        logger.exception('Error panel_text V111')
    try:
        return _old_panel_text_v98(state) if '_old_panel_text_v98' in globals() else '🔊 <b>DIRECTO</b>'
    except Exception:
        return '🔊 <b>DIRECTO</b>'


def _v111_panel_markup(chat_id: int) -> InlineKeyboardMarkup:

    try:
        mode = _v106_mode(chat_id) if '_v106_mode' in globals() else 'pro'
    except Exception:
        mode = 'pro'
    main = InlineKeyboardButton('🎧 DJ Fácil' if mode == 'easy' else '🎛 Mesa DJ-PRO', callback_data='dj_easy_menu' if mode == 'easy' else 'menu_panel')
    return InlineKeyboardMarkup([
        [main, InlineKeyboardButton('❤️ Me gusta', callback_data='djlike|current')],
        [InlineKeyboardButton('❌ Cerrar sesión DJ', callback_data='panel_close')],
    ])


_old_ensure_panel_v111 = ensure_panel
async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v111_panel_markup(chat_id)
        old_id = int(state.panel_message_id or 0)
        if old_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=old_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
                return
            except BadRequest as e:
                msg = str(e).lower()
                if 'message is not modified' in msg:
                    return
                if 'message to edit not found' in msg:
                    state.panel_message_id = None
                    save_all_states()
            except Exception:
                logger.exception('V111 no pudo editar panel fijado DJ; se recrea')
        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        state.panel_message_id = int(msg.message_id)
        save_all_states()
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            pass
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass


async def _v111_dj_fast_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_minimize','panel_close','menu_panel','dj_easy_menu'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    try:
        if data == 'panel_minimize':
            if not await _v106_user_can(context, chat_id, user, 'pro'):
                await q.answer('No estás autorizado para minimizar la mesa.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = True
            cfg['dj_mesa_visible'] = False
            state = get_state(chat_id)
            old = int(state.control_message_id or 0)
            state.control_message_id = None
            save_all_states()
            if old and old != int(state.panel_message_id or 0):
                try: await safe_delete(context.bot, chat_id, old)
                except Exception: pass
            await q.answer('Mesa minimizada. Pulsa Mesa DJ-PRO para volver a abrirla.', show_alert=True)
            raise _V111Stop
        if data == 'panel_close':

            await callback_router(update, context)
            raise _V111Stop
        if data == 'menu_panel':
            if not await _v106_user_can(context, chat_id, user, 'pro'):
                await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = False
            cfg['dj_mesa_visible'] = True
            cfg['dj_session_mode'] = 'pro'
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            set_control_view(state, 'home', 0)
            save_all_states()
            await q.answer()
            await ensure_panel(context.bot, chat_id)
            await _v109_send_control_panel(context.bot, chat_id, force_new=False, reset_home=False)
            raise _V111Stop
        if data == 'dj_easy_menu':
            if not await _v106_user_can(context, chat_id, user, 'easy'):
                await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = True
            cfg['dj_mesa_visible'] = False
            cfg['dj_session_mode'] = 'easy'
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            save_all_states()
            await q.answer()
            await ensure_panel(context.bot, chat_id)
            if '_v107_send_easy_panel' in globals():
                await _v107_send_easy_panel(context.bot, chat_id)
            else:
                await context.bot.send_message(chat_id, _v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
            raise _V111Stop
    except _V111Stop:
        raise
    except Exception:
        logger.exception('Error router DJ rápido V111: %s', data)
        try: await q.answer('Error en DJ. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V111Stop


