_DAILY_TONES_V113 = [
    ('random', '🎲 Aleatorio'),
    ('motivador', '💪 Motivador'),
    ('reflexivo', '🧠 Reflexivo'),
    ('familiar', '💛 Familiar'),
    ('divertido', '😄 Divertido'),
]


def _v113_tone_label(tone: str) -> str:
    return dict(_DAILY_TONES_V113).get(str(tone or 'random'), str(tone or 'random'))


def _v113_daily_custom_rows(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    rows = cfg.setdefault('daily_phrase_custom_rows', [])
    if not isinstance(rows, list):
        rows = []
        cfg['daily_phrase_custom_rows'] = rows

    old = cfg.get('daily_phrase_custom_phrases')
    if old and isinstance(old, list) and not rows:
        for item in old:
            txt = str(item or '').strip()
            if txt:
                rows.append({'text': txt, 'tone': 'motivador'})
    return rows


def _v113_daily_available_rows(chat_id: int) -> List[Dict[str, Any]]:
    rows = _v113_daily_custom_rows(chat_id)
    tone = str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random')
    if tone and tone != 'random':
        filtered = [r for r in rows if str(r.get('tone', 'motivador')) == tone]
        if filtered:
            return filtered
    return rows


_old_v113_daily_phrase_for_chat = globals().get('daily_phrase_for_chat_v30') or globals().get('daily_phrase_for_date_v15')
def daily_phrase_for_chat_v30(chat_id: int, now_ts: Optional[int] = None) -> str:
    rows = _v113_daily_available_rows(chat_id)
    if rows:
        offset = int(cfg_value(chat_id, 'daily_phrase_offset', 0) or 0)
        try:
            day_index = int((_local_dt_v15(now_ts).strftime('%j') if now_ts else _local_dt_v15(int(time.time())).strftime('%j')))
        except Exception:
            day_index = int(time.time() // 86400)
        idx = (day_index + offset) % len(rows)
        return str(rows[idx].get('text') or '').strip() or 'Hoy es un buen día para tener un gran día.'
    if callable(_old_v113_daily_phrase_for_chat):
        try:
            return _old_v113_daily_phrase_for_chat(chat_id, now_ts)
        except TypeError:
            return _old_v113_daily_phrase_for_chat(now_ts)
    return 'Hoy es un buen día para tener un gran día.'


def _v113_phrase_button_markup(chat_id: int) -> Optional[InlineKeyboardMarkup]:
    text = str(cfg_value(chat_id, 'daily_phrase_button_text', '') or '').strip()
    target = str(cfg_value(chat_id, 'daily_phrase_button_target', '') or '').strip()
    if not text or not target:
        return None
    if target.lower().startswith('cmd:') or target.startswith('/'):
        cmd = target[4:] if target.lower().startswith('cmd:') else target
        cmd = cmd.strip().lstrip('/').split()[0].lower()
        if cmd:
            return InlineKeyboardMarkup([[InlineKeyboardButton(text[:64], callback_data=f'reccmd|{int(chat_id)}|{cmd}')]])
    if target.startswith('t.me/'):
        target = 'https://' + target
    if target.startswith(('http://', 'https://', 'tg://')):
        return InlineKeyboardMarkup([[InlineKeyboardButton(text[:64], url=target)]])
    return None


def _v113_phrase_text(chat_id: int, now_ts: Optional[int] = None) -> str:
    title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')
    phrase = daily_phrase_for_chat_v30(chat_id, now_ts)
    tone = _v113_tone_label(str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random'))
    show_tone = bool(cfg_value(chat_id, 'daily_phrase_show_tone', False))
    extra = f"\n<code>{h(tone)}</code>" if show_tone else ''
    return f"<b>{h(title)}</b>{extra}\n\n<i>{h(phrase)}</i>"


async def _v113_send_daily_phrase(application_or_bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> List[int]:
    bot = getattr(application_or_bot, 'bot', application_or_bot)
    sent_ids: List[int] = []
    cfg = admin_cfg(chat_id)
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    markup = _v113_phrase_button_markup(chat_id)
    text = _v113_phrase_text(chat_id, now_ts)

    try:
        if image and image.get('file_id') and bool(cfg_value(chat_id, 'daily_phrase_image_enabled', True)):
            msg_img = await bot.send_photo(chat_id, photo=image.get('file_id'))
            await register_bot_message(chat_id, msg_img.message_id)
            sent_ids.append(int(msg_img.message_id))
        msg = await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
        await register_bot_message(chat_id, msg.message_id)
        sent_ids.append(int(msg.message_id))
        if bool(cfg_value(chat_id, 'daily_phrase_pin', False)):
            try:
                await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass
    except Exception:
        logger.exception('No se pudo enviar frase del día V113')
        raise
    return sent_ids


_old_v113_daily_phrase_maybe_send = daily_phrase_maybe_send
async def daily_phrase_maybe_send(application: Application, chat_id: int, now_ts: int) -> None:
    cfg = admin_cfg(chat_id)
    if not bool(cfg.get('daily_phrase_enabled', False)):
        return

    now_dt = _local_dt_v15(now_ts) if '_local_dt_v15' in globals() else datetime.datetime.fromtimestamp(now_ts)
    day = now_dt.strftime('%Y-%m-%d')
    start = str(cfg.get('daily_phrase_time', '10:00') or '10:00')
    repeat = bool(cfg.get('daily_phrase_repeat_enabled', False))
    every = max(15, int(cfg.get('daily_phrase_repeat_every_minutes', 60) or 60))
    until = str(cfg.get('daily_phrase_repeat_until', start) or start)
    def _mins(v: str) -> int:
        try:
            h0,m0 = [int(x) for x in str(v).split(':',1)]
            return h0*60+m0
        except Exception:
            return 0
    now_min = now_dt.hour*60 + now_dt.minute
    start_min = _mins(start)
    until_min = _mins(until)
    if not repeat:
        slot = f'{day}:{start}'
        if cfg.get('daily_phrase_last_key') == slot or now_min < start_min:
            return
    else:
        if now_min < start_min or now_min > until_min:
            return
        slot_index = (now_min - start_min) // every
        slot_min = start_min + slot_index * every
        slot = f'{day}:{slot_min}'
        if cfg.get('daily_phrase_last_key') == slot:
            return
    if cfg.get('daily_phrase_sending_key') == slot:
        return
    cfg['daily_phrase_sending_key'] = slot
    cfg['daily_phrase_last_key'] = slot
    cfg['daily_phrase_last_sent_ts'] = int(now_ts)
    save_all_states()
    try:
        await _v113_send_daily_phrase(application, chat_id, now_ts=now_ts)
    except Exception:
        cfg['daily_phrase_last_key'] = ''
        save_all_states()
        raise
    finally:
        cfg['daily_phrase_sending_key'] = ''
        save_all_states()


async def daily_phrase_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        await update.message.reply_html('Usa <code>/frasedia</code> dentro del grupo o configúralo desde <code>/ajustes</code>.')
        return
    await _v113_send_daily_phrase(context.bot, chat_id, force=True)


