_old_v113_admin_private_config_callback = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|'):
        parts = data.split('|')
        action = parts[1] if len(parts) > 1 else ''
        try:
            chat_id = int(parts[2]) if len(parts) > 2 and parts[2].lstrip('-').isdigit() else 0
        except Exception:
            chat_id = 0
        async def _show_phrase():
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        try:
            if action == 'phrase_send':
                await _v113_send_daily_phrase(context.bot, chat_id, now_ts=int(time.time()), force=True)
                await q.answer('Frase enviada ✅')
                await _show_phrase()
                raise _V113Stop
            if action == 'phrase_tone' and len(parts) >= 4:
                tone = parts[3]
                if tone not in dict(_DAILY_TONES_V113):
                    await q.answer('Tono no válido', show_alert=True); raise _V113Stop
                cfg_set(chat_id, 'daily_phrase_tone', tone)
                await q.answer('Tono actualizado ✅')
                await _show_phrase()
                raise _V113Stop
            if action == 'phrase_image_set':
                set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_image_v113', 'chat_id': chat_id})
                await q.answer()
                await q.edit_message_text('🖼 Envíame la imagen que quieres poner encima de la frase del día.\n\nPuede ser una foto normal enviada aquí al privado.', parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]]))
                raise _V113Stop
            if action == 'phrase_image_clear':
                cfg = admin_cfg(chat_id)
                cfg.pop('daily_phrase_image', None)
                save_all_states()
                await q.answer('Imagen quitada ✅')
                await _show_phrase()
                raise _V113Stop
            if action == 'phrase_button_set':
                set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_button_v113', 'chat_id': chat_id})
                await q.answer()
                await q.edit_message_text('🔘 Envíame el botón en este formato:\n\n<code>Texto del botón=https://t.me/...</code>\n\nTambién admite:\n<code>Texto del botón=cmd:comando</code>', parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]]))
                raise _V113Stop
            if action == 'phrase_button_clear':
                cfg_set(chat_id, 'daily_phrase_button_text', '')
                cfg_set(chat_id, 'daily_phrase_button_target', '')
                await q.answer('Botón quitado ✅')
                await _show_phrase()
                raise _V113Stop
            if action == 'phrase_bulk_add':
                tone = str(cfg_value(chat_id, 'daily_phrase_tone', 'motivador') or 'motivador')
                if tone == 'random':
                    tone = 'motivador'
                set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_bulk_v113', 'chat_id': chat_id, 'tone': tone})
                await q.answer()
                await q.edit_message_text(
                    f'➕ <b>Añadir frases masivas</b>\n\nTono que se asignará: <b>{h(_v113_tone_label(tone))}</b>\n\nPega las frases, una por línea.\nNo voy a meter ninguna frase por defecto: solo se guardan las que tú envíes.',
                    parse_mode=ParseMode.HTML,
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
                )
                raise _V113Stop
            if action == 'phrase_bulk_clear':
                cfg = admin_cfg(chat_id)
                cfg['daily_phrase_custom_rows'] = []
                cfg['daily_phrase_custom_phrases'] = []
                save_all_states()
                await q.answer('Frases propias borradas ✅')
                await _show_phrase()
                raise _V113Stop
        except _V113Stop:
            raise
        except Exception:
            logger.exception('Error V113 frase día callback: %s', data)
            try:
                await q.answer('Error. Revisa logs.', show_alert=True)
            except Exception:
                pass
            raise _V113Stop
    return await _old_v113_admin_private_config_callback(update, context)


_old_v113_admin_private_config_text = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending:
            kind = pending.get('kind')
            chat_id = int(pending.get('chat_id') or 0)
            if kind == 'cfg_phrase_image_v113':
                if not update.message.photo:
                    await update.message.reply_html('❌ Envíame una foto, no texto.')
                    return True
                file_id = update.message.photo[-1].file_id
                cfg = admin_cfg(chat_id)
                cfg['daily_phrase_image'] = {'type': 'photo', 'file_id': file_id, 'set_by': int(update.effective_user.id), 'set_ts': int(time.time())}
                cfg['daily_phrase_image_enabled'] = True
                save_all_states(); pop_config_pending(update.effective_user.id)
                await update.message.reply_html('✅ Imagen actualizada.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
                return True
            if kind == 'cfg_phrase_button_v113':
                raw = plain_text_from_message(update.message).strip()
                if '=' not in raw:
                    await update.message.reply_html('Formato inválido. Usa <code>Texto=https://...</code> o <code>Texto=cmd:comando</code>.')
                    return True
                label, target = [x.strip() for x in raw.split('=', 1)]
                if not label or not target:
                    await update.message.reply_html('Falta texto o destino del botón.')
                    return True
                cfg_set(chat_id, 'daily_phrase_button_text', label[:64])
                cfg_set(chat_id, 'daily_phrase_button_target', target[:500])
                pop_config_pending(update.effective_user.id)
                await update.message.reply_html('✅ Botón actualizado.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
                return True
            if kind == 'cfg_phrase_bulk_v113':
                raw = plain_text_from_message(update.message)
                tone = str(pending.get('tone') or 'motivador')
                lines = []
                seen = {str(r.get('text','')).strip().lower() for r in _v113_daily_custom_rows(chat_id)}
                for line in raw.splitlines():
                    txt = line.strip(' \t•-*0123456789.)')
                    txt = ' '.join(txt.split())
                    if not txt:
                        continue
                    key = txt.lower()
                    if key in seen:
                        continue
                    seen.add(key)
                    lines.append({'text': txt[:500], 'tone': tone})
                if not lines:
                    await update.message.reply_html('No he detectado frases nuevas. Pega una frase por línea.')
                    return True
                rows = _v113_daily_custom_rows(chat_id)
                rows.extend(lines)
                save_all_states(); pop_config_pending(update.effective_user.id)
                await update.message.reply_html(f'✅ Añadidas <b>{len(lines)}</b> frases al tono <b>{h(_v113_tone_label(tone))}</b>.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
                return True
    return await _old_v113_admin_private_config_text(update, context)


_old_build_application_v113 = build_application

def build_application() -> Application:
    app = _old_build_application_v113()
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r'^cfg\|phrase_'), group=-920000000)
    app.add_handler(MessageHandler((filters.PHOTO | filters.TEXT) & ~filters.COMMAND, admin_private_config_text), group=-920000000)
    app.add_handler(command_handler('frasedia', daily_phrase_command), group=-920000000)
    logger.info('V113 frase del día imagen/botón/frases masivas/tonos cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V114Stop
except Exception:
    _V114Stop = Exception


def _v114_phrase_key(text: str) -> str:
    return ' '.join(str(text or '').strip().lower().split())[:220]


def _v114_phrase_likes_store(chat_id: int) -> Dict[str, Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    store = cfg.setdefault('daily_phrase_likes', {})
    if not isinstance(store, dict):
        store = {}
        cfg['daily_phrase_likes'] = store
    return store


def _v114_phrase_likes_count(chat_id: int, phrase: str) -> int:
    key = _v114_phrase_key(phrase)
    data = _v114_phrase_likes_store(chat_id).get(key, {})
    users = data.get('users') if isinstance(data, dict) else []
    return len(users) if isinstance(users, list) else 0


def _v114_sent_store(chat_id: int) -> Dict[str, Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    store = cfg.setdefault('daily_phrase_sent_messages', {})
    if not isinstance(store, dict):
        store = {}
        cfg['daily_phrase_sent_messages'] = store
    return store


def _v114_phrase_caption(chat_id: int, phrase: str) -> str:
    title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')
    tone = _v113_tone_label(str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random')) if '_v113_tone_label' in globals() else ''
    show_tone = bool(cfg_value(chat_id, 'daily_phrase_show_tone', False))
    extra = f"\n<code>{h(tone)}</code>" if show_tone and tone else ''
    likes = _v114_phrase_likes_count(chat_id, phrase)
    text = f"<b>{h(title)}</b>{extra}\n\n<i>{h(phrase)}</i>\n\n❤️ Me gusta: <b>{likes}</b>"

    return text[:1000]


def _v114_phrase_markup(chat_id: int, message_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton('⏭ Otra frase', callback_data=f'dphrase|next|{int(chat_id)}|{int(message_id)}'), InlineKeyboardButton('❤️ Me gusta', callback_data=f'dphrase|like|{int(chat_id)}|{int(message_id)}')]])


def _v114_top_liked_text(chat_id: int) -> str:
    store = _v114_phrase_likes_store(chat_id)
    rows=[]
    for data in store.values():
        if not isinstance(data, dict):
            continue
        text = str(data.get('text') or '').strip()
        users = data.get('users') if isinstance(data.get('users'), list) else []
        if text and users:
            rows.append((len(users), text))
    rows.sort(key=lambda x: x[0], reverse=True)
    if not rows:
        return '<b>🏆 Frases con más me gusta</b>\n\nTodavía no hay votos.'
    lines=['<b>🏆 Frases con más me gusta</b>\n']
    medals=['🥇','🥈','🥉']
    for i,(count,text) in enumerate(rows[:15],1):
        prefix=medals[i-1] if i<=3 else f'{i}.'
        lines.append(f'{prefix} ❤️ <b>{count}</b> · <i>{h(text[:180])}</i>')
    return '\n'.join(lines)


async def _v114_update_daily_phrase_message(bot, chat_id: int, message_id: int) -> None:
    entry = _v114_sent_store(chat_id).get(str(message_id))
    if not isinstance(entry, dict):
        return
    phrase = str(entry.get('phrase') or daily_phrase_for_chat_v30(chat_id))
    markup = _v114_phrase_markup(chat_id, message_id)
    caption = _v114_phrase_caption(chat_id, phrase)
    try:
        if entry.get('kind') == 'photo':
            await bot.edit_message_caption(chat_id=chat_id, message_id=message_id, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        logger.exception('No se pudo actualizar frase del día V114')


async def _v113_send_daily_phrase(application_or_bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> List[int]:
    bot = getattr(application_or_bot, 'bot', application_or_bot)
    cfg = admin_cfg(chat_id)
    phrase = daily_phrase_for_chat_v30(chat_id, now_ts)
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    caption = _v114_phrase_caption(chat_id, phrase)
    sent_ids: List[int] = []
    try:
        if image and image.get('file_id') and bool(cfg_value(chat_id, 'daily_phrase_image_enabled', True)):
            msg = await bot.send_photo(chat_id, photo=image.get('file_id'), caption=caption, parse_mode=ParseMode.HTML)
            kind = 'photo'
        else:
            msg = await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
            kind = 'text'
        await register_bot_message(chat_id, msg.message_id)
        sent_ids.append(int(msg.message_id))
        store = _v114_sent_store(chat_id)
        store[str(msg.message_id)] = {'phrase': phrase, 'kind': kind, 'next_used': [], 'sent_ts': int(time.time())}
        save_all_states()
        try:
            await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v114_phrase_markup(chat_id, msg.message_id))
        except Exception:
            pass
        if bool(cfg_value(chat_id, 'daily_phrase_pin', False)):
            try:
                await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass
    except Exception:
        logger.exception('No se pudo enviar frase del día V114')
        raise
    return sent_ids


async def _v114_daily_phrase_button_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    parts=(q.data or '').split('|')
    if len(parts) < 4:
        return
    action=parts[1]
    try:
        chat_id=int(parts[2]); msg_id=int(parts[3])
    except Exception:
        await q.answer('Botón inválido.', show_alert=True); raise _V114Stop
    store=_v114_sent_store(chat_id)
    entry=store.get(str(msg_id))
    if not isinstance(entry, dict):
        await q.answer('Esta frase ya no está activa.', show_alert=True); raise _V114Stop
    uid=str(int(q.from_user.id))
    phrase=str(entry.get('phrase') or daily_phrase_for_chat_v30(chat_id))
    try:
        if action == 'like':
            key=_v114_phrase_key(phrase)
            likes=_v114_phrase_likes_store(chat_id)
            data=likes.setdefault(key, {'text': phrase, 'users': []})
            users=data.setdefault('users', [])
            if uid not in users:
                users.append(uid)
                data['text']=phrase
                save_all_states()
                await _v114_update_daily_phrase_message(context.bot, chat_id, msg_id)
                await q.answer('❤️ Me gusta añadido')
            else:
                await q.answer('Ya habías dado me gusta ❤️')
            raise _V114Stop
        if action == 'next':
            used=entry.setdefault('next_used', [])
            if uid in used:
                await q.answer('Solo puedes cambiar esta frase una vez.', show_alert=True)
                raise _V114Stop
            used.append(uid)
            cfg_set(chat_id, 'daily_phrase_offset', int(cfg_value(chat_id, 'daily_phrase_offset', 0) or 0) + 1)
            new_phrase=daily_phrase_for_chat_v30(chat_id)
            entry['phrase']=new_phrase
            entry['changed_by']=int(q.from_user.id)
            entry['changed_ts']=int(time.time())
            save_all_states()
            await _v114_update_daily_phrase_message(context.bot, chat_id, msg_id)
            await q.answer('Frase cambiada ✨')
            raise _V114Stop
    except _V114Stop:
        raise
    except Exception:
        logger.exception('Error en botones frase del día V114')
        try:
            await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V114Stop


