def _v115_pregonero_mentions(chat_id: int) -> int:
    try:
        return max(1, min(20, int(cfg_value(chat_id, 'pregonero_max_mentions_per_message', 4) or 4)))
    except Exception:
        return 4


def _v115_pregonero_delay(chat_id: int) -> float:
    try:
        return max(0.0, min(10.0, float(cfg_value(chat_id, 'pregonero_delay_seconds', 0.6) or 0.6)))
    except Exception:
        return 0.6


def _v115_delay_label(seconds: float) -> str:
    try:
        sec = float(seconds)
    except Exception:
        sec = 0.6
    if sec <= 0:
        return 'sin pausa'
    if sec < 1:
        return f'{sec:.1f}s'
    return f'{sec:g}s'


async def _v115_send_pregonero_same_message(bot, chat_id: int, text: str, *, reply_to_message_id: Optional[int] = None) -> Optional[int]:
    """Pregonero siempre en un único mensaje cuando hay multimedia.

    Telegram solo permite multimedia+texto en el mismo mensaje usando caption.
    Para evitar dos mensajes, mandamos la imagen/vídeo/documento con caption y botones.
    """
    media = cfg_value(chat_id, 'pregonero_media', None)
    markup = build_config_buttons_keyboard(chat_id, 'pregonero_buttons')
    has_media = isinstance(media, dict) and media.get('file_id')
    if has_media:

        caption = str(text or '')
        if len(caption) > 1000:
            caption = caption[:960].rstrip() + '\n\n…'
        sent_id = await send_media_blob(bot, chat_id, media, caption=caption, reply_markup=markup, reply_to_message_id=reply_to_message_id)
        if sent_id:
            return sent_id
    msg = await bot.send_message(
        chat_id=chat_id,
        text=text,
        parse_mode=ParseMode.HTML,
        reply_markup=markup,
        reply_to_message_id=reply_to_message_id,
        allow_sending_without_reply=True,
        disable_web_page_preview=True,
    )
    return getattr(msg, 'message_id', None)


async def send_pregonero(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, title: str = '') -> None:
    mentions = known_pregonero_mentions(chat_id)
    if not mentions:
        await send_temp_message(context.bot, chat_id, '📣 No tengo usuarios registrados todavía para mencionar.', ttl=40)
        return
    max_per_message = _v115_pregonero_mentions(chat_id)
    delay = _v115_pregonero_delay(chat_id)
    template = str(cfg_value(chat_id, 'pregonero_text', '📣 <b>EL PLAN TE LLAMA</b>\n\n{mentions}'))
    if title:
        template = title + '\n\n{mentions}'
    total_blocks = ((len(mentions) - 1) // max_per_message) + 1
    for idx, start in enumerate(range(0, len(mentions), max_per_message), 1):
        chunk = mentions[start:start + max_per_message]
        text = (
            template
            .replace('{mentions}', ' '.join(chunk))
            .replace('{count}', str(len(chunk)))
            .replace('{total}', str(len(mentions)))
            .replace('{bloque}', str(idx))
            .replace('{bloques}', str(total_blocks))
        )
        await _v115_send_pregonero_same_message(context.bot, chat_id, text)
        if delay > 0 and idx < total_blocks:
            await asyncio.sleep(delay)
    add_action_log(chat_id, 'pregonero', f'{len(mentions)} menciones en bloques de {max_per_message}, pausa {_v115_delay_label(delay)}')


_old_v115_send_configured_profile_message = send_configured_profile_message
async def send_configured_profile_message(bot, chat_id: int, profile: str, text: str, *, reply_to_message_id: Optional[int] = None) -> Optional[int]:
    if profile == 'pregonero':
        return await _v115_send_pregonero_same_message(bot, chat_id, text, reply_to_message_id=reply_to_message_id)
    return await _old_v115_send_configured_profile_message(bot, chat_id, profile, text, reply_to_message_id=reply_to_message_id)


_old_v115_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    text = _old_v115_admin_private_block_text(chat_id, block, page)
    if block == 'pregonero':
        mentions = _v115_pregonero_mentions(chat_id)
        delay = _v115_pregonero_delay(chat_id)
        total_users = len(known_pregonero_mentions(chat_id))
        blocks = ((total_users - 1) // mentions) + 1 if total_users else 0
        approx = max(0.0, (blocks - 1) * delay)
        extra = (
            '\n\n<b>⚙️ Ritmo del pregonero</b>'
            f'\nMenciones por mensaje: <b>{mentions}</b>'
            f'\nPausa entre mensajes: <b>{h(_v115_delay_label(delay))}</b>'
            f'\nBloques estimados: <b>{blocks}</b>'
            f'\nTiempo total estimado: <b>{h(_v115_delay_label(approx))}</b>'
            '\n<i>La imagen y el texto del pregonero se envían juntos en el mismo mensaje.</i>'
        )
        if '<b>⚙️ Ritmo del pregonero</b>' not in text:
            text += extra
    return text


_old_v115_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v115_admin_private_block_markup(chat_id, block, page)
    if block != 'pregonero':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    mentions = _v115_pregonero_mentions(chat_id)
    delay = _v115_pregonero_delay(chat_id)
    controls = [
        [
            InlineKeyboardButton('➖ menciones', callback_data=f'cfg|pregonero_mentions_delta|{chat_id}|-1|pregonero'),
            InlineKeyboardButton(f'👥 {mentions} por mensaje', callback_data=f'cfg|noop|{chat_id}|pregonero'),
            InlineKeyboardButton('➕ menciones', callback_data=f'cfg|pregonero_mentions_delta|{chat_id}|1|pregonero'),
        ],
        [
            InlineKeyboardButton('⚡ Sin pausa', callback_data=f'cfg|pregonero_delay_set|{chat_id}|0|pregonero'),
            InlineKeyboardButton('🚀 0.3s', callback_data=f'cfg|pregonero_delay_set|{chat_id}|0.3|pregonero'),
            InlineKeyboardButton('⏱ 0.6s', callback_data=f'cfg|pregonero_delay_set|{chat_id}|0.6|pregonero'),
        ],
        [
            InlineKeyboardButton('🐢 1s', callback_data=f'cfg|pregonero_delay_set|{chat_id}|1|pregonero'),
            InlineKeyboardButton('🐌 2s', callback_data=f'cfg|pregonero_delay_set|{chat_id}|2|pregonero'),
            InlineKeyboardButton(f'Actual: {_v115_delay_label(delay)}', callback_data=f'cfg|noop|{chat_id}|pregonero'),
        ],
    ]

    insert_at = max(0, len(rows) - 1)
    for r in reversed(controls):
        rows.insert(insert_at, r)
    return InlineKeyboardMarkup(rows)


_old_v115_admin_private_config_callback = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|pregonero_'):
        parts = data.split('|')
        action = parts[1] if len(parts) > 1 else ''
        try:
            chat_id = int(parts[2])
            if action == 'pregonero_mentions_delta':
                delta = int(parts[3])
                current = _v115_pregonero_mentions(chat_id)
                new_value = max(1, min(20, current + delta))
                cfg_set(chat_id, 'pregonero_max_mentions_per_message', new_value)
                await q.answer(f'Menciones por mensaje: {new_value}')
                await q.edit_message_text(admin_private_block_text(chat_id, 'pregonero'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'pregonero'))
                raise _V115Stop
            if action == 'pregonero_delay_set':
                delay = max(0.0, min(10.0, float(parts[3])))
                cfg_set(chat_id, 'pregonero_delay_seconds', delay)
                await q.answer(f'Pausa: {_v115_delay_label(delay)}')
                await q.edit_message_text(admin_private_block_text(chat_id, 'pregonero'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'pregonero'))
                raise _V115Stop
        except _V115Stop:
            raise
        except Exception:
            logger.exception('Error callback pregonero V115: %s', data)
            try:
                await q.answer('Error. Revisa logs.', show_alert=True)
            except Exception:
                pass
            raise _V115Stop
    return await _old_v115_admin_private_config_callback(update, context)


