async def _v116_send_profile_data_message(bot, chat_id: int, profile: Dict[str, Any], text: str, *, reply_to_message_id: Optional[int] = None) -> Optional[int]:
    """Envía cualquier perfil de pregonero en un único mensaje si hay multimedia.

    Telegram solo permite texto+multimedia en el mismo mensaje mediante caption.
    Por eso, tanto pregonero base como automáticos antiguos/nuevos se envían así.
    """
    media = profile.get('media') if isinstance(profile.get('media'), dict) else None
    markup = _v116_profile_markup(profile)
    has_media = isinstance(media, dict) and media.get('file_id')
    if has_media:
        caption = str(text or '')
        if len(caption) > 1000:
            caption = caption[:960].rstrip() + '\n\n…'
        try:
            sent_id = await send_media_blob(
                bot,
                chat_id,
                media,
                caption=caption,
                reply_markup=markup,
                reply_to_message_id=reply_to_message_id,
            )
            if sent_id:
                return sent_id
        except TypeError:

            sent_id = await send_media_blob(bot, chat_id, media, caption=caption, reply_markup=markup)
            if sent_id:
                return sent_id
        except Exception:
            logger.exception('No se pudo enviar pregonero con multimedia en un mensaje')
    msg = await bot.send_message(
        chat_id=chat_id,
        text=str(text or ''),
        parse_mode=ParseMode.HTML,
        reply_markup=markup,
        reply_to_message_id=reply_to_message_id,
        allow_sending_without_reply=True,
        disable_web_page_preview=True,
    )
    return getattr(msg, 'message_id', None)


_v31_send_profile_data_message = _v116_send_profile_data_message


async def _v116_send_pregonero_with_profile(context: ContextTypes.DEFAULT_TYPE, chat_id: int, profile: Dict[str, Any], *, title: str = '') -> None:
    mentions = known_pregonero_mentions(chat_id)
    if not mentions:
        await send_temp_message(context.bot, chat_id, '📣 No tengo usuarios registrados todavía para mencionar.', ttl=40)
        return
    max_per_message = _v115_pregonero_mentions(chat_id) if '_v115_pregonero_mentions' in globals() else 4
    delay = _v115_pregonero_delay(chat_id) if '_v115_pregonero_delay' in globals() else 0.6
    template = str(profile.get('text') or cfg_value(chat_id, 'pregonero_text', '📣 <b>EL PLAN TE LLAMA</b>\n\n{mentions}'))
    if title:
        template = title + '\n\n{mentions}'
    total_blocks = ((len(mentions) - 1) // max_per_message) + 1
    for idx, start in enumerate(range(0, len(mentions), max_per_message), 1):
        chunk = mentions[start:start + max_per_message]
        text = (
            template
            .replace('{mentions}', ' '.join(chunk))
            .replace('{count}', str(len(chunk)))
            .replace('{total}', str(len(mentions)))
            .replace('{bloque}', str(idx))
            .replace('{bloques}', str(total_blocks))
        )
        await _v116_send_profile_data_message(context.bot, chat_id, profile, text)
        if delay > 0 and idx < total_blocks:
            await asyncio.sleep(delay)
    add_action_log(chat_id, 'pregonero', f'{len(mentions)} menciones en bloques de {max_per_message}, pausa {_v115_delay_label(delay) if "_v115_delay_label" in globals() else delay}')


async def send_pregonero(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, title: str = '', job: Optional[Dict[str, Any]] = None) -> None:

    if job and isinstance(job, dict):
        profile = _v31_job_profile(job, chat_id) if '_v31_job_profile' in globals() else job.get('profile', {})
        if isinstance(profile, dict):
            await _v116_send_pregonero_with_profile(context, chat_id, profile, title=title)
