def _v117_minimized_text(chat_id: int) -> str:
    st = get_state(chat_id)
    current = 'Nada sonando'
    nxt = 'Nada en cola'
    try:
        if st.now_playing:
            current = shorten_title(Track(**st.now_playing).title, 42)
        if st.queue:
            nxt = shorten_title(Track(**st.queue[0]).title, 42)
    except Exception:
        pass
    return (
        '<b>🎛 MESA DJ-PRO MINIMIZADA</b>\n\n'
        f'▶️ Actual: <b>{h(current)}</b>\n'
        f'⏭ Próxima: <b>{h(nxt)}</b>\n\n'
        'Pulsa <b>Mostrar mesa</b> para recuperar esta misma mesa.'
    )


def _v117_minimized_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎛 Mostrar mesa DJ-PRO', callback_data='menu_panel')],
        [InlineKeyboardButton('❌ Cerrar sesión DJ', callback_data='panel_close')],
    ])


async def _v117_edit_or_send(bot, chat_id: int, message_id: int, text: str, markup: Optional[InlineKeyboardMarkup]) -> int:
    if message_id:
        try:
            await bot.edit_message_text(chat_id=chat_id, message_id=int(message_id), text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            return int(message_id)
        except BadRequest as e:
            low = str(e).lower()
            if 'message is not modified' in low:
                return int(message_id)
            if 'message to edit not found' not in low:
                logger.warning('V117 edit_or_send BadRequest no fatal: %s', e)
        except Exception:
            logger.exception('V117 no pudo editar mensaje; se recrea')
    msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    return int(msg.message_id)


async def _v117_send_control_panel(bot, chat_id: int, *, reset_home: bool = False, force_show: bool = False) -> Optional[int]:
    state = get_state(chat_id)
    state.dj_mode = True


    if _v117_is_pro_minimized(chat_id) and not force_show:
        if state.control_message_id:
            mid = await _v117_edit_or_send(bot, chat_id, int(state.control_message_id), _v117_minimized_text(chat_id), _v117_minimized_markup())
            state.control_message_id = mid
            save_all_states()
            return mid
        return None

    _v117_mark_pro_visible(chat_id)
    if reset_home:
        set_control_view(state, 'home', 0)
    save_all_states()
    text, markup = current_control_view(state)
    mid = await _v117_edit_or_send(bot, chat_id, int(state.control_message_id or 0), text, markup)
    state.control_message_id = int(mid)
    save_all_states()
    return int(mid)


_v109_send_control_panel = _v117_send_control_panel
_v107_send_control_panel = _v117_send_control_panel


async def ensure_control_panel(bot, chat_id: int) -> None:

    try:
        if '_v106_mode' in globals() and _v106_mode(chat_id) == 'easy':
            return
    except Exception:
        pass
    if _v117_is_pro_minimized(chat_id):

        if get_state(chat_id).control_message_id:
            await _v117_send_control_panel(bot, chat_id, force_show=False)
        return
    await _v117_send_control_panel(bot, chat_id, force_show=False)


async def render_control_home(bot, chat_id: int) -> None:
    st = get_state(chat_id)
    set_control_view(st, 'home', 0)
    save_all_states()
    await _v117_send_control_panel(bot, chat_id, reset_home=False, force_show=True)


