async def _v120_delete_game_pair(bot, chat_id: int, game: Dict[str, Any]) -> None:
    ids = []
    for key in ('v58_prompt_message_id', 'v58_card_message_id', 'turn_message_id'):
        try:
            mid = int(game.get(key) or 0)
            if mid and mid not in ids:
                ids.append(mid)
        except Exception:
            pass
    for mid in ids:
        try:
            await bot.delete_message(chat_id=chat_id, message_id=int(mid))
        except Exception:
            pass


async def _v58_imp_render_down(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, delete_previous: bool = True) -> None:
    bot = context.bot
    if not game or str(game.get('status')) not in {'active', 'voting', 'lobby'}:
        return
    game['chat_id'] = int(chat_id)


    if str(game.get('status')) == 'lobby':
        ok = False
        try:
            if '_v118_edit_lobby_only' in globals():
                ok = await _v118_edit_lobby_only(context, chat_id, game)
        except Exception:
            ok = False
        if not ok:
            mid = int(game.get('message_id') or game.get('v58_card_message_id') or 0)
            mid = await _v117_edit_or_send_imp(bot, chat_id, mid, _v58_imp_card_text(game), _v58_imp_card_markup(chat_id, game))
            game['message_id'] = mid
            game['v58_card_message_id'] = mid
        save_all_states()
        return


    if str(game.get('status')) == 'voting':
        save_all_states()
        return


    new_key = _v120_render_key(game)
    old_key = str(game.get('v120_render_key') or '')

    if new_key != old_key:

        if bool(delete_previous):
            await _v120_delete_game_pair(bot, chat_id, game)
        card_mid = await _v120_send_card_new(bot, chat_id, game)
        prompt_mid = await _v120_send_prompt_new(bot, chat_id, game)
        game['v58_card_message_id'] = card_mid
        game['turn_message_id'] = card_mid
        game['v58_prompt_message_id'] = prompt_mid
        game['v119_prompt_turn_key'] = new_key
        game['v120_render_key'] = new_key
        save_all_states()
        return


    card_mid = int(game.get('v58_card_message_id') or game.get('turn_message_id') or 0)
    if card_mid:
        try:
            await bot.edit_message_text(chat_id=chat_id, message_id=card_mid, text=_v58_imp_card_text(game), parse_mode=ParseMode.HTML, reply_markup=_v58_imp_card_markup(chat_id, game))
        except BadRequest as e:
            if 'message is not modified' not in str(e).lower():
                card_mid = await _v120_send_card_new(bot, chat_id, game)
                game['v58_card_message_id'] = card_mid
                game['turn_message_id'] = card_mid
        except Exception:
            card_mid = await _v120_send_card_new(bot, chat_id, game)
            game['v58_card_message_id'] = card_mid
            game['turn_message_id'] = card_mid
    else:
        card_mid = await _v120_send_card_new(bot, chat_id, game)
        game['v58_card_message_id'] = card_mid
        game['turn_message_id'] = card_mid

    prompt_mid = int(game.get('v58_prompt_message_id') or 0)
    if prompt_mid:
        try:
            await bot.edit_message_text(chat_id=chat_id, message_id=prompt_mid, text=_v58_imp_prompt_text(game), parse_mode=ParseMode.HTML, reply_markup=_v58_imp_prompt_markup(chat_id, game))
        except BadRequest as e:
            if 'message is not modified' not in str(e).lower():
                prompt_mid = await _v120_send_prompt_new(bot, chat_id, game)
                game['v58_prompt_message_id'] = prompt_mid
        except Exception:
            prompt_mid = await _v120_send_prompt_new(bot, chat_id, game)
            game['v58_prompt_message_id'] = prompt_mid
    else:
        prompt_mid = await _v120_send_prompt_new(bot, chat_id, game)
        game['v58_prompt_message_id'] = prompt_mid

    save_all_states()


