V121_LOBBY_TIMER_TASKS: Dict[str, asyncio.Task] = {}
V121_TURN_TIMER_TASKS: Dict[str, asyncio.Task] = {}


def _v121_task_key(chat_id: int, gid: int) -> str:
    return f"{int(chat_id)}:{int(gid)}"


def _v121_game_elapsed(game: Dict[str, Any]) -> int:
    return max(0, int(time.time()) - int(game.get('created_ts') or time.time()))


def _v121_lobby_remaining(chat_id: int, game: Dict[str, Any]) -> Optional[int]:
    sec = int(game.get('v83_auto_start_sec') or cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    if sec <= 0:
        return None
    return max(0, sec - _v121_game_elapsed(game))


def _v121_turn_key(game: Dict[str, Any]) -> str:
    try:
        base = _v120_render_key(game) if '_v120_render_key' in globals() else ''
    except Exception:
        base = ''
    if not base:
        base = f"{int(game.get('id',0) or 0)}:{int(game.get('round',1) or 1)}:{int(game.get('turn_idx',0) or 0)}:{len(game.get('clues') if isinstance(game.get('clues'), list) else [])}"
    return str(base)


def _v121_turn_remaining(chat_id: int, game: Dict[str, Any]) -> int:
    seconds = int(_v110_turn_seconds(chat_id, game) if '_v110_turn_seconds' in globals() else 60)
    started = int(game.get('v121_turn_started_ts') or game.get('turn_started_ts') or time.time())
    return max(0, seconds - (int(time.time()) - started))


def _v121_player_lines(game: Dict[str, Any]) -> str:
    players = game.get('players') if isinstance(game.get('players'), list) else []
    active = _imp_active_players(game) if '_imp_active_players' in globals() else players
    active_ids = {int(p.get('id', 0) or 0) for p in active if isinstance(p, dict)}
    act_lines, elim_lines = [], []
    for p in players:
        if not isinstance(p, dict):
            continue
        if int(p.get('id', 0) or 0) in active_ids:
            act_lines.append(_imp_mention(p))
        else:
            elim_lines.append(_imp_mention(p))
    return (
        f"✅ <b>Activos:</b> {', '.join(act_lines) if act_lines else '<i>ninguno</i>'}\n"
        f"❌ <b>Eliminados:</b> {', '.join(elim_lines) if elim_lines else '<i>ninguno</i>'}"
    )


def _v110_lobby_text(game: Dict[str, Any]) -> str:
    chat_id = int(game.get('chat_id') or 0)
    players = game.get('players') if isinstance(game.get('players'), list) else []
    rem = _v121_lobby_remaining(chat_id, game)
    if rem is None:
        rem_line = '⏱ Auto-inicio lobby: <b>OFF</b>'
    else:
        rem_line = f'⏱ Inicio automático: <b>{fmt_duration(rem)}</b>'
    return (
        '<b>🎭 EL JUEGO DEL IMPOSTOR</b>\n\n'
        'Sala abierta. Entra y espera al inicio.\n\n'
        f'👥 Jugadores: <b>{len(players)}</b>\n'
        f'{_v110_players_lines(game)}\n\n'
        f'⚙️ <b>Configuración:</b> {h(_v110_config_summary(chat_id, game))}\n'
        f'{rem_line}\n\n'
        '<i>Mínimo 3 jugadores para empezar.</i>'
    )


def _imp_lobby_text(game: Dict[str, Any]) -> str:
    return _v110_lobby_text(game)


def _v83_lobby_public_text(game: Dict[str, Any]) -> str:
    return _v110_lobby_text(game)


def _v110_lobby_cfg_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    cfg = _v110_ensure_game_config(chat_id, game)
    acc = int(cfg.get('accuse_round') or 1)
    final_only = bool(cfg.get('final_vote_only'))
    speed = str(cfg.get('speed') or 'normal')
    hot = bool(cfg.get('hot'))
    def chk(cond: bool, label: str) -> str:
        return ('✅ ' if cond else '') + label
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(chk(not final_only and acc == 1, 'Acusar R1'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|1'), InlineKeyboardButton(chk(not final_only and acc == 2, 'Acusar R2'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|2'), InlineKeyboardButton(chk(not final_only and acc == 3, 'Acusar R3'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|3')],
        [InlineKeyboardButton(chk(final_only, 'Solo votación final R3'), callback_data=f'imp|cfgset|{chat_id}|{gid}|final|1')],
        [InlineKeyboardButton(chk(speed == 'normal', 'Normal · 2 min'), callback_data=f'imp|cfgset|{chat_id}|{gid}|speed|normal'), InlineKeyboardButton(chk(speed == 'fast', 'Rápido · 1 min'), callback_data=f'imp|cfgset|{chat_id}|{gid}|speed|fast')],
        [InlineKeyboardButton(chk(not hot, 'Modo normal'), callback_data=f'imp|cfgset|{chat_id}|{gid}|hot|0'), InlineKeyboardButton(chk(hot, 'Modo HOT 🔥'), callback_data=f'imp|cfgset|{chat_id}|{gid}|hot|1')],
        [InlineKeyboardButton('✅ Confirmar configuración', callback_data=f'imp|cfgconfirm|{chat_id}|{gid}')],
        [InlineKeyboardButton('🔙 Volver al lobby', callback_data=f'imp|cfgback|{chat_id}|{gid}')],
    ])


def _v110_clues_by_round(game: Dict[str, Any]) -> str:
    clues = game.get('clues') if isinstance(game.get('clues'), list) else []
    lines: List[str] = []
    for r in (1, 2, 3):
        lines.append(f'<b>RONDA {r}</b>')
        part = [c for c in clues if int(c.get('round', 0) or 0) == r]
        if not part:
            lines.append('• <i>Sin pistas todavía.</i>')
        else:
            for c in part:
                if c.get('system'):
                    lines.append(f'• <i>{h(c.get("text", ""))}</i>')
                else:
                    lines.append(f'• <b>{h(c.get("name", "Jugador"))}</b>: <i>{h(c.get("text", ""))}</i>')
        lines.append('')
    return '\n'.join(lines).strip()


def _v58_imp_card_text(game: Dict[str, Any]) -> str:
    chat_id = int(game.get('chat_id') or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _v110_lobby_text(game)
    active = _imp_active_players(game) if '_imp_active_players' in globals() else []
    current = _imp_current_player(game) if '_imp_current_player' in globals() else None
    ronda = int(game.get('round', 1) or 1)
    can_accuse, _reason = _v61_can_accuse_now(chat_id, game) if '_v61_can_accuse_now' in globals() else (False, '')
    extra = ''
    if can_accuse and status == 'active':
        extra += '\n\n<b>🚨 EN ESTE MOMENTO YA SE PUEDE ACUSAR.</b>'
    if status == 'voting':
        extra += '\n\n<b>🗳 FIN DE LA RONDA 3. ¡VAMOS A VOTAR!</b>'
    return (
        '<b>EL JUEGO DEL IMPOSTOR</b>\n'
        f'🎯 Turno: <b>RONDA {ronda}</b>\n'
        f'👤 Jugador actual: {_imp_mention(current) if current else "<i>sin turno</i>"}\n'
        f'👥 Activos: <b>{len(active)}</b>\n'
        f'⚙️ {h(_v110_config_summary(chat_id, game))}\n\n'
        f'{_v121_player_lines(game)}\n\n'
        '<b>🧩 Pistas</b>\n'
        f'{_v110_clues_by_round(game)}'
        f'{extra}'
    )


def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:
    current = _imp_current_player(game) if '_imp_current_player' in globals() else None
    if not current:
        return '🎭 Sin turno.'
    chat_id = int(game.get('chat_id') or 0)
    ronda = int(game.get('round', 1) or 1)
    rem = _v121_turn_remaining(chat_id, game)
    return (
        f'✍️ {_imp_mention(current)}, te toca R{ronda}.\n'
        'Pulsa <b>Responder pista</b> y escribe una pista corta.\n'
        f'⏱ {fmt_duration(rem)}'
    )


async def _v121_edit_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    try:
        if '_v118_edit_lobby_only' in globals():
            ok = await _v118_edit_lobby_only(context, chat_id, game)
            if ok:
                return
    except Exception:
        pass
    try:
        mid = int(game.get('message_id') or 0)
        if mid:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v110_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    except Exception:
        pass


def _v121_cancel_lobby_watch(chat_id: int, gid: int) -> None:
    key = _v121_task_key(chat_id, gid)
    task = V121_LOBBY_TIMER_TASKS.pop(key, None)
    if task and not task.done():
        task.cancel()


def _v121_start_lobby_watch(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    gid = int(game.get('id', 0) or 0)
    if not gid:
        return
    key = _v121_task_key(chat_id, gid)
    old = V121_LOBBY_TIMER_TASKS.get(key)
    if old and not old.done():
        return
    V121_LOBBY_TIMER_TASKS[key] = asyncio.create_task(_v121_lobby_watch_loop(context, chat_id, gid))


async def _v121_lobby_watch_loop(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int) -> None:
    warned = False
    try:
        while True:
            await asyncio.sleep(15)
            game = _imp_find(chat_id, gid) if '_imp_find' in globals() else None
            if not game or str(game.get('status')) != 'lobby':
                return
            rem = _v121_lobby_remaining(chat_id, game)
            await _v121_edit_lobby(context, chat_id, game)
            if rem is not None and rem <= 30 and rem > 0 and not warned:
                warned = True
                try:
                    await context.bot.send_message(chat_id, '🎭⏳ <b>La partida se iniciará en 30 segundos.</b>\nÚltima llamada para apuntarse.', parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            if rem is not None and rem <= 0:
                return
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error watcher lobby Impostor V121')


def _v121_cancel_turn_watch(chat_id: int, gid: int) -> None:
    key = _v121_task_key(chat_id, gid)
    task = V121_TURN_TIMER_TASKS.pop(key, None)
    if task and not task.done():
        task.cancel()


def _v121_start_turn_watch(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    gid = int(game.get('id', 0) or 0)
    if not gid or str(game.get('status')) != 'active':
        return
    key = _v121_task_key(chat_id, gid)
    old = V121_TURN_TIMER_TASKS.get(key)
    tkey = _v121_turn_key(game)
    if old and not old.done() and str(game.get('v121_timer_key')) == tkey:
        return
    if old and not old.done():
        old.cancel()
    game['v121_timer_key'] = tkey
    game.setdefault('v121_turn_started_ts', int(time.time()))
    V121_TURN_TIMER_TASKS[key] = asyncio.create_task(_v121_turn_watch_loop(context, chat_id, gid, tkey))


async def _v121_turn_watch_loop(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, tkey: str) -> None:
    warned = False
    try:
        while True:
            await asyncio.sleep(15)
            game = _imp_find(chat_id, gid) if '_imp_find' in globals() else None
            if not game or str(game.get('status')) != 'active' or str(game.get('v121_timer_key')) != tkey:
                return
            rem = _v121_turn_remaining(chat_id, game)
            mid = int(game.get('v58_prompt_message_id') or 0)
            if mid:
                try:
                    await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v58_imp_prompt_text(game), parse_mode=ParseMode.HTML, reply_markup=_v58_imp_prompt_markup(chat_id, game))
                except BadRequest as e:
                    if 'message is not modified' not in str(e).lower():
                        pass
                except Exception:
                    pass
            if rem <= 30 and rem > 0 and not warned:
                warned = True
                current = _imp_current_player(game) if '_imp_current_player' in globals() else None
                if current:
                    try:
                        await context.bot.send_message(chat_id, f'😴 {_imp_mention(current)} estás durmiendo la partida… vamos, que se acaba el tiempo.', parse_mode=ParseMode.HTML)
                    except Exception:
                        pass
            if rem <= 0:
                return
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error watcher turno Impostor V121')


_old_v121_pin_lobby = _v79_pin_lobby
async def _v79_pin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int) -> None:
    await _old_v121_pin_lobby(context, chat_id, message_id)
    try:
        game = next((g for g in _imp_games(chat_id) if str(g.get('status')) == 'lobby' and int(g.get('message_id',0) or 0) == int(message_id)), None)
        if game:
            game.setdefault('created_ts', int(time.time()))
            game['v83_auto_start_sec'] = int(game.get('v83_auto_start_sec') or cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
            _v121_start_lobby_watch(context, chat_id, game)
            save_all_states()
    except Exception:
        logger.exception('No se pudo iniciar watcher lobby V121')


_old_v121_render_down = _v58_imp_render_down
async def _v58_imp_render_down(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, delete_previous: bool = True) -> None:
    if game and str(game.get('status')) == 'active':
        tkey = _v121_turn_key(game)
        if str(game.get('v121_active_turn_key')) != tkey:
            game['v121_active_turn_key'] = tkey
            game['v121_turn_started_ts'] = int(time.time())

            game['v121_turn_30_warned'] = False
    await _old_v121_render_down(context, chat_id, game, delete_previous=delete_previous)
    if game and str(game.get('status')) == 'active':
        _v121_start_turn_watch(context, chat_id, game)
    elif game and str(game.get('status')) == 'lobby':
        _v121_start_lobby_watch(context, chat_id, game)
    save_all_states()


_old_v121_impostor_callback_router = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_v121_impostor_callback_router(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action in {'cfg','cfgset','cfgback','cfgconfirm'}:
        try:
            chat_id = int(parts[2]); gid = int(parts[3])
        except Exception:
            return await _old_v121_impostor_callback_router(update, context)
        game = _imp_find(chat_id, gid) if '_imp_find' in globals() else None
        if not game or str(game.get('status')) != 'lobby':
            await q.answer('Solo se configura mientras el lobby está abierto.', show_alert=True)
            raise _V121Stop
        if not await _v110_can_configure(context, chat_id, q.from_user.id):
            await q.answer('Solo dueño/admin puede configurar esta partida.', show_alert=True)
            raise _V121Stop
        if action == 'cfg':
            await q.answer('Configurando esta partida')
            msg = await context.bot.send_message(chat_id, '<b>⚙️ Configurar esta partida</b>\n\n' + h(_v110_config_summary(chat_id, game)), parse_mode=ParseMode.HTML, reply_markup=_v110_lobby_cfg_markup(chat_id, game))
            game['v121_config_message_id'] = int(msg.message_id)
            save_all_states()
            raise _V121Stop
        if action == 'cfgback':
            await q.answer('Volviendo al lobby')
            try:
                await q.message.delete()
            except Exception:
                pass
            await _v121_edit_lobby(context, chat_id, game)
            raise _V121Stop
        if action == 'cfgconfirm':
            await q.answer('Configuración confirmada ✅')
            try:
                await q.message.delete()
            except Exception:
                pass
            await _v121_edit_lobby(context, chat_id, game)
            raise _V121Stop
        if action == 'cfgset':
            if len(parts) < 6:
                await q.answer('Configuración inválida', show_alert=True)
                raise _V121Stop
            key = parts[4]; val = parts[5]
            cfg = _v110_ensure_game_config(chat_id, game)
            if key == 'accuse':
                cfg['final_vote_only'] = False
                cfg['accuse_round'] = max(1, min(3, int(val)))
            elif key == 'final':
                cfg['final_vote_only'] = True
            elif key == 'speed':
                cfg['speed'] = 'fast' if val == 'fast' else 'normal'
            elif key == 'hot':
                cfg['hot'] = val == '1'
                game['word'] = _v110_pick_word(chat_id, bool(cfg.get('hot')))
            save_all_states()
            await q.answer('Opción marcada ✅')
            try:
                await q.edit_message_text('<b>⚙️ Configurar esta partida</b>\n\n' + h(_v110_config_summary(chat_id, game)) + '\n\nPulsa <b>Confirmar configuración</b> para volver al lobby.', parse_mode=ParseMode.HTML, reply_markup=_v110_lobby_cfg_markup(chat_id, game))
            except Exception:
                pass
            raise _V121Stop

    if action in {'start','cancel'} and len(parts) >= 4:
        try:
            _v121_cancel_lobby_watch(int(parts[2]), int(parts[3]))
        except Exception:
            pass
    return await _old_v121_impostor_callback_router(update, context)


async def _v121_djemoji_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or not str(pending.get('kind','')).startswith('djemoji_'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    raw = telegram_html_from_message(update.message).strip() or plain_text_from_message(update.message).strip()
    if not raw:
        await update.message.reply_html('Envíame un emoji o texto válido.')
        raise _V121Stop
    kind = str(pending.get('kind'))
    if 'on' in kind:
        admin_cfg(chat_id)['dj_status_on_emoji'] = raw[:200]
    else:
        admin_cfg(chat_id)['dj_status_off_emoji'] = raw[:200]
    pop_config_pending(update.effective_user.id)
    save_all_states()
    await update.message.reply_html('✅ Estado guardado con soporte HTML/emoji premium.\n\n' + admin_private_block_text(chat_id, 'dj_permissions'), reply_markup=admin_private_block_markup(chat_id, 'dj_permissions'))
    raise _V121Stop


_old_v121_build_application = build_application

def build_application() -> Application:
    app = _old_v121_build_application()
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-3000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v121_djemoji_text_handler), group=-3000000000)
    logger.info('V121 Impostor timers/config + DJ emoji premium cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V122Stop
except Exception:
    _V122Stop = Exception


def _v122_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return admin_cfg(chat_id)
    except Exception:
        return get_state(chat_id).admin_config


def _v122_mode(chat_id: int) -> str:
    cfg = _v122_cfg(chat_id)
    try:
        if '_v106_mode' in globals():
            return _v106_mode(chat_id)
    except Exception:
        pass
    return str(cfg.get('dj_session_mode') or cfg.get('dj_mode_type') or 'pro')


def _v122_set_mode(chat_id: int, mode: str) -> None:
    cfg = _v122_cfg(chat_id)
    cfg['dj_session_mode'] = mode
    cfg['dj_mode_type'] = mode
    try:
        if '_v106_set_mode' in globals():
            _v106_set_mode(chat_id, mode)
    except Exception:
        pass


def _v122_is_control_message(chat_id: int, mid: Optional[int]) -> bool:
    try:
        return bool(mid and int(get_state(chat_id).control_message_id or 0) == int(mid))
    except Exception:
        return False


async def _v122_can_pro(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> bool:
    try:
        if '_v106_user_can' in globals():
            return await _v106_user_can(context, chat_id, user, 'pro')
    except Exception:
        pass
    try:
        return await is_controller(context, chat_id, int(user.id))
    except Exception:
        return int(getattr(user, 'id', 0) or 0) in ADMIN_IDS


