def queue_markup(state: ChatState, page: int = 0) -> InlineKeyboardMarkup:
    total = len(state.queue)
    page = clamp_page(page, total)
    _, start, end, chunk = page_slice(state.queue, page)
    rows: List[List[InlineKeyboardButton]] = []
    for rel_idx, item in enumerate(chunk):
        idx = start + rel_idx
        track = Track(**item)
        rows.append([
            InlineKeyboardButton(truncated_button_title(track.title, 42), callback_data=f'q|noop|{idx}|{page}'),
            InlineKeyboardButton('▶️', callback_data=f'q|p|{idx}|{page}'),
            InlineKeyboardButton('+1', callback_data=f'q|f|{idx}|{page}'),
            InlineKeyboardButton('🗑️', callback_data=f'q|x|{idx}|{page}'),
        ])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'q|pg|{page-1}|0'))
    if end < len(state.queue):
        nav.append(InlineKeyboardButton('➡️', callback_data=f'q|pg|{page+1}|0'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🧹 Vaciar cola', callback_data=f'q|c|0|{page}'), InlineKeyboardButton('🔙 Volver', callback_data='q|r|0|0')])
    return InlineKeyboardMarkup(rows)


