try:
    from telegram.ext import ApplicationHandlerStop as _V123Stop
except Exception:
    _V123Stop = Exception

_V123_EVENT_CACHE: Dict[str, int] = {}


def _v123_now() -> int:
    return int(time.time())


def _v123_seen(key: str, ttl: int = 20) -> bool:
    now = _v123_now()

    if len(_V123_EVENT_CACHE) > 1000:
        for k, ts in list(_V123_EVENT_CACHE.items()):
            if now - int(ts or 0) > 300:
                _V123_EVENT_CACHE.pop(k, None)
    last = int(_V123_EVENT_CACHE.get(key, 0) or 0)
    if last and now - last < ttl:
        return True
    _V123_EVENT_CACHE[key] = now
    return False


def _v123_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cfg.setdefault('validation_lock_entries', True)
    cfg.setdefault('validation_public_left_enabled', True)
    cfg.setdefault('validation_public_kicked_enabled', True)
    cfg.setdefault('validation_left_message', '🚪 {mention} ha salido del grupo.')
    cfg.setdefault('validation_kicked_message', '⛔ {mention} ha sido expulsado del grupo.')
    return cfg


def _v123_user_mention(user) -> str:
    try:
        return user.mention_html()
    except Exception:
        return h(display_name(user))


async def _v123_send_template(context: ContextTypes.DEFAULT_TYPE, chat_id: int, template: str, user) -> Optional[int]:
    try:
        text = validation_format_template(str(template or ''), user)
        msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML)
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass
        return int(msg.message_id)
    except Exception:
        logger.exception('V123 no pudo enviar plantilla en %s', chat_id)
        return None


async def _v123_start_validation(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, *, source: str, public: bool = True) -> bool:
    if not user or getattr(user, 'is_bot', False):
        return False
    if not chat_is_allowed(chat_id) or not validation_is_active_for_chat(chat_id):
        return False
    cfg = _v123_cfg(chat_id)
    if not bool(cfg.get('validation_lock_entries', True)):
        return False
    key = f'join:{chat_id}:{int(user.id)}:{source}'
    if _v123_seen(key, ttl=20):

        return True
    try:

        started = await start_validation_for_user(
            context,
            context,
            int(chat_id),
            user,
            reply_to_message_id=None,
            source=source,
            force=True,
        )
    except Exception:
        logger.exception('V123 no pudo iniciar validación para %s en %s', getattr(user, 'id', None), chat_id)
        started = False
    if started and public:
        try:
            mid = await send_configured_public_join(context.bot, int(chat_id), user, reply_to_message_id=None)
            rec = validation_get_record(chat_id, user.id) or {}
            if mid:
                rec['public_message_id'] = mid
            rec['v123_locked_entry'] = True
            rec['source'] = source
            validation_set_record(chat_id, user.id, rec)
        except Exception:
            logger.exception('V123 no pudo enviar mensaje público de entrada')
    return bool(started)


async def _v123_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    req = getattr(update, 'chat_join_request', None)
    if not req:
        return
    chat_id = int(req.chat.id)
    user = req.from_user
    if not validation_is_active_for_chat(chat_id):
        return
    remember_chat_title(chat_id, getattr(req.chat, 'title', '') or '')
    cfg = _v123_cfg(chat_id)
    if bool(cfg_value(chat_id, 'validation_auto_approve_join_requests', True)):
        key = f'joinreq:{chat_id}:{int(user.id)}'
        if _v123_seen(key, ttl=30):
            raise _V123Stop
        try:
            await context.bot.approve_chat_join_request(chat_id=chat_id, user_id=int(user.id))
        except Exception:
            logger.exception('V123 no pudo aprobar solicitud; revisa permisos del bot')

            raise _V123Stop
        await _v123_start_validation(context, chat_id, user, source='join_request_v123', public=True)
        raise _V123Stop


async def _v123_new_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not validation_is_active_for_chat(chat_id):
        return
    remember_chat_title(chat_id, getattr(update.effective_chat, 'title', '') or '')
    users = list(getattr(update.message, 'new_chat_members', []) or [])
    handled = False
    for user in users:
        ok = await _v123_start_validation(context, chat_id, user, source='service_new_member_v123', public=True)
        handled = handled or ok
    if handled:
        raise _V123Stop


async def _v123_chat_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, 'chat_member', None)
    if not cmu or not getattr(cmu, 'chat', None):
        return
    chat_id = int(cmu.chat.id)
    remember_chat_title(chat_id, getattr(cmu.chat, 'title', '') or '')
    old = getattr(cmu, 'old_chat_member', None)
    new = getattr(cmu, 'new_chat_member', None)
    user = getattr(new, 'user', None) or getattr(old, 'user', None)
    if not user or getattr(user, 'is_bot', False):
        return
    old_status = str(getattr(old, 'status', '') or '')
    new_status = str(getattr(new, 'status', '') or '')


    if validation_is_active_for_chat(chat_id) and old_status in ('left', 'kicked', '') and new_status in ('member', 'restricted', 'administrator', 'creator'):
        ok = await _v123_start_validation(context, chat_id, user, source='chat_member_join_v123', public=True)
        if ok:
            raise _V123Stop
        return


    if old_status not in ('left', 'kicked', '') and new_status in ('left', 'kicked'):
        await _v123_handle_exit(context, chat_id, user, kicked=(new_status == 'kicked'), source='chat_member_v123')
        raise _V123Stop


async def _v123_left_service(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not getattr(update.message, 'left_chat_member', None):
        return
    chat_id = int(update.effective_chat.id)
    user = update.message.left_chat_member
    await _v123_handle_exit(context, chat_id, user, kicked=False, source='service_left_v123')
    raise _V123Stop


async def _v123_handle_exit(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, *, kicked: bool, source: str) -> None:
    if not user or getattr(user, 'is_bot', False):
        return
    key = f'exit:{chat_id}:{int(user.id)}:{"kick" if kicked else "left"}'
    if _v123_seen(key, ttl=45):
        return
    cfg = _v123_cfg(chat_id)
    try:
        if kicked:
            if not bool(cfg.get('validation_public_kicked_enabled', True)):
                return
            template = str(cfg.get('validation_kicked_message') or '⛔ {mention} ha sido expulsado del grupo.')
            src = 'kicked_v123'
        else:
            if not bool(cfg.get('validation_public_left_enabled', True)):
                return
            template = str(cfg.get('validation_left_message') or '🚪 {mention} ha salido del grupo.')
            src = 'left_v123'
        _v31_record_left_user(chat_id, user, source=src) if '_v31_record_left_user' in globals() and not kicked else None
        remember_member_activity(chat_id, user, kind='left' if not kicked else 'kicked', source=source)
        await _v123_send_template(context, chat_id, template, user)
    except Exception:
        logger.exception('V123 error registrando salida/expulsión')


async def _v123_pending_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Evita que usuarios pendientes usen comandos/media antes de validar.

    Las respuestas de texto normales se dejan pasar para que validation_handle_text las procese.
    """
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private' or not validation_is_active_for_chat(chat_id):
        return
    record = validation_get_record(chat_id, int(update.effective_user.id))
    if not record:
        return
    status = str(record.get('status') or '')
    if status in ('validated', 'approved'):
        return

    if status == 'answering' and update.message.text and not update.message.text.startswith('/'):
        return

    try:
        await safe_delete(context.bot, chat_id, update.message.message_id)
    except Exception:
        pass
    try:
        await validation_restrict_answering(context, chat_id, update.effective_user.id)
    except Exception:
        pass

    try:
        await send_temp_message(context.bot, chat_id, f'🛡 {_v123_user_mention(update.effective_user)}, completa primero la presentación y preguntas.', ttl=20)
    except Exception:
        pass
    raise _V123Stop


_old_v123_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    txt = _old_v123_admin_private_block_text(chat_id, block, page)
    if block == 'validation':
        cfg = _v123_cfg(chat_id)
        txt += (
            '\n\n<b>Blindaje de entradas</b>\n'
            f'Obligar presentación a toda entrada: <b>{bool_label(cfg.get("validation_lock_entries", True))}</b>\n'
            f'Aviso público de salidas: <b>{bool_label(cfg.get("validation_public_left_enabled", True))}</b>\n'
            f'Aviso público de expulsiones: <b>{bool_label(cfg.get("validation_public_kicked_enabled", True))}</b>\n'
            '\n<i>Para bloquear de verdad, el bot debe ser admin con permisos de restringir usuarios, aprobar solicitudes y ver eventos de miembros.</i>'
        )
    return txt


_old_v123_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v123_admin_private_block_markup(chat_id, block, page)
    if block != 'validation':
        return markup
    cfg = _v123_cfg(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    extra = [
        [InlineKeyboardButton(f'🛡 Blindar entradas {bool_label(cfg.get("validation_lock_entries", True))}', callback_data=f'cfg|v123_toggle|{chat_id}|validation_lock_entries|validation')],
        [
            InlineKeyboardButton(f'🚪 Salidas {bool_label(cfg.get("validation_public_left_enabled", True))}', callback_data=f'cfg|v123_toggle|{chat_id}|validation_public_left_enabled|validation'),
            InlineKeyboardButton(f'⛔ Expulsiones {bool_label(cfg.get("validation_public_kicked_enabled", True))}', callback_data=f'cfg|v123_toggle|{chat_id}|validation_public_kicked_enabled|validation'),
        ],
    ]

    if rows:
        rows = rows[:-1] + extra + rows[-1:]
    else:
        rows = extra
    return InlineKeyboardMarkup(rows)


_old_v123_admin_private_config_callback = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|v123_toggle|'):
        try:
            parts = data.split('|')
            chat_id = int(parts[2]); key = parts[3]; block = parts[4] if len(parts) > 4 else 'validation'
            cfg = _v123_cfg(chat_id)
            cfg[key] = not bool(cfg.get(key, True))
            save_all_states()
            await q.answer('Actualizado ✅')
            await q.edit_message_text(admin_private_block_text(chat_id, block), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, block))
        except Exception:
            logger.exception('V123 callback config')
            try:
                await q.answer('Error. Revisa logs.', show_alert=True)
            except Exception:
                pass
        raise _V123Stop
    return await _old_v123_admin_private_config_callback(update, context)


_old_v123_build_application = build_application
def build_application() -> Application:
    app = _old_v123_build_application()

    app.add_handler(ChatJoinRequestHandler(_v123_join_request), group=-5000000000)
    app.add_handler(ChatMemberHandler(_v123_chat_member, ChatMemberHandler.CHAT_MEMBER), group=-5000000000)
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, _v123_new_member), group=-5000000000)
    app.add_handler(MessageHandler(filters.StatusUpdate.LEFT_CHAT_MEMBER, _v123_left_service), group=-5000000000)
    app.add_handler(MessageHandler(filters.ALL, _v123_pending_guard), group=-4999999999)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r'^cfg\|v123_toggle\|'), group=-5000000000)
    logger.info('V123 validación blindada y salidas visibles cargado')
    return app


