def _v130_cards_upload_text(chat_id: int, page: int = 0) -> str:
    page_size = 6
    total_pages = ((len(TAROT_CARDS_V129)-1)//page_size)+1
    page = max(0, min(page, total_pages-1))
    imgs = _v130_tarot_images(chat_id)
    cards = imgs.get('cards') if isinstance(imgs.get('cards'), dict) else {}
    lines = [f'<b>🃏 Subir cartas Tarot</b> · pág. {page+1}/{total_pages}', '']
    for c in TAROT_CARDS_V129[page*page_size:(page+1)*page_size]:
        lines.append(f"{'✅' if cards.get(c['id']) else '❌'} <b>{_v130_card_number(c['id'])}</b> · {h(c['name'])}")
    return '\n'.join(lines)


def _v130_cards_upload_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    page_size = 6
    total_pages = ((len(TAROT_CARDS_V129)-1)//page_size)+1
