async def _v130_tarot_settings_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|t130|'):
        return
    parts = q.data.split('|')
    try:
        chat_id = int(parts[2]); action = parts[3]
        if action == 'assets':
            await q.answer()
            await q.edit_message_text(_v130_tarot_assets_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton('🖼 Subir imagen inicio/lobby', callback_data=f'cfg|t130|{chat_id}|up|start')],
                [InlineKeyboardButton('🂠 Subir reverso/barajeo', callback_data=f'cfg|t130|{chat_id}|up|back')],
                [InlineKeyboardButton('🃏 Subir imágenes de cartas', callback_data=f'cfg|t130|{chat_id}|cards|0')],
                [InlineKeyboardButton('🧹 Quitar inicio', callback_data=f'cfg|t130|{chat_id}|del|start'), InlineKeyboardButton('🧹 Quitar reverso', callback_data=f'cfg|t130|{chat_id}|del|back')],
                [InlineKeyboardButton('🔙 Tarot', callback_data=f'cfg|block|{chat_id}|tarot')],
            ]))
            raise _V130Stop
        if action == 'cards':
            page = int(parts[4]) if len(parts)>4 else 0
            await q.answer()
            await q.edit_message_text(_v130_cards_upload_text(chat_id, page), parse_mode=ParseMode.HTML, reply_markup=_v130_cards_upload_markup(chat_id, page))
            raise _V130Stop
        if action == 'up':
            kind = parts[4]
            set_config_pending(q.from_user.id, {'kind': 'tarot_image_upload_v130', 'chat_id': chat_id, 'target': kind})
            await q.answer()
            await q.message.reply_html('📸 Envíame ahora la foto para <b>{}</b>.'.format('imagen de inicio/lobby' if kind=='start' else 'reverso de la carta/barajeo'))
            raise _V130Stop
        if action == 'upc':
            cid = parts[4]
            card = next((c for c in TAROT_CARDS_V129 if c['id']==cid), None)
            if not card:
                await q.answer('Carta inválida', show_alert=True); raise _V130Stop
            set_config_pending(q.from_user.id, {'kind': 'tarot_image_upload_v130', 'chat_id': chat_id, 'target': 'card', 'card_id': cid})
            await q.answer()
            await q.message.reply_html(f"📸 Envíame ahora la imagen de la carta <b>{_v130_card_number(cid)} · {h(card['name'])}</b>.")
            raise _V130Stop
        if action == 'del':
            kind = parts[4]
            imgs = _v130_tarot_images(chat_id)
            if kind in ('start','back'):
                imgs[kind] = ''
                save_all_states()
            await q.answer('Imagen quitada ✅')
            await q.edit_message_text(_v130_tarot_assets_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton('🖼 Subir imagen inicio/lobby', callback_data=f'cfg|t130|{chat_id}|up|start')],
                [InlineKeyboardButton('🂠 Subir reverso/barajeo', callback_data=f'cfg|t130|{chat_id}|up|back')],
                [InlineKeyboardButton('🃏 Subir imágenes de cartas', callback_data=f'cfg|t130|{chat_id}|cards|0')],
                [InlineKeyboardButton('🔙 Tarot', callback_data=f'cfg|block|{chat_id}|tarot')],
            ]))
            raise _V130Stop
    except _V130Stop:
        raise
    except Exception:
        logger.exception('Error ajustes Tarot V130')
        try: await q.answer('Error Tarot. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V130Stop


async def _v130_tarot_upload_photo(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_image_upload_v130':
        return
    if not update.message.photo:
        await update.message.reply_html('Necesito que envíes una <b>foto</b>, no texto ni documento.')
        raise _V130Stop
    chat_id = int(pending.get('chat_id') or 0)
    file_id = update.message.photo[-1].file_id
    target = str(pending.get('target'))
    imgs = _v130_tarot_images(chat_id)
    if target in ('start','back'):
        imgs[target] = file_id
        label = 'imagen de inicio/lobby' if target=='start' else 'reverso/barajeo'
    elif target == 'card':
        cid = str(pending.get('card_id'))
        imgs.setdefault('cards', {})[cid] = file_id
        card = next((c for c in TAROT_CARDS_V129 if c['id']==cid), {'name': cid})
        label = f"carta {_v130_card_number(cid)} · {card['name']}"
    else:
        await update.message.reply_html('Destino de imagen no válido.')
        pop_config_pending(update.effective_user.id)
        raise _V130Stop
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html(f'✅ Guardada la imagen de <b>{h(label)}</b>.')
    raise _V130Stop


async def _v130_reccmd_tarot(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = q.data.split('|', 2)
    if len(parts) < 3:
        return
    cmd = parts[2].strip().lower().lstrip('/')
    if cmd != 'tarot':
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = int(q.message.chat_id) if q.message else int(update.effective_chat.id)
    await q.answer()
    await _v130_send_lobby(context.bot, chat_id, q.from_user)
    raise _V130Stop


_old_build_application_v130 = build_application
def build_application() -> Application:
    _v129_ensure_tarot_block()
    app = _old_build_application_v130()
    app.add_handler(CommandHandler(['tarot','tarotplan'], tarot_command), group=-7100000000)
    app.add_handler(CallbackQueryHandler(_v129_tarot_callback, pattern=r'^tar\|'), group=-7100000000)
    app.add_handler(CallbackQueryHandler(_v130_tarot_settings_callback, pattern=r'^cfg\|t130\|'), group=-7100000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.PHOTO, _v130_tarot_upload_photo), group=-7100000000)
    app.add_handler(CallbackQueryHandler(_v130_reccmd_tarot, pattern=r'^reccmd\|'), group=-7100000001)
    logger.info('V130 Tarot configurable con imágenes cargado')
    return app


