def _v132_bool(v: bool) -> str:
    return 'ON ✅' if bool(v) else 'OFF ❌'


def _v132_sec_label(sec: int) -> str:
    try:
        sec = int(sec)
    except Exception:
        sec = 0
    if sec <= 0:
        return 'No borrar'
    if sec < 60:
        return f'{sec}s'
    if sec % 60 == 0:
        return f'{sec//60}m'
    return f'{sec}s'


