def build_application() -> Application:
    try:
        _v129_ensure_tarot_block()
    except Exception:
        pass
    app = _old_build_application_v132()
    app.add_handler(CallbackQueryHandler(_v132_tarot_router, pattern=r'^(t32\||cfg\|block\|-?\d+\|tarot$)'), group=-7300000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v132_tarot_upload_image), group=-7300000000)
    logger.info('V132 Tarot estable: ajustes, PNG, limpieza y callbacks cortos cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V133Stop
except Exception:
    _V133Stop = Exception


def _v133_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_active_lock_sec', 300)
    cfg.setdefault('tarot_cooldown_sec', 60)
    cfg.setdefault('tarot_image_size', 'medium')
    cfg.setdefault('tarot_active_until_ts', 0)
    cfg.setdefault('tarot_active_user_id', 0)
    cfg.setdefault('tarot_last_end_ts', 0)
    return cfg


def _v133_sec_label(seconds: int) -> str:
    try:
        seconds = int(seconds)
    except Exception:
        seconds = 0
    if seconds <= 0:
        return 'OFF'
    if seconds % 60 == 0:
        m = seconds // 60
        return f'{m} min'
    return f'{seconds}s'


def _v133_size_label(size: str) -> str:
    return {'small':'Pequeña', 'medium':'Mediana', 'large':'Grande'}.get(str(size), 'Mediana')


def _v133_size_dims(chat_id: int) -> tuple[int, int]:
    size = str(_v133_tarot_cfg(chat_id).get('tarot_image_size', 'medium'))
    if size == 'small':
        return (420, 620)
    if size == 'large':
        return (900, 1280)
    return (650, 920)


def _v133_is_chat_locked(chat_id: int, user_id: int) -> tuple[bool, str]:
    cfg = _v133_tarot_cfg(chat_id)
    now = int(time.time())
    active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
    active_user = int(cfg.get('tarot_active_user_id', 0) or 0)
    if active_until > now and active_user and active_user != int(user_id):
        remain = active_until - now
        return True, f'🔮 Ya hay una tirada de Tarot abierta. Espera {_v133_sec_label(remain)} o a que termine.'
    cooldown = int(cfg.get('tarot_cooldown_sec', 0) or 0)
    last_end = int(cfg.get('tarot_last_end_ts', 0) or 0)
    if cooldown > 0 and last_end > 0 and now - last_end < cooldown:
        return True, f'🔮 Espera {_v133_sec_label(cooldown - (now - last_end))} antes de abrir otra tirada.'
    return False, ''


def _v133_mark_tarot_started(chat_id: int, user_id: int) -> None:
    cfg = _v133_tarot_cfg(chat_id)
    sec = int(cfg.get('tarot_active_lock_sec', 0) or 0)
    if sec > 0:
        cfg['tarot_active_until_ts'] = int(time.time()) + sec
        cfg['tarot_active_user_id'] = int(user_id)
    else:
        cfg['tarot_active_until_ts'] = 0
        cfg['tarot_active_user_id'] = 0
    save_all_states()


def _v133_mark_tarot_finished(chat_id: int) -> None:
    cfg = _v133_tarot_cfg(chat_id)
    cfg['tarot_active_until_ts'] = 0
    cfg['tarot_active_user_id'] = 0
    cfg['tarot_last_end_ts'] = int(time.time())
    save_all_states()


_old_v133_tarot_settings_text = _v132_tarot_settings_text

def _v132_tarot_settings_text(chat_id: int) -> str:
    base = _old_v133_tarot_settings_text(chat_id)
    cfg = _v133_tarot_cfg(chat_id)
    now = int(time.time())
    active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
    active_text = 'libre'
    if active_until > now:
        active_text = f'bloqueado {_v133_sec_label(active_until-now)}'
    return base + (
        '\n\n<b>Control de partidas</b>\n'
        f"Tarot abierto bloquea nuevas tiradas: <b>{_v133_sec_label(int(cfg.get('tarot_active_lock_sec', 0) or 0))}</b>\n"
        f"Espera entre tiradas: <b>{_v133_sec_label(int(cfg.get('tarot_cooldown_sec', 0) or 0))}</b>\n"
        f"Estado actual: <b>{h(active_text)}</b>\n\n"
        '<b>Tamaño de imágenes</b>\n'
        f"Cartas: <b>{h(_v133_size_label(str(cfg.get('tarot_image_size', 'medium'))))}</b>"
    )

_old_v133_tarot_settings_markup = _v132_tarot_settings_markup

def _v132_tarot_settings_markup(chat_id: int) -> InlineKeyboardMarkup:
    old = _old_v133_tarot_settings_markup(chat_id)
    rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]

    insert_at = max(0, len(rows)-2)
    extra = [
        [InlineKeyboardButton('⏳ Bloqueo partida', callback_data=f't33|lock|{chat_id}')],
        [InlineKeyboardButton('⌛ Espera entre tiradas', callback_data=f't33|cool|{chat_id}')],
        [InlineKeyboardButton('🖼 Tamaño cartas', callback_data=f't33|size|{chat_id}')],
    ]
    rows = rows[:insert_at] + extra + rows[insert_at:]
    return InlineKeyboardMarkup(rows)


