def build_application() -> Application:
    app = _old_build_application_v133()
    app.add_handler(CallbackQueryHandler(_v133_settings_router, pattern=r'^t33\|'), group=-7400000000)
    app.add_handler(CallbackQueryHandler(_v133_tarot_start_finish_router, pattern=r'^tar\|(start|final)\|?'), group=-7400000000)

    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v132_tarot_upload_image), group=-7400000001)
    logger.info('V133 Tarot bloqueo/cooldown e imágenes pequeñas/medianas/grandes cargado')
    return app


