async def _v136_processed_tarot_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, file_id: str, role: str = 'card'):
    """Procesa imágenes según su uso.

    role='choice'/'shuffle': imagen ancha, completa, sin lienzo de carta vertical.
    role='card'/'lobby': usa el procesador actual de tamaño elegido.
    """
    if not file_id:
        return None
    if role in ('choice', 'shuffle'):
        try:
            from PIL import Image
            from io import BytesIO
            tgfile = await context.bot.get_file(file_id)
            raw = BytesIO()
            await tgfile.download_to_memory(raw)
            raw.seek(0)
            img = Image.open(raw).convert('RGB')

            max_w, max_h = 1100, 520
            img.thumbnail((max_w, max_h))
            out = BytesIO()
            out.name = 'tarot_taco_ancho.jpg'
            img.save(out, format='JPEG', quality=90, optimize=True)
            out.seek(0)
            return out
        except Exception:
            logger.exception('No pude procesar imagen Tarot ancho V136')
            return file_id
    try:
        return await _v134_processed_image_from_file_id(context, chat_id, file_id)
    except Exception:
        return file_id


async def _v136_store_tarot_image(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Guarda también shuffle y no deja que handlers antiguos rechacen el target."""
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') not in ('tarot_image_upload_v132', 'tarot_image_upload_v130'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    target = str(pending.get('target') or '')
    src_file_id = ''
    if update.message.photo:
        src_file_id = update.message.photo[-1].file_id
    elif update.message.document:
        src_file_id = update.message.document.file_id
    if not src_file_id:
        await update.message.reply_html('Necesito que envíes una imagen PNG/JPG como foto o documento.')
        raise _V136Stop

    imgs = _v136_tarot_images(chat_id)
    if target in ('start', 'shuffle', 'back'):
        role = 'shuffle' if target == 'shuffle' else ('choice' if target == 'back' else 'lobby')
        processed = await _v136_processed_tarot_image(context, chat_id, src_file_id, role=role)

        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src_file_id, caption='✅ Imagen recibida para Tarot.')
            file_id = preview.photo[-1].file_id if preview.photo else src_file_id
            try:
                await asyncio.sleep(1.5)
                await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception:
                pass
        except Exception:
            file_id = src_file_id
        imgs[target] = file_id
        label = {'start': 'inicio/lobby', 'shuffle': 'barajeo', 'back': 'taco/reverso elección'}.get(target, target)
    elif target == 'card':
        cid = str(pending.get('card_id'))
        processed = await _v136_processed_tarot_image(context, chat_id, src_file_id, role='card')
        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src_file_id, caption='✅ Carta recibida para Tarot.')
            file_id = preview.photo[-1].file_id if preview.photo else src_file_id
            try:
                await asyncio.sleep(1.5)
                await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception:
                pass
        except Exception:
            file_id = src_file_id
        imgs.setdefault('cards', {})[cid] = file_id
        card = next((c for c in TAROT_CARDS_V129 if c['id'] == cid), {'name': cid})
        label = f"{_v130_card_number(cid)} · {card['name']}"
    else:
        await update.message.reply_html('Destino de imagen Tarot no válido.')
        pop_config_pending(update.effective_user.id)
        raise _V136Stop
    save_all_states(); pop_config_pending(update.effective_user.id)
    await update.message.reply_html(f'✅ Guardada imagen de <b>{h(label)}</b>.')
    raise _V136Stop


async def _v136_tarot_del_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t32|del|'):
        return
    parts = q.data.split('|')
    try:
        chat_id = int(parts[2]); target = parts[3]
    except Exception:
        return
    if target not in ('start', 'shuffle', 'back'):
        return
    imgs = _v136_tarot_images(chat_id)
    imgs[target] = ''
    save_all_states()
    await q.answer('Quitado ✅')
    await _v132_edit(q, _v132_assets_text(chat_id), _v132_assets_markup(chat_id))
    raise _V136Stop


async def _v129_send_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], *, new_pair: bool = True) -> None:
    """La elección usa taco/reverso en formato ancho completo."""
    if new_pair:
        await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        session['draws_msg_id'] = 0
        session['choice_msg_id'] = 0
    draws_msg = await context.bot.send_message(chat_id, _v129_draws_text(session), parse_mode=ParseMode.HTML)
    session['draws_msg_id'] = int(draws_msg.message_id)
    try: await register_bot_message(chat_id, draws_msg.message_id)
    except Exception: pass
    imgs = _v136_tarot_images(chat_id)
    back = str(imgs.get('back') or '')
    caption = _v129_choice_text(session, user)
    if back:
        try:
            photo = await _v136_processed_tarot_image(context, chat_id, back, role='choice')
            choice_msg = await context.bot.send_photo(chat_id, photo=photo or back, caption=caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
        except Exception:
            logger.exception('No se pudo enviar taco/reverso ancho Tarot; uso texto')
            choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
    else:
        choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
    session['choice_msg_id'] = int(choice_msg.message_id)
    try: await register_bot_message(chat_id, choice_msg.message_id)
    except Exception: pass


async def _v136_tarot_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|start|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    mode = parts[2] if len(parts) > 2 else 'day'
    if mode not in ('ppf', 'day'):
        mode = 'day'
    try:
        try:
            locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
            if locked:
                await q.answer(reason, show_alert=True)
                raise _V136Stop
            _v133_mark_tarot_started(chat_id, int(user.id))
        except _V136Stop:
            raise
        except Exception:
            pass
        ok, reason = _v129_can_play(chat_id, int(user.id), mode)
        if not ok:
            await q.answer(reason, show_alert=True); raise _V136Stop
        skey = _v129_session_key(chat_id, int(user.id))
        session = {
            'chat_id': chat_id,
            'user_id': int(user.id),
            'mode': mode,
            'stage': 0,
            'draws': [],
            'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)),
            'started_ts': int(time.time()),
        }
        TAROT_SESSIONS_V129[skey] = session
        await q.answer('Barajando el taco…')
        imgs = _v136_tarot_images(chat_id)
        shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
        caption = (
            f'🔮 {user.mention_html()} está barajando el taco de cartas…\n'
            '✨ Que hablen los arcanos, la intuición, las almas y los amores del recuerdo.'
        )
        if shuffle_id:
            try:
                from telegram import InputMediaPhoto
                photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle')
                await context.bot.edit_message_media(
                    chat_id=chat_id,
                    message_id=q.message.message_id,
                    media=InputMediaPhoto(media=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML),
                    reply_markup=None,
                )
            except Exception:
                try:
                    await q.edit_message_caption(caption=caption, parse_mode=ParseMode.HTML, reply_markup=None)
                except Exception:
                    try:
                        await q.edit_message_text(caption, parse_mode=ParseMode.HTML)
                    except Exception:
                        pass
        else:
            try:
                await q.edit_message_caption(caption=caption, parse_mode=ParseMode.HTML, reply_markup=None)
            except Exception:
                try:
                    await q.edit_message_text(caption, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
        await asyncio.sleep(0.8)
        await _v129_send_pair(context, chat_id, user, session, new_pair=True)
        raise _V136Stop
    except _V136Stop:
        raise
    except Exception:
        logger.exception('Error Tarot V136 start')
        try:
            await q.answer('Error en Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V136Stop


_old_build_application_v136 = build_application

def build_application() -> Application:
    app = _old_build_application_v136()
    app.add_handler(CallbackQueryHandler(_v136_tarot_start_router, pattern=r'^tar\|start\|'), group=-7700000000)
    app.add_handler(CallbackQueryHandler(_v136_tarot_del_router, pattern=r'^t32\|del\|'), group=-7700000001)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v136_store_tarot_image), group=-7700000002)
    logger.info('V136 Tarot barajeo separado y taco ancho cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V137Stop
except Exception:
    _V137Stop = Exception


def _v137_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v133_tarot_cfg(chat_id) if '_v133_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_delete_lobby_on_start', True)
    cfg.setdefault('tarot_delete_shuffle_msg', True)
    cfg.setdefault('tarot_keep_only_final', True)
    return cfg


def _v137_onoff(v: Any) -> str:
    return 'ON ✅' if bool(v) else 'OFF ❌'


_old_v137_tarot_settings_text = _v132_tarot_settings_text if '_v132_tarot_settings_text' in globals() else _v129_tarot_settings_text

def _v132_tarot_settings_text(chat_id: int) -> str:
    base = _old_v137_tarot_settings_text(chat_id)
    cfg = _v137_tarot_cfg(chat_id)
    extra = (
        '\n\n<b>Limpieza del juego</b>\n'
        f"Borrar lobby al empezar: <b>{_v137_onoff(cfg.get('tarot_delete_lobby_on_start', True))}</b>\n"
        f"Borrar barajeo al elegir: <b>{_v137_onoff(cfg.get('tarot_delete_shuffle_msg', True))}</b>\n"
        f"Dejar solo resultado final: <b>{_v137_onoff(cfg.get('tarot_keep_only_final', True))}</b>\n"
        '\n<i>Si está activo, el juego va limpiando mensajes antiguos y deja como principal el resultado final.</i>'
    )
    return base + extra


_old_v137_tarot_settings_markup = _v132_tarot_settings_markup if '_v132_tarot_settings_markup' in globals() else _v129_tarot_settings_markup

def _v132_tarot_settings_markup(chat_id: int) -> InlineKeyboardMarkup:
    old = _old_v137_tarot_settings_markup(chat_id)
    rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]
    cfg = _v137_tarot_cfg(chat_id)
    extra = [
        [InlineKeyboardButton(f"🧹 Borrar lobby: {'ON' if cfg.get('tarot_delete_lobby_on_start', True) else 'OFF'}", callback_data=f't37|tog|{chat_id}|lobby')],
        [InlineKeyboardButton(f"🌀 Borrar barajeo: {'ON' if cfg.get('tarot_delete_shuffle_msg', True) else 'OFF'}", callback_data=f't37|tog|{chat_id}|shuffle')],
        [InlineKeyboardButton(f"🏁 Solo resultado final: {'ON' if cfg.get('tarot_keep_only_final', True) else 'OFF'}", callback_data=f't37|tog|{chat_id}|final')],
    ]

    insert_at = max(0, len(rows)-2)
    return InlineKeyboardMarkup(rows[:insert_at] + extra + rows[insert_at:])


async def _v137_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t37|'):
        return
    parts = (q.data or '').split('|')
    try:
        action = parts[1]
        chat_id = int(parts[2])
        cfg = _v137_tarot_cfg(chat_id)
        if action == 'tog':
            what = parts[3]
            key = {'lobby': 'tarot_delete_lobby_on_start', 'shuffle': 'tarot_delete_shuffle_msg', 'final': 'tarot_keep_only_final'}.get(what)
            if key:
                cfg[key] = not bool(cfg.get(key, True))
                save_all_states()
            await q.answer('Actualizado ✅')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
            raise _V137Stop
    except _V137Stop:
        raise
    except Exception:
        logger.exception('Error ajustes Tarot V137: %s', q.data)
        try:
            await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V137Stop


async def _v137_safe_delete(bot, chat_id: int, mid: Any) -> None:
    try:
        mid = int(mid or 0)
    except Exception:
        mid = 0
    if not mid:
        return
    try:
        await bot.delete_message(chat_id, mid)
    except Exception:
        pass


async def _v137_delete_intermediate(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any], *, include_result: bool = False) -> None:
    keys = ['lobby_msg_id', 'shuffle_msg_id', 'draws_msg_id', 'choice_msg_id']
    if include_result:
        keys.append('final_msg_id')
    for k in keys:
        await _v137_safe_delete(context.bot, chat_id, session.get(k))
        if k in session:
            session[k] = 0


async def _v137_tarot_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Router definitivo para iniciar tirada: evita residuos y no edita el lobby si se quiere borrar."""
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|start|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    mode = parts[2] if len(parts) > 2 else 'day'
    if mode not in ('ppf', 'day'):
        mode = 'day'
    try:
        try:
            locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
            if locked:
                await q.answer(reason, show_alert=True)
                raise _V137Stop
            _v133_mark_tarot_started(chat_id, int(user.id))
        except _V137Stop:
            raise
        except Exception:
            pass
        ok, reason = _v129_can_play(chat_id, int(user.id), mode)
        if not ok:
            await q.answer(reason, show_alert=True)
            raise _V137Stop

        skey = _v129_session_key(chat_id, int(user.id))
        old = TAROT_SESSIONS_V129.get(skey)
        if isinstance(old, dict):
            await _v137_delete_intermediate(context, chat_id, old, include_result=False)

        session = {
            'chat_id': chat_id,
            'user_id': int(user.id),
            'mode': mode,
            'stage': 0,
            'draws': [],
            'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)) if '_v135_mystic_shuffle_deck' in globals() else [dict(c) for c in TAROT_CARDS_V129],
            'started_ts': int(time.time()),
            'lobby_msg_id': int(q.message.message_id) if q.message else 0,
        }
        TAROT_SESSIONS_V129[skey] = session
        cfg = _v137_tarot_cfg(chat_id)

        await q.answer('Barajando el taco…')
        if bool(cfg.get('tarot_delete_lobby_on_start', True)) and q.message:
            await _v137_safe_delete(context.bot, chat_id, q.message.message_id)
            session['lobby_msg_id'] = 0

        imgs = _v136_tarot_images(chat_id) if '_v136_tarot_images' in globals() else _v130_tarot_images(chat_id)
        shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
        caption = (
            f'🔮 {user.mention_html()} está barajando el taco de cartas…\n'
            '✨ Que hablen los arcanos, la intuición, las almas y los amores del recuerdo.'
        )
        if shuffle_id:
            try:
                photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
                smsg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
            except Exception:
                logger.exception('No se pudo enviar barajeo Tarot V137')
                smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        else:
            smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        session['shuffle_msg_id'] = int(smsg.message_id)
        try:
            await register_bot_message(chat_id, smsg.message_id)
        except Exception:
            pass
        await asyncio.sleep(0.8)
        if bool(cfg.get('tarot_delete_shuffle_msg', True)):
            await _v137_safe_delete(context.bot, chat_id, session.get('shuffle_msg_id'))
            session['shuffle_msg_id'] = 0
        await _v129_send_pair(context, chat_id, user, session, new_pair=True)
        raise _V137Stop
    except _V137Stop:
        raise
    except Exception:
        logger.exception('Error Tarot V137 start')
        try:
            await q.answer('Error en Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V137Stop


async def _v137_card_pil(context: ContextTypes.DEFAULT_TYPE, source_chat_id: int, card: Dict[str, str]):
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO
    photo = _v130_card_photo(source_chat_id, card, '') if '_v130_card_photo' in globals() else None
    try:
        if photo and isinstance(photo, str):
            f = await context.bot.get_file(photo)
            bio = BytesIO()
            await f.download_to_memory(bio)
            bio.seek(0)
            return Image.open(bio).convert('RGB')
        if photo and hasattr(photo, 'read'):
            try:
                photo.seek(0)
            except Exception:
                pass
            return Image.open(photo).convert('RGB')
    except Exception:
        logger.exception('No pude descargar imagen de carta para collage')

    img = Image.new('RGB', (420, 620), (28, 18, 54))
    d = ImageDraw.Draw(img)
    try:
        font1 = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 32)
        font2 = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 22)
    except Exception:
        font1 = font2 = None
    d.rectangle([10, 10, 410, 610], outline=(214, 178, 92), width=4)
    d.text((30, 70), _v130_card_number(card.get('id','')) if '_v130_card_number' in globals() else card.get('id',''), fill=(245, 221, 140), font=font1)
    d.text((30, 140), card.get('name','Carta'), fill=(255,255,255), font=font2)
    return img


async def _v137_make_result_image(context: ContextTypes.DEFAULT_TYPE, source_chat_id: int, user_name: str, cards: List[str]):
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO
    from datetime import datetime
    card_objs = []
    for cid in cards:
        c = next((x for x in TAROT_CARDS_V129 if x['id'] == cid), None)
        if c:
            card_objs.append(c)
    if not card_objs:
        return None
    imgs = []
    for c in card_objs:
        im = await _v137_card_pil(context, source_chat_id, c)
        im.thumbnail((360, 540))
        canvas = Image.new('RGB', (360, 540), (12, 8, 22))
        x = (360 - im.width)//2
        y = (540 - im.height)//2
        canvas.paste(im, (x, y))
        imgs.append(canvas)
    gap = 18
    header_h = 120
    footer_h = 95
    w = len(imgs)*360 + (len(imgs)-1)*gap + 60
    hgt = header_h + 540 + footer_h
    out = Image.new('RGB', (w, hgt), (18, 11, 35))
    d = ImageDraw.Draw(out)
    try:
        font_title = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 38)
        font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 22)
        font_small = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 18)
    except Exception:
        font_title = font = font_small = None
    d.text((30, 24), '🔮 TAROT EL PLAN', fill=(245, 220, 145), font=font_title)
    date_s = datetime.now().strftime('%d/%m/%Y · %H:%M')
    d.text((30, 76), f'Tirada de {user_name} · {date_s}', fill=(235, 235, 245), font=font)
    x = 30
    for im, c in zip(imgs, card_objs):
        out.paste(im, (x, header_h))
        label = f"{_v130_card_number(c.get('id','')) if '_v130_card_number' in globals() else c.get('id','')} · {c.get('name','')}"
        d.text((x+12, header_h+548), label[:34], fill=(255, 255, 255), font=font_small)
        x += 360 + gap
    d.text((30, hgt-38), 'Guárdala en tu galería desde Telegram.', fill=(190, 180, 215), font=font_small)
    bio = BytesIO()
    bio.name = 'tarot_el_plan_resultado.jpg'
    out.save(bio, format='JPEG', quality=90, optimize=True)
    bio.seek(0)
    return bio


async def _v137_tarot_save_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|save|'):
        return
    parts = data.split('|')
    chat_id = int(update.effective_chat.id)
    rid = parts[2] if len(parts) > 2 else ''
    try:
        cfg = _v129_tarot_cfg(chat_id)
        res = cfg.setdefault('tarot_results', {}).get(rid)
        if not isinstance(res, dict):
            await q.answer('No encuentro esta tirada.', show_alert=True)
            raise _V137Stop
        cards = list(res.get('cards') or [])
        if not cards:
            await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True)
            raise _V137Stop
        await q.answer('Creando imagen para guardar…')
        img = await _v137_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards)
        if not img:
            await q.answer('No pude crear la imagen.', show_alert=True)
            raise _V137Stop
        try:
            await context.bot.send_photo(q.from_user.id, photo=img, caption='💾 Tu tirada del Tarot del Plan. Toca la imagen y guárdala en tu galería.')
        except Exception:
            await q.answer('No puedo enviártelo al privado. Abre el chat con el bot y pulsa Start.', show_alert=True)
        raise _V137Stop
    except _V137Stop:
        raise
    except Exception:
        logger.exception('Error guardando imagen Tarot V137')
        try:
            await q.answer('Error creando imagen. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V137Stop


_old_v137_show_final = _v129_show_final
async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:

    if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)):
        await _v137_delete_intermediate(context, chat_id, session, include_result=False)
    await _old_v137_show_final(context, chat_id, user, session)
    try:
        _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass


_old_build_application_v137 = build_application

def build_application() -> Application:
    app = _old_build_application_v137()
    app.add_handler(CallbackQueryHandler(_v137_settings_router, pattern=r'^t37\|'), group=-7800000002)
    app.add_handler(CallbackQueryHandler(_v137_tarot_save_router, pattern=r'^tar\|save\|'), group=-7800000001)
    app.add_handler(CallbackQueryHandler(_v137_tarot_start_router, pattern=r'^tar\|start\|'), group=-7800000000)
    logger.info('V137 Tarot limpieza configurable y resultado guardable cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V138Stop
except Exception:
    _V138Stop = Exception


def _v138_apply_card_order() -> None:
    """Ajusta el orden clásico que usa el usuario: 08 La Fuerza, 11 La Justicia.

    Se conservan los IDs internos: si subes imagen a 08, ahora corresponde a Fuerza;
    si subes imagen a 11, corresponde a Justicia.
    """
    global TAROT_CARDS_V129, TAROT_ORDER_V130
    try:
        by_id = {c.get('id'): c for c in TAROT_CARDS_V129}
        desired = [
            'loco','mago','sacerdotisa','emperatriz','emperador','hierofante','enamorados','carro',
            'fuerza','ermitano','rueda','justicia','colgado','muerte','templanza','diablo','torre',
            'estrella','luna','sol','juicio','mundo'
        ]
        new_cards = [by_id[i] for i in desired if i in by_id]

        new_cards.extend([c for c in TAROT_CARDS_V129 if c.get('id') not in desired])
        TAROT_CARDS_V129 = new_cards
        TAROT_ORDER_V130 = [c['id'] for c in TAROT_CARDS_V129]

        for c in TAROT_CARDS_V129:
            if c.get('id') == 'fuerza':
                c['name'] = 'La Fuerza'; c['emoji'] = '🦁'
                c['short'] = 'Coraje, calma y dominio interior.'
                c['meaning'] = 'La Fuerza habla de una valentía serena: no impone, sostiene. Esta carta te recuerda que la verdadera potencia aparece cuando dominas el impulso y actúas desde la calma, la ternura y la seguridad interior.'
            if c.get('id') == 'justicia':
                c['name'] = 'La Justicia'; c['emoji'] = '⚖️'
                c['short'] = 'Equilibrio, verdad y consecuencias.'
                c['meaning'] = 'La Justicia pide claridad, equilibrio y responsabilidad. Cada decisión tiene peso, y esta carta invita a mirar los hechos sin disfrazarlos: lo justo no siempre es cómodo, pero ordena el camino.'
    except Exception:
        logger.exception('No se pudo aplicar orden Tarot V138')

_v138_apply_card_order()


def _v138_card_by_id(cid: str) -> Optional[Dict[str, str]]:
    return next((c for c in TAROT_CARDS_V129 if c.get('id') == cid), None)


def _v138_extra_meaning(card: Dict[str, str], stage: str = '') -> str:
    name = card.get('name','esta carta')
    cid = card.get('id','')
    base = {
        'loco': 'En una tirada, El Loco no te dice que actúes sin pensar, sino que no conviertas el miedo en una jaula. Hay una puerta abierta, una experiencia nueva o una forma distinta de vivir algo. La clave está en caminar con frescura, pero sin negar las señales del camino.',
        'mago': 'El Mago indica que hay recursos disponibles: palabra, intención, carisma, contactos o talento. No esperes a que todo esté perfecto; esta carta aparece cuando ya tienes suficiente para iniciar el movimiento y transformar una idea en algo real.',
        'sacerdotisa': 'La Sacerdotisa habla de intuición y de información que aún no está del todo visible. Conviene observar, escuchar y no precipitarse. Hay una verdad que se revela mejor en silencio que en ruido.',
        'emperatriz': 'La Emperatriz trae crecimiento, cuidado y magnetismo. Lo que alimentes ahora puede tomar forma con fuerza. Habla de afecto, creatividad, belleza y de crear un espacio donde algo pueda florecer.',
        'emperador': 'El Emperador pide estructura. Cuando aparece, el mensaje es ordenar, decidir y sostener límites. No todo se arregla con emoción: también hace falta dirección, firmeza y responsabilidad.',
        'hierofante': 'El Hierofante invita a aprender, pedir consejo o respetar una enseñanza que viene de antes. Puede hablar de valores, tradición o guía. A veces avanzar no es romperlo todo, sino entender qué merece conservarse.',
        'enamorados': 'Los Enamorados señalan una elección importante, especialmente cuando deseo y razón no van por el mismo camino. Esta carta pide elegir desde la verdad, no desde la presión ni el miedo a decepcionar.',
        'carro': 'El Carro marca avance y voluntad. La energía está, pero necesita dirección. Si tomas las riendas, puedes moverte rápido; si dudas demasiado, otros acabarán conduciendo por ti.',
        'fuerza': 'La Fuerza no representa agresividad, sino dominio interior. Habla de calmar la fiera sin destruirla: usar la pasión, el carácter y el deseo a tu favor sin dejar que te gobiernen.',
        'ermitano': 'El Ermitaño aparece cuando necesitas perspectiva. No es soledad vacía, sino pausa útil. Hay respuestas que no se encuentran preguntando a todo el mundo, sino mirando con honestidad hacia dentro.',
        'rueda': 'La Rueda recuerda que todo cambia. Puede traer giros, oportunidades o cierres de ciclo. Lo importante no es controlar la rueda, sino saber colocarte cuando empieza a moverse.',
        'justicia': 'La Justicia pone la verdad sobre la mesa. Habla de equilibrio, acuerdos, consecuencias y decisiones limpias. Si algo está descompensado, esta carta pide corregirlo sin autoengaños.',
        'colgado': 'El Colgado invita a cambiar la mirada. Si algo se frena, quizá no es castigo: puede ser una pausa para entenderlo desde otro ángulo. A veces rendirse a la realidad abre más puertas que forzarla.',
        'muerte': 'La Muerte anuncia transformación. No tiene por qué ser algo oscuro: habla de soltar una piel vieja, cerrar una etapa o permitir que algo nuevo nazca donde antes había apego.',
        'templanza': 'La Templanza pide medida, paciencia y mezcla correcta. Ni exceso ni bloqueo. Esta carta aconseja armonizar emociones, tiempos y decisiones para que la situación madure sin romperse.',
        'diablo': 'El Diablo enseña aquello que engancha: deseo, miedo, dependencia, tentación o costumbre. No viene a juzgarte, sino a mostrar qué tiene poder sobre ti para que puedas recuperar el control.',
        'torre': 'La Torre sacude lo que estaba sostenido por una base débil. Puede incomodar, pero también libera. Cuando cae lo falso, queda espacio para construir algo más honesto.',
        'estrella': 'La Estrella trae calma, esperanza y una luz limpia después del ruido. No promete resultados inmediatos, pero sí una dirección más clara y una sensación de alivio que conviene proteger.',
        'luna': 'La Luna habla de dudas, emociones mezcladas y cosas que no se ven del todo. No es buen momento para decidir desde el miedo. Observa, espera claridad y no confundas intuición con fantasía.',
        'sol': 'El Sol ilumina, aclara y calienta. Trae energía de alegría, verdad y expansión. Cuando aparece, invita a mostrarse sin tantas defensas y a confiar en lo que se ve con claridad.',
        'juicio': 'El Juicio marca despertar. Algo pide respuesta: una conversación, una decisión o una nueva versión de ti. No se trata de culpa, sino de reconocer lo evidente y actuar en consecuencia.',
        'mundo': 'El Mundo habla de culminación, integración y logro. Una etapa se completa y deja aprendizaje. No es solo llegar a una meta: es entender quién eres después del camino recorrido.',
    }.get(cid, '')
    if stage:
        st = stage.lower()
        if 'pasado' in st:
            base += ' En el pasado, esta carta señala una energía que ha dejado huella y explica parte de lo que hoy pesa o sostiene la tirada.'
        elif 'presente' in st:
            base += ' En el presente, esta carta muestra la energía activa ahora mismo: lo que conviene mirar, ordenar o aprovechar en este momento.'
        elif 'futuro' in st:
            base += ' En el futuro, esta carta no sentencia; marca una tendencia probable si sigues alimentando la energía actual.'
    return base or f'{name} pide mirar la situación con más profundidad, sin quedarse solo en la primera impresión.'


def _v138_card_full_text(card: Dict[str, str], stage: str = '') -> str:
    meaning = str(card.get('meaning') or '').strip()
    extra = _v138_extra_meaning(card, stage)
    if extra and extra not in meaning:
        return meaning + '\n\n' + extra
    return meaning


_old_v138_lobby_markup = _v129_lobby_markup

def _v129_lobby_markup() -> InlineKeyboardMarkup:
    try:
        rows = [list(r) for r in _old_v138_lobby_markup().inline_keyboard]
    except Exception:
        rows = []

