async def _v129_show_card_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], card: Dict[str, str]) -> None:
    stage = _v129_stage_name(session)
    caption = (
        f"🔮 <b>{h(stage)}</b>\n"
        f"<b>{_v130_card_number(card.get('id',''))} · {h(card['name'])}</b> {card.get('emoji','')}\n\n"
        f"{h(_v138_card_full_text(card, stage))}"
    )
    photo = await _v138_card_photo(context, chat_id, card, stage)
    if session.get('mode') == 'ppf' and int(session.get('stage', 0) or 0) < 2:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('➡️ Siguiente tirada', callback_data='tar|next')]])
    else:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('🏁 Ver resultado final', callback_data='tar|final')]])
    try:
        if photo:
            from telegram import InputMediaPhoto
            await context.bot.edit_message_media(
                chat_id=chat_id,
                message_id=int(session.get('choice_msg_id')),
                media=InputMediaPhoto(media=photo, caption=caption[:1024], parse_mode=ParseMode.HTML),
                reply_markup=markup,
            )

            if len(caption) > 1024:
                extra_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
                session.setdefault('extra_msg_ids', []).append(int(extra_msg.message_id))
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=caption[:1024], parse_mode=ParseMode.HTML, reply_markup=markup)
            if len(caption) > 1024:
                extra_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
                session.setdefault('extra_msg_ids', []).append(int(extra_msg.message_id))
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        session['choice_msg_id'] = int(msg.message_id)


def _v138_result_text(user, session: Dict[str, Any], draws: List[Dict[str, str]]) -> str:
    title = '☀️ <b>RESULTADO DE TU CARTA DEL DÍA</b>' if session.get('mode') == 'day' else '🔮 <b>RESULTADO FINAL DE LA TIRADA</b>'
    lines = [title, f"Para {user.mention_html()}", '']
    if session.get('mode') == 'ppf':
        labels = [('🕰 Pasado','pasado'),('🔥 Presente','presente'),('✨ Futuro','futuro')]
        for (label, stage_key), c in zip(labels, draws):
            lines.append(f"{label}: <b>{_v130_card_number(c.get('id',''))} · {h(c['name'])}</b> {c.get('emoji','')}")
            lines.append(h(_v138_card_full_text(c, stage_key)))
            lines.append('')
        if len(draws) == 3:
            lines.append('<b>Lectura conjunta:</b>')
            lines.append(h(
                'La tirada muestra un recorrido: el pasado explica la raíz, el presente enseña la energía activa y el futuro marca la tendencia. No es una condena ni una promesa cerrada; es una lectura simbólica para comentar, reflexionar y decidir con más claridad.'
            ))
            lines.append('')
    else:
        c = draws[0]
        lines.append(f"<b>{_v130_card_number(c.get('id',''))} · {h(c['name'])}</b> {c.get('emoji','')}")
        lines.append(h(_v138_card_full_text(c, 'día de hoy')))
        lines.append('')
    lines.append('Comentad qué os transmite la tirada. A veces el grupo interpreta mejor que los arcanos 😄')
    txt = '\n'.join(lines)

    return txt[:3900]


async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    draws = session.get('draws', [])
    if not draws:
        return
    if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)):
        try:
            await _v137_delete_intermediate(context, chat_id, session, include_result=False)
        except Exception:
            pass

    for mid in list(session.get('extra_msg_ids', []) or []):
        try:
            await _v129_delete_msg(context.bot, chat_id, mid)
        except Exception:
            pass
    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_results', {})[result_id] = {
        'user_id': int(user.id),
        'user_name': display_name(user),
        'mode': session.get('mode','day'),
        'cards': [c['id'] for c in draws],
        'likes': [],
        'ts': int(time.time()),
    }
    save_all_states()
    text = _v138_result_text(user, session, draws)
    rows = [
        [InlineKeyboardButton('❤️ Me gusta · 0', callback_data=f'tar|like|{result_id}')],
        [InlineKeyboardButton('🔮 Opinión de tarotista IA', callback_data=f'tar|ai|{result_id}')],
        [InlineKeyboardButton('🃏 Ver mis cartas', callback_data=f'tar|showdraw|{result_id}'), InlineKeyboardButton('💾 Guardar en privado', callback_data=f'tar|save|{result_id}')],
        [InlineKeyboardButton('📖 Ver arcanos', callback_data='tar|cards|0')],
    ]
    msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
    session['final_msg_id'] = int(msg.message_id)
    _v129_inc_usage(chat_id, int(user.id), session.get('mode','day'))
    try:
        _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass
    sec=_v132_cleanup_get(chat_id, 'tarot_cleanup_result_sec', 0) if '_v132_cleanup_get' in globals() else 0
    if sec:
        asyncio.create_task(_v132_auto_delete(context.bot, chat_id, int(session.get('final_msg_id')), sec))


async def _v138_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    data = q.data or ''
    if not data.startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = data.split('|', 2)[2]
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not res:
        await q.answer('No encuentro esa tirada.', show_alert=True); raise _V138Stop
    cards = []
    for cid in res.get('cards', []) or []:
        c = _v138_card_by_id(cid)
        if c:
            cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V138Stop
    await q.answer('Consultando al tarotista IA…')
    labels = ['Pasado','Presente','Futuro'] if len(cards) == 3 else ['Carta del día']
    card_lines = []
    for label, c in zip(labels, cards):
        card_lines.append(f"{label}: {c.get('name')} ({c.get('short')}). Significado base: {c.get('meaning')}")
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro para un grupo de Telegram llamado EL PLAN. '
        'Interpreta esta tirada de tarot de forma simbólica, sin afirmar certezas absolutas ni hacer predicciones médicas, legales o peligrosas. '
        'Explica cómo se relacionan las cartas entre sí, qué energía trae cada una y qué consejo práctico puede extraer la persona. '
        'Tono místico, humano y fácil de entender.\n\n'
        + '\n'.join(card_lines)
    )
    wait = None
    try:
        wait = await q.message.reply_html('🔮 Consultando al tarotista IA…')
        if '_v57_cerebrito_answer' in globals():
            ans = await _v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900)
        else:
            ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=900)
        try:
            await wait.edit_text('🔮 <b>Opinión del tarotista IA</b>\n\n' + h(ans[:3500]), parse_mode=ParseMode.HTML)
        except Exception:
            await context.bot.send_message(chat_id, '🔮 <b>Opinión del tarotista IA</b>\n\n' + h(ans[:3500]), parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V138')
        if wait:
            try: await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
            except Exception: pass
        else:
            await q.answer('Error IA. Revisa logs.', show_alert=True)
    raise _V138Stop


async def _v138_tarot_close_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('tar|close'):
        return
    try:
        await q.answer('Tarot cerrado')
    except Exception:
        pass
    try:
        await q.message.delete()
    except Exception:
        try:
            await q.edit_message_text('🔮 Tarot cerrado.')
        except Exception:
            pass
    raise _V138Stop


