def _v139_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_ai_enabled', True)
    cfg.setdefault('tarot_ai_limit_day', 2)
    cfg.setdefault('tarot_cleanup_ai_sec', 0)
    cfg.setdefault('tarot_ai_usage', {})
    return cfg


def _v139_today_key() -> str:
    try:
        return _local_dt_v15(int(time.time())).strftime('%Y-%m-%d')
    except Exception:
        import datetime
        return datetime.datetime.now().strftime('%Y-%m-%d')


def _v139_ai_used(chat_id: int, user_id: int) -> int:
    cfg = _v139_tarot_cfg(chat_id)
    usage = cfg.setdefault('tarot_ai_usage', {})
    day = usage.setdefault(_v139_today_key(), {})
    try:
        return int(day.get(str(int(user_id)), 0) or 0)
    except Exception:
        return 0


def _v139_ai_inc(chat_id: int, user_id: int) -> None:
    cfg = _v139_tarot_cfg(chat_id)
    usage = cfg.setdefault('tarot_ai_usage', {})

    if isinstance(usage, dict) and len(usage) > 14:
        for k in sorted(list(usage.keys()))[:-10]:
            usage.pop(k, None)
    day = usage.setdefault(_v139_today_key(), {})
    uid = str(int(user_id))
    day[uid] = int(day.get(uid, 0) or 0) + 1
    save_all_states()


def _v139_can_use_ai(chat_id: int, user_id: int) -> Tuple[bool, str]:
    cfg = _v139_tarot_cfg(chat_id)
    if not bool(cfg.get('tarot_ai_enabled', True)):
        return False, 'La consulta al tarotista IA está desactivada.'
    limit = int(cfg.get('tarot_ai_limit_day', 2) or 0)
    if limit > 0 and _v139_ai_used(chat_id, user_id) >= limit:
        return False, f'Has alcanzado el límite de {limit} consulta(s) al tarotista IA por día.'
    return True, ''


def _v139_onoff(v: bool) -> str:
    return 'ON ✅' if bool(v) else 'OFF ❌'


def _v139_sec_label(sec: int) -> str:
    return _v132_sec_label(sec) if '_v132_sec_label' in globals() else ('No borrar' if not sec else f'{sec}s')


