async def _v139_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t39|'):
        return
    parts = q.data.split('|')
    try:
        action = parts[1]
        chat_id = int(parts[2])
        cfg = _v139_tarot_cfg(chat_id)
        if action == 'noop':
            await q.answer(); raise _V139Stop
        if action == 'aitog':
            cfg['tarot_ai_enabled'] = not bool(cfg.get('tarot_ai_enabled', True)); save_all_states()
            await q.answer('Tarotista IA actualizado ✅')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
            raise _V139Stop
        if action == 'ailim':
            delta = int(parts[3])
            current = int(cfg.get('tarot_ai_limit_day', 2) or 0)
            cfg['tarot_ai_limit_day'] = max(0, current + delta); save_all_states()
            await q.answer('Límite actualizado ✅')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
            raise _V139Stop
        if action == 'aiclean':
            await q.answer()
            await _v132_edit(q, _v139_ai_clean_text(chat_id), _v139_ai_clean_markup(chat_id))
            raise _V139Stop
        if action == 'aicleanset':
            cfg['tarot_cleanup_ai_sec'] = int(parts[3]); save_all_states()
            await q.answer('Borrado IA actualizado ✅')
            await _v132_edit(q, _v139_ai_clean_text(chat_id), _v139_ai_clean_markup(chat_id))
            raise _V139Stop
    except _V139Stop:
        raise
    except Exception:
        logger.exception('Error settings Tarot V139: %s', q.data)
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V139Stop


async def _v139_auto_delete(bot, chat_id: int, message_id: int, sec: int) -> None:
    try:
        sec = int(sec)
    except Exception:
        sec = 0
    if sec <= 0:
        return
    await asyncio.sleep(sec)
    try:
        await bot.delete_message(chat_id, int(message_id))
    except Exception:
        pass


async def _v139_card_pil(context: ContextTypes.DEFAULT_TYPE, source_chat_id: int, card: Dict[str, str]):

    try:
        return await _v137_card_pil(context, source_chat_id, card)
    except Exception:
        pass
    from PIL import Image, ImageDraw
    img = Image.new('RGB', (320, 460), (28, 18, 54))
    d = ImageDraw.Draw(img)
    d.rectangle([8,8,312,452], outline=(214,178,92), width=3)
    d.text((24,40), card.get('name','Carta'), fill=(255,255,255))
    return img


def _v139_wrap_text(draw, text: str, font, max_width: int, max_lines: int = 5) -> List[str]:
    words = str(text or '').split()
    lines, cur = [], ''
    for w in words:
        test = (cur + ' ' + w).strip()
        try:
            bbox = draw.textbbox((0,0), test, font=font)
            width = bbox[2]-bbox[0]
        except Exception:
            width = len(test)*10
        if width <= max_width:
            cur = test
        else:
            if cur:
                lines.append(cur)
            cur = w
        if len(lines) >= max_lines:
            break
    if cur and len(lines) < max_lines:
        lines.append(cur)
    if len(lines) == max_lines and len(' '.join(words)) > len(' '.join(lines)):
        lines[-1] = lines[-1].rstrip('.,;:') + '…'
    return lines


async def _v139_make_result_image(context: ContextTypes.DEFAULT_TYPE, source_chat_id: int, user_name: str, cards: List[str]):
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO
    from datetime import datetime
    card_objs = []
    for cid in cards:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id'] == cid), None)
        if c:
            card_objs.append(c)
    if not card_objs:
        return None
    labels = ['PASADO','PRESENTE','FUTURO'] if len(card_objs) == 3 else ['CARTA DEL DÍA']

    card_w, card_h = (300, 450) if len(card_objs) == 3 else (420, 620)
    gap = 22
    side = 34
    header_h = 130
    summary_h = 260 if len(card_objs) == 3 else 220
    footer_h = 46
    w = max(900, side*2 + len(card_objs)*card_w + (len(card_objs)-1)*gap)
    hgt = header_h + card_h + summary_h + footer_h
    out = Image.new('RGB', (w, hgt), (18, 11, 35))
    d = ImageDraw.Draw(out)
    try:
        font_title = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 42)
        font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 23)
        font_b = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 24)
        font_s = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 18)
    except Exception:
        font_title = font = font_b = font_s = None
    d.text((side, 24), 'TAROT EL PLAN', fill=(245, 220, 145), font=font_title)
    date_s = datetime.now().strftime('%d/%m/%Y · %H:%M')
    d.text((side, 82), f'Tirada de {user_name} · {date_s}', fill=(235,235,245), font=font)
    start_x = (w - (len(card_objs)*card_w + (len(card_objs)-1)*gap))//2
    y = header_h
    for i, c in enumerate(card_objs):
        im = await _v139_card_pil(context, source_chat_id, c)
        im.thumbnail((card_w, card_h))
        canvas = Image.new('RGB', (card_w, card_h), (12, 8, 22))
        canvas.paste(im, ((card_w-im.width)//2, (card_h-im.height)//2))
        x = start_x + i*(card_w+gap)
        out.paste(canvas, (x, y))
        d.rectangle([x, y, x+card_w-1, y+card_h-1], outline=(214,178,92), width=3)
        d.text((x+12, y+12), labels[i] if i < len(labels) else '', fill=(245,220,145), font=font_b)
        d.text((x+12, y+card_h-36), f"{_v130_card_number(c.get('id','')) if '_v130_card_number' in globals() else c.get('id','')} · {c.get('name','')}", fill=(255,255,255), font=font_s)
    sy = header_h + card_h + 26
    d.text((side, sy), 'Resumen de la tirada', fill=(245,220,145), font=font_b)
    sy += 36
    if len(card_objs) == 3:
        summary = (
            f"Pasado: {card_objs[0].get('name')}. Presente: {card_objs[1].get('name')}. Futuro: {card_objs[2].get('name')}. "
            'La lectura une lo vivido, lo que se mueve ahora y la tendencia que puede abrirse si la energía actual continúa.'
        )
    else:
        summary = f"Carta del día: {card_objs[0].get('name')}. Una señal simbólica para mirar el día con más intención, calma y claridad."
    for line in _v139_wrap_text(d, summary, font, w-side*2, max_lines=5):
        d.text((side, sy), line, fill=(230,230,240), font=font)
        sy += 31
    d.text((side, hgt-34), 'Toca la imagen en Telegram y guárdala en tu galería.', fill=(185,175,210), font=font_s)
    bio = BytesIO()
    bio.name = 'tarot_el_plan_resultado.jpg'
    out.save(bio, format='JPEG', quality=92, optimize=True)
    bio.seek(0)
    return bio


async def _v139_tarot_save_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    if not (q.data or '').startswith('tar|save|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = (q.data or '').split('|', 2)[2]
    try:
        cfg = _v129_tarot_cfg(chat_id)
        res = cfg.setdefault('tarot_results', {}).get(rid)
        if not isinstance(res, dict):
            await q.answer('No encuentro esta tirada.', show_alert=True); raise _V139Stop
        cards = list(res.get('cards') or [])
        if not cards:
            await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V139Stop
        await q.answer('Creando imagen para guardar…')
        img = await _v139_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards)
        if not img:
            await q.answer('No pude crear la imagen.', show_alert=True); raise _V139Stop
        msg = await context.bot.send_photo(chat_id, photo=img, caption='💾 Imagen de la tirada lista para guardar en galería.')
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass
        sec = int(_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) or 0)
        if sec:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec))
        raise _V139Stop
    except _V139Stop:
        raise
    except Exception:
        logger.exception('Error guardando imagen Tarot V139')
        try: await q.answer('Error creando imagen. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V139Stop


async def _v139_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    data = q.data or ''
    if not data.startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not res:
        await q.answer('No encuentro esa tirada.', show_alert=True); raise _V139Stop
    ok, why = _v139_can_use_ai(chat_id, int(q.from_user.id))
    if not ok:
        await q.answer(why, show_alert=True); raise _V139Stop
    cards = []
    for cid in res.get('cards', []) or []:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x.get('id') == cid), None)
        if c: cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V139Stop
    await q.answer('Consultando al tarotista IA…')
    labels = ['Pasado','Presente','Futuro'] if len(cards) == 3 else ['Carta del día']
    card_lines = [f"{label}: {c.get('name')} ({c.get('short')}). Significado base: {c.get('meaning')}" for label,c in zip(labels,cards)]
    user_name = str(res.get('user_name') or display_name(q.from_user) or 'la persona consultante')
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        f'La persona consultante se llama {user_name}. Dirígete a esa persona o habla de forma neutra; no digas que EL PLAN es quien consulta ni te refieras al bot como consultante. '
        'Interpreta esta tirada de tarot de forma simbólica, sin afirmar certezas absolutas ni hacer predicciones médicas, legales o peligrosas. '
        'Explica cómo se relacionan las cartas entre sí, qué energía trae cada una y qué consejo práctico puede extraer la persona. '
        'Tono místico, humano y fácil de entender.\n\n' + '\n'.join(card_lines)
    )
    wait = None
    try:
        wait = await q.message.reply_html(f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…')
        if '_v57_cerebrito_answer' in globals():
            ans = await _v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900)
        else:
            ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=900)
        _v139_ai_inc(chat_id, int(q.from_user.id))
        text = '🔮 <b>Opinión del tarotista IA</b>\n\n' + h(ans[:3500])
        try:
            edited = await wait.edit_text(text, parse_mode=ParseMode.HTML)
            mid = int(wait.message_id)
        except Exception:
            msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)
            mid = int(msg.message_id)
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        if sec:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, mid, sec))
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V139')
        if wait:
            try: await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
            except Exception: pass
        else:
            await q.answer('Error IA. Revisa logs.', show_alert=True)
    raise _V139Stop


