def _v140_perm_text(chat_id: int) -> str:
    cfg = _v140_tarot_cfg(chat_id)
    role = str(cfg.get('tarot_perm_role', 'members') or 'members')
    ids = sorted(_v140_manual_ids(chat_id))
    users = sorted(_v140_manual_usernames(chat_id))
    lines = [
        '<b>🔐 Permisos del Tarot</b>',
        '',
        f'Actual: <b>{h(_v140_role_label(role))}</b>',
        '',
        '<b>Usuarios manuales:</b>',
    ]
    if ids or users:
        for x in ids[:15]:
            lines.append(f'• ID <code>{x}</code>')
        for u in users[:15]:
            lines.append(f'• @{h(u)}')
    else:
        lines.append('<i>Ninguno</i>')
    return '\n'.join(lines)


def _v140_perm_markup(chat_id: int) -> InlineKeyboardMarkup:
    role = str(_v140_tarot_cfg(chat_id).get('tarot_perm_role', 'members') or 'members')
    rows = []
    for key, label in [('members','👥 Miembros'),('admins','🛡 Admins'),('admin_ids','🆔 IDs Admin'),('manual','👤 Solo manuales')]:
        rows.append([InlineKeyboardButton(('✅ ' if key == role else '') + label, callback_data=f't40|role|{chat_id}|{key}')])
    rows.append([InlineKeyboardButton('➕ Añadir usuario manual', callback_data=f't40|add|{chat_id}'), InlineKeyboardButton('🧹 Vaciar manuales', callback_data=f't40|clear|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v140_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t40|'):
        return
    parts = q.data.split('|')
    try:
        action = parts[1]
        chat_id = int(parts[2])
        cfg = _v140_tarot_cfg(chat_id)
        if action == 'perm':
            await q.answer()
            await _v132_edit(q, _v140_perm_text(chat_id), _v140_perm_markup(chat_id))
            raise _V140Stop
        if action == 'role':
            role = parts[3]
            if role not in _TAROT_ROLE_LABELS_V140:
                await q.answer('Rol inválido', show_alert=True); raise _V140Stop
            cfg['tarot_perm_role'] = role
            save_all_states()
            await q.answer('Permisos actualizados ✅')
            await _v132_edit(q, _v140_perm_text(chat_id), _v140_perm_markup(chat_id))
            raise _V140Stop
        if action == 'add':
            set_config_pending(q.from_user.id, {'kind': 'tarot_perm_add_v140', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html('➕ <b>Añadir usuario al Tarot</b>\n\nEnvía un ID numérico o @username.\n\nEjemplos:\n<code>123456789</code>\n<code>@usuario</code>')
            raise _V140Stop
        if action == 'clear':
            cfg['tarot_perm_manual_ids'] = []
            cfg['tarot_perm_manual_usernames'] = []
            save_all_states()
            await q.answer('Usuarios manuales borrados ✅')
            await _v132_edit(q, _v140_perm_text(chat_id), _v140_perm_markup(chat_id))
            raise _V140Stop
    except _V140Stop:
        raise
    except Exception:
        logger.exception('Error permisos Tarot V140')
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V140Stop


_old_v140_config_text = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending and pending.get('kind') == 'tarot_perm_add_v140':
            chat_id = int(pending.get('chat_id') or 0)
            raw = (update.message.text or update.message.caption or '').strip()
            cfg = _v140_tarot_cfg(chat_id)
            if raw.startswith('@') or (raw and not raw.lstrip('-').isdigit()):
                username = raw.strip().lower().lstrip('@').split()[0]
                arr = cfg.setdefault('tarot_perm_manual_usernames', [])
                if username and username not in arr:
                    arr.append(username)
            else:
                try:
                    uid = int(raw)
                    arr = cfg.setdefault('tarot_perm_manual_ids', [])
                    if uid not in arr:
                        arr.append(uid)
                except Exception:
                    await update.message.reply_html('❌ No entendí el usuario. Envía ID numérico o @username.')
                    return True
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html('✅ Usuario añadido a permisos del Tarot.')
            return True
    return await _old_v140_config_text(update, context)


_old_build_application_v140 = build_application

def build_application() -> Application:
    app = _old_build_application_v140()
    app.add_handler(command_handler('tarot', _v140_tarot_command_guard), group=-8100000000)
    app.add_handler(CallbackQueryHandler(_v140_tarot_start_guard, pattern=r'^tar\|start\|'), group=-8100000001)
    app.add_handler(CallbackQueryHandler(_v140_settings_router, pattern=r'^t40\|'), group=-8100000002)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, admin_private_config_text), group=-8100000003)
    logger.info('V140 Tarot final limpio y permisos cargado')
    return app


