def _v141_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v140_tarot_cfg(chat_id) if '_v140_tarot_cfg' in globals() else (_v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id))
    cfg.setdefault('tarot_shuffle_seconds', 10)
    return cfg


def _v141_shuffle_seconds(chat_id: int) -> int:
    try:
        sec = int(_v141_tarot_cfg(chat_id).get('tarot_shuffle_seconds', 10) or 10)
    except Exception:
        sec = 10
    return max(1, min(60, sec))


def _v141_stage_for_shuffle(session: Dict[str, Any]) -> str:
    try:
        return _v129_stage_name(session)
    except Exception:
        return 'Carta'


def _v141_shuffle_caption(user, session: Dict[str, Any], seconds: int) -> str:
    stage = _v141_stage_for_shuffle(session)
    return (
        f"🔮 <b>Barajando…</b>\n\n"
        f"{user.mention_html()}, las cartas se están mezclando para <b>{h(stage)}</b>.\n"
        f"Respira, concéntrate y deja que los arcanos se coloquen.\n\n"
        f"⏳ En unos <b>{seconds} segundos</b> podrás elegir carta."
    )


async def _v141_delete_existing_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]) -> None:
    for key in ('draws_msg_id', 'choice_msg_id', 'shuffle_msg_id'):
        try:
            await _v137_safe_delete(context.bot, chat_id, session.get(key)) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, session.get(key))
        except Exception:
            pass
        session[key] = 0
    for mid in list(session.get('extra_msg_ids', []) or []):
        try:
            await _v137_safe_delete(context.bot, chat_id, mid) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, mid)
        except Exception:
            pass
    session['extra_msg_ids'] = []


async def _v141_send_shuffle_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> int:
    seconds = _v141_shuffle_seconds(chat_id)
    caption = _v141_shuffle_caption(user, session, seconds)
    imgs = _v136_tarot_images(chat_id) if '_v136_tarot_images' in globals() else _v130_tarot_images(chat_id)
    shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
    msg = None
    if shuffle_id:
        try:
            photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
            msg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
        except Exception:
            logger.exception('No se pudo enviar imagen de barajeo V141; uso texto')
    if msg is None:
        msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
    session['shuffle_msg_id'] = int(msg.message_id)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    return int(msg.message_id)


async def _v141_shuffle_then_choice(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:

    await _v141_delete_existing_pair(context, chat_id, session)
    await _v141_send_shuffle_message(context, chat_id, user, session)
    await asyncio.sleep(_v141_shuffle_seconds(chat_id))

    if bool(_v141_tarot_cfg(chat_id).get('tarot_delete_shuffle_msg', True)):
        try:
            await _v137_safe_delete(context.bot, chat_id, session.get('shuffle_msg_id')) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, session.get('shuffle_msg_id'))
        except Exception:
            pass
        session['shuffle_msg_id'] = 0
    await _v129_send_pair(context, chat_id, user, session, new_pair=True)
    save_all_states()


async def _v141_tarot_start_next_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in {'start', 'next'}:
        return
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    skey = _v129_session_key(chat_id, int(user.id))
    try:
        if action == 'start':
            mode = parts[2] if len(parts) > 2 else 'day'
            if mode not in ('ppf', 'day'):
                mode = 'day'
            if '_v140_user_can_tarot' in globals():
                allowed = await _v140_user_can_tarot(context, chat_id, user)
                if not allowed:
                    await q.answer('No tienes permiso para usar el Tarot.', show_alert=True)
                    raise _V141Stop
            try:
                locked, reason = _v133_is_chat_locked(chat_id, int(user.id)) if '_v133_is_chat_locked' in globals() else (False, '')
                if locked:
                    await q.answer(reason, show_alert=True)
                    raise _V141Stop
                if '_v133_mark_tarot_started' in globals():
                    _v133_mark_tarot_started(chat_id, int(user.id))
            except _V141Stop:
                raise
            except Exception:
                pass
            ok, reason = _v129_can_play(chat_id, int(user.id), mode)
            if not ok:
                await q.answer(reason, show_alert=True)
                raise _V141Stop
            old = TAROT_SESSIONS_V129.get(skey)
            if isinstance(old, dict):
                await _v141_delete_existing_pair(context, chat_id, old)
            session = {
                'chat_id': chat_id,
                'user_id': int(user.id),
                'mode': mode,
                'stage': 0,
                'draws': [],
                'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)) if '_v135_mystic_shuffle_deck' in globals() else [c['id'] for c in TAROT_CARDS_V129],
                'started_ts': int(time.time()),
                'lobby_msg_id': int(q.message.message_id) if q.message else 0,
            }
            TAROT_SESSIONS_V129[skey] = session
            cfg = _v141_tarot_cfg(chat_id)
            await q.answer(f'Barajando { _v141_shuffle_seconds(chat_id) } segundos…')
            if bool(cfg.get('tarot_delete_lobby_on_start', True)) and q.message:
                try:
                    await _v137_safe_delete(context.bot, chat_id, q.message.message_id) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, q.message.message_id)
                except Exception:
                    pass
                session['lobby_msg_id'] = 0
            await _v141_shuffle_then_choice(context, chat_id, user, session)
            raise _V141Stop

        if action == 'next':
            session = TAROT_SESSIONS_V129.get(skey)
            if not session:
                await q.answer('No tienes una tirada activa.', show_alert=True)
                raise _V141Stop
            session['stage'] = int(session.get('stage', 0) or 0) + 1
            await q.answer(f'Barajando {_v141_shuffle_seconds(chat_id)} segundos…')
            await _v141_shuffle_then_choice(context, chat_id, user, session)
            raise _V141Stop
    except _V141Stop:
        raise
    except Exception:
        logger.exception('Error Tarot V141 start/next: %s', data)
        try:
            await q.answer('Error en Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V141Stop


