async def _v141_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t41|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts)>1 else ''
    try:
        chat_id = int(parts[2])
        if action == 'shuffle':
            await q.answer()
            await _v132_edit(q, _v141_shuffle_settings_text(chat_id), _v141_shuffle_settings_markup(chat_id))
            raise _V141Stop
        if action == 'setshuffle':
            sec = int(parts[3])
            _v141_tarot_cfg(chat_id)['tarot_shuffle_seconds'] = max(1, min(60, sec))
            save_all_states()
            await q.answer('Tiempo actualizado ✅')
            await _v132_edit(q, _v141_shuffle_settings_text(chat_id), _v141_shuffle_settings_markup(chat_id))
            raise _V141Stop
    except _V141Stop:
        raise
    except Exception:
        logger.exception('Error ajustes barajeo Tarot V141')
        try:
            await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V141Stop


