async def tarot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_html('🔮 Usa <code>/tarot</code> dentro del grupo para abrir el Tarot del Plan.')
        raise _V142Stop
    chat_id = int(update.effective_chat.id)
    if not bool(_v129_tarot_cfg(chat_id).get('tarot_enabled', True)):
        await update.message.reply_text('🔮 El Tarot del Plan está desactivado en este grupo.')
        raise _V142Stop
    try:
        if '_v140_user_can_tarot' in globals() and not await _v140_user_can_tarot(context, chat_id, update.effective_user):
            await update.message.reply_text('🔮 No tienes permiso para ejecutar el Tarot en este grupo.')
            raise _V142Stop
    except _V142Stop:
        raise
    except Exception:
        pass
    await _v130_send_lobby(context.bot, chat_id, update.effective_user)
    raise _V142Stop


_old_build_application_v142 = build_application

def build_application() -> Application:
    app = _old_build_application_v142()
    app.add_handler(CommandHandler(['tarot','tarotplan'], tarot_command), group=-8300000000)
    logger.info('V142 Tarot lobby misterioso definitivo cargado')
    return app


