async def _v144_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t44|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
        if action == 'emojis':
            set_config_pending(q.from_user.id, {'kind': 'tarot_shuffle_emojis_v144', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html(
                '✨ Envíame ahora <b>uno o dos emojis</b> para mostrar junto a ✨ en el barajeo.\n\n'
                'Puedes enviar emojis normales o emojis premium de Telegram.'
            )
            raise _V144Stop
    except _V144Stop:
        raise
    except Exception:
        logger.exception('Error ajustes Tarot V144')
        try:
            await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V144Stop


async def _v144_shuffle_emojis_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_shuffle_emojis_v144':
        return
    chat_id = int(pending.get('chat_id') or 0)
    raw = ''
    try:
        raw = telegram_html_from_message(update.message).strip()
    except Exception:
        raw = ''
    if not raw:
        try:
            raw = plain_text_from_message(update.message).strip()
        except Exception:
            raw = (update.message.text or '').strip()
    if not raw:
        await update.message.reply_html('No he detectado emojis. Envíame 1 o 2 emojis.')
        raise _V144Stop
    _v144_tarot_cfg(chat_id)['tarot_shuffle_magic_emojis_html'] = raw[:500]
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html('✅ Emojis de barajeo guardados.\n\n' + _v132_tarot_settings_text(chat_id), reply_markup=_v132_tarot_settings_markup(chat_id))
    raise _V144Stop


_old_build_application_v144 = build_application

def build_application() -> Application:
    app = _old_build_application_v144()
    app.add_handler(CallbackQueryHandler(_v144_settings_router, pattern=r'^t44\|'), group=-8500000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v144_shuffle_emojis_text_handler), group=-8500000000)
    logger.info('V144 Tarot botones elección, emojis premium barajeo y etapas PASADO/PRESENTE/FUTURO cargado')
    return app


