async def _v146_send_or_update_ai_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str, op: Dict[str, Any], *, reply_to=None, image_id: str = ''):
    markup = _v146_ai_markup(rid)
    msg_id = int(op.get('message_id') or 0)
    has_photo = bool(op.get('has_photo'))
    if msg_id:
        try:
            if has_photo:
                await context.bot.edit_message_caption(chat_id=chat_id, message_id=msg_id, caption=_v146_ai_full_text(op, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup)
            else:
                await context.bot.edit_message_text(chat_id=chat_id, message_id=msg_id, text=_v146_ai_full_text(op), parse_mode=ParseMode.HTML, reply_markup=markup)
            return msg_id
        except Exception:
            pass
    if image_id:
        sent = await context.bot.send_photo(chat_id, photo=image_id, caption=_v146_ai_full_text(op, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup, reply_to_message_id=reply_to)
        op['has_photo'] = True
    else:
        sent = await context.bot.send_message(chat_id, _v146_ai_full_text(op), parse_mode=ParseMode.HTML, reply_markup=markup, reply_to_message_id=reply_to)
        op['has_photo'] = False
    op['message_id'] = int(sent.message_id)
    save_all_states()
    return int(sent.message_id)


async def _v146_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esa tirada.', show_alert=True)
        raise _V146Stop
    ok, reason = _v139_can_use_ai(chat_id, int(q.from_user.id)) if '_v139_can_use_ai' in globals() else (True, '')
    store = _v146_ai_store(chat_id)
    cached = store.get(rid)

    if isinstance(cached, dict) and cached.get('answer'):
        await q.answer('Opinión ya generada ✅')
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        await _v146_send_or_update_ai_message(context, chat_id, rid, cached, reply_to=q.message.message_id if q.message else None, image_id=img)
        raise _V146Stop
    if not ok:
        await q.answer(reason, show_alert=True)
        raise _V146Stop
    cards = []
    for cid in res.get('cards', []) or []:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id'] == cid), None)
        if c:
            cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True)
        raise _V146Stop
    user_name = str(res.get('user_name') or 'la persona que hizo la tirada')
    await q.answer('Consultando al tarotista IA…')
    labels = ['Pasado','Presente','Futuro'] if len(cards) == 3 else ['Carta del día']
    card_lines = []
    for label, c in zip(labels, cards):
        card_lines.append(f"{label}: {c.get('name')} ({c.get('short')}). Significado base: {c.get('meaning')}")
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        f'La persona consultante es {user_name}; si no encaja mencionar el nombre, habla de forma neutra como “la persona consultante”. '
        'No digas que EL PLAN consulta ni que el bot consulta. '
        'Interpreta esta tirada de forma simbólica, sin afirmar certezas absolutas ni hacer predicciones médicas, legales o peligrosas. '
        'Explica cómo se relacionan las cartas, qué energía trae cada una y qué consejo práctico puede extraer. '
        'Tono místico, humano y fácil de entender. Sé claro, con una lectura bonita pero no larguísima.\n\n' + '\n'.join(card_lines)
    )
    wait = None
    try:
        wait = await q.message.reply_html(f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…')
        ans = await (_v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900) if '_v57_cerebrito_answer' in globals() else _ai_openai_response(chat_id, prompt, max_output_tokens=900))
        op = {
            'answer': str(ans or '').strip(),
            'likes': [],
            'flips': [],
            'created_ts': int(time.time()),
            'result_id': rid,
            'user_name': user_name,
        }
        store[rid] = op
        try:
            await wait.delete()
        except Exception:
            pass
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        mid = await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=q.message.message_id if q.message else None, image_id=img)
        try:
            _v139_ai_inc(chat_id, int(q.from_user.id))
        except Exception:
            pass
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        if sec and mid:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(mid), sec))
        save_all_states()
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V146')
        if wait:
            try:
                await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
            except Exception:
                pass
        else:
            await q.answer('Error IA. Revisa logs.', show_alert=True)
    raise _V146Stop


async def _v146_ai_reaction_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|air|'):
        return
    parts = data.split('|')
    if len(parts) < 4:
        return
    chat_id = int(update.effective_chat.id)
    rid = parts[2]
    kind = parts[3]
    store = _v146_ai_store(chat_id)
    op = store.get(rid)
    if not isinstance(op, dict):
        await q.answer('No encuentro esta opinión IA.', show_alert=True)
        raise _V146Stop
    uid = str(int(q.from_user.id))
    key = 'likes' if kind == 'like' else 'flips'
    arr = op.setdefault(key, [])
    if uid in arr:
        await q.answer('Ya habías pulsado aquí ✅')
    else:
        arr.append(uid)
        save_all_states()
        await q.answer('Guardado ✨')
    await _v146_send_or_update_ai_message(context, chat_id, rid, op)
    raise _V146Stop


