async def _v147_update_result_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str) -> None:
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        return
    mid = int(res.get('message_id') or 0)
    if not mid:
        return
    base = str(res.get('text') or '')
    markup = _v147_final_markup(chat_id, rid)
    try:
        if res.get('photo'):
            await context.bot.edit_message_caption(chat_id=chat_id, message_id=mid, caption=_v147_result_caption_or_text(base, chat_id, rid, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v147_result_caption_or_text(base, chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=markup)
    except BadRequest as e:
        if 'not modified' not in str(e).lower():
            logger.warning('No pude actualizar resultado Tarot %s: %s', rid, e)
    except Exception:
        logger.exception('No pude actualizar resultado Tarot %s', rid)


_old_v147_show_final = _v129_show_final
async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    draws = session.get('draws', [])
    if not draws:
        return
    if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)) if '_v137_tarot_cfg' in globals() else True:
        try:
            await _v137_delete_intermediate(context, chat_id, session, include_result=False)
        except Exception:
            pass
    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cards = [c['id'] for c in draws]
    text = _v138_result_text(user, session, draws) if '_v138_result_text' in globals() else _v130_result_text(user, session, draws)
    res = {
        'user_id': int(user.id),
        'user_name': display_name(user),
        'cards': cards,
        'likes': [],
        'flips': [],
        'ts': int(time.time()),
        'text': text,
    }
    cfg.setdefault('tarot_results', {})[result_id] = res
    _v147_result_op(chat_id, result_id)
    save_all_states()
    img = str((_v143_tarot_images(chat_id).get('result') if '_v143_tarot_images' in globals() else '') or '')
    try:
        if img:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=_v147_result_caption_or_text(text, chat_id, result_id, max_len=980), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
            res['photo'] = True
        else:
            msg = await context.bot.send_message(chat_id, _v147_result_caption_or_text(text, chat_id, result_id), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
            res['photo'] = False
    except Exception:
        logger.exception('No pude enviar resultado Tarot V147')
        msg = await context.bot.send_message(chat_id, _v147_result_caption_or_text(text, chat_id, result_id), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
        res['photo'] = False
    res['message_id'] = int(msg.message_id)
    session['final_msg_id'] = int(msg.message_id)
    try: await register_bot_message(chat_id, msg.message_id)
    except Exception: pass
    save_all_states()
    try:
        _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass
    sec = int((_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) if '_v139_tarot_cfg' in globals() else 0) or 0)
    if sec:

        asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, int(msg.message_id)))


async def _v147_result_reaction_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|rr|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id)
    rid = parts[2] if len(parts) > 2 else ''
    kind = parts[3] if len(parts) > 3 else 'like'
    key = 'likes' if kind == 'like' else 'flips'
    op = _v147_result_op(chat_id, rid)
    uid = int(q.from_user.id)
    arr = [int(x) for x in op.get(key, [])]
    if uid in arr:
        await q.answer('Ya lo habías pulsado ✅')
    else:
        arr.append(uid); op[key] = arr; save_all_states(); await q.answer('Guardado ✨')
    await _v147_update_result_message(context, chat_id, rid)
    raise _V147Stop


async def _v147_tarot_save_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|save|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    try:
        cfg = _v129_tarot_cfg(chat_id)
        res = cfg.setdefault('tarot_results', {}).get(rid)
        if not isinstance(res, dict):
            await q.answer('No encuentro esta tirada.', show_alert=True); raise _V147Stop
        cards = list(res.get('cards') or [])
        if not cards:
            await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V147Stop
        await q.answer('Creando imagen para guardar…')
        img = await _v139_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards) if '_v139_make_result_image' in globals() else await _v137_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards)
        if not img:
            await q.answer('No pude crear la imagen.', show_alert=True); raise _V147Stop
        msg = await context.bot.send_photo(chat_id, photo=img, caption='💾 Resumen listo. Toca la imagen y guárdala en tu galería.')
        try: await register_bot_message(chat_id, msg.message_id)
        except Exception: pass

        sec = int((_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) if '_v139_tarot_cfg' in globals() else 0) or 0)
        if sec:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, int(msg.message_id)))
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error guardar resumen Tarot V147')
        try: await q.answer('Error creando imagen. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


async def _v147_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esa tirada.', show_alert=True); raise _V147Stop
    ok, reason = _v139_can_use_ai(chat_id, int(q.from_user.id)) if '_v139_can_use_ai' in globals() else (True, '')
    store = _v146_ai_store(chat_id) if '_v146_ai_store' in globals() else cfg.setdefault('tarot_ai_opinions', {})
    cached = store.get(rid)
    if isinstance(cached, dict):
        await q.answer('Opinión ya generada ✅')
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        await _v146_send_or_update_ai_message(context, chat_id, rid, cached, reply_to=None, image_id=img)
        raise _V147Stop
    if not ok:
        await q.answer(reason, show_alert=True); raise _V147Stop
    cards_ids = list(res.get('cards') or [])
    cards = []
    for cid in cards_ids:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id']==cid), None)
        if c: cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V147Stop
    user_name = str(res.get('user_name') or display_name(q.from_user))
    labels = ['Pasado','Presente','Futuro'] if len(cards)==3 else ['Carta del día']
    cards_txt = '\n'.join([f'{labels[i] if i < len(labels) else "Carta"}: {c["name"]} — {c.get("meaning", c.get("short", ""))}' for i,c in enumerate(cards)])
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        'Interpreta la tirada para la persona consultante, no para el bot ni para EL PLAN. '
        'Puedes referirte a la persona como "la persona que ha hecho la tirada" o usar su nombre si queda natural. '
        'No digas que el bot consulta. No inventes datos personales. '
        'Haz una lectura breve, misteriosa y útil, con conclusión final.\n\n'
        f'Persona consultante: {user_name}\n'
        f'Cartas:\n{cards_txt}'
    )
    await q.answer('Consultando al tarotista IA…')
    wait = await context.bot.send_message(chat_id, f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…', parse_mode=ParseMode.HTML)
    try:
        ans = await (_v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900) if '_v57_cerebrito_answer' in globals() else _ai_openai_response(chat_id, prompt, max_output_tokens=900))
        op = {'answer': ans, 'likes': [], 'flips': [], 'message_id': 0, 'ts': int(time.time()), 'result_id': rid}
        store[rid] = op; save_all_states()
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')

        try:
            if img:
                await wait.delete()
                sent_mid = await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id=img)
            else:
                op['message_id'] = int(wait.message_id)
                await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id='')
        except Exception:
            await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id=img)
        try: _v139_ai_inc(chat_id, int(q.from_user.id))
        except Exception: pass
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        mid = int(op.get('message_id') or 0)
        if sec and mid:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, mid, sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, mid))
        save_all_states()
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V147')
        try: await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
        except Exception: pass
        try: await q.answer('Error IA. Revisa logs.', show_alert=True)
        except Exception: pass
    raise _V147Stop


async def _v147_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = q.data.split('|', 2)
    if len(parts) < 3:
        return
    cmd = (_v112_clean_cmd(parts[2]) if '_v112_clean_cmd' in globals() else str(parts[2]).strip().lower().lstrip('/'))

    real_chat_id = int(q.message.chat_id) if q.message else int(update.effective_chat.id)
    if cmd in {'vitamina','horoscopo','horóscopo','tiempecito','resumenia','historia','salseo'} or (_v112_ai_command_data(real_chat_id, cmd) if '_v112_ai_command_data' in globals() else None):
        data = _v112_ai_command_data(real_chat_id, cmd) if '_v112_ai_command_data' in globals() else None
        if isinstance(data, dict):
            try:
                needs = _v112_prompt_needs_query(data) if '_v112_prompt_needs_query' in globals() else any(x in str(data.get('prompt','')) for x in ('{query}','{consulta}','{texto}'))
                if needs:
                    await q.answer('Responde al mensaje 👇')
                    ask = _v112_ask_text(q.from_user, data) if '_v112_ask_text' in globals() else f'{q.from_user.mention_html()} {h(data.get("ask") or "Escribe el dato y envía.")}'
                    set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v112', 'chat_id': real_chat_id, 'cmd': cmd})
                    msg = await context.bot.send_message(chat_id=real_chat_id, text=ask, parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=q.message.message_id if q.message else None)
                    try: _v85_schedule_delete(context, real_chat_id, msg.message_id, _v85_ask_delete_seconds(real_chat_id))
                    except Exception: pass
                else:
                    await q.answer('Ejecutando IA…')
                    await _v112_send_ai_result(context, real_chat_id, q.from_user, data, '', reply_to=None)
            except Exception:
                logger.exception('Error IA recurrente V147 /%s chat %s', cmd, real_chat_id)
                await q.answer('Error ejecutando IA. Mira logs.', show_alert=True)
            raise _V147Stop
    return


async def _v147_dj_live_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or (q.data or '') not in {'panel_live_toggle','panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    st = get_state(chat_id)
    try:
        try:
            live_result = await VOICE.toggle_live(chat_id)
            st.live_enabled = bool(live_result)
        except Exception:
            st.live_enabled = not bool(st.live_enabled)
        save_all_states()
        url = None
        try: url = await build_live_join_url(context.bot, chat_id)
        except Exception: url = None
        if st.live_enabled and st.queue and not st.now_playing:
            try:
                await simulate_panel_next(chat_id, reason='live_on_auto_play')
            except Exception:
                logger.exception('No se pudo iniciar reproducción automática al activar LIVE')
        if url:
            try:
                await q.answer('Abriendo videochat…', url=url)
            except Exception:
                await q.answer('LIVE ON. Abre el videochat desde el nombre del grupo.', show_alert=True)
        else:
            await q.answer('LIVE ON. Pulsa el nombre del grupo y abre el videochat manualmente.', show_alert=True)
        try:
            await ensure_panel(context.bot, chat_id)
        except Exception:
            pass
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error DJ live V147')
        try: await q.answer('Error al activar directo. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


def _v147_dj_like_key_from_track(track: Track) -> str:
    try:
        return _dj_track_like_key_v20(asdict(track))
    except Exception:
        return track_key(asdict(track)) if 'track_key' in globals() else str(hash(track.title))


def _v147_dj_like_count(chat_id: int, key: str) -> int:
    row = admin_cfg(chat_id).setdefault('dj_track_likes', {}).get(key, {})
    return len(row.get('users') or [])


def _v147_dj_announce_text(chat_id: int, track: Track, key: str) -> str:
    txt = "🎧 <b>EN DIRECTO AHORA</b>\n\n" + f"🎶 <b>{h(track.title)}</b>"
    if track.performer:
        txt += f"\n👤 <i>{h(track.performer)}</i>"
    txt += f"\n\n❤️ Me gusta: <b>{_v147_dj_like_count(chat_id, key)}</b>"
    return txt


def _v147_dj_announce_markup(mid: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton('❤️ Me gusta', callback_data=f'djlike_msg|{int(mid)}'), InlineKeyboardButton('🎛 Mesa', callback_data='panel_home')]])


async def _send_dj_now_announce_v24(bot, chat_id: int, track: Track) -> None:
    if not _dj_announce_enabled_v24(chat_id):
        return
    try:
        key = _v147_dj_like_key_from_track(track)
        cfg = admin_cfg(chat_id)
        likes = cfg.setdefault('dj_track_likes', {})
        row = likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
        row['title'] = track.title; row['track'] = asdict(track)
        msg = await bot.send_message(chat_id=chat_id, text=_v147_dj_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML)
        ann = cfg.setdefault('dj_announce_messages', {})
        ann[str(msg.message_id)] = {'key': key, 'track': asdict(track)}
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v147_dj_announce_markup(msg.message_id))
        save_all_states()
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        logger.exception('No se pudo mandar aviso de canción V147')


async def _v147_djlike_msg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('djlike_msg|'):
        return
    chat_id = int(update.effective_chat.id)
    try: mid = int(q.data.split('|')[1])
    except Exception: mid = int(q.message.message_id) if q.message else 0
    cfg = admin_cfg(chat_id)
    ann = cfg.setdefault('dj_announce_messages', {})
    info = ann.get(str(mid)) or {}
    track_data = info.get('track') or get_state(chat_id).now_playing
    if not track_data:
        await q.answer('No encuentro esta canción.', show_alert=True); raise _V147Stop
    track = Track(**track_data)
    key = info.get('key') or _v147_dj_like_key_from_track(track)
    likes = cfg.setdefault('dj_track_likes', {})
    row = likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
    row['title'] = track.title; row['track'] = asdict(track)
    users = [int(x) for x in row.get('users', [])]
    uid = int(q.from_user.id)
    if uid in users:
        await q.answer('Ya le habías dado ❤️')
    else:
        users.append(uid); row['users'] = users; save_all_states(); await q.answer('❤️ Sumado')
    try:
        await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v147_dj_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML, reply_markup=_v147_dj_announce_markup(mid))
    except Exception:
        pass
    raise _V147Stop


