_old_v147_save_image_target = _v143_save_image_target if '_v143_save_image_target' in globals() else None
async def _v147_save_image_target(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    pending = get_config_pending(update.effective_user.id) if update.effective_user else None
    if pending and pending.get('kind') in ('tarot_image_upload_v132','tarot_image_upload_v130') and str(pending.get('target')) == 'reading':

        if not update.message or not (update.message.photo or update.message.document):
            await update.message.reply_html('Necesito una imagen PNG/JPG como foto o documento.')
            raise _V147Stop
        chat_id = int(pending.get('chat_id') or 0)
        src = None
        if update.message.photo: src = update.message.photo[-1].file_id
        elif update.message.document: src = update.message.document.file_id
        processed = await _v136_processed_tarot_image(context, chat_id, src, role='lobby') if '_v136_processed_tarot_image' in globals() else src
        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src, caption='✅ Imagen recibida para Lectura del camino.')
            fid = preview.photo[-1].file_id if preview.photo else (processed or src)
            try:
                await asyncio.sleep(1.2); await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception: pass
        except Exception:
            fid = processed or src
        _v143_tarot_images(chat_id)['reading'] = fid
        save_all_states(); pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Guardada imagen de <b>Lectura del camino</b>.')
        raise _V147Stop
    if callable(_old_v147_save_image_target):
        return await _old_v147_save_image_target(update, context)


_old_v147_send_pair = _v129_send_pair
async def _v129_send_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], *, new_pair: bool = True) -> None:

    if new_pair:
        try:
            await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
            await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        except Exception: pass
        session['draws_msg_id'] = 0; session['choice_msg_id'] = 0
    img = str((_v143_tarot_images(chat_id).get('reading') if '_v143_tarot_images' in globals() else '') or '')
    if img:
        try:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=_v129_draws_text(session)[:1000], parse_mode=ParseMode.HTML)
            session['draws_msg_id'] = int(msg.message_id)
            try: await register_bot_message(chat_id, msg.message_id)
            except Exception: pass

            imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else _v130_tarot_images(chat_id)
            back = str(imgs.get('back') or '')
            caption = _v129_choice_text(session, user)
            if back:
                try:
                    choice_msg = await context.bot.send_photo(chat_id, photo=back, caption=caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
                except Exception:
                    choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
            else:
                choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
            session['choice_msg_id'] = int(choice_msg.message_id)
            try: await register_bot_message(chat_id, choice_msg.message_id)
            except Exception: pass
            return
        except Exception:
            logger.exception('No se pudo usar imagen lectura; fallback old')
    return await _old_v147_send_pair(context, chat_id, user, session, new_pair=new_pair)


async def _v147_tarot_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|start|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id); user = q.from_user
    mode = parts[2] if len(parts) > 2 else 'day'
    if mode not in ('ppf','day'): mode = 'day'
    try:
        try:
            locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
            if locked:
                await q.answer(reason, show_alert=True); raise _V147Stop
            _v133_mark_tarot_started(chat_id, int(user.id))
        except _V147Stop: raise
        except Exception: pass
        ok, reason = _v129_can_play(chat_id, int(user.id), mode)
        if not ok:
            await q.answer(reason, show_alert=True); raise _V147Stop
        skey = _v129_session_key(chat_id, int(user.id))
        old = TAROT_SESSIONS_V129.get(skey)
        if isinstance(old, dict):
            try: await _v137_delete_intermediate(context, chat_id, old, include_result=False)
            except Exception: pass
        session = {'chat_id': chat_id, 'user_id': int(user.id), 'mode': mode, 'stage': 0, 'draws': [], 'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)) if '_v135_mystic_shuffle_deck' in globals() else [c['id'] for c in TAROT_CARDS_V129], 'started_ts': int(time.time()), 'lobby_msg_id': int(q.message.message_id) if q.message else 0}
        TAROT_SESSIONS_V129[skey] = session
        cfg = _v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
        await q.answer('Barajando…')
        if bool(cfg.get('tarot_delete_lobby_on_start', True)) and q.message:
            await _v137_safe_delete(context.bot, chat_id, q.message.message_id)
            session['lobby_msg_id'] = 0
        imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else _v130_tarot_images(chat_id)
        shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
        stage = _v129_stage_name(session)
        caption = (
            f'🔮 <b>Las cartas se están mezclando para {h(stage)}</b>.\n\n'
            '🌙 Respira despacio. Concéntrate en lo que quieres entender.\n'
            '🃏 El taco se mueve, los arcanos se cruzan y algo empieza a colocarse.'
        )
        if shuffle_id:
            try:
                photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
                smsg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
            except Exception:
                smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        else:
            smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        session['shuffle_msg_id'] = int(smsg.message_id)
        delay = int((_v141_tarot_cfg(chat_id).get('tarot_shuffle_seconds', 10) if '_v141_tarot_cfg' in globals() else cfg.get('tarot_shuffle_seconds', 10)) or 10)
        await asyncio.sleep(max(1, delay))
        if bool(cfg.get('tarot_delete_shuffle_msg', True)):
            await _v137_safe_delete(context.bot, chat_id, session.get('shuffle_msg_id')); session['shuffle_msg_id'] = 0
        await _v129_send_pair(context, chat_id, user, session, new_pair=True)
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error start Tarot V147')
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


