async def _v148_tarot_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|start|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    mode = parts[2] if len(parts) > 2 else 'day'
    if mode not in ('ppf','day'):
        mode = 'day'
    try:
        try:
            if '_v140_user_can_tarot' in globals() and not await _v140_user_can_tarot(context, chat_id, user):
                await q.answer('No tienes permiso para ejecutar el Tarot en este grupo.', show_alert=True)
                raise _V148Stop
        except _V148Stop:
            raise
        except Exception:
            pass
        try:
            locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
            if locked:
                await q.answer(reason, show_alert=True)
                raise _V148Stop
            _v133_mark_tarot_started(chat_id, int(user.id))
        except _V148Stop:
            raise
        except Exception:
            pass
        ok, reason = _v129_can_play(chat_id, int(user.id), mode)
        if not ok:
            await q.answer(reason, show_alert=True)
            raise _V148Stop
        skey = _v129_session_key(chat_id, int(user.id))
        old = TAROT_SESSIONS_V129.get(skey)
        if isinstance(old, dict):
            try:
                await _v137_delete_intermediate(context, chat_id, old, include_result=False)
            except Exception:
                pass
        session = {
            'chat_id': chat_id,
            'user_id': int(user.id),
            'mode': mode,
            'stage': 0,
            'draws': [],
            'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)) if '_v135_mystic_shuffle_deck' in globals() else [c['id'] for c in TAROT_CARDS_V129],
            'started_ts': int(time.time()),
            'lobby_msg_id': int(q.message.message_id) if q.message else 0,
        }
        TAROT_SESSIONS_V129[skey] = session
        cfg = _v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
        await q.answer('Barajando…')
        if bool(cfg.get('tarot_delete_lobby_on_start', True)) and q.message:
            try:
                await _v137_safe_delete(context.bot, chat_id, q.message.message_id)
            except Exception:
                pass
            session['lobby_msg_id'] = 0
        imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else _v130_tarot_images(chat_id)
        shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
        stage = _v129_stage_name(session)
        caption = _v148_shuffle_caption(chat_id, stage)
        if shuffle_id:
            try:
                photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
                smsg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
            except Exception:
                logger.exception('No se pudo enviar imagen de barajeo V148; uso texto')
                smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        else:
            smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        session['shuffle_msg_id'] = int(smsg.message_id)
        try:
            await register_bot_message(chat_id, smsg.message_id)
        except Exception:
            pass
        delay = int((_v141_tarot_cfg(chat_id).get('tarot_shuffle_seconds', 10) if '_v141_tarot_cfg' in globals() else cfg.get('tarot_shuffle_seconds', 10)) or 10)
        await asyncio.sleep(max(1, delay))
        if bool(cfg.get('tarot_delete_shuffle_msg', True)):
            try:
                await _v137_safe_delete(context.bot, chat_id, session.get('shuffle_msg_id'))
            except Exception:
                pass
            session['shuffle_msg_id'] = 0
        await _v129_send_pair(context, chat_id, user, session, new_pair=True)
        raise _V148Stop
    except _V148Stop:
        raise
    except Exception:
        logger.exception('Error start Tarot V148')
        try:
            await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V148Stop


def _v148_clone_jsonable(obj: Any) -> Any:
    try:
        return json.loads(json.dumps(obj, ensure_ascii=False))
    except Exception:

        if isinstance(obj, dict):
            return {str(k): _v148_clone_jsonable(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_v148_clone_jsonable(x) for x in obj]
        if isinstance(obj, tuple):
            return [_v148_clone_jsonable(x) for x in obj]
        return obj


def _v148_exportable_state(src: int, dst: int) -> Dict[str, Any]:
    src_state = get_state(int(src))
    return {
        'admin_config': _v148_clone_jsonable(src_state.admin_config),
        'saved_lists': _v148_clone_jsonable(src_state.saved_lists),
        'library': _v148_clone_jsonable(src_state.library),
        'member_activity': _v148_clone_jsonable(src_state.member_activity),
    }


def _v148_apply_export(src: int, dst: int) -> None:
    src = int(src); dst = int(dst)
    src_state = get_state(src)
    dst_state = get_state(dst)
    exported = _v148_exportable_state(src, dst)

    old_title = str(dst_state.admin_config.get('chat_title') or cfg_value(dst, 'chat_title', '') or dst)
    old_validation_users = _v148_clone_jsonable(dst_state.validation_users)
    old_entry_log = _v148_clone_jsonable(dst_state.entry_log)
    old_action_log = _v148_clone_jsonable(dst_state.action_log)

    dst_state.admin_config = exported['admin_config'] if isinstance(exported.get('admin_config'), dict) else {}

    dst_state.admin_config['chat_title'] = old_title
    for k in [
        'dj_session_mode', 'dj_mesa_visible', 'dj_mesa_minimized',
        'tarot_active_until_ts', 'tarot_active_user_id',
        'daily_phrase_last_sent_ts',
    ]:
        if k in dst_state.admin_config:
            if k in ('dj_session_mode',):
                dst_state.admin_config[k] = 'off'
            elif k in ('dj_mesa_visible','dj_mesa_minimized'):
                dst_state.admin_config[k] = False
            else:
                dst_state.admin_config[k] = 0

    dst_state.saved_lists = exported.get('saved_lists') if isinstance(exported.get('saved_lists'), dict) else {}
    dst_state.library = exported.get('library') if isinstance(exported.get('library'), list) else []
    dst_state.member_activity = exported.get('member_activity') if isinstance(exported.get('member_activity'), dict) else {}
    dst_state.queue = []
    dst_state.now_playing = None
    dst_state.dj_mode = False
    dst_state.assigned_dj_id = None
    dst_state.assigned_dj_name = ''
    dst_state.panel_message_id = None
    dst_state.control_message_id = None
    dst_state.temp_message_ids = []
    dst_state.bot_message_ids = []

    dst_state.validation_users = old_validation_users if isinstance(old_validation_users, dict) else dst_state.validation_users
    dst_state.entry_log = old_entry_log if isinstance(old_entry_log, list) else dst_state.entry_log
    dst_state.action_log = old_action_log if isinstance(old_action_log, list) else dst_state.action_log
    try:
        add_action_log(dst, 'export_config', f'Configuración importada desde {src}')
    except Exception:
        pass
    save_all_states()


