def _v148_export_dest_markup(src: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for dst in known_admin_chats_for_private():
        if int(dst) == int(src):
            continue
        title = str(cfg_value(dst, 'chat_title', '') or dst)
        rows.append([InlineKeyboardButton(f'➡️ {truncated_button_title(title, 38)}', callback_data=f'cfgx|ask|{src}|{dst}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay otros grupos detectados', callback_data=f'cfgx|noop|{src}')])
    rows.append([InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|open|{src}')])
    return InlineKeyboardMarkup(rows)


def _v148_export_confirm_text(src: int, dst: int) -> str:
    return (
        '<b>⚠️ Confirmar exportación</b>\n\n'
        f'Origen: <b>{h(str(cfg_value(src, "chat_title", "") or src))}</b>\n'
        f'Destino: <b>{h(str(cfg_value(dst, "chat_title", "") or dst))}</b>\n\n'
        'Esto sobrescribirá la configuración del destino con la del origen.\n'
        'Las imágenes funcionarán porque se copian los file_id del mismo bot.'
    )


def _v148_export_confirm_markup(src: int, dst: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('✅ Sí, exportar todo', callback_data=f'cfgx|do|{src}|{dst}')],
        [InlineKeyboardButton('🔙 Elegir otro destino', callback_data=f'cfgx|export|{src}')],
    ])


_old_v148_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_v148_admin_private_main_markup(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]

    insert_at = max(0, len(rows)-2)
    rows.insert(insert_at, [InlineKeyboardButton('📤 Exportar configuración a otro grupo', callback_data=f'cfgx|export|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v148_export_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfgx|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'noop':
            await q.answer('No hay otro grupo disponible.', show_alert=True)
            raise _V148Stop
        if action == 'export':
            src = int(parts[2])
            await q.answer()
            await q.edit_message_text(_v148_export_text(src), parse_mode=ParseMode.HTML, reply_markup=_v148_export_dest_markup(src))
            raise _V148Stop
        if action == 'ask':
            src = int(parts[2]); dst = int(parts[3])
            await q.answer()
            await q.edit_message_text(_v148_export_confirm_text(src, dst), parse_mode=ParseMode.HTML, reply_markup=_v148_export_confirm_markup(src, dst))
            raise _V148Stop
        if action == 'do':
            src = int(parts[2]); dst = int(parts[3])
            _v148_apply_export(src, dst)
            await q.answer('Configuración exportada ✅', show_alert=True)
            text = (
                '<b>✅ Exportación completada</b>\n\n'
                f'Origen: <b>{h(str(cfg_value(src, "chat_title", "") or src))}</b>\n'
                f'Destino: <b>{h(str(cfg_value(dst, "chat_title", "") or dst))}</b>\n\n'
                'Ya puedes abrir el bot en ese grupo y usar la configuración copiada.'
            )
            await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('⚙️ Abrir destino', callback_data=f'cfg|open|{dst}')], [InlineKeyboardButton('🔙 Origen', callback_data=f'cfg|open|{src}')]]))
            raise _V148Stop
    except _V148Stop:
        raise
    except Exception:
        logger.exception('Error exportando configuración V148: %s', q.data)
        try:
            await q.answer('Error exportando. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V148Stop


