_old_v149_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_v149_admin_private_main_markup(chat_id)
    rows = []
    for r in getattr(markup, 'inline_keyboard', []) or []:

        clean = [b for b in r if not ((getattr(b, 'callback_data', '') or '').startswith('cfgx|export|'))]
        if clean:
            rows.append(clean)
    insert_at = max(0, len(rows)-2)
    rows.insert(insert_at, [InlineKeyboardButton('📤 Exportar por módulo', callback_data=f'cfgx|menu|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v149_export_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfgx|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action in {'export', 'menu'}:
            src = int(parts[2])
            await q.answer('', show_alert=False)
            await q.edit_message_text(_v149_export_menu_text(src), parse_mode=ParseMode.HTML, reply_markup=_v149_export_module_markup(src))
            raise _V149Stop
        if action == 'noop':
            await q.answer('No hay otro grupo disponible.', show_alert=False)
            raise _V149Stop
        if action == 'mod':
            src = int(parts[2]); module = parts[3]
            await q.answer('', show_alert=False)
            await q.edit_message_text(
                f'<b>📤 Exportar {h(_V149_MODULES.get(module, module))}</b>\n\nElige grupo destino:',
                parse_mode=ParseMode.HTML,
                reply_markup=_v149_export_dest_markup(src, module)
            )
            raise _V149Stop
        if action == 'askm':
            src = int(parts[2]); dst = int(parts[3]); module = parts[4]
            await q.answer('', show_alert=False)
            await q.edit_message_text(_v149_confirm_text(src, dst, module), parse_mode=ParseMode.HTML, reply_markup=_v149_confirm_markup(src, dst, module))
            raise _V149Stop
        if action == 'dom':
            src = int(parts[2]); dst = int(parts[3]); module = parts[4]
            _v149_export_module(src, dst, module)
            await q.answer('Módulo exportado ✅', show_alert=False)
            text = (
                '<b>✅ Exportación completada</b>\n\n'
                f'Módulo: <b>{h(_V149_MODULES.get(module, module))}</b>\n'
                f'Origen: <b>{h(str(cfg_value(src, "chat_title", "") or src))}</b>\n'
                f'Destino: <b>{h(str(cfg_value(dst, "chat_title", "") or dst))}</b>\n\n'
                'No se copiaron resultados, mensajes abiertos ni sesiones activas.'
            )
            await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('⚙️ Abrir destino', callback_data=f'cfg|open|{dst}')], [InlineKeyboardButton('📤 Exportar otro módulo', callback_data=f'cfgx|menu|{src}')]]))
            raise _V149Stop

        if action in {'ask', 'do'}:
            src = int(parts[2])
            await q.answer('Ahora la exportación es por módulo.', show_alert=False)
            await q.edit_message_text(_v149_export_menu_text(src), parse_mode=ParseMode.HTML, reply_markup=_v149_export_module_markup(src))
            raise _V149Stop
    except _V149Stop:
        raise
    except Exception:
        logger.exception('Error exportación por módulo V149: %s', q.data)
        try:
            await q.answer('Error exportando. Revisa logs.', show_alert=False)
        except Exception:
            pass
        raise _V149Stop


