def _v150_clean_jm_from_phrase(text: str) -> str:
    s = str(text or '').strip()

    s = re.sub(r'(?i)\s*[-–—]?\s*j\s*\.?\s*m\s*\.?\s*$', '', s).strip()
    return s


def _v150_has_jm(text: str) -> bool:
    try:
        return _v127_is_jm_phrase(text) if '_v127_is_jm_phrase' in globals() else bool(re.search(r'(?i)j\s*\.?\s*m\s*\.?', str(text or '')))
    except Exception:
        return bool(re.search(r'(?i)j\s*\.?\s*m\s*\.?', str(text or '')))


_old_v150_daily_phrase_for_chat = daily_phrase_for_chat_v30

def daily_phrase_for_chat_v30(chat_id: int, now_ts: Optional[int] = None) -> str:
    manual = str(cfg_value(chat_id, 'daily_phrase_manual_current', '') or '').strip()
    if manual:
        return manual
    return _old_v150_daily_phrase_for_chat(chat_id, now_ts)


def _v150_phrase_html(phrase: str) -> str:
    raw = str(phrase or '').strip()
    is_jm = _v150_has_jm(raw)
    clean = _v150_clean_jm_from_phrase(raw) if is_jm else raw
    quote = f'“{h(clean)}”'
    suffix = '\n♾️<b>J.M.</b>✨' if is_jm else ''
    return f'<b><i>{quote}</i></b>{suffix}'


def _v114_phrase_caption(chat_id: int, phrase: str) -> str:
    title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')
    tone = _v113_tone_label(str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random')) if '_v113_tone_label' in globals() else ''
    show_tone = bool(cfg_value(chat_id, 'daily_phrase_show_tone', False))
    extra = f"\n<code>{h(tone)}</code>" if show_tone and tone else ''
    likes = _v114_phrase_likes_count(chat_id, phrase) if '_v114_phrase_likes_count' in globals() else 0
    text = f"<b>{h(title)}</b>{extra}\n\n{_v150_phrase_html(phrase)}\n\n❤️ Me gusta: <b>{likes}</b>"
    return text[:1000]


def _v114_phrase_markup(chat_id: int, message_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('💪 Vitamina', callback_data=f'dphrase|vitamina|{int(chat_id)}|{int(message_id)}'), InlineKeyboardButton('❤️ Me gusta', callback_data=f'dphrase|like|{int(chat_id)}|{int(message_id)}')]
    ])


async def _v150_daily_phrase_button_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('dphrase|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2]); msg_id = int(parts[3])
    except Exception:
        try: await q.answer('Botón inválido.', show_alert=False)
        except Exception: pass
        raise _V150Stop

    if action == 'vitamina':
        try:
            await q.answer('Te pregunto cómo te sientes 👇', show_alert=False)
        except Exception:
            pass
        ask_text = '¿Cómo te sientes? Escríbelo y envía.'
        if '_v126_ask_for_query' in globals():
            await _v126_ask_for_query(context, chat_id, q.from_user, 'vitamina', ask_text, reply_to=msg_id)
        else:
            set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v126', 'chat_id': int(chat_id), 'cmd': 'vitamina'})
            await context.bot.send_message(chat_id=chat_id, text=f'{q.from_user.mention_html()} {h(ask_text)}', parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=msg_id)
        raise _V150Stop

    if action == 'like':
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else {}
        entry = store.get(str(msg_id)) if isinstance(store, dict) else None
        if not isinstance(entry, dict):
            try: await q.answer('Esta frase ya no está activa.', show_alert=False)
            except Exception: pass
            raise _V150Stop
        phrase = str(entry.get('phrase') or daily_phrase_for_chat_v30(chat_id))
        uid = str(int(q.from_user.id))
        key = _v114_phrase_key(phrase)
        likes = _v114_phrase_likes_store(chat_id)
        row = likes.setdefault(key, {'text': phrase, 'users': []})
        users = row.setdefault('users', [])
        if uid not in users:
            users.append(uid); row['text'] = phrase
            save_all_states()
            await _v114_update_daily_phrase_message(context.bot, chat_id, msg_id)
            try: await q.answer('❤️ Me gusta añadido', show_alert=False)
            except Exception: pass
        else:
            try: await q.answer('Ya habías dado me gusta ❤️', show_alert=False)
            except Exception: pass
        raise _V150Stop


    if action == 'next':
        try: await q.answer('Ahora usa 💪 Vitamina. Otra frase se gestiona desde ajustes.', show_alert=False)
        except Exception: pass
        raise _V150Stop


_old_v150_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    txt = _old_v150_block_text(chat_id, block, page)
    if block == 'daily_phrase':
        try:
            current = daily_phrase_for_chat_v30(chat_id)
            locked = bool(str(cfg_value(chat_id, 'daily_phrase_manual_current', '') or '').strip())
            txt += (
                '\n\n<b>Selección manual</b>\n'
                f"Estado: <b>{'fijada manualmente' if locked else 'rotación automática'}</b>\n"
                f"Vista actual:\n{_v150_phrase_html(current)}"
            )
        except Exception:
            pass
    return txt


_old_v150_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v150_block_markup(chat_id, block, page)
    if block != 'daily_phrase':
        return markup
    rows = []

    for row in getattr(markup, 'inline_keyboard', []) or []:
        clean = []
        for btn in row:
            txt = getattr(btn, 'text', '') or ''
            cd = getattr(btn, 'callback_data', '') or ''
            if 'Siguiente frase' in txt or cd.startswith('cfg|phrase_next|'):
                continue
            clean.append(btn)
        if clean:
            rows.append(clean)
    insert_at = 1 if len(rows) > 1 else 0
    manual_rows = [
        [InlineKeyboardButton('⏭ Pasar a otra frase', callback_data=f'cfg|phrase_pass|{chat_id}|daily_phrase'), InlineKeyboardButton('✅ Quedarme esta', callback_data=f'cfg|phrase_keep|{chat_id}|daily_phrase')],
        [InlineKeyboardButton('🔁 Rotación automática', callback_data=f'cfg|phrase_auto|{chat_id}|daily_phrase')],
    ]
    rows = rows[:insert_at] + manual_rows + rows[insert_at:]
    return InlineKeyboardMarkup(rows)


_old_v150_admin_config_cb = admin_private_config_callback

async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|phrase_'):
        parts = data.split('|')
        action = parts[1] if len(parts) > 1 else ''
        if action in {'phrase_pass', 'phrase_keep', 'phrase_auto'}:
            try:
                chat_id = int(parts[2])
                if action == 'phrase_pass':

                    cfg_set(chat_id, 'daily_phrase_manual_current', '')
                    cfg_set(chat_id, 'daily_phrase_offset', int(cfg_value(chat_id, 'daily_phrase_offset', 0) or 0) + 1)
                    new_phrase = _old_v150_daily_phrase_for_chat(chat_id, int(time.time()))
                    cfg_set(chat_id, 'daily_phrase_manual_current', new_phrase)
                    save_all_states()
                    await q.answer('Frase cambiada y fijada ✅', show_alert=False)
                elif action == 'phrase_keep':
                    current = daily_phrase_for_chat_v30(chat_id)
                    cfg_set(chat_id, 'daily_phrase_manual_current', current)
                    save_all_states()
                    await q.answer('Te quedas con esta frase ✅', show_alert=False)
                elif action == 'phrase_auto':
                    cfg_set(chat_id, 'daily_phrase_manual_current', '')
                    save_all_states()
                    await q.answer('Rotación automática activada 🔁', show_alert=False)
                await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
                raise _V150Stop
            except _V150Stop:
                raise
            except Exception:
                logger.exception('Error selección manual frase V150: %s', data)
                try: await q.answer('Error frase día. Mira logs.', show_alert=False)
                except Exception: pass
                raise _V150Stop
    return await _old_v150_admin_config_cb(update, context)


