async def _v153_djlike_msg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('djlike_msg|'):
        return
    chat_id = int(update.effective_chat.id)
    try:
        mid = int(q.data.split('|')[1])
    except Exception:
        mid = int(q.message.message_id) if q.message else 0
    cfg = admin_cfg(chat_id)
    ann = cfg.setdefault('dj_announce_messages', {})
    info = ann.get(str(mid)) or {}
    track_data = info.get('track') or get_state(chat_id).now_playing
    if not track_data:
        try:
            await q.answer('No encuentro esta canción.', show_alert=False)
        except Exception:
            pass
        raise _V153Stop
    track = Track(**track_data)
    key = info.get('key') or _v147_dj_like_key_from_track(track)
    likes = cfg.setdefault('dj_track_likes', {})
    row = likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
    row['title'] = track.title
    row['track'] = asdict(track)
    users = [int(x) for x in row.get('users', [])]
    uid = int(q.from_user.id)
    if uid in users:
        try:
            await q.answer('Ya le habías dado ❤️', show_alert=False)
        except Exception:
            pass
    else:
        users.append(uid)
        row['users'] = users
        save_all_states()
        try:
            await q.answer('❤️ Sumado', show_alert=False)
        except Exception:
            pass


    try:
        await context.bot.edit_message_text(
            chat_id=chat_id,
            message_id=mid,
            text=_v147_dj_announce_text(chat_id, track, key),
            parse_mode=ParseMode.HTML,
            reply_markup=_v147_dj_announce_markup(mid),
        )
    except BadRequest as e:
        if 'message is not modified' not in str(e).lower():
            logger.warning('No se pudo editar like canción V153: %s', e)
    except Exception:
        logger.exception('No se pudo actualizar like canción V153')
    raise _V153Stop


