def _v154_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Botonera del mensaje fijado superior.

    Importante: este mensaje es el único fijado del DJ y NO es la mesa. La mesa
    aparece debajo cuando se pulsa Mostrar mesa.
    """
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎛 Mostrar mesa DJ', callback_data='menu_panel')],
        [InlineKeyboardButton('❌ Cerrar sesión DJ', callback_data='panel_close')],
    ])


async def ensure_panel(bot, chat_id: int) -> None:
    """Crea/edita SIEMPRE el panel fijado superior del DJ.

    Respeta panel_text() actual, por tanto conserva emojis premium ON/OFF, canción
    en negrita/cursiva y texto personalizado si está configurado.
    """
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v154_panel_markup(chat_id)
        old_id = int(state.panel_message_id or 0)
        if old_id:
            try:
                await bot.edit_message_text(
                    chat_id=chat_id,
                    message_id=old_id,
                    text=text,
                    parse_mode=ParseMode.HTML,
                    reply_markup=markup,
                )

                try:
                    await bot.pin_chat_message(chat_id=chat_id, message_id=old_id, disable_notification=True)
                except Exception:
                    pass
                save_all_states()
                return
            except BadRequest as e:
                low = str(e).lower()
                if 'message is not modified' in low:
                    try:
                        await bot.pin_chat_message(chat_id=chat_id, message_id=old_id, disable_notification=True)
                    except Exception:
                        pass
                    return
                if 'message to edit not found' in low or 'message identifier is not specified' in low:
                    state.panel_message_id = None
                    save_all_states()
                else:
                    logger.warning('V154 no pudo editar panel fijado %s chat %s: %s', old_id, chat_id, e)
                    return
            except Exception:
                logger.exception('V154 fallo editando panel fijado DJ; no duplico salvo que no exista')
                return

        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        state.panel_message_id = int(msg.message_id)
        save_all_states()
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            logger.exception('V154 no pudo fijar panel DJ')

        try:
            await enforce_single_core_messages(bot, chat_id)
        except Exception:
            pass


async def _v154_show_mesa(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> None:
    state = get_state(chat_id)
    cfg = admin_cfg(chat_id)
    cfg['dj_session_mode'] = 'pro'
    cfg['dj_mesa_visible'] = True
    cfg['dj_mesa_minimized'] = False
    try:
        _v122_set_mode(chat_id, 'pro')
    except Exception:
        pass
    state.dj_mode = True
    state.assigned_dj_id = int(user.id)
    state.assigned_dj_name = display_name(user)
    set_control_view(state, 'home', 0)
    save_all_states()
    await ensure_panel(context.bot, chat_id)

    try:
        await ensure_control_panel(context.bot, chat_id)
    except Exception:
        logger.exception('V154 no pudo mostrar mesa con ensure_control_panel; intento fallback')
        try:
            text, markup = current_control_view(state)
            msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            state.control_message_id = int(msg.message_id)
            save_all_states()
        except Exception:
            logger.exception('V154 fallback mesa falló')


async def _v154_minimize_mesa(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    state = get_state(chat_id)
    cfg = admin_cfg(chat_id)
    cfg['dj_mesa_visible'] = False
    cfg['dj_mesa_minimized'] = True
    try:
        _v122_set_mode(chat_id, 'pro')
    except Exception:
        pass
    old = int(state.control_message_id or 0)
    state.control_message_id = None
    save_all_states()
    if old and old != int(state.panel_message_id or 0):
        try:
            await safe_delete(context.bot, chat_id, old)
        except Exception:
            pass
    await ensure_panel(context.bot, chat_id)


async def _v154_dj_core_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'menu_panel', 'panel_minimize'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    try:
        if data == 'menu_panel':
            try:
                allowed = await _v106_user_can(context, chat_id, user, 'pro')
            except Exception:
                allowed = True
            if not allowed:
                await q.answer('No estás autorizado para abrir la mesa DJ.', show_alert=False)
                raise _V154Stop
            await q.answer('Mostrando mesa DJ…', show_alert=False)
            await _v154_show_mesa(context, chat_id, user)
            raise _V154Stop
        if data == 'panel_minimize':
            try:
                allowed = await _v106_user_can(context, chat_id, user, 'pro')
            except Exception:
                allowed = True
            if not allowed:
                await q.answer('No estás autorizado para minimizar la mesa.', show_alert=False)
                raise _V154Stop
            await q.answer('Mesa minimizada. Usa el mensaje fijado para mostrarla.', show_alert=False)
            await _v154_minimize_mesa(context, chat_id)
            raise _V154Stop
    except _V154Stop:
        raise
    except Exception:
        logger.exception('V154 error router DJ core: %s', data)
        try:
            await q.answer('Error DJ. Revisa logs.', show_alert=False)
        except Exception:
            pass
        raise _V154Stop


