def _v133_size_dims(chat_id: int) -> tuple[int, int]:
    cfg = _v133_tarot_cfg(chat_id) if '_v133_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    size = str(cfg.get('tarot_image_size', 'large') or 'large')

    if size == 'compact':
        return (900, 700)
    if size == 'small':
        return (620, 900)
    if size == 'medium':
        return (780, 1120)

    return (980, 1400)


def _v155_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)

    if str(cfg.get('tarot_image_size', '') or '') in ('', 'compact'):
        cfg['tarot_image_size'] = 'large'
    cfg.setdefault('tarot_block_all_while_active', True)
    return cfg


def _v155_active_session(chat_id: int) -> Optional[Dict[str, Any]]:
    now = int(time.time())

    cfg = _v155_tarot_cfg(chat_id)
    active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
    active_user = int(cfg.get('tarot_active_user_id', 0) or 0)
    if active_until > now and active_user:
        return {'chat_id': int(chat_id), 'user_id': active_user, 'active_until_ts': active_until, 'source': 'lock'}

    for s in list(TAROT_SESSIONS_V129.values()):
        try:
            if int(s.get('chat_id') or 0) != int(chat_id):
                continue
            if s.get('final_msg_id'):
                continue
            if now - int(s.get('started_ts', now) or now) > 3600:
                continue
            return s
        except Exception:
            continue
    return None


def _v155_tarot_owner_id(chat_id: int) -> int:
    s = _v155_active_session(chat_id)
    try:
        return int(s.get('user_id') or 0) if s else 0
    except Exception:
        return 0


async def _v155_tarot_button_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|'):
        return
    chat_id = int(update.effective_chat.id)
    uid = int(q.from_user.id)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''


    if action in {'rr', 'air'}:
        return

    active = _v155_active_session(chat_id)
    owner = int((active or {}).get('user_id') or 0)


    if action == 'start':
        if active and owner and owner != uid and bool(_v155_tarot_cfg(chat_id).get('tarot_block_all_while_active', True)):
            await q.answer('🔮 Hay un Tarot en curso. Mientras una tirada esté abierta no se puede iniciar otra.', show_alert=True)
            raise _V155Stop
        return


    game_actions = {'pick', 'next', 'final', 'ai', 'save', 'showdraw'}
    if action in game_actions and owner and owner != uid:
        await q.answer('🔮 Esta tirada no es tuya. Solo quien está jugando puede tocar este botón.', show_alert=True)
        raise _V155Stop


_old_v155_tarot_command = tarot_command if 'tarot_command' in globals() else None
async def tarot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_html('🔮 Usa <code>/tarot</code> dentro del grupo para abrir el Tarot del Plan.')
        raise _V155Stop
    chat_id = int(update.effective_chat.id)
    active = _v155_active_session(chat_id)
    if active and int(active.get('user_id') or 0) != int(update.effective_user.id):
        await update.message.reply_text('🔮 Hay un Tarot en curso. Mientras una tirada esté abierta no se puede abrir otra.')
        raise _V155Stop
    if callable(_old_v155_tarot_command):
        await _old_v155_tarot_command(update, context)
    raise _V155Stop


async def _v155_send_all_tarot_cards(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    await context.bot.send_message(chat_id, '🃏 <b>Arcanos del Tarot</b>\nPulsa cada imagen para verla más grande.', parse_mode=ParseMode.HTML)
    for c in TAROT_CARDS_V129:
        try:
            photo = _v130_card_photo(chat_id, c, '') if '_v130_card_photo' in globals() else None
            caption = f"<b>{_v130_card_number(c.get('id','')) if '_v130_card_number' in globals() else c.get('id','')} · {h(c.get('name',''))}</b> {c.get('emoji','')}\n{h(c.get('short') or c.get('meaning') or '')}"
            if photo:
                await context.bot.send_photo(chat_id, photo=photo, caption=caption[:1000], parse_mode=ParseMode.HTML)
            else:
                await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
            await asyncio.sleep(0.05)
        except Exception:
            logger.exception('No pude enviar carta Tarot V155')


