def _v156_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v155_tarot_cfg(chat_id) if '_v155_tarot_cfg' in globals() else (_v147_tarot_cfg(chat_id) if '_v147_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id))
    cfg.setdefault('tarot_intro_day_image', '')
    cfg.setdefault('tarot_intro_ppf_image', '')
    cfg.setdefault('tarot_showdraw_seconds', 20)
    cfg.setdefault('tarot_pin_text', '🔮 CARTAS DEL TAROT')
    cfg.setdefault('tarot_pin_button', 'QUIERO')
    cfg.setdefault('tarot_pin_message_id', 0)
    return cfg


def _v156_chat_active_tarot(chat_id: int) -> Optional[Dict[str, Any]]:
    try:
        now = int(time.time())
        cfg = _v156_tarot_cfg(chat_id)
        active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
        active_uid = int(cfg.get('tarot_active_user_id', 0) or 0)
        for s in list(TAROT_SESSIONS_V129.values()):
            if int(s.get('chat_id', 0) or 0) == int(chat_id) and int(s.get('user_id', 0) or 0):

                if s.get('finished'):
                    continue
                return s
        if active_until > now and active_uid:
            return {'chat_id': chat_id, 'user_id': active_uid, 'virtual': True, 'remain': active_until-now}
    except Exception:
        pass
    return None


def _v156_block_reason(chat_id: int, user_id: int) -> str:
    active = _v156_chat_active_tarot(chat_id)
    if active and int(active.get('user_id') or 0) != int(user_id):
        remain = int(active.get('remain') or max(0, int(_v156_tarot_cfg(chat_id).get('tarot_active_until_ts',0) or 0)-int(time.time())))
        return f'🔮 Ya hay un Tarot en curso. Espera {remain}s para abrir otro.' if remain else '🔮 Ya hay un Tarot en curso. Espera a que termine.'
    try:
        locked, reason = _v133_is_chat_locked(chat_id, user_id)
        if locked:
            return reason
    except Exception:
        pass
    return ''


