async def _v156_delete_ids(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any], keys: list[str]) -> None:
    for k in keys:
        try:
            await _v137_safe_delete(context.bot, chat_id, session.get(k)) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, session.get(k))
        except Exception:
            pass
        session[k] = 0


async def _v156_send_mode_intro(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    mode = str(session.get('mode') or 'day')
    text = _v156_intro_text(mode)
    img = _v156_intro_image(chat_id, mode)
    markup = InlineKeyboardMarkup([[InlineKeyboardButton('🔮 BARAJEAR CARTAS', callback_data='tar|shuffle')]])
    if img:
        try:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except Exception:
            logger.exception('No se pudo enviar intro Tarot con imagen')
            msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
    else:
        msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
    session['intro_msg_id'] = int(msg.message_id)
    try: await register_bot_message(chat_id, msg.message_id)
    except Exception: pass
    save_all_states()


async def _v156_shuffle_then_choice(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    await _v156_delete_ids(context, chat_id, session, ['intro_msg_id','draws_msg_id','choice_msg_id','shuffle_msg_id'])

    caption = _v156_shuffle_caption(session)
    imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else (_v136_tarot_images(chat_id) if '_v136_tarot_images' in globals() else _v130_tarot_images(chat_id))
    shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
    msg = None
    if shuffle_id:
        try:
            photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
            msg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
        except Exception:
            logger.exception('No se pudo enviar barajeo V156')
    if msg is None:
        msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
    session['shuffle_msg_id'] = int(msg.message_id)
    try: await register_bot_message(chat_id, msg.message_id)
    except Exception: pass
    await asyncio.sleep(_v141_shuffle_seconds(chat_id) if '_v141_shuffle_seconds' in globals() else 10)
    if bool(_v156_tarot_cfg(chat_id).get('tarot_delete_shuffle_msg', True)):
        await _v156_delete_ids(context, chat_id, session, ['shuffle_msg_id'])
    await _v129_send_pair(context, chat_id, user, session, new_pair=True)
    save_all_states()


def _v156_next_label(session: Dict[str, Any]) -> str:
    stage = int(session.get('stage', 0) or 0)
    if stage == 0:
        return '🔥 IR A PRESENTE'
    if stage == 1:
        return '✨ IR A FUTURO'
    return '📖 VER EXPLICACIÓN DE LAS CARTAS'


async def _v129_show_card_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], card: Dict[str, str]) -> None:
    stage = _v129_stage_name(session)
    text = _v138_card_full_text(card, stage) if '_v138_card_full_text' in globals() else str(card.get('meaning') or card.get('short') or '')
    caption = f"🔮 <b>{h(stage)}</b>\n{card.get('emoji','')} <b>{h(card['name'])}</b>\n\n{h(text)}"
    photo = await _v138_card_photo(context, chat_id, card, stage) if '_v138_card_photo' in globals() else (_v130_card_photo(chat_id, card, stage) if '_v130_card_photo' in globals() else None)
    if session.get('mode') == 'ppf' and int(session.get('stage', 0) or 0) < 2:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton(_v156_next_label(session), callback_data='tar|next')]])
    else:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('📖 VER EXPLICACIÓN DE LAS CARTAS', callback_data='tar|final')]])
    try:
        if photo:
            await context.bot.edit_message_media(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), media=__import__('telegram').InputMediaPhoto(media=photo, caption=caption[:1000], parse_mode=ParseMode.HTML), reply_markup=markup)
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await _v137_safe_delete(context.bot, chat_id, session.get('choice_msg_id')) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=caption[:1000], parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        session['choice_msg_id'] = int(msg.message_id)


