async def _v156_showdraw_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|showdraw|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esta tirada.', show_alert=True); raise _V156Stop
    await q.answer('Mostrando tus cartas…')
    sec = int(_v156_tarot_cfg(chat_id).get('tarot_showdraw_seconds', 20) or 20)
    mids = []
    for cid in list(res.get('cards') or []):
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id']==cid), None)
        if not c: continue
        photo = await _v138_card_photo(context, chat_id, c, '') if '_v138_card_photo' in globals() else (_v130_card_photo(chat_id, c, '') if '_v130_card_photo' in globals() else None)
        cap = f"<b>{_v130_card_number(c.get('id','')) if '_v130_card_number' in globals() else c.get('id','')} · {h(c.get('name',''))}</b> {c.get('emoji','')}"
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=cap, parse_mode=ParseMode.HTML)
        else:
            msg = await context.bot.send_message(chat_id, cap, parse_mode=ParseMode.HTML)
        mids.append(msg.message_id)
    async def _del():
        await asyncio.sleep(max(1, sec))
        for mid in mids:
            await _v137_safe_delete(context.bot, chat_id, mid) if '_v137_safe_delete' in globals() else await _v129_delete_msg(context.bot, chat_id, mid)
    if sec > 0: asyncio.create_task(_del())
    raise _V156Stop


async def _v156_tarot_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user or not (q.data or '').startswith('tar|'):
        return
    data = q.data or ''
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    uid = int(user.id)

    if action in {'rr','air'}:
        return
    if action == 'close':
        await q.answer('Cerrado')
        try: await q.message.delete()
        except Exception: pass
        raise _V156Stop
    if action == 'open':
        reason = _v156_block_reason(chat_id, uid)
        if reason:
            await q.answer(reason, show_alert=True); raise _V156Stop
        if not _v129_can_play(chat_id, uid, 'day')[0] and not _v129_can_play(chat_id, uid, 'ppf')[0]:
            await q.answer('🔮 Has consumido tus tiradas disponibles hoy.', show_alert=True); raise _V156Stop
        await q.answer()
        await _v130_send_lobby(context.bot, chat_id, user)
        raise _V156Stop
    if action == 'start':
        mode = parts[2] if len(parts)>2 else 'day'
        mode = mode if mode in ('day','ppf') else 'day'
        reason = _v156_block_reason(chat_id, uid)
        if reason:
            await q.answer(reason, show_alert=True); raise _V156Stop
        if '_v140_user_can_tarot' in globals() and not await _v140_user_can_tarot(context, chat_id, user):
            await q.answer('🔮 No tienes permiso para usar el Tarot.', show_alert=True); raise _V156Stop
        ok, why = _v129_can_play(chat_id, uid, mode)
        if not ok:
            await q.answer(why, show_alert=True); raise _V156Stop

        try: await q.message.delete()
        except Exception: pass
        if '_v133_mark_tarot_started' in globals(): _v133_mark_tarot_started(chat_id, uid)
        skey = _v129_session_key(chat_id, uid)
        old = TAROT_SESSIONS_V129.get(skey)
        if isinstance(old, dict): await _v156_delete_ids(context, chat_id, old, ['intro_msg_id','draws_msg_id','choice_msg_id','shuffle_msg_id'])
        session = {'chat_id': chat_id, 'user_id': uid, 'mode': mode, 'stage': 0, 'draws': [], 'deck': _v135_mystic_shuffle_deck(chat_id, uid) if '_v135_mystic_shuffle_deck' in globals() else [c['id'] for c in TAROT_CARDS_V129], 'started_ts': int(time.time())}
        TAROT_SESSIONS_V129[skey] = session
        await q.answer()
        await _v156_send_mode_intro(context, chat_id, user, session)
        raise _V156Stop

    if action in {'shuffle','pick','next','final','ai','save'}:

        active = _v156_chat_active_tarot(chat_id)
        skey = _v129_session_key(chat_id, uid)
        session = TAROT_SESSIONS_V129.get(skey)
        if action in {'shuffle','pick','next','final'}:
            if not session:
                await q.answer('🔮 Esta tirada no es tuya o ya terminó.', show_alert=True); raise _V156Stop
        elif active and int(active.get('user_id') or 0) != uid:
            await q.answer('🔮 Solo quien está jugando puede tocar este botón.', show_alert=True); raise _V156Stop
    if action == 'shuffle':
        skey = _v129_session_key(chat_id, uid); session = TAROT_SESSIONS_V129.get(skey)
        await q.answer('Barajando…')
        await _v156_shuffle_then_choice(context, chat_id, user, session)
        raise _V156Stop
    if action == 'next':
        skey = _v129_session_key(chat_id, uid); session = TAROT_SESSIONS_V129.get(skey)
        session['stage'] = int(session.get('stage', 0) or 0) + 1
        await q.answer('Barajando…')
        await _v156_shuffle_then_choice(context, chat_id, user, session)
        raise _V156Stop
    if action == 'pick':
        skey = _v129_session_key(chat_id, uid); session = TAROT_SESSIONS_V129.get(skey)
        pick = parts[2] if len(parts)>2 else 'any'
        await q.answer('Carta elegida 🔮')
        card = _v129_pick_deck(session, pick)
        session.setdefault('draws', []).append(card)
        await _v129_show_card_result(context, chat_id, user, session, card)
        raise _V156Stop
    if action == 'final':
        skey = _v129_session_key(chat_id, uid); session = TAROT_SESSIONS_V129.get(skey)
        await q.answer('Mostrando explicación…')
        await _v129_show_final(context, chat_id, user, session)
        session['finished'] = True
        raise _V156Stop


