async def _v156_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q=update.callback_query
    if not q or not (q.data or '').startswith('t56|'): return
    parts=q.data.split('|'); act=parts[1]; chat_id=int(parts[2]); cfg=_v156_tarot_cfg(chat_id)
    try:
        if act=='img':
            mode=parts[3]
            set_config_pending(q.from_user.id, {'kind':'tarot_v156_image','chat_id':chat_id,'target':mode})
            await q.answer(); await q.message.reply_html('Envíame la imagen para la explicación de <b>{}</b>.'.format('tirada diaria' if mode=='day' else 'pasado/presente/futuro'))
            raise _V156Stop
        if act=='showsec':
            vals=[10,20,30,60]
            cur=int(cfg.get('tarot_showdraw_seconds',20) or 20); nxt=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else 20
            cfg['tarot_showdraw_seconds']=nxt; save_all_states(); await q.answer(f'Ver cartas: {nxt}s')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id)); raise _V156Stop
        if act=='pintext':
            set_config_pending(q.from_user.id, {'kind':'tarot_v156_pintext','chat_id':chat_id}); await q.answer(); await q.message.reply_html('Escribe el texto del mensaje fijado del Tarot.'); raise _V156Stop
        if act=='pinbtn':
            set_config_pending(q.from_user.id, {'kind':'tarot_v156_pinbtn','chat_id':chat_id}); await q.answer(); await q.message.reply_html('Escribe el texto del botón, por ejemplo: <b>QUIERO</b>.'); raise _V156Stop
        if act=='pinpub':
            text=str(cfg.get('tarot_pin_text') or '🔮 CARTAS DEL TAROT')
            btn=str(cfg.get('tarot_pin_button') or 'QUIERO')
            msg=await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(btn, callback_data='tar|open')]]))
            cfg['tarot_pin_message_id']=int(msg.message_id); save_all_states()
            try: await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception: pass
            await q.answer('Publicado/fijado ✅', show_alert=True); raise _V156Stop
    except _V156Stop: raise
    except Exception:
        logger.exception('Error ajustes Tarot V156')
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V156Stop

async def _v156_private_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message: return
    pending=get_config_pending(update.effective_user.id)
    if not pending or not str(pending.get('kind','')).startswith('tarot_v156_'): return
    chat_id=int(pending.get('chat_id') or 0); cfg=_v156_tarot_cfg(chat_id); kind=pending.get('kind')
    if kind=='tarot_v156_image':
        if not update.message.photo:
            await update.message.reply_html('Envíame una foto.'); raise _V156Stop
        target=pending.get('target')
        cfg['tarot_intro_day_image' if target=='day' else 'tarot_intro_ppf_image']=update.message.photo[-1].file_id
        pop_config_pending(update.effective_user.id); save_all_states(); await update.message.reply_html('✅ Imagen guardada.'); raise _V156Stop
    txt=(update.message.text or '').strip()
    if kind=='tarot_v156_pintext': cfg['tarot_pin_text']=txt[:1000]
    if kind=='tarot_v156_pinbtn': cfg['tarot_pin_button']=txt[:40]
    pop_config_pending(update.effective_user.id); save_all_states(); await update.message.reply_html('✅ Guardado.'); raise _V156Stop


async def _v155_unknown_speaker_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message: return
    if update.effective_chat.type == 'private': return
    chat_id=int(update.effective_chat.id); user=update.effective_user
    if getattr(user,'is_bot',False): return
    rec=validation_get_record(chat_id, int(user.id))

    if rec and str(rec.get('status') or '') in ('answering','pending_admin'):
        return

    return

_old_build_application_v156 = build_application

def build_application() -> Application:
    app=_old_build_application_v156()
    app.add_handler(CallbackQueryHandler(_v156_tarot_router, pattern=r'^tar\|'), group=-10000000000)
    app.add_handler(CallbackQueryHandler(_v156_showdraw_router, pattern=r'^tar\|showdraw\|'), group=-10000000001)
    app.add_handler(CallbackQueryHandler(_v156_settings_router, pattern=r'^t56\|'), group=-10000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.PHOTO) & ~filters.COMMAND, _v156_private_input), group=-10000000000)

    logger.info('V156 Tarot flujo visual definitivo + validación solo nuevos cargado')
    return app


