async def _v157_tarot_save_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|save|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    try:
        await q.answer('Creando resumen…')
        await _v157_send_summary_image_to_group(context, chat_id, rid, q.from_user)
    except Exception:
        logger.exception('Error guardando resumen Tarot V157')
        try: await q.answer('No pude crear el resumen.', show_alert=True)
        except Exception: pass
    raise _V157Stop


async def _v157_tarot_finish_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|finish|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid, {})
    owner = int(res.get('user_id') or 0)
    uid = int(q.from_user.id)
    if owner and owner != uid:
        await q.answer('🔮 Solo quien hizo esta tirada puede finalizarla.', show_alert=True)
        raise _V157Stop
    try:

        for s in list(TAROT_SESSIONS_V129.values()):
            if int(s.get('chat_id',0) or 0)==chat_id and int(s.get('user_id',0) or 0)==uid:
                s['finished'] = True
        if '_v133_mark_tarot_finished' in globals():
            _v133_mark_tarot_finished(chat_id)
        save_all_states()
        await q.answer('Tarot finalizado ✨')

        try:
            if getattr(q.message, 'photo', None):
                await q.edit_message_caption(caption=(q.message.caption_html or q.message.caption or '')[:1000], parse_mode=ParseMode.HTML, reply_markup=None)
            else:
                await q.edit_message_text((q.message.text_html or q.message.text or '🔮 Tarot finalizado.')[:3900], parse_mode=ParseMode.HTML, reply_markup=None)
        except Exception:
            pass
    except Exception:
        logger.exception('Error finalizando Tarot V157')
    raise _V157Stop


