    app = _old_build_application_v157()
    app.add_handler(CallbackQueryHandler(_v157_tarot_save_router, pattern=r'^tar\|save\|'), group=-10100000003)
    app.add_handler(CallbackQueryHandler(_v157_tarot_finish_router, pattern=r'^tar\|finish\|'), group=-10100000002)
    logger.info('V157 Tarot guardar en grupo, finalizar y miniaturas lectura cargado')
    return app


