def _v158_center_text(draw, x0: int, x1: int, y: int, text: str, font, fill) -> None:
    text = str(text or '')
    try:
        bbox = draw.textbbox((0, 0), text, font=font)
        tw = bbox[2] - bbox[0]
    except Exception:
        tw = len(text) * 8
    x = x0 + max(0, (x1 - x0 - tw) // 2)
    draw.text((x, y), text, fill=fill, font=font)


def _v158_short_card_name(name: str, max_len: int = 18) -> str:
    name = str(name or '').strip()
    return name if len(name) <= max_len else name[:max_len-1] + '…'


async def _v157_make_reading_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]):
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO
    base_img = None
    img_id = ''
    try:
        img_id = str((_v143_tarot_images(chat_id).get('reading') if '_v143_tarot_images' in globals() else '') or '')
    except Exception:
        img_id = ''
    try:
        if img_id:
            f = await context.bot.get_file(img_id)
            bio = BytesIO(); await f.download_to_memory(bio); bio.seek(0)
            base_img = Image.open(bio).convert('RGB')
    except Exception:
        base_img = None
    if base_img is None:
        base_img = Image.new('RGB', (1000, 560), (21, 14, 42))
    base_img.thumbnail((1050, 690))


    strip_h = 205
    canvas = Image.new('RGB', (base_img.width, base_img.height + strip_h), (16, 10, 32))
    canvas.paste(base_img, (0, 0))
    draw = ImageDraw.Draw(canvas)
    try:
        font_label = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf', 19)
        font_name = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 19)
        font_pending = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf', 16)
    except Exception:
        font_label = font_name = font_pending = None

    labels = ['PASADO', 'PRESENTE', 'FUTURO'] if session.get('mode') == 'ppf' else ['HOY']
    draws = list(session.get('draws') or [])
    count = 3 if session.get('mode') == 'ppf' else 1
    slot_w = canvas.width // count
    strip_y = base_img.height


    try:
        draw.rectangle([0, strip_y, canvas.width, strip_y + strip_h], fill=(18, 10, 36))
    except Exception:
        pass

    for i in range(count):
        x0 = i * slot_w
        x1 = canvas.width if i == count - 1 else (i + 1) * slot_w
        _v158_center_text(draw, x0, x1, strip_y + 12, labels[i], font_label, (240, 219, 150))
        if i < len(draws):
            card = draws[i]
            name = _v158_short_card_name(str(card.get('name') or ''))
            _v158_center_text(draw, x0, x1, strip_y + 40, name, font_name, (255, 255, 255))
            cim = await _v157_card_image_for_pil(context, chat_id, card)
            if cim:
                cim.thumbnail((92, 135))
                px = x0 + max(0, (slot_w - cim.width) // 2)
                py = strip_y + 68

                try:
                    draw.rectangle([px-3, py-3, px+cim.width+3, py+cim.height+3], outline=(221, 183, 94), width=2)
                except Exception:
                    pass
                canvas.paste(cim, (px, py))
        else:
            _v158_center_text(draw, x0, x1, strip_y + 78, 'Pendiente…', font_pending, (170, 160, 190))

    out = BytesIO(); out.name = 'lectura_camino.jpg'
    canvas.save(out, format='JPEG', quality=90, optimize=True)
    out.seek(0)
    return out


async def _v158_delete_many(bot, chat_id: int, ids: list) -> None:
    seen = set()
    for mid in ids:
        try:
            mid = int(mid or 0)
        except Exception:
            mid = 0
        if not mid or mid in seen:
            continue
        seen.add(mid)
        try:
            await bot.delete_message(chat_id, mid)
        except Exception:
            pass


def _v158_session_for_result(chat_id: int, user_id: int) -> Optional[Dict[str, Any]]:
    try:
        for s in list(TAROT_SESSIONS_V129.values()):
            if int(s.get('chat_id', 0) or 0) == int(chat_id) and int(s.get('user_id', 0) or 0) == int(user_id):
                return s
    except Exception:
        pass
    return None


async def _v158_collect_and_delete_tarot(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str, user_id: int, current_mid: int = 0) -> None:
    ids = []
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid, {})
    if isinstance(res, dict):
        for k in ('message_id', 'summary_msg_id', 'save_msg_id', 'ai_msg_id'):
            if res.get(k): ids.append(res.get(k))
        for k in ('summary_msg_ids', 'showdraw_mids', 'extra_msg_ids'):
            val = res.get(k)
            if isinstance(val, list): ids.extend(val)

    try:
        store = _v146_ai_store(chat_id) if '_v146_ai_store' in globals() else cfg.setdefault('tarot_ai_opinions', {})
        op = store.get(rid)
        if isinstance(op, dict):
            if op.get('message_id'): ids.append(op.get('message_id'))
            if op.get('ai_msg_id'): ids.append(op.get('ai_msg_id'))
    except Exception:
        pass
    s = _v158_session_for_result(chat_id, user_id)
    if isinstance(s, dict):
        for k, v in list(s.items()):
            if k.endswith('_msg_id') or k in {'lobby_msg_id','shuffle_msg_id','draws_msg_id','choice_msg_id','final_msg_id'}:
                ids.append(v)
            elif isinstance(v, list) and (k.endswith('_mids') or k.endswith('_msg_ids')):
                ids.extend(v)
        s['finished'] = True
    if current_mid:
        ids.append(current_mid)
    await _v158_delete_many(context.bot, chat_id, ids)
    try:
        if '_v133_mark_tarot_finished' in globals():
            _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass
    save_all_states()


_old_v158_send_summary_image_to_group = _v157_send_summary_image_to_group if '_v157_send_summary_image_to_group' in globals() else None
async def _v157_send_summary_image_to_group(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str, user) -> None:
    if not callable(_old_v158_send_summary_image_to_group):
        return
    before = set()
    try:

        cfg = _v129_tarot_cfg(chat_id)
        res = cfg.setdefault('tarot_results', {}).get(rid)
        if not isinstance(res, dict):
            return
        cards = list(res.get('cards') or [])
        if not cards:
            return
        maker = _v139_make_result_image if '_v139_make_result_image' in globals() else (_v137_make_result_image if '_v137_make_result_image' in globals() else None)
        if not maker:
            return
        img = await maker(context, chat_id, res.get('user_name') or display_name(user), cards)
        if not img:
            return
        msg = await context.bot.send_photo(chat_id, photo=img, caption='💾 Guarda esta imagen en tu galería.')
        res.setdefault('summary_msg_ids', []).append(int(msg.message_id))
        res['summary_msg_id'] = int(msg.message_id)
        save_all_states()
        try: await register_bot_message(chat_id, msg.message_id)
        except Exception: pass
    except Exception:
        logger.exception('Error V158 enviando resumen')


async def _v158_showdraw_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|showdraw|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esta tirada.', show_alert=True); raise _V158Stop
    await q.answer('Mostrando cartas…')
    sec = int(_v156_tarot_cfg(chat_id).get('tarot_showdraw_seconds', 20) or 20) if '_v156_tarot_cfg' in globals() else 20
    mids = []
    for cid in list(res.get('cards') or []):
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id']==cid), None)
        if not c: continue
        photo = await _v138_card_photo(context, chat_id, c, '') if '_v138_card_photo' in globals() else (_v130_card_photo(chat_id, c, '') if '_v130_card_photo' in globals() else None)
        cap = f"<b>{_v130_card_number(c.get('id','')) if '_v130_card_number' in globals() else c.get('id','')} · {h(c.get('name',''))}</b> {c.get('emoji','')}"
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=cap, parse_mode=ParseMode.HTML)
        else:
            msg = await context.bot.send_message(chat_id, cap, parse_mode=ParseMode.HTML)
        mids.append(int(msg.message_id))
    res.setdefault('showdraw_mids', []).extend(mids)
    save_all_states()
    async def _del():
        await asyncio.sleep(max(1, sec))
        await _v158_delete_many(context.bot, chat_id, mids)
    if sec > 0:
        asyncio.create_task(_del())
    raise _V158Stop


async def _v158_tarot_finish_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|finish|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid, {})
    owner = int(res.get('user_id') or 0) if isinstance(res, dict) else 0
    uid = int(q.from_user.id)
    if owner and owner != uid:
        await q.answer('🔮 Solo quien hizo esta tirada puede finalizarla.', show_alert=True)
        raise _V158Stop
    await q.answer('Tarot finalizado. Limpio la mesa ✨')
    current_mid = int(q.message.message_id) if q.message else 0
    await _v158_collect_and_delete_tarot(context, chat_id, rid, uid, current_mid=current_mid)
    raise _V158Stop


