async def _v157_make_reading_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]):
    """Panel de lectura compacto: sin imagen superior duplicada y con cartas más grandes."""
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO

    mode = session.get('mode')
    labels = ['PASADO', 'PRESENTE', 'FUTURO'] if mode == 'ppf' else ['HOY']
    draws = list(session.get('draws') or [])
    count = 3 if mode == 'ppf' else 1


    width = 1080
    height = 500 if count == 3 else 560
    bg = Image.new('RGB', (width, height), (17, 8, 34))
    draw = ImageDraw.Draw(bg)

    try:
        font_label = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf', 24)
        font_name = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 28)
        font_pending = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf', 24)
        font_title = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 34)
    except Exception:
        font_label = font_name = font_pending = font_title = None


    try:
        for i in range(0, height, 14):
            shade = 26 + (i % 60)
            draw.line([(0, i), (width, i)], fill=(shade, 10, 52), width=1)
        draw.rectangle([10, 10, width-10, height-10], outline=(198, 151, 76), width=3)
        _v158_center_text(draw, 0, width, 26, '🔮 LECTURA DEL CAMINO', font_title, (246, 221, 147))
    except Exception:
        pass

    slot_w = width // count
    top_y = 92

    thumb_size = (190, 285) if count == 3 else (260, 380)

    for i in range(count):
        x0 = i * slot_w
        x1 = width if i == count - 1 else (i + 1) * slot_w
        label = labels[i]
        _v158_center_text(draw, x0, x1, top_y, label, font_label, (236, 207, 128))

        if i < len(draws):
            card = draws[i]
            name = _v158_short_card_name(str(card.get('name') or ''), 22)
            _v158_center_text(draw, x0, x1, top_y + 34, name, font_name, (255, 255, 255))
            cim = await _v157_card_image_for_pil(context, chat_id, card)
            if cim:
                cim.thumbnail(thumb_size)
                px = x0 + max(0, (slot_w - cim.width) // 2)
                py = top_y + 82
                try:
                    draw.rectangle([px-6, py-6, px+cim.width+6, py+cim.height+6], outline=(230, 185, 94), width=4)
                    draw.rectangle([px-10, py-10, px+cim.width+10, py+cim.height+10], outline=(92, 49, 135), width=2)
                except Exception:
                    pass
                bg.paste(cim, (px, py))
        else:
            _v158_center_text(draw, x0, x1, top_y + 98, 'Pendiente…', font_pending, (180, 166, 205))

            ph_w, ph_h = thumb_size
            px = x0 + max(0, (slot_w - ph_w) // 2)
            py = top_y + 145
            try:
                draw.rounded_rectangle([px, py, px+ph_w, py+ph_h], radius=18, outline=(90, 70, 120), width=3, fill=(25, 14, 45))
                _v158_center_text(draw, px, px+ph_w, py + ph_h//2 - 12, '🂠', font_title, (118, 98, 150))
            except Exception:
                pass

    out = BytesIO()
    out.name = 'lectura_camino.jpg'
    bg.save(out, format='JPEG', quality=92, optimize=True)
    out.seek(0)
    return out


async def _v159_get_bot_admin_report(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> Dict[str, Any]:
    report: Dict[str, Any] = {
        'chat_ok': False,
        'bot_admin': False,
        'can_delete': False,
        'can_restrict': False,
        'can_pin': False,
        'can_invite': False,
        'can_manage_chat': False,
        'bot_username': '',
        'chat_title': '',
        'error': '',
    }
    try:
        chat = await context.bot.get_chat(chat_id)
        report['chat_ok'] = True
        report['chat_title'] = getattr(chat, 'title', '') or str(chat_id)
        me = await context.bot.get_me()
        report['bot_username'] = getattr(me, 'username', '') or ''
        member = await context.bot.get_chat_member(chat_id, me.id)
        status = getattr(member, 'status', '')
        report['bot_admin'] = status in ('administrator', 'creator')
        report['can_delete'] = bool(getattr(member, 'can_delete_messages', False)) or status == 'creator'
        report['can_restrict'] = bool(getattr(member, 'can_restrict_members', False)) or status == 'creator'
        report['can_pin'] = bool(getattr(member, 'can_pin_messages', False)) or status == 'creator'
        report['can_invite'] = bool(getattr(member, 'can_invite_users', False)) or status == 'creator'
        report['can_manage_chat'] = bool(getattr(member, 'can_manage_chat', False)) or status == 'creator'
    except Exception as e:
        report['error'] = f'{type(e).__name__}: {e}'[:300]
    return report


def _v159_module_status(chat_id: int) -> Dict[str, bool]:
    cfg = admin_cfg(chat_id)
    return {
        'validation_enabled': bool(cfg.get('validation_enabled', False)),
        'validation_questions': len(cfg_questions(chat_id)) > 0,
        'welcome_configured': bool(str(cfg.get('welcome_text') or cfg.get('validation_intro_message') or '').strip()),
        'tarot': bool(cfg.get('tarot_enabled', True)),
        'dj': True,
        'recurrentes': True,
        'ai': True,
        'daily_phrase': True,
        'impostor': bool(cfg.get('impostor_enabled', True)),
        'pregonero': True,
    }


async def _v159_build_health_text(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> str:
    state = get_state(chat_id)
    cfg = admin_cfg(chat_id)
    perms = await _v159_get_bot_admin_report(context, chat_id)
    modules = _v159_module_status(chat_id)
    pending = sum(1 for r in state.validation_users.values() if r.get('status') in ('answering','pending_admin','timeout'))
    validated = sum(1 for r in state.validation_users.values() if r.get('status') == 'validated')
    known = len(state.validation_users)

    validation_ready = bool(modules['validation_enabled'] and modules['validation_questions'] and perms['bot_admin'] and perms['can_restrict'])
    welcome_ready = bool(modules['welcome_configured'] and perms['bot_admin'])

    lines = [
        '<b>✅ COMPROBACIÓN DEL BOT · EL PLAN</b>',
        f"Grupo: <b>{h(perms.get('chat_title') or get_chat_title(chat_id) if 'get_chat_title' in globals() else str(chat_id))}</b>",
        '',
        '<b>Permisos del bot</b>',
        f"{_v159_check_mark(perms['chat_ok'])} Acceso al grupo",
        f"{_v159_check_mark(perms['bot_admin'])} Bot administrador",
        f"{_v159_check_mark(perms['can_delete'])} Puede borrar mensajes",
        f"{_v159_check_mark(perms['can_restrict'])} Puede restringir usuarios",
        f"{_v159_check_mark(perms['can_pin'])} Puede fijar mensajes",
        f"{_v159_check_mark(perms['can_invite'])} Puede gestionar/invitar miembros",
        '',
        '<b>Validación y bienvenida de nuevos</b>',
        f"{_v159_check_mark(modules['validation_enabled'])} Validación activada",
        f"{_v159_check_mark(modules['validation_questions'])} Preguntas configuradas: <b>{len(cfg_questions(chat_id))}</b>",
        f"{_v159_check_mark(welcome_ready)} Mensaje de bienvenida/presentación configurado",
        f"{_v159_check_mark(validation_ready)} Sistema listo para nuevos miembros",
        f"👥 Pendientes actuales: <b>{pending}</b>",
        f"✅ Validados registrados: <b>{validated}</b>",
        f"📚 Registros de validación: <b>{known}</b>",
        '',
        '<b>Módulos principales</b>',
        f"{_v159_check_mark(modules['tarot'])} Tarot",
        f"{_v159_check_mark(modules['dj'])} DJ / Música",
        f"{_v159_check_mark(modules['recurrentes'])} Recurrentes",
        f"{_v159_check_mark(modules['ai'])} Cerebrito IA",
        f"{_v159_check_mark(modules['daily_phrase'])} Frase del día",
        f"{_v159_check_mark(modules['impostor'])} Impostor",
        f"{_v159_check_mark(modules['pregonero'])} Pregonero",
        '',
        '<b>Lectura rápida</b>',
    ]
    if validation_ready:
        lines.append('✅ La validación está preparada. Para que salte siempre al entrar alguien, el bot debe seguir siendo admin con permiso de restringir usuarios.')
    else:
        lines.append('❌ Revisa validación: normalmente falta permiso de restringir usuarios, preguntas o validación activada.')
    if perms.get('error'):
        lines.append(f"\n<code>{h(perms['error'])}</code>")
    return '\n'.join(lines)[:3900]


async def _v159_health_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|botcheck|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V159Stop
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V159Stop
    try:
        await q.answer('Comprobando módulos…')
    except Exception:
        pass
    text = await _v159_build_health_text(context, chat_id)
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('🔄 Repetir comprobación', callback_data=f'cfg|botcheck|{chat_id}')],
        [InlineKeyboardButton('🔙 Volver a ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html(text, reply_markup=markup)
    raise _V159Stop


_old_v159_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    old = _old_v159_admin_private_main_markup(chat_id)
    rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]

    exists = any(any((getattr(b, 'callback_data', '') or '').startswith('cfg|botcheck|') for b in row) for row in rows)
    if not exists:
        insert_at = max(0, len(rows)-2)
        rows.insert(insert_at, [InlineKeyboardButton('✅ Comprobar funcionamiento del bot', callback_data=f'cfg|botcheck|{chat_id}')])
    return InlineKeyboardMarkup(rows)


_old_v159_build_application = build_application

def build_application() -> Application:
    app = _old_v159_build_application()
    app.add_handler(CallbackQueryHandler(_v159_health_router, pattern=r'^cfg\|botcheck\|'), group=-10300000000)
    logger.info('V159 Tarot miniaturas grandes sin imagen superior + comprobador de módulos cargado')
    return app


async def _v157_make_reading_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]):
    from PIL import Image, ImageDraw, ImageFont
    from io import BytesIO

    mode = session.get('mode')
    labels = ['PASADO', 'PRESENTE', 'FUTURO'] if mode == 'ppf' else ['HOY']
    draws = list(session.get('draws') or [])
    count = 3 if mode == 'ppf' else 1

    width = 1080

    height = 760 if count == 3 else 820
    bg = Image.new('RGB', (width, height), (14, 6, 29))
    draw = ImageDraw.Draw(bg)

    try:
        font_label = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Oblique.ttf', 34)
        font_name = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Bold.ttf', 32)
        font_pending = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Oblique.ttf', 28)
        font_symbol = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 54)
    except Exception:
        font_label = font_name = font_pending = font_symbol = None


    try:
        for y in range(height):

            r = 16 + int(16 * (y / max(1, height)))
            g = 7 + int(5 * (y / max(1, height)))
            b = 34 + int(34 * (y / max(1, height)))
            draw.line([(0, y), (width, y)], fill=(r, g, b), width=1)
        for y in range(24, height, 34):
            draw.line([(26, y), (width - 26, y)], fill=(44, 20, 76), width=1)
        draw.rounded_rectangle([14, 14, width-14, height-14], radius=18, outline=(224, 176, 85), width=4)
        draw.rounded_rectangle([27, 27, width-27, height-27], radius=14, outline=(82, 42, 122), width=2)
    except Exception:
        pass

    slot_w = width // count
    label_y = 48
    name_y = 102
    card_y = 155


    thumb_size = (270, 455) if count == 3 else (440, 650)

    for i in range(count):
        x0 = i * slot_w
        x1 = width if i == count - 1 else (i + 1) * slot_w
        label = labels[i]


        _v158_center_text(draw, x0, x1, label_y, label, font_label, (238, 207, 131))

        if i < len(draws):
            card = draws[i]
            name = _v158_short_card_name(str(card.get('name') or ''), 24)
            _v158_center_text(draw, x0, x1, name_y, name, font_name, (255, 248, 225))
            cim = await _v157_card_image_for_pil(context, chat_id, card)
            if cim:
                cim.thumbnail(thumb_size)
                px = x0 + max(0, (slot_w - cim.width) // 2)
                py = card_y
                try:
                    draw.rounded_rectangle([px-13, py-13, px+cim.width+13, py+cim.height+13], radius=14, fill=(26, 12, 47), outline=(235, 189, 94), width=5)
                    draw.rounded_rectangle([px-21, py-21, px+cim.width+21, py+cim.height+21], radius=18, outline=(110, 52, 158), width=3)
                except Exception:
                    pass
                bg.paste(cim, (px, py))
        else:
            _v158_center_text(draw, x0, x1, name_y, 'Pendiente…', font_pending, (190, 174, 214))
            ph_w, ph_h = thumb_size
            px = x0 + max(0, (slot_w - ph_w) // 2)
            py = card_y
            try:
                draw.rounded_rectangle([px-13, py-13, px+ph_w+13, py+ph_h+13], radius=18, fill=(19, 9, 35), outline=(90, 70, 122), width=4)
                draw.rounded_rectangle([px, py, px+ph_w, py+ph_h], radius=16, outline=(138, 99, 180), width=3, fill=(29, 14, 52))

                _v158_center_text(draw, px, px+ph_w, py + ph_h//2 - 26, '🂠', font_symbol, (136, 105, 170))
            except Exception:
                pass


    try:
        footer = 'Las cartas van revelando el camino…'
        _v158_center_text(draw, 0, width, height - 54, footer, font_pending, (174, 151, 200))
    except Exception:
        pass

    out = BytesIO()
    out.name = 'lectura_camino.jpg'
    bg.save(out, format='JPEG', quality=94, optimize=True)
    out.seek(0)
    return out

