def _v163_fit_contain(img, size, *, bg=(12, 6, 26)):
    from PIL import Image, ImageFilter
    tw, th = size
    base = Image.new('RGB', size, bg)
    if img is None:
        return base
    img = img.convert('RGB')
    iw, ih = img.size
    scale = min(tw / max(1, iw), th / max(1, ih))
    nw, nh = max(1, int(iw * scale)), max(1, int(ih * scale))
    resized = img.resize((nw, nh), Image.LANCZOS)

    try:
        cover_scale = max(tw / max(1, iw), th / max(1, ih))
        cw, ch = max(1, int(iw * cover_scale)), max(1, int(ih * cover_scale))
        cover = img.resize((cw, ch), Image.LANCZOS)
        left = max(0, (cw - tw) // 2)
        top = max(0, (ch - th) // 2)
        cover = cover.crop((left, top, left + tw, top + th)).filter(ImageFilter.GaussianBlur(12))

        overlay = Image.new('RGB', size, (8, 4, 18))
        base = Image.blend(cover, overlay, 0.45)
    except Exception:
        pass
    x = (tw - nw) // 2
    y = (th - nh) // 2
    base.paste(resized, (x, y))
    return base


def _v163_draw_card_frame(draw, box, *, active=False):
    x1, y1, x2, y2 = box
    try:
        fill = (25, 9, 48) if not active else (24, 11, 45)
        outline1 = (232, 187, 93) if active else (110, 73, 150)
        outline2 = (126, 57, 176) if active else (70, 42, 112)
        draw.rounded_rectangle([x1-12, y1-12, x2+12, y2+12], radius=24, fill=(13, 6, 29), outline=outline2, width=4)
        draw.rounded_rectangle([x1, y1, x2, y2], radius=20, fill=fill, outline=outline1, width=4)
        draw.rounded_rectangle([x1+12, y1+12, x2-12, y2-12], radius=16, outline=(148, 105, 191), width=2)
    except Exception:
        pass


async def _v157_make_reading_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]):
    from PIL import Image, ImageDraw
    from io import BytesIO

    mode = session.get('mode')
    draws = list(session.get('draws') or [])
    count = 3 if mode == 'ppf' else 1

    width = 1080
    top_h = 360 if count == 3 else 330
    panel_h = 470 if count == 3 else 560
    height = top_h + panel_h

    top_img = await _v162_reading_top_image(context, chat_id) if '_v162_reading_top_image' in globals() else None
    top = _v163_fit_contain(top_img, (width, top_h))

    bg = Image.new('RGB', (width, height), (13, 6, 27))
    bg.paste(top, (0, 0))
    draw = ImageDraw.Draw(bg)

    panel_y = top_h

    for y in range(panel_y, height):
        t = (y - panel_y) / max(1, panel_h)
        draw.line([(0, y), (width, y)], fill=(15 + int(10*t), 6 + int(5*t), 31 + int(22*t)), width=1)
    try:
        draw.rounded_rectangle([18, panel_y + 12, width - 18, height - 14], radius=26, outline=(224, 176, 85), width=4)
        draw.rounded_rectangle([34, panel_y + 28, width - 34, height - 30], radius=22, outline=(84, 43, 130), width=2)
    except Exception:
        pass

    slot_w = width // count
    if count == 3:
        thumb_size = (245, 390)
        card_top = panel_y + 54
    else:
        thumb_size = (380, 500)
        card_top = panel_y + 34

    for i in range(count):
        x0 = i * slot_w
        x1 = width if i == count - 1 else (i + 1) * slot_w
        area_cx = (x0 + x1) // 2
        ph_w, ph_h = thumb_size
        px = area_cx - ph_w // 2
        py = card_top

        if i < len(draws):
            card = draws[i]
            cim = await _v157_card_image_for_pil(context, chat_id, card)
            if cim:
                cim.thumbnail(thumb_size)
                cx = area_cx - cim.width // 2
                cy = card_top + max(0, (thumb_size[1] - cim.height) // 2)
                _v163_draw_card_frame(draw, (cx, cy, cx+cim.width, cy+cim.height), active=True)
                bg.paste(cim, (cx, cy))
        else:
            _v163_draw_card_frame(draw, (px, py, px+ph_w, py+ph_h), active=False)

            for sx, sy, col in [
                (px + ph_w*0.22, py + ph_h*0.20, (179, 139, 230)),
                (px + ph_w*0.76, py + ph_h*0.25, (231, 193, 112)),
                (px + ph_w*0.50, py + ph_h*0.52, (130, 97, 174)),
                (px + ph_w*0.28, py + ph_h*0.78, (231, 193, 112)),
                (px + ph_w*0.72, py + ph_h*0.76, (179, 139, 230)),
            ]:
                sx, sy = int(sx), int(sy)
                draw.line([(sx-8, sy), (sx+8, sy)], fill=col, width=2)
                draw.line([(sx, sy-8), (sx, sy+8)], fill=col, width=2)

    out = BytesIO()
    out.name = 'lectura_camino.jpg'
    bg.save(out, format='JPEG', quality=94, optimize=True)
    out.seek(0)
    return out


