_old_v163_show_final = _v129_show_final
async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    """Final con imagen visual de miniaturas debajo de la imagen principal.

    Mantiene las mismas claves de resultados/botones usadas por las versiones previas.
    """
    draws = session.get('draws', [])
    if not draws:
        return

    try:
        if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)):
            await _v137_delete_intermediate(context, chat_id, session, include_result=False)
    except Exception:
        pass

    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cards = [c['id'] for c in draws]
    text = _v138_result_text(user, session, draws) if '_v138_result_text' in globals() else (_v130_result_text(user, session, draws) if '_v130_result_text' in globals() else '')
    res = {
        'user_id': int(user.id),
        'user_name': display_name(user),
        'mode': session.get('mode','day'),
        'cards': cards,
        'likes': [],
        'flips': [],
        'ts': int(time.time()),
        'text': text,
        'photo': True,
    }
    cfg.setdefault('tarot_results', {})[result_id] = res
    try:
        _v147_result_op(chat_id, result_id)
    except Exception:
        pass
    save_all_states()

    try:
        img = await _v163_result_visual_image(context, chat_id, session)
        caption = _v147_result_caption_or_text(text, chat_id, result_id, max_len=980) if '_v147_result_caption_or_text' in globals() else text[:980]
        markup = _v147_final_markup(chat_id, result_id) if '_v147_final_markup' in globals() else InlineKeyboardMarkup([[InlineKeyboardButton('🃏 Ver cartas', callback_data=f'tar|showdraw|{result_id}'), InlineKeyboardButton('💾 GUARDAR', callback_data=f'tar|save|{result_id}')]])
        msg = await context.bot.send_photo(chat_id, photo=img, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        logger.exception('No pude enviar final visual V163; uso final anterior')

        return await _old_v163_show_final(context, chat_id, user, session)

    res['message_id'] = int(msg.message_id)
    session['final_msg_id'] = int(msg.message_id)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    try:
        _v129_inc_usage(chat_id, int(user.id), session.get('mode','day'))
    except Exception:
        pass
    try:
        _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass
    save_all_states()
    try:
        sec = int((_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) if '_v139_tarot_cfg' in globals() else 0) or 0)
        if sec:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, int(msg.message_id)))
    except Exception:
        pass


