def _v164_draw_soft_placeholder(draw, box):
    """Hueco pendiente sin marco amarillo, solo sombra morada suave."""
    x1, y1, x2, y2 = box
    try:

        draw.rounded_rectangle([x1-10, y1-10, x2+10, y2+10], radius=24, fill=(12, 5, 28), outline=(45, 24, 75), width=2)

        draw.rounded_rectangle([x1, y1, x2, y2], radius=22, fill=(23, 8, 45), outline=(91, 52, 135), width=3)
        draw.rounded_rectangle([x1+10, y1+10, x2-10, y2-10], radius=17, outline=(52, 29, 86), width=2)

        for sx, sy, col in [
            (x1 + (x2-x1)*0.27, y1 + (y2-y1)*0.25, (169, 121, 229)),
            (x1 + (x2-x1)*0.72, y1 + (y2-y1)*0.38, (118, 78, 170)),
            (x1 + (x2-x1)*0.48, y1 + (y2-y1)*0.68, (194, 151, 235)),
        ]:
            sx, sy = int(sx), int(sy)
            draw.line([(sx-7, sy), (sx+7, sy)], fill=col, width=2)
            draw.line([(sx, sy-7), (sx, sy+7)], fill=col, width=2)
    except Exception:
        pass


def _v164_draw_card_shadow(draw, box):
    """Solo sombra detrás de carta real; sin borde externo amarillo."""
    x1, y1, x2, y2 = box
    try:
        draw.rounded_rectangle([x1-8, y1-8, x2+8, y2+8], radius=20, fill=(10, 4, 24), outline=(44, 22, 72), width=2)
    except Exception:
        pass


async def _v157_make_reading_image(context: ContextTypes.DEFAULT_TYPE, chat_id: int, session: Dict[str, Any]):
    from PIL import Image, ImageDraw
    from io import BytesIO

    mode = session.get('mode')
    draws = list(session.get('draws') or [])
    count = 3 if mode == 'ppf' else 1

    width = 1080

    top_h = 360 if count == 3 else 330
    panel_h = 440 if count == 3 else 520
    height = top_h + panel_h

    top_img = await _v162_reading_top_image(context, chat_id) if '_v162_reading_top_image' in globals() else None
    top = _v163_fit_contain(top_img, (width, top_h)) if '_v163_fit_contain' in globals() else Image.new('RGB', (width, top_h), (12,6,26))

    bg = Image.new('RGB', (width, height), (13, 6, 27))
    bg.paste(top, (0, 0))
    draw = ImageDraw.Draw(bg)

    panel_y = top_h

    for y in range(panel_y, height):
        t = (y - panel_y) / max(1, panel_h)
        draw.line([(0, y), (width, y)], fill=(12 + int(8*t), 5 + int(4*t), 26 + int(16*t)), width=1)


    try:
        draw.rectangle([0, panel_y, width, panel_y+4], fill=(56, 27, 91))
    except Exception:
        pass

    slot_w = width // count
    if count == 3:
        thumb_size = (270, 395)
        card_top = panel_y + 24
    else:
        thumb_size = (430, 500)
        card_top = panel_y + 16

    for i in range(count):
        x0 = i * slot_w
        x1 = width if i == count - 1 else (i + 1) * slot_w
        area_cx = (x0 + x1) // 2
        ph_w, ph_h = thumb_size
        px = area_cx - ph_w // 2
        py = card_top

        if i < len(draws):
            card = draws[i]
            cim = await _v157_card_image_for_pil(context, chat_id, card)
            if cim:
                cim.thumbnail(thumb_size)
                cx = area_cx - cim.width // 2
                cy = card_top + max(0, (thumb_size[1] - cim.height) // 2)
                _v164_draw_card_shadow(draw, (cx, cy, cx+cim.width, cy+cim.height))
                bg.paste(cim, (cx, cy))
        else:
            _v164_draw_soft_placeholder(draw, (px, py, px+ph_w, py+ph_h))

    out = BytesIO()
    out.name = 'lectura_camino.jpg'
    bg.save(out, format='JPEG', quality=94, optimize=True)
    out.seek(0)
    return out


