def _v165_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cfg.setdefault('validation_force_unknown_speakers', False)
    cfg.setdefault('validation_enabled', True)
    cfg.setdefault('imp_start_image_file_id', '')
    cfg.setdefault('imp_round1_image_file_id', '')
    cfg.setdefault('imp_round2_image_file_id', '')
    cfg.setdefault('imp_round3_image_file_id', '')
    cfg.setdefault('imp_visual_emoji_html', '🎭')
    cfg.setdefault('imp_round_delay_sec', 5)
    return cfg


