def _v155_validation_cfg(chat_id: int) -> Dict[str, Any]:
    if callable(_old_v165_validation_cfg):
        cfg = _old_v165_validation_cfg(chat_id)
    else:
        cfg = admin_cfg(chat_id)
    cfg['validation_force_unknown_speakers'] = False
    cfg.setdefault('validation_enabled', True)
    return cfg


def _v165_entry_seen_key(chat_id: int, user_id: int) -> str:
    return f'{int(chat_id)}:{int(user_id)}'


def _v165_recent_entry_seen(chat_id: int, user_id: int, ttl: int = 20) -> bool:
    cfg = admin_cfg(chat_id)
    seen = cfg.setdefault('v165_entry_seen', {})
    now = int(time.time())

    try:
        for k, ts in list(seen.items())[:200]:
            if now - int(ts or 0) > 300:
                seen.pop(k, None)
    except Exception:
        pass
    key = _v165_entry_seen_key(chat_id, user_id)
    last = int(seen.get(key, 0) or 0)
    if last and now - last < ttl:
        return True
    seen[key] = now
    return False


async def _v165_start_validation_new_user(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, *, source: str, reply_to_message_id: Optional[int] = None) -> bool:
    if not user or getattr(user, 'is_bot', False):
        return False
    if not bool(_v165_cfg(chat_id).get('validation_enabled', True)):
        return False
    if _v165_recent_entry_seen(chat_id, int(user.id)):
        return False

    try:
        return bool(await start_validation_for_user(context, context, chat_id, user, reply_to_message_id=reply_to_message_id, source=source, force=True))
    except Exception:
        logger.exception('V165 no pudo validar nuevo usuario %s en %s', getattr(user, 'id', None), chat_id)
        return False


async def _v165_new_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    for user in list(getattr(update.message, 'new_chat_members', []) or []):
        await _v165_start_validation_new_user(context, chat_id, user, source='new_member_v165', reply_to_message_id=update.message.message_id)
    raise _V165Stop


async def _v165_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    req = update.chat_join_request
    if not req or not req.chat or not req.from_user:
        return
    chat_id = int(req.chat.id)
    user = req.from_user
    if bool(cfg_value(chat_id, 'validation_auto_approve_join_requests', True)):
        try:
            await context.bot.approve_chat_join_request(chat_id=chat_id, user_id=int(user.id))
        except Exception:
            logger.exception('V165 no pudo aprobar solicitud de entrada')
    await _v165_start_validation_new_user(context, chat_id, user, source='join_request_v165')
    raise _V165Stop


async def _v165_chat_member_join(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, 'chat_member', None)
    if not cmu or not getattr(cmu, 'chat', None):
        return
    chat_id = int(cmu.chat.id)
    old = getattr(cmu, 'old_chat_member', None)
    new = getattr(cmu, 'new_chat_member', None)
    user = getattr(new, 'user', None) or getattr(old, 'user', None)
    if not user or getattr(user, 'is_bot', False):
        return
    old_s = str(getattr(old, 'status', '') or '')
    new_s = str(getattr(new, 'status', '') or '')
    if old_s in ('left', 'kicked', '') and new_s in ('member', 'restricted', 'administrator', 'creator'):
        await _v165_start_validation_new_user(context, chat_id, user, source='chat_member_join_v165')
        raise _V165Stop


