async def _v165_imp_settings_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|imp165'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True); raise _V165Stop
    if action == 'imp165emoji':
        set_config_pending(q.from_user.id, {'kind': 'imp165_emoji', 'chat_id': chat_id})
        await q.answer()
        await q.message.reply_html('Envíame ahora el emoji o emojis premium de Telegram para los avisos del Impostor.')
        raise _V165Stop
    if action == 'imp165img':
        kind = parts[3] if len(parts) > 3 else 'start'
        set_config_pending(q.from_user.id, {'kind': 'imp165_img', 'chat_id': chat_id, 'target': kind})
        await q.answer()
        await q.message.reply_html('Envíame ahora la imagen 3:1 para Impostor. Recomendado: <b>1080x360 px</b>.')
        raise _V165Stop
    if action == 'imp165delay':
        sec = int(parts[3]) if len(parts) > 3 else 5
        _v165_cfg(chat_id)['imp_round_delay_sec'] = max(1, min(20, sec))
        save_all_states()
        await q.answer('Tiempo actualizado ✅')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        except Exception:
            pass
        raise _V165Stop


async def _v165_imp_private_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or str(pending.get('kind','')) not in ('imp165_emoji', 'imp165_img'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    cfg = _v165_cfg(chat_id)
    if pending.get('kind') == 'imp165_emoji':
        val = telegram_html_from_message(update.message).strip() or plain_text_from_message(update.message).strip()
        if not val:
            await update.message.reply_html('Envíame un emoji o texto válido.')
            raise _V165Stop
        cfg['imp_visual_emoji_html'] = val[:300]
        pop_config_pending(update.effective_user.id); save_all_states()
        await update.message.reply_html('✅ Emoji guardado para Impostor.\n\n' + admin_private_block_text(chat_id, 'impostor_settings'), reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        raise _V165Stop

    photos = getattr(update.message, 'photo', None)
    if not photos:
        await update.message.reply_html('Envíame una <b>foto</b>, no texto.')
        raise _V165Stop
    fid = photos[-1].file_id
    target = str(pending.get('target') or 'start')
    key = {'start':'imp_start_image_file_id','r1':'imp_round1_image_file_id','r2':'imp_round2_image_file_id','r3':'imp_round3_image_file_id'}.get(target, 'imp_start_image_file_id')
    cfg[key] = fid
    pop_config_pending(update.effective_user.id); save_all_states()
    await update.message.reply_html('✅ Imagen guardada para Impostor.\n\n' + admin_private_block_text(chat_id, 'impostor_settings'), reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
    raise _V165Stop


def _v165_imp_mentions(game: Dict[str, Any]) -> str:
    vals = []
    for p in game.get('players', []) if isinstance(game.get('players'), list) else []:
        try:
            vals.append(f'<a href="tg://user?id={int(p.get("id"))}">{h(str(p.get("name") or "Jugador"))}</a>')
        except Exception:
            vals.append(h(str(p.get('name') or 'Jugador')))
    return ', '.join(vals)


async def _v165_send_temp_photo_or_text(bot, chat_id: int, *, photo: str = '', text: str = '', seconds: int = 5, markup=None) -> int:
    msg = None
    try:
        if photo:
            msg = await bot.send_photo(chat_id, photo=photo, caption=text[:1000], parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        logger.exception('V165 no pudo enviar aviso visual')
        msg = await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    if seconds > 0:
        await asyncio.sleep(seconds)
        try:
            await bot.delete_message(chat_id, msg.message_id)
        except Exception:
            pass
    return int(msg.message_id)


_old_v165_imp_start_game = _v58_imp_start_game
async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:
    cfg = _v165_cfg(chat_id)
    emoji = str(cfg.get('imp_visual_emoji_html') or '🎭')
    players = game.get('players', []) if isinstance(game.get('players'), list) else []
    starter = secrets.choice(players) if players else None
    starter_txt = ''
    if starter:
        try:
            starter_txt = f'\n\nEmpieza: <a href="tg://user?id={int(starter.get("id"))}">{h(str(starter.get("name") or "Jugador"))}</a>'
        except Exception:
            starter_txt = f'\n\nEmpieza: <b>{h(str(starter.get("name") or "Jugador"))}</b>'
    text = (
        f'{emoji} <b>LA PARTIDA VA A COMENZAR</b> {emoji}\n\n'
        f'Jugadores: {_v165_imp_mentions(game)}\n'
        f'{starter_txt}\n\n'
        'Preparad la mente. El impostor ya camina entre vosotros…'
    )
    sec = int(cfg.get('imp_round_delay_sec', 5) or 5)
    await _v165_send_temp_photo_or_text(context.bot, chat_id, photo=str(cfg.get('imp_start_image_file_id') or ''), text=text, seconds=sec)
    return await _old_v165_imp_start_game(update, context, chat_id, gid, game)


_old_v165_imp_render_down = _v58_imp_render_down
async def _v58_imp_render_down(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, delete_previous: bool = True) -> None:
    try:
        if str(game.get('status')) == 'active':
            ronda = int(game.get('round', 1) or 1)
            if int(game.get('v165_round_intro_shown', 0) or 0) != ronda:
                cfg = _v165_cfg(chat_id)
                sec = int(cfg.get('imp_round_delay_sec', 5) or 5)
                img = str(cfg.get(f'imp_round{ronda}_image_file_id') or '')
                emoji = str(cfg.get('imp_visual_emoji_html') or '🎭')
                round_names = {1:'PRIMERA',2:'SEGUNDA',3:'TERCERA'}
                text = f'{emoji} <b>VAMOS CON LA {round_names.get(ronda, str(ronda))} RONDA DE PREGUNTAS</b> {emoji}'
                await _v165_send_temp_photo_or_text(context.bot, chat_id, photo=img, text=text, seconds=sec)
                game['v165_round_intro_shown'] = ronda
                try:
                    can_accuse, _ = _v61_can_accuse_now(chat_id, game)
                except Exception:
                    can_accuse = False
                if can_accuse and int(game.get('v165_accuse_notice_round', 0) or 0) != ronda:
                    m = await context.bot.send_message(chat_id, '🚨 <b>YA SE PUEDE ACUSAR AL IMPOSTOR</b>\nObservad las pistas… y señalad con cabeza.', parse_mode=ParseMode.HTML)
                    game['v165_accuse_notice_round'] = ronda
                    try:
                        await register_bot_message(chat_id, m.message_id)
                    except Exception:
                        pass
                    await asyncio.sleep(2)
                    try:
                        await context.bot.delete_message(chat_id, m.message_id)
                    except Exception:
                        pass
    except Exception:
        logger.exception('V165 intro de ronda Impostor falló')
    return await _old_v165_imp_render_down(context, chat_id, game, delete_previous=delete_previous)


_old_v165_rec_detail_markup = recurring_detail_markup

def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    markup = _old_v165_rec_detail_markup(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    if not any(any((getattr(b, 'callback_data', '') or '').startswith(f'cfg|rec_dup|{chat_id}|{rid}') for b in row) for row in rows):
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('📄 Duplicar recurrente', callback_data=f'cfg|rec_dup|{chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)


async def _v165_recurrentes_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rec_'):
        return
    parts = q.data.split('|')
    action = parts[1]
    if action not in ('rec_send','rec_dup'):
        return
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
    except Exception:
        await q.answer('Recurrente inválido.', show_alert=True); raise _V165Stop
    row = recurring_find(chat_id, rid)
    if not row:
        await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V165Stop
    if action == 'rec_send':
        await send_recurring_message(context, chat_id, row)
        await q.answer('Enviado ✅')

        raise _V165Stop
    if action == 'rec_dup':
        import copy
        new_row = copy.deepcopy(row)
        new_id = recurring_next_id(chat_id)
        new_row['id'] = new_id
        new_row['name'] = (str(row.get('name') or f'Recurrente {rid}') + ' · copia')[:90]
        new_row['enabled'] = False
        new_row['last_sent_ts'] = 0
        new_row.pop('last_day', None)
        recurring_list(chat_id).append(new_row)
        save_all_states()
        await q.answer('Duplicado ✅. Entra en la copia y cambia el horario.', show_alert=True)
        await q.edit_message_text(recurring_detail_text(chat_id, new_id), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, new_id))
        raise _V165Stop


