import copy as _copy_v167


def _v167_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v156_tarot_cfg(chat_id) if '_v156_tarot_cfg' in globals() else (_v129_tarot_cfg(chat_id) if '_v129_tarot_cfg' in globals() else admin_cfg(chat_id))
    cfg.setdefault('tarot_zero_requires_ticket', True)
    cfg.setdefault('tarot_ticket_grant_role', 'admins')
    cfg.setdefault('tarot_ticket_manual_ids', [])
    cfg.setdefault('tarot_tickets', {})
    return cfg


def _v167_day_key() -> str:
    try:
        return _v129_today_key()
    except Exception:
        return time.strftime('%Y-%m-%d')


def _v167_ticket_row(chat_id: int, user_id: int) -> Dict[str, int]:
    cfg = _v167_tarot_cfg(chat_id)
    root = cfg.setdefault('tarot_tickets', {})
    day = root.setdefault(_v167_day_key(), {})
    row = day.setdefault(str(int(user_id)), {'day': 0, 'ppf': 0})
    if not isinstance(row, dict):
        row = {'day': 0, 'ppf': 0}
        day[str(int(user_id))] = row
    row.setdefault('day', 0); row.setdefault('ppf', 0)
    return row


def _v167_ticket_count(chat_id: int, user_id: int, mode: str) -> int:
    try:
        return int(_v167_ticket_row(chat_id, user_id).get(mode, 0) or 0)
    except Exception:
        return 0


def _v167_add_ticket(chat_id: int, user_id: int, mode: str, qty: int = 1) -> None:
    row = _v167_ticket_row(chat_id, user_id)
    row[mode] = max(0, int(row.get(mode, 0) or 0) + int(qty))
    save_all_states()


def _v167_consume_ticket(chat_id: int, user_id: int, mode: str) -> bool:
    row = _v167_ticket_row(chat_id, user_id)
    cur = int(row.get(mode, 0) or 0)
    if cur <= 0:
        return False
    row[mode] = cur - 1
    save_all_states()
    return True


async def _v167_can_grant_ticket(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> bool:
    uid = int(getattr(user, 'id', 0) or 0)
    if uid in ADMIN_IDS:
        return True
    cfg = _v167_tarot_cfg(chat_id)
    role = str(cfg.get('tarot_ticket_grant_role', 'admins') or 'admins')
    if role == 'members':
        return True
    if role == 'admin_ids':
        return uid in ADMIN_IDS
    if role == 'manual':
        ids = set(int(x) for x in (cfg.get('tarot_ticket_manual_ids') or []) if str(x).strip().lstrip('-').isdigit())
        return uid in ids
    try:
        member = await context.bot.get_chat_member(chat_id, uid)
        if role == 'creator':
            return member.status == 'creator'
        if role == 'admins':
            return member.status in ('administrator', 'creator')
    except Exception:
        return False
    return False


_old_v167_can_play = _v129_can_play

def _v129_can_play(chat_id: int, user_id: int, mode: str) -> tuple[bool, str]:
    cfg = _v167_tarot_cfg(chat_id)

    if _v167_ticket_count(chat_id, user_id, mode) > 0:
        return True, ''

    if bool(cfg.get('tarot_zero_requires_ticket', True)):
        if mode == 'ppf' and int(cfg.get('tarot_ppf_limit', 2) or 0) == 0:
            return False, '🔮 Esta tirada requiere ticket. Pídeselo a un admin.'
        if mode == 'day' and int(cfg.get('tarot_day_limit', 3) or 0) == 0:
            return False, '🔮 Esta tirada requiere ticket. Pídeselo a un admin.'
    return _old_v167_can_play(chat_id, user_id, mode)


_old_v167_inc_usage = _v129_inc_usage

def _v129_inc_usage(chat_id: int, user_id: int, mode: str) -> None:

    if _v167_consume_ticket(chat_id, user_id, mode):
        return
    return _old_v167_inc_usage(chat_id, user_id, mode)


async def _v167_ticket_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /ticket respondiendo a un usuario dentro del grupo.')
        return
    chat_id = int(update.effective_chat.id)
    if not await _v167_can_grant_ticket(context, chat_id, update.effective_user):
        await update.message.reply_text('🔮 No tienes permiso para dar tickets de Tarot.')
        raise _V167Stop
    target = getattr(update.message.reply_to_message, 'from_user', None) if update.message.reply_to_message else None
    if not target or getattr(target, 'is_bot', False):
        await update.message.reply_text('Responde con /ticket al mensaje del usuario al que quieras darle una tirada.')
        raise _V167Stop
    uid = int(target.id)
    txt = f'🔮 Ticket de Tarot para {target.mention_html()}\n\nElige qué tirada podrá hacer:'
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton('☀️ 1 carta', callback_data=f'tkt|{chat_id}|{uid}|day'), InlineKeyboardButton('🕰 Pasado/Presente/Futuro', callback_data=f'tkt|{chat_id}|{uid}|ppf')],
        [InlineKeyboardButton('🎟 Ambas', callback_data=f'tkt|{chat_id}|{uid}|both')],
    ])
    await update.message.reply_html(txt, reply_markup=kb)
    raise _V167Stop


async def _v167_ticket_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('tkt|'):
        return
    parts = q.data.split('|')
    try:
        chat_id = int(parts[1]); target_id = int(parts[2]); mode = parts[3]
    except Exception:
        await q.answer('Ticket inválido.', show_alert=True); raise _V167Stop
    if not await _v167_can_grant_ticket(context, chat_id, q.from_user):
        await q.answer('No tienes permiso para dar tickets.', show_alert=True); raise _V167Stop
    if mode in ('day', 'both'):
        _v167_add_ticket(chat_id, target_id, 'day', 1)
    if mode in ('ppf', 'both'):
        _v167_add_ticket(chat_id, target_id, 'ppf', 1)
    await q.answer('Ticket concedido ✅')
    try:
        await q.edit_message_text('✅ Ticket de Tarot concedido. El usuario podrá hacer la tirada seleccionada.', parse_mode=ParseMode.HTML)
    except Exception:
        pass
    raise _V167Stop


_old_v167_tarot_settings_text = _v132_tarot_settings_text if '_v132_tarot_settings_text' in globals() else admin_private_block_text

