_old_v167_tarot_settings_markup = _v132_tarot_settings_markup if '_v132_tarot_settings_markup' in globals() else None

def _v132_tarot_settings_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_v167_tarot_settings_markup(chat_id) if callable(_old_v167_tarot_settings_markup) else InlineKeyboardMarkup([])
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
