async def _v167_awards_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('awd|'):
        return
    parts = q.data.split('|')
    action = parts[1]
    chat_id = int(parts[2])
    cfg = _v167_awards_cfg(chat_id)
    if action == 'tog':
        key = parts[3]
        cfg[key] = not bool(cfg.get(key, False))
        save_all_states(); await q.answer('Actualizado ✅')
    elif action == 'time':
        target = parts[3]
        cur = str(cfg.get('awards_daily_time' if target=='daily' else 'awards_weekly_time', '23:30'))
        vals = ['12:00','18:00','21:00','23:30','00:30']
        nxt = vals[(vals.index(cur)+1)%len(vals)] if cur in vals else '23:30'
        cfg['awards_daily_time' if target=='daily' else 'awards_weekly_time'] = nxt
        save_all_states(); await q.answer(f'Hora: {nxt}')
    elif action == 'send':
        weekly = len(parts)>3 and parts[3]=='weekly'
        await _v167_send_awards(context, chat_id, weekly=weekly)
        await q.answer('Enviado ✅')
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, 'awards'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'awards'))
    except Exception:
        pass
    raise _V167Stop

_old_build_application_v167 = build_application

def build_application() -> Application:
    app = _old_build_application_v167()
    app.add_handler(CommandHandler(['ticket'], _v167_ticket_command), group=-11100000000)
    app.add_handler(CallbackQueryHandler(_v167_ticket_callback, pattern=r'^tkt\|'), group=-11100000000)
    app.add_handler(CallbackQueryHandler(_v167_tarot_settings_cb, pattern=r'^t167\|'), group=-11100000000)
    app.add_handler(CallbackQueryHandler(_v167_recurrentes_send_now, pattern=r'^cfg\|rec_send\|'), group=-11100000000)
    app.add_handler(CallbackQueryHandler(_v167_awards_callback, pattern=r'^awd\|'), group=-11100000000)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v167_collect_awards_stats), group=1110000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v167_awards_job, interval=60, first=15, name='v167_awards_job')
    except Exception:
        logger.exception('No se pudo iniciar job Premios V167')
    logger.info('V167 tickets Tarot, recurrentes manuales sin tocar horario y premios sociales cargado')
    return app


