def _v168_awards_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v167_awards_cfg(chat_id)
    cfg.setdefault('awards_competidor_enabled', True)
    cfg.setdefault('awards_noctambulo_enabled', True)
    cfg.setdefault('awards_pair_enabled', True)
    cfg.setdefault('awards_parlante_enabled', True)
    cfg.setdefault('awards_holi_enabled', True)
    return cfg


def _v168_hours_label(hours: Any) -> str:
    try:
        hs = sorted(int(x) for x in (hours or {}).keys()) if isinstance(hours, dict) else []
    except Exception:
        hs = []
    if not hs:
        return '0 franjas'
    return f'{len(hs)} franjas ({min(hs):02d}:00-{max(hs):02d}:59)'


def _v168_today_key() -> str:
    try:
        return _v167_stats_day_key()
    except Exception:
        return time.strftime('%Y-%m-%d')


def _v168_week_keys() -> List[str]:
    now = time.time()
    return [_v167_stats_day_key(int(now - i * 86400)) for i in range(7)]


_old_v168_collect_awards_stats = _v167_collect_awards_stats
async def _v167_collect_awards_stats(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _old_v168_collect_awards_stats(update, context)
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
        return
    txt = (update.message.text or update.message.caption or '').strip()
    if not txt:
        return
    chat_id = int(update.effective_chat.id)
    cfg = _v168_awards_cfg(chat_id)
    if not bool(cfg.get('awards_enabled', True)):
        return
    day = _v167_awards_day(chat_id)
    uid = str(int(update.effective_user.id))
    row = day.setdefault('users', {}).setdefault(uid, {'name': _v167_name(update.effective_user), 'messages': 0, 'holas': 0})
    row['name'] = _v167_name(update.effective_user)
    row['username'] = getattr(update.effective_user, 'username', '') or ''
    hours = row.setdefault('hours', {})
    if isinstance(hours, dict):
        try:
            dt = getattr(update.message, 'date', None)
            ts = dt.timestamp() if dt else time.time()
        except Exception:
            ts = time.time()
        hh = time.strftime('%H', time.localtime(ts))
        hours[hh] = int(hours.get(hh, 0) or 0) + 1
    try:
        save_all_states()
    except Exception:
        pass


def _v168_extract_ranking_points(chat_id: int, *, weekly: bool = False) -> Dict[str, Dict[str, Any]]:
    acc: Dict[str, Dict[str, Any]] = {}

    def add(uid: str, name: str, points: int):
        try:
            points = int(points)
        except Exception:
            points = 0
        if not uid or not points:
            return
        row = acc.setdefault(str(uid), {'name': name or str(uid), 'points': 0})
        if name:
            row['name'] = name
        row['points'] = int(row.get('points', 0) or 0) + points

    cfg = admin_cfg(chat_id)
    try:
        hcfg = hot_cfg(chat_id) if 'hot_cfg' in globals() else cfg
        rankings: List[Any] = []
        if weekly:
            wk = _v167_stats_week_key() if '_v167_stats_week_key' in globals() else ''
            rankings.append((hcfg.get('hot_ranking_weekly', {}) or {}).get(wk, {}))
        else:
            dk = _v168_today_key()
            rankings.append((hcfg.get('hot_ranking_daily', {}) or {}).get(dk, {}))
        if not any(bool(x) for x in rankings):
            rankings.append(hcfg.get('hot_ranking', {}) or {})
        for ranking in rankings:
            if isinstance(ranking, dict):
                for uid, row in ranking.items():
                    if isinstance(row, dict):
                        add(str(uid), str(row.get('name') or uid), int(row.get('points', 0) or 0))
    except Exception:
        pass
    try:
        istore = cfg.get('impostor_ranking', {}) or {}
        if isinstance(istore, dict):
            rankings = []
            if weekly:
                wk = _v167_stats_week_key() if '_v167_stats_week_key' in globals() else ''
                rankings.append((istore.get('weekly', {}) or {}).get(wk, {}))
            else:
                dk = _v168_today_key()
                rankings.append((istore.get('daily', {}) or {}).get(dk, {}))
            if not any(bool(x) for x in rankings):
                rankings.append(istore.get('general', {}) or {})
            for ranking in rankings:
                if isinstance(ranking, dict):
                    for uid, row in ranking.items():
                        if isinstance(row, dict):
                            add(str(uid), str(row.get('name') or uid), int(row.get('points', 0) or 0))
    except Exception:
        pass
    return acc


def _v168_awards_calculate(chat_id: int, *, weekly: bool = False) -> str:
    cfg = _v168_awards_cfg(chat_id)
    stats = cfg.setdefault('awards_stats', {})
    days = _v168_week_keys() if weekly else [_v168_today_key()]
    users_acc: Dict[str, Dict[str, Any]] = {}
    pair_acc: Dict[str, Dict[str, Any]] = {}
    for dk in days:
        day = stats.get(dk, {}) or {}
        for uid, row in (day.get('users', {}) or {}).items():
            dst = users_acc.setdefault(uid, {'name': row.get('name') or uid, 'messages': 0, 'holas': 0, 'hours': {}})
            dst['name'] = row.get('name') or dst['name']
            dst['messages'] += int(row.get('messages', 0) or 0)
            dst['holas'] += int(row.get('holas', 0) or 0)
            for hh, c in (row.get('hours', {}) or {}).items():
                dst.setdefault('hours', {})[str(hh)] = int(dst.setdefault('hours', {}).get(str(hh), 0) or 0) + int(c or 0)
        for pk, row in (day.get('pairs', {}) or {}).items():
            dst = pair_acc.setdefault(pk, {'count': 0, 'names': {}})
            dst['count'] += int(row.get('count', 0) or 0)
            dst['names'].update(row.get('names') or {})

    title = '🏆 <b>PREMIOS DE LA SEMANA</b>' if weekly else '🏆 <b>PREMIOS DEL DÍA</b>'
    suffix = 'semana' if weekly else 'día'
    lines = [title, '']
    if bool(cfg.get('awards_pair_enabled', True)):
        if pair_acc:
            pk, pr = max(pair_acc.items(), key=lambda kv: kv[1].get('count', 0))
            a, b = pk.split(':') if ':' in pk else (pk, '')
            n1 = pr.get('names', {}).get(a, a); n2 = pr.get('names', {}).get(b, b)
            lines.append(f'💞 <b>Pareja del {suffix}</b>: {h(n1)} + {h(n2)} · <b>{int(pr.get("count", 0))}</b> interacciones')
        else:
            lines.append(f'💞 <b>Pareja del {suffix}</b>: todavía sin datos suficientes')
    if bool(cfg.get('awards_parlante_enabled', True)):
        if users_acc:
            uid, ur = max(users_acc.items(), key=lambda kv: kv[1].get('messages', 0))
            lines.append(f'🗣 <b>Más parlante</b>: {h(ur.get("name") or uid)} · <b>{int(ur.get("messages", 0))}</b> mensajes')
        else:
            lines.append('🗣 <b>Más parlante</b>: sin datos')
    if bool(cfg.get('awards_holi_enabled', True)):
        if users_acc:
            uid2, uh = max(users_acc.items(), key=lambda kv: kv[1].get('holas', 0))
            if int(uh.get('holas', 0)) > 0:
                lines.append(f'👋 <b>Holi holi</b>: {h(uh.get("name") or uid2)} · <b>{int(uh.get("holas", 0))}</b> holas')
            else:
                lines.append('👋 <b>Holi holi</b>: nadie saludó lo suficiente todavía')
        else:
            lines.append('👋 <b>Holi holi</b>: sin datos')
    if bool(cfg.get('awards_noctambulo_enabled', True)):
        if users_acc:
            uid3, un = max(users_acc.items(), key=lambda kv: (len((kv[1].get('hours') or {}).keys()), kv[1].get('messages', 0)))
            lines.append(f'🌙 <b>Noctámbulo</b>: {h(un.get("name") or uid3)} · <b>{_v168_hours_label(un.get("hours") or {})}</b>')
        else:
            lines.append('🌙 <b>Noctámbulo</b>: sin datos')
    if bool(cfg.get('awards_competidor_enabled', True)):
        comp = _v168_extract_ranking_points(chat_id, weekly=weekly)
        if comp:
            uid4, cr = max(comp.items(), key=lambda kv: kv[1].get('points', 0))
            if int(cr.get('points', 0) or 0) > 0:
                lines.append(f'🎮 <b>Más competidor</b>: {h(cr.get("name") or uid4)} · <b>{int(cr.get("points", 0))}</b> puntos')
            else:
                lines.append('🎮 <b>Más competidor</b>: todavía sin puntos de juegos')
        else:
            lines.append('🎮 <b>Más competidor</b>: todavía sin rankings de juegos')
    return '\n'.join(lines)


def _v167_awards_calculate(chat_id: int, *, weekly: bool = False) -> str:
    return _v168_awards_calculate(chat_id, weekly=weekly)

async def _v167_send_awards(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, weekly: bool = False) -> None:
    await context.bot.send_message(chat_id, _v168_awards_calculate(chat_id, weekly=weekly), parse_mode=ParseMode.HTML)


