async def _v168_awards_block_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|block|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 4 or parts[3] != 'awards':
        return
    try:
        chat_id = int(parts[2])
        await q.answer()
        await q.edit_message_text(admin_private_block_text(chat_id, 'awards'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'awards'))
    except Exception:
        logger.exception('Error abriendo Premios sociales V168')
        try:
            await q.answer('Error abriendo premios. Mira logs.', show_alert=True)
        except Exception:
            pass
    raise _V168Stop


