    markup = _old_v168_main_markup(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    clean_rows = []
    for row in rows:
        new_row = [b for b in row if not ((getattr(b, 'callback_data', '') or '').endswith('|awards') or (getattr(b, 'text', '') or '') == '🏆 Premios sociales')]
        if new_row:
            clean_rows.append(new_row)
    clean_rows.insert(max(1, len(clean_rows) - 2), [InlineKeyboardButton('🏆 Premios sociales', callback_data=f'cfg|block|{chat_id}|awards')])
    return InlineKeyboardMarkup(clean_rows)


