def admin_block_icon(chat_id: int, block: str) -> str:
    if block == 'daily_phrase':
        return cfg_status(cfg_value(chat_id, 'daily_phrase_enabled', False))
    if block == 'recurrentes':
        try:
            rows = recurring_list(chat_id)
            return '✅' if any(bool(r.get('enabled', True)) for r in rows) else ('⚫' if rows else '❌')
        except Exception:
            return '❌'
    if block == 'awards':
        return cfg_status(_v168_awards_cfg(chat_id).get('awards_enabled', True) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id).get('awards_enabled', True))
    return _old_v170_admin_block_icon(chat_id, block)


def _v170_ai_stats(chat_id: int) -> tuple[int, int]:
    cfg = admin_cfg(chat_id)
    cmds = cfg.get('ai_custom_commands', {}) or cfg.get('cerebrito_ai_commands', {}) or {}
    active = 0; blocked = 0
    if isinstance(cmds, dict):
        for _k, v in cmds.items():
            if isinstance(v, dict):
                if bool(v.get('enabled', True)):
                    active += 1
                else:
                    blocked += 1
    return active, blocked


def _v170_hot_auto_summary(chat_id: int) -> str:
    try:
        cfg = hot_cfg(chat_id) if 'hot_cfg' in globals() else admin_cfg(chat_id)
        if not bool(cfg.get('hot_auto_enabled', False)):
            return 'OFF'
        level = cfg.get('hot_auto_level', cfg.get('auto_level', ''))
        sec = cfg.get('hot_auto_interval_seconds', cfg.get('auto_interval_seconds', ''))
        return f'Nivel {h(str(level or "?"))} · {h(str(sec or "?"))}s'
    except Exception:
        return 'OFF'


