def _v170_phrase_text(chat_id: int, now_ts: Optional[int] = None) -> str:
    title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')
    phrase = daily_phrase_for_date_v15(now_ts or int(time.time()))
    return f'<b>{h(title)}</b>\n\n<b><i>“{h(phrase)}”</i></b>'


async def _v170_send_daily_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> Optional[int]:
    cfg = admin_cfg(chat_id)
    now_ts = int(now_ts or time.time())
    day_key = _local_day_key_v15(now_ts) if '_local_day_key_v15' in globals() else time.strftime('%Y-%m-%d', time.localtime(now_ts))
    if not force:
        if not bool(cfg.get('daily_phrase_enabled', False)):
            return None
        if cfg.get('daily_phrase_last_key') == day_key:
            return None
    msg = await bot.send_message(chat_id, _v170_phrase_text(chat_id, now_ts), parse_mode=ParseMode.HTML)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    if bool(cfg.get('daily_phrase_pin', False)):
        try:
            await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
        except Exception:
            pass
    cfg['daily_phrase_last_key'] = day_key
    cfg['daily_phrase_last_sent_ts'] = now_ts
    cfg['daily_phrase_sending_key'] = ''
    save_all_states()
    return int(msg.message_id)


async def daily_phrase_maybe_send(application: Application, chat_id: int, now_ts: int) -> None:
    if not daily_phrase_due(chat_id, now_ts):
        return
    try:
        await _v170_send_daily_phrase(application.bot, chat_id, now_ts=now_ts, force=False)
    except Exception:
        logger.exception('V170 no pudo enviar frase del día chat %s', chat_id)
        raise


async def _v170_phrase_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        return
    if action == 'phrase_send':
        try:
            await _v170_send_daily_phrase(context.bot, chat_id, force=True)
            await q.answer('Frase enviada ✅')
        except Exception:
            logger.exception('V170 frase enviar ahora falló')
            await q.answer('No pude enviar la frase. Mira logs.', show_alert=True)
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        except Exception:
            pass
        raise _V170Stop


def _v170_chat_ids() -> List[int]:
    ids = set()
    try:
        ids.update(int(x) for x in STATE_CACHE.keys())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in PRIVATE_GROUPS.keys())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in (STATE.get('admin_cfg', {}) or {}).keys())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in known_admin_chats_for_private())
    except Exception:
        pass
    return sorted(ids)


async def _v170_send_recurring_manual(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    tmp = copy.deepcopy(row)

    before = copy.deepcopy(row)
    mid = await send_recurring_message(context, chat_id, tmp)

    for k in ('last_sent_ts','last_day','last_week_key','last_date_key','enabled','schedule','schedule_label'):
        if k in before:
            row[k] = before[k]
        else:
            row.pop(k, None)
    save_all_states()
    return mid


async def _v170_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    now_dt = _local_dt_v15(now) if '_local_dt_v15' in globals() else datetime.datetime.now()
    for chat_id in _v170_chat_ids():
        try:
            await daily_phrase_maybe_send(context.application, chat_id, now)
        except Exception:
            logger.exception('V170 scheduler frase falló chat %s', chat_id)
        try:
            for row in list(recurring_list(chat_id)):
                if recurring_due(row, now):
                    sent_id = await send_recurring_message(context, chat_id, row)
                    if sent_id:
                        row['last_sent_ts'] = now
                        stype = (row.get('schedule') or {}).get('type')
                        if stype == 'daily':
                            row['last_day'] = now_dt.strftime('%Y-%m-%d')
                        elif stype == 'weekly':
                            row['last_week_key'] = f"{now_dt.strftime('%G-%V')}-{now_dt.weekday()}"
                        elif stype == 'date':
                            row['last_date_key'] = str((row.get('schedule') or {}).get('date', now_dt.strftime('%Y-%m-%d')))
                            row['enabled'] = False
                        save_all_states()
                        await asyncio.sleep(0.4)
        except Exception:
            logger.exception('V170 scheduler recurrentes falló chat %s', chat_id)


async def _v170_recurring_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rec_'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        return
    cfg = admin_cfg(chat_id)
    if action == 'rec_send':
        rid = int(parts[3])
        row = recurring_find(chat_id, rid)
        if not row:
            await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V170Stop
        try:
            await _v170_send_recurring_manual(context, chat_id, row)
            await q.answer('Enviado ✅')
        except Exception:
            logger.exception('V170 enviar recurrente manual falló')
            await q.answer('No pude enviarlo. Mira logs.', show_alert=True)
        raise _V170Stop
    if action == 'rec_sel':
        rid = int(parts[3])
        sel = cfg.setdefault('rec_block_selection', [])
        rid_s = str(rid)
        if rid_s in sel:
            sel.remove(rid_s)
        else:
            sel.append(rid_s)
        save_all_states()
        await q.answer('Selección actualizada')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'recurrentes'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'recurrentes'))
        except Exception:
            pass
        raise _V170Stop
    if action == 'rec_block_send':
        sel = [int(x) for x in cfg.setdefault('rec_block_selection', []) if str(x).isdigit()]
        if not sel:
            await q.answer('No hay recurrentes seleccionados.', show_alert=True); raise _V170Stop
        ok = 0
        for rid in sel:
            row = recurring_find(chat_id, rid)
            if row:
                try:
                    mid = await _v170_send_recurring_manual(context, chat_id, row)
                    ok += 1 if mid else 0
                    await asyncio.sleep(0.4)
                except Exception:
                    logger.exception('V170 bloque recurrente %s falló', rid)
        await q.answer(f'Bloque enviado: {ok}/{len(sel)} ✅', show_alert=True)
        raise _V170Stop
    if action == 'rec_block_clear':
        cfg['rec_block_selection'] = []
        save_all_states()
        await q.answer('Selección limpia')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'recurrentes'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'recurrentes'))
        except Exception:
            pass
        raise _V170Stop


_old_v170_admin_private_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == 'recurrentes':
        rows = recurring_list(chat_id)
        sel = admin_cfg(chat_id).setdefault('rec_block_selection', [])
        text = _old_v170_admin_private_block_text(chat_id, block, page)
        text += f'\n\n<b>📦 Bloque manual:</b> <b>{len(sel)}</b> seleccionados. Marca varios y pulsa enviar bloque.'
        return text
    if block == 'awards':
        cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
        base = _old_v170_admin_private_block_text(chat_id, block, page)
        base += f"\n😂 Más se ríe: <b>{'ON' if cfg.get('awards_risas_enabled', True) else 'OFF'}</b>"
        return base
    return _old_v170_admin_private_block_text(chat_id, block, page)


_old_v170_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    if block == 'recurrentes':
        markup = _old_v170_admin_private_block_markup(chat_id, block, page)
        rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
        sel = set(str(x) for x in admin_cfg(chat_id).setdefault('rec_block_selection', []))

        out = []
        for r in rows:
            out.append(r)
            try:
                for b in r:
                    cb = getattr(b, 'callback_data', '') or ''
                    if cb.startswith(f'cfg|rec_edit|{chat_id}|'):
                        rid = cb.split('|')[3]
                        mark = '✅' if rid in sel else '⬜'
                        out.append([InlineKeyboardButton(f'{mark} Seleccionar #{rid} para bloque', callback_data=f'cfg|rec_sel|{chat_id}|{rid}|recurrentes')])
                        break
            except Exception:
                pass
        insert_at = max(0, len(out)-1)
        out.insert(insert_at, [InlineKeyboardButton('📦 Enviar bloque seleccionado', callback_data=f'cfg|rec_block_send|{chat_id}|recurrentes'), InlineKeyboardButton('🧹 Limpiar selección', callback_data=f'cfg|rec_block_clear|{chat_id}|recurrentes')])
        return InlineKeyboardMarkup(out)
    if block == 'awards':
        markup = _old_v170_admin_private_block_markup(chat_id, block, page)
        rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
        cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
        insert_at = max(0, len(rows)-2)
        rows.insert(insert_at, [InlineKeyboardButton(f"😂 Risas {'ON' if cfg.get('awards_risas_enabled', True) else 'OFF'}", callback_data=f'awd|tog|{chat_id}|awards_risas_enabled')])
        return InlineKeyboardMarkup(rows)
    return _old_v170_admin_private_block_markup(chat_id, block, page)


def _v170_risa_count(txt: str) -> int:
    t = (txt or '').lower()
    return t.count('jaja') + t.count('ja ja') + t.count('😂') + t.count('🤣') + t.count('😆')


_old_v170_collect_awards_stats = _v167_collect_awards_stats if '_v167_collect_awards_stats' in globals() else None
async def _v167_collect_awards_stats(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if callable(_old_v170_collect_awards_stats):
        await _old_v170_collect_awards_stats(update, context)
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
        return
    txt = (update.message.text or update.message.caption or '').strip()
    if not txt:
        return
    chat_id = int(update.effective_chat.id)
    day = _v167_awards_day(chat_id) if '_v167_awards_day' in globals() else admin_cfg(chat_id).setdefault('awards_stats', {}).setdefault(time.strftime('%Y-%m-%d'), {'users': {}, 'pairs': {}})
    uid = str(int(update.effective_user.id))
    row = day.setdefault('users', {}).setdefault(uid, {'name': display_name(update.effective_user), 'messages': 0, 'holas': 0})
    row['name'] = display_name(update.effective_user)
    row['risas'] = int(row.get('risas', 0) or 0) + _v170_risa_count(txt)
    save_all_states()


_old_v170_awards_calculate = _v167_awards_calculate if '_v167_awards_calculate' in globals() else None

def _v167_awards_calculate(chat_id: int, *, weekly: bool = False) -> str:
    base = _old_v170_awards_calculate(chat_id, weekly=weekly) if callable(_old_v170_awards_calculate) else '🏆 <b>PREMIOS</b>'
    cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
    if not bool(cfg.get('awards_risas_enabled', True)):
        return base
    try:
        days = _v168_week_keys() if weekly and '_v168_week_keys' in globals() else [_v168_today_key() if '_v168_today_key' in globals() else time.strftime('%Y-%m-%d')]
        acc: Dict[str, Dict[str, Any]] = {}
        stats = cfg.setdefault('awards_stats', {})
        for dk in days:
            for uid, row in (stats.get(dk, {}) or {}).get('users', {}).items():
                dst = acc.setdefault(uid, {'name': row.get('name') or uid, 'risas': 0})
                dst['name'] = row.get('name') or dst['name']
                dst['risas'] += int(row.get('risas', 0) or 0)
        if acc:
            uid, row = max(acc.items(), key=lambda kv: kv[1].get('risas', 0))
            if int(row.get('risas', 0) or 0) > 0:
                base += f'\n😂 <b>El que más se ríe</b>: {h(row.get("name") or uid)} · <b>{int(row.get("risas",0))}</b> risas'
            else:
                base += '\n😂 <b>El que más se ríe</b>: todavía sin risas suficientes'
        else:
            base += '\n😂 <b>El que más se ríe</b>: sin datos'
    except Exception:
        logger.exception('Error calculando premio risas V170')
    return base


async def _v170_awards_send(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, weekly: bool=False) -> None:
    await context.bot.send_message(chat_id, _v167_awards_calculate(chat_id, weekly=weekly), parse_mode=ParseMode.HTML)


_old_build_application_v170 = build_application

def build_application() -> Application:
    app = _old_build_application_v170()
    app.add_handler(CallbackQueryHandler(_v170_phrase_callback, pattern=r'^cfg\|phrase_send\|'), group=-11300000000)
    app.add_handler(CallbackQueryHandler(_v170_recurring_router, pattern=r'^cfg\|rec_(send|sel|block_send|block_clear)\|'), group=-11300000000)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v167_collect_awards_stats), group=1130000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v170_scheduler_tick, interval=60, first=10, name='v170_scheduler_tick')
    except Exception:
        logger.exception('No se pudo iniciar scheduler V170')
    logger.info('V170 scheduler frase/recurrentes, bloques recurrentes, menú resumido y premio risas cargado')
    return app


