def _v171_panel_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    pcfg = cfg.setdefault('panel_config_v171', _v171_default_panel_cfg(chat_id))
    if not isinstance(pcfg, dict):
        pcfg = _v171_default_panel_cfg(chat_id)
        cfg['panel_config_v171'] = pcfg
    pcfg.setdefault('top_fields', ['grupo', 'validation', 'recurrentes', 'ia', 'pending', 'daily_phrase', 'awards'])
    pcfg.setdefault('blocks', _v171_default_panel_cfg(chat_id)['blocks'])
    pcfg.setdefault('show_group_before_change', True)

    defs = _v171_available_panel_items()
    used = set()
    for b in pcfg.get('blocks', []) or []:
        items = []
        for it in b.get('items', []) or []:
            if it in defs and it not in used:
                items.append(it); used.add(it)
        b['items'] = items
        b.setdefault('title', 'Bloque')
        b.setdefault('id', 'block')

    missing = [k for k in defs.keys() if k not in used and k not in ('change_group',)]
    control = None
    for b in pcfg['blocks']:
        if b.get('id') == 'control':
            control = b; break
    if control is None:
        control = {'id': 'control', 'title': '🧰 Control', 'items': []}
        pcfg['blocks'].append(control)
    for k in missing:
        if k not in control['items']:
            control['items'].append(k)
    return pcfg


def _v171_field_value(chat_id: int, key: str) -> str:
    title = str(cfg_value(chat_id, 'chat_title', '') or chat_id)
    state = get_state(chat_id)
    try:
        pending_count = sum(1 for r in state.validation_users.values() if r.get('status') in ('answering', 'pending_admin', 'timeout'))
    except Exception:
        pending_count = 0
    try:
        recs = recurring_list(chat_id); rec_on = sum(1 for r in recs if bool(r.get('enabled', True)))
    except Exception:
        recs = []; rec_on = 0
    ai_on, ai_off = _v170_ai_stats(chat_id) if '_v170_ai_stats' in globals() else (0,0)
    awards_time = str((_v168_awards_cfg(chat_id).get('awards_daily_time', '23:30') if '_v168_awards_cfg' in globals() else admin_cfg(chat_id).get('awards_daily_time', '23:30')))
    vals = {
        'grupo': f'📍 Grupo: <b>{h(title)}</b>',
        'validation': f'🛡 Validación: <b>{bool_label(cfg_value(chat_id, "validation_enabled", False))}</b>',
        'pending': f'👥 Pendientes: <b>{pending_count}</b>',
        'recurrentes': f'🔁 Recurrentes: <b>{rec_on}/{len(recs)}</b>',
        'ia': f'🧠 IA: <b>{ai_on} ON</b> · <b>{ai_off} OFF</b>',
        'daily_phrase': f'🌞 Frase: <b>{bool_label(cfg_value(chat_id, "daily_phrase_enabled", False))}</b> · {h(str(cfg_value(chat_id, "daily_phrase_time", "10:00")))}',
        'hot': f'❓ Preguntitas: <b>{_v170_hot_auto_summary(chat_id) if "_v170_hot_auto_summary" in globals() else "OFF"}</b>',
        'awards': f'🏆 Premios: <b>{h(awards_time)}</b>',
        'dj': f'🎧 DJ: <b>{bool_label(bool(get_state(chat_id).dj_mode))}</b>',
        'tarot': f'🔮 Tarot: <b>{bool_label(bool((_v129_tarot_cfg(chat_id) if "_v129_tarot_cfg" in globals() else {}).get("tarot_enabled", True)))}</b>',
    }
    return vals.get(key, '')


def _v171_top_fields_available() -> Dict[str, str]:
    return {
        'grupo': '📍 Grupo actual', 'validation': '🛡 Validación', 'pending': '👥 Pendientes',
        'recurrentes': '🔁 Recurrentes', 'ia': '🧠 IA', 'daily_phrase': '🌞 Frase día',
        'hot': '❓ Preguntitas', 'awards': '🏆 Premios', 'dj': '🎧 DJ', 'tarot': '🔮 Tarot'
    }


def admin_private_main_text(chat_id: int) -> str:
    pcfg = _v171_panel_cfg(chat_id)
    lines = ['<b>⚙️ PLAN DE AJUSTES</b>']
    fields = pcfg.get('top_fields', []) or []
    if fields:
        lines.append('')
        for k in fields:
            v = _v171_field_value(chat_id, k)
            if v:
                lines.append(v)
    lines.append('\nConfigura el panel desde <b>⚙️ Configuración del panel</b>.')
    return '\n'.join(lines)


def _v171_item_button(chat_id: int, key: str) -> InlineKeyboardButton:
    d = _v171_available_panel_items().get(key, {'label': key, 'cb': f'cfg|block|{{chat_id}}|{key}'})
    label = d['label']
    try:

        if key not in ('export','checkbot','reload','save','close','change_group'):
            label = block_label(chat_id, key, label)
    except Exception:
        pass
    return InlineKeyboardButton(label, callback_data=d['cb'].format(chat_id=chat_id))


def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v171_panel_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    for block in pcfg.get('blocks', []) or []:
        title = str(block.get('title') or '').strip()
        if title:
            rows.append([InlineKeyboardButton(title[:60], callback_data=f'cfg|panel_noop|{chat_id}|{block.get("id","b")}')])
        items = [i for i in (block.get('items') or []) if i in _v171_available_panel_items()]
        pair: List[InlineKeyboardButton] = []
        for it in items:

            pair.append(_v171_item_button(chat_id, it))
            if len(pair) == 2:
                rows.append(pair); pair = []
        if pair:
            rows.append(pair)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}')])
    if bool(pcfg.get('show_group_before_change', True)):
        title = str(cfg_value(chat_id, 'chat_title', '') or chat_id)
        rows.append([InlineKeyboardButton(f'📍 GRUPO ACTUAL · {truncated_button_title(title, 35)}', callback_data=f'cfg|open|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Cambiar grupo', callback_data='cfg|list')])
    return InlineKeyboardMarkup(rows)


def _v171_panelcfg_text(chat_id: int) -> str:
    pcfg = _v171_panel_cfg(chat_id)
    fields = _v171_top_fields_available()
    top = ', '.join(fields.get(x, x) for x in pcfg.get('top_fields', [])) or 'Nada'
    lines = ['<b>⚙️ Configuración del panel de ajustes</b>', '', f'<b>Resumen superior:</b> {h(top)}', '', '<b>Bloques actuales:</b>']
    for idx, b in enumerate(pcfg.get('blocks', []) or [], start=1):
        items = ', '.join((_v171_available_panel_items().get(i, {}).get('label', i)) for i in b.get('items', [])) or 'vacío'
        lines.append(f'{idx}. <b>{h(str(b.get("title","Bloque")))}</b> · {h(items)}')
    lines.append('\nDesde aquí puedes mover botones entre bloques, activar datos del resumen y resetear el panel.')
    return '\n'.join(lines)


