def _v171_panel_blocks_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v171_panel_cfg(chat_id)
    rows = []
    for bi, b in enumerate(pcfg.get('blocks', []) or []):
        rows.append([InlineKeyboardButton(f'🧩 {b.get("title","Bloque")}', callback_data=f'panelcfg|block|{chat_id}|{bi}')])
