def _v171_panel_block_text(chat_id: int, bi: int) -> str:
    pcfg = _v171_panel_cfg(chat_id); blocks = pcfg.get('blocks', []) or []
    if bi < 0 or bi >= len(blocks): return 'Bloque no válido'
    b = blocks[bi]
    items = b.get('items', []) or []
    defs = _v171_available_panel_items()
    lines = [f'<b>{h(str(b.get("title","Bloque")))}</b>', '', 'Botones dentro de este bloque:']
    for it in items:
        lines.append('• ' + h(defs.get(it, {}).get('label', it)))
    lines.append('\nPulsa un botón para meterlo/quitarlo de este bloque. Si lo metes aquí, sale de otro bloque.')
    return '\n'.join(lines)


def _v171_panel_block_markup(chat_id: int, bi: int) -> InlineKeyboardMarkup:
    pcfg = _v171_panel_cfg(chat_id); blocks = pcfg.get('blocks', []) or []
    defs = _v171_available_panel_items(); rows = []
    current = set(blocks[bi].get('items', []) if 0 <= bi < len(blocks) else [])
    pair = []
    for key, d in defs.items():
        if key == 'change_group': continue
        mark = '✅' if key in current else '⬜'
        pair.append(InlineKeyboardButton(f'{mark} {d["label"]}', callback_data=f'panelcfg|toggleitem|{chat_id}|{bi}|{key}'))
        if len(pair) == 2:
            rows.append(pair); pair=[]
    if pair: rows.append(pair)
    rows.append([InlineKeyboardButton('⬆️ Subir bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|up'), InlineKeyboardButton('⬇️ Bajar bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|down')])
    rows.append([InlineKeyboardButton('🗑 Quitar bloque', callback_data=f'panelcfg|delblock|{chat_id}|{bi}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'panelcfg|blocks|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v171_panel_top_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v171_panel_cfg(chat_id); active = set(pcfg.get('top_fields', []) or [])
    rows=[]; pair=[]
    for k,lbl in _v171_top_fields_available().items():
        pair.append(InlineKeyboardButton(f'{"✅" if k in active else "⬜"} {lbl}', callback_data=f'panelcfg|top_toggle|{chat_id}|{k}'))
        if len(pair)==2: rows.append(pair); pair=[]
    if pair: rows.append(pair)
    rows.append([InlineKeyboardButton('🔙 Panel', callback_data=f'panelcfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v171_panel_config_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|'):
        return
    parts = q.data.split('|'); action = parts[1]
    chat_id = int(parts[2]) if len(parts) > 2 and str(parts[2]).lstrip('-').isdigit() else int(update.effective_chat.id)
    pcfg = _v171_panel_cfg(chat_id)
    try:
        if action == 'open':
            await q.answer(); await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_panelcfg_markup(chat_id)); raise _V171Stop
        if action == 'blocks':
            await q.answer(); await q.edit_message_text('<b>🧩 Bloques del panel</b>\n\nElige un bloque para mover botones dentro/fuera.', parse_mode=ParseMode.HTML, reply_markup=_v171_panel_blocks_markup(chat_id)); raise _V171Stop
        if action == 'block':
            bi = int(parts[3]); await q.answer(); await q.edit_message_text(_v171_panel_block_text(chat_id, bi), parse_mode=ParseMode.HTML, reply_markup=_v171_panel_block_markup(chat_id, bi)); raise _V171Stop
        if action == 'toggleitem':
            bi = int(parts[3]); key = parts[4]
            blocks = pcfg.get('blocks', []) or []
            if 0 <= bi < len(blocks):

                for b in blocks:
                    if key in (b.get('items') or []): b['items'] = [x for x in b.get('items', []) if x != key]
                if key not in blocks[bi].get('items', []): blocks[bi].setdefault('items', []).append(key)
                save_all_states()
            await q.answer('Actualizado'); await q.edit_message_text(_v171_panel_block_text(chat_id, bi), parse_mode=ParseMode.HTML, reply_markup=_v171_panel_block_markup(chat_id, bi)); raise _V171Stop
        if action == 'moveblock':
            bi = int(parts[3]); direction = parts[4]; blocks = pcfg.get('blocks', []) or []
            ni = bi-1 if direction=='up' else bi+1
            if 0 <= bi < len(blocks) and 0 <= ni < len(blocks):
                blocks[bi], blocks[ni] = blocks[ni], blocks[bi]; save_all_states(); bi = ni
            await q.answer('Movido'); await q.edit_message_text('<b>🧩 Bloques del panel</b>', parse_mode=ParseMode.HTML, reply_markup=_v171_panel_blocks_markup(chat_id)); raise _V171Stop
        if action == 'delblock':
            bi = int(parts[3]); blocks = pcfg.get('blocks', []) or []
            if len(blocks) > 1 and 0 <= bi < len(blocks):
                removed = blocks.pop(bi)

                blocks[0].setdefault('items', []).extend(removed.get('items', [])); save_all_states()
            await q.answer('Bloque quitado'); await q.edit_message_text('<b>🧩 Bloques del panel</b>', parse_mode=ParseMode.HTML, reply_markup=_v171_panel_blocks_markup(chat_id)); raise _V171Stop
        if action == 'addblock':
            n = len(pcfg.get('blocks', [])) + 1
            pcfg.setdefault('blocks', []).append({'id': f'custom{n}', 'title': f'📦 Bloque {n}', 'items': []}); save_all_states()
            await q.answer('Bloque añadido'); await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_panelcfg_markup(chat_id)); raise _V171Stop
        if action == 'reset':
            admin_cfg(chat_id)['panel_config_v171'] = _v171_default_panel_cfg(chat_id); save_all_states()
            await q.answer('Panel reseteado'); await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_panelcfg_markup(chat_id)); raise _V171Stop
        if action == 'top':
            await q.answer(); await q.edit_message_text('<b>🔝 Resumen superior configurable</b>\n\nMarca qué datos quieres ver arriba del panel.', parse_mode=ParseMode.HTML, reply_markup=_v171_panel_top_markup(chat_id)); raise _V171Stop
        if action == 'top_toggle':
            key = parts[3]; arr = pcfg.setdefault('top_fields', [])
            if key in arr: arr.remove(key)
            else: arr.append(key)
            save_all_states(); await q.answer('Actualizado'); await q.edit_message_text('<b>🔝 Resumen superior configurable</b>', parse_mode=ParseMode.HTML, reply_markup=_v171_panel_top_markup(chat_id)); raise _V171Stop
    except _V171Stop:
        raise
    except Exception:
        logger.exception('Error panel config V171: %s', q.data)
        try: await q.answer('Error panel. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V171Stop


def _v171_rec_blocks(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    blocks = cfg.setdefault('recurring_blocks_v171', [])
    if not isinstance(blocks, list):
        blocks = []; cfg['recurring_blocks_v171'] = blocks
    return blocks


def _v171_next_rec_block_id(chat_id: int) -> int:
    ids = [int(b.get('id',0) or 0) for b in _v171_rec_blocks(chat_id)]
    return (max(ids) + 1) if ids else 1


def _v171_rec_blocks_text(chat_id: int) -> str:
    blocks = _v171_rec_blocks(chat_id)
    lines = ['<b>📦 Bloques de recurrentes</b>', '', 'Crea bloques para lanzar varios recurrentes juntos cuando quieras.']
    if not blocks:
        lines.append('\nNo hay bloques todavía.')
    else:
        for b in blocks:
            lines.append(f"\n<b>#{b.get('id')}</b> {h(str(b.get('name','Bloque')))} · <b>{len(b.get('items',[]) or [])}</b> recurrentes")
    return '\n'.join(lines)


def _v171_rec_blocks_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows=[]
    for b in _v171_rec_blocks(chat_id):
        rows.append([InlineKeyboardButton(f"📦 #{b.get('id')} · {truncated_button_title(str(b.get('name','Bloque')), 35)}", callback_data=f'cfg|rblk_open|{chat_id}|{b.get("id")}')])
    rows.append([InlineKeyboardButton('➕ Crear bloque recurrente', callback_data=f'cfg|rblk_new|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Recurrentes', callback_data=f'cfg|block|{chat_id}|recurrentes')])
    return InlineKeyboardMarkup(rows)


def _v171_rec_block_find(chat_id: int, bid: int) -> Optional[Dict[str, Any]]:
    for b in _v171_rec_blocks(chat_id):
        if int(b.get('id',0) or 0) == int(bid): return b
    return None


def _v171_rec_block_text(chat_id: int, bid: int) -> str:
    b = _v171_rec_block_find(chat_id, bid) or {'name':'Bloque','items':[]}
    lines = [f"<b>📦 {h(str(b.get('name','Bloque')))}</b>", '', 'Recurrentes dentro:']
    items = [int(x) for x in (b.get('items') or []) if str(x).isdigit()]
    if not items: lines.append('Sin recurrentes todavía.')
    for rid in items:
        row = recurring_find(chat_id, rid)
        lines.append(f"• #{rid} · {h(str((row or {}).get('name') or (row or {}).get('title') or 'Recurrente'))}")
    return '\n'.join(lines)


def _v171_rec_block_markup(chat_id: int, bid: int) -> InlineKeyboardMarkup:
    b = _v171_rec_block_find(chat_id, bid) or {'items':[]}
    current = set(str(x) for x in (b.get('items') or []))
    rows = [[InlineKeyboardButton('▶️ Lanzar este bloque', callback_data=f'cfg|rblk_send|{chat_id}|{bid}')]]
    for row in recurring_list(chat_id):
        rid = str(row.get('id'))
        mark = '✅' if rid in current else '⬜'
        name = str(row.get('name') or row.get('title') or f'Recurrente {rid}')
        rows.append([InlineKeyboardButton(f'{mark} #{rid} · {truncated_button_title(name, 38)}', callback_data=f'cfg|rblk_toggle|{chat_id}|{bid}|{rid}')])
    rows.append([InlineKeyboardButton('🗑 Borrar bloque', callback_data=f'cfg|rblk_del|{chat_id}|{bid}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'cfg|rblk_list|{chat_id}')])
    return InlineKeyboardMarkup(rows)


_old_v171_admin_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == 'recurrentes':
        base = _old_v171_admin_block_text(chat_id, block, page)
        base += f"\n\n<b>📦 Bloques guardados:</b> <b>{len(_v171_rec_blocks(chat_id))}</b>"
        return base
    return _old_v171_admin_block_text(chat_id, block, page)

_old_v171_admin_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    if block == 'recurrentes':
        markup = _old_v171_admin_block_markup(chat_id, block, page)
        rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('📦 Bloques de recurrentes', callback_data=f'cfg|rblk_list|{chat_id}')])
        return InlineKeyboardMarkup(rows)
    return _old_v171_admin_block_markup(chat_id, block, page)


async def _v171_rec_blocks_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rblk_'):
        return
    parts = q.data.split('|'); action = parts[1]
    chat_id = int(parts[2])
    try:
        if action == 'rblk_list':
            await q.answer(); await q.edit_message_text(_v171_rec_blocks_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_blocks_markup(chat_id)); raise _V171Stop
        if action == 'rblk_new':
            bid = _v171_next_rec_block_id(chat_id)
            _v171_rec_blocks(chat_id).append({'id': bid, 'name': f'Bloque {bid}', 'items': []}); save_all_states()
            await q.answer('Bloque creado'); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V171Stop
        if action == 'rblk_open':
            bid = int(parts[3]); await q.answer(); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V171Stop
        if action == 'rblk_toggle':
            bid = int(parts[3]); rid = str(parts[4]); b = _v171_rec_block_find(chat_id, bid)
            if b:
                items = [str(x) for x in b.setdefault('items', [])]
                if rid in items: items.remove(rid)
                else: items.append(rid)
                b['items'] = items; save_all_states()
            await q.answer('Actualizado'); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V171Stop
        if action == 'rblk_send':
            bid = int(parts[3]); b = _v171_rec_block_find(chat_id, bid)
            if not b: await q.answer('Bloque no encontrado', show_alert=True); raise _V171Stop
            ok=0; total=0
            for rid in [int(x) for x in b.get('items', []) if str(x).isdigit()]:
                row = recurring_find(chat_id, rid); total += 1
                if row:
                    try:
                        await _v170_send_recurring_manual(context, chat_id, row) if '_v170_send_recurring_manual' in globals() else await send_recurring_message(context, chat_id, dict(row))
                        ok += 1; await asyncio.sleep(0.4)
                    except Exception: logger.exception('V171 bloque recurrente %s falló', rid)
            await q.answer(f'Bloque enviado: {ok}/{total}', show_alert=True); raise _V171Stop
        if action == 'rblk_del':
            bid = int(parts[3]); blocks = _v171_rec_blocks(chat_id); blocks[:] = [b for b in blocks if int(b.get('id',0) or 0) != bid]; save_all_states()
            await q.answer('Bloque borrado'); await q.edit_message_text(_v171_rec_blocks_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_blocks_markup(chat_id)); raise _V171Stop
    except _V171Stop:
        raise
    except Exception:
        logger.exception('Error bloques recurrentes V171: %s', q.data)
        try: await q.answer('Error bloque recurrente. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V171Stop


_old_build_application_v171 = build_application

def build_application() -> Application:
    app = _old_build_application_v171()
    app.add_handler(CallbackQueryHandler(_v171_panel_config_router, pattern=r'^panelcfg\|'), group=-11400000000)
    app.add_handler(CallbackQueryHandler(_v171_rec_blocks_router, pattern=r'^cfg\|rblk_'), group=-11400000000)
    logger.info('V171 panel configurable y bloques recurrentes múltiples cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V172Stop
except Exception:
    _V172Stop = Exception


def _v172_used_panel_items(chat_id: int) -> set:
    pcfg = _v171_panel_cfg(chat_id)
    used = set()
    for b in pcfg.get('blocks', []) or []:
        for it in b.get('items', []) or []:
            if it in _v171_available_panel_items():
                used.add(it)
    return used


def _v172_unassigned_items(chat_id: int) -> List[str]:
    defs = _v171_available_panel_items()
    used = _v172_used_panel_items(chat_id)
    return [k for k in defs.keys() if k not in used and k != 'change_group']


def _v171_panel_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    pcfg = cfg.setdefault('panel_config_v171', _v171_default_panel_cfg(chat_id))
    if not isinstance(pcfg, dict):
        pcfg = _v171_default_panel_cfg(chat_id)
        cfg['panel_config_v171'] = pcfg
    pcfg.setdefault('top_fields', ['grupo', 'validation', 'recurrentes', 'ia', 'pending', 'daily_phrase', 'awards'])
    pcfg.setdefault('blocks', _v171_default_panel_cfg(chat_id)['blocks'])
    pcfg.setdefault('show_group_before_change', True)

    defs = _v171_available_panel_items()
    used = set()
    clean_blocks = []
    for b in pcfg.get('blocks', []) or []:
        if not isinstance(b, dict):
            continue
        clean_items = []
        for it in b.get('items', []) or []:

            if it in defs and it not in used and it != 'change_group':
                clean_items.append(it)
                used.add(it)
        b['items'] = clean_items
        b.setdefault('title', 'Bloque')
        b.setdefault('id', f'block{len(clean_blocks)+1}')
        clean_blocks.append(b)
    if not clean_blocks:
        clean_blocks = _v171_default_panel_cfg(chat_id)['blocks']
    pcfg['blocks'] = clean_blocks
    return pcfg


_old_v172_panelcfg_text = _v171_panelcfg_text

def _v171_panelcfg_text(chat_id: int) -> str:
    pcfg = _v171_panel_cfg(chat_id)
    fields = _v171_top_fields_available()
    top = ', '.join(fields.get(x, x) for x in pcfg.get('top_fields', [])) or 'Nada'
    unassigned = _v172_unassigned_items(chat_id)
    lines = [
        '<b>⚙️ Configuración del panel de ajustes</b>',
        '',
        f'<b>Resumen superior:</b> {h(top)}',
        f'<b>Botones sin asignar:</b> {len(unassigned)}',
        '',
        '<b>Bloques actuales:</b>'
    ]
    for idx, b in enumerate(pcfg.get('blocks', []) or [], start=1):
        items = ', '.join((_v171_available_panel_items().get(i, {}).get('label', i)) for i in b.get('items', [])) or 'vacío'
        lines.append(f'{idx}. <b>{h(str(b.get("title","Bloque")))}</b> · {h(items)}')
    lines.append('\nPulsa un bloque para meter o quitar botones. Si quitas un botón, aparecerá en <b>Botones sin asignar</b>.')
    return '\n'.join(lines)


