async def _v173_validation_block_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|block|'):
        return
    parts = q.data.split('|')
    if len(parts) < 4 or parts[3] != 'validation':
        return
    chat_id = int(parts[2])
    await q.answer()
    try:
        await _v124_edit_validation_panel(q, chat_id)
    except Exception:
        logger.exception('V173 error abriendo panel completo Validación')
        await q.edit_message_text(admin_private_block_text(chat_id, 'validation'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'validation'))
    raise _V173Stop


def _v173_rec_block_defaults(b: Dict[str, Any]) -> Dict[str, Any]:
    b.setdefault('enabled', False)
    b.setdefault('time', '21:00')
    b.setdefault('mode', 'manual')
    b.setdefault('last_sent_day', '')
    return b


_old_v173_rec_blocks = _v171_rec_blocks

def _v171_rec_blocks(chat_id: int) -> List[Dict[str, Any]]:
    blocks = _old_v173_rec_blocks(chat_id)
    for b in blocks:
        if isinstance(b, dict): _v173_rec_block_defaults(b)
    return blocks


def _v171_rec_block_text(chat_id: int, bid: int) -> str:
    b = _v173_rec_block_defaults(_v171_rec_block_find(chat_id, bid) or {'name':'Bloque','items':[]})
    lines = [f"<b>📦 {h(str(b.get('name','Bloque')))}</b>", '', f"Modo: <b>{'Automático diario' if b.get('mode') == 'daily' else 'Manual'}</b>", f"Activo: <b>{bool_label(bool(b.get('enabled', False)))}</b>", f"Hora: <b>{h(str(b.get('time','21:00')))}</b>", '', 'Recurrentes dentro:']
    items = [int(x) for x in (b.get('items') or []) if str(x).isdigit()]
    if not items: lines.append('Sin recurrentes todavía.')
    for rid in items:
        row = recurring_find(chat_id, rid)
        lines.append(f"• #{rid} · {h(str((row or {}).get('name') or (row or {}).get('title') or 'Recurrente'))}")
    return '\n'.join(lines)


def _v171_rec_block_markup(chat_id: int, bid: int) -> InlineKeyboardMarkup:
    b = _v173_rec_block_defaults(_v171_rec_block_find(chat_id, bid) or {'items':[]})
    current = set(str(x) for x in (b.get('items') or []))
    rows = [
        [InlineKeyboardButton('✏️ Cambiar nombre', callback_data=f'cfg|rblk_rename|{chat_id}|{bid}')],
        [InlineKeyboardButton('▶️ Lanzar este bloque', callback_data=f'cfg|rblk_send|{chat_id}|{bid}')],
        [InlineKeyboardButton(f"🤖 Auto {'ON' if b.get('enabled') else 'OFF'}", callback_data=f'cfg|rblk_auto|{chat_id}|{bid}'), InlineKeyboardButton(f"🕒 {b.get('time','21:00')}", callback_data=f'cfg|rblk_time|{chat_id}|{bid}')],
    ]
    for row in recurring_list(chat_id):
        rid = str(row.get('id'))
        mark = '✅' if rid in current else '⬜'
        name = str(row.get('name') or row.get('title') or f'Recurrente {rid}')
        rows.append([InlineKeyboardButton(f'{mark} #{rid} · {truncated_button_title(name, 38)}', callback_data=f'cfg|rblk_toggle|{chat_id}|{bid}|{rid}')])
    rows.append([InlineKeyboardButton('🗑 Borrar bloque', callback_data=f'cfg|rblk_del|{chat_id}|{bid}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'cfg|rblk_list|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v173_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int,int]:
    ok=0; total=0
    for rid in [int(x) for x in b.get('items', []) if str(x).isdigit()]:
        row = recurring_find(chat_id, rid); total += 1
        if row:
            try:
                tmp = dict(row)
                if '_v170_send_recurring_manual' in globals():
                    await _v170_send_recurring_manual(context, chat_id, tmp)
                else:
                    await send_recurring_message(context, chat_id, tmp)
                ok += 1; await asyncio.sleep(0.35)
            except Exception:
                logger.exception('V173 bloque recurrente %s falló', rid)
    return ok,total


async def _v173_rec_blocks_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rblk_'):
        return
    parts = q.data.split('|'); action = parts[1]; chat_id = int(parts[2])
    try:
        if action == 'rblk_list':
            await q.answer(); await q.edit_message_text(_v171_rec_blocks_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_blocks_markup(chat_id)); raise _V173Stop
        if action == 'rblk_new':
            bid = _v171_next_rec_block_id(chat_id)
            _v171_rec_blocks(chat_id).append({'id': bid, 'name': f'Bloque {bid}', 'items': [], 'enabled': False, 'mode': 'manual', 'time': '21:00'}); save_all_states()
            set_config_pending(q.from_user.id, {'kind':'rec_block_rename_v173','chat_id':chat_id,'bid':bid})
            await q.answer('Bloque creado'); await q.message.reply_html('✏️ Envíame el nombre del nuevo bloque de recurrentes.')
            await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V173Stop
        if action == 'rblk_rename':
            bid = int(parts[3]); set_config_pending(q.from_user.id, {'kind':'rec_block_rename_v173','chat_id':chat_id,'bid':bid})
            await q.answer(); await q.message.reply_html('✏️ Envíame el nuevo nombre para este bloque de recurrentes.'); raise _V173Stop
        if action == 'rblk_auto':
            bid = int(parts[3]); b = _v171_rec_block_find(chat_id, bid)
            if b:
                _v173_rec_block_defaults(b); b['enabled'] = not bool(b.get('enabled')); b['mode'] = 'daily' if b.get('enabled') else 'manual'; save_all_states()
            await q.answer('Actualizado'); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V173Stop
        if action == 'rblk_time':
            bid = int(parts[3]); b = _v171_rec_block_find(chat_id, bid)
            vals=['09:00','12:00','18:00','21:00','23:30','00:30']
            if b:
                cur=str(b.get('time','21:00')); b['time']=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else '21:00'; save_all_states()
            await q.answer('Hora actualizada'); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V173Stop
        if action == 'rblk_open':
            bid=int(parts[3]); await q.answer(); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V173Stop
        if action == 'rblk_toggle':
            bid=int(parts[3]); rid=str(parts[4]); b=_v171_rec_block_find(chat_id,bid)
            if b:
                items=[str(x) for x in b.setdefault('items', [])]
                if rid in items: items.remove(rid)
                else: items.append(rid)
                b['items']=items; save_all_states()
            await q.answer('Actualizado'); await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid)); raise _V173Stop
        if action == 'rblk_send':
            bid=int(parts[3]); b=_v171_rec_block_find(chat_id,bid)
            if not b: await q.answer('Bloque no encontrado', show_alert=True); raise _V173Stop
            ok,total=await _v173_send_rec_block(context, chat_id, b)
            await q.answer(f'Bloque enviado: {ok}/{total}', show_alert=True); raise _V173Stop
        if action == 'rblk_del':
            bid=int(parts[3]); blocks=_v171_rec_blocks(chat_id); blocks[:]=[b for b in blocks if int(b.get('id',0) or 0)!=bid]; save_all_states()
            await q.answer('Bloque borrado'); await q.edit_message_text(_v171_rec_blocks_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_blocks_markup(chat_id)); raise _V173Stop
    except _V173Stop:
        raise
    except Exception:
        logger.exception('Error bloques recurrentes V173: %s', q.data)
        try: await q.answer('Error bloque recurrente. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V173Stop


async def _v173_private_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending:
        return
    kind = pending.get('kind')
    txt = (update.message.text or update.message.caption or '').strip()
    if not txt:
        return
    if kind == 'panel_rename_block_v173':
        chat_id = int(pending.get('chat_id')); bi = int(pending.get('bi'))
        blocks = _v173_panel_cfg(chat_id).get('blocks', []) or []
        if 0 <= bi < len(blocks):
            blocks[bi]['title'] = txt[:60]; save_all_states()
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Nombre de bloque actualizado.')
        raise _V173Stop
    if kind == 'rec_block_rename_v173':
        chat_id = int(pending.get('chat_id')); bid = int(pending.get('bid'))
        b = _v171_rec_block_find(chat_id, bid)
        if b:
            b['name'] = txt[:80]; save_all_states()
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Nombre de bloque recurrente actualizado.')
        raise _V173Stop


async def _v173_rec_block_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        hm = time.strftime('%H:%M')
        day = time.strftime('%Y-%m-%d')
        chat_ids = set()
        try: chat_ids.update(int(x) for x in STATE_CACHE.keys())
        except Exception: pass
        for chat_id in list(chat_ids):
            for b in _v171_rec_blocks(chat_id):
                _v173_rec_block_defaults(b)
                if not bool(b.get('enabled')) or b.get('mode') != 'daily':
                    continue
                if str(b.get('time','21:00')) != hm:
                    continue
                if str(b.get('last_sent_day','')) == day:
                    continue
                await _v173_send_rec_block(context, chat_id, b)
                b['last_sent_day'] = day; save_all_states()
    except Exception:
        logger.exception('Error job bloques recurrentes V173')


_old_build_application_v173 = build_application

def build_application() -> Application:
    app = _old_build_application_v173()
    app.add_handler(CallbackQueryHandler(_v173_validation_block_router, pattern=r'^cfg\|block\|-?\d+\|validation$'), group=-11600000000)
    app.add_handler(CallbackQueryHandler(_v173_panel_config_router, pattern=r'^panelcfg\|'), group=-11600000000)
    app.add_handler(CallbackQueryHandler(_v173_rec_blocks_router, pattern=r'^cfg\|rblk_'), group=-11600000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v173_private_text_router), group=-11600000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v173_rec_block_job, interval=60, first=20, name='v173_rec_block_job')
    except Exception:
        logger.exception('No se pudo iniciar job bloques recurrentes V173')
    logger.info('V173 panel PRO, validación completa y bloques recurrentes programables cargado')
    return app


