_old_v174_validation_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    if block != 'validation':
        return _old_v174_validation_markup(chat_id, block, page)

    try:
        base_markup = _old_v174_validation_markup(chat_id, block, page)
        rows = [list(r) for r in getattr(base_markup, 'inline_keyboard', [])]
    except Exception:
        rows = []
    quick = [
        [InlineKeyboardButton('👋 Mensaje bienvenida', callback_data=f'cfg|block|{chat_id}|welcome'), InlineKeyboardButton('❓ Preguntas', callback_data=f'cfg|block|{chat_id}|questions')],
        [InlineKeyboardButton('✅ Mensaje aceptar', callback_data=f'cfg|block|{chat_id}|approved'), InlineKeyboardButton('❌ Mensaje rechazo', callback_data=f'cfg|block|{chat_id}|rejected')],
        [InlineKeyboardButton('⏰ Mensaje timeout', callback_data=f'cfg|block|{chat_id}|timeout'), InlineKeyboardButton('🔔 Recordatorio', callback_data=f'cfg|block|{chat_id}|reminder')],
        [InlineKeyboardButton('📌 Normas al aceptar', callback_data=f'cfg|block|{chat_id}|rules'), InlineKeyboardButton('🚪 Despedida/salidas', callback_data=f'cfg|block|{chat_id}|farewell')],
        [InlineKeyboardButton('👥 Pendientes', callback_data=f'cfg|pending|{chat_id}'), InlineKeyboardButton('📜 Log', callback_data=f'cfg|log|{chat_id}')],
    ]

    existing_callbacks = {getattr(btn, 'callback_data', '') for row in rows for btn in row}
    quick_clean = []
    for row in quick:
        newrow = [btn for btn in row if getattr(btn, 'callback_data', '') not in existing_callbacks]
        if newrow:
            quick_clean.append(newrow)

    if rows:
        rows = rows[:-1] + quick_clean + rows[-1:]
    else:
        rows = quick_clean + block_footer_rows(chat_id, block)
    return InlineKeyboardMarkup(rows)


