def _v175_profile_ready(chat_id: int, profile: str) -> bool:
    """Listo para funcionar aunque no tenga multimedia.

    La X que se veía venía de media_status(), que solo mira si hay foto/vídeo.
    Para validación, lo importante es si hay texto configurable o texto por defecto.
    """
    try:
        if profile == 'questions':
            return bool(cfg_questions(chat_id))
        if profile == 'welcome':
            return bool(profile_is_configured(chat_id, 'welcome') or str(cfg_value(chat_id, 'validation_intro_message', '') or cfg_value(chat_id, 'welcome_text', '') or VALIDATION_INTRO_MESSAGE).strip())
        if profile == 'approved':
            return bool(profile_is_configured(chat_id, 'approved') or str(cfg_value(chat_id, 'validation_approved_message', VALIDATION_APPROVED_MESSAGE) or '').strip())
        if profile == 'rejected':
            return bool(profile_is_configured(chat_id, 'rejected') or str(cfg_value(chat_id, 'validation_rejected_message', VALIDATION_REJECTED_MESSAGE) or '').strip())
        if profile == 'timeout':
            return bool(profile_is_configured(chat_id, 'timeout') or str(cfg_value(chat_id, 'validation_timeout_message', VALIDATION_TIMEOUT_MESSAGE) or '').strip())
        if profile == 'reminder':
            return bool(profile_is_configured(chat_id, 'reminder') or str(cfg_value(chat_id, 'validation_reminder_message', VALIDATION_REMINDER_MESSAGE) or '').strip())
        if profile == 'rules':
            return bool(profile_is_configured(chat_id, 'rules') or str(cfg_value(chat_id, 'rules_text', '') or '').strip() or bool(cfg_value(chat_id, 'rules_auto_after_approve', False)))
        if profile == 'farewell':
            return bool(profile_is_configured(chat_id, 'farewell') or str(cfg_value(chat_id, 'farewell_text', '') or '').strip())
        return bool(profile_is_configured(chat_id, profile))
    except Exception:
        return False


def _v175_ready_mark(chat_id: int, profile: str) -> str:
    return '✅' if _v175_profile_ready(chat_id, profile) else '❌'


