def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == 'validation':
        txt = _old_v175_validation_text_base(chat_id, block, page)

        marker = '\n\n<b>Mensajes configurables de entrada</b>'
        if marker in txt:
            txt = txt.split(marker)[0]
        marker2 = '\n\n<b>Mensajes de validación listos para funcionar</b>'
        if marker2 in txt:
            txt = txt.split(marker2)[0]
