async def _v175_validation_repair_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v175|valrepair|'):
        return
    try:
        chat_id = int(q.data.split('|')[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V175Stop
    cfg = admin_cfg(chat_id)

    cfg.setdefault('validation_questions', VALIDATION_QUESTIONS)
    cfg.setdefault('validation_intro_message', VALIDATION_INTRO_MESSAGE)
    cfg.setdefault('validation_approved_message', VALIDATION_APPROVED_MESSAGE)
    cfg.setdefault('validation_rejected_message', VALIDATION_REJECTED_MESSAGE)
    cfg.setdefault('validation_timeout_message', VALIDATION_TIMEOUT_MESSAGE)
    cfg.setdefault('validation_reminder_message', VALIDATION_REMINDER_MESSAGE)
    cfg['validation_enabled'] = True
    cfg['validation_require_presentation'] = True
    save_all_states()
    await q.answer('Validación revisada/reparada ✅')
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, 'validation'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'validation'))
    except Exception:
        pass
    raise _V175Stop


