def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v175_validation_markup(chat_id, block, page)
    if block != 'validation':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    exists = any(any((getattr(b, 'callback_data', '') or '').startswith('v175|valrepair|') for b in r) for r in rows)
    if not exists:
        rows.insert(0, [InlineKeyboardButton('🧩 Revisar/reparar validación', callback_data=f'v175|valrepair|{chat_id}')])
    return InlineKeyboardMarkup(rows)


