def _v176_next_recurring_time(chat_id: int) -> str:
    try:
        vals = []
        for r in recurring_list(chat_id):
            if not bool(r.get('enabled', False)):
                continue
            t = str(r.get('time') or r.get('hour') or r.get('scheduled_time') or '').strip()
            if t:
                vals.append(t[:5])
        return sorted(vals)[0] if vals else '—'
    except Exception:
        return '—'


def _v176_next_rec_block_time(chat_id: int) -> str:
    try:
        blocks = _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []
        vals = []
        for b in blocks:
            if bool(b.get('auto', False) or b.get('enabled', False)):
                t = str(b.get('time') or '').strip()
                if t:
                    vals.append(t[:5])
        return sorted(vals)[0] if vals else '—'
    except Exception:
        return '—'


