_old_v176_field_value = _v171_field_value

def _v171_field_value(chat_id: int, key: str) -> str:
    try:
        if key == 'group_id':
            return f'🆔 ID grupo: <code>{int(chat_id)}</code>'
        if key == 'validation_msgs':
            ready = 0
            total = 6
            if '_v175_profile_ready' in globals():
                for p in ('welcome','questions','approved','rejected','timeout','reminder'):
                    ready += 1 if _v175_profile_ready(chat_id, p) else 0
            return f'🛡 Msg validación: <b>{ready}/{total}</b>'
        if key == 'next_recurring':
            return f'⏭ Próx. recurrente: <b>{h(_v176_next_recurring_time(chat_id))}</b>'
        if key == 'next_rec_block':
            return f'📦 Próx. bloque rec.: <b>{h(_v176_next_rec_block_time(chat_id))}</b>'
        if key == 'rec_blocks':
            n = len(_v171_rec_blocks(chat_id)) if '_v171_rec_blocks' in globals() else 0
            return f'📦 Bloques recurrentes: <b>{n}</b>'
        if key == 'awards_daily':
            cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
            return f'🏆 Premios diario: <b>{bool_label(bool(cfg.get("awards_daily_enabled", True)))}</b> · {h(str(cfg.get("awards_daily_time", "23:30")))}'
        if key == 'awards_weekly':
            cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
            return f'📆 Premios semanal: <b>{bool_label(bool(cfg.get("awards_weekly_enabled", False)))}</b> · {h(str(cfg.get("awards_weekly_time", "23:30")))}'
        if key == 'dj_queue':
            st = get_state(chat_id)
            return f'🎧 Cola DJ: <b>{len(st.queue)}</b>'
        if key == 'tarot_lock':
            cfg = _v129_tarot_cfg(chat_id) if '_v129_tarot_cfg' in globals() else admin_cfg(chat_id)
            active = bool(int(cfg.get('tarot_active_until_ts', 0) or 0) > int(time.time()))
            return f'🔮 Tarot en curso: <b>{bool_label(active)}</b>'
        if key == 'check_short':
            val = bool(cfg_value(chat_id, 'validation_enabled', False))
            recs = len(recurring_list(chat_id)) if 'recurring_list' in globals() else 0
            return f'✅ Estado: Validación <b>{bool_label(val)}</b> · Recurrentes <b>{recs}</b>'
    except Exception:
        return ''
    return _old_v176_field_value(chat_id, key)


