def _v149_export_module(src: int, dst: int, module: str) -> None:
    if module == 'panel':
        src_cfg = admin_cfg(src)
        dst_cfg = admin_cfg(dst)
        dst_cfg['panel_config_v171'] = _v149_clean_export_value(src_cfg.get('panel_config_v171', _v171_default_panel_cfg(src))) if '_v149_clean_export_value' in globals() else json.loads(json.dumps(src_cfg.get('panel_config_v171', _v171_default_panel_cfg(src)), ensure_ascii=False, default=str))
        save_all_states()
        try:
            add_action_log(src, 'export_panel', f'panel exportado a {dst}')
            add_action_log(dst, 'export_panel', f'panel importado desde {src}')
        except Exception:
            pass
        return
    if callable(_old_v176_export_module):
        return _old_v176_export_module(src, dst, module)


