def _v177_panel_cfg(chat_id: int) -> Dict[str, Any]:
    pcfg = _v173_panel_cfg(chat_id) if '_v173_panel_cfg' in globals() else _v171_panel_cfg(chat_id)
    pcfg.setdefault('panel_item_labels', {})
    pcfg.setdefault('hidden_items', [])
    pcfg.setdefault('loose_items', [])
    return pcfg


_old_v177_items = _v171_available_panel_items

def _v171_available_panel_items() -> Dict[str, Dict[str, str]]:
    items = dict(_old_v177_items())
