def _v177_label(chat_id: int, key: str) -> str:
    defs = _v171_available_panel_items()
    custom = _v177_panel_cfg(chat_id).get('panel_item_labels', {}) or {}
    return str(custom.get(key) or defs.get(key, {}).get('label') or key)


def _v177_cb(chat_id: int, key: str) -> str:
    defs = _v171_available_panel_items()
    cb = str(defs.get(key, {}).get('cb') or f'panelcfg|control|{chat_id}|{key}')
