def _v177_all_keys() -> List[str]:

    preferred = [
        'validation','welcome','questions','lists','val_welcome_msg','val_questions_msg','val_accept_msg','val_reject_msg','val_timeout_msg','val_reminder_msg','val_rules_accept','val_exit_msg','val_pending','val_entries','val_log','val_silenced','val_kicked','val_who_validates','val_test_entry','val_toggle','val_autoapprove','val_timeout_kick',
        'daily_phrase','awards','recurrentes','recurrent_blocks','pregonero','impostor_settings','tarot','hot','resumen_fun','privadito',
        'ia','dj','dj_permissions','permissions','module_permissions','command_cleanup','commands','manual',
        'cmd_djconfig','cmd_hotconfig','cmd_start','cmd_ajustes',
        'export','checkbot','panel_config','unassigned','all_controls','reload','save','close','change_group'
    ]
    defs = _v171_available_panel_items()
    out = []
    for k in preferred:
        if k in defs and k not in out:
            out.append(k)
    for k in defs:
        if k not in out:
            out.append(k)
    return out


def _v177_used_keys(chat_id: int) -> set:
    pcfg = _v177_panel_cfg(chat_id)
    used = set()
    for b in pcfg.get('blocks', []) or []:
        for k in b.get('items', []) or []:
            used.add(k)
    for item in pcfg.get('loose_items', []) or []:
        if isinstance(item, dict) and item.get('key'):
            used.add(str(item['key']))
    return used


def _v172_unassigned_items(chat_id: int) -> List[str]:
    pcfg = _v177_panel_cfg(chat_id)
    defs = _v171_available_panel_items()
    hidden = set(pcfg.get('hidden_items') or [])
    used = _v177_used_keys(chat_id)
    return [k for k in _v177_all_keys() if k in defs and k not in used and k not in hidden and k != 'change_group']


def _v171_render_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v177_panel_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    for block in pcfg.get('blocks', []) or []:
        title = str(block.get('title') or 'Bloque')
        rows.append([InlineKeyboardButton(f'──── {title} ────', callback_data=f'panelnoop|{chat_id}')])
        pair: List[InlineKeyboardButton] = []
        for key in block.get('items', []) or []:
            if key not in _v171_available_panel_items():
                continue
            pair.append(InlineKeyboardButton(_v177_label(chat_id, key), callback_data=_v177_cb(chat_id, key)))
            if len(pair) == 2:
                rows.append(pair); pair=[]
        if pair:
            rows.append(pair)

    loose_small: List[InlineKeyboardButton] = []
    for item in pcfg.get('loose_items', []) or []:
        if not isinstance(item, dict):
            continue
        key = item.get('key')
        if key not in _v171_available_panel_items():
            continue
        btn = InlineKeyboardButton(_v177_label(chat_id, key), callback_data=_v177_cb(chat_id, key))
        if item.get('size') == 'big':
            if loose_small:
                rows.append(loose_small); loose_small=[]
            rows.append([btn])
        else:
            loose_small.append(btn)
            if len(loose_small) == 2:
                rows.append(loose_small); loose_small=[]
    if loose_small:
        rows.append(loose_small)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}'), InlineKeyboardButton('🎛 Todos los controles', callback_data=f'panelcfg|all|{chat_id}')])
    if bool(pcfg.get('show_group_before_change', True)):
        try:
            title = cfg_value(chat_id, 'chat_title', str(chat_id))
        except Exception:
            title = str(chat_id)
        rows.append([InlineKeyboardButton(f'🌐 Grupo actual: {str(title)[:45]}', callback_data=f'panelnoop|{chat_id}')])
    rows.append([InlineKeyboardButton('🌐 Cambiar grupo', callback_data='cfg|list')])
    return InlineKeyboardMarkup(rows)


def _v177_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    keys = _v172_unassigned_items(chat_id) if unassigned_only else [k for k in _v177_all_keys() if k in _v171_available_panel_items()]
    title = '🧺 Botones sin asignar' if unassigned_only else '🎛 Todos los controles'
    lines = [f'<b>{title}</b>', '', 'Pulsa un control para ejecutarlo. Usa ✏️ para cambiar su nombre visible en el panel.']
    if unassigned_only:
        lines.append('\nEstos controles no están dentro de ningún bloque ni como botones sueltos.')
    return '\n'.join(lines)


def _v177_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    keys = _v172_unassigned_items(chat_id) if unassigned_only else [k for k in _v177_all_keys() if k in _v171_available_panel_items()]
    per_page = 12
    max_page = max(0, (len(keys)-1)//per_page)
    page = max(0, min(int(page or 0), max_page))
    chunk = keys[page*per_page:(page+1)*per_page]
    rows: List[List[InlineKeyboardButton]] = []
    for k in chunk:
        rows.append([
            InlineKeyboardButton(_v177_label(chat_id, k), callback_data=f'panelcfg|control|{chat_id}|{k}'),
            InlineKeyboardButton('✏️', callback_data=f'panelcfg|renameitem|{chat_id}|{k}'),
        ])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'panelcfg|{"unassigned" if unassigned_only else "all"}|{chat_id}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{max_page+1}', callback_data=f'panelnoop|{chat_id}'))
    if page < max_page:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'panelcfg|{"unassigned" if unassigned_only else "all"}|{chat_id}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('➕ Meter en bloque', callback_data=f'panelcfg|assignmenu|{chat_id}|{page}|{1 if unassigned_only else 0}'), InlineKeyboardButton('🔙 Panel config', callback_data=f'panelcfg|open|{chat_id}')])
    rows.append([InlineKeyboardButton('⚙️ Volver a ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v177_open_block(q, chat_id: int, block: str) -> None:
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, block), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, block))
    except Exception:
        logger.exception('V177 no pudo abrir bloque %s', block)
        await q.answer('Error abriendo el bloque. Mira logs.', show_alert=True)


async def _v177_execute_key(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, key: str) -> None:
    q = update.callback_query
    if not q:
        return

    block_map = {
        'validation':'validation', 'welcome':'welcome', 'questions':'questions', 'lists':'lists',
        'daily_phrase':'daily_phrase', 'awards':'awards', 'recurrentes':'recurrentes', 'recurrent_blocks':'recurrent_blocks',
        'pregonero':'pregonero', 'impostor_settings':'impostor_settings', 'tarot':'tarot', 'hot':'hot',
        'resumen_fun':'resumen_fun', 'privadito':'privadito', 'ia':'ai', 'dj':'dj', 'dj_permissions':'dj_permissions',
        'permissions':'permissions', 'module_permissions':'permissions', 'command_cleanup':'command_cleanup', 'commands':'command_cleanup',
        'manual':'manual',

        'cmd_djconfig':'dj_permissions', 'cmd_hotconfig':'hot', 'cmd_start':'manual', 'cmd_ajustes':'home',
    }
    if key == 'unassigned':
        await q.edit_message_text(_v177_controls_text(chat_id, unassigned_only=True), parse_mode=ParseMode.HTML, reply_markup=_v177_controls_markup(chat_id, unassigned_only=True)); return
    if key == 'all_controls':
        await q.edit_message_text(_v177_controls_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v177_controls_markup(chat_id)); return
    if key == 'panel_config':
        await q.edit_message_text(_v171_panel_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v172_panel_config_markup(chat_id) if '_v172_panel_config_markup' in globals() else _v171_panel_config_markup(chat_id)); return
    if key == 'export':
        await q.edit_message_text(_v148_export_text(chat_id) if '_v148_export_text' in globals() else '<b>📤 Exportar</b>', parse_mode=ParseMode.HTML, reply_markup=_v148_export_dest_markup(chat_id) if '_v148_export_dest_markup' in globals() else InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|open|{chat_id}')]])); return
    if key == 'checkbot':
        if '_v159_checkbot_text' in globals():
            await q.edit_message_text(_v159_checkbot_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Ajustes', callback_data=f'cfg|open|{chat_id}')]])); return
        await q.answer('Comprobación no disponible en esta versión.', show_alert=True); return
    if key == 'reload':
        await q.answer('Reload ejecutado ✅'); await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id)); return
    if key == 'save':
        save_all_states(); await q.answer('Guardado ✅'); return
    if key == 'close':
        await q.answer('Cerrando');
        try: await q.message.delete()
        except Exception: pass
        return
    if key == 'change_group':

        try:
            await q.edit_message_text(admin_private_choose_group_text(), parse_mode=ParseMode.HTML, reply_markup=admin_private_choose_group_markup())
        except Exception:
            await q.answer('Usa /ajustes para cambiar de grupo.', show_alert=True)
        return
    block = block_map.get(key)
    if block == 'home':
        await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id)); return
    if block:
        await _v177_open_block(q, chat_id, block); return

    cb = _v177_cb(chat_id, key)
    if cb.startswith('cfg|block|'):
        await _v177_open_block(q, chat_id, cb.split('|')[-1]); return
    await q.answer('Control disponible para colocar en el panel, pero no tiene acción directa configurada.', show_alert=True)


async def _v177_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V177Stop
    try:
        if action == 'unassigned':
            page = int(parts[3]) if len(parts) > 3 and parts[3].lstrip('-').isdigit() else 0
            await q.answer(); await q.edit_message_text(_v177_controls_text(chat_id, unassigned_only=True), parse_mode=ParseMode.HTML, reply_markup=_v177_controls_markup(chat_id, unassigned_only=True, page=page)); raise _V177Stop
        if action == 'all':
            page = int(parts[3]) if len(parts) > 3 and parts[3].lstrip('-').isdigit() else 0
            await q.answer(); await q.edit_message_text(_v177_controls_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v177_controls_markup(chat_id, page=page)); raise _V177Stop
        if action == 'control':
            key = parts[3]
            await q.answer(); await _v177_execute_key(update, context, chat_id, key); raise _V177Stop
        if action == 'renameitem':
            key = parts[3]
            set_config_pending(q.from_user.id, {'kind':'panel_rename_item_v177','chat_id':chat_id,'key':key})
            await q.answer()
            await q.message.reply_html(f'✏️ Envíame el nuevo nombre para el botón <b>{h(_v177_label(chat_id, key))}</b>.')
            raise _V177Stop
        if action == 'assignmenu':

            await q.answer()
            await q.edit_message_text(_v172_unassigned_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v172_unassigned_markup(chat_id))
            raise _V177Stop
    except _V177Stop:
        raise
    except Exception:
        logger.exception('Error router panel V177: %s', q.data)
        try: await q.answer('Error en panel. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V177Stop


async def _v177_private_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message or not update.message.text:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'panel_rename_item_v177':
        return
    chat_id = int(pending.get('chat_id') or 0); key = str(pending.get('key') or '')
    txt = update.message.text.strip()
    if not txt:
        await update.message.reply_text('Nombre vacío. Envíame un nombre válido.'); raise _V177Stop
    pcfg = _v177_panel_cfg(chat_id)
    labels = pcfg.setdefault('panel_item_labels', {})
    labels[key] = txt[:60]
    pop_config_pending(update.effective_user.id)
    save_all_states()
    await update.message.reply_html(f'✅ Botón renombrado a: <b>{h(labels[key])}</b>', reply_markup=_v177_controls_markup(chat_id))
    raise _V177Stop


