    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, _v177_private_text_router), group=-13000000000)
    logger.info('V177 panel: sin asignar definitivo, todos los controles, permisos, comandos y renombrar botones cargado')
    return app


