def _v178_mark(on: bool) -> str:
    return '🟢' if bool(on) else '⚫️'


def _v178_is_rec_key(key: str) -> bool:
    return str(key).startswith('recsend_') and str(key).split('_', 1)[1].lstrip('-').isdigit()


def _v178_is_rblk_key(key: str) -> bool:
    return str(key).startswith('rblksend_') and str(key).split('_', 1)[1].lstrip('-').isdigit()


def _v178_rec_id_from_key(key: str) -> int:
    return int(str(key).split('_', 1)[1])


def _v178_rblk_id_from_key(key: str) -> int:
    return int(str(key).split('_', 1)[1])


def _v178_known_key(chat_id: int, key: str) -> bool:
    return key in _v171_available_panel_items() or _v178_is_rec_key(key) or _v178_is_rblk_key(key)


def _v178_dynamic_keys(chat_id: int) -> List[str]:
    out: List[str] = []
    try:
        for r in recurring_list(chat_id):
            rid = int(r.get('id', 0) or 0)
            if rid:
                out.append(f'recsend_{rid}')
    except Exception:
        pass
    try:
        for b in _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []:
            bid = int(b.get('id', 0) or 0)
            if bid:
                out.append(f'rblksend_{bid}')
    except Exception:
        pass
    return out


def _v178_label(chat_id: int, key: str) -> str:

    try:
        custom = _v177_panel_cfg(chat_id).get('panel_item_labels', {}) or {}
        if key in custom:
            return str(custom[key])[:64]
    except Exception:
        pass
    if _v178_is_rec_key(key):
        rid = _v178_rec_id_from_key(key)
        try:
            row = recurring_find(chat_id, rid)
            name = str((row or {}).get('name') or (row or {}).get('title') or f'Recurrente {rid}')
        except Exception:
            name = f'Recurrente {rid}'
        return '🔁 ' + truncated_button_title(f'Enviar · {name}', 45)
    if _v178_is_rblk_key(key):
        bid = _v178_rblk_id_from_key(key)
        name = f'Bloque {bid}'
        try:
            for b in _v171_rec_blocks(chat_id):
                if int(b.get('id', 0) or 0) == bid:
                    name = str(b.get('name') or name); break
        except Exception:
            pass
        return '📦 ' + truncated_button_title(f'Lanzar · {name}', 45)
    try:
        return _v177_label(chat_id, key)
    except Exception:
        return str(key)


def _v177_label(chat_id: int, key: str) -> str:
    return _v178_label(chat_id, key)


_old_v178_items = _v171_available_panel_items

def _v171_available_panel_items() -> Dict[str, Dict[str, str]]:
    items = dict(_old_v178_items())

