def _v177_cb(chat_id: int, key: str) -> str:
    if _v178_is_rec_key(key):
        return f'panelrun|rec|{chat_id}|{_v178_rec_id_from_key(key)}'
    if _v178_is_rblk_key(key):
        return f'panelrun|rblk|{chat_id}|{_v178_rblk_id_from_key(key)}'
    defs = _v171_available_panel_items()
    cb = str(defs.get(key, {}).get('cb') or f'panelcfg|control|{chat_id}|{key}')
    return cb.format(chat_id=chat_id)


_old_v178_all_keys = _v177_all_keys

def _v177_all_keys(chat_id: Optional[int] = None) -> List[str]:
    try:
        base = list(_old_v178_all_keys())
    except TypeError:
        base = list(_old_v178_all_keys(chat_id))
    except Exception:
        base = list(_v171_available_panel_items().keys())
    for k in ('dj_permissions','module_permissions','command_permissions','permissions','cmd_djconfig','cmd_hotconfig','cmd_start','cmd_ajustes'):
        if k in _v171_available_panel_items() and k not in base:
            base.append(k)
    if chat_id is not None:
        for k in _v178_dynamic_keys(chat_id):
            if k not in base:
                base.append(k)
    return base


def _v177_used_keys(chat_id: int) -> set:
    pcfg = _v177_panel_cfg(chat_id)
    used = set()
    for b in pcfg.get('blocks', []) or []:
        for k in b.get('items', []) or []:
            used.add(k)
    for item in pcfg.get('loose_items', []) or []:
        if isinstance(item, dict) and item.get('key'):
            used.add(str(item['key']))
    return used


def _v172_unassigned_items(chat_id: int) -> List[str]:
    pcfg = _v177_panel_cfg(chat_id)
    hidden = set(pcfg.get('hidden_items') or [])
    used = _v177_used_keys(chat_id)
    return [k for k in _v177_all_keys(chat_id) if _v178_known_key(chat_id, k) and k not in used and k not in hidden and k != 'change_group']


def _v171_render_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v177_panel_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    for block in pcfg.get('blocks', []) or []:
        title = str(block.get('title') or 'Bloque')
        rows.append([InlineKeyboardButton(f'──── {title} ────', callback_data=f'panelnoop|{chat_id}')])
        pair: List[InlineKeyboardButton] = []
        for key in block.get('items', []) or []:
            if not _v178_known_key(chat_id, key):
                continue
            pair.append(InlineKeyboardButton(_v178_label(chat_id, key), callback_data=_v177_cb(chat_id, key)))
            if len(pair) == 2:
                rows.append(pair); pair = []
        if pair:
            rows.append(pair)
    loose_small: List[InlineKeyboardButton] = []
    for item in pcfg.get('loose_items', []) or []:
        if not isinstance(item, dict):
            continue
        key = item.get('key')
        if not _v178_known_key(chat_id, key):
            continue
        btn = InlineKeyboardButton(_v178_label(chat_id, key), callback_data=_v177_cb(chat_id, key))
        if item.get('size') == 'big':
            if loose_small:
                rows.append(loose_small); loose_small = []
            rows.append([btn])
        else:
            loose_small.append(btn)
            if len(loose_small) == 2:
                rows.append(loose_small); loose_small = []
    if loose_small:
        rows.append(loose_small)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}'), InlineKeyboardButton('🎛 Todos los controles', callback_data=f'panelcfg|all|{chat_id}')])
    if bool(pcfg.get('show_group_before_change', True)):
        try:
            title = cfg_value(chat_id, 'chat_title', str(chat_id))
        except Exception:
            title = str(chat_id)
        rows.append([InlineKeyboardButton(f'🌐 Grupo actual: {str(title)[:45]}', callback_data=f'panelnoop|{chat_id}')])
    rows.append([InlineKeyboardButton('🌐 Cambiar grupo', callback_data='cfg|list')])
    return InlineKeyboardMarkup(rows)


def _v171_panel_block_text(chat_id: int, bi: int) -> str:
    pcfg = _v177_panel_cfg(chat_id); blocks = pcfg.get('blocks', []) or []
    if bi < 0 or bi >= len(blocks):
        return 'Bloque no válido'
    b = blocks[bi]
    lines = [f'<b>{h(str(b.get("title", "Bloque")))}</b>', '', 'Botones dentro de este bloque:']
    items = b.get('items', []) or []
    if not items:
        lines.append('Vacío.')
    for it in items:
        lines.append('• ' + h(_v178_label(chat_id, it)))
    lines.append('\n🟢 = dentro de este bloque. Pulsa para quitarlo.\n⚫️ = fuera. Pulsa para meterlo aquí.')
    return '\n'.join(lines)


def _v171_panel_block_markup(chat_id: int, bi: int) -> InlineKeyboardMarkup:
    pcfg = _v177_panel_cfg(chat_id); blocks = pcfg.get('blocks', []) or []
    current = set(blocks[bi].get('items', []) if 0 <= bi < len(blocks) else [])
    keys = [k for k in _v177_all_keys(chat_id) if _v178_known_key(chat_id, k) and k != 'change_group']
    hidden = set(pcfg.get('hidden_items') or [])
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('✏️ Cambiar nombre del bloque', callback_data=f'panelcfg|renameblock|{chat_id}|{bi}')]]
    pair: List[InlineKeyboardButton] = []
    for key in keys:
        if key in hidden:
            continue
        pair.append(InlineKeyboardButton(f'{_v178_mark(key in current)} {_v178_label(chat_id, key)}', callback_data=f'panelcfg|toggleitem|{chat_id}|{bi}|{key}'))
        if len(pair) == 2:
            rows.append(pair); pair=[]
    if pair:
        rows.append(pair)
    rows.append([InlineKeyboardButton('⬆️ Subir bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|up'), InlineKeyboardButton('⬇️ Bajar bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|down')])
    rows.append([InlineKeyboardButton('🗑 Quitar bloque', callback_data=f'panelcfg|delblock|{chat_id}|{bi}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'panelcfg|blocks|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v171_panel_top_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v177_panel_cfg(chat_id); active = set(pcfg.get('top_fields', []) or [])
    rows=[]; pair=[]
    for k,lbl in _v171_top_fields_available().items():
        pair.append(InlineKeyboardButton(f'{_v178_mark(k in active)} {lbl}', callback_data=f'panelcfg|top_toggle|{chat_id}|{k}'))
        if len(pair)==2:
            rows.append(pair); pair=[]
    if pair:
        rows.append(pair)
    rows.append([InlineKeyboardButton('🔙 Panel', callback_data=f'panelcfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v177_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    keys = _v172_unassigned_items(chat_id) if unassigned_only else [k for k in _v177_all_keys(chat_id) if _v178_known_key(chat_id, k)]
    title = '🧺 Botones sin asignar' if unassigned_only else '🎛 Todos los controles'
    lines = [f'<b>{title}</b>', '', 'Pulsa un control para ejecutarlo. Usa ✏️ para cambiar su nombre visible en el panel.']
    if unassigned_only:
        lines.append('\nEstos controles no están dentro de ningún bloque ni como botones sueltos.')
    lines.append(f'\nTotal: <b>{len(keys)}</b>')
    return '\n'.join(lines)


def _v177_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    keys = _v172_unassigned_items(chat_id) if unassigned_only else [k for k in _v177_all_keys(chat_id) if _v178_known_key(chat_id, k)]
    per_page = 10
    max_page = max(0, (len(keys)-1)//per_page)
    page = max(0, min(int(page or 0), max_page))
    chunk = keys[page*per_page:(page+1)*per_page]
    rows: List[List[InlineKeyboardButton]] = []
    for k in chunk:
        rows.append([
            InlineKeyboardButton(_v178_label(chat_id, k), callback_data=f'panelcfg|control|{chat_id}|{k}'),
            InlineKeyboardButton('✏️', callback_data=f'panelcfg|renameitem|{chat_id}|{k}'),
        ])
    nav=[]
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'panelcfg|{"unassigned" if unassigned_only else "all"}|{chat_id}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{max_page+1}', callback_data=f'panelnoop|{chat_id}'))
    if page < max_page:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'panelcfg|{"unassigned" if unassigned_only else "all"}|{chat_id}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('➕ Meter en bloque', callback_data=f'panelcfg|assignmenu|{chat_id}|{page}|{1 if unassigned_only else 0}'), InlineKeyboardButton('🔙 Panel config', callback_data=f'panelcfg|open|{chat_id}')])
    rows.append([InlineKeyboardButton('⚙️ Volver a ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v178_group_msg_counts(chat_id: int) -> tuple[int, int]:
    try:
        cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
        stats = cfg.setdefault('awards_stats', {})
        today = _v167_stats_day_key() if '_v167_stats_day_key' in globals() else time.strftime('%Y-%m-%d')
        day = stats.get(today, {}) or {}
        day_total = sum(int(r.get('messages', 0) or 0) for r in (day.get('users', {}) or {}).values() if isinstance(r, dict))
        week_total = 0
        now = time.time()
        for i in range(7):
            dk = _v167_stats_day_key(int(now - i*86400)) if '_v167_stats_day_key' in globals() else time.strftime('%Y-%m-%d', time.localtime(now - i*86400))
            d = stats.get(dk, {}) or {}
            week_total += sum(int(r.get('messages', 0) or 0) for r in (d.get('users', {}) or {}).values() if isinstance(r, dict))
        return day_total, week_total
    except Exception:
        return 0, 0


