def _v180_known_key(chat_id: int, key: str) -> bool:
    try:
        return bool(_v178_known_key(chat_id, key)) or str(key) == 'clean_private'
    except Exception:
        return key in _v171_available_panel_items() or str(key) == 'clean_private'


_old_v180_available_items = _v171_available_panel_items

def _v171_available_panel_items() -> Dict[str, Dict[str, str]]:
    items = dict(_old_v180_available_items())
    items.update({
        'clean_private': {'label': '🧹 Limpiar chat privado del bot', 'cb': 'panelcmd|cleanprivate|{chat_id}'},
        'recurrent_blocks': {'label': '📦 Bloques recurrentes', 'cb': 'cfg|rblk_list|{chat_id}'},
        'recurrentes': {'label': '🔁 Mensajes recurrentes', 'cb': 'cfg|block|{chat_id}|recurrentes'},
    })
    return items


_old_v180_all_keys = _v177_all_keys

def _v177_all_keys(chat_id: Optional[int] = None) -> List[str]:
    try:
        base = list(_old_v180_all_keys(chat_id))
    except TypeError:
        base = list(_old_v180_all_keys())
    except Exception:
        base = list(_v171_available_panel_items().keys())
    for k in ('clean_private', 'recurrentes', 'recurrent_blocks'):
        if k not in base:
            base.append(k)
    if chat_id is not None:
        try:
            for k in _v178_dynamic_keys(chat_id):
                if k not in base:
                    base.append(k)
        except Exception:
            pass
    return base


