def _v172_unassigned_items(chat_id: int) -> List[str]:
    pcfg = _v177_panel_cfg(chat_id)
    hidden = set(pcfg.get('hidden_items') or [])
    used = set()
    for b in pcfg.get('blocks', []) or []:
        for k in b.get('items', []) or []:
            used.add(str(k))
    for item in pcfg.get('loose_items', []) or []:
        if isinstance(item, dict) and item.get('key'):
            used.add(str(item.get('key')))
    out = []
    for k in _v177_all_keys(chat_id):
        if k == 'change_group':
            continue
        if k in used or k in hidden:
            continue
        if _v180_known_key(chat_id, k):
            out.append(k)
    return out


def _v180_blocks(chat_id: int) -> List[Dict[str, Any]]:
    pcfg = _v177_panel_cfg(chat_id)
    blocks = pcfg.setdefault('blocks', [])
    if not blocks:
        blocks.append({'id': 'main', 'title': 'Principal', 'items': []})
    return blocks


