async def _v180_clean_private_from_panel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcmd|cleanprivate|'):
        return
    if not q.message or getattr(q.message.chat, 'type', '') != 'private':
        await q.answer('Este botón limpia el privado del bot. Ábrelo en el chat privado.', show_alert=True)
        raise _V180Stop
    await q.answer('Limpiando privado…')
    deleted = 0
    try:
        if '_v99_clean_private' in globals():
            deleted = await _v99_clean_private(context.bot, q.message.chat_id, q.from_user.id)
        elif '_v92_clean_private_chat' in globals():
            deleted = await _v92_clean_private_chat(context.bot, q.message.chat_id, q.from_user.id, also_current=q.message.message_id)
        else:
            try:
                await q.message.delete(); deleted = 1
            except Exception:
                deleted = 0
    except Exception:
        logger.exception('No pude limpiar privado desde panel')
    try:
        await q.message.delete()
    except Exception:
        pass

    raise _V180Stop


_old_v180_execute_key = _v177_execute_key

async def _v177_execute_key(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, key: str) -> None:
    q = update.callback_query
    if key == 'clean_private':
        if q:
            if q.message and getattr(q.message.chat, 'type', '') == 'private':
                await _v180_clean_private_from_panel(update, context)
            else:
                await q.answer('Abre /ajustes en privado y pulsa limpiar allí.', show_alert=True)
        return
    return await _old_v180_execute_key(update, context, chat_id, key)


