import copy as _copy_v181


def _v181_find_rec_block(chat_id: int, bid: int) -> Optional[Dict[str, Any]]:
    try:
        for b in _v171_rec_blocks(chat_id):
            try:
                if int(b.get('id', 0) or 0) == int(bid):
                    return b
            except Exception:
                continue
    except Exception:
        logger.exception('V181 no pudo leer bloques recurrentes')
    return None


def _v181_extract_rids_from_block(block: Dict[str, Any]) -> List[int]:
    """Acepta varios formatos históricos para que ningún bloque quede mudo."""
    raw_items: List[Any] = []
    for key in ('items', 'rids', 'recurring_ids', 'recurrentes', 'recurrents'):
        val = block.get(key)
        if isinstance(val, list):
            raw_items.extend(val)
        elif val not in (None, ''):
            raw_items.append(val)
    out: List[int] = []
    for item in raw_items:
        rid = None
        if isinstance(item, dict):
            for k in ('id', 'rid', 'rec_id', 'recurring_id'):
                if item.get(k) is not None:
                    rid = item.get(k); break
            if rid is None and isinstance(item.get('key'), str):
                item = item.get('key')
            else:
                item = rid
        if isinstance(item, str):
            s = item.strip()
            if s.startswith('recsend_'):
                s = s.split('_', 1)[1]
            elif s.startswith('rec:'):
                s = s.split(':', 1)[1]
            elif s.startswith('rec_'):
                s = s.split('_', 1)[1]
            rid = s
        else:
            rid = item
        try:
            rid_int = int(rid)
            if rid_int > 0 and rid_int not in out:
                out.append(rid_int)
        except Exception:
            pass
    return out


async def _v181_send_recurring_manual_clean(context: ContextTypes.DEFAULT_TYPE, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    """Envía un recurrente como disparo manual sin tocar su programación real."""
    tmp = _copy_v181.deepcopy(row)


    for k in ('last_sent_ts', 'last_day', 'last_week', 'next_ts', 'next_run_ts'):
        tmp.pop(k, None)
    try:
        if '_v170_send_recurring_manual' in globals():
            return await _v170_send_recurring_manual(context, chat_id, tmp)
    except Exception:
        logger.exception('V181 _v170_send_recurring_manual falló; uso send_recurring_message')
    return await send_recurring_message(context, chat_id, tmp)


async def _v181_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[int, int, List[str]]:
    block = _v181_find_rec_block(chat_id, bid)
    if not block:
        return 0, 0, ['No encuentro ese bloque recurrente.']
    rids = _v181_extract_rids_from_block(block)
    if not rids:
        return 0, 0, ['El bloque está vacío. Añade recurrentes dentro del bloque.']
    ok = 0
    errors: List[str] = []
    for rid in rids:
        row = recurring_find(chat_id, int(rid))
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        try:
            await _v181_send_recurring_manual_clean(context, chat_id, row)
            ok += 1
            await asyncio.sleep(0.25)
        except Exception:
            logger.exception('V181 bloque recurrente %s falló en recurrente #%s', bid, rid)
            errors.append(f'#{rid} error')
    return ok, len(rids), errors


async def _v173_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int]:
    bid = int(b.get('id', 0) or 0)
    ok, total, _errors = await _v181_send_rec_block(context, chat_id, bid)
    return ok, total


async def _v178_run_rblk(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[bool, str]:
    ok, total, errors = await _v181_send_rec_block(context, chat_id, bid)
    if total <= 0:
        return False, errors[0] if errors else 'El bloque está vacío.'
    if ok <= 0:
        return False, 'No se envió ningún recurrente del bloque. ' + (' · '.join(errors[:3]) if errors else '')
    if errors:
        return True, f'Bloque enviado parcialmente: {ok}/{total} ⚠️'
    return True, f'Bloque enviado: {ok}/{total} ✅'


async def _v181_rblk_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    chat_id = None
    bid = None
    if data.startswith('cfg|rblk_send|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2]); bid = int(parts[3])
        except Exception:
            await q.answer('Bloque inválido.', show_alert=True); raise _V181Stop
    elif data.startswith('panelrun|rblk|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2]); bid = int(parts[3])
        except Exception:
            await q.answer('Bloque inválido.', show_alert=True); raise _V181Stop
    elif data.startswith('panelcfg|control|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2]); key = parts[3]
            if not str(key).startswith('rblksend_'):
                return
            bid = int(str(key).split('_', 1)[1])
        except Exception:
            return
    else:
        return

    ok, total, errors = await _v181_send_rec_block(context, int(chat_id), int(bid))
    if total <= 0:
        await q.answer(errors[0] if errors else 'El bloque está vacío.', show_alert=True)
    elif ok <= 0:
        await q.answer('No se envió ningún recurrente. ' + (' · '.join(errors[:3]) if errors else ''), show_alert=True)
    else:
        await q.answer(f'Bloque enviado: {ok}/{total}' + (' ⚠️' if errors else ' ✅'), show_alert=bool(errors))

    raise _V181Stop


_old_build_application_v181 = build_application

def build_application() -> Application:
    app = _old_build_application_v181()
    app.add_handler(CallbackQueryHandler(_v181_rblk_send_router, pattern=r'^(cfg\|rblk_send\||panelrun\|rblk\||panelcfg\|control\|)'), group=-15000000000)
    logger.info('V181 recurrentes: lanzamiento manual de bloques blindado cargado')
    return app


