def _v182_panel_cfg(chat_id: int) -> Dict[str, Any]:
    return _v177_panel_cfg(chat_id) if '_v177_panel_cfg' in globals() else _v171_panel_cfg(chat_id)


def _v182_all_keys(chat_id: int) -> List[str]:
    keys: List[str] = []
    try:
        for k in _v177_all_keys(chat_id):
            if k not in keys:
                keys.append(k)
    except Exception:
        pass

    try:
        for r in recurring_list(chat_id):
            rid = int(r.get('id', 0) or 0)
            if rid and f'recsend_{rid}' not in keys:
                keys.append(f'recsend_{rid}')
    except Exception:
        logger.exception('V182 no pudo listar recurrentes dinámicos')
    try:
        blocks = _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []
        for b in blocks:
            bid = int(b.get('id', 0) or 0)
            if bid and f'rblksend_{bid}' not in keys:
                keys.append(f'rblksend_{bid}')
    except Exception:
        logger.exception('V182 no pudo listar bloques recurrentes dinámicos')
    return keys


def _v182_is_known(chat_id: int, key: str) -> bool:
    key = str(key)
    try:
        if _v180_known_key(chat_id, key):
            return True
    except Exception:
        pass
    try:
        if _v178_known_key(chat_id, key):
            return True
    except Exception:
        pass
    return key in _v182_all_keys(chat_id) or key.startswith('recsend_') or key.startswith('rblksend_')


def _v182_blocks(chat_id: int) -> List[Dict[str, Any]]:
    pcfg = _v182_panel_cfg(chat_id)
    blocks = pcfg.setdefault('blocks', [])
    if not blocks:
        blocks.append({'id': 'base', 'title': '🧩 Principal', 'items': []})
    for b in blocks:
        b.setdefault('items', [])
    return blocks


def _v182_label(chat_id: int, key: str) -> str:
    try:
        return _v177_label(chat_id, key)
    except Exception:
        return str(key)


def _v182_used_keys(chat_id: int) -> set:
    used = set()
    pcfg = _v182_panel_cfg(chat_id)
    for b in pcfg.get('blocks', []) or []:
        used.update(str(x) for x in (b.get('items') or []))
    for item in pcfg.get('loose_items', []) or []:
        if isinstance(item, dict) and item.get('key'):
            used.add(str(item.get('key')))
    return used


def _v172_unassigned_items(chat_id: int) -> List[str]:
    pcfg = _v182_panel_cfg(chat_id)
    hidden = set(str(x) for x in (pcfg.get('hidden_items') or []))
    used = _v182_used_keys(chat_id)
    return [k for k in _v182_all_keys(chat_id) if _v182_is_known(chat_id, k) and k not in used and k not in hidden and k != 'change_group']


def _v182_assign_to_block(chat_id: int, bi: int, key: str) -> bool:
    key = str(key)
    if not _v182_is_known(chat_id, key):
        return False
    blocks = _v182_blocks(chat_id)
    if not (0 <= int(bi) < len(blocks)):
        return False
    pcfg = _v182_panel_cfg(chat_id)
    pcfg['hidden_items'] = [x for x in (pcfg.get('hidden_items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    for b in blocks:
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    blocks[int(bi)].setdefault('items', []).append(key)
    save_all_states()
    return True


def _v182_toggle_in_block(chat_id: int, bi: int, key: str) -> str:
    key = str(key)
    blocks = _v182_blocks(chat_id)
    if not (0 <= int(bi) < len(blocks)) or not _v182_is_known(chat_id, key):
        return 'No válido'
    pcfg = _v182_panel_cfg(chat_id)
    pcfg['hidden_items'] = [x for x in (pcfg.get('hidden_items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    current = [str(x) for x in (blocks[int(bi)].get('items') or [])]
    if key in current:
        blocks[int(bi)]['items'] = [x for x in current if x != key]
        msg = 'Quitado del bloque'
    else:
        for b in blocks:
            b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
        blocks[int(bi)].setdefault('items', []).append(key)
        msg = 'Añadido al bloque'
    save_all_states()
    return msg


def _v182_loose(chat_id: int, key: str, size: str) -> bool:
    key = str(key)
    if not _v182_is_known(chat_id, key):
        return False
    pcfg = _v182_panel_cfg(chat_id)
    for b in _v182_blocks(chat_id):
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    pcfg['hidden_items'] = [x for x in (pcfg.get('hidden_items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    pcfg.setdefault('loose_items', []).append({'key': key, 'size': 'big' if size == 'big' else 'small'})
    save_all_states()
    return True


def _v182_hide(chat_id: int, key: str) -> bool:
    key = str(key)
    if not _v182_is_known(chat_id, key):
        return False
    pcfg = _v182_panel_cfg(chat_id)
    for b in _v182_blocks(chat_id):
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    hidden = pcfg.setdefault('hidden_items', [])
    if key not in hidden:
        hidden.append(key)
    save_all_states()
    return True


def _v182_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    title = '🧺 <b>Botones sin asignar</b>' if unassigned_only else '🎛 <b>Todos los controles</b>'
    return (
        f'{title}\n\n'
        'Desde aquí puedes ejecutar, renombrar o colocar cualquier control.\n'
        'Los recurrentes y bloques recurrentes también se pueden meter en tus bloques del panel.\n\n'
        '➕ Bloque = colocarlo dentro de un bloque\n'
        '⬇️ Grande / ↔️ Pequeño = ponerlo debajo de los bloques\n'
        '✏️ = cambiar nombre visible\n'
        '🚫 = ocultarlo'
    )


def _v182_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    keys = _v172_unassigned_items(chat_id) if unassigned_only else [k for k in _v182_all_keys(chat_id) if _v182_is_known(chat_id, k) and k != 'change_group']
    per_page = 6
    max_page = max(0, (len(keys) - 1) // per_page)
    page = max(0, min(int(page or 0), max_page))
    chunk = keys[page*per_page:(page+1)*per_page]
    mode = 'unassigned' if unassigned_only else 'all'
    rows: List[List[InlineKeyboardButton]] = []
    if not chunk:
        rows.append([InlineKeyboardButton('No hay controles aquí', callback_data=f'panelnoop|{chat_id}')])
    for key in chunk:
        rows.append([InlineKeyboardButton(_v182_label(chat_id, key), callback_data=f'panelcfg|control|{chat_id}|{key}')])
        rows.append([
            InlineKeyboardButton('➕ Bloque', callback_data=f'p182|choose|{chat_id}|{key}'),
            InlineKeyboardButton('⬇️ Grande', callback_data=f'p182|loose|{chat_id}|{key}|big'),
            InlineKeyboardButton('↔️ Pequeño', callback_data=f'p182|loose|{chat_id}|{key}|small'),
            InlineKeyboardButton('✏️', callback_data=f'p182|rename|{chat_id}|{key}'),
            InlineKeyboardButton('🚫', callback_data=f'p182|hide|{chat_id}|{key}'),
        ])
    nav=[]
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'p182|{mode}|{chat_id}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{max_page+1}', callback_data=f'panelnoop|{chat_id}'))
    if page < max_page:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'p182|{mode}|{chat_id}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}'), InlineKeyboardButton('🔙 Ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v177_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    return _v182_controls_text(chat_id, unassigned_only=unassigned_only)


def _v177_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    return _v182_controls_markup(chat_id, unassigned_only=unassigned_only, page=page)


def _v180_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    return _v182_controls_text(chat_id, unassigned_only=unassigned_only)


def _v180_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    return _v182_controls_markup(chat_id, unassigned_only=unassigned_only, page=page)


def _v182_choose_text(chat_id: int, key: str) -> str:
    return f'<b>➕ Meter en bloque</b>\n\nControl: <b>{h(_v182_label(chat_id, key))}</b>\n\nElige el bloque donde quieres ponerlo:'


def _v182_choose_markup(chat_id: int, key: str) -> InlineKeyboardMarkup:
    rows=[]
    for i,b in enumerate(_v182_blocks(chat_id)):
        title = str(b.get('title') or f'Bloque {i+1}')
        rows.append([InlineKeyboardButton(f'📦 {truncated_button_title(title, 48)}', callback_data=f'p182|assign|{chat_id}|{i}|{key}')])
    rows.append([InlineKeyboardButton('🔙 Botones sin asignar', callback_data=f'p182|unassigned|{chat_id}|0'), InlineKeyboardButton('🎛 Todos', callback_data=f'p182|all|{chat_id}|0')])
    return InlineKeyboardMarkup(rows)


async def _v182_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('p182|'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V182Stop
    try:
        if action in ('unassigned','all'):
            page = int(parts[3]) if len(parts) > 3 and str(parts[3]).lstrip('-').isdigit() else 0
            await q.answer()
            await q.edit_message_text(_v182_controls_text(chat_id, unassigned_only=(action=='unassigned')), parse_mode=ParseMode.HTML, reply_markup=_v182_controls_markup(chat_id, unassigned_only=(action=='unassigned'), page=page))
            raise _V182Stop
        if action == 'choose':
            key = '|'.join(parts[3:])
            await q.answer()
            await q.edit_message_text(_v182_choose_text(chat_id, key), parse_mode=ParseMode.HTML, reply_markup=_v182_choose_markup(chat_id, key))
            raise _V182Stop
        if action == 'assign':
            bi = int(parts[3]); key = '|'.join(parts[4:])
            if _v182_assign_to_block(chat_id, bi, key):
                await q.answer('Añadido al bloque ✅')
                await q.edit_message_text(_v171_panel_block_text(chat_id, bi), parse_mode=ParseMode.HTML, reply_markup=_v171_panel_block_markup(chat_id, bi))
            else:
                await q.answer('No pude añadirlo al bloque.', show_alert=True)
            raise _V182Stop
        if action == 'loose':
            key = parts[3]; size = parts[4] if len(parts) > 4 else 'small'
            if _v182_loose(chat_id, key, size):
                await q.answer('Añadido debajo de los bloques ✅')
                await q.edit_message_text(_v171_panelcfg_text(chat_id) if '_v171_panelcfg_text' in globals() else _v171_panel_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_panelcfg_markup(chat_id) if '_v171_panelcfg_markup' in globals() else _v172_panel_config_markup(chat_id))
            else:
                await q.answer('No pude añadirlo.', show_alert=True)
            raise _V182Stop
        if action == 'hide':
            key = '|'.join(parts[3:])
            if _v182_hide(chat_id, key):
                await q.answer('Oculto ✅')
                await q.edit_message_text(_v182_controls_text(chat_id, unassigned_only=True), parse_mode=ParseMode.HTML, reply_markup=_v182_controls_markup(chat_id, unassigned_only=True))
            else:
                await q.answer('No pude ocultarlo.', show_alert=True)
            raise _V182Stop
        if action == 'rename':
            key = '|'.join(parts[3:])
            set_config_pending(q.from_user.id, {'kind': 'panel_rename_item_v182', 'chat_id': chat_id, 'key': key})
            await q.answer()
            await q.message.reply_html(f'✏️ Envíame el nuevo nombre para:\n<b>{h(_v182_label(chat_id, key))}</b>')
            raise _V182Stop
    except _V182Stop:
        raise
    except Exception:
        logger.exception('Error panel V182: %s', q.data)
        try: await q.answer('Error panel V182. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V182Stop


async def _v182_toggle_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|toggleitem|'):
        return
    parts = q.data.split('|')
    try:
        chat_id = int(parts[2]); bi = int(parts[3]); key = '|'.join(parts[4:])
    except Exception:
        return
    msg = _v182_toggle_in_block(chat_id, bi, key)
    await q.answer(msg)
    await q.edit_message_text(_v171_panel_block_text(chat_id, bi), parse_mode=ParseMode.HTML, reply_markup=_v171_panel_block_markup(chat_id, bi))
    raise _V182Stop


async def _v182_rename_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'panel_rename_item_v182':
        return
    chat_id = int(pending.get('chat_id') or 0)
    key = str(pending.get('key') or '')
    new_name = (update.message.text or update.message.caption or '').strip()
    if not new_name:
        await update.message.reply_html('Envíame un nombre válido.')
        raise _V182Stop
    pcfg = _v182_panel_cfg(chat_id)
    labels = pcfg.setdefault('panel_item_labels', {})
    labels[key] = new_name[:64]
    pop_config_pending(update.effective_user.id)
    save_all_states()
    await update.message.reply_html(f'✅ Nombre cambiado a: <b>{h(new_name[:64])}</b>')
    raise _V182Stop


_old_build_application_v182 = build_application

def build_application() -> Application:
    app = _old_build_application_v182()
    app.add_handler(CallbackQueryHandler(_v182_router, pattern=r'^p182\|'), group=-16000000000)
    app.add_handler(CallbackQueryHandler(_v182_toggle_router, pattern=r'^panelcfg\|toggleitem\|'), group=-16000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v182_rename_text), group=-16000000000)
    logger.info('V182 panel PRO: recurrentes/bloques añadibles a bloques y renombrado universal cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V189Stop
except Exception:
    _V189Stop = Exception

import dataclasses as _dataclasses_v189
import shutil as _shutil_v189

_V189_STATE_LOAD_OK = False
_V189_LAST_STATE_ERROR = ""


def _v189_state_fields() -> set:
    return {f.name for f in _dataclasses_v189.fields(ChatState)}


def _v189_migrate_state_dict(state_data: Dict[str, Any]) -> Dict[str, Any]:
    sd = dict(state_data or {})
    legacy_offset = sd.pop("auto_next_offset", sd.pop("autoplay_offset", None))
    if "auto_sig_seconds" not in sd:
        if legacy_offset is None:
            sd["auto_sig_seconds"] = -1
        else:
            try:
                legacy_offset = int(legacy_offset)
            except Exception:
                legacy_offset = -1
            sd["auto_sig_seconds"] = abs(legacy_offset) if legacy_offset < 0 else legacy_offset
    for k, v in {
        "live_enabled": False,
        "auto_track_enabled": False,
        "auto_sig_seconds": -1,
        "dj_shuffle_enabled": False,
        "control_view": "home",
        "control_page": 0,
        "panel_override_text": "",
        "panel_override_until": None,
        "temp_pin_message_id": None,
        "validation_users": {},
        "admin_config": {},
        "member_activity": {},
        "muted_users": {},
        "entry_log": [],
        "expelled_users": {},
        "action_log": [],
    }.items():
        sd.setdefault(k, v)
    return sd


def _v189_backup_file(path: Path, suffix: str = "bak") -> None:
    try:
        if path.exists() and path.stat().st_size > 0:
            dst = path.with_name(path.name + f".v189.{suffix}.{int(time.time())}")
            _shutil_v189.copy2(path, dst)
            logger.info("V189 backup creado: %s", dst)
    except Exception:
        logger.exception("V189 no pudo crear backup de %s", path)


def load_all_states() -> None:
    global STATE_CACHE, _V189_STATE_LOAD_OK, _V189_LAST_STATE_ERROR
    _V189_STATE_LOAD_OK = False
    _V189_LAST_STATE_ERROR = ""
    if not STATE_PATH.exists():
        logger.warning("V189 state no existe en %s; no se cargan grupos", STATE_PATH)
        STATE_CACHE = {}
        return
    try:
        raw = json.loads(STATE_PATH.read_text(encoding="utf-8"))
    except Exception as e:
        _V189_LAST_STATE_ERROR = f"No se pudo leer state.json: {type(e).__name__}: {e}"
        logger.exception("V189 no se pudo leer state.json")

        if not STATE_CACHE:
            STATE_CACHE = {}
        return
    if not isinstance(raw, dict):
        _V189_LAST_STATE_ERROR = "state.json no es dict raíz"
        logger.error("V189 state.json raíz no es dict")
        return
    fields = _v189_state_fields()
    data: Dict[int, ChatState] = {}
    bad = 0
    for chat_id_str, state_data in raw.items():
        try:
            chat_id = int(chat_id_str)
        except Exception:
            bad += 1
            logger.warning("V189 chat_id inválido en state: %s", chat_id_str)
            continue
        try:
            sd = _v189_migrate_state_dict(state_data if isinstance(state_data, dict) else {})
            extras = {k: v for k, v in sd.items() if k not in fields}
            clean = {k: v for k, v in sd.items() if k in fields}
            if extras:
                ac = clean.setdefault("admin_config", {})
                if isinstance(ac, dict):

                    ac.setdefault("_state_extra_top_level_v189", {}).update(extras)
            st = ChatState(**clean)
            try:
                st.library = dedupe_library_items(st.library)
                st.queue = [dict(item) for item in st.queue]
                st.saved_lists = {name: dedupe_track_items(items) for name, items in st.saved_lists.items()}
            except Exception:
                logger.exception("V189 dedupe parcial falló chat %s; continúo", chat_id)
            data[chat_id] = st
        except Exception:
            bad += 1
            logger.exception("V189 estado inválido para chat %s: se conserva grupo mínimo", chat_id_str)
            try:
                sd = state_data if isinstance(state_data, dict) else {}
                ac = sd.get("admin_config", {}) if isinstance(sd, dict) else {}
                data[int(chat_id_str)] = ChatState(admin_config=ac if isinstance(ac, dict) else {})
            except Exception:
                pass
    STATE_CACHE = data
    _V189_STATE_LOAD_OK = True
    if bad:
        _V189_LAST_STATE_ERROR = f"Cargado con {bad} registros problemáticos, pero sin vaciar estado."
    logger.info("V189 state cargado: %s chats desde %s", len(STATE_CACHE), STATE_PATH)
    _v189_recover_groups_from_private_files()


def save_all_states() -> None:

    if not STATE_CACHE and STATE_PATH.exists() and not os.getenv("ALLOW_EMPTY_STATE_SAVE", "").lower() in ("1", "true", "yes", "on"):
        logger.error("V189 BLOQUEADO save_all_states vacío para no sobrescribir %s", STATE_PATH)
        return
    try:
        STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        if STATE_PATH.exists() and STATE_PATH.stat().st_size > 10:

            bak = STATE_PATH.with_suffix(STATE_PATH.suffix + ".last_good")
            try:
                _shutil_v189.copy2(STATE_PATH, bak)
            except Exception:
                pass
        payload = {str(chat_id): asdict(state) for chat_id, state in STATE_CACHE.items()}
        tmp = STATE_PATH.with_suffix(STATE_PATH.suffix + ".tmp")
        tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(STATE_PATH)
    except Exception:
        logger.exception("V189 error guardando state")


def _v189_recover_groups_from_private_files() -> None:
    """Si STATE_CACHE carga, no toca nada. Si faltan grupos auxiliares, los añade mínimos."""
    recovered = 0
    try:
        load_dj_private_groups()
    except Exception:
        pass
    try:
        load_hot_private_groups()
    except Exception:
        pass
    for root_name in ("DJ_PRIVATE_GROUPS", "HOT_PRIVATE_GROUPS"):
        root = globals().get(root_name, {}) or {}
        if not isinstance(root, dict):
            continue
        for user_rec in root.values():
            if not isinstance(user_rec, dict):
                continue
            groups = user_rec.get("groups", {}) or {}
            if isinstance(groups, dict):
                for gid, info in groups.items():
                    try:
                        cid = int(gid)
                    except Exception:
                        continue
                    if cid not in STATE_CACHE:
                        title = ""
                        if isinstance(info, dict):
                            title = str(info.get("title") or "")
                        STATE_CACHE[cid] = ChatState(admin_config={"chat_title": title} if title else {})
                        recovered += 1
    if recovered:
        logger.warning("V189 recuperó %s grupos mínimos desde ficheros privados", recovered)
        save_all_states()


def known_admin_chats_for_private() -> List[int]:

    if not STATE_CACHE and STATE_PATH.exists():
        try:
            load_all_states()
        except Exception:
            logger.exception("V189 no pudo recargar estados en known_admin_chats")
    _v189_recover_groups_from_private_files()
    return sorted(int(chat_id) for chat_id in STATE_CACHE.keys())


def _v189_now_ts() -> int:
    return int(time.time())


def _v189_dt(now_ts: Optional[int] = None):
    try:
        return _local_dt_v15(now_ts or _v189_now_ts())
    except Exception:
        import datetime as _dt
        return _dt.datetime.fromtimestamp(now_ts or time.time())


def _v189_day_key(now_ts: Optional[int] = None) -> str:
    try:
        return _local_day_key_v15(now_ts or _v189_now_ts())
    except Exception:
        return time.strftime("%Y-%m-%d", time.localtime(now_ts or time.time()))


def _v189_parse_hhmm(value: Any, default: str = "21:00") -> tuple[int, int]:
    s = str(value or default).strip().replace('.', ':')
    try:
        if ':' not in s:
            return max(0, min(23, int(s))), 0
        hh, mm = s.split(':', 1)
        return max(0, min(23, int(hh))), max(0, min(59, int(mm[:2])))
    except Exception:
        hh, mm = default.split(':', 1)
        return int(hh), int(mm)


def _v189_schedule(row: Dict[str, Any]) -> Dict[str, Any]:
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    sched = dict(sched or {})
    if 'type' not in sched:
        sched['type'] = row.get('schedule_type') or row.get('type') or ('daily' if (row.get('time') or row.get('hour')) else '')
    if 'time' not in sched:
        for k in ('time', 'hour', 'scheduled_time', 'hhmm'):
            if row.get(k):
                sched['time'] = row.get(k); break
    if 'days' not in sched:
        for k in ('days', 'weekdays', 'weekday', 'day'):
            if row.get(k) not in (None, ''):
                sched['days'] = row.get(k); break
    if 'seconds' not in sched:
        if row.get('interval_seconds'):
            sched['seconds'] = row.get('interval_seconds')
        elif row.get('repeat_seconds'):
            sched['seconds'] = row.get('repeat_seconds')
        elif row.get('interval_minutes'):
            try: sched['seconds'] = int(row.get('interval_minutes')) * 60
            except Exception: pass
    return sched


def _v189_weekday(x: Any) -> Optional[int]:
    if isinstance(x, int):
        return x if 0 <= x <= 6 else None
    s = str(x or '').strip().lower()
    mp = {'lunes':0,'lu':0,'mon':0,'mo':0,'0':0,'1':0,'martes':1,'ma':1,'tue':1,'tu':1,'2':1,'miercoles':2,'miércoles':2,'mi':2,'wed':2,'we':2,'3':2,'jueves':3,'ju':3,'thu':3,'th':3,'4':3,'viernes':4,'vi':4,'fri':4,'fr':4,'5':4,'sabado':5,'sábado':5,'sa':5,'sat':5,'6':5,'domingo':6,'do':6,'sun':6,'su':6,'7':6}
    return mp.get(s)


def _v189_days(val: Any) -> List[int]:
    if val in (None, '', []):
        return []
    parts = re.split(r'[,;|/ ]+', val) if isinstance(val, str) else list(val if isinstance(val, (list, tuple, set)) else [val])
    out=[]
    for p in parts:
        wd = _v189_weekday(p)
        if wd is not None and wd not in out:
            out.append(wd)
    return out


def _v189_recurring_due_reason(row: Dict[str, Any], now_ts: int) -> tuple[bool, str]:
    if not bool(row.get('enabled', True)):
        return False, 'OFF'
    sched = _v189_schedule(row)
    stype = str(sched.get('type') or '').lower().strip()
    now_dt = _v189_dt(now_ts)
    last = int(row.get('last_sent_ts', 0) or 0)
    if stype in ('interval', 'cada', 'repeat'):
        sec = max(30, int(sched.get('seconds') or 3600))
        return (now_ts - last >= sec), f'cada {sec//60} min'
    if stype == 'start_interval':
        start_ts = int(sched.get('start_ts') or 0)
        if start_ts and now_ts < start_ts:
            return False, 'antes de inicio'
        repeat = max(60, int(sched.get('repeat_seconds') or sched.get('seconds') or 3600))
        return (last <= 0 or now_ts - last >= repeat), f'intervalo {repeat//60} min'
    if stype in ('weekly', 'semanal', 'week'):
        days = _v189_days(sched.get('days')) or [now_dt.weekday()]
        if now_dt.weekday() not in days:
            return False, 'otro día'
        wk = now_dt.strftime('%G-%V')
        if str(row.get('last_week_key') or '') == wk:
            return False, 'ya enviado semana'
        hh, mm = _v189_parse_hhmm(sched.get('time', '21:00'))
        return (now_dt.hour, now_dt.minute) >= (hh, mm), f'semanal {hh:02d}:{mm:02d}'
    if stype in ('date', 'fecha', 'once'):
        date_s = str(sched.get('date') or row.get('date') or '').strip()
        if not date_s or now_dt.strftime('%Y-%m-%d') != date_s:
            return False, 'otra fecha'
        if str(row.get('last_date_key') or '') == date_s:
            return False, 'ya enviado fecha'
        hh, mm = _v189_parse_hhmm(sched.get('time', '21:00'))
        return (now_dt.hour, now_dt.minute) >= (hh, mm), f'fecha {hh:02d}:{mm:02d}'

    if sched.get('time') or stype in ('daily', 'diario', 'day', ''):
        dk = _v189_day_key(now_ts)
        if str(row.get('last_day') or '') == dk:
            return False, 'ya enviado hoy'
        hh, mm = _v189_parse_hhmm(sched.get('time', '21:00'))
        return (now_dt.hour, now_dt.minute) >= (hh, mm), f'diario {hh:02d}:{mm:02d}'
    return False, f'tipo no soportado {stype}'


def recurring_due(row: Dict[str, Any], now_ts: int) -> bool:
    try:
        return _v189_recurring_due_reason(row, now_ts)[0]
    except Exception:
        logger.exception('V189 recurring_due error')
        return False


def _v189_mark_sent(row: Dict[str, Any], now_ts: int) -> None:
    sched = _v189_schedule(row)
    stype = str(sched.get('type') or '').lower().strip()
    dt = _v189_dt(now_ts)
    row['last_sent_ts'] = now_ts
    if stype in ('weekly','semanal','week'):
        row['last_week_key'] = dt.strftime('%G-%V')
    elif stype in ('date','fecha','once'):
        row['last_date_key'] = str(sched.get('date') or dt.strftime('%Y-%m-%d'))
        row['enabled'] = False
    else:
        row['last_day'] = _v189_day_key(now_ts)


def _v189_chat_ids() -> List[int]:
    ids = set(known_admin_chats_for_private())
    return sorted(int(x) for x in ids if int(x) < 0)


def _v189_phrase_due(chat_id: int, now_ts: int) -> tuple[bool, str]:
    cfg = admin_cfg(chat_id)
    if not bool(cfg.get('daily_phrase_enabled', False)):
        return False, 'OFF'
    if str(cfg.get('daily_phrase_last_key') or '') == _v189_day_key(now_ts):
        return False, 'ya enviada hoy'
    hh, mm = _v189_parse_hhmm(cfg.get('daily_phrase_time', '10:00'), '10:00')
    dt = _v189_dt(now_ts)
    return (dt.hour, dt.minute) >= (hh, mm), f'{hh:02d}:{mm:02d}'


async def _v189_send_daily_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> Optional[int]:

    now_ts = int(now_ts or time.time())
    try:
        if '_v113_send_daily_phrase' in globals():
            ids = await _v113_send_daily_phrase(bot, chat_id, now_ts=now_ts, force=force)
            mid = int(ids[-1]) if ids else None
        else:
            phrase = daily_phrase_for_chat_v30(chat_id, now_ts) if 'daily_phrase_for_chat_v30' in globals() else daily_phrase_for_date_v15(now_ts)
            msg = await bot.send_message(chat_id, f'<b>🌞 Frase del día</b>\n\n<b><i>“{h(str(phrase))}”</i></b>', parse_mode=ParseMode.HTML)
            mid = int(msg.message_id)
        cfg = admin_cfg(chat_id)
        cfg['daily_phrase_last_key'] = _v189_day_key(now_ts)
        cfg['daily_phrase_last_sent_ts'] = now_ts
        cfg['daily_phrase_sending_key'] = ''
        save_all_states()
        return mid
    except Exception:
        logger.exception('V189 no pudo enviar frase del día')
        raise


async def _v189_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = _v189_now_ts()
    for chat_id in _v189_chat_ids():
        try:
            due, _reason = _v189_phrase_due(chat_id, now)
            if due:
                await _v189_send_daily_phrase(context.bot, chat_id, now_ts=now, force=False)
                await asyncio.sleep(0.25)
        except Exception:
            logger.exception('V189 scheduler frase chat=%s', chat_id)
        try:
            for row in list(recurring_list(chat_id)):
                try:
                    due, reason = _v189_recurring_due_reason(row, now)
                    if due:
                        sent = await send_recurring_message(context, chat_id, row)
                        if sent:
                            _v189_mark_sent(row, now)
                            save_all_states()
                            logger.info('V189 recurrente enviado chat=%s id=%s reason=%s', chat_id, row.get('id'), reason)
                            await asyncio.sleep(0.35)
                except Exception:
                    logger.exception('V189 scheduler recurrente chat=%s id=%s', chat_id, row.get('id'))
        except Exception:
            logger.exception('V189 scheduler recurrentes chat=%s', chat_id)


async def _v189_scheduler_loop(app: Application) -> None:
    logger.info('V189 scheduler interno arrancado')
    while True:
        try:
            class _Ctx:
                application = app
                bot = app.bot
            await _v189_scheduler_tick(_Ctx())
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V189 scheduler loop error')
        await asyncio.sleep(60)


async def _v189_post_init(app: Application) -> None:
    if app.bot_data.get('v189_scheduler_started'):
        return
    app.bot_data['v189_scheduler_started'] = True
    try:
        app.create_task(_v189_scheduler_loop(app), name='v189_scheduler_loop')
    except TypeError:
        app.create_task(_v189_scheduler_loop(app))


async def _v189_phrase_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_send|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[2])
        await _v189_send_daily_phrase(context.bot, chat_id, force=True)
        await q.answer('Frase enviada ✅')
    except Exception:
        logger.exception('V189 enviar frase manual falló')
        await q.answer('No pude enviar frase. Mira logs.', show_alert=True)
    raise _V189Stop


async def _v189_health_text(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> str:
    now = _v189_now_ts()
    phrase_due, phrase_reason = _v189_phrase_due(chat_id, now)
    recs = list(recurring_list(chat_id))
    active = [r for r in recs if bool(r.get('enabled', True))]
    due_recs=[]; lines=[]
    for r in active[:30]:
        due, reason = _v189_recurring_due_reason(r, now)
        if due: due_recs.append(r)
        lines.append(f"• #{h(str(r.get('id','?')))} {h(str(r.get('name') or r.get('title') or '')[:26])} · {'YA' if due else h(reason)}")
    cfg = admin_cfg(chat_id)
    return ('<b>✅ COMPROBAR BOT V189</b>\n\n'
            f'📂 STATE_PATH: <code>{h(str(STATE_PATH))}</code>\n'
            f'📦 Grupos cargados: <b>{len(STATE_CACHE)}</b>\n'
            f'🧠 State OK: <b>{bool_label(_V189_STATE_LOAD_OK)}</b> {h(_V189_LAST_STATE_ERROR)}\n'
            f'⏱ Scheduler loop: <b>{bool_label(bool(context.application.bot_data.get("v189_scheduler_started")))}</b> · JobQueue: <b>{bool_label(bool(getattr(context.application, "job_queue", None)))}</b>\n'
            f'🌞 Frase día: <b>{bool_label(bool(cfg.get("daily_phrase_enabled", False)))}</b> · hora <b>{h(str(cfg.get("daily_phrase_time", "10:00")))}</b> · vencida <b>{bool_label(phrase_due)}</b> ({h(phrase_reason)})\n'
            f'🔁 Recurrentes activos: <b>{len(active)}/{len(recs)}</b> · vencidos ahora: <b>{len(due_recs)}</b>\n\n'
            + ('<b>Estado recurrentes</b>\n' + '\n'.join(lines[:12]) if lines else 'Sin recurrentes configurados.'))[:3900]


async def _v189_health_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not ((q.data or '').startswith('checkbot|') or (q.data or '').startswith('cfg|botcheck|')):
        return
    try:
        chat_id = int((q.data or '').split('|')[-1])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True); raise _V189Stop
    await q.answer('Comprobando…')
    text = await _v189_health_text(context, chat_id)
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('🔄 Repetir', callback_data=f'checkbot|{chat_id}')],
        [InlineKeyboardButton('🌞 Enviar frase ahora', callback_data=f'cfg|phrase_send|{chat_id}|daily_phrase'), InlineKeyboardButton('🔁 Recurrentes', callback_data=f'cfg|block|{chat_id}|recurrentes')],
        [InlineKeyboardButton('⚙️ Ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html(text, reply_markup=markup)
    raise _V189Stop


_old_build_application_v189 = build_application

def build_application() -> Application:
    app = _old_build_application_v189()
    app.add_handler(CallbackQueryHandler(_v189_phrase_send_router, pattern=r'^cfg\|phrase_send\|'), group=-19000000000)
    app.add_handler(CallbackQueryHandler(_v189_health_router, pattern=r'^(checkbot\|-?\d+|cfg\|botcheck\|-?\d+)$'), group=-19000000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v189_scheduler_tick, interval=60, first=8, name='v189_scheduler_tick')
            logger.info('V189 scheduler registrado en JobQueue')
    except Exception:
        logger.exception('V189 no pudo registrar JobQueue')
    try:
        app.post_init = _v189_post_init
    except Exception:
        logger.exception('V189 no pudo registrar post_init')
    logger.info('V189 núcleo estable cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V190Stop
except Exception:
    _V190Stop = Exception

import glob as _glob_v190
import shutil as _shutil_v190

_V190_RECOVERY_REPORT: List[str] = []
_V190_AUTO_RECOVERY_DONE = False


def _v190_candidate_paths() -> List[Path]:
    roots: List[str] = []
    for v in (os.getenv('STATE_PATH'), os.getenv('DATA_DIR'), os.getenv('RAILWAY_VOLUME_MOUNT_PATH'), '/data'):
        if not v:
            continue
        p = str(v)
        if p.endswith('.json'):
            roots.append(str(Path(p).parent))
            roots.append(p)
        else:
            roots.append(p)

    seen=set(); paths=[]
    for r in roots:
        if r in seen:
            continue
        seen.add(r)
        try:
            rp = Path(r)
            if rp.is_file():
                paths.append(rp)
            elif rp.exists():
                for pattern in ('state.json', 'state.json.last_good', 'state.json.bak', 'state*.json', '*.last_good', '*groups*.json'):
                    for found in rp.glob(pattern):
                        if found.is_file():
                            paths.append(found)
        except Exception:
            pass

    try:
        for found in _glob_v190.glob('/data/**/*.json', recursive=True):
            p = Path(found)
            if p.is_file():
                paths.append(p)
    except Exception:
        pass
    out=[]; seen=set()
    for p in paths:
        try:
            key=str(p.resolve())
        except Exception:
            key=str(p)
        if key not in seen:
            seen.add(key); out.append(p)
    return out


def _v190_score_state_file(path: Path) -> tuple[int, int, str]:
    """Devuelve (num_chats, bytes, tipo). No modifica nada."""
    try:
        if not path.exists() or path.stat().st_size <= 2:
            return (0, 0, 'vacío')
        raw = json.loads(path.read_text(encoding='utf-8'))
        if isinstance(raw, dict):

            chat_like = 0
            for k, v in raw.items():
                try:
                    int(k)
                    if isinstance(v, dict):
                        chat_like += 1
                except Exception:
                    pass

            aux_like = len(raw) if chat_like == 0 else 0
            return (chat_like or aux_like, int(path.stat().st_size), 'dict')
        if isinstance(raw, list):
            return (len(raw), int(path.stat().st_size), 'list')
    except Exception as e:
        return (0, 0, f'error:{type(e).__name__}')
    return (0, int(path.stat().st_size if path.exists() else 0), 'otro')


def _v190_best_state_candidate() -> Optional[Path]:
    candidates=[]
    for p in _v190_candidate_paths():
        score, size, typ = _v190_score_state_file(p)
        name = p.name.lower()
        is_state = 'state' in name
        candidates.append((score, 1 if is_state else 0, size, p, typ))
    candidates.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
    if candidates:
        _V190_RECOVERY_REPORT[:] = [f'{c[3]} · chats={c[0]} · bytes={c[2]} · {c[4]}' for c in candidates[:10]]
    for score, _is_state, _size, p, _typ in candidates:
        if score > 0 and 'state' in p.name.lower():
            return p
    return None


def _v190_restore_from_path(path: Path, *, make_backup: bool = True) -> bool:
    global _V189_STATE_LOAD_OK, _V189_LAST_STATE_ERROR
    try:
        if not path.exists():
            return False
        if make_backup and STATE_PATH.exists():
            stamp = time.strftime('%Y%m%d-%H%M%S')
            _shutil_v190.copy2(STATE_PATH, STATE_PATH.with_name(f'state.before_v190_restore.{stamp}.json'))
        STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        if path.resolve() != STATE_PATH.resolve():
            _shutil_v190.copy2(path, STATE_PATH)
        load_all_states()
        _V189_STATE_LOAD_OK = bool(STATE_CACHE)
        _V189_LAST_STATE_ERROR = f'Recuperado desde {path}' if STATE_CACHE else f'Restaurado pero 0 chats desde {path}'
        save_all_states()
        logger.warning('V190 restauración aplicada desde %s; chats=%s', path, len(STATE_CACHE))
        return bool(STATE_CACHE)
    except Exception as e:
        _V189_LAST_STATE_ERROR = f'Error recuperando desde {path}: {type(e).__name__}: {e}'
        logger.exception('V190 no pudo restaurar desde %s', path)
        return False


def _v190_auto_recover_if_needed() -> None:
    global _V190_AUTO_RECOVERY_DONE
    if _V190_AUTO_RECOVERY_DONE:
        return
    _V190_AUTO_RECOVERY_DONE = True
    try:

        if STATE_CACHE:
            _v190_best_state_candidate()
            return
        best = _v190_best_state_candidate()
        if best:
            logger.warning('V190 STATE_CACHE vacío; intento recuperación automática desde %s', best)
            _v190_restore_from_path(best, make_backup=True)
        else:
            logger.warning('V190 STATE_CACHE vacío y no hay candidato state válido. Revisa volumen.')
    except Exception:
        logger.exception('V190 auto recuperación falló')


_old_v190_load_all_states = load_all_states

def load_all_states() -> None:
    _old_v190_load_all_states()
    _v190_auto_recover_if_needed()


def _v190_recovery_text() -> str:
    lines = ['<b>🧯 Recuperación de datos V190</b>', '', f'📂 STATE_PATH actual: <code>{h(str(STATE_PATH))}</code>', f'📦 Chats cargados ahora: <b>{len(STATE_CACHE)}</b>', '']
    lines.append('<b>Candidatos encontrados:</b>')
    if not _V190_RECOVERY_REPORT:
        _v190_best_state_candidate()
    if _V190_RECOVERY_REPORT:
        for i, x in enumerate(_V190_RECOVERY_REPORT[:10], start=1):
            lines.append(f'{i}. {h(x)}')
    else:
        lines.append('No encontré state.json ni backups útiles en /data o volumen.')
    lines.append('\nUsa recuperar solo si ahora aparecen 0 grupos o faltan configuraciones.')
    return '\n'.join(lines)[:3900]


def _v190_recovery_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows=[]
    best = _v190_best_state_candidate()
    if best:
        rows.append([InlineKeyboardButton('🧯 Recuperar mejor state encontrado', callback_data=f'statefix|restore_best|{chat_id}')])
    rows.append([InlineKeyboardButton('🔎 Reescanear volumen', callback_data=f'statefix|scan|{chat_id}')])
    rows.append([InlineKeyboardButton('✅ Comprobar bot', callback_data=f'checkbot|{chat_id}'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v190_statefix_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('statefix|'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id if update.effective_chat else 0)
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True); raise _V190Stop
    if action == 'restore_best':
        best = _v190_best_state_candidate()
        if not best:
            await q.answer('No encontré backup válido.', show_alert=True); raise _V190Stop
        ok = _v190_restore_from_path(best, make_backup=True)
        await q.answer('Recuperado ✅' if ok else 'No pude recuperar. Mira logs.', show_alert=True)
        try:
            await q.edit_message_text(_v190_recovery_text(), parse_mode=ParseMode.HTML, reply_markup=_v190_recovery_markup(chat_id))
        except Exception:
            pass
        raise _V190Stop
    if action == 'scan':
        _v190_best_state_candidate()
        await q.answer('Volumen reescaneado')
        await q.edit_message_text(_v190_recovery_text(), parse_mode=ParseMode.HTML, reply_markup=_v190_recovery_markup(chat_id))
        raise _V190Stop


