    extra = ['','<b>Recuperación V190</b>', f'🧯 Candidatos de estado: <b>{len(_V190_RECOVERY_REPORT)}</b>']
    if _V190_RECOVERY_REPORT:
        extra.append('Mejor candidato:')
        extra.append(h(_V190_RECOVERY_REPORT[0]))
    return (base + '\n' + '\n'.join(extra))[:3900]


