try:
    from telegram.ext import ApplicationHandlerStop as _V191Stop
except Exception:
    _V191Stop = Exception


def _v191_candidate_entries() -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    seen=set()
    try:
        paths = _v190_candidate_paths() if '_v190_candidate_paths' in globals() else []
    except Exception:
        paths = []
    for p in paths:
        try:
            p = Path(p)
            rp = str(p.resolve()) if p.exists() else str(p)
            if rp in seen or not p.exists() or not p.is_file():
                continue
            seen.add(rp)
            chats, typ = _v190_score_state_file(p) if '_v190_score_state_file' in globals() else (0, 'unknown')
            size = p.stat().st_size
            if chats <= 0 and size < 20:
                continue
            entries.append({'path': p, 'chats': int(chats or 0), 'type': typ, 'size': int(size or 0), 'is_current': False})
        except Exception:
            continue
    try:
        cur = Path(STATE_PATH).resolve()
        for e in entries:
            try:
                e['is_current'] = e['path'].resolve() == cur
            except Exception:
                e['is_current'] = False
    except Exception:
        pass
    entries.sort(key=lambda e: (int(e.get('chats',0)), 1 if str(e.get('path')).endswith('state.json') else 0, int(e.get('size',0))), reverse=True)
    return entries


def _v191_recovery_text() -> str:
    entries = _v191_candidate_entries()
    lines = [
        '<b>🧯 Recuperación de datos V191</b>',
        '',
        f'📂 STATE_PATH actual: <code>{h(str(STATE_PATH))}</code>',
        f'📦 Grupos cargados ahora: <b>{len(STATE_CACHE)}</b>',
        '',
        '<b>Candidatos encontrados:</b>'
    ]
    if not entries:
        lines.append('No encontré candidatos útiles en el volumen.')
    else:
        for i,e in enumerate(entries[:10], start=1):
            cur = ' · <b>ACTUAL</b>' if e.get('is_current') else ''
            lines.append(f'{i}. <code>{h(str(e["path"]))}</code> · chats=<b>{e["chats"]}</b> · bytes={e["size"]} · {h(str(e["type"]))}{cur}')
    if entries and entries[0].get('is_current'):
        lines.append('\n⚠️ El mejor candidato es el <b>state actual</b>. Restaurarlo no cambiará nada. Si faltan recurrentes, puede que estén en otro archivo con menos chats o que nunca se guardaran en este state.')
    else:
        lines.append('\nPulsa un candidato para restaurarlo. Antes se hará copia del state actual.')
    return '\n'.join(lines)[:3900]


def _v191_recovery_markup(chat_id: int) -> InlineKeyboardMarkup:
    entries = _v191_candidate_entries()
    rows=[]
    for i,e in enumerate(entries[:8], start=1):
        label = f'🧯 Restaurar #{i} · chats {e["chats"]}'
        if e.get('is_current'):
            label = f'📌 #{i} actual · chats {e["chats"]}'
        rows.append([InlineKeyboardButton(label, callback_data=f'statefix191|restore|{chat_id}|{i-1}')])
    rows.append([InlineKeyboardButton('🔎 Reescanear volumen', callback_data=f'statefix191|scan|{chat_id}')])
    rows.append([InlineKeyboardButton('✅ Comprobar bot', callback_data=f'checkbot|{chat_id}'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v191_statefix_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('statefix191|'):
        return
    parts = q.data.split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id if update.effective_chat else 0)
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True); raise _V191Stop
    if action == 'scan':
        try:
            _v190_best_state_candidate()
        except Exception:
            pass
        await q.answer('Volumen reescaneado')
        await q.edit_message_text(_v191_recovery_text(), parse_mode=ParseMode.HTML, reply_markup=_v191_recovery_markup(chat_id))
        raise _V191Stop
    if action == 'restore':
        try:
            idx = int(parts[3])
        except Exception:
            await q.answer('Índice inválido.', show_alert=True); raise _V191Stop
        entries = _v191_candidate_entries()
        if not (0 <= idx < len(entries)):
            await q.answer('Candidato no encontrado.', show_alert=True); raise _V191Stop
        path = entries[idx]['path']
        if entries[idx].get('is_current'):
            await q.answer('Ese ya es el state actual. No cambia nada.', show_alert=True)
            raise _V191Stop
        ok = _v190_restore_from_path(path, make_backup=True) if '_v190_restore_from_path' in globals() else False
        await q.answer('Recuperado ✅ Reinicia si no ves cambios.' if ok else 'No pude recuperar. Mira logs.', show_alert=True)
        try:
            await q.edit_message_text(_v191_recovery_text(), parse_mode=ParseMode.HTML, reply_markup=_v191_recovery_markup(chat_id))
        except Exception:
            pass
        raise _V191Stop


async def _v191_health_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('checkbot|') or data.startswith('cfg|botcheck|')):
        return
    try:
        chat_id = int(data.split('|')[-1])
    except Exception:
        return
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True); raise _V191Stop
    await q.answer('Comprobando…')
    try:
        text = await _v189_health_text(context, chat_id)
    except Exception:
        text = '<b>✅ COMPROBAR BOT V191</b>\n\nNo pude generar diagnóstico completo.'
    entries = _v191_candidate_entries()
    best_line = ''
    if entries:
        best_line = f'\n\n<b>Recuperación V191</b>\n🧯 Candidatos: <b>{len(entries)}</b> · Mejor: chats={entries[0]["chats"]} · {"actual" if entries[0].get("is_current") else "restaurable"}'
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('🔄 Repetir', callback_data=f'checkbot|{chat_id}')],
        [InlineKeyboardButton('🧯 Recuperación de datos', callback_data=f'statefix191|scan|{chat_id}')],
        [InlineKeyboardButton('🌞 Enviar frase ahora', callback_data=f'cfg|phrase_send|{chat_id}|daily_phrase'), InlineKeyboardButton('🔁 Recurrentes', callback_data=f'cfg|block|{chat_id}|recurrentes')],
        [InlineKeyboardButton('⚙️ Ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])
    try:
        await q.edit_message_text((text + best_line)[:3900], parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html((text + best_line)[:3900], reply_markup=markup)
    raise _V191Stop


_old_build_application_v191 = build_application

def build_application() -> Application:
    app = _old_build_application_v191()
    app.add_handler(CallbackQueryHandler(_v191_health_router, pattern=r'^(checkbot\|-?\d+|cfg\|botcheck\|-?\d+)$'), group=-21000000000)
    app.add_handler(CallbackQueryHandler(_v191_statefix_router, pattern=r'^statefix191\|'), group=-21000000000)
    logger.info('V191 recuperación visible cargada')
    return app


