def _v192_panel_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    pcfg = cfg.setdefault('panel_config_v171', {})
    if not isinstance(pcfg, dict) or not pcfg.get('blocks'):
        old_labels = {}
        if isinstance(pcfg, dict):
            old_labels = dict(pcfg.get('panel_item_labels') or {})
        pcfg = _v192_recommended_panel(chat_id)
        pcfg['panel_item_labels'] = old_labels
        cfg['panel_config_v171'] = pcfg
        try: save_all_states()
        except Exception: pass
    pcfg.setdefault('panel_item_labels', {})
    pcfg.setdefault('loose_items', [])
    pcfg.setdefault('hidden_items', [])
    pcfg.setdefault('top_fields', _v192_recommended_panel(chat_id)['top_fields'])
    return pcfg


