def _v192_label(chat_id: int, key: str) -> str:
    key = str(key)
    try:
        labels = _v192_panel_cfg(chat_id).get('panel_item_labels') or {}
        if str(labels.get(key) or '').strip():
            return str(labels[key])[:64]
    except Exception:
        pass
    try:
        if '_v186_label' in globals() and key.startswith(('recsend_', 'rblksend_')):
            return _v186_label(chat_id, key)
    except Exception:
        pass
    try:
        return str(_v171_available_panel_items().get(key, {}).get('label') or key)
    except Exception:
        return key


