def _v186_label(chat_id: int, key: str) -> str:

    key = str(key)
    if key.startswith('recsend_'):
        try:
            rid = int(key.split('_', 1)[1])
            row = recurring_find(chat_id, rid)
            name = str((row or {}).get('name') or (row or {}).get('title') or f'Recurrente {rid}')
            return (_v192_panel_cfg(chat_id).get('panel_item_labels') or {}).get(key) or ('🔁 ' + truncated_button_title(f'Enviar · {name}', 45))
        except Exception:
            pass
    if key.startswith('rblksend_'):
        try:
            bid = int(key.split('_', 1)[1])
            name = f'Bloque {bid}'
            for b in (_v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []):
                if int(b.get('id', 0) or 0) == bid:
                    name = str(b.get('name') or name); break
            return (_v192_panel_cfg(chat_id).get('panel_item_labels') or {}).get(key) or ('📦 ' + truncated_button_title(f'Lanzar · {name}', 45))
        except Exception:
            pass
    return _v192_label(chat_id, key)


def _v192_cb(chat_id: int, key: str) -> str:
    key = str(key)
    if key.startswith('recsend_'):
        try: return f'panelrun|rec|{chat_id}|{int(key.split("_", 1)[1])}'
        except Exception: pass
    if key.startswith('rblksend_'):
        try: return f'panelrun|rblk|{chat_id}|{int(key.split("_", 1)[1])}'
        except Exception: pass
    cb = str(_v171_available_panel_items().get(key, {}).get('cb') or f'panelcfg|control|{chat_id}|{key}')
    return cb.format(chat_id=chat_id)


