async def _v192_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('p192|'):
        return
    parts = q.data.split('|')
    action = parts[1]
    chat_id = int(parts[2])
    if action == 'template':
        old = _v192_panel_cfg(chat_id)
        labels = dict(old.get('panel_item_labels') or {})
        cfg = admin_cfg(chat_id)
        cfg['panel_config_v171'] = _v192_recommended_panel(chat_id)
        cfg['panel_config_v171']['panel_item_labels'] = labels
        save_all_states()
        await q.answer('Panel recomendado aplicado ✅')
        await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
        raise _V192Stop


