try:
    from telegram.ext import ApplicationHandlerStop as _V194Stop
except Exception:
    _V194Stop = Exception

V194_SILENCE_SECONDS = max(600, env_int('DJ_SILENCE_SECONDS', '3600'))
V194_SILENCE_PATH = DOWNLOAD_DIR / 'djplan_silence_join.ogg'


def _v194_client_connected(client) -> bool:
    try:
        value = client.is_connected()
        return bool(value() if callable(value) else value)
    except Exception:
        return False


def _v194_ensure_silence_file() -> str:
    """Crea un OGG OPUS silencioso para forzar la entrada del userbot al directo."""
    try:
        if V194_SILENCE_PATH.exists() and V194_SILENCE_PATH.stat().st_size > 1024:
            return str(V194_SILENCE_PATH)
    except Exception:
        pass
    V194_SILENCE_PATH.parent.mkdir(parents=True, exist_ok=True)
    try:
        subprocess.run(
            [
                'ffmpeg', '-y',
                '-f', 'lavfi',
                '-i', 'anullsrc=channel_layout=stereo:sample_rate=48000',
                '-t', str(int(V194_SILENCE_SECONDS)),
                '-vn', '-c:a', 'libopus', '-b:a', '8k', '-application', 'audio',
                str(V194_SILENCE_PATH),
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
        )
        return str(V194_SILENCE_PATH)
    except Exception:
        logger.exception('V194 no pudo crear silencio con ffmpeg; creo WAV temporal corto')

        import wave
        wav = DOWNLOAD_DIR / 'djplan_silence_join.wav'
        rate = 48000
        seconds = 30
        with wave.open(str(wav), 'wb') as w:
            w.setnchannels(2)
            w.setsampwidth(2)
            w.setframerate(rate)
            w.writeframes(b'\x00\x00' * 2 * rate * seconds)
        return str(wav)


async def _v194_voice_ensure_ready(self, application: Optional[Application] = None) -> None:
    """Reinicia Telethon/PyTgCalls si quedó a medias en Railway."""
    if application is not None:
        self.application = application
    if self.client is None or not _v194_client_connected(self.client):
        self.client = TelegramClient(load_userbot_string_session(), API_ID, API_HASH)
        await self.client.start()
    if self.calls is None:
        self.calls = PyTgCalls(self.client)
        await self.calls.start()


async def _v194_voice_start(self, application: Application) -> None:
    global WATCHDOG_TASK
    self.application = application
    await self.ensure_ready(application)
    if WATCHDOG_TASK is None or WATCHDOG_TASK.done():
        WATCHDOG_TASK = asyncio.create_task(_watchdog_loop())
    try:
        me = await self.client.get_me() if self.client else None
        logger.info('V194 userbot iniciado: %s (%s)', getattr(me, 'username', None) or getattr(me, 'first_name', 'sin nombre'), getattr(me, 'id', 'sin id'))
    except Exception:
        logger.info('V194 userbot iniciado')


async def _v194_ensure_videochat_started(self, chat_id: int) -> bool:
    await self.ensure_ready(self.application)
    if not self.client:
        return False
    existing = await self._get_input_group_call(chat_id)
    if existing:
        return True
    try:
        entity = await self.client.get_entity(chat_id)
        await self.client(functions.phone.CreateGroupCallRequest(peer=entity, title='DJ-PLAN'))

        for _ in range(5):
            await asyncio.sleep(0.6)
            if await self._get_input_group_call(chat_id):
                logger.info('V194 videochat iniciado en chat %s', chat_id)
                return True
        logger.warning('V194 creó videochat pero no pudo confirmarlo en chat %s', chat_id)
        return True
    except Exception as e:

        low = str(e).lower()
        if any(x in low for x in ('already', 'already exists', 'groupcall', 'call')):
            if await self._get_input_group_call(chat_id):
                return True
        logger.exception('V194 no pudo iniciar/confirmar videochat en chat %s', chat_id)
        return False


async def _v194_try_pytgcalls_play(calls, chat_id: int, file_path: str) -> None:
    """Compatibilidad PyTgCalls: prueba APIs nuevas y antiguas."""
    errors: List[str] = []

    async def attempt(label: str, coro_factory) -> bool:
        try:
            await coro_factory()
            logger.info('V194 PyTgCalls OK con método %s en chat %s', label, chat_id)
            return True
        except Exception as e:
            errors.append(f'{label}: {type(e).__name__}: {str(e)[:220]}')
            return False


    play = getattr(calls, 'play', None)
    if callable(play):
        if await attempt('play(path)', lambda: play(chat_id, file_path)):
            return

        try:
            from pytgcalls.types import MediaStream
            if await attempt('play(MediaStream)', lambda: play(chat_id, MediaStream(file_path))):
                return
        except Exception as e:
            errors.append(f'import MediaStream: {type(e).__name__}: {str(e)[:180]}')


    join_group_call = getattr(calls, 'join_group_call', None)
    if callable(join_group_call):
        try:
            from pytgcalls.types.input_stream import AudioPiped
            if await attempt('join_group_call(AudioPiped)', lambda: join_group_call(chat_id, AudioPiped(file_path))):
                return
        except Exception as e:
            errors.append(f'import AudioPiped: {type(e).__name__}: {str(e)[:180]}')


    change_stream = getattr(calls, 'change_stream', None)
    if callable(change_stream):
        try:
            from pytgcalls.types.input_stream import AudioPiped
            if await attempt('change_stream(AudioPiped)', lambda: change_stream(chat_id, AudioPiped(file_path))):
                return
        except Exception as e:
            errors.append(f'import/change_stream AudioPiped: {type(e).__name__}: {str(e)[:180]}')

    raise RuntimeError('PyTgCalls no pudo reproducir/entrar. ' + ' | '.join(errors[-6:]))


async def _v194_play_file(self, chat_id: int, file_path: str) -> None:
    await self.ensure_ready(self.application)
    if not self.calls:
        raise RuntimeError('Voice engine no iniciado')
    ok_call = await self.ensure_videochat_started(chat_id)
    if not ok_call:
        raise RuntimeError('No hay videochat activo y el userbot no pudo crearlo. Abre el videochat manualmente y vuelve a pulsar LIVE.')
    if not file_path or not Path(file_path).exists():
        raise RuntimeError(f'Archivo de audio no existe: {file_path}')
    await _v194_try_pytgcalls_play(self.calls, chat_id, file_path)


async def _v194_join_silence(self, chat_id: int) -> None:
    """Entra al videochat aunque no haya canción todavía."""
    silence = _v194_ensure_silence_file()
    await self.play_file(chat_id, silence)
    state = get_state(chat_id)
    state.live_enabled = True
    state.paused = False
    state.now_playing = None
    state.play_started_at = None
    state.paused_remaining = None
    save_all_states()
    if self.application:
        await ensure_panel(self.application.bot, chat_id)
        await ensure_control_panel(self.application.bot, chat_id)


async def _v194_play_track(self, bot, chat_id: int, track: Track) -> None:
    import time as _time
    state = get_state(chat_id)
    await self.ensure_ready(self.application)
    if not await self.ensure_videochat_started(chat_id):
        raise RuntimeError('No pude abrir/encontrar el videochat. Ábrelo manualmente desde el nombre del grupo y vuelve a pulsar reproducir.')
    if not track.local_path or not Path(track.local_path).exists():
        track = await materialize_track(bot, chat_id, track)
    if track.duration <= 0 and track.local_path and Path(track.local_path).exists():
        track.duration = probe_duration_seconds(track.local_path)
    await self.play_file(chat_id, track.local_path)
    await self._apply_volume(chat_id, state.volume)
    state.live_enabled = True
    state.now_playing = asdict(track)
    state.paused = False
    state.play_started_at = int(_time.time())
    state.paused_remaining = None
    save_all_states()
    await ensure_panel(bot, chat_id)
    await ensure_control_panel(bot, chat_id)
    await cleanup_old_files(chat_id)
    await schedule_auto_next(chat_id, track.duration, state.auto_sig_seconds)


async def _v194_toggle_live(self, chat_id: int) -> bool:
    state = get_state(chat_id)
    await self.ensure_ready(self.application)

    if state.live_enabled:
        if state.now_playing:
            current = dict(state.now_playing)
            current_key = track_key(current)
            first_key = track_key(state.queue[0]) if state.queue else ''
            if not state.queue or current_key != first_key:
                state.queue.insert(0, current)
        state.live_enabled = False
        state.now_playing = None
        state.paused = False
        state.play_started_at = None
        state.paused_remaining = None
        save_all_states()
        await cancel_auto_next(chat_id)
        await self.leave(chat_id, end_videochat=True)
        if self.application:
            await ensure_panel(self.application.bot, chat_id)
            await ensure_control_panel(self.application.bot, chat_id)
        return False

    state.live_enabled = True
    state.paused = False
    save_all_states()

    if state.queue:
        await self.play_next_from_queue(chat_id)
    else:
        await self.join_silence(chat_id)
    return True


async def _v194_leave(self, chat_id: int, *, end_videochat: bool = False) -> None:
    await cancel_auto_next(chat_id)
    if self.calls:
        for name in ('leave_call', 'leave_group_call'):
            method = getattr(self.calls, name, None)
            if callable(method):
                try:
                    await method(chat_id)
                    break
                except Exception:
                    pass
    if end_videochat:
        await self.end_videochat(chat_id)


async def _v194_dj_live_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    if (q.data or '') not in {'panel_live_toggle', 'panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    try:
        allowed = await is_controller(context, chat_id, int(update.effective_user.id))
    except Exception:
        allowed = False
    if not allowed:
        await q.answer('No estás autorizado para controlar DJ-PRO.', show_alert=True)
        raise _V194Stop
    try:
        await q.answer('Activando directo…' if not get_state(chat_id).live_enabled else 'Cerrando directo…')
        live = await VOICE.toggle_live(chat_id)
        if live:
            msg = '✅ Userbot dentro del videochat. Si no lo ves al instante, espera 2-3 segundos y abre el videochat.'
            try:
                url = await build_live_join_url(context.bot, chat_id)
                if url:
                    await q.answer(msg, url=url)
                else:
                    await q.answer(msg, show_alert=True)
            except Exception:
                await q.answer(msg, show_alert=True)
        else:
            await q.answer('Directo cerrado ✅')
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
    except Exception as e:
        logger.exception('V194 error activando DJ-PRO/userbot')
        await q.answer('No pude meter el userbot. Mira logs y ejecuta /djdiag.', show_alert=True)
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text='❌ <b>DJ-PRO no pudo entrar al videochat</b>\n\n<code>' + h(str(e)[-1200:]) + '</code>\n\nPrueba: abre el videochat manualmente desde el nombre del grupo y pulsa LIVE otra vez. También puedes ejecutar /djdiag.',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    raise _V194Stop


async def djdiag_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    lines = ['<b>🧪 Diagnóstico DJ-PRO / Userbot</b>', '']
    try:
        await VOICE.ensure_ready(context.application)
        lines.append('✅ Telethon/Userbot: iniciado')
    except Exception as e:
        lines.append('❌ Telethon/Userbot: error')
        lines.append('<code>' + h(str(e)[-700:]) + '</code>')
    try:
        me = await VOICE.client.get_me() if VOICE.client else None
        lines.append(f'👤 Userbot: <b>{h(getattr(me, "username", None) or getattr(me, "first_name", "sin nombre"))}</b> · <code>{h(getattr(me, "id", "?"))}</code>')
    except Exception as e:
        lines.append('⚠️ No pude leer usuario Telethon: <code>' + h(str(e)[-400:]) + '</code>')
    lines.append('✅ PyTgCalls: iniciado' if VOICE.calls else '❌ PyTgCalls: no iniciado')
    try:
        entity = await VOICE.client.get_entity(chat_id) if VOICE.client else None
        lines.append(f'✅ Grupo accesible por userbot: <b>{h(getattr(entity, "title", chat_id))}</b>')
    except Exception as e:
        lines.append('❌ El userbot NO accede a este grupo. Añade esa cuenta al grupo y dale permisos suficientes.')
        lines.append('<code>' + h(str(e)[-700:]) + '</code>')
    try:
        call = await VOICE._get_input_group_call(chat_id)
        lines.append('✅ Videochat detectado' if call else '⚠️ No hay videochat detectado ahora')
    except Exception as e:
        lines.append('⚠️ Error leyendo videochat: <code>' + h(str(e)[-500:]) + '</code>')
    st = get_state(chat_id)
    lines.append('')
    lines.append(f'🎛 DJ mode: <b>{bool_label(st.dj_mode)}</b>')
    lines.append(f'🔴 LIVE: <b>{bool_label(st.live_enabled)}</b>')
    lines.append(f'📋 Cola: <b>{len(st.queue)}</b>')
    lines.append(f'▶️ Sonando: <b>{h((st.now_playing or {}).get("title") or "Nada")}</b>')
    lines.append('')
    lines.append('Botón recomendado: pulsa <b>LIVE ON</b>. Si no hay canciones, el userbot entrará con silencio.')
    await update.message.reply_html('\n'.join(lines))


VoiceEngine.ensure_ready = _v194_voice_ensure_ready
VoiceEngine.start = _v194_voice_start
VoiceEngine.ensure_videochat_started = _v194_ensure_videochat_started
VoiceEngine.play_file = _v194_play_file
VoiceEngine.play_track = _v194_play_track
VoiceEngine.toggle_live = _v194_toggle_live
VoiceEngine.join_silence = _v194_join_silence
VoiceEngine.leave = _v194_leave

_old_build_application_v194 = build_application

def build_application() -> Application:
    app = _old_build_application_v194()
    app.add_handler(CallbackQueryHandler(_v194_dj_live_router, pattern=r'^(panel_live_toggle|panel_pause_resume)$'), group=-21000000000)
    app.add_handler(CommandHandler('djdiag', djdiag_command), group=-21000000000)
    logger.info('V194 DJ-PRO userbot join real + silencio + /djdiag cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V195Stop
except Exception:
    _V195Stop = Exception

VOICE_CHAT_PEER_RAW = os.getenv('VOICE_CHAT_PEER', '').strip()
VOICE_CHAT_PEERS_RAW = os.getenv('VOICE_CHAT_PEERS', '').strip()
VOICE_CHAT_INVITE_HASH = os.getenv('VOICE_CHAT_INVITE_HASH', '').strip()
VOICE_JOIN_AS_RAW = os.getenv('VOICE_JOIN_AS', 'self').strip()


def _v195_parse_peer_map(raw: str) -> Dict[int, str]:
    result: Dict[int, str] = {}
    for part in (raw or '').split(','):
        part = part.strip()
        if not part or '=' not in part:
            continue
        left, right = part.split('=', 1)
        left = left.strip(); right = right.strip()
        if not left or not right:
            continue
        try:
            result[int(left)] = right
        except Exception:
            logger.warning('VOICE_CHAT_PEERS entrada inválida ignorada: %r', part)
    return result


VOICE_CHAT_PEERS = _v195_parse_peer_map(VOICE_CHAT_PEERS_RAW)


def _v195_group_ref_for_chat(chat_id: int) -> Any:
    """Permite forzar el peer usado por Telethon/PyTgCalls.

    Normalmente se usa el chat_id del bot (-100...). Si tu sesión Telethon no
    resuelve bien ese id, define en Railway:
      VOICE_CHAT_PEER=@usuarioDelGrupo
    o para varios grupos:
      VOICE_CHAT_PEERS=-100111=@grupo1,-100222=@grupo2
    """
    cfg = {}
    try:
        cfg = admin_cfg(chat_id)
    except Exception:
        cfg = {}
    for key in ('voice_chat_peer', 'dj_voice_peer', 'userbot_peer'):
        value = str((cfg or {}).get(key) or '').strip()
        if value:
            return value
    if int(chat_id) in VOICE_CHAT_PEERS:
        return VOICE_CHAT_PEERS[int(chat_id)]
    if VOICE_CHAT_PEER_RAW:
        return VOICE_CHAT_PEER_RAW
    return int(chat_id)


async def _v195_resolve_input_entity(self, chat_id: int):
    await self.ensure_ready(self.application)
    if not self.client:
        raise RuntimeError('Userbot/Telethon no iniciado')
    ref = _v195_group_ref_for_chat(chat_id)
    return await self.client.get_input_entity(ref)


async def _v195_resolve_entity(self, chat_id: int):
    await self.ensure_ready(self.application)
    if not self.client:
        raise RuntimeError('Userbot/Telethon no iniciado')
    ref = _v195_group_ref_for_chat(chat_id)
    return await self.client.get_entity(ref)


async def _v195_resolve_join_as(self, chat_id: int):
    """Fuerza join_as personal por defecto.

    Algunas cuentas/grupos tienen groupcall_default_join_as configurado como canal.
    Eso puede romper JoinGroupCall. Por eso usamos SELF salvo que se indique
    VOICE_JOIN_AS=default o VOICE_JOIN_AS=@canal.
    """
    if not self.client:
        return None
    raw = (VOICE_JOIN_AS_RAW or 'self').strip()
    if not raw or raw.lower() == 'default':
        return None
    if raw.lower() in ('self', 'me', 'userbot', 'usuario'):
        try:
            return await self.client.get_me(input_peer=True)
        except Exception:
            return None
    try:
        return await self.client.get_input_entity(raw)
    except Exception:
        logger.exception('VOICE_JOIN_AS no se pudo resolver: %s', raw)
        return None


async def _v195_get_input_group_call(self, chat_id: int):
    if not self.client:
        return None
    try:
        entity = await _v195_resolve_entity(self, chat_id)
        if getattr(entity, 'megagroup', False) or getattr(entity, 'broadcast', False):
            full = await self.client(functions.channels.GetFullChannelRequest(channel=entity))
        else:
            real_id = getattr(entity, 'id', abs(int(chat_id)))
            full = await self.client(functions.messages.GetFullChatRequest(chat_id=abs(int(real_id))))
        full_chat = getattr(full, 'full_chat', None)
        call = getattr(full_chat, 'call', None) if full_chat else None
        if not call:
            return None
        call_id = getattr(call, 'id', None)
        access_hash = getattr(call, 'access_hash', None)
        if call_id is None or access_hash is None:
            return None
        return types.InputGroupCall(id=call_id, access_hash=access_hash)
    except Exception:
        logger.exception('V195 no pudo obtener group call en chat %s', chat_id)
        return None


async def _v195_ensure_videochat_started(self, chat_id: int) -> bool:
    await self.ensure_ready(self.application)
    if not self.client:
        return False
    existing = await self._get_input_group_call(chat_id)
    if existing:
        return True
    try:
        entity = await _v195_resolve_entity(self, chat_id)
        await self.client(functions.phone.CreateGroupCallRequest(peer=entity, title='DJ-PLAN'))
        for _ in range(8):
            await asyncio.sleep(0.7)
            if await self._get_input_group_call(chat_id):
                logger.info('V195 videochat iniciado/confirmado en chat %s', chat_id)
                return True

        logger.warning('V195 creó videochat pero no pudo confirmarlo inmediatamente en chat %s', chat_id)
        return True
    except Exception as e:
        low = str(e).lower()
        if any(x in low for x in ('already', 'exists', 'groupcall', 'call')):
            if await self._get_input_group_call(chat_id):
                return True
        logger.exception('V195 no pudo iniciar/confirmar videochat en chat %s', chat_id)
        return False


async def _v195_restart_calls(self) -> None:
    try:
        if self.calls:
            stop = getattr(self.calls, 'stop', None)
            if callable(stop):
                res = stop()
                if hasattr(res, '__await__'):
                    await res
    except Exception:
        pass
    self.calls = None
    await self.ensure_ready(self.application)


async def _v195_call_with_optional_kwargs(method, group_ref, stream_obj, join_as, invite_hash: str):

    attempts = []
    if join_as is not None and invite_hash:
        attempts.append({'join_as': join_as, 'invite_hash': invite_hash})
    if join_as is not None:
        attempts.append({'join_as': join_as})
    if invite_hash:
        attempts.append({'invite_hash': invite_hash})
    attempts.append({})
    last_exc = None
    for kwargs in attempts:
        try:
            return await method(group_ref, stream_obj, **kwargs)
        except TypeError as e:
            last_exc = e
            continue
        except Exception as e:
            last_exc = e
            raise
    if last_exc:
        raise last_exc


async def _v195_try_pytgcalls_play(self, chat_id: int, file_path: str) -> None:
    """Prueba varias referencias de grupo y fuerza join_as personal."""
    if not self.calls:
        raise RuntimeError('PyTgCalls no iniciado')
    if not file_path or not Path(file_path).exists():
        raise RuntimeError(f'Archivo de audio no existe: {file_path}')

    ref = _v195_group_ref_for_chat(chat_id)
    join_as = await _v195_resolve_join_as(self, chat_id)
    input_entity = None
    entity = None
    try:
        input_entity = await _v195_resolve_input_entity(self, chat_id)
    except Exception:
        logger.exception('V195 no pudo resolver input_entity para %s', ref)
    try:
        entity = await _v195_resolve_entity(self, chat_id)
    except Exception:
        logger.exception('V195 no pudo resolver entity para %s', ref)

    group_candidates: List[Any] = []
    for item in (input_entity, entity, ref, int(chat_id)):
        if item is None:
            continue
        if item not in group_candidates:
            group_candidates.append(item)

    stream_candidates: List[Tuple[str, Any]] = [('path', file_path)]
    try:
        from pytgcalls.types import MediaStream
        stream_candidates.insert(0, ('MediaStream', MediaStream(file_path)))
    except Exception as e:
        logger.info('V195 MediaStream no disponible: %s', e)

    errors: List[str] = []
    play = getattr(self.calls, 'play', None)
    if callable(play):
        for group_ref in group_candidates:
            for stream_label, stream_obj in stream_candidates:
                label = f'play({type(group_ref).__name__},{stream_label})'
                try:
                    await _v195_call_with_optional_kwargs(play, group_ref, stream_obj, join_as, VOICE_CHAT_INVITE_HASH)
                    logger.info('V195 PyTgCalls OK con %s en chat %s', label, chat_id)
                    return
                except Exception as e:
                    errors.append(f'{label}: {type(e).__name__}: {str(e)[:260]}')
                    low = f'{type(e).__name__}: {e}'.lower()
                    if 'groupcallinvalid' in low or 'specified group call is invalid' in low:

                        try:
                            await _v195_restart_calls(self)
                        except Exception:
                            pass


    join_group_call = getattr(self.calls, 'join_group_call', None)
    if callable(join_group_call):
        try:
            from pytgcalls.types.input_stream import AudioPiped
            for group_ref in group_candidates:
                try:
                    await join_group_call(group_ref, AudioPiped(file_path))
                    logger.info('V195 PyTgCalls OK con join_group_call en chat %s', chat_id)
                    return
                except Exception as e:
                    errors.append(f'join_group_call({type(group_ref).__name__}): {type(e).__name__}: {str(e)[:260]}')
        except Exception as e:
            errors.append(f'import AudioPiped: {type(e).__name__}: {str(e)[:200]}')

    detail = ' | '.join(errors[-10:])
    hint = (
        'No he conseguido entrar al videochat. Revisa: '
        '1) la cuenta USERBOT_SESSION está dentro del grupo; '
        '2) el videochat está realmente activo; '
        '3) si el grupo es privado, define VOICE_CHAT_PEER=@usuarioDelGrupo o VOICE_CHAT_PEERS=-100xxxx=@usuario; '
        '4) prueba VOICE_JOIN_AS=self.'
    )
    raise RuntimeError(hint + '\n\nDetalle: ' + detail)


async def _v195_play_file(self, chat_id: int, file_path: str) -> None:
    await self.ensure_ready(self.application)
    if not await self.ensure_videochat_started(chat_id):
        raise RuntimeError('No hay videochat activo y el userbot no pudo crearlo. Abre el videochat manualmente y vuelve a pulsar LIVE.')
    await _v195_try_pytgcalls_play(self, chat_id, file_path)


async def _v195_join_silence(self, chat_id: int) -> None:
    silence = _v194_ensure_silence_file() if '_v194_ensure_silence_file' in globals() else str(DOWNLOAD_DIR / 'djplan_silence_join.ogg')
    await self.play_file(chat_id, silence)
    state = get_state(chat_id)
    state.live_enabled = True
    state.paused = False
    state.now_playing = None
    state.play_started_at = None
    state.paused_remaining = None
    save_all_states()
    if self.application:
        await ensure_panel(self.application.bot, chat_id)
        await ensure_control_panel(self.application.bot, chat_id)


def _v195_panelcfg_markup(chat_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎛 Todos los controles', callback_data=f'panelcfg|all|{chat_id}|0')],
        [InlineKeyboardButton('🧺 Botones sin asignar', callback_data=f'panelcfg|unassigned|{chat_id}|0')],
        [InlineKeyboardButton('🧩 Editar bloques/botones', callback_data=f'panelcfg|blocks|{chat_id}')],
        [InlineKeyboardButton('🔝 Menú de resumen rápido', callback_data=f'panelcfg|top|{chat_id}')],
        [InlineKeyboardButton('➕ Añadir bloque', callback_data=f'panelcfg|addblock|{chat_id}'), InlineKeyboardButton('♻️ Reset panel', callback_data=f'panelcfg|reset|{chat_id}')],
        [InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])


def _v195_known_key(chat_id: int, key: str) -> bool:
    try:
        return bool(_v182_is_known(chat_id, key))
    except Exception:
        pass
    try:
        return bool(_v178_known_key(chat_id, key))
    except Exception:
        pass
    try:
        return key in _v171_available_panel_items()
    except Exception:
        return False


def _v195_all_keys(chat_id: int) -> List[str]:
    keys: List[str] = []
    for fn in ('_v182_all_keys', '_v177_all_keys'):
        try:
            f = globals().get(fn)
            if not callable(f):
                continue
            try:
                arr = list(f(chat_id))
            except TypeError:
                arr = list(f())
            for k in arr:
                if k not in keys and _v195_known_key(chat_id, k):
                    keys.append(str(k))
        except Exception:
            pass
    try:
        for k in _v171_available_panel_items().keys():
            if k not in keys and _v195_known_key(chat_id, k):
                keys.append(str(k))
    except Exception:
        pass
    return [k for k in keys if k != 'change_group']


def _v195_panel_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return _v182_panel_cfg(chat_id)
    except Exception:
        try:
            return _v177_panel_cfg(chat_id)
        except Exception:
            return _v171_panel_cfg(chat_id)


def _v195_used_keys(chat_id: int) -> set:
    pcfg = _v195_panel_cfg(chat_id)
    used = set()
    for b in pcfg.get('blocks', []) or []:
        for x in b.get('items', []) or []:
            used.add(str(x))
    for item in pcfg.get('loose_items', []) or []:
        if isinstance(item, dict) and item.get('key'):
            used.add(str(item.get('key')))
    return used


def _v195_unassigned_keys(chat_id: int) -> List[str]:
    pcfg = _v195_panel_cfg(chat_id)
    hidden = set(str(x) for x in (pcfg.get('hidden_items') or []))
    used = _v195_used_keys(chat_id)
    return [k for k in _v195_all_keys(chat_id) if k not in used and k not in hidden]


def _v195_label(chat_id: int, key: str) -> str:
    try:
        return _v182_label(chat_id, key)
    except Exception:
        pass
    try:
        return _v178_label(chat_id, key)
    except Exception:
        pass
    try:
        return _v177_label(chat_id, key)
    except Exception:
        pass
    try:
        d = _v171_available_panel_items().get(key, {})
        return str(d.get('label') or key)
    except Exception:
        return str(key)


def _v195_controls_text(chat_id: int, *, unassigned_only: bool = False) -> str:
    total = len(_v195_unassigned_keys(chat_id) if unassigned_only else _v195_all_keys(chat_id))
    title = '🧺 <b>Botones sin asignar</b>' if unassigned_only else '🎛 <b>Todos los controles</b>'
    return (
        f'{title}\n\n'
        'Aquí puedes ejecutar, renombrar, meter en bloque, dejar suelto u ocultar cualquier botón.\n'
        'Los recurrentes y bloques recurrentes también aparecen aquí.\n\n'
        f'Total: <b>{total}</b>'
    )


def _v195_controls_markup(chat_id: int, *, unassigned_only: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    keys = _v195_unassigned_keys(chat_id) if unassigned_only else _v195_all_keys(chat_id)
    per_page = 5
    max_page = max(0, (len(keys)-1)//per_page)
    page = max(0, min(int(page or 0), max_page))
    chunk = keys[page*per_page:(page+1)*per_page]
    mode = 'unassigned' if unassigned_only else 'all'
    rows: List[List[InlineKeyboardButton]] = []
    if not chunk:
        rows.append([InlineKeyboardButton('No hay botones aquí', callback_data=f'panelnoop|{chat_id}')])
    for key in chunk:
        rows.append([InlineKeyboardButton(_v195_label(chat_id, key), callback_data=f'panelcfg|control|{chat_id}|{key}')])
        rows.append([
            InlineKeyboardButton('➕ Bloque', callback_data=f'p195|choose|{chat_id}|{key}'),
            InlineKeyboardButton('⬇️ Grande', callback_data=f'p195|loose|{chat_id}|{key}|big'),
            InlineKeyboardButton('↔️ Peq.', callback_data=f'p195|loose|{chat_id}|{key}|small'),
            InlineKeyboardButton('✏️', callback_data=f'panelcfg|renameitem|{chat_id}|{key}'),
            InlineKeyboardButton('🚫', callback_data=f'p195|hide|{chat_id}|{key}'),
        ])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'panelcfg|{mode}|{chat_id}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{max_page+1}', callback_data=f'panelnoop|{chat_id}'))
    if page < max_page:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'panelcfg|{mode}|{chat_id}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}'), InlineKeyboardButton('🔙 Ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v195_choose_markup(chat_id: int, key: str) -> InlineKeyboardMarkup:
    pcfg = _v195_panel_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    for i, b in enumerate(pcfg.get('blocks', []) or []):
        title = str(b.get('title') or f'Bloque {i+1}')
        rows.append([InlineKeyboardButton(f'📦 {truncated_button_title(title, 48)}', callback_data=f'p195|assign|{chat_id}|{i}|{key}')])
    rows.append([InlineKeyboardButton('🔙 Todos controles', callback_data=f'panelcfg|all|{chat_id}|0'), InlineKeyboardButton('🧺 Sin asignar', callback_data=f'panelcfg|unassigned|{chat_id}|0')])
    return InlineKeyboardMarkup(rows)


def _v195_assign_to_block(chat_id: int, bi: int, key: str) -> bool:
    if not _v195_known_key(chat_id, key):
        return False
    pcfg = _v195_panel_cfg(chat_id)
    blocks = pcfg.setdefault('blocks', [])
    if not blocks:
        blocks.append({'id': 'base', 'title': '🧩 Principal', 'items': []})
    if not (0 <= int(bi) < len(blocks)):
        return False
    pcfg['hidden_items'] = [x for x in (pcfg.get('hidden_items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    for b in blocks:
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    blocks[int(bi)].setdefault('items', []).append(key)
    save_all_states()
    return True


def _v195_loose(chat_id: int, key: str, size: str) -> bool:
    if not _v195_known_key(chat_id, key):
        return False
    pcfg = _v195_panel_cfg(chat_id)
    for b in pcfg.setdefault('blocks', []):
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    pcfg['hidden_items'] = [x for x in (pcfg.get('hidden_items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    pcfg.setdefault('loose_items', []).append({'key': key, 'size': 'big' if size == 'big' else 'small'})
    save_all_states()
    return True


def _v195_hide(chat_id: int, key: str) -> bool:
    if not _v195_known_key(chat_id, key):
        return False
    pcfg = _v195_panel_cfg(chat_id)
    for b in pcfg.setdefault('blocks', []):
        b['items'] = [str(x) for x in (b.get('items') or []) if str(x) != key]
    pcfg['loose_items'] = [x for x in (pcfg.get('loose_items') or []) if not (isinstance(x, dict) and str(x.get('key')) == key)]
    hidden = pcfg.setdefault('hidden_items', [])
    if key not in hidden:
        hidden.append(key)
    save_all_states()
    return True


async def _v195_panelcfg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2]) if len(parts) > 2 and str(parts[2]).lstrip('-').isdigit() else 0
    except Exception:
        chat_id = 0
    if not chat_id:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V195Stop
    try:
        if action == 'open':
            await q.answer()
            await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v195_panelcfg_markup(chat_id))
            raise _V195Stop
        if action in ('all', 'unassigned'):
            page = int(parts[3]) if len(parts) > 3 and str(parts[3]).lstrip('-').isdigit() else 0
            await q.answer()
            await q.edit_message_text(_v195_controls_text(chat_id, unassigned_only=(action == 'unassigned')), parse_mode=ParseMode.HTML, reply_markup=_v195_controls_markup(chat_id, unassigned_only=(action == 'unassigned'), page=page))
            raise _V195Stop
        if action == 'control':
            key = '|'.join(parts[3:])
            await q.answer()
            try:
                await _v177_execute_key(update, context, chat_id, key)
            except Exception:
                logger.exception('V195 error ejecutando control %s', key)
                await q.answer('No pude ejecutar ese control. Mira logs.', show_alert=True)
            raise _V195Stop
        if action == 'renameitem':
            key = '|'.join(parts[3:])
            set_config_pending(q.from_user.id, {'kind': 'panel_rename_item_v195', 'chat_id': chat_id, 'key': key})
            await q.answer()
            await q.message.reply_html(f'✏️ Envíame el nuevo nombre para el botón:\n<b>{h(_v195_label(chat_id, key))}</b>')
            raise _V195Stop
    except _V195Stop:
        raise
    except Exception:
        logger.exception('V195 error panelcfg: %s', q.data)
        try:
            await q.answer('Error panel V195. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V195Stop


async def _v195_p_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('p195|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V195Stop
    try:
        if action == 'choose':
            key = '|'.join(parts[3:])
            await q.answer()
            await q.edit_message_text(f'<b>➕ Meter en bloque</b>\n\nBotón: <b>{h(_v195_label(chat_id, key))}</b>\n\nElige bloque:', parse_mode=ParseMode.HTML, reply_markup=_v195_choose_markup(chat_id, key))
            raise _V195Stop
        if action == 'assign':
            bi = int(parts[3]); key = '|'.join(parts[4:])
            if _v195_assign_to_block(chat_id, bi, key):
                await q.answer('Añadido al bloque ✅')
                await q.edit_message_text(_v171_panel_block_text(chat_id, bi), parse_mode=ParseMode.HTML, reply_markup=_v171_panel_block_markup(chat_id, bi))
            else:
                await q.answer('No pude añadirlo.', show_alert=True)
            raise _V195Stop
        if action == 'loose':
            key = parts[3]; size = parts[4] if len(parts) > 4 else 'small'
            if _v195_loose(chat_id, key, size):
                await q.answer('Añadido debajo de los bloques ✅')
                await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v195_panelcfg_markup(chat_id))
            else:
                await q.answer('No pude añadirlo.', show_alert=True)
            raise _V195Stop
        if action == 'hide':
            key = '|'.join(parts[3:])
            if _v195_hide(chat_id, key):
                await q.answer('Oculto ✅')
                await q.edit_message_text(_v195_controls_text(chat_id, unassigned_only=True), parse_mode=ParseMode.HTML, reply_markup=_v195_controls_markup(chat_id, unassigned_only=True))
            else:
                await q.answer('No pude ocultarlo.', show_alert=True)
            raise _V195Stop
    except _V195Stop:
        raise
    except Exception:
        logger.exception('V195 error p195: %s', q.data)
        try:
            await q.answer('Error panel V195. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V195Stop


async def _v195_panel_rename_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'panel_rename_item_v195':
        return
    chat_id = int(pending.get('chat_id') or 0)
    key = str(pending.get('key') or '')
    new_name = (update.message.text or update.message.caption or '').strip()
    if not new_name:
        await update.message.reply_html('Envíame un nombre válido.')
        raise _V195Stop
    pcfg = _v195_panel_cfg(chat_id)
    labels = pcfg.setdefault('panel_item_labels', {})
    labels[key] = new_name[:64]
    pop_config_pending(update.effective_user.id)
    save_all_states()
    await update.message.reply_html(f'✅ Nombre cambiado a: <b>{h(new_name[:64])}</b>', reply_markup=_v195_controls_markup(chat_id))
    raise _V195Stop


async def djdiag_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    lines = ['<b>🧪 Diagnóstico DJ-PRO / Userbot V195</b>', '']
    lines.append(f'🆔 Chat bot: <code>{chat_id}</code>')
    lines.append(f'🎯 Peer usado: <code>{h(_v195_group_ref_for_chat(chat_id))}</code>')
    lines.append(f'VOICE_CHAT_PEER: <b>{bool_label(bool(VOICE_CHAT_PEER_RAW))}</b>')
    lines.append(f'VOICE_CHAT_PEERS: <b>{bool_label(bool(VOICE_CHAT_PEERS))}</b>')
    lines.append(f'VOICE_JOIN_AS: <code>{h(VOICE_JOIN_AS_RAW or "self")}</code>')
    try:
        await VOICE.ensure_ready(context.application)
        lines.append('✅ Telethon/Userbot: iniciado')
    except Exception as e:
        lines.append('❌ Telethon/Userbot: error')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        me = await VOICE.client.get_me() if VOICE.client else None
        lines.append(f'👤 Userbot: <b>{h(getattr(me, "username", None) or getattr(me, "first_name", "sin nombre"))}</b> · <code>{h(getattr(me, "id", "?"))}</code>')
    except Exception as e:
        lines.append('⚠️ No pude leer usuario Telethon: <code>' + h(str(e)[-500:]) + '</code>')
    lines.append('✅ PyTgCalls: iniciado' if VOICE.calls else '❌ PyTgCalls: no iniciado')
    try:
        entity = await _v195_resolve_entity(VOICE, chat_id)
        lines.append(f'✅ Grupo accesible por userbot: <b>{h(getattr(entity, "title", chat_id))}</b>')
        lines.append(f'Entity: <code>{h(type(entity).__name__)}</code> · id <code>{h(getattr(entity, "id", "?"))}</code>')
    except Exception as e:
        lines.append('❌ El userbot NO accede a este grupo. Añade esa cuenta al grupo y dale permisos suficientes.')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        call = await VOICE._get_input_group_call(chat_id)
        if call:
            lines.append(f'✅ Videochat detectado · call id <code>{h(getattr(call, "id", "?"))}</code>')
        else:
            lines.append('⚠️ No hay videochat detectado ahora')
    except Exception as e:
        lines.append('⚠️ Error leyendo videochat: <code>' + h(str(e)[-700:]) + '</code>')
    st = get_state(chat_id)
    lines.append('')
    lines.append(f'🎛 DJ mode: <b>{bool_label(st.dj_mode)}</b>')
    lines.append(f'🔴 LIVE: <b>{bool_label(st.live_enabled)}</b>')
    lines.append(f'📋 Cola: <b>{len(st.queue)}</b>')
    lines.append(f'▶️ Sonando: <b>{h((st.now_playing or {}).get("title") or "Nada")}</b>')
    lines.append('')
    lines.append('Si sigue saliendo <code>GroupcallInvalidError</code>, pon en Railway <code>VOICE_CHAT_PEER=@usuarioDelGrupo</code> y reinicia.')
    await update.message.reply_html('\n'.join(lines))
    raise _V195Stop


VoiceEngine._get_input_group_call = _v195_get_input_group_call
VoiceEngine.ensure_videochat_started = _v195_ensure_videochat_started
VoiceEngine.play_file = _v195_play_file
VoiceEngine.join_silence = _v195_join_silence


try:
    _old_v195_panelcfg_markup = _v171_panelcfg_markup
    def _v171_panelcfg_markup(chat_id: int) -> InlineKeyboardMarkup:
        return _v195_panelcfg_markup(chat_id)
except Exception:
    pass

_old_build_application_v195 = build_application

def build_application() -> Application:
    app = _old_build_application_v195()
    app.add_handler(CallbackQueryHandler(_v195_panelcfg_router, pattern=r'^panelcfg\|'), group=-22000000000)
    app.add_handler(CallbackQueryHandler(_v195_p_router, pattern=r'^p195\|'), group=-22000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v195_panel_rename_text), group=-22000000000)

    app.add_handler(CommandHandler('djdiag', djdiag_command), group=-22000000000)
    logger.info('V195 DJ-PRO peer/join_as + panel controles robusto cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V196Stop
except Exception:
    _V196Stop = Exception


async def _v196_get_input_group_call(self, chat_id: int):
    """Versión original que funcionaba: resuelve la group call con el chat_id real."""
    if not self.client:
        return None
    try:
        entity = await self.client.get_entity(chat_id)
        if getattr(entity, "megagroup", False) or getattr(entity, "broadcast", False):
            full = await self.client(functions.channels.GetFullChannelRequest(channel=entity))
        else:
            full = await self.client(functions.messages.GetFullChatRequest(chat_id=abs(int(chat_id))))
        full_chat = getattr(full, "full_chat", None)
        call = getattr(full_chat, "call", None) if full_chat else None
        if not call:
            return None
        call_id = getattr(call, "id", None)
        access_hash = getattr(call, "access_hash", None)
        if call_id is None or access_hash is None:
            return None
        return types.InputGroupCall(id=call_id, access_hash=access_hash)
    except Exception:
        logger.exception("V196 no pudo obtener la group call en chat %s", chat_id)
        return None


async def _v196_ensure_videochat_started(self, chat_id: int) -> bool:
    await self.ensure_ready(self.application)
    if not self.client:
        return False
    existing = await self._get_input_group_call(chat_id)
    if existing:
        return True
    try:
        entity = await self.client.get_entity(chat_id)
        await self.client(functions.phone.CreateGroupCallRequest(peer=entity, title='DJ-PLAN'))
        logger.info('V196 videochat iniciado en chat %s', chat_id)
        return True
    except Exception:

        try:
            if await self._get_input_group_call(chat_id):
                return True
        except Exception:
            pass
        logger.exception('V196 no pudo iniciar el videochat en chat %s', chat_id)
        return False


async def _v196_play_file(self, chat_id: int, file_path: str) -> None:
    """Ruta exacta de la versión buena: self.calls.play(chat_id, file_path)."""
    await self.ensure_ready(self.application)
    if not self.calls:
        raise RuntimeError('Voice engine no iniciado')
    if not file_path or not Path(file_path).exists():
        raise RuntimeError(f'Archivo de audio no existe: {file_path}')
    await self.calls.play(chat_id, file_path)


async def _v196_play_track(self, bot, chat_id: int, track: Track) -> None:
    import time as _time
    state = get_state(chat_id)
    await self.ensure_ready(self.application)
    await self.ensure_videochat_started(chat_id)
    if not track.local_path or not Path(track.local_path).exists():
        track = await materialize_track(bot, chat_id, track)
    if track.duration <= 0 and track.local_path and Path(track.local_path).exists():
        track.duration = probe_duration_seconds(track.local_path)
    await self.play_file(chat_id, track.local_path)
    await self._apply_volume(chat_id, state.volume)
    state.live_enabled = True
    state.now_playing = asdict(track)
    state.paused = False
    state.play_started_at = int(_time.time())
    state.paused_remaining = None
    save_all_states()
    await ensure_panel(bot, chat_id)
    await ensure_control_panel(bot, chat_id)
    await cleanup_old_files(chat_id)
    await schedule_auto_next(chat_id, track.duration, state.auto_sig_seconds)


async def _v196_toggle_live(self, chat_id: int) -> bool:
    """Mismo comportamiento estable de la versión que sonaba.
    Si no hay cola, NO intenta entrar con silencio ni fuerza peers raros: sólo deja LIVE preparado.
    """
    state = get_state(chat_id)
    await self.ensure_ready(self.application)

    if state.live_enabled:
        if state.now_playing:
            current = dict(state.now_playing)
            current_key = track_key(current)
            first_key = track_key(state.queue[0]) if state.queue else ""
            if not state.queue or current_key != first_key:
                state.queue.insert(0, current)
        state.live_enabled = False
        state.now_playing = None
        state.paused = False
        state.play_started_at = None
        state.paused_remaining = None
        save_all_states()
        await cancel_auto_next(chat_id)
        await self.leave(chat_id, end_videochat=True)
        if self.application:
            await ensure_panel(self.application.bot, chat_id)
            await ensure_control_panel(self.application.bot, chat_id)
        return False

    state.live_enabled = True
    state.paused = False
    save_all_states()
    await self.ensure_videochat_started(chat_id)

    if state.queue:
        await self.play_next_from_queue(chat_id)
    elif self.application:
        await ensure_panel(self.application.bot, chat_id)
        await ensure_control_panel(self.application.bot, chat_id)
    return True


async def _v196_dj_live_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    if (q.data or '') not in {'panel_live_toggle', 'panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await q.answer('No estás autorizado para controlar DJ-PRO.', show_alert=True)
        raise _V196Stop
    try:
        await q.answer('Activando directo…' if not get_state(chat_id).live_enabled else 'Cerrando directo…')
        live = await VOICE.toggle_live(chat_id)
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
        if live:
            if get_state(chat_id).queue:
                await q.answer('LIVE ON ✅')
            else:
                await q.answer('LIVE ON ✅ Añade una canción y pulsa PROX. para que suene.', show_alert=True)
        else:
            await q.answer('Directo cerrado ✅')
    except Exception as e:
        logger.exception('V196 error activando DJ-PRO/userbot')
        await q.answer('No pude activar DJ-PRO. Mira /djdiag.', show_alert=True)
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text='❌ <b>DJ-PRO no pudo reproducir</b>\n\n<code>' + h(str(e)[-1200:]) + '</code>\n\nEsta versión usa el método antiguo que sí te funcionaba: <code>PyTgCalls.play(chat_id, file_path)</code>. Si falla, ejecuta /djdiag.',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    raise _V196Stop


async def _v196_send_or_edit(q, text: str, markup: Optional[InlineKeyboardMarkup] = None) -> None:
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        return
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
    except Exception:
        logger.exception('V196 no pudo editar panel; envío uno nuevo')
    try:
        await q.message.reply_html(text, reply_markup=markup)
    except Exception:
        logger.exception('V196 no pudo enviar panel de respaldo')


async def _v196_panelcfg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Router prioritario para que entren sí o sí Todos los controles, Sin asignar y Renombrar."""
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|'):
        return
    data = q.data or ''
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in {'open', 'all', 'unassigned', 'renameitem'}:
        return
    try:
        chat_id = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        chat_id = 0
    if not chat_id:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V196Stop
    try:
        if action == 'open':
            await q.answer()
            await _v196_send_or_edit(q, _v171_panelcfg_text(chat_id), _v195_panelcfg_markup(chat_id))
            raise _V196Stop
        if action in {'all', 'unassigned'}:
            page = int(parts[3]) if len(parts) > 3 and str(parts[3]).lstrip('-').isdigit() else 0
            await q.answer()
            await _v196_send_or_edit(
                q,
                _v195_controls_text(chat_id, unassigned_only=(action == 'unassigned')),
                _v195_controls_markup(chat_id, unassigned_only=(action == 'unassigned'), page=page),
            )
            raise _V196Stop
        if action == 'renameitem':
            key = '|'.join(parts[3:])
            set_config_pending(q.from_user.id, {'kind': 'panel_rename_item_v195', 'chat_id': chat_id, 'key': key})
            await q.answer()
            await q.message.reply_html(f'✏️ Envíame el nuevo nombre para el botón:\n<b>{h(_v195_label(chat_id, key))}</b>')
            raise _V196Stop
    except _V196Stop:
        raise
    except Exception:
        logger.exception('V196 error en configuración panel: %s', data)
        try:
            await q.answer('Error abriendo configuración del panel. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V196Stop


async def djdiag_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    lines = ['<b>🧪 Diagnóstico DJ-PRO / Userbot V196</b>', '']
    lines.append(f'🆔 Chat usado por PyTgCalls: <code>{chat_id}</code>')
    lines.append('🎧 Motor: <b>modo antiguo funcional</b> · <code>calls.play(chat_id, file_path)</code>')
    try:
        await VOICE.ensure_ready(context.application)
        lines.append('✅ Telethon/Userbot: iniciado')
    except Exception as e:
        lines.append('❌ Telethon/Userbot: error')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        me = await VOICE.client.get_me() if VOICE.client else None
        lines.append(f'👤 Userbot: <b>{h(getattr(me, "username", None) or getattr(me, "first_name", "sin nombre"))}</b> · <code>{h(getattr(me, "id", "?"))}</code>')
    except Exception as e:
        lines.append('⚠️ No pude leer usuario Telethon: <code>' + h(str(e)[-500:]) + '</code>')
    lines.append('✅ PyTgCalls: iniciado' if VOICE.calls else '❌ PyTgCalls: no iniciado')
    try:
        entity = await VOICE.client.get_entity(chat_id) if VOICE.client else None
        lines.append(f'✅ Grupo accesible por userbot: <b>{h(getattr(entity, "title", chat_id))}</b>')
        lines.append(f'Entity: <code>{h(type(entity).__name__)}</code> · id <code>{h(getattr(entity, "id", "?"))}</code>')
    except Exception as e:
        lines.append('❌ El userbot NO accede a este grupo. Añade esa cuenta al grupo y dale permisos suficientes.')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        call = await VOICE._get_input_group_call(chat_id)
        lines.append(f'✅ Videochat detectado · call id <code>{h(getattr(call, "id", "?"))}</code>' if call else '⚠️ No hay videochat detectado ahora')
    except Exception as e:
        lines.append('⚠️ Error leyendo videochat: <code>' + h(str(e)[-700:]) + '</code>')
    st = get_state(chat_id)
    lines.append('')
    lines.append(f'🎛 DJ mode: <b>{bool_label(st.dj_mode)}</b>')
    lines.append(f'🔴 LIVE: <b>{bool_label(st.live_enabled)}</b>')
    lines.append(f'📋 Cola: <b>{len(st.queue)}</b>')
    lines.append(f'▶️ Sonando: <b>{h((st.now_playing or {}).get("title") or "Nada")}</b>')
    lines.append('')
    lines.append('Esta versión elimina el cambio de peer de V195 porque en tu caso rompía la entrada del userbot.')
    await update.message.reply_html('\n'.join(lines))
    raise _V196Stop


VoiceEngine._get_input_group_call = _v196_get_input_group_call
VoiceEngine.ensure_videochat_started = _v196_ensure_videochat_started
VoiceEngine.play_file = _v196_play_file
VoiceEngine.play_track = _v196_play_track
VoiceEngine.toggle_live = _v196_toggle_live

_old_build_application_v196 = build_application

def build_application() -> Application:
    app = _old_build_application_v196()
    app.add_handler(CallbackQueryHandler(_v196_dj_live_router, pattern=r'^(panel_live_toggle|panel_pause_resume)$'), group=-23000000000)
    app.add_handler(CallbackQueryHandler(_v196_panelcfg_router, pattern=r'^panelcfg\|(open|all|unassigned|renameitem)\|'), group=-23000000000)
    app.add_handler(CommandHandler('djdiag', djdiag_command), group=-23000000000)
    logger.info('V196 motor DJ restaurado desde versión funcional + panel config blindado cargado')
    return app


