def _v197_phrase_tone(text: str) -> str:
    t = str(text or '').lower()
    if any(x in t for x in ('familia', 'hijo', 'hogar', 'amigos', 'abrazo')):
        return 'familiar'
    if any(x in t for x in ('sonríe', 'fiesta', 'bailar', 'música', 'feliz')):
        return 'divertido'
    if any(x in t for x in ('sabiduría', 'silencio', 'alma', 'vida', 'paz')):
        return 'reflexivo'
    return 'motivador'


def _v197_seed_daily_phrases(chat_id: int) -> int:
    """Mete las frases V197 en el banco propio del grupo sin duplicar."""
    try:
        rows = _v113_daily_custom_rows(chat_id) if '_v113_daily_custom_rows' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_custom_rows', [])
        if not isinstance(rows, list):
            rows = []
            admin_cfg(chat_id)['daily_phrase_custom_rows'] = rows
        seen = {' '.join(str(r.get('text', '') if isinstance(r, dict) else r).strip().lower().split()) for r in rows}
        added = 0
        for txt in V197_DAILY_PHRASES:
            clean = str(txt or '').strip()
            if not clean:
                continue
            key = ' '.join(clean.lower().split())
            if key in seen:
                continue
            rows.append({'text': clean, 'tone': _v197_phrase_tone(clean), 'source': 'v197_user_phrases'})
            seen.add(key)
            added += 1
        if added:
            save_all_states()
        return added
    except Exception:
        logger.exception('V197 no pudo cargar frases del día en chat %s', chat_id)
        return 0


_old_v197_daily_phrase_for_chat = daily_phrase_for_chat_v30 if 'daily_phrase_for_chat_v30' in globals() else None

def daily_phrase_for_chat_v30(chat_id: int, now_ts: Optional[int] = None) -> str:
    try:
        _v197_seed_daily_phrases(int(chat_id))
    except Exception:
        pass
    if callable(_old_v197_daily_phrase_for_chat):
        return _old_v197_daily_phrase_for_chat(chat_id, now_ts)
    return V197_DAILY_PHRASES[0] if V197_DAILY_PHRASES else 'Hoy es un buen día para tener un gran día.'


