async def _v197_send_phrase_text(bot, chat_id: int, phrase: str) -> Optional[int]:
    """Publica una frase concreta con el formato actual, imagen si existe y botones conectados."""
    phrase = str(phrase or '').strip()
    if not phrase:
        return None
    cfg = admin_cfg(chat_id)
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    caption = _v114_phrase_caption(chat_id, phrase) if '_v114_phrase_caption' in globals() else f"<b>🌞 Frase del día</b>\n\n<i>{h(phrase)}</i>"
    kind = 'text'
    if image and image.get('file_id') and bool(cfg_value(chat_id, 'daily_phrase_image_enabled', True)):
        msg = await bot.send_photo(chat_id, photo=image.get('file_id'), caption=caption, parse_mode=ParseMode.HTML)
        kind = 'photo'
    else:
        msg = await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    await register_bot_message(chat_id, msg.message_id)
    try:
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_sent_messages', {})
        store[str(msg.message_id)] = {'phrase': phrase, 'kind': kind, 'next_used': [], 'sent_ts': int(time.time())}
        save_all_states()
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v197_phrase_markup(chat_id, msg.message_id))
    except Exception:
        logger.exception('V197 no pudo registrar botones de frase')
    if bool(cfg_value(chat_id, 'daily_phrase_pin', False)):
        try:
            await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
        except Exception:
            pass
    return int(msg.message_id)


async def _v197_send_daily_phrase_now(bot, chat_id: int) -> Optional[int]:
    """Enviar ahora sin tocar daily_phrase_time ni daily_phrase_last_key."""
    _v197_seed_daily_phrases(chat_id)
    phrase = daily_phrase_for_chat_v30(chat_id, int(time.time()))
    return await _v197_send_phrase_text(bot, chat_id, phrase)


async def _v197_phrase_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_send|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[2])
        before = dict(admin_cfg(chat_id))
        await _v197_send_daily_phrase_now(context.bot, chat_id)

        cfg = admin_cfg(chat_id)
        for key in ('daily_phrase_last_key', 'daily_phrase_last_sent_ts', 'daily_phrase_sending_key'):
            if key in before:
                cfg[key] = before.get(key)
            else:
                cfg.pop(key, None)
        save_all_states()
        await q.answer('Frase enviada sin modificar horario ✅')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        except Exception:
            pass
    except Exception:
        logger.exception('V197 enviar frase manual falló')
        try:
            await q.answer('No pude enviar frase. Mira logs.', show_alert=True)
        except Exception:
            pass
    raise _V197Stop


async def _v197_dphrase_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('dphrase|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 4:
        return
    action = parts[1]
    try:
        chat_id = int(parts[2])
        msg_id = int(parts[3])
    except Exception:
        await q.answer('Botón inválido.', show_alert=True)
        raise _V197Stop

    if action == 'vitamina':
        try:
            await q.answer('Te pregunto cómo te sientes 👇')
        except Exception:
            pass
        ask_text = '¿Cómo te sientes? Escríbelo y envía.'
        if '_v126_ask_for_query' in globals():
            await _v126_ask_for_query(context, chat_id, q.from_user, 'vitamina', ask_text, reply_to=msg_id)
        else:
            set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v126', 'chat_id': int(chat_id), 'cmd': 'vitamina'})
            await context.bot.send_message(chat_id=chat_id, text=f'{q.from_user.mention_html()} {h(ask_text)}', parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=msg_id)
        raise _V197Stop

    if action == 'like':
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else {}
        entry = store.get(str(msg_id)) if isinstance(store, dict) else None
        if not isinstance(entry, dict):
            await q.answer('Esta frase ya no está activa.', show_alert=True)
            raise _V197Stop
        phrase = str(entry.get('phrase') or daily_phrase_for_chat_v30(chat_id))
        uid = str(int(q.from_user.id))
        key = _v114_phrase_key(phrase) if '_v114_phrase_key' in globals() else ' '.join(phrase.lower().split())[:220]
        likes = _v114_phrase_likes_store(chat_id) if '_v114_phrase_likes_store' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_likes', {})
        row = likes.setdefault(key, {'text': phrase, 'users': []})
        users = row.setdefault('users', [])
        if uid not in users:
            users.append(uid)
            row['text'] = phrase
            save_all_states()
            if '_v114_update_daily_phrase_message' in globals():
                await _v114_update_daily_phrase_message(context.bot, chat_id, msg_id)
            await q.answer('❤️ Me gusta añadido')
        else:
            await q.answer('Ya habías dado me gusta ❤️')
        raise _V197Stop


_old_v197_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == 'daily_phrase':
        _v197_seed_daily_phrases(chat_id)
        txt = _old_v197_block_text(chat_id, block, page)
        try:
            total = len(_v113_daily_custom_rows(chat_id))
            txt += f"\n\n<b>Banco V197:</b> <b>{len(V197_DAILY_PHRASES)}</b> frases cargadas · Total guardadas: <b>{total}</b>"
            txt += "\n🚀 <b>Enviar ahora</b> publica sin cambiar la hora ni consumir la programación."
        except Exception:
            pass
        return txt
    return _old_v197_block_text(chat_id, block, page)


_old_v197_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v197_block_markup(chat_id, block, page)
    if block != 'daily_phrase':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]
    insert_at = max(0, len(rows) - 1)
    rows.insert(insert_at, [
        InlineKeyboardButton('➕ Añadir frase propia', callback_data=f'cfg|phrase_add_one|{chat_id}|daily_phrase'),
        InlineKeyboardButton('🚀 Añadir y publicar', callback_data=f'cfg|phrase_add_publish|{chat_id}|daily_phrase'),
    ])
    rows.insert(insert_at + 1, [
        InlineKeyboardButton('📚 Recargar frases V197', callback_data=f'cfg|phrase_seed_v197|{chat_id}|daily_phrase'),
    ])
    return InlineKeyboardMarkup(rows)


async def _v197_phrase_admin_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_'):
        return
    parts = (q.data or '').split('|')
    action = parts[1]
    if action not in {'phrase_add_one', 'phrase_add_publish', 'phrase_seed_v197'}:
        return
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V197Stop

    if action == 'phrase_seed_v197':
        added = _v197_seed_daily_phrases(chat_id)
        await q.answer(f'Frases revisadas. Nuevas añadidas: {added} ✅', show_alert=True)
        await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        raise _V197Stop

    publish = action == 'phrase_add_publish'
    set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_one_v197', 'chat_id': chat_id, 'publish': publish})
    await q.answer()
    await q.edit_message_text(
        '✍️ Envíame la frase que quieres añadir.\n\n'
        + ('La guardaré y la publicaré ahora en el grupo.' if publish else 'La guardaré en el banco de frases.'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
    )
    raise _V197Stop


_old_v197_admin_text = admin_private_config_text

async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending and pending.get('kind') == 'cfg_phrase_one_v197':
            chat_id = int(pending.get('chat_id') or 0)
            publish = bool(pending.get('publish'))
            phrase = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
            if not phrase:
                await update.message.reply_html('Envíame una frase válida.')
                raise _V197Stop
            rows = _v113_daily_custom_rows(chat_id)
            key = ' '.join(phrase.lower().split())
            seen = {' '.join(str(r.get('text','') if isinstance(r, dict) else r).strip().lower().split()) for r in rows}
            if key not in seen:
                rows.append({'text': phrase, 'tone': _v197_phrase_tone(phrase), 'source': 'manual_v197'})
            pop_config_pending(update.effective_user.id)
            save_all_states()
            if publish:
                await _v197_send_phrase_text(context.bot, chat_id, phrase)
                await update.message.reply_html('✅ Frase añadida y publicada en el grupo.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
            else:
                await update.message.reply_html('✅ Frase añadida al banco.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
            raise _V197Stop
    return await _old_v197_admin_text(update, context)


def _v197_panel_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return _v195_panel_cfg(chat_id)
    except Exception:
        try:
            return _v192_panel_cfg(chat_id)
        except Exception:
            return admin_cfg(chat_id).setdefault('panel_config_v171', {'blocks': [], 'loose_items': []})


def _v197_main_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    pcfg = _v197_panel_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    hidden = set(str(x) for x in pcfg.get('hidden_items', []) or [])

    for block in pcfg.get('blocks', []) or []:
        title = str(block.get('title') or 'Bloque')

        rows.append([InlineKeyboardButton(f'📦 {truncated_button_title(title, 52)}', callback_data=f'panelnoop|{chat_id}')])
        pair: List[InlineKeyboardButton] = []
        for key in block.get('items', []) or []:
            key = str(key)
            try:
                known = _v195_known_key(chat_id, key)
            except Exception:
                known = True
            if key in hidden or not known:
                continue
            pair.append(InlineKeyboardButton(_v195_label(chat_id, key) if '_v195_label' in globals() else key, callback_data=_v192_cb(chat_id, key) if '_v192_cb' in globals() else f'panelcfg|control|{chat_id}|{key}'))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)

    for item in pcfg.get('loose_items', []) or []:
        if not isinstance(item, dict):
            continue
        key = str(item.get('key') or '')
        if not key or key in hidden:
            continue
        rows.append([InlineKeyboardButton(_v195_label(chat_id, key) if '_v195_label' in globals() else key, callback_data=_v192_cb(chat_id, key) if '_v192_cb' in globals() else f'panelcfg|control|{chat_id}|{key}')])

    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}')])
    title = str(cfg_value(chat_id, 'chat_title', str(chat_id)))
    rows.append([InlineKeyboardButton(f'🌐 Grupo actual: {truncated_button_title(title, 42)}', callback_data='cfg|list')])
    rows.append([
        InlineKeyboardButton('✅ Comprobar bot', callback_data=f'checkbot|{chat_id}'),
        InlineKeyboardButton('💾 Guardar', callback_data=f'cfg|save|{chat_id}'),
        InlineKeyboardButton('❌ Cerrar', callback_data=f'cfg|close|{chat_id}'),
    ])
    return InlineKeyboardMarkup(rows)


