async def _v197_live_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    if (q.data or '') not in {'panel_live_toggle', 'panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await q.answer('No estás autorizado para controlar DJ-PRO.', show_alert=True)
        raise _V197Stop
    st = get_state(chat_id)
    try:
        if not st.live_enabled:
            await q.answer('Activando y preparando sonido…')
            await VOICE.ensure_ready(context.application)
            if st.queue:
                st.live_enabled = True
                st.paused = False
                save_all_states()
                await VOICE.play_next_from_queue(chat_id)
                await q.answer('LIVE ON y sonando ✅')
            else:
                live = await VOICE.toggle_live(chat_id)
                await q.answer('LIVE ON ✅ Añade una canción y pulsa PROX.' if live else 'Directo cerrado')
        else:
            await q.answer('Cerrando directo…')
            await VOICE.toggle_live(chat_id)
            await q.answer('Directo cerrado ✅')
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
    except Exception as e:
        logger.exception('V197 error activando DJ-PRO')
        try:
            await q.answer('No pude activar DJ-PRO. Mira /djdiag.', show_alert=True)
        except Exception:
            pass
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text='❌ <b>Error DJ-PRO al poner ON</b>\n\n<code>' + h(str(e)[-1400:]) + '</code>\n\nEjecuta <code>/djdiag</code> y pásame el resultado si sigue fallando.',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    raise _V197Stop


_old_build_application_v197 = build_application

def build_application() -> Application:
    app = _old_build_application_v197()
    app.add_handler(CallbackQueryHandler(_v197_phrase_send_router, pattern=r'^cfg\|phrase_send\|'), group=-24000000000)
    app.add_handler(CallbackQueryHandler(_v197_phrase_admin_router, pattern=r'^cfg\|phrase_(add_one|add_publish|seed_v197)\|'), group=-24000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, admin_private_config_text), group=-24000000000)
    app.add_handler(CallbackQueryHandler(_v197_dphrase_router, pattern=r'^dphrase\|(vitamina|like)\|'), group=-24000000000)
    app.add_handler(CallbackQueryHandler(_v197_live_router, pattern=r'^(panel_live_toggle|panel_pause_resume)$'), group=-24000000000)
    try:
        for cid in list(known_admin_chats_for_private()):
            if int(cid) < 0:
                _v197_seed_daily_phrases(int(cid))
    except Exception:
        logger.exception('V197 no pudo sembrar frases al arrancar')
    logger.info('V197 frase/panel/LIVE cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V198Stop
except Exception:
    _V198Stop = Exception


async def _v198_start_watchdog_if_needed() -> None:
    global WATCHDOG_TASK
    if WATCHDOG_TASK is None or WATCHDOG_TASK.done():
        WATCHDOG_TASK = asyncio.create_task(_watchdog_loop())
        logger.info('V198 watchdog DJ-PRO arrancado/rearmado')


async def _v198_force_start_from_queue(chat_id: int, *, reason: str = 'v198_force_start') -> bool:
    """Arranca la primera canción de la cola aunque LIVE haya quedado ON sin now_playing."""
    state = get_state(chat_id)
    if not state.queue:
        return False
    try:
        await VOICE.ensure_ready(VOICE.application)
        state.live_enabled = True
        state.paused = False
        save_all_states()
        logger.info('V198 arranque forzado desde cola chat %s (%s). Cola=%s', chat_id, reason, len(state.queue))
        await VOICE.play_next_from_queue(chat_id)
        return True
    except Exception:
        logger.exception('V198 no pudo arrancar desde cola chat %s (%s)', chat_id, reason)
        return False


async def _watchdog_loop() -> None:
    """Watchdog DJ-PRO V198.

    Recupera tres estados problemáticos:
    1) LIVE ON + AUTO ON + cola + sin canción -> arranca primera canción.
    2) LIVE ON + canción con duración -> avanza cuando llega al final.
    3) LIVE ON + canción sin duración -> usa fallback temporal.
    """
    import time as _time

    while True:
        try:
            await asyncio.sleep(WATCHDOG_TICK_SECONDS)
            bot = VOICE.application.bot if VOICE.application else None
            now_ts = _time.time()

            for chat_id, state in list(STATE_CACHE.items()):
                if not state.dj_mode:
                    WATCHDOG_RUNTIME.pop(chat_id, None)
                    continue

                runtime = WATCHDOG_RUNTIME.setdefault(
                    chat_id,
                    {
                        'token': None,
                        'last_remaining': None,
                        'none_hits': 0,
                        'last_advance_at': 0.0,
                        'next_refresh': 0.0,
                        'stuck_hits': 0,
                    },
                )


                if bot and now_ts >= float(runtime.get('next_refresh', 0.0)):
                    runtime['next_refresh'] = now_ts + UI_REFRESH_SECONDS
                    try:
                        await ensure_panel(bot, chat_id)
                        await ensure_control_panel(bot, chat_id)
                    except Exception:
                        logger.exception('V198 no pudo refrescar panel DJ chat %s', chat_id)

                if not state.live_enabled:
                    runtime['token'] = None
                    runtime['last_remaining'] = None
                    runtime['none_hits'] = 0
                    runtime['stuck_hits'] = 0
                    continue


                if state.auto_track_enabled and not state.now_playing and state.queue:
                    runtime['stuck_hits'] = int(runtime.get('stuck_hits', 0) or 0) + 1
                    if runtime['stuck_hits'] >= 1 and now_ts - float(runtime.get('last_advance_at', 0.0)) >= 2:
                        runtime['last_advance_at'] = now_ts
                        ok = await _v198_force_start_from_queue(chat_id, reason='auto_recover_live_on_no_now_playing')
                        if ok:
                            runtime['stuck_hits'] = 0
                    continue

                if not state.now_playing:
                    runtime['token'] = None
                    runtime['last_remaining'] = None
                    runtime['none_hits'] = 0
                    runtime['stuck_hits'] = 0
                    continue

                runtime['stuck_hits'] = 0
                token = track_key(state.now_playing)
                if runtime.get('token') != token:
                    runtime['token'] = token
                    runtime['last_remaining'] = None
                    runtime['none_hits'] = 0

                if not state.auto_track_enabled or not state.queue:
                    continue

                trigger = 0 if int(state.auto_sig_seconds or -1) < 0 else int(state.auto_sig_seconds or 0)
                remaining = remaining_seconds(state)

                if remaining is not None:
                    runtime['last_remaining'] = remaining
                    runtime['none_hits'] = 0
                    if remaining <= trigger and now_ts - float(runtime.get('last_advance_at', 0.0)) >= 2:
                        runtime['last_advance_at'] = now_ts
                        await simulate_panel_next(chat_id, reason=f'v198_auto_end_{trigger}')
                    continue


                runtime['none_hits'] = int(runtime.get('none_hits', 0) or 0) + 1
                track = Track(**state.now_playing)
                elapsed = 0
                if state.play_started_at is not None:
                    elapsed = max(0, int(now_ts - int(state.play_started_at)))

                should_advance = False
                if track.duration > 0 and elapsed >= max(0, int(track.duration) - trigger):
                    should_advance = True
                elif track.duration <= 0 and elapsed >= max(UNKNOWN_END_FALLBACK_SECONDS, trigger):
                    should_advance = True
                elif runtime.get('last_remaining') is not None and int(runtime.get('none_hits', 0) or 0) >= 2:
                    should_advance = True

                if should_advance and now_ts - float(runtime.get('last_advance_at', 0.0)) >= 2:
                    runtime['last_advance_at'] = now_ts
                    await simulate_panel_next(chat_id, reason='v198_auto_unknown_duration')
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V198 error en watchdog global DJ-PRO')


async def _v198_dj_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_live_toggle', 'panel_pause_resume', 'panel_next', 'panel_auto_track'}:
        return

    chat_id = int(update.effective_chat.id)
    user_id = int(update.effective_user.id)
    if not await is_controller(context, chat_id, user_id):
        await q.answer('Solo el DJ asignado o admin puede controlar DJ-PRO.', show_alert=True)
        raise _V198Stop

    await _v198_start_watchdog_if_needed()
    state = get_state(chat_id)

    try:
        if data == 'panel_auto_track':
            state.auto_track_enabled = not bool(state.auto_track_enabled)
            save_all_states()
            await q.answer('AUTO ON ✅' if state.auto_track_enabled else 'AUTO OFF')
            if state.auto_track_enabled and state.live_enabled and state.queue and not state.now_playing:
                ok = await _v198_force_start_from_queue(chat_id, reason='auto_button_recover')
                if not ok:
                    await q.answer('AUTO ON, pero no pude arrancar la cola. Pulsa PROX. o mira /djdiag.', show_alert=True)
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
            raise _V198Stop

        if data == 'panel_next':
            if not state.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
                raise _V198Stop
            await q.answer('Pasando a la siguiente…')
            ok = await _v198_force_start_from_queue(chat_id, reason='manual_next')
            if not ok:
                await q.answer('No pude reproducir. Ejecuta /djdiag.', show_alert=True)
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
            raise _V198Stop


        if data in {'panel_live_toggle', 'panel_pause_resume'}:
            if state.live_enabled and not state.now_playing and state.queue:
                await q.answer('LIVE estaba ON sin sonido. Recuperando cola…')
                ok = await _v198_force_start_from_queue(chat_id, reason='live_on_recover_no_now_playing')
                if ok:
                    await q.answer('Sonando ✅')
                else:
                    await q.answer('No pude recuperar sonido. Ejecuta /djdiag.', show_alert=True)
                await ensure_panel(context.bot, chat_id)
                await ensure_control_panel(context.bot, chat_id)
                raise _V198Stop

            if not state.live_enabled:
                await q.answer('Activando DJ-PRO…')
                await VOICE.ensure_ready(context.application)
                if state.queue:
                    ok = await _v198_force_start_from_queue(chat_id, reason='live_on_start')
                    if ok:
                        await q.answer('LIVE ON y sonando ✅')
                    else:
                        await q.answer('LIVE no pudo arrancar. Ejecuta /djdiag.', show_alert=True)
                else:
                    state.live_enabled = True
                    state.paused = False
                    save_all_states()
                    try:
                        await VOICE.ensure_videochat_started(chat_id)
                    except Exception:
                        logger.exception('V198 no pudo preparar videochat sin cola')
                    await q.answer('LIVE ON ✅ Añade una canción y pulsa PROX.', show_alert=True)
                await ensure_panel(context.bot, chat_id)
                await ensure_control_panel(context.bot, chat_id)
                raise _V198Stop


            await q.answer('Cerrando directo…')
            await VOICE.toggle_live(chat_id)
            await q.answer('Directo cerrado ✅')
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
            raise _V198Stop
    except _V198Stop:
        raise
    except Exception as e:
        logger.exception('V198 error en router DJ-PRO %s', data)
        try:
            await q.answer('Error DJ-PRO. Ejecuta /djdiag.', show_alert=True)
        except Exception:
            pass
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text='❌ <b>Error DJ-PRO V198</b>\n\n<code>' + h(str(e)[-1400:]) + '</code>\n\nEstado recuperable: si ves LIVE ON, cola > 0 y Sonando: Nada, pulsa <b>PROX.</b> o <b>LIVE</b> otra vez.',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        raise _V198Stop


async def djdiag_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    st = get_state(chat_id)
    lines = ['<b>🧪 Diagnóstico DJ-PRO / Userbot V198</b>', '']
    lines.append(f'🆔 Chat usado por PyTgCalls: <code>{chat_id}</code>')
    lines.append('🎧 Motor: <b>modo antiguo funcional</b> · <code>calls.play(chat_id, file_path)</code>')
    try:
        await VOICE.ensure_ready(context.application)
        await _v198_start_watchdog_if_needed()
        lines.append('✅ Telethon/Userbot: iniciado')
    except Exception as e:
        lines.append('❌ Telethon/Userbot: error')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        me = await VOICE.client.get_me() if VOICE.client else None
        lines.append(f'👤 Userbot: <b>{h(getattr(me, "username", None) or getattr(me, "first_name", "sin nombre"))}</b> · <code>{h(getattr(me, "id", "?"))}</code>')
    except Exception as e:
        lines.append('⚠️ No pude leer usuario Telethon: <code>' + h(str(e)[-500:]) + '</code>')
    lines.append('✅ PyTgCalls: iniciado' if VOICE.calls else '❌ PyTgCalls: no iniciado')
    try:
        entity = await VOICE.client.get_entity(chat_id) if VOICE.client else None
        lines.append(f'✅ Grupo accesible por userbot: <b>{h(getattr(entity, "title", chat_id))}</b>')
        lines.append(f'Entity: <code>{h(type(entity).__name__)}</code> · id <code>{h(getattr(entity, "id", "?"))}</code>')
    except Exception as e:
        lines.append('❌ El userbot NO accede a este grupo.')
        lines.append('<code>' + h(str(e)[-900:]) + '</code>')
    try:
        call = await VOICE._get_input_group_call(chat_id)
        lines.append(f'✅ Videochat detectado · call id <code>{h(getattr(call, "id", "?"))}</code>' if call else '⚠️ No hay videochat detectado ahora')
    except Exception as e:
        lines.append('⚠️ Error leyendo videochat: <code>' + h(str(e)[-700:]) + '</code>')
    lines.append('')
    lines.append(f'🎛 DJ mode: <b>{bool_label(st.dj_mode)}</b>')
    lines.append(f'🔴 LIVE: <b>{bool_label(st.live_enabled)}</b>')
    lines.append(f'🤖 AUTO: <b>{bool_label(st.auto_track_enabled)}</b> · Temp: <b>{h(format_auto_sig_label(st.auto_sig_seconds))}</b>')
    lines.append(f'📋 Cola: <b>{len(st.queue)}</b>')
    lines.append(f'▶️ Sonando: <b>{h((st.now_playing or {}).get("title") or "Nada")}</b>')
    rem = remaining_seconds(st)
    lines.append(f'🕐 Restante calculado: <b>{fmt_duration(rem) if rem is not None else "--:--"}</b>')
    lines.append('')
    if st.live_enabled and not st.now_playing and st.queue:
        lines.append('⚠️ Estado atascado detectado: LIVE ON + cola + Sonando Nada.')
        lines.append('✅ V198 lo recupera con PROX., LIVE otra vez o AUTO ON.')
    lines.append('Watchdog: <b>' + ('ON</b>' if WATCHDOG_TASK and not WATCHDOG_TASK.done() else 'OFF</b>'))
    await update.message.reply_html('\n'.join(lines))
    raise _V198Stop


_old_build_application_v198 = build_application

def build_application() -> Application:
    app = _old_build_application_v198()

    app.add_handler(CallbackQueryHandler(_v198_dj_router, pattern=r'^(panel_live_toggle|panel_pause_resume|panel_next|panel_auto_track)$'), group=-25000000000)
    app.add_handler(CommandHandler('djdiag', djdiag_command), group=-25000000000)
    logger.info('V198 DJ-PRO auto-recuperación + auto-siguiente blindado cargado')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V199Stop
except Exception:
    _V199Stop = Exception


def _v199_cfg(chat_id: int) -> Dict[str, Any]:
    return admin_cfg(int(chat_id))


def _v199_now_ts() -> int:
    return int(time.time())


def _v199_dt(ts: Optional[int] = None):
    try:
        return _v189_dt(int(ts or time.time())) if '_v189_dt' in globals() else _local_dt_v15(int(ts or time.time()))
    except Exception:
        return datetime.datetime.fromtimestamp(int(ts or time.time()))


def _v199_day_key(ts: Optional[int] = None) -> str:
    try:
        return _v189_day_key(int(ts or time.time())) if '_v189_day_key' in globals() else _local_day_key_v15(int(ts or time.time()))
    except Exception:
        return time.strftime('%Y-%m-%d', time.localtime(int(ts or time.time())))


def _v199_parse_hhmm(value: Any, default: str = '10:00') -> tuple[int, int]:
    raw = str(value or default).strip()
    try:
        hh, mm = raw.split(':', 1)
        hhi = max(0, min(23, int(hh)))
        mmi = max(0, min(59, int(mm)))
        return hhi, mmi
    except Exception:
        hh, mm = default.split(':', 1)
        return int(hh), int(mm)


def _v199_minutes(value: Any, default: str = '10:00') -> int:
    hh, mm = _v199_parse_hhmm(value, default)
    return hh * 60 + mm


def _v199_slot_key(chat_id: int, now_ts: Optional[int] = None) -> tuple[bool, str, str]:
    """Devuelve (vencida, slot_key, motivo) para frase del día.
    Soporta una vez al día o repetición por franja.
    """
    cfg = _v199_cfg(chat_id)
    if not bool(cfg.get('daily_phrase_enabled', False)):
        return False, '', 'OFF'
    now_ts = int(now_ts or time.time())
    dt = _v199_dt(now_ts)
    day = dt.strftime('%Y-%m-%d')
    start = str(cfg.get('daily_phrase_time') or '10:00')
    start_min = _v199_minutes(start, '10:00')
    now_min = int(dt.hour) * 60 + int(dt.minute)
    repeat = bool(cfg.get('daily_phrase_repeat_enabled', False))
    if not repeat:
        slot = f'{day}:once:{start_min}'
        if str(cfg.get('daily_phrase_last_key') or '') == slot:
            return False, slot, 'ya enviada en el horario de hoy'
        if now_min < start_min:
            return False, slot, f'esperando {start}'
        return True, slot, f'vencida {start}'
    every = max(15, int(cfg.get('daily_phrase_repeat_every_minutes', 60) or 60))
    until = str(cfg.get('daily_phrase_repeat_until') or start)
    until_min = _v199_minutes(until, start)
    if until_min < start_min:

        in_range = now_min >= start_min or now_min <= until_min
        distance = (now_min - start_min) if now_min >= start_min else (1440 - start_min + now_min)
    else:
        in_range = start_min <= now_min <= until_min
        distance = now_min - start_min
    if not in_range:
        return False, '', f'fuera de franja {start}-{until}'
    slot_index = max(0, distance // every)
    slot_min = (start_min + slot_index * every) % 1440
    slot = f'{day}:repeat:{slot_min}'
    if str(cfg.get('daily_phrase_last_key') or '') == slot:
        return False, slot, 'slot ya enviado'
    return True, slot, f'slot {slot_min // 60:02d}:{slot_min % 60:02d}'


def _v199_daily_phrase_text(chat_id: int, now_ts: Optional[int] = None) -> str:
    try:
        _v197_seed_daily_phrases(chat_id)
    except Exception:
        pass
    try:
        return str(daily_phrase_for_chat_v30(chat_id, int(now_ts or time.time())) or '').strip()
    except Exception:
        logger.exception('V199 no pudo obtener daily_phrase_for_chat_v30')
    try:
        rows = _v113_daily_custom_rows(chat_id) if '_v113_daily_custom_rows' in globals() else []
        vals = [str((r.get('text') if isinstance(r, dict) else r) or '').strip() for r in rows]
        vals = [x for x in vals if x]
        if vals:
            idx = int(_v199_dt(now_ts).strftime('%j')) % len(vals)
            return vals[idx]
    except Exception:
        pass
    return 'Hoy es un buen día para tener un gran día. — J.M.'


async def _v199_send_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False, phrase: Optional[str] = None) -> Optional[int]:
    """Envío robusto de frase. Si falla foto/caption, cae a texto simple.
    force=True no toca programación salvo que lo pida el scheduler.
    """
    chat_id = int(chat_id)
    cfg = _v199_cfg(chat_id)
    now_ts = int(now_ts or time.time())
    phrase = str(phrase or _v199_daily_phrase_text(chat_id, now_ts)).strip()
    if not phrase:
        phrase = 'Hoy es un buen día para tener un gran día. — J.M.'
    title = str(cfg.get('daily_phrase_title') or '🌞 Frase del día')
    try:
        caption = _v114_phrase_caption(chat_id, phrase) if '_v114_phrase_caption' in globals() else f'<b>{h(title)}</b>\n\n<i>{h(phrase)}</i>'
    except Exception:
        caption = f'<b>{h(title)}</b>\n\n<i>{h(phrase)}</i>'
    msg = None
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    if image and image.get('file_id') and bool(cfg.get('daily_phrase_image_enabled', True)):
        try:
            msg = await bot.send_photo(chat_id, photo=image.get('file_id'), caption=caption, parse_mode=ParseMode.HTML, reply_markup=None)
        except Exception:
            logger.exception('V199 envío con foto falló; uso texto')
    if msg is None:
        try:
            msg = await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        except Exception:

            logger.exception('V199 envío HTML falló; uso texto plano')
            plain = f'{title}\n\n{phrase}'
            msg = await bot.send_message(chat_id, plain, disable_web_page_preview=True)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    try:
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else cfg.setdefault('daily_phrase_sent_messages', {})
        store[str(msg.message_id)] = {'phrase': phrase, 'kind': 'photo' if getattr(msg, 'photo', None) else 'text', 'next_used': [], 'sent_ts': now_ts}
        save_all_states()
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v197_phrase_markup(chat_id, msg.message_id))
    except Exception:
        logger.exception('V199 no pudo poner botones Vitamina/Me gusta')
    if bool(cfg.get('daily_phrase_pin', False)):
        try:
            await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
        except Exception:
            pass
    return int(msg.message_id)


async def _v199_send_daily_phrase_now(bot, chat_id: int) -> Optional[int]:
    before = {k: _v199_cfg(chat_id).get(k) for k in ('daily_phrase_last_key', 'daily_phrase_last_sent_ts', 'daily_phrase_sending_key')}
    mid = await _v199_send_phrase(bot, chat_id, now_ts=_v199_now_ts(), force=True)

    cfg = _v199_cfg(chat_id)
    for k, v in before.items():
        if v is None:
            cfg.pop(k, None)
        else:
            cfg[k] = v
    save_all_states()
    return mid


async def _v199_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = _v199_now_ts()
    for chat_id in list(known_admin_chats_for_private() if 'known_admin_chats_for_private' in globals() else STATE_CACHE.keys()):
        try:
            chat_id = int(chat_id)
            if chat_id >= 0:
                continue
        except Exception:
            continue

        try:
            due, slot, reason = _v199_slot_key(chat_id, now)
            if due and slot:
                cfg = _v199_cfg(chat_id)
                if str(cfg.get('daily_phrase_sending_key') or '') == slot:
                    continue
                cfg['daily_phrase_sending_key'] = slot
                save_all_states()
                try:
                    await _v199_send_phrase(context.bot, chat_id, now_ts=now, force=False)
                    cfg['daily_phrase_last_key'] = slot
                    cfg['daily_phrase_last_sent_ts'] = now
                    logger.info('V199 frase enviada chat=%s slot=%s reason=%s', chat_id, slot, reason)
                except Exception:
                    logger.exception('V199 scheduler frase falló chat=%s', chat_id)

                finally:
                    cfg['daily_phrase_sending_key'] = ''
                    save_all_states()
                await asyncio.sleep(0.25)
        except Exception:
            logger.exception('V199 scheduler frase error chat=%s', chat_id)

        try:
            for row in list(recurring_list(chat_id)):
                try:
                    due, reason = _v189_recurring_due_reason(row, now) if '_v189_recurring_due_reason' in globals() else (False, 'sin motor')
                    if due:
                        sent = await send_recurring_message(context, chat_id, row)
                        if sent:
                            if '_v189_mark_sent' in globals():
                                _v189_mark_sent(row, now)
                            else:
                                row['last_sent_ts'] = now
                            save_all_states()
                            logger.info('V199 recurrente enviado chat=%s id=%s reason=%s', chat_id, row.get('id'), reason)
                            await asyncio.sleep(0.35)
                except Exception:
                    logger.exception('V199 scheduler recurrente chat=%s id=%s', chat_id, row.get('id'))
        except Exception:
            logger.exception('V199 scheduler recurrentes chat=%s', chat_id)


async def _v199_phrase_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V199Stop
    cfg = _v199_cfg(chat_id)
    try:
        if action == 'phrase_send':
            await _v199_send_daily_phrase_now(context.bot, chat_id)
            await q.answer('Frase enviada sin modificar horario ✅', show_alert=False)
        elif action == 'phrase_toggle':
            cfg['daily_phrase_enabled'] = not bool(cfg.get('daily_phrase_enabled', False))
            await q.answer('Frase del día ' + ('ON ✅' if cfg['daily_phrase_enabled'] else 'OFF'))
        elif action == 'phrase_pin':
            cfg['daily_phrase_pin'] = not bool(cfg.get('daily_phrase_pin', False))
            await q.answer('Fijar ' + ('ON ✅' if cfg['daily_phrase_pin'] else 'OFF'))
        elif action == 'phrase_repeat_toggle':
            cfg['daily_phrase_repeat_enabled'] = not bool(cfg.get('daily_phrase_repeat_enabled', False))
            await q.answer('Repetir franja ' + ('ON ✅' if cfg['daily_phrase_repeat_enabled'] else 'OFF'))
        elif action == 'phrase_repeat_every' and len(parts) >= 4:
            cfg['daily_phrase_repeat_every_minutes'] = max(15, int(parts[3]))
            await q.answer('Frecuencia actualizada ✅')
        elif action == 'phrase_time':
            set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_time_v199', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html('⏰ Envíame la hora inicial. Ejemplo: <code>10:00</code>')
            raise _V199Stop
        elif action == 'phrase_repeat_until':
            set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_repeat_until_v199', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html('🛑 Envíame la hora final. Ejemplo: <code>15:00</code>')
            raise _V199Stop
        elif action == 'phrase_title':
            set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_title_v199', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html('✏️ Envíame el nuevo título de la frase del día.')
            raise _V199Stop
        else:
            return
        save_all_states()
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        except BadRequest as e:
            if 'message is not modified' not in str(e).lower():
                raise
        raise _V199Stop
    except _V199Stop:
        raise
    except Exception as e:
        logger.exception('V199 fallo en frase del día action=%s', action)
        try:
            await q.answer('No pude ejecutar frase del día. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V199Stop


_old_v199_admin_text = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending and str(pending.get('kind') or '').endswith('_v199'):
            chat_id = int(pending.get('chat_id') or 0)
            txt = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
            kind = pending.get('kind')
            if kind in ('cfg_phrase_time_v199', 'cfg_phrase_repeat_until_v199'):
                import re as _re_v199
                if not _re_v199.match(r'^[0-2]?\d:[0-5]\d$', txt):
                    await update.message.reply_html('Hora no válida. Ejemplo: <code>10:00</code>')
                    raise _V199Stop
                hh, mm = _v199_parse_hhmm(txt, '10:00')
                txt = f'{hh:02d}:{mm:02d}'
                if kind == 'cfg_phrase_time_v199':
                    _v199_cfg(chat_id)['daily_phrase_time'] = txt
                else:
                    _v199_cfg(chat_id)['daily_phrase_repeat_until'] = txt
            elif kind == 'cfg_phrase_title_v199':
                if not txt:
                    await update.message.reply_html('Título vacío no válido.')
                    raise _V199Stop
                _v199_cfg(chat_id)['daily_phrase_title'] = txt[:80]
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html('✅ Actualizado.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
            raise _V199Stop
    return await _old_v199_admin_text(update, context)


_old_v199_main_panel_markup = _v197_main_panel_markup if '_v197_main_panel_markup' in globals() else admin_private_main_markup

def _v199_main_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_v199_main_panel_markup(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]

    new_rows = []
    for r in rows:
        callbacks = [(getattr(b, 'callback_data', '') or '') for b in r]
        labels = [(getattr(b, 'text', '') or '') for b in r]
        if any(cb == f'cfg|save|{chat_id}' for cb in callbacks) or any('Guardar' == lab or lab.startswith('💾 Guardar') for lab in labels):
            new_rows.append([
                InlineKeyboardButton('✅ Comprobar bot', callback_data=f'checkbot|{chat_id}'),
                InlineKeyboardButton('💾 Guardar y cerrar', callback_data=f'cfg|saveclose|{chat_id}'),
            ])
        else:
            new_rows.append(r)
    return InlineKeyboardMarkup(new_rows)


def _v197_main_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    return _v199_main_panel_markup(chat_id)


def _v171_render_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    return _v199_main_panel_markup(chat_id)


def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    return _v199_main_panel_markup(chat_id)


async def _v199_saveclose_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|saveclose|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V199Stop
    save_all_states()
    await q.answer('Guardado ✅')
    try:
        await q.edit_message_text('✅ Ajustes guardados y panel cerrado.')
    except Exception:
        try:
            await q.message.delete()
        except Exception:
            pass
    raise _V199Stop


async def _v199_recurring_manual_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''

    try:
        if data.startswith('cfg|rec_send|'):
            parts = data.split('|')
            chat_id = int(parts[2]); rid = int(parts[3])
            row = recurring_find(chat_id, rid)
            if not row:
                await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V199Stop
            await _v181_send_recurring_manual_clean(context, chat_id, row) if '_v181_send_recurring_manual_clean' in globals() else await _v170_send_recurring_manual(context, chat_id, row)
            await q.answer('Recurrente enviado ✅', show_alert=False)
            raise _V199Stop
        if data.startswith('panelcfg|control|'):
            parts = data.split('|')
            chat_id = int(parts[2]); key = str(parts[3]) if len(parts) > 3 else ''
            if key.startswith('recsend_'):
                rid = int(key.split('_', 1)[1])
                row = recurring_find(chat_id, rid)
                if not row:
                    await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V199Stop
                await _v181_send_recurring_manual_clean(context, chat_id, row) if '_v181_send_recurring_manual_clean' in globals() else await _v170_send_recurring_manual(context, chat_id, row)
                await q.answer('Recurrente enviado ✅', show_alert=False)
                raise _V199Stop

        if data.startswith('cfg|rblk_send|') or data.startswith('panelrun|rblk|') or (data.startswith('panelcfg|control|') and '|rblksend_' in data):
            await _v181_rblk_send_router(update, context)
            raise _V199Stop
    except _V199Stop:
        raise
    except Exception:
        logger.exception('V199 recurrente/bloque manual falló: %s', data)
        try:
            await q.answer('No pude enviar recurrente/bloque. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V199Stop


async def _v199_health_text(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> str:
    try:
        base = await _v189_health_text(context, chat_id) if '_v189_health_text' in globals() else '<b>✅ COMPROBAR BOT</b>'
    except Exception:
        base = '<b>✅ COMPROBAR BOT</b>'
    due, slot, reason = _v199_slot_key(chat_id, _v199_now_ts())
    cfg = _v199_cfg(chat_id)
    extra = (
        '\n\n<b>V199 frase/recurrentes</b>\n'
        f'🌞 Programación: <b>{bool_label(bool(cfg.get("daily_phrase_enabled", False)))}</b> · '
        f'hora <b>{h(str(cfg.get("daily_phrase_time", "10:00")))}</b> · '
        f'repetir <b>{bool_label(bool(cfg.get("daily_phrase_repeat_enabled", False)))}</b> · '
        f'vencida <b>{bool_label(due)}</b> ({h(reason)})\n'
        f'🔑 Último slot: <code>{h(str(cfg.get("daily_phrase_last_key", "")))}</code>\n'
        f'⏭ Próximo slot calculado: <code>{h(slot)}</code>'
    )
    return (base + extra)[:3900]


async def _v199_health_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not ((q.data or '').startswith('checkbot|') or (q.data or '').startswith('cfg|botcheck|')):
        return
    try:
        chat_id = int((q.data or '').split('|')[-1])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True); raise _V199Stop
    await q.answer('Comprobando…')
    text = await _v199_health_text(context, chat_id)
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('🔄 Repetir', callback_data=f'checkbot|{chat_id}')],
        [InlineKeyboardButton('🌞 Enviar frase ahora', callback_data=f'cfg|phrase_send|{chat_id}|daily_phrase'), InlineKeyboardButton('🔁 Recurrentes', callback_data=f'cfg|block|{chat_id}|recurrentes')],
        [InlineKeyboardButton('⚙️ Ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html(text, reply_markup=markup)
    raise _V199Stop


_old_build_application_v199 = build_application

def build_application() -> Application:
    app = _old_build_application_v199()
    app.add_handler(CallbackQueryHandler(_v199_phrase_router, pattern=r'^cfg\|phrase_'), group=-26000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, admin_private_config_text), group=-26000000000)
    app.add_handler(CallbackQueryHandler(_v199_saveclose_router, pattern=r'^cfg\|saveclose\|-?\d+$'), group=-26000000000)
    app.add_handler(CallbackQueryHandler(_v199_recurring_manual_router, pattern=r'^(cfg\|rec_send\||cfg\|rblk_send\||panelrun\|rblk\||panelcfg\|control\|)'), group=-26000000000)
    app.add_handler(CallbackQueryHandler(_v199_health_router, pattern=r'^(checkbot\|-?\d+|cfg\|botcheck\|-?\d+)$'), group=-26000000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v199_scheduler_tick, interval=60, first=6, name='v199_scheduler_tick')
            logger.info('V199 scheduler registrado en JobQueue')
    except Exception:
        logger.exception('V199 no pudo registrar JobQueue')
    async def _v199_post_init(app_: Application) -> None:
        try:
            if '_v189_post_init' in globals():
                await _v189_post_init(app_)
        except Exception:
            logger.exception('V199 post_init heredado falló')
        if app_.bot_data.get('v199_scheduler_started'):
            return
        app_.bot_data['v199_scheduler_started'] = True
        try:
            app_.create_task(_v199_scheduler_loop(app_), name='v199_scheduler_loop')
        except TypeError:
            app_.create_task(_v199_scheduler_loop(app_))
    app.post_init = _v199_post_init
    logger.info('V199 frase del día/recurrentes/panel inferior cargado')
    return app


async def _v199_scheduler_loop(app: Application) -> None:
    logger.info('V199 scheduler interno arrancado')
    while True:
        try:
            class _Ctx:
                application = app
                bot = app.bot
            await _v199_scheduler_tick(_Ctx())
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V199 scheduler loop error')
        await asyncio.sleep(60)


