def _v200_phrase_key(phrase: str) -> str:
    if '_v114_phrase_key' in globals():
        try:
            return _v114_phrase_key(phrase)
        except Exception:
            pass
    return ' '.join(str(phrase or '').lower().split())[:220]


def _v200_likes_store(chat_id: int) -> Dict[str, Any]:
    if '_v114_phrase_likes_store' in globals():
        try:
            return _v114_phrase_likes_store(chat_id)
        except Exception:
            pass
    return admin_cfg(chat_id).setdefault('daily_phrase_likes', {})


def _v200_like_count(chat_id: int, phrase: str) -> int:
    try:
        likes = _v200_likes_store(chat_id)
        row = likes.get(_v200_phrase_key(phrase), {}) if isinstance(likes, dict) else {}
        users = row.get('users', []) if isinstance(row, dict) else []
        return len(users or [])
    except Exception:
        return 0


def _v200_phrase_title(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    raw_title = str(cfg.get('daily_phrase_title') or '🌞 Frase del día').strip()

    raw_title = raw_title.replace('━', '').replace('─', '').strip()
    return f'1️⃣  {raw_title}  1️⃣'


def _v200_phrase_caption(chat_id: int, phrase: str) -> str:
    likes = _v200_like_count(chat_id, phrase)
    title = _v200_phrase_title(chat_id)
    quote = str(phrase or '').strip()

    quote = quote.strip('“”"')
    return (
        f'<b>━━━━━━━━ {h(title)} ━━━━━━━━</b>\n\n'
        f'<b><i>“{h(quote)}”</i></b>\n\n'
        f'❤️ Me gusta: <b>{likes}</b>'
    )


def _v114_phrase_caption(chat_id: int, phrase: str) -> str:
    return _v200_phrase_caption(chat_id, phrase)


def _v200_phrase_markup(chat_id: int, message_id: int, phrase: Optional[str] = None) -> InlineKeyboardMarkup:
    likes = _v200_like_count(chat_id, phrase or '') if phrase else 0
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton('💪 Vitamina IA', callback_data=f'dphrase|vitamina|{int(chat_id)}|{int(message_id)}'),
            InlineKeyboardButton(f'❤️ Me gusta · {likes}', callback_data=f'dphrase|like|{int(chat_id)}|{int(message_id)}'),
        ]
    ])


def _v197_phrase_markup(chat_id: int, message_id: int) -> InlineKeyboardMarkup:
    try:
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_sent_messages', {})
        entry = store.get(str(message_id), {}) if isinstance(store, dict) else {}
        phrase = str(entry.get('phrase') or '') if isinstance(entry, dict) else ''
        return _v200_phrase_markup(chat_id, message_id, phrase)
    except Exception:
        return _v200_phrase_markup(chat_id, message_id, '')


def _v114_phrase_markup(chat_id: int, message_id: int) -> InlineKeyboardMarkup:
    return _v197_phrase_markup(chat_id, message_id)


async def _v200_update_phrase_message(bot, chat_id: int, message_id: int) -> None:
    store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_sent_messages', {})
    entry = store.get(str(message_id)) if isinstance(store, dict) else None
    if not isinstance(entry, dict):
        return
    phrase = str(entry.get('phrase') or '').strip()
    if not phrase:
        return
    text = _v200_phrase_caption(chat_id, phrase)
    markup = _v200_phrase_markup(chat_id, message_id, phrase)
    kind = str(entry.get('kind') or 'text')
    try:
        if kind == 'photo':
            await bot.edit_message_caption(chat_id=chat_id, message_id=message_id, caption=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        raise


async def _v200_send_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False, phrase: Optional[str] = None) -> Optional[int]:
    """Envío V200: mismo flujo robusto V199, pero con formato cita y likes visibles desde el inicio."""
    chat_id = int(chat_id)
    cfg = _v199_cfg(chat_id) if '_v199_cfg' in globals() else admin_cfg(chat_id)
    now_ts = int(now_ts or time.time())
    phrase = str(phrase or (_v199_daily_phrase_text(chat_id, now_ts) if '_v199_daily_phrase_text' in globals() else daily_phrase_for_chat_v30(chat_id, now_ts))).strip()
    if not phrase:
        phrase = 'Hoy es un buen día para tener un gran día. — J.M.'
    caption = _v200_phrase_caption(chat_id, phrase)
    msg = None
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    if image and image.get('file_id') and bool(cfg.get('daily_phrase_image_enabled', True)):
        try:
            msg = await bot.send_photo(chat_id, photo=image.get('file_id'), caption=caption, parse_mode=ParseMode.HTML, reply_markup=None)
        except Exception:
            logger.exception('V200 envío con foto falló; uso texto')
    if msg is None:
        try:
            msg = await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        except Exception:
            logger.exception('V200 envío HTML falló; uso texto plano')
            msg = await bot.send_message(chat_id, f'{_v200_phrase_title(chat_id)}\n\n“{phrase}”\n\n❤️ Me gusta: 0', disable_web_page_preview=True)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    try:
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else cfg.setdefault('daily_phrase_sent_messages', {})
        store[str(msg.message_id)] = {'phrase': phrase, 'kind': 'photo' if getattr(msg, 'photo', None) else 'text', 'next_used': [], 'sent_ts': now_ts}

        likes = _v200_likes_store(chat_id)
        likes.setdefault(_v200_phrase_key(phrase), {'text': phrase, 'users': []})
        save_all_states()
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v200_phrase_markup(chat_id, msg.message_id, phrase))
    except Exception:
        logger.exception('V200 no pudo registrar botones de frase')
    if bool(cfg.get('daily_phrase_pin', False)):
        try:
            await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
        except Exception:
            pass
    return int(msg.message_id)


async def _v199_send_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False, phrase: Optional[str] = None) -> Optional[int]:
    return await _v200_send_phrase(bot, chat_id, now_ts=now_ts, force=force, phrase=phrase)


async def _v197_send_phrase_text(bot, chat_id: int, phrase: str) -> Optional[int]:
    return await _v200_send_phrase(bot, chat_id, now_ts=int(time.time()), force=True, phrase=phrase)


async def _v200_dphrase_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('dphrase|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 4:
        return
    action = parts[1]
    try:
        chat_id = int(parts[2]); msg_id = int(parts[3])
    except Exception:
        await q.answer('Botón inválido.', show_alert=True)
        raise _V200Stop

    if action == 'vitamina':
        try:
            await q.answer('Te pregunto cómo te sientes 👇')
        except Exception:
            pass
        ask_text = '¿Cómo te sientes? Escríbelo y envía.'
        if '_v126_ask_for_query' in globals():
            await _v126_ask_for_query(context, chat_id, q.from_user, 'vitamina', ask_text, reply_to=msg_id)
        else:
            set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v126', 'chat_id': int(chat_id), 'cmd': 'vitamina'})
            await context.bot.send_message(chat_id=chat_id, text=f'{q.from_user.mention_html()} {h(ask_text)}', parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=msg_id)
        raise _V200Stop

    if action == 'like':
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else admin_cfg(chat_id).setdefault('daily_phrase_sent_messages', {})
        entry = store.get(str(msg_id)) if isinstance(store, dict) else None
        if not isinstance(entry, dict):
            await q.answer('Esta frase ya no está activa.', show_alert=True)
            raise _V200Stop
        phrase = str(entry.get('phrase') or '').strip()
        if not phrase:
            await q.answer('No encuentro la frase.', show_alert=True)
            raise _V200Stop
        uid = str(int(q.from_user.id))
        likes = _v200_likes_store(chat_id)
        row = likes.setdefault(_v200_phrase_key(phrase), {'text': phrase, 'users': []})
        users = row.setdefault('users', [])
        if uid not in users:
            users.append(uid)
            row['text'] = phrase
            save_all_states()
            try:
                await _v200_update_phrase_message(context.bot, chat_id, msg_id)
            except Exception:
                logger.exception('V200 no pudo actualizar contador de likes en frase')
            await q.answer(f'❤️ Me gusta añadido · Total: {len(users)}')
        else:
            await q.answer(f'Ya habías dado me gusta ❤️ · Total: {len(users)}')
        raise _V200Stop


