def _v201_clean_configured_title(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    title = str(cfg.get('daily_phrase_title') or 'Frase del día').strip()

    for token in ('1️⃣', '━', '─'):
        title = title.replace(token, '')
    title = ' '.join(title.split()).strip()
    return title or 'Frase del día'


def _v201_is_jm_phrase(text: str) -> tuple[bool, str]:
    raw = str(text or '').strip()
    if not raw:
        return False, raw

    work = raw.strip().strip('“”"').strip()
    variants = [
        '— J.M.', '– J.M.', '- J.M.', '— JM', '– JM', '- JM',
        'J.M.', 'JM', 'J. M.', 'J.M', 'J M'
    ]
    low = work.lower().rstrip()
    for v in variants:
        vl = v.lower()
        if low.endswith(vl):
            body = work[:len(work)-len(v)].rstrip(' .—–-').strip()
            return True, body or work
    return False, work


def _v201_display_phrase(phrase: str) -> str:
    is_jm, body = _v201_is_jm_phrase(phrase)
    body = body.strip().strip('“”"').strip()
    if is_jm:
        return f'✨✨ {body} ✨✨'
    return body


def _v200_phrase_title(chat_id: int) -> str:
    return _v201_clean_configured_title(chat_id)


def _v200_phrase_caption(chat_id: int, phrase: str) -> str:
    likes = _v200_like_count(chat_id, phrase)
    title = _v201_clean_configured_title(chat_id)
    quote = _v201_display_phrase(phrase)
    return (
        f'<b>{h(title)}</b>\n\n'
        f'<b><i>“{h(quote)}”</i></b>\n\n'
        f'❤️ Me gusta: <b>{likes}</b>'
    )


