def _v202_block_item_to_rid(item: Any) -> Optional[int]:
    """Convierte un item histórico de bloque a ID de recurrente sin alterar su posición."""
    rid: Any = None
    if isinstance(item, dict):
        for k in ('id', 'rid', 'rec_id', 'recurring_id'):
            if item.get(k) is not None:
                rid = item.get(k)
                break
        if rid is None:
            rid = item.get('key')
    else:
        rid = item
    if isinstance(rid, str):
        s = rid.strip()
        for prefix in ('recsend_', 'rec:', 'rec_'):
            if s.startswith(prefix):
                s = s.split(prefix, 1)[1]
                break
        rid = s
    try:
        rid_int = int(rid)
        return rid_int if rid_int > 0 else None
    except Exception:
        return None


def _v181_extract_rids_from_block(block: Dict[str, Any]) -> List[int]:
    """Extrae recurrentes respetando el orden/posición de los IDs dentro del bloque.

    Importante: NO deduplicamos ni ordenamos por tipo de contenido.
    Manda la posición que tú hayas colocado: #12, luego #7, luego #4, etc.
    Da igual si ese recurrente es imagen, texto, vídeo o mensaje con botón.
    """
    raw_items: List[Any] = []

    if isinstance(block.get('items'), list):
        raw_items.extend(block.get('items') or [])

    if not raw_items:
        for key in ('rids', 'recurring_ids', 'recurrentes', 'recurrents'):
            val = block.get(key)
            if isinstance(val, list):
                raw_items.extend(val)
            elif val not in (None, ''):
                raw_items.append(val)
    out: List[int] = []
    for item in raw_items:
        rid = _v202_block_item_to_rid(item)
        if rid is not None:
            out.append(rid)
    return out


def _v202_rec_block_name(block: Dict[str, Any]) -> str:
    return str(block.get('name') or block.get('title') or f"Bloque {block.get('id','')}").strip() or 'Bloque'


def _v171_rec_blocks_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Lista de bloques con columna para lanzar ahora sin entrar al bloque."""
    rows: List[List[InlineKeyboardButton]] = []
    blocks = _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []
    for b in blocks:
        try:
            bid = int(b.get('id', 0) or 0)
        except Exception:
            continue
        name = _v202_rec_block_name(b)
        count = len(_v181_extract_rids_from_block(b)) if '_v181_extract_rids_from_block' in globals() else len(b.get('items', []) or [])
        rows.append([
            InlineKeyboardButton(f"📦 #{bid} · {truncated_button_title(name, 29)} ({count})", callback_data=f'cfg|rblk_open|{chat_id}|{bid}'),
            InlineKeyboardButton('▶️ Lanzar', callback_data=f'cfg|rblk_send|{chat_id}|{bid}'),
        ])
    rows.append([InlineKeyboardButton('➕ Crear bloque recurrente', callback_data=f'cfg|rblk_new|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Recurrentes', callback_data=f'cfg|block|{chat_id}|recurrentes')])
    return InlineKeyboardMarkup(rows)


def _v171_rec_blocks_text(chat_id: int) -> str:
    blocks = _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []
    lines = [
        '<b>📦 Bloques recurrentes</b>',
        '',
        'Abre un bloque para configurarlo o pulsa <b>▶️ Lanzar</b> para enviarlo ahora.',
        'El envío respeta la posición de los IDs dentro del bloque: primero el primer ID colocado, después el segundo, y así sucesivamente.',
    ]
    if not blocks:
        lines.append('\nNo hay bloques todavía.')
    else:
        for b in blocks:
            try:
                bid = int(b.get('id', 0) or 0)
            except Exception:
                bid = 0
            items = _v181_extract_rids_from_block(b) if '_v181_extract_rids_from_block' in globals() else []
            lines.append(f"\n<b>#{bid}</b> {h(_v202_rec_block_name(b))} · <b>{len(items)}</b> recurrentes")
    return '\n'.join(lines)


def _v171_rec_block_text(chat_id: int, bid: int) -> str:
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    b = b or {'id': bid, 'name': 'Bloque', 'items': []}
    lines = [
        f"<b>📦 {h(_v202_rec_block_name(b))}</b>",
        '',
        'Orden de envío:',
    ]
    rids = _v181_extract_rids_from_block(b)
    if not rids:
        lines.append('Sin recurrentes todavía.')
    for pos, rid in enumerate(rids, 1):
        row = recurring_find(chat_id, rid) if 'recurring_find' in globals() else None
        name = str((row or {}).get('name') or (row or {}).get('title') or 'Recurrente')
        lines.append(f"{pos}. #{rid} · {h(name)}")
    lines.append('')
    lines.append('<i>Se enviará exactamente en este orden/posición de IDs, sea imagen, texto o lo que sea.</i>')
    return '\n'.join(lines)


async def _v181_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[int, int, List[str]]:
    """Envía un bloque en orden estricto."""
    block = _v181_find_rec_block(chat_id, bid) if '_v181_find_rec_block' in globals() else None
    if not block:
        return 0, 0, ['No encuentro ese bloque recurrente.']
    rids = _v181_extract_rids_from_block(block)
    if not rids:
        return 0, 0, ['El bloque está vacío. Añade recurrentes dentro del bloque.']
    ok = 0
    errors: List[str] = []
    total = len(rids)
    for pos, rid in enumerate(rids, 1):
        row = recurring_find(chat_id, int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'{pos}. #{rid} no existe')
            continue
        try:

            if '_v181_send_recurring_manual_clean' in globals():
                await _v181_send_recurring_manual_clean(context, chat_id, row)
            elif '_v170_send_recurring_manual' in globals():
                await _v170_send_recurring_manual(context, chat_id, dict(row))
            else:
                await send_recurring_message(context, chat_id, dict(row))
            ok += 1

            await asyncio.sleep(1.0)
        except Exception:
            logger.exception('V202 bloque %s falló en posición %s recurrente #%s', bid, pos, rid)
            errors.append(f'{pos}. #{rid} error')
    return ok, total, errors


async def _v178_run_rblk(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[bool, str]:
    ok, total, errors = await _v181_send_rec_block(context, chat_id, bid)
    if total <= 0:
        return False, errors[0] if errors else 'El bloque está vacío.'
    if ok <= 0:
        return False, 'No se envió ningún recurrente del bloque. ' + (' · '.join(errors[:3]) if errors else '')
    if errors:
        return True, f'Bloque enviado parcialmente y en orden: {ok}/{total} ⚠️'
    return True, f'Bloque enviado en orden de IDs: {ok}/{total} ✅'


async def _v202_rblk_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('cfg|rblk_send|') or data.startswith('panelrun|rblk|') or (data.startswith('panelcfg|control|') and '|rblksend_' in data)):
        return
    try:
        if data.startswith('cfg|rblk_send|'):
            parts = data.split('|')
            chat_id = int(parts[2]); bid = int(parts[3])
        elif data.startswith('panelrun|rblk|'):
            parts = data.split('|')
            chat_id = int(parts[2]); bid = int(parts[3])
        else:
            parts = data.split('|')
            chat_id = int(parts[2]); key = str(parts[3])
            bid = int(key.split('_', 1)[1])
        ok, total, errors = await _v181_send_rec_block(context, chat_id, bid)
        if total <= 0:
            await q.answer(errors[0] if errors else 'El bloque está vacío.', show_alert=True)
        elif ok <= 0:
            await q.answer('No se envió ningún recurrente. ' + (' · '.join(errors[:3]) if errors else ''), show_alert=True)
        elif errors:
            await q.answer(f'Bloque enviado parcialmente: {ok}/{total}', show_alert=True)
        else:
            await q.answer(f'Bloque enviado en orden de IDs: {ok}/{total} ✅', show_alert=False)

        try:
            await q.edit_message_text(_v171_rec_blocks_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_blocks_markup(chat_id))
        except Exception:
            pass
        raise _V202Stop
    except _V202Stop:
        raise
    except Exception:
        logger.exception('V202 error lanzando bloque recurrente: %s', data)
        try:
            await q.answer('No pude lanzar el bloque. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V202Stop


_old_build_application_v203 = build_application

def build_application() -> Application:
    app = _old_build_application_v203()
    app.add_handler(CallbackQueryHandler(_v202_rblk_send_router, pattern=r'^(cfg\|rblk_send\||panelrun\|rblk\||panelcfg\|control\|)'), group=-27000000000)
    logger.info('V203 bloques recurrentes: orden por posición/ID y pausa 1s cargado')
    return app


