        rows.append([InlineKeyboardButton('🏆 Lanzar todos hoy', callback_data=f'awdpro|all|{chat_id}|daily'), InlineKeyboardButton('📆 Lanzar todos semana', callback_data=f'awdpro|all|{chat_id}|weekly')])
