def _v206_ensure_polls_block_visible() -> None:
    """Asegura el bloque polls en la lista interna de bloques privados."""
    try:
        existing = {str(k) for k, _label in ADMIN_PRIVATE_BLOCKS}
        if 'polls' not in existing:
            insert_at = len(ADMIN_PRIVATE_BLOCKS)

            for i, (key, _label) in enumerate(ADMIN_PRIVATE_BLOCKS):
                if key in ('awards', 'recurrentes', 'lists'):
                    insert_at = i + 1
            ADMIN_PRIVATE_BLOCKS.insert(insert_at, ('polls', '📊 Encuestas'))
        try:
            ADMIN_PRIVATE_BLOCK_IDS.add('polls')
        except Exception:
            pass
    except Exception:
        logger.exception('V206 no pudo registrar bloque polls')


_v206_ensure_polls_block_visible()


_old_v206_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Fuerza el botón 📊 Encuestas en el panel principal de ajustes si no aparece."""
    _v206_ensure_polls_block_visible()
    markup = _old_v206_admin_private_main_markup(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]
    found = False
    for r in rows:
        for b in r:
            cb = getattr(b, 'callback_data', '') or ''
            txt = getattr(b, 'text', '') or ''
            if 'polls' in cb or 'Encuestas' in txt or 'encuesta' in txt.lower():
                found = True
                break
        if found:
            break
    if not found:

        insert_at = max(1, len(rows) - 2)
        for i, r in enumerate(rows):
            joined = ' '.join((getattr(b, 'text', '') or '') for b in r)
            if 'Premios' in joined or 'Frase' in joined or 'Recurrentes' in joined:
                insert_at = i + 1
        rows.insert(insert_at, [InlineKeyboardButton('📊 Encuestas', callback_data=f'cfg|block|{chat_id}|polls')])
    return InlineKeyboardMarkup(rows)


async def _v206_render_polls(query, chat_id: int) -> None:
    _v206_ensure_polls_block_visible()
    try:
        await query.edit_message_text(
            admin_private_block_text(chat_id, 'polls'),
            parse_mode=ParseMode.HTML,
            reply_markup=admin_private_block_markup(chat_id, 'polls'),
        )
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        try:
            await query.message.reply_html(admin_private_block_text(chat_id, 'polls'), reply_markup=admin_private_block_markup(chat_id, 'polls'))
        except Exception:
            raise
    except Exception:
        try:
            await query.message.reply_html(admin_private_block_text(chat_id, 'polls'), reply_markup=admin_private_block_markup(chat_id, 'polls'))
        except Exception:
            raise


async def _v206_polls_block_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('cfg|block|') and data.endswith('|polls')):
        return
    try:
        parts = data.split('|')
        chat_id = int(parts[2])
        await q.answer()
        await _v206_render_polls(q, chat_id)
    except Exception:
        logger.exception('V206 no pudo abrir menú de encuestas: %s', data)
        try:
            await q.answer('No pude abrir encuestas. Mira logs.', show_alert=True)
        except Exception:
            pass
    raise _V206Stop


async def _v206_polls_actions_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Da prioridad a acciones cfg|poll_* para que no las capture otro router de ajustes."""
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|poll_'):
        return
    try:

        await admin_private_config_callback(update, context)
    except _V206Stop:
        raise
    except Exception:
        logger.exception('V206 error en acción de encuesta: %s', q.data)
        try:
            await q.answer('Error en encuestas. Mira logs.', show_alert=True)
        except Exception:
            pass
    raise _V206Stop


async def _v206_encuestas_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Comando directo de recuperación por si el botón no aparece en alguna capa."""
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == 'private':

        chat_id = None
        try:
            chat_id = dj_selected_private_group(update.effective_user.id)
        except Exception:
            pass
        if chat_id is None:
            try:
                chats = known_admin_chats_for_private()
                chat_id = int(chats[0]) if chats else None
            except Exception:
                chat_id = None
        if chat_id is None:
            await update.message.reply_html('Primero abre <code>/ajustes</code> y selecciona un grupo, o ejecuta /encuestas dentro del grupo.')
            return
        await update.message.reply_html(admin_private_block_text(int(chat_id), 'polls'), reply_markup=admin_private_block_markup(int(chat_id), 'polls'))
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text('Solo administradores.')
        return
    await update.message.reply_html(admin_private_block_text(chat_id, 'polls'), reply_markup=admin_private_block_markup(chat_id, 'polls'))


_old_build_application_v206 = build_application

def build_application() -> Application:
    app = _old_build_application_v206()
    app.add_handler(CallbackQueryHandler(_v206_polls_block_router, pattern=r'^cfg\|block\|-?\d+\|polls$'), group=-30000000000)
    app.add_handler(CallbackQueryHandler(_v206_polls_actions_router, pattern=r'^cfg\|poll_'), group=-30000000000)
    app.add_handler(command_handler('encuestas', _v206_encuestas_command), group=-30000000000)
    logger.info('V206 menú de encuestas recuperado y blindado')
    return app


