def _v207_awards_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v205_awards_cfg(chat_id) if '_v205_awards_cfg' in globals() else (_v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id))
    cfg.setdefault('awards_schedule_mode', 'all')
    cfg.setdefault('awards_minute_sent', {})
    cfg.setdefault('awards_texts', {})
    defaults = {
        'parlante': 'Hoy destacamos a {ganador} como {premio}. Ha mantenido vivo el grupo durante el {periodo}.',
        'risas': 'Hoy destacamos a {ganador} como {premio}. Gracias por llenar el grupo de buen rollo durante el {periodo}.',
        'holi': 'Hoy destacamos a {ganador} como {premio}. Sus saludos han puesto energía al grupo durante el {periodo}.',
        'noctambulo': 'Hoy destacamos a {ganador} como {premio}. Ha estado presente cuando otros ya descansaban durante el {periodo}.',
        'pareja': 'Hoy destacamos a {ganador} como {premio}. Su conexión ha dado juego al grupo durante el {periodo}.',
        'competidor': 'Hoy destacamos a {ganador} como {premio}. Ha sumado puntos y participación durante el {periodo}.',
    }
    for k, v in defaults.items():
        cfg.setdefault('awards_texts', {}).setdefault(k, v)
        cfg.setdefault(f'awards_{k}_enabled', True)

    if 'awards_pair_enabled' in cfg and 'awards_pareja_enabled' not in cfg:
        cfg['awards_pareja_enabled'] = bool(cfg.get('awards_pair_enabled'))
    return cfg


def _v207_award_enabled(chat_id: int, kind: str) -> bool:
    cfg = _v207_awards_cfg(chat_id)
    if kind == 'pareja' and 'awards_pair_enabled' in cfg:
        return bool(cfg.get('awards_pareja_enabled', cfg.get('awards_pair_enabled', True)))
    return bool(cfg.get(f'awards_{kind}_enabled', True))


def _v207_set_award_enabled(chat_id: int, kind: str, value: bool) -> None:
    cfg = _v207_awards_cfg(chat_id)
    cfg[f'awards_{kind}_enabled'] = bool(value)
    if kind == 'pareja':
        cfg['awards_pair_enabled'] = bool(value)
    save_all_states()


def _v207_enabled_awards(chat_id: int) -> List[Tuple[str, str]]:
    return [(kind, label) for kind, label in V205_AWARD_TYPES if _v207_award_enabled(chat_id, kind)]


async def _v207_send_all_awards(context: ContextTypes.DEFAULT_TYPE, chat_id: int, period: str = 'daily') -> int:
    ok = 0
    if not bool(_v207_awards_cfg(chat_id).get('awards_enabled', True)):
        return 0
    for kind, _label in _v207_enabled_awards(chat_id):
        try:
            await _v205_send_award(context, chat_id, kind, period)
            ok += 1
            await asyncio.sleep(1.0)
        except Exception:
            logger.exception('V207 fallo enviando premio %s', kind)
    return ok


def _v207_time_to_minutes(value: str) -> Optional[int]:
    try:
        hh, mm = str(value or '').strip().split(':', 1)
        return int(hh) * 60 + int(mm)
    except Exception:
        return None


def _v207_period_key(period: str) -> str:
    if period == 'weekly':
        return _v167_stats_week_key() if '_v167_stats_week_key' in globals() else time.strftime('%G-%V')
    return _v167_stats_day_key() if '_v167_stats_day_key' in globals() else time.strftime('%Y-%m-%d')


def _v207_period_enabled_and_due(cfg: Dict[str, Any], period: str) -> Tuple[bool, str, str]:
    if period == 'weekly':
        enabled = bool(cfg.get('awards_weekly_enabled', False))
        when = str(cfg.get('awards_weekly_time', '23:30'))
        wanted_day = str(cfg.get('awards_weekly_day', 'SU'))[:2].upper()
        today_day = time.strftime('%a').upper()[:2]
        return enabled and today_day == wanted_day, when, 'awards_last_weekly'
    return bool(cfg.get('awards_daily_enabled', True)), str(cfg.get('awards_daily_time', '23:30')), 'awards_last_daily'


async def _v207_awards_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now_hm = time.strftime('%H:%M')
    now_minutes = _v207_time_to_minutes(now_hm)
    if now_minutes is None:
        return
    for chat_id in list(STATE_CACHE.keys()):
        try:
            cfg = _v207_awards_cfg(int(chat_id))
            if not bool(cfg.get('awards_enabled', True)):
                continue
            mode = str(cfg.get('awards_schedule_mode', 'all') or 'all')
            for period in ('daily', 'weekly'):
                enabled, when, last_key_name = _v207_period_enabled_and_due(cfg, period)
                if not enabled:
                    continue
                scheduled_minutes = _v207_time_to_minutes(when)
                if scheduled_minutes is None or now_minutes < scheduled_minutes:
                    continue
                key = f'{period}:{_v207_period_key(period)}'
                if mode == 'minute':
                    sent_map = cfg.setdefault('awards_minute_sent', {})
                    sent = sent_map.setdefault(key, [])
                    enabled_awards = _v207_enabled_awards(int(chat_id))
                    if len(sent) >= len(enabled_awards):
                        cfg[last_key_name] = _v207_period_key(period)
                        save_all_states()
                        continue

                    slot_key = f'{key}:{now_hm}'
                    if cfg.get('awards_minute_last_slot') == slot_key:
                        continue
                    next_kind = None
                    for kind, _label in enabled_awards:
                        if kind not in sent:
                            next_kind = kind
                            break
                    if not next_kind:
                        cfg[last_key_name] = _v207_period_key(period)
                        save_all_states()
                        continue
                    await _v205_send_award(context, int(chat_id), next_kind, period)
                    sent.append(next_kind)
                    cfg['awards_minute_last_slot'] = slot_key
                    if len(sent) >= len(enabled_awards):
                        cfg[last_key_name] = _v207_period_key(period)
                    save_all_states()
                else:
                    period_key = _v207_period_key(period)
                    if cfg.get(last_key_name) == period_key:
                        continue

                    if now_hm != when:
                        continue
                    await _v207_send_all_awards(context, int(chat_id), period)
                    cfg[last_key_name] = period_key
                    save_all_states()
        except Exception:
            logger.exception('V207 scheduler premios falló chat %s', chat_id)


