async def _v207_awards_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('awdpro|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V207Stop
    cfg = _v207_awards_cfg(chat_id)
    try:
        if action == 'mode':
            cfg['awards_schedule_mode'] = 'all' if str(cfg.get('awards_schedule_mode', 'all')) == 'minute' else 'minute'
            save_all_states()
            await q.answer('Modo actualizado')
            await q.edit_message_text(admin_private_block_text(chat_id, 'awards'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'awards'))
            raise _V207Stop
        if action == 'toggleaward':
            kind = parts[3]
            _v207_set_award_enabled(chat_id, kind, not _v207_award_enabled(chat_id, kind))
            await q.answer('Premio actualizado')
            await q.edit_message_text(admin_private_block_text(chat_id, 'awards'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'awards'))
            raise _V207Stop
        if action == 'send':
            kind = parts[3]; period = parts[4] if len(parts) > 4 else 'daily'
            await q.answer('Enviando premio…')
            await _v205_send_award(context, chat_id, kind, period)
            raise _V207Stop
        if action == 'all':
            period = parts[3] if len(parts) > 3 else 'daily'
            await q.answer('Enviando premios activos…')
            ok = await _v207_send_all_awards(context, chat_id, period)
            await q.message.reply_html(f'✅ Premios enviados: <b>{ok}</b>')
            raise _V207Stop

    except _V207Stop:
        raise
    except Exception:
        logger.exception('V207 error premios sociales: %s', q.data)
        try: await q.answer('Error en premios. Mira logs.', show_alert=True)
        except Exception: pass
        raise _V207Stop


_old_build_application_v207 = build_application

def build_application() -> Application:
    app = _old_build_application_v207()
    app.add_handler(CallbackQueryHandler(_v207_awards_router, pattern=r'^awdpro\|(mode|toggleaward|send|all)\|'), group=-31000000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v207_awards_scheduler_tick, interval=60, first=20, name='v207_awards_scheduler')
    except Exception:
        logger.exception('V207 no pudo iniciar scheduler de premios sociales')
    logger.info('V207 premios sociales ON/OFF por premio y programación por minuto cargado')
    return app


