def _v208_period_day_key(entry: Dict[str, Any]) -> str:
    try:
        if entry.get('period') == 'weekly':
            return _v167_stats_week_key() if '_v167_stats_week_key' in globals() else time.strftime('%G-%V')
        return _v168_today_key() if '_v168_today_key' in globals() else time.strftime('%Y-%m-%d')
    except Exception:
        return time.strftime('%Y-%m-%d')


def _v205_award_key(chat_id: int, entry: Dict[str, Any]) -> str:
    """Clave corta y estable para likes de premios.

    El callback final queda como: awdlike|CHAT_ID|daily:parlante:HASH
    Evita el error Telegram Button_data_invalid.
    """
    import hashlib
    period = str(entry.get('period') or 'daily')[:8]
    kind = str(entry.get('kind') or 'award')[:18]
    day = _v208_period_day_key(entry)
    winner = str(entry.get('winner') or 'sin_datos')
    raw = f'{chat_id}|{period}|{kind}|{day}|{winner}'
    digest = hashlib.blake2s(raw.encode('utf-8', 'ignore'), digest_size=6).hexdigest()
    return f'{period}:{kind}:{digest}'


def _v205_award_markup(chat_id: int, entry: Dict[str, Any]) -> InlineKeyboardMarkup:
    key = _v205_award_key(chat_id, entry)
    cfg = _v205_awards_cfg(chat_id)
    row = cfg.setdefault('awards_likes', {}).setdefault(key, {'users': [], 'entry': entry})
    row['entry'] = entry
    count = len(row.get('users', []) or [])
    callback = f'awdlike|{int(chat_id)}|{key}'

    if len(callback.encode('utf-8')) > 64:
        callback = f'awdlike|{int(chat_id)}|{key[-24:]}'
        cfg.setdefault('awards_likes', {}).setdefault(key[-24:], row)
    return InlineKeyboardMarkup([[InlineKeyboardButton(f'❤️ Me gusta · {count}', callback_data=callback)]])


def _v208_safe_award_text(chat_id: int, entry: Dict[str, Any], likes: int = 0) -> str:
    """Texto compatible con HTML; escapa el texto personalizado para evitar errores."""
    cfg = _v205_awards_cfg(chat_id)
    header = cfg.get('awards_header_weekly' if entry.get('period') == 'weekly' else 'awards_header_daily') or ('Miembros de la semana' if entry.get('period') == 'weekly' else 'Miembros del día')
    template = (cfg.setdefault('awards_texts', {}).get(entry.get('kind')) or '').strip()
    if template:
        try:
            custom_raw = template.format(
                ganador=entry.get('winner') or '',
                valor=entry.get('value') or '',
                premio=entry.get('label') or '',
                periodo='semana' if entry.get('period') == 'weekly' else 'día',
            )
        except Exception:
            custom_raw = template
    else:
        custom_raw = f"Hoy este premio es para {entry.get('winner') or 'Sin datos'}."
    return (
        f"<b>🏆 {h(header)}</b>\n\n"
        f"<b>{h(entry.get('label') or 'Premio')}</b>\n"
        f"{h(custom_raw)}\n\n"
        f"<b>¿Por qué?</b> {h(entry.get('reason') or '')}\n"
        f"<b>Dato:</b> {h(entry.get('value') or 'sin datos')}\n\n"
        f"❤️ Me gusta: <b>{int(likes)}</b>"
    )


async def _v205_send_award(context: ContextTypes.DEFAULT_TYPE, chat_id: int, kind: str, period: str = 'daily') -> Optional[int]:
    """Envía un premio al grupo con fallbacks para no quedarse mudo."""
    cfg = _v205_awards_cfg(chat_id)
    entry = _v205_award_entry(chat_id, kind, period)
    key = _v205_award_key(chat_id, entry)
    cfg.setdefault('awards_likes', {}).setdefault(key, {'users': [], 'entry': entry})
    cfg['awards_likes'][key]['entry'] = entry


    media = (cfg.setdefault('awards_media', {}) or {}).get(kind) or cfg.setdefault('awards_media', {}).get('default')
    if media:
        try:
            await context.bot.send_photo(chat_id=int(chat_id), photo=media)
            await asyncio.sleep(0.35)
        except Exception:
            logger.exception('V208 no pudo enviar multimedia premio %s; sigo con texto', kind)

    text = _v208_safe_award_text(chat_id, entry, 0)
    markup = _v205_award_markup(chat_id, entry)
    try:
        msg = await context.bot.send_message(int(chat_id), text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except BadRequest as e:
        logger.exception('V208 fallo enviando premio HTML, intento texto simple: %s', e)

        plain = (
            f"🏆 {cfg.get('awards_header_weekly' if period == 'weekly' else 'awards_header_daily', 'Premios sociales')}\n\n"
            f"{entry.get('label') or 'Premio'}\n"
            f"Ganador: {entry.get('winner') or 'Sin datos'}\n"
            f"¿Por qué? {entry.get('reason') or ''}\n"
            f"Dato: {entry.get('value') or 'sin datos'}\n\n"
            "❤️ Me gusta: 0"
        )
        msg = await context.bot.send_message(int(chat_id), plain)
    cfg.setdefault('awards_sent_messages', {})[str(msg.message_id)] = {'key': key, 'entry': entry}
    save_all_states()
    return int(msg.message_id)


async def _v205_award_like_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user or not (q.data or '').startswith('awdlike|'):
        return
    parts = (q.data or '').split('|', 2)
    try:
        chat_id = int(parts[1]); key = parts[2]
    except Exception:
        return
    cfg = _v205_awards_cfg(chat_id)
    row = cfg.setdefault('awards_likes', {}).setdefault(key, {'users': [], 'entry': {}})
    users = row.setdefault('users', [])
    uid = int(update.effective_user.id)
    if uid in users:
        users.remove(uid); msg = 'Quitado'
    else:
        users.append(uid); msg = '¡Gracias!'
    save_all_states()
    await q.answer(msg)
    entry = row.get('entry') or {}
    try:


        await q.edit_message_text(_v208_safe_award_text(chat_id, entry, len(users)), parse_mode=ParseMode.HTML, reply_markup=_v205_award_markup(chat_id, entry))
    except Exception:
        logger.exception('V208 no pudo actualizar like premio')
    raise _V208Stop


async def _v208_awards_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('awdpro|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in ('send', 'all'):
        return
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V208Stop
    try:
        if action == 'send':
            kind = parts[3] if len(parts) > 3 else 'parlante'
            period = parts[4] if len(parts) > 4 else 'daily'
            await q.answer('Enviando premio…')
            mid = await _v205_send_award(context, chat_id, kind, period)
            await q.message.reply_html(f'✅ Premio enviado al grupo. ID mensaje: <b>{mid}</b>')
            raise _V208Stop
        if action == 'all':
            period = parts[3] if len(parts) > 3 else 'daily'
            await q.answer('Enviando premios activos…')
            ok = await _v207_send_all_awards(context, chat_id, period)
            await q.message.reply_html(f'✅ Premios enviados al grupo: <b>{ok}</b>')
            raise _V208Stop
    except _V208Stop:
        raise
    except Exception as e:
        logger.exception('V208 error enviando premio manual: %s', q.data)
        try:
            await q.answer('No pude enviar el premio. Mira logs.', show_alert=True)
            await q.message.reply_html('❌ Error enviando premio:<br><code>' + h(str(e)[-900:]) + '</code>')
        except Exception:
            pass
        raise _V208Stop


