def _v209_valid_hhmm(value: str) -> Optional[str]:
    try:
        txt = (value or '').strip().replace('.', ':').replace('h', ':')
        parts = txt.split(':')
        if len(parts) != 2:
            return None
        hh = int(parts[0]); mm = int(parts[1])
        if 0 <= hh <= 23 and 0 <= mm <= 59:
            return f'{hh:02d}:{mm:02d}'
    except Exception:
        return None
    return None


def _v209_rec_block_summary_line(chat_id: int, b: Dict[str, Any]) -> str:
    _v173_rec_block_defaults(b) if '_v173_rec_block_defaults' in globals() else None
    enabled = 'ON' if bool(b.get('enabled')) and b.get('mode') == 'daily' else 'OFF'
    time_s = str(b.get('time', '21:00') or '21:00')
    ids = _v181_extract_rids_from_block(b) if '_v181_extract_rids_from_block' in globals() else []
    return f'Auto: <b>{enabled}</b> · Hora: <b>{h(time_s)}</b> · Recurrentes: <b>{len(ids)}</b>'


_old_v209_rec_block_text = _v171_rec_block_text

def _v171_rec_block_text(chat_id: int, bid: int) -> str:
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    b = b or {'id': bid, 'name': 'Bloque', 'items': []}
    try:
        _v173_rec_block_defaults(b)
    except Exception:
        pass
    lines = [
        f"<b>📦 {h(_v202_rec_block_name(b) if '_v202_rec_block_name' in globals() else str(b.get('name','Bloque')))}</b>",
        '',
        _v209_rec_block_summary_line(chat_id, b),
        '',
        '<b>Orden de envío:</b>',
    ]
    rids = _v181_extract_rids_from_block(b) if '_v181_extract_rids_from_block' in globals() else [int(x) for x in (b.get('items') or []) if str(x).isdigit()]
    if not rids:
        lines.append('Sin recurrentes todavía.')
    for pos, rid in enumerate(rids, 1):
        row = recurring_find(chat_id, rid) if 'recurring_find' in globals() else None
        name = str((row or {}).get('name') or (row or {}).get('title') or 'Recurrente')
        lines.append(f'{pos}. #{rid} · {h(name)}')
    lines.extend([
        '',
        '<i>El bloque se lanza a la hora exacta indicada. Cada recurrente mantiene su propia configuración: repetir cada, hasta, hora fin, fijar, borrar anterior, multimedia y botones.</i>'
    ])
    return '\n'.join(lines)


_old_v209_rec_block_markup = _v171_rec_block_markup if '_v171_rec_block_markup' in globals() else None

def _v171_rec_block_markup(chat_id: int, bid: int) -> InlineKeyboardMarkup:
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    if not b:
        b = {'id': bid, 'items': [], 'enabled': False, 'mode': 'manual', 'time': '21:00'}
    try:
        _v173_rec_block_defaults(b)
    except Exception:
        pass
    current = set(str(x) for x in (b.get('items') or []))
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton('✏️ Cambiar nombre', callback_data=f'cfg|rblk_rename|{chat_id}|{bid}')],
        [InlineKeyboardButton('▶️ Lanzar este bloque', callback_data=f'cfg|rblk_send|{chat_id}|{bid}')],
        [
            InlineKeyboardButton(f"🤖 Auto {'ON' if b.get('enabled') and b.get('mode') == 'daily' else 'OFF'}", callback_data=f'cfg|rblk_auto|{chat_id}|{bid}'),
            InlineKeyboardButton(f"🕒 Hora exacta {b.get('time','21:00')}", callback_data=f'cfg|rblk_time_exact|{chat_id}|{bid}'),
        ],
    ]
    for row in recurring_list(chat_id) if 'recurring_list' in globals() else []:
        rid = str(row.get('id'))
        mark = '✅' if rid in current else '⬜'
        name = str(row.get('name') or row.get('title') or f'Recurrente {rid}')
        rows.append([InlineKeyboardButton(f'{mark} #{rid} · {truncated_button_title(name, 38)}', callback_data=f'cfg|rblk_toggle|{chat_id}|{bid}|{rid}')])
    rows.append([InlineKeyboardButton('🗑 Borrar bloque', callback_data=f'cfg|rblk_del|{chat_id}|{bid}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'cfg|rblk_list|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v209_rblk_time_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rblk_time'):
        return
    parts = (q.data or '').split('|')
    action = parts[1]
    try:
        chat_id = int(parts[2]); bid = int(parts[3])
    except Exception:
        await q.answer('Datos inválidos', show_alert=True)
        raise _V209Stop

    if action in ('rblk_time', 'rblk_time_exact'):
        set_config_pending(q.from_user.id, {'kind': 'rec_block_time_v209', 'chat_id': chat_id, 'bid': bid})
        await q.answer()
        try:
            await q.message.reply_html(
                '🕒 Envíame la <b>hora exacta</b> para lanzar este bloque recurrente.\n\n'
                'Formato: <code>HH:MM</code>\n'
                'Ejemplos: <code>09:07</code>, <code>21:30</code>, <code>00:05</code>\n\n'
                'El bloque se lanzará a esa hora. Los recurrentes conservarán su propia configuración de repetición, fijado y borrado anterior.'
            )
        except Exception:
            pass
        raise _V209Stop


_old_v209_private_text_router = _v173_private_text_router if '_v173_private_text_router' in globals() else None

async def _v209_private_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not pending or pending.get('kind') != 'rec_block_time_v209':
        if callable(_old_v209_private_text_router):
            return await _old_v209_private_text_router(update, context)
        return
    txt = (update.message.text or update.message.caption or '').strip()
    hm = _v209_valid_hhmm(txt)
    chat_id = int(pending.get('chat_id') or 0)
    bid = int(pending.get('bid') or 0)
    if not hm:
        await update.message.reply_html('❌ Hora no válida. Escríbela como <code>HH:MM</code>. Ejemplo: <code>21:35</code>')
        raise _V209Stop
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    if not b:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('❌ No encuentro ese bloque recurrente.')
        raise _V209Stop
    try:
        _v173_rec_block_defaults(b)
    except Exception:
        pass
    b['time'] = hm

    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html(
        f'✅ Hora exacta guardada: <b>{hm}</b>\n\n'
        'Activa <b>Auto ON</b> en el bloque para que se lance automáticamente a esa hora.'
    )
    raise _V209Stop


async def _v209_send_rec_block_at_schedule(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    """Disparo programado de bloque: usa la configuración real de cada recurrente, sin modificarla."""
    try:
        bid = int(b.get('id', 0) or 0)
    except Exception:
        bid = 0
    if '_v181_send_rec_block' in globals() and bid:
        return await _v181_send_rec_block(context, chat_id, bid)

    ok = total = 0
    errors: List[str] = []
    for rid in [int(x) for x in (b.get('items') or []) if str(x).isdigit()]:
        total += 1
        row = recurring_find(chat_id, rid) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        try:
            await send_recurring_message(context, chat_id, dict(row))
            ok += 1
            await asyncio.sleep(1.0)
        except Exception:
            logger.exception('V209 bloque programado falló recurrente #%s', rid)
            errors.append(f'#{rid} error')
    return ok, total, errors


async def _v209_rec_block_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """Scheduler de bloques con hora exacta HH:MM.

    Sólo dispara el bloque. No cambia la configuración de los recurrentes contenidos.
    """
    try:
        hm = time.strftime('%H:%M')
        day = time.strftime('%Y-%m-%d')
        chat_ids = set()
        try:
            chat_ids.update(int(x) for x in STATE_CACHE.keys())
        except Exception:
            pass
        for chat_id in list(chat_ids):
            for b in _v171_rec_blocks(chat_id) if '_v171_rec_blocks' in globals() else []:
                try:
                    _v173_rec_block_defaults(b)
                except Exception:
                    pass
                if not bool(b.get('enabled')) or b.get('mode') != 'daily':
                    continue
                block_time = _v209_valid_hhmm(str(b.get('time', '21:00'))) or '21:00'
                b['time'] = block_time
                if block_time != hm:
                    continue
                key = f'{day}|{hm}'
                if str(b.get('last_sent_slot', '')) == key or str(b.get('last_sent_day', '')) == day:

                    continue
                ok, total, errors = await _v209_send_rec_block_at_schedule(context, chat_id, b)
                logger.info('V209 bloque recurrente programado chat=%s bloque=%s enviados=%s/%s errores=%s', chat_id, b.get('id'), ok, total, errors[:3])
                b['last_sent_slot'] = key
                b['last_sent_day'] = day
                save_all_states()
    except Exception:
        logger.exception('Error job bloques recurrentes V209')


_old_build_application_v209 = build_application

def build_application() -> Application:
    app = _old_build_application_v209()

    app.add_handler(CallbackQueryHandler(_v209_rblk_time_router, pattern=r'^cfg\|rblk_time'), group=-33000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v209_private_text_router), group=-33000000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v209_rec_block_job, interval=30, first=12, name='v209_rec_block_job')
    except Exception:
        logger.exception('No se pudo iniciar job bloques recurrentes V209')
    logger.info('V209 bloques recurrentes: hora exacta HH:MM y configuración individual respetada')
    return app


