import re as _v212_re


def _v212_strip_tgemoji_tags(text: str) -> str:
    """Elimina tags <tg-emoji> potencialmente inválidos dejando el contenido visible."""
    if not text:
        return text
    value = str(text)

    value = _v212_re.sub(r'<tg-emoji\b[^>]*>(.*?)</tg-emoji>', r'\1', value, flags=_v212_re.I | _v212_re.S)

    value = _v212_re.sub(r'</?tg-emoji\b[^>]*>', '', value, flags=_v212_re.I | _v212_re.S)
    return value


def _v212_clean_dj_html_cfg(chat_id: int) -> bool:
    """Limpia en estado los campos DJ que pueden contener tg-emoji roto."""
    try:
        cfg = admin_cfg(chat_id)
        changed = False
        for key in ('dj_status_on_emoji', 'dj_status_off_emoji', 'dj_panel_custom_text_html'):
            old = str(cfg.get(key) or '')
            new = _v212_strip_tgemoji_tags(old)
            if old != new:
                cfg[key] = new
                changed = True
        if changed:
            save_all_states()
        return changed
    except Exception:
        logger.exception('V212 no pudo limpiar configuración DJ HTML del chat %s', chat_id)
        return False


_old_v212_panel_text = panel_text

def panel_text(state: ChatState) -> str:
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is not None:
            _v212_clean_dj_html_cfg(int(chat_id))
        return _v212_strip_tgemoji_tags(_old_v212_panel_text(state))
    except Exception:
        logger.exception('V212 error limpiando panel_text')
        try:
            return _v212_strip_tgemoji_tags(_old_v212_panel_text(state))
        except Exception:
            return '🔊 <b>DIRECTO</b> 🛑 OFF | 🎧 DJ: <b>Sin asignar</b>'


_old_v212_control_header = control_header

def control_header(state: ChatState) -> str:
    return _v212_strip_tgemoji_tags(_old_v212_control_header(state))


_old_v212_ensure_panel = ensure_panel

async def ensure_panel(bot, chat_id: int) -> None:
    _v212_clean_dj_html_cfg(int(chat_id))
    try:
        await _old_v212_ensure_panel(bot, chat_id)
    except BadRequest as e:

        if 'tg-emoji' not in str(e).lower() and "can't parse entities" not in str(e).lower():
            raise
        logger.warning('V212 recuperando panel DJ por HTML tg-emoji inválido en chat %s: %s', chat_id, e)
        state = get_state(chat_id)
        text = _v212_strip_tgemoji_tags(panel_text(state))
        markup = panel_markup()
        try:
            if state.panel_message_id:
                try:
                    await bot.edit_message_text(chat_id=chat_id, message_id=state.panel_message_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
                    return
                except Exception:
                    state.panel_message_id = None
                    save_all_states()
            msg = await bot.send_message(chat_id=chat_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
            state.panel_message_id = msg.message_id
            save_all_states()
            await register_bot_message(chat_id, msg.message_id)
            try:
                await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
            except Exception:
                pass
        except Exception:
            logger.exception('V212 no pudo recuperar panel DJ tras limpiar tg-emoji')
            raise


_old_v212_ensure_control_panel = ensure_control_panel

async def ensure_control_panel(bot, chat_id: int) -> None:
    _v212_clean_dj_html_cfg(int(chat_id))
    try:
        await _old_v212_ensure_control_panel(bot, chat_id)
    except BadRequest as e:
        if 'tg-emoji' not in str(e).lower() and "can't parse entities" not in str(e).lower():
            raise
        logger.warning('V212 recuperando cuadro DJ por HTML tg-emoji inválido en chat %s: %s', chat_id, e)
        state = get_state(chat_id)
        text, markup = current_control_view(state)
        text = _v212_strip_tgemoji_tags(text)
        try:
            if state.control_message_id:
                try:
                    await bot.edit_message_text(chat_id=chat_id, message_id=state.control_message_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
                    return
                except Exception:
                    state.control_message_id = None
                    save_all_states()
            msg = await bot.send_message(chat_id=chat_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
            state.control_message_id = msg.message_id
            save_all_states()
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            logger.exception('V212 no pudo recuperar cuadro DJ tras limpiar tg-emoji')
            raise


_old_build_application_v212 = build_application

def build_application() -> Application:
    app = _old_build_application_v212()
    logger.info('V212 fix tg-emoji DJ-PRO cargado')
    return app


def main() -> None:
    try:
        _v63_ensure_private_blocks()
    except Exception:
        pass
    try:
        _v72_ensure_dj_block()
    except Exception:
        pass
    try:
        _v110_ensure_manual_block()
    except Exception:
        pass
    try:
        _v129_ensure_tarot_block()
    except Exception:
        pass
    try:
        load_all_states()
        for _cid in list(STATE_CACHE.keys()):
            _v212_clean_dj_html_cfg(int(_cid))
    except Exception:
        logger.exception('V212 main: error cargando/limpiando estados')
    app = build_application()
    app.run_polling(drop_pending_updates=False)


