import re as _v213_re


def _v213_strip_tgemoji_fragments(value: str) -> str:
    if not value:
        return value
    text = str(value)

    text = _v213_re.sub(r'<\s*tg-emoji\b[^>]*>(.*?)<\s*/\s*tg-emoji\s*>', r'\1', text, flags=_v213_re.I | _v213_re.S)

    text = _v213_re.sub(r'<\s*/?\s*tg-emoji\b[^>]*>', '', text, flags=_v213_re.I | _v213_re.S)

    text = _v213_re.sub(r'<\s*/?\s*tg-emoji\b[^\n\r<>]*(?=$|\n|\r)', '', text, flags=_v213_re.I | _v213_re.S)
    return text


def _v213_plain_from_html(value: str) -> str:
    text = _v213_strip_tgemoji_fragments(str(value or ''))

    text = _v213_re.sub(r'<[^>]*>', '', text, flags=_v213_re.S)
    text = text.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&')
    return text.strip() or 'DJ-PLAN'


def _v213_safe_html(value: str) -> str:
    text = _v213_strip_tgemoji_fragments(str(value or ''))

    text = _v213_re.sub(r'<[^>\n\r]*(?=$|\n|\r)', '', text, flags=_v213_re.S)
    return text


def _v213_clean_cfg_all(chat_id: int) -> None:
    try:
        cfg = admin_cfg(chat_id)
        changed = False

        for key in list(cfg.keys()):
            lk = str(key).lower()
            if any(x in lk for x in ('dj_', 'panel', 'emoji', 'title', 'header')):
                val = cfg.get(key)
                if isinstance(val, str):
                    new = _v213_safe_html(val)
                    if new != val:
                        cfg[key] = new
                        changed = True
        if changed:
            save_all_states()
    except Exception:
        logger.exception('V213 no pudo limpiar cfg HTML del chat %s', chat_id)


