async def _v213_send_or_edit_safe(bot, chat_id: int, message_id: Optional[int], text: str, markup=None, *, pin: bool=False) -> int:
    """Intenta HTML; si falla por entidades, usa texto plano sin parse_mode."""
    safe_html = _v213_safe_html(text)
    try:
        if message_id:
            await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=safe_html, reply_markup=markup, parse_mode=ParseMode.HTML)
            return int(message_id)
        msg = await bot.send_message(chat_id=chat_id, text=safe_html, reply_markup=markup, parse_mode=ParseMode.HTML)
        mid = int(msg.message_id)
        if pin:
            try:
                await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
            except Exception:
                pass
        return mid
    except BadRequest as e:
        if "can't parse entities" not in str(e).lower() and 'parse entities' not in str(e).lower():
            raise
        logger.warning('V213 HTML rechazado en DJ-PRO chat %s. Reintento texto plano: %s', chat_id, e)
        plain = _v213_plain_from_html(text)
        if message_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=plain, reply_markup=markup, parse_mode=None)
                return int(message_id)
            except Exception:
                pass
        msg = await bot.send_message(chat_id=chat_id, text=plain, reply_markup=markup, parse_mode=None)
        mid = int(msg.message_id)
        if pin:
            try:
                await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
            except Exception:
                pass
        return mid


