import re as _v214_re


_V214_TG_PLACEHOLDERS: Dict[str, str] = {}

def _v214_keep_valid_tgemoji(html: str) -> str:
    """Mantiene tags tg-emoji válidos y limpia fragmentos rotos.

    V213 eliminaba todo tg-emoji para evitar errores. Aquí conservamos los premium
    si llegan bien formados: <tg-emoji emoji-id="123">🙂</tg-emoji>.
    """
    text = str(html or '')
    _V214_TG_PLACEHOLDERS.clear()

    def _save(m):
        key = f'@@TGEMOJI_{len(_V214_TG_PLACEHOLDERS)}@@'
        _V214_TG_PLACEHOLDERS[key] = m.group(0)
        return key


    text = _v214_re.sub(
        r'<\s*tg-emoji\s+emoji-id=["\']?\d+["\']?\s*>.*?<\s*/\s*tg-emoji\s*>',
        _save,
        text,
        flags=_v214_re.I | _v214_re.S,
    )

    text = _v214_re.sub(r'<\s*/?\s*tg-emoji\b[^>]*>', '', text, flags=_v214_re.I | _v214_re.S)
    text = _v214_re.sub(r'<\s*/?\s*tg-emoji\b[^\n\r<>]*(?=$|\n|\r)', '', text, flags=_v214_re.I | _v214_re.S)

    text = _v214_re.sub(r'<[^>\n\r]*(?=$|\n|\r)', '', text, flags=_v214_re.S)
    for key, val in _V214_TG_PLACEHOLDERS.items():
        text = text.replace(key, val)
    return text


def _v213_strip_tgemoji_fragments(value: str) -> str:
    return _v214_keep_valid_tgemoji(value)

def _v213_safe_html(value: str) -> str:
    return _v214_keep_valid_tgemoji(value)

def _v213_plain_from_html(value: str) -> str:
    text = _v214_keep_valid_tgemoji(value)
    text = _v214_re.sub(r'<\s*tg-emoji\s+emoji-id=["\']?\d+["\']?\s*>(.*?)<\s*/\s*tg-emoji\s*>', r'\1', text, flags=_v214_re.I | _v214_re.S)
    text = _v214_re.sub(r'<[^>]*>', '', text, flags=_v214_re.S)
    text = text.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&')
    return text.strip() or 'DJ-PLAN'


async def _v214_send_message_safe(bot, chat_id: int, text: str, *, reply_markup=None, reply_to_message_id: Optional[int]=None, pin: bool=False) -> int:
    html = _v214_keep_valid_tgemoji(text)
    try:
        msg = await bot.send_message(
            chat_id=chat_id,
            text=html,
            parse_mode=ParseMode.HTML,
            reply_markup=reply_markup,
            reply_to_message_id=reply_to_message_id,
            allow_sending_without_reply=True,
        )
    except BadRequest as e:
        if 'parse entities' not in str(e).lower() and "can't parse" not in str(e).lower() and 'unclosed start tag' not in str(e).lower():
            raise
        msg = await bot.send_message(
            chat_id=chat_id,
            text=_v213_plain_from_html(text),
            parse_mode=None,
            reply_markup=reply_markup,
            reply_to_message_id=reply_to_message_id,
            allow_sending_without_reply=True,
        )
    mid = int(msg.message_id)
    try:
        await register_bot_message(chat_id, mid)
    except Exception:
        pass
    if pin:
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
        except Exception:
            pass
    return mid


async def _v214_show_fresh_mesa(bot, chat_id: int, *, force_fresh: bool=True) -> None:
    """Muestra la mesa de DJ recreándola como mensaje nuevo, referida al panel fijado.

    Telegram no permite insertar mensajes antiguos justo debajo del fijado real.
    Lo más parecido y estable es: asegurar/fijar panel, borrar mesa antigua si existe,
    y enviar una mesa nueva como respuesta al panel fijado. Así al pulsar Mesa aparece
    inmediatamente y no queda perdida entre mensajes viejos.
    """
    state = get_state(chat_id)
    state.dj_mode = True
    set_control_view(state, 'home', 0)
    admin_cfg(chat_id)['dj_mesa_visible'] = True
    admin_cfg(chat_id)['dj_mesa_minimized'] = False
    save_all_states()

    await ensure_panel(bot, chat_id)
    state = get_state(chat_id)
    old_id = state.control_message_id
    if force_fresh and old_id:
        state.control_message_id = None
        save_all_states()
        try:
            await safe_delete(bot, chat_id, old_id)
        except Exception:
            pass

    text, markup = current_control_view(state)
    reply_to = state.panel_message_id or None
    mid = await _v214_send_message_safe(bot, chat_id, text, reply_markup=markup, reply_to_message_id=reply_to, pin=False)
    state.control_message_id = mid
    save_all_states()


async def _v214_minimize_mesa(bot, chat_id: int) -> None:
    state = get_state(chat_id)
    old_id = state.control_message_id
    state.control_message_id = None
    admin_cfg(chat_id)['dj_mesa_visible'] = False
    admin_cfg(chat_id)['dj_mesa_minimized'] = True
    save_all_states()
    if old_id:
        try:
            await safe_delete(bot, chat_id, old_id)
        except Exception:
            pass
    await ensure_panel(bot, chat_id)


