def _v214_audio_opt_enabled() -> bool:
    return os.getenv('DJ_AUDIO_NORMALIZE_OPUS', 'false').strip().lower() in ('1','true','yes','on','si','sí')

async def _v214_run_ffmpeg_opus(src: str, chat_id: int) -> Optional[str]:
    if not _v214_audio_opt_enabled():
        return None
    try:
        srcp = Path(src)
        if not srcp.exists():
            return None

        if srcp.suffix.lower() == '.ogg':
            return None
        out = DOWNLOAD_DIR / f'{chat_id}_voiceopt_{secrets.token_hex(5)}.ogg'
        proc = await asyncio.create_subprocess_exec(
            'ffmpeg', '-y', '-i', str(srcp), '-vn', '-ac', '2', '-ar', '48000', '-c:a', 'libopus', '-b:a', os.getenv('DJ_AUDIO_OPUS_KBPS','96') + 'k', str(out),
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        try:
            await asyncio.wait_for(proc.communicate(), timeout=180)
        except asyncio.TimeoutError:
            try: proc.kill()
            except Exception: pass
            return None
        if proc.returncode == 0 and out.exists():
            return str(out)
    except Exception:
        logger.exception('V214 no pudo normalizar audio')
    return None

_old_v214_voice_play_track = VoiceEngine.play_track
async def _voice_play_track_v214(self, bot, chat_id: int, track: Track) -> None:

    if track.local_path and Path(track.local_path).exists():
        opt = await _v214_run_ffmpeg_opus(track.local_path, chat_id)
        if opt:
            track.local_path = opt
            track.mime_type = 'audio/ogg'
            if track.duration <= 0:
                track.duration = probe_duration_seconds(opt)
    await _old_v214_voice_play_track(self, bot, chat_id, track)

VoiceEngine.play_track = _voice_play_track_v214


def _v214_ensure_hot_block() -> None:
    try:

        existing = {str(k) for k, _ in ADMIN_PRIVATE_BLOCKS}
        if 'hot' not in existing:
            insert_at = len(ADMIN_PRIVATE_BLOCKS)
            try:
                insert_at = next((i for i, (k, _l) in enumerate(ADMIN_PRIVATE_BLOCKS) if k in ('daily_phrase','recurrentes','awards')), len(ADMIN_PRIVATE_BLOCKS))
            except Exception:
                pass
            ADMIN_PRIVATE_BLOCKS.insert(insert_at, ('hot', '🔥 Preguntitas / Retitos'))
        ADMIN_PRIVATE_BLOCK_IDS.add('hot')
    except Exception:
        logger.exception('V214 no pudo asegurar HOT block')


def hot_auto_has_enough_interaction(chat_id: int, now: Optional[int] = None) -> bool:
    now = int(now or time.time())
    cfg = hot_cfg(chat_id)
    window = max(20, int(cfg.get('hot_auto_activity_window_seconds', 240) or 240))
    min_messages = max(1, int(cfg.get('hot_auto_min_messages', 1) or 1))
    min_users = max(1, int(cfg.get('hot_auto_min_users', 1) or 1))
    cutoff = now - window
    recent = [x for x in HOT_CHAT_ACTIVITY_LOG.get(int(chat_id), []) if int(x.get('ts', 0)) >= cutoff]
    unique_users = {int(x.get('user_id', 0)) for x in recent if int(x.get('user_id', 0))}
    return len(recent) >= min_messages and len(unique_users) >= min_users

async def _v214_hot_send_to_group(application: Application, chat_id: int, *, force: bool=False) -> bool:
    try:
        return await _v210_send_auto_hot(application, chat_id, force=force) if '_v210_send_auto_hot' in globals() else False
    except Exception:
        logger.exception('V214 HOT no pudo enviar por v210; intento directo')

    try:
        cfg = hot_cfg(chat_id)
        level = hot_pick_level(chat_id, automatic=True)
        kind = hot_pick_auto_kind(chat_id)
        item = hot_get_item(chat_id, level, kind)
        text = f'🎲 <b>{"Retito" if kind == "challenge" else "Preguntita"} automática · Nivel {level}</b>\n\n{h(item)}'
        msg = await application.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML)
        await register_bot_message(chat_id, msg.message_id)
        cfg['hot_last_auto_ts'] = int(time.time())
        save_all_states()
        return True
    except Exception:
        logger.exception('V214 HOT fallback directo falló')
        return False

async def _v214_hot_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    app = context.application
    for chat_id in list(STATE_CACHE.keys()):
        try:
            cfg = hot_cfg(int(chat_id))
            if not bool(cfg.get('hot_auto_enabled', False)):
                continue
            now = int(time.time())
            interval = max(20, int(cfg.get('hot_auto_interval_seconds', 180) or 180))
            if now - int(cfg.get('hot_last_auto_ts', 0) or 0) < interval:
                continue
            if not hot_auto_has_enough_interaction(int(chat_id), now):
                continue
            await _v214_hot_send_to_group(app, int(chat_id), force=True)
        except Exception:
            logger.exception('V214 HOT tick falló chat %s', chat_id)

async def _v214_hot_activity(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user:
        return
    if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
        return
    try:
        hot_activity_remember(int(update.effective_chat.id), update.effective_user)
    except Exception:
        pass

    try:
        remember_activity(int(update.effective_chat.id), update.effective_user, getattr(update, 'message', None))
    except Exception:
        pass

async def _v214_hot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:

    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        selected = hot_private_group_for(update.effective_user.id) if 'hot_private_group_for' in globals() else None
        if selected is None:
            await update.message.reply_html('Primero vincula grupo con <code>/hotgrupo</code>.')
            return
        chat_id = int(selected)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo admin puede probar auto preguntitas.')
        return
    ok = await _v214_hot_send_to_group(context.application, chat_id, force=True)
    await update.message.reply_text('✅ Preguntita enviada al grupo.' if ok else '❌ No pude enviar preguntita. Mira logs.')


