def build_application() -> Application:
    _v214_ensure_hot_block()
    app = _old_build_application_v214()

    app.add_handler(CallbackQueryHandler(_v214_dj_callback_router, pattern=r'^(menu_panel|panel_home|panel_minimize|panel_scan)$'), group=-41000000000)
    app.add_handler(CommandHandler(['djmesa', 'DJmesa'], _v214_djmesa_command), group=-41000000000)
    app.add_handler(CommandHandler(['djscan', 'rastrear'], _v214_djscan_command), group=-41000000000)

    app.add_handler(CommandHandler(['preguntaauto', 'hotauto'], _v214_hot_command), group=-41000000000)
    app.add_handler(MessageHandler(filters.ALL, _v214_hot_activity), group=-41000000000)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v214_hot_tick, interval=5, first=8, name='v214_hot_tick')
    except Exception:
        logger.exception('V214 no pudo iniciar hot tick')

    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, _v214_validation_new_members_first), group=-41000000001)
    app.add_handler(MessageHandler(filters.ChatType.GROUPS & filters.TEXT & ~filters.COMMAND, _v214_validation_text_first), group=-41000000001)
    logger.info('V214 DJ fluido + premium seguro + HOT/validación reforzado cargado')
    return app


