try:
    from telegram.ext import ApplicationHandlerStop as _V215Stop
except Exception:
    _V215Stop = Exception

DJ_ANNOUNCE_LIKE_TOKENS_V215: Dict[str, Dict[str, Any]] = {}
PODCAST_PENDING_V215: Dict[str, Dict[str, Any]] = {}
PODCAST_URL_RE_V215 = __import__('re').compile(r'https?://\S+', __import__('re').I)
PODCAST_MAX_DIRECT_MB_V215 = max(10, env_int('PODCAST_MAX_DIRECT_MB', '45'))
PODCAST_OPUS_KBPS_V215 = max(64, env_int('PODCAST_OPUS_KBPS', '96'))
PODCAST_SPLIT_MINUTES_V215 = max(5, env_int('PODCAST_SPLIT_MINUTES', '20'))
PODCAST_YTDLP_TIMEOUT_V215 = max(60, env_int('PODCAST_YTDLP_TIMEOUT', '1200'))


def _v215_state_chat_id(state: ChatState) -> Optional[int]:
    try:
        for cid, st in STATE_CACHE.items():
            if st is state:
                return int(cid)
    except Exception:
        pass
    return None


def _v215_dj_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cfg.setdefault('dj_opus_hd_enabled', env_bool('DJ_AUDIO_NORMALIZE_OPUS', 'false'))
    cfg.setdefault('dj_opus_kbps', max(96, env_int('DJ_AUDIO_OPUS_KBPS', '128')))
    cfg.setdefault('dj_announce_now_enabled', True)
    return cfg


_old_control_panel_markup_v215 = control_panel_markup

def control_panel_markup(state: ChatState) -> InlineKeyboardMarkup:
    old = _old_control_panel_markup_v215(state)
    rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]
    chat_id = _v215_state_chat_id(state)
    enabled = False
    kbps = 128
    announce = False
    if chat_id is not None:
        cfg = _v215_dj_cfg(chat_id)
        enabled = bool(cfg.get('dj_opus_hd_enabled', False))
        kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
        announce = bool(cfg.get('dj_announce_now_enabled', True))
    label_opus = f'🎚 OPUS HD {"ON" if enabled else "OFF"}'
    label_quality = f'💎 {kbps}k'
    label_announce = f'📣 Aviso {"ON" if announce else "OFF"}'

    flat = ' '.join(getattr(b, 'text', '') for r in rows for b in r)
    insert_at = max(0, len(rows) - 1)
    if 'OPUS HD' not in flat:
        rows.insert(insert_at, [
            InlineKeyboardButton(label_opus, callback_data='panel_opus_toggle'),
            InlineKeyboardButton(label_quality, callback_data='panel_opus_quality'),
            InlineKeyboardButton(label_announce, callback_data='panel_announce_now'),
        ])
    return InlineKeyboardMarkup(rows)


async def _v215_run_ffmpeg_opus(src_path: str, chat_id: int) -> Optional[str]:
    """Convierte a OPUS HD con normalización suave. Sólo si está activado en mesa."""
    try:
        cfg = _v215_dj_cfg(chat_id)
        if not bool(cfg.get('dj_opus_hd_enabled', False)):
            return None
        src = Path(src_path)
        if not src.exists():
            return None

        if '_v215opus_' in src.name and src.suffix.lower() == '.ogg':
            return str(src)
        kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
        kbps = max(64, min(192, kbps))
        out = DOWNLOAD_DIR / f'{chat_id}_v215opus_{secrets.token_hex(5)}.ogg'
        cmd = [
            'ffmpeg', '-y', '-i', str(src), '-vn',
            '-af', 'loudnorm=I=-16:LRA=11:TP=-1.5',
            '-c:a', 'libopus', '-b:a', f'{kbps}k', '-vbr', 'on',
            '-application', 'audio', str(out)
        ]
        proc = await asyncio.create_subprocess_exec(*cmd, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
        try:
            _out, _err = await asyncio.wait_for(proc.communicate(), timeout=240)
        except asyncio.TimeoutError:
            try: proc.kill()
            except Exception: pass
            return None
        if proc.returncode == 0 and out.exists():
            return str(out)
    except Exception:
        logger.exception('V215 no pudo convertir a OPUS HD')
    return None


_old_voice_play_track_v215 = VoiceEngine.play_track
async def _voice_play_track_v215(self, bot, chat_id: int, track: Track) -> None:

    try:
        if track.local_path and Path(track.local_path).exists() and bool(_v215_dj_cfg(chat_id).get('dj_opus_hd_enabled', False)):
            opt = await _v215_run_ffmpeg_opus(track.local_path, chat_id)
            if opt:
                track.local_path = opt
                track.mime_type = 'audio/ogg'
                track.duration = probe_duration_seconds(opt) or int(track.duration or 0)
    except Exception:
        logger.exception('V215 OPUS HD pre-play falló; reproduzco original')
    await _old_voice_play_track_v215(self, bot, chat_id, track)

VoiceEngine.play_track = _voice_play_track_v215


