async def _send_dj_now_announce_v24(bot, chat_id: int, track: Track) -> None:
    if not bool(_v215_dj_cfg(chat_id).get('dj_announce_now_enabled', True)):
        return
    try:
        key = _v215_track_like_key(track)
        token = secrets.token_hex(4)
        DJ_ANNOUNCE_LIKE_TOKENS_V215[token] = {'chat_id': int(chat_id), 'key': key, 'title': track.title, 'created_at': int(time.time())}
        cfg = admin_cfg(chat_id)
        likes = cfg.setdefault('dj_track_likes', {})
        likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
        save_all_states()
        text = '🎧 <b>EN DIRECTO AHORA</b>\n\n' + f'🎶 <b>{h(track.title)}</b>'
        if track.performer:
            text += f'\n👤 <i>{h(track.performer)}</i>'
        text += f'\n\n❤️ <b>Me gusta:</b> {_v215_like_count(chat_id, key)}'
        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=_v215_announce_markup(chat_id, token, key))
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        logger.exception('V215 no pudo mandar aviso de canción nueva')


async def _v215_dj_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    if data in ('panel_opus_toggle', 'panel_opus_quality', 'panel_announce_now'):
        if not await is_controller(context, chat_id, uid):
            await q.answer('Solo DJ/admin.', show_alert=True)
            raise _V215Stop
        cfg = _v215_dj_cfg(chat_id)
        if data == 'panel_opus_toggle':
            cfg['dj_opus_hd_enabled'] = not bool(cfg.get('dj_opus_hd_enabled', False))
            save_all_states()
            await q.answer('OPUS HD ' + ('ON' if cfg['dj_opus_hd_enabled'] else 'OFF'), show_alert=True)
        elif data == 'panel_opus_quality':
            options = [96, 128, 160, 192]
            cur = int(cfg.get('dj_opus_kbps', 128) or 128)
            nxt = options[(options.index(cur) + 1) % len(options)] if cur in options else 128
            cfg['dj_opus_kbps'] = nxt
            save_all_states()
            await q.answer(f'Calidad OPUS: {nxt}k', show_alert=True)
        else:
            cfg['dj_announce_now_enabled'] = not bool(cfg.get('dj_announce_now_enabled', True))
            save_all_states()
            await q.answer('Aviso canción ' + ('ON' if cfg['dj_announce_now_enabled'] else 'OFF'), show_alert=True)
            if cfg['dj_announce_now_enabled'] and get_state(chat_id).now_playing:
                await _send_dj_now_announce_v24(context.bot, chat_id, Track(**get_state(chat_id).now_playing))
        try:
            await ensure_control_panel(context.bot, chat_id)
        except Exception:
            pass
        raise _V215Stop
    if data.startswith('djl2|'):
        token = data.split('|', 1)[1]
        row = DJ_ANNOUNCE_LIKE_TOKENS_V215.get(token)
        if not row:
            await q.answer('Este aviso ya caducó.', show_alert=True)
            raise _V215Stop
        key = str(row.get('key') or '')
        title = str(row.get('title') or 'Canción')
        likes = admin_cfg(chat_id).setdefault('dj_track_likes', {})
        lrow = likes.setdefault(key, {'title': title, 'users': []})
        users = lrow.setdefault('users', [])
        suid = str(uid)
        if suid in users:
            users.remove(suid)
            msg = 'Quitado ❤️'
        else:
            users.append(suid)
            msg = 'Me gusta ❤️'
        save_all_states()
        await q.answer(msg)
        try:

            await q.edit_message_reply_markup(reply_markup=_v215_announce_markup(chat_id, token, key))
        except Exception:
            pass
        raise _V215Stop


def _v215_first_url(text: str) -> str:
    m = PODCAST_URL_RE_V215.search(text or '')
    return m.group(0).strip().rstrip(').,;]\n\r') if m else ''


def _v215_file_mb(path: str) -> float:
    try: return Path(path).stat().st_size / (1024 * 1024)
    except Exception: return 0.0


async def _v215_run_cmd(args: List[str], *, timeout: int = PODCAST_YTDLP_TIMEOUT_V215) -> subprocess.CompletedProcess:
    proc = await asyncio.create_subprocess_exec(*args, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
    try:
        out, err = await asyncio.wait_for(proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError:
        try: proc.kill()
        except Exception: pass
        raise RuntimeError('Tiempo agotado descargando/convirtiendo el podcast.')
    cp = subprocess.CompletedProcess(args, proc.returncode, out.decode('utf-8', 'replace'), err.decode('utf-8', 'replace'))
    if cp.returncode != 0:
        raise RuntimeError((cp.stderr or cp.stdout or 'Comando fallido')[-1200:])
    return cp


async def _v215_check_tools() -> None:
    import shutil
    missing = [x for x in ('yt-dlp','ffmpeg','ffprobe') if not shutil.which(x)]
    if missing:
        raise RuntimeError('Faltan herramientas: ' + ', '.join(missing) + '. Añade yt-dlp a requirements y ffmpeg al Dockerfile.')


async def _v215_download_podcast(url: str, chat_id: int, user_name: str='') -> Track:
    await _v215_check_tools()
    token = secrets.token_hex(6)
    base = DOWNLOAD_DIR / f'{chat_id}_pod215_{token}'
    title = 'Podcast'
    duration = 0
    try:
        meta = await _v215_run_cmd(['yt-dlp','--no-playlist','--dump-single-json','--no-warnings','--skip-download',url], timeout=90)
        data = json.loads(meta.stdout or '{}')
        title = shorten_title(' '.join(str(data.get('title') or data.get('fulltitle') or 'Podcast').split()), 120)
        duration = int(float(data.get('duration') or 0))
    except Exception:
        logger.exception('V215 metadatos podcast fallaron; sigo')
    await _v215_run_cmd(['yt-dlp','--no-playlist','-f','ba/bestaudio','--no-warnings','-o',str(base)+'.%(ext)s',url])
    candidates = sorted(DOWNLOAD_DIR.glob(f'{chat_id}_pod215_{token}.*'), key=lambda p: p.stat().st_mtime, reverse=True)
    source = next((p for p in candidates if p.is_file() and not p.name.endswith('.part') and p.suffix.lower() not in ('.json',)), None)
    if not source:
        raise RuntimeError('yt-dlp no generó audio utilizable.')
    out = DOWNLOAD_DIR / f'{chat_id}_pod215_{token}.ogg'
    kbps = PODCAST_OPUS_KBPS_V215
    await _v215_run_cmd(['ffmpeg','-y','-i',str(source),'-vn','-af','loudnorm=I=-16:LRA=11:TP=-1.5','-c:a','libopus','-b:a',f'{kbps}k','-vbr','on','-application','audio',str(out)], timeout=PODCAST_YTDLP_TIMEOUT_V215)
    try:
        if source.resolve() != out.resolve(): source.unlink(missing_ok=True)
    except Exception:
        pass
    if duration <= 0:
        duration = probe_duration_seconds(str(out))
    return Track(title='🎙️ '+title, performer='Podcast' if not user_name else f'Podcast · {user_name}', duration=duration, local_path=str(out), file_unique_id=f'pod215:{chat_id}:{token}', mime_type='audio/ogg', added_by_name=user_name)


def _v215_podcast_markup(token: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('▶️ Directo ahora', callback_data=f'pod215|play|{token}')],
        [InlineKeyboardButton('⏭️ Primera cola', callback_data=f'pod215|first|{token}'), InlineKeyboardButton('➕ Cola final', callback_data=f'pod215|queue|{token}')],
        [InlineKeyboardButton('✂️ Dividir en partes', callback_data=f'pod215|split|{token}')],
        [InlineKeyboardButton('📚 Biblioteca', callback_data=f'pod215|lib|{token}'), InlineKeyboardButton('❌ Cancelar', callback_data=f'pod215|cancel|{token}')],
    ])


async def _v215_present_podcast(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, track: Track, status_msg=None):
    token = secrets.token_hex(5)
    PODCAST_PENDING_V215[token] = {'chat_id': chat_id, 'track': asdict(track), 'created_at': int(time.time())}
    mb = _v215_file_mb(track.local_path)
    warn = '' if mb <= PODCAST_MAX_DIRECT_MB_V215 else f'\n⚠️ Pesa <b>{mb:.1f} MB</b>. Mejor dividirlo en partes.'
    text = ('🎙️ <b>MODO PODCAST</b>\n\n'
            f'Título: <b>{h(track.title)}</b>\n'
            f'Duración: <b>{fmt_duration(track.duration)}</b>\n'
            f'Archivo: <b>{mb:.1f} MB</b> · OPUS {PODCAST_OPUS_KBPS_V215}k{warn}\n\n¿Qué hacemos?')
    if status_msg:
        try:
            await status_msg.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=_v215_podcast_markup(token))
            return
        except Exception:
            pass
    await update.message.reply_html(text, reply_markup=_v215_podcast_markup(token))


async def _v215_split_track(track: Track, chat_id: int) -> List[Track]:
    if not track.local_path or not Path(track.local_path).exists():
        raise RuntimeError('El archivo local ya no existe.')
    token = secrets.token_hex(5)
    pattern = DOWNLOAD_DIR / f'{chat_id}_pod215part_{token}_%03d.ogg'
    await _v215_run_cmd(['ffmpeg','-y','-i',track.local_path,'-vn','-c:a','libopus','-b:a',f'{PODCAST_OPUS_KBPS_V215}k','-vbr','on','-f','segment','-segment_time',str(PODCAST_SPLIT_MINUTES_V215*60),'-reset_timestamps','1',str(pattern)], timeout=PODCAST_YTDLP_TIMEOUT_V215)
    files = sorted(DOWNLOAD_DIR.glob(f'{chat_id}_pod215part_{token}_*.ogg'))
    total = len(files)
    out=[]
    for i,f in enumerate(files,1):
        out.append(Track(title=f'{track.title} · Parte {i}/{total}', performer=track.performer, duration=probe_duration_seconds(str(f)), local_path=str(f), file_unique_id=f'pod215part:{chat_id}:{token}:{i}', mime_type='audio/ogg', added_by_id=track.added_by_id, added_by_name=track.added_by_name))
    try: Path(track.local_path).unlink(missing_ok=True)
    except Exception: pass
    return out


async def _v215_podcast_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat:
        return
    text = update.message.text or update.message.caption or ''
    url = _v215_first_url(text or ' '.join(context.args or []))
    if not url:
        await update.message.reply_html('<b>🎙️ MODO PODCAST</b>\n\nUso: <code>/podcast ENLACE</code>\nTambién puedes pegar un enlace de YouTube, iVoox, SoundCloud o podcast por privado.')
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        selected = dj_selected_private_group(update.effective_user.id) if 'dj_selected_private_group' in globals() else None
        if selected is None:
            await update.message.reply_html('Primero vincula/elige un grupo con <code>/djgrupos</code> o <code>/djgrupo</code>.')
            return
        chat_id = int(selected)
    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await update.message.reply_text('Solo admin o DJ puede añadir podcasts.')
        return
    status = await update.message.reply_html('🎙️ Preparando podcast…\nDescargo audio, comprimo a OPUS y lo dejo listo.')
    try:
        track = await _v215_download_podcast(url, chat_id, display_name(update.effective_user))
        track.added_by_id = update.effective_user.id
        track.added_by_name = display_name(update.effective_user)
        await _v215_present_podcast(update, context, chat_id, track, status_msg=status)
    except Exception as e:
        logger.exception('V215 error podcast')
        await status.edit_text('❌ No pude preparar ese podcast.\n\n<code>'+h(str(e)[-1200:])+'</code>', parse_mode=ParseMode.HTML)


async def _v215_private_podcast_url(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or update.effective_chat.type != 'private' or not update.message:
        return
    url = _v215_first_url(update.message.text or update.message.caption or '')
    if not url:
        return
    low = url.lower()
    if not any(x in low for x in ('youtube.com','youtu.be','podcast','ivoox','spotify.com','soundcloud.com')):
        return
    await _v215_podcast_command(update, context)
    raise _V215Stop


async def _v215_podcast_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    parts = (q.data or '').split('|')
    if len(parts) < 3:
        return
    action, token = parts[1], parts[2]
    row = PODCAST_PENDING_V215.get(token)
    if not row:
        await q.answer('Podcast caducado. Envíalo otra vez.', show_alert=True); raise _V215Stop
    chat_id = int(row['chat_id'])
    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await q.answer('Solo admin/DJ.', show_alert=True); raise _V215Stop
    track = Track(**row['track'])
    try:
        if action == 'cancel':
            try:
                if track.local_path: Path(track.local_path).unlink(missing_ok=True)
            except Exception: pass
            PODCAST_PENDING_V215.pop(token, None)
            await q.edit_message_text('❌ Podcast cancelado.'); raise _V215Stop
        if action == 'play':
            await q.answer('Reproduciendo…')
            await play_selected_track(context, chat_id, track)
            txt = '▶️ Podcast enviado al directo.'
        elif action == 'first':
            await queue_track_first(chat_id, track); txt = '⏭️ Podcast añadido como primero en cola.'
        elif action == 'queue':
            await queue_track(chat_id, track); txt = '➕ Podcast añadido al final de la cola.'
        elif action == 'lib':
            added = await add_to_library(chat_id, track); txt = '📚 Guardado en biblioteca.' if added else 'ℹ️ Ya estaba en biblioteca.'
        elif action == 'split':
            await q.edit_message_text('✂️ Dividiendo podcast en partes…')
            parts_tracks = await _v215_split_track(track, chat_id)
            for tr in parts_tracks:
                await queue_track(chat_id, tr)
                await asyncio.sleep(0.4)
            txt = f'✅ Podcast dividido en <b>{len(parts_tracks)}</b> partes y añadido a cola.'
        else:
            await q.answer('Acción no válida', show_alert=True); raise _V215Stop
        PODCAST_PENDING_V215.pop(token, None)
        save_all_states()
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
        await q.edit_message_text(txt, parse_mode=ParseMode.HTML)
    except _V215Stop:
        raise
    except Exception as e:
        logger.exception('V215 callback podcast falló')
        await q.answer('Error podcast', show_alert=True)
        try: await q.edit_message_text('❌ Error: <code>'+h(str(e)[-1000:])+'</code>', parse_mode=ParseMode.HTML)
        except Exception: pass
    raise _V215Stop


