import re as _v216_re

_V216_VALID_TGEMOJI_RE = _v216_re.compile(
    r'<\s*tg-emoji\s+emoji-id=["\']?\d+["\']?\s*>.*?<\s*/\s*tg-emoji\s*>',
    _v216_re.I | _v216_re.S,
)


def _v216_preserve_valid_tgemoji(value: Any) -> str:
    """Conserva emojis premium Telegram válidos y limpia HTML roto.

    Aceptado por Telegram:
    <tg-emoji emoji-id="123456789">🔥</tg-emoji>

    Se eliminan tags tg-emoji cortados, atributos vacíos o mal formados, dejando el texto visible cuando sea posible.
    """
    text = str(value or '')
    if not text:
        return ''
    saved: Dict[str, str] = {}

    def save(m):
        key = f'@@V216TG{len(saved)}@@'
        saved[key] = m.group(0)
        return key

    text = _V216_VALID_TGEMOJI_RE.sub(save, text)

    text = _v216_re.sub(r'<\s*tg-emoji\b[^>]*>(.*?)<\s*/\s*tg-emoji\s*>', r'\1', text, flags=_v216_re.I | _v216_re.S)

    text = _v216_re.sub(r'<\s*/?\s*tg-emoji\b[^>]*>', '', text, flags=_v216_re.I | _v216_re.S)
    text = _v216_re.sub(r'<\s*/?\s*tg-emoji\b[^\n\r<>]*(?=$|\n|\r)', '', text, flags=_v216_re.I | _v216_re.S)

    text = _v216_re.sub(r'<[^>\n\r]*(?=$|\n|\r)', '', text, flags=_v216_re.S)
    for k, v in saved.items():
        text = text.replace(k, v)
    return text


def _v216_plain_from_html(value: Any) -> str:
    text = _v216_preserve_valid_tgemoji(value)

    text = _v216_re.sub(r'<\s*tg-emoji\s+emoji-id=["\']?\d+["\']?\s*>(.*?)<\s*/\s*tg-emoji\s*>', r'\1', text, flags=_v216_re.I | _v216_re.S)

    text = _v216_re.sub(r'<[^>]*>', '', text, flags=_v216_re.S)
    text = text.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&')
    return text.strip() or 'DJ-PLAN'


def _v212_strip_tgemoji_tags(text: str) -> str:
    return _v216_preserve_valid_tgemoji(text)

def _v212_clean_dj_html_cfg(chat_id: int) -> bool:
    try:
        cfg = admin_cfg(chat_id)
        changed = False
        for key in ('dj_status_on_emoji', 'dj_status_off_emoji', 'dj_panel_custom_text_html'):
            old = str(cfg.get(key) or '')
            new = _v216_preserve_valid_tgemoji(old)
            if old != new:
                cfg[key] = new
                changed = True
        if changed:
            save_all_states()
        return changed
    except Exception:
        logger.exception('V216 no pudo limpiar cfg DJ premium chat %s', chat_id)
        return False

def _v213_strip_tgemoji_fragments(value: str) -> str:
    return _v216_preserve_valid_tgemoji(value)

def _v213_safe_html(value: str) -> str:
    return _v216_preserve_valid_tgemoji(value)

def _v213_plain_from_html(value: str) -> str:
    return _v216_plain_from_html(value)

def _v214_keep_valid_tgemoji(html: str) -> str:
    return _v216_preserve_valid_tgemoji(html)

def _v213_clean_cfg_all(chat_id: int) -> None:
    """Limpia sólo HTML roto, conserva premium emoji válido."""
    try:
        cfg = admin_cfg(chat_id)
        changed = False
        for key in list(cfg.keys()):
            lk = str(key).lower()
            if any(x in lk for x in ('dj_', 'panel', 'emoji', 'status')):
                val = cfg.get(key)
                if isinstance(val, str):
                    new = _v216_preserve_valid_tgemoji(val)
                    if new != val:
                        cfg[key] = new
                        changed = True
        if changed:
            save_all_states()
    except Exception:
        logger.exception('V216 no pudo limpiar cfg HTML premium chat %s', chat_id)


def _v216_status_html(chat_id: int, state: ChatState) -> str:
    cfg = admin_cfg(chat_id)
    on = _v216_preserve_valid_tgemoji(cfg.get('dj_status_on_emoji') or '🛜 ON')
    off = _v216_preserve_valid_tgemoji(cfg.get('dj_status_off_emoji') or '🛑 OFF')
    return on if bool(state.live_enabled) else off


def _v216_song_html(chat_id: int, value: str) -> str:
    safe = h(value)
    if bool(cfg_value(chat_id, 'dj_current_bold_italic', False)):
        return f'<b><i>{safe}</i></b>'
    return safe


def panel_text(state: ChatState) -> str:
    """Panel fijado DJ conservando premium emoji en {estado} y en el texto custom."""
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is None:
            raise RuntimeError('chat no localizado para panel DJ')
        chat_id = int(chat_id)
        _v213_clean_cfg_all(chat_id)
        cfg = admin_cfg(chat_id)
        custom = _v216_preserve_valid_tgemoji(str(cfg.get('dj_panel_custom_text_html') or '').strip())
        current = 'Nada sonando'
        nxt = 'Nada en cola'
        if state.now_playing:
            current = shorten_title(Track(**state.now_playing).title, 42)
        if state.queue:
            nxt = shorten_title(Track(**state.queue[0]).title, 42)
        status = _v216_status_html(chat_id, state)
        current_html = _v216_song_html(chat_id, current)
        next_html = _v216_song_html(chat_id, nxt) if (not state.now_playing and state.queue) else h(nxt)
        if custom:
            repl = {
                '{estado}': status,
                '{cancion}': current_html,
                '{actual}': current_html,
                '{siguiente}': next_html,
                '{dj}': h(state.assigned_dj_name or 'Sin asignar'),
                '{cola}': str(len(state.queue)),
                '{biblioteca}': str(len(state.library)),
            }
            for k, v in repl.items():
                custom = custom.replace(k, v)
            return _v216_preserve_valid_tgemoji(custom)
        dj = h(state.assigned_dj_name or 'Sin asignar')
        if state.now_playing:
            song_label = '💽'; song_value = current_html
        elif state.queue:
            song_label = '⏭️'; song_value = next_html
        else:
            song_label = '❌'; song_value = h('Nada sonando')
        return _v216_preserve_valid_tgemoji(f'🔊 <b>DIRECTO</b> {status} <b>{song_label}</b> {song_value} | 🎧 DJ: <b>{dj}</b>')
    except Exception:
        logger.exception('V216 panel_text falló')
        return '🔊 <b>DIRECTO</b> 🛑 OFF | 🎧 DJ: <b>Sin asignar</b>'


async def _v216_send_or_edit_panel(bot, chat_id: int, message_id: Optional[int], text: str, markup=None, *, pin: bool=False, reply_to_message_id: Optional[int]=None) -> int:
    html = _v216_preserve_valid_tgemoji(text)
    try:
        if message_id:
            await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=html, reply_markup=markup, parse_mode=ParseMode.HTML)
            return int(message_id)
        msg = await bot.send_message(chat_id=chat_id, text=html, reply_markup=markup, parse_mode=ParseMode.HTML, reply_to_message_id=reply_to_message_id, allow_sending_without_reply=True)
        mid = int(msg.message_id)
        await register_bot_message(chat_id, mid)
        if pin:
            try: await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
            except Exception: pass
        return mid
    except BadRequest as e:

        if 'parse entities' not in str(e).lower() and "can't parse" not in str(e).lower() and 'unclosed start tag' not in str(e).lower():
            raise
        logger.warning('V216 panel HTML rechazado chat %s; fallback texto plano: %s', chat_id, e)
        plain = _v216_plain_from_html(text)
        if message_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=plain, reply_markup=markup, parse_mode=None)
                return int(message_id)
            except Exception:
                pass
        msg = await bot.send_message(chat_id=chat_id, text=plain, reply_markup=markup, parse_mode=None, reply_to_message_id=reply_to_message_id, allow_sending_without_reply=True)
        mid = int(msg.message_id)
        await register_bot_message(chat_id, mid)
        if pin:
            try: await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
            except Exception: pass
        return mid


async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        sync_panel_override_expiry(state)
        text = panel_text(state)
        markup = panel_markup()
        old_panel_id = state.panel_message_id
        if old_panel_id:
            try:
                state.panel_message_id = await _v216_send_or_edit_panel(bot, chat_id, old_panel_id, text, markup, pin=False)
                save_all_states()
                return
            except BadRequest as e:
                if 'message is not modified' in str(e).lower():
                    return
                state.panel_message_id = None
                save_all_states()
            except Exception:
                logger.exception('V216 no pudo editar panel; recreo')
                state.panel_message_id = None
                save_all_states()
        if old_panel_id:
            try: await bot.unpin_chat_message(chat_id=chat_id, message_id=old_panel_id)
            except Exception: pass
            try: await safe_delete(bot, chat_id, old_panel_id)
            except Exception: pass
        mid = await _v216_send_or_edit_panel(bot, chat_id, None, text, markup, pin=True)
        state.panel_message_id = int(mid)
        save_all_states()
        try: await enforce_single_core_messages(bot, chat_id)
        except Exception: pass


async def _v216_djemoji_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or not str(pending.get('kind','')).startswith('djemoji_'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    raw = telegram_html_from_message(update.message).strip() or plain_text_from_message(update.message).strip()
    raw = _v216_preserve_valid_tgemoji(raw)
    if not raw:
        await update.message.reply_html('Envíame el emoji premium o texto de estado.')
        raise _V216Stop
    kind = str(pending.get('kind'))
    if 'on' in kind:
        admin_cfg(chat_id)['dj_status_on_emoji'] = raw[:600]
    else:
        admin_cfg(chat_id)['dj_status_off_emoji'] = raw[:600]
    pop_config_pending(update.effective_user.id)
    save_all_states()
    try:
        if VOICE.application:
            await ensure_panel(VOICE.application.bot, chat_id)
    except Exception:
        pass
    await update.message.reply_html('✅ Estado guardado. Si era emoji premium válido, se verá en el mensaje fijado DJ.')
    raise _V216Stop


