def _v217_open_dj_settings_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Botonera mínima para abrir la configuración DJ desde el panel de ajustes."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎛 Abrir configuración DJ en ajustes', callback_data=f'cfg|block|{chat_id}|dj_permissions')],
        [InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'cfg|open|{chat_id}')],
    ])


def _v217_clean_dj_private_rows(rows: List[List[InlineKeyboardButton]]) -> List[List[InlineKeyboardButton]]:
    """Quita de /djconfig botones que editaban el fijado/estado y solapaban con /ajustes."""
    clean: List[List[InlineKeyboardButton]] = []
    banned_fragments = (
        'djpaneltext', 'djpanelreset', 'djemoji',
        'Editar fijado', 'Fijado por defecto', 'Emoji ON', 'Emoji OFF',
        'Editar mensaje fijado', 'Mensaje por defecto',
    )
    for row in rows or []:
        new_row: List[InlineKeyboardButton] = []
        for btn in row:
            text = str(getattr(btn, 'text', '') or '')
            cb = str(getattr(btn, 'callback_data', '') or '')
            if any(x in cb or x in text for x in banned_fragments):
                continue
            new_row.append(btn)
        if new_row:
            clean.append(new_row)
    return clean


