_old_djconfig_command_v217 = djconfig_command

async def djconfig_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Mantiene /djconfig como acceso rápido, pero ya no abre edición paralela.

    La configuración real queda centralizada en /ajustes -> DJ para que no se pisen
    emojis premium, estados y texto del panel fijado.
    """
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == 'private':
        groups = dj_private_groups_for(update.effective_user.id)
        if not groups:
            await update.message.reply_html('Primero entra en el grupo y ejecuta <code>/djgrupo</code>. Luego vuelve aquí y usa <code>/ajustes</code>.')
            return
        if len(groups) > 1:
            await update.message.reply_html('🎛️ <b>Elige el grupo DJ que quieres configurar</b>', reply_markup=dj_group_selector_markup(update.effective_user.id))
            return
    chat_id = dj_target_chat_id(update)
    if chat_id is None:
        await update.message.reply_html('Primero vincula un grupo con <code>/djgrupo</code>.')
        return
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text('Solo administradores del grupo vinculado.')
        return
    await update.message.reply_html(
        '<b>🎛 Configuración DJ centralizada</b>\n\n'
        'Para evitar que se solapen configuraciones, el mensaje fijado DJ, los estados ON/OFF y los emojis premium se editan sólo desde el menú de ajustes.\n\n'
        'Pulsa el botón para abrir el bloque correcto:',
        reply_markup=_v217_open_dj_settings_markup(int(chat_id))
    )


async def _v217_block_old_djpriv_panel_edit(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Bloquea las rutas antiguas djpriv|djpaneltext/reset para que no vuelvan a pisar ajustes."""
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('djpriv|djpanel'):
        return
    parts = data.split('|')
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = dj_target_chat_id(update) or 0
    await q.answer('Ahora se configura desde /ajustes → DJ', show_alert=True)
    try:
        if chat_id:
            await q.edit_message_text(
                '<b>🎛 Configuración DJ centralizada</b>\n\n'
                'Esta opción antigua está desactivada para no pisar los emojis premium ni el estado del panel.\n\n'
                'Usa el menú oficial de ajustes:',
                parse_mode=ParseMode.HTML,
                reply_markup=_v217_open_dj_settings_markup(int(chat_id)),
            )
    except Exception:
        pass
    raise _V217Stop


