    cfg.setdefault('hot_auto_enabled', False)
    cfg.setdefault('hot_auto_interval_seconds', 180)
    cfg.setdefault('hot_auto_min_messages', 1)
    cfg.setdefault('hot_auto_min_users', 1)
    cfg.setdefault('hot_auto_activity_window_seconds', 300)
    cfg.setdefault('hot_auto_allow_without_activity', False)
    cfg.setdefault('hot_auto_mix_challenges', True)
    cfg.setdefault('hot_auto_challenge_every', 5)
