def hot_auto_activity_label(chat_id: int) -> str:
    cfg = _v218_ensure_hot_defaults(chat_id)
    allow = bool(cfg.get('hot_auto_allow_without_activity', False))
    base = f"{max(1, int(cfg.get('hot_auto_min_messages', 1) or 1))} msgs / {max(1, int(cfg.get('hot_auto_min_users', 1) or 1))} users"
    return base + (' · sin actividad permitido' if allow else '')


def hot_auto_has_enough_interaction(chat_id: int, now: Optional[int] = None) -> bool:
    now = int(now or time.time())
    cfg = _v218_ensure_hot_defaults(chat_id)
    if bool(cfg.get('hot_auto_allow_without_activity', False)):
        return True
    window = max(20, int(cfg.get('hot_auto_activity_window_seconds', 300) or 300))
    min_messages = max(1, int(cfg.get('hot_auto_min_messages', 1) or 1))
    min_users = max(1, int(cfg.get('hot_auto_min_users', 1) or 1))
    cutoff = now - window
    recent = [x for x in HOT_CHAT_ACTIVITY_LOG.get(int(chat_id), []) if int(x.get('ts', 0)) >= cutoff]
    unique_users = {int(x.get('user_id', 0)) for x in recent if int(x.get('user_id', 0))}
    return len(recent) >= min_messages and len(unique_users) >= min_users


def _v218_recent_targets(chat_id: int, now: Optional[int] = None) -> List[Dict[str, Any]]:
    now = int(now or time.time())
    cfg = _v218_ensure_hot_defaults(chat_id)
    window = max(20, int(cfg.get('hot_auto_activity_window_seconds', 300) or 300))
    out: List[Dict[str, Any]] = []

    for u in HOT_RECENT_ACTIVITY.get(int(chat_id), {}).values():
        try:
            if now - int(u.get('ts', 0)) <= window:
                out.append(dict(u))
        except Exception:
            continue

    if not out:
        try:
            st = get_state(int(chat_id))
            for uid, row in (st.member_activity or {}).items():
                if not row or bool(row.get('is_bot', False)):
                    continue
                out.append({
                    'id': int(uid),
                    'name': row.get('name') or row.get('username') or str(uid),
                    'first_name': row.get('first_name') or row.get('name') or 'Usuario',
                    'ts': now,
                })
        except Exception:
            pass

    seen=set(); clean=[]
    for u in out:
        try:
            uid=int(u.get('id') or 0)
            if uid and uid not in seen:
                seen.add(uid); clean.append(u)
        except Exception:
            continue
    return clean


async def _v218_send_hot_to_group(application: Application, chat_id: int, *, force: bool = False, reason: str = 'auto') -> bool:
    """Envío HOT robusto: no depende de _v210 si devuelve False."""
    chat_id = int(chat_id)
    if not chat_is_allowed(chat_id):
        logger.info('V218 HOT: chat no permitido %s', chat_id)
        return False
    cfg = _v218_ensure_hot_defaults(chat_id)
    now = int(time.time())
    if not force:
        if not bool(cfg.get('hot_auto_enabled', False)):
            return False
        interval = max(10, int(cfg.get('hot_auto_interval_seconds', 180) or 180))
        if now - int(cfg.get('hot_last_auto_ts', 0) or 0) < interval:
            return False
        if not hot_auto_has_enough_interaction(chat_id, now):
            return False

    targets = _v218_recent_targets(chat_id, now)
    target = secrets.choice(targets) if targets else None
    level = hot_pick_level(chat_id, automatic=True)
    kind = hot_pick_auto_kind(chat_id)
    item = hot_get_item(chat_id, level, kind)
    is_challenge = kind == 'challenge'
    title = 'Retito automático' if is_challenge else 'Preguntita automática'
    icon = '🎲' if is_challenge else '💬'
    if target:
        mention = f'<a href="tg://user?id={int(target["id"])}">{h(target.get("first_name") or target.get("name") or "Usuario")}</a>'
        text = f'🎯 {mention}\n\n🤖 <b>{title} · Nivel {level}</b>\n\n{icon} {h(item)}'
    else:

        text = f'🤖 <b>{title} · Nivel {level}</b>\n\n{icon} {h(item)}\n\n<i>Para quien se anime a responder.</i>'
    try:
        msg = await application.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML)
    except Exception:
        logger.exception('V218 HOT: envío HTML falló; intento texto plano')
        plain = re.sub(r'<[^>]+>', '', text) if 're' in globals() else text.replace('<b>','').replace('</b>','').replace('<i>','').replace('</i>')
        msg = await application.bot.send_message(chat_id=chat_id, text=plain)
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    if target:
        try:
            class _U: pass
            fake = _U()
            fake.id = int(target['id'])
            fake.first_name = str(target.get('first_name') or target.get('name') or 'Usuario')
            fake.last_name = ''
            fake.username = None
            hot_register_question(chat_id, msg.message_id, fake, level, kind=kind)
        except Exception:
            logger.exception('V218 HOT: no pude registrar pregunta activa')
    cfg['hot_last_auto_ts'] = now
    cfg['hot_last_auto_reason'] = reason
    save_all_states()
    try:
        asyncio.create_task(hot_safe_delete(application, chat_id, msg.message_id))
    except Exception:
        pass
    logger.info('V218 HOT enviado chat=%s force=%s reason=%s', chat_id, force, reason)
    return True


async def _v218_hot_loop(app: Application) -> None:
    logger.info('V218 HOT loop interno arrancado')
    while True:
        try:
            await asyncio.sleep(V218_HOT_LOOP_SECONDS)
            for chat_id in list(STATE_CACHE.keys()):
                try:
                    await _v218_send_hot_to_group(app, int(chat_id), force=False, reason='loop')
                except Exception:
                    logger.exception('V218 HOT loop falló chat %s', chat_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V218 HOT loop error general')


async def _v218_hot_activity(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user:
        return
    if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
        return
    try:
        hot_activity_remember(int(update.effective_chat.id), update.effective_user)
    except Exception:
        pass
    try:
        remember_activity(int(update.effective_chat.id), update.effective_user, getattr(update, 'message', None))
    except Exception:
        pass


async def _v218_hot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        selected = hot_private_group_for(update.effective_user.id) if 'hot_private_group_for' in globals() else None
        if selected is None:
            await update.message.reply_html('Primero vincula grupo con <code>/hotgrupo</code>.')
            return
        chat_id = int(selected)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo admin puede probar preguntitas automáticas.')
        return
    ok = await _v218_send_hot_to_group(context.application, chat_id, force=True, reason='manual_command')
    await update.message.reply_text('✅ Preguntita/retito enviado al grupo.' if ok else '❌ No pude enviarlo. Revisa permisos o ALLOWED_CHAT_IDS.')


