async def _v218_hot_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('hotv218|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V218Stop
    if not (is_global_admin_user(q.from_user.id) or await is_admin(context, chat_id, q.from_user.id)):
        await q.answer('Solo administradores.', show_alert=True)
        raise _V218Stop
    cfg = _v218_ensure_hot_defaults(chat_id)
    if action == 'test':
        ok = await _v218_send_hot_to_group(context.application, chat_id, force=True, reason='manual_button')
        await q.answer('Enviado ✅' if ok else 'No pude enviar', show_alert=not ok)
    elif action == 'auto':
        cfg['hot_auto_enabled'] = not bool(cfg.get('hot_auto_enabled', False))
        save_all_states()
        await q.answer('Auto actualizado')
    elif action == 'act':
        cfg['hot_auto_min_messages'] = max(1, int(parts[3]))
        cfg['hot_auto_min_users'] = max(1, int(parts[4]))
        save_all_states()
        await q.answer('Actividad actualizada')
    elif action == 'allow':
        cfg['hot_auto_allow_without_activity'] = not bool(cfg.get('hot_auto_allow_without_activity', False))
        save_all_states()
        await q.answer('Modo sin actividad actualizado')
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, 'hot'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'hot'))
    except Exception:
        pass
    raise _V218Stop


