def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    txt = _old_admin_private_block_text_v218(chat_id, block, page)
    if block == 'hot':
        cfg = _v218_ensure_hot_defaults(chat_id)
        now = int(time.time())
        recent = [x for x in HOT_CHAT_ACTIVITY_LOG.get(int(chat_id), []) if now - int(x.get('ts', 0)) <= int(cfg.get('hot_auto_activity_window_seconds', 300) or 300)]
        users = {int(x.get('user_id', 0)) for x in recent if int(x.get('user_id', 0))}
        txt += (
            '\n\n<b>🔥 Estado V218:</b>'
            f'\nAuto real: <b>{bool_label(cfg.get("hot_auto_enabled", False))}</b>'
            f'\nActividad ahora: <b>{len(recent)} msgs / {len(users)} users</b>'
            f'\nSin actividad permitido: <b>{bool_label(cfg.get("hot_auto_allow_without_activity", False))}</b>'
            f'\nÚltimo motivo: <b>{h(str(cfg.get("hot_last_auto_reason", "")))}</b>'
        )
    return txt


_old_admin_private_block_markup_v218 = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    if block != 'hot':
        return _old_admin_private_block_markup_v218(chat_id, block, page)
    cfg = _v218_ensure_hot_defaults(chat_id)
    markup = _old_admin_private_block_markup_v218(chat_id, block, page)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    insert_at = max(0, len(rows)-1)
    rows.insert(insert_at, [
        InlineKeyboardButton('🧪 Enviar ahora V218', callback_data=f'hotv218|test|{chat_id}'),
        InlineKeyboardButton(('🔴 Auto OFF' if cfg.get('hot_auto_enabled') else '🟢 Auto ON'), callback_data=f'hotv218|auto|{chat_id}'),
    ])
    rows.insert(insert_at+1, [
        InlineKeyboardButton('Act. 1/1', callback_data=f'hotv218|act|{chat_id}|1|1'),
        InlineKeyboardButton('Act. 3/1', callback_data=f'hotv218|act|{chat_id}|3|1'),
        InlineKeyboardButton(('Sin actividad OFF' if cfg.get('hot_auto_allow_without_activity') else 'Sin actividad ON'), callback_data=f'hotv218|allow|{chat_id}'),
    ])
    return InlineKeyboardMarkup(rows)


async def _v218_post_init(app: Application) -> None:

    try:
        if '_old_post_init_v218' in globals() and callable(_old_post_init_v218):
            await _old_post_init_v218(app)
    except Exception:
        logger.exception('V218 post_init heredado falló')
    if app.bot_data.get(V218_HOT_TASK_KEY):
        return
    app.bot_data[V218_HOT_TASK_KEY] = True
    try:
        app.create_task(_v218_hot_loop(app), name='v218_hot_loop')
    except TypeError:
        app.create_task(_v218_hot_loop(app))


_old_build_application_v218 = build_application
_old_post_init_v218 = None

def build_application() -> Application:
    global _old_post_init_v218
    app = _old_build_application_v218()
    _old_post_init_v218 = getattr(app, 'post_init', None)
    app.post_init = _v218_post_init
    app.add_handler(CommandHandler(['preguntaauto', 'hotauto', 'probarpreguntita'], _v218_hot_command), group=-45000000000)
    app.add_handler(CommandHandler(['hotdebug', 'preguntitasdiag'], _v218_hot_debug_command), group=-45000000000)
    app.add_handler(CallbackQueryHandler(_v218_hot_router, pattern=r'^hotv218\|'), group=-45000000000)
    app.add_handler(MessageHandler(filters.ALL, _v218_hot_activity), group=-45000000000)
    logger.info('V218 Preguntitas AUTO real cargado')
    return app


