import re as _re_v219
import io as _io_v219
import shutil as _shutil_v219
from datetime import datetime as _dt_v219, timezone as _tz_v219, timedelta as _td_v219

BOT_VERSION = "V219"
V219_SECURITY_TASK_KEY = "v219_security_init_done"
V219_OWNER_NOTIFIED: set[str] = set()
V219_RESTORE_PENDING_KIND = "v219_restore_backup"


def _v219_parse_ids(raw: str) -> set[int]:
    out: set[int] = set()
    for part in (raw or "").replace(";", ",").split(","):
        part = part.strip().lstrip("=")
        if not part:
            continue
        try:
            out.add(int(part))
        except Exception:
            pass
    return out


def owner_ids() -> set[int]:
    ids = _v219_parse_ids(os.getenv("OWNER_IDS", ""))
    ids |= _v219_parse_ids(os.getenv("OWNER_ID", ""))
    if not ids:
        try:
            ids |= set(int(x) for x in ADMIN_IDS)
        except Exception:
            pass
    return ids


def is_owner_id(user_id: int) -> bool:
    ids = owner_ids()
    return bool(ids and int(user_id) in ids)


_old_is_global_admin_user_v219 = is_global_admin_user if 'is_global_admin_user' in globals() else None

def is_global_admin_user(user_id: int) -> bool:
    ids = owner_ids()
    if ids:
        return int(user_id) in ids
    if callable(_old_is_global_admin_user_v219):
        return bool(_old_is_global_admin_user_v219(user_id))
    return int(user_id) in ADMIN_IDS


def _v219_security_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    sec = cfg.setdefault('security_v219', {})
    if not isinstance(sec, dict):
        sec = {}
        cfg['security_v219'] = sec
    sec.setdefault('authorized', bool(cfg.get('owner_authorized', False)))
    sec.setdefault('first_seen_ts', int(time.time()))
    sec.setdefault('last_seen_ts', int(time.time()))
    sec.setdefault('auto_leave_if_unauthorized', env_bool('AUTO_LEAVE_UNAUTHORIZED_GROUPS', 'false'))
    sec.setdefault('strict_allowlist', env_bool('STRICT_GROUP_ALLOWLIST', 'true'))
    return sec


def _v219_group_authorized(chat_id: int) -> bool:
    chat_id = int(chat_id)
    if chat_id > 0:
        return True
    if ALLOWED_CHAT_IDS and chat_id in ALLOWED_CHAT_IDS:
        return True
    cfg = admin_cfg(chat_id)
    sec = _v219_security_cfg(chat_id)
    return bool(cfg.get('owner_authorized', False) or sec.get('authorized', False))


def _v219_set_group_authorized(chat_id: int, value: bool) -> None:
    cfg = admin_cfg(int(chat_id))
    cfg['owner_authorized'] = bool(value)
    sec = _v219_security_cfg(int(chat_id))
    sec['authorized'] = bool(value)
    sec['authorized_ts'] = int(time.time()) if value else None
    save_all_states()


def _v219_register_group(chat_id: int, title: str = "", *, source: str = "seen") -> None:
    if not chat_id or int(chat_id) > 0:
        return
    st = get_state(int(chat_id))
    cfg = admin_cfg(int(chat_id))
    if title:
        cfg['chat_title'] = title
    sec = _v219_security_cfg(int(chat_id))
    sec['last_seen_ts'] = int(time.time())
    sec['last_source'] = source
    if 'authorized' not in sec:
        sec['authorized'] = bool(cfg.get('owner_authorized', False))
    save_all_states()


def _v219_known_groups() -> List[int]:
    try:
        load_all_states()
    except Exception:
        pass
    groups = set(int(cid) for cid in STATE_CACHE.keys() if int(cid) < 0)
    try:
        for cid in known_admin_chats_for_private():
            if int(cid) < 0:
                groups.add(int(cid))
    except Exception:
        pass
    return sorted(groups)


def _v219_group_title(chat_id: int) -> str:
    try:
        return str(cfg_value(int(chat_id), 'chat_title', '') or chat_id)
    except Exception:
        return str(chat_id)


def _v219_fmt_dt(ts: Any) -> str:
    try:
        return _dt_v219.fromtimestamp(int(ts), tz=_tz_v219.utc).astimezone().strftime('%d/%m/%Y %H:%M')
    except Exception:
        return '—'


def _v219_initialize_known_groups() -> None:
    changed = False
    for chat_id in list(STATE_CACHE.keys()):
        try:
            if int(chat_id) < 0:
                cfg = admin_cfg(int(chat_id))
                sec = _v219_security_cfg(int(chat_id))
                if 'v219_initialized' not in sec:
                    sec['v219_initialized'] = True
                    if 'owner_authorized' not in cfg and 'authorized' not in sec:
                        cfg['owner_authorized'] = True
                        sec['authorized'] = True
                    elif 'owner_authorized' not in cfg:
                        cfg['owner_authorized'] = bool(sec.get('authorized', True))
                    changed = True
        except Exception:
            pass
    if changed:
        save_all_states()


