async def _v219_notify_owners(bot, text: str, key: str = '') -> None:
    ids = owner_ids()
    if not ids:
        logger.warning('V219 sin OWNER_ID/OWNER_IDS/ADMIN_IDS para notificar: %s', text)
        return
    if key and key in V219_OWNER_NOTIFIED:
        return
    if key:
        V219_OWNER_NOTIFIED.add(key)
    for oid in ids:
        try:
            await bot.send_message(chat_id=oid, text=text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        except Exception:
            logger.exception('No pude notificar al owner %s', oid)


async def _v219_my_chat_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    upd = getattr(update, 'my_chat_member', None)
    if not upd or not getattr(upd, 'chat', None):
        return
    chat = upd.chat
    chat_id = int(chat.id)
    if chat_id > 0:
        return
    new_status = getattr(getattr(upd, 'new_chat_member', None), 'status', '')
    old_status = getattr(getattr(upd, 'old_chat_member', None), 'status', '')
    title = getattr(chat, 'title', '') or str(chat_id)
    _v219_register_group(chat_id, title, source=f'my_chat_member:{old_status}->{new_status}')
    if new_status in ('member', 'administrator') and not _v219_group_authorized(chat_id):
        txt = (
            '🚨 <b>AVISO DE SEGURIDAD</b>\n\n'
            'Han metido el bot en un grupo no autorizado.\n\n'
            f'Grupo: <b>{h(title)}</b>\n'
            f'ID: <code>{chat_id}</code>\n'
            f'Estado bot: <b>{h(new_status)}</b>\n\n'
            'Entra en <b>/ajustes → 🛡 Seguridad / Grupos</b> para autorizarlo, bloquearlo o sacar el bot.'
        )
        await _v219_notify_owners(context.bot, txt, key=f'new_group:{chat_id}:{new_status}')
        if env_bool('AUTO_LEAVE_UNAUTHORIZED_GROUPS', 'false'):
            try:
                await context.bot.leave_chat(chat_id)
            except Exception:
                logger.exception('No pude salir automáticamente del grupo no autorizado %s', chat_id)


async def _v219_unauthorized_message_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    chat = update.effective_chat
    if not chat or chat.type == 'private' or int(chat.id) > 0:
        return
    chat_id = int(chat.id)
    _v219_register_group(chat_id, getattr(chat, 'title', '') or '', source='message_guard')
    if _v219_group_authorized(chat_id):
        return

    await _v219_notify_owners(
        context.bot,
        '🚫 <b>Bot usado en grupo no autorizado</b>\n\n'
        f'Grupo: <b>{h(getattr(chat, "title", "") or chat_id)}</b>\nID: <code>{chat_id}</code>\n\n'
        'El mensaje ha sido bloqueado por V219.',
        key=f'unauth_msg:{chat_id}'
    )
    raise _V219Stop


async def _v219_unauthorized_callback_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    chat = update.effective_chat
    if not q or not chat or chat.type == 'private' or int(chat.id) > 0:
        return
    chat_id = int(chat.id)
    if _v219_group_authorized(chat_id):
        return
    try:
        await q.answer('Grupo no autorizado por el dueño del bot.', show_alert=True)
    except Exception:
        pass
    await _v219_notify_owners(context.bot, f'🚫 Callback bloqueado en grupo no autorizado <code>{chat_id}</code>.', key=f'unauth_cb:{chat_id}')
    raise _V219Stop


def _v219_panel_safe_text(text: str) -> str:
    return str(text or '').replace('\x00', '').strip() or '🎧 DJ-PLAN'


async def _v219_edit_or_send(bot, *, chat_id: int, message_id: Optional[int], text: str, reply_markup=None, parse_mode=ParseMode.HTML, reply_to_message_id: Optional[int]=None):
    text = _v219_panel_safe_text(text)
    if message_id:
        try:
            return await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=text, reply_markup=reply_markup, parse_mode=parse_mode)
        except BadRequest as e:
            low = str(e).lower()
            if 'message is not modified' in low:
                return None
            if 'message to edit not found' not in low and 'message can\'t be edited' not in low:
                logger.warning('V219 edit_message falló; recreo: %s', e)
        except Exception:
            logger.exception('V219 edit_message falló; recreo')
    try:
        return await bot.send_message(chat_id=chat_id, text=text, reply_markup=reply_markup, parse_mode=parse_mode, reply_to_message_id=reply_to_message_id, allow_sending_without_reply=True)
    except BadRequest:

        plain = _re_v219.sub(r'<[^>]+>', '', text)
        return await bot.send_message(chat_id=chat_id, text=plain, reply_markup=reply_markup, reply_to_message_id=reply_to_message_id, allow_sending_without_reply=True)


async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, int(chat_id)):
        state = get_state(int(chat_id))
        if not state.dj_mode:
            return
        try:
            sync_panel_override_expiry(state)
        except Exception:
            pass
        text = panel_text(state)
        markup = panel_markup()
        old_id = state.panel_message_id
        msg = await _v219_edit_or_send(bot, chat_id=int(chat_id), message_id=old_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
        if msg is not None:
            state.panel_message_id = msg.message_id
            await register_bot_message(int(chat_id), msg.message_id)
            try:
                await bot.pin_chat_message(chat_id=int(chat_id), message_id=msg.message_id, disable_notification=True)
            except BadRequest as e:
                if 'not modified' not in str(e).lower():
                    logger.warning('V219 no pudo fijar panel: %s', e)
            except Exception:
                logger.exception('V219 no pudo fijar panel')
        save_all_states()


async def ensure_control_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(CONTROL_LOCKS, int(chat_id)):
        state = get_state(int(chat_id))
        if not state.dj_mode:
            return
        cfg = admin_cfg(int(chat_id))
        if bool(cfg.get('dj_control_minimized_v219', False)):
            return
        if not state.panel_message_id:
            await ensure_panel(bot, int(chat_id))
        text, markup = current_control_view(state)
        old_id = state.control_message_id
        msg = await _v219_edit_or_send(
            bot,
            chat_id=int(chat_id),
            message_id=old_id,
            text=text,
            reply_markup=markup,
            parse_mode=ParseMode.HTML,
            reply_to_message_id=state.panel_message_id,
        )
        if msg is not None:

            if old_id and old_id != msg.message_id:
                try:
                    await safe_delete(bot, int(chat_id), old_id)
                except Exception:
                    pass
            state.control_message_id = msg.message_id
            await register_bot_message(int(chat_id), msg.message_id)
        save_all_states()


async def _v219_dj_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    data = q.data or ''
    if data not in ('menu_panel', 'panel_home', 'panel_minimize'):
        return
    chat_id = int(update.effective_chat.id)
    if not _v219_group_authorized(chat_id):
        await q.answer('Grupo no autorizado.', show_alert=True)
        raise _V219Stop
    state = get_state(chat_id)
    if data in ('menu_panel', 'panel_home'):
        state.dj_mode = True
        admin_cfg(chat_id)['dj_control_minimized_v219'] = False
        save_all_states()
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
        await q.answer('Mesa DJ-PRO abierta')
        raise _V219Stop
    if data == 'panel_minimize':
        admin_cfg(chat_id)['dj_control_minimized_v219'] = True
        if state.control_message_id:
            await safe_delete(context.bot, chat_id, state.control_message_id)
            state.control_message_id = None
        save_all_states()
        await ensure_panel(context.bot, chat_id)
        await q.answer('Mesa minimizada. Pulsa Mesa para mostrarla.')
        raise _V219Stop


def _v219_dj_like_key(track: Track) -> str:
    try:
        return _dj_track_like_key_v20(asdict(track))
    except Exception:
        return track_fingerprint(track)


def _v219_like_count(chat_id: int, key: str) -> int:
    try:
        return len(admin_cfg(chat_id).setdefault('dj_track_likes', {}).setdefault(key, {'users': []}).setdefault('users', []))
    except Exception:
        return 0


def _v219_announce_text(chat_id: int, track: Track, key: str) -> str:
    text = f'🎵 <b>Sonando ahora</b>\n{h(track.title)}'
    if track.performer:
        text += f'\n<i>{h(track.performer)}</i>'
    text += f'\n\n❤️ Me gusta: <b>{_v219_like_count(chat_id, key)}</b>'
    return text


def _v219_announce_markup(chat_id: int, token: str, key: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton(f'❤️ Me gusta · {_v219_like_count(chat_id, key)}', callback_data=f'djv219like|{token}')]])


DJ_ANNOUNCE_TOKENS_V219: Dict[str, Dict[str, Any]] = globals().setdefault('DJ_ANNOUNCE_TOKENS_V219', {})


async def _send_dj_now_announce_v24(bot, chat_id: int, track: Track) -> None:
    try:
        enabled = True
        if '_v215_dj_cfg' in globals():
            enabled = bool(_v215_dj_cfg(chat_id).get('dj_announce_now_enabled', True))
        if not enabled:
            return
        key = _v219_dj_like_key(track)
        token = secrets.token_hex(4)
        DJ_ANNOUNCE_TOKENS_V219[token] = {'chat_id': int(chat_id), 'key': key, 'track': asdict(track), 'created_at': int(time.time())}
        cfg = admin_cfg(chat_id)
        likes = cfg.setdefault('dj_track_likes', {})
        likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
        save_all_states()
        msg = await bot.send_message(chat_id=chat_id, text=_v219_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML, reply_markup=_v219_announce_markup(chat_id, token, key))
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        logger.exception('V219 no pudo mandar aviso limpio de canción')


async def _v219_dj_like_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djv219like|') or not update.effective_chat:
        return
    token = (q.data or '').split('|', 1)[1]
    info = DJ_ANNOUNCE_TOKENS_V219.get(token)
    if not info:
        await q.answer('Aviso caducado.', show_alert=True)
        raise _V219Stop
    chat_id = int(info.get('chat_id') or update.effective_chat.id)
    key = str(info.get('key') or '')
    track = Track(**(info.get('track') or get_state(chat_id).now_playing or {'title': 'Canción'}))
    row = admin_cfg(chat_id).setdefault('dj_track_likes', {}).setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
    users = [str(x) for x in row.setdefault('users', [])]
    uid = str(q.from_user.id)
    if uid in users:
        users.remove(uid)
        await q.answer('Quitado ❤️')
    else:
        users.append(uid)
        await q.answer('Me gusta ❤️')
    row['users'] = users
    save_all_states()
    try:
        await q.edit_message_text(_v219_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML, reply_markup=_v219_announce_markup(chat_id, token, key))
    except Exception:
        pass
    raise _V219Stop


