async def _v219_export_backup(context: ContextTypes.DEFAULT_TYPE, user_id: int, chat_id: Optional[int] = None) -> None:
    load_all_states()
    payload = {
        'version': BOT_VERSION,
        'created_at': int(time.time()),
        'created_at_iso': _dt_v219.now(_tz_v219.utc).isoformat(),
        'state_path': str(STATE_PATH),
        'selected_chat_id': int(chat_id) if chat_id else None,
        'state': {str(cid): asdict(st) for cid, st in STATE_CACHE.items()},
    }
    raw = json.dumps(payload, ensure_ascii=False, indent=2).encode('utf-8')
    bio = _io_v219.BytesIO(raw)
    bio.name = f'djplan_backup_{BOT_VERSION}_{int(time.time())}.json'
    await context.bot.send_document(chat_id=user_id, document=bio, filename=bio.name, caption=f'📦 Copia de seguridad DJ-PLAN {BOT_VERSION}')


async def _v219_backup_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('backup|'):
        return
    if not is_owner_id(q.from_user.id):
        await q.answer('Solo el dueño puede usar backups.', show_alert=True)
        raise _V219Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    chat_id = int(parts[2]) if len(parts) > 2 and str(parts[2]).lstrip('-').isdigit() else None
    if action == 'export':
        await q.answer('Generando copia…')
        await _v219_export_backup(context, q.from_user.id, chat_id)
    elif action == 'restore':
        set_config_pending(q.from_user.id, {'kind': V219_RESTORE_PENDING_KIND, 'chat_id': chat_id or 0})
        await q.answer('Envíame el archivo JSON por privado.', show_alert=True)
        try:
            await q.message.reply_html('📥 <b>Restaurar backup</b>\n\nEnvíame ahora el archivo <code>.json</code> de copia de seguridad.\n\nAntes de restaurar crearé una copia automática del estado actual.')
        except Exception:
            pass
    raise _V219Stop


async def _v219_restore_document_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message or not update.message.document:
        return
    if not is_owner_id(update.effective_user.id):
        return
    if update.effective_chat and update.effective_chat.type != 'private':
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != V219_RESTORE_PENDING_KIND:
        return
    doc = update.message.document
    name = doc.file_name or 'backup.json'
    if not name.lower().endswith('.json'):
        await update.message.reply_text('Ese archivo no parece JSON. Envíame el backup .json.')
        raise _V219Stop
    try:
        tg_file = await context.bot.get_file(doc.file_id)
        tmp = DOWNLOAD_DIR / f'v219_restore_{secrets.token_hex(6)}.json'
        await tg_file.download_to_drive(custom_path=str(tmp))
        data = json.loads(tmp.read_text(encoding='utf-8'))
        state_raw = data.get('state') if isinstance(data, dict) else None
        if not isinstance(state_raw, dict):
            raise RuntimeError('El JSON no contiene clave state válida.')

        try:
            if STATE_PATH.exists():
                dst = STATE_PATH.with_name(STATE_PATH.name + f'.before_restore_v219_{int(time.time())}.bak')
                _shutil_v219.copy2(STATE_PATH, dst)
        except Exception:
            pass

        fields = {f.name for f in dataclasses.fields(ChatState)} if 'dataclasses' in globals() else set()
        new_cache: Dict[int, ChatState] = {}
        for cid_s, st_data in state_raw.items():
            cid = int(cid_s)
            sd = dict(st_data or {})
            if '_v189_migrate_state_dict' in globals():
                sd = _v189_migrate_state_dict(sd)
            if fields:
                sd = {k: v for k, v in sd.items() if k in fields}
            new_cache[cid] = ChatState(**sd)
        STATE_CACHE.clear()
        STATE_CACHE.update(new_cache)
        save_all_states()
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html(f'✅ Backup restaurado correctamente. Grupos cargados: <b>{len(STATE_CACHE)}</b>. Reinicia Railway para asegurar todos los jobs.')
    except Exception as e:
        logger.exception('V219 restore falló')
        await update.message.reply_html('❌ No pude restaurar el backup.\n\n<code>' + h(str(e)[:900]) + '</code>')
    raise _V219Stop


def _v219_security_menu_text() -> str:
    groups = _v219_known_groups()
    lines = [
        f'<b>🛡 Seguridad / Grupos · {BOT_VERSION}</b>',
        '',
        f'Dueños configurados: <b>{len(owner_ids())}</b>',
        f'Grupos conocidos: <b>{len(groups)}</b>',
        '',
        'Sólo el dueño puede autorizar grupos y acceder a áreas privadas del bot.',
        '',
    ]
    if not groups:
        lines.append('No tengo grupos registrados todavía.')
    else:
        for cid in groups[:20]:
            lines.append(f'{"✅" if _v219_group_authorized(cid) else "🚫"} <code>{cid}</code> · {h(_v219_group_title(cid))}')
        if len(groups) > 20:
            lines.append(f'… y {len(groups)-20} más')
    return '\n'.join(lines)


