async def _v219_security_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('sec|'):
        return
    if not is_owner_id(q.from_user.id):
        await q.answer('Solo el dueño del bot.', show_alert=True)
        raise _V219Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else 'menu'
    if action == 'menu':
        await q.answer()
        await q.edit_message_text(_v219_security_menu_text(), parse_mode=ParseMode.HTML, reply_markup=_v219_security_menu_markup())
    elif action == 'group' and len(parts) >= 3:
        cid = int(parts[2])
        await q.answer()
        await q.edit_message_text(_v219_group_text(cid), parse_mode=ParseMode.HTML, reply_markup=_v219_group_markup(cid))
    elif action in ('auth', 'block') and len(parts) >= 3:
        cid = int(parts[2])
        _v219_set_group_authorized(cid, action == 'auth')
        await q.answer('Grupo autorizado ✅' if action == 'auth' else 'Grupo bloqueado 🚫', show_alert=False)
        await q.edit_message_text(_v219_group_text(cid), parse_mode=ParseMode.HTML, reply_markup=_v219_group_markup(cid))
    elif action == 'leave' and len(parts) >= 3:
        cid = int(parts[2])
        try:
            await context.bot.leave_chat(cid)
            await q.answer('Bot saliendo del grupo…', show_alert=True)
        except Exception as e:
            await q.answer('No pude salir: ' + str(e)[:120], show_alert=True)
        await q.edit_message_text(_v219_group_text(cid), parse_mode=ParseMode.HTML, reply_markup=_v219_group_markup(cid))
    raise _V219Stop


def _v219_member_rows(chat_id: int) -> List[Tuple[int, Dict[str, Any]]]:
    st = get_state(int(chat_id))
    rows: Dict[int, Dict[str, Any]] = {}
    for uid, rec in (st.member_activity or {}).items():
        try:
            rows[int(uid)] = dict(rec or {})
        except Exception:
            pass
    for rec in (st.entry_log or []):
        try:
            uid = int(rec.get('user_id') or 0)
            if uid:
                rows.setdefault(uid, {}).update({k: v for k, v in rec.items() if v is not None})
        except Exception:
            pass
    return sorted(rows.items(), key=lambda kv: int(kv[1].get('last_seen_ts') or kv[1].get('joined_ts') or 0), reverse=True)


def _v219_members_text(chat_id: int, page: int = 0) -> str:
    rows = _v219_member_rows(chat_id)
    page_size = 8
    total_pages = max(1, (len(rows)-1)//page_size + 1)
    page = max(0, min(int(page), total_pages-1))
    chunk = rows[page*page_size:(page+1)*page_size]
    lines = [f'<b>👥 Miembros conocidos</b> · {h(_v219_group_title(chat_id))}', '', f'Total conocidos: <b>{len(rows)}</b> · Página <b>{page+1}/{total_pages}</b>', '']
    if not chunk:
        lines.append('Aún no tengo miembros registrados. Telegram no permite listar todos los miembros antiguos si no los ha visto el bot.')
    for uid, rec in chunk:
        name = rec.get('name') or rec.get('username') or uid
        msgs = int(rec.get('message_count') or 0)
        media = int(rec.get('media_count') or rec.get('multimedia_count') or 0)
        joined = rec.get('joined_ts') or rec.get('first_seen_ts')
        source = rec.get('join_source') or rec.get('source') or rec.get('last_source') or '—'
        lines.append(f'• {mention_from_known_user(uid, rec)}')
        lines.append(f'  Mensajes: <b>{msgs}</b> · Multimedia: <b>{media}</b> · Entrada: <b>{_v219_fmt_dt(joined)}</b> · Vía: <i>{h(source)}</i>')
    return '\n'.join(lines)


def _v219_members_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    rows_data = _v219_member_rows(chat_id)
    page_size = 8
    total_pages = max(1, (len(rows_data)-1)//page_size + 1)
    page = max(0, min(int(page), total_pages-1))
    chunk = rows_data[page*page_size:(page+1)*page_size]
    rows: List[List[InlineKeyboardButton]] = []
    for uid, rec in chunk:
        label = (rec.get('name') or rec.get('username') or str(uid))[:32]
        rows.append([InlineKeyboardButton('👤 ' + label, callback_data=f'members|view|{chat_id}|{uid}|{page}')])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'members|list|{chat_id}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{total_pages}', callback_data=f'members|list|{chat_id}|{page}'))
    if page < total_pages - 1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'members|list|{chat_id}|{page+1}'))
    rows.append(nav)
    rows.append([InlineKeyboardButton('🔙 Grupo', callback_data=f'sec|group|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v219_member_text(chat_id: int, user_id: int) -> str:
    rec = dict(get_state(chat_id).member_activity.get(str(user_id), {}))
    for e in reversed(get_state(chat_id).entry_log):
        if int(e.get('user_id') or 0) == int(user_id):
            rec.update({k: v for k, v in e.items() if v is not None})
            break
    return (
        f'<b>👤 Ficha miembro</b>\n\n'
        f'Usuario: {mention_from_known_user(int(user_id), rec)}\n'
        f'ID: <code>{int(user_id)}</code>\n'
        f'Username: <b>{h(rec.get("username") or "—")}</b>\n'
        f'Mensajes: <b>{int(rec.get("message_count") or 0)}</b>\n'
        f'Multimedia: <b>{int(rec.get("media_count") or rec.get("multimedia_count") or 0)}</b>\n'
        f'Entrada detectada: <b>{_v219_fmt_dt(rec.get("joined_ts") or rec.get("first_seen_ts"))}</b>\n'
        f'Última actividad: <b>{_v219_fmt_dt(rec.get("last_seen_ts"))}</b>\n'
        f'Vía/enlace: <i>{h(rec.get("join_source") or rec.get("source") or rec.get("last_source") or "—")}</i>'
    )


def _v219_member_markup(chat_id: int, user_id: int, page: int = 0) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🔇 Silenciar 1h', callback_data=f'members|mute|{chat_id}|{user_id}|{page}'), InlineKeyboardButton('🔊 Quitar silencio', callback_data=f'members|unmute|{chat_id}|{user_id}|{page}')],
        [InlineKeyboardButton('👢 Expulsar', callback_data=f'members|kick|{chat_id}|{user_id}|{page}'), InlineKeyboardButton('🚫 Banear', callback_data=f'members|ban|{chat_id}|{user_id}|{page}')],
        [InlineKeyboardButton('🔙 Lista', callback_data=f'members|list|{chat_id}|{page}')],
    ])


async def _v219_members_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('members|'):
        return
    if not is_owner_id(q.from_user.id):
        await q.answer('Solo el dueño del bot.', show_alert=True)
        raise _V219Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else 'list'
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V219Stop
    if action == 'list':
        page = int(parts[3]) if len(parts) > 3 else 0
        await q.answer()
        await q.edit_message_text(_v219_members_text(chat_id, page), parse_mode=ParseMode.HTML, reply_markup=_v219_members_markup(chat_id, page))
    elif action == 'view':
        user_id = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
        await q.answer()
        await q.edit_message_text(_v219_member_text(chat_id, user_id), parse_mode=ParseMode.HTML, reply_markup=_v219_member_markup(chat_id, user_id, page))
    elif action in ('mute', 'unmute', 'kick', 'ban'):
        user_id = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
        try:
            if action == 'mute':
                until = _dt_v219.now(_tz_v219.utc) + _td_v219(hours=1)
                await context.bot.restrict_chat_member(chat_id=chat_id, user_id=user_id, permissions=ChatPermissions(can_send_messages=False), until_date=until)
                mark_user_muted(chat_id, user_id, reason='owner_panel_1h', until_ts=int(until.timestamp()))
                await q.answer('Silenciado 1h ✅')
            elif action == 'unmute':
                await context.bot.restrict_chat_member(chat_id=chat_id, user_id=user_id, permissions=ChatPermissions.all_permissions())
                unmark_user_muted(chat_id, user_id)
                await q.answer('Silencio quitado ✅')
            elif action == 'kick':
                await context.bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
                await context.bot.unban_chat_member(chat_id=chat_id, user_id=user_id, only_if_banned=True)
                mark_user_expelled(chat_id, user_id, reason='kick desde panel owner', by_user_id=q.from_user.id)
                await q.answer('Expulsado ✅', show_alert=True)
            elif action == 'ban':
                await context.bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
                mark_user_expelled(chat_id, user_id, reason='ban desde panel owner', by_user_id=q.from_user.id)
                await q.answer('Baneado ✅', show_alert=True)
        except Exception as e:
            await q.answer('No pude ejecutar acción: ' + str(e)[:140], show_alert=True)
        await q.edit_message_text(_v219_member_text(chat_id, user_id), parse_mode=ParseMode.HTML, reply_markup=_v219_member_markup(chat_id, user_id, page))
    raise _V219Stop


_old_remember_member_activity_v219 = remember_member_activity if 'remember_member_activity' in globals() else None

def remember_member_activity(chat_id: int, user, *, kind: str = "message", source: str = "") -> None:
    if callable(_old_remember_member_activity_v219):
        _old_remember_member_activity_v219(chat_id, user, kind=kind, source=source)
    try:
        if not user or getattr(user, 'is_bot', False):
            return
        st = get_state(int(chat_id))
        uid = str(int(user.id))
        rec = st.member_activity.setdefault(uid, user_record_from_user(user))
        rec.setdefault('first_seen_ts', int(time.time()))
        rec['last_seen_ts'] = int(time.time())
        if kind in ('photo', 'video', 'document', 'audio', 'voice', 'animation', 'sticker', 'media') or 'media' in str(source):
            rec['media_count'] = int(rec.get('media_count') or 0) + 1
        save_all_states()
    except Exception:
        pass


async def _v219_member_activity_tracker(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or update.effective_chat.type == 'private':
        return
    msg = update.message or update.edited_message
    kind = 'message'
    if msg:
        for attr, name in [('photo','photo'),('video','video'),('document','document'),('audio','audio'),('voice','voice'),('animation','animation'),('sticker','sticker')]:
            if getattr(msg, attr, None):
                kind = name
                break
    try:
        remember_member_activity(int(update.effective_chat.id), update.effective_user, kind=kind, source=kind)
    except Exception:
        pass


_old_admin_private_main_markup_v219 = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    base = _old_admin_private_main_markup_v219(chat_id)
    rows = [list(r) for r in getattr(base, 'inline_keyboard', [])]
    insert_at = max(0, len(rows)-1)
