def _v221_owner_or_admin_id(user_id: int) -> bool:
    try:
        if int(user_id) in set(owner_ids()):
            return True
    except Exception:
        pass
    try:
        return int(user_id) in set(ADMIN_IDS)
    except Exception:
        return False


async def _v221_can_force_validate(context: ContextTypes.DEFAULT_TYPE, chat_id: int, actor_id: int) -> bool:

    if _v221_owner_or_admin_id(actor_id):
        return True
    try:
        member = await context.bot.get_chat_member(chat_id, actor_id)
        return getattr(member, 'status', '') in ('administrator', 'creator')
    except Exception:
        return False


async def _v221_unrestrict_best_effort(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> tuple[bool, str]:
    """Intenta quitar restricciones de varias formas. Devuelve (ok, detalle)."""
    attempts = []


    try:
        perms = ChatPermissions(
            can_send_messages=True,
            can_send_audios=True,
            can_send_documents=True,
            can_send_photos=True,
            can_send_videos=True,
            can_send_video_notes=True,
            can_send_voice_notes=True,
            can_send_polls=True,
            can_send_other_messages=True,
            can_add_web_page_previews=True,
            can_invite_users=True,
            can_manage_topics=True,
        )
        attempts.append(('permisos explícitos', perms))
    except Exception as e:
        attempts.append(('permisos explícitos no disponibles', e))

    try:
        attempts.append(('all_permissions', ChatPermissions.all_permissions()))
    except Exception as e:
        attempts.append(('all_permissions no disponible', e))

    last_error = ''
    for label, perms in attempts:
        if isinstance(perms, Exception):
            last_error = f'{label}: {perms}'
            continue
        try:
            await context.bot.restrict_chat_member(chat_id=chat_id, user_id=int(user_id), permissions=perms)
            try:
                unmark_user_muted(chat_id, int(user_id))
            except Exception:
                pass
            return True, label
        except Exception as e:
            last_error = f'{label}: {type(e).__name__}: {e}'
            logger.exception('V221 intento de desrestricción fallido: %s', label)

    return False, last_error or 'sin detalle'


def _v221_record_for_user(chat_id: int, user_id: int) -> Dict[str, Any]:
    record = {}
    try:
        record = validation_get_record(chat_id, user_id) or {}
    except Exception:
        record = {}
    if not record:
        try:
            record = dict(get_state(chat_id).member_activity.get(str(user_id), {}) or {})
        except Exception:
            record = {}
    record.setdefault('user_id', int(user_id))
    record.setdefault('name', str(record.get('name') or record.get('username') or user_id))
    record.setdefault('username', str(record.get('username') or ''))
    record.setdefault('answers', record.get('answers') or [])
    return record


async def _v221_force_validate_user(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id: int,
    user_id: int,
    actor_id: int,
    actor_html: str = '',
    *,
    send_public_message: bool = True,
) -> tuple[bool, str]:
    """Marca validado y quita restricciones. Diseñado para usarse desde botones y comandos."""
    if not await _v221_can_force_validate(context, chat_id, actor_id):
        return False, 'No tienes permiso para forzar validaciones en ese grupo.'


    try:
        if chat_id < 0 and not _v219_group_authorized(chat_id) and not _v221_owner_or_admin_id(actor_id):
            return False, 'Grupo no autorizado por el dueño del bot.'
    except Exception:
        pass

    unrestrict_ok, unrestrict_detail = await _v221_unrestrict_best_effort(context, chat_id, int(user_id))

    record = _v221_record_for_user(chat_id, int(user_id))
    record['status'] = 'validated'
    record['force_validated'] = True
    record['validated_by'] = int(actor_id)
    try:
        record['validated_ts'] = _now_ts()
    except Exception:
        record['validated_ts'] = int(__import__('time').time())
    record['unrestrict_ok'] = bool(unrestrict_ok)
    record['unrestrict_detail'] = str(unrestrict_detail)

    try:
        validation_set_record(chat_id, int(user_id), record)
    except Exception:
        logger.exception('V221 no pudo guardar validation_set_record')
        try:
            st = get_state(chat_id)
            st.validation_users[str(int(user_id))] = record
            save_all_states()
        except Exception:
            logger.exception('V221 no pudo guardar en state.validation_users')

    try:
        unmark_user_muted(chat_id, int(user_id))
    except Exception:
        pass

    try:
        add_action_log(chat_id, 'validación forzada', f'Usuario {record.get("name") or user_id} · unrestrict={unrestrict_ok}', user_id=actor_id)
    except Exception:
        pass

    target_mention = f'<a href="tg://user?id={int(user_id)}">{h(record.get("name") or user_id)}</a>'
    if send_public_message:
        try:
            approved_text = str(cfg_value(chat_id, 'validation_approved_message', VALIDATION_APPROVED_MESSAGE))
            approved_text = approved_text.replace('{mention}', target_mention).replace('{name}', h(record.get('name', '')))
            await send_configured_profile_message(context.bot, chat_id, 'approved', approved_text)
        except Exception:
            logger.exception('V221 no pudo mandar mensaje aprobado; envío fallback')
            try:
                await context.bot.send_message(chat_id=chat_id, text=f'✅ Usuario validado: {target_mention}', parse_mode=ParseMode.HTML)
            except Exception:
                pass

    if unrestrict_ok:
        return True, f'Usuario validado y desilenciado correctamente ({unrestrict_detail}).'
    return True, 'Usuario marcado como validado, pero Telegram no permitió quitar restricciones: ' + str(unrestrict_detail)


try:
    _old_v219_member_markup_v221 = _v219_member_markup
except Exception:
    _old_v219_member_markup_v221 = None


def _v219_member_markup(chat_id: int, user_id: int, page: int = 0) -> InlineKeyboardMarkup:
    try:
        old = _old_v219_member_markup_v221(chat_id, user_id, page) if callable(_old_v219_member_markup_v221) else None
        rows = [list(r) for r in (old.inline_keyboard if old else [])]
    except Exception:
        rows = []

    force_row = [InlineKeyboardButton('✅ Forzar validación', callback_data=f'members|forceval|{int(chat_id)}|{int(user_id)}|{int(page)}')]

    if not any(any(getattr(b, 'callback_data', '') == force_row[0].callback_data for b in row) for row in rows):
        rows.insert(0, force_row)
    if not rows:
        rows.append([InlineKeyboardButton('🔙 Lista', callback_data=f'members|list|{int(chat_id)}|{int(page)}')])
    return InlineKeyboardMarkup(rows)


async def _v221_force_validation_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not (data.startswith('members|forceval|') or data.startswith('cfg|pendapprove|') or data.startswith('val|ok|')):
        return

    actor_id = int(update.effective_user.id)


    if data.startswith('members|forceval|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2]); user_id = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
        except Exception:
            await q.answer('Datos inválidos para validar.', show_alert=True)
            raise _V221Stop
        ok, msg = await _v221_force_validate_user(context, chat_id, user_id, actor_id, update.effective_user.mention_html())
        await q.answer(('✅ ' if ok else '❌ ') + msg[:180], show_alert=not ok)
        try:
            await q.edit_message_text(_v219_member_text(chat_id, user_id), parse_mode=ParseMode.HTML, reply_markup=_v219_member_markup(chat_id, user_id, page))
        except Exception:
            pass
        raise _V221Stop


    if data.startswith('cfg|pendapprove|'):
        parts = data.split('|')
        try:
            chat_id = int(parts[2]); user_id = int(parts[3])
        except Exception:
            await q.answer('Datos inválidos para validar.', show_alert=True)
            raise _V221Stop
        ok, msg = await _v221_force_validate_user(context, chat_id, user_id, actor_id, update.effective_user.mention_html())
        await q.answer(('✅ ' if ok else '❌ ') + msg[:180], show_alert=not ok)
        try:
            await q.edit_message_text(validation_pending_summary_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=private_pending_markup(chat_id))
        except Exception:
            pass
        raise _V221Stop


    if data.startswith('val|ok|'):
        parts = data.split('|')
        try:
            user_id = int(parts[2])
            chat_id = int(update.effective_chat.id)
        except Exception:
            await q.answer('Datos inválidos para validar.', show_alert=True)
            raise _V221Stop
        ok, msg = await _v221_force_validate_user(context, chat_id, user_id, actor_id, update.effective_user.mention_html())
        try:
            target_mention = f'<a href="tg://user?id={int(user_id)}">{h(_v221_record_for_user(chat_id, user_id).get("name") or user_id)}</a>'
            await q.edit_message_text(
                f'✅ <b>Validación forzada</b>\n\nUsuario: {target_mention}\nAdmin: {update.effective_user.mention_html()}\n\n{h(msg)}',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        await q.answer(('✅ ' if ok else '❌ ') + msg[:180], show_alert=not ok)
        raise _V221Stop


async def _v221_force_validate_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return


    try:
        if update.effective_chat and update.effective_chat.type == 'private':
            if len(context.args or []) < 2:
                await update.message.reply_html('Uso en privado: <code>/forzarvalidar CHAT_ID USER_ID</code>')
                return
            chat_id = int(context.args[0]); user_id = int(context.args[1])
        else:
            chat_id = int(update.effective_chat.id)
            if update.message.reply_to_message and update.message.reply_to_message.from_user:
                user_id = int(update.message.reply_to_message.from_user.id)
            elif context.args:
                user_id = int(context.args[0])
            else:
                await update.message.reply_html('Uso: responde al usuario con <code>/forzarvalidar</code> o escribe <code>/forzarvalidar USER_ID</code>.')
                return
    except Exception:
        await update.message.reply_text('No pude leer CHAT_ID/USER_ID. Revisa el formato.')
        return

    ok, msg = await _v221_force_validate_user(context, chat_id, user_id, int(update.effective_user.id), update.effective_user.mention_html())
    if ok:
        await update.message.reply_html(f'✅ <b>Validación forzada aplicada</b>\n\nUsuario: <code>{user_id}</code>\nGrupo: <code>{chat_id}</code>\n{h(msg)}')
    else:
        await update.message.reply_html(f'❌ <b>No pude forzar validación</b>\n\n{h(msg)}')


async def _v221_validacion_diag(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:

    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await _v221_can_force_validate(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo dueño/admin puede usar este diagnóstico.')
        return
    bot_user = await context.bot.get_me()
    try:
        bm = await context.bot.get_chat_member(chat_id, bot_user.id)
    except Exception as e:
        await update.message.reply_text('No pude leer permisos del bot: ' + str(e))
        return
    st = get_state(chat_id)
    pending = [(uid, r) for uid, r in (st.validation_users or {}).items() if r.get('status') in ('answering', 'pending_admin', 'timeout', 'rejected')]
    lines = [
        '🧪 <b>Diagnóstico validación V221</b>', '',
        f'Grupo: <code>{chat_id}</code>',
        f'Versión: <b>{h(BOT_VERSION)}</b>',
        f'Tu permiso para forzar validar: <b>{bool_label(await _v221_can_force_validate(context, chat_id, int(update.effective_user.id)))}</b>',
        f'Pendientes/atascados registrados: <b>{len(pending)}</b>', '',
        f'Bot status: <b>{h(getattr(bm, "status", ""))}</b>',
        f'Puede restringir/banear: <b>{bool_label(getattr(bm, "can_restrict_members", False) or getattr(bm, "status", "") == "creator")}</b>',
        f'Puede borrar: <b>{bool_label(getattr(bm, "can_delete_messages", False) or getattr(bm, "status", "") == "creator")}</b>',
        '',
        'Comando de rescate:',
        '<code>/forzarvalidar</code> respondiendo al usuario',
        '<code>/forzarvalidar USER_ID</code>',
    ]
    if pending:
        lines.append('\nUsuarios detectados:')
        for uid, r in pending[:10]:
            lines.append(f'• <code>{h(uid)}</code> · {h(r.get("name") or "")}: <b>{h(r.get("status") or "")}</b>')
    await update.message.reply_html('\n'.join(lines))


_old_build_application_v221 = build_application

def build_application() -> Application:
    app = _old_build_application_v221()

    app.add_handler(CallbackQueryHandler(_v221_force_validation_router, pattern=r'^(members\|forceval\||cfg\|pendapprove\||val\|ok\|)'), group=-54000000000)
    app.add_handler(CommandHandler(['forzarvalidar', 'forcevalidar', 'validarforce', 'validar_forzado'], _v221_force_validate_command), group=-54000000000)
    app.add_handler(CommandHandler(['validiag', 'validaciondiag', 'validardiag', 'validaciondebug'], _v221_validacion_diag), group=-54000000001)
    logger.info('V221 cargado: forzar validación desde miembros, pendientes y comando')
    return app


