try:
    from telegram.ext import ApplicationHandlerStop as _V223Stop
except Exception:
    _V223Stop = Exception


async def _v223_group_admin_ids(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> set[int]:
    """Lista robusta de administradores reales del grupo."""
    ids: set[int] = set()
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for adm in admins or []:
            user = getattr(adm, 'user', None)
            if user and getattr(user, 'id', None):
                ids.add(int(user.id))
    except Exception:
        logger.exception('V223 no pudo leer get_chat_administrators en %s', chat_id)
    return ids


async def _v222_is_target_admin_or_owner(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> tuple[bool, str]:
    """V223: detecta OWNER_ID, ADMIN_IDS y, sobre todo, admin REAL del grupo."""
    uid = int(user_id)


    try:
        if uid in set(owner_ids()):
            return True, 'OWNER_ID'
    except Exception:
        pass


    try:
        if uid in set(ADMIN_IDS):
            return True, 'ADMIN_IDS'
    except Exception:
        pass


    try:
        member = await context.bot.get_chat_member(int(chat_id), uid)
        status = str(getattr(member, 'status', '') or '')
        if status in ('administrator', 'creator'):
            return True, f'admin_real_grupo:{status}'
    except Exception:

        logger.debug('V223 get_chat_member no confirmó admin %s en %s', uid, chat_id, exc_info=True)


    try:
        admin_ids = await _v223_group_admin_ids(context, int(chat_id))
        if uid in admin_ids:
            return True, 'admin_real_grupo:listado_admins'
    except Exception:
        pass

    return False, ''


async def _v223_clear_any_pending_user(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id: int,
    user_id: int,
    actor_id: int,
    *,
    reason: str = 'manual_clear_pending',
    send_public_message: bool = False,
) -> tuple[bool, str]:
    """Saca un usuario del estado pendiente interno aunque Telegram no deje tocar permisos.

    Esto está protegido por _v221_can_force_validate. Es el botón/comando de rescate
    para estados corruptos: marca validado, elimina de muted_users y no intenta ban/restrict
    si el usuario es admin real del grupo.
    """
    if not await _v221_can_force_validate(context, int(chat_id), int(actor_id)):
        return False, 'No tienes permiso para limpiar validaciones en ese grupo.'

    is_admin_target, why = await _v222_is_target_admin_or_owner(context, int(chat_id), int(user_id))
    record = _v222_mark_validated_clean(
        int(chat_id),
        int(user_id),
        reason=f'{reason}:{why or "usuario"}',
        actor_id=int(actor_id),
    )


    restriction_note = ''
    if not is_admin_target:
        try:
            await validation_unrestrict(context, int(chat_id), int(user_id))
            restriction_note = ' También se intentó quitar restricción real.'
        except Exception:
            restriction_note = ' Estado interno limpiado; Telegram no permitió quitar restricciones reales.'
    else:
        restriction_note = f' Era administrador real del grupo ({why}); no se toca con restrict_chat_member.'

    if send_public_message:
        try:
            target_mention = f'<a href="tg://user?id={int(user_id)}">{h(record.get("name") or user_id)}</a>'
            approved_text = str(cfg_value(chat_id, 'validation_approved_message', VALIDATION_APPROVED_MESSAGE))
            approved_text = approved_text.replace('{mention}', target_mention).replace('{name}', h(record.get('name', '')))
            await send_configured_profile_message(context.bot, int(chat_id), 'approved', approved_text)
        except Exception:
            pass

    return True, 'Usuario sacado de pendientes y marcado como validado.' + restriction_note


async def _v223_limpiar_pendiente_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Rescate manual: /limpiarpendiente USER_ID o respondiendo al usuario."""
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    actor_id = int(update.effective_user.id)
    target_id = 0
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        target_id = int(update.message.reply_to_message.from_user.id)
    elif context.args:
        try:
            target_id = int(context.args[0])
        except Exception:
            target_id = 0
    if not target_id:
        await update.message.reply_html(
            'Uso: responde al usuario con <code>/limpiarpendiente</code> o escribe <code>/limpiarpendiente USER_ID</code>.'
        )
        return
    ok, msg = await _v223_clear_any_pending_user(
        context,
        chat_id,
        target_id,
        actor_id,
        reason='limpiarpendiente_command',
        send_public_message=True,
    )
    await update.message.reply_html(('✅ ' if ok else '❌ ') + h(msg))


async def _v223_clean_admin_pending_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """V223: limpia admins reales de grupo aunque no estén en ADMIN_IDS."""
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    actor_id = int(update.effective_user.id)
    if not await _v221_can_force_validate(context, chat_id, actor_id):
        await update.message.reply_text('Solo dueño/admin puede limpiar validaciones atascadas.')
        return


    real_admins = await _v223_group_admin_ids(context, chat_id)
    st = get_state(chat_id)
    cleaned = []
    for uid_raw, rec in list((st.validation_users or {}).items()):
        try:
            uid = int(uid_raw)
        except Exception:
            continue
        status = str(rec.get('status') or '')
        if status not in ('answering', 'pending_admin', 'timeout', 'rejected', 'kicked_from_pending'):
            continue
        is_admin_target, why = await _v222_is_target_admin_or_owner(context, chat_id, uid)
        if is_admin_target or uid in real_admins:
            why = why or 'admin_real_grupo:listado_admins'
            _v222_mark_validated_clean(chat_id, uid, reason=f'clean_admin_real_grupo:{why}', actor_id=actor_id)
            cleaned.append((uid, why, rec.get('name') or ''))

    if cleaned:
        lines = ['✅ <b>Admins reales del grupo limpiados de pendientes</b>', '']
        for uid, why, name in cleaned[:50]:
            lines.append(f'• <code>{uid}</code> · {h(name)} · {h(why)}')
        if len(cleaned) > 50:
            lines.append(f'… y {len(cleaned)-50} más')
        await update.message.reply_html('\n'.join(lines))
    else:
        await update.message.reply_html(
            '✅ No encontré administradores reales del grupo atascados en pendientes.\n\n'
            'Si quieres limpiar uno manualmente, responde a su mensaje con <code>/limpiarpendiente</code>.'
        )


