BOT_VERSION = 'V224-pendientes-limpios-arranque-final'

V224_PENDING_STATUSES = {'answering', 'pending_admin', 'timeout', 'rejected', 'kicked_from_pending'}


def _v224_pending_clean_enabled() -> bool:
    return os.getenv('V224_CLEAN_PENDING_ON_STARTUP', 'true').strip().lower() in ('1', 'true', 'yes', 'on', 'si', 'sí')


def _v224_clean_pending_records_for_chat(chat_id: int, *, force: bool = False) -> tuple[int, list[int]]:
    """Marca como validados internos los pendientes atascados y los saca de listados.

    Es conservador con datos: no borra member_activity ni entry_log.
    Sólo toca validation_users y muted_users de usuarios que estaban pendientes.
    """
    state = get_state(int(chat_id))
    cfg = admin_cfg(int(chat_id)) if 'admin_cfg' in globals() else state.admin_config
    if not force and cfg.get('v224_pending_cleaned_once'):
        return 0, []
    cleaned: list[int] = []
    validation_users = getattr(state, 'validation_users', {}) or {}
    muted_users = getattr(state, 'muted_users', {}) or {}
    for uid_raw, rec in list(validation_users.items()):
        try:
            uid = int(uid_raw)
        except Exception:
            continue
        status = str((rec or {}).get('status') or '')
        if status not in V224_PENDING_STATUSES:
            continue
        if not isinstance(rec, dict):
            rec = {}
        rec['status'] = 'validated'
        rec['validated_by'] = 'V224_AUTO_CLEAN'
        rec['validated_ts'] = int(__import__('time').time())
        rec['v224_cleaned'] = True
        rec['v224_previous_status'] = status
        validation_users[str(uid)] = rec
        muted_users.pop(str(uid), None)
        cleaned.append(uid)
    state.validation_users = validation_users
    state.muted_users = muted_users
    cfg['v224_pending_cleaned_once'] = True
    cfg['v224_pending_cleaned_count'] = int(cfg.get('v224_pending_cleaned_count') or 0) + len(cleaned)
    cfg['v224_pending_cleaned_last_ts'] = int(__import__('time').time())
    save_all_states()
    return len(cleaned), cleaned


async def _v224_unrestrict_cleaned_users(bot, chat_id: int, user_ids: list[int]) -> int:
    ok = 0
    for uid in user_ids:
        try:
            await bot.restrict_chat_member(chat_id=int(chat_id), user_id=int(uid), permissions=ChatPermissions.all_permissions())
            ok += 1
            await asyncio.sleep(0.15)
        except Exception:

            pass
    return ok


_old_post_init_v224 = None

async def _v224_post_init(application: Application) -> None:
    global _old_post_init_v224
    if callable(_old_post_init_v224):
        try:
            await _old_post_init_v224(application)
        except Exception:
            logger.exception('V224: post_init anterior falló')
    if not _v224_pending_clean_enabled():
        logger.info('V224: limpieza de pendientes desactivada por variable')
        return
    try:
        load_all_states()
        total = 0
        total_unrestricted = 0
        for cid in list(STATE_CACHE.keys()):
            cleaned_count, users = _v224_clean_pending_records_for_chat(int(cid), force=False)
            total += cleaned_count
            if users:
                total_unrestricted += await _v224_unrestrict_cleaned_users(application.bot, int(cid), users)
        if total:
            logger.warning('V224: limpiados %s pendientes atascados; desrestringidos %s', total, total_unrestricted)
    except Exception:
        logger.exception('V224: limpieza automática de pendientes falló')


async def _v224_clean_all_pending_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    uid = int(update.effective_user.id)

    chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    allowed = False
    try:
        if 'is_owner_user' in globals() and is_owner_user(uid):
            allowed = True
        elif uid in ADMIN_IDS:
            allowed = True
        elif chat_id and await is_admin(context, chat_id, uid):
            allowed = True
    except Exception:
        pass
    if not allowed:
        await update.message.reply_text('Solo dueño/admin puede limpiar pendientes.')
        return
    targets = []
    if update.effective_chat and update.effective_chat.type != 'private':
        targets = [chat_id]
    else:
        targets = list(STATE_CACHE.keys())
    total = 0
    total_unrestricted = 0
    details = []
    for cid in targets:
        count, users = _v224_clean_pending_records_for_chat(int(cid), force=True)
        total += count
        if users:
            total_unrestricted += await _v224_unrestrict_cleaned_users(context.bot, int(cid), users)
        details.append(f'<code>{int(cid)}</code>: {count}')
    await update.message.reply_html(
        '✅ <b>Pendientes limpiados por V224</b>\n\n'
        f'Registros sacados de pendientes: <b>{total}</b>\n'
        f'Intentos de quitar restricciones correctos: <b>{total_unrestricted}</b>\n\n'
        + '\n'.join(details[:30])
    )


async def _v224_validation_diag(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    st = get_state(chat_id)
    pending = []
    for uid_raw, rec in list((st.validation_users or {}).items()):
        if str((rec or {}).get('status') or '') in V224_PENDING_STATUSES:
            pending.append((uid_raw, rec))
    cfg = admin_cfg(chat_id)
    lines = [
        '🧪 <b>Diagnóstico validación V224</b>', '',
        f'Grupo: <code>{chat_id}</code>',
        f'Versión activa: <b>{h(BOT_VERSION)}</b>',
        f'Pendientes reales ahora: <b>{len(pending)}</b>',
        f'Limpieza automática al arrancar: <b>{bool_label(_v224_pending_clean_enabled())}</b>',
        f'Limpieza hecha una vez en este grupo: <b>{bool_label(cfg.get("v224_pending_cleaned_once", False))}</b>',
        f'Total limpiados por V224 en este grupo: <b>{int(cfg.get("v224_pending_cleaned_count") or 0)}</b>', '',
        'Comando rescate:',
        '<code>/limpiartodospendientes</code>',
    ]
    if pending:
        lines.append('\nPendientes encontrados:')
        for uid_raw, rec in pending[:30]:
            lines.append(f'• <code>{h(uid_raw)}</code> · {h((rec or {}).get("name") or "")} · {h((rec or {}).get("status") or "")}')
    await update.message.reply_html('\n'.join(lines))


_old_build_application_v224 = build_application

def build_application() -> Application:
    global _old_post_init_v224
    app = _old_build_application_v224()
    _old_post_init_v224 = getattr(app, 'post_init', None)
    app.post_init = _v224_post_init
    app.add_handler(CommandHandler(['limpiartodospendientes', 'limpiarpendientes', 'resetpendientes'], _v224_clean_all_pending_command), group=-57000000000)
    app.add_handler(CommandHandler(['validardiag', 'validaciondiag', 'validiag', 'validaciondebug'], _v224_validation_diag), group=-57000000001)
    logger.info('V224 cargado: arranque final correcto + pendientes limpios')
    return app


