def _v225_permissions_markup(chat_id: int) -> InlineKeyboardMarkup:
    pc = _v225_perm_cfg(chat_id)
    rows: List[List[InlineKeyboardButton]] = []
    for scope, info in V225_PERMISSION_SCOPES.items():
        mode = pc.get(scope, str(info.get('default') or 'admins_grupo'))
        rows.append([InlineKeyboardButton(f'{info["label"]}: {V225_PERMISSION_LABELS.get(mode, mode)}', callback_data=f'perm225|cycle|{chat_id}|{scope}')])
    rows.append([InlineKeyboardButton('🔄 Sincronizar todo', callback_data=f'perm225|sync|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v225_permissions_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('perm225|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V225Stop
    if not ('is_owner_id' in globals() and is_owner_id(q.from_user.id)):
        await q.answer('Solo el dueño puede cambiar permisos globales.', show_alert=True)
        raise _V225Stop
    if action == 'cycle' and len(parts) >= 4:
        scope = parts[3]
        current = _v225_perm_cfg(chat_id).get(scope, V225_PERMISSION_SCOPES.get(scope, {}).get('default','admins_grupo'))
        _v225_set_perm(chat_id, scope, _v225_next_perm_mode(current))
        await q.answer('Permiso actualizado y sincronizado ✅')
    elif action == 'sync':
        _v225_perm_cfg(chat_id)
        save_all_states()
        await q.answer('Permisos sincronizados ✅')
    await q.edit_message_text(_v225_permissions_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v225_permissions_markup(chat_id))
    raise _V225Stop


