def _v225_ensure_blocks(chat_id: int) -> None:
    try:
        if 'ADMIN_PRIVATE_BLOCKS' in globals():
            existing = {k for k, _ in ADMIN_PRIVATE_BLOCKS}
            for key, label in [
                ('permissions','🔐 Permisos'), ('all_controls','🧰 Todos los controles'), ('botcommands','🤖 BotCommands'),
                ('security','🛡 Seguridad / Grupos'), ('members','👥 Miembros'), ('polls','📊 Encuestas')
            ]:
                if key not in existing:
                    ADMIN_PRIVATE_BLOCKS.append((key, label)); existing.add(key)
            try:
                ADMIN_PRIVATE_BLOCK_IDS.update({k for k,_ in ADMIN_PRIVATE_BLOCKS})
            except Exception:
                pass
        pcfg = _v171_panel_cfg(chat_id)
        blocks = pcfg.setdefault('blocks', [])

        if not any(isinstance(b, dict) and b.get('id') == 'configuracion' for b in blocks):
            blocks.append({'id':'configuracion','title':'⚙️ Configuración y seguridad','items':['permissions','all_controls','botcommands','security','members','panel_settings','quick_summary','backup','restore']})
        else:
            for b in blocks:
                if isinstance(b, dict) and b.get('id') == 'configuracion':
                    for it in ['permissions','all_controls','botcommands','security','members','panel_settings','quick_summary','backup','restore']:
                        if it not in b.setdefault('items', []):
                            b['items'].append(it)
        save_all_states()
    except Exception:
        logger.exception('V225 no pudo asegurar bloques')


