async def _v225_cfg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action == 'saveclose225':
        try:
            save_all_states()
            await q.answer('Guardado ✅')
            await q.message.delete()
        except Exception:
            try:
                await q.edit_message_text('✅ Guardado y cerrado.')
            except Exception:
                pass
        raise _V225Stop


