def _v226_custom_block_markup(chat_id: int, block_id: str) -> InlineKeyboardMarkup:
    block = _v226_find_panel_block(chat_id, block_id)
    rows: List[List[InlineKeyboardButton]] = []
    if block:
        items = [i for i in (block.get('items') or []) if i in _v171_available_panel_items()]
        pair: List[InlineKeyboardButton] = []
        for key in items:
            pair.append(_v171_item_button(chat_id, key))
            if len(pair) == 2:
                rows.append(pair); pair = []
        if pair:
            rows.append(pair)
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v226_panel_block_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg225|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V226Stop
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo administradores autorizados.', show_alert=True)
        raise _V226Stop
    if action == 'block' and len(parts) >= 4:
        block_id = parts[3]
        await q.answer()
        await q.edit_message_text(
            _v226_custom_block_text(chat_id, block_id),
            parse_mode=ParseMode.HTML,
            reply_markup=_v226_custom_block_markup(chat_id, block_id),
        )
        raise _V226Stop
    await q.answer('Acción no reconocida.', show_alert=True)
    raise _V226Stop


async def _v226_cfg_block_fallback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|block|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 4:
        return
    try:
        chat_id = int(parts[2])
    except Exception:
        return
    block_id = parts[3]
    if block_id in ADMIN_PRIVATE_BLOCK_IDS:
        return
    if _v226_find_panel_block(chat_id, block_id) is None:
        return
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo administradores autorizados.', show_alert=True)
        raise _V226Stop
    await q.answer()
    await q.edit_message_text(
        _v226_custom_block_text(chat_id, block_id),
        parse_mode=ParseMode.HTML,
        reply_markup=_v226_custom_block_markup(chat_id, block_id),
    )
    raise _V226Stop


_old_build_application_v226 = build_application

def build_application() -> Application:
    app = _old_build_application_v226()
    app.add_handler(CallbackQueryHandler(_v226_panel_block_router, pattern=r'^cfg225\|'), group=-59000000000)
    app.add_handler(CallbackQueryHandler(_v226_cfg_block_fallback_router, pattern=r'^cfg\|block\|'), group=-59000000001)
    logger.info('V226 cargado: los bloques del panel ya abren correctamente')
    return app


