def _v227_panel_layout(chat_id: int) -> Dict[str, Any]:
    """Configuración visual del panel privado.

    panel_block_mode:
      - accordion: sólo se ven los títulos; al pulsar se entra al bloque.
      - expanded: se ven título y controles directamente en el panel principal.
    panel_block_cols:
      - 1 o 2 columnas para controles dentro de cada bloque.
    """
    try:
        pcfg = _v171_panel_cfg(chat_id)
        mode = str(pcfg.get('panel_block_mode') or pcfg.get('block_mode') or 'accordion').strip().lower()
        if mode not in ('accordion', 'expanded'):
            mode = 'accordion'
        try:
            cols = int(pcfg.get('panel_block_cols') or pcfg.get('block_cols') or 2)
        except Exception:
            cols = 2
        cols = 1 if cols <= 1 else 2
        pcfg['panel_block_mode'] = mode
        pcfg['panel_block_cols'] = cols
        return {'mode': mode, 'cols': cols}
    except Exception:
        logger.exception('V227 no pudo leer layout del panel')
        return {'mode': 'accordion', 'cols': 2}


def _v227_set_panel_layout(chat_id: int, *, mode: Optional[str] = None, cols: Optional[int] = None) -> None:
    pcfg = _v171_panel_cfg(chat_id)
    if mode is not None:
        mode = str(mode).strip().lower()
        if mode in ('accordion', 'expanded'):
            pcfg['panel_block_mode'] = mode
    if cols is not None:
        try:
            c = int(cols)
        except Exception:
            c = 2
        pcfg['panel_block_cols'] = 1 if c <= 1 else 2
    save_all_states()


def _v227_mode_label(chat_id: int) -> str:
    layout = _v227_panel_layout(chat_id)
    return '📂 Entrar en bloques' if layout['mode'] == 'accordion' else '📋 Bloques desplegados'


def _v227_cols_label(chat_id: int) -> str:
    return f"{_v227_panel_layout(chat_id)['cols']} columna{'s' if _v227_panel_layout(chat_id)['cols'] != 1 else ''}"


def _v227_item_rows(chat_id: int, items: List[str], cols: Optional[int] = None) -> List[List[InlineKeyboardButton]]:
    defs = _v171_available_panel_items()
    clean_items = [i for i in list(items or []) if i in defs]
    c = cols if cols in (1, 2) else int(_v227_panel_layout(chat_id)['cols'])
    rows: List[List[InlineKeyboardButton]] = []
    pair: List[InlineKeyboardButton] = []
    for key in clean_items:
        pair.append(_v171_item_button(chat_id, key))
        if len(pair) >= c:
            rows.append(pair)
            pair = []
    if pair:
        rows.append(pair)
    return rows


