async def _v227_panel_layout_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panelcfg|layout227|'):
        return
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V227Stop
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V227Stop
    action = parts[3] if len(parts) > 3 else ''
    layout = _v227_panel_layout(chat_id)
    if action == 'toggle_mode':
        new_mode = 'expanded' if layout['mode'] == 'accordion' else 'accordion'
        _v227_set_panel_layout(chat_id, mode=new_mode)
        await q.answer('Modo visual actualizado')
    elif action == 'toggle_cols':
        new_cols = 1 if int(layout['cols']) == 2 else 2
        _v227_set_panel_layout(chat_id, cols=new_cols)
        await q.answer('Columnas actualizadas')
    else:
        await q.answer('Acción no válida', show_alert=True)
        raise _V227Stop
    await q.edit_message_text(_v171_panelcfg_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v171_panelcfg_markup(chat_id))
    raise _V227Stop


async def _v227_noop_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg227|noop|'):
        return
    await q.answer('Bloque desplegado: usa los botones de debajo.')
    raise _V227Stop


