def _v228_clean_summary_text(text: str) -> str:
    """Quita la línea informativa redundante del resumen principal."""
    bad_lines = [
        'Configura el panel desde <b>⚙️ Configuración del panel</b>.',
        'Configura el panel desde ⚙️ Configuración del panel.',
    ]
    result = str(text or '')
    for line in bad_lines:
        result = result.replace('\n' + line, '')
        result = result.replace(line, '')

    while '\n\n\n' in result:
        result = result.replace('\n\n\n', '\n\n')
    return result.strip()


