_old_build_application_v228 = build_application

def build_application() -> Application:
    app = _old_build_application_v228()

    app.add_handler(CallbackQueryHandler(_v228_panel_blocks_router, pattern=r'^panelcfg\|blocks\|'), group=-61000000000)
