def _v229_all_panel_keys(chat_id: int) -> List[str]:
    keys: List[str] = []
    try:
        if '_v177_all_keys' in globals() and callable(_v177_all_keys):
            keys.extend([str(k) for k in _v177_all_keys(chat_id)])
    except Exception:
        pass
    try:
        keys.extend([str(k) for k in _v171_available_panel_items().keys()])
    except Exception:
        pass
    try:
        pcfg = _v171_panel_cfg(chat_id)
        for b in pcfg.get('blocks', []) or []:
            for k in b.get('items', []) or []:
                keys.append(str(k))
        for k in pcfg.get('loose_big', []) or []:
            keys.append(str(k))
        for k in pcfg.get('loose_small', []) or []:
            keys.append(str(k))
    except Exception:
        pass
    out: List[str] = []
    seen: set[str] = set()
    hidden = set()
    try:
        hidden = set(_v171_panel_cfg(chat_id).get('hidden_items') or [])
    except Exception:
        hidden = set()
    for k in keys:
        if not k or k in seen or k in hidden or k in {'change_group', 'save', 'close', 'reload'}:
            continue
        try:
            if '_v178_known_key' in globals() and callable(_v178_known_key) and not _v178_known_key(chat_id, k):

                if k not in _v171_available_panel_items():
                    continue
        except Exception:
            pass
        seen.add(k)
        out.append(k)
    return out


def _v229_label(chat_id: int, key: str) -> str:
    try:
        if '_v178_label' in globals() and callable(_v178_label):
            return str(_v178_label(chat_id, key))[:45]
    except Exception:
        pass
    try:
        return str(_v171_available_panel_items().get(key, {}).get('label') or key)[:45]
    except Exception:
        return str(key)[:45]


def _v229_block_text(chat_id: int, bi: int, page: int = 0) -> str:
    pcfg = _v171_panel_cfg(chat_id)
    blocks = pcfg.get('blocks', []) or []
    if not (0 <= int(bi) < len(blocks)):
        return '<b>🧩 Bloque no encontrado</b>'
    b = blocks[int(bi)]
    title = str(b.get('title') or 'Bloque').strip() or 'Bloque'
    current = list(b.get('items', []) or [])
    all_keys = _v229_all_panel_keys(chat_id)
    total_pages = max(1, ((len(all_keys)-1)//V229_BLOCK_ITEMS_PER_PAGE)+1)
    page = max(0, min(int(page or 0), total_pages-1))
    lines = [
        f'<b>🧩 {h(title)}</b>',
        '',
        f'Controles dentro: <b>{len(current)}</b>',
        f'Página de controles: <b>{page+1}/{total_pages}</b>',
        '',
        '✅ = está dentro de este bloque. Pulsa para quitarlo.',
        '⬜ = está fuera. Pulsa para meterlo aquí.',
        '',
        '<b>Controles actuales:</b>'
    ]
    if current:
        for k in current[:20]:
            lines.append('• ' + h(_v229_label(chat_id, str(k))))
        if len(current) > 20:
            lines.append(f'… y {len(current)-20} más')
    else:
        lines.append('Vacío.')
    return '\n'.join(lines)


def _v229_block_markup(chat_id: int, bi: int, page: int = 0) -> InlineKeyboardMarkup:
    pcfg = _v171_panel_cfg(chat_id)
    blocks = pcfg.get('blocks', []) or []
    rows: List[List[InlineKeyboardButton]] = []
    if not (0 <= int(bi) < len(blocks)):
        return InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Bloques', callback_data=f'panelcfg229|blocks|{chat_id}')]])
    current = set(blocks[int(bi)].get('items', []) or [])
    all_keys = _v229_all_panel_keys(chat_id)
    total_pages = max(1, ((len(all_keys)-1)//V229_BLOCK_ITEMS_PER_PAGE)+1)
    page = max(0, min(int(page or 0), total_pages-1))
    start = page * V229_BLOCK_ITEMS_PER_PAGE
    chunk = all_keys[start:start+V229_BLOCK_ITEMS_PER_PAGE]
    layout = _v227_panel_layout(chat_id) if '_v227_panel_layout' in globals() else {'cols': 2}
    cols = 1 if int(layout.get('cols', 2)) == 1 else 2
    rows.append([InlineKeyboardButton('✏️ Cambiar nombre del bloque', callback_data=f'panelcfg|renameblock|{chat_id}|{bi}')])
    line: List[InlineKeyboardButton] = []
    for key in chunk:
        mark = '✅' if key in current else '⬜'
        line.append(InlineKeyboardButton(f'{mark} {_v229_label(chat_id, key)}', callback_data=f'panelcfg229|toggle|{chat_id}|{bi}|{page}|{key}'))
        if len(line) == cols:
            rows.append(line); line = []
    if line:
        rows.append(line)
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'panelcfg229|block|{chat_id}|{bi}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{total_pages}', callback_data=f'panelcfg229|noop|{chat_id}'))
    if page < total_pages-1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'panelcfg229|block|{chat_id}|{bi}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([
        InlineKeyboardButton('⬆️ Subir bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|up'),
        InlineKeyboardButton('⬇️ Bajar bloque', callback_data=f'panelcfg|moveblock|{chat_id}|{bi}|down'),
    ])
    rows.append([InlineKeyboardButton('🗑 Quitar bloque', callback_data=f'panelcfg|delblock|{chat_id}|{bi}')])
    rows.append([InlineKeyboardButton('🔙 Bloques', callback_data=f'panelcfg229|blocks|{chat_id}')])
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v229_blocks_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith(('panelcfg229|', 'panelcfg228|block|', 'panelcfg|block|', 'panelcfg|blocks|')):
        return
    data = q.data or ''
    parts = data.split('|')

    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V229Stop
    try:
        if data.startswith('panelcfg|blocks|'):
            chat_id = int(parts[2])
            await q.answer()
            await _v229_safe_edit(q, _v229_panel_blocks_text(chat_id), _v229_panel_blocks_markup(chat_id))
            raise _V229Stop
        if data.startswith('panelcfg228|block|') or data.startswith('panelcfg|block|'):

            chat_id = int(parts[2]); bi = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
            await q.answer()
            await _v229_safe_edit(q, _v229_block_text(chat_id, bi, page), _v229_block_markup(chat_id, bi, page))
            raise _V229Stop
        action = parts[1] if len(parts) > 1 else ''
        if action == 'blocks':
            chat_id = int(parts[2])
            await q.answer()
            await _v229_safe_edit(q, _v229_panel_blocks_text(chat_id), _v229_panel_blocks_markup(chat_id))
            raise _V229Stop
        if action == 'layout':
            chat_id = int(parts[2]); what = parts[3] if len(parts) > 3 else ''
            layout = _v227_panel_layout(chat_id) if '_v227_panel_layout' in globals() else {'mode':'accordion','cols':2}
            if what == 'toggle_mode':
                _v227_set_panel_layout(chat_id, mode=('expanded' if layout.get('mode') == 'accordion' else 'accordion'))
                await q.answer('Modo actualizado')
            elif what == 'toggle_cols':
                _v227_set_panel_layout(chat_id, cols=(1 if int(layout.get('cols', 2)) == 2 else 2))
                await q.answer('Columnas actualizadas')
            else:
                await q.answer()
            await _v229_safe_edit(q, _v229_panel_blocks_text(chat_id), _v229_panel_blocks_markup(chat_id))
            raise _V229Stop
        if action == 'block':
            chat_id = int(parts[2]); bi = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
            await q.answer()
            await _v229_safe_edit(q, _v229_block_text(chat_id, bi, page), _v229_block_markup(chat_id, bi, page))
            raise _V229Stop
        if action == 'toggle':
            chat_id = int(parts[2]); bi = int(parts[3]); page = int(parts[4]); key = '|'.join(parts[5:])
            pcfg = _v171_panel_cfg(chat_id)
            blocks = pcfg.get('blocks', []) or []
            if not (0 <= bi < len(blocks)):
                await q.answer('Bloque no encontrado', show_alert=True)
                raise _V229Stop
            items = list(blocks[bi].get('items', []) or [])
            if key in items:
                blocks[bi]['items'] = [x for x in items if x != key]
                await q.answer('Quitado del bloque ✅')
            else:

                for b in blocks:
                    if isinstance(b, dict):
                        b['items'] = [x for x in (b.get('items', []) or []) if x != key]
                blocks[bi].setdefault('items', []).append(key)
                await q.answer('Añadido al bloque ✅')
            save_all_states()
            await _v229_safe_edit(q, _v229_block_text(chat_id, bi, page), _v229_block_markup(chat_id, bi, page))
            raise _V229Stop
        if action == 'noop':
            await q.answer()
            raise _V229Stop
    except _V229Stop:
        raise
    except Exception as e:
        logger.exception('V229 error en bloques del panel: %s', data)
        try:
            await q.answer('Error abriendo bloque. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V229Stop


_old_build_application_v229 = build_application

def build_application() -> Application:
    app = _old_build_application_v229()

    app.add_handler(CallbackQueryHandler(_v229_blocks_router, pattern=r'^(panelcfg229\||panelcfg228\|block\||panelcfg\|block\||panelcfg\|blocks\|)'), group=-62000000000)
    logger.info('V229 cargado: bloques del panel con entrada estable y paginada')
    return app


