def _v230_awards_cfg(chat_id: int) -> Dict[str, Any]:
    for fn_name in ("_v207_awards_cfg", "_v205_awards_cfg", "_v168_awards_cfg"):
        fn = globals().get(fn_name)
        if callable(fn):
            try:
                cfg = fn(int(chat_id))
                if isinstance(cfg, dict):
                    return cfg
            except Exception:
                pass
    try:
        return admin_cfg(int(chat_id))
    except Exception:
        return {}


def _v230_awards_enabled(chat_id: int) -> bool:
    cfg = _v230_awards_cfg(chat_id)
    return bool(cfg.get("awards_enabled", cfg.get("social_awards_enabled", False)))


def _v230_awards_short(chat_id: int) -> str:
    cfg = _v230_awards_cfg(chat_id)
    enabled = _v230_awards_enabled(chat_id)
    daily = bool(cfg.get("awards_daily_enabled", True)) if enabled else False
    weekly = bool(cfg.get("awards_weekly_enabled", False)) if enabled else False
    if not enabled:
        return "🏆 Premios: <b>OFF ❌</b>"
    extra = []
    if daily:
        extra.append("D")
    if weekly:
        extra.append("S")
    suffix = f" ({'/'.join(extra)})" if extra else ""
    return f"🏆 Premios: <b>ON ✅</b>{h(suffix)}"


