def _v230_summary_fields(chat_id: int) -> List[str]:
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        fields = [str(x) for x in (pcfg.get('top_fields') or []) if str(x)]
    except Exception:
        fields = []
    if not fields:
        fields = [
            'validation_status', 'daily_phrase_status', 'awards_status', 'recurrentes',
            'dj', 'hot', 'pending', 'ia', 'security', 'members', 'service_cleanup', 'version'
        ]

    for must in ('validation_status', 'daily_phrase_status', 'awards_status'):
        if must not in fields:
            fields.insert(0, must)

    out = []
    seen = set()
    for k in fields:
        if k not in seen:
            seen.add(k); out.append(k)
    return out


def _v230_two_col_summary(chat_id: int) -> List[str]:
    items = []
    for key in _v230_summary_fields(chat_id):
        val = _v230_short_field(int(chat_id), key)
        if val:
            items.append(val)
    lines = []
    for i in range(0, len(items), 2):
        left = items[i]
        right = items[i+1] if i+1 < len(items) else ""
        if right:
            lines.append(left + "  ·  " + right)
        else:
            lines.append(left)
    return lines


