def _v230_direct_cfg(chat_id: int) -> List[str]:
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        raw = pcfg.setdefault('direct_buttons_v230', [])
        if not isinstance(raw, list):
            raw = []
            pcfg['direct_buttons_v230'] = raw

        allowed = set(_v230_direct_keys(int(chat_id)))
        clean = []
        for k in raw:
            k = str(k)
            if k in allowed and k not in clean:
                clean.append(k)
        if clean != raw:
            pcfg['direct_buttons_v230'] = clean
            save_all_states()
        return clean
    except Exception:
        return []


def _v230_direct_keys(chat_id: int) -> List[str]:
    keys = []
    try:
        if '_v229_all_panel_keys' in globals() and callable(_v229_all_panel_keys):
            keys = list(_v229_all_panel_keys(int(chat_id)))
        else:
            keys = list((_v171_available_panel_items() or {}).keys())
    except Exception:
        keys = list((_v171_available_panel_items() or {}).keys())
    banned = {'change_group', 'save', 'close', 'reload', 'checkbot'}
    out = []
    seen = set()
    for k in keys:
        k = str(k)
        if not k or k in banned or k in seen:
            continue
        seen.add(k)
        out.append(k)
    return out


def _v230_direct_rows(chat_id: int) -> List[List[InlineKeyboardButton]]:
    keys = _v230_direct_cfg(int(chat_id))
    if not keys:
        return []
    cols = 2
    try:
        cols = int((_v227_panel_layout(int(chat_id)) if '_v227_panel_layout' in globals() else {}).get('cols', 2))
        cols = 1 if cols == 1 else 2
    except Exception:
        cols = 2
    rows: List[List[InlineKeyboardButton]] = []
    line: List[InlineKeyboardButton] = []
    for k in keys:
        try:
            line.append(_v171_item_button(int(chat_id), k))
        except Exception:
            d = _v171_available_panel_items().get(k, {'label': k, 'cb': f'cfg|block|{{chat_id}}|{k}'})
            line.append(InlineKeyboardButton(str(d.get('label') or k), callback_data=str(d.get('cb') or '').format(chat_id=int(chat_id))))
        if len(line) == cols:
            rows.append(line); line = []
    if line:
        rows.append(line)
    return rows


