def _v230_direct_text(chat_id: int, page: int = 0) -> str:
    direct = _v230_direct_cfg(int(chat_id))
    keys = _v230_direct_keys(int(chat_id))
    total_pages = max(1, ((len(keys)-1)//V230_DIRECT_PER_PAGE)+1)
    page = max(0, min(int(page or 0), total_pages-1))
    lines = [
        '<b>⚡ Botones directos bajo los bloques</b>',
        '',
        'Estos botones se muestran en el panel principal debajo de los separadores/bloques y justo encima de <b>GRUPO ACTUAL</b>.',
        '',
        f'Activos: <b>{len(direct)}</b> · Página <b>{page+1}/{total_pages}</b>',
        '',
        '✅ = visible como botón directo. ⬜ = no visible.',
    ]
    return '\n'.join(lines)


def _v230_direct_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    keys = _v230_direct_keys(int(chat_id))
    direct = set(_v230_direct_cfg(int(chat_id)))
    total_pages = max(1, ((len(keys)-1)//V230_DIRECT_PER_PAGE)+1)
    page = max(0, min(int(page or 0), total_pages-1))
    chunk = keys[page*V230_DIRECT_PER_PAGE:(page+1)*V230_DIRECT_PER_PAGE]
    rows: List[List[InlineKeyboardButton]] = []
    line: List[InlineKeyboardButton] = []
    for k in chunk:
        mark = '✅' if k in direct else '⬜'
        label = _v229_label(int(chat_id), k) if '_v229_label' in globals() else k
        line.append(InlineKeyboardButton(f'{mark} {label}', callback_data=f'direct230|toggle|{int(chat_id)}|{page}|{k}'))
        if len(line) == 2:
            rows.append(line); line=[]
    if line:
        rows.append(line)
    nav=[]
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'direct230|menu|{int(chat_id)}|{page-1}'))
    nav.append(InlineKeyboardButton(f'{page+1}/{total_pages}', callback_data=f'direct230|noop|{int(chat_id)}'))
    if page < total_pages-1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'direct230|menu|{int(chat_id)}|{page+1}'))
    rows.append(nav)
    rows.append([InlineKeyboardButton('🧹 Quitar todos', callback_data=f'direct230|clear|{int(chat_id)}|{page}')])
    rows.append([InlineKeyboardButton('⚙️ Configuración del panel', callback_data=f'panelcfg|open|{int(chat_id)}')])
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)


async def _v230_direct_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('direct230|'):
        return
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V230Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else 'menu'
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V230Stop
    page = 0
    try:
        page = int(parts[3]) if len(parts) > 3 else 0
    except Exception:
        page = 0
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        direct = pcfg.setdefault('direct_buttons_v230', [])
        if not isinstance(direct, list):
            direct = []
            pcfg['direct_buttons_v230'] = direct
        if action == 'toggle' and len(parts) >= 5:
            key = '|'.join(parts[4:])
            if key in direct:
                pcfg['direct_buttons_v230'] = [x for x in direct if x != key]
                await q.answer('Quitado de directos')
            else:
                pcfg['direct_buttons_v230'] = direct + [key]
                await q.answer('Añadido a directos ✅')
            save_all_states()
        elif action == 'clear':
            pcfg['direct_buttons_v230'] = []
            save_all_states()
            await q.answer('Directos limpiados')
        elif action == 'noop':
            await q.answer()
            raise _V230Stop
        else:
            await q.answer()
        await q.edit_message_text(_v230_direct_text(int(chat_id), page), parse_mode=ParseMode.HTML, reply_markup=_v230_direct_markup(int(chat_id), page))
    except _V230Stop:
        raise
    except Exception:
        logger.exception('V230 direct router falló: %s', q.data)
        await q.answer('Error en botones directos. Mira logs.', show_alert=True)
    raise _V230Stop


