BOT_VERSION = "V231"

try:
    from telegram.ext import ApplicationHandlerStop as _V231Stop
except Exception:
    _V231Stop = Exception


def _v231_onoff(value: Any) -> str:
    return "ON" if bool(value) else "OFF"


def _v231_short_value(chat_id: int, key: str) -> str:
    """Valor muy corto para que el resumen no salte de línea."""
    st = get_state(int(chat_id))
    key = str(key or "")
    try:
        if key in ("validation", "validation_status"):
            return f"Val:{_v231_onoff(cfg_value(chat_id, 'validation_enabled', False))}"
        if key in ("daily_phrase", "daily_phrase_status"):
            return f"Fra:{_v231_onoff(cfg_value(chat_id, 'daily_phrase_enabled', False))}"
        if key in ("awards", "awards_status"):
            return f"Pre:{_v231_onoff(_v230_awards_enabled(chat_id) if '_v230_awards_enabled' in globals() else False)}"
        if key == "pending":
            return f"Pdt:{_v230_pending_count(chat_id) if '_v230_pending_count' in globals() else 0}"
        if key == "recurrentes":
            try:
                rows = recurring_list(int(chat_id))
                on = sum(1 for r in rows if bool(r.get('enabled', True)))
                return f"Rec:{on}/{len(rows)}"
            except Exception:
                return "Rec:0"
        if key == "dj":
            return f"DJ:{_v231_onoff(bool(st.dj_mode or st.panel_message_id or st.control_message_id))}"
        if key == "hot":
            return f"Hot:{_v231_onoff(cfg_value(chat_id, 'hot_auto_enabled', False))}"
        if key == "ia":
            try:
                if '_v170_ai_stats' in globals():
                    on, off = _v170_ai_stats(int(chat_id))
                    return f"IA:{on}"
                if '_ai_custom_commands' in globals():
                    return f"IA:{len(_ai_custom_commands(int(chat_id)))}"
            except Exception:
                pass
            return "IA:—"
        if key == "security":
            ok = _v219_group_authorized(chat_id) if '_v219_group_authorized' in globals() else True
            return f"Seg:{_v231_onoff(ok)}"
        if key == "members":
            return f"Miem:{len(st.member_activity or {})}"
        if key == "service_cleanup":
            return f"Serv:{_v231_onoff(cfg_value(chat_id, 'service_cleanup_enabled', False))}"
        if key == "polls":
            return "Enc:ON"
        if key == "backup":
            return f"Bkp:{_v231_onoff(STATE_PATH.exists())}"
        if key == "botcommands":
            return "Cmd:ON"
        if key == "tarot":
            try:
                cfg = _v129_tarot_cfg(chat_id) if '_v129_tarot_cfg' in globals() else {}
                return f"Tar:{_v231_onoff(cfg.get('tarot_enabled', True))}"
            except Exception:
                return "Tar:ON"
        if key == "version":
            return "Ver:V231"
        if key == "grupo":
            return "Grupo:OK"
    except Exception:
        logger.exception('V231 error calculando resumen corto %s', key)
    return ""


def _v231_summary_lines(chat_id: int) -> List[str]:
    fields = _v230_summary_fields(int(chat_id)) if '_v230_summary_fields' in globals() else [
        'validation_status','daily_phrase_status','awards_status','recurrentes','dj','hot','pending','ia','security','members','service_cleanup','version'
    ]

    priority = ['validation_status','daily_phrase_status','awards_status','pending','recurrentes','dj','hot','ia','security','members','service_cleanup','polls','backup','version']
    ordered = []
    for k in priority + list(fields):
        if k not in ordered:
            ordered.append(k)
    values = []
    for k in ordered:
        v = _v231_short_value(int(chat_id), k)
        if v and v not in values:
            values.append(v)

    lines = []
    width = 15
    for i in range(0, len(values), 2):
        left = values[i][:width]
        right = values[i+1][:width] if i+1 < len(values) else ""
        if right:
            lines.append(left.ljust(width) + right)
        else:
            lines.append(left)
    return lines


