def _v231_set_group_hidden(chat_id: int, hidden: bool) -> None:
    try:
        cfg_set(int(chat_id), 'hidden_from_group_selector_v231', bool(hidden))
    except Exception:
        st = get_state(int(chat_id))
        if not isinstance(st.admin_config, dict):
            st.admin_config = {}
        st.admin_config['hidden_from_group_selector_v231'] = bool(hidden)
        save_all_states()


def _v231_known_chats(include_hidden: bool = False) -> List[int]:
    try:
        chats = [int(x) for x in known_admin_chats_for_private()]
    except Exception:
        chats = sorted([int(x) for x in STATE_CACHE.keys()])
    out = []
    for cid in chats:
        if include_hidden or not _v231_group_hidden(cid):
            out.append(cid)
    return out


