def admin_private_chat_list_markup() -> InlineKeyboardMarkup:
    """Selector normal: oculta grupos marcados y permite quitarlos del listado."""
    try:
        rows: List[List[InlineKeyboardButton]] = []
        chats = _v231_known_chats(False)
        if not chats:
            rows.append([InlineKeyboardButton('No hay grupos visibles', callback_data='cfg231|noop')])
        for chat_id in chats:
            title = str(cfg_value(chat_id, 'chat_title', '') or get_chat_title(chat_id) or chat_id)
            rows.append([
                InlineKeyboardButton(f'⚙️ {truncated_button_title(title, 34)}', callback_data=f'cfg|open|{int(chat_id)}'),
                InlineKeyboardButton('🙈 Quitar', callback_data=f'cfg231|hide|{int(chat_id)}'),
            ])
        hidden = [cid for cid in _v231_known_chats(True) if _v231_group_hidden(cid)]
        if hidden:
            rows.append([InlineKeyboardButton(f'👁 Ver ocultos ({len(hidden)})', callback_data='cfg231|hidden')])
        rows.append([InlineKeyboardButton('🔄 Actualizar lista', callback_data='cfg|list')])
        return InlineKeyboardMarkup(rows)
    except Exception:
        logger.exception('V231 selector grupos falló; uso anterior')
        return _old_v231_admin_private_chat_list_markup()


def _v231_hidden_groups_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    hidden = [cid for cid in _v231_known_chats(True) if _v231_group_hidden(cid)]
    if not hidden:
        rows.append([InlineKeyboardButton('No hay grupos ocultos', callback_data='cfg231|noop')])
    for chat_id in hidden:
        title = str(cfg_value(chat_id, 'chat_title', '') or get_chat_title(chat_id) or chat_id)
        rows.append([
            InlineKeyboardButton(f'🙈 {truncated_button_title(title, 34)}', callback_data=f'cfg|open|{int(chat_id)}'),
            InlineKeyboardButton('↩️ Restaurar', callback_data=f'cfg231|show|{int(chat_id)}'),
        ])
    rows.append([InlineKeyboardButton('🔙 Volver selector', callback_data='cfg|list')])
    return InlineKeyboardMarkup(rows)


async def _v231_group_selector_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg231|'):
        return
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V231Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else 'noop'
    try:
        if action == 'noop':
            await q.answer()
            raise _V231Stop
        if action == 'hidden':
            await q.answer()
            await q.edit_message_text('<b>Grupos ocultos del selector</b>\n\nPuedes restaurarlos cuando quieras.', parse_mode=ParseMode.HTML, reply_markup=_v231_hidden_groups_markup())
            raise _V231Stop
        if action in ('hide','show') and len(parts) >= 3:
            chat_id = int(parts[2])
            _v231_set_group_hidden(chat_id, action == 'hide')
            await q.answer('Grupo ocultado del selector' if action == 'hide' else 'Grupo restaurado')
            if action == 'show':
                await q.edit_message_text('<b>Grupos ocultos del selector</b>\n\nPuedes restaurarlos cuando quieras.', parse_mode=ParseMode.HTML, reply_markup=_v231_hidden_groups_markup())
            else:
                await q.edit_message_text('<b>Elige el grupo que quieres configurar:</b>', parse_mode=ParseMode.HTML, reply_markup=admin_private_chat_list_markup())
            raise _V231Stop
        await q.answer('Acción no reconocida', show_alert=True)
    except _V231Stop:
        raise
    except Exception:
        logger.exception('V231 selector router falló: %s', q.data)
        await q.answer('Error actualizando selector', show_alert=True)
    raise _V231Stop


_old_v231_checkbot_text = _v219_checkbot_text if '_v219_checkbot_text' in globals() else None

def _v219_checkbot_text(chat_id: int) -> str:
    try:
        base = _old_v231_checkbot_text(int(chat_id)) if callable(_old_v231_checkbot_text) else ''
    except Exception:
        base = ''
    hidden = _v231_group_hidden(int(chat_id))
    extra = [
        '',
        '<b>🔎 Comprobación V231</b>',
        f'Versión actual: <b>{h(BOT_VERSION)}</b>',
        f'Selector grupo: <b>{"oculto" if hidden else "visible"}</b>',
        'Resumen rápido: <b>2 columnas alineadas</b>',
    ]
    return (base + '\n' if base else '') + '\n'.join(extra)


_old_build_application_v231 = build_application

def build_application() -> Application:
    app = _old_build_application_v231()
    app.add_handler(CallbackQueryHandler(_v231_group_selector_router, pattern=r'^cfg231\|'), group=-64000000000)
    logger.info('V231 cargado: resumen alineado y ocultar/restaurar grupos del selector')
    return app


