def _v232_default_summary_fields() -> List[str]:
    return [
        'validation_status', 'daily_phrase_status', 'awards_status', 'pending',
        'recurrentes', 'dj', 'hot', 'ia',
        'security', 'members', 'service_cleanup', 'polls',
        'backup', 'version'
    ]


def _v232_summary_fields(chat_id: int) -> List[str]:
    specs = _v232_summary_specs()
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        raw = pcfg.get('top_fields') or []
        if not isinstance(raw, list):
            raw = []
    except Exception:
        raw = []
    fields: List[str] = []
    for k in raw:
        k = str(k)
        if k in specs and k not in fields:
            fields.append(k)
    if not fields:
        fields = list(_v232_default_summary_fields())
    return fields


def _v232_set_summary_fields(chat_id: int, fields: List[str]) -> None:
    specs = _v232_summary_specs()
    clean: List[str] = []
    for k in fields:
        k = str(k)
        if k in specs and k not in clean:
            clean.append(k)
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        pcfg['top_fields'] = clean
    except Exception:
        cfg_set(int(chat_id), 'top_fields_v232_fallback', clean)
    save_all_states()


def _v232_bool(value: Any) -> str:
    return 'ON' if bool(value) else 'OFF'


def _v232_short_raw_value(chat_id: int, key: str) -> str:
    st = get_state(int(chat_id))
    try:
        if key == 'validation_status':
            return _v232_bool(cfg_value(chat_id, 'validation_enabled', False))
        if key == 'daily_phrase_status':
            return _v232_bool(cfg_value(chat_id, 'daily_phrase_enabled', False))
        if key == 'awards_status':
            return _v232_bool(_v230_awards_enabled(chat_id) if '_v230_awards_enabled' in globals() else False)
        if key == 'pending':
            return str(_v230_pending_count(chat_id) if '_v230_pending_count' in globals() else 0)
        if key == 'recurrentes':
            try:
                rows = recurring_list(int(chat_id))
                return f"{sum(1 for r in rows if bool(r.get('enabled', True)))}/{len(rows)}"
            except Exception:
                return '0'
        if key == 'recurrent_blocks':
            try:
                blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
                return str(len(blocks or []))
            except Exception:
                return '0'
        if key == 'dj':
            return _v232_bool(bool(st.dj_mode or st.panel_message_id or st.control_message_id))
        if key == 'live':
            return _v232_bool(bool(st.live_enabled))
        if key == 'dj_auto':
            return _v232_bool(bool(st.auto_track_enabled))
        if key == 'queue':
            return str(len(st.queue or []))
        if key == 'library':
            return str(len(st.library or []))
        if key == 'hot':
            return _v232_bool(cfg_value(chat_id, 'hot_auto_enabled', False))
        if key == 'ia':
            try:
                if '_v170_ai_stats' in globals():
                    on, _off = _v170_ai_stats(int(chat_id))
                    return str(on)
                if '_ai_custom_commands' in globals():
                    return str(len(_ai_custom_commands(int(chat_id))))
            except Exception:
                pass
            return '—'
        if key == 'security':
            return _v232_bool(_v219_group_authorized(chat_id) if '_v219_group_authorized' in globals() else True)
        if key == 'members':
            return str(len(st.member_activity or {}))
        if key == 'service_cleanup':
            return _v232_bool(cfg_value(chat_id, 'service_cleanup_enabled', False))
        if key == 'polls':
            return _v232_bool(True)
        if key == 'backup':
            return _v232_bool(STATE_PATH.exists())
        if key == 'botcommands':
            return _v232_bool(True)
        if key == 'tarot':
            try:
                cfg = _v129_tarot_cfg(chat_id) if '_v129_tarot_cfg' in globals() else {}
                return _v232_bool(cfg.get('tarot_enabled', True))
            except Exception:
                return 'ON'
        if key == 'impostor_settings':
            try:
                return _v232_bool(cfg_value(chat_id, 'impostor_enabled', True))
            except Exception:
                return 'ON'
        if key == 'pregonero':
            try:
                jobs = pregonero_auto_jobs(chat_id) if 'pregonero_auto_jobs' in globals() else []
                return str(len(jobs or []))
            except Exception:
                return 'ON'
        if key == 'privadito':
            return _v232_bool(cfg_value(chat_id, 'privadito_enabled', False))
        if key == 'resumen_fun':
            return _v232_bool(cfg_value(chat_id, 'resumen_fun_enabled', False))
        if key == 'command_cleanup':
            return 'OFF' if str(cfg_value(chat_id, 'command_cleanup_mode', 'off')) == 'off' else 'ON'
        if key == 'podcast':
            return _v232_bool('PODCAST_DOWNLOAD_ENABLED_V171' in globals() or 'PODCAST_PENDING_V171' in globals())
        if key == 'direct_buttons':
            try:
                return str(len(_v230_direct_cfg(int(chat_id)) if '_v230_direct_cfg' in globals() else []))
            except Exception:
                return '0'
        if key == 'panel_mode':
            try:
                layout = _v227_panel_layout(int(chat_id)) if '_v227_panel_layout' in globals() else {}
                mode = str(layout.get('mode', 'accordion'))
                cols = int(layout.get('cols', 2) or 2)
                return ('Ent' if mode == 'accordion' else 'Des') + f'/{cols}'
            except Exception:
                return '—'
        if key == 'hidden_groups':
            try:
                return str(len([cid for cid in _v231_known_chats(True) if _v231_group_hidden(cid)]))
            except Exception:
                return '0'
        if key == 'allowed_group':
            return _v232_bool(_v219_group_authorized(chat_id) if '_v219_group_authorized' in globals() else True)
        if key == 'owner':
            try:
                owners = _v219_owner_ids() if '_v219_owner_ids' in globals() else set()
                return 'OK' if owners else 'NO'
            except Exception:
                return '—'
        if key == 'version':
            return BOT_VERSION
    except Exception:
        logger.exception('V232 error valor resumen %s', key)
    return '—'


def _v232_cell(chat_id: int, key: str, width: int = 15) -> str:
    spec = _v232_summary_specs().get(key, {'icon': '•', 'abbr': key[:4]})
    value = _v232_short_raw_value(int(chat_id), key)
    text = f"{spec.get('icon','•')}{spec.get('abbr',key[:4])}:{value}"

    if len(text) > width:
        text = text[:width]
    return text.ljust(width)


def _v232_summary_lines(chat_id: int) -> List[str]:
    fields = _v232_summary_fields(int(chat_id))
    lines: List[str] = []
    width = 15
    for i in range(0, len(fields), 2):
        left = _v232_cell(int(chat_id), fields[i], width)
        right = _v232_cell(int(chat_id), fields[i+1], width).rstrip() if i + 1 < len(fields) else ''
        lines.append((left + right).rstrip())
    return lines


