def _v233_summary_cols(chat_id: int) -> int:
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        cols = int(pcfg.get('top_cols', 2) or 2)
    except Exception:
        cols = 2
    return max(1, min(3, cols))


def _v233_set_summary_cols(chat_id: int, cols: int) -> None:
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        pcfg['top_cols'] = max(1, min(3, int(cols)))
        save_all_states()
    except Exception:
        cfg_set(int(chat_id), 'top_cols_v233_fallback', max(1, min(3, int(cols))))


def _v233_time_hhmm(value: Any, default: str = '—') -> str:
    s = str(value or '').strip()
    if not s:
        return default
    m = __import__('re').search(r'([0-2]?\d:[0-5]\d)', s)
    if m:
        return m.group(1).zfill(5)
    return s[:5]


def _v233_onoff(value: Any) -> str:
    return 'ON' if bool(value) else 'OFF'


def _v233_msg_counts(chat_id: int) -> Tuple[int, int]:
    try:
        if '_v178_group_msg_counts' in globals():
            d, w = _v178_group_msg_counts(int(chat_id))
            return int(d or 0), int(w or 0)
    except Exception:
        pass
    try:
        root = _v179_stats_cfg(int(chat_id)) if '_v179_stats_cfg' in globals() else {}
        dkey = _v179_day_key_from_ts() if '_v179_day_key_from_ts' in globals() else time.strftime('%Y-%m-%d')
        wkey = _v179_week_key_from_ts() if '_v179_week_key_from_ts' in globals() else time.strftime('%G-W%V')
        return int((root.get('days', {}).get(dkey, {}) or {}).get('total', 0) or 0), int((root.get('weeks', {}).get(wkey, {}) or {}).get('total', 0) or 0)
    except Exception:
        return 0, 0


def _v233_media_day_count(chat_id: int) -> int:

    try:
        root = _v179_stats_cfg(int(chat_id)) if '_v179_stats_cfg' in globals() else {}
        dkey = _v179_day_key_from_ts() if '_v179_day_key_from_ts' in globals() else time.strftime('%Y-%m-%d')
        day = (root.get('days', {}).get(dkey, {}) or {})
        return int(day.get('media', 0) or day.get('multimedia', 0) or 0)
    except Exception:
        return 0


def _v233_entries_today_count(chat_id: int) -> int:
    try:
        today = time.strftime('%Y-%m-%d')
        st = get_state(int(chat_id))
        total = 0
        for e in st.entry_log or []:
            ts = int(e.get('joined_ts') or e.get('ts') or 0)
            if ts and time.strftime('%Y-%m-%d', time.localtime(ts)) == today:
                total += 1
        return total
    except Exception:
        return 0


def _v233_next_daily_time(rows: List[Dict[str, Any]], *, kind: str = 'rec') -> str:
    now = time.localtime()
    now_min = now.tm_hour * 60 + now.tm_min
    candidates: List[Tuple[int, str]] = []
    for r in rows:
        try:
            if kind == 'block':
                if not bool(r.get('enabled')) or str(r.get('mode', 'manual')) != 'daily':
                    continue
                hhmm = _v233_time_hhmm(r.get('time', ''), '')
            else:
                if not bool(r.get('enabled', True)):
                    continue
                sched = r.get('schedule') if isinstance(r.get('schedule'), dict) else {}
                stype = str(sched.get('type') or '')
                if stype == 'interval':
                    last = int(r.get('last_sent_ts', 0) or 0)
                    sec = max(30, int(sched.get('seconds', 3600) or 3600))
                    nxt = last + sec if last else int(time.time()) + sec
                    candidates.append((max(0, int((nxt - time.time()) // 60)), f"+{max(1, int((nxt - time.time()) // 60))}m"))
                    continue
                hhmm = _v233_time_hhmm(sched.get('time', ''), '')
            if not hhmm or ':' not in hhmm:
                continue
            hh, mm = [int(x) for x in hhmm.split(':', 1)]
            m = hh * 60 + mm
            delta = m - now_min
            if delta < 0:
                delta += 24 * 60
            candidates.append((delta, hhmm))
        except Exception:
            continue
    if not candidates:
        return '—'
    return sorted(candidates, key=lambda x: x[0])[0][1]


def _v233_next_recurrent(chat_id: int) -> str:
    try:
        return _v233_next_daily_time(recurring_list(int(chat_id)), kind='rec')
    except Exception:
        return '—'


def _v233_next_block(chat_id: int) -> str:
    try:
        blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
        return _v233_next_daily_time(blocks or [], kind='block')
    except Exception:
        return '—'


def _v233_pregonero_enabled(chat_id: int) -> bool:
    try:
        cfg = admin_cfg(int(chat_id))
        if bool(cfg.get('pregonero_auto_enabled', False)):
            return True
        jobs = pregonero_auto_jobs(int(chat_id)) if 'pregonero_auto_jobs' in globals() else []
        return any(bool(j.get('pregonero_auto_enabled', j.get('enabled', True))) for j in jobs if isinstance(j, dict))
    except Exception:
        return False


def _v233_pregonero_next(chat_id: int) -> str:
    try:
        times: List[str] = []
        cfg = admin_cfg(int(chat_id))
        if bool(cfg.get('pregonero_auto_enabled', False)):
            t = _v233_time_hhmm(cfg.get('pregonero_auto_time', ''), '')
            if t:
                times.append(t)
        jobs = pregonero_auto_jobs(int(chat_id)) if 'pregonero_auto_jobs' in globals() else []
        for j in jobs or []:
            if not isinstance(j, dict) or not bool(j.get('pregonero_auto_enabled', j.get('enabled', True))):
                continue
            sched = j.get('pregonero_auto_schedule') if isinstance(j.get('pregonero_auto_schedule'), dict) else {}
            t = _v233_time_hhmm(sched.get('time') or j.get('pregonero_auto_time') or j.get('time') or '', '')
            if t:
                times.append(t)
        if not times:
            return '—'
        now = time.localtime(); now_min = now.tm_hour * 60 + now.tm_min
        def delta(t: str) -> int:
            try:
                hh, mm = [int(x) for x in t.split(':', 1)]
                d = hh * 60 + mm - now_min
                return d if d >= 0 else d + 1440
            except Exception:
                return 99999
        return sorted(times, key=delta)[0]
    except Exception:
        return '—'


def _v233_pregonero_jobs(chat_id: int) -> int:
    try:
        jobs = pregonero_auto_jobs(int(chat_id)) if 'pregonero_auto_jobs' in globals() else []
        return sum(1 for j in jobs if isinstance(j, dict) and bool(j.get('pregonero_auto_enabled', j.get('enabled', True))))
    except Exception:
        return 0


def _v233_validation_check(chat_id: int) -> str:
    try:
        if not bool(cfg_value(int(chat_id), 'validation_enabled', False)):
            return 'OFF'
        q = cfg_questions(int(chat_id)) if 'cfg_questions' in globals() else []
        if not q:
            return 'NOQ'

        return 'OK'
    except Exception:
        return 'ERR'


def _v232_short_raw_value(chat_id: int, key: str) -> str:
    st = get_state(int(chat_id))
    try:
        if key == 'validation_status': return _v233_onoff(cfg_value(chat_id, 'validation_enabled', False))
        if key == 'validation_check': return _v233_validation_check(chat_id)
        if key == 'pending': return str(_v230_pending_count(chat_id) if '_v230_pending_count' in globals() else 0)
        if key == 'daily_phrase_status': return _v233_onoff(cfg_value(chat_id, 'daily_phrase_enabled', False))
        if key == 'daily_phrase_time': return _v233_time_hhmm(cfg_value(chat_id, 'daily_phrase_time', '10:00'))
        if key == 'awards_status': return _v233_onoff(_v230_awards_enabled(chat_id) if '_v230_awards_enabled' in globals() else False)
        if key == 'awards_daily_time':
            cfg = _v230_awards_cfg(chat_id) if '_v230_awards_cfg' in globals() else {}
            return _v233_time_hhmm(cfg.get('awards_daily_time', '23:30'))
        if key == 'awards_weekly_time':
            cfg = _v230_awards_cfg(chat_id) if '_v230_awards_cfg' in globals() else {}
            return _v233_time_hhmm(cfg.get('awards_weekly_time', '23:30'))
        if key == 'msg_day': return str(_v233_msg_counts(chat_id)[0])
        if key == 'msg_week': return str(_v233_msg_counts(chat_id)[1])
        if key == 'media_day': return str(_v233_media_day_count(chat_id))
        if key == 'entries_today': return str(_v233_entries_today_count(chat_id))
        if key == 'members': return str(len(st.member_activity or {}))
        if key == 'recurrentes':
            rows = recurring_list(int(chat_id))
            return f"{sum(1 for r in rows if bool(r.get('enabled', True)))}/{len(rows)}"
        if key == 'next_recurrent': return _v233_next_recurrent(chat_id)
        if key == 'recurrent_blocks':
            blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
            active = sum(1 for b in blocks if isinstance(b, dict) and bool(b.get('enabled')))
            return f"{active}/{len(blocks or [])}"
        if key == 'next_block': return _v233_next_block(chat_id)
        if key == 'direct_buttons':
            return str(len(_v230_direct_cfg(int(chat_id)) if '_v230_direct_cfg' in globals() else []))
        if key == 'dj': return _v233_onoff(bool(st.dj_mode or st.panel_message_id or st.control_message_id))
        if key == 'live': return _v233_onoff(bool(st.live_enabled))
        if key == 'dj_auto': return _v233_onoff(bool(st.auto_track_enabled))
        if key == 'queue': return str(len(st.queue or []))
        if key == 'library': return str(len(st.library or []))
        if key == 'podcast': return _v233_onoff('PODCAST_DOWNLOAD_ENABLED_V171' in globals() or 'PODCAST_PENDING_V171' in globals())
        if key == 'dj_opus': return _v233_onoff(bool(cfg_value(chat_id, 'dj_audio_normalize_opus', False) or os.getenv('DJ_AUDIO_NORMALIZE_OPUS','').lower() in ('1','true','yes','on')))
        if key == 'hot': return _v233_onoff(cfg_value(chat_id, 'hot_auto_enabled', False))
        if key == 'hot_interval': return str(int(cfg_value(chat_id, 'hot_auto_interval_seconds', 180) or 180)) + 's'
        if key == 'tarot':
            cfg = _v129_tarot_cfg(chat_id) if '_v129_tarot_cfg' in globals() else {}
            return _v233_onoff(cfg.get('tarot_enabled', True))
        if key == 'impostor_settings': return _v233_onoff(cfg_value(chat_id, 'impostor_enabled', True))
        if key == 'ia':
            if '_v170_ai_stats' in globals():
                on, _off = _v170_ai_stats(int(chat_id)); return str(on)
            if '_ai_custom_commands' in globals(): return str(len(_ai_custom_commands(int(chat_id))))
            return '—'
        if key == 'cerebrito': return _v233_onoff(cfg_value(chat_id, 'cerebrito_enabled', True))
        if key == 'pregonero': return _v233_onoff(_v233_pregonero_enabled(chat_id))
        if key == 'pregonero_next': return _v233_pregonero_next(chat_id)
        if key == 'pregonero_jobs': return str(_v233_pregonero_jobs(chat_id))
        if key == 'privadito': return _v233_onoff(cfg_value(chat_id, 'privadito_enabled', False))
        if key == 'resumen_fun': return _v233_onoff(cfg_value(chat_id, 'resumen_fun_enabled', False))
        if key == 'polls': return _v233_onoff(True)
        if key == 'security': return _v233_onoff(_v219_group_authorized(chat_id) if '_v219_group_authorized' in globals() else True)
        if key == 'allowed_group': return _v233_onoff(_v219_group_authorized(chat_id) if '_v219_group_authorized' in globals() else True)
        if key == 'service_cleanup': return _v233_onoff(cfg_value(chat_id, 'service_cleanup_enabled', False))
        if key == 'command_cleanup': return 'OFF' if str(cfg_value(chat_id, 'command_cleanup_mode', 'off')) == 'off' else 'ON'
        if key == 'backup': return _v233_onoff(STATE_PATH.exists())
        if key == 'botcommands': return _v233_onoff(True)
        if key == 'permissions': return _v233_onoff(True)
        if key == 'panel_mode':
            layout = _v227_panel_layout(int(chat_id)) if '_v227_panel_layout' in globals() else {}
            mode = str(layout.get('mode', 'accordion'))
            cols = int(layout.get('cols', 2) or 2)
            return ('ENT' if mode == 'accordion' else 'DES') + f'/{cols}'
        if key == 'hidden_groups':
            return str(len([cid for cid in _v231_known_chats(True) if _v231_group_hidden(cid)])) if '_v231_known_chats' in globals() else '0'
        if key == 'owner':
            owners = _v219_owner_ids() if '_v219_owner_ids' in globals() else set()
            return 'OK' if owners else 'NO'
        if key == 'version': return BOT_VERSION
    except Exception:
        logger.exception('V233 error valor resumen %s', key)
    return '—'


def _v233_abbr5(key: str) -> str:
    spec = _v233_summary_specs().get(key, {'abbr': key[:5]})
    raw = str(spec.get('abbr') or key[:5]).upper()
    raw = ''.join(ch for ch in raw if ch.isalnum())[:5]
    return raw.ljust(5, '0')[:5]


def _v232_cell(chat_id: int, key: str, width: Optional[int] = None) -> str:
    cols = _v233_summary_cols(int(chat_id))
    width = int(width or (23 if cols == 1 else 15 if cols == 2 else 11))
    spec = _v233_summary_specs().get(key, {'icon': '•', 'abbr': key[:5]})
    icon = spec.get('icon', '•')
    abbr = _v233_abbr5(key)
    value = str(_v232_short_raw_value(int(chat_id), key))
    max_value = max(1, width - 8)
    if len(value) > max_value:
        value = value[:max_value]
    text = f"{icon}{abbr}:{value}"
    if len(text) > width:
        text = text[:width]
    return text.ljust(width)


def _v232_summary_lines(chat_id: int) -> List[str]:
    fields = _v232_summary_fields(int(chat_id))
    cols = _v233_summary_cols(int(chat_id))
    width = 23 if cols == 1 else 15 if cols == 2 else 11
    lines: List[str] = []
    for i in range(0, len(fields), cols):
        chunk = fields[i:i + cols]
        lines.append(''.join(_v232_cell(int(chat_id), k, width) for k in chunk).rstrip())
    return lines


def _v232_top_text(chat_id: int) -> str:
    fields = _v232_summary_fields(int(chat_id))
    active = len(fields)
    total = len(_v233_summary_specs())
    cols = _v233_summary_cols(int(chat_id))
    preview = '\n'.join(_v232_summary_lines(int(chat_id)))
    return (
        '<b>🔝 Resumen rápido PRO</b>\n\n'
        'Elige qué información aparece arriba del panel. Cada dato usa icono + 5 letras + valor.\n'
        f'Activos: <b>{active}/{total}</b> · Columnas: <b>{cols}</b>\n\n'
        '<b>Vista previa:</b>\n'
        f'<pre>{h(preview)}</pre>\n\n'
        'Puedes activar, ocultar, subir y bajar cada dato. Usa 1/2/3 columnas según lo compacto que lo quieras.'
    )


def _v232_top_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    specs = _v233_summary_specs()
    keys = list(specs.keys())
    fields = _v232_summary_fields(int(chat_id))
    cols = _v233_summary_cols(int(chat_id))
    per_page = 8
    total_pages = max(1, ((len(keys) - 1) // per_page) + 1)
    page = max(0, min(int(page or 0), total_pages - 1))
    chunk = keys[page * per_page:(page + 1) * per_page]
    rows: List[List[InlineKeyboardButton]] = []
    rows.append([
        InlineKeyboardButton(('✅ ' if cols == 1 else '') + '1 columna', callback_data=f'cfg233|top_cols|{int(chat_id)}|1|{page}'),
        InlineKeyboardButton(('✅ ' if cols == 2 else '') + '2 columnas', callback_data=f'cfg233|top_cols|{int(chat_id)}|2|{page}'),
        InlineKeyboardButton(('✅ ' if cols == 3 else '') + '3 columnas', callback_data=f'cfg233|top_cols|{int(chat_id)}|3|{page}'),
    ])
    for key in chunk:
        spec = specs[key]
        enabled = key in fields
        label = ('✅ ' if enabled else '❌ ') + f"{spec['icon']} {_v233_abbr5(key)} · {spec['name']}"
        row = [InlineKeyboardButton(label[:46], callback_data=f'cfg233|top_toggle|{int(chat_id)}|{key}|{page}')]
        if enabled:
            row.append(InlineKeyboardButton('⬆️', callback_data=f'cfg233|top_up|{int(chat_id)}|{key}|{page}'))
            row.append(InlineKeyboardButton('⬇️', callback_data=f'cfg233|top_down|{int(chat_id)}|{key}|{page}'))
        rows.append(row)
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'cfg233|top_page|{int(chat_id)}|{page-1}'))
    nav.append(InlineKeyboardButton(f'📄 {page+1}/{total_pages}', callback_data=f'cfg233|noop|{int(chat_id)}'))
    if page < total_pages - 1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'cfg233|top_page|{int(chat_id)}|{page+1}'))
    rows.append(nav)
    rows.append([
        InlineKeyboardButton('✅ Recomendado', callback_data=f'cfg233|top_default|{int(chat_id)}|{page}'),
        InlineKeyboardButton('🧹 Vaciar', callback_data=f'cfg233|top_clear|{int(chat_id)}|{page}'),
    ])
    rows.append([InlineKeyboardButton('🔙 Configuración del panel', callback_data=f'panelcfg|open|{int(chat_id)}')])
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)


async def _v233_summary_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    try:
        if data.startswith('panelcfg|top|'):
            parts = data.split('|')
            chat_id = int(parts[2]) if len(parts) > 2 else int(update.effective_chat.id)
            if not is_global_admin_user(q.from_user.id):
                await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
                raise _V233Stop
            await q.answer()
            await q.edit_message_text(_v232_top_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v232_top_markup(chat_id, 0))
            raise _V233Stop
        if not (data.startswith('cfg233|') or data.startswith('cfg232|')):
            return
        parts = data.split('|')
        action = parts[1] if len(parts) > 1 else 'noop'
        chat_id = int(parts[2]) if len(parts) > 2 and str(parts[2]).lstrip('-').isdigit() else int(update.effective_chat.id)
        if not is_global_admin_user(q.from_user.id):
            await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
            raise _V233Stop
        page = 0
        fields = _v232_summary_fields(chat_id)
        if action == 'noop':
            await q.answer(); raise _V233Stop
        if action == 'top_cols' and len(parts) >= 5:
            cols = int(parts[3]); page = int(parts[4])
            _v233_set_summary_cols(chat_id, cols)
            await q.answer(f'{cols} columnas')
        elif action == 'top_page' and len(parts) >= 4:
            page = int(parts[3]); await q.answer()
        elif action in ('top_toggle', 'top_up', 'top_down') and len(parts) >= 5:
            key = parts[3]; page = int(parts[4])
            if key not in _v233_summary_specs():
                await q.answer('Dato no válido.', show_alert=True); raise _V233Stop
            if action == 'top_toggle':
                if key in fields: fields = [x for x in fields if x != key]
                else: fields.append(key)
                _v232_set_summary_fields(chat_id, fields)
                await q.answer('Resumen actualizado')
            elif action == 'top_up':
                if key in fields:
                    i = fields.index(key)
                    if i > 0:
                        fields[i-1], fields[i] = fields[i], fields[i-1]
                        _v232_set_summary_fields(chat_id, fields)
                await q.answer('Movido')
            elif action == 'top_down':
                if key in fields:
                    i = fields.index(key)
                    if i < len(fields) - 1:
                        fields[i+1], fields[i] = fields[i], fields[i+1]
                        _v232_set_summary_fields(chat_id, fields)
                await q.answer('Movido')
        elif action == 'top_default':
            page = int(parts[3]) if len(parts) >= 4 else 0
            _v232_set_summary_fields(chat_id, _v232_default_summary_fields())
            await q.answer('Resumen recomendado restaurado')
        elif action == 'top_clear':
            page = int(parts[3]) if len(parts) >= 4 else 0
            _v232_set_summary_fields(chat_id, [])
            await q.answer('Resumen vaciado')
        else:
            await q.answer('Acción no reconocida', show_alert=True)
            raise _V233Stop
        await q.edit_message_text(_v232_top_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v232_top_markup(chat_id, page))
    except _V233Stop:
        raise
    except Exception:
        logger.exception('V233 router resumen falló: %s', data)
        try: await q.answer('Error actualizando resumen', show_alert=True)
        except Exception: pass
    raise _V233Stop


