async def _v236_can_validate(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> bool:
    try:
        if '_v219_is_owner' in globals() and _v219_is_owner(int(user_id)):
            return True
        if int(user_id) in ADMIN_IDS:
            return True
        mode = str(cfg_value(int(chat_id), 'validation_approver_mode', 'telegram_admins') or 'telegram_admins')
        if mode == 'admin_ids':
            return int(user_id) in ADMIN_IDS
        if mode == 'creator':
            try:
                m = await context.bot.get_chat_member(int(chat_id), int(user_id))
                return getattr(m, 'status', '') == 'creator'
            except Exception:
                return False
        return await is_admin(context, int(chat_id), int(user_id))
    except Exception:
        return False

async def _v236_validation_silent_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('val|') or data.startswith('valreq|') or data.startswith('cfg|pendapprove|') or data.startswith('cfg|pendkick|')):
        return
    chat_id = int(update.effective_chat.id) if update.effective_chat else 0

    try:
        parts = data.split('|')
        if data.startswith('cfg|pend') and len(parts) >= 3:
            chat_id = int(parts[2])
    except Exception:
        pass
    if chat_id and not await _v236_can_validate(context, chat_id, int(q.from_user.id)):

        try:
            await q.answer(cache_time=2)
        except Exception:
            pass
        raise _V236Stop


