async def ensure_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(PANEL_LOCKS, int(chat_id)):
        state = get_state(int(chat_id))
        if not state.dj_mode:
            return
        sync_panel_override_expiry(state)
        text = panel_text(state)
        markup = panel_markup()
        panel_id = state.panel_message_id
        if panel_id:
            try:
                await bot.edit_message_text(chat_id=int(chat_id), message_id=panel_id, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
                save_all_states()
                try:
                    await bot.pin_chat_message(chat_id=int(chat_id), message_id=panel_id, disable_notification=True)
                except Exception:
                    pass
                return
            except BadRequest as e:
                low = str(e).lower()
                if 'message is not modified' in low:
                    return
                if not any(x in low for x in ('message to edit not found','message_id_invalid','message not found')):
                    logger.warning('V236: no se pudo editar panel DJ %s: %s', panel_id, e)
                    return
                state.panel_message_id = None
                save_all_states()
            except Exception:
                logger.exception('V236: fallo temporal editando panel; evito duplicar')
                return

        msg = await bot.send_message(chat_id=int(chat_id), text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
        state.panel_message_id = int(msg.message_id)
        save_all_states()
        await register_bot_message(int(chat_id), msg.message_id)
        try:
            await bot.pin_chat_message(chat_id=int(chat_id), message_id=msg.message_id, disable_notification=True)
        except Exception:
            logger.exception('V236: no se pudo fijar panel DJ')
        try:
            await cleanup_bot_messages_keep_core(bot, int(chat_id))
        except Exception:
            pass

async def ensure_control_panel(bot, chat_id: int) -> None:
    async with get_chat_lock(CONTROL_LOCKS, int(chat_id)):
        state = get_state(int(chat_id))
        if not state.dj_mode:
            return
        cfg = admin_cfg(int(chat_id))
        if bool(cfg.get('dj_mesa_minimized', False)):
            return
        text, markup0 = current_control_view(state)
        markup = markup0
        if (state.control_view or 'home') == 'home':
            markup = _v236_control_markup_with_minimize(state)
        mid = state.control_message_id
        if mid:
            try:
                await bot.edit_message_text(chat_id=int(chat_id), message_id=mid, text=text, reply_markup=markup, parse_mode=ParseMode.HTML)
                cfg['dj_mesa_visible'] = True; cfg['dj_mesa_minimized'] = False
                save_all_states()
                return
            except BadRequest as e:
                low = str(e).lower()
                if 'message is not modified' in low:
                    return
                if not any(x in low for x in ('message to edit not found','message_id_invalid','message not found')):
                    logger.warning('V236: no se pudo editar mesa DJ %s: %s', mid, e)
                    return
                state.control_message_id = None
                save_all_states()
            except Exception:
                logger.exception('V236: fallo temporal editando mesa; evito duplicar')
                return

        msg = await bot.send_message(
            chat_id=int(chat_id), text=text, reply_markup=markup, parse_mode=ParseMode.HTML,
            reply_to_message_id=state.panel_message_id, allow_sending_without_reply=True
        )
        state.control_message_id = int(msg.message_id)
        cfg['dj_mesa_visible'] = True; cfg['dj_mesa_minimized'] = False
        save_all_states()
        await register_bot_message(int(chat_id), msg.message_id)

_old_v236_callback_router = callback_router
async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ''
    if q and update.effective_chat and update.effective_user:
        chat_id = int(update.effective_chat.id); uid = int(update.effective_user.id)
        if data == 'panel_minimize':
            if not await is_controller(context, chat_id, uid):
                await q.answer('Solo admin o DJ.', show_alert=True); return
            st = get_state(chat_id); old = st.control_message_id; st.control_message_id = None
            cfg = admin_cfg(chat_id); cfg['dj_mesa_minimized'] = True; cfg['dj_mesa_visible'] = False
            save_all_states()
            if old:
                await safe_delete(context.bot, chat_id, old)
            await ensure_panel(context.bot, chat_id)
            await q.answer('Mesa minimizada. Pulsa Mesa para mostrarla.', show_alert=False)
            return
        if data in ('panel_home','menu_panel'):

            st = get_state(chat_id); st.dj_mode = True
            if st.assigned_dj_id is None:
                st.assigned_dj_id = uid; st.assigned_dj_name = display_name(update.effective_user)
            set_control_view(st, 'home', 0)
            cfg = admin_cfg(chat_id); cfg['dj_mesa_minimized'] = False; cfg['dj_mesa_visible'] = True
            save_all_states()
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
            await q.answer('Mesa mostrada ✅')
            return
    return await _old_v236_callback_router(update, context)

