def _v232_cell(chat_id: int, key: str, width: Optional[int] = None) -> str:
    cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2

    width = int(width or (24 if cols == 1 else 17 if cols == 2 else 14))
    spec = _v233_summary_specs().get(key, {'icon': '•', 'abbr': key[:5]}) if '_v233_summary_specs' in globals() else {'icon':'•','abbr':key[:5]}
    icon = spec.get('icon', '•')
    abbr = _v233_abbr5(key) if '_v233_abbr5' in globals() else str(spec.get('abbr', key[:5])).upper()[:5]
    value = str(_v232_short_raw_value(int(chat_id), key)) if '_v232_short_raw_value' in globals() else '—'
    max_value = max(1, width - (len(icon) + 7))
    if len(value) > max_value:
        value = value[:max_value]
    text = f'{icon}{abbr}:{value}'
    return text[:width].ljust(width)

def _v232_summary_lines(chat_id: int) -> List[str]:
    fields = _v232_summary_fields(int(chat_id)) if '_v232_summary_fields' in globals() else []
    cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2
    width = 24 if cols == 1 else 17 if cols == 2 else 14
    lines=[]
    for i in range(0, len(fields), cols):
        chunk=fields[i:i+cols]
        lines.append(''.join(_v232_cell(int(chat_id), k, width) for k in chunk).rstrip())
    return lines


def _v236_rblk_cfg(chat_id: int, bid: int) -> Optional[Dict[str, Any]]:
    try:
        blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
        return next((b for b in blocks if int(b.get('id',0) or 0)==int(bid)), None)
    except Exception:
        return None

def _v236_hhmm_to_min(s: str) -> Optional[int]:
    try:
        import re
        m = re.search(r'([0-2]?\d):([0-5]\d)', str(s or ''))
        if not m: return None
        h0=int(m.group(1)); m0=int(m.group(2))
        if h0>23: return None
        return h0*60+m0
    except Exception: return None

def _v236_rblk_due(block: Dict[str, Any], now_ts: Optional[int]=None) -> bool:
    now_ts = int(now_ts or time.time())
    if not bool(block.get('enabled')): return False
    mode = str(block.get('mode','daily'))
    now = time.localtime(now_ts)
    now_min = now.tm_hour*60 + now.tm_min
    start_min = _v236_hhmm_to_min(str(block.get('time','21:00')))
    if start_min is None or now_min != start_min: return False
    last_key = str(block.get('last_sent_key',''))
    today = time.strftime('%Y-%m-%d', now)
    if last_key == f'{today}:{now_min}': return False
    return True

async def _v236_send_rblk_once(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> int:
    block = _v236_rblk_cfg(chat_id, bid)
    if not block: return 0
    ids = [int(x) for x in (block.get('recurring_ids') or block.get('ids') or []) if str(x).lstrip('-').isdigit()]
    sent=0
    for rid in ids:
        row = recurring_find(int(chat_id), rid) if 'recurring_find' in globals() else None
        if not row: continue
        await send_recurring_message(context, int(chat_id), row)
        sent += 1
        await asyncio.sleep(1)
    return sent

async def _v236_rblk_scheduler(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        now_ts=int(time.time()); today=time.strftime('%Y-%m-%d', time.localtime(now_ts))
        for chat_id in list(STATE_CACHE.keys()):
            blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
            for b in blocks or []:
                if not isinstance(b, dict) or not _v236_rblk_due(b, now_ts): continue
                sent = await _v236_send_rblk_once(context, int(chat_id), int(b.get('id',0) or 0))
                if sent:
                    b['last_sent_key'] = f"{today}:{_v236_hhmm_to_min(str(b.get('time','21:00')))}"
                    save_all_states()
    except Exception:
        logger.exception('V236 scheduler bloques recurrentes falló')


def _v236_known_humans(chat_id: int) -> List[Tuple[int, Dict[str, Any]]]:
    st=get_state(int(chat_id)); out=[]
    for uid, r in (st.member_activity or {}).items():
        try:
            if r.get('is_bot'): continue
            out.append((int(uid), r))
        except Exception: pass
    return out

def _v236_best_member(chat_id: int, kind: str) -> Tuple[int, Dict[str, Any], int]:
    users=_v236_known_humans(chat_id)
    if not users: return (0, {}, 0)
    key_map={'parlante':'message_count','holi':'message_count','competidor':'message_count','noctambulo':'message_count','risas':'laugh_count'}
    k=key_map.get(kind,'message_count')
    best=max(users, key=lambda item: int(item[1].get(k) or item[1].get('message_count') or 0))
    val=int(best[1].get(k) or best[1].get('message_count') or 0)
    return best[0], best[1], val

_old_v236_award_entry = _v205_award_entry if '_v205_award_entry' in globals() else None
def _v205_award_entry(chat_id: int, kind: str, period: str='daily') -> Dict[str, Any]:
    try:
        entry = _old_v236_award_entry(int(chat_id), kind, period) if callable(_old_v236_award_entry) else {}
        if entry and entry.get('winner') and str(entry.get('winner')) not in ('—','Sin datos',''):
            return entry
    except Exception:
        entry = {}
    uid, rec, val = _v236_best_member(int(chat_id), kind)
    label = _v205_award_label(kind) if '_v205_award_label' in globals() else kind
    if uid:
        return {'kind': kind, 'period': period, 'label': label, 'winner': rec.get('name') or rec.get('username') or str(uid), 'user_id': uid, 'value': val, 'why': f'Destaca por su actividad registrada en el grupo: {val} interacciones/mensajes.'}
    return {'kind': kind, 'period': period, 'label': label, 'winner': 'Sin datos', 'user_id': 0, 'value': 0, 'why': 'Todavía no hay actividad suficiente registrada.'}

_old_v236_awards_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int=0) -> str:
    if block == 'awards':
        try:
            base = _old_v236_awards_block_text(int(chat_id), block, page)
        except Exception:
            base = '<b>🏆 Premios sociales</b>'
        kinds = [('parlante','🗣'),('risas','😂'),('pareja','💞'),('holi','👋'),('noctambulo','🌙'),('competidor','🎮')]
        lines=['', '<b>📌 Si lanzas ahora, saldría:</b>']
        for k, ico in kinds:
            e = _v205_award_entry(int(chat_id), k, 'daily')
            lines.append(f"{ico} {h(e.get('label', k))}: <b>{h(e.get('winner','Sin datos'))}</b> · {h(e.get('value',0))}")
        return base.rstrip() + '\n' + '\n'.join(lines)
    return _old_v236_awards_block_text(int(chat_id), block, page)


_old_build_application_v236 = build_application
def build_application() -> Application:
    app = _old_build_application_v236()
    app.add_handler(CallbackQueryHandler(_v236_validation_silent_guard, pattern=r'^(val\||valreq\||cfg\|pendapprove\||cfg\|pendkick\|)'), group=-90000000000)
    app.add_handler(CallbackQueryHandler(_v236_dj_menu_cleanup_router, pattern=r'^(dj_easy_menu|menu_panel|dj_podcast_menu|dj_menu_close)$'), group=-89000000000)
    try:
        if getattr(app, 'job_queue', None):
            app.job_queue.run_repeating(_v236_rblk_scheduler, interval=30, first=10, name='v236_rblk_scheduler')
    except Exception:
        logger.exception('V236 no pudo iniciar job de bloques recurrentes')
    logger.info('V236 cargado: DJ estable, validación silenciosa, resumen ancho, premios y bloques recurrentes reforzados')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V237Stop
except Exception:
    _V237Stop = Exception

V237_VERSION = 'V237'

import re as _v237_re


_V237_LAUGH_RE = _v237_re.compile(r'(j+a+j+a+|jaja+|jeje+|jiji+|haha+|hehe+|😂|🤣|😆|😹|😄|😁)', _v237_re.I)
_V237_HELLO_RE = _v237_re.compile(r'\b(hola+|holi+|buenas+|buenos\s+d[ií]as|buenas\s+tardes|buenas\s+noches|hey+|ey+|hi+)\b', _v237_re.I)


def _v237_day_key(ts: Optional[int] = None) -> str:
    return time.strftime('%Y-%m-%d', time.localtime(ts or time.time()))


def _v237_week_days(ts: Optional[int] = None) -> List[str]:
    now = ts or time.time()

    return [_v237_day_key(int(now - i * 86400)) for i in range(7)]


def _v237_awards_stats_root(chat_id: int) -> Dict[str, Any]:
    cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
    return cfg.setdefault('awards_stats', {})


def _v237_day_stats(chat_id: int, key: Optional[str] = None) -> Dict[str, Any]:
    root = _v237_awards_stats_root(chat_id)
    day = root.setdefault(key or _v237_day_key(), {'users': {}, 'pairs': {}})
    day.setdefault('users', {})
    day.setdefault('pairs', {})
    return day


def _v237_name_from_record(uid: str, row: Dict[str, Any]) -> str:
    return str(row.get('name') or row.get('username') or uid)


_old_v237_collect_awards_stats = _v167_collect_awards_stats if '_v167_collect_awards_stats' in globals() else None
async def _v167_collect_awards_stats(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:

    if callable(_old_v237_collect_awards_stats):
        try:
            await _old_v237_collect_awards_stats(update, context)
        except Exception:
            logger.exception('V237: recolector antiguo de premios falló')
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
        return
    chat_id = int(update.effective_chat.id)
    cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
    if not bool(cfg.get('awards_enabled', True)):
        return
    txt = (update.message.text or update.message.caption or '').strip()

    uid = str(int(update.effective_user.id))
    day = _v237_day_stats(chat_id)
    users = day.setdefault('users', {})
    row = users.setdefault(uid, {'name': display_name(update.effective_user), 'username': getattr(update.effective_user, 'username', '') or '', 'messages': 0, 'risas': 0, 'holas': 0, 'hours': {}, 'media': 0})
    row['name'] = display_name(update.effective_user)
    row['username'] = getattr(update.effective_user, 'username', '') or ''
    row['messages'] = int(row.get('messages', 0) or 0) + 1
    if getattr(update.message, 'photo', None) or getattr(update.message, 'video', None) or getattr(update.message, 'animation', None) or getattr(update.message, 'document', None) or getattr(update.message, 'audio', None) or getattr(update.message, 'voice', None):
        row['media'] = int(row.get('media', 0) or 0) + 1
    if txt:
        row['risas'] = int(row.get('risas', 0) or 0) + len(_V237_LAUGH_RE.findall(txt))
        if _V237_HELLO_RE.search(txt):
            row['holas'] = int(row.get('holas', 0) or 0) + 1
    try:
        dt = getattr(update.message, 'date', None)
        ts = int(dt.timestamp()) if dt else int(time.time())
    except Exception:
        ts = int(time.time())

    hh = time.strftime('%H', time.localtime(ts))
    hours = row.setdefault('hours', {})
    if isinstance(hours, dict):
        hours[hh] = int(hours.get(hh, 0) or 0) + 1

    reply_user = getattr(getattr(update.message, 'reply_to_message', None), 'from_user', None)
    if reply_user and not getattr(reply_user, 'is_bot', False) and int(reply_user.id) != int(update.effective_user.id):
        a, b = sorted([str(int(update.effective_user.id)), str(int(reply_user.id))])
        key = f'{a}:{b}'
        pairs = day.setdefault('pairs', {})
        pr = pairs.setdefault(key, {'a': a, 'b': b, 'count': 0, 'names': {}})
        pr['count'] = int(pr.get('count', 0) or 0) + 1
        pr.setdefault('names', {})[uid] = display_name(update.effective_user)
        pr.setdefault('names', {})[str(int(reply_user.id))] = display_name(reply_user)

    try:
        remember_member_activity(chat_id, update.effective_user, kind='message', source='awards_stats')
    except Exception:
        pass

    try:
        if int(row.get('messages', 0) or 0) % 5 == 0 or bool(reply_user):
            save_all_states()
    except Exception:
        pass


def _v237_merge_award_period(chat_id: int, period: str = 'daily') -> tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    days = _v237_week_days() if str(period).lower().startswith('week') or str(period).lower().startswith('sem') else [_v237_day_key()]
    stats = _v237_awards_stats_root(chat_id)
    users: Dict[str, Dict[str, Any]] = {}
    pairs: Dict[str, Dict[str, Any]] = {}
    for dk in days:
        day = stats.get(dk, {}) if isinstance(stats, dict) else {}
        for uid, src in (day.get('users', {}) or {}).items():
            dst = users.setdefault(str(uid), {'name': src.get('name') or str(uid), 'username': src.get('username', ''), 'messages': 0, 'risas': 0, 'holas': 0, 'media': 0, 'hours': {}})
            dst['name'] = src.get('name') or dst.get('name') or str(uid)
            dst['username'] = src.get('username', dst.get('username', ''))
            for k in ('messages', 'risas', 'holas', 'media'):
                dst[k] = int(dst.get(k, 0) or 0) + int(src.get(k, 0) or 0)
            for hh, c in (src.get('hours', {}) or {}).items():
                dst.setdefault('hours', {})[str(hh)] = int(dst.setdefault('hours', {}).get(str(hh), 0) or 0) + int(c or 0)
        for pk, src in (day.get('pairs', {}) or {}).items():
            dst = pairs.setdefault(str(pk), {'count': 0, 'names': {}, 'a': src.get('a'), 'b': src.get('b')})
            dst['count'] = int(dst.get('count', 0) or 0) + int(src.get('count', 0) or 0)
            dst.setdefault('names', {}).update(src.get('names') or {})
            if src.get('a'): dst['a'] = src.get('a')
            if src.get('b'): dst['b'] = src.get('b')
    return users, pairs


def _v237_best_award(chat_id: int, kind: str, period: str = 'daily') -> Dict[str, Any]:
    users, pairs = _v237_merge_award_period(chat_id, period)
    kind = str(kind or '').lower()
    suffix = 'semana' if str(period).lower().startswith('week') or str(period).lower().startswith('sem') else 'día'
    labels = {
        'parlante': 'Más parlante', 'risas': 'El que más se ríe', 'pareja': f'Pareja del {suffix}',
        'holi': 'Holi holi', 'noctambulo': 'Noctámbulo', 'competidor': 'Más competidor'
    }
    if kind == 'pareja':
        if not pairs:
            return {'kind': kind, 'label': labels[kind], 'winner': 'Sin datos', 'value': 0, 'why': 'Aún no hay respuestas entre miembros suficientes.'}
        pk, pr = max(pairs.items(), key=lambda kv: int(kv[1].get('count', 0) or 0))
        if int(pr.get('count', 0) or 0) <= 0:
            return {'kind': kind, 'label': labels[kind], 'winner': 'Sin datos', 'value': 0, 'why': 'Aún no hay respuestas entre miembros suficientes.'}
        a, b = pk.split(':') if ':' in pk else (str(pr.get('a') or ''), str(pr.get('b') or ''))
        n1 = pr.get('names', {}).get(a, a)
        n2 = pr.get('names', {}).get(b, b)
        return {'kind': kind, 'label': labels[kind], 'winner': f'{n1} + {n2}', 'value': int(pr.get('count', 0) or 0), 'why': f'Son quienes más han interactuado entre sí mediante respuestas: {int(pr.get("count", 0) or 0)} interacciones.'}
    if kind == 'parlante':
        metric = lambda row: int(row.get('messages', 0) or 0)
        why = 'Es quien más mensajes ha enviado en el periodo.'
    elif kind == 'risas':
        metric = lambda row: int(row.get('risas', 0) or 0)
        why = 'Es quien más mensajes de risas, jaja o emojis de risa ha enviado.'
    elif kind == 'holi':
        metric = lambda row: int(row.get('holas', 0) or 0)
        why = 'Es quien más saludos tipo hola, holi o buenas ha enviado.'
    elif kind == 'noctambulo':
        metric = lambda row: len([hh for hh, c in (row.get('hours', {}) or {}).items() if int(c or 0) > 0])
        why = 'Es quien ha escrito en más franjas horarias distintas; no necesariamente quien más mensajes mandó.'
    elif kind == 'competidor':
        comp = _v168_extract_ranking_points(chat_id, weekly=(period != 'daily')) if '_v168_extract_ranking_points' in globals() else {}
        if comp:
            uid, row = max(comp.items(), key=lambda kv: int(kv[1].get('points', 0) or 0))
            val = int(row.get('points', 0) or 0)
            if val > 0:
                return {'kind': kind, 'label': labels[kind], 'winner': row.get('name') or uid, 'user_id': int(uid) if str(uid).isdigit() else 0, 'value': val, 'why': 'Es quien más puntos acumula en juegos o dinámicas.'}
        return {'kind': kind, 'label': labels[kind], 'winner': 'Sin datos', 'value': 0, 'why': 'Todavía no hay puntos de juegos suficientes.'}
    else:
        metric = lambda row: int(row.get('messages', 0) or 0)
        why = 'Actividad registrada en el grupo.'
    if not users:
        return {'kind': kind, 'label': labels.get(kind, kind), 'winner': 'Sin datos', 'value': 0, 'why': 'Todavía no hay mensajes suficientes.'}
    uid, row = max(users.items(), key=lambda kv: metric(kv[1]))
    val = metric(row)
    if val <= 0:
        return {'kind': kind, 'label': labels.get(kind, kind), 'winner': 'Sin datos', 'value': 0, 'why': why}
    return {'kind': kind, 'label': labels.get(kind, kind), 'winner': _v237_name_from_record(uid, row), 'user_id': int(uid) if str(uid).isdigit() else 0, 'value': val, 'why': f'{why} Total: {val}.'}


def _v205_award_entry(chat_id: int, kind: str, period: str='daily') -> Dict[str, Any]:
    return _v237_best_award(int(chat_id), kind, period)


def _v237_awards_calculate(chat_id: int, *, weekly: bool = False) -> str:
    period = 'weekly' if weekly else 'daily'
    suffix = 'SEMANA' if weekly else 'DÍA'
    cfg = _v168_awards_cfg(chat_id) if '_v168_awards_cfg' in globals() else admin_cfg(chat_id)
    kinds = [
        ('pareja', 'awards_pair_enabled', '💞'), ('parlante', 'awards_parlante_enabled', '🗣'),
        ('risas', 'awards_risas_enabled', '😂'), ('holi', 'awards_holi_enabled', '👋'),
        ('noctambulo', 'awards_noctambulo_enabled', '🌙'), ('competidor', 'awards_competidor_enabled', '🎮')
    ]
    lines = [f'🏆 <b>PREMIOS DEL {suffix}</b>', '']
    for kind, flag, ico in kinds:
        if not bool(cfg.get(flag, True)):
            continue
        e = _v237_best_award(chat_id, kind, period)
        val = int(e.get('value', 0) or 0)
        if e.get('winner') and e.get('winner') != 'Sin datos' and val > 0:
            lines.append(f'{ico} <b>{h(e.get("label", kind))}</b>: {h(e.get("winner"))} · <b>{val}</b>')
            lines.append(f'   <i>{h(e.get("why", ""))}</i>')
        else:
            lines.append(f'{ico} <b>{h(e.get("label", kind))}</b>: sin datos suficientes')
    return '\n'.join(lines)


def _v167_awards_calculate(chat_id: int, *, weekly: bool = False) -> str:
    return _v237_awards_calculate(int(chat_id), weekly=weekly)

async def _v167_send_awards(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, weekly: bool = False) -> None:
    await context.bot.send_message(chat_id, _v237_awards_calculate(int(chat_id), weekly=weekly), parse_mode=ParseMode.HTML)


