def _v237_rblk_defaults(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        _v173_rec_block_defaults(b)
    except Exception:
        pass
    b.setdefault('repeat_enabled', False)
    b.setdefault('repeat_every_minutes', 120)
    b.setdefault('repeat_until', b.get('time', '23:59') or '23:59')
    b.setdefault('last_sent_slot', '')
    return b


def _v237_hhmm(s: str) -> Optional[str]:
    try:
        m = _v237_re.search(r'\b([0-2]?\d):([0-5]\d)\b', str(s or ''))
        if not m: return None
        hh = int(m.group(1)); mm = int(m.group(2))
        if hh > 23: return None
        return f'{hh:02d}:{mm:02d}'
    except Exception:
        return None


def _v237_min(hm: str) -> Optional[int]:
    hm = _v237_hhmm(hm) or ''
    if not hm: return None
    h0, m0 = hm.split(':')
    return int(h0) * 60 + int(m0)


def _v237_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    _v237_rblk_defaults(b)
    if not bool(b.get('enabled')):
        return False, ''
    if str(b.get('mode', 'daily')) not in ('daily', 'repeat'):
        return False, ''
    now_ts = int(now_ts or time.time())
    now = time.localtime(now_ts)
    now_min = now.tm_hour * 60 + now.tm_min
    start = _v237_min(str(b.get('time', '21:00'))) or 21 * 60
    today = time.strftime('%Y-%m-%d', now)
    if bool(b.get('repeat_enabled')):
        until = _v237_min(str(b.get('repeat_until', '23:59'))) or (23 * 60 + 59)
        every = max(1, int(b.get('repeat_every_minutes', 120) or 120))
        if until < start:
            until += 24 * 60
        check_min = now_min
        if check_min < start and until >= 24 * 60:
            check_min += 24 * 60
        if not (start <= check_min <= until):
            return False, ''
        if (check_min - start) % every != 0:
            return False, ''
        slot = f'{today}|{check_min % (24*60):04d}'
        return str(b.get('last_sent_slot', '')) != slot, slot
    else:
        if now_min != start:
            return False, ''
        slot = f'{today}|{start:04d}'
        return str(b.get('last_sent_slot', '')) != slot and str(b.get('last_sent_day', '')) != today, slot


def _v209_rec_block_summary_line(chat_id: int, b: Dict[str, Any]) -> str:
    _v237_rblk_defaults(b)
    enabled = 'ON' if bool(b.get('enabled')) else 'OFF'
    time_s = _v237_hhmm(str(b.get('time', '21:00'))) or '21:00'
    ids = _v181_extract_rids_from_block(b) if '_v181_extract_rids_from_block' in globals() else [int(x) for x in (b.get('items') or []) if str(x).isdigit()]
    if bool(b.get('repeat_enabled')):
        return f'Auto: <b>{enabled}</b> · Inicio: <b>{h(time_s)}</b> · Cada: <b>{int(b.get("repeat_every_minutes",120) or 120)} min</b> · Hasta: <b>{h(str(b.get("repeat_until","23:59")))}</b> · Recurrentes: <b>{len(ids)}</b>'
    return f'Auto: <b>{enabled}</b> · Hora: <b>{h(time_s)}</b> · Repetición bloque: <b>OFF</b> · Recurrentes: <b>{len(ids)}</b>'


_old_v237_rblk_markup = _v171_rec_block_markup
def _v171_rec_block_markup(chat_id: int, bid: int) -> InlineKeyboardMarkup:
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    if not b:
        return _old_v237_rblk_markup(chat_id, bid)
    _v237_rblk_defaults(b)
    rows = list(_old_v237_rblk_markup(chat_id, bid).inline_keyboard)

    insert_at = 3 if len(rows) >= 3 else len(rows)
    extra = [
        [InlineKeyboardButton(f"🔁 Repetir bloque {'ON' if b.get('repeat_enabled') else 'OFF'}", callback_data=f'cfg|rblk_repeat_toggle|{chat_id}|{bid}')],
        [InlineKeyboardButton(f"⏱ Cada {int(b.get('repeat_every_minutes',120) or 120)} min", callback_data=f'cfg|rblk_repeat_every|{chat_id}|{bid}'), InlineKeyboardButton(f"🛑 Hasta {b.get('repeat_until','23:59')}", callback_data=f'cfg|rblk_repeat_until|{chat_id}|{bid}')],
    ]
    return InlineKeyboardMarkup(rows[:insert_at] + extra + rows[insert_at:])


async def _v237_rblk_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rblk_repeat_'):
        return
    parts = (q.data or '').split('|')
    action = parts[1]
    chat_id = int(parts[2]); bid = int(parts[3])
    b = _v171_rec_block_find(chat_id, bid)
    if not b:
        await q.answer('Bloque no encontrado', show_alert=True); raise _V237Stop
    _v237_rblk_defaults(b)
    if action == 'rblk_repeat_toggle':
        b['repeat_enabled'] = not bool(b.get('repeat_enabled'))
        if b['repeat_enabled']:
            b['mode'] = 'daily'; b['enabled'] = True
        save_all_states()
        await q.answer('Repetición actualizada')
        await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid))
        raise _V237Stop
    if action in ('rblk_repeat_every', 'rblk_repeat_until'):
        set_config_pending(q.from_user.id, {'kind': action + '_v237', 'chat_id': chat_id, 'bid': bid})
        txt = '⏱ Envíame cada cuántos minutos debe repetirse el bloque. Ejemplo: <code>60</code>, <code>120</code>, <code>180</code>.' if action == 'rblk_repeat_every' else '🛑 Envíame la hora final hasta la que puede repetirse el bloque. Ejemplo: <code>23:30</code>.'
        await q.answer()
        await q.message.reply_html(txt)
        raise _V237Stop


_old_v237_private_text_router = _v209_private_text_router if '_v209_private_text_router' in globals() else None
async def _v237_private_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not pending or str(pending.get('kind','')) not in ('rblk_repeat_every_v237','rblk_repeat_until_v237','cfg_phrase_buttons_v237'):
        if callable(_old_v237_private_text_router):
            return await _old_v237_private_text_router(update, context)
        return
    kind = str(pending.get('kind'))
    chat_id = int(pending.get('chat_id') or 0)
    text = (update.message.text or update.message.caption or '').strip()
    if kind.startswith('rblk_'):
        bid = int(pending.get('bid') or 0)
        b = _v171_rec_block_find(chat_id, bid)
        if not b:
            pop_config_pending(update.effective_user.id); await update.message.reply_html('❌ No encuentro ese bloque.'); raise _V237Stop
        _v237_rblk_defaults(b)
        if kind == 'rblk_repeat_every_v237':
            m = _v237_re.search(r'\d+', text or '')
            if not m:
                await update.message.reply_html('❌ Envía un número de minutos. Ejemplo: <code>120</code>')
                raise _V237Stop
            b['repeat_every_minutes'] = max(1, int(m.group(0)))
            b['repeat_enabled'] = True; b['enabled'] = True; b['mode'] = 'daily'
        else:
            hm = _v237_hhmm(text)
            if not hm:
                await update.message.reply_html('❌ Hora no válida. Usa <code>HH:MM</code>.')
                raise _V237Stop
            b['repeat_until'] = hm
            b['repeat_enabled'] = True; b['enabled'] = True; b['mode'] = 'daily'
        save_all_states(); pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Repetición del bloque actualizada.\n\n' + _v171_rec_block_text(chat_id, bid), reply_markup=_v171_rec_block_markup(chat_id, bid))
        raise _V237Stop
    if kind == 'cfg_phrase_buttons_v237':
        if text.upper() in ('QUITAR','BORRAR','SIN BOTONES','NO'):
            cfg_set(chat_id, 'daily_phrase_extra_buttons', [])
        else:
            buttons = parse_buttons_text(text) if 'parse_buttons_text' in globals() else []
            if not buttons:
                await update.message.reply_html('❌ No he detectado botones. Usa formato: <code>Texto - https://enlace.com</code>')
                raise _V237Stop
            cfg_set(chat_id, 'daily_phrase_extra_buttons', buttons)
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Botones extra actualizados.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        raise _V237Stop


async def _v237_rblk_scheduler(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        now_ts = int(time.time())
        for chat_id in list(STATE_CACHE.keys()):
            for b in _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []:
                try:
                    due, slot = _v237_block_due(b, now_ts)
                    if not due: continue
                    ok, total, errors = await _v209_send_rec_block_at_schedule(context, int(chat_id), b) if '_v209_send_rec_block_at_schedule' in globals() else (0,0,[])
                    b['last_sent_slot'] = slot
                    if not bool(b.get('repeat_enabled')):
                        b['last_sent_day'] = time.strftime('%Y-%m-%d', time.localtime(now_ts))
                    save_all_states()
                    logger.info('V237 bloque recurrente chat=%s bid=%s ok=%s/%s slot=%s', chat_id, b.get('id'), ok, total, slot)
                except Exception:
                    logger.exception('V237 error bloque recurrente chat=%s block=%s', chat_id, b)
    except Exception:
        logger.exception('V237 scheduler bloques recurrentes falló')


