def _v237_next_recurring_time(chat_id: int) -> str:
    try:
        if '_v176_next_recurring_time' in globals():
            return str(_v176_next_recurring_time(int(chat_id)))
    except Exception:
        pass
    return '--:--'


def _v237_next_block_time(chat_id: int) -> str:
    try:
        vals = []
        now_min = time.localtime().tm_hour * 60 + time.localtime().tm_min
        for b in _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []:
            _v237_rblk_defaults(b)
            if not bool(b.get('enabled')): continue
            hm = _v237_hhmm(str(b.get('time','')))
            if not hm: continue
            mn = _v237_min(hm) or 0
            delta = (mn - now_min) % (24*60)
            vals.append((delta, hm))
        if vals:
            return sorted(vals)[0][1]
    except Exception:
        pass
    return '--:--'


