_old_build_application_v237 = build_application
def build_application() -> Application:
    app = _old_build_application_v237()
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption() | filters.PHOTO | filters.VIDEO | filters.Document.ALL | filters.AUDIO | filters.VOICE) & ~filters.COMMAND, _v167_collect_awards_stats), group=-37000000000)
    app.add_handler(CallbackQueryHandler(_v237_rblk_router, pattern=r'^cfg\|rblk_repeat_'), group=-37000000000)
    app.add_handler(CallbackQueryHandler(_v237_phrase_buttons_router, pattern=r'^cfg\|phrase_buttons\|'), group=-37000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v237_private_text_router), group=-37000000000)
    try:
        if getattr(app, 'job_queue', None):
            app.job_queue.run_repeating(_v237_rblk_scheduler, interval=30, first=8, name='v237_rblk_repeat_scheduler')
    except Exception:
        logger.exception('V237 no pudo iniciar scheduler de bloques con repetición')
    logger.info('V237 cargado: premios reales, bloques recurrentes con repetición, resumen IA y frase ajustada')
    return app


BOT_VERSION = "V238"

try:
    from telegram.ext import ApplicationHandlerStop as _V238Stop
except Exception:
    _V238Stop = Exception


_old_v238_summary_value = _v233_summary_value if '_v233_summary_value' in globals() else None

def _v233_summary_value(chat_id: int, key: str) -> str:
    """Valor único para cualquier campo del resumen.

    En V237 los campos antiguos llamaban a una función que no existía en V233 y
    devolvían cadena vacía. Aquí se fuerza fallback a _v232_short_raw_value().
    """
    chat_id = int(chat_id)
    try:

        if key == 'ai_commands_status':
            return 'ON' if _v237_ai_cmd_count(chat_id) > 0 else 'OFF'
        if key == 'ai_commands_count':
            return str(_v237_ai_cmd_count(chat_id))
        if key == 'next_recurring_full':
            v = _v237_next_recurring_time(chat_id)
            return v if v and v not in ('--:--', '—') else _v233_next_recurrent(chat_id)
        if key == 'next_block_full':
            v = _v237_next_block_time(chat_id)
            return v if v and v not in ('--:--', '—') else _v233_next_block(chat_id)
        if key == 'daily_phrase_time_full':
            return str(cfg_value(chat_id, 'daily_phrase_time', '10:00') or '10:00')[:5]


        if '_v232_short_raw_value' in globals():
            v = _v232_short_raw_value(chat_id, key)
            if v is not None and str(v) != '':
                return str(v)


        if callable(_old_v238_summary_value):
            v = _old_v238_summary_value(chat_id, key)
            if v is not None and str(v) != '':
                return str(v)
    except Exception:
        logger.exception('V238 error obteniendo valor resumen %s', key)
    return '—'


