async def _v238_collect_awards_stats(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Recolector estable para premios.

    No detiene otros módulos. Cuenta todos los mensajes humanos: texto, multimedia,
    audios, respuestas, etc. Guarda siempre para que la vista del menú de premios
    se actualice inmediatamente al abrirlo.
    """
    try:
        if not update.effective_chat or not update.effective_user or not update.message:
            return
        if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
            return
        chat_id = int(update.effective_chat.id)
        if not chat_is_allowed(chat_id):
            return
        if not _v238_is_awards_enabled(chat_id):
            return

        msg_id = int(getattr(update.message, 'message_id', 0) or 0)
        day = _v238_day_stats(chat_id)
        seen = day.setdefault('seen', [])
        seen_key = str(msg_id)
        if seen_key in seen:
            return
        seen.append(seen_key)
        if len(seen) > 5000:
            del seen[:-5000]

        user = update.effective_user
        uid = str(int(user.id))
        txt = (getattr(update.message, 'text', None) or getattr(update.message, 'caption', None) or '').strip()
        row = day.setdefault('users', {}).setdefault(uid, {
            'name': display_name(user),
            'username': getattr(user, 'username', '') or '',
            'messages': 0,
            'risas': 0,
            'holas': 0,
            'media': 0,
            'hours': {},
        })
        row['name'] = display_name(user)
        row['username'] = getattr(user, 'username', '') or ''
        row['messages'] = int(row.get('messages', 0) or 0) + 1

        if any(getattr(update.message, attr, None) for attr in ('photo','video','animation','document','audio','voice','sticker')):
            row['media'] = int(row.get('media', 0) or 0) + 1

        if txt:
            row['risas'] = int(row.get('risas', 0) or 0) + len(_V237_LAUGH_RE.findall(txt))
            if _V237_HELLO_RE.search(txt):
                row['holas'] = int(row.get('holas', 0) or 0) + 1

        try:
            dt = getattr(update.message, 'date', None)
            ts = int(dt.timestamp()) if dt else int(time.time())
        except Exception:
            ts = int(time.time())
        hh = time.strftime('%H', time.localtime(ts))
        row.setdefault('hours', {})[hh] = int(row.setdefault('hours', {}).get(hh, 0) or 0) + 1

        reply_user = getattr(getattr(update.message, 'reply_to_message', None), 'from_user', None)
        if reply_user and not getattr(reply_user, 'is_bot', False) and int(reply_user.id) != int(user.id):
            a, b = sorted([str(int(user.id)), str(int(reply_user.id))])
            pk = f'{a}:{b}'
            pr = day.setdefault('pairs', {}).setdefault(pk, {'a': a, 'b': b, 'count': 0, 'names': {}})
            pr['count'] = int(pr.get('count', 0) or 0) + 1
            pr.setdefault('names', {})[str(int(user.id))] = display_name(user)
            pr.setdefault('names', {})[str(int(reply_user.id))] = display_name(reply_user)

        try:
            remember_member_activity(chat_id, user, kind='message', source='awards_v238')
        except Exception:
            pass
        save_all_states()
    except Exception:
        logger.exception('V238: fallo recolectando estadísticas de premios')


def _v238_merge_roots_for_period(chat_id: int, period: str = 'daily') -> tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    """Fusiona estadísticas antiguas + V238 para no perder histórico."""
    days = _v237_week_days() if str(period).lower().startswith(('week','sem')) else [_v237_day_key()]
    roots: List[Dict[str, Any]] = []
    try:
        old_root = _v237_awards_stats_root(int(chat_id)) if '_v237_awards_stats_root' in globals() else {}
        if isinstance(old_root, dict):
            roots.append(old_root)
    except Exception:
        pass
    try:
        new_root = _v238_awards_root(int(chat_id))
        if isinstance(new_root, dict):
            roots.append(new_root)
    except Exception:
        pass

    users: Dict[str, Dict[str, Any]] = {}
    pairs: Dict[str, Dict[str, Any]] = {}
    for root in roots:
        for dk in days:
            day = root.get(dk, {}) if isinstance(root, dict) else {}
            for uid, src in (day.get('users', {}) or {}).items():
                dst = users.setdefault(str(uid), {'name': src.get('name') or str(uid), 'username': src.get('username',''), 'messages': 0, 'risas': 0, 'holas': 0, 'media': 0, 'hours': {}})
                dst['name'] = src.get('name') or dst.get('name') or str(uid)
                dst['username'] = src.get('username', dst.get('username',''))
                for k in ('messages','risas','holas','media'):
                    dst[k] = int(dst.get(k, 0) or 0) + int(src.get(k, 0) or 0)
                for hh, c in (src.get('hours', {}) or {}).items():
                    dst.setdefault('hours', {})[str(hh)] = int(dst.setdefault('hours', {}).get(str(hh), 0) or 0) + int(c or 0)
            for pk, src in (day.get('pairs', {}) or {}).items():
                dst = pairs.setdefault(str(pk), {'count': 0, 'names': {}, 'a': src.get('a'), 'b': src.get('b')})
                dst['count'] = int(dst.get('count', 0) or 0) + int(src.get('count', 0) or 0)
                dst.setdefault('names', {}).update(src.get('names') or {})
                if src.get('a'): dst['a'] = src.get('a')
                if src.get('b'): dst['b'] = src.get('b')
    return users, pairs


def _v237_merge_award_period(chat_id: int, period: str = 'daily') -> tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    return _v238_merge_roots_for_period(int(chat_id), period)


_old_v238_awards_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    if block == 'awards':
        cfg = _v238_awards_cfg(int(chat_id))
        kinds = [('parlante','🗣'),('risas','😂'),('pareja','💞'),('holi','👋'),('noctambulo','🌙'),('competidor','🎮')]
        users, pairs = _v237_merge_award_period(int(chat_id), 'daily')
        lines = [
            '<b>🏆 Premios sociales</b>',
            '',
            f"Estado: <b>{'ON' if cfg.get('awards_enabled', True) else 'OFF'}</b>",
            f"Datos hoy: <b>{len(users)}</b> miembros · <b>{sum(int(u.get('messages',0) or 0) for u in users.values())}</b> mensajes · <b>{len(pairs)}</b> parejas",
            '',
            '<b>📌 Si lanzas ahora, saldría:</b>'
        ]
        for k, ico in kinds:
            e = _v237_best_award(int(chat_id), k, 'daily')
            lines.append(f'{ico} {h(e.get("label", k))}: <b>{h(e.get("winner", "Sin datos"))}</b> · {h(e.get("value", 0))}')
        lines.extend([
            '',
            '<i>Los datos se actualizan con cada mensaje del grupo. Parlante = más mensajes. Risas = jajaja/emojis. Pareja = respuestas entre dos miembros. Holi = saludos. Noctámbulo = más franjas horarias distintas.</i>'
        ])
        return '\n'.join(lines)
    return _old_v238_awards_block_text(int(chat_id), block, page)


_old_build_application_v238 = build_application

def build_application() -> Application:
    app = _old_build_application_v238()

    app.add_handler(MessageHandler((filters.TEXT | filters.Caption() | filters.PHOTO | filters.VIDEO | filters.Document.ALL | filters.AUDIO | filters.VOICE | filters.Sticker.ALL) & ~filters.COMMAND, _v238_collect_awards_stats), group=-88000000000)
    logger.info('V238 cargado: resumen con valores reales y premios sociales actualizados en tiempo real')
    return app


BOT_VERSION = "V239"

try:
    import re as _v239_re
    import time as _v239_time
except Exception:
    pass

_V239_LAUGH_RE = _v239_re.compile(r"(j+a+j+a+|j+e+j+e+|j+i+j+i+|ja{2,}|je{2,}|jeje+|jaja+|😂|🤣|😹|😆|😅|😄|😁|😜|😝)", _v239_re.I)
_V239_HELLO_RE = _v239_re.compile(r"\b(hola+|holi+|holaa+|holaaa+|buenas+|buenos\s+d[ií]as|buenas\s+tardes|buenas\s+noches|hey+|hello+|hi+)\b", _v239_re.I)


def _v239_now_ts() -> int:
    try:
        return _now_ts() if '_now_ts' in globals() else int(_v239_time.time())
    except Exception:
        return int(_v239_time.time())


def _v239_day_key(ts: Optional[int] = None) -> str:
    try:
        return _v239_time.strftime('%Y-%m-%d', _v239_time.localtime(int(ts or _v239_now_ts())))
    except Exception:
        return _v239_time.strftime('%Y-%m-%d')


def _v239_week_keys() -> List[str]:
    now = _v239_now_ts()
    try:
        tm = _v239_time.localtime(now)

        start = now - int(tm.tm_wday) * 86400
        return [_v239_day_key(start + i * 86400) for i in range(7)]
    except Exception:
        return [_v239_day_key()]


def _v239_bool(value: Any) -> str:
    return 'ON' if bool(value) else 'OFF'


def _v239_hhmm(value: Any, default: str = '—') -> str:
    s = str(value or '').strip()
    if not s:
        return default
    m = _v239_re.search(r'([0-2]?\d:[0-5]\d)', s)
    if not m:
        return default if s in ('--:--', '—') else s[:5]
    hhmm = m.group(1)
    hhh, mm = hhmm.split(':', 1)
    try:
        return f'{int(hhh):02d}:{int(mm):02d}'
    except Exception:
        return hhmm.zfill(5)


def _v239_stats_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    root = cfg.setdefault('v239_stats', {})
    root.setdefault('days', {})
    return root


def _v239_day_record(chat_id: int, day_key: Optional[str] = None) -> Dict[str, Any]:
    root = _v239_stats_cfg(int(chat_id))
    day = root.setdefault('days', {}).setdefault(day_key or _v239_day_key(), {
        'users': {},
        'pairs': {},
        'seen': [],
        'total_messages': 0,
        'media_messages': 0,
    })
    day.setdefault('users', {})
    day.setdefault('pairs', {})
    day.setdefault('seen', [])
    day.setdefault('total_messages', 0)
    day.setdefault('media_messages', 0)
    return day


async def _v239_collect_group_stats(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Recolector único y temprano.

    No responde, no detiene otros módulos y sólo guarda datos. Cuenta texto, multimedia,
    respuestas, stickers, audios, vídeos y documentos para premios/resumen.
    """
    try:
        if not update.effective_chat or not update.effective_user or not update.message:
            return
        if update.effective_chat.type == 'private' or getattr(update.effective_user, 'is_bot', False):
            return
        chat_id = int(update.effective_chat.id)
        if not chat_is_allowed(chat_id):
            return
        user = update.effective_user
        msg = update.message
        msg_id = int(getattr(msg, 'message_id', 0) or 0)
        if msg_id <= 0:
            return


        try:
            dt = getattr(msg, 'date', None)
            ts = int(dt.timestamp()) if dt else _v239_now_ts()
        except Exception:
            ts = _v239_now_ts()
        day = _v239_day_record(chat_id, _v239_day_key(ts))
        seen = day.setdefault('seen', [])
        skey = str(msg_id)
        if skey in seen:
            return
        seen.append(skey)
        if len(seen) > 15000:
            del seen[:-15000]

        uid = str(int(user.id))
        text = (getattr(msg, 'text', None) or getattr(msg, 'caption', None) or '').strip()
        is_media = any(getattr(msg, attr, None) for attr in ('photo','video','animation','document','audio','voice','sticker'))
        hour = _v239_time.strftime('%H', _v239_time.localtime(ts))

        day['total_messages'] = int(day.get('total_messages', 0) or 0) + 1
        if is_media:
            day['media_messages'] = int(day.get('media_messages', 0) or 0) + 1

        users = day.setdefault('users', {})
        row = users.setdefault(uid, {
            'user_id': int(user.id),
            'name': display_name(user),
            'username': getattr(user, 'username', '') or '',
            'messages': 0,
            'media': 0,
            'risas': 0,
            'holas': 0,
            'hours': {},
            'replies_given': 0,
            'replies_received': 0,
        })
        row['user_id'] = int(user.id)
        row['name'] = display_name(user)
        row['username'] = getattr(user, 'username', '') or ''
        row['messages'] = int(row.get('messages', 0) or 0) + 1
        if is_media:
            row['media'] = int(row.get('media', 0) or 0) + 1
        if text:
            row['risas'] = int(row.get('risas', 0) or 0) + len(_V239_LAUGH_RE.findall(text))
            if _V239_HELLO_RE.search(text):
                row['holas'] = int(row.get('holas', 0) or 0) + 1
        row.setdefault('hours', {})[hour] = int(row.setdefault('hours', {}).get(hour, 0) or 0) + 1

        reply_user = getattr(getattr(msg, 'reply_to_message', None), 'from_user', None)
        if reply_user and not getattr(reply_user, 'is_bot', False) and int(reply_user.id) != int(user.id):
            rid = str(int(reply_user.id))

            rrow = users.setdefault(rid, {
                'user_id': int(reply_user.id),
                'name': display_name(reply_user),
                'username': getattr(reply_user, 'username', '') or '',
                'messages': 0,
                'media': 0,
                'risas': 0,
                'holas': 0,
                'hours': {},
                'replies_given': 0,
                'replies_received': 0,
            })
            rrow['name'] = display_name(reply_user)
            rrow['username'] = getattr(reply_user, 'username', '') or ''
            row['replies_given'] = int(row.get('replies_given', 0) or 0) + 1
            rrow['replies_received'] = int(rrow.get('replies_received', 0) or 0) + 1
            a, b = sorted([uid, rid])
            pk = f'{a}:{b}'
            pair = day.setdefault('pairs', {}).setdefault(pk, {'a': a, 'b': b, 'count': 0, 'names': {}})
            pair['count'] = int(pair.get('count', 0) or 0) + 1
            pair.setdefault('names', {})[uid] = display_name(user)
            pair.setdefault('names', {})[rid] = display_name(reply_user)

        try:
            remember_member_activity(chat_id, user, kind='message', source='v239_stats')
        except Exception:
            pass
        save_all_states()
    except Exception:
        logger.exception('V239: fallo recolectando estadísticas de grupo')


def _v239_merge_period(chat_id: int, period: str = 'daily') -> Tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]], Dict[str, int]]:
    days = _v239_week_keys() if str(period).lower().startswith(('week','sem')) else [_v239_day_key()]
    users: Dict[str, Dict[str, Any]] = {}
    pairs: Dict[str, Dict[str, Any]] = {}
    totals = {'messages': 0, 'media': 0}


    roots: List[Dict[str, Any]] = []
    try:
        roots.append(_v239_stats_cfg(int(chat_id)).get('days', {}))
    except Exception:
        pass
    try:
        if '_v238_awards_root' in globals():
            roots.append(_v238_awards_root(int(chat_id)))
    except Exception:
        pass
    try:
        if '_v237_awards_stats_root' in globals():
            roots.append(_v237_awards_stats_root(int(chat_id)))
    except Exception:
        pass

    for root in roots:
        if not isinstance(root, dict):
            continue
        for dk in days:
            day = root.get(dk, {}) if isinstance(root.get(dk, {}), dict) else {}
            totals['messages'] += int(day.get('total_messages', day.get('total', 0)) or 0)
            totals['media'] += int(day.get('media_messages', day.get('media', 0)) or 0)
            for uid, src in (day.get('users', {}) or {}).items():
                uid = str(uid)
                dst = users.setdefault(uid, {
                    'user_id': int(src.get('user_id') or uid) if str(uid).isdigit() else 0,
                    'name': src.get('name') or str(uid),
                    'username': src.get('username',''),
                    'messages': 0,
                    'media': 0,
                    'risas': 0,
                    'holas': 0,
                    'hours': {},
                    'replies_given': 0,
                    'replies_received': 0,
                })
                dst['name'] = src.get('name') or dst.get('name') or str(uid)
                dst['username'] = src.get('username', dst.get('username',''))
                for k in ('messages','media','risas','holas','replies_given','replies_received'):
                    dst[k] = int(dst.get(k, 0) or 0) + int(src.get(k, 0) or 0)
                for hh, c in (src.get('hours', {}) or {}).items():
                    dst.setdefault('hours', {})[str(hh)] = int(dst.setdefault('hours', {}).get(str(hh), 0) or 0) + int(c or 0)
            for pk, src in (day.get('pairs', {}) or {}).items():
                dst = pairs.setdefault(str(pk), {'a': src.get('a'), 'b': src.get('b'), 'count': 0, 'names': {}})
                dst['count'] = int(dst.get('count', 0) or 0) + int(src.get('count', 0) or 0)
                dst.setdefault('names', {}).update(src.get('names') or {})
                if src.get('a'): dst['a'] = str(src.get('a'))
                if src.get('b'): dst['b'] = str(src.get('b'))
    if totals['messages'] <= 0:
        totals['messages'] = sum(int(u.get('messages', 0) or 0) for u in users.values())
    if totals['media'] <= 0:
        totals['media'] = sum(int(u.get('media', 0) or 0) for u in users.values())
    return users, pairs, totals


def _v239_award_label(kind: str) -> str:
    return {
        'parlante': 'Más parlante',
        'risas': 'El que más se ríe',
        'pareja': 'Pareja del día',
        'holi': 'Holi holi',
        'noctambulo': 'Noctámbulo',
        'competidor': 'Más competidor',
    }.get(str(kind), str(kind))


def _v239_best_award(chat_id: int, kind: str, period: str = 'daily') -> Dict[str, Any]:
    users, pairs, _totals = _v239_merge_period(int(chat_id), period)
    label = _v239_award_label(kind)
    if kind == 'pareja':
        if not pairs:
            return {'kind': kind, 'label': label, 'winner': 'Sin datos', 'value': 0, 'reason': 'Aún no hay respuestas entre miembros registradas.'}
        pk, p = max(pairs.items(), key=lambda item: int(item[1].get('count', 0) or 0))
        names = p.get('names') or {}
        a = str(p.get('a') or '').strip()
        b = str(p.get('b') or '').strip()
        n1 = names.get(a) or users.get(a, {}).get('name') or a
        n2 = names.get(b) or users.get(b, {}).get('name') or b
        value = int(p.get('count', 0) or 0)
        return {'kind': kind, 'label': label, 'winner': f'{n1} + {n2}', 'value': value, 'reason': f'Han interactuado entre ellos mediante respuestas {value} veces.'}

    metric = 'messages'
    reason_name = 'mensajes enviados'
    if kind == 'risas':
        metric = 'risas'; reason_name = 'mensajes/rastros de risa'
    elif kind == 'holi':
        metric = 'holas'; reason_name = 'saludos detectados'
    elif kind == 'noctambulo':

        candidates = []
        for uid, u in users.items():
            hours = len([h for h, c in (u.get('hours') or {}).items() if int(c or 0) > 0])
            msg_count = int(u.get('messages', 0) or 0)
            if hours > 0:
                candidates.append((hours, msg_count, uid, u))
        if not candidates:
            return {'kind': kind, 'label': label, 'winner': 'Sin datos', 'value': 0, 'reason': 'Aún no hay suficientes franjas horarias registradas.'}
        hours, msg_count, uid, u = max(candidates, key=lambda x: (x[0], x[1]))
        return {'kind': kind, 'label': label, 'winner': u.get('name') or uid, 'value': hours, 'reason': f'Ha escrito en {hours} franjas horarias diferentes.'}
    elif kind == 'competidor':

        metric = 'replies_given'; reason_name = 'interacciones/respuestas registradas'

    candidates = [(int(u.get(metric, 0) or 0), int(u.get('messages', 0) or 0), uid, u) for uid, u in users.items()]
    candidates = [c for c in candidates if c[0] > 0]
    if not candidates:
        return {'kind': kind, 'label': label, 'winner': 'Sin datos', 'value': 0, 'reason': f'Aún no hay {reason_name} suficientes.'}
    value, _msg_count, uid, u = max(candidates, key=lambda x: (x[0], x[1]))
    return {'kind': kind, 'label': label, 'winner': u.get('name') or uid, 'value': value, 'reason': f'Destaca con {value} {reason_name} en el periodo.'}


def _v237_merge_award_period(chat_id: int, period: str = 'daily') -> tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    users, pairs, _totals = _v239_merge_period(int(chat_id), period)
    return users, pairs


