def _v239_msg_counts(chat_id: int) -> Tuple[int, int]:
    users_d, pairs_d, totals_d = _v239_merge_period(int(chat_id), 'daily')
    users_w, pairs_w, totals_w = _v239_merge_period(int(chat_id), 'weekly')
    day = int(totals_d.get('messages', 0) or 0)
    week = int(totals_w.get('messages', 0) or 0)
    if day <= 0 or week <= 0:
        try:
            if '_v233_msg_counts' in globals():
                d2, w2 = _v233_msg_counts(int(chat_id))
                day = max(day, int(d2 or 0)); week = max(week, int(w2 or 0))
        except Exception:
            pass
    return day, week


def _v239_media_day(chat_id: int) -> int:
    _users, _pairs, totals = _v239_merge_period(int(chat_id), 'daily')
    val = int(totals.get('media', 0) or 0)
    if val <= 0:
        try:
            val = int(_v233_media_day_count(int(chat_id)) if '_v233_media_day_count' in globals() else 0)
        except Exception:
            val = 0
    return val


