BOT_VERSION = 'V240'

try:
    from telegram.ext import ApplicationHandlerStop as _V240Stop
except Exception:
    _V240Stop = Exception

import time as _v240_time
from datetime import datetime as _v240_datetime


async def _v240_can_validate_silent(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> bool:
    try:
        fn = globals().get('_v220_can_validate') or globals().get('can_validate_presentation')
        if callable(fn):
            return bool(await fn(context, int(chat_id), int(user_id)))
    except Exception:
        pass
    try:
        if '_v219_is_owner' in globals() and _v219_is_owner(int(user_id)):
            return True
        if int(user_id) in ADMIN_IDS:
            return True
        return bool(await is_admin(context, int(chat_id), int(user_id)))
    except Exception:
        return False

async def _v240_validation_silent_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not (data.startswith('val|') or data.startswith('valreq|') or data.startswith('cfg|pendapprove|') or data.startswith('cfg|pendkick|')):
        return
    chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not chat_id:
        return
    allowed = await _v240_can_validate_silent(context, chat_id, int(update.effective_user.id))
    if allowed:
        return

    try:
        await q.answer()
    except Exception:
        pass
    raise _V240Stop

async def _v240_validation_permissions_report(context: ContextTypes.DEFAULT_TYPE, chat_id: int, viewer_id: Optional[int] = None) -> str:
    lines: List[str] = []
    state = get_state(int(chat_id))
    try:
        bot_user = await context.bot.get_me()
        bot_member = await context.bot.get_chat_member(int(chat_id), bot_user.id)
        status = getattr(bot_member, 'status', '')
        can_restrict = bool(getattr(bot_member, 'can_restrict_members', False)) or status == 'creator'
        can_delete = bool(getattr(bot_member, 'can_delete_messages', False)) or status == 'creator'
        can_invite = bool(getattr(bot_member, 'can_invite_users', False)) or status == 'creator'
        can_pin = bool(getattr(bot_member, 'can_pin_messages', False)) or status == 'creator'
        can_send = getattr(bot_member, 'can_send_messages', None)
        can_send_ok = True if status in ('administrator','creator') else bool(can_send)
    except Exception as e:
        status = 'ERROR'
        can_restrict = can_delete = can_invite = can_pin = can_send_ok = False
        lines.append(f'❌ No pude leer permisos del bot: <code>{h(str(e)[:300])}</code>')

    qs = cfg_questions(int(chat_id))
    answering = sum(1 for r in state.validation_users.values() if r.get('status') == 'answering')
    pending = sum(1 for r in state.validation_users.values() if r.get('status') == 'pending_admin')
    timeout = sum(1 for r in state.validation_users.values() if r.get('status') in ('timeout','kicked_timeout'))
    stuck_admins = 0
    for uid, rec in list(state.validation_users.items()):
        if rec.get('status') in ('answering','pending_admin','timeout'):
            try:
                m = await context.bot.get_chat_member(int(chat_id), int(uid))
                if getattr(m, 'status', '') in ('administrator','creator'):
                    stuck_admins += 1
            except Exception:
                pass
    viewer_can = await _v240_can_validate_silent(context, int(chat_id), int(viewer_id or 0)) if viewer_id else False
    lines.extend([
        '<b>🧪 Comprobación de validación V240</b>',
        '',
        f'Grupo autorizado: <b>{bool_label(chat_is_allowed(int(chat_id)))}</b>',
        f'Validación activa: <b>{bool_label(validation_is_active_for_chat(int(chat_id)) if "validation_is_active_for_chat" in globals() else cfg_value(int(chat_id), "validation_enabled", False))}</b>',
        f'Preguntas: <b>{len(qs)}</b>',
        f'Tiempo límite: <b>{h(cfg_value(int(chat_id), "validation_timeout_minutes", "—"))} min</b>',
        f'Expulsa por timeout: <b>{bool_label(cfg_value(int(chat_id), "validation_kick_if_timeout", False))}</b>',
        '',
        '<b>Permisos del bot</b>',
        f'Estado bot: <b>{h(status)}</b>',
        f'Puede enviar: <b>{bool_label(can_send_ok)}</b>',
        f'Puede restringir/banear: <b>{bool_label(can_restrict)}</b>',
        f'Puede borrar: <b>{bool_label(can_delete)}</b>',
        f'Puede aprobar solicitudes: <b>{bool_label(can_invite)}</b>',
        f'Puede fijar: <b>{bool_label(can_pin)}</b>',
        '',
        '<b>Estado interno</b>',
        f'Respondiendo: <b>{answering}</b>',
        f'Pendientes admin: <b>{pending}</b>',
        f'Timeouts/expulsión: <b>{timeout}</b>',
        f'Admins atascados: <b>{stuck_admins}</b>',
        f'Tu permiso para validar: <b>{bool_label(viewer_can)}</b>' if viewer_id else '',
        '',
        '<b>Resultado esperado</b>',
        '1) Entra usuario → se le restringe y se muestran preguntas.',
        '2) Responde todas → aparece revisión con Validar/Rechazar.',
        '3) Sólo autorizados pueden pulsar; miembros normales no reciben aviso.',
        '4) Si no termina a tiempo y está activado, el bot puede expulsar.',
    ])
    if not can_restrict:
        lines.append('\n⚠️ Falta permiso clave: <b>Banear/restringir miembros</b>. Sin eso no podrá silenciar, validar ni expulsar bien.')
    return '\n'.join([x for x in lines if x is not None])

async def _v240_validation_check_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await _v240_can_validate_silent(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo admins autorizados pueden comprobar validación.')
        return
    await update.message.reply_html(await _v240_validation_permissions_report(context, chat_id, int(update.effective_user.id)), reply_markup=InlineKeyboardMarkup([
        [InlineKeyboardButton('🧪 Simular flujo visual', callback_data=f'v240val|simulate|{chat_id}')],
        [InlineKeyboardButton('🧹 Limpiar pendientes atascados', callback_data=f'v240val|clean|{chat_id}')],
    ]))

async def _v240_validation_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('v240val|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not await _v240_can_validate_silent(context, chat_id, int(update.effective_user.id)):
        await q.answer()
        raise _V240Stop
    if action == 'simulate':
        await q.answer('Simulación enviada')
        qs = cfg_questions(chat_id)
        sample_user = update.effective_user
        text = (
            '🧪 <b>SIMULACIÓN DE VALIDACIÓN</b>\n\n'
            f'Usuario simulado: {sample_user.mention_html()}\n'
            f'Pregunta 1/{len(qs)}: <b>{h(qs[0] if qs else "Nombre:")}</b>\n\n'
            '✅ Si esto fuera una entrada real, el usuario estaría restringido hasta completar las preguntas.\n'
            '✅ Al terminar, sólo un admin autorizado podría validar/rechazar.'
        )
        await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('✅ Validar demo', callback_data='v240val|noop|0'), InlineKeyboardButton('❌ Rechazar demo', callback_data='v240val|noop|0')]]))
        return
    if action == 'clean':
        cleaned = 0
        state = get_state(chat_id)
        for uid, rec in list(state.validation_users.items()):
            if rec.get('status') in ('answering','pending_admin','timeout','rejected'):
                rec['status'] = 'validated'
                rec['v240_cleaned'] = True
                state.validation_users[str(uid)] = rec
                state.muted_users.pop(str(uid), None)
                cleaned += 1
        save_all_states()
        await q.answer(f'Limpios: {cleaned}', show_alert=True)
        await q.edit_message_text(await _v240_validation_permissions_report(context, chat_id, int(update.effective_user.id)), parse_mode=ParseMode.HTML)
        return
    await q.answer()


_old_v240_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_v240_admin_private_block_markup(int(chat_id), block, page)
