_old_v240_validation_menu_callback = _v240_validation_menu_callback
async def _v240_validation_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if data.startswith('v240val|report|'):
        try:
            chat_id = int(data.split('|')[2])
        except Exception:
            chat_id = int(update.effective_chat.id) if update.effective_chat else 0
        if not update.effective_user or not await _v240_can_validate_silent(context, chat_id, int(update.effective_user.id)):
            await q.answer()
            raise _V240Stop
        await q.answer('Comprobando…')
        await q.edit_message_text(await _v240_validation_permissions_report(context, chat_id, int(update.effective_user.id)), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton('🧪 Simular flujo visual', callback_data=f'v240val|simulate|{chat_id}')],
            [InlineKeyboardButton('🧹 Limpiar pendientes atascados', callback_data=f'v240val|clean|{chat_id}')],
            [InlineKeyboardButton('🔙 Volver Validación', callback_data=f'cfg|block|{chat_id}|validation')],
        ]))
        return
    await _old_v240_validation_menu_callback(update, context)


