_old_build_application_v240 = build_application

def build_application() -> Application:
    app = _old_build_application_v240()

    app.add_handler(CallbackQueryHandler(_v240_validation_silent_guard, pattern=r'^(val\||valreq\||cfg\|pend(approve|kick)\|)'), group=-60000000000)
    app.add_handler(CommandHandler(['comprobarvalidacion','checkvalidacion','validacioncheck','testvalidacion'], _v240_validation_check_command), group=-60000000001)
    app.add_handler(CallbackQueryHandler(_v240_validation_menu_callback, pattern=r'^v240val\|'), group=-60000000002)

    app.add_handler(CallbackQueryHandler(_v240_award_like_callback, pattern=r'^awdlike\|'), group=-60000000003)
    app.add_handler(CallbackQueryHandler(_v240_cfg_awards_audience_open, pattern=r'^cfg\|block\|-?\d+\|awards_audience$'), group=-60000000004)
    app.add_handler(CallbackQueryHandler(_v240_awdpoll_callback, pattern=r'^awdpoll\|'), group=-60000000005)
    app.add_handler(CallbackQueryHandler(_v240_vote_callback, pattern=r'^awdvot\|'), group=-60000000006)
    app.add_handler(MessageHandler((filters.TEXT | filters.PHOTO | filters.VIDEO | filters.Document.ALL | filters.ANIMATION) & ~filters.COMMAND, _v240_awards_pending_handler), group=-60000000007)
    logger.info('V240 cargado: comprobación validación, premios con likes y premio audiencia oculto')
    return app


