def _v241_summary_abbr_len(chat_id: int) -> int:
    """Longitud de la etiqueta del resumen.
    0/auto: 3 columnas=4 letras, 2 columnas=5 letras, 1 columna=6 letras.
    """
    try:
        cfg = admin_cfg(int(chat_id))
        raw = cfg.get('summary_abbr_len', 0)
        n = int(raw or 0)
        if 3 <= n <= 6:
            return n
    except Exception:
        pass
    try:
        cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2
    except Exception:
        cols = 2
    return 6 if int(cols) == 1 else 5 if int(cols) == 2 else 4


def _v241_summary_width(chat_id: int) -> int:
    try:
        cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2
    except Exception:
        cols = 2
    cols = max(1, min(3, int(cols or 2)))

    return 26 if cols == 1 else 18 if cols == 2 else 12


def _v241_abbr(key: str, chat_id: int) -> str:
    spec = _v233_summary_specs().get(key, {'abbr': key[:5]}) if '_v233_summary_specs' in globals() else {'abbr': key[:5]}
    n = _v241_summary_abbr_len(int(chat_id))
    raw = str(spec.get('abbr') or key[:n]).upper()
    raw = ''.join(ch for ch in raw if ch.isalnum())[:n]
    return raw.ljust(n, '0')[:n]


def _v237_summary_cell(chat_id: int, key: str) -> str:
    spec = _v233_summary_specs().get(key, {'icon':'•', 'abbr': key[:5].upper()}) if '_v233_summary_specs' in globals() else {'icon':'•','abbr':key[:5]}
    icon = str(spec.get('icon','•'))
    abbr = _v241_abbr(key, int(chat_id))
    value = str((_v239_summary_value(int(chat_id), key) if '_v239_summary_value' in globals() else _v233_summary_value(int(chat_id), key)) or '—')
    width = _v241_summary_width(int(chat_id))
    max_val = max(1, width - len(icon) - len(abbr) - 1)
    if len(value) > max_val:
        value = value[:max_val]
    return f'{icon}{abbr}:{value}'


def _v232_cell(chat_id: int, key: str, width: Optional[int] = None) -> str:
    return _v237_summary_cell(int(chat_id), key).ljust(int(width or _v241_summary_width(int(chat_id))))


def _v232_summary_lines(chat_id: int) -> List[str]:
    fields = _v232_summary_fields(int(chat_id)) if '_v232_summary_fields' in globals() else _v232_default_summary_fields()
    cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2
    cols = max(1, min(3, int(cols or 2)))
    width = _v241_summary_width(int(chat_id))
    cells = [_v237_summary_cell(int(chat_id), k) for k in fields]
    lines: List[str] = []
    for i in range(0, len(cells), cols):
        row = cells[i:i+cols]
        lines.append(''.join(c.ljust(width) for c in row).rstrip())
    return lines


_old_v241_top_text = _v232_top_text if '_v232_top_text' in globals() else None

def _v232_top_text(chat_id: int) -> str:
    fields = _v232_summary_fields(int(chat_id)) if '_v232_summary_fields' in globals() else []
    total = len(_v233_summary_specs()) if '_v233_summary_specs' in globals() else len(fields)
    cols = _v233_summary_cols(int(chat_id)) if '_v233_summary_cols' in globals() else 2
    abbr_len = admin_cfg(int(chat_id)).get('summary_abbr_len', 0)
    etiqueta = 'auto' if not abbr_len else str(abbr_len)
    preview = '\n'.join(_v232_summary_lines(int(chat_id)))
    return (
        '<b>🔝 Configurar resumen superior</b>\n\n'
        f'Activos: <b>{len(fields)}/{total}</b> · Columnas: <b>{cols}</b> · Letras: <b>{h(etiqueta)}</b>\n\n'
        '<b>Vista previa:</b>\n'
        f'<pre>{h(preview)}</pre>\n\n'
        'Puedes activar, ocultar, subir, bajar y ajustar columnas/letras para que quepa mejor en móvil.'
    )


_old_v241_top_markup = _v232_top_markup if '_v232_top_markup' in globals() else None

def _v232_top_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    base = _old_v241_top_markup(int(chat_id), int(page)) if callable(_old_v241_top_markup) else InlineKeyboardMarkup([])
    rows = [list(r) for r in (base.inline_keyboard or [])]
    cur = int(admin_cfg(int(chat_id)).get('summary_abbr_len', 0) or 0)
    label = '🔤 Letras: AUTO' if cur == 0 else f'🔤 Letras: {cur}'

    insert_at = 1 if rows else 0
    rows.insert(insert_at, [InlineKeyboardButton(label, callback_data=f'cfg241|abbr|{int(chat_id)}|{int(page)}')])
    return InlineKeyboardMarkup(rows)


