_old_v241_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    """Abajo: GRUPO ACTUAL, Actualizar y Guardar/Cerrar. No genera mensaje nuevo."""
    try:
        base = _old_v241_admin_private_main_markup(int(chat_id))
        rows = [list(r) for r in (base.inline_keyboard or [])]

        new_rows: List[List[InlineKeyboardButton]] = []
        for row in rows:
            datas = ' '.join((getattr(b, 'callback_data', '') or '') for b in row)
            texts = ' '.join((getattr(b, 'text', '') or '') for b in row)
            if 'checkbot|' in datas or 'saveclose' in datas or 'Guardar y cerrar' in texts or 'Comprobar bot' in texts:
                continue
            new_rows.append(row)

        group_rows = [r for r in new_rows if any('GRUPO ACTUAL' in (getattr(b,'text','') or '') for b in r)]
        new_rows = [r for r in new_rows if not any('GRUPO ACTUAL' in (getattr(b,'text','') or '') for b in r)]
        if group_rows:
            new_rows.extend(group_rows[-1:])
        else:
            label = _v225_group_bar_label(int(chat_id)) if '_v225_group_bar_label' in globals() else f'📍 GRUPO ACTUAL: {int(chat_id)}'
            new_rows.append([InlineKeyboardButton(label, callback_data='cfg|list')])
        new_rows.append([
            InlineKeyboardButton('🔄 Actualizar', callback_data=f'cfg241|refresh|{int(chat_id)}'),
            InlineKeyboardButton('💾 Guardar y cerrar', callback_data=f'cfg|saveclose225|{int(chat_id)}'),
        ])
        return InlineKeyboardMarkup(new_rows)
    except Exception:
        logger.exception('V241 no pudo montar markup principal')
        return _old_v241_admin_private_main_markup(int(chat_id))


async def _v241_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    data = q.data or ''
    if not (data.startswith('cfg241|refresh|') or data.startswith('cfg241|abbr|')):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not update.effective_user or not is_global_admin_user(update.effective_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V241Stop
    if action == 'refresh':
        save_all_states()
        await q.answer('Actualizado')
        await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
        raise _V241Stop
    if action == 'abbr':
        page = int(parts[3]) if len(parts) > 3 and str(parts[3]).isdigit() else 0
        cfg = admin_cfg(chat_id)
        cur = int(cfg.get('summary_abbr_len', 0) or 0)
        seq = [0, 3, 4, 5, 6]
        nxt = seq[(seq.index(cur) + 1) % len(seq)] if cur in seq else 0
        cfg['summary_abbr_len'] = nxt
        save_all_states()
        await q.answer('Letras: AUTO' if nxt == 0 else f'Letras: {nxt}')
        await q.edit_message_text(_v232_top_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v232_top_markup(chat_id, page))
        raise _V241Stop


async def _v241_validation_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    data = q.data or ''
    if not data.startswith('v241val|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not update.effective_user or not await _v240_can_validate_silent(context, chat_id, int(update.effective_user.id)):
        await q.answer()
        raise _V241Stop
    if action == 'simulate':
        qs = cfg_questions(chat_id)
        sample_user = update.effective_user
        text = (
            '🧪 <b>SIMULACIÓN REAL DE VALIDACIÓN</b>\n\n'
            f'Usuario demo: {sample_user.mention_html()}\n'
            f'Pregunta 1/{len(qs)}: <b>{h(qs[0] if qs else "Nombre:")}</b>\n\n'
            'Pulsa un botón demo para verificar que el router responde. No afecta a usuarios reales.'
        )
        msg = await context.bot.send_message(
            chat_id=chat_id,
            text=text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('✅ Validar demo', callback_data=f'v241val|demo_ok|{chat_id}'), InlineKeyboardButton('❌ Rechazar demo', callback_data=f'v241val|demo_no|{chat_id}')]])
        )
        await register_bot_message(chat_id, getattr(msg, 'message_id', None))
        await q.answer('Demo enviada')
        raise _V241Stop
    if action in ('demo_ok', 'demo_no'):
        ok = action == 'demo_ok'
        await q.answer('Demo validada ✅' if ok else 'Demo rechazada ❌')
        try:
            await q.edit_message_text(('✅ <b>DEMO VALIDADA</b>\n\nEl botón de validación responde correctamente.' if ok else '❌ <b>DEMO RECHAZADA</b>\n\nEl botón de rechazo responde correctamente.'), parse_mode=ParseMode.HTML)
        except Exception:
            pass
        raise _V241Stop


_old_v241_v240_validation_menu_callback = _v240_validation_menu_callback if '_v240_validation_menu_callback' in globals() else None
