_old_build_application_v241 = build_application

def build_application() -> Application:
    app = _old_build_application_v241()

    app.add_handler(CallbackQueryHandler(_v241_panel_router, pattern=r'^cfg241\|'), group=-70000000000)
    app.add_handler(CallbackQueryHandler(_v241_validation_menu_callback, pattern=r'^v241val\|'), group=-70000000001)
    app.add_handler(CallbackQueryHandler(_v240_validation_menu_callback, pattern=r'^v240val\|'), group=-70000000002)
    app.add_handler(CallbackQueryHandler(_v241_awdaud_router, pattern=r'^awdaud\|open\|'), group=-70000000003)
    app.add_handler(CallbackQueryHandler(_v241_podcast_menu_callback, pattern=r'^dj_podcast_menu$'), group=-70000000004)
    logger.info('V241 cargado: demo validación real, audiencia aislada, resumen móvil configurable, actualizar sin mensaje y podcast estable')
    return app


BOT_VERSION = "V242"

try:
    from telegram.ext import ApplicationHandlerStop as _V242Stop
except Exception:
    _V242Stop = Exception


def _v242_admin_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return admin_cfg(int(chat_id))
    except Exception:
        return get_state(int(chat_id)).admin_config


def _v242_set_mode(chat_id: int, mode: str) -> None:
    cfg = _v242_admin_cfg(int(chat_id))
    cfg['dj_session_mode'] = str(mode or 'pro')
    try:
        if '_v75_set_mode' in globals():
            _v75_set_mode(int(chat_id), str(mode or 'pro'))
    except Exception:
        pass
    save_all_states()


def _v242_is_pro(chat_id: int) -> bool:
    try:
        mode = str(_v75_session_mode(int(chat_id)) if '_v75_session_mode' in globals() else _v242_admin_cfg(int(chat_id)).get('dj_session_mode', 'pro')).lower()
    except Exception:
        mode = str(_v242_admin_cfg(int(chat_id)).get('dj_session_mode', 'pro')).lower()
    return mode not in ('easy', 'facil', 'fácil', 'podcast')


def _v242_panel_status_text(chat_id: int) -> str:
    state = get_state(int(chat_id))
    try:
        base = panel_text(state)
    except Exception:
        logger.exception('V242: no pude crear panel_text; uso fallback')
        now = 'Nada sonando'
        if state.now_playing:
            try:
                now = shorten_title(Track(**state.now_playing).title, 32)
            except Exception:
                pass
        live = 'ON' if state.live_enabled else 'OFF'
        base = f'<b>🎛 DJ-PRO</b> · LIVE <b>{h(live)}</b> · 🎵 <i>{h(now)}</i>'
    return str(base).strip()


