async def _v242_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    data = q.data or ''
    if data not in ('menu_panel','panel_home','panel_minimize','panel_refresh'):
        return
    if not update.effective_chat or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    user_id = int(update.effective_user.id)
    if not await is_controller(context, chat_id, user_id):
        await q.answer('Solo admin o DJ asignado.', show_alert=True)
        raise _V242Stop
    state = get_state(chat_id)
    state.dj_mode = True
    if state.assigned_dj_id is None:
        state.assigned_dj_id = user_id
        state.assigned_dj_name = display_name(update.effective_user)
    _v242_set_mode(chat_id, 'pro')
    cfg = _v242_admin_cfg(chat_id)
    if data == 'panel_minimize':
        cfg['dj_mesa_minimized'] = True
        cfg['dj_mesa_visible'] = False

        state.control_message_id = state.panel_message_id
        save_all_states()
        await q.answer('Mesa minimizada')
        await _v242_edit_or_create_single_panel(context.bot, chat_id)
        raise _V242Stop

    cfg['dj_mesa_minimized'] = False
    cfg['dj_mesa_visible'] = True
    if data in ('menu_panel', 'panel_home'):
        set_control_view(state, 'home', 0)
    save_all_states()

    from_menu = bool(q.message and state.panel_message_id and int(q.message.message_id) != int(state.panel_message_id))
    await _v242_edit_or_create_single_panel(context.bot, chat_id)
    if from_menu:
        try:
            await q.message.delete()
        except Exception:
            pass
    await q.answer('Mesa actualizada' if data == 'panel_refresh' else 'Mesa DJ-PRO mostrada')
    raise _V242Stop


async def djmesa_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        if update.message:
            await update.message.reply_text('Solo admin o DJ asignado.')
        return
    state = get_state(chat_id)
    state.dj_mode = True
    if state.assigned_dj_id is None:
        state.assigned_dj_id = int(update.effective_user.id)
        state.assigned_dj_name = display_name(update.effective_user)
    _v242_set_mode(chat_id, 'pro')
    cfg = _v242_admin_cfg(chat_id)
    cfg['dj_mesa_minimized'] = False
    cfg['dj_mesa_visible'] = True
    set_control_view(state, 'home', 0)
    save_all_states()
    await _v242_edit_or_create_single_panel(context.bot, chat_id)
    if update.message:
        try:
            await safe_delete(context.bot, chat_id, update.message.message_id)
        except Exception:
            pass


