def _v149_key_allowed_for_module(key: str, module: str) -> bool:
    """Incluye las claves del módulo Premios en el exportador general por módulos."""
    if module == 'premios':
        k = str(key)
        if any(x in k for x in _V149_VOLATILE_SUBSTRINGS):
            return False
        return (
            k.startswith(('awards_', 'award_', 'audience_award_', 'social_awards_', 'premios_', 'popular_audience_'))
            or k in ('pair_day_enabled', 'pair_day_last_key')
        )
    if callable(_old_v245_key_allowed_for_module):
        return bool(_old_v245_key_allowed_for_module(key, module))
    return False


_old_v245_export_module = _v149_export_module if '_v149_export_module' in globals() else None

def _v149_export_module(src: int, dst: int, module: str) -> None:
    """Exporta premios con el mismo sistema del menú Exportar por módulo.

    Para Premios Sociales usamos el payload V243, que ya sabe incluir imágenes/file_id,
    textos, candidatos, encuesta de audiencia, likes y estadísticas cuando procede.
    """
    if module == 'premios':
        src = int(src); dst = int(dst)
        if '_v243_awards_export_payload' in globals() and '_v243_apply_awards_payload' in globals():


            payload = _v243_awards_export_payload(src, include_stats=True)
            applied, skipped = _v243_apply_awards_payload(dst, payload)
            try:
                add_action_log(src, 'export_module', f'premios exportado a {dst} · claves {applied}')
                add_action_log(dst, 'export_module', f'premios importado desde {src} · claves {applied}')
            except Exception:
                pass
            save_all_states()
            return

        src_state = get_state(src); dst_state = get_state(dst)
        src_cfg = src_state.admin_config if isinstance(src_state.admin_config, dict) else {}
        dst_cfg = dst_state.admin_config if isinstance(dst_state.admin_config, dict) else {}
        for key, value in src_cfg.items():
            if _v149_key_allowed_for_module(key, 'premios'):
                dst_cfg[key] = _v149_clean_export_value(value)
        dst_state.admin_config = dst_cfg
        save_all_states()
        return
    if callable(_old_v245_export_module):
        return _old_v245_export_module(src, dst, module)


