async def _v248_user_is_owner_or_admin(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> bool:
    """Permiso conservador para refrescar sin abrir zonas a usuarios normales."""
    try:
        if 'is_owner_user' in globals() and callable(globals().get('is_owner_user')):
            if is_owner_user(int(user_id)):
                return True
    except Exception:
        pass
    try:
        if 'is_global_admin_user' in globals() and callable(globals().get('is_global_admin_user')):
            if is_global_admin_user(int(user_id)):
                return True
    except Exception:
        pass
    try:
        return bool(await is_admin(context, int(chat_id), int(user_id)))
    except Exception:
        return False


def _v248_known_group_buttons(prefix: str = 'v248_refresh_group') -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    try:
        chat_ids = known_admin_chats_for_private() if 'known_admin_chats_for_private' in globals() else sorted(STATE_CACHE.keys())
    except Exception:
        chat_ids = sorted(STATE_CACHE.keys())
    for cid in chat_ids[:40]:
        try:
            title = str(cfg_value(int(cid), 'chat_title', '') or cid)
        except Exception:
            title = str(cid)
        rows.append([InlineKeyboardButton(f'🔄 {title[:45]}', callback_data=f'{prefix}|{int(cid)}')])
    rows.append([InlineKeyboardButton('❌ Cerrar', callback_data='v248_refresh_close')])
    return InlineKeyboardMarkup(rows)


async def _v248_refresh_chat(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> Dict[str, Any]:
    """Refresca estado/UI sin borrar datos ni recrear módulos innecesariamente."""
    result: Dict[str, Any] = {'chat_id': int(chat_id), 'panel': False, 'mesa': False, 'temp_clean': False, 'saved': False}
    load_all_states()
    state = get_state(int(chat_id))
    try:
        await cleanup_temp_messages(context.bot, int(chat_id))
        result['temp_clean'] = True
    except Exception:
        logger.exception('V248: no se pudieron limpiar temporales en %s', chat_id)
    try:
        if getattr(state, 'dj_mode', False):
            await ensure_panel(context.bot, int(chat_id))
            result['panel'] = True

            await ensure_control_panel(context.bot, int(chat_id))
            result['mesa'] = True
    except Exception:
        logger.exception('V248: no se pudo refrescar DJ en %s', chat_id)
    try:
        save_all_states()
        result['saved'] = True
    except Exception:
        logger.exception('V248: no se pudo guardar estado al refrescar %s', chat_id)
    return result


async def _v248_refreshbot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    user_id = int(update.effective_user.id)
    chat = update.effective_chat
    if not chat:
        return


    if getattr(chat, 'type', '') == 'private':
        if not (is_global_admin_user(user_id) if 'is_global_admin_user' in globals() else user_id in ADMIN_IDS):
            await update.message.reply_text('Solo el dueño/ADMIN_IDS puede refrescar desde privado.')
            return
        if context.args:
            try:
                target = int(context.args[0])
            except Exception:
                await update.message.reply_text('Uso: /refreshbot CHAT_ID')
                return
            res = await _v248_refresh_chat(context, target)
            await update.message.reply_html(
                '🔄 <b>Bot refrescado</b>\n\n'
                f'Grupo: <code>{target}</code>\n'
                f'Panel DJ: <b>{"OK" if res.get("panel") else "—"}</b>\n'
                f'Mesa DJ: <b>{"OK" if res.get("mesa") else "—"}</b>\n'
                f'Temporales: <b>{"OK" if res.get("temp_clean") else "—"}</b>\n'
                f'Guardado: <b>{"OK" if res.get("saved") else "—"}</b>\n'
                f'Versión: <b>{BOT_VERSION}</b>'
            )
            return
        await update.message.reply_html(
            '🔄 <b>Refrescar bot</b>\n\nElige el grupo que quieres refrescar o usa <code>/refreshbot CHAT_ID</code>.',
            reply_markup=_v248_known_group_buttons()
        )
        return

    chat_id = int(chat.id)
    if not await _v248_user_is_owner_or_admin(context, chat_id, user_id):
        await update.message.reply_text('Solo admins/dueño pueden refrescar el bot.')
        return
    res = await _v248_refresh_chat(context, chat_id)
    await update.message.reply_html(
        '🔄 <b>Bot refrescado en este grupo</b>\n\n'
        f'Panel DJ: <b>{"OK" if res.get("panel") else "—"}</b>\n'
        f'Mesa DJ: <b>{"OK" if res.get("mesa") else "—"}</b>\n'
        f'Temporales: <b>{"OK" if res.get("temp_clean") else "—"}</b>\n'
        f'Guardado: <b>{"OK" if res.get("saved") else "—"}</b>\n'
        f'Versión: <b>{BOT_VERSION}</b>'
    )


async def _v248_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if data == 'v248_refresh_close':
        await q.answer('Cerrado')
        try:
            await q.message.delete()
        except Exception:
            pass
        return
    if not data.startswith('v248_refresh_group|'):
        return
    if not (is_global_admin_user(update.effective_user.id) if 'is_global_admin_user' in globals() else int(update.effective_user.id) in ADMIN_IDS):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        return
    try:
        chat_id = int(data.split('|', 1)[1])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        return
    await q.answer('Refrescando…')
    res = await _v248_refresh_chat(context, chat_id)
    try:
        title = str(cfg_value(chat_id, 'chat_title', '') or chat_id)
    except Exception:
        title = str(chat_id)
    await q.edit_message_text(
        '🔄 <b>Bot refrescado</b>\n\n'
        f'Grupo: <b>{h(title)}</b>\n'
        f'ID: <code>{chat_id}</code>\n'
        f'Panel DJ: <b>{"OK" if res.get("panel") else "—"}</b>\n'
        f'Mesa DJ: <b>{"OK" if res.get("mesa") else "—"}</b>\n'
        f'Temporales: <b>{"OK" if res.get("temp_clean") else "—"}</b>\n'
        f'Guardado: <b>{"OK" if res.get("saved") else "—"}</b>\n'
        f'Versión: <b>{BOT_VERSION}</b>',
        parse_mode=ParseMode.HTML,
        reply_markup=_v248_known_group_buttons(),
    )


