BOT_VERSION = "V249-base245-refresh-impostor-lobby-unico"

try:
    from telegram.ext import ApplicationHandlerStop
except Exception:
    class ApplicationHandlerStop(Exception):
        pass

_IMP_V249_LOCKS: Dict[str, asyncio.Lock] = {}


def _v249_imp_lock_key(data: str) -> str:
    parts = (data or "").split("|")
    if len(parts) >= 4:
        return f"{parts[2]}:{parts[3]}"
    return data or "global"


def _v249_imp_lock(data: str) -> asyncio.Lock:
    key = _v249_imp_lock_key(data)
    lock = _IMP_V249_LOCKS.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _IMP_V249_LOCKS[key] = lock
    return lock


async def _v249_impostor_single_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Router cortafuegos para Impostor.

    En la base V245 había varias capas históricas registradas para callbacks `imp|`.
    Eso permitía que un mismo click de lobby fuera procesado más de una vez:
    1) una capa editaba el lobby;
    2) otra capa vieja recibía el mismo callback y podía generar/recrear otro mensaje.

    Este router se registra antes que todos los demás, ejecuta UNA sola vez el router final
    que ya existía y después detiene la cadena con ApplicationHandlerStop.
    Resultado: el lobby se edita, no se duplica.
    """
    q = update.callback_query
    if not q or not (q.data or "").startswith("imp|"):
        return
    data = q.data or ""
    async with _v249_imp_lock(data):
        try:

            await impostor_callback_router(update, context)
        except BadRequest as e:
            msg = str(e).lower()
            if "message is not modified" in msg:
                try:
                    await q.answer()
                except Exception:
                    pass
            else:
                logger.exception("V249: error BadRequest en Impostor")
                try:
                    await q.answer("No pude actualizar el juego. Usa /refreshbot si se queda pillado.", show_alert=True)
                except Exception:
                    pass
        except Exception:
            logger.exception("V249: error en router único de Impostor")
            try:
                await q.answer("No pude actualizar el juego. Usa /refreshbot si se queda pillado.", show_alert=True)
            except Exception:
                pass

    raise ApplicationHandlerStop


_old_build_application_v249 = build_application

def build_application() -> Application:
    app = _old_build_application_v249()

    app.add_handler(CallbackQueryHandler(_v249_impostor_single_callback_router, pattern=r"^imp\|"), group=-20000000001)
    logger.info("V249 cargado: base V245/V248 + lobby Impostor único sin duplicados")
    return app


