def _v250_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    cfg.setdefault("summary_page_v250", 0)
    cfg.setdefault("summary_visual_style_v250", "none")
    cfg.setdefault("summary_cols_v250", int(cfg.get("summary_cols", cfg.get("summary_columns", 2)) or 2))
    return cfg


def _v250_summary_page(chat_id: int) -> int:
    cfg = _v250_cfg(int(chat_id))
    try:
        p = int(cfg.get("summary_page_v250", 0) or 0)
    except Exception:
        p = 0
    return max(0, min(p, len(V250_SUMMARY_PAGES) - 1))


def _v250_summary_cols(chat_id: int) -> int:
    cfg = _v250_cfg(int(chat_id))
    try:
        cols = int(cfg.get("summary_cols_v250", cfg.get("summary_cols", 2)) or 2)
    except Exception:
        cols = 2
    return max(1, min(3, cols))


def _v250_abbr_len(chat_id: int, cols: Optional[int] = None) -> int:
    cfg = admin_cfg(int(chat_id))
    try:
        forced = int(cfg.get("summary_abbr_len", 0) or 0)
    except Exception:
        forced = 0
    if forced > 0:
        return max(3, min(8, forced))
    cols = int(cols or _v250_summary_cols(int(chat_id)))

    return 4 if cols >= 3 else 5 if cols == 2 else 6


def _v250_clean_abbr(raw: str, n: int) -> str:
    s = ''.join(ch for ch in str(raw or '').upper() if ch.isalnum())
    if not s:
        s = 'DATO'
    return s[:n].ljust(n)[:n]


def _v250_short_title(value: str, max_len: int = 12) -> str:
    value = str(value or '').strip()
    if not value:
        return '—'

    value = value.replace('\n', ' ').replace('\r', ' ')
    value = ' '.join(value.split())
    return value if len(value) <= max_len else value[:max_len-1] + '…'


