def _v250_queue_title(chat_id: int, idx: int) -> str:
    try:
        st = get_state(int(chat_id))
        if idx == 0:
            data = st.now_playing
        else:
            q = st.queue or []
            data = q[idx-1] if len(q) >= idx else None
        if not data:
            return '—'
        return _v250_short_title(str(data.get('title') or data.get('performer') or 'Canción'), 11)
    except Exception:
        return '—'


def _v250_today_entries(chat_id: int) -> int:
    try:
        today = time.strftime('%Y-%m-%d')
        count = 0
        for e in (get_state(int(chat_id)).entry_log or []):
            ts = int(e.get('joined_ts') or e.get('ts') or 0)
            if ts and time.strftime('%Y-%m-%d', time.localtime(ts)) == today:
                count += 1
        return count
    except Exception:
        return 0


def _v250_dj_timer_value(chat_id: int) -> str:
    try:
        if '_v75_timer_label' in globals():
            return _v250_short_title(_v75_timer_label(int(chat_id)), 8)
    except Exception:
        pass
    try:
        ends = int(admin_cfg(int(chat_id)).get('dj_session_ends_at') or 0)
        if ends > int(time.time()):
            mins = max(1, int((ends - time.time()) // 60))
            return f'{mins}m'
    except Exception:
        pass
    return 'OFF'


