def _v239_summary_value(chat_id: int, key: str) -> str:
    chat_id = int(chat_id)
    try:
        if key == 'now_track': return _v250_queue_title(chat_id, 0)
        if key.startswith('queue_'):
            try: n = int(key.split('_', 1)[1])
            except Exception: n = 1
            return _v250_queue_title(chat_id, n)
        if key == 'dj_timer': return _v250_dj_timer_value(chat_id)
        if key == 'dj_mode_sound':
            try:
                if bool(cfg_value(chat_id, 'dj_audio_normalize_opus', False)) or os.getenv('DJ_AUDIO_NORMALIZE_OPUS','').lower() in ('1','true','yes','on'):
                    return 'OPUS'
            except Exception:
                pass
            return 'STD'
        if key == 'validation_timeout': return str(cfg_value(chat_id, 'validation_timeout_minutes', VALIDATION_TIMEOUT_MINUTES if 'VALIDATION_TIMEOUT_MINUTES' in globals() else 10)) + 'm'
        if key == 'validation_kick': return _v239_bool(cfg_value(chat_id, 'validation_kick_if_timeout', True)) if '_v239_bool' in globals() else ('ON' if cfg_value(chat_id, 'validation_kick_if_timeout', True) else 'OFF')
        if key == 'validation_perms': return 'OK' if bool(cfg_value(chat_id, 'validation_enabled', False)) else 'OFF'
        if key == 'new_entries': return str(_v250_today_entries(chat_id))
        if key == 'next_block_message': return _v239_summary_value(chat_id, 'next_block') if _old_v250_summary_value is not None else '—'
        if key == 'next_recurrent_message': return _v239_summary_value(chat_id, 'next_recurrent') if _old_v250_summary_value is not None else '—'
        if key == 'pregonero_time': return _v250_pregonero_next(chat_id)
        if key == 'impostor_status': return _v239_bool(cfg_value(chat_id, 'impostor_enabled', True)) if '_v239_bool' in globals() else ('ON' if cfg_value(chat_id, 'impostor_enabled', True) else 'OFF')
        if key == 'impostor_config':
            vals = []
            try:
                vals.append('ON' if cfg_value(chat_id, 'impostor_enabled', True) else 'OFF')
                vals.append(str(cfg_value(chat_id, 'impostor_rounds', cfg_value(chat_id, 'impostor_max_rounds', '—'))))
            except Exception:
                vals = ['ON']
            return '/'.join(vals)[:8]
        if key == 'hot_status': return _v239_bool(cfg_value(chat_id, 'hot_mode', 'manual') != 'off') if '_v239_bool' in globals() else 'ON'
        if key == 'hot_auto_status': return _v239_bool(cfg_value(chat_id, 'hot_auto_enabled', False)) if '_v239_bool' in globals() else ('ON' if cfg_value(chat_id, 'hot_auto_enabled', False) else 'OFF')
        if callable(_old_v250_summary_value):
            return str(_old_v250_summary_value(chat_id, key) or '—')
    except Exception:
        logger.exception('V250 error obteniendo resumen %s', key)
    return '—'


def _v233_summary_value(chat_id: int, key: str) -> str:
    return _v239_summary_value(int(chat_id), key)

def _v232_short_raw_value(chat_id: int, key: str) -> str:
    return _v239_summary_value(int(chat_id), key)


def _v250_page_keys(chat_id: int, page: Optional[int] = None) -> List[str]:
    if page is None:
        page = _v250_summary_page(int(chat_id))
    page_id = V250_SUMMARY_PAGES[max(0, min(int(page), len(V250_SUMMARY_PAGES)-1))][0]
    if page_id == 'dj':
        return ['dj','live','dj_auto','dj_timer','dj_mode_sound','queue','now_track','queue_1','queue_2','queue_3','queue_4','queue_5','podcast','library']
    if page_id == 'recurrentes':
        return ['recurrentes','next_recurrent_message','recurrent_blocks','next_block_message','pregonero','pregonero_time','pregonero_jobs','direct_buttons','msg_day','msg_week']
    if page_id == 'juegos':
        return ['hot_status','hot_auto_status','hot_interval','impostor_status','impostor_config','tarot','cerebrito','ia','ai_commands_count','polls']
    if page_id == 'validacion':
        return ['validation_status','validation_perms','validation_timeout','validation_kick','pending','new_entries','members','service_cleanup','allowed_group','owner']

    try:
        fields = _v232_summary_fields(int(chat_id)) if '_v232_summary_fields' in globals() else []
        if fields:
            return list(fields)
    except Exception:
        pass
    return ['validation_status','daily_phrase_status','awards_status','pending','recurrentes','next_recurrent_message','recurrent_blocks','next_block_message','dj','live','hot','pregonero','msg_day','msg_week','version']


def _v250_summary_cell(chat_id: int, key: str, width: int, abbr_len: int, style_prefix: str = '') -> str:
    spec = _v233_summary_specs().get(key, {'icon':'•','abbr':key[:abbr_len].upper(),'name':key})
    icon = str(spec.get('icon','•'))
    abbr = _v250_clean_abbr(str(spec.get('abbr') or key), abbr_len)
    val = str(_v239_summary_value(int(chat_id), key) or '—')

    max_val = max(4, width - (len(icon) + abbr_len + 2))
    val = _v250_short_title(val, max_val)
    txt = f'{style_prefix}{icon}{abbr}:{val}'
    if len(txt) > width:
        txt = txt[:width]
    return txt.ljust(width)


def _v250_summary_lines(chat_id: int) -> List[str]:
    chat_id = int(chat_id)
    cols = _v250_summary_cols(chat_id)
    abbr_len = _v250_abbr_len(chat_id, cols)
    width = 28 if cols == 1 else 21 if cols == 2 else 16
    keys = _v250_page_keys(chat_id)
    style = str(_v250_cfg(chat_id).get('summary_visual_style_v250', 'none') or 'none')
    lines: List[str] = []
    for row_i, i in enumerate(range(0, len(keys), cols)):
        row_keys = keys[i:i+cols]
        cells = []
        for col_i, key in enumerate(row_keys):
            prefix = ''
            if style == 'row':
                prefix = '▸' if row_i % 2 == 0 else '▫'
            elif style == 'col':
                prefix = ['▸','▫','▪'][col_i % 3]
            cells.append(_v250_summary_cell(chat_id, key, width, abbr_len, prefix))
        lines.append(''.join(cells).rstrip())
    return lines or ['—']


def _v232_summary_lines(chat_id: int) -> List[str]:
    return _v250_summary_lines(int(chat_id))


def _v250_summary_header(chat_id: int) -> str:
    page_i = _v250_summary_page(int(chat_id))
    page_label = V250_SUMMARY_PAGES[page_i][1]
    summary = '\n'.join(_v250_summary_lines(int(chat_id)))
    return f'<b>{h(page_label)}</b> <code>{page_i+1}/{len(V250_SUMMARY_PAGES)}</code>\n<pre>{h(summary)}</pre>'


