def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows = [list(r) for r in (_old_v250_main_markup(int(chat_id)).inline_keyboard or [])]
    page = _v250_summary_page(int(chat_id))
    prev_i = (page - 1) % len(V250_SUMMARY_PAGES)
    next_i = (page + 1) % len(V250_SUMMARY_PAGES)
    cols = _v250_summary_cols(int(chat_id))
    style = str(_v250_cfg(int(chat_id)).get('summary_visual_style_v250','none'))
    style_label = {'none':'Limpio','row':'Filas','col':'Columnas'}.get(style, style)
    controls = [
        [InlineKeyboardButton('◀️ Resumen', callback_data=f'v250sum|page|{int(chat_id)}|{prev_i}'), InlineKeyboardButton(f'{V250_SUMMARY_PAGES[page][1]}', callback_data=f'v250sum|style|{int(chat_id)}'), InlineKeyboardButton('Resumen ▶️', callback_data=f'v250sum|page|{int(chat_id)}|{next_i}')],
        [InlineKeyboardButton(f'Columnas {cols}', callback_data=f'v250sum|cols|{int(chat_id)}'), InlineKeyboardButton(f'Estilo {style_label}', callback_data=f'v250sum|style|{int(chat_id)}'), InlineKeyboardButton('🔄 Datos', callback_data=f'cfg241|refresh|{int(chat_id)}')],
    ]

    return InlineKeyboardMarkup(controls + rows)


async def _v250_summary_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v250sum|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not update.effective_user or not is_global_admin_user(update.effective_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V250Stop
    cfg = _v250_cfg(chat_id)
    if action == 'page':
        cfg['summary_page_v250'] = max(0, min(int(parts[3]) if len(parts) > 3 else 0, len(V250_SUMMARY_PAGES)-1))
        await q.answer('Resumen cambiado')
    elif action == 'cols':
        cur = _v250_summary_cols(chat_id)
        cfg['summary_cols_v250'] = 1 if cur >= 3 else cur + 1
        await q.answer(f"Columnas: {cfg['summary_cols_v250']}")
    elif action == 'style':
        seq = ['none','row','col']
        cur = str(cfg.get('summary_visual_style_v250','none'))
        cfg['summary_visual_style_v250'] = seq[(seq.index(cur)+1) % len(seq)] if cur in seq else 'none'
        await q.answer('Estilo visual actualizado')
    else:
        await q.answer()
    save_all_states()
    await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
    raise _V250Stop


