_old_v250_control_panel_markup = control_panel_markup if 'control_panel_markup' in globals() else None

def control_panel_markup(state: ChatState) -> InlineKeyboardMarkup:
    markup = _old_v250_control_panel_markup(state) if callable(_old_v250_control_panel_markup) else InlineKeyboardMarkup([])
    rows: List[List[InlineKeyboardButton]] = []
    chat_id = None

    try:
        for cid, st in STATE_CACHE.items():
            if st is state:
                chat_id = int(cid); break
    except Exception:
        pass
    for row in (markup.inline_keyboard or []):
        newrow: List[InlineKeyboardButton] = []
        for btn in row:
            text = str(getattr(btn, 'text', '') or '')
            cb = str(getattr(btn, 'callback_data', '') or '')
            if 'Biblioteca' in text and chat_id is not None:
                newrow.append(InlineKeyboardButton('💾 Act. lista', callback_data=f'panel_update_current|{chat_id}'))
            else:
                newrow.append(btn)
        rows.append(newrow)
    return InlineKeyboardMarkup(rows)


async def _v250_dj_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('panel_update_current|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[1])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not update.effective_user or not await is_controller(context, chat_id, update.effective_user.id):
        await q.answer('Solo DJ/admin.', show_alert=True); raise _V250Stop
    try:
        if '_update_current_dj_list_from_queue_v23' in globals():
            ok, name, added = _update_current_dj_list_from_queue_v23(chat_id)
            await q.answer((f'Lista actualizada: {name} · nuevas: {added}' if ok else 'No hay lista actual seleccionada.'), show_alert=not ok)
        else:
            await q.answer('Esta versión no tiene lista actual cargada.', show_alert=True)
    except Exception:
        logger.exception('V250 no pudo actualizar lista actual')
        await q.answer('No pude actualizar lista actual.', show_alert=True)
    try:
        await ensure_control_panel(context.bot, chat_id)
    except Exception:
        pass
    raise _V250Stop


