_old_build_application_v250 = build_application

def build_application() -> Application:
    app = _old_build_application_v250()
    app.add_handler(CallbackQueryHandler(_v250_summary_router, pattern=r'^v250sum\|'), group=-20000000010)
    app.add_handler(CallbackQueryHandler(_v250_dj_router, pattern=r'^panel_update_current\|'), group=-20000000010)
    logger.info('V250 cargado: resumen paginado, vistas DJ/juegos/validación, estilos visuales, ir al grupo y actualización de lista actual')
    return app


