def _v251_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    pages = cfg.get('summary_pages_v251')
    if not isinstance(pages, list) or not pages:
        cfg['summary_pages_v251'] = json.loads(json.dumps(V251_DEFAULT_PAGES, ensure_ascii=False))
    cfg.setdefault('summary_page_index_v251', int(cfg.get('summary_page_v250', 0) or 0))
    cfg.setdefault('summary_show_title_v251', True)
    return cfg


def _v251_pages(chat_id: int) -> List[Dict[str, Any]]:
    cfg = _v251_cfg(int(chat_id))
    pages = cfg.get('summary_pages_v251')
    if not isinstance(pages, list) or not pages:
        pages = json.loads(json.dumps(V251_DEFAULT_PAGES, ensure_ascii=False))
        cfg['summary_pages_v251'] = pages

    for i, p in enumerate(pages):
        if not isinstance(p, dict):
            pages[i] = dict(V251_DEFAULT_PAGES[0]); p = pages[i]
        p.setdefault('id', f'page{i+1}')
        p.setdefault('title', f'📄 Panel {i+1}')
        p['cols'] = max(1, min(3, int(p.get('cols', 2) or 2)))
        p.setdefault('style', 'none')
        p['style'] = str(p.get('style') or 'none') if str(p.get('style') or 'none') in ('none','row','col','soft') else 'none'
        try:
            p['abbr_len'] = max(0, min(8, int(p.get('abbr_len', 0) or 0)))
        except Exception:
            p['abbr_len'] = 0
        if not isinstance(p.get('fields'), list):
            p['fields'] = []
    return pages


def _v251_page_index(chat_id: int) -> int:
    pages = _v251_pages(int(chat_id))
    try:
        idx = int(_v251_cfg(int(chat_id)).get('summary_page_index_v251', 0) or 0)
    except Exception:
        idx = 0
    return max(0, min(idx, len(pages)-1))


def _v251_current_page(chat_id: int) -> Dict[str, Any]:
    return _v251_pages(int(chat_id))[_v251_page_index(int(chat_id))]


def _v251_effective_abbr_len(page: Dict[str, Any]) -> int:
    forced = int(page.get('abbr_len', 0) or 0)
    if forced > 0:
        return forced
    cols = int(page.get('cols', 2) or 2)
    return 4 if cols >= 3 else 5 if cols == 2 else 6


def _v251_cell_width(page: Dict[str, Any]) -> int:
    cols = max(1, min(3, int(page.get('cols', 2) or 2)))

    return 30 if cols == 1 else 22 if cols == 2 else 15


