def _v251_value(chat_id: int, key: str) -> str:

    try:
        k = str(key or '')
        if k in {
            'perf_load','perf_state','perf_lag','perf_tasks','saving_mode','saving_level',
            'mod_dj','mod_rec','mod_frase','mod_hot','mod_pregonero','mod_limpieza','mod_validacion',
            'audio_opt','audio_kbps','auto_v338','seq_v338','priv_light'
        }:
            try:
                score, label = _v339_score(int(chat_id)) if '_v339_score' in globals() else (0, '🟢 Fluido')
            except Exception:
                score, label = 0, '🟢 Fluido'
            cfg_dj = _v339_cfg(int(chat_id)) if '_v339_cfg' in globals() else admin_cfg(int(chat_id))
            cfg_perf = _v336_cfg(int(chat_id)) if '_v336_cfg' in globals() else admin_cfg(int(chat_id))
            mods = cfg_perf.get('perf_modules_v336', {}) if isinstance(cfg_perf, dict) else {}
            if k == 'perf_load': return f'{int(score)}%'
            if k == 'perf_state': return str(label).replace('🟢 ', '').replace('🟡 ', '').replace('🟠 ', '').replace('🔴 ', '')[:10]
            if k == 'perf_lag':
                lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0) if 'V336_PERF_RUNTIME' in globals() else 0.0
                return f'{lag:.0f}ms'
            if k == 'perf_tasks': return str(_v336_task_count() if '_v336_task_count' in globals() else 0)
            if k == 'saving_mode': return 'ON' if bool(cfg_perf.get('perf_saving_mode_v336', False)) else 'OFF'
            if k == 'saving_level': return str(_v336_saving_level(int(chat_id)) if '_v336_saving_level' in globals() else 0)
            if k == 'mod_dj': return 'ON' if bool(mods.get('dj', True)) else 'OFF'
            if k == 'mod_rec': return 'ON' if bool(mods.get('recurrentes', True)) else 'OFF'
            if k == 'mod_frase': return 'ON' if bool(mods.get('frase', True)) else 'OFF'
            if k == 'mod_hot': return 'ON' if bool(mods.get('hot', True)) else 'OFF'
            if k == 'mod_pregonero': return 'ON' if bool(mods.get('pregonero', True)) else 'OFF'
            if k == 'mod_limpieza': return 'ON' if bool(mods.get('limpieza', True)) else 'OFF'
            if k == 'mod_validacion': return 'ON' if bool(mods.get('validacion', True)) else 'OFF'
            if k == 'audio_opt': return 'ON' if bool(cfg_dj.get('dj_audio_optimize_v338', True)) else 'OFF'
            if k == 'audio_kbps': return f"{int(cfg_dj.get('dj_audio_kbps_v338', 96) or 96)}k"
            if k == 'auto_v338': return 'ON' if bool(cfg_dj.get('dj_auto_engine_v338', True)) else 'OFF'
            if k == 'seq_v338': return 'ON' if bool(cfg_dj.get('dj_auto_force_sequential_v338', True)) else 'OFF'
            if k == 'priv_light': return 'ON' if bool(cfg_dj.get('dj_light_refresh_v338', True)) else 'OFF'
    except Exception:
        logger.exception('V341 valor rendimiento resumen')
    try:
        val = _v239_summary_value(int(chat_id), key) if '_v239_summary_value' in globals() else ''
        if val not in (None, ''):
            return str(val)
    except Exception:
        pass
    try:
        return _v233_summary_value(int(chat_id), key) if '_v233_summary_value' in globals() else '—'
    except Exception:
        return '—'


def _v251_clean_abbr(raw: str, n: int) -> str:
    s = ''.join(ch for ch in str(raw or '').upper() if ch.isalnum()) or 'DATO'
    return s[:n].ljust(n)[:n]


def _v251_short_val(raw: str, max_len: int) -> str:
    raw = str(raw or '—').replace('\n',' ').replace('\r',' ')
    raw = ' '.join(raw.split()) or '—'
    return raw if len(raw) <= max_len else raw[:max(1,max_len-1)] + '…'


def _v251_cell(chat_id: int, key: str, page: Dict[str, Any], col_i: int, row_i: int) -> str:
    specs = _v251_specs()
    spec = specs.get(key, {'icon':'•','abbr':str(key).upper()[:5], 'name':str(key)})
    icon = str(spec.get('icon') or '•')[:2]
    abbr_len = _v251_effective_abbr_len(page)
    abbr = _v251_clean_abbr(spec.get('abbr') or key, abbr_len)
    width = _v251_cell_width(page)
    val = _v251_short_val(_v251_value(int(chat_id), key), max(3, width - (len(icon) + abbr_len + 2)))
    style = str(page.get('style','none') or 'none')
    marker = ''
    if style == 'row':
        marker = '▸' if row_i % 2 == 0 else '▫'
    elif style == 'col':
        marker = ['▸','▫','▪'][col_i % 3]
    elif style == 'soft':
        marker = '·'

    marker = marker or ' '
    txt = f'{marker}{icon}{abbr}:{val}'
    return txt[:width].ljust(width)


def _v251_summary_lines(chat_id: int, page: Optional[Dict[str, Any]] = None) -> List[str]:
    page = page or _v251_current_page(int(chat_id))
    cols = max(1, min(3, int(page.get('cols', 2) or 2)))
    fields = [str(x) for x in (page.get('fields') or []) if str(x)]
    if not fields:
        fields = ['validation_status','dj','pending','version']
    out: List[str] = []
    for row_i, start in enumerate(range(0, len(fields), cols)):
        cells = [_v251_cell(int(chat_id), k, page, col_i, row_i) for col_i, k in enumerate(fields[start:start+cols])]
        out.append(''.join(cells).rstrip())
    return out or ['—']


def _v250_summary_lines(chat_id: int) -> List[str]:
    return _v251_summary_lines(int(chat_id))

def _v232_summary_lines(chat_id: int) -> List[str]:
    return _v251_summary_lines(int(chat_id))


