def _v251_summary_header(chat_id: int) -> str:
    pages = _v251_pages(int(chat_id))
    idx = _v251_page_index(int(chat_id))
    page = pages[idx]
    summary = '\n'.join(_v251_summary_lines(int(chat_id), page))
    show_title = bool(_v251_cfg(int(chat_id)).get('summary_show_title_v251', True))
    title = f'<b>{h(str(page.get("title") or f"Panel {idx+1}"))}</b> <code>{idx+1}/{len(pages)}</code>\n' if show_title else ''
    return f'{title}<pre>{h(summary)}</pre>'


