_old_v251_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    try:
        base = _old_v251_admin_private_main_markup(int(chat_id))
        rows = [list(r) for r in (base.inline_keyboard or [])]
    except Exception:
        rows = []

    filtered = []
    for r in rows:
        flat = '|'.join(str(getattr(b, 'callback_data', '') or '') for b in r)
        texts = ' '.join(str(getattr(b, 'text', '') or '') for b in r)
        if 'v250sum|' in flat or 'Columnas ' in texts or 'Estilo ' in texts:
            continue
        filtered.append(r)
    pages = _v251_pages(int(chat_id))
    idx = _v251_page_index(int(chat_id))
    prev_i = (idx - 1) % len(pages)
    next_i = (idx + 1) % len(pages)
    nav = [[
        InlineKeyboardButton('◀️ Resumen', callback_data=f'v251sum|page|{int(chat_id)}|{prev_i}'),
        InlineKeyboardButton(str(pages[idx].get('title') or f'Panel {idx+1}')[:24], callback_data=f'v251sum|menu|{int(chat_id)}'),
        InlineKeyboardButton('Resumen ▶️', callback_data=f'v251sum|page|{int(chat_id)}|{next_i}'),
    ]]
    return InlineKeyboardMarkup(nav + filtered)


