def _v251_fields_markup(chat_id: int, page_no: int = 0, mode: str = 'fields') -> InlineKeyboardMarkup:
    pages = _v251_pages(int(chat_id)); idx = _v251_page_index(int(chat_id)); p = pages[idx]
    specs = _v251_specs(); active = [str(x) for x in (p.get('fields') or [])]
    per = 10
    total = max(1, ((len(V251_AVAILABLE_FIELDS)-1)//per)+1)
    page_no = max(0, min(int(page_no or 0), total-1))
    chunk = V251_AVAILABLE_FIELDS[page_no*per:(page_no+1)*per]
    rows: List[List[InlineKeyboardButton]] = []
    for k in chunk:
        spec = specs.get(k, {'name':k})
        mark = '✅' if k in active else '⬜'
        rows.append([InlineKeyboardButton(f'{mark} {spec.get("icon","")} {spec.get("name",k)}', callback_data=f'v251sum|togglefield|{chat_id}|{page_no}|{k}')])
    nav=[]
    if page_no>0: nav.append(InlineKeyboardButton('⬅️', callback_data=f'v251sum|fields|{chat_id}|{page_no-1}'))
    nav.append(InlineKeyboardButton(f'{page_no+1}/{total}', callback_data=f'v251sum|noop|{chat_id}'))
    if page_no<total-1: nav.append(InlineKeyboardButton('➡️', callback_data=f'v251sum|fields|{chat_id}|{page_no+1}'))
    rows.append(nav)
    rows.append([InlineKeyboardButton('🧾 Volver resumen', callback_data=f'v251sum|menu|{chat_id}')])
    return InlineKeyboardMarkup(rows)


def _v251_order_markup(chat_id: int, page_no: int = 0) -> InlineKeyboardMarkup:
    pages = _v251_pages(int(chat_id)); idx = _v251_page_index(int(chat_id)); p = pages[idx]
    specs = _v251_specs(); fields = [str(x) for x in (p.get('fields') or [])]
    per=8; total=max(1, ((len(fields)-1)//per)+1); page_no=max(0,min(int(page_no or 0), total-1))
    chunk = fields[page_no*per:(page_no+1)*per]
    rows=[]
    for rel,k in enumerate(chunk):
        pos=page_no*per+rel
        name = specs.get(k, {'name':k}).get('name', k)
        rows.append([
            InlineKeyboardButton(f'{pos+1}. {name[:18]}', callback_data=f'v251sum|noop|{chat_id}'),
            InlineKeyboardButton('⬆️', callback_data=f'v251sum|upfield|{chat_id}|{page_no}|{pos}'),
            InlineKeyboardButton('⬇️', callback_data=f'v251sum|downfield|{chat_id}|{page_no}|{pos}'),
            InlineKeyboardButton('❌', callback_data=f'v251sum|removefield|{chat_id}|{page_no}|{pos}'),
        ])
    nav=[]
    if page_no>0: nav.append(InlineKeyboardButton('⬅️', callback_data=f'v251sum|order|{chat_id}|{page_no-1}'))
    nav.append(InlineKeyboardButton(f'{page_no+1}/{total}', callback_data=f'v251sum|noop|{chat_id}'))
    if page_no<total-1: nav.append(InlineKeyboardButton('➡️', callback_data=f'v251sum|order|{chat_id}|{page_no+1}'))
    rows.append(nav)
    rows.append([InlineKeyboardButton('🧾 Volver resumen', callback_data=f'v251sum|menu|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v251_summary_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v251sum|'):
        return
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V251Stop
    parts=(q.data or '').split('|')
    action=parts[1] if len(parts)>1 else 'menu'
    try: chat_id=int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V251Stop
    cfg=_v251_cfg(chat_id); pages=_v251_pages(chat_id); idx=_v251_page_index(chat_id); p=pages[idx]
    try:
        if action == 'noop':
            await q.answer(); raise _V251Stop
        if action == 'page':
            new_i=max(0,min(int(parts[3]) if len(parts)>3 else 0, len(pages)-1))
            cfg['summary_page_index_v251']=new_i; cfg['summary_page_v250']=new_i; save_all_states()
            await q.answer('Panel cambiado')

            try:
                await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
            except Exception:
                await q.edit_message_text(_v251_summary_menu_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v251_summary_menu_markup(chat_id))
            raise _V251Stop
        if action == 'cols':
            p['cols'] = 1 if int(p.get('cols',2) or 2) >= 3 else int(p.get('cols',2) or 2)+1
            save_all_states(); await q.answer(f"Columnas de este panel: {p['cols']}")
        elif action == 'style':
            seq=['none','row','col','soft']; cur=str(p.get('style','none'))
            p['style']=seq[(seq.index(cur)+1)%len(seq)] if cur in seq else 'none'
            save_all_states(); await q.answer(f"Estilo: {p['style']}")
        elif action == 'abbr':
            seq=[0,3,4,5,6,7,8]; cur=int(p.get('abbr_len',0) or 0)
            p['abbr_len']=seq[(seq.index(cur)+1)%len(seq)] if cur in seq else 0
            save_all_states(); await q.answer('Letras actualizadas')
        elif action == 'title':
            cfg['summary_show_title_v251']=not bool(cfg.get('summary_show_title_v251', True)); save_all_states(); await q.answer('Título ON/OFF')
        elif action == 'addpage':
            n=len(pages)+1
            pages.append({'id':f'custom{n}_{int(__import__("time").time())}','title':f'📄 Panel {n}','cols':2,'style':'none','abbr_len':0,'fields':[]})
            cfg['summary_page_index_v251']=len(pages)-1; cfg['summary_page_v250']=len(pages)-1; save_all_states(); await q.answer('Panel creado ✅')
        elif action == 'delpage':
            if len(pages) <= 1:
                await q.answer('No puedes borrar el único panel.', show_alert=True)
            else:
                pages.pop(idx); cfg['summary_page_index_v251']=max(0,min(idx,len(pages)-1)); cfg['summary_page_v250']=cfg['summary_page_index_v251']; save_all_states(); await q.answer('Panel borrado')
        elif action == 'resetpage':
            default = json.loads(json.dumps(V251_DEFAULT_PAGES[min(idx, len(V251_DEFAULT_PAGES)-1)], ensure_ascii=False))
            pages[idx].update(default); save_all_states(); await q.answer('Panel recomendado restaurado')
        elif action == 'fields':
            page_no=int(parts[3]) if len(parts)>3 else 0
            await q.edit_message_text('<b>➕ Añadir/quitar datos del resumen</b>\n\nMarca lo que quieres ver en este panel.', parse_mode=ParseMode.HTML, reply_markup=_v251_fields_markup(chat_id, page_no))
            raise _V251Stop
        elif action == 'order':
            page_no=int(parts[3]) if len(parts)>3 else 0
            await q.edit_message_text('<b>↕️ Ordenar datos del resumen</b>\n\nSube, baja o quita datos de este panel.', parse_mode=ParseMode.HTML, reply_markup=_v251_order_markup(chat_id, page_no))
            raise _V251Stop
        elif action == 'togglefield':
            page_no=int(parts[3]) if len(parts)>3 else 0; key='|'.join(parts[4:])
            fields=[str(x) for x in (p.get('fields') or [])]
            if key in fields:
                fields=[x for x in fields if x != key]; await q.answer('Quitado')
            else:
                fields.append(key); await q.answer('Añadido ✅')
            p['fields']=fields; save_all_states()
            await q.edit_message_text('<b>➕ Añadir/quitar datos del resumen</b>\n\nMarca lo que quieres ver en este panel.', parse_mode=ParseMode.HTML, reply_markup=_v251_fields_markup(chat_id, page_no))
            raise _V251Stop
        elif action in ('upfield','downfield','removefield'):
            page_no=int(parts[3]) if len(parts)>3 else 0; pos=int(parts[4]) if len(parts)>4 else 0
            fields=[str(x) for x in (p.get('fields') or [])]
            if 0 <= pos < len(fields):
                if action == 'removefield':
                    fields.pop(pos); await q.answer('Quitado')
                elif action == 'upfield' and pos > 0:
                    fields[pos-1], fields[pos] = fields[pos], fields[pos-1]; await q.answer('Subido')
                elif action == 'downfield' and pos < len(fields)-1:
                    fields[pos+1], fields[pos] = fields[pos], fields[pos+1]; await q.answer('Bajado')
            p['fields']=fields; save_all_states()
            await q.edit_message_text('<b>↕️ Ordenar datos del resumen</b>\n\nSube, baja o quita datos de este panel.', parse_mode=ParseMode.HTML, reply_markup=_v251_order_markup(chat_id, page_no))
            raise _V251Stop
        elif action == 'refresh':
            await q.answer('Actualizado')
        else:
            await q.answer()
        await q.edit_message_text(_v251_summary_menu_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v251_summary_menu_markup(chat_id))
    except _V251Stop:
        raise
    except Exception:
        logger.exception('V251 summary router falló: %s', q.data)
        await q.answer('Error en resumen rápido. Mira logs.', show_alert=True)
    raise _V251Stop


async def _v251_legacy_v250_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v250sum|'):
        return
    parts=(q.data or '').split('|')
    action=parts[1] if len(parts)>1 else ''
    try: chat_id=int(parts[2])
    except Exception: chat_id=int(update.effective_chat.id) if update.effective_chat else 0
    if action == 'page' and len(parts)>3:
        _v251_cfg(chat_id)['summary_page_index_v251']=int(parts[3]); save_all_states()
        await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
    else:
        await q.edit_message_text(_v251_summary_menu_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v251_summary_menu_markup(chat_id))
    raise _V251Stop

