def _v252_dedupe_keep_order(items: List[Any]) -> List[str]:
    """Elimina duplicados exactos conservando el orden configurado por el usuario."""
    out: List[str] = []
    seen: set[str] = set()
    for raw in list(items or []):
        key = str(raw or '').strip()
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(key)
    return out


def _v252_block_items(chat_id: int, block: Dict[str, Any]) -> List[str]:
    """Items de un bloque, limpios, válidos y sin duplicados."""
    try:
        available = _v171_available_panel_items() if '_v171_available_panel_items' in globals() else {}
    except Exception:
        available = {}
    items = _v252_dedupe_keep_order(block.get('items') or [])
    return [k for k in items if k in available]


def _v252_summary_enabled_in_blocks(chat_id: int) -> bool:
    """Por defecto sí: el resumen se ve al entrar en un bloque, no en subpantallas concretas."""
    try:
        cfg = _v251_cfg(int(chat_id)) if '_v251_cfg' in globals() else _v171_panel_cfg(int(chat_id))
        return bool(cfg.get('summary_in_block_menu_v252', True))
    except Exception:
        return True


