def _v253_summary_nav_row(chat_id: int) -> List[InlineKeyboardButton]:
    """Fila de navegación del resumen para pantallas de bloque."""
    try:
        pages = _v251_pages(int(chat_id)) if '_v251_pages' in globals() else []
        if not pages:
            return []
        idx = _v251_page_index(int(chat_id)) if '_v251_page_index' in globals() else 0
        idx = max(0, min(int(idx), len(pages)-1))
        prev_i = (idx - 1) % len(pages)
        next_i = (idx + 1) % len(pages)
        name = str(pages[idx].get('title') or f'Panel {idx+1}')[:22]
        return [
            InlineKeyboardButton('◀️ Resumen', callback_data=f'v251sum|page|{int(chat_id)}|{prev_i}'),
            InlineKeyboardButton(name, callback_data=f'v251sum|menu|{int(chat_id)}'),
            InlineKeyboardButton('Resumen ▶️', callback_data=f'v251sum|page|{int(chat_id)}|{next_i}'),
        ]
    except Exception:
        return []


