def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    try:

        if block == 'impostor_settings':
            return _v253_short_imp_text(int(chat_id))
        txt = _old_v253_admin_private_block_text(int(chat_id), block, page)

        if block not in ('quick_summary', 'summary', 'resumen_rapido') and txt.count('<pre>') >= 1:

            stripped = txt.lstrip()
            if stripped.startswith('<b>') and '</pre>' in stripped and stripped.find('</pre>') < 800:
                end = stripped.find('</pre>') + len('</pre>')
                rest = stripped[end:].lstrip('\n ')

                if rest:
                    txt = rest
        return txt
    except Exception:
        logger.exception('V253 no pudo pintar texto bloque/subopción')
        return _old_v253_admin_private_block_text(int(chat_id), block, page)


async def _v253_refresh_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    data = q.data or ''
    if not data.startswith('cfg241|refresh|'):
        return
    try:
        chat_id = int(data.split('|')[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not update.effective_user or not is_global_admin_user(update.effective_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V253Stop
    try:
        load_all_states()
    except Exception:
        pass
    save_all_states()
    try:
        await q.answer('Actualizado')
    except Exception:
        pass
    try:
        await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
    except BadRequest as e:
        if 'message is not modified' not in str(e).lower():
            raise
    raise _V253Stop


async def _v253_admin_private_config_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    if not is_global_admin_user(update.effective_user.id):
        await update.message.reply_text('Solo ADMIN_IDS puede abrir la configuración privada.')
        raise _V253Stop
    if update.effective_chat and update.effective_chat.type != 'private':
        await update.message.reply_text('Escríbeme /ajustes por privado para configurar el grupo sin ensuciar el chat.')
        raise _V253Stop
    load_all_states()
    key = f'v253:last_cfg_panel:{int(update.effective_user.id)}'
    old_mid = None
    old = PENDING_ACTIONS.get(key)
    if isinstance(old, dict):
        try:
            old_mid = int(old.get('message_id') or 0)
        except Exception:
            old_mid = None
    if old_mid:
        try:
            await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=old_mid)
        except Exception:
            pass
    if not known_admin_chats_for_private():
        msg = await update.message.reply_text('Todavía no tengo grupos registrados. Usa /plan una vez dentro del grupo o espera a que entre alguien.')
    else:
        msg = await update.message.reply_html('<b>Elige el grupo que quieres configurar:</b>', reply_markup=admin_private_chat_list_markup())
    try:
        PENDING_ACTIONS[key] = {'message_id': int(msg.message_id), 'ts': int(time.time())}
    except Exception:
        pass
    raise _V253Stop


def _v253_group_deleted(chat_id: int) -> bool:
    try:
        return bool(cfg_value(int(chat_id), 'deleted_from_group_selector_v253', False))
    except Exception:
        return False


def _v253_set_group_deleted(chat_id: int, value: bool) -> None:
    try:
        cfg_set(int(chat_id), 'deleted_from_group_selector_v253', bool(value))
        if bool(value):
            _v231_set_group_hidden(int(chat_id), True)
    except Exception:
        st = get_state(int(chat_id))
        if not isinstance(st.admin_config, dict):
            st.admin_config = {}
        st.admin_config['deleted_from_group_selector_v253'] = bool(value)
        if bool(value):
            st.admin_config['hidden_from_group_selector_v231'] = True
        save_all_states()


def _v253_group_is_visible(chat_id: int) -> bool:
    try:
        title = str(cfg_value(int(chat_id), 'chat_title', '') or get_chat_title(int(chat_id)) or '').strip()
        if not title or title == str(int(chat_id)):
            return False
        if _v253_group_deleted(int(chat_id)):
            return False
        if '_v231_group_hidden' in globals() and _v231_group_hidden(int(chat_id)):
            return False
        return True
    except Exception:
        return False


def _v231_known_chats(include_hidden: bool = False) -> List[int]:
    try:
        chats = [int(x) for x in known_admin_chats_for_private()]
    except Exception:
        chats = sorted([int(x) for x in STATE_CACHE.keys()])
    out: List[int] = []
    for cid in chats:
        if _v253_group_deleted(cid):
            if include_hidden:

                continue
            continue
        if include_hidden or _v253_group_is_visible(cid):
            out.append(cid)
    return out


def admin_private_chat_list_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    chats = [cid for cid in _v231_known_chats(False) if _v253_group_is_visible(cid)]
    if not chats:
        rows.append([InlineKeyboardButton('No hay grupos visibles con nombre', callback_data='cfg231|noop')])
    for chat_id in chats:
        title = _v253_title(chat_id)
        rows.append([
            InlineKeyboardButton(f'⚙️ {truncated_button_title(title, 34)}', callback_data=f'cfg|open|{int(chat_id)}'),
            InlineKeyboardButton('🙈 Ocultar', callback_data=f'cfg231|hide|{int(chat_id)}'),
        ])
    hidden = []
    try:
        hidden = [cid for cid in known_admin_chats_for_private() if (not _v253_group_deleted(cid)) and (not _v253_group_is_visible(cid))]
    except Exception:
        hidden = []
    if hidden:
        rows.append([InlineKeyboardButton(f'👁 Ver ocultos/sin nombre ({len(hidden)})', callback_data='cfg231|hidden')])
    rows.append([InlineKeyboardButton('🔄 Actualizar lista', callback_data='cfg|list')])
    return InlineKeyboardMarkup(rows)


def _v231_hidden_groups_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
