async def _v253_group_selector_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.data:
        return
    data = q.data or ''

    if not (data.startswith('cfg231|') or data.startswith('sec|')):
        return
    if not update.effective_user or not (is_global_admin_user(update.effective_user.id) or (('is_owner_id' in globals()) and is_owner_id(update.effective_user.id))):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V253Stop
    parts = data.split('|')
    ns = parts[0]
    action = parts[1] if len(parts) > 1 else ''
    if ns == 'cfg231':
        if action == 'delask' and len(parts) >= 3:
            cid = int(parts[2])
            await q.answer()
            await q.edit_message_text(
                f'<b>🗑 Borrar grupo del bot</b>\n\nGrupo: <b>{h(_v253_title(cid))}</b>\nID: <code>{cid}</code>\n\nEsto lo quitará del selector y marcará su configuración como borrada. No expulsa al bot del grupo.',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton('🗑 Sí, borrar', callback_data=f'cfg231|delete|{cid}')],
                    [InlineKeyboardButton('🔙 Volver ocultos', callback_data='cfg231|hidden')],
                ])
            )
            raise _V253Stop
        if action == 'delete' and len(parts) >= 3:
            cid = int(parts[2])
            _v253_set_group_deleted(cid, True)
            await q.answer('Grupo borrado del selector')
            await q.edit_message_text('<b>Grupos ocultos/sin nombre</b>', parse_mode=ParseMode.HTML, reply_markup=_v231_hidden_groups_markup())
            raise _V253Stop
        if action in ('hide','show') and len(parts) >= 3:
            cid = int(parts[2])
            _v253_set_group_deleted(cid, False)
            _v231_set_group_hidden(cid, action == 'hide')
            await q.answer('Grupo ocultado' if action == 'hide' else 'Grupo visible')
            if action == 'show':
                await q.edit_message_text('<b>Grupos ocultos/sin nombre</b>', parse_mode=ParseMode.HTML, reply_markup=_v231_hidden_groups_markup())
            else:
                await q.edit_message_text('<b>Elige el grupo que quieres configurar:</b>', parse_mode=ParseMode.HTML, reply_markup=admin_private_chat_list_markup())
            raise _V253Stop

        return
    if ns == 'sec':
        if action in ('hide','show') and len(parts) >= 3:
            cid = int(parts[2])
            _v253_set_group_deleted(cid, False)
            _v231_set_group_hidden(cid, action == 'hide')
            await q.answer('Oculto del selector' if action == 'hide' else 'Visible en selector')
            await q.edit_message_text(_v219_group_text(cid), parse_mode=ParseMode.HTML, reply_markup=_v219_group_markup(cid))
            raise _V253Stop
        if action == 'deleteask' and len(parts) >= 3:
            cid = int(parts[2])
            await q.answer()
            await q.edit_message_text(
                f'<b>🗑 Borrar definitivamente</b>\n\nGrupo: <b>{h(_v253_title(cid))}</b>\nID: <code>{cid}</code>\n\nSe quitará de selectores y listados visibles. Puedes volver a registrarlo si el bot vuelve a ver actividad en ese grupo.',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton('🗑 Confirmar borrado', callback_data=f'sec|delete|{cid}')],
                    [InlineKeyboardButton('🔙 Volver grupo', callback_data=f'sec|group|{cid}')],
                ])
            )
            raise _V253Stop
        if action == 'delete' and len(parts) >= 3:
            cid = int(parts[2])
            _v253_set_group_deleted(cid, True)
            await q.answer('Grupo borrado')
            await q.edit_message_text(_v219_security_menu_text(), parse_mode=ParseMode.HTML, reply_markup=_v219_security_menu_markup())
            raise _V253Stop
    return


