def _v254_summary_nav_labels(chat_id: int) -> tuple[str, str, str, int, int, int]:
    """Devuelve etiquetas compactas y páginas para navegación del resumen."""
    try:
        pages = _v251_pages(int(chat_id)) if '_v251_pages' in globals() else []
        if not pages:
            return ('◀️ Anterior', 'Panel', 'Siguiente ▶️', 0, 0, 0)
        idx = _v251_page_index(int(chat_id)) if '_v251_page_index' in globals() else 0
        idx = max(0, min(int(idx), len(pages)-1))
        prev_i = (idx - 1) % len(pages)
        next_i = (idx + 1) % len(pages)
        title = str(pages[idx].get('title') or f'Panel {idx+1}')[:22]
        return ('◀️ Anterior', title, 'Siguiente ▶️', idx, prev_i, next_i)
    except Exception:
        return ('◀️ Anterior', 'Panel', 'Siguiente ▶️', 0, 0, 0)


def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:
    try:
        base = _old_v251_admin_private_main_markup(int(chat_id)) if '_old_v251_admin_private_main_markup' in globals() else _old_v253_admin_private_main_markup(int(chat_id))
        rows = [list(r) for r in (base.inline_keyboard or [])]
    except Exception:
        rows = []
    filtered = []
    for r in rows:
        flat = '|'.join(str(getattr(b, 'callback_data', '') or '') for b in r)
        texts = ' '.join(str(getattr(b, 'text', '') or '') for b in r)
        if 'v250sum|' in flat or 'v251sum|page|' in flat or 'Columnas ' in texts or 'Estilo ' in texts:
            continue
        filtered.append(r)
    _prev_txt, title, _next_txt, idx, prev_i, next_i = _v254_summary_nav_labels(int(chat_id))
    nav = [[
        InlineKeyboardButton('◀️ Anterior', callback_data=f'v254sum|mainpage|{int(chat_id)}|{prev_i}'),
        InlineKeyboardButton(title, callback_data=f'v251sum|menu|{int(chat_id)}'),
        InlineKeyboardButton('Siguiente ▶️', callback_data=f'v254sum|mainpage|{int(chat_id)}|{next_i}'),
    ]]
    return InlineKeyboardMarkup(nav + filtered)


