async def _v254_summary_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v254sum|'):
        return
    if not q.from_user or not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V254Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V254Stop
    try:
        if action == 'mainpage':
            page = int(parts[3]) if len(parts) > 3 else 0
            cfg = _v251_cfg(chat_id)
            pages = _v251_pages(chat_id)
            page = max(0, min(page, len(pages)-1))
            cfg['summary_page_index_v251'] = page
            cfg['summary_page_v250'] = page
            save_all_states()
            await q.answer('Panel cambiado')
            await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
            raise _V254Stop
        if action == 'blockpage':
            if len(parts) < 5:
                await q.answer('Bloque inválido', show_alert=True)
                raise _V254Stop
            block_id = parts[3]
            page = int(parts[4])
            cfg = _v251_cfg(chat_id)
            pages = _v251_pages(chat_id)
            page = max(0, min(page, len(pages)-1))
            cfg['summary_page_index_v251'] = page
            cfg['summary_page_v250'] = page
            save_all_states()
            await q.answer('Panel cambiado')
            await q.edit_message_text(_v226_custom_block_text(chat_id, block_id), parse_mode=ParseMode.HTML, reply_markup=_v226_custom_block_markup(chat_id, block_id))
            raise _V254Stop
    except _V254Stop:
        raise
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            await q.answer('Ya está actualizado')
            raise _V254Stop
        logger.exception('V254 summary router BadRequest')
        await q.answer('No pude cambiar el panel.', show_alert=True)
        raise _V254Stop
    except Exception:
        logger.exception('V254 summary router falló: %s', q.data)
        await q.answer('Error al cambiar panel.', show_alert=True)
        raise _V254Stop
    raise _V254Stop


async def _v254_send_validation_expulsion_notice(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int, *, action: str = 'kick') -> None:
    """Publica el mensaje/gif configurado de rechazo/expulsión al expulsar desde Miembros."""
    try:
        st = get_state(int(chat_id))
        rec = dict(st.member_activity.get(str(user_id), {}))
        rec.update(st.validation_users.get(str(user_id), {}) if isinstance(st.validation_users, dict) else {})
        name = rec.get('name') or rec.get('username') or str(user_id)
        mention = f'<a href="tg://user?id={int(user_id)}">{h(name)}</a>'
        template = str(cfg_value(int(chat_id), 'validation_rejected_message', VALIDATION_REJECTED_MESSAGE) or VALIDATION_REJECTED_MESSAGE)

        text = (template
            .replace('{mention}', mention)
            .replace('{name}', h(str(name)))
            .replace('{first}', h(str(name).split()[0] if str(name).split() else str(name)))
            .replace('{username}', h(str(rec.get('username') or '')))
            .replace('{id}', str(int(user_id)))
            .replace('{chat}', h(_v253_title(int(chat_id)) if '_v253_title' in globals() else str(chat_id)))
        )
        if not text.strip():
            text = f'❌ Presentación rechazada. {mention} ha sido expulsado.'
        await send_configured_profile_message(context.bot, int(chat_id), 'rejected', text)
    except Exception:
        logger.exception('V254 no pudo enviar aviso configurado de expulsión desde miembros')


async def _v254_members_kick_notice_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Intercepta kick/ban desde Miembros para mandar el aviso configurado de validación rechazada."""
    q = update.callback_query
    if not q or not (q.data or '').startswith('members|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in ('kick', 'ban'):
        return
    if not q.from_user or not is_owner_id(q.from_user.id):
        await q.answer('Solo el dueño del bot.', show_alert=True)
        raise _V254Stop
    try:
        chat_id = int(parts[2]); user_id = int(parts[3]); page = int(parts[4]) if len(parts) > 4 else 0
    except Exception:
        await q.answer('Datos inválidos.', show_alert=True)
        raise _V254Stop
    try:
        rec = dict(get_state(chat_id).member_activity.get(str(user_id), {}))
        if action == 'kick':
            await context.bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
            await context.bot.unban_chat_member(chat_id=chat_id, user_id=user_id, only_if_banned=True)
            mark_user_expelled(chat_id, user_id, record=rec, reason='kick desde panel miembros', by_user_id=q.from_user.id)
            await q.answer('Expulsado ✅', show_alert=True)
        else:
            await context.bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
            mark_user_expelled(chat_id, user_id, record=rec, reason='ban desde panel miembros', by_user_id=q.from_user.id)
            await q.answer('Baneado ✅', show_alert=True)
        await _v254_send_validation_expulsion_notice(context, chat_id, user_id, action=action)
    except Exception as e:
        logger.exception('V254 no pudo expulsar/banear desde miembros')
        await q.answer('No pude ejecutar acción: ' + str(e)[:140], show_alert=True)
    try:
        await q.edit_message_text(_v219_member_text(chat_id, user_id), parse_mode=ParseMode.HTML, reply_markup=_v219_member_markup(chat_id, user_id, page))
    except Exception:
        pass
    raise _V254Stop


