async def validation_watchdog_loop(application: Application) -> None:
    """Watchdog reforzado: recordatorio + timeout + expulsión por chat configurado.

    La versión antigua dependía de VALIDATION_ENABLED global y podía quedarse sin actuar
    si la configuración real estaba en el state del grupo. Esta versión revisa cada grupo
    con validation_is_active_for_chat(chat_id).
    """
    while True:
        try:
            await asyncio.sleep(max(5, min(VALIDATION_WATCHDOG_SECONDS, 30)))
            now = _now_ts() if '_now_ts' in globals() else int(__import__('time').time())
            for chat_id, state in list(STATE_CACHE.items()):
                chat_id = int(chat_id)
                if not chat_is_allowed(chat_id):
                    continue
                if not validation_is_active_for_chat(chat_id):
                    continue

                timeout_min = max(1, int(cfg_value(chat_id, 'validation_timeout_minutes', VALIDATION_TIMEOUT_MINUTES) or VALIDATION_TIMEOUT_MINUTES))
                reminder_min = int(cfg_value(chat_id, 'validation_reminder_minutes', VALIDATION_REMINDER_MINUTES) or 0)
                kick_timeout = bool(cfg_value(chat_id, 'validation_kick_if_timeout', VALIDATION_KICK_IF_TIMEOUT))

                for user_id_str, record in list(state.validation_users.items()):
                    try:
                        status = str(record.get('status') or '')
                        if status not in ('answering',):
                            continue
                        user_id = int(user_id_str)
                        joined = int(record.get('joined_ts') or record.get('muted_ts') or now)


                        if not record.get('deadline_ts'):
                            record['deadline_ts'] = joined + timeout_min * 60
                        if reminder_min > 0 and not record.get('reminder_ts'):
                            record['reminder_ts'] = joined + min(reminder_min, timeout_min) * 60
                        validation_set_record(chat_id, user_id, record)

                        reminder_ts = int(record.get('reminder_ts') or 0)
                        deadline_ts = int(record.get('deadline_ts') or 0)

                        if reminder_min > 0 and reminder_ts and now >= reminder_ts and not bool(record.get('reminded')):
                            record['reminded'] = True
                            record['reminded_ts'] = now
                            validation_set_record(chat_id, user_id, record)
                            try:
                                await _v255_send_reminder_notice(application.bot, chat_id, user_id, record)
                                add_action_log(chat_id, 'recordatorio automático', record.get('name', str(user_id)))
                            except Exception:
                                logger.exception('V255 no pudo enviar recordatorio automático')

                        if deadline_ts and now >= deadline_ts and not bool(record.get('timeout_processed_v255')):
                            record['timeout_processed_v255'] = True
                            record['timeout_ts'] = now
                            record['status'] = 'timeout'
                            validation_set_record(chat_id, user_id, record)
                            try:
                                await _v255_send_timeout_notice(application.bot, chat_id, user_id, record)
                                add_action_log(chat_id, 'timeout presentación', record.get('name', str(user_id)))
                            except Exception:
                                logger.exception('V255 no pudo enviar aviso de timeout')

                            if kick_timeout:
                                ok = await _v255_kick_timeout_user(application.bot, chat_id, user_id, record)
                                record['status'] = 'kicked_timeout' if ok else 'timeout_kick_failed'
                                record['kicked_timeout_ts'] = now if ok else None
                                validation_set_record(chat_id, user_id, record)
                            else:
                                try:
                                    await validation_mute_bot(application.bot, chat_id, user_id)
                                except Exception:
                                    pass
                                validation_set_record(chat_id, user_id, record)
                    except Exception:
                        logger.exception('V255 error procesando registro de validación %s en %s', user_id_str, chat_id)
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V255 error general en watchdog de validación')


async def _v255_validation_check_report(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> str:
    def ck(ok: bool) -> str:
        return '✅' if ok else '❌'
    title = _v253_title(chat_id) if '_v253_title' in globals() else str(chat_id)
    cfg = admin_cfg(int(chat_id))
    questions = cfg_questions(int(chat_id))
    timeout_min = int(cfg_value(int(chat_id), 'validation_timeout_minutes', VALIDATION_TIMEOUT_MINUTES) or 0)
    reminder_min = int(cfg_value(int(chat_id), 'validation_reminder_minutes', VALIDATION_REMINDER_MINUTES) or 0)
    kick_timeout = bool(cfg_value(int(chat_id), 'validation_kick_if_timeout', VALIDATION_KICK_IF_TIMEOUT))
    active = validation_is_active_for_chat(int(chat_id))
    state = get_state(int(chat_id))
    answering = sum(1 for r in state.validation_users.values() if r.get('status') == 'answering')
    pending = sum(1 for r in state.validation_users.values() if r.get('status') == 'pending_admin')
    timed = sum(1 for r in state.validation_users.values() if str(r.get('status','')).startswith('timeout'))

    bot_admin = False; can_restrict = False; can_delete = False; can_invite = False; can_send = True
    try:
        me = await context.bot.get_me()
        member = await context.bot.get_chat_member(int(chat_id), me.id)
        status = getattr(member, 'status', '')
        bot_admin = status in ('administrator', 'creator')
        can_restrict = bool(getattr(member, 'can_restrict_members', False)) or status == 'creator'
        can_delete = bool(getattr(member, 'can_delete_messages', False)) or status == 'creator'
        can_invite = bool(getattr(member, 'can_invite_users', False)) or status == 'creator'
    except Exception:
        status = 'no leído'

    watchdog_ok = bool(VALIDATION_WATCHDOG_TASK and not VALIDATION_WATCHDOG_TASK.done())
    reminder_ok = reminder_min > 0 and (timeout_min <= 0 or reminder_min < timeout_min)
    timeout_ok = timeout_min > 0
    q_ok = bool(questions)

    lines = [
        '<b>🧪 Comprobación sistema de entradas</b>',
        f'Grupo: <b>{h(title)}</b>',
        '',
        f'{ck(active)} Entrada/validación activa: <b>{bool_label(active)}</b>',
        f'{ck(q_ok)} Preguntas configuradas: <b>{len(questions)}</b>',
        f'{ck(can_restrict)} Permiso restringir/expulsar: <b>{"OK" if can_restrict else "FALTA"}</b>',
        f'{ck(can_delete)} Permiso borrar mensajes: <b>{"OK" if can_delete else "FALTA"}</b>',
        f'{ck(can_invite)} Permiso aprobar solicitudes: <b>{"OK" if can_invite else "FALTA/NO NECESARIO"}</b>',
        f'{ck(watchdog_ok)} Motor recordatorio/timeout: <b>{"ACTIVO" if watchdog_ok else "PARADO"}</b>',
        f'{ck(reminder_ok)} Recordatorio: <b>{reminder_min} min</b>',
        f'{ck(timeout_ok)} Timeout presentación: <b>{timeout_min} min</b>',
        f'{ck(kick_timeout and can_restrict)} Expulsar si no responde: <b>{bool_label(kick_timeout)}</b>',
        '',
        f'📝 Contestando ahora: <b>{answering}</b>',
        f'✅ Pendientes de validar: <b>{pending}</b>',
        f'⏱ Timeouts registrados: <b>{timed}</b>',
        '',
        '<b>Flujo esperado:</b>',
        '1) Entra miembro → queda limitado a texto.',
        '2) Contesta preguntas → pasa a pendiente admin.',
        '3) Si no contesta → recordatorio.',
        '4) Si agota tiempo → aviso de timeout + expulsión automática.',
    ]
    if reminder_min >= timeout_min and timeout_min > 0:
        lines.append('\n⚠️ El recordatorio debe ser menor que el timeout para que salte antes de expulsar.')
    if not can_restrict:
        lines.append('\n⚠️ Da al bot permiso de admin para <b>Banear usuarios / restringir miembros</b>.')
    return '\n'.join(lines)


