def _v255_pages_order_text(chat_id: int) -> str:
    pages = _v251_pages(int(chat_id))
    cur = _v251_page_index(int(chat_id))
    lines = ['<b>↕️ Ordenar paneles de resumen</b>', '', 'Sube o baja cada panel. El orden será el que verás con Anterior/Siguiente.', '']
    for i,p in enumerate(pages):
        mark = '👉 ' if i == cur else ''
        lines.append(f'{mark}{i+1}. {h(str(p.get("title") or f"Panel {i+1}"))}')
    return '\n'.join(lines)


def _v255_pages_order_markup(chat_id: int) -> InlineKeyboardMarkup:
    pages = _v251_pages(int(chat_id))
    rows: List[List[InlineKeyboardButton]] = []
    for i,p in enumerate(pages):
        title = str(p.get('title') or f'Panel {i+1}')[:18]
        rows.append([
            InlineKeyboardButton(f'{i+1}. {title}', callback_data=f'v255sum|noop|{int(chat_id)}'),
            InlineKeyboardButton('⬆️', callback_data=f'v255sum|uppage|{int(chat_id)}|{i}'),
            InlineKeyboardButton('⬇️', callback_data=f'v255sum|downpage|{int(chat_id)}|{i}'),
        ])
    rows.append([InlineKeyboardButton('🧾 Volver resumen', callback_data=f'v251sum|menu|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)


async def _v255_summary_pages_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v255sum|'):
        return
    if not q.from_user or not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V255Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V255Stop
    try:
        if action == 'noop':
            await q.answer(); raise _V255Stop
        if action == 'pages':
            await q.edit_message_text(_v255_pages_order_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v255_pages_order_markup(chat_id))
            raise _V255Stop
        if action in ('uppage','downpage'):
            pos = int(parts[3]) if len(parts) > 3 else 0
            cfg = _v251_cfg(chat_id); pages = _v251_pages(chat_id)
            if 0 <= pos < len(pages):
                cur = _v251_page_index(chat_id)
                if action == 'uppage' and pos > 0:
                    pages[pos-1], pages[pos] = pages[pos], pages[pos-1]
                    if cur == pos: cur = pos-1
                    elif cur == pos-1: cur = pos
                    cfg['summary_page_index_v251'] = cur; cfg['summary_page_v250'] = cur
                    await q.answer('Panel subido')
                elif action == 'downpage' and pos < len(pages)-1:
                    pages[pos+1], pages[pos] = pages[pos], pages[pos+1]
                    if cur == pos: cur = pos+1
                    elif cur == pos+1: cur = pos
                    cfg['summary_page_index_v251'] = cur; cfg['summary_page_v250'] = cur
                    await q.answer('Panel bajado')
                else:
                    await q.answer('No se puede mover más')
                save_all_states()
            await q.edit_message_text(_v255_pages_order_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v255_pages_order_markup(chat_id))
            raise _V255Stop
    except _V255Stop:
        raise
    except Exception:
        logger.exception('V255 error ordenando paneles')
        await q.answer('Error ordenando paneles.', show_alert=True)
        raise _V255Stop


async def _v255_validation_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfgv255|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True); raise _V255Stop
    if not q.from_user or not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True); raise _V255Stop
    try:
        if action == 'nolink':
            await q.answer('No tengo enlace directo de ese grupo. Si es privado, Telegram sólo permite abrirlo desde t.me/c si eres miembro.', show_alert=True)
            raise _V255Stop
        if action == 'remtoggle':
            cur = int(cfg_value(chat_id, 'validation_reminder_minutes', VALIDATION_REMINDER_MINUTES) or 0)
            if cur > 0:
                cfg_set(chat_id, 'validation_reminder_minutes', 0)
                await q.answer('Recordatorio OFF')
            else:
                cfg_set(chat_id, 'validation_reminder_minutes', max(1, VALIDATION_REMINDER_MINUTES))
                await q.answer('Recordatorio ON')
            await q.edit_message_text(admin_private_block_text(chat_id, 'validation'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'validation'))
            raise _V255Stop
        if action == 'validcheck':
            report = await _v255_validation_check_report(context, chat_id, q.from_user.id)
            await q.edit_message_text(report, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton('🔄 Repetir comprobación', callback_data=f'cfgv255|validcheck|{chat_id}')],
                [InlineKeyboardButton('🔙 Volver validación', callback_data=f'cfg|block|{chat_id}|validation')],
            ]))
            await q.answer('Comprobado')
            raise _V255Stop
    except _V255Stop:
        raise
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            await q.answer('Ya está actualizado')
            raise _V255Stop
        raise
    except Exception:
        logger.exception('V255 router validación falló')
        await q.answer('Error en comprobación.', show_alert=True)
        raise _V255Stop


async def entradas_check_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text('Solo administradores.')
        return
    await update.message.reply_html(await _v255_validation_check_report(context, chat_id, update.effective_user.id))


_old_build_application_v255 = build_application
_old_post_init_v255 = None

async def _v255_post_init(application: Application) -> None:
    global _old_post_init_v255, VALIDATION_WATCHDOG_TASK
    if callable(_old_post_init_v255):
        try:
            await _old_post_init_v255(application)
        except Exception:
            logger.exception('V255 post_init heredado falló')

    if VALIDATION_WATCHDOG_TASK is None or VALIDATION_WATCHDOG_TASK.done():
        VALIDATION_WATCHDOG_TASK = asyncio.create_task(validation_watchdog_loop(application))
        logger.info('V255 watchdog de validación iniciado/rearmado')


def build_application() -> Application:
    global _old_post_init_v255
    app = _old_build_application_v255()
    _old_post_init_v255 = getattr(app, 'post_init', None)
    app.post_init = _v255_post_init
    app.add_handler(CallbackQueryHandler(_v255_validation_router, pattern=r'^cfgv255\|'), group=-20000000120)
    app.add_handler(CallbackQueryHandler(_v255_summary_pages_router, pattern=r'^v255sum\|'), group=-20000000121)
    app.add_handler(command_handler(['comprobarentradas','checkentradas','testentradas','validacionfullcheck'], entradas_check_command))
    logger.info('V255 cargado: watchdog entradas robusto, comprobación con checks, botón IR y orden de paneles resumen')
    return app


BOT_VERSION = "V256"

from urllib.parse import quote as _v256_urlquote


def _v256_clean_username(value: Any) -> str:
    try:
        value = str(value or '').strip()
        if value.startswith('@'):
            value = value[1:]

        value = value.split('/')[0].strip()
        return value
    except Exception:
        return ''


def _v256_store_chat_username(chat_id: int, username: str = '') -> None:
    try:
        username = _v256_clean_username(username)
        if not username:
            return
        cfg = admin_cfg(int(chat_id))
        if cfg.get('chat_username') != username:
            cfg['chat_username'] = username
            save_all_states()
    except Exception:
        logger.exception('V256 no pudo guardar username del grupo %s', chat_id)


async def _v256_refresh_chat_identity(bot, chat_id: int) -> None:
    """Guarda username/título del grupo para que el botón IR pueda abrirlo en app Telegram."""
    try:
        chat = await bot.get_chat(int(chat_id))
        title = getattr(chat, 'title', '') or getattr(chat, 'full_name', '') or ''
        username = getattr(chat, 'username', '') or ''
        if title:
            try:
                remember_chat_title(int(chat_id), title)
            except Exception:
                cfg_set(int(chat_id), 'chat_title', title)
        if username:
            _v256_store_chat_username(int(chat_id), username)
    except Exception:

        pass


def _v256_group_app_link(chat_id: int) -> Optional[str]:
    """Enlace interno de Telegram para el botón IR.

    Prioridad:
    1) Grupo público con username: tg://resolve?domain=grupo
    2) Supergrupo privado: tg://privatepost?channel=<id_sin_100>&post=1
    3) Fallback: tg://openmessage?chat_id=<id>

    Nota: los grupos privados sin username dependen del cliente Telegram. En iOS/Android
    normalmente tg://privatepost abre dentro de Telegram si el usuario pertenece al grupo.
    """
    try:
        username = _v256_clean_username(cfg_value(int(chat_id), 'chat_username', '') or '')
        if username:
            return 'tg://resolve?domain=' + _v256_urlquote(username)
    except Exception:
        pass
    try:
        s = str(int(chat_id))
        if s.startswith('-100'):
            internal = s[4:]

            return f'tg://privatepost?channel={internal}&post=1'
    except Exception:
        pass
    try:
        return 'tg://openmessage?chat_id=' + str(int(chat_id))
    except Exception:
        return None


def _v255_chat_link(chat_id: int) -> Optional[str]:
    return _v256_group_app_link(int(chat_id))


def _v250_group_url(chat_id: int) -> Optional[str]:
    return _v256_group_app_link(int(chat_id))


