async def _v256_ir_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if data.startswith('cfgv256|nolink|'):
        await q.answer('No puedo generar enlace directo para ese grupo todavía. Entra una vez al grupo desde Telegram y vuelve a abrir /ajustes.', show_alert=True)
        return

    parts = data.split('|')
    chat_id = None
    if data.startswith('cfg|open|') and len(parts) >= 3:
        try: chat_id = int(parts[2])
        except Exception: chat_id = None
    elif data.startswith('cfg241|refresh|') and len(parts) >= 3:
        try: chat_id = int(parts[2])
        except Exception: chat_id = None
    elif data.startswith('cfg|block|') and len(parts) >= 3:
        try: chat_id = int(parts[2])
        except Exception: chat_id = None
    if chat_id:
        await _v256_refresh_chat_identity(context.bot, int(chat_id))


_old_build_application_v256 = build_application

