async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or not update.message.text:
        return await _old_v257_admin_private_config_text(update, context)
    if update.effective_chat and update.effective_chat.type != 'private':
        return await _old_v257_admin_private_config_text(update, context)
    pending = get_config_pending(update.effective_user.id)
    if isinstance(pending, dict) and pending.get('kind') == 'cfg_group_ir_link':
        chat_id = int(pending.get('chat_id', 0) or 0)
        raw = (update.message.text or '').strip()
        if raw.upper() in ('CANCELAR', '/CANCELAR'):
            pop_config_pending(update.effective_user.id)
            await update.message.reply_html('❌ Cancelado.\n\n' + _v257_link_text(chat_id), reply_markup=_v257_link_markup(chat_id))
            return True
        link = _v257_clean_group_link(raw)
        cfg_set(chat_id, 'group_ir_link', link)
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Enlace del botón IR guardado.\n\n' + _v257_link_text(chat_id), reply_markup=_v257_link_markup(chat_id))
        return True
    return await _old_v257_admin_private_config_text(update, context)


class _V257Stop(Exception):
    pass


async def _v257_link_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfgv257|'):
        return
    data = q.data or ''
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V257Stop
    if not q.from_user or not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V257Stop
    try:
        if action == 'nolink':
            await q.answer('Configura primero el enlace del grupo desde Ajustes → Configurar enlace IR.', show_alert=True)
            raise _V257Stop
        if action == 'linkmenu':
            await q.edit_message_text(_v257_link_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v257_link_markup(chat_id))
            await q.answer()
            raise _V257Stop
        if action == 'setlink':
            set_config_pending(q.from_user.id, {'kind': 'cfg_group_ir_link', 'chat_id': chat_id})
            await q.edit_message_text(
                '✏️ <b>Configurar enlace del grupo</b>\n\n'
                'Pégame ahora el enlace que quieres usar en el botón <b>➡️ IR</b>.\n\n'
                '<b>Ejemplos válidos:</b>\n'
                '<code>https://t.me/nombregrupo</code>\n'
                '<code>https://t.me/+XXXXXXXX</code>\n'
                '<code>tg://resolve?domain=nombregrupo</code>\n\n'
                'Para cancelar escribe <code>CANCELAR</code>.',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfgv257|linkmenu|{chat_id}')]])
            )
            await q.answer('Envíame el enlace por privado')
            raise _V257Stop
        if action == 'clearlink':
            cfg_set(chat_id, 'group_ir_link', '')
            await q.edit_message_text(_v257_link_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v257_link_markup(chat_id))
            await q.answer('Enlace quitado')
            raise _V257Stop
    except _V257Stop:
        raise
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            await q.answer('Ya está actualizado')
            raise _V257Stop
        raise
    except Exception:
        logger.exception('V257 router enlace IR falló')
        await q.answer('Error configurando enlace IR.', show_alert=True)
        raise _V257Stop


_old_build_application_v257 = build_application

def build_application() -> Application:
    app = _old_build_application_v257()
    app.add_handler(CallbackQueryHandler(_v257_link_router, pattern=r'^cfgv257\|'), group=-20000000180)
    logger.info('V257 cargado: enlace de grupo configurable para botón IR')
    return app


