BOT_VERSION = "V259"


DJ_NEXT_LOCKS_V259: Dict[int, asyncio.Lock] = {}
DJ_ANNOUNCE_LOCKS_V259: Dict[int, asyncio.Lock] = {}
DJ_LAST_ANNOUNCE_V259: Dict[int, Dict[str, Any]] = {}


def _v259_lock(bucket: Dict[int, asyncio.Lock], chat_id: int) -> asyncio.Lock:
    lock = bucket.get(int(chat_id))
    if lock is None:
        lock = asyncio.Lock()
        bucket[int(chat_id)] = lock
    return lock


async def _v259_answer_fast(query, text: str = "Procesando…", *, show_alert: bool = False) -> None:
    try:
        await query.answer(text, show_alert=show_alert)
    except Exception:
        pass


async def _v259_dj_next_worker(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    """Pasa de canción con lock y refresca paneles sin dejar el botón colgado."""
    lock = _v259_lock(DJ_NEXT_LOCKS_V259, chat_id)
    async with lock:
        try:
            state = get_state(chat_id)
            if not state.queue:
                return


            state.live_enabled = True
            save_all_states()
            ok = await simulate_panel_next(chat_id, reason="manual_button_v259")
            if not ok:
                try:
                    await send_temp_message(context.bot, chat_id, "❌ No pude pasar a la siguiente canción.", ttl=25)
                except Exception:
                    pass
                return
            try:
                await ensure_panel(context.bot, chat_id)
                await ensure_control_panel(context.bot, chat_id)
            except Exception:
                logger.exception("V259: no se pudo refrescar DJ tras siguiente en chat %s", chat_id)
        except Exception:
            logger.exception("V259: fallo ejecutando siguiente canción en chat %s", chat_id)
            try:
                await send_temp_message(context.bot, chat_id, "❌ Error al pasar de canción. Usa /refreshbot y vuelve a probar.", ttl=35)
            except Exception:
                pass


async def _send_dj_now_announce_v24(bot, chat_id: int, track: Track) -> None:
    """Aviso fiable de canción nueva.

    - Solo se envía si el aviso está ON.
    - Se deduplica durante unos segundos para evitar duplicados por capas antiguas.
    - Si vuelve a sonar la misma canción más tarde, sí puede anunciarse otra vez.
    """
    if not _dj_announce_enabled_v24(chat_id):
        return
    lock = _v259_lock(DJ_ANNOUNCE_LOCKS_V259, chat_id)
    async with lock:
        try:
            import time as _time
            key = track_key(asdict(track)) if isinstance(track, Track) else str(getattr(track, "title", ""))
            now_ts = _time.time()
            last = DJ_LAST_ANNOUNCE_V259.get(int(chat_id), {})


            if last.get("key") == key and (now_ts - float(last.get("ts", 0))) < 8:
                return
            DJ_LAST_ANNOUNCE_V259[int(chat_id)] = {"key": key, "ts": now_ts}

            text = "🎧 <b>EN DIRECTO AHORA</b>\n\n" f"🎶 <b>{h(track.title)}</b>"
            if getattr(track, "performer", ""):
                text += f"\n👤 <i>{h(track.performer)}</i>"
            msg = await bot.send_message(
                chat_id=chat_id,
                text=text,
                parse_mode=ParseMode.HTML,
                reply_markup=_dj_now_announce_markup_v24(),
                disable_web_page_preview=True,
            )
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            logger.exception("V259: no se pudo mandar aviso de canción nueva en chat %s", chat_id)


_old_callback_router_v259 = callback_router
async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""

    if q and update.effective_chat and update.effective_user:
        chat_id = int(update.effective_chat.id)
        user_id = int(update.effective_user.id)


        if data == "panel_next":
            if not await is_controller(context, chat_id, user_id):
                await q.answer("Solo el DJ asignado puede controlar el directo.", show_alert=True)
                return
            state = get_state(chat_id)
            if not state.queue:
                await q.answer("No hay canciones en cola.", show_alert=True)
                return
            lock = _v259_lock(DJ_NEXT_LOCKS_V259, chat_id)
            if lock.locked():
                await q.answer("Ya estoy pasando a la siguiente…", show_alert=False)
                return
            await _v259_answer_fast(q, "⏭ Pasando canción…")
            asyncio.create_task(_v259_dj_next_worker(context, chat_id))
            return


        if data in ("panel_refresh", "panel_home"):
            try:
                await q.answer("Actualizando…", show_alert=False)
            except Exception:
                pass


        if data.startswith(("q|", "lib|", "lst|")):
            try:
                await q.answer("OK", show_alert=False)
            except Exception:
                pass

    return await _old_callback_router_v259(update, context)


