BOT_VERSION = "V260"

try:
    from telegram.ext import ApplicationHandlerStop as _V260Stop
except Exception:
    _V260Stop = Exception

V260_REC_MAX_SUMMARY = 10


def _v260_fmt_hhmm_from_ts(ts: Optional[int]) -> str:
    try:
        if not ts:
            return '—'
        dt = _v189_dt(int(ts)) if '_v189_dt' in globals() else datetime.fromtimestamp(int(ts))
        return f'{int(dt.hour):02d}:{int(dt.minute):02d}'
    except Exception:
        return '—'


def _v260_seconds_label(seconds: Any) -> str:
    try:
        sec = max(0, int(seconds or 0))
    except Exception:
        return 'NO'
    if sec <= 0:
        return 'NO'
    if sec % 3600 == 0:
        return f'{sec//3600}h'
    if sec % 60 == 0:
        return f'{sec//60}m'
    return f'{sec}s'


def _v260_rec_rows(chat_id: int) -> List[Dict[str, Any]]:
    try:
        rows = [r for r in recurring_list(int(chat_id)) if isinstance(r, dict)]
        rows.sort(key=lambda r: int(r.get('id', 0) or 0))
        return rows
    except Exception:
        return []


def _v260_rec_by_pos(chat_id: int, pos: int) -> Optional[Dict[str, Any]]:
    rows = _v260_rec_rows(int(chat_id))
    idx = max(0, int(pos) - 1)
    return rows[idx] if idx < len(rows) else None


def _v260_rec_schedule(row: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v189_schedule' in globals():
            return _v189_schedule(row)
    except Exception:
        pass
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    return dict(sched or {})


def _v260_extract_time_from_label(label: str) -> str:
    try:
        import re as _re
        m = _re.search(r'([0-2]?\d:[0-5]\d)', str(label or ''))
        if m:
            hh, mm = m.group(1).split(':', 1)
            return f'{int(hh):02d}:{int(mm):02d}'
    except Exception:
        pass
    return ''


def _v260_rec_launch_time(row: Dict[str, Any]) -> str:
    try:
        sched = _v260_rec_schedule(row)
        stype = str(sched.get('type') or '').lower().strip()
        if sched.get('time'):
            hh, mm = _v189_parse_hhmm(sched.get('time'), '21:00') if '_v189_parse_hhmm' in globals() else (0, 0)
            return f'{hh:02d}:{mm:02d}'
        label_time = _v260_extract_time_from_label(str(row.get('schedule_label') or sched.get('label') or ''))
        if label_time:
            return label_time
        if stype in ('interval', 'cada', 'repeat', 'start_interval'):
            nxt = _v260_rec_next_ts(row)
            return _v260_fmt_hhmm_from_ts(nxt)
    except Exception:
        logger.exception('V260 rec launch time error')
    return '—'


def _v260_rec_repeat_label(row: Dict[str, Any]) -> str:
    try:
        sched = _v260_rec_schedule(row)
        stype = str(sched.get('type') or '').lower().strip()
        if stype in ('interval', 'cada', 'repeat'):
            return _v260_seconds_label(sched.get('seconds') or row.get('interval_seconds') or row.get('repeat_seconds'))
        if stype == 'start_interval':
            return _v260_seconds_label(sched.get('repeat_seconds') or sched.get('seconds') or row.get('repeat_seconds'))
        if stype in ('weekly', 'semanal', 'week'):
            return 'SEM'
        if stype in ('daily', 'diario', 'day', '') and (sched.get('time') or row.get('schedule_label')):
            return 'DIA'
        if stype in ('date', 'fecha', 'once'):
            return 'NO'
    except Exception:
        pass
    return 'NO'


def _v260_rec_next_ts(row: Dict[str, Any], now_ts: Optional[int] = None) -> Optional[int]:
    """Calcula el próximo lanzamiento de un recurrente sin modificar estado.

    Devuelve timestamp aproximado para mostrarlo en el resumen. Usa la misma
    estructura de schedule que el scheduler real.
    """
    try:
        if not bool(row.get('enabled', True)):
            return None
        import datetime as _dt
        now_ts = int(now_ts or time.time())
        now_dt = _v189_dt(now_ts) if '_v189_dt' in globals() else _dt.datetime.fromtimestamp(now_ts)
        sched = _v260_rec_schedule(row)
        stype = str(sched.get('type') or '').lower().strip()
        last = int(row.get('last_sent_ts', 0) or 0)

        if stype in ('interval', 'cada', 'repeat'):
            sec = max(30, int(sched.get('seconds') or row.get('interval_seconds') or row.get('repeat_seconds') or 3600))
            base = last if last > 0 else now_ts
            nxt = base + sec
            return now_ts if nxt <= now_ts and last <= 0 else max(now_ts, nxt)

        if stype == 'start_interval':
            start_ts = int(sched.get('start_ts') or 0)
            repeat = max(60, int(sched.get('repeat_seconds') or sched.get('seconds') or row.get('repeat_seconds') or 3600))
            if start_ts and now_ts < start_ts:
                return start_ts
            base = last if last > 0 else (start_ts or now_ts)
            nxt = base + repeat
            return now_ts if nxt <= now_ts and last <= 0 else max(now_ts, nxt)

        if stype in ('date', 'fecha', 'once'):
            date_s = str(sched.get('date') or row.get('date') or '').strip()
            if not date_s:
                return None
            hh, mm = _v189_parse_hhmm(sched.get('time', '21:00'), '21:00') if '_v189_parse_hhmm' in globals() else (21, 0)
            target = _dt.datetime.strptime(date_s, '%Y-%m-%d').replace(hour=hh, minute=mm, second=0, microsecond=0)
            return int(target.timestamp()) if target.timestamp() >= now_ts else None

        if stype in ('weekly', 'semanal', 'week'):
            days = _v189_days(sched.get('days')) if '_v189_days' in globals() else []
            if not days:
                days = [now_dt.weekday()]
            hh, mm = _v189_parse_hhmm(sched.get('time', '21:00'), '21:00') if '_v189_parse_hhmm' in globals() else (21, 0)
            for add in range(0, 8):
                d = now_dt + _dt.timedelta(days=add)
                if d.weekday() not in days:
                    continue
                target = d.replace(hour=hh, minute=mm, second=0, microsecond=0)
                if int(target.timestamp()) >= now_ts:
                    return int(target.timestamp())
            return None


        hh, mm = _v189_parse_hhmm(sched.get('time') or _v260_extract_time_from_label(str(row.get('schedule_label') or '')) or '21:00', '21:00') if '_v189_parse_hhmm' in globals() else (21, 0)
        target = now_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if int(target.timestamp()) < now_ts:
            target = target + _dt.timedelta(days=1)
        return int(target.timestamp())
    except Exception:
        logger.exception('V260 rec next ts error')
        return None


def _v260_rec_value(chat_id: int, key: str) -> str:
    try:
        import re as _re
        m = _re.fullmatch(r'rec(\d+)_(on|time|rep|next)', str(key or ''))
        if not m:
            return '—'
        idx = int(m.group(1))
        kind = m.group(2)
        row = _v260_rec_by_pos(int(chat_id), idx)
        if not row:
            return '—'
        if kind == 'on':
            return 'ON' if bool(row.get('enabled', True)) else 'OFF'
        if kind == 'time':
            return _v260_rec_launch_time(row)
        if kind == 'rep':
            return _v260_rec_repeat_label(row)
        if kind == 'next':
            return _v260_fmt_hhmm_from_ts(_v260_rec_next_ts(row))
    except Exception:
        logger.exception('V260 rec value error %s', key)
    return '—'


