def _v261_block_rows(chat_id: int) -> List[Dict[str, Any]]:
    try:
        rows = [b for b in (_v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []) if isinstance(b, dict)]
        rows.sort(key=lambda b: int(b.get('id', 0) or 0))
        return rows
    except Exception:
        logger.exception('V261 no pudo leer bloques recurrentes')
        return []


def _v261_block_by_pos(chat_id: int, pos: int) -> Optional[Dict[str, Any]]:
    rows = _v261_block_rows(int(chat_id))
    idx = max(0, int(pos) - 1)
    return rows[idx] if idx < len(rows) else None


def _v261_block_defaults(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
        elif '_v173_rec_block_defaults' in globals():
            _v173_rec_block_defaults(b)
    except Exception:
        pass
    b.setdefault('enabled', False)
    b.setdefault('mode', 'daily' if b.get('enabled') else 'manual')
    b.setdefault('time', '21:00')
    b.setdefault('repeat_enabled', False)
    b.setdefault('repeat_every_minutes', 120)
    b.setdefault('repeat_until', b.get('time', '23:59') or '23:59')
    return b


def _v261_hhmm(value: Any, default: str = '21:00') -> str:
    try:
        if '_v237_hhmm' in globals():
            hm = _v237_hhmm(str(value or ''))
            if hm:
                return hm
        import re as _re
        m = _re.search(r'\b([0-2]?\d):([0-5]\d)\b', str(value or ''))
        if m:
            hh = int(m.group(1)); mm = int(m.group(2))
            if 0 <= hh <= 23:
                return f'{hh:02d}:{mm:02d}'
    except Exception:
        pass
    return default


def _v261_minutes_from_hhmm(hm: str) -> int:
    hm = _v261_hhmm(hm, '00:00')
    hh, mm = hm.split(':', 1)
    return int(hh) * 60 + int(mm)


def _v261_minutes_label(minutes: Any) -> str:
    try:
        m = max(1, int(minutes or 0))
    except Exception:
        return 'NO'
    if m <= 0:
        return 'NO'
    if m % 60 == 0:
        return f'{m//60}h'
    return f'{m}m'


def _v261_block_start_time(b: Dict[str, Any]) -> str:
    try:
        _v261_block_defaults(b)
        return _v261_hhmm(b.get('time') or b.get('start_time') or '21:00', '21:00')
    except Exception:
        return '—'


def _v261_block_repeat_label(b: Dict[str, Any]) -> str:
    try:
        _v261_block_defaults(b)
        if bool(b.get('repeat_enabled')):
            return _v261_minutes_label(b.get('repeat_every_minutes') or b.get('repeat_minutes') or 120)
        return 'NO'
    except Exception:
        return 'NO'


def _v261_block_next_ts(b: Dict[str, Any], now_ts: Optional[int] = None) -> Optional[int]:
    """Próximo lanzamiento del bloque, calculado por la programación del bloque.

    Importante: no mira si los recurrentes internos están ON/OFF. El bloque es
    el disparador superior y manda sobre sus elementos internos.
    """
    try:
        import datetime as _dt
        _v261_block_defaults(b)
        if not bool(b.get('enabled')):
            return None
        mode = str(b.get('mode') or 'daily').lower().strip()
        if mode not in ('daily', 'repeat', 'auto'):

            if mode == 'manual':
                return None
        now_ts = int(now_ts or time.time())
        now_dt = _v189_dt(now_ts) if '_v189_dt' in globals() else _dt.datetime.fromtimestamp(now_ts)
        now_min = now_dt.hour * 60 + now_dt.minute
        start_s = _v261_block_start_time(b)
        start_min = _v261_minutes_from_hhmm(start_s)

        if bool(b.get('repeat_enabled')):
            every = max(1, int(b.get('repeat_every_minutes') or 120))
            until_s = _v261_hhmm(b.get('repeat_until') or '23:59', '23:59')
            until_min = _v261_minutes_from_hhmm(until_s)

            crosses = until_min < start_min
            candidates = []
            for day_add in range(0, 3):
                base_date = (now_dt + _dt.timedelta(days=day_add)).date()
                window_start = _dt.datetime.combine(base_date, _dt.time(start_min // 60, start_min % 60))
                until_adj = until_min + (24 * 60 if crosses else 0)
                slot = start_min
                while slot <= until_adj:
                    slot_day_add = slot // (24 * 60)
                    slot_min = slot % (24 * 60)
                    cand = window_start + _dt.timedelta(days=slot_day_add, minutes=(slot_min - start_min))
                    if int(cand.timestamp()) >= now_ts:
                        candidates.append(cand)
                        break
                    slot += every
            if candidates:
                return int(min(candidates).timestamp())
            return None

        target = now_dt.replace(hour=start_min // 60, minute=start_min % 60, second=0, microsecond=0)
        if int(target.timestamp()) < now_ts:
            target = target + _dt.timedelta(days=1)
        return int(target.timestamp())
    except Exception:
        logger.exception('V261 block next ts error')
        return None


def _v261_fmt_hhmm_from_ts(ts: Optional[int]) -> str:
    try:
        if not ts:
            return '—'
        dt = _v189_dt(int(ts)) if '_v189_dt' in globals() else __import__('datetime').datetime.fromtimestamp(int(ts))
        return f'{int(dt.hour):02d}:{int(dt.minute):02d}'
    except Exception:
        return '—'


