async def _v181_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[int, int, List[str]]:
    block = _v181_find_rec_block(chat_id, bid) if '_v181_find_rec_block' in globals() else None
    if not block:
        return 0, 0, ['No encuentro ese bloque recurrente.']
    rids = _v181_extract_rids_from_block(block) if '_v181_extract_rids_from_block' in globals() else [int(x) for x in block.get('items', []) if str(x).isdigit()]
    if not rids:
        return 0, 0, ['El bloque está vacío. Añade recurrentes dentro del bloque.']
    ok = 0
    errors: List[str] = []
    for pos, rid in enumerate(rids, 1):
        row = recurring_find(chat_id, int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'{pos}. #{rid} no existe')
            continue
        try:
            tmp = dict(row)

            tmp['enabled'] = True
            if '_v181_send_recurring_manual_clean' in globals():
                await _v181_send_recurring_manual_clean(context, chat_id, tmp)
            elif '_v170_send_recurring_manual' in globals():
                await _v170_send_recurring_manual(context, chat_id, tmp)
            else:
                await send_recurring_message(context, chat_id, tmp)
            ok += 1
            await asyncio.sleep(1.0)
        except Exception:
            logger.exception('V261 bloque %s falló en posición %s recurrente #%s', bid, pos, rid)
            errors.append(f'{pos}. #{rid} error')
    return ok, len(rids), errors


