def _v262_clean_summary_name(value: Any, fallback: str = '—', max_len: int = 22) -> str:
    try:
        txt = str(value or '').strip()
        if not txt:
            return fallback
        txt = ' '.join(txt.split())
        if len(txt) > max_len:
            return txt[:max_len - 1].rstrip() + '…'
        return txt
    except Exception:
        return fallback


