    try:
        name = row.get('name') or row.get('title') or row.get('label')
        if name:
            return _v262_clean_summary_name(name, f'Rec {idx}' if idx else 'Recurrente')
        txt = str(row.get('text') or row.get('caption') or '').strip()
        if txt:
            return _v262_clean_summary_name(txt, f'Rec {idx}' if idx else 'Recurrente')
    except Exception:
        pass
    return f'Rec {idx}' if idx else 'Recurrente'


