def _v262_insert_before_group(fields: List[str], name_key: str, first_group_key: str) -> None:
    try:
        if name_key in fields:
            return
        if first_group_key in fields:
            fields.insert(fields.index(first_group_key), name_key)
        else:
            fields.append(name_key)
    except Exception:
        pass


_old_v262_v251_cfg = _v251_cfg if '_v251_cfg' in globals() else None

def _v251_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _old_v262_v251_cfg(int(chat_id)) if callable(_old_v262_v251_cfg) else admin_cfg(int(chat_id))
    try:
        pages = cfg.get('summary_pages_v251')
        if isinstance(pages, list):
            before_len = len(pages)
            pages[:] = [p for p in pages if not (isinstance(p, dict) and (str(p.get('id')) == 'rec_detail_v260' or 'rec. detalle' in str(p.get('title','')).lower()))]
            changed = len(pages) != before_len
            if not pages:
                pages.append({'id':'general','title':'📌 General','cols':2,'style':'none','abbr_len':0,'fields':['validation_status','dj','pending','version']})
                changed = True
            idx = int(cfg.get('summary_page_index_v251', 0) or 0)
            if idx >= len(pages):
                cfg['summary_page_index_v251'] = max(0, len(pages)-1)
                cfg['summary_page_v250'] = cfg['summary_page_index_v251']
                changed = True
            for p in pages:
                if not isinstance(p, dict):
                    continue
                fields = p.get('fields')
                if not isinstance(fields, list):
                    continue
                if str(p.get('id')) == 'block_detail_v261':
                    for i in range(1, 4):
                        before = list(fields)
                        _v262_insert_before_group(fields, f'blk{i}_name', f'blk{i}_on')
                        changed = changed or (before != fields)
            if changed:
                save_all_states()
    except Exception:
        logger.exception('V341 no pudo limpiar Rec.Detalle / nombres resumen')
    return cfg


