def _v262_repeat_label(minutes: Any) -> str:
    try:
        m = int(minutes or 0)
    except Exception:
        m = 0
    if m <= 0:
        return 'OFF'
    if m % 60 == 0:
        return f'{m // 60}h'
    return f'{m}m'


def _v262_current_repeat_minutes(b: Dict[str, Any]) -> int:
    try:
        if not bool(b.get('repeat_enabled')):
            return 0
        return int(b.get('repeat_every_minutes') or 0)
    except Exception:
        return 0


def _v262_next_repeat_minutes(b: Dict[str, Any]) -> int:
    cur = _v262_current_repeat_minutes(b)
    try:
        idx = V262_BLOCK_REPEAT_CHOICES.index(cur)
    except ValueError:

        idx = -1
    return V262_BLOCK_REPEAT_CHOICES[(idx + 1) % len(V262_BLOCK_REPEAT_CHOICES)]


_old_v262_rec_block_markup = _v171_rec_block_markup if '_v171_rec_block_markup' in globals() else None

def _v171_rec_block_markup(chat_id: int, bid: int) -> InlineKeyboardMarkup:
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    if not b or not callable(_old_v262_rec_block_markup):
        return _old_v262_rec_block_markup(chat_id, bid) if callable(_old_v262_rec_block_markup) else InlineKeyboardMarkup([])
    if '_v237_rblk_defaults' in globals():
        _v237_rblk_defaults(b)
    rows = []
    inserted_cycle = False
    label = _v262_repeat_label(_v262_current_repeat_minutes(b))
    cycle_btn = InlineKeyboardButton(f'⏱ Repetición bloque: {label}', callback_data=f'cfg|rblk_repeat_cycle|{int(chat_id)}|{int(bid)}')
    for row in list(_old_v262_rec_block_markup(chat_id, bid).inline_keyboard):
        callbacks = [getattr(btn, 'callback_data', '') or '' for btn in row]

        if any(cb.startswith('cfg|rblk_repeat_toggle|') for cb in callbacks):
            continue

        if any(cb.startswith('cfg|rblk_repeat_every|') for cb in callbacks):
            new_row = [cycle_btn]
            for btn in row:
                cb = getattr(btn, 'callback_data', '') or ''
                if not cb.startswith('cfg|rblk_repeat_every|'):
                    new_row.append(btn)
            rows.append(new_row)
            inserted_cycle = True
            continue
        rows.append(list(row))
    if not inserted_cycle:
        insert_at = 3 if len(rows) >= 3 else len(rows)
        rows.insert(insert_at, [cycle_btn])
    return InlineKeyboardMarkup(rows)


async def _v262_rblk_repeat_cycle_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|rblk_repeat_cycle|'):
        return
    try:
        parts = (q.data or '').split('|')
        chat_id = int(parts[2]); bid = int(parts[3])
        b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
        if not b:
            await q.answer('Bloque no encontrado', show_alert=True)
            raise _V262Stop
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
        nxt = _v262_next_repeat_minutes(b)
        if nxt <= 0:
            b['repeat_enabled'] = False
            b['repeat_every_minutes'] = 0
        else:
            b['repeat_enabled'] = True
            b['repeat_every_minutes'] = int(nxt)
            b['enabled'] = True
            b['mode'] = 'daily'
        save_all_states()
        await q.answer(f'Repetición: {_v262_repeat_label(nxt)}')
        await q.edit_message_text(_v171_rec_block_text(chat_id, bid), parse_mode=ParseMode.HTML, reply_markup=_v171_rec_block_markup(chat_id, bid))
        raise _V262Stop
    except _V262Stop:
        raise
    except Exception:
        logger.exception('V262 error cambiando repetición de bloque')
        try:
            await q.answer('Error cambiando repetición. Mira logs.', show_alert=True)
        except Exception:
            pass
        raise _V262Stop


_old_build_application_v262 = build_application

def build_application() -> Application:
    app = _old_build_application_v262()
    app.add_handler(CallbackQueryHandler(_v262_rblk_repeat_cycle_router, pattern=r'^cfg\|rblk_repeat_cycle\|'), group=-38000000000)
    logger.info('V262 cargado: nombres en resumen rápido y repetición cíclica de bloques recurrentes')
    return app


BOT_VERSION = "V263"

try:
    from telegram.ext import ApplicationHandlerStop as _V263Stop
except Exception:
    _V263Stop = Exception


def _v263_now_dt(now_ts: Optional[int] = None):
    try:
        return _v189_dt(int(now_ts or time.time())) if '_v189_dt' in globals() else _local_dt_v15(int(now_ts or time.time()))
    except Exception:
        import datetime as _dt
        return _dt.datetime.fromtimestamp(int(now_ts or time.time()))


def _v263_hhmm(value: Any, default: str = '21:00') -> str:
    try:
        if '_v237_hhmm' in globals():
            hm = _v237_hhmm(str(value or ''))
            if hm:
                return hm
        import re as _re
        m = _re.search(r'\b([0-2]?\d):([0-5]\d)\b', str(value or ''))
        if m:
            hh = int(m.group(1)); mm = int(m.group(2))
            if 0 <= hh <= 23:
                return f'{hh:02d}:{mm:02d}'
    except Exception:
        pass
    return default


def _v263_min(hm: str) -> int:
    hm = _v263_hhmm(hm, '00:00')
    hh, mm = hm.split(':', 1)
    return int(hh) * 60 + int(mm)


def _v263_block_defaults(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
        elif '_v261_block_defaults' in globals():
            _v261_block_defaults(b)
        elif '_v173_rec_block_defaults' in globals():
            _v173_rec_block_defaults(b)
    except Exception:
        pass
    b.setdefault('enabled', False)
    b.setdefault('mode', 'daily' if b.get('enabled') else 'manual')
    b['time'] = _v263_hhmm(b.get('time') or b.get('start_time') or '21:00', '21:00')
    try:
        b['repeat_every_minutes'] = max(0, int(b.get('repeat_every_minutes') or b.get('repeat_minutes') or 0))
    except Exception:
        b['repeat_every_minutes'] = 0
    if not b.get('repeat_until'):
        b['repeat_until'] = '23:59'
    else:
        b['repeat_until'] = _v263_hhmm(b.get('repeat_until'), '23:59')
    b.setdefault('last_sent_slot', '')
    b.setdefault('last_sent_day', '')
    return b


def _v263_block_window_datetimes(b: Dict[str, Any], now_ts: Optional[int] = None):
    import datetime as _dt
    b = _v263_block_defaults(b)
    now_dt = _v263_now_dt(now_ts)
    start_min = _v263_min(str(b.get('time', '21:00')))
    until_min = _v263_min(str(b.get('repeat_until') or '23:59'))
    duration = until_min - start_min
    if duration < 0:
        duration += 24 * 60
    windows = []
    for delta_days in (-1, 0, 1):
        base_date = (now_dt + _dt.timedelta(days=delta_days)).date()
        start_dt = _dt.datetime.combine(base_date, _dt.time(start_min // 60, start_min % 60))
        try:
            if getattr(now_dt, 'tzinfo', None) is not None:
                start_dt = start_dt.replace(tzinfo=now_dt.tzinfo)
        except Exception:
            pass
        until_dt = start_dt + _dt.timedelta(minutes=duration)
        windows.append((start_dt, until_dt))
    return now_dt, windows


def _v263_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    try:
        import datetime as _dt
        b = _v263_block_defaults(b)
        if not bool(b.get('enabled')):
            return False, ''
        now_dt, windows = _v263_block_window_datetimes(b, now_ts)
        repeat_enabled = bool(b.get('repeat_enabled')) and int(b.get('repeat_every_minutes') or 0) > 0
        every = max(1, int(b.get('repeat_every_minutes') or 0)) if repeat_enabled else 0
        tolerance_sec = 180
        for start_dt, until_dt in windows:
            if not (start_dt <= now_dt <= until_dt):
                continue
            if repeat_enabled:
                elapsed_min = int((now_dt - start_dt).total_seconds() // 60)
                slot_idx = max(0, elapsed_min // every)
                slot_dt = start_dt + _dt.timedelta(minutes=slot_idx * every)
                if slot_dt > until_dt:
                    continue
                if 0 <= (now_dt - slot_dt).total_seconds() <= tolerance_sec:
                    slot = f'{slot_dt.strftime("%Y-%m-%d")}|{slot_dt.hour:02d}{slot_dt.minute:02d}'


                    start_key = f'{start_dt.strftime("%Y-%m-%d")}|{start_dt.hour:02d}{start_dt.minute:02d}'
                    if slot == start_key and str(b.get('last_sent_day', '')) == slot_dt.strftime('%Y-%m-%d') and not str(b.get('last_sent_slot', '')):
                        return False, slot
                    return str(b.get('last_sent_slot', '')) != slot, slot
            else:
                if 0 <= (now_dt - start_dt).total_seconds() <= tolerance_sec:
                    slot = f'{start_dt.strftime("%Y-%m-%d")}|{start_dt.hour:02d}{start_dt.minute:02d}'
                    if str(b.get('last_sent_day', '')) == start_dt.strftime('%Y-%m-%d') and not str(b.get('last_sent_slot', '')):
                        return False, slot
                    return str(b.get('last_sent_slot', '')) != slot, slot
        return False, ''
    except Exception:
        logger.exception('V263 block due error')
        return False, ''


async def _v263_send_rec_block_scheduled(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    try:
        bid = int(b.get('id', 0) or 0)
    except Exception:
        bid = 0
    if bid and '_v181_send_rec_block' in globals():
        return await _v181_send_rec_block(context, int(chat_id), bid)
    ok = 0; total = 0; errors: List[str] = []
    try:
        ids = [int(x) for x in (b.get('items') or b.get('rids') or b.get('recurrentes') or []) if str(x).isdigit()]
    except Exception:
        ids = []
    for rid in ids:
        total += 1
        row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        try:
            tmp = dict(row)
            tmp['enabled'] = True
            if '_v181_send_recurring_manual_clean' in globals():
                await _v181_send_recurring_manual_clean(context, int(chat_id), tmp)
            elif '_v170_send_recurring_manual' in globals():
                await _v170_send_recurring_manual(context, int(chat_id), tmp)
            else:
                await send_recurring_message(context, int(chat_id), tmp)
            ok += 1
            await asyncio.sleep(1.0)
        except Exception:
            logger.exception('V263 bloque programado falló recurrente #%s', rid)
            errors.append(f'#{rid} error')
    return ok, total, errors


async def _v263_rblk_scheduler(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        now_ts = int(time.time())
        chat_ids = set()
        try:
            chat_ids.update(int(x) for x in (STATE_CACHE.keys() if 'STATE_CACHE' in globals() else []))
        except Exception:
            pass
        try:
            chat_ids.update(int(x) for x in ((STATE.get('admin_cfg', {}) or {}).keys() if 'STATE' in globals() else []))
        except Exception:
            pass
        for chat_id in sorted(chat_ids):
            blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
            for b in blocks:
                try:
                    _v263_block_defaults(b)
                    due, slot = _v263_block_due(b, now_ts)
                    if not due:
                        continue
                    ok, total, errors = await _v263_send_rec_block_scheduled(context, int(chat_id), b)
                    b['last_sent_slot'] = slot
                    b['last_sent_day'] = slot.split('|', 1)[0] if '|' in slot else _v263_now_dt(now_ts).strftime('%Y-%m-%d')
                    save_all_states()
                    logger.info('V263 bloque recurrente enviado chat=%s bid=%s ok=%s/%s slot=%s errors=%s', chat_id, b.get('id'), ok, total, slot, errors[:3])
                except Exception:
                    logger.exception('V263 error bloque recurrente chat=%s block=%s', chat_id, b)
    except Exception:
        logger.exception('V263 scheduler bloques recurrentes falló')


def _v237_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    return _v263_block_due(b, now_ts)


def _v261_block_next_ts(b: Dict[str, Any], now_ts: Optional[int] = None) -> Optional[int]:
    try:
        import datetime as _dt
        b = _v263_block_defaults(b)
        if not bool(b.get('enabled')):
            return None
        now_ts = int(now_ts or time.time())
        now_dt = _v263_now_dt(now_ts)
        start_min = _v263_min(str(b.get('time', '21:00')))
        until_min = _v263_min(str(b.get('repeat_until') or '23:59'))
        repeat_enabled = bool(b.get('repeat_enabled')) and int(b.get('repeat_every_minutes') or 0) > 0
        every = max(1, int(b.get('repeat_every_minutes') or 0)) if repeat_enabled else 0
        candidates = []
        for day_add in range(0, 3):
            base = (now_dt + _dt.timedelta(days=day_add)).date()
            start_dt = _dt.datetime.combine(base, _dt.time(start_min // 60, start_min % 60))
            try:
                if getattr(now_dt, 'tzinfo', None) is not None:
                    start_dt = start_dt.replace(tzinfo=now_dt.tzinfo)
            except Exception:
                pass
            if repeat_enabled:
                duration = until_min - start_min
                if duration < 0:
                    duration += 24 * 60
                until_dt = start_dt + _dt.timedelta(minutes=duration)
                slot_dt = start_dt
                while slot_dt <= until_dt:
                    if slot_dt.timestamp() >= now_ts:
                        candidates.append(slot_dt); break
                    slot_dt += _dt.timedelta(minutes=every)
            else:
                cand = start_dt if start_dt.timestamp() >= now_ts else start_dt + _dt.timedelta(days=1)
                candidates.append(cand)
        if not candidates:
            return None
        return int(min(candidates).timestamp())
    except Exception:
        logger.exception('V263 block next ts error')
        return None


_old_v263_rec_block_text = _v171_rec_block_text if '_v171_rec_block_text' in globals() else None

def _v171_rec_block_text(chat_id: int, bid: int) -> str:
    base = _old_v263_rec_block_text(int(chat_id), int(bid)) if callable(_old_v263_rec_block_text) else '<b>📦 Bloque recurrente</b>'
    try:
        b = _v171_rec_block_find(int(chat_id), int(bid)) if '_v171_rec_block_find' in globals() else None
        if not b:
            return base
        _v263_block_defaults(b)
        rep = _v262_repeat_label(b.get('repeat_every_minutes')) if bool(b.get('repeat_enabled')) and '_v262_repeat_label' in globals() else ('OFF' if not bool(b.get('repeat_enabled')) else f"{b.get('repeat_every_minutes')}m")
        nxt = _v261_fmt_hhmm_from_ts(_v261_block_next_ts(b)) if '_v261_fmt_hhmm_from_ts' in globals() else '—'
        extra = (
            '\n\n<b>⏱ Programación real del bloque</b>\n'
            f"Inicio: <b>{h(str(b.get('time','21:00')))}</b> · "
            f"Cada: <b>{h(str(rep))}</b> · "
            f"Hasta: <b>{h(str(b.get('repeat_until','23:59')))}</b> · "
            f"Próximo: <b>{h(str(nxt))}</b>\n"
            '<i>El bloque programado envía sus recurrentes internos aunque estén OFF individualmente.</i>'
        )
        if 'Programación real del bloque' not in base:
            return base + extra
        return base
    except Exception:
        return base


async def _v263_rblk_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not pending:
        return
    kind = str(pending.get('kind') or '')
    if kind not in ('rblk_repeat_until_v237', 'rblk_repeat_every_v237'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    bid = int(pending.get('bid') or 0)
    text = (update.message.text or update.message.caption or '').strip()
    b = _v171_rec_block_find(chat_id, bid) if '_v171_rec_block_find' in globals() else None
    if not b:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('❌ No encuentro ese bloque recurrente.')
        raise _V263Stop
    _v263_block_defaults(b)
    if kind == 'rblk_repeat_until_v237':
        hm = _v263_hhmm(text, '')
        if not hm:
            await update.message.reply_html('❌ Hora final no válida. Usa formato <code>HH:MM</code>, por ejemplo <code>03:00</code> o <code>23:30</code>.')
            raise _V263Stop
        b['repeat_until'] = hm
        b['repeat_enabled'] = int(b.get('repeat_every_minutes') or 0) > 0
        b['enabled'] = True
        b['mode'] = 'daily'
        msg = f'✅ Hora final guardada: <b>{hm}</b>'
    else:
        import re as _re
        m = _re.search(r'\d+', text or '')
        if not m:
            await update.message.reply_html('❌ Envía minutos. Ejemplo: <code>60</code>, <code>120</code>, <code>240</code>.')
            raise _V263Stop
        minutes = max(1, int(m.group(0)))
        b['repeat_every_minutes'] = minutes
        b['repeat_enabled'] = True
        b['enabled'] = True
        b['mode'] = 'daily'
        msg = f'✅ Repetición guardada: <b>{minutes} min</b>'
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html(msg + '\n\n' + _v171_rec_block_text(chat_id, bid), reply_markup=_v171_rec_block_markup(chat_id, bid))
    raise _V263Stop


_old_v263_pages_order_markup = _v255_pages_order_markup if '_v255_pages_order_markup' in globals() else None

def _v255_pages_order_markup(chat_id: int) -> InlineKeyboardMarkup:
    try:
        pages = _v251_pages(int(chat_id))
        rows: List[List[InlineKeyboardButton]] = []
        for i, p in enumerate(pages):
            title = str(p.get('title') or f'Panel {i+1}')[:16]
            rows.append([
                InlineKeyboardButton(f'{i+1}. {title}', callback_data=f'v255sum|noop|{int(chat_id)}'),
                InlineKeyboardButton('⬆️', callback_data=f'v255sum|uppage|{int(chat_id)}|{i}'),
                InlineKeyboardButton('⬇️', callback_data=f'v255sum|downpage|{int(chat_id)}|{i}'),
                InlineKeyboardButton('🗑', callback_data=f'v263sum|delpagepos|{int(chat_id)}|{i}'),
            ])
        rows.append([InlineKeyboardButton('🧾 Volver resumen', callback_data=f'v251sum|menu|{int(chat_id)}')])
        return InlineKeyboardMarkup(rows)
    except Exception:
        return _old_v263_pages_order_markup(int(chat_id)) if callable(_old_v263_pages_order_markup) else InlineKeyboardMarkup([])


_old_v263_summary_menu_markup = _v251_summary_menu_markup if '_v251_summary_menu_markup' in globals() else None

def _v251_summary_menu_markup(chat_id: int) -> InlineKeyboardMarkup:
    base = _old_v263_summary_menu_markup(int(chat_id)) if callable(_old_v263_summary_menu_markup) else InlineKeyboardMarkup([])
    try:
        rows = [list(r) for r in (base.inline_keyboard or [])]
        for row in rows:
            for i, btn in enumerate(row):
                cb = str(getattr(btn, 'callback_data', '') or '')
                if cb == f'v251sum|delpage|{int(chat_id)}':
                    row[i] = InlineKeyboardButton('🗑 Borrar panel actual', callback_data=cb)
        return InlineKeyboardMarkup(rows)
    except Exception:
        return base


async def _v263_summary_pages_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('v263sum|'):
        return
    if not q.from_user or not is_global_admin_user(q.from_user.id):
        await q.answer('Solo dueño/ADMIN_IDS.', show_alert=True)
        raise _V263Stop
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2]); pos = int(parts[3]) if len(parts) > 3 else -1
    except Exception:
        await q.answer('Grupo inválido', show_alert=True)
        raise _V263Stop
    try:
        if action == 'delpagepos':
            cfg = _v251_cfg(chat_id); pages = _v251_pages(chat_id)
            if len(pages) <= 1:
                await q.answer('No puedes borrar el único panel.', show_alert=True)
                raise _V263Stop
            if not (0 <= pos < len(pages)):
                await q.answer('Panel no encontrado.', show_alert=True)
                raise _V263Stop
            title = str(pages[pos].get('title') or f'Panel {pos+1}')
            pages.pop(pos)
            cur = _v251_page_index(chat_id)
            if cur >= len(pages):
                cur = len(pages) - 1
            elif pos <= cur and cur > 0:
                cur -= 1
            cfg['summary_page_index_v251'] = max(0, cur)
            cfg['summary_page_v250'] = cfg['summary_page_index_v251']
            save_all_states()
            await q.answer(f'Panel borrado: {title}')
            await q.edit_message_text(_v255_pages_order_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v255_pages_order_markup(chat_id))
            raise _V263Stop
    except _V263Stop:
        raise
    except Exception:
        logger.exception('V263 error borrando panel rápido')
        await q.answer('Error borrando panel.', show_alert=True)
        raise _V263Stop


_old_build_application_v263 = build_application

def build_application() -> Application:
    app = _old_build_application_v263()
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v263_rblk_text_router), group=-39000000000)
    app.add_handler(CallbackQueryHandler(_v263_summary_pages_router, pattern=r'^v263sum\|'), group=-39000000001)
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v263_rblk_scheduler, interval=30, first=5, name='v263_rblk_scheduler')
    except Exception:
        logger.exception('No se pudo iniciar scheduler V263 de bloques recurrentes')
    logger.info('V263 cargado: scheduler blindado bloques recurrentes, Hasta funcional y borrado de paneles rápidos')
    return app


BOT_VERSION = "V264"

_V264_RBLK_LOOP_TASK_KEY = 'v264_rblk_recurrent_loop_started'
_V264_RBLK_LOOP_INTERVAL = int(os.getenv('RBLK_LOOP_INTERVAL_SECONDS', '20') or 20)
_V264_RBLK_MAX_CATCHUP_MINUTES = int(os.getenv('RBLK_MAX_CATCHUP_MINUTES', '180') or 180)


def _v264_hhmm(value: Any, default: str = '21:00') -> str:
    """Acepta HH:MM y también claves antiguas. Devuelve siempre HH:MM válido."""
    try:
        if '_v237_hhmm' in globals():
            hm = _v237_hhmm(str(value or ''))
            if hm:
                return hm
        import re as _re
        m = _re.search(r'\b([0-2]?\d)[\.:]([0-5]\d)\b', str(value or ''))
        if m:
            hh = int(m.group(1)); mm = int(m.group(2))
            if 0 <= hh <= 23:
                return f'{hh:02d}:{mm:02d}'
    except Exception:
        pass
    return default


def _v264_minutes(hm: Any, default: str = '00:00') -> int:
    hm = _v264_hhmm(hm, default)
    hh, mm = hm.split(':', 1)
    return int(hh) * 60 + int(mm)


def _v264_dt(now_ts: Optional[int] = None):
    try:
        return _v189_dt(int(now_ts or time.time())) if '_v189_dt' in globals() else _local_dt_v15(int(now_ts or time.time()))
    except Exception:
        import datetime as _dt
        return _dt.datetime.fromtimestamp(int(now_ts or time.time()))


def _v264_chat_ids() -> List[int]:
    ids = set()
    try:
        ids.update(int(x) for x in STATE_CACHE.keys())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in known_admin_chats_for_private())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in (STATE.get('admin_cfg', {}) or {}).keys())
    except Exception:
        pass

    return sorted(int(x) for x in ids if int(x) < 0)


def _v264_block_defaults(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
        elif '_v173_rec_block_defaults' in globals():
            _v173_rec_block_defaults(b)
    except Exception:
        pass

    b['time'] = _v264_hhmm(b.get('time') or b.get('start_time') or b.get('start') or b.get('inicio') or '21:00', '21:00')

    try:
        every = int(b.get('repeat_every_minutes') or b.get('repeat_minutes') or b.get('every_minutes') or 0)
    except Exception:
        every = 0
    b['repeat_every_minutes'] = max(0, every)
    b['repeat_enabled'] = bool(b.get('repeat_enabled')) and b['repeat_every_minutes'] > 0
    b['repeat_until'] = _v264_hhmm(b.get('repeat_until') or b.get('until') or b.get('end_time') or b.get('hasta') or '23:59', '23:59')
    b.setdefault('mode', 'daily' if bool(b.get('enabled')) else 'manual')
    b.setdefault('last_sent_slot', '')
    b.setdefault('last_sent_day', '')
    return b


def _v264_block_enabled(b: Dict[str, Any]) -> bool:
    """Un bloque está programado si Auto está ON/enabled. El recurrente interno puede estar OFF."""
    try:
        if bool(b.get('enabled')):
            return True
        if bool(b.get('auto_enabled')):
            return True
        if str(b.get('mode') or '').lower() in ('daily', 'auto', 'repeat') and bool(b.get('scheduled', False)):
            return True
    except Exception:
        pass
    return False


def _v264_block_due_slot(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str, str]:
    """Devuelve si el bloque debe enviarse ahora y el slot que toca.

    La clave: no exige estar exactamente en el minuto. Si el bot se retrasa,
    envía el último slot vencido dentro de la ventana Inicio/Hasta.
    """
    try:
        import datetime as _dt
        b = _v264_block_defaults(b)
        if not _v264_block_enabled(b):
            return False, '', 'OFF'
        now_ts = int(now_ts or time.time())
        now_dt = _v264_dt(now_ts)
        start_min = _v264_minutes(b.get('time'), '21:00')
        until_min = _v264_minutes(b.get('repeat_until'), '23:59')
        every = int(b.get('repeat_every_minutes') or 0) if bool(b.get('repeat_enabled')) else 0
        duration = until_min - start_min
        if duration < 0:
            duration += 24 * 60

        best_slot_dt = None
        best_reason = ''

        for day_delta in (-1, 0, 1):
            base_date = (now_dt + _dt.timedelta(days=day_delta)).date()
            start_dt = _dt.datetime.combine(base_date, _dt.time(start_min // 60, start_min % 60))
            try:
                if getattr(now_dt, 'tzinfo', None) is not None:
                    start_dt = start_dt.replace(tzinfo=now_dt.tzinfo)
            except Exception:
                pass
            until_dt = start_dt + _dt.timedelta(minutes=duration if every else 0)
            if every:
                if now_dt < start_dt or now_dt > until_dt:
                    continue
                elapsed = int((now_dt - start_dt).total_seconds() // 60)
                slot_idx = max(0, elapsed // max(1, every))
                slot_dt = start_dt + _dt.timedelta(minutes=slot_idx * every)
                if slot_dt > until_dt:
                    continue

                age_min = int((now_dt - slot_dt).total_seconds() // 60)
                if age_min > max(1, _V264_RBLK_MAX_CATCHUP_MINUTES):
                    continue
                if best_slot_dt is None or slot_dt > best_slot_dt:
                    best_slot_dt = slot_dt
                    best_reason = f'cada {every}m hasta {b.get("repeat_until")}'
            else:

                slot_dt = start_dt
                age_min = int((now_dt - slot_dt).total_seconds() // 60)
                if age_min < 0 or age_min > max(1, _V264_RBLK_MAX_CATCHUP_MINUTES):
                    continue
                if best_slot_dt is None or slot_dt > best_slot_dt:
                    best_slot_dt = slot_dt
                    best_reason = f'diario {b.get("time")}'

        if best_slot_dt is None:
            return False, '', 'no toca'
        slot = f'{best_slot_dt.strftime("%Y-%m-%d")}|{best_slot_dt.hour:02d}{best_slot_dt.minute:02d}'
        if str(b.get('last_sent_slot') or '') == slot:
            return False, slot, 'ya enviado slot'
        if str(b.get('v264_sending_slot') or '') == slot:
            return False, slot, 'ya en envío'
        return True, slot, best_reason
    except Exception:
        logger.exception('V264 cálculo bloque debido falló')
        return False, '', 'error'


def _v263_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    due, slot, _reason = _v264_block_due_slot(b, now_ts)
    return due, slot


def _v237_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    due, slot, _reason = _v264_block_due_slot(b, now_ts)
    return due, slot


def _v264_extract_block_rids(b: Dict[str, Any]) -> List[int]:
    try:
        if '_v181_extract_rids_from_block' in globals():
            return _v181_extract_rids_from_block(b)
    except Exception:
        pass
    raw = []
    for key in ('items', 'rids', 'recurring_ids', 'recurrentes', 'recurrents'):
        v = b.get(key)
        if isinstance(v, list):
            raw.extend(v)
        elif v not in (None, ''):
            raw.append(v)
    out: List[int] = []
    for item in raw:
        try:
            if isinstance(item, dict):
                item = item.get('id') or item.get('rid') or item.get('recurring_id')
            if isinstance(item, str):
                item = item.replace('recsend_', '').replace('rec:', '').replace('rec_', '').strip()
            rid = int(item)
            if rid > 0 and rid not in out:
                out.append(rid)
        except Exception:
            pass
    return out


async def _v264_send_one_recurring_from_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, row: Dict[str, Any]) -> Optional[int]:
    """Envío de recurrente dentro de bloque. Fuerza ON sólo en la copia."""
    import copy as _copy
    tmp = _copy.deepcopy(row)
    tmp['enabled'] = True

    for k in ('last_sent_ts', 'last_day', 'last_week_key', 'last_date_key', 'next_ts', 'next_run_ts'):
        tmp.pop(k, None)
    if '_v170_send_recurring_manual' in globals():
        return await _v170_send_recurring_manual(context, chat_id, tmp)
    return await send_recurring_message(context, chat_id, tmp)


async def _v264_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    rids = _v264_extract_block_rids(b)
    if not rids:
        return 0, 0, ['bloque vacío']
    ok = 0
    errors: List[str] = []
    for rid in rids:
        row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        try:
            mid = await _v264_send_one_recurring_from_block(context, int(chat_id), row)
            if mid:
                ok += 1
            else:
                errors.append(f'#{rid} no enviado')
            await asyncio.sleep(0.8)
        except Exception:
            logger.exception('V264 bloque falló en recurrente #%s', rid)
            errors.append(f'#{rid} error')
    return ok, len(rids), errors


async def _v263_send_rec_block_scheduled(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    return await _v264_send_rec_block(context, int(chat_id), b)


async def _v209_send_rec_block_at_schedule(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    return await _v264_send_rec_block(context, int(chat_id), b)


async def _v181_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, bid: int) -> tuple[int, int, List[str]]:
    b = _v171_rec_block_find(int(chat_id), int(bid)) if '_v171_rec_block_find' in globals() else None
    if not b:
        return 0, 0, ['No encuentro ese bloque recurrente.']
    return await _v264_send_rec_block(context, int(chat_id), b)


async def _v264_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    for chat_id in _v264_chat_ids():

        try:
            for row in list(recurring_list(int(chat_id))):
                try:
                    due, reason = _v189_recurring_due_reason(row, now) if '_v189_recurring_due_reason' in globals() else (recurring_due(row, now), 'due')
                    if not due:
                        continue
                    sent = await send_recurring_message(context, int(chat_id), row)
                    if sent:
                        if '_v189_mark_sent' in globals():
                            _v189_mark_sent(row, now)
                        else:
                            row['last_sent_ts'] = now
                        save_all_states()
                        logger.info('V264 recurrente enviado chat=%s id=%s reason=%s', chat_id, row.get('id'), reason)
                        await asyncio.sleep(0.35)
                except Exception:
                    logger.exception('V264 scheduler recurrente chat=%s id=%s', chat_id, row.get('id'))
        except Exception:
            logger.exception('V264 scheduler recurrentes chat=%s', chat_id)


        try:
            blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
            for b in blocks:
                try:
                    _v264_block_defaults(b)
                    due, slot, reason = _v264_block_due_slot(b, now)
                    if not due:
                        continue
                    b['v264_sending_slot'] = slot
                    save_all_states()
                    ok, total, errors = await _v264_send_rec_block(context, int(chat_id), b)
                    b.pop('v264_sending_slot', None)
                    if ok > 0:
                        b['last_sent_slot'] = slot
                        b['last_sent_day'] = slot.split('|', 1)[0] if '|' in slot else _v189_day_key(now) if '_v189_day_key' in globals() else time.strftime('%Y-%m-%d')
                    save_all_states()
                    logger.info('V264 bloque recurrente chat=%s bid=%s ok=%s/%s slot=%s reason=%s errors=%s', chat_id, b.get('id'), ok, total, slot, reason, errors[:3])
                    await asyncio.sleep(0.5)
                except Exception:
                    try:
                        b.pop('v264_sending_slot', None); save_all_states()
                    except Exception:
                        pass
                    logger.exception('V264 scheduler bloque chat=%s bloque=%s', chat_id, b)
        except Exception:
            logger.exception('V264 scheduler bloques chat=%s', chat_id)


async def _v264_scheduler_loop(app: Application) -> None:
    logger.info('V264 scheduler interno arrancado: interval=%ss catchup=%sm', _V264_RBLK_LOOP_INTERVAL, _V264_RBLK_MAX_CATCHUP_MINUTES)
    while True:
        try:
            class _Ctx:
                application = app
                bot = app.bot
            await _v264_scheduler_tick(_Ctx())
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V264 scheduler loop error')
        await asyncio.sleep(max(5, _V264_RBLK_LOOP_INTERVAL))


_old_post_init_v264 = None

async def _v264_post_init(app: Application) -> None:
    global _old_post_init_v264
    if callable(_old_post_init_v264):
        try:
            await _old_post_init_v264(app)
        except Exception:
            logger.exception('V264 post_init heredado falló')
    if app.bot_data.get(_V264_RBLK_LOOP_TASK_KEY):
        return
    app.bot_data[_V264_RBLK_LOOP_TASK_KEY] = True
    try:
        app.create_task(_v264_scheduler_loop(app), name='v264_scheduler_loop')
    except TypeError:
        app.create_task(_v264_scheduler_loop(app))


_old_v264_health_text = _v189_health_text if '_v189_health_text' in globals() else None

async def _v189_health_text(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> str:
    base = await _old_v264_health_text(context, int(chat_id)) if callable(_old_v264_health_text) else '<b>✅ COMPROBAR BOT</b>'
    try:
        now = int(time.time())
        lines = []
        for b in (_v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else [])[:10]:
            _v264_block_defaults(b)
            due, slot, reason = _v264_block_due_slot(b, now)
            name = str(b.get('name') or f'Bloque {b.get("id", "?")}')[:28]
            cada = 'OFF' if not bool(b.get('repeat_enabled')) else f'{int(b.get("repeat_every_minutes") or 0)//60}h' if int(b.get('repeat_every_minutes') or 0) % 60 == 0 else f'{int(b.get("repeat_every_minutes") or 0)}m'
            lines.append(f'• #{h(str(b.get("id","?")))} {h(name)} · Auto <b>{bool_label(_v264_block_enabled(b))}</b> · Inicio <b>{h(str(b.get("time")))}</b> · Cada <b>{h(cada)}</b> · Hasta <b>{h(str(b.get("repeat_until")))}</b> · {"YA" if due else h(reason)}')
        extra = '\n\n<b>📦 Bloques recurrentes V264</b>\n' + ('\n'.join(lines) if lines else 'Sin bloques recurrentes configurados.')
        return (base + extra)[:3900]
    except Exception:
        logger.exception('V264 health bloques falló')
        return base


_old_build_application_v264 = build_application

def build_application() -> Application:
    app = _old_build_application_v264()
    global _old_post_init_v264
    _old_post_init_v264 = getattr(app, 'post_init', None)
    app.post_init = _v264_post_init
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v264_scheduler_tick, interval=max(15, _V264_RBLK_LOOP_INTERVAL), first=3, name='v264_scheduler_tick')
            logger.info('V264 scheduler registrado también en JobQueue')
    except Exception:
        logger.exception('V264 no pudo registrar JobQueue')
    logger.info('V264 cargado: scheduler interno definitivo para recurrentes y bloques recurrentes')
    return app


