def _v265_boolish(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    s = str(value or '').strip().lower()
    return s in ('1', 'true', 'yes', 'on', 'si', 'sí', 'daily', 'auto', 'repeat', 'programado')


def _v265_hhmm(value: Any, default: str = '21:00') -> str:
    try:
        return _v264_hhmm(value, default) if '_v264_hhmm' in globals() else default
    except Exception:
        return default


def _v265_minutes(value: Any, default: str = '00:00') -> int:
    hm = _v265_hhmm(value, default)
    try:
        h0, m0 = hm.split(':', 1)
        return int(h0) * 60 + int(m0)
    except Exception:
        return 0


def _v265_now_dt(now_ts: Optional[int] = None):
    try:
        return _v264_dt(int(now_ts or time.time())) if '_v264_dt' in globals() else datetime.datetime.fromtimestamp(int(now_ts or time.time()))
    except Exception:
        return datetime.datetime.fromtimestamp(int(now_ts or time.time()))


def _v265_chat_ids() -> List[int]:
    ids = set()
    for getter in (
        lambda: list(STATE_CACHE.keys()),
        lambda: known_admin_chats_for_private() if 'known_admin_chats_for_private' in globals() else [],
    ):
        try:
            ids.update(int(x) for x in getter())
        except Exception:
            pass

    return sorted(x for x in ids if int(x) < 0)


def _v265_normalize_block(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
        elif '_v173_rec_block_defaults' in globals():
            _v173_rec_block_defaults(b)
    except Exception:
        pass

    b['time'] = _v265_hhmm(b.get('time') or b.get('start_time') or b.get('start') or b.get('inicio') or '21:00', '21:00')

    try:
        every = int(b.get('repeat_every_minutes') or b.get('repeat_minutes') or b.get('every_minutes') or 0)
    except Exception:
        every = 0
    every = max(0, every)
    b['repeat_every_minutes'] = every
    b['repeat_enabled'] = bool(b.get('repeat_enabled')) and every > 0


    raw_until = b.get('repeat_until') or b.get('until') or b.get('end_time') or b.get('hasta')
    until = _v265_hhmm(raw_until, '') if raw_until not in (None, '') else ''
    if not until or (b.get('repeat_enabled') and until == b.get('time') and every > 0):
        until = '23:59'
    b['repeat_until'] = until

    if bool(b.get('enabled')) or bool(b.get('repeat_enabled')):
        b['mode'] = 'daily'
    else:
        b.setdefault('mode', 'manual')
    b.setdefault('v265_last_sent_slot', '')
    return b


def _v265_block_is_programmed(b: Dict[str, Any]) -> bool:
    try:
        _v265_normalize_block(b)
        mode = str(b.get('mode') or '').strip().lower()
        return (
            bool(b.get('enabled'))
            or bool(b.get('auto_enabled'))
            or bool(b.get('scheduled'))
            or bool(b.get('repeat_enabled'))
            or mode in ('daily', 'auto', 'repeat', 'programado')
        )
    except Exception:
        return False


def _v265_block_due_slot(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str, str]:
    try:
        import datetime as _dt
        b = _v265_normalize_block(b)
        if not _v265_block_is_programmed(b):
            return False, '', 'OFF'

        now_ts = int(now_ts or time.time())
        now_dt = _v265_now_dt(now_ts)
        start_min = _v265_minutes(b.get('time'), '21:00')
        until_min = _v265_minutes(b.get('repeat_until'), '23:59')
        repeat = bool(b.get('repeat_enabled')) and int(b.get('repeat_every_minutes') or 0) > 0
        every = max(1, int(b.get('repeat_every_minutes') or 0)) if repeat else 0

        if repeat:
            window = until_min - start_min
            if window < 0:
                window += 24 * 60
        else:
            window = 0

        best = None
        reason = 'no toca'
        for delta in (-1, 0, 1):
            base_date = (now_dt + _dt.timedelta(days=delta)).date()
            start_dt = _dt.datetime.combine(base_date, _dt.time(start_min // 60, start_min % 60))
            try:
                if getattr(now_dt, 'tzinfo', None) is not None:
                    start_dt = start_dt.replace(tzinfo=now_dt.tzinfo)
            except Exception:
                pass

            if repeat:
                end_dt = start_dt + _dt.timedelta(minutes=window)
                if not (start_dt <= now_dt <= end_dt):
                    continue
                elapsed_min = int((now_dt - start_dt).total_seconds() // 60)
                slot_idx = elapsed_min // every
                slot_dt = start_dt + _dt.timedelta(minutes=slot_idx * every)
                if slot_dt > end_dt:
                    continue
                age = int((now_dt - slot_dt).total_seconds() // 60)
                if age > max(1, _V265_CATCHUP_MINUTES):
                    continue
                if best is None or slot_dt > best:
                    best = slot_dt
                    reason = f'cada {every}m hasta {b.get("repeat_until")}'
            else:
                slot_dt = start_dt
                age = int((now_dt - slot_dt).total_seconds() // 60)
                if 0 <= age <= max(1, _V265_CATCHUP_MINUTES):
                    if best is None or slot_dt > best:
                        best = slot_dt
                        reason = f'inicio {b.get("time")}'

        if best is None:
            return False, '', 'no toca ahora'
        slot = f'{best.strftime("%Y-%m-%d")}|{best.hour:02d}{best.minute:02d}'

        if str(b.get('v265_last_sent_slot') or '') == slot:
            return False, slot, 'ya enviado V265'
        if str(b.get('v265_sending_slot') or '') == slot:
            return False, slot, 'en envío'
        return True, slot, reason
    except Exception:
        logger.exception('V265 cálculo due bloque falló')
        return False, '', 'error'


def _v264_block_due_slot(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str, str]:
    return _v265_block_due_slot(b, now_ts)


def _v263_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    due, slot, _ = _v265_block_due_slot(b, now_ts)
    return due, slot


def _v237_block_due(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str]:
    due, slot, _ = _v265_block_due_slot(b, now_ts)
    return due, slot


async def _v265_send_rec_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, b: Dict[str, Any]) -> tuple[int, int, List[str]]:
    try:
        rids = _v264_extract_block_rids(b) if '_v264_extract_block_rids' in globals() else []
    except Exception:
        rids = []
    if not rids:
        return 0, 0, ['bloque vacío']
    ok = 0
    errors: List[str] = []
    for rid in rids:
        row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        try:
            tmp = copy.deepcopy(row)
            tmp['enabled'] = True

            for k in ('last_sent_ts', 'last_day', 'last_week_key', 'last_date_key', 'next_ts', 'next_run_ts'):
                tmp.pop(k, None)
            mid = await send_recurring_message(context, int(chat_id), tmp)
            if mid:
                ok += 1
            else:
                errors.append(f'#{rid} no enviado')
            await asyncio.sleep(0.45)
        except Exception:
            logger.exception('V265 error enviando recurrente #%s dentro de bloque chat=%s', rid, chat_id)
            errors.append(f'#{rid} error')
    return ok, len(rids), errors


