async def _v265_blocks_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    for chat_id in _v265_chat_ids():
        try:
            blocks = _v171_rec_blocks(int(chat_id)) if '_v171_rec_blocks' in globals() else []
            for b in list(blocks):
                if not isinstance(b, dict):
                    continue
                try:
                    _v265_normalize_block(b)
                    due, slot, reason = _v265_block_due_slot(b, now)
                    if not due:
                        continue
                    b['v265_sending_slot'] = slot
                    save_all_states()
                    ok, total, errors = await _v265_send_rec_block(context, int(chat_id), b)
                    b.pop('v265_sending_slot', None)
                    if ok > 0:
                        b['v265_last_sent_slot'] = slot
                        b['last_sent_slot'] = slot
                        b['last_sent_day'] = slot.split('|', 1)[0]
                        logger.info('V265 bloque ENVIADO chat=%s bid=%s ok=%s/%s slot=%s reason=%s', chat_id, b.get('id'), ok, total, slot, reason)
                    else:

                        logger.warning('V265 bloque NO enviado chat=%s bid=%s total=%s slot=%s errors=%s', chat_id, b.get('id'), total, slot, errors[:5])
                    save_all_states()
                    await asyncio.sleep(0.35)
                except Exception:
                    try:
                        b.pop('v265_sending_slot', None); save_all_states()
                    except Exception:
                        pass
                    logger.exception('V265 error bloque chat=%s block=%s', chat_id, b)
        except Exception:
            logger.exception('V265 scheduler bloques falló chat=%s', chat_id)


async def _v265_dj_auto_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = time.time()
    for chat_id, st in list(STATE_CACHE.items()):
        try:
            chat_id = int(chat_id)
            if not getattr(st, 'dj_mode', False):
                continue
            if not getattr(st, 'auto_track_enabled', False):
                continue
            if not getattr(st, 'live_enabled', False):
                continue
            if not getattr(st, 'queue', None):
                continue

            if now - float(_V265_DJ_ADVANCING.get(chat_id, 0.0)) < 7:
                continue
            if not getattr(st, 'now_playing', None):
                _V265_DJ_ADVANCING[chat_id] = now
                await simulate_panel_next(chat_id, reason='v265_auto_no_now_playing')
                continue
            track_data = dict(st.now_playing or {})
            token = track_key(track_data) if 'track_key' in globals() else str(track_data.get('title') or '')
            duration = int(track_data.get('duration') or 0)
            if duration <= 0:
                path = track_data.get('local_path') or ''
                try:
                    if path and Path(path).exists() and 'probe_duration_seconds' in globals():
                        duration = int(probe_duration_seconds(path) or 0)
                        if duration > 0:
                            st.now_playing['duration'] = duration
                            save_all_states()
                except Exception:
                    pass
            trigger = 0 if int(getattr(st, 'auto_sig_seconds', -1) or -1) < 0 else int(getattr(st, 'auto_sig_seconds', 0) or 0)
            started = int(getattr(st, 'play_started_at', None) or 0)
            if not started:
                continue
            elapsed = max(0, int(now - started))
            fallback = int(globals().get('UNKNOWN_END_FALLBACK_SECONDS', 360))
            limit = max(0, duration - trigger) if duration > 0 else max(fallback, trigger)
            if elapsed >= limit:
                _V265_DJ_ADVANCING[chat_id] = now
                logger.info('V265 DJ auto siguiente chat=%s token=%s elapsed=%s duration=%s trigger=%s', chat_id, token, elapsed, duration, trigger)
                await simulate_panel_next(chat_id, reason='v265_auto_end')
        except Exception:
            logger.exception('V265 DJ auto tick falló chat=%s', chat_id)


async def _v265_scheduler_loop(app: Application) -> None:
    logger.info('V265 loop interno arrancado')
    while True:
        try:
            class _Ctx:
                application = app
                bot = app.bot
            await _v265_blocks_tick(_Ctx())
            await _v265_dj_auto_tick(_Ctx())
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V265 loop interno error')
        await asyncio.sleep(max(5, _V265_INTERVAL))


def _v265_remove_old_jobs(app: Application) -> None:
    try:
        jq = getattr(app, 'job_queue', None)
        if not jq:
            return
        for name in ('v236_rblk_scheduler', 'v237_rblk_repeat_scheduler', 'v263_rblk_scheduler', 'v264_scheduler_tick'):
            try:
                for job in jq.get_jobs_by_name(name):
                    job.schedule_removal()
                    logger.info('V265 eliminado job antiguo %s', name)
            except Exception:
                pass
    except Exception:
        logger.exception('V265 no pudo limpiar jobs antiguos')


_old_build_application_v265 = build_application

async def _v265_post_init(app: Application) -> None:

    try:
        app.bot_data[_V264_RBLK_LOOP_TASK_KEY] = True
    except Exception:
        pass
    old = globals().get('_old_post_init_v264')
    if callable(old):
        try:
            await old(app)
        except Exception:
            logger.exception('V265 post_init heredado falló')
    if app.bot_data.get(_V265_LOOP_TASK_KEY):
        return
    app.bot_data[_V265_LOOP_TASK_KEY] = True
    try:
        app.create_task(_v265_scheduler_loop(app), name='v265_scheduler_loop')
    except TypeError:
        app.create_task(_v265_scheduler_loop(app))


def build_application() -> Application:
    app = _old_build_application_v265()
    _v265_remove_old_jobs(app)
    try:
        app.post_init = _v265_post_init
    except Exception:
        logger.exception('V265 no pudo instalar post_init')
    try:
        if app.job_queue:
            app.job_queue.run_repeating(_v265_blocks_tick, interval=max(10, _V265_INTERVAL), first=4, name=_V265_BLOCK_JOB_NAME)
            app.job_queue.run_repeating(_v265_dj_auto_tick, interval=max(3, _V265_DJ_INTERVAL), first=6, name=_V265_DJ_JOB_NAME)
            logger.info('V265 jobs registrados: bloques + DJ auto')
    except Exception:
        logger.exception('V265 no pudo registrar jobs')
    logger.info('V265 cargado: bloques recurrentes y AUTO DJ blindados')
    return app


if False and __name__ == '__main__':
    main()


