_V267_CATCHUP_MINUTES = int(os.getenv('V267_BLOCK_CATCHUP_MINUTES', '240') or 240)


def _v267_hhmm(value: Any, default: str = '21:00') -> str:
    s = str(value or '').strip()
    m = re.search(r'(\d{1,2})\s*[:hH.]\s*(\d{1,2})', s)
    if not m:
        return default
    hh = max(0, min(23, int(m.group(1))))
    mm = max(0, min(59, int(m.group(2))))
    return f'{hh:02d}:{mm:02d}'


def _v267_minutes(value: Any, default: str = '00:00') -> int:
    hm = _v267_hhmm(value, default)
    h0, m0 = hm.split(':', 1)
    return int(h0) * 60 + int(m0)


def _v267_chat_ids() -> List[int]:
    ids = set()
    try:
        ids.update(int(x) for x in STATE_CACHE.keys())
    except Exception:
        pass
    try:
        ids.update(int(x) for x in known_admin_chats_for_private())
    except Exception:
        pass
    return sorted(x for x in ids if int(x) < 0)


