def _v267_find_block(chat_id: int, bid: int) -> Optional[Dict[str, Any]]:
    try:
        b = _v171_rec_block_find(int(chat_id), int(bid)) if '_v171_rec_block_find' in globals() else None
        if b:
            return b
    except Exception:
        pass
    for b in _v267_blocks(chat_id):
        try:
            if int(b.get('id', 0) or 0) == int(bid):
                return b
        except Exception:
            pass
    return None


def _v267_extract_rids(block: Dict[str, Any]) -> List[int]:
    raw: List[Any] = []
    try:
        if '_v181_extract_rids_from_block' in globals():
            raw.extend(_v181_extract_rids_from_block(block))
    except Exception:
        pass
    for key in ('items', 'rids', 'recurring_ids', 'recurrentes', 'recurrents', 'ids'):
        v = block.get(key)
        if isinstance(v, list):
            raw.extend(v)
        elif v not in (None, ''):
            raw.append(v)
    out: List[int] = []
    for item in raw:
        try:
            if isinstance(item, dict):
                item = item.get('id') or item.get('rid') or item.get('rec_id') or item.get('recurring_id') or item.get('key')
            if isinstance(item, str):
                item = item.strip().replace('recsend_', '').replace('rec:', '').replace('rec_', '')
            rid = int(item)
            if rid > 0 and rid not in out:
                out.append(rid)
        except Exception:
            pass
    return out


def _v267_normalize_block(b: Dict[str, Any]) -> Dict[str, Any]:
    try:
        if '_v237_rblk_defaults' in globals():
            _v237_rblk_defaults(b)
    except Exception:
        pass
    b['time'] = _v267_hhmm(b.get('time') or b.get('start_time') or b.get('inicio') or '21:00', '21:00')
    try:
        every = int(b.get('repeat_every_minutes') or b.get('repeat_minutes') or b.get('every_minutes') or 0)
    except Exception:
        every = 0
    every = max(0, every)
    b['repeat_every_minutes'] = every
    b['repeat_enabled'] = bool(b.get('repeat_enabled')) and every > 0
    raw_until = b.get('repeat_until') or b.get('until') or b.get('end_time') or b.get('hasta')
    until = _v267_hhmm(raw_until, '') if raw_until not in (None, '') else ''
    if not until:
        until = '23:59'
    b['repeat_until'] = until
    if bool(b.get('enabled')) or bool(b.get('repeat_enabled')):
        b['mode'] = 'daily'
    b.setdefault('v267_last_sent_slot', '')
    return b


def _v267_block_programmed(b: Dict[str, Any]) -> bool:
    _v267_normalize_block(b)
    mode = str(b.get('mode') or '').lower().strip()
    return bool(b.get('enabled')) or bool(b.get('repeat_enabled')) or bool(b.get('auto_enabled')) or bool(b.get('scheduled')) or mode in ('daily', 'auto', 'repeat', 'programado')


def _v267_due_slot(b: Dict[str, Any], now_ts: Optional[int] = None) -> tuple[bool, str, str]:
    try:
        import datetime as _dt
        b = _v267_normalize_block(b)
        if not _v267_block_programmed(b):
            return False, '', 'OFF'
        now_dt = _dt.datetime.fromtimestamp(int(now_ts or time.time()))
        start_min = _v267_minutes(b.get('time'), '21:00')
        until_min = _v267_minutes(b.get('repeat_until'), '23:59')
        repeat = bool(b.get('repeat_enabled')) and int(b.get('repeat_every_minutes') or 0) > 0
        every = int(b.get('repeat_every_minutes') or 0) if repeat else 0
        window = 0
        if repeat:
            window = until_min - start_min
            if window < 0:
                window += 24 * 60
        best = None
        reason = 'no toca'
        for delta in (-1, 0, 1):
            d = (now_dt + _dt.timedelta(days=delta)).date()
            start_dt = _dt.datetime.combine(d, _dt.time(start_min // 60, start_min % 60))
            if repeat:
                end_dt = start_dt + _dt.timedelta(minutes=window)
                if not (start_dt <= now_dt <= end_dt):
                    continue
                elapsed = int((now_dt - start_dt).total_seconds() // 60)
                idx = elapsed // max(1, every)
                slot_dt = start_dt + _dt.timedelta(minutes=idx * every)
                age = int((now_dt - slot_dt).total_seconds() // 60)
                if 0 <= age <= max(1, _V267_CATCHUP_MINUTES):
                    if best is None or slot_dt > best:
                        best = slot_dt
                        reason = f'cada {every}m hasta {b.get("repeat_until")}'
            else:
                slot_dt = start_dt
                age = int((now_dt - slot_dt).total_seconds() // 60)
                if 0 <= age <= max(1, _V267_CATCHUP_MINUTES):
                    if best is None or slot_dt > best:
                        best = slot_dt
                        reason = f'inicio {b.get("time")}'
        if best is None:
            return False, '', 'no toca ahora'
        slot = f'{best:%Y-%m-%d}|{best.hour:02d}{best.minute:02d}'
        if str(b.get('v267_last_sent_slot') or '') == slot:
            return False, slot, 'ya enviado V267'
        if str(b.get('v267_sending_slot') or '') == slot:
            return False, slot, 'en envío'
        return True, slot, reason
    except Exception:
        logger.exception('V267 error calculando due de bloque')
        return False, '', 'error due'


async def _v267_send_message_attempt(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, text: str, media: Optional[Dict[str, Any]], markup: Any, parse_mode: Any) -> Optional[Any]:
    if media and media.get('file_id'):
        fid = media.get('file_id')
        mtype = str(media.get('type') or '').lower()
        caption = text or None
        if mtype == 'photo':
            return await context.bot.send_photo(chat_id, photo=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
        if mtype == 'video':
            return await context.bot.send_video(chat_id, video=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
        if mtype == 'animation':
            return await context.bot.send_animation(chat_id, animation=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
        if mtype == 'audio':
            return await context.bot.send_audio(chat_id, audio=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
        if mtype == 'voice':
            return await context.bot.send_voice(chat_id, voice=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
        return await context.bot.send_document(chat_id, document=fid, caption=caption, parse_mode=parse_mode, reply_markup=markup)
    return await context.bot.send_message(chat_id, text=text or 'Mensaje recurrente', parse_mode=parse_mode, reply_markup=markup)


async def _v267_send_recurring_force(context: ContextTypes.DEFAULT_TYPE, chat_id: int, row: Dict[str, Any]) -> tuple[bool, str]:
    text = str(row.get('text') or row.get('caption') or '').strip()
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    markup = None
    try:
        markup = recurring_buttons_markup(row) if 'recurring_buttons_markup' in globals() else None
    except Exception as e:
        logger.exception('V267 botones recurrente #%s fallaron', row.get('id'))
        return False, f'botones {type(e).__name__}'
    previous_message_id = int(row.get('last_message_id') or 0)
    delete_previous = bool(row.get('delete_previous', True))
    last_error = ''
    msg = None
    for media_try, parse_try in ((media, ParseMode.HTML), (media, None), (None, ParseMode.HTML), (None, None)):
        try:
            msg = await _v267_send_message_attempt(context, int(chat_id), text=text, media=media_try, markup=markup, parse_mode=parse_try)
            break
        except Exception as e:
            last_error = f'{type(e).__name__}: {str(e)[:120]}'
            logger.warning('V267 intento envío recurrente #%s falló chat=%s: %s', row.get('id'), chat_id, last_error)
            continue
    if not msg:
        return False, last_error or 'no enviado'
    try:
        await register_bot_message(int(chat_id), int(msg.message_id))
    except Exception:
        pass
    try:
        if bool(row.get('pin', False)):
            await context.bot.pin_chat_message(int(chat_id), int(msg.message_id), disable_notification=True)
    except Exception:
        logger.exception('V267 no pudo fijar recurrente #%s', row.get('id'))
    try:
        row['last_message_id'] = int(msg.message_id)
        row['delete_previous'] = delete_previous
        save_all_states()
    except Exception:
        pass
    if delete_previous and previous_message_id and previous_message_id != int(msg.message_id):
        try:
            await safe_delete(context.bot, int(chat_id), previous_message_id)
        except Exception:
            pass
    return True, str(int(msg.message_id))


async def _v267_send_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, block_or_bid: Any) -> tuple[int, int, List[str]]:
    block = block_or_bid if isinstance(block_or_bid, dict) else _v267_find_block(int(chat_id), int(block_or_bid))
    if not block:
        return 0, 0, ['no encuentro bloque']
    rids = _v267_extract_rids(block)
    if not rids:
        return 0, 0, ['bloque vacío']
    ok = 0
    errors: List[str] = []
    for rid in rids:
        row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
        if not row:
            errors.append(f'#{rid} no existe')
            continue
        sent, info = await _v267_send_recurring_force(context, int(chat_id), row)
        if sent:
            ok += 1
        else:
            errors.append(f'#{rid} {info}')
        await asyncio.sleep(1.0)
    return ok, len(rids), errors


