def _v267_parse_block_callback(data: str) -> tuple[Optional[int], Optional[int]]:
    parts = (data or '').split('|')
    try:
        if data.startswith('cfg|rblk_send|') and len(parts) >= 4:
            return int(parts[2]), int(parts[3])
        if data.startswith('panelrun|rblk|') and len(parts) >= 4:
            return int(parts[2]), int(parts[3])
        if data.startswith('panelcfg|control|'):
            chat_id = int(parts[2]) if len(parts) > 2 else None
            m = re.search(r'rblksend_(\d+)', data)
            return chat_id, int(m.group(1)) if m else None
    except Exception:
        return None, None
    return None, None


async def _v267_rblk_manual_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('cfg|rblk_send|') or data.startswith('panelrun|rblk|') or (data.startswith('panelcfg|control|') and 'rblksend_' in data)):
        return
    chat_id, bid = _v267_parse_block_callback(data)
    if not chat_id or not bid:
        await q.answer('No encuentro el bloque.', show_alert=True)
        raise ApplicationHandlerStop
    try:
        await q.answer('Enviando bloque...', show_alert=False)
    except Exception:
        pass
    ok, total, errors = await _v267_send_block(context, int(chat_id), int(bid))
    if ok > 0:
        msg = f'Bloque enviado: {ok}/{total} ✅'
        if errors:
            msg += '\nErrores: ' + ' · '.join(errors[:2])
        await q.answer(msg[:190], show_alert=True)
    else:
        detail = ' · '.join(errors[:2]) if errors else 'sin detalle'
        await q.answer(('No se envió ningún recurrente. ' + detail)[:190], show_alert=True)
    raise ApplicationHandlerStop


async def _v267_blocks_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    for chat_id in _v267_chat_ids():
        try:
            for b in list(_v267_blocks(int(chat_id))):
                if not isinstance(b, dict):
                    continue
                due, slot, reason = _v267_due_slot(b, now)
                if not due:
                    continue
                b['v267_sending_slot'] = slot
                save_all_states()
                ok, total, errors = await _v267_send_block(context, int(chat_id), b)
                b.pop('v267_sending_slot', None)
                if ok > 0:
                    b['v267_last_sent_slot'] = slot
                    b['last_sent_slot'] = slot
                    b['last_sent_day'] = slot.split('|', 1)[0]
                    logger.info('V267 bloque enviado chat=%s bid=%s ok=%s/%s slot=%s reason=%s', chat_id, b.get('id'), ok, total, slot, reason)
                else:
                    logger.warning('V267 bloque NO enviado chat=%s bid=%s total=%s slot=%s errors=%s', chat_id, b.get('id'), total, slot, errors[:3])
                save_all_states()
                await asyncio.sleep(0.5)
        except Exception:
            logger.exception('V267 tick bloques falló chat=%s', chat_id)


_old_build_application_v267 = build_application

def build_application() -> Application:
    app = _old_build_application_v267()
    try:
        if app.job_queue:
            for name in ('v236_rblk_scheduler', 'v237_rblk_repeat_scheduler', 'v263_rblk_scheduler', 'v264_scheduler_tick', 'v265_rec_blocks_scheduler', _V267_BLOCK_JOB_NAME):
                try:
                    for job in app.job_queue.get_jobs_by_name(name):
                        job.schedule_removal()
                except Exception:
                    pass
            app.job_queue.run_repeating(_v267_blocks_tick, interval=max(10, _V267_INTERVAL), first=5, name=_V267_BLOCK_JOB_NAME)
    except Exception:
        logger.exception('V267 no pudo registrar scheduler de bloques')
    try:
        app.add_handler(CallbackQueryHandler(_v267_rblk_manual_router, pattern=r'^(cfg\|rblk_send\||panelrun\|rblk\||panelcfg\|control\|)'), group=-999999999)
    except Exception:
        logger.exception('V267 no pudo registrar router manual')
    logger.info('V267 cargado: bloques recurrentes manuales y programados reparados antes de main()')
    return app


