def _v269_layout_of(row: Dict[str, Any]) -> str:
    try:
        if '_v104_layout' in globals():
            return str(_v104_layout(row))
    except Exception:
        pass
    try:
        layout = str(row.get('media_layout') or row.get('rec_media_layout') or '').strip().lower()
        if layout in {'caption', 'media_above', 'text_above', 'media_only', 'text_only'}:
            return layout
        pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').strip().lower()
        return 'text_above' if pos == 'below' else 'media_above'
    except Exception:
        return 'media_above'


async def _v267_send_recurring_force(context: ContextTypes.DEFAULT_TYPE, chat_id: int, row: Dict[str, Any]) -> tuple[bool, str]:
    """V269: envío de recurrente dentro de bloque usando la ruta oficial.

    No comprueba enabled/disabled del recurrente; el bloque decide. Pero sí
    respeta exactamente el formato multimedia configurado en ese recurrente.
    """
    try:
        before_id = int(row.get('last_message_id') or 0)
    except Exception:
        before_id = 0
    try:
        sent_id = await send_recurring_message(context, int(chat_id), row)
        if sent_id:
            try:
                layout = _v269_layout_of(row)
                logger.info('V269 bloque envió recurrente #%s chat=%s layout=%s msg=%s', row.get('id'), chat_id, layout, sent_id)
            except Exception:
                pass
            return True, str(int(sent_id))

        try:
            after_id = int(row.get('last_message_id') or 0)
            if after_id and after_id != before_id:
                return True, str(after_id)
        except Exception:
            pass
        return False, 'send_recurring_message devolvió vacío'
    except Exception as e:
        logger.exception('V269 fallo enviando recurrente #%s desde bloque chat=%s', row.get('id'), chat_id)
        return False, f'{type(e).__name__}: {str(e)[:120]}'


