def _v270_state_chat_id(state: ChatState) -> Optional[int]:
    try:
        for cid, st in STATE_CACHE.items():
            if st is state:
                return int(cid)
    except Exception:
        pass
    return None


def _v270_dj_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    fields = cfg.get('dj_pro_summary_fields_v270')
    if not isinstance(fields, list) or not fields:
        cfg['dj_pro_summary_fields_v270'] = list(V270_DJ_DEFAULT_FIELDS)
    cfg['dj_pro_summary_cols_v270'] = max(1, min(2, int(cfg.get('dj_pro_summary_cols_v270', 2) or 2)))
    cfg['dj_pro_summary_max_v270'] = max(0, min(36, int(cfg.get('dj_pro_summary_max_v270', 0) or 0)))
    return cfg


def _v270_short(raw: Any, max_len: int) -> str:
    s = str(raw if raw is not None else '—').replace('\n', ' ').replace('\r', ' ')
    s = ' '.join(s.split()) or '—'
    if max_len <= 0:
        return s
    return s if len(s) <= max_len else s[:max(1, max_len-1)] + '…'


def _v270_track_title(data: Optional[Dict[str, Any]], limit: int = 28) -> str:
    if not data:
        return 'Nada'
    try:
        return shorten_title(Track(**data).title, limit)
    except Exception:
        return _v270_short((data or {}).get('title') or 'Canción', limit)


