def _v270_voice_count_label(chat_id: int) -> str:
    cfg = admin_cfg(int(chat_id))
    count = cfg.get('dj_voice_participants_count_v270')
    names = cfg.get('dj_voice_participants_names_v270')
    if isinstance(count, int):
        if isinstance(names, list) and names:
            return f"{count} · " + _v270_short(', '.join(str(x) for x in names[:3]), 24)
        return str(count)
    return '—'


def _v270_value(chat_id: int, state: ChatState, key: str) -> str:
    cfg = _v270_dj_cfg(int(chat_id))
    try:
        if key == 'live':
            return 'ON' if state.live_enabled else 'OFF'
        if key == 'current':
            return _v270_track_title(state.now_playing, 30) if state.now_playing else 'Nada'
        if key == 'next':
            return _v270_track_title(state.queue[0], 30) if state.queue else 'Nada'
        if key == 'remaining':
            rem = remaining_seconds(state)
            return fmt_duration(rem) if rem is not None else '--:--'
        if key == 'queue_count':
            return str(len(state.queue))
        if key == 'upcoming':
            if not state.queue:
                return 'Sin próximas'
            titles = []
            for i, item in enumerate(state.queue[:3], start=1):
                titles.append(f"{i}.{_v270_track_title(item, 16)}")
            more = f" +{len(state.queue)-3}" if len(state.queue) > 3 else ''
            return ' · '.join(titles) + more
        if key == 'current_list':
            return _v270_current_list_name(int(chat_id)) or 'Sin lista'
        if key == 'voice_users':
            return _v270_voice_count_label(int(chat_id))
        if key == 'dj':
            return state.assigned_dj_name or 'Sin asignar'
        if key == 'auto':
            return 'ON' if state.auto_track_enabled else 'OFF'
        if key == 'shuffle':
            return 'ON' if getattr(state, 'dj_shuffle_enabled', False) else 'OFF'
        if key == 'temp':
            return format_auto_sig_label(state.auto_sig_seconds)
        if key == 'volume':
            return str(int(state.volume))
        if key == 'library':
            return str(len(state.library))
        if key == 'history_count':
            return str(len(state.history))
        if key == 'timer':
            return _v270_timer_label(int(chat_id))
        if key == 'opus':
            try:
                c = _v215_dj_cfg(int(chat_id)) if '_v215_dj_cfg' in globals() else cfg
            except Exception:
                c = cfg
            return ('ON' if bool(c.get('dj_opus_hd_enabled', False)) else 'OFF') + f"/{int(c.get('dj_opus_kbps', 128) or 128)}k"
        if key == 'announce':
            try:
                c = _v215_dj_cfg(int(chat_id)) if '_v215_dj_cfg' in globals() else cfg
            except Exception:
                c = cfg
            return 'ON' if bool(c.get('dj_announce_now_enabled', True)) else 'OFF'
    except Exception:
        return '—'
    return '—'


def _v270_cell(chat_id: int, state: ChatState, key: str, width: int, max_val: int) -> str:
    icon, abbr, _name = V270_DJ_SUMMARY_SPECS.get(key, ('•', str(key).upper()[:5], str(key)))
    label = f"{icon}{abbr}:"
    val_len = max(4, width - len(label) - 1)
    if max_val > 0:
        val_len = min(val_len, max_val)
    val = _v270_short(_v270_value(int(chat_id), state, key), val_len)
    return (label + val).ljust(width)[:width]


def _v270_dj_summary_text(chat_id: int, state: ChatState) -> str:
    cfg = _v270_dj_cfg(int(chat_id))
    fields = [str(x) for x in cfg.get('dj_pro_summary_fields_v270', V270_DJ_DEFAULT_FIELDS) if str(x) in V270_DJ_SUMMARY_SPECS]
    if not fields:
        fields = list(V270_DJ_DEFAULT_FIELDS)
    cols = max(1, min(2, int(cfg.get('dj_pro_summary_cols_v270', 2) or 2)))
    width = 42 if cols == 1 else 22
    max_val = int(cfg.get('dj_pro_summary_max_v270', 0) or 0)
    lines = []
    for start in range(0, len(fields), cols):
        cells = [_v270_cell(int(chat_id), state, k, width, max_val) for k in fields[start:start+cols]]
        lines.append(''.join(cells).rstrip())
    return '<b>🎛️ CUADRO DE MANDOS DJ-PRO</b>\n<pre>' + h('\n'.join(lines) or '—') + '</pre>\n'


