def _v273_state_chat_id(state: ChatState) -> Optional[int]:
    try:
        return _v271_state_chat_id(state) if '_v271_state_chat_id' in globals() else _v270_state_chat_id(state)
    except Exception:
        try:
            for cid, st in STATE_CACHE.items():
                if st is state:
                    return int(cid)
        except Exception:
            pass
    return None


