async def _v273_edit_panel_safe(bot, chat_id: int) -> None:
    """Edita la mesa existente. No crea otra debajo salvo que no exista todavía."""
    try:
        await _v271_edit_panel(bot, int(chat_id)) if '_v271_edit_panel' in globals() else await ensure_control_panel(bot, int(chat_id))
    except BadRequest as e:
        if 'message is not modified' not in str(e).lower():
            logger.exception('V273 no pudo refrescar mesa DJ-PRO chat=%s', chat_id)
