    chat_id = _v273_state_chat_id(state) or 0
    cfg = _v273_cfg(int(chat_id)) if chat_id else {}
    live = bool(getattr(state, 'live_enabled', False))
    temp_on = int(getattr(state, 'auto_sig_seconds', -1) or -1) >= 0
    auto_on = bool(getattr(state, 'auto_track_enabled', False))
    shuffle_on = bool(getattr(state, 'dj_shuffle_enabled', False))
    opus_on = bool(cfg.get('dj_opus_hd_enabled', False))
    kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
    ann_on = bool(cfg.get('dj_announce_now_enabled', True))
