async def _v273_announce_track(bot, chat_id: int, track: Optional[Track]) -> None:
    if not track:
        return
    try:
        await _v271_send_now_announce(bot, int(chat_id), track) if '_v271_send_now_announce' in globals() else await _send_dj_now_announce_v24(bot, int(chat_id), track)
    except Exception:
        logger.exception('V273 no pudo enviar aviso de canción chat=%s', chat_id)


async def _v273_track_from_state_now(chat_id: int) -> Optional[Track]:
    try:
        st = get_state(int(chat_id))
        if st.now_playing:
            return Track(**st.now_playing)
    except Exception:
        pass
    return None


async def _v273_start_live(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> tuple[bool, str]:
    """LIVE ON fiable: inicia videochat y reproduce actual o primera cola."""
    state = get_state(int(chat_id))
    bot = context.bot
    try:
        state.dj_mode = True
        state.live_enabled = True
        state.paused = False
        save_all_states()
        try:
            await VOICE.ensure_videochat_started(int(chat_id))
        except Exception:
            logger.exception('V273 no pudo asegurar videochat chat=%s', chat_id)


        if state.now_playing:
            try:
                tr = Track(**state.now_playing)
                await VOICE.play_track(bot, int(chat_id), tr)
                await _v273_announce_track(bot, int(chat_id), tr)
                return True, 'LIVE ON · actual'
            except Exception:
                logger.exception('V273 no pudo reproducir canción actual; probará cola chat=%s', chat_id)


        if state.queue:
            ok = await simulate_panel_next(int(chat_id), reason='live_on_v273')
            tr2 = await _v273_track_from_state_now(int(chat_id))
            if ok:
                await _v273_announce_track(bot, int(chat_id), tr2)
                return True, 'LIVE ON · sonando'
            return True, 'LIVE ON · cola con error'


        save_all_states()
        return True, 'LIVE ON · sin cola'
    finally:
        await _v273_edit_panel_safe(bot, int(chat_id))


async def _v273_stop_live(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> tuple[bool, str]:
    state = get_state(int(chat_id))
    bot = context.bot
    try:
        if state.now_playing:
            current = dict(state.now_playing)
            current_key = track_key(current)
            first_key = track_key(state.queue[0]) if state.queue else ''
            if not state.queue or current_key != first_key:
                state.queue.insert(0, current)
        state.live_enabled = False
        state.now_playing = None
        state.paused = False
        state.play_started_at = None
        state.paused_remaining = None
        save_all_states()
        await cancel_auto_next(int(chat_id))
        try:
            await VOICE.leave(int(chat_id), end_videochat=True)
        except Exception:
            logger.exception('V273 no pudo cerrar/abandonar directo chat=%s', chat_id)
        return False, 'LIVE OFF'
    finally:
        await _v273_edit_panel_safe(bot, int(chat_id))


async def _v273_toggle_live(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> tuple[bool, str]:
    state = get_state(int(chat_id))
    if bool(state.live_enabled):
        return await _v273_stop_live(context, int(chat_id))
    return await _v273_start_live(context, int(chat_id))


