_old_v284_send_daily_phrase = _v113_send_daily_phrase if '_v113_send_daily_phrase' in globals() else None
async def _v113_send_daily_phrase(application_or_bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> List[int]:
    bot = getattr(application_or_bot, 'bot', application_or_bot)
    cfg = admin_cfg(int(chat_id))
    phrase = daily_phrase_for_chat_v30(int(chat_id), now_ts) if 'daily_phrase_for_chat_v30' in globals() else daily_phrase_for_date_v15(now_ts or int(time.time()))
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    caption = _v284_phrase_caption(int(chat_id), phrase, now_ts=now_ts)
    sent_ids: List[int] = []
    try:
        if image and image.get('file_id') and bool(cfg_value(int(chat_id), 'daily_phrase_image_enabled', True)):
            msg = await bot.send_photo(int(chat_id), photo=image.get('file_id'), caption=caption, parse_mode=ParseMode.HTML)
            kind = 'photo'
        else:
            msg = await bot.send_message(int(chat_id), caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
            kind = 'text'
        await register_bot_message(int(chat_id), msg.message_id)
        sent_ids.append(int(msg.message_id))
        if '_v114_sent_store' in globals():
            try:
                store = _v114_sent_store(int(chat_id))
                store[str(msg.message_id)] = {'phrase': phrase, 'kind': kind, 'next_used': [], 'sent_ts': int(time.time())}
                save_all_states()
            except Exception:
                pass
        try:
            if '_v114_phrase_markup' in globals():
                await bot.edit_message_reply_markup(chat_id=int(chat_id), message_id=msg.message_id, reply_markup=_v114_phrase_markup(int(chat_id), msg.message_id))
        except Exception:
            pass
        if bool(cfg_value(int(chat_id), 'daily_phrase_pin', False)):
            try:
                await bot.pin_chat_message(int(chat_id), msg.message_id, disable_notification=True)
            except Exception:
                pass
    except Exception:
        logger.exception('V284 no pudo enviar frase del día')
        raise
    return sent_ids


