async def _v284_ensure_easy_pinned(bot, chat_id: int) -> None:
    chat_id = int(chat_id)
    state = get_state(chat_id)
    mid = int(state.panel_message_id or 0)
    if not mid:
        return
    cfg = admin_cfg(chat_id)

    if int(cfg.get('dj_easy_pinned_message_id_v284') or 0) == mid:
        return
    try:
        await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
        cfg['dj_easy_pinned_message_id_v284'] = mid
        save_all_states()
    except BadRequest as e:

        if 'not modified' in str(e).lower() or 'already' in str(e).lower():
            cfg['dj_easy_pinned_message_id_v284'] = mid
            save_all_states()
        else:
            logger.warning('V284: no pude fijar mesa DJ Fácil en %s: %s', chat_id, e)
    except Exception:
        logger.exception('V284: error fijando mesa DJ Fácil en %s', chat_id)


_old_v284_render_easy_panel = _v283_render_easy_panel if '_v283_render_easy_panel' in globals() else None
async def _v283_render_easy_panel(bot, chat_id: int, query=None, *, force: bool = False) -> None:
    chat_id = int(chat_id)
    if callable(_old_v284_render_easy_panel):
        await _old_v284_render_easy_panel(bot, chat_id, query=query, force=force)
    else:

        state = get_state(chat_id)
        state.dj_mode = True
        if '_v75_set_mode' in globals():
            _v75_set_mode(chat_id, 'easy')
        text = _v75_easy_text(chat_id) if '_v75_easy_text' in globals() else '<b>🎧 DJ Fácil</b>'
        markup = _v75_easy_markup() if '_v75_easy_markup' in globals() else InlineKeyboardMarkup([[InlineKeyboardButton('▶️ DIRECTO', callback_data='dj_easy_start')]])
        if state.panel_message_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=int(state.panel_message_id), text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
            except Exception:
                state.panel_message_id = None
                state.control_message_id = None
        if not state.panel_message_id:
            msg = await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
            state.panel_message_id = int(msg.message_id)
            state.control_message_id = int(msg.message_id)
            await register_bot_message(chat_id, msg.message_id)
        save_all_states()
    await _v284_ensure_easy_pinned(bot, chat_id)


