_old_v285_easy_text = _v75_easy_text if '_v75_easy_text' in globals() else None
def _v75_easy_text(chat_id: int) -> str:
    """Texto compacto DJ Fácil. Se mantiene como panel editable/fijado."""
    chat_id = int(chat_id)
    state = get_state(chat_id)
    live = 'ON' if bool(state.live_enabled) else 'OFF'
    auto = 'ON' if bool(state.auto_track_enabled) else 'OFF'
    alea = 'ON' if bool(getattr(state, 'dj_shuffle_enabled', False)) else 'OFF'
    if state.now_playing:
        try:
            now = Track(**state.now_playing).title
        except Exception:
            now = str((state.now_playing or {}).get('title') or 'Nada sonando')
    else:
        now = 'Nada sonando'
    nxt = 'Sin siguiente'
    if state.queue:
        try:
            nxt = Track(**state.queue[0]).title
        except Exception:
            nxt = str((state.queue[0] or {}).get('title') or 'Sin siguiente')
    return (
        "<b>🎧 DJ FÁCIL</b>\n\n"
        f"LIVE: <b>{h(live)}</b> · AUTO: <b>{h(auto)}</b> · ALEA: <b>{h(alea)}</b>\n"
        f"SONANDO: <b>{h(shorten_title(now, 42))}</b>\n"
        f"SIGUIENTE: <b>{h(shorten_title(nxt, 42))}</b>\n"
        f"BIBLIOTECA: <b>{len(state.library)}</b> · COLA: <b>{len(state.queue)}</b>\n\n"
        "<i>Usa ℹ️ INFO para ver cómo iniciar el directo y añadir canciones con /cola.</i>"
    )


async def _v285_easy_info_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_instructions', 'dj_easy_back'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    try:
        allowed = True
        if '_v105_user_can_easy' in globals():
            allowed = await _v105_user_can_easy(context, chat_id, user)
        elif '_v77_dj_allowed' in globals():
            allowed = await _v77_dj_allowed(context, chat_id, user, 'easy')
        if not allowed and int(user.id) not in ADMIN_IDS:
            await q.answer('No estás autorizado para DJ Fácil.', show_alert=True)
            raise _V285Stop
    except _V285Stop:
        raise
    except Exception:
        pass

    try:
        if data == 'dj_easy_instructions':
            _v283_set_easy_mode(chat_id) if '_v283_set_easy_mode' in globals() else None
            state = get_state(chat_id)
            qmsg_id = int(getattr(getattr(q, 'message', None), 'message_id', 0) or 0)
            if qmsg_id:
                state.panel_message_id = qmsg_id
                state.control_message_id = qmsg_id
                save_all_states()
            await q.answer('Instrucciones')
            await q.edit_message_text(
                _v285_easy_instructions_text(chat_id),
                parse_mode=ParseMode.HTML,
                reply_markup=_v285_easy_instructions_markup(),
                disable_web_page_preview=True,
            )
            try:
                await _v284_ensure_easy_pinned(context.bot, chat_id)
            except Exception:
                pass
            raise _V285Stop

        if data == 'dj_easy_back':
            await q.answer('DJ Fácil')
            await _v283_render_easy_panel(context.bot, chat_id, query=q, force=True)
            raise _V285Stop
    except _V285Stop:
        raise
    except BadRequest as e:
        if 'message is not modified' not in str(e).lower():
            logger.warning('V285: no pude editar instrucciones DJ Fácil: %s', e)
        raise _V285Stop
    except Exception:
        logger.exception('V285: error en instrucciones DJ Fácil')
        raise _V285Stop


async def expulsar_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Expulsa al usuario respondido y manda el mensaje configurado de Rechazado con multimedia."""
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /expulsar respondiendo a un miembro dentro del grupo.')
        return
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    target_msg = update.message.reply_to_message
    target_user = getattr(target_msg, 'from_user', None) if target_msg else None
    if not target_user:
        await update.message.reply_text('Responde al mensaje del miembro que quieres expulsar con /expulsar.')
        return
    if getattr(target_user, 'is_bot', False):
        await update.message.reply_text('No expulso bots desde este comando.')
        return
    target_id = int(target_user.id)
    try:
        me = await context.bot.get_me()
        if target_id == int(me.id):
            await update.message.reply_text('No puedo expulsarme a mí mismo.')
            return
    except Exception:
        pass

    record = user_record_from_user(target_user) if 'user_record_from_user' in globals() else {
        'user_id': target_id,
        'name': display_name(target_user),
        'username': f"@{getattr(target_user, 'username', '')}" if getattr(target_user, 'username', None) else '',
    }
    try:

        await context.bot.ban_chat_member(chat_id=chat_id, user_id=target_id)
        try:
            await context.bot.unban_chat_member(chat_id=chat_id, user_id=target_id, only_if_banned=True)
        except Exception:
            pass
        try:
            mark_user_expelled(chat_id, target_id, record=record, reason='expulsado manualmente con /expulsar', by_user_id=int(update.effective_user.id))
        except Exception:
            pass

        target_mention = f'<a href="tg://user?id={target_id}">{h(display_name(target_user) or target_id)}</a>'
        rejected_text = str(cfg_value(chat_id, 'validation_rejected_message', VALIDATION_REJECTED_MESSAGE))
        rejected_text = (
            rejected_text
            .replace('{mention}', target_mention)
            .replace('{name}', h(display_name(target_user)))
            .replace('{first}', h(getattr(target_user, 'first_name', '') or display_name(target_user)))
            .replace('{username}', h('@' + target_user.username if getattr(target_user, 'username', None) else ''))
            .replace('{id}', str(target_id))
        )
        await send_configured_profile_message(context.bot, chat_id, 'rejected', rejected_text)
        try:
            await safe_delete(context.bot, chat_id, update.message.message_id)
        except Exception:
            pass
    except Exception:
        logger.exception('V285: no se pudo expulsar con /expulsar en chat %s', chat_id)
        await update.message.reply_text('No pude expulsar. Revisa que el bot sea administrador y tenga permiso de banear usuarios.')


