BOT_VERSION = "V287"

try:
    from telegram.ext import ApplicationHandlerStop as _V287Stop
except Exception:
    _V287Stop = Exception

_V287_EASY_RENDER_LOCKS: Dict[int, asyncio.Lock] = {}
_V287_EASY_RENDER_CACHE: Dict[int, str] = {}
_V287_EASY_LAST_RENDER_AT: Dict[int, float] = {}
_V287_AUTO_DELETE_TASKS: Dict[tuple[int, int], asyncio.Task] = {}


def _v287_lock(chat_id: int) -> asyncio.Lock:
    chat_id = int(chat_id)
    lock = _V287_EASY_RENDER_LOCKS.get(chat_id)
    if lock is None:
        lock = asyncio.Lock()
        _V287_EASY_RENDER_LOCKS[chat_id] = lock
    return lock


def _v287_now() -> float:
    return __import__('time').time()


def _v287_is_easy(chat_id: int) -> bool:
    try:
        return bool(_v283_is_easy(int(chat_id)))
    except Exception:
        try:
            return str(admin_cfg(int(chat_id)).get('dj_session_mode','')).lower() in ('easy','facil','fácil','podcast')
        except Exception:
            return False


def _v287_markup_sig(markup: Optional[InlineKeyboardMarkup]) -> str:
    try:
        rows = []
        for row in getattr(markup, 'inline_keyboard', []) or []:
            rows.append('|'.join(f"{getattr(b,'text','')}:{getattr(b,'callback_data','') or getattr(b,'url','')}" for b in row))
        return '\n'.join(rows)
    except Exception:
        return ''


def _v287_panel_ids(chat_id: int) -> set[int]:
    ids: set[int] = set()
    try:
        st = get_state(int(chat_id))
        for value in (st.panel_message_id, st.control_message_id, st.temp_pin_message_id):
            if value:
                ids.add(int(value))
    except Exception:
        pass
    try:
        cfg = admin_cfg(int(chat_id))
        for key in ('dj_easy_pinned_message_id_v284', 'dj_panel_message_id', 'dj_control_message_id'):
            value = cfg.get(key)
            if value:
                ids.add(int(value))
    except Exception:
        pass
    return ids


async def _v287_ensure_pin_once(bot, chat_id: int, message_id: int) -> None:
    """Fija sin insistir en cada refresh. Pin repetido = lentitud y avisos de servicio."""
    chat_id = int(chat_id); message_id = int(message_id)
    cfg = admin_cfg(chat_id)
    if int(cfg.get('dj_easy_pinned_message_id_v284') or 0) == message_id and int(cfg.get('dj_easy_last_pin_ok') or 0) == message_id:
        return
    try:
        await bot.pin_chat_message(chat_id=chat_id, message_id=message_id, disable_notification=True)
        cfg['dj_easy_pinned_message_id_v284'] = message_id
        cfg['dj_easy_last_pin_ok'] = message_id
        save_all_states()
    except Exception:

        cfg['dj_easy_pinned_message_id_v284'] = message_id
        save_all_states()


async def _v287_render_easy_panel(bot, chat_id: int, *, force: bool = False, pin: bool = False) -> None:
    """Render único y rápido de DJ Fácil: sin duplicados y sin repintados inútiles."""
    chat_id = int(chat_id)
    async with _v287_lock(chat_id):
        try:
            _v283_set_easy_mode(chat_id)
        except Exception:
            pass
        st = get_state(chat_id)
        text = _v75_easy_text(chat_id) if '_v75_easy_text' in globals() else '<b>🎧 DJ FÁCIL</b>'
        markup = _v75_easy_markup() if '_v75_easy_markup' in globals() else InlineKeyboardMarkup([
            [InlineKeyboardButton('▶️ INICIAR', callback_data='dj_easy_start'), InlineKeyboardButton('⏭ SIG.', callback_data='dj_easy_next')],
            [InlineKeyboardButton('ℹ️ INFO', callback_data='dj_easy_instructions'), InlineKeyboardButton('❌ CERRAR', callback_data='dj_easy_close')],
        ])
        sig = text + '\n---\n' + _v287_markup_sig(markup)
        now = _v287_now()
        target_id = int(st.control_message_id or st.panel_message_id or admin_cfg(chat_id).get('dj_easy_pinned_message_id_v284') or 0)


        if target_id and not force and _V287_EASY_RENDER_CACHE.get(chat_id) == sig:
            return

        if target_id and not force and (now - float(_V287_EASY_LAST_RENDER_AT.get(chat_id, 0.0))) < 0.45:
            return

        if target_id:
            try:
                await bot.edit_message_text(
                    chat_id=chat_id,
                    message_id=target_id,
                    text=text,
                    parse_mode=ParseMode.HTML,
                    reply_markup=markup,
                    disable_web_page_preview=True,
                )
                st.panel_message_id = target_id
                st.control_message_id = target_id

                st.temp_message_ids = [mid for mid in st.temp_message_ids if int(mid) != target_id]
                if target_id not in st.bot_message_ids:
                    st.bot_message_ids.append(target_id)
                _V287_EASY_RENDER_CACHE[chat_id] = sig
                _V287_EASY_LAST_RENDER_AT[chat_id] = now
                save_all_states()
                if pin:
                    await _v287_ensure_pin_once(bot, chat_id, target_id)
                return
            except BadRequest as e:
                low = str(e).lower()
                if 'message is not modified' in low:
                    _V287_EASY_RENDER_CACHE[chat_id] = sig
                    return
                if any(x in low for x in ('message to edit not found', 'message_id_invalid', 'message not found')):
                    st.panel_message_id = None
                    st.control_message_id = None
                    admin_cfg(chat_id).pop('dj_easy_pinned_message_id_v284', None)
                    save_all_states()
                else:
                    logger.warning('V287: no pude editar mesa fácil; evito duplicar: %s', e)
                    return
            except Exception:
                logger.exception('V287: error editando mesa fácil; evito duplicar')
                return

        try:
            msg = await bot.send_message(
                chat_id=chat_id,
                text=text,
                parse_mode=ParseMode.HTML,
                reply_markup=markup,
                disable_web_page_preview=True,
            )
            st.panel_message_id = int(msg.message_id)
            st.control_message_id = int(msg.message_id)
            st.temp_message_ids = [mid for mid in st.temp_message_ids if int(mid) != int(msg.message_id)]
            if int(msg.message_id) not in st.bot_message_ids:
                st.bot_message_ids.append(int(msg.message_id))
            admin_cfg(chat_id)['dj_easy_pinned_message_id_v284'] = int(msg.message_id)
            _V287_EASY_RENDER_CACHE[chat_id] = sig
            _V287_EASY_LAST_RENDER_AT[chat_id] = now
            save_all_states()
            if pin:
                await _v287_ensure_pin_once(bot, chat_id, int(msg.message_id))
        except Exception:
            logger.exception('V287: no pude crear mesa fácil persistente')


async def _v283_render_easy_panel(bot, chat_id: int, query=None, *, force: bool = False) -> None:
    chat_id = int(chat_id)
    q = query
    qmsg = getattr(q, 'message', None) if q is not None else None
    qmsg_id = int(getattr(qmsg, 'message_id', 0) or 0)
    data = str(getattr(q, 'data', '') or '') if q is not None else ''
    st = get_state(chat_id)


    if data == 'dj_easy_menu' and qmsg_id and qmsg_id not in _v287_panel_ids(chat_id):
        try:
            await _v286_delete_selector_message(bot, chat_id, qmsg_id)
        except Exception:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=qmsg_id)
            except Exception:
                pass
        if st.panel_message_id == qmsg_id:
            st.panel_message_id = None
        if st.control_message_id == qmsg_id:
            st.control_message_id = None
        save_all_states()
    await _v287_render_easy_panel(bot, chat_id, force=force, pin=True)


async def _v287_prepare_easy_queue(chat_id: int, *, force_library: bool = False) -> bool:
    st = get_state(int(chat_id))
    if force_library or not st.queue:
        items = [dict(x) for x in (st.library or [])]
        if st.now_playing:
            cur = track_key(st.now_playing)
            items = [x for x in items if track_key(x) != cur]
        if getattr(st, 'dj_shuffle_enabled', False) and len(items) > 1:
            import random as _r
            _r.shuffle(items)
        st.queue = dedupe_track_items(items)
        save_all_states()
    return bool(st.queue)


async def _v287_play_track_fast(context: ContextTypes.DEFAULT_TYPE, chat_id: int, data: Dict[str, Any]) -> bool:
    """Ruta rápida para DJ Fácil: no llama a VOICE.play_track para evitar 2-3 renders intermedios."""
    chat_id = int(chat_id)
    st = get_state(chat_id)
    bot = context.bot
    try:
        await VOICE.ensure_videochat_started(chat_id)
    except Exception:
        logger.exception('V287: no se pudo asegurar videochat')
    try:
        track = Track(**dict(data))
        if not track.local_path or not Path(track.local_path).exists():
            track = await materialize_track(bot, chat_id, track)
        if track.duration <= 0 and track.local_path and Path(track.local_path).exists():
            track.duration = probe_duration_seconds(track.local_path)
        await VOICE.play_file(chat_id, track.local_path)
        try:
            await VOICE._apply_volume(chat_id, int(st.volume or 100))
        except Exception:
            pass
        import time as _time
        st.live_enabled = True
        st.auto_track_enabled = True
        st.auto_sig_seconds = 0
        st.paused = False
        st.now_playing = asdict(track)
        st.play_started_at = int(_time.time())
        st.paused_remaining = None
        save_all_states()
        try:
            await cleanup_old_files(chat_id)
        except Exception:
            pass
        try:
            await schedule_auto_next(chat_id, int(track.duration or 0), 0)
        except Exception:
            pass
        return True
    except Exception:
        logger.exception('V287: fallo reproduciendo pista rápida easy')
        return False


async def _v283_play_next_easy(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, reason: str = 'easy') -> bool:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    try:
        _v283_set_easy_mode(chat_id)
    except Exception:
        pass
    st.live_enabled = True
    st.auto_track_enabled = True
    st.auto_sig_seconds = 0
    st.paused = False
    save_all_states()

    if not await _v287_prepare_easy_queue(chat_id):
        logger.warning('V287: DJ Fácil sin cola/biblioteca en %s (%s)', chat_id, reason)
        return False

    if getattr(st, 'dj_shuffle_enabled', False) and len(st.queue) > 1:
        idx = secrets.randbelow(len(st.queue))
        next_data = st.queue.pop(idx)
    else:
        next_data = st.queue.pop(0)
    if st.now_playing:
        try:
            if track_key(st.now_playing) != track_key(next_data):
                st.history.append(dict(st.now_playing))
                st.history = st.history[-50:]
        except Exception:
            pass
    save_all_states()

    ok = await _v287_play_track_fast(context, chat_id, next_data)
    if not ok:
        try:
            st.queue.insert(0, next_data)
            save_all_states()
        except Exception:
            pass
        return False
    return True


_old_simulate_panel_next_v287 = simulate_panel_next if 'simulate_panel_next' in globals() else None
async def simulate_panel_next(chat_id: int, reason: str = 'panel_next') -> bool:
    chat_id = int(chat_id)
    try:
        if _v287_is_easy(chat_id) and VOICE.application:
            ok = await _v283_play_next_easy(VOICE.application, chat_id, reason='auto_' + str(reason))
            if ok:
                await _v287_render_easy_panel(VOICE.application.bot, chat_id, force=True, pin=False)
            return ok
    except Exception:
        logger.exception('V287: fallo auto-next fácil')
        return False
    if callable(_old_simulate_panel_next_v287):
        return await _old_simulate_panel_next_v287(chat_id, reason)
    return False


