def _v287_autodel_seconds(chat_id: int) -> int:
    try:
        cfg = admin_cfg(int(chat_id))
        if not bool(cfg.get('chat_autodelete_enabled_v287', False)):
            return 0
        return int(cfg.get('chat_autodelete_seconds_v287') or 0)
    except Exception:
        return 0


def _v287_autodel_label(chat_id: int) -> str:
    sec = _v287_autodel_seconds(int(chat_id))
    if sec <= 0:
        return 'OFF'
    if sec % 3600 == 0:
        return f'{sec//3600}h'
    if sec % 60 == 0:
        return f'{sec//60}m'
    return f'{sec}s'


async def _v287_delete_message_after(bot, chat_id: int, message_id: int, seconds: int) -> None:
    key = (int(chat_id), int(message_id))
    try:
        await asyncio.sleep(max(1, int(seconds)))

        if int(message_id) in _v287_panel_ids(int(chat_id)):
            return
        try:
            await bot.delete_message(chat_id=int(chat_id), message_id=int(message_id))
        except Exception:
            pass
    finally:
        _V287_AUTO_DELETE_TASKS.pop(key, None)


async def _v287_chat_autodelete_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat = update.effective_chat

    if getattr(chat, 'type', '') == 'private':
        return
    chat_id = int(chat.id)
    seconds = _v287_autodel_seconds(chat_id)
    if seconds <= 0:
        return
    msg = update.message
    mid = int(getattr(msg, 'message_id', 0) or 0)
    if not mid:
        return

    if mid in _v287_panel_ids(chat_id):
        return
    if service_cleanup_detect_kind(msg) if 'service_cleanup_detect_kind' in globals() else False:
        return

    key = (chat_id, mid)
    if key in _V287_AUTO_DELETE_TASKS:
        return
    _V287_AUTO_DELETE_TASKS[key] = asyncio.create_task(_v287_delete_message_after(context.bot, chat_id, mid, seconds))


async def _v287_autodel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('cfg|chat_autodel|'):
        return
    parts = data.split('|')
    try:
        chat_id = int(parts[2])
        seconds = int(parts[3])
    except Exception:
        await q.answer('Dato inválido.', show_alert=True)
        raise _V287Stop
    try:
        if not is_global_admin_user(int(update.effective_user.id)) and not await is_admin(context, chat_id, int(update.effective_user.id)):
            await q.answer('Solo administradores.', show_alert=True)
            raise _V287Stop
    except _V287Stop:
        raise
    except Exception:
        pass
    cfg = admin_cfg(chat_id)
    if seconds <= 0:
        cfg['chat_autodelete_enabled_v287'] = False
        cfg['chat_autodelete_seconds_v287'] = 0
        label = 'OFF'
    else:
        cfg['chat_autodelete_enabled_v287'] = True
        cfg['chat_autodelete_seconds_v287'] = seconds
        label = _v287_autodel_label(chat_id)
    save_all_states()
    await q.answer(f'Autoeliminación: {label}', show_alert=False)
    try:
        await q.edit_message_text(
            service_cleanup_summary_text(chat_id),
            parse_mode=ParseMode.HTML,
            reply_markup=service_cleanup_markup(chat_id),
        )
    except Exception:
        pass
    raise _V287Stop


_old_service_cleanup_summary_text_v287 = service_cleanup_summary_text if 'service_cleanup_summary_text' in globals() else None
def service_cleanup_summary_text(chat_id: int) -> str:
    base = _old_service_cleanup_summary_text_v287(chat_id) if callable(_old_service_cleanup_summary_text_v287) else '<b>🧽 Limpieza</b>'
    return (
        base
        + "\n\n<b>🕒 Autoeliminación de mensajes normales</b>"
        + f"\nEstado: <b>{h(_v287_autodel_label(int(chat_id)))}</b>"
        + "\n<i>El bot programa el borrado de mensajes nuevos que vea en el chat. No usa el temporizador nativo de Telegram y no borra paneles fijados del bot.</i>"
    )


_old_service_cleanup_markup_v287 = service_cleanup_markup if 'service_cleanup_markup' in globals() else None
def service_cleanup_markup(chat_id: int) -> InlineKeyboardMarkup:
    try:
        old = _old_service_cleanup_markup_v287(chat_id) if callable(_old_service_cleanup_markup_v287) else InlineKeyboardMarkup([])
        rows = [list(r) for r in (getattr(old, 'inline_keyboard', None) or [])]
    except Exception:
        rows = []
    rows.append([
        InlineKeyboardButton(('✅ ' if _v287_autodel_seconds(chat_id) == 7200 else '') + '🕒 2h', callback_data=f'cfg|chat_autodel|{int(chat_id)}|7200|service_cleanup'),
        InlineKeyboardButton(('✅ ' if _v287_autodel_seconds(chat_id) == 21600 else '') + '6h', callback_data=f'cfg|chat_autodel|{int(chat_id)}|21600|service_cleanup'),
        InlineKeyboardButton(('✅ ' if _v287_autodel_seconds(chat_id) == 43200 else '') + '12h', callback_data=f'cfg|chat_autodel|{int(chat_id)}|43200|service_cleanup'),
    ])
    rows.append([
        InlineKeyboardButton(('✅ ' if _v287_autodel_seconds(chat_id) == 86400 else '') + '24h', callback_data=f'cfg|chat_autodel|{int(chat_id)}|86400|service_cleanup'),
        InlineKeyboardButton('❌ Autoelim OFF', callback_data=f'cfg|chat_autodel|{int(chat_id)}|0|service_cleanup'),
    ])
    return InlineKeyboardMarkup(rows)


_old_safe_delete_v287 = safe_delete if 'safe_delete' in globals() else None
async def safe_delete(bot, chat_id: int, message_id: Optional[int]) -> None:
    if message_id:
        try:
            if int(message_id) in _v287_panel_ids(int(chat_id)) and get_state(int(chat_id)).dj_mode:
                return
        except Exception:
            pass
    if callable(_old_safe_delete_v287):
        return await _old_safe_delete_v287(bot, int(chat_id), message_id)


_old_build_application_v287 = build_application
def build_application() -> Application:
    app = _old_build_application_v287()
    app.add_handler(CallbackQueryHandler(_v287_autodel_callback, pattern=r'^cfg\|chat_autodel\|'), group=-940000000000)
    app.add_handler(MessageHandler(filters.ALL, _v287_chat_autodelete_handler), group=940000000000)
    logger.info('V287 cargado: fluidez DJ, auto-next fácil rápido, anti-duplicados y autoeliminación de chat')
    return app


BOT_VERSION = "V288"

try:
    from telegram.ext import ApplicationHandlerStop as _V288Stop
except Exception:
    _V288Stop = Exception


def _v288_one_line(value: Any) -> str:
    """Normaliza a una sola línea visible en Telegram."""
    return " ".join(str(value if value is not None else "—").replace("\r", " ").replace("\n", " ").split())


def _v288_cut(value: Any, max_len: int) -> str:
    s = _v288_one_line(value)
    max_len = max(1, int(max_len or 1))
    if len(s) <= max_len:
        return s
    if max_len <= 1:
        return "…"
    return s[: max_len - 1] + "…"


def _v282_short_text(value: Any, max_len: int) -> str:
    """V288: nunca devuelve saltos de línea ni texto más largo que la celda."""
    return _v288_cut(value, max_len)


def _v282_cell(chat_id: int, state: ChatState, key: str, width: int, label_width: int, max_val: int) -> str:

    label = _v288_cut(_v282_label(key) if '_v282_label' in globals() else key.upper(), label_width).ljust(label_width)
    width = max(label_width + 4, int(width or 1))
    val_width = max(1, width - label_width - 2)
    if int(max_val or 0) > 0:
        val_width = min(val_width, int(max_val))
    try:
        value = _v270_value(int(chat_id), state, key) if '_v270_value' in globals() else '—'
    except Exception:
        value = '—'
    value = _v288_cut(value, val_width)

    return (f'{label}: {value}').ljust(width)[:width]


def _v270_dj_summary_text(chat_id: int, state: ChatState) -> str:
    cfg = _v270_dj_cfg(int(chat_id)) if '_v270_dj_cfg' in globals() else admin_cfg(int(chat_id))
    cols = _v275_summary_columns(int(chat_id)) if '_v275_summary_columns' in globals() else [[], []]
    try:
        max_val = int(cfg.get('dj_pro_summary_max_v270', 0) or 0)
    except Exception:
        max_val = 0


    w1 = int(cfg.get('dj_pro_summary_c1_width_v288', cfg.get('dj_pro_summary_c1_width_v282', 14)) or 14)
    w2 = int(cfg.get('dj_pro_summary_c2_width_v288', cfg.get('dj_pro_summary_c2_width_v282', 27)) or 27)
    w1 = max(10, min(16, w1))
    w2 = max(18, min(30, w2))


    total = w1 + 2 + w2
    if total > 44:
        overflow = total - 44
        w2 = max(18, w2 - overflow)
    if w1 + 2 + w2 > 44:
        w1 = max(10, 44 - 2 - w2)

    rows = max(len(cols[0]), len(cols[1])) if cols else 0
    lines: List[str] = []
    for i in range(rows):
        left = _v282_cell(int(chat_id), state, cols[0][i], w1, 5, max_val) if i < len(cols[0]) else ''.ljust(w1)
        right = _v282_cell(int(chat_id), state, cols[1][i], w2, 5, max_val) if i < len(cols[1]) else ''.ljust(w2)

        lines.append((left + '  ' + right)[:44].rstrip())

    return '<b>🎛️ CUADRO DE MANDOS DJ-PRO</b>\n<pre>' + h('\n'.join(lines) or '—') + '</pre>\n'


