async def _v288_manual_send_or_edit(q, text: str, markup: InlineKeyboardMarkup) -> None:
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        try:
            await q.message.reply_html(text, reply_markup=markup, disable_web_page_preview=True)
        except Exception:
            raise


async def v288_manual_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    if not is_global_admin_user(int(update.effective_user.id)):
        await update.message.reply_text('Solo ADMIN_IDS puede abrir el manual del bot.')
        return
    await update.message.reply_html(_v288_manual_main_text(), reply_markup=_v288_manual_main_markup(), disable_web_page_preview=True)


async def v288_manual_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('manual|'):
        return
    if not is_global_admin_user(int(update.effective_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V288Stop
    await q.answer()
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else 'open'
    if action == 'close':
        try:
            await q.message.delete()
        except Exception:
            await _v288_manual_send_or_edit(q, 'Manual cerrado.', InlineKeyboardMarkup([]))
        raise _V288Stop
    if action == 'commands':
        await _v288_manual_send_or_edit(q, _v288_commands_text(), _v288_manual_section_markup())
        raise _V288Stop
    if action == 'sec' and len(parts) >= 3:
        key = parts[2]
        title, body = V288_MANUAL_SECTIONS.get(key, ('📖 Manual', 'Sección no encontrada.'))
        await _v288_manual_send_or_edit(q, body, _v288_manual_section_markup())
        raise _V288Stop
    await _v288_manual_send_or_edit(q, _v288_manual_main_text(), _v288_manual_main_markup())
    raise _V288Stop


