async def _v290_manual_commands_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    if data not in ('manual|commands', 'manual|cmd_index') and not data.startswith('manual|cmd|'):
        return
    if not is_global_admin_user(int(update.effective_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V290Stop
    await q.answer()
    if data in ('manual|commands', 'manual|cmd_index'):
        await _v290_manual_edit(q, _v290_cmd_index_text(), _v290_cmd_index_markup())
        raise _V290Stop
    key = data.split('|', 2)[2] if data.count('|') >= 2 else 'main'
    await _v290_manual_edit(q, _v290_command_text(key), _v290_cmd_markup())
    raise _V290Stop


_old_build_application_v290_base = build_application

def build_application() -> Application:
    app = _old_build_application_v290_base()

    app.add_handler(CallbackQueryHandler(_v290_manual_commands_router, pattern=r'^(manual\|commands|manual\|cmd_index|manual\|cmd\|)'), group=-990000000000)
    logger.info('V290 cargado: botón Comandos del manual dividido en categorías y sin bloqueo por longitud')
    return app


