_V291_WEATHER_CODES = {
    0: 'despejado', 1: 'mayormente despejado', 2: 'parcialmente nuboso', 3: 'nuboso',
    45: 'niebla', 48: 'niebla con escarcha', 51: 'llovizna débil', 53: 'llovizna',
    55: 'llovizna intensa', 61: 'lluvia débil', 63: 'lluvia', 65: 'lluvia fuerte',
    71: 'nieve débil', 73: 'nieve', 75: 'nieve fuerte', 80: 'chubascos débiles',
    81: 'chubascos', 82: 'chubascos fuertes', 95: 'tormenta', 96: 'tormenta con granizo', 99: 'tormenta fuerte con granizo',
}


def _v291_now_in_tz(tz_name: str) -> str:
    try:
        if _V291ZoneInfo is None:
            raise RuntimeError('zoneinfo no disponible')
        now = _v291_datetime.datetime.now(_V291ZoneInfo(tz_name))
        return now.strftime('%H:%M:%S %Z')
    except Exception:
        return '--:--'


def _v291_hora_text() -> str:
    rows = [
        ('🇪🇸', 'España', 'Europe/Madrid'),
        ('🇦🇷', 'Argentina', 'America/Argentina/Buenos_Aires'),
        ('🇻🇪', 'Venezuela', 'America/Caracas'),
        ('🇨🇺', 'Cuba', 'America/Havana'),
        ('🇨🇱', 'Chile', 'America/Santiago'),
        ('🇺🇸', 'USA', 'America/New_York'),
        ('🇨🇳', 'China', 'Asia/Shanghai'),
    ]
    lines = ['🕒 <b>Hora actual</b>', '']
    for flag, name, tz in rows:
        lines.append(f'{flag} <b>{h(name)}</b>: <code>{h(_v291_now_in_tz(tz))}</code>')
    lines.append('')
    lines.append('<i>USA se muestra con horario de Nueva York / Costa Este.</i>')
    return '\n'.join(lines)


async def hora_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    await update.message.reply_html(_v291_hora_text())


def _v291_fetch_json(url: str, timeout: int = 12) -> Dict[str, Any]:
    req = _v291_urlrequest.Request(url, headers={'User-Agent': 'DJPLAN-Bot/1.0'})
    with _v291_urlrequest.urlopen(req, timeout=timeout) as r:
        return _v291_json.loads(r.read().decode('utf-8'))


async def _v291_fetch_json_async(url: str, timeout: int = 12) -> Dict[str, Any]:
    return await asyncio.to_thread(_v291_fetch_json, url, timeout)


async def _v291_geocode_city(city: str) -> Optional[Dict[str, Any]]:
    q = _v291_urlparse.urlencode({'name': city, 'count': 1, 'language': 'es', 'format': 'json'})
    data = await _v291_fetch_json_async('https://geocoding-api.open-meteo.com/v1/search?' + q)
    results = data.get('results') if isinstance(data, dict) else None
    if not results:
        return None
    return dict(results[0])


def _v291_weather_comment(temp: Optional[float], rain: int, humidity: Optional[int], code: int) -> str:
    try:
        t = float(temp) if temp is not None else None
    except Exception:
        t = None
    desc = _V291_WEATHER_CODES.get(int(code or 0), 'tiempo variable')
    if rain >= 55 or int(code or 0) in (61, 63, 65, 80, 81, 82, 95, 96, 99):
        return 'Lleva paraguas; hay probabilidad clara de lluvia.'
    if t is not None and t >= 28:
        return 'Va a calentar; agua y ropa ligera.'
    if t is not None and t <= 10:
        return 'Hace fresco; mejor salir abrigado.'
    if humidity is not None and int(humidity) >= 80:
        return 'Ambiente húmedo; puede sentirse más pesado.'
    return f'Día de {desc}; sin avisos fuertes ahora mismo.'


def _v291_air_label(pm25: Optional[float]) -> str:
    if pm25 is None:
        return 'sin dato'
    try:
        v = float(pm25)
    except Exception:
        return 'sin dato'
    if v <= 10:
        return 'buena'
    if v <= 25:
        return 'aceptable'
    if v <= 50:
        return 'regular'
    return 'mala'


async def _v291_weather_text(city: str) -> str:
    place = await _v291_geocode_city(city)
    if not place:
        return f'🌤 No encontré la ciudad <b>{h(city)}</b>. Prueba con ciudad y país, por ejemplo: <code>Oviedo España</code>.'
    lat = place.get('latitude'); lon = place.get('longitude')
    name = place.get('name') or city
    country = place.get('country') or ''
    timezone = place.get('timezone') or 'auto'
    params = {
        'latitude': lat,
        'longitude': lon,
        'timezone': timezone,
        'current': 'temperature_2m,relative_humidity_2m,weather_code',
        'hourly': 'temperature_2m,precipitation_probability,relative_humidity_2m,weather_code',
        'forecast_days': 1,
    }
    forecast_url = 'https://api.open-meteo.com/v1/forecast?' + _v291_urlparse.urlencode(params)
    air_url = 'https://air-quality-api.open-meteo.com/v1/air-quality?' + _v291_urlparse.urlencode({
        'latitude': lat,
        'longitude': lon,
        'timezone': timezone,
        'hourly': 'pm10,pm2_5',
        'forecast_days': 1,
    })
    forecast = await _v291_fetch_json_async(forecast_url)
    try:
        air = await _v291_fetch_json_async(air_url)
    except Exception:
        air = {}
    current = forecast.get('current') or {}
    hourly = forecast.get('hourly') or {}
    temp = current.get('temperature_2m')
    hum = current.get('relative_humidity_2m')
    code = int(current.get('weather_code') or 0)
    times = hourly.get('time') or []
    temps = hourly.get('temperature_2m') or []
    rains = hourly.get('precipitation_probability') or []
    hums = hourly.get('relative_humidity_2m') or []
    codes = hourly.get('weather_code') or []
    now_hour = str(current.get('time') or '')[:13]
    start_idx = 0
    for i, t0 in enumerate(times):
        if str(t0)[:13] >= now_hour:
            start_idx = i
            break
    next_lines = []
    max_rain = 0
    for i in range(start_idx, min(start_idx + 5, len(times))):
        hh = str(times[i])[11:16] if len(str(times[i])) >= 16 else str(times[i])
        tt = temps[i] if i < len(temps) else '--'
        rr = int(rains[i] or 0) if i < len(rains) and rains[i] is not None else 0
        max_rain = max(max_rain, rr)
        cc = int(codes[i] or 0) if i < len(codes) else 0
        next_lines.append(f'• <code>{h(hh)}</code> · <b>{h(tt)}°C</b> · lluvia <b>{rr}%</b> · {h(_V291_WEATHER_CODES.get(cc, "variable"))}')
    air_hourly = air.get('hourly') if isinstance(air, dict) else {}
    pm25 = None; pm10 = None
    try:
        pm25_list = air_hourly.get('pm2_5') or []
        pm10_list = air_hourly.get('pm10') or []
        pm25 = next((x for x in pm25_list if x is not None), None)
        pm10 = next((x for x in pm10_list if x is not None), None)
    except Exception:
        pass
    comment = _v291_weather_comment(temp, max_rain, hum, code)
    place_label = f'{name}, {country}'.strip(', ')
    lines = [
        f'🌤 <b>Tiempecito en {h(place_label)}</b>', '',
        f'Ahora: <b>{h(temp)}°C</b> · {h(_V291_WEATHER_CODES.get(code, "variable"))}',
        f'Humedad: <b>{h(hum)}%</b>',
        f'Lluvia próximas horas: <b>{max_rain}%</b>',
        f'Aire: <b>{h(_v291_air_label(pm25))}</b> · PM2.5: <b>{h(pm25 if pm25 is not None else "--")}</b> · PM10: <b>{h(pm10 if pm10 is not None else "--")}</b>',
        '', '<b>Próximas horas</b>',
    ]
    lines.extend(next_lines or ['Sin datos horarios disponibles.'])
    lines.extend(['', f'📝 <i>{h(comment)}</i>'])
    return '\n'.join(lines)


def _v291_pending_key(user_id: int, chat_id: int) -> str:
    return f'v291_weather:{int(chat_id)}:{int(user_id)}'


async def tiempecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    if not raw:
        PENDING_ACTIONS[_v291_pending_key(update.effective_user.id, chat_id)] = {'kind': 'v291_weather_city', 'chat_id': chat_id, 'user_id': int(update.effective_user.id)}
        await update.message.reply_html('🌤 ¿De qué ciudad quieres el tiempecito?')
        return
    msg = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(raw)
        await msg.edit_text(text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        logger.exception('V291 error consultando tiempo')
        await msg.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')


async def _v291_weather_pending_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message or not update.message.text:
        return
    key = _v291_pending_key(update.effective_user.id, update.effective_chat.id)
    pending = PENDING_ACTIONS.get(key)
    if not pending or pending.get('kind') != 'v291_weather_city':
        return
    city = update.message.text.strip()
    PENDING_ACTIONS.pop(key, None)
    msg = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(city)
        await msg.edit_text(text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        logger.exception('V291 error consultando tiempo pendiente')
        await msg.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')
    raise _V291Stop


def _v291_parse_phrase_extra_buttons(raw: str) -> List[Dict[str, str]]:
    buttons: List[Dict[str, str]] = []
    for line in str(raw or '').splitlines():
        line = line.strip()
        if not line:
            continue
        if ' - ' in line:
            label, target = line.split(' - ', 1)
        elif '=' in line:
            label, target = line.split('=', 1)
        elif '|' in line:
            label, target = line.split('|', 1)
        else:
            continue
        label = label.strip()[:64]
        target = target.strip()[:500]
        if not label or not target:
            continue
        low = target.lower()
        if low.startswith('cmd:') or low.startswith('command:') or target.startswith('/'):
            cmd = target.split(':', 1)[1] if ':' in target and not target.startswith('/') else target
            cmd = cmd.strip().lstrip('/').split()[0].lower()
            if cmd:
                buttons.append({'text': label, 'cmd': cmd})
            continue
        if target.startswith('t.me/'):
            target = 'https://' + target
        if target.startswith(('http://', 'https://', 'tg://')):
            buttons.append({'text': label, 'url': target})
    return buttons[:10]


def _v237_daily_phrase_extra_buttons(chat_id: int) -> List[List[InlineKeyboardButton]]:
    out: List[List[InlineKeyboardButton]] = []
    raw = cfg_value(int(chat_id), 'daily_phrase_extra_buttons', [])
    if isinstance(raw, list):
        for btn in raw[:10]:
            if not isinstance(btn, dict):
                continue
            text = str(btn.get('text','')).strip()[:64]
            if not text:
                continue
            cmd = str(btn.get('cmd','')).strip().lower().lstrip('/')
            url = str(btn.get('url','')).strip()
            target = str(btn.get('target','')).strip()
            if not cmd and target.lower().startswith('cmd:'):
                cmd = target.split(':', 1)[1].strip().lower().lstrip('/')
            if cmd:
                out.append([InlineKeyboardButton(text, callback_data=f'reccmd|{int(chat_id)}|{cmd}')])
            elif url and url.startswith(('http://', 'https://', 'tg://')):
                out.append([InlineKeyboardButton(text, url=url)])
    return out


async def _v291_phrase_buttons_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_buttons|'):
        return
    parts = (q.data or '').split('|')
    chat_id = int(parts[2])
    set_config_pending(q.from_user.id, {'kind':'cfg_phrase_buttons_v291', 'chat_id': chat_id, 'return_block':'daily_phrase'})
    await q.answer()
    await q.edit_message_text(
        '⌨️ <b>Botones extra de Frase del día</b>\n\n'
        'Se mantienen <b>Vitamina IA</b> y <b>Me gusta</b> en la primera fila.\n'
        'Los botones que añadas aquí salen debajo, <b>uno por fila</b>.\n\n'
        'Envíame los botones, uno por línea:\n'
        '<code>Instagram - https://instagram.com/...</code>\n'
        '<code>Normas - https://t.me/...</code>\n'
        '<code>Hora=cmd:hora</code>\n'
        '<code>Tiempo=cmd:tiempo</code>\n\n'
        'Para quitar todos escribe <code>QUITAR</code>.',
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
    )
    raise _V291Stop


async def _v291_phrase_buttons_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not pending or str(pending.get('kind','')) != 'cfg_phrase_buttons_v291':
        return
    chat_id = int(pending.get('chat_id') or 0)
    text = (update.message.text or update.message.caption or '').strip()
    if text.upper() in ('QUITAR','BORRAR','SIN BOTONES','NO'):
        cfg_set(chat_id, 'daily_phrase_extra_buttons', [])
    else:
        buttons = _v291_parse_phrase_extra_buttons(text)
        if not buttons:
            await update.message.reply_html('❌ No he detectado botones. Usa <code>Texto - https://enlace.com</code> o <code>Texto=cmd:comando</code>.')
            raise _V291Stop
        cfg_set(chat_id, 'daily_phrase_extra_buttons', buttons)
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html('✅ Botones extra actualizados.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
    raise _V291Stop


async def _v291_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').replace('command:', '').strip()
    if cmd not in ('hora', 'horas', 'tiempo', 'tiempecito'):
        return
    await q.answer()
    if cmd in ('hora', 'horas'):
        await q.message.reply_html(_v291_hora_text())
        raise _V291Stop
    user_id = int(update.effective_user.id) if update.effective_user else 0
    if user_id:
        PENDING_ACTIONS[_v291_pending_key(user_id, chat_id)] = {'kind': 'v291_weather_city', 'chat_id': chat_id, 'user_id': user_id}
    await q.message.reply_html('🌤 ¿De qué ciudad quieres el tiempecito?')
    raise _V291Stop


_old_build_application_v290_base_v291 = build_application

def build_application() -> Application:
    app = _old_build_application_v290_base_v291()
    app.add_handler(command_handler(('hora', 'horas'), hora_command), group=-39100000000)
    app.add_handler(command_handler(('tiempo', 'tiempecito'), tiempecito_command), group=-39100000000)
    app.add_handler(CallbackQueryHandler(_v291_reccmd_router, pattern=r'^reccmd\|'), group=-39100000000)
    app.add_handler(CallbackQueryHandler(_v291_phrase_buttons_router, pattern=r'^cfg\|phrase_buttons\|'), group=-39100000000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v291_weather_pending_router), group=-39100000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v291_phrase_buttons_text_router), group=-39100000000)
    logger.info('V305 cargado: base V290 con DJ clásico, /hora, /tiempecito y botones extra en frase diaria')
    return app


try:
    from telegram.ext import ApplicationHandlerStop as _V306Stop
except Exception:
    _V306Stop = Exception

V306_DJ_AUTO_TASK = None
V306_AUTO_RUNTIME: Dict[int, Dict[str, Any]] = {}

async def _v306_voice_ready(application: Optional[Application] = None) -> None:
    try:
        if hasattr(VOICE, 'ensure_ready') and callable(getattr(VOICE, 'ensure_ready')):
            await VOICE.ensure_ready(application or getattr(VOICE, 'application', None))
            return
    except Exception:
        logger.exception('V306 ensure_ready falló')
        raise
    if not getattr(VOICE, 'application', None) and application is not None:
        try:
            await VOICE.start(application)
        except Exception:
            logger.exception('V306 no pudo iniciar VOICE.start')
            raise


def _v306_state_is_dj_easy(state: ChatState) -> bool:
    try:
        if str(getattr(state, 'dj_ui_mode', '') or '').lower() in ('easy', 'facil', 'fácil'):
            return True
        cfg = getattr(state, 'admin_config', {}) if isinstance(getattr(state, 'admin_config', {}), dict) else {}
        return str(cfg.get('dj_ui_mode', '') or '').lower() in ('easy', 'facil', 'fácil')
    except Exception:
        return False


async def _v306_play_next(application: Application, chat_id: int, *, reason: str = 'v306_auto') -> bool:
    """Ruta directa y única para pasar canción.

    - Saca una canción real de la cola.
    - Guarda la anterior en historial.
    - Activa LIVE.
    - Llama a VOICE.play_track, que actualiza now_playing y reproduce.
    """
    chat_id = int(chat_id)
    state = get_state(chat_id)
    if not state.queue:
        logger.info('V306 auto-next sin cola chat=%s reason=%s', chat_id, reason)
        return False
    try:
        await _v306_voice_ready(application)
        state.live_enabled = True
        state.paused = False

        if getattr(state, 'dj_shuffle_enabled', False) and len(state.queue) > 1:
            next_data = state.queue.pop(secrets.randbelow(len(state.queue)))
        else:
            next_data = state.queue.pop(0)

        if state.now_playing:
            try:
                if track_key(state.now_playing) != track_key(next_data):
                    state.history.append(dict(state.now_playing))
                    state.history = state.history[-50:]
            except Exception:
                pass

        save_all_states()
        logger.info('V306 pasando canción chat=%s reason=%s title=%r cola_restante=%s', chat_id, reason, next_data.get('title'), len(state.queue))
        await VOICE.play_track(application.bot, chat_id, Track(**next_data))

        return True
    except Exception:
        logger.exception('V306 error al pasar canción chat=%s reason=%s', chat_id, reason)
        try:

            if 'next_data' in locals() and isinstance(next_data, dict):
                st = get_state(chat_id)
                if not any(track_key(x) == track_key(next_data) for x in st.queue[:3]):
                    st.queue.insert(0, next_data)
                    save_all_states()
        except Exception:
            pass
        return False


async def _v306_auto_loop() -> None:
    import time as _time
    while True:
        try:
            await asyncio.sleep(2)
            application = getattr(VOICE, 'application', None)
            if application is None:
                continue
            now_ts = _time.time()

            for chat_id, state in list(STATE_CACHE.items()):
                chat_id = int(chat_id)
                if not getattr(state, 'dj_mode', False):
                    V306_AUTO_RUNTIME.pop(chat_id, None)
                    continue
                if not getattr(state, 'auto_track_enabled', False):

                    continue

                rt = V306_AUTO_RUNTIME.setdefault(chat_id, {'last_advance_at': 0.0, 'token': None, 'last_log': 0.0})
                if now_ts - float(rt.get('last_advance_at', 0.0) or 0.0) < 3:
                    continue


                if not state.now_playing and state.queue:
                    rt['last_advance_at'] = now_ts
                    await _v306_play_next(application, chat_id, reason='auto_idle_no_now_playing')
                    continue


                if state.now_playing and not state.live_enabled:
                    state.live_enabled = True
                    state.paused = False
                    save_all_states()

                if not state.now_playing or not state.queue:
                    continue

                token = track_key(state.now_playing)
                if rt.get('token') != token:
                    rt['token'] = token

                trigger = 0 if int(getattr(state, 'auto_sig_seconds', -1) or -1) < 0 else int(getattr(state, 'auto_sig_seconds', 0) or 0)
                remaining = remaining_seconds(state)

                should_advance = False
                if remaining is not None:
                    should_advance = remaining <= trigger
                else:

                    try:
                        track = Track(**state.now_playing)
                        elapsed = int(now_ts - int(state.play_started_at or now_ts))
                        if int(track.duration or 0) > 0:
                            should_advance = elapsed >= max(0, int(track.duration) - trigger)
                        else:

                            should_advance = elapsed >= max(180, int(UNKNOWN_END_FALLBACK_SECONDS or 20))
                    except Exception:
                        should_advance = False

                if should_advance:
                    rt['last_advance_at'] = now_ts
                    await _v306_play_next(application, chat_id, reason='auto_end_reached')
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V306 error en auto-loop DJ')


async def _v306_start_auto_loop() -> None:
    global V306_DJ_AUTO_TASK
    if V306_DJ_AUTO_TASK is None or V306_DJ_AUTO_TASK.done():
        V306_DJ_AUTO_TASK = asyncio.create_task(_v306_auto_loop())
        logger.info('V306 auto-loop DJ arrancado')


async def _v306_dj_button_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_auto_track', 'panel_next', 'panel_live_toggle', 'panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await q.answer('Solo DJ/admin.', show_alert=True)
        raise _V306Stop
    state = get_state(chat_id)
    await _v306_start_auto_loop()

    try:
        if data == 'panel_auto_track':
            state.auto_track_enabled = not bool(state.auto_track_enabled)
            if state.auto_track_enabled:
                state.auto_sig_seconds = 0
            save_all_states()
            await q.answer('AUTO ON ✅' if state.auto_track_enabled else 'AUTO OFF')

            if state.auto_track_enabled and state.queue and not state.now_playing:
                await _v306_play_next(context.application, chat_id, reason='auto_button_idle')
            else:
                await ensure_panel(context.bot, chat_id)
                await ensure_control_panel(context.bot, chat_id)
            raise _V306Stop

        if data == 'panel_next':
            if not state.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
                raise _V306Stop
            await q.answer('Siguiente…')
            await _v306_play_next(context.application, chat_id, reason='button_next')
            raise _V306Stop

        if data in {'panel_live_toggle', 'panel_pause_resume'}:

            if state.live_enabled and not state.now_playing and state.queue:
                await q.answer('Recuperando sonido…')
                await _v306_play_next(context.application, chat_id, reason='live_recover_idle')
                raise _V306Stop

            if not state.live_enabled and state.queue:
                await q.answer('LIVE ON y sonando…')
                await _v306_play_next(context.application, chat_id, reason='live_on_start')
                raise _V306Stop

            return
    except _V306Stop:
        raise
    except Exception as e:
        logger.exception('V306 error botón DJ %s', data)
        try:
            await q.answer('Error DJ: ' + str(e)[:80], show_alert=True)
        except Exception:
            pass
        raise _V306Stop


async def djauto_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo administradores.')
        return
    st = get_state(chat_id)
    await _v306_start_auto_loop()
    lines = [
        '<b>🧪 DJ AUTO V306</b>',
        f'DJ mode: <b>{bool_label(st.dj_mode)}</b>',
        f'LIVE: <b>{bool_label(st.live_enabled)}</b>',
        f'AUTO: <b>{bool_label(st.auto_track_enabled)}</b>',
        f'Sonando: <b>{h((st.now_playing or {}).get("title") or "Nada")}</b>',
        f'Cola: <b>{len(st.queue)}</b>',
        f'Loop V306: <b>{"ON" if V306_DJ_AUTO_TASK and not V306_DJ_AUTO_TASK.done() else "OFF"}</b>',
    ]
    if st.auto_track_enabled and st.queue and not st.now_playing:
        ok = await _v306_play_next(context.application, chat_id, reason='djauto_command_idle')
        lines.append('Acción: <b>arranque forzado ejecutado</b> ' + ('✅' if ok else '❌'))
    await update.message.reply_html('\n'.join(lines))


