async def _v307_refresh_dj_panels(bot, chat_id: int) -> None:
    try:
        await ensure_panel(bot, chat_id)
    except Exception:
        logger.exception('V307 no pudo refrescar panel fijado DJ chat=%s', chat_id)
    try:
        await ensure_control_panel(bot, chat_id)
    except Exception:
        logger.exception('V307 no pudo refrescar mesa DJ chat=%s', chat_id)


async def _v307_turn_live_off(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    state = get_state(chat_id)
    try:
        if state.now_playing:
            current = dict(state.now_playing)
            current_key = track_key(current)
            first_key = track_key(state.queue[0]) if state.queue else ''
            if not state.queue or current_key != first_key:
                state.queue.insert(0, current)
    except Exception:
        pass
    state.live_enabled = False
    state.now_playing = None
    state.paused = False
    state.play_started_at = None
    state.paused_remaining = None
    save_all_states()
    try:
        await cancel_auto_next(chat_id)
    except Exception:
        pass
    try:
        await VOICE.leave(chat_id, end_videochat=True)
    except Exception:
        logger.exception('V307 no pudo cerrar/salir del voice chat=%s', chat_id)
    await _v307_refresh_dj_panels(context.bot, chat_id)


async def _v307_turn_live_on(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, force_next: bool = True) -> bool:
    state = get_state(chat_id)
    await _v306_start_auto_loop()
    await _v306_voice_ready(context.application)
    state.dj_mode = True
    state.live_enabled = True
    state.paused = False
    save_all_states()


    if force_next and state.queue:
        return await _v306_play_next(context.application, chat_id, reason='v307_live_on_start')


    if state.now_playing:
        try:
            await VOICE.play_track(context.bot, chat_id, Track(**state.now_playing))
            return True
        except Exception:
            logger.exception('V307 no pudo relanzar now_playing en LIVE ON chat=%s', chat_id)

    await _v307_refresh_dj_panels(context.bot, chat_id)
    return False


async def _v307_dj_button_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_live_toggle', 'panel_pause_resume', 'panel_auto_track', 'panel_next'}:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await q.answer('Solo DJ/admin.', show_alert=True)
        raise _V307Stop
    state = get_state(chat_id)
    await _v306_start_auto_loop()

    try:
        if data in {'panel_live_toggle', 'panel_pause_resume'}:

            if state.live_enabled:
                await q.answer('Cerrando directo…')
                await _v307_turn_live_off(context, chat_id)
                try:
                    await q.answer('LIVE OFF ✅')
                except Exception:
                    pass
                raise _V307Stop


            if state.queue:
                await q.answer('LIVE ON · reproduciendo…')
                ok = await _v307_turn_live_on(context, chat_id, force_next=True)
                if not ok:
                    await q.answer('LIVE ON, pero no pude lanzar la canción. Revisa /djauto.', show_alert=True)
                raise _V307Stop


            await q.answer('LIVE ON · sin cola')
            await _v307_turn_live_on(context, chat_id, force_next=False)
            try:
                await q.answer('LIVE ON ✅ Añade canciones a la cola.')
            except Exception:
                pass
            raise _V307Stop

        if data == 'panel_auto_track':
            state.auto_track_enabled = not bool(state.auto_track_enabled)
            if state.auto_track_enabled:
                state.auto_sig_seconds = 0
            save_all_states()
            await q.answer('AUTO ON ✅' if state.auto_track_enabled else 'AUTO OFF')

            if state.auto_track_enabled and state.live_enabled and state.queue and not state.now_playing:
                await _v306_play_next(context.application, chat_id, reason='v307_auto_on_idle')
            else:
                await _v307_refresh_dj_panels(context.bot, chat_id)
            raise _V307Stop

        if data == 'panel_next':
            if not state.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
                raise _V307Stop
            await q.answer('Siguiente…')
            await _v306_play_next(context.application, chat_id, reason='v307_button_next')
            raise _V307Stop

    except _V307Stop:
        raise
    except Exception as e:
        logger.exception('V307 error botón DJ %s', data)
        try:
            await q.answer('Error DJ: ' + str(e)[:80], show_alert=True)
        except Exception:
            pass
        raise _V307Stop


async def _v307_auto_loop() -> None:
    """Capa extra mínima: si AUTO ON + LIVE ON + cola + sin sonando, arranca.

    No sustituye a V306; solo corrige el estado que el usuario está viendo.
    """
    import time as _time
    last: Dict[int, float] = {}
    while True:
        try:
            await asyncio.sleep(2)
            app = getattr(VOICE, 'application', None)
            if not app:
                continue
            now = _time.time()
            for chat_id, st in list(STATE_CACHE.items()):
                chat_id = int(chat_id)
                if not getattr(st, 'dj_mode', False):
                    continue
                if not getattr(st, 'live_enabled', False):
                    continue
                if not getattr(st, 'auto_track_enabled', False):
                    continue
                if st.now_playing or not st.queue:
                    continue
                if now - float(last.get(chat_id, 0.0)) < 4:
                    continue
                last[chat_id] = now
                logger.info('V307 AUTO recupera LIVE ON sin sonando chat=%s cola=%s', chat_id, len(st.queue))
                await _v306_play_next(app, chat_id, reason='v307_auto_idle_live_on')
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V307 error en auto-loop extra')


