async def _v308_live_on(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> bool:
    state = get_state(chat_id)
    await _v306_start_auto_loop()
    voice_ok = await _v308_ensure_voice(context, chat_id)

    state.dj_mode = True
    state.live_enabled = True
    state.paused = False
    state.paused_remaining = None
    save_all_states()


    if not state.now_playing and state.queue:
        ok = await _v306_play_next(context.application, chat_id, reason='v308_live_on_queue_start')
        if not ok:
            await _v308_refresh(context.bot, chat_id)
        return ok and voice_ok


    if state.now_playing:
        try:
            await VOICE.play_track(context.bot, chat_id, Track(**state.now_playing))
            await _v308_refresh(context.bot, chat_id)
            return True and voice_ok
        except Exception:
            logger.exception('V308 no pudo relanzar now_playing en LIVE ON chat=%s', chat_id)

            if state.queue:
                ok = await _v306_play_next(context.application, chat_id, reason='v308_live_on_fallback_next')
                return ok and voice_ok


    await _v308_refresh(context.bot, chat_id)
    return voice_ok


async def _v308_live_off(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    state = get_state(chat_id)

    try:
        if state.now_playing:
            current = dict(state.now_playing)
            current_key = track_key(current)
            first_key = track_key(state.queue[0]) if state.queue else ''
            if not state.queue or current_key != first_key:
                state.queue.insert(0, current)
    except Exception:
        pass

    state.live_enabled = False
    state.now_playing = None
    state.paused = False
    state.play_started_at = None
    state.paused_remaining = None
    save_all_states()

    try:
        await cancel_auto_next(chat_id)
    except Exception:
        pass
    try:


        await VOICE.leave(chat_id, end_videochat=True)
    except Exception:
        logger.exception('V308 no pudo cerrar/salir del voice chat=%s', chat_id)

    await _v308_refresh(context.bot, chat_id)


async def _v308_next(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> bool:
    state = get_state(chat_id)
    if not state.queue:
        await _v308_refresh(context.bot, chat_id)
        return False
    await _v308_ensure_voice(context, chat_id)
    state.dj_mode = True
    state.live_enabled = True
