async def _v308_dj_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_live_toggle', 'panel_pause_resume', 'panel_next', 'panel_auto_track', 'panel_refresh', 'panel_join_live'}:
        return

    chat_id = int(update.effective_chat.id)
    if not await is_controller(context, chat_id, int(update.effective_user.id)):
        await _v308_safe_answer(q, 'Solo DJ/admin.', show_alert=True)
        raise _V308Stop

    state = get_state(chat_id)
    await _v306_start_auto_loop()

    try:
        if data in {'panel_live_toggle', 'panel_pause_resume'}:
            if state.live_enabled:
                await _v308_safe_answer(q, 'Apagando directo…')
                await _v308_live_off(context, chat_id)
                raise _V308Stop

            await _v308_safe_answer(q, 'Encendiendo directo…')
            ok = await _v308_live_on(context, chat_id)
            if not ok and not get_state(chat_id).queue and not get_state(chat_id).now_playing:
                await _v308_safe_answer(q, 'LIVE ON. No hay canciones en cola.', show_alert=False)
            raise _V308Stop

        if data == 'panel_next':
            if not state.queue:
                await _v308_safe_answer(q, 'No hay canciones en cola.', show_alert=True)
                raise _V308Stop
            await _v308_safe_answer(q, 'Siguiente…')
            await _v308_next(context, chat_id)
            raise _V308Stop

        if data == 'panel_auto_track':
            state.auto_track_enabled = not bool(state.auto_track_enabled)
            if state.auto_track_enabled:
                state.auto_sig_seconds = 0
            save_all_states()
            await _v308_safe_answer(q, 'AUTO ON ✅' if state.auto_track_enabled else 'AUTO OFF')

            if state.auto_track_enabled and state.live_enabled and state.queue and not state.now_playing:
                await _v308_next(context, chat_id)
            else:
                await _v308_refresh(context.bot, chat_id)
            raise _V308Stop

        if data == 'panel_refresh':
            await _v308_safe_answer(q, 'Actualizando…')

            if state.live_enabled and state.auto_track_enabled and state.queue and not state.now_playing:
                await _v308_next(context, chat_id)
            else:
                await _v308_refresh(context.bot, chat_id)
            raise _V308Stop

        if data == 'panel_join_live':
            url = await _v308_join_live(context, chat_id)
            await _v308_refresh(context.bot, chat_id)
            if url:


                await _v308_safe_answer(q, 'Directo preparado. Abre el videochat desde el grupo.', show_alert=True)
            else:
                await _v308_safe_answer(q, 'Directo preparado. Pulsa el nombre del grupo y abre el videochat.', show_alert=True)
            raise _V308Stop

    except _V308Stop:
        raise
    except Exception as e:
        logger.exception('V308 error router DJ data=%s chat=%s', data, chat_id)
        await _v308_safe_answer(q, 'Error DJ: ' + str(e)[:90], show_alert=True)
        try:
            await _v308_refresh(context.bot, chat_id)
        except Exception:
            pass
        raise _V308Stop


async def _v308_watchdog() -> None:
    """Refuerzo mínimo para estado colgado: LIVE ON + AUTO ON + cola + nada sonando."""
    import time as _time
    last: Dict[int, float] = {}
    while True:
        try:
            await asyncio.sleep(2)
            app = getattr(VOICE, 'application', None)
            if not app:
                continue
            now = _time.time()
            for chat_id, st in list(STATE_CACHE.items()):
                chat_id = int(chat_id)
                if not getattr(st, 'dj_mode', False):
                    continue
                if not getattr(st, 'live_enabled', False):
                    continue
                if not getattr(st, 'auto_track_enabled', False):
                    continue
                if st.now_playing or not st.queue:
                    continue
                if now - float(last.get(chat_id, 0.0)) < 4:
                    continue
                last[chat_id] = now
                logger.info('V308 watchdog arranca cola: chat=%s cola=%s', chat_id, len(st.queue))
                await _v306_play_next(app, chat_id, reason='v308_watchdog_idle')
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V308 watchdog error')


