BOT_VERSION = "V309"
try:
    from telegram.ext import ApplicationHandlerStop as _V309Stop
except Exception:
    class _V309Stop(Exception):
        pass

import time as _v309_time
import secrets as _v309_secrets

V309_CLEANUP_SETS: Dict[str, Dict[str, Any]] = {}
V309_CLEANUP_SECONDS_OPTIONS = [0, 60, 120, 300, 600]


def _v309_cmd_cleanup_seconds(chat_id: int) -> int:
    try:
        return max(0, int(cfg_value(int(chat_id), 'cmd_result_cleanup_seconds_v309', 120) or 0))
    except Exception:
        return 120


def _v309_cleanup_label(seconds: int) -> str:
    seconds = int(seconds or 0)
    if seconds <= 0:
        return 'OFF'
    if seconds < 60:
        return f'{seconds}s'
    if seconds % 60 == 0:
        return f'{seconds//60}min'
    return f'{seconds}s'


def _v309_next_cleanup_seconds(current: int) -> int:
    opts = list(V309_CLEANUP_SECONDS_OPTIONS)
    try:
        idx = opts.index(int(current or 0))
    except Exception:
        idx = 1
    return opts[(idx + 1) % len(opts)]


async def _v309_delete_ids(bot, chat_id: int, ids: List[int]) -> None:
    for mid in list(dict.fromkeys(int(x) for x in ids if x)):
        try:
            await safe_delete(bot, int(chat_id), int(mid))
        except Exception:
            pass


async def _v309_auto_cleanup(bot, token: str, delay: int) -> None:
    try:
        await asyncio.sleep(max(1, int(delay)))
        item = V309_CLEANUP_SETS.pop(str(token), None)
        if not item:
            return
        await _v309_delete_ids(bot, int(item.get('chat_id')), list(item.get('ids') or []))
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('V309 auto cleanup error token=%s', token)


def _v309_close_markup(token: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cerrar', callback_data=f'utilclose|{token}')]])


async def _v309_send_cleanable(bot, chat_id: int, text: str, *, ids: Optional[List[int]]=None, ttl: Optional[int]=None) -> Any:
    token = _v309_secrets.token_urlsafe(8)
    msg = await bot.send_message(
        chat_id=int(chat_id),
        text=text,
        parse_mode=ParseMode.HTML,
        reply_markup=_v309_close_markup(token),
        disable_web_page_preview=True,
    )
    all_ids = list(ids or []) + [int(msg.message_id)]
    V309_CLEANUP_SETS[token] = {'chat_id': int(chat_id), 'ids': all_ids, 'created': int(_v309_time.time())}
    seconds = _v309_cmd_cleanup_seconds(int(chat_id)) if ttl is None else int(ttl or 0)
    if seconds > 0:
        asyncio.create_task(_v309_auto_cleanup(bot, token, seconds))
    return msg


async def _v309_close_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('utilclose|'):
        return
    token = (q.data or '').split('|', 1)[1]
    item = V309_CLEANUP_SETS.pop(token, None)
    await q.answer('Cerrado')
    if item:
        await _v309_delete_ids(context.bot, int(item.get('chat_id')), list(item.get('ids') or []))
    else:
        try:
            await q.message.delete()
        except Exception:
            pass
    raise _V309Stop


async def hora_command_v309(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    ids = [int(update.message.message_id)]
    await _v309_send_cleanable(context.bot, int(update.effective_chat.id), _v291_hora_text(), ids=ids)
    raise _V309Stop


async def tiempecito_command_v309(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
