        [InlineKeyboardButton('📂Listas', callback_data=f'djpropriv|{chat_id}|lists'), InlineKeyboardButton('💾Guardar cola', callback_data=f'djpropriv|{chat_id}|savequeue'), InlineKeyboardButton('🔄Mesa', callback_data=f'djpropriv|{chat_id}|refresh')],
