async def _v309_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'
    if action == 'close':
        await q.answer('Cerrado')
        try:
            await q.message.delete()
        except Exception:
            pass
        raise _V309Stop
    if action == 'groups' or not chat_id:
        await q.answer('Elige grupo')
        await q.edit_message_text('🎛 <b>Elige grupo para DJPRO privado</b>', parse_mode=ParseMode.HTML, reply_markup=_v309_djpro_groups_markup(int(q.from_user.id)))
        raise _V309Stop
    if not await is_admin(context, chat_id, int(q.from_user.id)):
        await q.answer('Solo administradores del grupo.', show_alert=True)
        raise _V309Stop
    st = get_state(chat_id)
    try:
        if action == 'home':
            await q.answer('DJPRO')
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'live':
            await q.answer('LIVE')
            if st.live_enabled:
                if '_v308_live_off' in globals():
                    await _v308_live_off(context, chat_id)
                else:
                    await VOICE.toggle_live(chat_id)
            else:
                st.dj_mode = True
                save_all_states()
                if '_v308_live_on' in globals():
                    await _v308_live_on(context, chat_id)
                else:
                    await VOICE.toggle_live(chat_id)
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'next':
            await q.answer('Siguiente')
            if '_v308_next' in globals():
                await _v308_next(context, chat_id)
            else:
                await VOICE.play_next_from_queue(chat_id)
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'auto':
            st.auto_track_enabled = not bool(st.auto_track_enabled)
            if st.auto_track_enabled:
                st.auto_sig_seconds = 0
            save_all_states()
            if st.auto_track_enabled and st.live_enabled and st.queue and not st.now_playing:
                if '_v308_next' in globals():
                    await _v308_next(context, chat_id)
            await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'shuffle':
            st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
            save_all_states(); await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
            await _v308_refresh(context.bot, chat_id) if '_v308_refresh' in globals() else None
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'refresh':
            await q.answer('Actualizado')
            await _v308_refresh(context.bot, chat_id) if '_v308_refresh' in globals() else None
            await _v309_show_djpro_private(q, context, chat_id)
            raise _V309Stop
        if action == 'queue':
            lines = ['📋 <b>Cola actual</b>', '']
            if not st.queue:
                lines.append('Vacía.')
            else:
                for i, item in enumerate(st.queue[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 50))}')
            await q.answer('Cola')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
            raise _V309Stop
        if action == 'library':
            lines = ['📚 <b>Biblioteca</b>', '']
            if not st.library:
                lines.append('Vacía. Puedes mandar audios por privado con /djconfig abierto para añadirlos.')
            else:
                for i, item in enumerate(st.library[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 50))}')
            await q.answer('Biblioteca')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=dj_private_library_markup(chat_id) if 'dj_private_library_markup' in globals() else InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
            raise _V309Stop
        if action == 'lists':
            lines = ['📂 <b>Listas guardadas</b>', '']
            names = sorted(st.saved_lists.keys())[:30]
            if not names:
                lines.append('No hay listas guardadas.')
            else:
                for i, name in enumerate(names, 1):
                    lines.append(f'{i}. {h(name)} ({len(st.saved_lists.get(name, []))})')
            await q.answer('Listas')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=dj_private_lists_markup(chat_id) if 'dj_private_lists_markup' in globals() else InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
            raise _V309Stop
        if action == 'savequeue':
            if not st.queue:
                await q.answer('La cola está vacía.', show_alert=True)
                raise _V309Stop
            set_config_pending(int(q.from_user.id), {'kind': 'djpriv_savequeue_name', 'chat_id': chat_id})
            await q.message.reply_html('💾 Envíame el nombre de la lista que quieres guardar.')
            await q.answer('Envíame el nombre')
            raise _V309Stop
    except _V309Stop:
        raise
    except Exception as e:
        logger.exception('V309 DJPRO privado error action=%s chat=%s', action, chat_id)
        await q.answer('Error DJPRO: ' + str(e)[:80], show_alert=True)
        raise _V309Stop
    await q.answer('Acción no válida', show_alert=True)
    raise _V309Stop


