_old_v267_send_block_v309 = _v267_send_block
async def _v267_send_block(context: ContextTypes.DEFAULT_TYPE, chat_id: int, block_or_bid: Any) -> tuple[int, int, List[str]]:
    block = block_or_bid if isinstance(block_or_bid, dict) else (_v267_find_block(int(chat_id), int(block_or_bid)) if '_v267_find_block' in globals() else None)
    if isinstance(block, dict) and bool(block.get('delete_previous_block_messages_v309', False)):
        old_ids = [int(x) for x in (block.get('last_block_message_ids_v309') or []) if str(x).isdigit()]
        if old_ids:
            await _v309_delete_ids(context.bot, int(chat_id), old_ids)
            block['last_block_message_ids_v309'] = []
            save_all_states()
    before: Dict[int, int] = {}
    if isinstance(block, dict):
        for rid in _v267_extract_rids(block):
            row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
            if row:
                try:
                    before[int(rid)] = int(row.get('last_message_id') or 0)
                except Exception:
                    before[int(rid)] = 0
    ok, total, errors = await _old_v267_send_block_v309(context, int(chat_id), block_or_bid)
    if isinstance(block, dict) and bool(block.get('delete_previous_block_messages_v309', False)):
        new_ids: List[int] = []
        for rid in _v267_extract_rids(block):
            row = recurring_find(int(chat_id), int(rid)) if 'recurring_find' in globals() else None
            if row:
                try:
                    mid = int(row.get('last_message_id') or 0)
                    if mid and mid != before.get(int(rid), 0):
                        new_ids.append(mid)
                except Exception:
                    pass
        block['last_block_message_ids_v309'] = list(dict.fromkeys(new_ids))
        save_all_states()
    return ok, total, errors


