_old_build_application_v308_for_v309 = build_application

def build_application() -> Application:
    app = _old_build_application_v308_for_v309()

    app.add_handler(CommandHandler(('hora', 'horas'), hora_command_v309), group=-1000000000100)
    app.add_handler(CommandHandler(('tiempo', 'tiempecito'), tiempecito_command_v309), group=-1000000000100)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v309_weather_pending_router), group=-1000000000100)
    app.add_handler(CallbackQueryHandler(_v309_close_router, pattern=r'^utilclose\|'), group=-1000000000100)
    app.add_handler(CallbackQueryHandler(_v309_reccmd_router, pattern=r'^reccmd\|'), group=-1000000000100)
    app.add_handler(CallbackQueryHandler(_v309_cmd_cleanup_cfg_router, pattern=r'^cfg\|cmdres_clean\|'), group=-1000000000100)
    app.add_handler(CallbackQueryHandler(_v309_djpro_private_router, pattern=r'^djpropriv\|'), group=-1000000000100)
    app.add_handler(CallbackQueryHandler(_v309_rblk_cleanprev_router, pattern=r'^cfg\|rblk_cleanprev\|'), group=-1000000000100)
    logger.info('V309 cargado: DJPRO privado, limpieza hora/tiempo, cmd:reglas y borrado anterior de bloques recurrentes')
    return app


