def _v310_djpro_markup(chat_id: int) -> InlineKeyboardMarkup:
    st = get_state(int(chat_id))
    live = '🟢ON' if st.live_enabled else '🔴OFF'
    auto = '🤖ON' if st.auto_track_enabled else '🤖OFF'
    alea = '🔀ON' if getattr(st, 'dj_shuffle_enabled', False) else '🔀OFF'
    timer = _v75_timer_label(int(chat_id)) if '_v75_timer_label' in globals() else 'sin temporizador'
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(live, callback_data=f'djpropriv|{chat_id}|live'), InlineKeyboardButton('⏭SIG', callback_data=f'djpropriv|{chat_id}|next'), InlineKeyboardButton(auto, callback_data=f'djpropriv|{chat_id}|auto')],
        [InlineKeyboardButton(alea, callback_data=f'djpropriv|{chat_id}|shuffle'), InlineKeyboardButton('📋Cola', callback_data=f'djpropriv|{chat_id}|queue'), InlineKeyboardButton('📚Biblio', callback_data=f'djpropriv|{chat_id}|library')],
        [InlineKeyboardButton('📂Listas', callback_data=f'djpropriv|{chat_id}|lists'), InlineKeyboardButton('💾Guardar', callback_data=f'djpropriv|{chat_id}|savequeue'), InlineKeyboardButton('🔄Refrescar', callback_data=f'djpropriv|{chat_id}|refresh')],
        [InlineKeyboardButton('⏱1H', callback_data=f'djpropriv|{chat_id}|timer1'), InlineKeyboardButton('⏱2H', callback_data=f'djpropriv|{chat_id}|timer2'), InlineKeyboardButton(f'⏳ {timer}', callback_data=f'djpropriv|{chat_id}|refresh')],
        [InlineKeyboardButton('📤 Subir música aquí', callback_data=f'djpropriv|{chat_id}|uploadinfo')],
        [InlineKeyboardButton('❌ Cerrar sesión grupo', callback_data=f'djpropriv|{chat_id}|sessionclose')],
        [InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'djpropriv|{chat_id}|settings'), InlineKeyboardButton('🌐 Grupo', callback_data='djpropriv|0|groups'), InlineKeyboardButton('Cerrar panel', callback_data=f'djpropriv|{chat_id}|close')],
    ])


def _v310_djpro_text(chat_id: int) -> str:
    st = get_state(int(chat_id))
    base = control_header(st)
    return (
        base
        + '<b>🎛 DJPRO privado</b>\n'
        + 'Controla la mesa del grupo desde este privado. Lo que pulses aquí actualiza también la mesa del grupo.\n\n'
        + '<i>Puedes enviarme audios, canciones o podcast por este privado y te daré botones para ponerlos en cola, biblioteca o reproducirlos en el grupo.</i>'
    )


async def _v310_show_djpro_private(q, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    await q.edit_message_text(_v310_djpro_text(int(chat_id)), parse_mode=ParseMode.HTML, reply_markup=_v310_djpro_markup(int(chat_id)))
    try:
        _v310_set_private_panel(int(chat_id), int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
    except Exception:
        pass


async def _v310_refresh_private_panel(bot, chat_id: int) -> None:
    info = _v310_private_panel_info(int(chat_id))
    if not info:
        return
    try:
        await bot.edit_message_text(
            chat_id=int(info.get('private_chat_id')),
            message_id=int(info.get('message_id')),
            text=_v310_djpro_text(int(chat_id)),
            parse_mode=ParseMode.HTML,
            reply_markup=_v310_djpro_markup(int(chat_id)),
        )
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
    except Exception:

        pass


_old_ensure_control_panel_v310 = ensure_control_panel
async def ensure_control_panel(bot, chat_id: int) -> None:
    await _old_ensure_control_panel_v310(bot, int(chat_id))
    await _v310_refresh_private_panel(bot, int(chat_id))


async def _v310_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V310Stop
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'
    try:
        if action == 'groups' or chat_id == 0:
            await q.answer()
            await q.edit_message_text('🎛 <b>Elige grupo para DJPRO privado</b>', parse_mode=ParseMode.HTML, reply_markup=_v309_djpro_groups_markup(int(q.from_user.id)))
            raise _V310Stop
        if action == 'close':
            await q.answer('Cerrado')
            try:
                await q.message.delete()
            except Exception:
                pass
            raise _V310Stop
        if action == 'settings':
            await q.answer()
            await q.edit_message_text(admin_private_main_text(int(chat_id)), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(int(chat_id)))
            raise _V310Stop
        if action == 'home':
            await q.answer('DJPRO')
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        st = get_state(int(chat_id))
        st.dj_mode = True
        save_all_states()

        if action == 'live':
            await q.answer('LIVE')

            try:
                if st.live_enabled:
                    await VOICE.toggle_live(int(chat_id))
                else:
                    st.live_enabled = True
                    save_all_states()
                    await VOICE.ensure_videochat_started(int(chat_id))
                    if st.queue and not st.now_playing:
                        await simulate_panel_next(int(chat_id), reason='v310_private_live_on')
                    elif st.now_playing:
                        await VOICE.play_track(context.bot, int(chat_id), Track(**st.now_playing))
            except Exception:
                logger.exception('V310 LIVE privado falló')
                await q.answer('Error cambiando LIVE', show_alert=True)
            await ensure_panel(context.bot, int(chat_id))
            await ensure_control_panel(context.bot, int(chat_id))
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action == 'next':
            if not st.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
            else:
                await q.answer('Siguiente')
                await simulate_panel_next(int(chat_id), reason='v310_private_next')
            await ensure_panel(context.bot, int(chat_id))
            await ensure_control_panel(context.bot, int(chat_id))
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action == 'auto':
            st.auto_track_enabled = not bool(st.auto_track_enabled)
            st.auto_sig_seconds = 0
            save_all_states()
            await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
            if st.live_enabled and st.auto_track_enabled and st.queue and not st.now_playing:
                await simulate_panel_next(int(chat_id), reason='v310_private_auto_on')
            await ensure_control_panel(context.bot, int(chat_id))
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action == 'shuffle':
            st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
            save_all_states()
            await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
            await ensure_control_panel(context.bot, int(chat_id))
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action == 'refresh':
            await q.answer('Actualizado')
            await ensure_panel(context.bot, int(chat_id))
            await ensure_control_panel(context.bot, int(chat_id))
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action in ('timer1', 'timer2'):
            hours = 1 if action == 'timer1' else 2
            if '_v75_set_timer' in globals():
                _v75_set_timer(context.bot, int(chat_id), hours, 'pro')
                await q.answer(f'Temporizador {hours}h')
            else:
                await q.answer('Temporizador no disponible', show_alert=True)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V310Stop

        if action == 'sessionclose':
            await q.answer('Cerrando sesión DJ del grupo…')
            await close_dj_session(context.bot, int(chat_id))
            await q.edit_message_text('✅ <b>Sesión DJ cerrada en el grupo.</b>', parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V310Stop

        if action == 'uploadinfo':
            PENDING_ACTIONS[f'djpropriv_target:{int(q.from_user.id)}'] = {'chat_id': int(chat_id)}
            await q.answer('Envíame música por este privado')
            await q.message.reply_html(
                '📤 <b>Subir música al DJPRO</b>\n\n'
                'Envíame aquí un audio, canción, documento de audio, nota de voz o podcast.\n\n'
                'Después podrás elegir:\n'
                '▶️ Reproducir ahora en el grupo\n'
                '⏭ Poner primera en cola\n'
                '➕ Añadir a cola\n'
                '📚 Guardar en biblioteca'
            )
            raise _V310Stop

        if action == 'queue':
            lines = ['📋 <b>Cola actual</b>', '']
            if st.now_playing:
                lines.append('🔴 Sonando: <b>' + h(shorten_title(Track(**st.now_playing).title, 60)) + '</b>')
                lines.append('')
            if not st.queue:
                lines.append('Cola vacía.')
            else:
                for i, item in enumerate(st.queue[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 55))}')
            await q.answer('Cola')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V310Stop

        if action == 'library':
            lines = ['📚 <b>Biblioteca</b>', '']
            if not st.library:
                lines.append('Biblioteca vacía. Puedes subir audios por este privado.')
            else:
                for i, item in enumerate(st.library[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 55))}')
            await q.answer('Biblioteca')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V310Stop

        if action == 'lists':
            lines = ['📂 <b>Listas guardadas</b>', '']
            names = sorted(st.saved_lists.keys())[:30]
            if not names:
                lines.append('No hay listas guardadas.')
            else:
                for i, name in enumerate(names, 1):
                    lines.append(f'{i}. {h(name)} ({len(st.saved_lists.get(name, []))})')
            await q.answer('Listas')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V310Stop

        if action == 'savequeue':
            if not st.queue:
                await q.answer('La cola está vacía.', show_alert=True)
                raise _V310Stop
            set_config_pending(int(q.from_user.id), {'kind': 'djpriv_savequeue_name', 'chat_id': int(chat_id)})
            await q.message.reply_html('💾 Envíame el nombre de la lista que quieres guardar.')
            await q.answer('Envíame el nombre')
            raise _V310Stop

        await q.answer('Acción no válida', show_alert=True)
        raise _V310Stop
    except _V310Stop:
        raise
    except Exception as e:
        logger.exception('V310 DJPRO privado error action=%s chat=%s', action, chat_id)
        await q.answer('Error DJPRO: ' + str(e)[:80], show_alert=True)
        raise _V310Stop


async def _v310_private_audio_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or update.effective_chat.type != 'private' or not update.effective_user or not update.message:
        return
    user_id = int(update.effective_user.id)
    if not _v310_is_admin_id(user_id):
        return
    pending = PENDING_ACTIONS.get(f'djpropriv_target:{user_id}')
    if not pending:
        return
    try:
        chat_id = int(pending.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    if not chat_id:
        return
    track = extract_track_from_message(update.message)
    if not track:
        return
    track.added_by_id = user_id
    track.added_by_name = display_name(update.effective_user)
    token = _v310_secrets.token_urlsafe(8)
    V310_PRIVATE_TRACKS[token] = {'chat_id': int(chat_id), 'track': asdict(track)}
    await update.message.reply_html(
        '🎵 <b>Música recibida para DJPRO</b>\n\n'
        f'Canción/podcast: <b>{h(shorten_title(track.title, 70))}</b>\n'
        f'Grupo destino: <b>{h(str(cfg_value(chat_id, "chat_title", chat_id)))}</b>\n\n'
        'Elige qué hacer:',
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton('▶️ Sonar ahora', callback_data=f'djup|{token}|play'), InlineKeyboardButton('⏭ Primera', callback_data=f'djup|{token}|first')],
            [InlineKeyboardButton('➕ Cola', callback_data=f'djup|{token}|queue'), InlineKeyboardButton('📚 Biblio', callback_data=f'djup|{token}|lib')],
            [InlineKeyboardButton('🎛 DJPRO', callback_data=f'djpropriv|{chat_id}|home')],
        ])
    )
    raise _V310Stop


async def _v310_private_upload_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djup|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V310Stop
    parts = (q.data or '').split('|')
    token = parts[1] if len(parts) > 1 else ''
    action = parts[2] if len(parts) > 2 else ''
    item = V310_PRIVATE_TRACKS.get(token)
    if not item:
        await q.answer('Esta canción ya no está disponible.', show_alert=True)
        raise _V310Stop
    chat_id = int(item.get('chat_id') or 0)
    track = Track(**dict(item.get('track') or {}))
    st = get_state(chat_id)
    try:
        if action == 'lib':
            added = await add_to_library(chat_id, track)
            await q.answer('Añadida a biblioteca' if added else 'Ya estaba en biblioteca')
        elif action == 'queue':
            await queue_track(chat_id, track)
            await q.answer('Añadida a cola')
        elif action == 'first':
            await queue_track_first(chat_id, track)
            await q.answer('Puesta primera')
        elif action == 'play':
            st.dj_mode = True
            st.live_enabled = True
            save_all_states()
            await play_selected_track(context, chat_id, track)
            await q.answer('Sonando en el grupo')
        else:
            await q.answer('Acción no válida', show_alert=True)
            raise _V310Stop
        await ensure_panel(context.bot, chat_id)
        await ensure_control_panel(context.bot, chat_id)
        try:
            await q.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🎛 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
        except Exception:
            pass
    except Exception as e:
        logger.exception('V310 upload privado error')
        await q.answer('Error: ' + str(e)[:80], show_alert=True)
    raise _V310Stop


_old_build_application_v309_for_v310 = build_application

def build_application() -> Application:
    app = _old_build_application_v309_for_v310()

    app.add_handler(CallbackQueryHandler(_v310_djpro_private_router, pattern=r'^djpropriv\|'), group=-1000000000200)
    app.add_handler(CallbackQueryHandler(_v310_private_upload_callback, pattern=r'^djup\|'), group=-1000000000200)
    app.add_handler(MessageHandler((filters.AUDIO | filters.VOICE | filters.Document.ALL), _v310_private_audio_router), group=-1000000000200)
    logger.info('V310 cargado: DJPRO privado colocable en bloques, panel vivo, volver ajustes, cierre/timer y subida privada de música')
    return app


class _V311Stop(Exception):
    pass


def _v311_group_title(chat_id: int) -> str:
    try:
        return str(cfg_value(int(chat_id), 'chat_title', '') or chat_id)
    except Exception:
        return str(chat_id)


def _v311_is_valid_music_group(chat_id: int) -> bool:
    """Para voice/chat de grupo, evitamos usar el chat privado por accidente."""
    try:
        cid = int(chat_id)
    except Exception:
        return False
    if cid == 0:
        return False


    if cid > 0:
        return False
    try:
        return cid in STATE_CACHE or bool(str(cfg_value(cid, 'chat_title', '') or '').strip())
    except Exception:
        return cid in STATE_CACHE


def _v311_store_selected_dj_group(user_id: int, chat_id: int) -> None:
    PENDING_ACTIONS[f'djpropriv_target:{int(user_id)}'] = {'chat_id': int(chat_id)}


def _v311_selected_dj_group(user_id: int) -> int:
    try:
        pending = PENDING_ACTIONS.get(f'djpropriv_target:{int(user_id)}') or {}
        cid = int(pending.get('chat_id') or 0)
        return cid if _v311_is_valid_music_group(cid) else 0
    except Exception:
        return 0


def _v311_extract_target_chat(q) -> int:
    data = q.data or ''
    parts = data.split('|')
    raw = 0
    try:
        raw = int(parts[1]) if len(parts) > 1 else 0
    except Exception:
        raw = 0
    if _v311_is_valid_music_group(raw):
        return int(raw)

    return _v311_selected_dj_group(int(q.from_user.id))


async def _v311_show_group_picker(q) -> None:
    await q.edit_message_text(
        '🎛 <b>Elige el grupo donde está la música</b>\n\n'
        'El videochat se abrirá exclusivamente en el grupo que selecciones aquí.',
        parse_mode=ParseMode.HTML,
        reply_markup=_v309_djpro_groups_markup(int(q.from_user.id)),
    )


async def _v311_refresh_both_panels(bot, chat_id: int) -> None:
    try:
        await ensure_panel(bot, int(chat_id))
    except Exception:
        logger.exception('V311 no pudo refrescar panel fijado grupo %s', chat_id)
    try:
        await ensure_control_panel(bot, int(chat_id))
    except Exception:
        logger.exception('V311 no pudo refrescar mesa grupo %s', chat_id)


async def _v311_live_on(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    """Enciende LIVE en el grupo destino y reproduce si hay cola/sonando."""
    chat_id = int(chat_id)
    st = get_state(chat_id)
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()


    await VOICE.ensure_videochat_started(chat_id)

    if st.queue and not st.now_playing:
        await simulate_panel_next(chat_id, reason='v311_private_live_on_target_group')
    elif st.now_playing:
        try:
            await VOICE.play_track(context.bot, chat_id, Track(**st.now_playing))
        except Exception:
            logger.exception('V311 no pudo relanzar now_playing en grupo %s', chat_id)
            if st.queue:
                await simulate_panel_next(chat_id, reason='v311_private_live_recover_next')
    await _v311_refresh_both_panels(context.bot, chat_id)


async def _v311_live_off(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    chat_id = int(chat_id)
    try:
        await VOICE.toggle_live(chat_id)
    except Exception:
        logger.exception('V311 toggle_live OFF falló; forzando estado OFF en grupo %s', chat_id)
        st = get_state(chat_id)
        st.live_enabled = False
        st.now_playing = None
        st.paused = False
        st.play_started_at = None
        st.paused_remaining = None
        save_all_states()
        try:
            await VOICE.leave(chat_id, end_videochat=True)
        except Exception:
            pass
    await _v311_refresh_both_panels(context.bot, chat_id)


async def _v310_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V311Stop

    parts = (q.data or '').split('|')
    action = parts[2] if len(parts) > 2 else 'home'

    try:
        if action == 'close':
            await q.answer('Cerrado')
            try:
                await q.message.delete()
            except Exception:
                pass
            raise _V311Stop

        if action == 'groups':
            await q.answer('Elige grupo')
            await _v311_show_group_picker(q)
            raise _V311Stop

        chat_id = _v311_extract_target_chat(q)
        if not _v311_is_valid_music_group(chat_id):
            await q.answer('Elige primero el grupo de música.', show_alert=True)
            await _v311_show_group_picker(q)
            raise _V311Stop

        _v311_store_selected_dj_group(int(q.from_user.id), chat_id)

        if action == 'settings':
            await q.answer()
            await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
            raise _V311Stop


        if not await is_admin(context, chat_id, int(q.from_user.id)):
            await q.answer('No eres admin de ese grupo destino.', show_alert=True)
            raise _V311Stop

        st = get_state(chat_id)
        st.dj_mode = True
        save_all_states()

        if action == 'home':
            await q.answer('DJPRO · ' + _v311_group_title(chat_id)[:35])
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'live':
            if st.live_enabled:
                await q.answer('LIVE OFF · ' + _v311_group_title(chat_id)[:30])
                await _v311_live_off(context, chat_id)
            else:
                await q.answer('LIVE ON · ' + _v311_group_title(chat_id)[:30])
                await _v311_live_on(context, chat_id)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'next':
            if not st.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
            else:
                await q.answer('Siguiente · ' + _v311_group_title(chat_id)[:30])
                await simulate_panel_next(chat_id, reason='v311_private_next_target_group')
            await _v311_refresh_both_panels(context.bot, chat_id)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'auto':
            st.auto_track_enabled = not bool(st.auto_track_enabled)
            st.auto_sig_seconds = 0
            save_all_states()
            await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
            if st.live_enabled and st.auto_track_enabled and st.queue and not st.now_playing:
                await simulate_panel_next(chat_id, reason='v311_private_auto_on_target_group')
            await _v311_refresh_both_panels(context.bot, chat_id)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'shuffle':
            st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
            save_all_states()
            await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
            await _v311_refresh_both_panels(context.bot, chat_id)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'refresh':
            await q.answer('Actualizado · ' + _v311_group_title(chat_id)[:30])
            await _v311_refresh_both_panels(context.bot, chat_id)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action in ('timer1', 'timer2'):
            hours = 1 if action == 'timer1' else 2
            if '_v75_set_timer' in globals():
                _v75_set_timer(context.bot, chat_id, hours, 'pro')
                await q.answer(f'Temporizador {hours}h')
            else:
                await q.answer('Temporizador no disponible', show_alert=True)
            await _v310_show_djpro_private(q, context, chat_id)
            raise _V311Stop

        if action == 'sessionclose':
            await q.answer('Cerrando sesión DJ en ' + _v311_group_title(chat_id)[:30])
            await close_dj_session(context.bot, chat_id)
            await _v311_refresh_both_panels(context.bot, chat_id)
            await q.edit_message_text(
                f'✅ <b>Sesión DJ cerrada en el grupo destino.</b>\n\nGrupo: <b>{h(_v311_group_title(chat_id))}</b>',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'djpropriv|{chat_id}|settings'), InlineKeyboardButton('🎛 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]])
            )
            raise _V311Stop

        if action == 'uploadinfo':
            _v311_store_selected_dj_group(int(q.from_user.id), chat_id)
            await q.answer('Envíame música por este privado')
            await q.message.reply_html(
                '📤 <b>Subir música al DJPRO</b>\n\n'
                f'Grupo destino: <b>{h(_v311_group_title(chat_id))}</b>\n\n'
                'Envíame aquí un audio, canción, documento de audio, nota de voz o podcast.\n\n'
                'Después podrás elegir:\n'
                '▶️ Reproducir ahora en el grupo destino\n'
                '⏭ Poner primera en cola\n'
                '➕ Añadir a cola\n'
                '📚 Guardar en biblioteca'
            )
            raise _V311Stop

        if action == 'queue':
            lines = ['📋 <b>Cola actual</b>', f'Grupo: <b>{h(_v311_group_title(chat_id))}</b>', '']
            if st.now_playing:
                lines.append('🔴 Sonando: <b>' + h(shorten_title(Track(**st.now_playing).title, 60)) + '</b>')
                lines.append('')
            if not st.queue:
                lines.append('Cola vacía.')
            else:
                for i, item in enumerate(st.queue[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 55))}')
            await q.answer('Cola')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V311Stop

        if action == 'library':
            lines = ['📚 <b>Biblioteca</b>', f'Grupo: <b>{h(_v311_group_title(chat_id))}</b>', '']
            if not st.library:
                lines.append('Biblioteca vacía. Puedes subir audios por este privado.')
            else:
                for i, item in enumerate(st.library[:30], 1):
                    lines.append(f'{i}. {h(shorten_title(Track(**item).title, 55))}')
            await q.answer('Biblioteca')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V311Stop

        if action == 'lists':
            lines = ['📂 <b>Listas guardadas</b>', f'Grupo: <b>{h(_v311_group_title(chat_id))}</b>', '']
            names = sorted(st.saved_lists.keys())[:30]
            if not names:
                lines.append('No hay listas guardadas.')
            else:
                for i, name in enumerate(names, 1):
                    lines.append(f'{i}. {h(name)} ({len(st.saved_lists.get(name, []))})')
            await q.answer('Listas')
            await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
            raise _V311Stop

        if action == 'savequeue':
            if not st.queue:
                await q.answer('La cola está vacía.', show_alert=True)
                raise _V311Stop
            set_config_pending(int(q.from_user.id), {'kind': 'djpriv_savequeue_name', 'chat_id': chat_id})
            await q.message.reply_html(f'💾 Envíame el nombre de la lista que quieres guardar para <b>{h(_v311_group_title(chat_id))}</b>.')
            await q.answer('Envíame el nombre')
            raise _V311Stop

        await q.answer('Acción no válida', show_alert=True)
        raise _V311Stop
    except _V311Stop:
        raise
    except Exception as e:
        logger.exception('V311 DJPRO privado error action=%s data=%s', action, q.data)
        await q.answer('Error DJPRO: ' + str(e)[:80], show_alert=True)
        raise _V311Stop


async def _v310_private_upload_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djup|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V311Stop
    parts = (q.data or '').split('|')
    token = parts[1] if len(parts) > 1 else ''
    action = parts[2] if len(parts) > 2 else ''
    item = V310_PRIVATE_TRACKS.get(token)
    if not item:
        await q.answer('Esta canción ya no está disponible.', show_alert=True)
        raise _V311Stop
    chat_id = int(item.get('chat_id') or 0)
    if not _v311_is_valid_music_group(chat_id):
        await q.answer('Grupo destino no válido. Abre DJPRO y elige grupo.', show_alert=True)
        raise _V311Stop
    track = Track(**dict(item.get('track') or {}))
    st = get_state(chat_id)
    try:
        if action == 'lib':
            added = await add_to_library(chat_id, track)
            await q.answer('Añadida a biblioteca' if added else 'Ya estaba en biblioteca')
        elif action == 'queue':
            await queue_track(chat_id, track)
            await q.answer('Añadida a cola en ' + _v311_group_title(chat_id)[:30])
        elif action == 'first':
            await queue_track_first(chat_id, track)
            await q.answer('Puesta primera en ' + _v311_group_title(chat_id)[:30])
        elif action == 'play':
            st.dj_mode = True
            st.live_enabled = True
            save_all_states()
            await VOICE.ensure_videochat_started(chat_id)
            await play_selected_track(context, chat_id, track)
            await q.answer('Sonando en ' + _v311_group_title(chat_id)[:30])
        else:
            await q.answer('Acción no válida', show_alert=True)
            raise _V311Stop
        await _v311_refresh_both_panels(context.bot, chat_id)
        try:
            await q.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🎛 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
        except Exception:
            pass
    except Exception as e:
        logger.exception('V311 upload privado error')
        await q.answer('Error: ' + str(e)[:80], show_alert=True)
    raise _V311Stop


_old_build_application_v310_for_v311 = build_application

def build_application() -> Application:
    app = _old_build_application_v310_for_v311()
    app.add_handler(CallbackQueryHandler(_v310_djpro_private_router, pattern=r'^djpropriv\|'), group=-1000000000300)
    app.add_handler(CallbackQueryHandler(_v310_private_upload_callback, pattern=r'^djup\|'), group=-1000000000300)
    logger.info('V311 cargado: DJPRO privado usa siempre grupo destino para videochat/voice')
    return app


BOT_VERSION = "V312"

try:
    from telegram.ext import ApplicationHandlerStop as _V312Stop
except Exception:
    class _V312Stop(Exception):
        pass

DJPRO_SYNC_LOCKS: Dict[int, asyncio.Lock] = {}


def _v312_sync_lock(chat_id: int) -> asyncio.Lock:
    lock = DJPRO_SYNC_LOCKS.get(int(chat_id))
    if lock is None:
        lock = asyncio.Lock()
        DJPRO_SYNC_LOCKS[int(chat_id)] = lock
    return lock


def _v312_valid_group_id(chat_id: int) -> bool:
    try:
        cid = int(chat_id)
        return cid < 0 and chat_is_allowed(cid)
    except Exception:
        return False


def _v312_group_title(chat_id: int) -> str:
    try:
        return _v311_group_title(int(chat_id))
    except Exception:
        try:
            return get_chat_title(int(chat_id))
        except Exception:
            return str(chat_id)


def _v312_track_title(data: Optional[Dict[str, Any]], max_len: int = 44) -> str:
    if not data:
        return "Nada"
    try:
        return shorten_title(Track(**data).title, max_len)
    except Exception:
        return shorten_title(str(data.get('title') or 'Sin título'), max_len)


def _v312_djpro_text(chat_id: int) -> str:
    st = get_state(int(chat_id))
    live = 'ON' if st.live_enabled else 'OFF'
    auto = 'ON' if st.auto_track_enabled else 'OFF'
    alea = 'ON' if getattr(st, 'dj_shuffle_enabled', False) else 'OFF'
    current = _v312_track_title(st.now_playing, 48)
    nxt = _v312_track_title(st.queue[0] if st.queue else None, 48)
    timer = _v75_timer_label(int(chat_id)) if '_v75_timer_label' in globals() else 'sin temporizador'
    return (
        '<b>🎛 DJPRO privado</b>\n'
        f'Grupo: <b>{h(_v312_group_title(chat_id))}</b>\n\n'
        f'LIVE: <b>{live}</b> · AUTO: <b>{auto}</b> · ALEA: <b>{alea}</b>\n'
        f'🔴 Sonando: <b>{h(current)}</b>\n'
        f'⏭ Próxima: <b>{h(nxt)}</b>\n'
        f'📋 Cola: <b>{len(st.queue)}</b> · 📚 Biblioteca: <b>{len(st.library)}</b> · ⏳ <b>{h(timer)}</b>\n\n'
        '<i>Esta mesa privada está sincronizada con la mesa del grupo. Lo que hagas aquí se refleja allí, y viceversa.</i>\n'
        '<i>Puedes enviarme audios, canciones o podcast por privado y elegir cola, primera, biblioteca o sonar ahora.</i>'
    )


def _v310_djpro_text(chat_id: int) -> str:
    return _v312_djpro_text(int(chat_id))


async def _v312_edit_private_home(bot, chat_id: int, *, q=None, force: bool = False) -> None:
    """Pinta la mesa privada con el estado real del grupo. Nunca calcula estado propio."""
    chat_id = int(chat_id)
    if q is not None and getattr(q, 'message', None):
        try:
            await q.edit_message_text(
                _v312_djpro_text(chat_id),
                parse_mode=ParseMode.HTML,
                reply_markup=_v310_djpro_markup(chat_id),
            )
            try:
                _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
            except Exception:
                pass
            return
        except BadRequest as e:
            if 'message is not modified' in str(e).lower():
                try:
                    _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
                except Exception:
                    pass
                return
            raise

    info = _v310_private_panel_info(chat_id)
    if not info:
        return
    try:
        await bot.edit_message_text(
            chat_id=int(info.get('private_chat_id')),
            message_id=int(info.get('message_id')),
            text=_v312_djpro_text(chat_id),
            parse_mode=ParseMode.HTML,
            reply_markup=_v310_djpro_markup(chat_id),
        )
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
    except Exception:

        pass


async def _v312_refresh_group_then_private(bot, chat_id: int) -> None:
    """Refresca ambas mesas desde una sola fuente: STATE_CACHE[chat_id]."""
    chat_id = int(chat_id)
    if not _v312_valid_group_id(chat_id):
        return
    try:
        await ensure_panel(bot, chat_id)
    except Exception:
        logger.exception('V312: no pude refrescar mensaje fijado grupo %s', chat_id)
    try:

        base = globals().get('_old_ensure_control_panel_v310')
        if callable(base):
            await base(bot, chat_id)
        else:
            await ensure_control_panel(bot, chat_id)
    except Exception:
        logger.exception('V312: no pude refrescar mesa grupo %s', chat_id)
    await _v312_edit_private_home(bot, chat_id)


_old_ensure_control_panel_v312 = ensure_control_panel
async def ensure_control_panel(bot, chat_id: int) -> None:
    await _old_ensure_control_panel_v312(bot, int(chat_id))
    if _v312_valid_group_id(int(chat_id)):
        await _v312_edit_private_home(bot, int(chat_id))


_old_close_dj_session_v312 = close_dj_session
async def close_dj_session(bot, chat_id: int) -> None:
    await _old_close_dj_session_v312(bot, int(chat_id))
    try:
        await _v312_edit_private_home(bot, int(chat_id))
    except Exception:
        pass


async def _v312_live_on(bot, chat_id: int) -> None:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()
    await VOICE.ensure_videochat_started(chat_id)

    if st.queue and not st.now_playing:
        await simulate_panel_next(chat_id, reason='v312_live_on_sync')
    elif st.now_playing:
        try:
            await VOICE.play_track(bot, chat_id, Track(**st.now_playing))
        except Exception:
            logger.exception('V312: no pude relanzar now_playing al activar LIVE')
            if st.queue:
                await simulate_panel_next(chat_id, reason='v312_live_recover_next')
    save_all_states()


async def _v312_live_off(bot, chat_id: int) -> None:
    chat_id = int(chat_id)
    st = get_state(chat_id)

    if st.live_enabled:
        await VOICE.toggle_live(chat_id)
    else:
        st.live_enabled = False
        st.now_playing = None
        st.paused = False
        st.play_started_at = None
        st.paused_remaining = None
        save_all_states()


async def _v312_private_home_or_groups(q, context: ContextTypes.DEFAULT_TYPE, chat_id: int, action: str) -> None:
    if action == 'groups' or int(chat_id) == 0:
        await q.answer()
        await q.edit_message_text(
            '🎛 <b>Elige grupo para DJPRO privado</b>',
            parse_mode=ParseMode.HTML,
            reply_markup=_v309_djpro_groups_markup(int(q.from_user.id)),
        )
        raise _V312Stop
    if not _v312_valid_group_id(int(chat_id)):
        await q.answer('Elige un grupo válido para controlar la música.', show_alert=True)
        await q.edit_message_text(
            '🎛 <b>Elige grupo para DJPRO privado</b>',
            parse_mode=ParseMode.HTML,
            reply_markup=_v309_djpro_groups_markup(int(q.from_user.id)),
        )
        raise _V312Stop


async def _v312_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V312Stop

    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'

    await _v312_private_home_or_groups(q, context, chat_id, action)
    chat_id = int(chat_id)

    try:
        if action == 'close':
            await q.answer('Panel cerrado')
            try:
                await q.message.delete()
            except Exception:
                pass
            raise _V312Stop

        if action == 'settings':
            await q.answer()
            await q.edit_message_text(admin_private_main_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=admin_private_main_markup(chat_id))
            raise _V312Stop

        if action == 'home':
            await q.answer('DJPRO')
            await _v312_edit_private_home(context.bot, chat_id, q=q)
            raise _V312Stop

        async with _v312_sync_lock(chat_id):
            st = get_state(chat_id)
            st.dj_mode = True
            save_all_states()

            if action == 'live':
                if st.live_enabled:
                    await q.answer('LIVE OFF')
                    await _v312_live_off(context.bot, chat_id)
                else:
                    await q.answer('LIVE ON')
                    await _v312_live_on(context.bot, chat_id)
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'next':
                if not st.queue:
                    await q.answer('No hay canciones en cola.', show_alert=True)
                else:
                    await q.answer('Siguiente')
                    await simulate_panel_next(chat_id, reason='v312_private_next_sync')
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'auto':
                st.auto_track_enabled = not bool(st.auto_track_enabled)
                st.auto_sig_seconds = 0
                save_all_states()
                await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
                if st.live_enabled and st.auto_track_enabled and st.queue and not st.now_playing:
                    await simulate_panel_next(chat_id, reason='v312_private_auto_idle_sync')
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'shuffle':
                st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
                save_all_states()
                await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'refresh':
                await q.answer('Actualizado')
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action in ('timer1', 'timer2'):
                hours = 1 if action == 'timer1' else 2
                if '_v75_set_timer' in globals():
                    _v75_set_timer(context.bot, chat_id, hours, 'pro')
                    await q.answer(f'Temporizador {hours}h')
                else:
                    await q.answer('Temporizador no disponible', show_alert=True)
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'sessionclose':
                await q.answer('Cerrando sesión DJ')
                await close_dj_session(context.bot, chat_id)
                await _v312_refresh_group_then_private(context.bot, chat_id)
                await _v312_edit_private_home(context.bot, chat_id, q=q)
                raise _V312Stop

            if action == 'uploadinfo':
                _v311_store_selected_dj_group(int(q.from_user.id), chat_id)
                await q.answer('Envíame música por privado')
                await q.message.reply_html(
                    '📤 <b>Subir música al DJPRO</b>\n\n'
                    f'Grupo destino: <b>{h(_v312_group_title(chat_id))}</b>\n\n'
                    'Envíame aquí un audio, canción, documento de audio, nota de voz o podcast.\n\n'
                    'Después podrás elegir:\n'
                    '▶️ Reproducir ahora en el grupo destino\n'
                    '⏭ Poner primera en cola\n'
                    '➕ Añadir a cola\n'
                    '📚 Guardar en biblioteca'
                )
                raise _V312Stop

            if action == 'queue':
                lines = ['📋 <b>Cola actual</b>', f'Grupo: <b>{h(_v312_group_title(chat_id))}</b>', '']
                if st.now_playing:
                    lines.append('🔴 Sonando: <b>' + h(_v312_track_title(st.now_playing, 60)) + '</b>')
                    lines.append('')
                if not st.queue:
                    lines.append('Cola vacía.')
                else:
                    for i, item in enumerate(st.queue[:30], 1):
                        lines.append(f'{i}. {h(_v312_track_title(item, 55))}')
                await q.answer('Cola')
                await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
                try:
                    _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
                except Exception:
                    pass
                raise _V312Stop

            if action == 'library':
                lines = ['📚 <b>Biblioteca</b>', f'Grupo: <b>{h(_v312_group_title(chat_id))}</b>', '']
                if not st.library:
                    lines.append('Biblioteca vacía. Puedes subir audios por este privado.')
                else:
                    for i, item in enumerate(st.library[:30], 1):
                        lines.append(f'{i}. {h(_v312_track_title(item, 55))}')
                await q.answer('Biblioteca')
                await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
                try:
                    _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
                except Exception:
                    pass
                raise _V312Stop

            if action == 'lists':
                lines = ['📂 <b>Listas guardadas</b>', f'Grupo: <b>{h(_v312_group_title(chat_id))}</b>', '']
                names = sorted(st.saved_lists.keys())[:30]
                if not names:
                    lines.append('No hay listas guardadas.')
                else:
                    for i, name in enumerate(names, 1):
                        lines.append(f'{i}. {h(name)} ({len(st.saved_lists.get(name, []))})')
                await q.answer('Listas')
                await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')]]))
                try:
                    _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
                except Exception:
                    pass
                raise _V312Stop

            if action == 'savequeue':
                if not st.queue:
                    await q.answer('La cola está vacía.', show_alert=True)
                    raise _V312Stop
                set_config_pending(int(q.from_user.id), {'kind': 'djpriv_savequeue_name', 'chat_id': chat_id})
                await q.message.reply_html(f'💾 Envíame el nombre de la lista que quieres guardar para <b>{h(_v312_group_title(chat_id))}</b>.')
                await q.answer('Envíame el nombre')
                raise _V312Stop

        await q.answer('Acción no válida', show_alert=True)
        raise _V312Stop

    except _V312Stop:
        raise
    except Exception as e:
        logger.exception('V312 DJPRO privado error action=%s data=%s', action, q.data)
        try:
            await q.answer('Error DJPRO: ' + str(e)[:80], show_alert=True)
        except Exception:
            pass
        raise _V312Stop


async def _v312_private_upload_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djup|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V312Stop
    parts = (q.data or '').split('|')
    token = parts[1] if len(parts) > 1 else ''
    action = parts[2] if len(parts) > 2 else ''
    item = V310_PRIVATE_TRACKS.get(token)
    if not item:
        await q.answer('Esta canción ya no está disponible.', show_alert=True)
        raise _V312Stop
    chat_id = int(item.get('chat_id') or 0)
    if not _v312_valid_group_id(chat_id):
        await q.answer('Grupo destino no válido. Abre DJPRO y elige grupo.', show_alert=True)
        raise _V312Stop
    track = Track(**dict(item.get('track') or {}))
    async with _v312_sync_lock(chat_id):
        st = get_state(chat_id)
        try:
            if action == 'lib':
                added = await add_to_library(chat_id, track)
                await q.answer('Añadida a biblioteca' if added else 'Ya estaba en biblioteca')
            elif action == 'queue':
                await queue_track(chat_id, track)
                await q.answer('Añadida a cola')
            elif action == 'first':
                await queue_track_first(chat_id, track)
                await q.answer('Puesta primera')
            elif action == 'play':
                st.dj_mode = True
                st.live_enabled = True
                save_all_states()
                await VOICE.ensure_videochat_started(chat_id)
                await play_selected_track(context, chat_id, track)
                await q.answer('Sonando en grupo')
            else:
                await q.answer('Acción no válida', show_alert=True)
                raise _V312Stop
            await _v312_refresh_group_then_private(context.bot, chat_id)
            try:
                await q.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🎛 DJPRO', callback_data=f'djpropriv|{chat_id}|home')]]))
            except Exception:
                pass
        except _V312Stop:
            raise
        except Exception as e:
            logger.exception('V312 upload privado error')
            await q.answer('Error: ' + str(e)[:80], show_alert=True)
    raise _V312Stop


_old_simulate_panel_next_v312 = simulate_panel_next
async def simulate_panel_next(chat_id: int, reason: str = 'panel_next') -> bool:
    ok = await _old_simulate_panel_next_v312(int(chat_id), reason=reason)
    try:
        if ok and VOICE.application:
            await _v312_refresh_group_then_private(VOICE.application.bot, int(chat_id))
    except Exception:
        pass
    return bool(ok)


_old_build_application_v311_for_v312 = build_application

def build_application() -> Application:
    app = _old_build_application_v311_for_v312()

    app.add_handler(CallbackQueryHandler(_v312_djpro_private_router, pattern=r'^djpropriv\|'), group=-1000000000600)
    app.add_handler(CallbackQueryHandler(_v312_private_upload_callback, pattern=r'^djup\|'), group=-1000000000600)
    logger.info('V312 cargado: mesas DJPRO grupo/privado sincronizadas como una sola mesa')
    return app


def _v313_short_onoff(value: bool) -> str:
    return 'ON' if bool(value) else 'OFF'


def _v313_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return admin_cfg(int(chat_id))
    except Exception:
        st = get_state(int(chat_id))
        if not isinstance(st.admin_config, dict):
            st.admin_config = {}
        return st.admin_config


def _v313_private_markup(chat_id: int) -> InlineKeyboardMarkup:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    cfg = _v313_cfg(chat_id)
    live = '🟢ON' if st.live_enabled else '🔴OFF'
    auto = '🤖ON' if st.auto_track_enabled else '🤖OFF'
    alea = '🔀ON' if getattr(st, 'dj_shuffle_enabled', False) else '🔀OFF'
    timer = _v75_timer_label(chat_id) if '_v75_timer_label' in globals() else 'sin temp.'
    opus = '🎚ON' if bool(cfg.get('dj_opus_hd_enabled', False)) else '🎚OFF'
    kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
    aviso = '📣ON' if bool(cfg.get('dj_announce_now_enabled', True)) else '📣OFF'
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(live, callback_data=f'djpropriv|{chat_id}|live'), InlineKeyboardButton('⏭SIG', callback_data=f'djpropriv|{chat_id}|next'), InlineKeyboardButton(auto, callback_data=f'djpropriv|{chat_id}|auto')],
        [InlineKeyboardButton(alea, callback_data=f'djpropriv|{chat_id}|shuffle'), InlineKeyboardButton('📋Cola', callback_data=f'djpropriv|{chat_id}|queue'), InlineKeyboardButton('📚Biblio', callback_data=f'djpropriv|{chat_id}|library')],
        [InlineKeyboardButton('📂Cargar', callback_data=f'djpropriv|{chat_id}|lists'), InlineKeyboardButton('💾Guardar', callback_data=f'djpropriv|{chat_id}|savequeue'), InlineKeyboardButton('🔁Act.Lista', callback_data=f'djpropriv|{chat_id}|updatelist')],
        [InlineKeyboardButton('🔉-4', callback_data=f'djpropriv|{chat_id}|voldown4'), InlineKeyboardButton('🔊+4', callback_data=f'djpropriv|{chat_id}|volup4'), InlineKeyboardButton('🔇0', callback_data=f'djpropriv|{chat_id}|vol0'), InlineKeyboardButton('🔈25', callback_data=f'djpropriv|{chat_id}|vol25'), InlineKeyboardButton('🔊75', callback_data=f'djpropriv|{chat_id}|vol75')],
        [InlineKeyboardButton(opus, callback_data=f'djpropriv|{chat_id}|opus'), InlineKeyboardButton(f'💎{kbps}K', callback_data=f'djpropriv|{chat_id}|quality'), InlineKeyboardButton(aviso, callback_data=f'djpropriv|{chat_id}|announce')],
        [InlineKeyboardButton('⏱1H', callback_data=f'djpropriv|{chat_id}|timer1'), InlineKeyboardButton('⏱2H', callback_data=f'djpropriv|{chat_id}|timer2'), InlineKeyboardButton('🔄Refrescar', callback_data=f'djpropriv|{chat_id}|refresh')],
        [InlineKeyboardButton('📤 Subir música aquí', callback_data=f'djpropriv|{chat_id}|uploadinfo')],
        [InlineKeyboardButton('❌ Cerrar sesión grupo', callback_data=f'djpropriv|{chat_id}|sessionclose')],
        [InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'djpropriv|{chat_id}|settings'), InlineKeyboardButton('🌐 Grupo', callback_data='djpropriv|0|groups'), InlineKeyboardButton('Cerrar panel', callback_data=f'djpropriv|{chat_id}|close')],
    ])


def _v310_djpro_markup(chat_id: int) -> InlineKeyboardMarkup:
    return _v313_private_markup(int(chat_id))


_old_control_panel_markup_v313 = control_panel_markup

def control_panel_markup(state: ChatState) -> InlineKeyboardMarkup:
    try:
        chat_id = _v273_state_chat_id(state) or 0 if '_v273_state_chat_id' in globals() else 0
        live = bool(getattr(state, 'live_enabled', False))
        temp_on = int(getattr(state, 'auto_sig_seconds', -1) or -1) >= 0
        auto_on = bool(getattr(state, 'auto_track_enabled', False))
        shuffle_on = bool(getattr(state, 'dj_shuffle_enabled', False))
        return InlineKeyboardMarkup([
            [InlineKeyboardButton(('🔴OFF' if live else '🟢ON'), callback_data='panel_live_toggle'), InlineKeyboardButton('⏭', callback_data='panel_next'), InlineKeyboardButton('⏮', callback_data='panel_prev')],
            [InlineKeyboardButton('⏱' + _v313_short_onoff(temp_on), callback_data='panel_temp_toggle'), InlineKeyboardButton('🤖' + _v313_short_onoff(auto_on), callback_data='panel_auto_track'), InlineKeyboardButton('🔀' + _v313_short_onoff(shuffle_on), callback_data='panel_shuffle')],
            [InlineKeyboardButton('📋Lista', callback_data='panel_queue'), InlineKeyboardButton('💾Act.', callback_data='panel_update_current_full'), InlineKeyboardButton('🎧', callback_data='panel_join_live')],
            [InlineKeyboardButton('📂Carg.', callback_data='panel_load_lists'), InlineKeyboardButton('💽Guard.', callback_data='panel_save_list')],
            [InlineKeyboardButton('🔉-4', callback_data='panel_vol_down4'), InlineKeyboardButton('🔊+4', callback_data='panel_vol_up4'), InlineKeyboardButton('🔇0', callback_data='panel_vol_set|0'), InlineKeyboardButton('🔈25', callback_data='panel_vol_set|25'), InlineKeyboardButton('🔊75', callback_data='panel_vol_set|75')],
            [InlineKeyboardButton('⏳1h', callback_data='dj_timer|pro|1'), InlineKeyboardButton('⏳2h', callback_data='dj_timer|pro|2'), InlineKeyboardButton('🔄', callback_data='panel_refresh_v273')],
            [InlineKeyboardButton('➖', callback_data='panel_minimize'), InlineKeyboardButton('❤️', callback_data='panel_likes'), InlineKeyboardButton('❌', callback_data='panel_close')],
        ])
    except Exception:
        return _old_control_panel_markup_v313(state)


def _v313_current_list_name(chat_id: int) -> str:
    cfg = _v313_cfg(int(chat_id))
    for key in ('dj_current_list_name', 'dj_current_saved_list', 'current_dj_list_name'):
        val = cfg.get(key)
        if val:
            return str(val)
    return ''


def _v313_set_current_list_name(chat_id: int, name: str) -> None:
    cfg = _v313_cfg(int(chat_id))
    cfg['dj_current_list_name'] = str(name or '')
    cfg['dj_current_saved_list'] = str(name or '')
    save_all_states()


def _v313_session_items(chat_id: int) -> List[Dict[str, Any]]:
    st = get_state(int(chat_id))
    items: List[Dict[str, Any]] = []
    for x in list(st.history or []):
        if isinstance(x, dict):
            items.append(dict(x))
    if isinstance(st.now_playing, dict):
        items.append(dict(st.now_playing))
    for x in list(st.queue or []):
        if isinstance(x, dict):
            items.append(dict(x))
    return dedupe_track_items(items) if 'dedupe_track_items' in globals() else items


def _v313_lists_markup(chat_id: int) -> InlineKeyboardMarkup:
    st = get_state(int(chat_id))
    rows: List[List[InlineKeyboardButton]] = []
    names = sorted((st.saved_lists or {}).keys())[:20]
    for idx, name in enumerate(names):
        short = str(name)[:18]
        rows.append([InlineKeyboardButton('▶️ ' + short, callback_data=f'djpropriv|{chat_id}|listplay|{idx}'), InlineKeyboardButton('➕Cola', callback_data=f'djpropriv|{chat_id}|listqueue|{idx}'), InlineKeyboardButton('📚Biblio', callback_data=f'djpropriv|{chat_id}|listlib|{idx}')])
    rows.append([InlineKeyboardButton('🔁 Actualizar lista actual', callback_data=f'djpropriv|{chat_id}|updatelist')])
    rows.append([InlineKeyboardButton('🔙 DJPRO', callback_data=f'djpropriv|{chat_id}|home'), InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings')])
    return InlineKeyboardMarkup(rows)


async def _v313_refresh_all(bot, chat_id: int, *, q=None) -> None:
    try:
        await _v312_refresh_group_then_private(bot, int(chat_id))
    except Exception:
        logger.exception('V313 no pudo refrescar grupo+privado')
    if q is not None:
        try:
            await _v312_edit_private_home(bot, int(chat_id), q=q)
        except BadRequest as e:
            if 'message is not modified' not in str(e).lower():
                raise
        except Exception:
            logger.exception('V313 no pudo repintar privado')


async def _v313_live_on(bot, chat_id: int) -> None:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()
    try:
        await VOICE.ensure_videochat_started(chat_id)
    except Exception:
        logger.exception('V313 no pudo asegurar videochat chat=%s', chat_id)

    if st.queue:
        if not st.now_playing:
            await simulate_panel_next(chat_id, reason='v313_live_on_first_queue')
        else:
            try:
                await VOICE.play_track(bot, chat_id, Track(**st.now_playing))
            except Exception:
                logger.exception('V313 no pudo relanzar now_playing; pasa a cola')
                await simulate_panel_next(chat_id, reason='v313_live_on_recover_queue')
    elif st.now_playing:
        try:
            await VOICE.play_track(bot, chat_id, Track(**st.now_playing))
        except Exception:
            logger.exception('V313 no pudo relanzar now_playing sin cola')
    save_all_states()


async def _v313_announce_once(bot, chat_id: int, track: Optional[Track]) -> None:
    if not track:
        return
    chat_id = int(chat_id)
    cfg = _v313_cfg(chat_id)
    if not bool(cfg.get('dj_announce_now_enabled', True)):
        return
    try:
        key = track_fingerprint(track) if 'track_fingerprint' in globals() else (track.file_unique_id or track.file_id or track.title)
    except Exception:
        key = getattr(track, 'file_unique_id', '') or getattr(track, 'file_id', '') or getattr(track, 'title', '')
    import time as _time
    last_key = str(cfg.get('dj_announce_last_key_v313', '') or '')
    last_ts = float(cfg.get('dj_announce_last_ts_v313', 0) or 0)
    if key and key == last_key and (_time.time() - last_ts) < 20:
        return
    cfg['dj_announce_last_key_v313'] = key
    cfg['dj_announce_last_ts_v313'] = _time.time()
    save_all_states()
    try:

        if '_v271_send_now_announce' in globals():
            await _v271_send_now_announce(bot, chat_id, track)
        elif '_send_dj_now_announce_v24' in globals():
            await _send_dj_now_announce_v24(bot, chat_id, track)
        elif '_v273_announce_track' in globals():
            await _v273_announce_track(bot, chat_id, track)
    except Exception:
        logger.exception('V313 no pudo enviar aviso automático de canción chat=%s', chat_id)


_old_voice_play_track_v313 = VOICE.play_track
async def _v313_voice_play_track(bot, chat_id: int, track: Track) -> None:
    await _old_voice_play_track_v313(bot, int(chat_id), track)
    try:
        await _v313_announce_once(bot, int(chat_id), track)
    except Exception:
        pass
VOICE.play_track = _v313_voice_play_track


_old_simulate_panel_next_v313 = simulate_panel_next
async def simulate_panel_next(chat_id: int, reason: str = 'panel_next') -> bool:
    ok = await _old_simulate_panel_next_v313(int(chat_id), reason=reason)
    try:
        if ok and VOICE.application:
            st = get_state(int(chat_id))
            tr = Track(**st.now_playing) if st.now_playing else None
            await _v313_announce_once(VOICE.application.bot, int(chat_id), tr)
            await _v312_refresh_group_then_private(VOICE.application.bot, int(chat_id))
    except Exception:
        pass
    return bool(ok)


class _V313Stop(Exception):
    pass


async def _v313_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V313Stop
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'


    await _v312_private_home_or_groups(q, context, chat_id, action)
    chat_id = int(chat_id)

    try:
        async with _v312_sync_lock(chat_id):
            st = get_state(chat_id)
            st.dj_mode = True
            save_all_states()

            if action == 'live':
                if st.live_enabled:
                    await q.answer('LIVE OFF')
                    await _v312_live_off(context.bot, chat_id)
                else:
                    await q.answer('LIVE ON')
                    await _v313_live_on(context.bot, chat_id)
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'next':
                if not st.queue:
                    await q.answer('No hay canciones en cola.', show_alert=True)
                else:
                    await q.answer('Siguiente')
                    await simulate_panel_next(chat_id, reason='v313_private_next')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'auto':
                st.auto_track_enabled = not bool(st.auto_track_enabled)
                st.auto_sig_seconds = 0
                save_all_states()
                await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
                if st.live_enabled and st.auto_track_enabled and st.queue and not st.now_playing:
                    await simulate_panel_next(chat_id, reason='v313_private_auto_idle')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'shuffle':
                st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
                save_all_states()
                await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action in ('voldown4', 'volup4', 'vol0', 'vol25', 'vol75'):
                if action == 'voldown4':
                    vol = await VOICE.change_volume(chat_id, -4)
                elif action == 'volup4':
                    vol = await VOICE.change_volume(chat_id, 4)
                else:
                    target = {'vol0': 0, 'vol25': 25, 'vol75': 75}.get(action, 75)
                    vol = await VOICE.set_volume(chat_id, target)
                st.volume = int(vol)
                save_all_states()
                await q.answer(f'Vol {vol}')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'opus':
                cfg = _v313_cfg(chat_id)
                cfg['dj_opus_hd_enabled'] = not bool(cfg.get('dj_opus_hd_enabled', False))
                save_all_states()
                await q.answer('OPUS ' + _v313_short_onoff(cfg['dj_opus_hd_enabled']))
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'quality':
                cfg = _v313_cfg(chat_id)
                opts = [96, 128, 160, 192]
                cur = int(cfg.get('dj_opus_kbps', 128) or 128)
                cfg['dj_opus_kbps'] = opts[(opts.index(cur) + 1) % len(opts)] if cur in opts else 128
                save_all_states()
                await q.answer(f"{cfg['dj_opus_kbps']}k")
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'announce':
                cfg = _v313_cfg(chat_id)
                cfg['dj_announce_now_enabled'] = not bool(cfg.get('dj_announce_now_enabled', True))
                save_all_states()
                await q.answer('AVISO ' + _v313_short_onoff(cfg['dj_announce_now_enabled']))
                if cfg['dj_announce_now_enabled'] and st.now_playing:
                    await _v313_announce_once(context.bot, chat_id, Track(**st.now_playing))
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action in ('timer1', 'timer2'):
                hours = 1 if action == 'timer1' else 2
                if '_v75_set_timer' in globals():
                    _v75_set_timer(context.bot, chat_id, hours, 'pro')
                    await q.answer(f'Temporizador {hours}h')
                else:
                    await q.answer('Temporizador no disponible', show_alert=True)
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'updatelist':
                name = _v313_current_list_name(chat_id) or 'Sesión actual'
                items = _v313_session_items(chat_id)
                if not items:
                    await q.answer('No hay canciones para actualizar.', show_alert=True)
                    raise _V313Stop
                st.saved_lists[name] = items
                _v313_set_current_list_name(chat_id, name)
                save_all_states()
                await q.answer(f'Lista actualizada: {name}')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'lists':
                lines = ['📂 <b>Listas guardadas</b>', f'Grupo: <b>{h(_v312_group_title(chat_id))}</b>', '']
                names = sorted((st.saved_lists or {}).keys())[:20]
                if not names:
                    lines.append('No hay listas guardadas.')
                else:
                    for i, name in enumerate(names, 1):
                        current = ' ✅' if name == _v313_current_list_name(chat_id) else ''
                        lines.append(f'{i}. {h(name)} ({len(st.saved_lists.get(name, []))}){current}')
                await q.answer('Listas')
                await q.edit_message_text('\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=_v313_lists_markup(chat_id))
                try:
                    _v310_set_private_panel(chat_id, int(q.message.chat.id), int(q.message.message_id), int(q.from_user.id))
                except Exception:
                    pass
                raise _V313Stop

            if action in ('listplay', 'listqueue', 'listlib'):
                try:
                    idx = int(parts[3])
                except Exception:
                    idx = -1
                names = sorted((st.saved_lists or {}).keys())
                if idx < 0 or idx >= len(names):
                    await q.answer('Lista no encontrada.', show_alert=True)
                    raise _V313Stop
                name = names[idx]
                items = [dict(x) for x in (st.saved_lists.get(name) or []) if isinstance(x, dict)]
                if not items:
                    await q.answer('Lista vacía.', show_alert=True)
                    raise _V313Stop
                if action == 'listplay':
                    st.queue = dedupe_track_items(items)
                    st.now_playing = None
                    _v313_set_current_list_name(chat_id, name)
                    st.live_enabled = True
                    save_all_states()
                    await q.answer()
                    await _v313_live_on(context.bot, chat_id)
                elif action == 'listqueue':
                    st.queue = dedupe_track_items(list(st.queue or []) + items)
                    _v313_set_current_list_name(chat_id, name)
                    save_all_states()
                    await q.answer('Añadida a cola')
                else:
                    st.library = dedupe_library_items(list(st.library or []) + items) if 'dedupe_library_items' in globals() else list(st.library or []) + items
                    save_all_states()
                    await q.answer('Añadida a biblioteca')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop

            if action == 'refresh':
                await q.answer('Actualizado')
                await _v313_refresh_all(context.bot, chat_id, q=q)
                raise _V313Stop


    except _V313Stop:
        raise
    except Exception as e:
        logger.exception('V313 DJPRO privado error action=%s data=%s', action, q.data)
        try:
            await q.answer('Error DJPRO: ' + str(e)[:80], show_alert=True)
        except Exception:
            pass
        raise _V313Stop


_old_build_application_v312_for_v313 = build_application

def build_application() -> Application:
    app = _old_build_application_v312_for_v313()
    app.add_handler(CallbackQueryHandler(_v313_djpro_private_router, pattern=r'^djpropriv\|'), group=-1000000000700)
    logger.info('V313 cargado: DJPRO privado con listas, volumen, OPUS/aviso privados y anuncios automáticos')
    return app


BOT_VERSION = "V314"

try:
    from telegram.ext import ApplicationHandlerStop as _V314Stop
except Exception:
    class _V314Stop(Exception):
        pass

_V314_PRIVATE_RENDER_CACHE: Dict[int, str] = {}
_V314_PRIVATE_REFRESH_LOCKS: Dict[int, asyncio.Lock] = {}


def _v314_lock(chat_id: int) -> asyncio.Lock:
    try:
        return _v312_sync_lock(int(chat_id))
    except Exception:
        lock = _V314_PRIVATE_REFRESH_LOCKS.get(int(chat_id))
        if lock is None:
            lock = asyncio.Lock()
            _V314_PRIVATE_REFRESH_LOCKS[int(chat_id)] = lock
        return lock


def _v314_valid_group(chat_id: int) -> bool:
    try:
        return int(chat_id) < 0 and chat_is_allowed(int(chat_id))
    except Exception:
        return False


def _v314_title(chat_id: int) -> str:
    try:
        return _v312_group_title(int(chat_id))
    except Exception:
        try:
            return get_chat_title(int(chat_id))
        except Exception:
            return str(chat_id)


def _v314_track_label(data: Optional[Dict[str, Any]], max_len: int = 46) -> str:
    if not data:
        return 'Nada'
    try:
        return shorten_title(Track(**data).title, max_len)
    except Exception:
        try:
            return shorten_title(str(data.get('title') or 'Sin título'), max_len)
        except Exception:
            return 'Sin título'


def _v314_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return _v313_cfg(int(chat_id))
    except Exception:
        return admin_cfg(int(chat_id))


def _v314_onoff(value: Any) -> str:
    return 'ON' if bool(value) else 'OFF'


def _v314_current_list_name(chat_id: int) -> str:
    try:
        return _v313_current_list_name(int(chat_id))
    except Exception:
        return str(_v314_cfg(int(chat_id)).get('dj_current_list_name', '') or '')


def _v314_set_current_list_name(chat_id: int, name: str) -> None:
    try:
        _v313_set_current_list_name(int(chat_id), name)
    except Exception:
        _v314_cfg(int(chat_id))['dj_current_list_name'] = str(name or '')
        save_all_states()


def _v314_session_items(chat_id: int) -> List[Dict[str, Any]]:
    try:
        return _v313_session_items(int(chat_id))
    except Exception:
        st = get_state(int(chat_id))
        items: List[Dict[str, Any]] = []
        items.extend([dict(x) for x in (st.history or []) if isinstance(x, dict)])
        if st.now_playing:
            items.append(dict(st.now_playing))
        items.extend([dict(x) for x in (st.queue or []) if isinstance(x, dict)])
        return dedupe_track_items(items) if 'dedupe_track_items' in globals() else items


def _v314_private_text(chat_id: int) -> str:
    st = get_state(int(chat_id))
    cfg = _v314_cfg(int(chat_id))
    live = _v314_onoff(st.live_enabled)
    auto = _v314_onoff(st.auto_track_enabled)
    alea = _v314_onoff(getattr(st, 'dj_shuffle_enabled', False))
    aviso = _v314_onoff(cfg.get('dj_announce_now_enabled', True))
    opus = _v314_onoff(cfg.get('dj_opus_hd_enabled', False))
    kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
    current = _v314_track_label(st.now_playing, 48)
    nxt = _v314_track_label(st.queue[0] if st.queue else None, 48)
    prev = _v314_track_label(st.history[-1] if st.history else None, 36)
    timer = _v75_timer_label(int(chat_id)) if '_v75_timer_label' in globals() else 'sin temporizador'
    list_name = _v314_current_list_name(int(chat_id)) or 'Sesión actual'
    return (
        '<b>🎛 DJPRO privado</b>\n'
        f'Grupo: <b>{h(_v314_title(chat_id))}</b>\n\n'
        f'LIVE: <b>{live}</b> · AUTO: <b>{auto}</b> · ALEA: <b>{alea}</b> · VOL: <b>{int(getattr(st, "volume", 100) or 100)}</b>\n'
        f'📣 Aviso: <b>{aviso}</b> · OPUS: <b>{opus}</b> · Calidad: <b>{kbps}k</b>\n'
        f'🔴 Sonando: <b>{h(current)}</b>\n'
        f'⏭ Próxima: <b>{h(nxt)}</b>\n'
        f'⏮ Anterior: <b>{h(prev)}</b>\n'
        f'📋 Cola: <b>{len(st.queue)}</b> · 📚 Biblioteca: <b>{len(st.library)}</b> · 📂 Lista: <b>{h(list_name)}</b>\n'
        f'⏳ Temporizador: <b>{h(timer)}</b>\n\n'
        '<i>Mesa privada sincronizada con la mesa del grupo. Ambas leen y modifican el mismo estado.</i>'
    )


