BOT_VERSION = "V315"

V315_GROUP_DJ_ACTIONS = {
    'panel_live_toggle', 'panel_pause_resume', 'panel_next', 'panel_prev',
    'panel_auto_track', 'panel_shuffle', 'panel_auto_sig', 'panel_auto_next',
    'panel_join_live', 'panel_refresh', 'panel_close', 'panel_minimize',
    'panel_update_current_full', 'panel_vol_down', 'panel_vol_up',
    'panel_likes', 'panel_announce_now',
}
V315_PRIVATE_CONTROL_ACTIONS = {
    'live', 'next', 'prev', 'auto', 'shuffle',
    'voldown4', 'volup4', 'vol0', 'vol25', 'vol75',
    'opus', 'quality', 'announce', 'timer1', 'timer2',
    'sessionclose', 'listplay', 'listqueue', 'listlib',
    'updatelist', 'savequeue', 'uploadinfo',
}
V315_VOICE_RECOVERY: Dict[int, Dict[str, Any]] = {}
V315_RECOVERY_TASK: Optional[asyncio.Task] = None


def _v315_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return _v314_cfg(int(chat_id))
    except Exception:
        return admin_cfg(int(chat_id))


def _v315_control_owner(chat_id: int) -> str:
    cfg = _v315_cfg(int(chat_id))
    owner = str(cfg.get('dj_control_owner') or 'group').strip().lower()
    return 'private' if owner == 'private' else 'group'


def _v315_set_control_owner(chat_id: int, owner: str) -> None:
    cfg = _v315_cfg(int(chat_id))
    cfg['dj_control_owner'] = 'private' if str(owner).lower() == 'private' else 'group'
    save_all_states()


def _v315_control_label(chat_id: int, panel: str) -> str:
    owner = _v315_control_owner(int(chat_id))
    active = (owner == panel)
    if panel == 'group':
        return ('🔵 C Grupo' if active else '⚫ C Privado')
    return ('🔵 C Privado' if active else '⚫ C Grupo')


def _v315_group_control_row(chat_id: int) -> List[InlineKeyboardButton]:
    return [InlineKeyboardButton(_v315_control_label(int(chat_id), 'group'), callback_data='panel_control_take')]


def _v315_private_control_row(chat_id: int) -> List[InlineKeyboardButton]:
    return [InlineKeyboardButton(_v315_control_label(int(chat_id), 'private'), callback_data=f'djpropriv|{int(chat_id)}|control')]


def _v315_should_block_group(chat_id: int, data: str) -> bool:
    if data == 'panel_control_take':
        return False
    if data.startswith('panel_vol_set|'):
        return _v315_control_owner(int(chat_id)) != 'group'
    return data in V315_GROUP_DJ_ACTIONS and _v315_control_owner(int(chat_id)) != 'group'


def _v315_should_block_private(chat_id: int, action: str) -> bool:
    if action in {'control', 'home', 'noop', 'groups', 'settings', 'close', 'refresh', 'queue', 'library', 'lists'}:
        return False
    return action in V315_PRIVATE_CONTROL_ACTIONS and _v315_control_owner(int(chat_id)) != 'private'


def _v314_private_markup(chat_id: int) -> InlineKeyboardMarkup:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    cfg = _v314_cfg(chat_id)
    live = '🟢LIVE' if st.live_enabled else '🔴LIVE'
    auto = '🤖ON' if st.auto_track_enabled else '🤖OFF'
    alea = '🔀ON' if getattr(st, 'dj_shuffle_enabled', False) else '🔀OFF'
    aviso = '📣ON' if cfg.get('dj_announce_now_enabled', True) else '📣OFF'
    opus = '🎚ON' if cfg.get('dj_opus_hd_enabled', False) else '🎚OFF'
    kbps = int(cfg.get('dj_opus_kbps', 128) or 128)
    return InlineKeyboardMarkup([
        _v315_private_control_row(chat_id),
        [InlineKeyboardButton(live, callback_data=f'djpropriv|{chat_id}|live'), InlineKeyboardButton('⏭SIG', callback_data=f'djpropriv|{chat_id}|next'), InlineKeyboardButton(auto, callback_data=f'djpropriv|{chat_id}|auto')],
        [InlineKeyboardButton(alea, callback_data=f'djpropriv|{chat_id}|shuffle'), InlineKeyboardButton('📋Cola', callback_data=f'djpropriv|{chat_id}|queue'), InlineKeyboardButton('📚Biblio', callback_data=f'djpropriv|{chat_id}|library')],
        [InlineKeyboardButton('📂Listas', callback_data=f'djpropriv|{chat_id}|lists'), InlineKeyboardButton('💾Act.Lista', callback_data=f'djpropriv|{chat_id}|updatelist'), InlineKeyboardButton('💽Guardar', callback_data=f'djpropriv|{chat_id}|savequeue')],
        [InlineKeyboardButton('🔉-4', callback_data=f'djpropriv|{chat_id}|voldown4'), InlineKeyboardButton('🔊+4', callback_data=f'djpropriv|{chat_id}|volup4'), InlineKeyboardButton('🔇0', callback_data=f'djpropriv|{chat_id}|vol0'), InlineKeyboardButton('🔈25', callback_data=f'djpropriv|{chat_id}|vol25'), InlineKeyboardButton('🔊75', callback_data=f'djpropriv|{chat_id}|vol75')],
        [InlineKeyboardButton(opus, callback_data=f'djpropriv|{chat_id}|opus'), InlineKeyboardButton(f'💎{kbps}k', callback_data=f'djpropriv|{chat_id}|quality'), InlineKeyboardButton(aviso, callback_data=f'djpropriv|{chat_id}|announce')],
        [InlineKeyboardButton('⏱1H', callback_data=f'djpropriv|{chat_id}|timer1'), InlineKeyboardButton('⏱2H', callback_data=f'djpropriv|{chat_id}|timer2'), InlineKeyboardButton('🔄Refrescar', callback_data=f'djpropriv|{chat_id}|refresh')],
        [InlineKeyboardButton('📤Subir música', callback_data=f'djpropriv|{chat_id}|uploadinfo'), InlineKeyboardButton('❌Cerrar sesión', callback_data=f'djpropriv|{chat_id}|sessionclose')],
        [InlineKeyboardButton('⚙️ Ajustes', callback_data=f'djpropriv|{chat_id}|settings'), InlineKeyboardButton('🌐 Grupo', callback_data='djpropriv|0|groups'), InlineKeyboardButton('Cerrar panel', callback_data=f'djpropriv|{chat_id}|close')],
    ])


def _v310_djpro_markup(chat_id: int) -> InlineKeyboardMarkup:
    return _v314_private_markup(int(chat_id))


_old_control_panel_markup_v315 = control_panel_markup

def control_panel_markup(state: ChatState) -> InlineKeyboardMarkup:
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), 0)
    except Exception:
        chat_id = 0
    try:
        base = _old_control_panel_markup_v315(state)
        rows = [list(row) for row in getattr(base, 'inline_keyboard', [])]
        if int(chat_id) and rows:

            rows = [row for row in rows if not any(str(getattr(btn, 'callback_data', '')) == 'panel_control_take' for btn in row)]
            rows.insert(0, _v315_group_control_row(int(chat_id)))
        return InlineKeyboardMarkup(rows)
    except Exception:
        return _old_control_panel_markup_v315(state)


async def _v315_send_manual_voice_hint(bot, chat_id: int) -> None:
    now = int(__import__('time').time())
    data = V315_VOICE_RECOVERY.setdefault(int(chat_id), {})
    if now - int(data.get('last_hint_ts') or 0) < 60:
        return
    data['last_hint_ts'] = now
    try:
        await send_temp_message(
            bot,
            int(chat_id),
            '🎧 <b>Directo preparado</b>\n\nNo he podido abrir el videochat automáticamente.\nAbre el videochat manualmente desde el nombre del grupo. En cuanto esté abierto, si hay cola y LIVE está ON, intentaré subir al voice y reproducir la primera canción.',
            ttl=45,
        )
    except Exception:
        pass


async def _v315_try_start_voice_and_first(bot, chat_id: int, *, reason: str = 'v315_live') -> bool:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()

    opened = False
    try:
        opened = bool(await VOICE.ensure_videochat_started(chat_id))
    except Exception:
        logger.exception('V315 no pudo asegurar videochat chat=%s reason=%s', chat_id, reason)
        opened = False

    if not opened:
        await _v315_send_manual_voice_hint(bot, chat_id)
        await _v314_refresh_both(bot, chat_id, force_private=True)
        return False

    if st.queue and not st.now_playing:
        return bool(await _v314_play_next(bot, chat_id, reason=reason))
    if st.now_playing:
        try:
            await VOICE.play_track(bot, chat_id, Track(**st.now_playing))
            await _v314_refresh_both(bot, chat_id, force_private=True)
            return True
        except Exception:
            logger.exception('V315 no pudo relanzar now_playing chat=%s', chat_id)
            if st.queue:
                return bool(await _v314_play_next(bot, chat_id, reason=reason + '_recover'))
    await _v314_refresh_both(bot, chat_id, force_private=True)
    return False


async def _v314_live_on(bot, chat_id: int) -> None:
    await _v315_try_start_voice_and_first(bot, int(chat_id), reason='v315_live_on')


async def _v315_recovery_loop() -> None:
    while True:
        try:
            await asyncio.sleep(4)
            bot = VOICE.application.bot if VOICE.application else None
            if not bot:
                continue
            for chat_id, st in list(STATE_CACHE.items()):
                try:
                    if not _v314_valid_group(int(chat_id)):
                        continue
                    if not st.dj_mode or not st.live_enabled:
                        continue

                    if st.auto_track_enabled and st.queue and not st.now_playing:
                        await _v315_try_start_voice_and_first(bot, int(chat_id), reason='v315_auto_recovery')
                except Exception:
                    logger.exception('V315 recovery error chat=%s', chat_id)
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V315 recovery loop error')


async def _v315_group_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    data = q.data or ''
    if not (data == 'panel_control_take' or data in V315_GROUP_DJ_ACTIONS or data.startswith('panel_vol_set|')):
        return
    chat_id = int(update.effective_chat.id)
    if not _v314_valid_group(chat_id):
        return

    if data == 'panel_control_take':
        _v315_set_control_owner(chat_id, 'group')
        await q.answer('Control en mesa del grupo')
        await _v314_refresh_both(context.bot, chat_id, force_private=True)
        raise _V314Stop

    if _v315_should_block_group(chat_id, data):
        await q.answer('El control lo tiene DJPRO privado. Pulsa C para recuperarlo aquí.', show_alert=False)
        await ensure_control_panel(context.bot, chat_id)
        raise _V314Stop


    async with _v314_lock(chat_id):
        st = get_state(chat_id)
        if data in ('panel_live_toggle', 'panel_pause_resume'):
            if st.live_enabled:
                await q.answer('LIVE OFF')
                await _v314_live_off(context.bot, chat_id)
            else:
                await q.answer('LIVE ON')
                await _v315_try_start_voice_and_first(context.bot, chat_id, reason='group_live_on')
            raise _V314Stop

        if data == 'panel_next':
            if not st.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
            else:
                await q.answer('Siguiente')
                await _v314_play_next(context.bot, chat_id, reason='group_next')
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data == 'panel_auto_track':
            st.auto_track_enabled = not bool(st.auto_track_enabled)
            st.auto_sig_seconds = 0
            save_all_states()
            await q.answer('AUTO ' + ('ON' if st.auto_track_enabled else 'OFF'))
            if st.live_enabled and st.auto_track_enabled and st.queue and not st.now_playing:
                await _v315_try_start_voice_and_first(context.bot, chat_id, reason='group_auto_on')
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data == 'panel_shuffle':
            st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
            save_all_states()
            await q.answer('Aleatorio ' + ('ON' if st.dj_shuffle_enabled else 'OFF'))
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data.startswith('panel_vol_set|') or data in ('panel_vol_down', 'panel_vol_up'):
            if data == 'panel_vol_down':
                vol = await VOICE.change_volume(chat_id, -4)
            elif data == 'panel_vol_up':
                vol = await VOICE.change_volume(chat_id, 4)
            else:
                try:
                    vol = await VOICE.set_volume(chat_id, int(data.split('|', 1)[1]))
                except Exception:
                    vol = get_state(chat_id).volume
            await q.answer(f'Vol {vol}')
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data == 'panel_join_live':
            ok = False
            try:
                ok = bool(await VOICE.ensure_videochat_started(chat_id))
            except Exception:
                ok = False
            if ok:
                await q.answer('Videochat preparado')
            else:
                await q.answer('Abre el videochat manualmente desde el nombre del grupo.', show_alert=True)
                await _v315_send_manual_voice_hint(context.bot, chat_id)
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data == 'panel_refresh':
            await q.answer('')
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop

        if data == 'panel_close':
            await q.answer('Cerrando sesión')
            await close_dj_session(context.bot, chat_id)
            await _v314_refresh_both(context.bot, chat_id, force_private=True)
            raise _V314Stop


async def _v315_djpro_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V314Stop

    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'

    if action == 'control' and _v314_valid_group(chat_id):
        _v315_set_control_owner(chat_id, 'private')
        await q.answer('Control en DJPRO privado')
        await _v314_refresh_both(context.bot, int(chat_id), q=q, force_private=True)
        raise _V314Stop

    if _v314_valid_group(chat_id) and _v315_should_block_private(chat_id, action):
        await q.answer('El control lo tiene la mesa del grupo. Pulsa C para controlarlo desde privado.', show_alert=False)
        await _v314_edit_private(context.bot, int(chat_id), q=q, force=True)
        raise _V314Stop


    if _v314_valid_group(chat_id) and action == 'live':
        async with _v314_lock(int(chat_id)):
            st = get_state(int(chat_id))
            if st.live_enabled:
                await q.answer('LIVE OFF')
                await _v314_live_off(context.bot, int(chat_id))
            else:
                await q.answer('LIVE ON')
                await _v315_try_start_voice_and_first(context.bot, int(chat_id), reason='private_live_on')
            await _v314_edit_private(context.bot, int(chat_id), q=q, force=True)
        raise _V314Stop


    await _v314_djpro_router(update, context)
    raise _V314Stop


