    app = _old_build_application_v314_for_v315()
    app.add_handler(CallbackQueryHandler(_v315_group_panel_router, pattern=r'^(panel_control_take|panel_live_toggle|panel_pause_resume|panel_next|panel_prev|panel_auto_track|panel_shuffle|panel_auto_sig|panel_auto_next|panel_join_live|panel_refresh|panel_close|panel_minimize|panel_update_current_full|panel_vol_down|panel_vol_up|panel_vol_set\|.*|panel_likes|panel_announce_now)$'), group=-1000000001000)
