def _v316_parse_daily_phrase_buttons(raw: str) -> List[Dict[str, str]]:
    buttons: List[Dict[str, str]] = []
    for line in str(raw or '').splitlines():
        line = line.strip()
        if not line:
            continue
        if ' - ' in line:
            label, target = line.split(' - ', 1)
        elif '=' in line:
            label, target = line.split('=', 1)
        elif '|' in line:
            label, target = line.split('|', 1)
        else:
            continue
        label = label.strip()[:64]
        target = target.strip()[:500]
        if not label or not target:
            continue
        low = target.lower()
        if low.startswith(('cmd:', 'command:')) or target.startswith('/'):
            cmd = target.split(':', 1)[1] if ':' in target and not target.startswith('/') else target
            cmd = cmd.strip().lstrip('/').split()[0].lower()
            if cmd:
                buttons.append({'text': label, 'cmd': cmd})
            continue
        if target.startswith('t.me/'):
            target = 'https://' + target
        if target.startswith(('http://', 'https://', 'tg://')):
            buttons.append({'text': label, 'url': target})
    return buttons[:10]


def _v316_daily_phrase_extra_buttons(chat_id: int) -> List[List[InlineKeyboardButton]]:
    rows: List[List[InlineKeyboardButton]] = []
    raw = cfg_value(int(chat_id), 'daily_phrase_extra_buttons', []) if 'cfg_value' in globals() else []
    if not isinstance(raw, list):
        return rows
    for btn in raw[:10]:
        if not isinstance(btn, dict):
            continue
        text = str(btn.get('text') or '').strip()[:64]
        if not text:
            continue
        cmd = str(btn.get('cmd') or '').strip().lower().lstrip('/')
        target = str(btn.get('target') or '').strip()
        url = str(btn.get('url') or '').strip()
        if not cmd and target.lower().startswith(('cmd:', 'command:')):
            cmd = target.split(':', 1)[1].strip().lower().lstrip('/')
        if cmd:
            rows.append([InlineKeyboardButton(text, callback_data=f'reccmd|{int(chat_id)}|{cmd}')])
        elif url and url.startswith(('http://', 'https://', 'tg://')):
            rows.append([InlineKeyboardButton(text, url=url)])
    return rows


_v237_daily_phrase_extra_buttons = _v316_daily_phrase_extra_buttons


async def _v316_phrase_buttons_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_buttons|'):
        return
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V316Stop
    if 'set_config_pending' in globals():
        set_config_pending(q.from_user.id, {
            'kind': 'cfg_phrase_buttons_v316',
            'chat_id': chat_id,
            'return_block': 'daily_phrase',
        })
    await q.answer()
    current = cfg_value(chat_id, 'daily_phrase_extra_buttons', []) if 'cfg_value' in globals() else []
    current_lines: List[str] = []
    if isinstance(current, list):
        for btn in current:
            if not isinstance(btn, dict):
                continue
            text = str(btn.get('text') or '').strip()
            cmd = str(btn.get('cmd') or '').strip()
            url = str(btn.get('url') or '').strip()
            if text and cmd:
                current_lines.append(f'{text}=cmd:{cmd}')
            elif text and url:
                current_lines.append(f'{text} - {url}')
    current_txt = '\n'.join(current_lines) if current_lines else 'Sin botones extra configurados.'
    await q.edit_message_text(
        '⌨️ <b>Botones extra de Frase del día</b>\n\n'
        'La primera fila se mantiene así:\n'
        '💪 <b>Vitamina IA</b> + ❤️ <b>Me gusta</b>\n\n'
        'Los botones extra saldrán debajo, <b>uno por fila</b>.\n\n'
        '<b>Actual:</b>\n'
        f'<pre>{h(current_txt)}</pre>\n\n'
        'Envíame los nuevos botones, uno por línea:\n'
        '<code>Instagram - https://instagram.com/...</code>\n'
        '<code>Normas - https://t.me/...</code>\n'
        '<code>Hora=cmd:hora</code>\n'
        '<code>Tiempo=cmd:tiempo</code>\n'
        '<code>Reglas=cmd:reglas</code>\n\n'
        'Para borrar todos escribe <code>QUITAR</code>.',
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
    )
    raise _V316Stop


async def _v316_phrase_buttons_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not isinstance(pending, dict):
        return
    kind = str(pending.get('kind') or '')
    if kind not in ('cfg_phrase_buttons_v316', 'cfg_phrase_buttons_v291', 'cfg_phrase_buttons_v237', 'cfg_phrase_buttons_v301'):
        return
    try:
        chat_id = int(pending.get('chat_id') or pending.get('target_chat_id') or 0)
    except Exception:
        chat_id = 0
    if not chat_id:
        if 'pop_config_pending' in globals():
            pop_config_pending(update.effective_user.id)
        await update.message.reply_text('❌ No encuentro el grupo de destino. Entra de nuevo en Frase del día > Botones extra.')
        raise _V316Stop

    text = (update.message.text or update.message.caption or '').strip()
    if not text:
        await update.message.reply_html('❌ Envíame texto con el formato <code>Botón - https://enlace.com</code> o <code>Botón=cmd:comando</code>.')
        raise _V316Stop

    if text.upper() in ('QUITAR', 'BORRAR', 'SIN BOTONES', 'NO', 'OFF'):
        cfg_set(chat_id, 'daily_phrase_extra_buttons', [])
        saved_count = 0
    else:
        buttons = _v316_parse_daily_phrase_buttons(text)
        if not buttons:
            await update.message.reply_html(
                '❌ No he detectado botones válidos.\n\n'
                'Usa uno por línea, por ejemplo:\n'
                '<code>Instagram - https://instagram.com/...</code>\n'
                '<code>Hora=cmd:hora</code>\n'
                '<code>Reglas=cmd:reglas</code>'
            )
            raise _V316Stop
        cfg_set(chat_id, 'daily_phrase_extra_buttons', buttons)
        saved_count = len(buttons)

    if 'pop_config_pending' in globals():
        pop_config_pending(update.effective_user.id)
    if 'save_all_states' in globals():
        save_all_states()
    await update.message.reply_html(
        f'✅ Botones extra actualizados: <b>{saved_count}</b>.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'),
        reply_markup=admin_private_block_markup(chat_id, 'daily_phrase')
    )
    raise _V316Stop


_old_build_application_v315_base_v316 = build_application

def build_application() -> Application:
    app = _old_build_application_v315_base_v316()
    app.add_handler(CallbackQueryHandler(_v316_phrase_buttons_callback, pattern=r'^cfg\|phrase_buttons\|'), group=-999999999)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v316_phrase_buttons_text), group=-999999999)
    logger.info('V316 cargado: corregido guardado de botones extra en Frase del día')
    return app


