def _v317_jm_parts(phrase: str) -> Tuple[bool, str]:
    raw = str(phrase or '').strip()
    is_jm = False
    try:
        if '_v150_has_jm' in globals():
            is_jm = bool(_v150_has_jm(raw))
        elif '_v127_is_jm_phrase' in globals():
            is_jm = bool(_v127_is_jm_phrase(raw))
        else:
            is_jm = bool(re.search(r'(?i)j\s*\.?\s*m\s*\.?', raw))
    except Exception:
        is_jm = bool(re.search(r'(?i)j\s*\.?\s*m\s*\.?', raw))
    if is_jm:
        try:
            raw = _v150_clean_jm_from_phrase(raw) if '_v150_clean_jm_from_phrase' in globals() else re.sub(r'(?i)\s*[-–—]?\s*j\s*\.?\s*m\s*\.?\s*$', '', raw).strip()
        except Exception:
            raw = re.sub(r'(?i)\s*[-–—]?\s*j\s*\.?\s*m\s*\.?\s*$', '', raw).strip()
    return is_jm, raw.strip().strip('“”"').strip()


def _v317_phrase_caption(chat_id: int, phrase: str) -> str:
    title = str(cfg_value(int(chat_id), 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')

    header = h(title)
    try:
        if '_v284_current_date_header' in globals():
            header = h(_v284_current_date_header())
    except Exception:
        pass
    is_jm, body = _v317_jm_parts(phrase)
    stars_top = '✨✨\n' if is_jm else ''
    stars_bottom = '\n✨✨' if is_jm else ''
    likes = 0
    try:
        if '_v200_like_count' in globals():
            likes = _v200_like_count(int(chat_id), phrase)
        elif '_v114_phrase_likes_count' in globals():
            likes = _v114_phrase_likes_count(int(chat_id), phrase)
    except Exception:
        likes = 0
    extra = str(cfg_value(int(chat_id), 'daily_phrase_extra_text', '') or '').strip()
    extra_html = f"\n\n{h(extra)}" if extra else ''
    return (f"<b>{header}</b>\n\n"
            f"{stars_top}<b><i>“{h(body)}”</i></b>{stars_bottom}"
            f"{extra_html}\n\n❤️ Me gusta: <b>{likes}</b>")[:1024]


