_old_admin_private_block_text_v317 = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:
    txt = _old_admin_private_block_text_v317(int(chat_id), block, page)
    if block == 'daily_phrase':
        extra = str(cfg_value(int(chat_id), 'daily_phrase_extra_text', '') or '').strip()
        manual = str(cfg_value(int(chat_id), 'daily_phrase_manual_current', '') or '').strip()
        buttons = cfg_value(int(chat_id), 'daily_phrase_extra_buttons', [])
        n = len(buttons) if isinstance(buttons, list) else 0
        txt = txt.rstrip()
        txt += (
            '\n\n<b>Edición actual</b>\n'
            f"Frase manual: <b>{'Sí' if manual else 'No'}</b>\n"
            f"Texto extra: <b>{'Sí' if extra else 'No'}</b>\n"
            f"Botones extra: <b>{n}</b>"
        )
        if extra:
            prev = extra.replace('\n', ' ')
            if len(prev) > 160:
                prev = prev[:157] + '…'
            txt += f"\nTexto extra actual:\n<pre>{h(prev)}</pre>"
    return txt


_old_admin_private_block_markup_v317 = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:
    markup = _old_admin_private_block_markup_v317(int(chat_id), block, page)
    if block != 'daily_phrase':
        return markup
    rows = [list(row) for row in (getattr(markup, 'inline_keyboard', []) or [])]

    flat_cd = {getattr(btn, 'callback_data', '') for row in rows for btn in row}
    insert_at = max(0, len(rows) - 1)
    new_rows: List[List[InlineKeyboardButton]] = []
    if not any(str(cd).startswith(f'cfg|phrase_buttons|{int(chat_id)}') for cd in flat_cd):
        new_rows.append([InlineKeyboardButton('⌨️ Botones extra', callback_data=f'cfg|phrase_buttons|{int(chat_id)}|daily_phrase')])
    if not any(str(cd).startswith(f'cfg|phrase_extra_text|{int(chat_id)}') for cd in flat_cd):
        new_rows.append([InlineKeyboardButton('➕ Texto extra actual', callback_data=f'cfg|phrase_extra_text|{int(chat_id)}|daily_phrase')])
    if not any(str(cd).startswith(f'cfg|phrase_manual_edit|{int(chat_id)}') for cd in flat_cd):
        new_rows.append([InlineKeyboardButton('✏️ Editar frase actual', callback_data=f'cfg|phrase_manual_edit|{int(chat_id)}|daily_phrase')])
    if new_rows:
        rows = rows[:insert_at] + new_rows + rows[insert_at:]
    return InlineKeyboardMarkup(rows)


async def _v317_phrase_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not (data.startswith('cfg|phrase_buttons|') or data.startswith('cfg|phrase_extra_text|') or data.startswith('cfg|phrase_manual_edit|')):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V317Stop
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V317Stop

    if action == 'phrase_buttons':
        set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_buttons_v317', 'chat_id': chat_id, 'return_block': 'daily_phrase'})
        current = cfg_value(chat_id, 'daily_phrase_extra_buttons', [])
        lines: List[str] = []
        if isinstance(current, list):
            for btn in current:
                if not isinstance(btn, dict):
                    continue
                text = str(btn.get('text') or '').strip()
                cmd = str(btn.get('cmd') or '').strip()
                url = str(btn.get('url') or '').strip()
                if text and cmd:
                    lines.append(f'{text}=cmd:{cmd}')
                elif text and url:
                    lines.append(f'{text} - {url}')
        current_txt = '\n'.join(lines) if lines else 'Sin botones extra configurados.'
        await q.answer()
        await q.edit_message_text(
            '⌨️ <b>Botones extra de Frase del día</b>\n\n'
            'La primera fila se mantiene:\n💪 <b>Vitamina IA</b> + ❤️ <b>Me gusta</b>\n\n'
            'Los botones extra saldrán debajo, <b>uno por fila</b>.\n\n'
            '<b>Actual:</b>\n'
            f'<pre>{h(current_txt)}</pre>\n\n'
            'Envíame los botones, uno por línea:\n'
            '<code>Instagram - https://instagram.com/...</code>\n'
            '<code>Normas - https://t.me/...</code>\n'
            '<code>Hora=cmd:hora</code>\n'
            '<code>Tiempo=cmd:tiempo</code>\n'
            '<code>Reglas=cmd:reglas</code>\n\n'
            'Para borrar todos escribe <code>QUITAR</code>.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
        )
        raise _V317Stop

    if action == 'phrase_extra_text':
        set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_extra_text_v317', 'chat_id': chat_id, 'return_block': 'daily_phrase'})
        current = str(cfg_value(chat_id, 'daily_phrase_extra_text', '') or '').strip()
        await q.answer()
        await q.edit_message_text(
            '➕ <b>Texto extra de la Frase del día</b>\n\n'
            'Este texto se mostrará debajo de la frase, además de la cita.\n\n'
            '<b>Actual:</b>\n'
            f'<pre>{h(current or "Sin texto extra")}</pre>\n\n'
            'Envíame el texto extra. Para quitarlo escribe <code>QUITAR</code>.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
        )
        raise _V317Stop

    if action == 'phrase_manual_edit':
        set_config_pending(q.from_user.id, {'kind': 'cfg_phrase_manual_current_v317', 'chat_id': chat_id, 'return_block': 'daily_phrase'})
        current = daily_phrase_for_chat_v30(chat_id) if 'daily_phrase_for_chat_v30' in globals() else daily_phrase_for_date_v15()
        await q.answer()
        await q.edit_message_text(
            '✏️ <b>Editar frase actual</b>\n\n'
            'Esta frase quedará fijada como frase actual hasta que actives rotación automática o la cambies.\n\n'
            '<b>Actual:</b>\n'
            f'<pre>{h(current)}</pre>\n\n'
            'Envíame la nueva frase. Para volver a rotación automática escribe <code>AUTO</code>.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cancelar', callback_data=f'cfg|block|{chat_id}|daily_phrase')]])
        )
        raise _V317Stop


async def _v317_phrase_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    if update.effective_chat and update.effective_chat.type != 'private':
        return
    pending = get_config_pending(update.effective_user.id) if 'get_config_pending' in globals() else None
    if not isinstance(pending, dict):
        return
    kind = str(pending.get('kind') or '')
    if kind not in ('cfg_phrase_buttons_v317', 'cfg_phrase_buttons_v316', 'cfg_phrase_buttons_v291', 'cfg_phrase_buttons_v237', 'cfg_phrase_extra_text_v317', 'cfg_phrase_manual_current_v317'):
        return
    try:
        chat_id = int(pending.get('chat_id') or pending.get('target_chat_id') or 0)
    except Exception:
        chat_id = 0
    if not chat_id:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_text('❌ No encuentro el grupo de destino. Entra de nuevo en Frase del día.')
        raise _V317Stop
    if not is_global_admin_user(update.effective_user.id):
        pop_config_pending(update.effective_user.id)
        await update.message.reply_text('Solo ADMIN_IDS puede editar la frase del día.')
        raise _V317Stop

    text = (update.message.text or update.message.caption or '').strip()
    html_text = telegram_html_from_message(update.message).strip() if 'telegram_html_from_message' in globals() else h(text)
    if not text:
        await update.message.reply_html('❌ Envíame texto válido.')
        raise _V317Stop

    upper = text.upper().strip()
    if kind.startswith('cfg_phrase_buttons'):
        if upper in ('QUITAR', 'BORRAR', 'SIN BOTONES', 'NO', 'OFF'):
            cfg_set(chat_id, 'daily_phrase_extra_buttons', [])
            saved_count = 0
        else:
            buttons = _v317_parse_daily_phrase_buttons(text)
            if not buttons:
                await update.message.reply_html(
                    '❌ No he detectado botones válidos.\n\n'
                    'Usa uno por línea:\n'
                    '<code>Instagram - https://instagram.com/...</code>\n'
                    '<code>Hora=cmd:hora</code>\n'
                    '<code>Reglas=cmd:reglas</code>'
                )
                raise _V317Stop
            cfg_set(chat_id, 'daily_phrase_extra_buttons', buttons)
            saved_count = len(buttons)
        pop_config_pending(update.effective_user.id)
        save_all_states()
        await update.message.reply_html(
            f'✅ Botones extra actualizados: <b>{saved_count}</b>.\n\n' + admin_private_block_text(chat_id, 'daily_phrase'),
            reply_markup=admin_private_block_markup(chat_id, 'daily_phrase')
        )
        raise _V317Stop

    if kind == 'cfg_phrase_extra_text_v317':
        if upper in ('QUITAR', 'BORRAR', 'SIN TEXTO', 'NO', 'OFF'):
            cfg_set(chat_id, 'daily_phrase_extra_text', '')
            msg = '✅ Texto extra quitado.'
        else:
            cfg_set(chat_id, 'daily_phrase_extra_text', html_text[:700])
            msg = '✅ Texto extra guardado.'
        pop_config_pending(update.effective_user.id)
        save_all_states()
        await update.message.reply_html(msg + '\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        raise _V317Stop

    if kind == 'cfg_phrase_manual_current_v317':
        if upper in ('AUTO', 'AUTOMATICO', 'AUTOMÁTICO', 'ROTACION', 'ROTACIÓN'):
            cfg_set(chat_id, 'daily_phrase_manual_current', '')
            msg = '✅ Rotación automática activada.'
        else:
            cfg_set(chat_id, 'daily_phrase_manual_current', html_text[:700])
            msg = '✅ Frase actual guardada.'
        pop_config_pending(update.effective_user.id)
        save_all_states()
        await update.message.reply_html(msg + '\n\n' + admin_private_block_text(chat_id, 'daily_phrase'), reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        raise _V317Stop


