try:
    from telegram.ext import ApplicationHandlerStop as _V318Stop
except Exception:
    _V318Stop = Exception


def _v318_phrase_now_ts() -> int:
    try:
        return int(time.time())
    except Exception:
        return int(__import__('time').time())


def _v318_chat_ids() -> List[int]:
    ids: set[int] = set()
    try:
        for cid in STATE_CACHE.keys():
            try:
                cid_i = int(cid)
                if cid_i < 0:
                    ids.add(cid_i)
            except Exception:
                continue
    except Exception:
        pass
    try:
        if 'known_admin_chats_for_private' in globals():
            for cid in known_admin_chats_for_private():
                try:
                    cid_i = int(cid)
                    if cid_i < 0:
                        ids.add(cid_i)
                except Exception:
                    continue
    except Exception:
        pass
    return sorted(ids)


def _v318_phrase_text(chat_id: int, now_ts: Optional[int] = None) -> str:
    cfg = admin_cfg(int(chat_id))
    manual = str(cfg.get('daily_phrase_manual_current') or '').strip()
    if manual:
        return manual
    try:
        if '_v199_daily_phrase_text' in globals():
            txt = str(_v199_daily_phrase_text(int(chat_id), int(now_ts or _v318_phrase_now_ts())) or '').strip()
            if txt:
                return txt
    except Exception:
        logger.exception('V318 no pudo obtener frase con _v199_daily_phrase_text')
    try:
        txt = str(daily_phrase_for_chat_v30(int(chat_id), int(now_ts or _v318_phrase_now_ts())) or '').strip()
        if txt:
            return txt
    except Exception:
        pass
    try:
        txt = str(daily_phrase_for_date_v15(int(now_ts or _v318_phrase_now_ts())) or '').strip()
        if txt:
            return txt
    except Exception:
        pass
    return 'Hoy es un buen día para tener un gran día. — J.M.'


async def _v318_send_media_or_text(bot, chat_id: int, caption: str, image: Optional[Dict[str, Any]]) -> Any:
    """Envía frase con multimedia si existe. Si falla, cae a texto sin romper."""
    if isinstance(image, dict) and image.get('file_id'):
        mtype = str(image.get('type') or 'photo').lower()
        fid = image.get('file_id')
        try:
            if mtype == 'video':
                return await bot.send_video(chat_id, video=fid, caption=caption, parse_mode=ParseMode.HTML)
            if mtype in ('animation', 'gif'):
                return await bot.send_animation(chat_id, animation=fid, caption=caption, parse_mode=ParseMode.HTML)
            if mtype == 'document':
                return await bot.send_document(chat_id, document=fid, caption=caption, parse_mode=ParseMode.HTML)
            return await bot.send_photo(chat_id, photo=fid, caption=caption, parse_mode=ParseMode.HTML)
        except Exception:
            logger.exception('V318 envío frase con multimedia falló; cae a texto')
    try:
        return await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        logger.exception('V318 envío frase HTML falló; cae a texto plano')

        plain = re.sub(r'<[^>]+>', '', str(caption or '')) if '_re_v7' not in globals() else _re_v7.sub(r'<[^>]+>', '', str(caption or ''))
        return await bot.send_message(chat_id, plain[:3900], disable_web_page_preview=True)


async def _v318_send_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False, phrase: Optional[str] = None) -> Optional[int]:
    """Ruta única y final para publicar Frase del día.

    - Respeta imagen configurada.
    - Respeta Vitamina IA + Me gusta.
    - Respeta botones extra uno por fila.
    - Respeta texto extra y frase manual.
    - Registra la frase para likes/vitamina.
    - Fija si está configurado.
    """
    chat_id = int(chat_id)
    cfg = admin_cfg(chat_id)
    now_ts = int(now_ts or _v318_phrase_now_ts())
    phrase = str(phrase or _v318_phrase_text(chat_id, now_ts)).strip()
    if not phrase:
        phrase = 'Hoy es un buen día para tener un gran día. — J.M.'

    try:
        caption = _v317_phrase_caption(chat_id, phrase) if '_v317_phrase_caption' in globals() else _v200_phrase_caption(chat_id, phrase)
    except Exception:
        title = str(cfg.get('daily_phrase_title') or '🌞 Frase del día')
        caption = f'<b>{h(title)}</b>\n\n<b><i>“{h(phrase)}”</i></b>'


    if len(caption) > 1024:
        caption = caption[:1018] + '…'

    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    if not bool(cfg.get('daily_phrase_image_enabled', True)):
        image = None

    msg = await _v318_send_media_or_text(bot, chat_id, caption, image)
    mid = int(getattr(msg, 'message_id', 0) or 0)
    if not mid:
        return None

    try:
        await register_bot_message(chat_id, mid)
    except Exception:
        pass

    try:
        store = _v114_sent_store(chat_id) if '_v114_sent_store' in globals() else cfg.setdefault('daily_phrase_sent_messages', {})
        kind = 'photo' if getattr(msg, 'photo', None) else 'video' if getattr(msg, 'video', None) else 'document' if getattr(msg, 'document', None) else 'text'
        store[str(mid)] = {'phrase': phrase, 'kind': kind, 'next_used': [], 'sent_ts': now_ts}
        save_all_states()
    except Exception:
        logger.exception('V318 no pudo registrar frase enviada')

    try:
        markup = _v317_phrase_markup(chat_id, mid, phrase) if '_v317_phrase_markup' in globals() else _v197_phrase_markup(chat_id, mid)
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=mid, reply_markup=markup)
    except Exception:
        logger.exception('V318 no pudo poner botones de frase')

    if bool(cfg.get('daily_phrase_pin', False)):
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=mid, disable_notification=True)
        except Exception:
            pass
    return mid


async def _v199_send_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False, phrase: Optional[str] = None) -> Optional[int]:
    return await _v318_send_phrase(bot, int(chat_id), now_ts=now_ts, force=force, phrase=phrase)


async def _v197_send_phrase_text(bot, chat_id: int, phrase: str) -> Optional[int]:
    return await _v318_send_phrase(bot, int(chat_id), now_ts=_v318_phrase_now_ts(), force=True, phrase=phrase)


async def _v189_send_daily_phrase(bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> Optional[int]:
    now_ts = int(now_ts or _v318_phrase_now_ts())
    mid = await _v318_send_phrase(bot, int(chat_id), now_ts=now_ts, force=force)
    if mid:
        try:
            cfg = admin_cfg(int(chat_id))
            if '_v199_slot_key' in globals():
                _due, slot, _reason = _v199_slot_key(int(chat_id), now_ts)
                if slot:
                    cfg['daily_phrase_last_key'] = slot
                else:
                    cfg['daily_phrase_last_key'] = _local_day_key_v15(now_ts) if '_local_day_key_v15' in globals() else time.strftime('%Y-%m-%d', time.localtime(now_ts))
            else:
                cfg['daily_phrase_last_key'] = _local_day_key_v15(now_ts) if '_local_day_key_v15' in globals() else time.strftime('%Y-%m-%d', time.localtime(now_ts))
            cfg['daily_phrase_last_sent_ts'] = now_ts
            cfg['daily_phrase_sending_key'] = ''
            save_all_states()
        except Exception:
            logger.exception('V318 no pudo marcar frase programada enviada')
    return mid


async def daily_phrase_maybe_send(application: Application, chat_id: int, now_ts: int) -> None:
    chat_id = int(chat_id)
    cfg = admin_cfg(chat_id)
    if not bool(cfg.get('daily_phrase_enabled', False)):
        return
    if '_v199_slot_key' in globals():
        due, slot, reason = _v199_slot_key(chat_id, int(now_ts))
    else:
        due = daily_phrase_due(chat_id, int(now_ts)) if 'daily_phrase_due' in globals() else False
        slot = _local_day_key_v15(now_ts) if '_local_day_key_v15' in globals() else time.strftime('%Y-%m-%d', time.localtime(now_ts))
        reason = 'daily'
    if not due or not slot:
        return
    if str(cfg.get('daily_phrase_last_key') or '') == str(slot):
        return
    if str(cfg.get('daily_phrase_sending_key') or '') == str(slot):
        return
    cfg['daily_phrase_sending_key'] = str(slot)
    save_all_states()
    try:
        mid = await _v318_send_phrase(application.bot, chat_id, now_ts=int(now_ts), force=False)
        if mid:
            cfg['daily_phrase_last_key'] = str(slot)
            cfg['daily_phrase_last_sent_ts'] = int(now_ts)
            logger.info('V318 frase programada enviada chat=%s slot=%s reason=%s', chat_id, slot, reason)
    except Exception:
        logger.exception('V318 frase programada falló chat=%s', chat_id)

    finally:
        cfg['daily_phrase_sending_key'] = ''
        save_all_states()


async def _v318_scheduler_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = _v318_phrase_now_ts()
    for chat_id in _v318_chat_ids():
        try:
            await daily_phrase_maybe_send(context.application, int(chat_id), now)
        except Exception:
            logger.exception('V318 scheduler frase error chat=%s', chat_id)
        await asyncio.sleep(0.05)


async def _v318_phrase_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_send|'):
        return
    try:
        chat_id = int((q.data or '').split('|')[2])
    except Exception:
        await q.answer('Grupo inválido.', show_alert=True)
        raise _V318Stop
    if not is_global_admin_user(q.from_user.id):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V318Stop
    try:
        await q.answer('Enviando frase…')
    except Exception:
        pass
    before = {k: admin_cfg(chat_id).get(k) for k in ('daily_phrase_last_key', 'daily_phrase_last_sent_ts', 'daily_phrase_sending_key')}
    try:
        mid = await _v318_send_phrase(context.bot, chat_id, now_ts=_v318_phrase_now_ts(), force=True)

        cfg = admin_cfg(chat_id)
        for k, v in before.items():
            if v is None:
                cfg.pop(k, None)
            else:
                cfg[k] = v
        cfg['daily_phrase_sending_key'] = ''
        save_all_states()
        if not mid:
            await q.answer('No se pudo enviar la frase.', show_alert=True)
        else:
            await q.answer('Frase enviada ✅')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        except Exception:
            pass
    except Exception:
        logger.exception('V318 enviar frase manual falló')
        try:
            await q.answer('No pude enviar frase. Mira logs.', show_alert=True)
        except Exception:
            pass
    raise _V318Stop


async def daily_phrase_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    await _v318_send_phrase(context.bot, chat_id, now_ts=_v318_phrase_now_ts(), force=True)


