_V320_WEEKDAYS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo']
_V320_MONTHS = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre']


def _v320_date_header(now_ts: Optional[int] = None) -> str:
    import time as _time
    ts = int(now_ts or _time.time())
    lt = _time.localtime(ts)
    day_name = _V320_WEEKDAYS[lt.tm_wday].capitalize()
    month_name = _V320_MONTHS[lt.tm_mon - 1]
    return f'{day_name}, {lt.tm_mday} de {month_name} de {lt.tm_year}'


def _v284_current_date_header(now_ts: Optional[int] = None) -> str:
    return _v320_date_header(now_ts)


def _v317_phrase_caption(chat_id: int, phrase: str) -> str:
    header = h(_v320_date_header())
    is_jm, body = _v317_jm_parts(phrase) if '_v317_jm_parts' in globals() else (False, str(phrase or '').strip())
    stars_top = '✨✨\n' if is_jm else ''
    stars_bottom = '\n✨✨' if is_jm else ''
    likes = 0
    try:
        if '_v200_like_count' in globals():
            likes = _v200_like_count(int(chat_id), phrase)
        elif '_v114_phrase_likes_count' in globals():
            likes = _v114_phrase_likes_count(int(chat_id), phrase)
    except Exception:
        likes = 0
    extra = str(cfg_value(int(chat_id), 'daily_phrase_extra_text', '') or '').strip() if 'cfg_value' in globals() else ''
    extra_html = f"\n\n{h(extra)}" if extra else ''
    return (f"<b>{header}</b>\n\n"
            f"{stars_top}<b><i>“{h(body)}”</i></b>{stars_bottom}"
            f"{extra_html}\n\n❤️ Me gusta: <b>{likes}</b>")[:1024]


def _v200_phrase_caption(chat_id: int, phrase: str) -> str:
    return _v317_phrase_caption(int(chat_id), phrase)


def _v114_phrase_caption(chat_id: int, phrase: str) -> str:
    return _v317_phrase_caption(int(chat_id), phrase)


def _v320_norm(s: str) -> str:
    import unicodedata, re as _re
    raw = str(s or '').strip().lower()
    raw = ''.join(c for c in unicodedata.normalize('NFD', raw) if unicodedata.category(c) != 'Mn')
    return _re.sub(r'[^a-z0-9]+', '', raw)


def _v320_all_blocks(chat_id: int) -> List[Dict[str, Any]]:
    try:
        return list(_v171_rec_blocks(int(chat_id))) if '_v171_rec_blocks' in globals() else []
    except Exception:
        return []


def _v320_block_by_token(chat_id: int, token: str) -> Optional[Dict[str, Any]]:
    token_raw = str(token or '').strip().lower().lstrip('/')
    if not token_raw:
        return None
    import re as _re

    m = _re.search(r'(?:bloque|block|rblk|rb|b)[_\-\s]*(\d+)$', token_raw)
    if not m and token_raw.isdigit():
        m = _re.match(r'^(\d+)$', token_raw)
    if m:
        bid = int(m.group(1))
        try:
            return _v171_rec_block_find(int(chat_id), bid)
        except Exception:
            return None
    wanted = _v320_norm(token_raw.replace('bloque', '').replace('block', '').replace('rblk', ''))
    if not wanted:
        return None
    for b in _v320_all_blocks(int(chat_id)):
        name = _v320_norm(str(b.get('name') or f'bloque{b.get("id", "")}'))
        if wanted == name or wanted == _v320_norm(f'bloque{b.get("id", "")}'):
            return b
    return None


def _v320_blocks_help(chat_id: int) -> str:
    blocks = _v320_all_blocks(int(chat_id))
    lines = ['<b>📦 Comandos de bloques recurrentes</b>', '']
    if not blocks:
        lines.append('No hay bloques recurrentes creados todavía.')
    else:
        lines.append('Puedes lanzar cada bloque con estos comandos:')
        lines.append('')
        for b in blocks:
            try:
                bid = int(b.get('id', 0) or 0)
            except Exception:
                bid = 0
            if not bid:
                continue
            name = str(b.get('name') or f'Bloque {bid}')
            items = b.get('items') or []
            lines.append(f'• <code>/bloque{bid}</code> — <b>{h(name)}</b> · {len(items)} recurrentes')
    lines.extend(['', 'También puedes usar:', '<code>/bloque 1</code>', '<code>/bloques</code> para ver esta lista.', '', 'En botones:', '<code>Plan=cmd:bloque1</code>'])
    return '\n'.join(lines)


async def _v320_send_block_by_command(context: ContextTypes.DEFAULT_TYPE, chat_id: int, block: Dict[str, Any]) -> tuple[int, int, List[str]]:
    bid = int(block.get('id', 0) or 0)
    if '_v267_send_block' in globals():
        return await _v267_send_block(context, int(chat_id), int(bid))
    if '_v181_send_rec_block' in globals():
        return await _v181_send_rec_block(context, int(chat_id), int(bid))

    ok = 0; total = 0; errors: List[str] = []
    for rid in [int(x) for x in (block.get('items') or []) if str(x).isdigit()]:
        total += 1
        row = recurring_find(int(chat_id), rid) if 'recurring_find' in globals() else None
        if row:
            try:
                await send_recurring_message(context, int(chat_id), dict(row))
                ok += 1
            except Exception as e:
                errors.append(str(e)[:120])
    return ok, total, errors


async def _v320_rblk_command_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_chat or not update.effective_user:
        return
    txt = (update.message.text or '').strip()
    if not txt.startswith('/'):
        return
    cmd_full = txt.split()[0].split('@')[0].lstrip('/').lower()
    args = txt.split()[1:]
    if not (cmd_full in ('bloques', 'blocks', 'rblks') or cmd_full.startswith(('bloque', 'block', 'rblk', 'rb'))):
        return
    chat_id = int(update.effective_chat.id)

    if chat_id > 0:
        candidates = _v318_chat_ids() if '_v318_chat_ids' in globals() else []
        if len(candidates) == 1:
            chat_id = int(candidates[0])
        else:
            await update.message.reply_html('📦 Usa este comando dentro del grupo, o deja solo un grupo configurado para poder lanzarlo desde privado.')
            raise _V320Stop
    try:
        allowed = await is_admin(context, chat_id, int(update.effective_user.id)) if 'is_admin' in globals() else is_global_admin_user(int(update.effective_user.id))
    except Exception:
        allowed = is_global_admin_user(int(update.effective_user.id)) if 'is_global_admin_user' in globals() else False
    if not allowed:
        await update.message.reply_text('Solo administradores.')
        raise _V320Stop
    if cmd_full in ('bloques', 'blocks', 'rblks'):
        await update.message.reply_html(_v320_blocks_help(chat_id))
        raise _V320Stop
    token = cmd_full
    if args and cmd_full in ('bloque', 'block', 'rblk', 'rb'):
        token = args[0]
    block = _v320_block_by_token(chat_id, token)
    if not block:
        await update.message.reply_html('❌ No encuentro ese bloque.\n\n' + _v320_blocks_help(chat_id))
        raise _V320Stop
    ok, total, errors = await _v320_send_block_by_command(context, chat_id, block)
    name = str(block.get('name') or f'Bloque {block.get("id", "") or ""}')
    await update.message.reply_html(f'📦 Bloque lanzado: <b>{h(name)}</b> · <b>{ok}/{total}</b> enviados')
    raise _V320Stop


async def _v320_reccmd_blocks_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').replace('command:', '').strip()
    if not (cmd in ('bloques', 'blocks', 'rblks') or cmd.startswith(('bloque', 'block', 'rblk', 'rb'))):
        return
    if cmd in ('bloques', 'blocks', 'rblks'):
        await q.answer()
        try:
            await q.message.reply_html(_v320_blocks_help(chat_id))
        except Exception:
            pass
        raise _V320Stop
    block = _v320_block_by_token(chat_id, cmd)
    if not block:
        await q.answer('No encuentro ese bloque.', show_alert=True)
        raise _V320Stop
    await q.answer('Lanzando bloque…')
    ok, total, errors = await _v320_send_block_by_command(context, chat_id, block)
    try:
        await q.message.reply_html(f'📦 Bloque lanzado: <b>{h(str(block.get("name") or "Bloque"))}</b> · <b>{ok}/{total}</b>')
    except Exception:
        pass
    raise _V320Stop


