def control_panel_markup(state: ChatState) -> InlineKeyboardMarkup:
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), 0)
        base = _old_control_panel_markup_v320(state)
        rows = [list(row) for row in getattr(base, 'inline_keyboard', [])]
        if not int(chat_id):
            return base

        clean: List[List[InlineKeyboardButton]] = []
        for row in rows:
            new_row = [btn for btn in row if str(getattr(btn, 'callback_data', '') or '') != 'panel_control_take']
            if new_row:
                clean.append(new_row)
        cbtn = InlineKeyboardButton(_v315_control_label(int(chat_id), 'group'), callback_data='panel_control_take')
        placed = False

        for row in clean:
            if any('like' in str(getattr(btn, 'callback_data', '') or '').lower() or '❤️' in str(getattr(btn, 'text', '') or '') for btn in row):
                row.insert(0, cbtn)
                placed = True
                break
        if not placed:

            if clean:
                clean[0].insert(0, cbtn)
            else:
                clean.append([cbtn])
        return InlineKeyboardMarkup(clean)
    except Exception:
        return _old_control_panel_markup_v320(state)


