        [InlineKeyboardButton('🔉-4', callback_data=f'djpropriv|{chat_id}|voldown4'), InlineKeyboardButton('🔊+4', callback_data=f'djpropriv|{chat_id}|volup4'), InlineKeyboardButton('🔇0', callback_data=f'djpropriv|{chat_id}|vol0'), InlineKeyboardButton('🔈25', callback_data=f'djpropriv|{chat_id}|vol25'), InlineKeyboardButton('🔊75', callback_data=f'djpropriv|{chat_id}|vol75')],
