BOT_VERSION = "V321"

try:
    from telegram.ext import ApplicationHandlerStop as _V321Stop
except Exception:
    class _V321Stop(Exception):
        pass

V321_AUTO_TASK: Optional[asyncio.Task] = None
V321_AUTO_RUNTIME: Dict[int, Dict[str, Any]] = {}
V321_TICK_SECONDS = 2
V321_MIN_ADVANCE_GAP = 3


def _v321_track_token(data: Optional[Dict[str, Any]]) -> str:
    if not data:
        return ''
    try:
        return track_key(data)
    except Exception:
        return str(data.get('file_unique_id') or data.get('file_id') or data.get('title') or '')


def _v321_track_duration(data: Optional[Dict[str, Any]]) -> int:
    if not data:
        return 0
    try:
        return max(0, int(data.get('duration') or 0))
    except Exception:
        return 0


def _v321_elapsed_seconds(st: ChatState) -> int:
    try:
        if not st.play_started_at:
            return 0
        return max(0, int(__import__('time').time() - int(st.play_started_at)))
    except Exception:
        return 0


def _v321_remaining_seconds(st: ChatState) -> Optional[int]:
    try:
        rem = remaining_seconds(st)
        if rem is not None:
            return int(rem)
    except Exception:
        pass
    dur = _v321_track_duration(st.now_playing if st.now_playing else None)
    if dur > 0:
        return max(0, dur - _v321_elapsed_seconds(st))
    return None


async def _v321_auto_advance_one(bot, chat_id: int, *, reason: str) -> bool:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    if not getattr(st, 'live_enabled', False):
        return False
    if not getattr(st, 'auto_track_enabled', False):
        return False
    if not st.queue:
        return False
    now = __import__('time').time()
    rt = V321_AUTO_RUNTIME.setdefault(chat_id, {})
    if now - float(rt.get('last_advance_at', 0.0) or 0.0) < V321_MIN_ADVANCE_GAP:
        return False
    rt['last_advance_at'] = now
    logger.info('V321 autoavance chat=%s reason=%s now=%s queue=%s', chat_id, reason, _v321_track_token(st.now_playing), len(st.queue))
    try:
        if '_v314_play_next' in globals():
            ok = await _v314_play_next(bot, chat_id, reason='v321_' + reason)
        elif hasattr(VOICE, 'play_next_from_queue'):
            await VOICE.play_next_from_queue(chat_id)
            ok = True
        else:
            ok = False
        try:
            await _v314_refresh_both(bot, chat_id, force_private=True)
        except Exception:
            try:
                await ensure_panel(bot, chat_id)
                await ensure_control_panel(bot, chat_id)
            except Exception:
                pass
        return bool(ok)
    except Exception:
        logger.exception('V321 fallo autoavance chat=%s reason=%s', chat_id, reason)
        return False


async def _v321_auto_loop() -> None:
    while True:
        try:
            await asyncio.sleep(V321_TICK_SECONDS)
            bot = VOICE.application.bot if VOICE.application else None
            if not bot:
                continue
            for chat_id, st in list(STATE_CACHE.items()):
                try:
                    chat_id = int(chat_id)
                    if '_v314_valid_group' in globals() and not _v314_valid_group(chat_id):
                        continue
                    if not getattr(st, 'dj_mode', False):
                        continue
                    if not getattr(st, 'live_enabled', False):
                        continue
                    if not getattr(st, 'auto_track_enabled', False):
                        continue
                    if not st.queue:
                        continue

                    rt = V321_AUTO_RUNTIME.setdefault(chat_id, {})
                    token = _v321_track_token(st.now_playing)
                    if rt.get('token') != token:
                        rt['token'] = token
                        rt['zero_hits'] = 0


                    if not st.now_playing:
                        await _v321_auto_advance_one(bot, chat_id, reason='idle_no_now_playing')
                        continue


                    rem = _v321_remaining_seconds(st)
                    if rem is not None:
                        if rem <= 1:
                            rt['zero_hits'] = int(rt.get('zero_hits', 0) or 0) + 1
                        else:
                            rt['zero_hits'] = 0

                        if int(rt.get('zero_hits', 0) or 0) >= 2:
                            await _v321_auto_advance_one(bot, chat_id, reason='remaining_zero')
                        continue


                except Exception:
                    logger.exception('V321 error revisando auto chat=%s', chat_id)
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V321 auto loop error')


def _v321_start_auto_loop() -> None:
    global V321_AUTO_TASK
    try:
        if V321_AUTO_TASK is None or V321_AUTO_TASK.done():
            V321_AUTO_TASK = asyncio.create_task(_v321_auto_loop())
    except Exception:
        logger.exception('V321 no pudo arrancar auto loop')


_old_voice_start_v321 = VOICE.start
async def _v321_voice_start(application: Application) -> None:
    await _old_voice_start_v321(application)
    _v321_start_auto_loop()
VOICE.start = _v321_voice_start


