BOT_VERSION = "V324"

import time as _v324_time

V324_TASK: Optional[asyncio.Task] = None
V324_LOCKS: Dict[int, asyncio.Lock] = {}
V324_RUNTIME: Dict[int, Dict[str, Any]] = {}

V324_TICK_SECONDS = 2
V324_MIN_ADVANCE_GAP = 12
V324_START_GRACE = 8
V324_ZERO_HITS_REQUIRED = 3


def _v324_key(data: Any) -> str:
    try:
        if isinstance(data, dict):
            return str(data.get('file_unique_id') or data.get('file_id') or data.get('local_path') or data.get('title') or '')
    except Exception:
        pass
    return ''


def _v324_duration(st: Any) -> int:
    try:
        np = getattr(st, 'now_playing', None)
        if not isinstance(np, dict):
            return 0
        dur = int(np.get('duration') or 0)
        if dur > 0:
            return dur
        path = str(np.get('local_path') or '')
        if path and Path(path).exists():
            dur = int(probe_duration_seconds(path) or 0)
            if dur > 0:
                np['duration'] = dur
                st.now_playing = np
                save_all_states()
                return dur
    except Exception:
        logger.exception('V324 no pudo obtener duración')
    return 0


def _v324_state_reason(chat_id: int, st: Any) -> tuple[bool, str]:
    """Decide si toca pasar. Conservador para no pasar canciones a lo loco."""
    if not getattr(st, 'dj_mode', False):
        return False, 'dj_off'
    if not getattr(st, 'live_enabled', False):
        return False, 'live_off'
    if not getattr(st, 'auto_track_enabled', False):
        return False, 'auto_off'
    if not getattr(st, 'queue', None):
        return False, 'no_queue'

    now = _v324_time.time()
    rt = V324_RUNTIME.setdefault(int(chat_id), {})
    if now - float(rt.get('last_advance_at', 0.0) or 0.0) < V324_MIN_ADVANCE_GAP:
        return False, 'cooldown'


    if not getattr(st, 'now_playing', None):
        rt['zero_hits'] = 0
        return True, 'idle_no_now_playing'

    token = _v324_key(st.now_playing)
    if rt.get('token') != token:
        rt['token'] = token
        rt['track_seen_at'] = now
        rt['zero_hits'] = 0


    started = int(getattr(st, 'play_started_at', 0) or 0)
    if started > 0 and now - started < V324_START_GRACE:
        rt['zero_hits'] = 0
        return False, 'start_grace'

    try:
        rem = remaining_seconds(st)
    except Exception:
        rem = None

    if rem is not None:
        if int(rem) <= 0:
            rt['zero_hits'] = int(rt.get('zero_hits', 0) or 0) + 1
        else:
            rt['zero_hits'] = 0
        if int(rt.get('zero_hits', 0) or 0) >= V324_ZERO_HITS_REQUIRED:
            return True, 'remaining_confirmed_zero'
        return False, 'playing_remaining'


    dur = _v324_duration(st)
    if dur > 0 and started > 0:
        elapsed = int(now - started)
        if elapsed >= dur + 1:
            rt['zero_hits'] = int(rt.get('zero_hits', 0) or 0) + 1
        else:
            rt['zero_hits'] = 0
        if int(rt.get('zero_hits', 0) or 0) >= V324_ZERO_HITS_REQUIRED:
            return True, 'elapsed_confirmed_end'
        return False, 'playing_elapsed'


    return False, 'unknown_duration_safe'


async def _v324_refresh(bot, chat_id: int) -> None:
    try:
        if '_v314_refresh_both' in globals():
            await _v314_refresh_both(bot, int(chat_id), force_private=True)
            return
    except Exception:
        logger.exception('V324 error refrescando ambas mesas chat=%s', chat_id)
    try:
        await ensure_panel(bot, int(chat_id))
    except Exception:
        pass
    try:
        await ensure_control_panel(bot, int(chat_id))
    except Exception:
        pass


async def _v324_next(application: Application, chat_id: int, reason: str) -> bool:
    chat_id = int(chat_id)
    lock = V324_LOCKS.setdefault(chat_id, asyncio.Lock())
    async with lock:
        st = get_state(chat_id)
        ok, why = _v324_state_reason(chat_id, st)
        if not ok:
            return False
        if not getattr(st, 'queue', None):
            return False

        V324_RUNTIME.setdefault(chat_id, {})['last_advance_at'] = _v324_time.time()
        V324_RUNTIME.setdefault(chat_id, {})['zero_hits'] = 0

        try:
            logger.info('V324 siguiente chat=%s reason=%s why=%s cola=%s actual=%s',
                        chat_id, reason, why, len(st.queue), _v324_key(getattr(st, 'now_playing', None)))

            await VOICE.play_next_from_queue(chat_id)


            st2 = get_state(chat_id)
            V324_RUNTIME.setdefault(chat_id, {})['token'] = _v324_key(getattr(st2, 'now_playing', None))
            V324_RUNTIME.setdefault(chat_id, {})['track_seen_at'] = _v324_time.time()
            V324_RUNTIME.setdefault(chat_id, {})['zero_hits'] = 0

            bot = application.bot if application else (VOICE.application.bot if VOICE.application else None)
            if bot:
                await _v324_refresh(bot, chat_id)
            return True
        except Exception:
            logger.exception('V324 fallo pasando canción chat=%s reason=%s', chat_id, reason)
            return False


async def _v324_loop(application: Application) -> None:
    while True:
        try:
            await asyncio.sleep(V324_TICK_SECONDS)
            for chat_id, st in list(STATE_CACHE.items()):
                try:
                    chat_id = int(chat_id)
                    ok, reason = _v324_state_reason(chat_id, st)
                    if ok:
                        await _v324_next(application, chat_id, reason)
                except Exception:
                    logger.exception('V324 error revisando chat=%s', chat_id)
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V324 loop global error')


def _v324_cancel_conflicting_auto() -> None:
    """Apaga motores anteriores para que solo mande V324."""
    names = [
        'V306_DJ_AUTO_TASK',
        'V307_AUTO_TASK',
        'V308_WATCHDOG_TASK',
        'V321_AUTO_TASK',
        'V322_WATCHDOG_TASK',
        'V323_FALLBACK_TASK',
    ]
    for name in names:
        try:
            task = globals().get(name)
            if task and not task.done():
                task.cancel()
            globals()[name] = None
        except Exception:
            pass

    for dict_name in ('V322_AUTO_TASKS', 'V323_RUNTIME'):
        try:
            obj = globals().get(dict_name)
            if isinstance(obj, dict):
                for val in list(obj.values()):
                    try:
                        if hasattr(val, 'cancel') and not val.done():
                            val.cancel()
                    except Exception:
                        pass
                if dict_name != 'V323_RUNTIME':
                    obj.clear()
        except Exception:
            pass


async def schedule_auto_next(chat_id: int, duration: int, offset: int) -> None:
    try:
        st = get_state(int(chat_id))
        rt = V324_RUNTIME.setdefault(int(chat_id), {})
        rt['token'] = _v324_key(getattr(st, 'now_playing', None))
        rt['track_seen_at'] = _v324_time.time()
        rt['zero_hits'] = 0
    except Exception:
        pass


async def cancel_auto_next(chat_id: int) -> None:
    try:
        V324_RUNTIME.pop(int(chat_id), None)
    except Exception:
        pass


try:
    from telegram.ext import ApplicationHandlerStop as _V324Stop
except Exception:
    class _V324Stop(Exception):
        pass


