async def _v332_like_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or (q.data or '') != 'dj_now_like_v332':
        return
    chat_id = int(update.effective_chat.id)
    st = get_state(chat_id)
    data = _v332_track_dict(st.now_playing, chat_id)
    if not data:
        await q.answer('No hay canción sonando.')
        raise _V332Stop
    uid = int(q.from_user.id) if q.from_user else 0
    try:
        cfg = admin_cfg(chat_id)
        likes = cfg.setdefault('dj_track_likes', {})
        lk = _v332_like_key(chat_id, data)
        row = likes.setdefault(lk, {'title': data.get('title') or 'Canción', 'users': [], 'track': data})
        users = row.setdefault('users', [])
        if uid and uid not in users:
            users.append(uid)
        row['count'] = len(users)
        row['track'] = data
        save_all_states()
        count = int(row['count'])
    except Exception:
        count = _v332_like_count(chat_id, data)
    await q.answer(f'❤️ {count}')
    try:
        await q.edit_message_reply_markup(reply_markup=_v332_like_markup(chat_id, data))
    except Exception:
        pass
    raise _V332Stop


