async def _v308_live_on(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> bool:
    st = get_state(int(chat_id))
    ok_voice = False
    try:
        if '_v306_voice_ready' in globals():
            await _v306_voice_ready(context.application)
        ok_voice = bool(await VOICE.ensure_videochat_started(int(chat_id)))
    except Exception:
        ok_voice = False
    if not ok_voice:
        st.live_enabled = False
        save_all_states()
        await _v332_send_manual_prompt(context.bot, int(chat_id))
        try:
            await ensure_control_panel(context.bot, int(chat_id))
        except Exception:
            pass
        return False
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()
    if not st.now_playing and st.queue:
        await VOICE.play_next_from_queue(int(chat_id))
    elif st.now_playing:
        await VOICE.play_track(context.bot, int(chat_id), Track(**st.now_playing))
    try:
        await ensure_control_panel(context.bot, int(chat_id))
    except Exception:
        pass
    return True


async def _v332_manual_live_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('dj_manual_live_start_v332|'):
        return
    try:
        chat_id = int((q.data or '').split('|', 1)[1])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    try:
        await q.message.delete()
    except Exception:
        pass
    V332_MANUAL_LIVE_PROMPTS.pop(chat_id, None)
    st = get_state(chat_id)
    try:
        if '_v306_voice_ready' in globals():
            await _v306_voice_ready(context.application)
        ok_voice = bool(await VOICE.ensure_videochat_started(chat_id))
    except Exception:
        ok_voice = False
    if not ok_voice:
        st.live_enabled = False
        save_all_states()
        await _v332_send_manual_prompt(context.bot, chat_id)
        await q.answer('Aún no detecto el videochat.', show_alert=True)
        raise _V332Stop
    st.dj_mode = True
    st.live_enabled = True
    st.paused = False
    save_all_states()
    if not st.now_playing and st.queue:
        await VOICE.play_next_from_queue(chat_id)
    elif st.now_playing:
        await VOICE.play_track(context.bot, chat_id, Track(**st.now_playing))
    try:
        await ensure_control_panel(context.bot, chat_id)
    except Exception:
        pass
    await q.answer('Música iniciada ✅')
    raise _V332Stop


