_V335_WEEKDAYS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo']
_V335_MONTHS = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre']


def _v335_date_header(now_ts: Optional[int] = None) -> str:
    import time as _time
    ts = int(now_ts or _time.time())
    try:
        if '_local_dt_v15' in globals():
            dt = _local_dt_v15(ts)
            wd = int(dt.weekday())
            day = int(dt.day)
            mon = int(dt.month)
            year = int(dt.year)
        else:
            lt = _time.localtime(ts)
            wd = int(lt.tm_wday); day = int(lt.tm_mday); mon = int(lt.tm_mon); year = int(lt.tm_year)
    except Exception:
        lt = _time.localtime(ts)
        wd = int(lt.tm_wday); day = int(lt.tm_mday); mon = int(lt.tm_mon); year = int(lt.tm_year)
    return f'{_V335_WEEKDAYS[wd].capitalize()}, {day} de {_V335_MONTHS[mon-1]} de {year}'


