def _v335_is_jm_parts(phrase: str) -> tuple[bool, str]:
    try:
        if '_v317_jm_parts' in globals():
            return _v317_jm_parts(phrase)
    except Exception:
        pass
    txt = str(phrase or '').strip()
    import re as _re
    is_jm = bool(_re.search(r'(?:—|-)?\s*J\.?M\.?\s*$', txt, _re.I))
    body = _re.sub(r'(?:—|-)?\s*J\.?M\.?\s*$', '', txt, flags=_re.I).strip() if is_jm else txt
    return is_jm, body


def _v335_phrase_caption(chat_id: int, phrase: str, now_ts: Optional[int] = None) -> str:
    phrase = str(phrase or '').strip()
    header = h(_v335_date_header(now_ts))
    is_jm, body = _v335_is_jm_parts(phrase)
    stars_top = '✨✨\n' if is_jm else ''
    stars_bottom = '\n✨✨' if is_jm else ''
    likes = _v335_like_count(int(chat_id), phrase)
    try:
        extra = str(cfg_value(int(chat_id), 'daily_phrase_extra_text', '') or '').strip()
    except Exception:
        extra = ''
    extra_html = f"\n\n{h(extra)}" if extra else ''
    return (
        f"<b>{header}</b>\n\n"
        f"{stars_top}<b><i>“{h(body)}”</i></b>{stars_bottom}"
        f"{extra_html}\n\n❤️ Me gusta: <b>{likes}</b>"
    )[:1024]


