async def _v335_update_phrase_message(bot, chat_id: int, message_id: int) -> None:
    chat_id = int(chat_id); message_id = int(message_id)
    store = _v335_sent_store(chat_id)
    entry = store.get(str(message_id), {}) if isinstance(store, dict) else {}
    phrase = str(entry.get('phrase') or '').strip() if isinstance(entry, dict) else ''
    if not phrase:
        return
    sent_ts = int(entry.get('sent_ts') or time.time()) if isinstance(entry, dict) else int(time.time())
    text = _v335_phrase_caption(chat_id, phrase, sent_ts)
    markup = _v335_phrase_markup(chat_id, message_id, phrase)
    kind = str(entry.get('kind') or 'text') if isinstance(entry, dict) else 'text'
    try:
        if kind in ('photo', 'video', 'document', 'animation', 'gif'):
            await bot.edit_message_caption(chat_id=chat_id, message_id=message_id, caption=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await bot.edit_message_text(chat_id=chat_id, message_id=message_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        raise


async def _v335_dphrase_like_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('dphrase|like|'):
        return
    parts = (q.data or '').split('|')
    if len(parts) < 4:
        return
    try:
        chat_id = int(parts[2]); msg_id = int(parts[3])
    except Exception:
        await q.answer('Botón inválido.', show_alert=True)
        raise _V335Stop
    phrase = _v335_phrase_from_message(chat_id, msg_id)
    if not phrase:
        await q.answer('Esta frase ya no está activa.', show_alert=True)
        raise _V335Stop
    uid = str(int(q.from_user.id)) if q.from_user else '0'
    store = _v335_likes_store(chat_id)
    key = _v335_phrase_key(phrase)
    row = store.setdefault(key, {'text': phrase, 'users': []})
    users = row.setdefault('users', []) if isinstance(row, dict) else []
    if uid not in users:
        users.append(uid)
        row['text'] = phrase
        row['users'] = users
        save_all_states()
        await _v335_update_phrase_message(context.bot, chat_id, msg_id)
        await q.answer(f'❤️ Me gusta añadido · Total: {len(users)}')
    else:
        await q.answer(f'Ya habías dado me gusta ❤️ · Total: {len(users)}')
    raise _V335Stop


