BOT_VERSION = "V336"

import time as _v336_time
import math as _v336_math

try:
    import psutil as _v336_psutil
except Exception:
    _v336_psutil = None

try:
    from telegram.ext import ApplicationHandlerStop as _V336Stop
except Exception:
    class _V336Stop(Exception):
        pass

V336_PERF_RUNTIME: Dict[str, Any] = {
    'last_tick': 0.0,
    'loop_lag_ms': 0.0,
    'samples': [],
    'last_score': 0,
    'last_reason': '',
}
V336_PERF_TASK: Optional[asyncio.Task] = None

V336_MODULES = {
    'dj': ('🎧 DJ', 'Música, mesas, voice y autoavance'),
    'recurrentes': ('🔁 Recurrentes', 'Mensajes recurrentes y bloques'),
    'frase': ('💬 Frase diaria', 'Frase del día programada'),
    'hot': ('🎲 Hot/IA', 'Preguntitas, retos y utilidades IA'),
    'pregonero': ('📣 Pregonero', 'Automatismos de avisos y pregonero'),
    'limpieza': ('🧹 Limpieza auto', 'Borrado automático y limpieza de chat'),
    'validacion': ('🛡 Validación', 'Validación y seguridad de entradas'),
}


def _v336_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    mods = cfg.setdefault('perf_modules_v336', {})
    for k in V336_MODULES:
        mods.setdefault(k, True)
    cfg.setdefault('perf_saving_mode_v336', False)
    cfg.setdefault('perf_saving_level_v336', 0)
    return cfg


def _v336_mod_enabled(chat_id: int, module: str) -> bool:
    try:
        cfg = _v336_cfg(int(chat_id))
        return bool(cfg.get('perf_modules_v336', {}).get(module, True))
    except Exception:
        return True


def _v336_saving_level(chat_id: int) -> int:
    try:
        cfg = _v336_cfg(int(chat_id))
        if not bool(cfg.get('perf_saving_mode_v336', False)):
            return 0
        return max(1, min(2, int(cfg.get('perf_saving_level_v336', 1) or 1)))
    except Exception:
        return 0


def _v336_bool(v: bool) -> str:
    return 'ON ✅' if bool(v) else 'OFF ⛔'


def _v336_bar(score: int) -> str:
    score = max(0, min(100, int(score)))
    filled = max(0, min(10, int(round(score / 10))))
    return '█' * filled + '░' * (10 - filled)


def _v336_load_label(score: int) -> str:
    score = int(score)
    if score < 35:
        return '🟢 Fluido'
    if score < 65:
        return '🟡 Medio'
    if score < 85:
        return '🟠 Cargado'
    return '🔴 Saturado'


async def _v336_perf_probe_loop() -> None:
    expected = _v336_time.monotonic() + 2.0
    while True:
        try:
            await asyncio.sleep(2)
            now = _v336_time.monotonic()
            lag_ms = max(0.0, (now - expected) * 1000.0)
            expected = now + 2.0
            samples = V336_PERF_RUNTIME.setdefault('samples', [])
            samples.append(lag_ms)
            del samples[:-20]
            V336_PERF_RUNTIME['loop_lag_ms'] = sum(samples) / max(1, len(samples))
            V336_PERF_RUNTIME['last_tick'] = _v336_time.time()
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V336 perf probe error')


def _v336_start_probe() -> None:
    global V336_PERF_TASK
    try:
        if V336_PERF_TASK is None or V336_PERF_TASK.done():
            V336_PERF_TASK = asyncio.create_task(_v336_perf_probe_loop())
            logger.info('V336 monitor rendimiento arrancado')
    except Exception:
        logger.exception('V336 no pudo arrancar monitor rendimiento')


def _v336_task_count() -> int:
    try:
        return len([t for t in asyncio.all_tasks() if not t.done()])
    except Exception:
        return 0


def _v336_process_stats() -> tuple[int, int]:
    """CPU aproximada y memoria MB si psutil existe."""
    try:
        if _v336_psutil:
            p = _v336_psutil.Process(os.getpid())
            mem = int(p.memory_info().rss / (1024 * 1024))

            cpu = int(min(100, max(0, p.cpu_percent(interval=None))))
            return cpu, mem
    except Exception:
        pass
    return 0, 0


def _v336_score(chat_id: int) -> tuple[int, List[str]]:
    chat_id = int(chat_id)
    st = get_state(chat_id)
    reasons: List[str] = []

    lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0)
    tasks = _v336_task_count()
    cpu, mem = _v336_process_stats()

    score = 0


    if lag > 20:
        add = min(35, int(lag / 8))
        score += add
        reasons.append(f'lag {lag:.0f}ms')


    if tasks > 40:
        add = min(25, int((tasks - 40) / 4))
        score += add
        reasons.append(f'{tasks} tareas')


    if mem > 450:
        add = min(20, int((mem - 450) / 40))
        score += add
        reasons.append(f'{mem}MB RAM')


    if getattr(st, 'dj_mode', False):
        score += 8
        if getattr(st, 'live_enabled', False):
            score += 8
        if getattr(st, 'auto_track_enabled', False):
            score += 5
        if len(getattr(st, 'queue', []) or []) > 25:
            score += 8
            reasons.append('cola larga')
        if len(getattr(st, 'library', []) or []) > 200:
            score += 5
            reasons.append('biblioteca grande')


    temp_n = len(getattr(st, 'temp_message_ids', []) or [])
    bot_n = len(getattr(st, 'bot_message_ids', []) or [])
    if temp_n + bot_n > 80:
        score += min(15, int((temp_n + bot_n) / 25))
        reasons.append('mensajes temporales')


    cfg = _v336_cfg(chat_id)
    active_mods = sum(1 for v in cfg.get('perf_modules_v336', {}).values() if v)
    if active_mods >= 6:
        score += 5

    if cpu:
        score += min(20, int(cpu / 5))
        if cpu > 60:
            reasons.append(f'CPU {cpu}%')

    score = max(0, min(100, int(score)))
    if not reasons:
        reasons.append('normal')
    return score, reasons[:5]


def _v336_perf_text(chat_id: int) -> str:
    chat_id = int(chat_id)
    cfg = _v336_cfg(chat_id)
    score, reasons = _v336_score(chat_id)
    V336_PERF_RUNTIME['last_score'] = score
    V336_PERF_RUNTIME['last_reason'] = ', '.join(reasons)

    st = get_state(chat_id)
    lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0)
    tasks = _v336_task_count()
    cpu, mem = _v336_process_stats()
    saving = bool(cfg.get('perf_saving_mode_v336', False))
    level = _v336_saving_level(chat_id)

    lines = [
        '⚙️ <b>Rendimiento / Fluidez</b>',
        '',
        f'Saturación estimada: <b>{score}%</b> · {_v336_load_label(score)}',
        f'<code>{_v336_bar(score)}</code>',
        f'Motivo: <i>{h(", ".join(reasons))}</i>',
        '',
        f'Loop lag: <b>{lag:.0f}ms</b> · Tareas: <b>{tasks}</b>',
    ]
    if mem or cpu:
        lines.append(f'CPU aprox.: <b>{cpu}%</b> · RAM: <b>{mem}MB</b>')

    lines += [
        '',
        f'Modo ahorro: <b>{_v336_bool(saving)}</b> · Nivel: <b>{level}</b>',
        '',
        '<b>Módulos principales</b>',
    ]

    mods = cfg.get('perf_modules_v336', {})
    for key, (name, desc) in V336_MODULES.items():
        lines.append(f'{name}: <b>{_v336_bool(bool(mods.get(key, True)))}</b>')

    lines += [
        '',
        '<i>Consejo:</i> si está cargado, activa ahorro suave. Si sigue lento, pausa módulos que no uses en ese momento.',
        '',
        f'DJ: LIVE <b>{_v336_bool(getattr(st, "live_enabled", False))}</b> · AUTO <b>{_v336_bool(getattr(st, "auto_track_enabled", False))}</b> · Cola <b>{len(getattr(st, "queue", []) or [])}</b>',
    ]
    return '\n'.join(lines)


def _v336_perf_markup(chat_id: int) -> InlineKeyboardMarkup:
    chat_id = int(chat_id)
    cfg = _v336_cfg(chat_id)
    saving = bool(cfg.get('perf_saving_mode_v336', False))
    level = _v336_saving_level(chat_id)
    mods = cfg.get('perf_modules_v336', {})

    rows = [
        [
            InlineKeyboardButton('🔄 Refrescar', callback_data=f'perf336|refresh|{chat_id}'),
            InlineKeyboardButton(('⚡ Ahorro ON' if saving else '⚡ Ahorro OFF'), callback_data=f'perf336|saving|{chat_id}'),
        ],
        [
            InlineKeyboardButton(f'Nivel {level}', callback_data=f'perf336|level|{chat_id}'),
            InlineKeyboardButton('🧹 Limpiar temp', callback_data=f'perf336|clean|{chat_id}'),
        ],
    ]


    keys = list(V336_MODULES.keys())
    for i in range(0, len(keys), 2):
        row = []
        for key in keys[i:i+2]:
            name = V336_MODULES[key][0]
            enabled = bool(mods.get(key, True))
            row.append(InlineKeyboardButton(('✅ ' if enabled else '⛔ ') + name, callback_data=f'perf336|mod|{chat_id}|{key}'))
        rows.append(row)

    rows.append([
        InlineKeyboardButton('⚙️ Volver ajustes', callback_data=f'cfg|home|{chat_id}'),
        InlineKeyboardButton('❌ Cerrar', callback_data='cfg|close'),
    ])
    return InlineKeyboardMarkup(rows)


async def _v336_open_perf_panel(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    chat_id = int(chat_id)
    text = _v336_perf_text(chat_id)
    markup = _v336_perf_markup(chat_id)
    q = update.callback_query
    if q and q.message:
        try:
            await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
            await q.answer()
            return
        except BadRequest as e:
            if 'message is not modified' in str(e).lower():
                await q.answer()
                return
        except Exception:
            pass
    if update.effective_chat:
        await context.bot.send_message(chat_id=update.effective_chat.id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)


async def _v336_perf_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    await update.message.reply_html(_v336_perf_text(chat_id), reply_markup=_v336_perf_markup(chat_id))


async def _v336_clean_temp(bot, chat_id: int) -> int:
    st = get_state(int(chat_id))
    ids = []
    try:
        ids.extend(int(x) for x in list(getattr(st, 'temp_message_ids', []) or []) if x)
    except Exception:
        pass

    deleted = 0
    for mid in list(dict.fromkeys(ids))[:120]:
        try:
            await safe_delete(bot, int(chat_id), int(mid))
            deleted += 1
        except Exception:
            pass
    try:
        st.temp_message_ids = []
        save_all_states()
    except Exception:
        pass
    return deleted


async def _v336_perf_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('perf336|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    if not chat_id:
        return

    cfg = _v336_cfg(chat_id)

    if action == 'refresh':
        await _v336_open_perf_panel(update, context, chat_id)
        raise _V336Stop

    if action == 'saving':
        cfg['perf_saving_mode_v336'] = not bool(cfg.get('perf_saving_mode_v336', False))
        if cfg['perf_saving_mode_v336'] and int(cfg.get('perf_saving_level_v336', 0) or 0) <= 0:
            cfg['perf_saving_level_v336'] = 1
        save_all_states()
        await q.answer('Modo ahorro ' + ('ON' if cfg['perf_saving_mode_v336'] else 'OFF'))
        await _v336_open_perf_panel(update, context, chat_id)
        raise _V336Stop

    if action == 'level':
        cur = int(cfg.get('perf_saving_level_v336', 0) or 0)
        cfg['perf_saving_level_v336'] = 1 if cur <= 0 else (2 if cur == 1 else 0)
        cfg['perf_saving_mode_v336'] = bool(cfg['perf_saving_level_v336'] > 0)
        save_all_states()
        await q.answer(f'Nivel {cfg["perf_saving_level_v336"]}')
        await _v336_open_perf_panel(update, context, chat_id)
        raise _V336Stop

    if action == 'clean':
        deleted = await _v336_clean_temp(context.bot, chat_id)
        await q.answer(f'Limpieza: {deleted} mensajes temporales')
        await _v336_open_perf_panel(update, context, chat_id)
        raise _V336Stop

    if action == 'mod' and len(parts) >= 4:
        mod = parts[3]
        if mod in V336_MODULES:
            mods = cfg.setdefault('perf_modules_v336', {})
            mods[mod] = not bool(mods.get(mod, True))
            save_all_states()
            await q.answer(f'{V336_MODULES[mod][0]} ' + ('ON' if mods[mod] else 'OFF'))
        await _v336_open_perf_panel(update, context, chat_id)
        raise _V336Stop


