def _v336_should_skip_secondary(chat_id: int, module: str, seconds: int = 10) -> bool:
    """Devuelve True si se debe saltar un ciclo secundario por ahorro de carga."""
    try:
        if not _v336_mod_enabled(chat_id, module):
            return True
        level = _v336_saving_level(chat_id)
        if level <= 0:
            return False
        key = f'perf_skip_{module}_{chat_id}'
        now = _v336_time.time()
        runtime = V336_PERF_RUNTIME.setdefault('skip', {})
        last = float(runtime.get(key, 0.0) or 0.0)
        wait = seconds * (2 if level >= 2 else 1)
        if now - last < wait:
            return True
        runtime[key] = now
        return False
    except Exception:
        return False


