BOT_VERSION = "V338"

import time as _v338_time
import subprocess as _v338_subprocess

try:
    from telegram.ext import ApplicationHandlerStop as _V338Stop
except Exception:
    class _V338Stop(Exception):
        pass

V338_AUTO_TASK: Optional[asyncio.Task] = None
V338_AUTO_LOCKS: Dict[int, asyncio.Lock] = {}
V338_AUTO_RUNTIME: Dict[int, Dict[str, Any]] = {}

V338_TICK = 2
V338_MIN_GAP = 18
V338_START_GRACE = 10
V338_END_HITS = 3


def _v338_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    cfg.setdefault('dj_auto_engine_v338', True)
    cfg.setdefault('dj_audio_optimize_v338', True)
    cfg.setdefault('dj_audio_kbps_v338', 96)
    cfg.setdefault('dj_light_refresh_v338', True)
    cfg.setdefault('dj_auto_force_sequential_v338', True)
    return cfg


def _v338_onoff(v: Any) -> str:
    return 'ON ✅' if bool(v) else 'OFF ⛔'


def _v338_short(v: Any, n: int = 42) -> str:
    s = str(v or '').strip()
    return s if len(s) <= n else s[:max(1, n - 1)].rstrip() + '…'


def _v338_key(data: Any) -> str:
    try:
        if isinstance(data, dict):
            return str(data.get('file_unique_id') or data.get('file_id') or data.get('local_path') or data.get('title') or '')
    except Exception:
        pass
    return ''


def _v338_duration(st: Any) -> int:
    try:
        np = getattr(st, 'now_playing', None)
        if not isinstance(np, dict):
            return 0
        dur = int(np.get('duration') or 0)
        if dur > 0:
            return dur
        local = str(np.get('local_path') or '')
        if local and Path(local).exists():
            dur = int(probe_duration_seconds(local) or 0)
            if dur > 0:
                np['duration'] = dur
                st.now_playing = np
                save_all_states()
                return dur
    except Exception:
        logger.exception('V338 no pudo calcular duración')
    return 0


def _v338_remaining(st: Any) -> Optional[int]:
    try:
        rem = remaining_seconds(st)
        if rem is not None:
            return int(rem)
    except Exception:
        pass
    try:
        dur = _v338_duration(st)
        started = int(getattr(st, 'play_started_at', 0) or 0)
        if dur > 0 and started > 0:
            return max(0, dur - int(_v338_time.time() - started))
    except Exception:
        pass
    return None


def _v338_decision(chat_id: int, st: Any) -> tuple[bool, str]:
    if not bool(_v338_cfg(int(chat_id)).get('dj_auto_engine_v338', True)):
        return False, 'engine_off'
    if not getattr(st, 'dj_mode', False):
        return False, 'dj_off'
    if not getattr(st, 'live_enabled', False):
        return False, 'live_off'
    if not getattr(st, 'auto_track_enabled', False):
        return False, 'auto_off'
    if not getattr(st, 'queue', None):
        return False, 'no_queue'

    chat_id = int(chat_id)
    now = _v338_time.time()
    rt = V338_AUTO_RUNTIME.setdefault(chat_id, {})

    if now - float(rt.get('last_advance_at', 0.0) or 0.0) < V338_MIN_GAP:
        return False, 'cooldown'

    if not getattr(st, 'now_playing', None):
        rt['idle_hits'] = int(rt.get('idle_hits', 0) or 0) + 1
        if int(rt['idle_hits']) >= 2:
            return True, 'idle_no_song'
        return False, 'idle_confirm'

    rt['idle_hits'] = 0
    token = _v338_key(st.now_playing)
    if rt.get('token') != token:
        rt['token'] = token
        rt['end_hits'] = 0
        rt['track_seen_at'] = now

    started = int(getattr(st, 'play_started_at', 0) or 0)
    if started > 0 and now - started < V338_START_GRACE:
        rt['end_hits'] = 0
        return False, 'start_grace'

    rem = _v338_remaining(st)
    if rem is None:
        rt['end_hits'] = 0
        return False, 'unknown_duration'

    if int(rem) <= 0:
        rt['end_hits'] = int(rt.get('end_hits', 0) or 0) + 1
    else:
        rt['end_hits'] = 0

    if int(rt.get('end_hits', 0) or 0) >= V338_END_HITS:
        return True, 'ended_confirmed'
    return False, f'playing_{rem}'


def _v338_cancel_old_auto(application: Optional[Application] = None) -> None:
    for name in (
        'WATCHDOG_TASK',
        'V306_DJ_AUTO_TASK', 'V307_AUTO_TASK', 'V308_WATCHDOG_TASK',
        'V321_AUTO_TASK', 'V322_WATCHDOG_TASK', 'V323_FALLBACK_TASK',
        'V324_TASK', 'V325_TASK', 'V330_TASK', 'V331_TASK',
    ):
        try:
            task = globals().get(name)
            if task and hasattr(task, 'done') and not task.done():
                task.cancel()
            globals()[name] = None
        except Exception:
            pass

    for dict_name in ('AUTO_NEXT_TASKS', 'V322_AUTO_TASKS'):
        try:
            obj = globals().get(dict_name)
            if isinstance(obj, dict):
                for t in list(obj.values()):
                    try:
                        if t and hasattr(t, 'done') and not t.done():
                            t.cancel()
                    except Exception:
                        pass
                obj.clear()
        except Exception:
            pass

    try:
        if application and application.job_queue:
            for nm in ('v323_auto_dj_job',):
                for job in application.job_queue.get_jobs_by_name(nm):
                    job.schedule_removal()
    except Exception:
        pass


def _v321_start_auto_loop() -> None:
    return None

def _v322_start_watchdog() -> None:
    return None

async def schedule_auto_next(chat_id: int, duration: int, offset: int) -> None:
    try:
        st = get_state(int(chat_id))
        rt = V338_AUTO_RUNTIME.setdefault(int(chat_id), {})
        rt['token'] = _v338_key(getattr(st, 'now_playing', None))
        rt['track_seen_at'] = _v338_time.time()
        rt['end_hits'] = 0
        rt['idle_hits'] = 0
    except Exception:
        pass

async def cancel_auto_next(chat_id: int) -> None:
    try:
        V338_AUTO_RUNTIME.setdefault(int(chat_id), {})['end_hits'] = 0
    except Exception:
        pass


async def _v338_play_next(application: Application, chat_id: int, reason: str, *, force: bool = False, sequential: bool = True) -> bool:
    chat_id = int(chat_id)
    lock = V338_AUTO_LOCKS.setdefault(chat_id, asyncio.Lock())
    async with lock:
        st = get_state(chat_id)

        if not getattr(st, 'queue', None):
            return False

        if not force:
            ok, why = _v338_decision(chat_id, st)
            if not ok:
                return False
        else:
            why = 'manual_force'

        rt = V338_AUTO_RUNTIME.setdefault(chat_id, {})
        now = _v338_time.time()
        if not force and now - float(rt.get('last_advance_at', 0.0) or 0.0) < V338_MIN_GAP:
            return False

        rt['last_advance_at'] = now
        rt['end_hits'] = 0
        rt['idle_hits'] = 0

        bot = application.bot if application else (VOICE.application.bot if VOICE.application else None)
        if not bot:
            return False

        try:
            await cancel_auto_next(chat_id)


            if sequential or bool(_v338_cfg(chat_id).get('dj_auto_force_sequential_v338', True)):
                next_data = dict(st.queue.pop(0))
                if st.now_playing:
                    old_key = _v338_key(st.now_playing)
                    new_key = _v338_key(next_data)
                    if old_key and old_key != new_key:
                        st.history.append(dict(st.now_playing))
                        st.history = st.history[-25:]
                st.dj_mode = True
                st.live_enabled = True
                st.paused = False
                save_all_states()
                logger.info('V338 NEXT secuencial chat=%s reason=%s why=%s next=%s', chat_id, reason, why, _v338_key(next_data))
                await VOICE.play_track(bot, chat_id, Track(**next_data))
            else:
                logger.info('V338 NEXT delegada chat=%s reason=%s why=%s', chat_id, reason, why)
                await VOICE.play_next_from_queue(chat_id)

            st2 = get_state(chat_id)
            rt['token'] = _v338_key(getattr(st2, 'now_playing', None))
            rt['track_seen_at'] = _v338_time.time()
            rt['last_advance_at'] = _v338_time.time()
            rt['end_hits'] = 0
            rt['idle_hits'] = 0

            try:
                await ensure_control_panel(bot, chat_id)
            except Exception:
                pass
            try:
                if '_v314_edit_private' in globals() and _v336_saving_level(chat_id) < 2:
                    await _v314_edit_private(bot, chat_id)
            except Exception:
                pass
            return True
        except Exception:
            logger.exception('V338 error pasando siguiente chat=%s reason=%s', chat_id, reason)
            return False


async def _v338_auto_loop(application: Application) -> None:
    while True:
        try:
            await asyncio.sleep(V338_TICK)
            for chat_id, st in list(STATE_CACHE.items()):
                try:
                    chat_id = int(chat_id)
                    ok, reason = _v338_decision(chat_id, st)
                    if ok:
                        await _v338_play_next(application, chat_id, 'auto_' + reason, force=False, sequential=True)
                except Exception:
                    logger.exception('V338 loop error chat=%s', chat_id)
        except asyncio.CancelledError:
            return
        except Exception:
            logger.exception('V338 auto loop global error')


def _v338_start_auto(application: Application) -> None:
    global V338_AUTO_TASK
    _v338_cancel_old_auto(application)
    if V338_AUTO_TASK is None or V338_AUTO_TASK.done():
        V338_AUTO_TASK = asyncio.create_task(_v338_auto_loop(application))
        logger.info('V338 AUTO arrancado: único motor secuencial')


