def _v338_cache_dir(chat_id: int) -> Path:
    try:
        base = Path(DATA_DIR) if 'DATA_DIR' in globals() else Path('/tmp')
    except Exception:
        base = Path('/tmp')
    d = base / 'dj_audio_cache_v338' / str(int(chat_id))
    d.mkdir(parents=True, exist_ok=True)
    return d

def _v338_audio_cache_path(chat_id: int, src: str, kbps: int) -> str:
    import hashlib
    p = Path(src)
    try:
        key = f'{p.resolve()}:{p.stat().st_size}:{int(p.stat().st_mtime)}:{kbps}'
    except Exception:
        key = f'{src}:{kbps}'
    return str(_v338_cache_dir(chat_id) / (hashlib.sha1(key.encode()).hexdigest()[:18] + f'_{kbps}k.mp3'))

async def _v338_prepare_audio(chat_id: int, src: str) -> str:
    cfg = _v338_cfg(int(chat_id))
    if not bool(cfg.get('dj_audio_optimize_v338', True)):
        return src
    try:
        kbps = int(cfg.get('dj_audio_kbps_v338', 96) or 96)
        kbps = 64 if kbps <= 64 else (128 if kbps >= 128 else 96)
        source = Path(src)
        if not source.exists():
            return src
        out = _v338_audio_cache_path(int(chat_id), str(source), kbps)
        if Path(out).exists() and Path(out).stat().st_size > 0:
            return out

        def _run():
            tmp = out + '.tmp'
            cmd = [
                'ffmpeg', '-y', '-hide_banner', '-loglevel', 'error',
                '-i', str(source), '-vn',
                '-ac', '2', '-ar', '48000', '-b:a', f'{kbps}k',
                '-af', 'aresample=async=1:first_pts=0',
                tmp,
            ]
            cp = _v338_subprocess.run(cmd, stdout=_v338_subprocess.DEVNULL, stderr=_v338_subprocess.PIPE, timeout=120)
            if cp.returncode == 0 and Path(tmp).exists() and Path(tmp).stat().st_size > 0:
                Path(tmp).replace(out)
                return out
            try:
                Path(tmp).unlink(missing_ok=True)
            except Exception:
                pass
            return src
        return await asyncio.to_thread(_run)
    except Exception:
        logger.exception('V338 no pudo optimizar audio')
        return src

