async def _v338_group_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_next', 'panel_auto_track', 'panel_live_toggle', 'panel_pause_resume', 'panel_refresh', 'panel_close'}:
        return
    chat_id = int(update.effective_chat.id)
    try:
        if not await is_controller(context, chat_id, int(update.effective_user.id)):
            await _v338_answer(q, 'Solo DJ/admin.', alert=True)
            raise _V338Stop
    except _V338Stop:
        raise
    except Exception:
        pass

    st = get_state(chat_id)

    if data == 'panel_next':
        if not st.queue:
            await _v338_answer(q, 'No hay canciones en cola.', alert=True)
        else:
            await _v338_answer(q, '⏭ Siguiente')
            await _v338_play_next(context.application, chat_id, 'button_next', force=True, sequential=True)
        raise _V338Stop

    if data == 'panel_auto_track':
        st.auto_track_enabled = not bool(st.auto_track_enabled)
        if st.auto_track_enabled:
            st.auto_sig_seconds = 0
        V338_AUTO_RUNTIME.setdefault(chat_id, {})['end_hits'] = 0
        save_all_states()
        await _v338_answer(q, 'AUTO ON ✅' if st.auto_track_enabled else 'AUTO OFF')
        if st.auto_track_enabled and st.live_enabled and st.queue and not st.now_playing:
            await _v338_play_next(context.application, chat_id, 'auto_button_idle', force=True, sequential=True)
        else:
            try: await ensure_control_panel(context.bot, chat_id)
            except Exception: pass
        raise _V338Stop

    if data in {'panel_live_toggle', 'panel_pause_resume'}:
        if st.live_enabled:
            await _v338_answer(q, 'Apagando…')
            try:
                if '_v308_live_off' in globals():
                    await _v308_live_off(context, chat_id)
                else:
                    await close_dj_session(context.bot, chat_id)
            except Exception:
                logger.exception('V338 live off falló')
        else:
            await _v338_answer(q, 'Encendiendo…')
            try:
                if '_v308_live_on' in globals():
                    await _v308_live_on(context, chat_id)
                else:
                    st.live_enabled = True; st.dj_mode = True; save_all_states()
                    if st.queue:
                        await _v338_play_next(context.application, chat_id, 'live_start', force=True, sequential=True)
            except Exception:
                logger.exception('V338 live on falló')
                await _v338_answer(q, 'No pude iniciar. Abre videochat manualmente.', alert=True)
        try: await ensure_control_panel(context.bot, chat_id)
        except Exception: pass
        raise _V338Stop

    if data == 'panel_refresh':
        await _v338_answer(q, 'Actualizado')
        try: await ensure_control_panel(context.bot, chat_id)
        except Exception: pass
        raise _V338Stop

    if data == 'panel_close':
        await _v338_answer(q, 'Cerrando…')
        try:
            await close_dj_session(context.bot, chat_id)
        except Exception:
            logger.exception('V338 cerrar sesión falló')
        raise _V338Stop


