async def _v338_djpropriv_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('djpropriv|'):
        return
    if '_v310_is_admin_id' in globals() and not _v310_is_admin_id(int(q.from_user.id)):
        await q.answer('Solo ADMIN_IDS.', show_alert=True)
        raise _V338Stop
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[1])
    except Exception:
        chat_id = 0
    action = parts[2] if len(parts) > 2 else 'home'

    if action in {'home', 'refresh', 'control'} and chat_id:
        await _v338_show_private(q, context, chat_id)
        await _v338_answer(q, 'DJPRO')
        raise _V338Stop

    if action == 'groups' or not chat_id:

        if '_v310_groups_markup' in globals():
            try:
                await q.edit_message_text('🌐 <b>Elige grupo para DJPRO privado</b>', parse_mode=ParseMode.HTML, reply_markup=_v310_groups_markup())
                await q.answer()
                raise _V338Stop
            except Exception:
                pass
        await q.answer('Entra desde el grupo configurado o desde /djconfig.', show_alert=True)
        raise _V338Stop

    st = get_state(chat_id)

    if action == 'next':
        await _v338_answer(q, '⏭')
        await _v338_play_next(context.application, chat_id, 'private_next', force=True, sequential=True)
        await _v338_show_private(q, context, chat_id)
        raise _V338Stop

    if action == 'auto':
        st.auto_track_enabled = not bool(st.auto_track_enabled)
        if st.auto_track_enabled: st.auto_sig_seconds = 0
        save_all_states()
        await _v338_answer(q, 'AUTO ON ✅' if st.auto_track_enabled else 'AUTO OFF')
        if st.auto_track_enabled and st.live_enabled and st.queue and not st.now_playing:
            await _v338_play_next(context.application, chat_id, 'private_auto_idle', force=True, sequential=True)
        await _v338_show_private(q, context, chat_id)
        raise _V338Stop

    if action == 'live':
        if st.live_enabled:
            await _v338_answer(q, 'LIVE OFF')
            if '_v308_live_off' in globals():
                await _v308_live_off(context, chat_id)
            else:
                await close_dj_session(context.bot, chat_id)
        else:
            await _v338_answer(q, 'LIVE ON')
            if '_v308_live_on' in globals():
                await _v308_live_on(context, chat_id)
            else:
                st.live_enabled=True; st.dj_mode=True; save_all_states()
        await _v338_show_private(q, context, chat_id)
        raise _V338Stop


    if action in {'queue','library','lists','updatelist','savequeue','uploadinfo','settings','close','sessionclose','shuffle','voldown4','volup4','vol0','vol25','vol75','opus','quality','announce','timer1','timer2'}:
        try:
            await _v314_djpro_router(update, context)
        except Exception:
            if action == 'sessionclose':
                await close_dj_session(context.bot, chat_id)
                await q.answer('Sesión cerrada')
            elif action == 'close':
                try: await q.message.delete()
                except Exception: pass
            else:
                logger.exception('V338 ruta privada delegada falló action=%s', action)
                await q.answer('Error en DJPRO privado.', show_alert=True)
        raise _V338Stop


