_old_v232_summary_fields_v339 = _v232_summary_fields if '_v232_summary_fields' in globals() else None
def _v232_summary_fields(chat_id: int) -> List[str]:
    specs = _v232_summary_specs()
    try:
        pcfg = _v171_panel_cfg(int(chat_id))

        if isinstance(pcfg.get('top_fields'), list):
            raw = pcfg.get('top_fields')
            return [str(k) for k in raw if str(k) in specs and raw.count(k) >= 1 and str(k) not in []]
    except Exception:
        pass
    try:
        return _old_v232_summary_fields_v339(int(chat_id)) if callable(_old_v232_summary_fields_v339) else list(_v232_default_summary_fields())
    except Exception:
        return list(_v232_default_summary_fields())


_old_v232_set_summary_fields_v339 = _v232_set_summary_fields if '_v232_set_summary_fields' in globals() else None
def _v232_set_summary_fields(chat_id: int, fields: List[str]) -> None:
    specs = _v232_summary_specs()
    clean: List[str] = []
    for k in fields or []:
        k = str(k)
        if k in specs and k not in clean:
            clean.append(k)
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        pcfg['top_fields'] = clean

        pcfg['top_fields_explicit_v339'] = True
        save_all_states()
        return
    except Exception:
        pass
    if callable(_old_v232_set_summary_fields_v339):
        _old_v232_set_summary_fields_v339(int(chat_id), clean)


_old_v232_short_raw_value_v339 = _v232_short_raw_value if '_v232_short_raw_value' in globals() else None
def _v232_short_raw_value(chat_id: int, key: str) -> str:
    chat_id = int(chat_id)
    key = str(key)
    try:
        score, label = _v339_score(chat_id)
        cfg = _v339_cfg(chat_id)
        pcfg = _v336_cfg(chat_id) if '_v336_cfg' in globals() else admin_cfg(chat_id)
        mods = pcfg.get('perf_modules_v336', {}) if isinstance(pcfg, dict) else {}
        if key == 'perf_load':
            return f'{score}%'
        if key == 'perf_state':
            return label.replace('🟢 ', '').replace('🟡 ', '').replace('🟠 ', '').replace('🔴 ', '')[:6]
        if key == 'perf_lag':
            lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0) if 'V336_PERF_RUNTIME' in globals() else 0.0
            return f'{lag:.0f}ms'
        if key == 'perf_tasks':
            return str(_v336_task_count() if '_v336_task_count' in globals() else 0)
        if key == 'saving_mode':
            return _v339_onoff(bool(pcfg.get('perf_saving_mode_v336', False)))
        if key == 'saving_level':
            return str(_v336_saving_level(chat_id) if '_v336_saving_level' in globals() else 0)
        if key == 'mod_dj':
            return _v339_onoff(mods.get('dj', True))
        if key == 'mod_rec':
            return _v339_onoff(mods.get('recurrentes', True))
        if key == 'mod_frase':
            return _v339_onoff(mods.get('frase', True))
        if key == 'mod_hot':
            return _v339_onoff(mods.get('hot', True))
        if key == 'mod_pregonero':
            return _v339_onoff(mods.get('pregonero', True))
        if key == 'mod_validacion':
            return _v339_onoff(mods.get('validacion', True))
        if key == 'audio_opt':
            return _v339_onoff(cfg.get('dj_audio_optimize_v338', True))
        if key == 'audio_kbps':
            return f"{int(cfg.get('dj_audio_kbps_v338', 96) or 96)}k"
        if key == 'auto_v338':
            return _v339_onoff(cfg.get('dj_auto_engine_v338', True))
        if key == 'seq_v338':
            return _v339_onoff(cfg.get('dj_auto_force_sequential_v338', True))
        if key == 'priv_light':
            return _v339_onoff(cfg.get('dj_light_refresh_v338', True))
    except Exception:
        logger.exception('V339 error valor resumen %s', key)
    if callable(_old_v232_short_raw_value_v339):
        return _old_v232_short_raw_value_v339(chat_id, key)
    return '—'


def _v339_clean_summary_fields(chat_id: int) -> List[str]:
    try:
        pcfg = _v171_panel_cfg(int(chat_id))
        raw = pcfg.get('top_fields')
        specs = _v232_summary_specs()
        if isinstance(raw, list):
            out = []
            for k in raw:
                k = str(k)
                if k in specs and k not in out:
                    out.append(k)
            if out != raw:
                pcfg['top_fields'] = out
                save_all_states()
            return out
    except Exception:
        pass
    return _v232_summary_fields(int(chat_id))


