def _v314_private_text(chat_id: int) -> str:
    st = get_state(int(chat_id))
    cfg = _v339_cfg(int(chat_id))
    score, label = _v339_score(int(chat_id))
    live = _v339_onoff(st.live_enabled)
    auto = _v339_onoff(st.auto_track_enabled)
    alea = _v339_onoff(getattr(st, 'dj_shuffle_enabled', False))
    aviso = _v339_onoff(_v314_cfg(int(chat_id)).get('dj_announce_now_enabled', True) if '_v314_cfg' in globals() else True)
    current = _v314_track_label(st.now_playing, 48) if '_v314_track_label' in globals() else _v339_short((st.now_playing or {}).get('title') if st.now_playing else 'Nada')
    nxt = _v314_track_label(st.queue[0] if st.queue else None, 48) if '_v314_track_label' in globals() else (_v339_short(st.queue[0].get('title')) if st.queue else 'Nada')
    prev = _v314_track_label(st.history[-1] if st.history else None, 36) if '_v314_track_label' in globals() else (_v339_short(st.history[-1].get('title')) if st.history else 'Nada')
    timer = _v75_timer_label(int(chat_id)) if '_v75_timer_label' in globals() else 'sin temporizador'
    list_name = _v314_current_list_name(int(chat_id)) if '_v314_current_list_name' in globals() else 'Sesión actual'
    return (
        '<b>🎛 DJPRO privado</b>\n'
        f'Grupo: <b>{h(_v314_title(chat_id) if "_v314_title" in globals() else str(chat_id))}</b>\n\n'
        f'LIVE: <b>{live}</b> · AUTO: <b>{auto}</b> · ALEA: <b>{alea}</b> · VOL: <b>{int(getattr(st, "volume", 100) or 100)}</b>\n'
        f'📣 Aviso: <b>{aviso}</b> · 🎧 Audio OPT: <b>{_v339_onoff(cfg.get("dj_audio_optimize_v338", True))}</b> · Calidad: <b>{int(cfg.get("dj_audio_kbps_v338", 96) or 96)}k</b>\n'
        f'⚙️ Fluidez: <b>{score}%</b> · <b>{h(label)}</b> · Ahorro: <b>{_v336_saving_level(int(chat_id)) if "_v336_saving_level" in globals() else 0}</b> · Sec: <b>{_v339_onoff(cfg.get("dj_auto_force_sequential_v338", True))}</b>\n'
        f'🔴 Sonando: <b>{h(current)}</b>\n'
        f'⏭ Próxima: <b>{h(nxt)}</b>\n'
        f'⏮ Anterior: <b>{h(prev)}</b>\n'
        f'📋 Cola: <b>{len(st.queue)}</b> · 📚 Biblioteca: <b>{len(st.library)}</b> · 📂 Lista: <b>{h(list_name)}</b>\n'
        f'⏳ Temporizador: <b>{h(timer)}</b>\n\n'
        '<i>Calidad y optimización se controlan desde Rendimiento/Fluidez y desde el botón 🎚 de esta mesa.</i>'
    )


