def _v342_is_format_error(text: str) -> bool:
    t = str(text or '').lower()
    return (
        'requested format is not available' in t
        or 'no video formats found' in t
        or 'no suitable formats' in t
        or 'use --list-formats' in t
        or 'format is not available' in t
    )


