BOT_VERSION = "V343"


def _v343_ytdlp_base_args() -> List[str]:
    """Base yt-dlp reforzada con cookies y clientes alternativos."""
    if '_v334_ytdlp_base_args' in globals():
        args = list(_v334_ytdlp_base_args())
    else:
        args = ['yt-dlp', '--no-playlist', '--no-warnings']


    joined = ' '.join(args)
    extra: List[str] = []

    if '--force-ipv4' not in args:
        extra += ['--force-ipv4']


    if 'youtube:player_client=' not in joined:
        extra += ['--extractor-args', 'youtube:player_client=ios,android,web,web_embedded']
    else:

        pass


    for flag, val in [
        ('--extractor-retries', '5'),
        ('--fragment-retries', '5'),
        ('--retry-sleep', '1'),
    ]:
        if flag not in args:
            extra += [flag, val]

    return args + extra


def _v343_format_candidates() -> List[Optional[str]]:


    return [
        None,
        'bv*+ba/b',
        'bv*[height<=720]+ba/b[height<=720]/bv*+ba/b',
        'bv*[height<=480]+ba/b[height<=480]/bv*+ba/b',
        'ba/bestaudio/b',
        'bestaudio[ext=m4a]/bestaudio[ext=webm]/ba/b',
        'best[acodec!=none]/best',
        '18/22/17/best',
    ]


async def _v343_try_ytdlp_download(url: str, base_template: Path) -> Path:
    ytdlp_base = _v343_ytdlp_base_args()
    last_error = ''
    timeout = PODCAST_YTDLP_TIMEOUT_V215 if 'PODCAST_YTDLP_TIMEOUT_V215' in globals() else 420

    for idx, fmt in enumerate(_v343_format_candidates(), start=1):
        attempt_base = Path(str(base_template) + f'_try{idx}')
        try:
            for old in DOWNLOAD_DIR.glob(attempt_base.name + '.*'):
                try:
                    old.unlink(missing_ok=True)
                except Exception:
                    pass
        except Exception:
            pass

        cmd = ytdlp_base + [
            '--no-part',
            '--force-overwrites',
            '--merge-output-format', 'mkv',
            '-o', str(attempt_base) + '.%(ext)s',
        ]
        if fmt:
            cmd += ['-f', fmt]
        cmd += [url]

        try:
            logger.info('V343 yt-dlp intento %s formato=%s', idx, fmt or 'AUTO')
            await _v215_run_cmd(cmd, timeout=timeout)
            candidates = sorted(
                DOWNLOAD_DIR.glob(attempt_base.name + '.*'),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            source = next(
                (
                    p for p in candidates
                    if p.is_file()
                    and not p.name.endswith('.part')
                    and p.suffix.lower() not in ('.json', '.description', '.info')
                    and p.stat().st_size > 0
                ),
                None,
            )
            if source:
                return source
            last_error = f'yt-dlp terminó pero no generó archivo en intento {idx} formato {fmt or "AUTO"}'
        except Exception as e:
            err = str(e)
            last_error = err
            if '_v334_is_youtube_bot_error' in globals() and _v334_is_youtube_bot_error(err):
                raise
            logger.warning('V343 fallo intento %s formato=%s err=%s', idx, fmt or 'AUTO', err[:400])
            continue


    try:
        list_cmd = ytdlp_base + ['--list-formats', url]
        formats = await _v215_run_cmd(list_cmd, timeout=120)
        logger.warning('V343 list-formats salida:\n%s', (formats.stdout or '')[-4000:])
    except Exception as e:
        logger.warning('V343 no pudo obtener --list-formats: %s', str(e)[:500])

    raise RuntimeError(
        'No pude descargar ningún formato utilizable de YouTube. Último error: ' + str(last_error)
    )


