async def ytdlpdiagnostico_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    if not context.args:
        await update.message.reply_text('Uso: /ytdlpdiagnostico enlace_de_youtube')
        return
    url = context.args[0].strip()
    try:
        cmd = _v343_ytdlp_base_args() + ['--list-formats', url]
        res = await _v215_run_cmd(cmd, timeout=140)
        out = (res.stdout or '').strip()
        if len(out) > 3500:
            out = out[-3500:]
        await update.message.reply_html('<b>📋 Formatos detectados</b>\n\n<pre>' + h(out or 'Sin salida') + '</pre>')
    except Exception as e:
        await update.message.reply_html('<b>❌ Diagnóstico falló</b>\n\n<code>' + h(str(e)[:3500]) + '</code>')


