def _v348_group_title(chat_id: int) -> str:
    try:
        title = cfg_value(int(chat_id), 'chat_title', '') if 'cfg_value' in globals() else ''
        if title:
            return str(title)
    except Exception:
        pass
    try:
        return str(admin_cfg(int(chat_id)).get('chat_title') or int(chat_id))
    except Exception:
        return str(chat_id)


def _v348_controlled_groups() -> List[int]:
    groups = []
    try:
        for cid in STATE_CACHE.keys():
            try:
                cid_int = int(cid)
                if cid_int < 0:
                    groups.append(cid_int)
            except Exception:
                pass
    except Exception:
        pass

    try:
        for cid in (ALL_STATES.keys() if 'ALL_STATES' in globals() and isinstance(ALL_STATES, dict) else []):
            try:
                cid_int = int(cid)
                if cid_int < 0 and cid_int not in groups:
                    groups.append(cid_int)
            except Exception:
                pass
    except Exception:
        pass
    return sorted(set(groups), key=lambda x: _v348_group_title(x).lower())


def _v348_exportable_conf_cfg(chat_id: int) -> Dict[str, Any]:
    """Copia solo configuración, no logs ni estado de sesión."""
    c = dict(_v347_cfg(int(chat_id)))
    for k in (
        'enabled',
        'log',
        'last_by_user',
        'launcher_message_id',
        'pinned_message_id',
    ):
        c.pop(k, None)

    return c


def _v348_apply_conf_cfg(target_chat_id: int, exported: Dict[str, Any]) -> None:
    c = _v347_cfg(int(target_chat_id))
    keep = {
        'enabled': bool(c.get('enabled', False)),
        'log': list(c.get('log') or []),
        'last_by_user': dict(c.get('last_by_user') or {}),
        'launcher_message_id': int(c.get('launcher_message_id') or 0),
        'pinned_message_id': int(c.get('pinned_message_id') or 0),
    }
    for k, v in dict(exported or {}).items():
        if k in {'enabled', 'log', 'last_by_user', 'launcher_message_id', 'pinned_message_id'}:
            continue
        c[k] = v
    c.update(keep)
    save_all_states()


def _v348_summary(chat_id: int) -> str:
    c = _v347_cfg(int(chat_id))
    return (
        f'Portada: {"sí" if c.get("cover_file_id") else "no"} · '
        f'Confesión img: {"sí" if c.get("confession_file_id") else "no"} · '
        f'Likes: {"ON" if c.get("likes_enabled", True) else "OFF"} · '
        f'Categorías: {"ON" if c.get("categories_enabled", False) else "OFF"} '
        f'({len(c.get("categories") or {})}) · '
        f'Tiempo: {int(c.get("cooldown_seconds", 300) or 0)}s'
    )


def _v348_export_menu_markup(chat_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('📤 Exportar este grupo', callback_data=f'conf348|export|{int(chat_id)}')],
        [InlineKeyboardButton('📥 Importar desde otro grupo', callback_data=f'conf348|choose_source|{int(chat_id)}')],
        [InlineKeyboardButton('📋 Copiar este grupo a otro', callback_data=f'conf348|choose_target|{int(chat_id)}')],
        [InlineKeyboardButton('🔙 Volver', callback_data=f'conf347|config|{int(chat_id)}')]
    ])


def _v348_source_markup(target_chat_id: int) -> InlineKeyboardMarkup:
    rows = []
    for gid in _v348_controlled_groups():
        if int(gid) == int(target_chat_id):
            continue
        rows.append([InlineKeyboardButton(f'📥 {_v348_group_title(gid)}', callback_data=f'conf348|import_from|{int(target_chat_id)}|{int(gid)}')])
