def _v348_target_markup(source_chat_id: int) -> InlineKeyboardMarkup:
    rows = []
    for gid in _v348_controlled_groups():
        if int(gid) == int(source_chat_id):
            continue
        rows.append([InlineKeyboardButton(f'📋 {_v348_group_title(gid)}', callback_data=f'conf348|copy_to|{int(source_chat_id)}|{int(gid)}')])
