def _v349_reply_is_opus_like(message) -> bool:
    if not message:
        return False
    try:
        if getattr(message, 'voice', None):
            return True
        audio = getattr(message, 'audio', None)
        if audio:
            mt = (getattr(audio, 'mime_type', '') or '').lower()
            fn = (getattr(audio, 'file_name', '') or '').lower()
            return ('opus' in mt) or ('ogg' in mt) or fn.endswith(('.opus', '.ogg', '.oga'))
        doc = getattr(message, 'document', None)
        if doc:
            mt = (getattr(doc, 'mime_type', '') or '').lower()
            fn = (getattr(doc, 'file_name', '') or '').lower()
            return ('opus' in mt) or ('ogg' in mt) or fn.endswith(('.opus', '.ogg', '.oga'))
    except Exception:
        return False
    return False


def _v349_track_from_opus_reply(message) -> Optional[Track]:

    try:
        tr = extract_track_from_message(message)
        if tr:
            return tr
    except Exception:
        pass


    try:
        doc = getattr(message, 'document', None)
        if doc:
            fn = getattr(doc, 'file_name', '') or f'Podcast OPUS {message.message_id}'
            return Track(
                title=getattr(message, 'caption', None) or fn,
                performer='',
                duration=0,
                file_id=doc.file_id,
                file_unique_id=getattr(doc, 'file_unique_id', '') or f'opusdoc:{message.message_id}',
                mime_type=getattr(doc, 'mime_type', '') or 'audio/ogg',
                original_message_id=message.message_id,
            )
        audio = getattr(message, 'audio', None)
        if audio:
            return Track(
                title=audio.title or getattr(audio, 'file_name', '') or getattr(message, 'caption', None) or f'Podcast OPUS {message.message_id}',
                performer=audio.performer or '',
                duration=int(audio.duration or 0),
                file_id=audio.file_id,
                file_unique_id=getattr(audio, 'file_unique_id', '') or f'opusaudio:{message.message_id}',
                mime_type=getattr(audio, 'mime_type', '') or 'audio/ogg',
                original_message_id=message.message_id,
            )
        voice = getattr(message, 'voice', None)
        if voice:
            return Track(
                title=getattr(message, 'caption', None) or f'Podcast OPUS {message.message_id}',
                performer='',
                duration=int(voice.duration or 0),
                file_id=voice.file_id,
                file_unique_id=getattr(voice, 'file_unique_id', '') or f'opusvoice:{message.message_id}',
                mime_type='voice',
                original_message_id=message.message_id,
            )
    except Exception:
        logger.exception('V349 no pudo construir Track desde reply OPUS')
    return None


async def _v349_materialize_opus_reply(context: ContextTypes.DEFAULT_TYPE, chat_id: int, track: Track) -> Track:
    """Descarga el OPUS/OGG de Telegram a local sin reconvertirlo."""
    if track.local_path and Path(track.local_path).exists():
        if track.duration <= 0:
            track.duration = probe_duration_seconds(track.local_path)
        return track
    if not track.file_id:
        raise RuntimeError('El fichero OPUS no tiene file_id utilizable por el bot.')

    mt = (track.mime_type or '').lower()
    title_low = (track.title or '').lower()
    if 'opus' in mt or title_low.endswith('.opus'):
        ext = '.opus'
    else:
        ext = '.ogg'

    token = secrets.token_hex(6)
    path = DOWNLOAD_DIR / f'{int(chat_id)}_podreplyopus_{token}{ext}'
    tg_file = await context.bot.get_file(track.file_id)
    await tg_file.download_to_drive(custom_path=str(path))

    track.local_path = str(path)
    if track.duration <= 0:
        track.duration = probe_duration_seconds(str(path))
    if not track.performer:
        track.performer = 'Podcast OPUS'
    if not track.mime_type:
        track.mime_type = 'audio/ogg'
    return track


async def _v349_podcast_reply_opus_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Prioritario: /podcast o /pod respondiendo a un fichero OPUS/OGG ya subido."""
    if not update.message or not update.effective_user or not update.effective_chat:
        return


    text = update.message.text or update.message.caption or ''
    try:
        has_url = bool(_v215_first_url(text or ' '.join(context.args or [])))
    except Exception:
        has_url = False
    if has_url:
        return

    reply = getattr(update.message, 'reply_to_message', None)
    if not reply or not _v349_reply_is_opus_like(reply):

        return

    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        selected = dj_selected_private_group(update.effective_user.id) if 'dj_selected_private_group' in globals() else None
        if selected is None:
            await update.message.reply_html('Primero vincula/elige un grupo con <code>/djgrupos</code> o <code>/djgrupo</code>.')
            raise _V349Stop
        chat_id = int(selected)

    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await update.message.reply_text('Solo admin o DJ puede preparar podcasts.')
        raise _V349Stop

    status = await update.message.reply_html('🎙️ Preparando OPUS ya subido…\nNo descargo nada externo. Lo dejo listo para DJ-PRO.')
    try:
        track = _v349_track_from_opus_reply(reply)
        if not track:
            raise RuntimeError('No pude leer el fichero respondido como audio OPUS.')
        track.title = track.title or getattr(reply, 'caption', None) or 'Podcast OPUS'
        if not str(track.title).startswith('🎙️'):
            track.title = '🎙️ ' + str(track.title)
        track.added_by_id = update.effective_user.id
        track.added_by_name = display_name(update.effective_user)
        track = await _v349_materialize_opus_reply(context, chat_id, track)


        await _v215_present_podcast(update, context, chat_id, track, status_msg=status)
    except Exception as e:
        logger.exception('V349 error preparando OPUS respondido con /podcast')
        try:
            await status.edit_text('❌ No pude preparar ese OPUS.\n\n<code>'+h(str(e)[-1200:])+'</code>', parse_mode=ParseMode.HTML)
        except Exception:
            pass
    raise _V349Stop


