def build_application() -> Application:
    app = _old_build_application_v348_for_v349_podcast_opus()

    app.add_handler(CommandHandler(['podcast', 'pod'], _v349_podcast_reply_opus_command), group=-1000000034000)
    logger.info('V349 cargado: /podcast en respuesta a OPUS muestra opciones DJ-PRO sin descargar')
    return app


