def _ip_config_markup(chat_id: int) -> InlineKeyboardMarkup:
    c = _ip_cfg(chat_id)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎭 Lanzar lobby', callback_data=f'ip350|new|{int(chat_id)}')],
        [InlineKeyboardButton(f'🔁 Rondas {int(c.get("rounds",5))}', callback_data=f'ip350|cfg_rounds|{int(chat_id)}'),
         InlineKeyboardButton(f'⏱ Turno {int(c.get("turn_seconds",60))}s', callback_data=f'ip350|cfg_turn|{int(chat_id)}')],
        [InlineKeyboardButton(f'🚫 Tabú {int(c.get("taboo_words_count",3))}', callback_data=f'ip350|cfg_taboo|{int(chat_id)}')],
        [InlineKeyboardButton(('🧹 Limpieza ON' if c.get('cleanup_enabled', True) else '🧹 Limpieza OFF'), callback_data=f'ip350|cfg_cleanup|{int(chat_id)}'),
         InlineKeyboardButton(f'⏳ {int(c.get("cleanup_seconds",25))}s', callback_data=f'ip350|cfg_cleansecs|{int(chat_id)}')],
        [InlineKeyboardButton('🖼 Img lobby', callback_data=f'ip350|cfg_img_lobby|{int(chat_id)}'),
         InlineKeyboardButton('🖼 Img ronda', callback_data=f'ip350|cfg_img_round|{int(chat_id)}')],
        [InlineKeyboardButton('🖼 Img acierto', callback_data=f'ip350|cfg_img_right|{int(chat_id)}'),
         InlineKeyboardButton('🖼 Img fallo', callback_data=f'ip350|cfg_img_wrong|{int(chat_id)}')],
        [InlineKeyboardButton('🖼 Img eliminado', callback_data=f'ip350|cfg_img_elim|{int(chat_id)}'),
         InlineKeyboardButton('🖼 Img final', callback_data=f'ip350|cfg_img_final|{int(chat_id)}')],
        [InlineKeyboardButton('🏆 Ranking', callback_data=f'ip350|ranking|{int(chat_id)}')],
        [InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|home|{int(chat_id)}')],
    ])


async def _ip_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('ip350|') or not q.from_user:
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try: chat_id = int(parts[2])
    except Exception: chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    uid = int(q.from_user.id)
    s = _ip_state(chat_id)
    c = _ip_cfg(chat_id)

    if action == 'join':
        if s.get('phase') != 'lobby':
            await q.answer('El lobby no está abierto.', show_alert=True); raise _IPStop
        s.setdefault('participants', {})[str(uid)] = _ip_name(q.from_user)
        save_all_states()
        await _ip_render_lobby(context.bot, chat_id)
        await q.answer('Te has unido')
        raise _IPStop

    if action == 'leave':
        s.setdefault('participants', {}).pop(str(uid), None)
        save_all_states()
        await _ip_render_lobby(context.bot, chat_id)
        await q.answer('Has salido')
        raise _IPStop

    if action == 'rules':
        await q.answer(_ip_rules_text().replace('<b>','').replace('</b>','').replace('\n','\n')[:1900], show_alert=True)
        raise _IPStop

    if action == 'start':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True); raise _IPStop
        await _ip_start_game(context, chat_id)
        await q.answer('Partida iniciada')
        raise _IPStop

    if action in {'close','new'}:
        if action == 'new':
            if not await _ip_admin_ok(context, chat_id, uid):
                await q.answer('Solo admins.', show_alert=True); raise _IPStop
            await _ip_delete_all_messages(context.bot, chat_id)
            _ip_reset(chat_id)
            await _ip_render_lobby(context.bot, chat_id)
            await q.answer('Nueva partida')
        else:
            await _ip_delete_all_messages(context.bot, chat_id)
            _ip_reset(chat_id)
            await q.answer('Cerrado')
        raise _IPStop

    if action == 'ask':
        if s.get('phase') != 'playing':
            await q.answer('Ahora no se puede enviar pista.', show_alert=True); raise _IPStop
        if uid == int(s.get('impostor_id') or 0):
            await q.answer('El impostor no pregunta. Solo responde.', show_alert=True); raise _IPStop
        if uid != int(s.get('current_turn_user_id') or 0):
            await q.answer('No es tu turno.', show_alert=True); raise _IPStop
        if str(uid) in (s.get('eliminated') or {}):
            await q.answer('Estás eliminado.', show_alert=True); raise _IPStop
        IP_WAITING[uid] = {'chat_id': chat_id, 'step': 'question'}
        s['phase'] = 'awaiting_question'
        save_all_states()
        await _ip_render_panel(context.bot, chat_id)
        await q.answer('Ahora escribe tu pregunta en el grupo.', show_alert=True)
        raise _IPStop

    if action == 'accuse':
        if s.get('phase') not in {'playing','awaiting_question'}:
            await q.answer('Ahora no se puede acusar.', show_alert=True); raise _IPStop
        if uid == int(s.get('impostor_id') or 0):
            await q.answer('El impostor no acusa.', show_alert=True); raise _IPStop
        if uid != int(s.get('current_turn_user_id') or 0):
            await q.answer('Solo puede acusar quien tiene el turno.', show_alert=True); raise _IPStop
        IP_WAITING[uid] = {'chat_id': chat_id, 'step': 'accuse'}
        s['phase'] = 'awaiting_question'
        save_all_states()
        await _ip_render_panel(context.bot, chat_id)
        await q.answer('Escribe en el grupo el nombre que acusas.', show_alert=True)
        raise _IPStop

    if action.startswith('ans_'):
        if uid != int(s.get('impostor_id') or 0):
            await q.answer('Solo responde el impostor.', show_alert=True); raise _IPStop
        if s.get('phase') != 'awaiting_impostor_answer' or not s.get('pending_question'):
            await q.answer('No hay pregunta pendiente.', show_alert=True); raise _IPStop
        pq = s.get('pending_question') or {}
        by = int(pq.get('by') or 0)
        by_name = pq.get('by_name') or str(by)
        text = pq.get('text') or ''
        if action == 'ans_eliminate':
            s.setdefault('clues', []).append({'by': by, 'by_name': by_name, 'text': text, 'answer': 'manual_elim'})
            s['pending_question'] = None
            save_all_states()
            await _ip_eliminate(context, chat_id, by, 'El impostor detectó palabra tabú.')
            await _ip_start_turn_or_final(context, chat_id)
            await q.answer('Jugador eliminado')
            raise _IPStop
        ans = action.replace('ans_', '')
        s.setdefault('clues', []).append({'by': by, 'by_name': by_name, 'text': text, 'answer': ans})
        s['pending_question'] = None
        save_all_states()
        await q.answer('Respuesta guardada')
        await _ip_start_turn_or_final(context, chat_id)
        raise _IPStop

    if action.startswith('acc_'):
        if uid != int(s.get('impostor_id') or 0):
            await q.answer('Solo confirma el impostor.', show_alert=True); raise _IPStop
        if s.get('phase') != 'awaiting_impostor_accusation' or not s.get('pending_accusation'):
            await q.answer('No hay acusación pendiente.', show_alert=True); raise _IPStop
        pa = s.get('pending_accusation') or {}
        accuser = int(pa.get('by') or 0)
        accuser_name = pa.get('by_name') or str(accuser)
        accused = pa.get('text') or ''
        if action == 'acc_right':
            round_no = max(1, int(s.get('round') or 1))
            pts = max(1, 8 - round_no)
            _ip_rank_add(chat_id, accuser, accuser_name, pts)
            _ip_rank_add(chat_id, accuser, accuser_name, 1, 'wins')
            s['pending_accusation'] = None
            save_all_states()
            await q.answer('Correcto')
            await _ip_finish_game(context, chat_id, f'{accuser_name} ha descubierto la identidad en la ronda {round_no}. Suma +{pts} y +1 por participar.', winner_text=accuser_name, reveal=True)
            raise _IPStop
        else:
            total = int(c.get('rounds', 5) or 5)
            round_no = max(1, int(s.get('round') or 1))
            penalty = -7 if round_no >= total else -5
            _ip_rank_add(chat_id, accuser, accuser_name, penalty)
            s['pending_accusation'] = None
            save_all_states()
            await _ip_eliminate(context, chat_id, accuser, f'Acusación fallida ({penalty} puntos).')
            await q.answer('Incorrecto')
            if not _ip_alive(chat_id):
                imp = int(s.get('impostor_id') or 0)
                _ip_rank_add(chat_id, imp, s.get('impostor_name') or str(imp), 6)
                await _ip_finish_game(context, chat_id, 'No quedan jugadores. Gana el impostor y suma +6.', winner_text=s.get('impostor_name') or 'Impostor', reveal=True)
            else:
                await _ip_start_turn_or_final(context, chat_id)
            raise _IPStop

    if action == 'vote':
        if s.get('phase') != 'final_vote':
            await q.answer('No hay votación abierta.', show_alert=True); raise _IPStop
        if uid == int(s.get('impostor_id') or 0):
            await q.answer('El impostor no vota.', show_alert=True); raise _IPStop
        if str(uid) not in (s.get('participants') or {}):
            await q.answer('No participas en esta partida.', show_alert=True); raise _IPStop
        IP_WAITING[uid] = {'chat_id': chat_id, 'step': 'final_vote'}
        await q.answer('Escribe en el grupo tu voto final.', show_alert=True)
        raise _IPStop

    if action == 'closevote':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True); raise _IPStop
        await _ip_finish_final_vote(context, chat_id)
        await q.answer('Votación cerrada')
        raise _IPStop


    if action.startswith('cfg_'):
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True); raise _IPStop
        if action == 'cfg_rounds':
            vals=[3,5,7,10]; cur=int(c.get('rounds',5)); c['rounds']=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else 5
        elif action == 'cfg_turn':
            vals=[30,45,60,90,120]; cur=int(c.get('turn_seconds',60)); c['turn_seconds']=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else 60
        elif action == 'cfg_taboo':
            vals=[3,4,5]; cur=int(c.get('taboo_words_count',3)); c['taboo_words_count']=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else 3
        elif action == 'cfg_cleanup':
            c['cleanup_enabled'] = not bool(c.get('cleanup_enabled', True))
        elif action == 'cfg_cleansecs':
            vals=[10,20,25,40,60,90]; cur=int(c.get('cleanup_seconds',25)); c['cleanup_seconds']=vals[(vals.index(cur)+1)%len(vals)] if cur in vals else 25
        elif action.startswith('cfg_img_'):
            keymap={'cfg_img_lobby':'lobby_image_id','cfg_img_round':'round_image_id','cfg_img_right':'right_image_id','cfg_img_wrong':'wrong_image_id','cfg_img_elim':'eliminated_image_id','cfg_img_final':'final_image_id'}
            IP_WAITING[uid]={'chat_id': chat_id, 'step': 'set_image', 'image_key': keymap.get(action)}
            try: await context.bot.send_message(uid, 'Envíame la imagen para esa opción.')
            except Exception: pass
            await q.answer('Envíame la imagen por privado.', show_alert=True)
            raise _IPStop
        save_all_states()
        try: await q.edit_message_text('🎭 <b>Identidad Oculta PRO · Configuración</b>', parse_mode=ParseMode.HTML, reply_markup=_ip_config_markup(chat_id))
        except Exception: pass
        await q.answer('Actualizado')
        raise _IPStop

    if action == 'ranking':
        rk = c.get('ranking') or {}
        if not rk:
            await q.answer('Sin ranking todavía.', show_alert=True); raise _IPStop
        top = sorted(rk.items(), key=lambda kv: int(kv[1].get('points',0) or 0), reverse=True)[:10]
        text = '\n'.join([f"{i+1}. {v.get('name', k)} · {v.get('points',0)} pts · partidas {v.get('played',0)}" for i,(k,v) in enumerate(top)])
        await q.answer(text[:1900], show_alert=True)
        raise _IPStop


async def _ip_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat or update.effective_chat.type != 'private':
        return
    uid = int(update.effective_user.id)
    wait = IP_WAITING.get(uid)
    if not wait:
        return
    chat_id = int(wait.get('chat_id'))
    step = wait.get('step')
    s = _ip_state(chat_id)
    c = _ip_cfg(chat_id)
    if step == 'set_image':
        if not update.message.photo:
            await update.message.reply_text('Envíame una imagen.')
            raise _IPStop
        key = wait.get('image_key')
        if key:
            c[key] = update.message.photo[-1].file_id
            save_all_states()
        IP_WAITING.pop(uid, None)
        await update.message.reply_text('Imagen guardada ✅')
        raise _IPStop
    if uid != int(s.get('impostor_id') or 0):
        return
    if step == 'secret':
        txt = (update.message.text or '').strip()
        if not txt:
            await update.message.reply_text('Escribe la identidad oculta.')
            raise _IPStop
        s['secret_name'] = txt
        save_all_states()
        IP_WAITING[uid] = {'chat_id': chat_id, 'step': 'taboo'}
        await update.message.reply_text(f'Identidad guardada. Ahora escribe {int(c.get("taboo_words_count",3))} palabras tabú separadas por coma.')
        raise _IPStop
    if step == 'taboo':
        txt = (update.message.text or '').strip()
        maxc = int(c.get('taboo_words_count',3) or 3)
        words = [w.strip() for w in txt.replace('\n', ',').split(',') if w.strip()]
        words = [w for w in words if len(_ip_norm(w)) >= 3 and _ip_norm(w) != _ip_norm(s.get('secret_name',''))][:maxc]
        if len(words) < maxc:
            await update.message.reply_text(f'Necesito {maxc} palabras válidas de mínimo 3 letras, sin usar el nombre exacto.')
            raise _IPStop
        s['taboo_words'] = words
        save_all_states()
        IP_WAITING.pop(uid, None)
        await update.message.reply_text('Listo ✅ Vuelve al grupo. La partida empieza ya.')
        await _ip_begin_play(context, chat_id)
        raise _IPStop


async def _ip_group_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_chat or not update.effective_user or update.effective_chat.type == 'private':
        return
    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    wait = IP_WAITING.get(uid)
    if not wait or int(wait.get('chat_id') or 0) != chat_id:
        return
    s = _ip_state(chat_id)
    step = wait.get('step')
    text = (update.message.text or update.message.caption or '').strip()
    if not text:
        return
    try: await update.message.delete()
    except Exception: pass
    IP_WAITING.pop(uid, None)
    name = await _ip_chat_name(context, chat_id, uid, _ip_name(update.effective_user))
    if step == 'question':
        if uid != int(s.get('current_turn_user_id') or 0) or uid == int(s.get('impostor_id') or 0):
            return
        taboo_hit = ''
        for w in s.get('taboo_words') or []:
            if _ip_contains_word(text, w):
                taboo_hit = w
                break
        if taboo_hit:
            await _ip_eliminate(context, chat_id, uid, 'Ha dicho una palabra tabú.', taboo_hit)
            await _ip_start_turn_or_final(context, chat_id)
            raise _IPStop
        s['pending_question'] = {'by': uid, 'by_name': name, 'text': text}
        s['phase'] = 'awaiting_impostor_answer'
        save_all_states()
        await _ip_render_panel(context.bot, chat_id)
        raise _IPStop
    if step == 'accuse':
        if uid != int(s.get('current_turn_user_id') or 0) or uid == int(s.get('impostor_id') or 0):
            return
        s['pending_accusation'] = {'by': uid, 'by_name': name, 'text': text}
        s['phase'] = 'awaiting_impostor_accusation'
        save_all_states()
        await _ip_render_panel(context.bot, chat_id)
        raise _IPStop
    if step == 'final_vote':
        if uid == int(s.get('impostor_id') or 0):
            return
        s.setdefault('final_votes', {})[str(uid)] = text
        save_all_states()
        await _ip_render_panel(context.bot, chat_id)
        await _ip_send_temp(context.bot, chat_id, f'🗳 Voto de <b>{h(name)}</b> guardado.', seconds=8)
        raise _IPStop


_old_ip_admin_private_config_markup = admin_private_config_markup if 'admin_private_config_markup' in globals() else None
def admin_private_config_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_ip_admin_private_config_markup(int(chat_id)) if callable(_old_ip_admin_private_config_markup) else InlineKeyboardMarkup([])
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    exists = any(str(getattr(b, 'callback_data', '') or '').startswith('ip350|') for row in rows for b in row)
    if not exists:
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('🎭 IdentidadPRO', callback_data=f'ip350|new|{int(chat_id)}')])
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('⚙️ Opciones IdentidadPRO', callback_data=f'ip350|cfg_rounds|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)

_old_ip_v171_available_panel_items = _v171_available_panel_items if '_v171_available_panel_items' in globals() else None
def _v171_available_panel_items() -> Dict[str, Dict[str, str]]:
    defs = dict(_old_ip_v171_available_panel_items() if callable(_old_ip_v171_available_panel_items) else {})
    defs.update({
        'identidadpro': {'label': '🎭 IdentidadPRO', 'cb': 'ip350|new|{chat_id}'},
        'identidadpro_ranking': {'label': '🏆 Ranking IdentidadPRO', 'cb': 'ip350|ranking|{chat_id}'},
        'cmd_identidadpro': {'label': 'cmd:/identidadpro', 'cb': 'ip350|new|{chat_id}'},
    })
    return defs

_old_ip_v171_item_button = _v171_item_button if '_v171_item_button' in globals() else None
def _v171_item_button(chat_id: int, key: str) -> InlineKeyboardButton:
    if key == 'identidadpro':
        return InlineKeyboardButton('🎭 IdentidadPRO', callback_data=f'ip350|new|{int(chat_id)}')
    if key == 'identidadpro_ranking':
        return InlineKeyboardButton('🏆 Ranking IdentidadPRO', callback_data=f'ip350|ranking|{int(chat_id)}')
    if key == 'cmd_identidadpro':
        return InlineKeyboardButton('cmd:/identidadpro', callback_data=f'ip350|new|{int(chat_id)}')
    if callable(_old_ip_v171_item_button):
        return _old_ip_v171_item_button(int(chat_id), key)
    d = _v171_available_panel_items().get(key, {'label': key, 'cb': f'cfg|block|{{chat_id}}|{key}'})
    return InlineKeyboardButton(d['label'], callback_data=d['cb'].format(chat_id=int(chat_id)))


