async def _ip_pin_join_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    c = _ip_cfg(int(chat_id))
    text = str(c.get('pinned_join_text') or '🎭 IDENTIDAD OCULTA PRO\n\nPulsa para unirte a la próxima partida.')

    old = int(c.get('pinned_join_message_id') or 0)
    if old:
        try:
            await safe_delete(context.bot, int(chat_id), old)
        except Exception:
            pass
    msg = await context.bot.send_message(
        int(chat_id),
        h(text).replace('\n', '\n'),
        parse_mode=ParseMode.HTML,
        reply_markup=_ip_pinned_join_markup(int(chat_id)),
        disable_web_page_preview=True
    )
    c['pinned_join_message_id'] = int(msg.message_id)
    save_all_states()
    try:
        await context.bot.pin_chat_message(int(chat_id), int(msg.message_id), disable_notification=True)
    except Exception:

        logger.exception('IdentidadPRO no pudo fijar el mensaje de unión')


_old_ip_router_definitiva = _ip_router
async def _ip_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('ip350|') or not q.from_user:
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
    except Exception:
        chat_id = int(update.effective_chat.id) if update.effective_chat else 0
    uid = int(q.from_user.id)
    c = _ip_cfg(int(chat_id))


    if action in {'config','cfg','options','opciones'}:
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True)
            raise _IPStop
        try:
            await q.edit_message_text(_ip_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_ip_config_markup(chat_id), disable_web_page_preview=True)
        except Exception:
            await context.bot.send_message(uid, _ip_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_ip_config_markup(chat_id), disable_web_page_preview=True)
        await q.answer()
        raise _IPStop

    if action == 'rules_admin':
        await q.answer(_ip_rules_text()[:1900], show_alert=True)
        raise _IPStop

    if action == 'pin_join':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True)
            raise _IPStop
        await _ip_pin_join_message(context, chat_id)
        await q.answer('Mensaje fijado arriba ✅', show_alert=True)
        try:
            await q.edit_message_text(_ip_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_ip_config_markup(chat_id), disable_web_page_preview=True)
        except Exception:
            pass
        raise _IPStop

    if action == 'unpin_join':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True)
            raise _IPStop
        mid = int(c.get('pinned_join_message_id') or 0)
        if mid:
            try:
                await context.bot.unpin_chat_message(int(chat_id), message_id=mid)
            except Exception:
                pass
            try:
                await safe_delete(context.bot, int(chat_id), mid)
            except Exception:
                pass
        c['pinned_join_message_id'] = 0
        save_all_states()
        await q.answer('Mensaje fijado quitado')
        try:
            await q.edit_message_text(_ip_config_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_ip_config_markup(chat_id), disable_web_page_preview=True)
        except Exception:
            pass
        raise _IPStop

    if action == 'set_pin_text':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True)
            raise _IPStop
        IP_WAITING[uid] = {'chat_id': int(chat_id), 'step': 'set_pin_text'}
        try:
            await context.bot.send_message(uid, 'Escríbeme el texto del mensaje fijado de unión a Identidad Oculta PRO.')
        except Exception:
            pass
        await q.answer('Te he pedido el texto por privado.', show_alert=True)
        raise _IPStop

    if action == 'join_from_pin':

        s = _ip_state(int(chat_id))
        if s.get('phase') != 'lobby':
            _ip_reset(int(chat_id))
            s = _ip_state(int(chat_id))
            s['phase'] = 'lobby'
            s['active'] = True
        s.setdefault('participants', {})[str(uid)] = await _ip_chat_name(context, chat_id, uid, _ip_name(q.from_user))
        save_all_states()
        try:
            await _ip_render_lobby(context.bot, chat_id)
        except Exception:
            pass
        await q.answer('Te has unido 🎮')
        raise _IPStop


    if action == 'new':
        if not await _ip_admin_ok(context, chat_id, uid):
            await q.answer('Solo admins.', show_alert=True)
            raise _IPStop
        try:
            await _ip_delete_all_messages(context.bot, chat_id)
        except Exception:
            pass
        _ip_reset(chat_id)
        await _ip_render_lobby(context.bot, chat_id)
        await q.answer('Lobby listo')
        raise _IPStop


    if action.startswith('cfg_'):
        await _old_ip_router_definitiva(update, context)

        raise _IPStop

    await _old_ip_router_definitiva(update, context)


_old_ip_private_router_definitiva = _ip_private_router
async def _ip_private_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat or update.effective_chat.type != 'private':
        return
    uid = int(update.effective_user.id)
    wait = IP_WAITING.get(uid)
    if wait and wait.get('step') == 'set_pin_text':
        txt = (update.message.text or '').strip()
        if not txt:
            await update.message.reply_text('Escribe un texto válido.')
            raise _IPStop
        chat_id = int(wait.get('chat_id'))
        c = _ip_cfg(chat_id)
        c['pinned_join_text'] = txt
        save_all_states()
        IP_WAITING.pop(uid, None)
        await update.message.reply_text('Texto del mensaje fijado guardado ✅')
        raise _IPStop
    await _old_ip_private_router_definitiva(update, context)


_old_ip_admin_private_config_markup_def = admin_private_config_markup if 'admin_private_config_markup' in globals() else None
def admin_private_config_markup(chat_id: int) -> InlineKeyboardMarkup:
    markup = _old_ip_admin_private_config_markup_def(int(chat_id)) if callable(_old_ip_admin_private_config_markup_def) else InlineKeyboardMarkup([])
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]

    flat = [str(getattr(b, 'callback_data', '') or '') for row in rows for b in row]
    if not any(x == f'ip350|config|{int(chat_id)}' for x in flat):
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('⚙️ Opciones IdentidadPRO', callback_data=f'ip350|config|{int(chat_id)}')])
    if not any(x == f'ip350|new|{int(chat_id)}' for x in flat):
        rows.insert(max(0, len(rows)-1), [InlineKeyboardButton('🎭 IdentidadPRO', callback_data=f'ip350|new|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)


