_old_ip_v171_item_button_def = _v171_item_button if '_v171_item_button' in globals() else None
def _v171_item_button(chat_id: int, key: str) -> InlineKeyboardButton:
    mapping = {
        'identidadpro': ('🎭 IdentidadPRO', f'ip350|new|{int(chat_id)}'),
        'identidadpro_opciones': ('⚙️ Opciones IdentidadPRO', f'ip350|config|{int(chat_id)}'),
        'identidadpro_fijar': ('📌 Fijar unión IdentidadPRO', f'ip350|pin_join|{int(chat_id)}'),
        'identidadpro_ranking': ('🏆 Ranking IdentidadPRO', f'ip350|ranking|{int(chat_id)}'),
        'cmd_identidadpro': ('cmd:/identidadpro', f'ip350|new|{int(chat_id)}'),
        'cmd_identidadpro_config': ('cmd:/identidadproconfig', f'ip350|config|{int(chat_id)}'),
    }
    if key in mapping:
        label, cb = mapping[key]
        return InlineKeyboardButton(label, callback_data=cb)
    if callable(_old_ip_v171_item_button_def):
        return _old_ip_v171_item_button_def(int(chat_id), key)
    d = _v171_available_panel_items().get(key, {'label': key, 'cb': f'cfg|block|{{chat_id}}|{key}'})
    return InlineKeyboardButton(d['label'], callback_data=d['cb'].format(chat_id=int(chat_id)))


_old_identidadpro_config_command_def = identidadpro_config_command
async def identidadpro_config_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':

        try:
            chat_id = next(int(cid) for cid in STATE_CACHE.keys() if int(cid) < 0)
        except Exception:
            await update.message.reply_text('No encuentro grupo configurado para IdentidadPRO.')
            raise _IPStop
    if not await _ip_admin_ok(context, chat_id, int(update.effective_user.id)):
        await update.message.reply_text('Solo admins.')
        raise _IPStop
    await update.message.reply_html(_ip_config_text(chat_id), reply_markup=_ip_config_markup(chat_id))
    raise _IPStop


