def _perfpro_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id))
    p = cfg.setdefault('rendimiento_fluidez_v351', {})
    mods = p.setdefault('modules', {})
    for k in PERFPRO_MODULES_V351:
        mods.setdefault(k, True)
    p.setdefault('saving_mode', bool(cfg.get('perf_saving_mode_v336', False)))
    p.setdefault('saving_level', int(cfg.get('perf_saving_level_v336', 0) or 0))
    p.setdefault('last_clean_ts', 0)
    p.setdefault('silent_buttons', True)
    p.setdefault('block_disabled_modules', True)
    return p


def _perfpro_mod_enabled(chat_id: int, module: str) -> bool:
    try:
        if not module:
            return True
        p = _perfpro_cfg(int(chat_id))
        return bool(p.get('modules', {}).get(module, True))
    except Exception:
        return True


def _perfpro_set_mod(chat_id: int, module: str, enabled: bool) -> None:
    chat_id = int(chat_id)
    p = _perfpro_cfg(chat_id)
    p.setdefault('modules', {})[module] = bool(enabled)
    cfg = admin_cfg(chat_id)

    try:
        if module == 'tarot':
            cfg.setdefault('tarot_config_v129', {})['tarot_enabled'] = bool(enabled)
        elif module == 'frase':
            cfg['daily_phrase_enabled'] = bool(enabled)
        elif module == 'confesionario':
            cfg.setdefault('confesionario_v347', {})['enabled'] = bool(enabled)
        elif module == 'identidadpro':
            cfg.setdefault('identidadpro_v350', {})['enabled'] = bool(enabled)
        elif module == 'limpieza':
            cfg['command_cleanup_enabled'] = bool(enabled)
            cfg['auto_cleanup_enabled'] = bool(enabled)
        elif module == 'dj':
            cfg['dj_module_enabled_perfpro'] = bool(enabled)
        elif module == 'hotconfig':
            cfg['hot_module_enabled_perfpro'] = bool(enabled)
        elif module == 'cerebrito':
            cfg['ai_module_enabled_perfpro'] = bool(enabled)
        elif module == 'premios':
            cfg['awards_module_enabled_perfpro'] = bool(enabled)
        elif module == 'privaditos':
            cfg['privaditos_module_enabled_perfpro'] = bool(enabled)
        elif module == 'impostor':
            cfg['impostor_module_enabled_perfpro'] = bool(enabled)
        elif module == 'start_mentions':
            cfg['start_mentions_enabled_perfpro'] = bool(enabled)
    except Exception:
        pass

    try:
        pcfg = _v336_cfg(chat_id)
        mods = pcfg.setdefault('perf_modules_v336', {})
        map336 = {
            'dj': 'dj', 'frase': 'frase', 'hotconfig': 'hot', 'cerebrito': 'hot',
            'premios': 'pregonero', 'limpieza': 'limpieza', 'start_mentions': 'validacion'
        }
        if module in map336:
            mods[map336[module]] = bool(enabled)
    except Exception:
        pass
    save_all_states()


def _perfpro_saving_level(chat_id: int) -> int:
    p = _perfpro_cfg(int(chat_id))
    try:
        return max(0, min(3, int(p.get('saving_level', 0) or 0)))
    except Exception:
        return 0


def _perfpro_apply_saving(chat_id: int, level: int) -> None:
    chat_id = int(chat_id)
    level = max(0, min(3, int(level)))
    p = _perfpro_cfg(chat_id)
    p['saving_level'] = level
    p['saving_mode'] = bool(level)
    try:
        cfg = _v336_cfg(chat_id)
        cfg['perf_saving_mode_v336'] = bool(level)
        cfg['perf_saving_level_v336'] = 2 if level >= 2 else (1 if level == 1 else 0)
    except Exception:
        pass

    if level >= 2:
        for m in ('cerebrito', 'hotconfig', 'premios'):
            _perfpro_set_mod(chat_id, m, False)
    if level >= 3:
        for m in ('tarot', 'privaditos', 'confesionario', 'identidadpro'):
            _perfpro_set_mod(chat_id, m, False)
    save_all_states()


def _perfpro_score(chat_id: int) -> tuple[int, str, List[str]]:
    try:
        score, reasons = _v336_score(int(chat_id))
    except Exception:
        score, reasons = (0, ['normal'])
    enabled = sum(1 for v in (_perfpro_cfg(chat_id).get('modules') or {}).values() if v)
    if enabled >= 10:
        score = min(100, score + 8)
        reasons = list(reasons) + ['muchos módulos ON']
    level = _perfpro_saving_level(chat_id)
    if level:
        score = max(0, score - (level * 8))
    if score < 35:
        label = '🟢 Fluido'
    elif score < 65:
        label = '🟡 Medio'
    elif score < 85:
        label = '🟠 Cargado'
    else:
        label = '🔴 Saturado'
    return int(score), label, reasons[:5]


def _perfpro_stats_lines(chat_id: int) -> List[str]:
    st = get_state(int(chat_id))
    score, label, reasons = _perfpro_score(int(chat_id))
    lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0) if 'V336_PERF_RUNTIME' in globals() else 0.0
    tasks = _v336_task_count() if '_v336_task_count' in globals() else 0
    cpu, mem = _v336_process_stats() if '_v336_process_stats' in globals() else (0, 0)
    mods = _perfpro_cfg(chat_id).get('modules') or {}
    on = sum(1 for v in mods.values() if v)
    off = len(PERFPRO_MODULES_V351) - on
    temp = len(getattr(st, 'temp_message_ids', []) or [])
    botn = len(getattr(st, 'bot_message_ids', []) or [])
    queue_n = len(getattr(st, 'queue', []) or [])
    lib_n = len(getattr(st, 'library', []) or [])
    lines = [
        '⚙️ <b>Rendimiento / Fluidez PRO</b>',
        '',
        f'Estado: <b>{label}</b> · Carga: <b>{score}%</b>',
        f'<code>{_v336_bar(score) if "_v336_bar" in globals() else str(score)}</code>',
        f'Módulos: <b>{on} ON</b> · <b>{off} OFF</b> · Ahorro: <b>Nivel {_perfpro_saving_level(chat_id)}</b>',
        f'Temporales registrados: <b>{temp}</b> · Bot msgs: <b>{botn}</b>',
        f'DJ: LIVE <b>{"ON" if getattr(st, "live_enabled", False) else "OFF"}</b> · Cola <b>{queue_n}</b> · Biblioteca <b>{lib_n}</b>',
        f'Loop: <b>{lag:.0f}ms</b> · Tareas: <b>{tasks}</b>' + (f' · RAM: <b>{mem}MB</b>' if mem else ''),
        f'Motivo: <i>{h(", ".join(reasons) if reasons else "normal")}</i>',
    ]
    return lines


def _v336_perf_text(chat_id: int) -> str:
    p = _perfpro_cfg(int(chat_id))
    lines = _perfpro_stats_lines(int(chat_id))
    lines += [
        '',
        '<b>Control de módulos</b>',
        'Activa solo lo que estés usando. Si el bot va lento, limpia temporales y usa ahorro 1 o 2.',
    ]
    for key, meta in PERFPRO_MODULES_V351.items():
        enabled = bool((p.get('modules') or {}).get(key, True))
        lines.append(f'{meta["name"]}: <b>{"ON ✅" if enabled else "OFF ⛔"}</b>')
    return '\n'.join(lines)


