def _perfpro_stats_lines(chat_id: int) -> List[str]:
    st = get_state(int(chat_id))
    score, label, reasons = _perfpro_score(int(chat_id))
    lag = float(V336_PERF_RUNTIME.get('loop_lag_ms', 0.0) or 0.0) if 'V336_PERF_RUNTIME' in globals() else 0.0
    tasks = _v336_task_count() if '_v336_task_count' in globals() else 0
    cpu, mem = _v336_process_stats() if '_v336_process_stats' in globals() else (0, 0)
    mods = _perfpro_cfg(chat_id).get('modules') or {}
    on = sum(1 for v in mods.values() if v)
    off = len(PERFPRO_MODULES_V351) - on
    temp = len(getattr(st, 'temp_message_ids', []) or [])
    botn = len(getattr(st, 'bot_message_ids', []) or [])
    queue_n = len(getattr(st, 'queue', []) or [])
    lib_n = len(getattr(st, 'library', []) or [])
    last = str(_perfpro_cfg(chat_id).get('last_action_text_v352') or '').strip()
    lines = [
        '⚙️ <b>Rendimiento / Fluidez PRO</b>',
        '',
        f'Estado: <b>{label}</b> · Carga: <b>{score}%</b>',
        f'<code>{_v336_bar(score) if "_v336_bar" in globals() else str(score)}</code>',
        f'Módulos: <b>{on} ON</b> · <b>{off} OFF</b> · Ahorro: <b>Nivel {_perfpro_saving_level(chat_id)}</b>',
        f'Temporales registrados: <b>{temp}</b> · Bot msgs: <b>{botn}</b>',
        f'DJ: LIVE <b>{"ON" if getattr(st, "live_enabled", False) else "OFF"}</b> · Cola <b>{queue_n}</b> · Biblioteca <b>{lib_n}</b>',
        f'Loop: <b>{lag:.0f}ms</b> · Tareas: <b>{tasks}</b>' + (f' · RAM: <b>{mem}MB</b>' if mem else ''),
        f'Motivo: <i>{h(", ".join(reasons) if reasons else "normal")}</i>',
    ]
    if last:
        lines += ['', f'✅ Última acción: <b>{h(last)}</b>']
    return lines


