async def _perfpro_cleanup_private_only(bot, private_user_id: int) -> int:
    """Limpia únicamente mensajes registrados en el chat privado del usuario con el bot.
    No toca el grupo, no toca fijados, no toca multimedia/archivos no registrados.
    """
    deleted = 0
    if not private_user_id:
        return 0
    cid = int(private_user_id)
    try:
        st = get_state(cid)
        known = sorted(set(
            [x for x in (getattr(st, 'temp_message_ids', []) or []) if x]
            + [x for x in (getattr(st, 'bot_message_ids', []) or []) if x]
            + ([getattr(st, 'control_message_id', None)] if getattr(st, 'control_message_id', None) else [])
            + ([getattr(st, 'panel_message_id', None)] if getattr(st, 'panel_message_id', None) else [])
        ), reverse=True)
        for mid in known:
            try:
                await safe_delete(bot, cid, int(mid))
                deleted += 1
            except Exception:
                pass
        st.temp_message_ids = []
        st.bot_message_ids = []
        st.control_message_id = None
        st.panel_message_id = None
        save_all_states()
    except Exception:
        logger.exception('V354 no pudo limpiar solo privado')
    return deleted


async def _perfpro_close_settings_private_only_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Intercepta cerrar ajustes antes que el cierre viejo.
    Importante: no llama a _perfpro_cleanup_known(chat_id), porque eso limpiaba el grupo.
    """
    q = update.callback_query
    if not q or not q.message:
        return
    data = q.data or ''
    if not (data.startswith('cfg|close') or data.startswith('cfg|saveclose') or data.startswith('cfg|saveclose225') or data.startswith('cfgsafe|close')):
        return

    user_id = int(q.from_user.id) if q.from_user else int(q.message.chat_id)


    try:
        await q.answer('Cerrando ajustes y limpiando solo el privado…')
    except Exception:
        pass


    deleted = 0
    try:
        deleted = await _perfpro_cleanup_private_only(context.bot, user_id)
    except Exception:
        deleted = 0


    try:
        if getattr(q.message.chat, 'type', '') == 'private':
            await q.message.delete()
    except Exception:
        pass


    try:
        if getattr(q.message.chat, 'type', '') == 'private':
            msg = await context.bot.send_message(
                chat_id=user_id,
                text=f'✅ Ajustes cerrados. Limpieza privada hecha: {deleted} mensajes registrados. No he borrado nada del grupo.'
            )
            asyncio.create_task(delete_later(context.bot, user_id, msg.message_id, 8))
    except Exception:
        pass

    raise _PerfStop


