def _v355_chat_for_cfg(update: Update) -> int:
    try:
        cid = int(update.effective_chat.id)
        if cid < 0:
            return cid
    except Exception:
        pass
    return int(update.effective_chat.id) if update.effective_chat else 0

async def chiste_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = _v355_chat_for_cfg(update)
    if chat_id and not _perfpro_mod_enabled(chat_id, 'chistes'):
        await update.message.reply_html('😂 El módulo de chistes está <b>OFF</b> en Rendimiento.')
        raise _PerfStop
    await update.message.reply_html('😂 <b>Chiste del Plan</b>\n\n' + h(_v355_random.choice(_V355_CHISTES)))
    raise _PerfStop

def _v291_hora_text() -> str:
    rows = [
        ('🇪🇸', 'España', 'Europe/Madrid'),
        ('🇦🇩', 'Andorra', 'Europe/Andorra'),
        ('🇦🇷', 'Argentina', 'America/Argentina/Buenos_Aires'),
        ('🇻🇪', 'Venezuela', 'America/Caracas'),
        ('🇨🇺', 'Cuba', 'America/Havana'),
        ('🇨🇱', 'Chile', 'America/Santiago'),
        ('🇨🇴', 'Colombia', 'America/Bogota'),
        ('🇲🇽', 'México', 'America/Mexico_City'),
    ]
    lines = ['🕒 <b>Hora actual del Plan</b>', '']
    for flag, name, tz in rows:
        lines.append(f'{flag} <b>{h(name)}</b>: <code>{h(_v291_now_in_tz(tz))}</code>')
    lines.append('')
    lines.append('<i>México se muestra con horario de Ciudad de México.</i>')
    return '\n'.join(lines)

async def hora_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    await update.message.reply_html(_v291_hora_text())
    raise _V291Stop

def _v355_day_label(day_iso: str) -> str:
    try:
        dt = _v291_datetime.datetime.fromisoformat(str(day_iso)[:10])
        names = ['lunes','martes','miércoles','jueves','viernes','sábado','domingo']
        return names[dt.weekday()].capitalize() + ' ' + dt.strftime('%d/%m')
    except Exception:
        return str(day_iso)

async def _v291_weather_text(city: str) -> str:
    place = await _v291_geocode_city(city)
    if not place:
        return f'🌤 No encontré la ciudad <b>{h(city)}</b>. Prueba con ciudad y país, por ejemplo: <code>Oviedo España</code>.'
    lat = place.get('latitude'); lon = place.get('longitude')
    name = place.get('name') or city
    country = place.get('country') or ''
    timezone = place.get('timezone') or 'auto'
    params = {
        'latitude': lat,
        'longitude': lon,
        'timezone': timezone,
        'current': 'temperature_2m,relative_humidity_2m,weather_code',
        'hourly': 'temperature_2m,precipitation_probability,relative_humidity_2m,weather_code',
        'daily': 'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max',
        'forecast_days': 4,
    }
    forecast_url = 'https://api.open-meteo.com/v1/forecast?' + _v291_urlparse.urlencode(params)
    air_url = 'https://air-quality-api.open-meteo.com/v1/air-quality?' + _v291_urlparse.urlencode({
        'latitude': lat, 'longitude': lon, 'timezone': timezone, 'hourly': 'pm10,pm2_5', 'forecast_days': 1,
    })
    forecast = await _v291_fetch_json_async(forecast_url)
    try:
        air = await _v291_fetch_json_async(air_url)
    except Exception:
        air = {}
    current = forecast.get('current') or {}
    hourly = forecast.get('hourly') or {}
    daily = forecast.get('daily') or {}
    temp = current.get('temperature_2m')
    hum = current.get('relative_humidity_2m')
    code = int(current.get('weather_code') or 0)
    times = hourly.get('time') or []
    temps = hourly.get('temperature_2m') or []
    rains = hourly.get('precipitation_probability') or []
    hums = hourly.get('relative_humidity_2m') or []
    codes = hourly.get('weather_code') or []
    now_hour = str(current.get('time') or '')[:13]
    start_idx = 0
    for i, t0 in enumerate(times):
        if str(t0)[:13] >= now_hour:
            start_idx = i
            break
    idx6 = min(start_idx + 6, len(times) - 1) if times else 0
    rr6 = int(rains[idx6] or 0) if rains and idx6 < len(rains) and rains[idx6] is not None else 0
    tt6 = temps[idx6] if temps and idx6 < len(temps) else '--'
    hh6 = str(times[idx6])[11:16] if times and len(str(times[idx6])) >= 16 else '--:--'
    hum6 = hums[idx6] if hums and idx6 < len(hums) else '--'
    cc6 = int(codes[idx6] or 0) if codes and idx6 < len(codes) else 0
    air_hourly = air.get('hourly') if isinstance(air, dict) else {}
    pm25 = pm10 = None
    try:
        pm25 = next((x for x in (air_hourly.get('pm2_5') or []) if x is not None), None)
        pm10 = next((x for x in (air_hourly.get('pm10') or []) if x is not None), None)
    except Exception:
        pass
    day_lines = []
    dates = daily.get('time') or []
    dmax = daily.get('temperature_2m_max') or []
    dmin = daily.get('temperature_2m_min') or []
    drain = daily.get('precipitation_probability_max') or []
    dcodes = daily.get('weather_code') or []
    for i in range(0, min(3, len(dates))):
        label = _v355_day_label(dates[i])
        mx = dmax[i] if i < len(dmax) else '--'
        mn = dmin[i] if i < len(dmin) else '--'
        pr = int(drain[i] or 0) if i < len(drain) and drain[i] is not None else 0
        cd = int(dcodes[i] or 0) if i < len(dcodes) else 0
        day_lines.append(f'• <b>{h(label)}</b>: {h(mn)}°/{h(mx)}° · lluvia <b>{pr}%</b> · {h(_V291_WEATHER_CODES.get(cd, "variable"))}')
    max_rain = max([int(x or 0) for x in rains[start_idx:start_idx+12] if x is not None] or [0])
    comment = _v291_weather_comment(temp, max_rain, hum, code)
    place_label = f'{name}, {country}'.strip(', ')
    lines = [
        f'🌤 <b>Tiempecito en {h(place_label)}</b>', '',
        f'Ahora: <b>{h(temp)}°C</b> · {h(_V291_WEATHER_CODES.get(code, "variable"))}',
        f'Humedad: <b>{h(hum)}%</b>',
        f'Aire: <b>{h(_v291_air_label(pm25))}</b> · PM2.5: <b>{h(pm25 if pm25 is not None else "--")}</b> · PM10: <b>{h(pm10 if pm10 is not None else "--")}</b>',
        '', '<b>Dentro de 6 horas</b>',
        f'• <code>{h(hh6)}</code> · <b>{h(tt6)}°C</b> · humedad <b>{h(hum6)}%</b> · lluvia <b>{rr6}%</b> · {h(_V291_WEATHER_CODES.get(cc6, "variable"))}',
        '', '<b>Próximos 3 días</b>',
    ]
    lines.extend(day_lines or ['Sin datos diarios disponibles.'])
    lines.extend(['', f'📝 <i>{h(comment)}</i>'])
    return '\n'.join(lines)

async def tiempecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    if not raw:
        PENDING_ACTIONS[_v291_pending_key(update.effective_user.id, chat_id)] = {'kind': 'v355_weather_city', 'chat_id': chat_id, 'user_id': int(update.effective_user.id)}
        await update.message.reply_html('🌤 ¿De qué ciudad quieres el tiempecito?')
        raise _V291Stop
    msg = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(raw)
        await msg.edit_text(text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        logger.exception('V355 error consultando tiempo')
        await msg.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')
    raise _V291Stop

async def _v355_weather_pending_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message or not update.message.text:
        return
    key = _v291_pending_key(update.effective_user.id, update.effective_chat.id)
    pending = PENDING_ACTIONS.get(key)
    if not pending or str(pending.get('kind')) != 'v355_weather_city':
        return
    PENDING_ACTIONS.pop(key, None)
    msg = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(update.message.text.strip())
        await msg.edit_text(text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    except Exception:
        logger.exception('V355 error tiempo pendiente')
        await msg.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')
    raise _V291Stop

async def _v355_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        return
    chat_id = int(parts[1])
    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').replace('command:', '').strip()
    if cmd not in ('hora','horas','tiempo','tiempecito','chiste','chistes'):
        return
    try: await q.answer('✅')
    except Exception: pass
    if cmd in ('hora','horas'):
        await q.message.reply_html(_v291_hora_text())
    elif cmd in ('chiste','chistes'):
        if not _perfpro_mod_enabled(chat_id, 'chistes'):
            await q.message.reply_html('😂 El módulo de chistes está <b>OFF</b> en Rendimiento.')
        else:
            await q.message.reply_html('😂 <b>Chiste del Plan</b>\n\n' + h(_v355_random.choice(_V355_CHISTES)))
    else:
        user_id = int(update.effective_user.id) if update.effective_user else 0
        if user_id:
            PENDING_ACTIONS[_v291_pending_key(user_id, chat_id)] = {'kind':'v355_weather_city','chat_id':chat_id,'user_id':user_id}
        await q.message.reply_html('🌤 ¿De qué ciudad quieres el tiempecito?')
    raise _V291Stop


def _v355_adminmenu_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id)).setdefault('admin_menu_v355', {})
    cfg.setdefault('enabled', True)
    cfg.setdefault('allowed_users', [])
    cfg.setdefault('buttons', [])
    cfg.setdefault('title', '👑 Menú de administradores')
    return cfg

def _v355_adminmenu_can_edit(user_id: int) -> bool:
    try:
        return bool(is_global_admin_user(int(user_id)))
    except Exception:
        return False

def _v355_adminmenu_can_access(chat_id: int, user_id: int) -> bool:
    if _v355_adminmenu_can_edit(user_id):
        return True
    cfg = _v355_adminmenu_cfg(int(chat_id))
    return int(user_id) in [int(x) for x in (cfg.get('allowed_users') or [])]

def _v355_adminmenu_text(chat_id: int, user_id: int) -> str:
    cfg = _v355_adminmenu_cfg(int(chat_id))
    lines = [f'<b>{h(cfg.get("title") or "👑 Menú de administradores")}</b>', '', 'Accesos configurados por el dueño del bot.']
    if _v355_adminmenu_can_edit(user_id):
        lines += ['', f'Usuarios permitidos: <b>{len(cfg.get("allowed_users") or [])}</b>', f'Botones: <b>{len(cfg.get("buttons") or [])}</b>']
    return '\n'.join(lines)

def _v355_adminmenu_markup(chat_id: int, user_id: int) -> InlineKeyboardMarkup:
    cfg = _v355_adminmenu_cfg(int(chat_id))
    rows=[]
    for i,b in enumerate(cfg.get('buttons') or []):
        label=str(b.get('label') or f'Botón {i+1}')[:64]
        target=str(b.get('target') or '')
        if target.startswith(('http://','https://','tg://')):
            rows.append([InlineKeyboardButton(label, url=target)])
        else:
            rows.append([InlineKeyboardButton(label, callback_data=f'adminmenu|run|{int(chat_id)}|{i}')])
    if _v355_adminmenu_can_edit(user_id):
        rows += [
            [InlineKeyboardButton('➕ Añadir botón', callback_data=f'adminmenu|addbtn|{int(chat_id)}'), InlineKeyboardButton('👤 Añadir usuario', callback_data=f'adminmenu|adduser|{int(chat_id)}')],
            [InlineKeyboardButton('📋 Ver configuración', callback_data=f'adminmenu|list|{int(chat_id)}'), InlineKeyboardButton('🧹 Vaciar botones', callback_data=f'adminmenu|clearbtns|{int(chat_id)}')],
        ]
    rows.append([InlineKeyboardButton('🔙 Volver ajustes', callback_data=f'cfg|open|{int(chat_id)}'), InlineKeyboardButton('❌ Cerrar', callback_data=f'adminmenu|close|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)

async def adminmenu_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = _v355_chat_for_cfg(update)
    uid = int(update.effective_user.id)
    if not _v355_adminmenu_can_access(chat_id, uid):
        await update.message.reply_text('No tienes acceso al menú de administradores.')
        raise _PerfStop
    await update.message.reply_html(_v355_adminmenu_text(chat_id, uid), reply_markup=_v355_adminmenu_markup(chat_id, uid))
    raise _PerfStop

async def _v355_adminmenu_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q=update.callback_query
    if not q or not (q.data or '').startswith('adminmenu|'):
        return
    parts=(q.data or '').split('|')
    action=parts[1] if len(parts)>1 else 'open'
    chat_id=int(parts[2]) if len(parts)>2 else (int(update.effective_chat.id) if update.effective_chat else 0)
    uid=int(q.from_user.id) if q.from_user else 0
    if not _v355_adminmenu_can_access(chat_id, uid):
        await q.answer('No tienes acceso.', show_alert=True); raise _PerfStop
    try: await q.answer('✅')
    except Exception: pass
    cfg=_v355_adminmenu_cfg(chat_id)
    if action in ('open','config'):
        await q.edit_message_text(_v355_adminmenu_text(chat_id, uid), parse_mode=ParseMode.HTML, reply_markup=_v355_adminmenu_markup(chat_id, uid), disable_web_page_preview=True)
        raise _PerfStop
    if action=='close':
        try: await q.message.delete()
        except Exception: pass
        raise _PerfStop
    if not _v355_adminmenu_can_edit(uid) and action != 'run':
        await q.answer('Solo dueño/admin.', show_alert=True); raise _PerfStop
    if action=='adduser':
        PENDING_ACTIONS[f'adminmenu:{uid}']={'kind':'v355_adminmenu_adduser','chat_id':chat_id}
        await q.message.reply_html('👤 Envíame el ID numérico del usuario que podrá usar este menú.')
        raise _PerfStop
    if action=='addbtn':
        PENDING_ACTIONS[f'adminmenu:{uid}']={'kind':'v355_adminmenu_addbtn','chat_id':chat_id}
        await q.message.reply_html('➕ Envíame el botón así:\n<code>Nombre=cmd:comando</code>\n<code>Nombre=https://enlace</code>')
        raise _PerfStop
    if action=='clearbtns':
        cfg['buttons']=[]; save_all_states()
        await q.edit_message_text(_v355_adminmenu_text(chat_id, uid), parse_mode=ParseMode.HTML, reply_markup=_v355_adminmenu_markup(chat_id, uid))
        raise _PerfStop
    if action=='list':
        txt='👑 <b>Configuración admin menu</b>\n\nUsuarios:\n'
        txt += ('\n'.join([f'• <code>{x}</code>' for x in cfg.get('allowed_users') or []]) or 'Sin usuarios.')
        txt += '\n\nBotones:\n'
        txt += ('\n'.join([f'• {h(b.get("label"))} → <code>{h(b.get("target"))}</code>' for b in (cfg.get('buttons') or [])]) or 'Sin botones.')
        await q.message.reply_html(txt)
        raise _PerfStop
    if action=='run' and len(parts)>3:
        idx=int(parts[3])
        buttons=cfg.get('buttons') or []
        if not (0 <= idx < len(buttons)):
            await q.answer('Botón no encontrado.', show_alert=True); raise _PerfStop
        target=str(buttons[idx].get('target') or '').strip()
        cmd=target
        for pref in ('cmd:','command:','/'):
            if cmd.lower().startswith(pref):
                cmd=cmd[len(pref):]
                break
        cmd=cmd.strip().split()[0].lower()
        if cmd in ('chiste','chistes'):
            if not _perfpro_mod_enabled(chat_id, 'chistes'):
                await q.message.reply_html('😂 El módulo de chistes está <b>OFF</b>.')
            else:
                await q.message.reply_html('😂 <b>Chiste del Plan</b>\n\n'+h(_v355_random.choice(_V355_CHISTES)))
        elif cmd in ('hora','horas'):
            await q.message.reply_html(_v291_hora_text())
        elif cmd in ('rendimiento','fluidez'):
            await _perfpro_open(update, context, chat_id)
        else:
            await q.message.reply_html(f'▶️ Ejecuta: <code>/{h(cmd)}</code>')
        raise _PerfStop

async def _v355_adminmenu_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message or not update.message.text:
        return
    uid=int(update.effective_user.id)
    pending=PENDING_ACTIONS.get(f'adminmenu:{uid}')
    if not pending:
        return
    if not _v355_adminmenu_can_edit(uid):
        PENDING_ACTIONS.pop(f'adminmenu:{uid}', None); return
    chat_id=int(pending.get('chat_id'))
    cfg=_v355_adminmenu_cfg(chat_id)
    raw=update.message.text.strip()
    if pending.get('kind')=='v355_adminmenu_adduser':
        try:
            val=int(raw.replace('@','').strip())
            arr=[int(x) for x in cfg.get('allowed_users') or []]
            if val not in arr: arr.append(val)
            cfg['allowed_users']=arr; save_all_states()
            await update.message.reply_html(f'✅ Usuario añadido: <code>{val}</code>')
        except Exception:
            await update.message.reply_text('ID inválido. Envíame el ID numérico.')
            raise _PerfStop
    elif pending.get('kind')=='v355_adminmenu_addbtn':
        if '=' in raw:
            label,target=raw.split('=',1)
        elif '|' in raw:
            label,target=raw.split('|',1)
        else:
            await update.message.reply_html('Formato inválido. Usa <code>Nombre=cmd:comando</code>.'); raise _PerfStop
        cfg.setdefault('buttons',[]).append({'label':label.strip()[:64], 'target':target.strip()[:300]})
        save_all_states()
        await update.message.reply_html('✅ Botón añadido al menú de administradores.')
    PENDING_ACTIONS.pop(f'adminmenu:{uid}', None)
    raise _PerfStop

