BOT_VERSION = "V356"


_old_v356_send_hot_to_group = _v218_send_hot_to_group if '_v218_send_hot_to_group' in globals() else None
async def _v218_send_hot_to_group(application: Application, chat_id: int, *, force: bool = False, reason: str = 'auto') -> bool:
    chat_id = int(chat_id)

    if chat_id >= 0:
        return False
    try:
        if not chat_is_allowed(chat_id):

            return False
    except Exception:
        return False
    if callable(_old_v356_send_hot_to_group):
        return await _old_v356_send_hot_to_group(application, chat_id, force=force, reason=reason)
    return False


async def _v218_hot_loop(app: Application) -> None:
    logger.info('V356 HOT loop optimizado arrancado')
    while True:
        try:
            await asyncio.sleep(max(20, int(globals().get('V218_HOT_LOOP_SECONDS', 30) or 30)))
            try:
                chat_ids = [int(x) for x in list(STATE_CACHE.keys())]
            except Exception:
                chat_ids = []

            clean = []
            seen = set()
            for chat_id in chat_ids:
                if chat_id in seen or chat_id >= 0:
                    continue
                seen.add(chat_id)
                try:
                    if not chat_is_allowed(chat_id):
                        continue
                    cfg = _v218_ensure_hot_defaults(chat_id)
                    if not bool(cfg.get('hot_auto_enabled', False)):
                        continue
                    clean.append(chat_id)
                except Exception:
                    continue
            for chat_id in clean:
                try:
                    await _v218_send_hot_to_group(app, int(chat_id), force=False, reason='loop')
                except asyncio.CancelledError:
                    raise
                except Exception:
                    logger.exception('V356 HOT loop falló chat %s', chat_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception('V356 HOT loop error general')


