async def hora_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    await _v357_send_closable(context, int(update.effective_chat.id), _v291_hora_text(), ttl=60, reply_to=getattr(update.message, 'message_id', None))
    try:
        await update.message.delete()
    except Exception:
        pass
    raise _V291Stop if '_V291Stop' in globals() else _PerfStop

async def tiempecito_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    if not raw:
        PENDING_ACTIONS[_v291_pending_key(update.effective_user.id, chat_id)] = {'kind': 'v357_weather_city', 'chat_id': chat_id, 'user_id': int(update.effective_user.id)}
        prompt = await update.message.reply_html('🌤 ¿De qué ciudad quieres el tiempecito?')
        try:
            asyncio.create_task(_v357_delete_after(context.bot, chat_id, prompt.message_id, 60))
            await update.message.delete()
        except Exception:
            pass
        raise _V291Stop if '_V291Stop' in globals() else _PerfStop
    wait = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(raw)
        await wait.delete()
        await _v357_send_closable(context, chat_id, text, ttl=60)
    except Exception:
        logger.exception('V357 error consultando tiempo')
        try:
            await wait.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')
            asyncio.create_task(_v357_delete_after(context.bot, chat_id, wait.message_id, 20))
        except Exception:
            pass
    try:
        await update.message.delete()
    except Exception:
        pass
    raise _V291Stop if '_V291Stop' in globals() else _PerfStop

async def _v355_weather_pending_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message or not update.message.text:
        return
    key = _v291_pending_key(update.effective_user.id, update.effective_chat.id)
    pending = PENDING_ACTIONS.get(key)
    if not pending or str(pending.get('kind')) not in ('v355_weather_city', 'v357_weather_city'):
        return
    PENDING_ACTIONS.pop(key, None)
    chat_id = int(update.effective_chat.id)
    wait = await update.message.reply_html('🌤 Consultando tiempo…')
    try:
        text = await _v291_weather_text(update.message.text.strip())
        await wait.delete()
        await _v357_send_closable(context, chat_id, text, ttl=60)
    except Exception:
        logger.exception('V357 error tiempo pendiente')
        try:
            await wait.edit_text('❌ No pude consultar el tiempo ahora mismo. Prueba otra vez en unos minutos.')
            asyncio.create_task(_v357_delete_after(context.bot, chat_id, wait.message_id, 20))
        except Exception:
            pass
    try:
        await update.message.delete()
    except Exception:
        pass
    raise _V291Stop if '_V291Stop' in globals() else _PerfStop


def _v357_adminplan_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(int(chat_id)).setdefault('adminplan_v357', {})
    cfg.setdefault('enabled', True)
    cfg.setdefault('title', '👑 AdminPlan')
    cfg.setdefault('allowed_users', [])
    cfg.setdefault('buttons', [])
    cfg.setdefault('columns', 2)
    cfg.setdefault('show_summary', True)
    return cfg

def _v357_is_owner(user_id: int) -> bool:
    try:
        return bool(is_global_admin_user(int(user_id)))
    except Exception:
        try:
            return int(user_id) in set(int(x) for x in (globals().get('ADMIN_IDS') or []))
        except Exception:
            return False

def _v357_adminplan_can_access(chat_id: int, user_id: int) -> bool:
    if _v357_is_owner(user_id):
        return True
    cfg = _v357_adminplan_cfg(int(chat_id))
    return bool(cfg.get('enabled', True)) and int(user_id) in [int(x) for x in (cfg.get('allowed_users') or [])]

def _v357_first_group_id() -> int:
    try:
        gids = [int(x) for x in STATE_CACHE.keys() if int(x) < 0]
        return gids[0] if gids else 0
    except Exception:
        return 0

def _v357_adminplan_text(chat_id: int, user_id: int) -> str:
    cfg = _v357_adminplan_cfg(int(chat_id))
    lines = [f'<b>{h(cfg.get("title") or "👑 AdminPlan")}</b>', '']
    if cfg.get('show_summary', True):
        try:
            mods = _perfpro_cfg(int(chat_id)).get('modules') or {}
            on = sum(1 for v in mods.values() if v)
            off = sum(1 for v in mods.values() if not v)
        except Exception:
            on = off = 0
        lines += [
            f'Grupo: <code>{int(chat_id)}</code>',
            f'Usuarios permitidos: <b>{len(cfg.get("allowed_users") or [])}</b>',
            f'Botones: <b>{len(cfg.get("buttons") or [])}</b>',
            f'Módulos: ✅ <b>{on}</b> · ⛔ <b>{off}</b>',
            ''
        ]
    lines.append('Usa los botones configurados por el dueño.')
    if _v357_is_owner(user_id):
        lines.append('\n<i>Modo dueño: puedes configurar este bloque.</i>')
    return '\n'.join(lines)

def _v357_target_from_item(chat_id: int, key: str) -> Dict[str, str]:
    defs = _v171_available_panel_items() if '_v171_available_panel_items' in globals() else {}
    d = defs.get(key) or {}
    label = str(d.get('label') or key)
    cb = str(d.get('cb') or '').format(chat_id=int(chat_id)) if d.get('cb') else ''
    return {'key': key, 'label': label, 'target': cb}

def _v357_adminplan_run_markup(chat_id: int, user_id: int) -> InlineKeyboardMarkup:
    cfg = _v357_adminplan_cfg(int(chat_id))
    buttons = list(cfg.get('buttons') or [])
    rows = []
    cols = max(1, min(3, int(cfg.get('columns', 2) or 2)))
    row = []
    for i, b in enumerate(buttons):
        label = str(b.get('label') or b.get('key') or f'Botón {i+1}')[:64]
        row.append(InlineKeyboardButton(label, callback_data=f'adminplan|run|{int(chat_id)}|{i}'))
        if len(row) >= cols:
            rows.append(row); row = []
    if row:
        rows.append(row)
    if _v357_is_owner(user_id):
        rows.append([InlineKeyboardButton('⚙️ Configurar AdminPlan', callback_data=f'adminplan|config|{int(chat_id)}')])
    rows.append([InlineKeyboardButton('❌ Cerrar', callback_data=f'adminplan|close|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)

