        [InlineKeyboardButton(f'Columnas {int(cfg.get("columns",2))}', callback_data=f'adminplan|columns|{int(chat_id)}'), InlineKeyboardButton('📋 Ver config', callback_data=f'adminplan|list|{int(chat_id)}')],
        [InlineKeyboardButton('👑 Abrir AdminPlan', callback_data=f'adminplan|open|{int(chat_id)}')],
