def _v357_items_page_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    defs = _v171_available_panel_items() if '_v171_available_panel_items' in globals() else {}
    keys = sorted(defs.keys())
    per = 8
    page = max(0, int(page))
    subset = keys[page*per:(page+1)*per]
    rows = []
    for key in subset:
        label = str(defs.get(key, {}).get('label') or key)[:50]
        rows.append([InlineKeyboardButton('➕ ' + label, callback_data=f'adminplan|addkey|{int(chat_id)}|{key}')])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'adminplan|addbtnlist|{int(chat_id)}|{page-1}'))
    if (page+1)*per < len(keys):
        nav.append(InlineKeyboardButton('➡️', callback_data=f'adminplan|addbtnlist|{int(chat_id)}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🔙 Config', callback_data=f'adminplan|config|{int(chat_id)}')])
    return InlineKeyboardMarkup(rows)

