_old_v365_reccmd_router = _v355_reccmd_router if '_v355_reccmd_router' in globals() else None

async def _v365_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        return
    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').strip()
    if cmd != 'mundiplan':
        if callable(_old_v365_reccmd_router):
            return await _old_v365_reccmd_router(update, context)
        return
    try:
        await q.answer('🌍 Consultando…')
    except Exception:
        pass
    # Ejecutar en el chat donde está el botón.
    class _Obj: pass
    fake = _Obj()
    fake.effective_chat = q.message.chat
    fake.effective_user = q.from_user
    fake.message = q.message
    await mundiplan_command(fake, context)


