    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').strip()
    if cmd != 'mundiplan':
        if '_v365_reccmd_router' in globals() and callable(_v365_reccmd_router):
            return await _v365_reccmd_router(update, context)
        return
    try:
        await q.answer('🌍 Consultando MundiPlan…')
    except Exception:
        pass
    class _Obj: pass
    fake = _Obj()
    fake.effective_chat = q.message.chat
    fake.effective_user = q.from_user
    fake.message = q.message
    fake.callback_query = q
    await mundiplan_command(fake, context)


