# =========================================================
# V367 - MundiPlan por fuente directa fiable ESPN JSON
# =========================================================
# Corrección:
# - /mundiplan ya no depende de OpenAI para marcadores en directo.
# - Consulta URL pública de ESPN scoreboard para FIFA World Cup.
# - Si ESPN no devuelve por liga directa, prueba soccer/all y filtra Mundial.
# - Muestra EN JUEGO, resultado, minuto/tiempo, finalizados y pendientes.
# - Horas: España (Europe/Madrid) y USA Este (America/New_York).
# - Mantiene cmd:/mundiplan y botón cerrar.
#
# No toca DJ, IdentidadPRO, rendimiento, AdminPlan ni recurrentes.

BOT_VERSION = "V367"

import json as _v367_json
import urllib.request as _v367_urllib_request
import urllib.error as _v367_urllib_error
from datetime import datetime as _v367_datetime, timezone as _v367_timezone
try:
    from zoneinfo import ZoneInfo as _v367_ZoneInfo
except Exception:
    _v367_ZoneInfo = None

_V367_MUNDIPLAN_TTL = 120
_V367_UA = 'Mozilla/5.0 (MundiPlanBot/1.0; +Telegram)'


def _v367_tz(name: str):
    if _v367_ZoneInfo:
        try:
            return _v367_ZoneInfo(name)
        except Exception:
            pass
    return _v367_timezone.utc


def _v367_now_es():
    try:
        return _v367_datetime.now(_v367_tz('Europe/Madrid'))
    except Exception:
        return _v367_datetime.now()


def _v367_date_param():
    return _v367_now_es().strftime('%Y%m%d')


def _v367_fetch_json_url(url: str, timeout: int = 12):
    req = _v367_urllib_request.Request(url, headers={'User-Agent': _V367_UA, 'Accept': 'application/json,text/plain,*/*'})
    with _v367_urllib_request.urlopen(req, timeout=timeout) as r:
        raw = r.read()
    return _v367_json.loads(raw.decode('utf-8', errors='ignore'))


def _v367_event_is_worldcup(ev: dict, data_leagues=None) -> bool:
    # En endpoint fifa.world damos por bueno. En soccer/all filtramos.
    chunks = []
    for key in ('name', 'shortName'):
        if ev.get(key):
            chunks.append(str(ev.get(key)))
    for comp in ev.get('competitions') or []:
        if comp.get('league', {}).get('name'):
            chunks.append(str(comp.get('league', {}).get('name')))
        if comp.get('league', {}).get('abbreviation'):
            chunks.append(str(comp.get('league', {}).get('abbreviation')))
        for note in comp.get('notes') or []:
            if isinstance(note, dict) and note.get('headline'):
                chunks.append(str(note.get('headline')))
    for lg in data_leagues or []:
        if isinstance(lg, dict):
            chunks.append(str(lg.get('name') or ''))
            chunks.append(str(lg.get('abbreviation') or ''))
    hay = ' '.join(chunks).lower()
    return any(x in hay for x in ['fifa world cup', 'world cup', 'copa mundial', 'mundial'])


def _v367_parse_event(ev: dict, force_worldcup: bool = False, data_leagues=None):
    if not force_worldcup and not _v367_event_is_worldcup(ev, data_leagues):
        return None
    comps = ev.get('competitions') or []
    if not comps:
        return None
    comp = comps[0]
    competitors = comp.get('competitors') or []
    home = away = None
    for c in competitors:
        ha = str(c.get('homeAway') or '').lower()
        if ha == 'home':
            home = c
        elif ha == 'away':
            away = c
    if not home and len(competitors) >= 1:
        home = competitors[0]
    if not away and len(competitors) >= 2:
        away = competitors[1]
    if not home or not away:
        return None

    def team_name(c):
        t = c.get('team') or {}
        return t.get('displayName') or t.get('shortDisplayName') or t.get('name') or c.get('displayName') or 'Equipo'

    def score(c):
        s = c.get('score')
        if s in (None, ''):
            return None
        try:
            return int(s)
        except Exception:
            return str(s)

    status = ev.get('status') or comp.get('status') or {}
    st_type = status.get('type') or {}
    state = str(st_type.get('state') or '').lower()   # pre, in, post
    name = str(st_type.get('name') or '')
    detail = str(st_type.get('detail') or st_type.get('shortDetail') or st_type.get('description') or '')
    display_clock = str(status.get('displayClock') or st_type.get('shortDetail') or '')
    period = status.get('period')

    date_raw = ev.get('date') or comp.get('date')
    dt_utc = None
    if date_raw:
        try:
            dt_utc = _v367_datetime.fromisoformat(str(date_raw).replace('Z', '+00:00'))
            if not dt_utc.tzinfo:
                dt_utc = dt_utc.replace(tzinfo=_v367_timezone.utc)
        except Exception:
            dt_utc = None

    return {
        'id': ev.get('id'),
        'home': team_name(home),
        'away': team_name(away),
        'gh': score(home),
        'ga': score(away),
        'state': state,
        'status_name': name,
        'detail': detail,
        'clock': display_clock,
        'period': period,
        'dt': dt_utc,
        'source': 'ESPN',
    }


def _v367_fetch_mundiplan_matches(date_param: str):
    urls = [
        ('direct', f'https://site.api.espn.com/apis/site/v2/sports/soccer/fifa.world/scoreboard?dates={date_param}&limit=100'),
        ('all', f'https://site.api.espn.com/apis/site/v2/sports/soccer/all/scoreboard?dates={date_param}&limit=100'),
    ]
    last_err = None
    for mode, url in urls:
        try:
            data = _v367_fetch_json_url(url)
            events = data.get('events') or []
            leagues = data.get('leagues') or []
            out = []
            for ev in events:
                m = _v367_parse_event(ev, force_worldcup=(mode == 'direct'), data_leagues=leagues)
                if m:
                    out.append(m)
            if out:
                out.sort(key=lambda x: x.get('dt') or _v367_datetime.max.replace(tzinfo=_v367_timezone.utc))
                return out, None
        except Exception as e:
            last_err = f'{mode}: {e}'
            logger.warning('V367 MundiPlan fuente %s falló: %s', mode, e)
    return [], last_err


def _v367_is_live(m: dict) -> bool:
    state = str(m.get('state') or '').lower()
    detail = str(m.get('detail') or '').lower()
    name = str(m.get('status_name') or '').lower()
    return state == 'in' or any(x in detail + ' ' + name for x in ['live', 'in progress', '1st', '2nd', 'halftime', 'en juego'])


def _v367_is_finished(m: dict) -> bool:
    state = str(m.get('state') or '').lower()
    detail = str(m.get('detail') or '').lower()
    name = str(m.get('status_name') or '').lower()
    return state == 'post' or any(x in detail + ' ' + name for x in ['final', 'ft', 'finished'])


def _v367_score_txt(m: dict) -> str:
    gh, ga = m.get('gh'), m.get('ga')
    if gh is None or ga is None:
        return ''
    return f' <b>{h(gh)}-{h(ga)}</b>'


def _v367_time_pair(dt_utc):
    if not dt_utc:
        return '🇪🇸 sin hora · 🇺🇸 Este sin hora'
    try:
        es = dt_utc.astimezone(_v367_tz('Europe/Madrid')).strftime('%H:%M')
        us = dt_utc.astimezone(_v367_tz('America/New_York')).strftime('%H:%M')
        return f'🇪🇸 {es} · 🇺🇸 Este {us}'
    except Exception:
        return '🇪🇸 sin hora · 🇺🇸 Este sin hora'


def _v367_minute_txt(m: dict) -> str:
    clock = str(m.get('clock') or '').strip()
    detail = str(m.get('detail') or '').strip()
    if clock and clock not in {'0:00', '00:00'}:
        return f' · {h(clock)}'
    # ESPN suele poner "45'+2'" o "Halftime" en detail/shortDetail.
    if detail:
        return f' · {h(detail)}'
    return ''


def _v367_match_line(m: dict) -> str:
    home = h(m.get('home') or 'Equipo A')
    away = h(m.get('away') or 'Equipo B')
    if _v367_is_live(m):
        return f'🟢 <b>EN JUEGO</b>{_v367_minute_txt(m)}\n{home} vs {away}{_v367_score_txt(m)}'
    if _v367_is_finished(m):
        return f'✅ <b>Finalizado</b>\n{home} vs {away}{_v367_score_txt(m)}'
    return f'⏳ <b>Por empezar</b>\n{home} vs {away}\n🕒 {_v367_time_pair(m.get("dt"))}'


def _v367_mundiplan_text(matches, date_param: str, error=None) -> str:
    now = _v367_now_es()
    fecha = now.strftime('%d/%m/%Y')
    lines = ['🌍⚽ <b>MundiPlan 2026</b>', f'📅 <b>{h(fecha)}</b>', '']
    if not matches:
        lines += ['Hoy no he encontrado partidos del Mundial 2026 en la fuente de resultados.', '']
        if error:
            lines += [f'<i>Fuente revisada: ESPN · {h(str(error)[:180])}</i>']
        else:
            lines += ['<i>Fuente revisada: ESPN.</i>']
        return '\n'.join(lines).strip()

    live = [m for m in matches if _v367_is_live(m)]
    upcoming = [m for m in matches if not _v367_is_live(m) and not _v367_is_finished(m)]
    finished = [m for m in matches if _v367_is_finished(m)]
    if live:
        lines.append('🔥 <b>Ahora mismo</b>')
        for m in live:
            lines.append(_v367_match_line(m))
            lines.append('')
    if upcoming:
        lines.append('🕒 <b>Por empezar</b>')
        for m in upcoming:
            lines.append(_v367_match_line(m))
            lines.append('')
    if finished:
        lines.append('✅ <b>Finalizados</b>')
        for m in finished:
            lines.append(_v367_match_line(m))
            lines.append('')
    lines.append('<i>Fuente: ESPN.</i>')
    return '\n'.join(lines).strip()[:3900]


def _v367_mundiplan_close_markup(chat_id: int):
    return InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cerrar', callback_data=f'v367mundiclose|{int(chat_id)}')]])


async def _v367_delete_after(bot, chat_id: int, message_id: int, seconds: int = _V367_MUNDIPLAN_TTL):
    try:
        await asyncio.sleep(max(10, int(seconds)))
        await safe_delete(bot, int(chat_id), int(message_id))
    except Exception:
        pass


async def mundiplan_command(update: Update, context: ContextTypes.DEFAULT_TYPE):  # type: ignore[override]
    if not update.effective_chat:
        return
    chat_id = int(update.effective_chat.id)
    msg = None
    try:
        if update.message:
            msg = await update.message.reply_html('🌍⚽ Consultando MundiPlan…')
        elif getattr(update, 'callback_query', None) and update.callback_query.message:
            msg = await update.callback_query.message.reply_html('🌍⚽ Consultando MundiPlan…')
    except Exception:
        msg = None

    date_param = _v367_date_param()
    try:
        matches, err = await asyncio.to_thread(_v367_fetch_mundiplan_matches, date_param)
        text = _v367_mundiplan_text(matches, date_param, err)
    except Exception as e:
        logger.exception('V367 /mundiplan ESPN falló')
        text = _v367_mundiplan_text([], date_param, str(e))

    try:
        if msg:
            await msg.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=_v367_mundiplan_close_markup(chat_id), disable_web_page_preview=True)
            asyncio.create_task(_v367_delete_after(context.bot, chat_id, int(msg.message_id), _V367_MUNDIPLAN_TTL))
        elif update.message:
            sent = await update.message.reply_html(text, reply_markup=_v367_mundiplan_close_markup(chat_id), disable_web_page_preview=True)
            asyncio.create_task(_v367_delete_after(context.bot, chat_id, int(sent.message_id), _V367_MUNDIPLAN_TTL))
    except Exception:
        logger.exception('V367 /mundiplan no pudo enviar respuesta')

    try:
        if update.message and update.message.text and update.message.text.startswith('/'):
            asyncio.create_task(_v367_delete_after(context.bot, chat_id, int(update.message.message_id), 20))
    except Exception:
        pass
    raise _V291Stop if '_V291Stop' in globals() else ApplicationHandlerStop


