# =========================================================
# V368 - MundiPlan ayer+hoy + OPUS grande con particionado + depuración segura
# =========================================================
# - /mundiplan muestra partidos del día anterior y del día actual.
# - /pod y /podcast sobre OPUS/OGG grande ofrece partir en 2 o 3 partes.
# - Las partes se generan en OPUS reducido y se pueden mandar a cola o directo.
# - Depuración segura: reduce logs ruidosos y no elimina capas históricas necesarias.
#
# No toca IdentidadPRO, AdminPlan, HOTFIX, recurrentes ni DJ base.

BOT_VERSION = "V368"

from datetime import timedelta as _v368_timedelta
try:
    from telegram.ext import ApplicationHandlerStop as _V368Stop
except Exception:
    class _V368Stop(Exception):
        pass

V368_POD_SPLIT_PENDING: Dict[str, Dict[str, Any]] = {}
V368_SPLIT_READY: Dict[str, Dict[str, Any]] = {}
_V368_MUNDIPLAN_TTL = 120
_V368_OPUS_BIG_MB = max(10, int(os.getenv('OPUS_SPLIT_PROMPT_MB', str(PODCAST_MAX_DIRECT_MB_V215 if 'PODCAST_MAX_DIRECT_MB_V215' in globals() else 45))))

# Reducir logs de HTTP sin apagar errores importantes.
try:
    logging.getLogger('httpx').setLevel(logging.WARNING)
    logging.getLogger('telegram').setLevel(logging.WARNING)
    logging.getLogger('telegram.ext').setLevel(logging.INFO)
except Exception:
    pass


def _v368_date_param_es(delta_days: int = 0) -> str:
    try:
        return (_v367_now_es() + _v368_timedelta(days=int(delta_days))).strftime('%Y%m%d')
    except Exception:
        return (_v367_datetime.now() + _v368_timedelta(days=int(delta_days))).strftime('%Y%m%d')


def _v368_pretty_date(date_param: str) -> str:
    try:
        return _v367_datetime.strptime(str(date_param), '%Y%m%d').strftime('%d/%m/%Y')
    except Exception:
        return str(date_param)


def _v368_fetch_mundiplan_two_days():
    days = [(_v368_date_param_es(-1), 'Ayer'), (_v368_date_param_es(0), 'Hoy')]
    out = []
    errors = []
    for date_param, label in days:
        try:
            matches, err = _v367_fetch_mundiplan_matches(date_param)
            out.append({'date': date_param, 'label': label, 'matches': matches or []})
            if err:
                errors.append(f'{label}: {err}')
        except Exception as e:
            out.append({'date': date_param, 'label': label, 'matches': []})
            errors.append(f'{label}: {e}')
    return out, '; '.join(errors)[:400]


def _v368_mundiplan_text(groups, error=None) -> str:
    lines = ['🌍⚽ <b>MundiPlan 2026</b>', '<i>Ayer y hoy · resultados, directo y horarios</i>', '']
    any_match = False
    for group in groups or []:
        label = group.get('label') or ''
        date_param = group.get('date') or ''
        matches = group.get('matches') or []
        lines.append(f'📅 <b>{h(label)} · {_v368_pretty_date(date_param)}</b>')
        if not matches:
            lines.append('Sin partidos encontrados del Mundial 2026.')
            lines.append('')
            continue
        any_match = True
        live = [m for m in matches if _v367_is_live(m)]
        finished = [m for m in matches if _v367_is_finished(m)]
        upcoming = [m for m in matches if not _v367_is_live(m) and not _v367_is_finished(m)]
        # Orden lógico: en juego, finalizados, pendientes
        if live:
            lines.append('🔥 <b>EN JUEGO</b>')
            for m in live:
                lines.append(_v367_match_line(m))
                lines.append('')
        if finished:
            lines.append('✅ <b>Finalizados</b>')
            for m in finished:
                lines.append(_v367_match_line(m))
                lines.append('')
        if upcoming:
            lines.append('🕒 <b>Por empezar</b>')
            for m in upcoming:
                lines.append(_v367_match_line(m))
                lines.append('')
    if not any_match:
        lines.append('No he encontrado partidos del Mundial 2026 para ayer ni hoy en la fuente de resultados.')
        lines.append('')
    if error:
        lines.append(f'<i>Fuente: ESPN · {h(str(error)[:220])}</i>')
    else:
        lines.append('<i>Fuente: ESPN.</i>')
    return '\n'.join(lines).strip()[:3900]


def _v368_mundiplan_close_markup(chat_id: int):
    return InlineKeyboardMarkup([[InlineKeyboardButton('❌ Cerrar', callback_data=f'v368mundiclose|{int(chat_id)}')]])


async def _v368_delete_after(bot, chat_id: int, message_id: int, seconds: int = _V368_MUNDIPLAN_TTL):
    try:
        await asyncio.sleep(max(10, int(seconds)))
        await safe_delete(bot, int(chat_id), int(message_id))
    except Exception:
        pass


async def mundiplan_command(update: Update, context: ContextTypes.DEFAULT_TYPE):  # type: ignore[override]
    if not update.effective_chat:
        return
    chat_id = int(update.effective_chat.id)
    msg = None
    try:
        if update.message:
            msg = await update.message.reply_html('🌍⚽ Consultando MundiPlan…')
        elif getattr(update, 'callback_query', None) and update.callback_query.message:
            msg = await update.callback_query.message.reply_html('🌍⚽ Consultando MundiPlan…')
    except Exception:
        msg = None
    try:
        groups, err = await asyncio.to_thread(_v368_fetch_mundiplan_two_days)
        text = _v368_mundiplan_text(groups, err)
    except Exception as e:
        logger.exception('V368 /mundiplan falló')
        text = _v368_mundiplan_text([], str(e))
    try:
        if msg:
            await msg.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=_v368_mundiplan_close_markup(chat_id), disable_web_page_preview=True)
            asyncio.create_task(_v368_delete_after(context.bot, chat_id, int(msg.message_id), _V368_MUNDIPLAN_TTL))
        elif update.message:
            sent = await update.message.reply_html(text, reply_markup=_v368_mundiplan_close_markup(chat_id), disable_web_page_preview=True)
            asyncio.create_task(_v368_delete_after(context.bot, chat_id, int(sent.message_id), _V368_MUNDIPLAN_TTL))
    except Exception:
        logger.exception('V368 /mundiplan no pudo enviar respuesta')
    try:
        if update.message and update.message.text and update.message.text.startswith('/'):
            asyncio.create_task(_v368_delete_after(context.bot, chat_id, int(update.message.message_id), 20))
    except Exception:
        pass
    raise _V368Stop


async def _v368_mundiplan_close_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not q or not (q.data or '').startswith('v368mundiclose|'):
        return
    try: await q.answer('Cerrado')
    except Exception: pass
    try: await safe_delete(context.bot, int(q.message.chat_id), int(q.message.message_id))
    except Exception: pass
    raise _V368Stop


async def _v368_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        return
    cmd = str(parts[2] or '').lower().strip().lstrip('/').replace('cmd:', '').strip()
    if cmd != 'mundiplan':
        if '_v367_reccmd_router' in globals() and callable(_v367_reccmd_router):
            return await _v367_reccmd_router(update, context)
        return
    try: await q.answer('🌍 Consultando MundiPlan…')
    except Exception: pass
    class _Obj: pass
    fake = _Obj(); fake.effective_chat = q.message.chat; fake.effective_user = q.from_user; fake.message = q.message; fake.callback_query = q
    await mundiplan_command(fake, context)


def _v368_reply_file_size(message) -> int:
    try:
        for attr in ('document', 'audio', 'voice'):
            obj = getattr(message, attr, None)
            if obj and getattr(obj, 'file_size', None):
                return int(getattr(obj, 'file_size') or 0)
    except Exception:
        pass
    return 0


