async def _v368_split_track_n(track: Track, chat_id: int, n: int) -> List[Track]:
    if not track.local_path or not Path(track.local_path).exists():
        raise RuntimeError('El archivo local ya no existe para dividirlo.')
    duration = int(track.duration or probe_duration_seconds(track.local_path) or 0)
    if duration <= 0:
        # Fallback: usa el divisor clásico por minutos si no hay duración.
        return await _v215_split_track(track, chat_id)
    n = max(2, min(3, int(n)))
    seg = max(30, int((duration + n - 1) / n))
    token = secrets.token_hex(5)
    pattern = DOWNLOAD_DIR / f'{int(chat_id)}_pod368part_{token}_%03d.opus'
    kbps = max(48, min(int(PODCAST_OPUS_KBPS_V215 if 'PODCAST_OPUS_KBPS_V215' in globals() else 96), 96))
    await _v215_run_cmd([
        'ffmpeg','-y','-i',str(track.local_path),'-vn',
        '-c:a','libopus','-b:a',f'{kbps}k','-vbr','on','-application','audio',
        '-f','segment','-segment_time',str(seg),'-reset_timestamps','1',str(pattern)
    ], timeout=PODCAST_YTDLP_TIMEOUT_V215 if 'PODCAST_YTDLP_TIMEOUT_V215' in globals() else 900)
    files = sorted(DOWNLOAD_DIR.glob(f'{int(chat_id)}_pod368part_{token}_*.opus'))
    if not files:
        raise RuntimeError('FFmpeg no generó partes OPUS.')
    total = len(files)
    out: List[Track] = []
    for i, f in enumerate(files, 1):
        out.append(Track(
            title=f'{track.title} · Parte {i}/{total}',
            performer=track.performer or 'Podcast OPUS',
            duration=probe_duration_seconds(str(f)),
            local_path=str(f),
            file_unique_id=f'pod368part:{chat_id}:{token}:{i}',
            mime_type='audio/ogg',
            added_by_id=track.added_by_id,
            added_by_name=track.added_by_name,
        ))
    try: Path(track.local_path).unlink(missing_ok=True)
    except Exception: pass
    return out


async def _v368_offer_split_for_big_opus(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, track: Track, file_mb: float, status_msg=None):
    token = secrets.token_hex(5)
    V368_POD_SPLIT_PENDING[token] = {'chat_id': int(chat_id), 'track': asdict(track), 'created_at': int(time.time()), 'user_id': int(update.effective_user.id if update.effective_user else 0)}
    text = (
        '🎙️ <b>OPUS grande detectado</b>\n\n'
        f'Archivo: <b>{file_mb:.1f} MB</b>\n'
        'Para evitar errores y que pueda reproducirse bien, puedo recortarlo en partes OPUS más pequeñas.\n\n'
        'Elige cómo prepararlo:'
    )
    if status_msg:
        try:
            await status_msg.edit_text(text, parse_mode=ParseMode.HTML, reply_markup=_v368_pod_split_prompt_markup(token))
            return
        except Exception:
            pass
    await update.message.reply_html(text, reply_markup=_v368_pod_split_prompt_markup(token))


async def _v368_podcast_reply_opus_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat:
        return
    text = update.message.text or update.message.caption or ''
    try:
        has_url = bool(_v215_first_url(text or ' '.join(context.args or [])))
    except Exception:
        has_url = False
    if has_url:
        return
    reply = getattr(update.message, 'reply_to_message', None)
    if not reply or not _v349_reply_is_opus_like(reply):
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        selected = dj_selected_private_group(update.effective_user.id) if 'dj_selected_private_group' in globals() else None
        if selected is None:
            await update.message.reply_html('Primero vincula/elige un grupo con <code>/djgrupos</code> o <code>/djgrupo</code>.')
            raise _V368Stop
        chat_id = int(selected)
    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await update.message.reply_text('Solo admin o DJ puede preparar podcasts.')
        raise _V368Stop
    track = _v349_track_from_opus_reply(reply)
    if not track:
        await update.message.reply_text('No pude leer el OPUS respondido.')
        raise _V368Stop
    track.title = track.title or getattr(reply, 'caption', None) or 'Podcast OPUS'
    if not str(track.title).startswith('🎙️'):
        track.title = '🎙️ ' + str(track.title)
    track.added_by_id = update.effective_user.id
    track.added_by_name = display_name(update.effective_user)
    file_size = _v368_reply_file_size(reply)
    file_mb = file_size / (1024*1024) if file_size else 0.0
    status = await update.message.reply_html('🎙️ Preparando OPUS…')
    if file_mb and file_mb > float(_V368_OPUS_BIG_MB):
        await _v368_offer_split_for_big_opus(update, context, chat_id, track, file_mb, status_msg=status)
        raise _V368Stop
    try:
        track = await _v349_materialize_opus_reply(context, chat_id, track)
        mb = _v215_file_mb(track.local_path) if track.local_path else file_mb
        if mb and mb > float(_V368_OPUS_BIG_MB):
            await _v368_offer_split_for_big_opus(update, context, chat_id, track, mb, status_msg=status)
        else:
            await _v215_present_podcast(update, context, chat_id, track, status_msg=status)
    except Exception as e:
        logger.exception('V368 OPUS respondido falló')
        msg = str(e)
        if 'too large' in msg.lower() or 'file is too big' in msg.lower() or file_mb:
            await _v368_offer_split_for_big_opus(update, context, chat_id, track, file_mb or 0.0, status_msg=status)
        else:
            try: await status.edit_text('❌ No pude preparar ese OPUS.\n\n<code>'+h(msg[-1200:])+'</code>', parse_mode=ParseMode.HTML)
            except Exception: pass
    raise _V368Stop


async def _v368_pod_split_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not q or not q.data or not q.from_user:
        return
    data = q.data or ''
    if data.startswith('v368podsplit|'):
        parts = data.split('|')
        if len(parts) < 4:
            return
        token, n_raw, mode = parts[1], parts[2], parts[3]
        row = V368_POD_SPLIT_PENDING.get(token)
        if not row:
            await q.answer('Operación caducada. Vuelve a poner /pod.', show_alert=True); raise _V368Stop
        chat_id = int(row['chat_id'])
        if not (await is_admin(context, chat_id, q.from_user.id) or await is_controller(context, chat_id, q.from_user.id)):
            await q.answer('Solo admin/DJ.', show_alert=True); raise _V368Stop
        if mode == 'cancel' or n_raw == '0':
            V368_POD_SPLIT_PENDING.pop(token, None)
            try: await q.edit_message_text('❌ Operación cancelada.')
            except Exception: pass
            await q.answer('Cancelado')
            raise _V368Stop
        n = max(2, min(3, int(n_raw)))
        await q.answer('Preparando partes OPUS…')
        try:
            await q.edit_message_text(f'✂️ Descargando y partiendo en {n} partes OPUS…\nPuede tardar un poco si el archivo es grande.')
        except Exception:
            pass
        try:
            track = Track(**row['track'])
            track = await _v349_materialize_opus_reply(context, chat_id, track)
            tracks = await _v368_split_track_n(track, chat_id, n)
            if mode == 'play':
                await play_selected_track(context, chat_id, tracks[0])
                for tr in tracks[1:]:
                    await queue_track(chat_id, tr)
                    await asyncio.sleep(0.2)
                txt = f'▶️ Parte 1 al directo y <b>{len(tracks)-1}</b> parte(s) añadidas a cola.'
                V368_POD_SPLIT_PENDING.pop(token, None)
            elif mode == 'queue':
                for tr in tracks:
                    await queue_track(chat_id, tr)
                    await asyncio.sleep(0.2)
                txt = f'➕ OPUS dividido en <b>{len(tracks)}</b> partes y añadido a cola.'
                V368_POD_SPLIT_PENDING.pop(token, None)
            else:
                ready = secrets.token_hex(5)
                V368_SPLIT_READY[ready] = {'chat_id': chat_id, 'tracks': [asdict(t) for t in tracks], 'created_at': int(time.time())}
                txt = f'✅ OPUS dividido en <b>{len(tracks)}</b> partes. ¿Qué hacemos?'
                try:
                    await q.edit_message_text(txt, parse_mode=ParseMode.HTML, reply_markup=_v368_pod_ready_markup(ready))
                    raise _V368Stop
                except _V368Stop:
                    raise
                except Exception:
                    pass
            save_all_states()
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
            try: await q.edit_message_text(txt, parse_mode=ParseMode.HTML)
            except Exception: pass
        except Exception as e:
            logger.exception('V368 split OPUS falló')
            try: await q.edit_message_text('❌ No pude partir el OPUS.\n\n<code>'+h(str(e)[-1000:])+'</code>', parse_mode=ParseMode.HTML)
            except Exception: pass
        raise _V368Stop

    if data.startswith('v368podready|'):
        parts = data.split('|')
        if len(parts) < 3:
            return
        token, mode = parts[1], parts[2]
        row = V368_SPLIT_READY.get(token)
        if not row:
            await q.answer('Partes caducadas.', show_alert=True); raise _V368Stop
        chat_id = int(row['chat_id'])
        tracks = [Track(**d) for d in row.get('tracks') or []]
        if not tracks:
            await q.answer('No hay partes.', show_alert=True); raise _V368Stop
        if mode == 'cancel':
            for tr in tracks:
                try:
                    if tr.local_path: Path(tr.local_path).unlink(missing_ok=True)
                except Exception: pass
            V368_SPLIT_READY.pop(token, None)
            await q.edit_message_text('❌ Cancelado.'); raise _V368Stop
        if mode == 'play':
            await play_selected_track(context, chat_id, tracks[0])
            for tr in tracks[1:]: await queue_track(chat_id, tr)
            txt = f'▶️ Parte 1 al directo y resto a cola.'
        elif mode == 'queue':
            for tr in tracks: await queue_track(chat_id, tr)
            txt = f'➕ {len(tracks)} partes añadidas a cola.'
        elif mode == 'lib':
            added = 0
            for tr in tracks:
                if await add_to_library(chat_id, tr): added += 1
            txt = f'📚 Guardadas {added}/{len(tracks)} partes en biblioteca.'
        else:
            await q.answer('Acción no válida.', show_alert=True); raise _V368Stop
        V368_SPLIT_READY.pop(token, None)
        save_all_states(); await ensure_panel(context.bot, chat_id); await ensure_control_panel(context.bot, chat_id)
        try: await q.edit_message_text(txt, parse_mode=ParseMode.HTML)
        except Exception: pass
        raise _V368Stop


# Depuración segura: sanea blanco excesivo al construir esta versión y añade handler global si no existe.
async def _v368_global_error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        logger.exception('V368 error controlado en handler', exc_info=context.error)
    except Exception:
        pass


_old_build_application_v367_for_v368 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v367_for_v368()
    app.add_handler(CommandHandler(['mundiplan'], mundiplan_command), group=-1000000103000)
    app.add_handler(CallbackQueryHandler(_v368_mundiplan_close_router, pattern=r'^v368mundiclose\|'), group=-1000000103001)
    app.add_handler(CallbackQueryHandler(_v368_reccmd_router, pattern=r'^reccmd\|'), group=-1000000103002)
    app.add_handler(CommandHandler(['podcast', 'pod'], _v368_podcast_reply_opus_command), group=-1000000103010)
    app.add_handler(CallbackQueryHandler(_v368_pod_split_router, pattern=r'^v368pod(split|ready)\|'), group=-1000000103011)
    try:
        app.add_error_handler(_v368_global_error_handler)
    except Exception:
        pass
    logger.info('V368 cargado: MundiPlan ayer+hoy, OPUS grande por partes y depuración segura')
    return app


